INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Irmak Kenarı Hayatım', 'bir-irmak-kenari-hayatim-gulcan-sakal-zbkj8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir ırmak kenarı hayatım! 

Lalelerim, papatyalarım, sazlıklarım

Bir sevinç deryası rüyalarım

Masum bir çocuk kalbi yaşantım

Ufukta bir gemi derlerya

İşte öyle hayallerim

Kıpır kıpır yüreğim, sarhoş bedenim

İçimde menekşelerim, kır çiçeklerim

Uzat ellerini birlikte yürüyelim

Beraber gülelim, beraber hüzünlenelim

Beraber yeşertelim umutları, dostlukları

Al yüreğimi, ver yüreğini

Umut olalım umudumuz olsun

Ver elini bir kuş kanadı

Ver elini kafdağı', 'Bir ırmak kenarı hayatım!  Lalelerim, papatyalarım, sazlıklarım Bir sevinç deryası rüyalarım Masum bir çocuk kalbi yaşantım Ufukta bir gemi ...', ARRAY['Türk Edebiyatı','Şiir','Gülcan Sakal']::text[], 8.5, '{"poet":"Gülcan Sakal","poet_slug":"gulcan-sakal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-irmak-kenari-hayatim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk *ÜÇ* Kişiliktir', 'ask-uc-kisiliktir-tuba-celik-grl81', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk üç kişiliktir.

İki kişilik acı çekmektir birinin tarifesi.

Üçüncü sessizce seyreder köşesinden,

Takınıp yüzüne umursamaz maskesini.

Aşkın doğasında vardır gözyaşı,

Kurban geceye gözlerini akıtır.

Nereye dönse yönünü iki eder toplamı,

Üçüncüyü hep arkasında bırakır.

İki kişilik hayaller taşır  cebinde,

Masum bedeni iki kişilik acıkır.

İkincidir  tamamlayan yitik umudunu,

Üçüncü yarına hep eksik kalır.', 'Aşk üç kişiliktir. İki kişilik acı çekmektir birinin tarifesi. Üçüncü sessizce seyreder köşesinden, Takınıp yüzüne umursamaz maskesini. Aşkı...', ARRAY['Türk Edebiyatı','Şiir','Tuba Çelik']::text[], 8.5, '{"poet":"Tuba Çelik","poet_slug":"tuba-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-uc-kisiliktir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
