INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesleniş', 'seslenis-kemal-turk-e5hx6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SESLENİŞ                                                                       

Koskoca dağın arkasında uyuyan dev uyan artık

Senin uykunda devir değişti

Ülkem karanlık yarınlara sürükleniyor.

Bayrağın ayaklar altında eziliyor

Kanını akıttığın topraklar peşkeş çekiliyor emperyalist güçlere

Uyan artık yeter kalk bu uykudan

Ölü uykusuna mı yattın dev 

Ülkemiz değil sadece dünyamız elden gidiyor

Dilimizle başladı yok oluşumuz 1950ler de

İlk önce ezanımız Arapçalaştırıldı.

Sonra bakanlıklar çevrildi eski hallerine

Ülke vurguncuların çıkarcıların yobazların memleketi haline döndü

Emperyalizmin ahtapot kollarına teslim edildi ülkemiz 

Ulu tanrının adı bile indi siyaset meydanlarına

Sorgusuz sualsiz asıldı insanlar

Avrupa birliği uğruna vazgeçildi benliğimizden

Dünyada hangi ülke köle oldu İMF ye

Hangi ülkede millet açken,

Milleti yönetenler kraliyet ailesi gibi düğün yaptı

Ekmek bulamıyorsan pasta ye diyen zihniyet tekrar çıktı meydanlara

Emir altında ezilmekten bıktık biz

Bağıra bağıra sesimiz kısılmadı ama

Kalk gel artık uyan uykundan

Bak gidiyor vatan

Yurdum veda ediyor tarihine

Sokaklar kan çiçekleriyle dolmuş taşmakta

Yalvarırım sana uyan o büyük uykundan

At ölü toprağını sırtından

Silkin kendine gel…

Bu ülkeyi taşı aydınlık geleceklere

Uyan artık,

Canlarımızı verdiğimiz dev uyan.', 'SESLENİŞ                                                                        Koskoca dağın arkasında uyuyan dev uyan artık Senin uykunda ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Türk']::text[], 8.5, '{"poet":"Kemal Türk","poet_slug":"kemal-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/seslenis-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Dön Desem', 'sana-don-desem-zafer-ozkay-8nqqf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana dön desem dönmezsin,

Sana gel desem gelmezsin,

Bilirsin sen beni ne çok sevdim seni,

Unutamadım seni gittin bir kere,

Gidenler dönmüyor geri ne olur dön geri.

Lazımsın sen bana ellerin lazım,

Lazımsın sen bana gözlerin lazım,

Doyamadım sana tutamadım ellerini,

Tadamadım tenini kokun hâla üzerimde,

Yüreğim yanıyor kor ateşlerde.

Sana dön desem dönmezsin,

Sana gel desem gelmezsin,

Bilirsin sen beni ne çok özledim seni,

Bir seni bekledim bir seni istedim,

Silemedim seni gittin sen bir kere,

Gidenler dönmüyor geri.

Sensizlik batıyor içime, 

Yokluğunda uyku girmiyor gözüme,

Yaşlar dinmez oldu gözümde,

Hasretin çığ gibi büyüyor içimde,

Nerdesin sen ah nerde.

Lazımsın sen bana bir tek sen,

Gözlerin ellerin lazım bana,

Nefes gibi muhtacım sana,

Bir seni sevdim bir tek seni,

Bir seni istedim bir tek seni,

Bir seni özledim bir tek seni,

Ölüm gibi ne olur dön geri.

                                                                   20 Kasım 2005 KARAMAN', 'Sana dön desem dönmezsin, Sana gel desem gelmezsin, Bilirsin sen beni ne çok sevdim seni, Unutamadım seni gittin bir kere, Gidenler dönmüyor...', ARRAY['Türk Edebiyatı','Şiir','Zafer Özkay']::text[], 8.5, '{"poet":"Zafer Özkay","poet_slug":"zafer-ozkay","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sana-don-desem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanca', 'i-nsanca-kemal-turk-u4hv5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Satılık olan insanlıktır aslında

Ne köşkler ne de villalar değil

Sırtından hançerlenirken acır ya canın

Acıyor işte canım acıyor nicesine

Pazar sabahlarını hiç sevmem ömürce

Çünkü bomba patladı insanlık sembolünde

Bomba nedir bilir misiniz sizler? 

Nasıl kana bular etrafı nasıl 

Sokaklarda nasıl büyütür kan çiçeklerini 

Nasıl…

Bir mumcu açmak isterdim

Aydınlıkta görülmeyen pislikler belki görünür diye

Adını uğur koymak isterdim 

Uğurlu gelsin diye 

Sonra bir miting yapmak isterdim yoldaşlar buluşsun diye

Ama öyle Türkü, Kübalısı, Rusyalısı ayırarak değil

Hepsi dünyalı olsun isterdim

Sonra haykırmak isterdim

ÖZGÜRLÜK, EŞİTLİK, ADALET diye', 'Satılık olan insanlıktır aslında Ne köşkler ne de villalar değil Sırtından hançerlenirken acır ya canın Acıyor işte canım acıyor nicesine Pa...', ARRAY['Türk Edebiyatı','Şiir','Kemal Türk']::text[], 8.5, '{"poet":"Kemal Türk","poet_slug":"kemal-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/insanca-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüce var', 'yuce-var-kemal-turk-kxglu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'YÜCE VAR

Gecenin zifiri karanlığında aydınlattın yüreklerimizi.

Vatan aşkı millet sevgisiydi bütün çaban

Eğer şimdi bağımsız yaşıyorsak atam

Sendendir senin sayendedir MUSTAFA KEMAL

Çünkü sen gelmiş geçmiş en büyük öndersin gazi paşam

Anadolu’nun ortaçağında,

Ulusun bastırılmış duygularını depreştiren,

Bize bayrağımızı armağan eden yüce var.

Sana söz veriyoruz biz Türk gençliği:

Emperyalizme karşı dalgalandırdığımız ay yıldızlı bayrağımız 

Sonsuza dek göklerde kalacak.

Bir gün o ulu bayrak göklerden inecek olursa

Yaşamak haramdır bizlere 

Çünkü bizler onu yükseltmekle görevlendirilmiş 

Türk gençleriyiz

MUSTAFA KEMAL.', 'YÜCE VAR Gecenin zifiri karanlığında aydınlattın yüreklerimizi. Vatan aşkı millet sevgisiydi bütün çaban Eğer şimdi bağımsız yaşıyorsak atam...', ARRAY['Türk Edebiyatı','Şiir','Kemal Türk']::text[], 8.5, '{"poet":"Kemal Türk","poet_slug":"kemal-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yuce-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Millet adına', 'millet-adina-kemal-turk-yd9t3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'MİLLET ADINA

Hiçbir şey bıraktığın gibi değil atam,

Yurdumun ormanları orman, denizleri deniz değil.

Her yeni gelen bir şeyler götürür bizden 

Ne dediysen atam gerçekleşmekte hepsi birer birer

O sonsuz uykunda bile bizleri aydınlatmaktasın 

Hani geleceğin sahiplerine hitabende demişsin ya 

“İktidara sahip olanlar…” diye

İşte atam her şey bundan ibaret 

Yokluk, sefalet almış başını gidiyor

Millet açken milleti yönetenler,

Düşman çatlatırcasına düğün yapıyor 

N’olacak köylünün, işçinin, emeklinin hali 

N’olacak memurun hali.

Mustafa Kemaller bunları sorar

Hepiniz korkmaktasınız yarınlardan

Aklınızı başınıza alın sağlam adım atın ey gafiller

Millet getirdi sizi oralara,

Millet yaşattı bu zenginliği sizlere.

Bu yüce ulus getirdiği gibi götürmesini de bilir

Unutmayın ki:

“Egemenlik, kayıtsız şartsız milletindir.”.', 'MİLLET ADINA Hiçbir şey bıraktığın gibi değil atam, Yurdumun ormanları orman, denizleri deniz değil. Her yeni gelen bir şeyler götürür bizde...', ARRAY['Türk Edebiyatı','Şiir','Kemal Türk']::text[], 8.5, '{"poet":"Kemal Türk","poet_slug":"kemal-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/millet-adina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zeybeğin Ölümü', 'zeybegin-olumu-necip-fazil-kisakurek-36207', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '(Adnan Menderesin İdamı Üzerine Üstad Bu Şiiri KalemeAlmıştır) 

Zeybeğimi bir kaç kızan,vurdular

Çukurda üstüne taş doldurdular

Ya bir de kalkarsa diye kurdular

Zeybeğim Zeybeğim ne oldu sana 

Allah deyip şöyle bir doğrulsana! 

Zeybeğim kalkamaz dirilemez mi? 

Odası mühürlü girilemez mi? 

Şu ters akan sular çevrilemez mi? 

Ne güne dek böyle gider bu devran

Zeybeğim bir sel ol bir çığ ol davran! 

Kır at zincirlenmiş ufuk sahipsiz

Han kayıp hancı yok konuk sahipsiz

Baş köşede sırma koltuk sahipsiz

Kızanlar,dört yandan hep abandınız! 

Zeybeğin kanına ekmek bandınız! 

Bilemem susarak ölmek mi hüner? 

Lisan çıldırıyor dil nasıl döner? 

Ondan son iz uzak,uzak bir fener

Öldü mü? Çatlarım yine inanmam! 

Diriye yanarım ölüye yanmam! 

Zeybek kaybolduysa bunca kayıp ne? 

Tesbihi dökülmüş aranır nine

Balonu yok ağlar çocuk haline

Zeybeğim; dünyayı aldın götürdün

Bir öldün beni de binbir öldürdün! 

Beyni tırmık tırmık pençelere sor! 

Mevsim niçin ölgün bahçelere sor! 

Sor; çukuru nerde,serçelere sor! 

Ağla,bir dinmeyen hasrete ağla

Zeybeksiz yolları gözetle ağla! ....

                                 (1964)', '(Adnan Menderesin İdamı Üzerine Üstad Bu Şiiri KalemeAlmıştır)  Zeybeğimi bir kaç kızan,vurdular Çukurda üstüne taş doldurdular Ya bir de ka...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/zeybegin-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereye Baksam Yara', 'nereye-baksam-yara-numan-eksioglu-kxx9i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nereye baksam duvar

Çerçeve veya kapı 

Bazen boşver diyorum

Gir içine diyorum 

Ama öyle küçük ki öylesine dar yapı 

Ah pencere pencere ah acıkmış tencere 

Ay bir yastık 

Yakamoz kalın yatak 

Gökyüzü yün bir yorgan 

Olacak elbet birgün

Ama şimdi acıların elinde keskin kılıcın sapı

Ah cendere cendere evi götürmüş dere

Nereye baksam yara 

Sihhatin bomboş küpü 

Sarsam sargılar küçük

Sarılsam kanayacak 

Ah şimdilik uzak bir hayal öpü

Ah saygın dalavere adresin batsın yere', 'Nereye baksam duvar Çerçeve veya kapı  Bazen boşver diyorum Gir içine diyorum  Ama öyle küçük ki öylesine dar yapı  Ah pencere pencere ah ac...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/nereye-baksam-yara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Olmak', 'gunes-olmak-serdar-coskun-7geyh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsan olmak istiyorum 

Dini,dili,ırkı olmayan insan

İnsanı sevek insan oldugu için

Ona güvenmek ADEM''den oldugu için

Güneş olmak  dogmak 

İnsanları ısıtmak

Yakmadan kavurmadan ısıtmak

Isıtmak insan oldugu için

Yagmur olmak yagmak

İnsanlara

Sel olmadan yıkmadan yagmak

Temizlemek için.İnsan için yagmak

Özgür olmak istiyorum

Özgür insanlar için

Konuşmak,dinlemek,inanmak için

İnsan olmak,insanca yaşamak için.', 'İnsan olmak istiyorum  Dini,dili,ırkı olmayan insan İnsanı sevek insan oldugu için Ona güvenmek ADEM''den oldugu için Güneş olmak  dogmak  İn...', ARRAY['Türk Edebiyatı','Şiir','Serdar Coşkun']::text[], 8.5, '{"poet":"Serdar Coşkun","poet_slug":"serdar-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gunes-olmak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tozlanmış yakut kalp', 'tozlanmis-yakut-kalp-volkan-i-lguz-3qvt3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana hiçbir zaman birşans vermedin

Tozlanmış yakuttan bir kalbim vardı

Birkez olsun silmedin ki göresin

Değerini kıymetini bilesin

Sen zahmetsiz tozsuz olanı seçtin

Seçtiğin kalğ belkide bir demirdi

Ama öylesine parlıyordu ki

Gözlerini kamaştırmaya yetti

Demirden bir kalbinpaslanacağını

Sertleşip kabalaşacağını

Pamuktan kalbini yolacağını

Düşünmeden kandın parıltısına

O yakut kaldı raflarda

Düşüp kırıldı toprağa karıştı 

Hem senin pamuk kalbin ziyan oldu 

Hemde bir yakut kalp tarumar oldu', 'Bana hiçbir zaman birşans vermedin Tozlanmış yakuttan bir kalbim vardı Birkez olsun silmedin ki göresin Değerini kıymetini bilesin Sen zahme...', ARRAY['Türk Edebiyatı','Şiir','Volkan İlgüz']::text[], 8.5, '{"poet":"Volkan İlgüz","poet_slug":"volkan-i-lguz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tozlanmis-yakut-kalp-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsam', 'olsam-cafer-akyol-9ry6c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi yanında olsam

Gülümü koklasam

Gözlerinde boğulsam

Seni gülümden

Gülümü senden sorsam

Şimdi yanında olsam', 'Şimdi yanında olsam Gülümü koklasam Gözlerinde boğulsam Seni gülümden Gülümü senden sorsam Şimdi yanında olsam...', ARRAY['Türk Edebiyatı','Şiir','Cafer Akyol']::text[], 8.5, '{"poet":"Cafer Akyol","poet_slug":"cafer-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/olsam-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstifa Ediyorum', 'i-stifa-ediyorum-mehmet-akif-gulhan-rsj6f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen orada ben burada

Sen bana uzak ben sana

Şairim diye güvenme

Bak bana, bu defa

Seni içimde taşıyorum

Vallahi görmesen de seviyorum

Demeyeceğim artık

Böyle aşk mı olur

Böyle sevdamı olur

Bu akşam kalemi de kırdım

Sayfayı da yırttım

Yeter vallahi

Hayal kur,hayal yaz

Bulutlara tutun

Aşkları renk renk yap

İstemiyorum şairlik falan

Bu sözüm bitsin

Şairlikten de istifa ediyorum

Yeter artık canıma tak dedi

Elini tutmak istiyorum

Mehmet Akif Gülhan  09.11.2005 Saat 19.57', 'Sen orada ben burada Sen bana uzak ben sana Şairim diye güvenme Bak bana, bu defa Seni içimde taşıyorum Vallahi görmesen de seviyorum Demeye...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/istifa-ediyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Natürel Güzellik', 'naturel-guzellik-cafer-akyol-f9418', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çek aynayı

Bırak cımbızı

İhtiyacın yok

Yorma o güzel gözleri', 'Çek aynayı Bırak cımbızı İhtiyacın yok Yorma o güzel gözleri...', ARRAY['Türk Edebiyatı','Şiir','Cafer Akyol']::text[], 8.5, '{"poet":"Cafer Akyol","poet_slug":"cafer-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/naturel-guzellik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinde Boğuldum', 'gozlerinde-boguldum-cafer-akyol-pe6da', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bakma öyle tebessüm ettiğime 

Yürürken konuştuğuma, gülmelerime 

Hüzünlenip yumruğumu sıktığıma 

Mimiklerimle karakterler yaptığıma 

Bil ki o zaman; 

Duygularım seninledir

Seni bana getirmeye çalışıyorlar

Durduramıyorum duygularımı

Günün her saatinde; 

Kanat açıp sana uçuyorlar

Gözlerini gözlerime

Yüreğimi yüreğine taşıyorlar

Ondandır nefes nefese kaldığım

Gün boyu soluk soluğa 

Gözlerinde boğulduğum

Gözlerinde…', 'Bakma öyle tebessüm ettiğime  Yürürken konuştuğuma, gülmelerime  Hüzünlenip yumruğumu sıktığıma  Mimiklerimle karakterler yaptığıma  Bil ki ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Akyol']::text[], 8.5, '{"poet":"Cafer Akyol","poet_slug":"cafer-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerinde-boguldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Dogdu', 'umut-dogdu-serdar-coskun-x5yha', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kış günüydü soguktu

Hüzün vardı ama ben mutluydum

Çok mutluydum umut dogmuştu

Yüregime evime ışık dogmuştu

Oglum umut dogmuştu

Aşkımın meyvesi,ömrümün güneşi

Canımın parçası

Oglum dogmuştu

6 yıl geçti umut büyüyor

Hergün biraz daha filizleniyor

Göz bebegim oglum iyiki dogdun

Seni seviyorum UMUT''um oglum', 'Bir kış günüydü soguktu Hüzün vardı ama ben mutluydum Çok mutluydum umut dogmuştu Yüregime evime ışık dogmuştu Oglum umut dogmuştu Aşkımın m...', ARRAY['Türk Edebiyatı','Şiir','Serdar Coşkun']::text[], 8.5, '{"poet":"Serdar Coşkun","poet_slug":"serdar-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umut-dogdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklım Gitti Seninle', 'aklim-gitti-seninle-cafer-akyol-qfaub', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çiçeğim narin ellerde

Gözlerim kaldı gözlerde

Aklım gitti seninle

Sen kim bilir nerede

Ateşlerde kaldım yine

Sana hasret yandım yine

Tek hatıran gözlerin

O da çok uzaklarda be…

Gülüm bahçende çiçek açtı

Sen yüreğimde hala tomurcuk

Şafakta görünmüyor

Söyle güzelim yok mu umut', 'Çiçeğim narin ellerde Gözlerim kaldı gözlerde Aklım gitti seninle Sen kim bilir nerede Ateşlerde kaldım yine Sana hasret yandım yine Tek hat...', ARRAY['Türk Edebiyatı','Şiir','Cafer Akyol']::text[], 8.5, '{"poet":"Cafer Akyol","poet_slug":"cafer-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aklim-gitti-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışkanlıkların Olsan', 'aliskanliklarin-olsan-cafer-akyol-h1w86', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir kuş olup her sabah, 

Pencerene konup,

Avuçlarından beslensem.

Aynan olup gözlerine baksam

Bir avuç su olup; 

Yanaklarından dudaklarına aksam

Kaynayan bir demlik olup

Günaydın deyip elinden tutsam

Çay bardağın olup; 

Dudaklarından öpsem

Taşıdığın çanta olup; 

Yolda hep el ele yürüsek

Kulağına küpe olup; 

Seni sendiğimi söylesem

Boynunda kolye olup; 

Yüreğinin sesini dinlesem 

Gecenin sessizliği olup; 

Bir kenarda yanına kıvrılıp,

Rüyalarını süslesem.

Yorganın olup sana sarılsam 

Yastığın olup; 

Yanaklarından öpsem! 

Alışkanlıkların olup; 

Hep seninle yaşasam! 

İster misin? 

Ne güzel olur!', 'Bir kuş olup her sabah,  Pencerene konup, Avuçlarından beslensem. Aynan olup gözlerine baksam Bir avuç su olup;  Yanaklarından dudaklarına a...', ARRAY['Türk Edebiyatı','Şiir','Cafer Akyol']::text[], 8.5, '{"poet":"Cafer Akyol","poet_slug":"cafer-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/aliskanliklarin-olsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Kasım', '10-kasim-timur-i-likan-32exk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geldi yine bir 10 Kasım

Bitmek bilmiyor hiç yasım

Dinmiyor kanlı gözyaşım

Geçmiyor boğazımdan aşım

Anıyoruz Ata''mızı şâd ile

Söyleniyor adı dilden dile

Şapka çıkardı düşmanı bile

Onun önünde saygı ile

O her Türk''ün sevgilisi

Doluydu yüreği vatan sevgisi

Genci yaşlısı hemen hepsi

Hayrân ona yok bunun ötesi

Onun adı Mustafa Kemal

Dalgalan bayrağım yıldızlı hilâl

Dökülür şehit kanları al al

Ya ölüm vardır ya da istiklâl

Bu vatan Ata''mızdan bize mîras

Şehâdet şerbeti dolu her tas

Nice yiğit içti ondan tas tas

Bütün kahramanlıklar onlara has

Ölmedi Mustafam hiç ölmeyecek

Onun yolunda her Türk yürüyecek

Düşmanın yüzü bir an gülmeyecek

Bayrağım gönderden hiç inmeyecek

(9 Kasım 2005/ İstanbul)', 'Geldi yine bir 10 Kasım Bitmek bilmiyor hiç yasım Dinmiyor kanlı gözyaşım Geçmiyor boğazımdan aşım Anıyoruz Ata''mızı şâd ile Söyleniyor adı ...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/10-kasim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çare', 'care-mim-ahmir-rengi-3qbz1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Derd-i ruhuma bir çare

Kılmayın beni biçare', 'Derd-i ruhuma bir çare Kılmayın beni biçare...', ARRAY['Türk Edebiyatı','Şiir','Mim Ahmir Rengi']::text[], 8.5, '{"poet":"Mim Ahmir Rengi","poet_slug":"mim-ahmir-rengi","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/care-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-omer-arslan-6w2t2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çoktan beri mektup gelmez tel gelmez; 

	Sevenlerim gelmezse el hiç gelmez; 

	Çiçek gelmez,lale gelmez, gül gelmez; 

	Sevenlerim birer birer sır arkadaş. 

	Bu bahar cemre yüreğime düştü,

	Cemre değil sanki bu bir ateşti,

	Durduk yere felek bağrımı deşti,

	Göz yaşı dökmek bana ar arkadaş.

	Senin bekleyenin yok mu arkadaş? 

	Gurbetlik bağrında ok mu arkadaş? 

	Hiç senin sevdiğin yok mu arkadaş? 

	Mesela ana baba yar arkadaş.

	

	Geçti gitti bize gelmeyen kervan,

	Bilirsin dinlemez gönül ferman, 

	Duymasınlar ama halim pek yaman,

	Sevdanın aşkın gözü kör arkadaş', 'Çoktan beri mektup gelmez tel gelmez;  	Sevenlerim gelmezse el hiç gelmez;  	Çiçek gelmez,lale gelmez, gül gelmez;  	Sevenlerim birer birer ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Arslan']::text[], 8.5, '{"poet":"Ömer Arslan","poet_slug":"omer-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/arkadas-98-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Az Düşünüyorum', 'az-dusunuyorum-omer-arslan-zxmbh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne kadar az düşünürsem, 

	O kadar az taratıyorum:

	Taranmayan saçalarımı rüzgara.

	

               Artık sen de ağlayan bir şaire ağla,

	Anam ana dilinde ağıtlar yakıyor nasılsa.

	İstemiyorum acıyla gelen mutluluğu,

	İstemiyorum yüreğime çöreklenen kini,

	Düşmanlık gütmüyorum insanlara.

	

                Kaşlarım çatılmıyor, küfretmiyorum.

	Eskisi gibi dişlerimi sıkıp,

	Moral bozucu şeylere aldırmıyorum.

	Aldırmıyorum ipi kopan uçurtmama,

	Gönül koymuyorum artık; 

	Selamsız dostlara.

	

                 Bu yüzden az düşünüyorum, 

	Anla beni, anlayabilirsen.

                                         

	 http://sairarslan.sitemynet.com', 'Ne kadar az düşünürsem,  	O kadar az taratıyorum: 	Taranmayan saçalarımı rüzgara. 	                Artık sen de ağlayan bir şaire ağla, 	Ana...', ARRAY['Türk Edebiyatı','Şiir','Ömer Arslan']::text[], 8.5, '{"poet":"Ömer Arslan","poet_slug":"omer-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/az-dusunuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deruni Mahbube', 'deruni-mahbube-mim-ahmir-rengi-x2jev', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey sevgili! Sen nesin de ettin beni köle

Vurdun beni yerdenyere,oldum emrine amade

Mecalim de kalmadı bulunmaya serzenişte

Sensizim,sessizim,olmuşum avare

Bir latifsin,ayrısın,farklısın,cansın canansın

Gönlüme hitap,aşkıma mehtapsın

Ben aciz ve mecruhum,sen güle mazharsın

Gel sev beni tekrar,sen yine bana sezasın', 'Ey sevgili! Sen nesin de ettin beni köle Vurdun beni yerdenyere,oldum emrine amade Mecalim de kalmadı bulunmaya serzenişte Sensizim,sessizim...', ARRAY['Türk Edebiyatı','Şiir','Mim Ahmir Rengi']::text[], 8.5, '{"poet":"Mim Ahmir Rengi","poet_slug":"mim-ahmir-rengi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/deruni-mahbube-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu günlerde', 'bu-gunlerde-omer-arslan-0kzho', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geçiyor baharım geçiyor yazım,

	Neyleyim kara yazılmış yazım,

	Telleri kırılmış çalmaz ki sazım,

	Düşündüğüm resmi çiz bu günlerde.

	Kulaklarımda şimdi içli şarkın

	Mecnundan da inan kalmadı farkım,

	Felek çomak soktu kırıldı çarkım,

	Gönlümde bahar yok güz bu günlerde.

	Yüreğim  kurudu sanki  oldu çöl,

	Bir gül yaprağı gönder,veyahut gül.

	Sabrım kalmadı,bilesin ey gönül,

	İyi haber gönder tez bu günlere.

	Hayat ağacında kuruyor dalım,

	Hep ayrılık çıkıyor nedense falım,

	Delinmiş gibi yana yatıyor salım,

	Sende bana doğru yüz bu günlerde.

	

http://sairarslan.sitemynet.com', 'Geçiyor baharım geçiyor yazım, 	Neyleyim kara yazılmış yazım, 	Telleri kırılmış çalmaz ki sazım, 	Düşündüğüm resmi çiz bu günlerde. 	Kulakla...', ARRAY['Türk Edebiyatı','Şiir','Ömer Arslan']::text[], 8.5, '{"poet":"Ömer Arslan","poet_slug":"omer-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-gunlerde-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Harfli Kelime...', 'uc-harfli-kelime-i-brahim-ethem-bingul-bdql2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Örttüm

Perdeyi pencereyi

Olurda 

Güneş giriverir içeri...

Yazdırır sonra

O üç harfli kelimeyi...

Değiştiririm

Kemiksiz dilimi

Tuttuğum

Kurşun kalemi...

Yok yok

Değişmezki

Yüreğimin ifade şekli...', 'Örttüm Perdeyi pencereyi Olurda  Güneş giriverir içeri... Yazdırır sonra O üç harfli kelimeyi... Değiştiririm Kemiksiz dilimi Tuttuğum Kurşu...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/uc-harfli-kelime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürüm', 'ozgurum-ali-sagmen-hvqe7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özgürüm; 

oglum.

Özgürüm,

canim cigerim.

Özgürüm,

yigitim benim.

Özgürüm,

gelecegim.

Özgürüm,

ben özgür degilim.', 'Özgürüm;  oglum. Özgürüm, canim cigerim. Özgürüm, yigitim benim. Özgürüm, gelecegim. Özgürüm, ben özgür degilim....', ARRAY['Türk Edebiyatı','Şiir','Ali Sagmen']::text[], 8.5, '{"poet":"Ali Sagmen","poet_slug":"ali-sagmen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ozgurum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yosma', 'yosma-muharrem-cetinkaya-ytny3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ince sırrını yırtar gönlümün

üçüncü şahsın kollarındaki

işkenceci bakışların 

kanar ığıl ığıl içerden

yaş kütüğü gibi çentik attığın yüreğim

belli ki hiç sarmak aklına gelmez

kanattığın yaraları

.

…………………….

bak umurunda mı dünya

.

oysa samanlıkta yitirilmiş bir iğne gibidir

“seninle” kurduğum düşler

buldukça kaybeder

kaybettikçe bulurum

ve bir saman tanesidir sensizlik

yaşam bir samanlık

içinde tatlı düşlerimi yitirdiğim

ve ayrılık denizinde kayboluşumda

bir saman tanesidir düşlerim

deryalarda yüzdürdüğüm..

.

yine de kalır geceye

hüzünlenmek için 

bakışlarından bir dem

ve yalnızlığıma katıktır

henüz yitirmediğim umutlarım

.

ince bir sır_dır bu saatte yaşamak

kırmadan kabuğunu

kuluçkadaki yumurtanın sarısı gibidir

bir can_a gebe

deli divane gönlümdeki arzular

.

ve her doğan güneşle

güzel umutlara gebe kalan yüreğim

kırılmamış kabuklar içinde

ölü doğanlar mezarlığı gibidir

.

 …her imsak vakti

yalnızlığın ıslaklığında

sıcaklığın

___ölüye can verir

___diriden can alır 

soğukluğun

ve yüreğimde saplı bir hançer gibidir

bir pul_a sattığın

yosma_lığın', 'ince sırrını yırtar gönlümün üçüncü şahsın kollarındaki işkenceci bakışların  kanar ığıl ığıl içerden yaş kütüğü gibi çentik attığın yüreğim...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/yosma-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarih 10 Kasım- Saat Kaç? ?', 'tarih-10-kasim-saat-kac-muharrem-cetinkaya-unyqr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''''

Düşündü birden bire kayalardaki adam

kaynakları ve yolları düşman elinde kalan bütün nehirleri.

…………….

O saati sordu:

Paşalar “üç”dediler.

Sarışın bir kurda benziyordu

Ve mavi gözleri çakmak çakmaktı.

Yürüdü uçurumun başına kadar,

eğildi,durdu

Bıraksalar

........................................''

.

Tarih yine 10 Kasım

O şimdi, yine saati soruyor

.

''…………………….! ''

.

Sahi saat kaç? ? ?', ''''' Düşündü birden bire kayalardaki adam kaynakları ve yolları düşman elinde kalan bütün nehirleri. ……………. O saati sordu: Paşalar “üç”dediler...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/tarih-10-kasim-saat-kac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğruda Olmak', 'dogruda-olmak-abdullah-yasar-erdogan-lvbes', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeri yok bu davada sû-i ahlakın,

Terakki de bulunmaz yeri tamahın,

Teşne-i beşer olsa da insan,

Kadr-i kıymetin bilmez ki mahlukatın.

Hiç eksilmemiş ki seciye-i şaki,

Var git bakıver insan ne ile baki,

Acz-i beşer olsa da şu insan,

Menzl-i maksuddaki renklerin haki.

Hatem-i Resûl aşkı ile yanmayan,

O büyük ki şetmetme ile anmayan,

Lakin acz-i beşer dedik insan,

Yoldan hepten sapar, doğruda olmayan.

Terakki: Yükselme, ilerleme.

Sû-ı ahlak: Kötü huy.

Teşne-i beşer: Hevesli insan.

Seciye-i şaki: Kötü huylu haydut.

Menzil-i Maksud: Ulaşmak için hedeflenen yer.

Şetmetme: Sövme

Abdullah Yaşar Erdoğan.', 'Yeri yok bu davada sû-i ahlakın, Terakki de bulunmaz yeri tamahın, Teşne-i beşer olsa da insan, Kadr-i kıymetin bilmez ki mahlukatın. Hiç ek...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dogruda-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-mehmet-korkmaz-uqho3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'umut

ellerimde tutuğum

beyaz bir güvercin

bıraksam 

uçacak

bırakmasam

umut

tutsak', 'umut ellerimde tutuğum beyaz bir güvercin bıraksam  uçacak bırakmasam umut tutsak...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Korkmaz']::text[], 8.5, '{"poet":"Mehmet Korkmaz","poet_slug":"mehmet-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umut-213-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk-ı Solumak', 'ask-i-solumak-abdullah-yasar-erdogan-3dnav', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu ilim dünyasının içinde olmak,

Gönlü mübin-i tebeiyyet kılmak,

Zebunluğunu bilip edepli olmak,

İşte dileğim bu aşk-ı solumak.

Kitaplarla saadetini buldum,

İlm-i nâfi kapısında kul oldum,

İlm-i ummanında yakin bulundum,

İşte dileğim bu aşk-ı solumak.

Zuumdan uzak her ilim dostu,

Ubudiyet-i ilâhiyle ol tulû,

Kurtuluşa erdir Rabbim bu kulu,

İşte dileğim bu aşk-ı solumak.

Zebun: Zayıf, kuvvetsiz.

Ubudiyet: kulluk, kölelik.

Tulû: Doğma, ortaya çıkma.

Zuum: Boş inanç, haksız yere zan.

Yakin: Şüphesiz bilme, inanma.

Tebeiyyet: Tabi olmak, bağlılık.

İlm-i nâfi: faydalı ilim.

Abdullah Yaşar Erdoğan.', 'Şu ilim dünyasının içinde olmak, Gönlü mübin-i tebeiyyet kılmak, Zebunluğunu bilip edepli olmak, İşte dileğim bu aşk-ı solumak. Kitaplarla s...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ask-i-solumak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Degisim Saat 17.00', 'degisim-saat-17-00-ali-sagmen-kwkix', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aliskin  degilim Almanyada

tabutu basinda elbaglayip

anilarini düsünerek insan ugurlamaya

Ruhi Su dostun sesinden

Kerimoglu zeybegi dolduruyor

kabristan merasim salonunu

cok garip geliyor bana,

icimdeki aciyla birlikte,yigitlik türküleri

Yörük efelerinin ölümü böyle güzel ve

coskulu kucaklamasi

iste degisim böyle olmali diyorum; 

tipki  Isci Yazar FETHI SAVASCI gibi', 'Aliskin  degilim Almanyada tabutu basinda elbaglayip anilarini düsünerek insan ugurlamaya Ruhi Su dostun sesinden Kerimoglu zeybegi dolduruy...', ARRAY['Türk Edebiyatı','Şiir','Ali Sagmen']::text[], 8.5, '{"poet":"Ali Sagmen","poet_slug":"ali-sagmen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/degisim-saat-17-00-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On Kasım', 'on-kasim-mehmet-ali-yapici-jn46t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin hasretinle bütün gözler yaşarsın,

Yaşlı bütün gözler bugün yine on kasım,

Her günümüzde her anımızda sen varsın,

Büyük Atam sen dünya durdukça yaşarsın.

Acı bir sonbahar rüzgarı idi esen,

On Kasım bin dokuz yüz otuz sekiz günü,

Kim inanır Mustafa Kemal öldü desem,

Atam kabullenmek mümkün mü öldüğünü? 

Yüce Atamızı ruhu terk etse bile,

Bir ulus bağlı ona sonsuz sevgi ile,

Düşman olurum Atam öldü diyen dile,

Bütün günlerimiz Mustafa Kemal ile...

Sessizlik ve sükun sarar on kasım günü,

İnandıramaz bize kimse öldüğünü,

Kulaklarımızda çınlıyor hala sesin,

Sen milyonlarca Türk''ün hala kalbindesin...', 'Senin hasretinle bütün gözler yaşarsın, Yaşlı bütün gözler bugün yine on kasım, Her günümüzde her anımızda sen varsın, Büyük Atam sen dünya ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Yapıcı']::text[], 8.5, '{"poet":"Mehmet Ali Yapıcı","poet_slug":"mehmet-ali-yapici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/on-kasim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine yollardayım', 'yine-yollardayim-sinan-aydindag-ekqo4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '13 ekim 2004

Yine yollardayım yine yalın ayak

Yine yağmur yağıyor yine fırtına koyar mı? bana

Senin sıcaklığındır en soğuk günlerde 

Giren vücuduma

Yine akşamdır olan

Yine hayalindir karanlık sokaklarda kaybolan

Yine sevincimdir,yine umudum,

Bir çiğ tanesi gibi paramparca olan

Gel be gel seviyorum seni,seviyorum ulan

Şimdi çökmiş omuzlarıma 

Sensizlik daha da ağır basıyor

Bulamamak var ya seni cigerim sızlatıyor

Sevdiğin sensiz bu acı havadan zehir soluyor

Gel gel tek başına yaşanmıyor,yaşanmıyor.', '13 ekim 2004 Yine yollardayım yine yalın ayak Yine yağmur yağıyor yine fırtına koyar mı? bana Senin sıcaklığındır en soğuk günlerde  Giren v...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yine-yollardayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvenini yitirme dostum', 'guvenini-yitirme-dostum-sinan-aydindag-k2nm0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '16 ekim 2004

Kendine güvenini yitirme dostum,

Sonra yıkılır gidersin

Hayat çok kısa sende konup göçersin

Bu boşluk yaralasada seni,

Biliyorum başedersin

Sen her zaman gülki dostum,

Yüreklerimiz yeşersin', '16 ekim 2004 Kendine güvenini yitirme dostum, Sonra yıkılır gidersin Hayat çok kısa sende konup göçersin Bu boşluk yaralasada seni, Biliyoru...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/guvenini-yitirme-dostum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Legal Şair', 'legal-sair-kamil-at-7o2yb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir güzeli kıskananlar şair olurmu

İnsanlık kalbinde rıza bulurmu

Bu uğurda kendine doğru kalırmı

Zengin diye kravat takan şaire bak.

İnsanı bilmez, boşluğa bağırmış

Kendine kazılan çukura çağırmış

Duymadığı hayata hepten sağırmış

Paşanın ateşini yakan şaire bak.

Baskıcıların ekmeğine yağ çalar

Zorba hakime bitmiş çağ çalar

Çıkmazlığın içinde yalvarır sığ çalar

Irkçı düşmanlık eken şaire bak.

Hakim kararının dışına çıkmamış

Zorla yazdırana dişini sıkmamış

Çalıp yiyenlerin aşına bıkmamış

İzinli onay ile yazan şaire bak.

Sana derim zalimdensin ulan

Sahteden yalan namaz kılan

Dünyayı çözsen yine de için yalan

Yoksul küfür döken şaire bak.

Hiçbir zaman kendini bilmemiş

Çok kirli cinleri içinden silmemiş

Tor kalmış Kamil At gibi olmamış

Hacılara duayı çeken şaire bak.', 'Bir güzeli kıskananlar şair olurmu İnsanlık kalbinde rıza bulurmu Bu uğurda kendine doğru kalırmı Zengin diye kravat takan şaire bak. İnsanı...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/legal-sair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen yoksun diye', 'sen-yoksun-diye-sinan-aydindag-6ww0b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '30 ekim 2004

Yüzüm kanıyor,ellerim kanıyor

Yüreğim kanıyor sen gittin diye

Ay batmıyor,güneş doğmuyor,

Kuşlarsa uçmuyor sen yoksun diye

Cigerlerime hava dolmuyor

Ocağım artık tütmüyor

Kimse beni istemiyor sensizim diye

Şimdi dönüp gelsen bana

Son versen bu ızdırabıma

Sarılıp koklasam be doya doya

Ne olur gel sensiz katlanamıyorum bu hayata

Ama sen inatsın gelmezsin

Açtığın yaralara merhem sürmezsin

Nasıl çürüdüğümü görmezsin

İnatsın kızım sen inat onun için gelmezsin

Gelmezsen kızım gelme

Bir daha bana haber gönderme

Sevdiğin seni terk ettiğinde,

Ağlayarak sakın kapıma gelme.', '30 ekim 2004 Yüzüm kanıyor,ellerim kanıyor Yüreğim kanıyor sen gittin diye Ay batmıyor,güneş doğmuyor, Kuşlarsa uçmuyor sen yoksun diye Cige...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-yoksun-diye-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin Soğuk Bir Kış / Bin Çocuk Bir Düş', 'bin-soguk-bir-kis-bin-cocuk-bir-dus-devran-demir-zasry', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bin karakıştı 

bin ayaz geceydi

binlerce kimsesiz çocuktular

Sığınacak bir yuva

bağrına basacak bir anne 

uyuyacak bir yatak arıyordular

Hiç kimse onları düşünmüyor 

hiç kimse onları görmüyor 

hiç kimse onları anlamıyordu

Bir yerden bir yere itilip 

bir yerden bir yere sürülüp duruyordular

yalnızdılar, kırgındılar, bitkindiler

suskundular, dalgındılar, mahzundular

Onlarca büyük şehrin, yüzlerce 

ışıklı-işlek caddelerinde kimileri

kimileri karanlık ıssız sokaklarında 

tedirgin, uykusuz dolaşıyordular

Nereye gideceklerini bilmiyordular 

ne yapacaklarını bilmiyordular

insanlara korkuyla bakıyordular

her şeyden ürküyordular

birbirlerinden bile çekiniyordular

Ve unutup açlıklarını çoğu zaman 

yalnızca üşümeden uyuyabilecekleri 

bir yer arıyordular

tepeden tırnağa titriyordular 

çok öksürüyordular 

çok üşüyordular...

Ve onlar ki yine

kimileri telefon, kimileri 

bankamatik kulübelerine 

kimileri inşaat, kimileri 

apartman bodrumlarına 

sığınıp yine sessiz

bazıları yalnız 

bazıları koyun koyuna

koyup başlarını usulca

kurulmaktan yorgun 

düşmüş bir düş''ün

güzelliği ve sıcaklığını 

alıp alıp, o hiçbir zaman 

doyamadıkları uykularına 

rüyalarına dek 

taşıyor, taşıyordular...

Bin mavi gökyüzüydü

bin sıcak gündü

binlerce sahipli çocuktular

Sığındıkları bir yuvaları

bağrına basan bir anneleri

uyudukları bir yatakları vardı

Herkes onları görüyor 

herkes onlara gülümsüyor 

herkes onları seviyordu

bütün sevdikleri yanlarındaydı

içten sıcak yumuşak öpüşler 

dokunuşlar içindeydiler

hiç titremiyor 

hiç üşümüyor artık

hiç öksürmüyordular

Dünyayı seviyordular 

hayatı seviyordular 

kendilerini seviyordular

neşeliydiler mutluydular huzurluydular

koşuyordular, gülüyordular, oynuyordular

çocuktular çocuktular çocuktular...

Ve günün ilk ışıklarıyla yine onlar 

şehrin ağır gürültüleriyle irkilip 

bazen hoyrat insan elleriyle 

dürtülerek / yeniden yeniden

görmek istemedikleri bir dünya

yaşamak istemedikleri bir hayata

birer birer çaresiz ve üzgün 

uyanıyordular...

Bin karakıştı

bin soğuk sabahtı

binlerce kimsesiz çocuktular...

(İstanbul, 2005)', 'Bin karakıştı  bin ayaz geceydi binlerce kimsesiz çocuktular Sığınacak bir yuva bağrına basacak bir anne  uyuyacak bir yatak arıyordular Hiç...', ARRAY['Türk Edebiyatı','Şiir','Devran Demir']::text[], 8.5, '{"poet":"Devran Demir","poet_slug":"devran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/bin-soguk-bir-kis-bin-cocuk-bir-dus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Sorma Aşkı', 'bana-sorma-aski-i-smail-haki-simsek-ck4hz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayatı renkleriyle

Biçimsiz bir tablo yapmış birileri

İsmini veremem bebe''m

Aşk kızar küçülürüm

Bana sorma aşkı

Logolarla ev yapmadım hiç

Topaçlar döndürdüm

Dünyadan daha hızlı

Bu cüsse Picasso''yu aldatır

Aşk küser küçülürüm', 'Hayatı renkleriyle Biçimsiz bir tablo yapmış birileri İsmini veremem bebe''m Aşk kızar küçülürüm Bana sorma aşkı Logolarla ev yapmadım hiç To...', ARRAY['Türk Edebiyatı','Şiir','İsmail Haki Şimşek']::text[], 8.5, '{"poet":"İsmail Haki Şimşek","poet_slug":"i-smail-haki-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bana-sorma-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On Kasım''a Ağıt', 'on-kasim-a-agit-muharrem-cetinkaya-rlrea', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biz seni hiç anlatamadık-atam- 

Umudum dediğin gençliğe

Saçlarının sarılığını moda yaptılar

Gözlerine sürdüler

Entelliklerinde

_____- maviliğini

Gözlerinin

.

Makyajlı gezdiler yıllar yılı

Sonunda

Kendileri bile inandı 

Aynadaki akislerine.

Oysa

Nakış gibi işlemeliydik

Fikirlerini yüreklere

Ve hepsi gurur duymanın yanında 

_tarihiyle

_şerefiyle

_.............

“çılgın”olmalıydılar,

Tıpkı kahraman ecdadı gibi…

Şimdi yakalarında rozetin

Yürekleri ürkek

 korkuyorlar gözlerindeki şimşek gibi

_______________direktiflerden

.

Hani bir gelsen diyorum:

_bir gece 

_ansızın

_girsen düşlerimize

_bir su serpsen

uyansak,

bir su serpsen yüreğimize

…………….

Bakışlarında yüreklendirip

Dik durmayı öğretsen

Yolumuz yolundan geçe

Ve

Başımızı öne eğmesek

Her 10 Kasım’da

Saat Dokuzu beş geçe..', 'Biz seni hiç anlatamadık-atam-  Umudum dediğin gençliğe Saçlarının sarılığını moda yaptılar Gözlerine sürdüler Entelliklerinde _____- mavili...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/on-kasim-a-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüregimdeki gemi', 'yuregimdeki-gemi-meryem-i-sler-3a8nx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Batıyordu yüregimdeki gemi

Yok oluşuna ağlıyordu

Gözlerim gizli gizli

Gömüldü hayallerim hiç yaşanmamış gibi

Açmıştı deniz o kocaman ağzını

Bir lokmada yutuverdi tüm umutlarımı

Anılarım giderken içim için için sızladı

Batarken yüregimdeki gemi yalnızdı

Söz vermişti  beni bırakmayacaktı

Beyaz köpükler bıraktı ardında 

İçi boş baloncuklarla

Kandırmış beni meğer yıllarca

Batıyordu yüreğimde ki ğemi 

Oysa ne çok inanmıştım ona', 'Batıyordu yüregimdeki gemi Yok oluşuna ağlıyordu Gözlerim gizli gizli Gömüldü hayallerim hiç yaşanmamış gibi Açmıştı deniz o kocaman ağzını ...', ARRAY['Türk Edebiyatı','Şiir','Meryem İşler']::text[], 8.5, '{"poet":"Meryem İşler","poet_slug":"meryem-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yuregimdeki-gemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OYUNcak Silah', 'oyuncak-silah-cihan-kaya-dpz3s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ben mahfoluşun galibi 

sen aşk savaşının yenilgisi 

gözün elde oyuncak silah gibi 

ilgisizlerin en içten ilgisi...', 'ben mahfoluşun galibi  sen aşk savaşının yenilgisi  gözün elde oyuncak silah gibi  ilgisizlerin en içten ilgisi......', ARRAY['Türk Edebiyatı','Şiir','Cihan Kaya']::text[], 8.5, '{"poet":"Cihan Kaya","poet_slug":"cihan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/oyuncak-silah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Sızım', 'gonul-sizim-belgin-turan-efzup', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir hayalet O karşında gördüğün,

Sevdan için değer her gün öldüğün.

Gerçek gibi dolaşan, yiyip, içen,

Uykusuz gecelerde keder biçen,

Bekler ki hep geçsin zaman,

Atlayarak yaşamadan,

Sevgiliyi görmek ister,

Gün geçsin der: Çilem bitsin.

Kimse görmez gözyaşını,

Kendi bilmez günahını.

Kurulu bir saat gibi,

Geleceği anı bekler,

Kahreden acı nöbetler.

İşte geldi en büyük an,

Can nasılda ona hayran.

Gözlerine inanamaz,

Yüreğine sığdıramaz.

Belki bin kez öpmek ister,

Acıları dökmek ister.

Döner ayrılınca başa,

Kader bakmaz ki gözyaşa.

Der: Nasıl da çok sevmişim,

O dur benim tek ruh eşim.

Zaman yine çabuk geçsin,

O yaşanan bir an için.

Belgin TURAN

''Güzden Önce Aşktan Sonra'' adlı şiir kitabımdan alınmıştır.

Gündüz Kitabevi Yayınları

Demet 7. Sokak No:7/b

Yenimahalle/Ankara', 'Bir hayalet O karşında gördüğün, Sevdan için değer her gün öldüğün. Gerçek gibi dolaşan, yiyip, içen, Uykusuz gecelerde keder biçen, Bekler ...', ARRAY['Türk Edebiyatı','Şiir','Belgin Turan']::text[], 8.5, '{"poet":"Belgin Turan","poet_slug":"belgin-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gonul-sizim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağrı', 'cagri-hasan-husnu-sula-0fjtx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özlemle aradım seni yıllarca

Ülkeleri karış karış dolaştım

Sarp dağları kızgın çölleri aştım.

Gün ışığında yürürken

Düzgün yollarda şaştım.

Halifeyim.

Omuzlarıma emanet edilen bu yük

Dağları sarsacak derece büyük.

Bir daldan bir dala atlayıp durdum

Küfür batağından kaçayım derken

Nifak girdabında boğuldum.

Cahiliye dönemi geri döndü yurduma

Fakat bu kez daha asri, daha süslü, daha şık

Görüşler bulanık, kafa karışık.

Ebu Cehil, Ebu Leheb yeniden doğuyordu.

İdealler derin bir gaflet uykusundayken

Kaplan yuvalarında çakallar uluyordu.

Zifiri karanlıkta beynimin kıvrımları

Şimşek çaktı ansızın yırtan karanlıkları

Bir ses geldi maveradan:

''Ey bürünmüş mihmandar! 

Uyku zamanı değil, silkin, uyan ve uyar! 

Sığın yüce Rabbine. Allah büyük, Allah bir

Ne nefsinde bir kibir, ne eteğinde bir kir,

Sıratı müstakime tertemiz olarak gir! ''

Bir bahar seherinde çiçek açtı tomurcuk.

Dünyaya gözlerini yeni açmış bir çocuk,

Nun karnından çıkan karaya

Yunus gibi

Yepyeni bir istekle dalarken yaşamaya

Seni buldu bu gönül, güllere ad veren gül...

Sen ey! ...

Çöllerin ortasından parlayan güneş,

Zulmeti nura döndüren ışık

Yüreğimi kor gibi dağlayan ateş,

Sevda ne demektir öğreten maşuk! ..

Suya hasret pare pare çatlayan topraklara

Rahmet yüklü yağmur bulutu ol, gel...

Ezilen, horlanan topluluklara

Eşitlik, adalet umudu ol, gel...

Gel ey şahit, et müjdeci! ...

Uyarıcı ve davetçi! ...

Gel! Kararmış gönüllere nur.

Gel! Ey sevinç ve sürur.

Gel! Bunalımlara şifa

Gel! Ahde ve misaka vefa

Gel! Ya Muhammed Mustafa...

Senin gelişinle vicdanlar özgür.

Gelişinle ufuklar aydınlığa bürünür.

Rüzgar diriltici hayat soluğu

Yürekler gümbür gümbür.

Gelişin bir muştu. Gelişin umut

Gelişin, insanlığın mutlu olduğu gündür.', 'Özlemle aradım seni yıllarca Ülkeleri karış karış dolaştım Sarp dağları kızgın çölleri aştım. Gün ışığında yürürken Düzgün yollarda şaştım. ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüsnü Sula']::text[], 8.5, '{"poet":"Hasan Hüsnü Sula","poet_slug":"hasan-husnu-sula","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/cagri-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-sinan-goztas-p92q6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğim İstanbul akşamları

Bir vapur kalkar Beşiktaş''a

Eminönü sen

Beyoğlu sen.

Atarım başımı yatarım geceleri

Düşümde sen

Beni kurtaramaz hiçbir güç

Bu bataklıktan

Balçığım sen.

Dirilişin simgesi bu kavgam

Sonuna kadar yürüdüğüm

Mücadelem sen.

Birden 

Yok olurum

Ustura ağzında bir kalabalık

Sonsuz sevdayı ararsın

Cesedimi görürsün ansızın

Ölümüm sen...', 'Yüreğim İstanbul akşamları Bir vapur kalkar Beşiktaş''a Eminönü sen Beyoğlu sen. Atarım başımı yatarım geceleri Düşümde sen Beni kurtaramaz h...', ARRAY['Türk Edebiyatı','Şiir','Sinan Göztaş']::text[], 8.5, '{"poet":"Sinan Göztaş","poet_slug":"sinan-goztas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-675-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nice Yıllara -I-', 'nice-yillara-i-mustafa-sekerci-cn5ww', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Varlığınla dünyamı dolduruyorsun amma.

Sevilmen tatlı acı, sevmen bin bir muamma.

Nice on kasımları mutlulukla idrak et. 

Hoş geldin can damarım, sen hoş geldin dünyama.', 'Varlığınla dünyamı dolduruyorsun amma. Sevilmen tatlı acı, sevmen bin bir muamma. Nice on kasımları mutlulukla idrak et.  Hoş geldin can dam...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Şekerci']::text[], 8.5, '{"poet":"Mustafa Şekerci","poet_slug":"mustafa-sekerci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nice-yillara-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nice Yıllara', 'nice-yillara-mustafa-sekerci-fqcpr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne hüzün nede keder değmesin gözlerine.

Yıldız yağsın göklerden  ipeksi ellerine.

Bu şiir doğum günü hediyem olsun sana. 

Gönlümden derlediğim bir demet gül yerine.', 'Ne hüzün nede keder değmesin gözlerine. Yıldız yağsın göklerden  ipeksi ellerine. Bu şiir doğum günü hediyem olsun sana.  Gönlümden derlediğ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Şekerci']::text[], 8.5, '{"poet":"Mustafa Şekerci","poet_slug":"mustafa-sekerci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nice-yillara-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolacağım Kursağınızı', 'yolacagim-kursaginizi-sinan-goztas-he0ox', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Utanmayın 

Yiyin

Fakirin hakkını

Aç olanın umudunu

Tüyü bitmemiş yetim hakkını

Sofrada bağdaş kuranı

Gecede bekçi duranı

Tablada alınteri satanı

Utanmayın 

Yiyin

Bu dünya size kalsın

Bu sızı bana kalsın

Öbür tarafta bir fırsat kalsın

Yolacağım kursağınızı...', 'Utanmayın  Yiyin Fakirin hakkını Aç olanın umudunu Tüyü bitmemiş yetim hakkını Sofrada bağdaş kuranı Gecede bekçi duranı Tablada alınteri sa...', ARRAY['Türk Edebiyatı','Şiir','Sinan Göztaş']::text[], 8.5, '{"poet":"Sinan Göztaş","poet_slug":"sinan-goztas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yolacagim-kursaginizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçluyum', 'sucluyum-abdullah-atay-aa6us', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bağımdaki kızıl gül goncasına 

Her dokunuşumda 

Hele bir de koklayışımda 

Sen düşersin aklıma... 

Suçluluk duyar 

Yanar ağlarım....', 'Bağımdaki kızıl gül goncasına  Her dokunuşumda  Hele bir de koklayışımda  Sen düşersin aklıma...  Suçluluk duyar  Yanar ağlarım.......', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sucluyum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür Kısa', 'omur-kisa-ramazan-ates-n52d8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel seninle bir anlaşma yapalım, 

Ben acıyı sen ölümü yazma hiç. 

Ben sevgiyi ve güzeli yazayım, 

Sen hayatı yudum yudum koyda iç. 

Ben hüzünlü, sen karamsar oluyor, 

Ne özümüz, ne yüzümüz gülüyor. 

Bundan sonra karaları koyalım, 

Omur kısa gel zevkini alalım. 

Zor gelse de başlayalım bir yerden. 

Niye teslim olalım ki, çok erken. 

Bırak derdi ve elemi kederi, 

Sevgi yeter, gel sunalım yürekten. 

Bizi gören bizden mutlu olmalı, 

Mutluluğa bizden ilham almalı, 

Bu anlaşma ömür boyu sürsün gel, 

Güzel gözün, gonca yüzün, gülsün gel

Enschede-9.11.2005', 'Gel seninle bir anlaşma yapalım,  Ben acıyı sen ölümü yazma hiç.  Ben sevgiyi ve güzeli yazayım,  Sen hayatı yudum yudum koyda iç.  Ben hüzü...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/omur-kisa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efendim', 'efendim-mikdat-bal-68r9a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İp piçin eline geçti geçeli

Bize bir hal oldu, sustuk efendim

Koç yiğitler burdan göçtü göçeli

Zehir içtik kanlar kustuk efendim

Elin gavurunu bize övdüler

Ecdadımı inkar edip sövdüler

Bacımıza öcü deyip dövdüler

Ses etmedik ancak küstük efendim

Bir yanda sefalet bir yanda sefa

Bir yanda mutluluk bir yanda cefa

Bu gariban halkım gülse bir defa

Onlardan ilgiyi kestik efendim

Geri kaldık var bir çok sebebimiz

Hortumcular çaldı boştur cebimiz

Borçlarını vermek için hepimiz

Kemer sıktık boğaz kıstık efendim

Bal der millet yine yanlış oyladı

Uyardığım herkes beni payladı

Atı alan Üsküdarı boyladı

Çığlıkla feryadı bastık efendim', 'İp piçin eline geçti geçeli Bize bir hal oldu, sustuk efendim Koç yiğitler burdan göçtü göçeli Zehir içtik kanlar kustuk efendim Elin gavuru...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/efendim-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanayan', 'kanayan-sinan-goztas-w6h9l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Denizaşırı bir ülke yeşeren göğün en sıcak yüzüne

Ebegümeci yalnızlığında sığ bir bekleyiş

İki tarafı yasak kelimeler

Islak aydınlığı büyütmesi zor bir utangaçlık

Kitap aralarına sıkışan demirden örülü bir korkuluk

Deriden çekilen kabuk bağlamamış yaralar

Ve kanayan bir aşkın ilk ışıklarını yakan

Yüreğir...

Yüreğir...', 'Denizaşırı bir ülke yeşeren göğün en sıcak yüzüne Ebegümeci yalnızlığında sığ bir bekleyiş İki tarafı yasak kelimeler Islak aydınlığı büyütm...', ARRAY['Türk Edebiyatı','Şiir','Sinan Göztaş']::text[], 8.5, '{"poet":"Sinan Göztaş","poet_slug":"sinan-goztas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kanayan-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-hidir-altas-zvzpn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben bir arı olsam, sende gül

Gelsem konsam yapraklarına

Bir aşağı, bir yukarı dolaşsam

Koklasam seni bir seher vakti

Nafile güzelim gelemem yanına

Çünkü kanadım kırık, çaresizim

Ölüme terkedildim bir köşede

Ölmeye mahkumum ben güzelim

İkimiz kuzu olsak yaylalarda

Çayırlarda koşsak, zıplasak dursak

Sonra kıvrılıp yatsak bir köşeye

Kalsak başbaşa, baksak yarınlara

Nafile güzelim gelemem yanına

Ayaklarım kırık çaresizim

Ben seninle koşup zıplayamamki

Ben yalnızlığa mahkumum güzelim

Sen ve ben leylek olsak bir köyde

Uçsak gitsek şöyle bir ovalara

Sonra yavrularımızı taksak peşimize

Nafile güzelim gelemem yanına

Çünkü kanadım kırık kaldım ovada

Git güzelim git bak kış geliyor

Ben seninle gelememki

Ben yalnızlığa mahkumum

Turhani derki keklik olsak dağlarda

Seksek seninle taştan taşa

Sonra palazlarımız olsa bir çok

Çıksak taşlara ötsek bir kuşluk vakti

Nafile güzelim gelemem yanına

Gözlerim kör uyamam ben sana

Git güzelim git bak avcılar geliyor

Ben seninle kaçamamki

Ben vurulmaya mahkumum', 'Ben bir arı olsam, sende gül Gelsem konsam yapraklarına Bir aşağı, bir yukarı dolaşsam Koklasam seni bir seher vakti Nafile güzelim gelemem ...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Altaş']::text[], 8.5, '{"poet":"Hıdır Altaş","poet_slug":"hidir-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sen-ve-ben-141-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önsöz', 'onsoz-sinan-goztas-1dmhj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Olmadı hiçbir zaman önsözüm

Kuşe kağıdına basılı bir yalanda

Nasıl olsun ki; 

Şaşkın yazanlar listesinde

Gizli bir biyografisi

Erdem çamurunda yüzenlerin.', 'Olmadı hiçbir zaman önsözüm Kuşe kağıdına basılı bir yalanda Nasıl olsun ki;  Şaşkın yazanlar listesinde Gizli bir biyografisi Erdem çamurun...', ARRAY['Türk Edebiyatı','Şiir','Sinan Göztaş']::text[], 8.5, '{"poet":"Sinan Göztaş","poet_slug":"sinan-goztas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/onsoz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bize Göre Değil', 'bize-gore-degil-sinan-goztas-ovgfy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bize göre değil...

Kirli zamanların ısındığı,yeşil yapraklı bir geçimsiz engebe

Ağlarına ayrıkotu dolaşmış balıkçı yazgısı

Bize göre değil...

Ağzı rakı kokan akşam düşüncesizliği

Bırakmak bir çiçeği kuru dalında

Kitapları öğütülmüş bir genç

Göğünde incelen bir ay

Gürültüsüz,kavgasız sandalye kenarına ilişmiş bir kıç

Değil ihanet

Bize göre değil...', 'Bize göre değil... Kirli zamanların ısındığı,yeşil yapraklı bir geçimsiz engebe Ağlarına ayrıkotu dolaşmış balıkçı yazgısı Bize göre değil.....', ARRAY['Türk Edebiyatı','Şiir','Sinan Göztaş']::text[], 8.5, '{"poet":"Sinan Göztaş","poet_slug":"sinan-goztas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bize-gore-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutanak', 'tutanak-melih-coskun-224na', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kırılganlığımın kaydını düşüyor 

Şimdi bütün kalemler

Kandan mürekkepleriyle. 

Morarmış gözlerimin çukuruna 

Binlerce Akdeniz sığdırdım 

Bir martının parıldayan gözlerinden gördüm 

Sınırları acılarla çizilmiş dünyayı  

Yalnızım diyorum sürekli

Şikayet etmiyorum ama

Şiirime kastediyor 

Bütün gereksiz kalabalıklar. 

Tökezleyip düştüğüm yerde 

Üzerime basarak geçiyorlar 

Farkına bile varmadan.

Hiç bir tutanakta yazmıyor seni nasıl sevdiğim 

Ve nasıl sevdiğim kanatılmış ülkemi.

Yedi ceddimin hatırını soruyor sorgucular 

Geceler boyu 

Söyleyecek hiç bir şey gelmiyor aklıma 

Adından başka.. 

Aşkın

En asi rüzgar kavgamın yelkeninde, 

İçini seninle dolduruyorum 

Bütün yalnızlıklarımın. 

Acıtmıyor 

Bileklerimi oyan şu kelepçe

Senin ellerimi bir kerecik olsun 

Tutmayışın kadar...

2005', 'Kırılganlığımın kaydını düşüyor  Şimdi bütün kalemler Kandan mürekkepleriyle.  Morarmış gözlerimin çukuruna  Binlerce Akdeniz sığdırdım  Bir...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/tutanak-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Zaman Beni Anlayacaksın', 'o-zaman-beni-anlayacaksin-tijen-karabina-la5qq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne kadar uzak olursan benden,

O kadar yaklaşmak isteyeceksin.

Gün gelip te sabırlar bitiverince,

Hasretin ateşini hissedeceksin.

Sarılmak isteyeceksin boş hayalime,

Kollarının arasından kaybolup gideceğim.

O gün ki bana özlem duyunca,

Yalnızlık korkusuyla tükeneceksin.

Çaresizlik saracak dört bir yanını,

Sevgini paylaşacak birini arayacaksın

O gün ki kimse seni anlamayınca,

O zaman beni anlayacaksın...', 'Ne kadar uzak olursan benden, O kadar yaklaşmak isteyeceksin. Gün gelip te sabırlar bitiverince, Hasretin ateşini hissedeceksin. Sarılmak is...', ARRAY['Türk Edebiyatı','Şiir','Tijen Karabina']::text[], 8.5, '{"poet":"Tijen Karabina","poet_slug":"tijen-karabina","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/o-zaman-beni-anlayacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peronda', 'peronda-meral-vurgun-zdx40', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bekliyorum

gelişine beş var

heyecan göğe tırmanıyor

yüreğim koptu kopacak

gelişine beş var 

soğuk yüzlü yolcular

valizlerinde bir yudum sevgi 

birer ikişer gidecekler

öyle bir şey ki öpüşmek

korkarım dudaklarımız şişecek...', 'bekliyorum gelişine beş var heyecan göğe tırmanıyor yüreğim koptu kopacak gelişine beş var  soğuk yüzlü yolcular valizlerinde bir yudum sevg...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/peronda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-duran-dalkilic-qf7qz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rüzgarla savrulur goncalar,güller

Güle hasret ölür öten bülbüller

Maziye karışır yaşanan günler

Zaman bu herşeyi siler götürür

Kaybolur umudun ışığın söner

Ömrünün baharı hazana döner

Kaderin cilvesi senide yener

Hayat bu herşeyi alır götürür.

(03.01.1989)', 'Rüzgarla savrulur goncalar,güller Güle hasret ölür öten bülbüller Maziye karışır yaşanan günler Zaman bu herşeyi siler götürür Kaybolur umud...', ARRAY['Türk Edebiyatı','Şiir','Duran Dalkılıç']::text[], 8.5, '{"poet":"Duran Dalkılıç","poet_slug":"duran-dalkilic","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/zaman-252-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-gulseren-onay-fux1y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İstemem ölümü bu kadar erken

Ne ruhumdan vazgeçerim

Ne de bedenimden 

Hala yaşayamadığım

Aşklarım varken', 'İstemem ölümü bu kadar erken Ne ruhumdan vazgeçerim Ne de bedenimden  Hala yaşayamadığım Aşklarım varken...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/olum-222-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereye', 'nereye-duran-dalkilic-pwdvl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bırakıpda beni mahzun hallerde

Candan sevdiğim o yarim ellerde

Benimse bu halim şimdi dillerde 

Nereye gençliğim,nereye böyle

Bıraktın artık sen beni bir yana 

Yazıktır,günahtır şu mahzun cana

Sitemkar oldum bak şimdi ben sana

Nereye gençliğim,nereye böyle

Yalnız kaldım şimdi tek bir başıma 

Bakmadın gözümden akan yaşıma

Gariban yazdırdın mezar taşıma

Nereye gençliğim,nereye böyle

(12.02.1991)', 'Bırakıpda beni mahzun hallerde Candan sevdiğim o yarim ellerde Benimse bu halim şimdi dillerde  Nereye gençliğim,nereye böyle Bıraktın artık...', ARRAY['Türk Edebiyatı','Şiir','Duran Dalkılıç']::text[], 8.5, '{"poet":"Duran Dalkılıç","poet_slug":"duran-dalkilic","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nereye-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur', 'ne-olur-duran-dalkilic-kpmze', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sende benim gibi alsan kalemi,

Birkaç satır mektup  yazsan ne olur.

Seviyorum seni desen mektupda, 

Bütün hep dünyalar hep benim olur.

(20.12.1988)', 'Sende benim gibi alsan kalemi, Birkaç satır mektup  yazsan ne olur. Seviyorum seni desen mektupda,  Bütün hep dünyalar hep benim olur. (20.1...', ARRAY['Türk Edebiyatı','Şiir','Duran Dalkılıç']::text[], 8.5, '{"poet":"Duran Dalkılıç","poet_slug":"duran-dalkilic","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ne-olur-78-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanayan Avuçlarımla..Kendime Sarıldım...', 'kanayan-avuclarimla-kendime-sarildim-busra-sahin-ogext', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçimdeki tüm sevgiye rağmen,

Ellerimle iterken seni kendimden,

Kanayan avuçlarımla,

Kendime sarıldım...

Şimdi ölmek zamanıydı..

Ölmek ve......

Bu dayanılmaz gelen,

Acıyı hissetmemek....

Yarım yamalak düşlerdi benimkisi,

Başı sonu olmayan..

Düşlerde yalan oldu.. 

Sende... 

Yalan...

Kanayan avuclarımla,

Kendime sarıldım...

09/11/2005 

ஐ ๑ KЄ di§ (@)    ๑ ஐ', 'İçimdeki tüm sevgiye rağmen, Ellerimle iterken seni kendimden, Kanayan avuçlarımla, Kendime sarıldım... Şimdi ölmek zamanıydı.. Ölmek ve.......', ARRAY['Türk Edebiyatı','Şiir','Büşra Şahin']::text[], 8.5, '{"poet":"Büşra Şahin","poet_slug":"busra-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kanayan-avuclarimla-kendime-sarildim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaşım Hüzün', 'arkadasim-huzun-alper-torun-w7l0d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yani sakil durmuyor bende hüzün.

Ne yalan söyleyeyim,

İlk başlarda kendi tercihim olmasa da

sonraları hüznü ben de sever oldum.

Böylece arkadaş olduk; 

Birlikte ağladık masumlara, 

Mahzunlara ve dahi mahrumlara

Ve birlikte güldük hüzünle; 

hiçbir zaman doyasıya kahkaha atamadık belki ama

hazin de olsa tebessüm eksilmedi dudağımızın bir kenarından.

Şimdi artık öylesine benimsedik ki birbirimizi,

dudağımızda tebessüm, 

Gözümüzde buğulu bakışlar, 

Kirpiğimizin ucunda hazır duran bir kaç damla yaşla 

Gönül penceresi açık dostlar arıyoruz kendimize.

”Buluruz elbet” diye içimizde 

Ümit tohumları yeşertmeye gayret ederek,

 geçip gitmekteyiz dünya denilen kısa süreli fani konaklıktan...

03.06.2005

Dost Abidin’in tespitine cevap…', 'Yani sakil durmuyor bende hüzün. Ne yalan söyleyeyim, İlk başlarda kendi tercihim olmasa da sonraları hüznü ben de sever oldum. Böylece arka...', ARRAY['Türk Edebiyatı','Şiir','Alper Torun']::text[], 8.5, '{"poet":"Alper Torun","poet_slug":"alper-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/arkadasim-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senlilik ve sensizlik…. Sessizlik… susuzluk', 'senlilik-ve-sensizlik-sessizlik-susuzluk-selman-faris-karakose-j3ibb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senlilik ve sensizlik…. Sessizlik… susuzluk

Ve bilmezsin ki gülüşlerim sessizliğe düşerdi…

Bilmezsin ki.. benim sensiz kalmışlığımda ağladığımı.

Çokça yağmurlarla kavga etmişliğimden haberin yoktu.

Beni tanıyana kadar…. Aşk yoktu

Ola ki bir an, ansızın, anılmadığım bir vakitti 

Nisan yağmurlarıyla ah deyişlerim.

Senlilik ve sensizlik…. Sessizlik… susuzluk

Aşk besmelesiyle koyulur …..

En iyisi ya.... yular takılmış gibi sürüklenmiyorum peşinden hayallerin,

Hayaller peşimden sürükleniyor.

Şimdi bulutların üstüne kocaman kancalar atıyorum

Ve sana hayaller indiriyorum, 

Masmavi beşiklerden bembeyaz hayaller

Ben sende kalan ümitsizlikleri alıyorum kendime... hayaller …. 

….halsizlikler...... bir aleme bin tebessüm yükleyen halsizlikler

Gizli öznesinde kötü, kötü öznesinde gizli hal, hallerinde tebessüm…..

Çokça gülmelerim var lakin yalnız ağlamalarım da…

Mim mekanında, lâl bekleyişlerim sırra haiz bir hazine

Hazinelerin içinde bin bir zan, zanaat….. mabet….

Ve mabet içinde bir efsunlu aşk, bir sanduka

Senlilik ve sensizlik…. Sessizlik… susuzluk

Toz ayan gibi kalkar gözlerimin önünden, 

Billura durur bir nihal sevda,

Nihayetine dem kala göz yaşına vurur.

Depreşir tüm arz, vesselama bırakır kendini,

Kendi etrafına kandiller dizer, 

Ardından nihal de buluşur tüm sarmaşıklar.

Ne sırrına meftun, ne meftuna hasret kalır

Demişim ki ben; mazide çok yoruldum,

Yararsız bir matem imiş meğerse

Yorgunlum boşunaymış. Varolan yekpare

Senlilik ve sensizlik…. Sessizlik… susuzluk…

Dökülür usulcana çiçekler, şarka dönerler,

Kelebeklerin nura, bedenin toprağa, derdin devaya,

Gurbetin vuslata, 

Gecenin güne dönüşü gibidir nihale dönüş…

Nihale dönüş, kendine dönüşün ötesindedir,

Sevdaya dönüştür, mabede dönüş, hallerden halsizliklere…

Sensizlikten senliliğe, susuzluktan gümrah ırmaklara, 

Sessizlikten, şarkılaradır…

Bitmemektir…

Yitmemektir…

Gitmemektir…

Nihaledir, nihal ile nihayetedir… 

Selman Faris KARAKÖSE

(10.11.2005)', 'Senlilik ve sensizlik…. Sessizlik… susuzluk Ve bilmezsin ki gülüşlerim sessizliğe düşerdi… Bilmezsin ki.. benim sensiz kalmışlığımda ağladığ...', ARRAY['Türk Edebiyatı','Şiir','Selman Faris Karaköse']::text[], 8.5, '{"poet":"Selman Faris Karaköse","poet_slug":"selman-faris-karakose","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/senlilik-ve-sensizlik-sessizlik-susuzluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...........Atatürk Ölüyor.', 'ataturk-oluyor-suheyl-turkoglu-81409', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gün on kasım,

Bakmayın gözyaşıma,

Ağıtçı değilim,

Kahrımdan serzenişim,

Yıllar sonra panikliyorum,

Atatürk ölüyor.', 'Bu gün on kasım, Bakmayın gözyaşıma, Ağıtçı değilim, Kahrımdan serzenişim, Yıllar sonra panikliyorum, Atatürk ölüyor....', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ataturk-oluyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Affet /me ATAM!', 'affet-me-atam-fatma-caglayan-cwgdo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mahcubuz sana karsı ATAM! 

Bilmiyorum nerden başlasam 

Sen bırakıp gittikten sonra 

Pek ilerleyemedi bu VATAN 

Gidemiyor çünkü engelleniyor 

Emanet ettiğin bu vatan 

Ne içerde ne de dışarıda 

Başarılı değiliz ATAM! 

İrtica, türban diye bağıranlar 

Dini istismar eden şarlatanlar 

Teröristler can alıyor bir yandan 

İçimiz kan ağlıyor ATAM! 

Misyonerler hala aramızda 

Çalışıyorlar arı gibi dört bir yanda 

Kimisi uğraşıyor dinimizle 

Kimileri de toprağımızla… 

Alacaklarmış bizi, ortak pazara 

Öyle söylüyor senelerce, Avrupa 

Yeter ki her dediklerini yapalım 

Sürüyorlar bir parmak bal ağzımıza 

Ermeni soykırımı var dediler 

Avrupa da anıtlar diktiler 

Yalandır, iftiradır diyemedik 

Elimizde olduğu halde belgeler… 

Elimizi verdik, kolumuzdan oluyoruz 

Bir türlü, ortak pazara giremiyoruz 

Oynuyorlar bizimle ATAM! 

Sözümüzü geçiremiyoruz… 

Diğer tarafta desen Amerika 

Soktu bizi IMF iyice borca 

Biz olmuşuz ellerinde kukla 

Emirler yağdıran yağdırana 

ATAM! Sen gittin gideli 

Durumumuz çok vahim 

Maalesef çalışkan olamadık 

Vatanımızı iyi koruyamadık... 

Affet/me  bizi ATAM!', 'Mahcubuz sana karsı ATAM!  Bilmiyorum nerden başlasam  Sen bırakıp gittikten sonra  Pek ilerleyemedi bu VATAN  Gidemiyor çünkü engelleniyor ...', ARRAY['Türk Edebiyatı','Şiir','Fatma Caglayan']::text[], 8.5, '{"poet":"Fatma Caglayan","poet_slug":"fatma-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/affet-me-atam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İbiş''in Rüyası', 'i-bis-in-ruyasi-suheyl-turkoglu-a4oqb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dudaklarınla dokun,

Göğüslerinle ver

Elektriğini,

Ateşinle ısıt

Vücudumu,

Arzunla kavur

Beynimi,

Çıldırt,

Zevkler doruğunda

Arayayım kendimi.

En kıralını

Bu uğurda

Feda edeyim.

Vücudun vücudumla

Sarmaş dolaş,

İçimde deprem,

Okşadıkça avuçlarım,

Uydu anten gibi

İletsin beynime

Daha fazla,

Daha fazla,

Sarılalım

Dünya batsa.', 'Dudaklarınla dokun, Göğüslerinle ver Elektriğini, Ateşinle ısıt Vücudumu, Arzunla kavur Beynimi, Çıldırt, Zevkler doruğunda Arayayım kendimi...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ibis-in-ruyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece Yılbaşı', 'bu-gece-yilbasi-cengiz-manga-9w6gp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gece yılbaşı...

Bozdoğan karanlık,

Yanmıyor ışıkları kasabanın...

Trafo patlamış diyorlar...

Yazgıya bak,bu gece yılbaşı...

Evet bu gece yılbaşı..sevdiceğim,

Diğerlerinden çook farklı...

Dışarıda yağmur yağıyor,

Camlara savurturcasına...

Bahçede portakal ağaçları...

Tebrik ve mektubunu getirdi bugün postacı.

Seni,bundan böyle unutmamı yazıyordun nedense....

Oysa ayrılmak yoktu yeminlerimizde.

Hani sen benim bende senin ilk göz ağrımdın...

Öyle mi? ....! 

Şimdi ayrılıyoruz,sen yoluna ben yoluma...

İşte bak saat on ikiyi vurdu,

Uyuduğunu sanmıyorum.

Her şeye rahmen bin dokuz yüz altmış yedi,

Sana mutluluk getirsin,sevdiceğim mutluluk...

Biz taş basmasını da biliriz bahrımıza....

                                       31/12/1967    Bozdoğan/AYDIN', 'Bu gece yılbaşı... Bozdoğan karanlık, Yanmıyor ışıkları kasabanın... Trafo patlamış diyorlar... Yazgıya bak,bu gece yılbaşı... Evet bu gece ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Manga']::text[], 8.5, '{"poet":"Cengiz Manga","poet_slug":"cengiz-manga","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bu-gece-yilbasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Gözlerde Kaybolmak', 'mavi-gozlerde-kaybolmak-cigdem-altinoz-fkpnv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ufuklara bakıp dalarak

Ufkun ötesini görebilmekti hüneri

Yarın gelmeden daha

Yarını hazırlayabilmekti

Yatarken 

kaputu döşek sayıp

kalpağı yastık

karların üstünde

Zafer rüyalarına uyanmak

sırtına yüklenip de dertleri

bir Mayıs sabahında

hırçın mavilerle

kıraçlara yürümek

bozkırları yeşertmeye

 - ve kalbinde Anadolu’nun

bin çiçek açtırabilmek

Ölmeyi

istemek kadar 

emredebilmek

yığınları yürütebilmek

yalınayak

elif elif yağabilmek,

kağnılara dolabilmek

biz hep vardık diyebilmek

ufuklara dalarak masmavi

ufkun ötesini görebilmekti hüneri

gün doğmadan bozkırlara

güneşi sunabilmekti 

gecenin karasında

kaybetmişken umudu

bir çimdik tuz

bir avuç una muhtaçken vatan

doyurabilmekti yeniden

Söyletebilmek

Yüzyılların öyküsünü

ve Özgürlük türküsünü

Sevmekti

Sevmekti hüneri

Konuşurken,dinlenirken

Yüzyılları düşünürken

bir sigara içiminde

dostluğunu paylaşırken

kaybolurdum mavi gözlerinde

derin derin bakarken', 'Ufuklara bakıp dalarak Ufkun ötesini görebilmekti hüneri Yarın gelmeden daha Yarını hazırlayabilmekti Yatarken  kaputu döşek sayıp kalpağı y...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Altınöz']::text[], 8.5, '{"poet":"Çiğdem Altınöz","poet_slug":"cigdem-altinoz","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/mavi-gozlerde-kaybolmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sızı', 'sizi-erkan-kaner-cpqws', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'senin için gökyüzüne

astığım milyarlarca yıldızı

dene görmemezlikten gelmeyi

deneyebilirsen

mümkünü yok, kalacak yine de

kalbinde derin bir sızı

unut hadi

unutabilirsen

                                          (7 kasım 2005)', 'senin için gökyüzüne astığım milyarlarca yıldızı dene görmemezlikten gelmeyi deneyebilirsen mümkünü yok, kalacak yine de kalbinde derin bir ...', ARRAY['Türk Edebiyatı','Şiir','Erkan Kaner']::text[], 8.5, '{"poet":"Erkan Kaner","poet_slug":"erkan-kaner","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sizi-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani bazen...', 'hani-bazen-hasan-esat-heptunali-gvsra', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hani bazen...

bi insan dilersin yanında...

ki...

kim olduğu önemli değil...

bi insan sıcağıdır  aradığın...

bi bakış...

bi gülümseyiş belki...

hem de hiç pazarlıksız...

ne sen...

ne de o...

sorumluluk hisseder karşısındakine....

ama ordadır işte...

öyle bi gülümseyiş ki...

gülümsetir seni...

ya da ne bileyim..

öyle sarhoşum ki...

ondandır bu dile gelişim..

görmedi kimse...

bu denli çıplak beni...

göremez de...

ama  çıplağım...

çırıl çıplak hem de...

yine de....

görmedi kimse...

göremez de...

desem de

..................

biliyorum...

green park merter...', 'hani bazen... bi insan dilersin yanında... ki... kim olduğu önemli değil... bi insan sıcağıdır  aradığın... bi bakış... bi gülümseyiş belki....', ARRAY['Türk Edebiyatı','Şiir','Hasan Esat Heptunalı']::text[], 8.5, '{"poet":"Hasan Esat Heptunalı","poet_slug":"hasan-esat-heptunali","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hani-bazen-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretimsin Ozan''ım', 'hasretimsin-ozan-im-nesrin-gocmen-92wzx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bakarken ışıl, ışıl,

Beni süzer, Ozan''ım.

Uyurken mışıl, mışıl,

Sevgi gözler, Ozan''ım.

.

Tuttuğunda elimden,

Umut taşar selinden.

Ballar akan dilinden,

Coşar sözler, Ozan''ım.

.

Gözlerine vuruldum,

Ağlamana darıldım.

Beklemekten yoruldum,

Yandı közler,  Ozan''ım.

.

Nur saçan meleğimsin,

Sevda çiçeğim,  sensin.

Uğur böceği misin? 

Ermiş yüzlü,  Ozan''ım.

.

Yanıma geldiğin gün,

Başlar yürekte düğün.

Yarınım ve bugünüm,

Hasretimsin Ozan''ım,

Yeşeren güzüm, canım.

10/11/2005', 'Bakarken ışıl, ışıl, Beni süzer, Ozan''ım. Uyurken mışıl, mışıl, Sevgi gözler, Ozan''ım. . Tuttuğunda elimden, Umut taşar selinden. Ballar aka...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hasretimsin-ozan-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter Atam Allah aşkına yeter uyudun', 'yeter-atam-allah-askina-yeter-uyudun-halil-colak-3dbkd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yeter Atam Allah aşkına yeter uyudun

Vatan elden gidiyor bizi unuttun

Bu vatanı sen bize böylemi bırakıp gittin.

Baykuşlar ötüyor vatanda virandır bugün

On kasımda sen ölmedin millette öldü

Sen ölünce yurda palikaryalar doldu

Bu vatanın açmadan gülleri soldu

Sahiler İngiliz, Alman PKK doldu

Uyan artık Anadolu toprağı talandır bugün

Halil ÇOLAK 10.11.2005 Saat.02.35 Ankara', 'Yeter Atam Allah aşkına yeter uyudun Vatan elden gidiyor bizi unuttun Bu vatanı sen bize böylemi bırakıp gittin. Baykuşlar ötüyor vatanda vi...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yeter-atam-allah-askina-yeter-uyudun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşıkların Leyla ömrü bitecek', 'asiklarin-leyla-omru-bitecek-halil-colak-re7xw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevda gülleri bu dünyada hep böyle açacak

Bir ömür boyu Leyla seninle birlikte aşkı sevecek

Sana sahip olmadan âşıklarda hep açı çekecek

Sana kavuşamadan âşıkların Leyla ömrü bitecek

Halil ÇOLAK 10.11.2005 Ankara saat.02.55', 'Sevda gülleri bu dünyada hep böyle açacak Bir ömür boyu Leyla seninle birlikte aşkı sevecek Sana sahip olmadan âşıklarda hep açı çekecek San...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/asiklarin-leyla-omru-bitecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansiz Hiçkirik', 'zamansiz-hickirik-zeki-savci-li51f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zamansiz bir hiçkirik 

Pençe atar yüregime derinden,

Bir yani sen dolu, 

Bir yani çürük. 

burkulur yüregim orta yerinden.

Belki hayaline ulasmak icin

Dalarim bendeki gizli dünyama. 

Gözümde bulutlar, 

Yüregim egik 

sen dolu rüzgarlar carpar alnima. 

Ürperir yüregim, hizlanir birden, 

Köse, bucak sen görünür gözüme...

izini sürerim ay, yil demeden 

Sen dolu sancilar iner dizime.', 'Zamansiz bir hiçkirik  Pençe atar yüregime derinden, Bir yani sen dolu,  Bir yani çürük.  burkulur yüregim orta yerinden. Belki hayaline ula...', ARRAY['Türk Edebiyatı','Şiir','Zeki Savci']::text[], 8.5, '{"poet":"Zeki Savci","poet_slug":"zeki-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zamansiz-hickirik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alnayabilsen', 'alnayabilsen-halil-colak-2qd8f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Umutsuzluk kervanına bende katıldım

Sende uğrayıp içine bir girebilsen

Acı ile aşk karıştı cananım birden

Sevenin neler çektiğini bir anlayabilsen	

Halil ÇOLAK 10.11.2005 Ankara saat 03.07', 'Umutsuzluk kervanına bende katıldım Sende uğrayıp içine bir girebilsen Acı ile aşk karıştı cananım birden Sevenin neler çektiğini bir anlaya...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/alnayabilsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksa', 'yoksa-belgin-duran-vgr8u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İlk gördüğümde seni kayboldum sarhoş gözlerinde 

Hissettim içimde çopcukça bir heyecan

GEcem gündüzüm gözlerin oldu o an

Bağlandı sana ansızın bu can

Yemyeşil oluverdi ağaçlar

Büllbül sesli oldu kargalar

Sevgi dolu oldu insanlar

Benim oldu tüm dünyalar

YOKSA BU AŞK MI? 

Sonra ellerini benden çekti

Aldı gözlerini gitti

İçimdeki tüm güzellikler yitti

Yaşama sevincim birden bitti

O gün bugündür yüzüm gülmez

Gözlerim başka kimseyi görmez

Akan yaşım bir an  dinmez

İçimdeki acım korkarım bitmez.

YOKSA AŞK ACI MI?', 'İlk gördüğümde seni kayboldum sarhoş gözlerinde  Hissettim içimde çopcukça bir heyecan GEcem gündüzüm gözlerin oldu o an Bağlandı sana ansız...', ARRAY['Türk Edebiyatı','Şiir','Belgin Duran']::text[], 8.5, '{"poet":"Belgin Duran","poet_slug":"belgin-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yoksa-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup (Yerel)', 'mektup-yerel-mikdat-bal-85j6u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(Şaka bir tarafa bu mektupta anlatılanlar  gerçektir küçükken bu mealde bir mektup yazmıştım yaşlı bir teyzem için)  

Ey  gözumun nuri, gönlümün ilaci, başumun taci uşağum

Önce acele acele selam ederum gözlerunden, yanagundan öperum

Acele dedum habu mektubi babandan gizli gizli yazayurum

Birazda hizli hizli yazayurum, bilurum işlerun çoktur, vaktun yoktur

Sen da hizli hizli oku da işun geri kalmasun

Eşun huzursuz olmasun

Baban da nerde ise çıkar gelur.

Sonra bilursun kavga olur

Uşağum, buralardan sorar isen, ne yarar var ne yaramaz,

Kuçuk kardaşun askere gitti o bizi aramaz, 

ablanda yeni doğum yapti bize varamaz,

Ben gene açuk açuk haberleri yazacağum

Sözlerumi ters anlamaman içun mektubi sağdan sola oku

Bu sene da yayla edemeduk, inekleri gönderduk 

biz gidemeduk

Bir tane inek sattuk verduk borca Koyinlari da kattuk koca

Bu sene çayirlar eyi biterse, havalar da güzel giderse

Komşilar da yardim ederse, üç tane inek saklayacağuk

Sağolsun komşilar  tarlalari kazdiler, odunlari düzdiler

Mısırleri da öğuttiler ezdiler

Elumi sıcak sudan soğuk suya değdurmediler

İşumi yaptiler bobana döğdürmediler

Bobandan sorarsen, sabah evden çıkayur

Akşam gelup evi başuma yikayur

Ne bahçeye gider ne bağa

Ne yaylaya gider ne dağa

Boğazina da oyle düşkün değil

Çok zayıftur şiskin değil

Çok ciğdur pişkin değil

Açıktum demez, yaparsun yemez

Yapmazsun affetmez

Kırk senedur anlayamadum oni

Ayni bilduğun gibi bağırur

Çağırur sonra kafasi ağırur

Geçen gün niyet etti öbür tarafa 

Babana bir şey oldi çay içeyidi

Bir den düşti, akşamdan sonra gece idi

Sehhiye onbaşisi yoldan geçeyidi

Bağırdum hemen geldi,

Durumi anladi bildi,

Zanettum yardım edecek 

Bobanun döşüne çökti

Boğazina hortom sokti

Bir da baktum boban kalkti

Şimdi birz eyidur 

Uşağum sen nezaman geleceksun

Yoksa gurbette mi öleceksun

Guguk kuşlari oteyur

Herkes yaylaya gideyur

Misırlar biteyur,çok şükür hepumuze yeteyur

Gelun bureya bir daha göreyim sizi

Topal Ahmet öldi,

Oğli bırakup geldi

Sen da oni mi bekleyursun, 

korkma uşağum boban beni da öldürür 

seni da öldürür

O adam mi güldürür,

Rasimun kızi kaçti

İki hane köyümüzden göçti

Başka da bişe bilmeyurum

Habu mektubi cevaplandur

Kısa yaz de ki: geluyurum,

Gelmeyurum

Selam ve dua ile', '(Şaka bir tarafa bu mektupta anlatılanlar  gerçektir küçükken bu mealde bir mektup yazmıştım yaşlı bir teyzem için)   Ey  gözumun nuri, gönl...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/mektup-yerel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doyamıyorum', 'doyamiyorum-celal-topo-2dqtb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her gece yastığa baş koyarken

İnan ki seninle uykuya dalıyorum

Geceler boyu rüyalarımdasın

Neden se sana bir türlü doyamıyorum....

01 /11 / 1997 Çanakkale', 'Her gece yastığa baş koyarken İnan ki seninle uykuya dalıyorum Geceler boyu rüyalarımdasın Neden se sana bir türlü doyamıyorum.... 01 /11 / ...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/doyamiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
