INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazar Boncuğum', 'nazar-boncugum-nurten-tarim-bg5ew', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ugurum oldun nazar boncuğum

Gözlerımde bakış,damarlarımda kan

Sensiz nefes almak haram

Geceler bağlasın 

Kördüğüm olsun kader yolumuz

Aşk-ı muhabbet gecsin ömrümüz

Yandı kandiller çoştu gönüller

Hüzün bulutları dağıldı 

Gönül bahçem gonca gül

Kalp yolum sensin birtanem', 'Ugurum oldun nazar boncuğum Gözlerımde bakış,damarlarımda kan Sensiz nefes almak haram Geceler bağlasın  Kördüğüm olsun kader yolumuz Aşk-ı ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Tarım']::text[], 8.5, '{"poet":"Nurten Tarım","poet_slug":"nurten-tarim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/nazar-boncugum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Krık Kalem', 'bir-krik-kalem-temel-bayarslan-w2ulo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BİR KIRIK KALEM

Her şeye gücün yetti

Tek şey istisna 

Kalemim

Seni mat edecek

Tek dostum, güvencim

O ki

Kar yağışındaki iki çift düğün 

Güneşteki iki çarpan yüreğin 

Yağmurda ıslanan tenin 

Beraberken kıskanç gözlerin 

İntikamını alacak

Aç midelerin yazılan mürekkebin

Çizilen kağıtların 

Uykusuz gözlerin 

Biçare garibin 

İntikamını alacak 

İntikamını alacak

Geç vakitlerin 

Hastalanan kalbin 

Burkulan bir yüreğin 

Titreyen dudakların 

İntikamını alacak

Bir kırık kalemle bitecek

Vücudun kursuna olan 

Yarasının güneşe 

Sigaranın ateşe 

Manzaranın dumana olan kini 

Benim kinim

Alelade bir kalemle bitecek 

Yazık sana olan aşkımda 

Tarihe gömülecek.

26.12.1989', 'BİR KIRIK KALEM Her şeye gücün yetti Tek şey istisna  Kalemim Seni mat edecek Tek dostum, güvencim O ki Kar yağışındaki iki çift düğün  Güne...', ARRAY['Türk Edebiyatı','Şiir','Temel Bayarslan']::text[], 8.5, '{"poet":"Temel Bayarslan","poet_slug":"temel-bayarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bir-krik-kalem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Geçerken', 'zaman-gecerken-serhat-sumer-sp9i1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-sen yine yoktun-

yüreğimizin en ücra köşelerine işlerken kader

zaman gibi o ölümcül zehri

gözbebeklerinde bir ışıltı

hatırlatır eskileri

hani küçük çocuklar gibi gülümsediğimiz 

hani sessiz şarkımıza 

kocaman yaşama sevinçleri iliştirdiğimiz...

her yıldız kaydığında 

geleceğimize yepyeni hayatlar çizdiğimiz...

bir nehir ki

yalnız sesi kalmış kulaklarımızda 

gözlerimizin buğusunda 

eski zaman sevdaları...

bir çayır ki 

yalnız yeşili çimenin 

ellerimde tütün kokusu 

yağmuru farketmemişiz...

giderken

bir ''döneceğim'' bırakmışsın 

en derin yaralarının yanına kalbimin 

beklemeyi böyle öğrenmişim 

gözlerini ilk defa 

bu kadar mavi görmüşüm.

bir el ki

ancak bu kadar zor ayrılır 

bir başka elden 

bir ses ki

ancak bu kadar sarsar bir bedeni

ancak bu kadar derinden

hoşçakal 

gideceğin yere götürme benden hiçbir şey

ayrılık daha zor gelsin 

belki daha erken dönersin..

yaşamın en ücra köşelerinden bir zehir

belki hasretinide 

unutturuverir...', '-sen yine yoktun- yüreğimizin en ücra köşelerine işlerken kader zaman gibi o ölümcül zehri gözbebeklerinde bir ışıltı hatırlatır eskileri ha...', ARRAY['Türk Edebiyatı','Şiir','Serhat Sümer']::text[], 8.5, '{"poet":"Serhat Sümer","poet_slug":"serhat-sumer","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/zaman-gecerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yalan Kalacak', 'bir-yalan-kalacak-temel-bayarslan-nhye2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir Yalan Kalacak

Benim aşkım hiçbir zaman 

Kokuşmayacak

Gömdün onu 

Kalbime değil

Yedi kat yerin dibine 

Sendeki biçare 

Her defasında yüzünü kızartacak 

Sözlerinde daima 

Bir yalan kalacak

Sözüm geçtiğinde 

Yüreğin burkulacak

İşte senin aşkın hiçbir zaman 

Eskimeyecek

Eskimeyecek

26.12.1989', 'Bir Yalan Kalacak Benim aşkım hiçbir zaman  Kokuşmayacak Gömdün onu  Kalbime değil Yedi kat yerin dibine  Sendeki biçare  Her defasında yüzü...', ARRAY['Türk Edebiyatı','Şiir','Temel Bayarslan']::text[], 8.5, '{"poet":"Temel Bayarslan","poet_slug":"temel-bayarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-yalan-kalacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Olmadın', 'neden-olmadin-abdullah-yasar-erdogan-t8u5a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne olur zemmedip yerme beni,

Şer olur şetmetip germe beni,

Sana dedim ki giderken,

Sakın zulmette koma beni.

Vahamet kapıda bilirim.

Sen sevmezken nasıl gelirim

Hayatım zindan geçerken,

Yokluk ölümse sevinirim.

Yıkma beni diye yalvardım,

Memnun ol diye yuvarlandım,

Ruhen yıkılmış biriyken,

Derdime çare neden olmadın.

Damarımdaki kan titredi,

Can pınarında su kesildi,

Mazi kurumuş pınarken,

Allah’û âlem can çekildi.

Zor günümde el olan sendin,

Dost demedin, düşman demedin,

El alem mutlu yaşarken,

Bir gün de yürekten gülmedin.

Başkası ne der dedin, bana,

Çok karıştın yürek dünyama,

Ben yok içinde koşarken,

Neden destek olmadın bana.

Ülfet etme istemem gayri,

Hep karşımda oldun bir şaki,

Tedris haline kanarken,

Sadece dedim ol müttaki.

Zemmetme: Kötüleme.

Şetmetme: Sövme.

Ülfet: Dostluk.

Müttaki: Allah’tan korkan.

Şaki: Haydut.

Tedris: Ders veren.

Abdullah Yaşar Erdoğan.', 'Ne olur zemmedip yerme beni, Şer olur şetmetip germe beni, Sana dedim ki giderken, Sakın zulmette koma beni. Vahamet kapıda bilirim. Sen sev...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/neden-olmadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Sayın', 'adam-sayin-abdullah-yasar-erdogan-525pb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şetmetme ile gelene de,

Methetme ile gelene de,

Dedik alerre’si vel-ayn,

Bekler olduk adam sayın.

İktidar külfeti bize, nimeti size,

Yeter ki tebessüm gelsin yüze,

Hep dedik alerre’si vel-ayn,

Boyun eğdik siz gibi yüzsüze.

Ne doymaz karnınız varmış,

Yemedik kul hakkı kalmamış,

Hep dedik alerre’si vel-ayn.

Doğru dedik, öğüt almamış.

                                      1983

Alerre’si vel-ayn: Baş göz üstüne.

Abdullah Yaşar Erdoğan', 'Şetmetme ile gelene de, Methetme ile gelene de, Dedik alerre’si vel-ayn, Bekler olduk adam sayın. İktidar külfeti bize, nimeti size, Yeter k...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/adam-sayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayşem', 'aysem-temel-bayarslan-03f1d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayşem

Gün olur seni görürsem 

Önüme bakmak zorunda kalacağım 

Ama inan seni 

Hep ellere soracağım 

Yüreğimdeki yaranı 

Her gün dağlayacağım

Beynimin sokaklarını süpürüp

Seni arayacağım 

Gün olur o sokağa gidersem

Sokakları ıslatacağım göz yaşlarımla 

Ne günlerimiz geçmişti bizim 

Nisan aksamlarında 

Bakkalda kasapta manavda 

Çarşamba pazarında hele hele o upuzun sahilde

Gün olur iki çift yakalarsam 

Kuytu bir köşede

Dudak dudağa 

Yüreğim burkulacak 

Kısacası küçük serçem 

Aşkım hep yaşayacak

Gün olur sana bir mektup yazarsam 

Verdiğin kalemi kullanacağım 

O ilk günkü gibi aşkım 

Sevinçten ağlayacağım

Yine o mektubu 

Fişek yapıp 

Gece yarısı 

Bulaşma saatimizde

Balkona atacağım

12.12.1989', 'Ayşem Gün olur seni görürsem  Önüme bakmak zorunda kalacağım  Ama inan seni  Hep ellere soracağım  Yüreğimdeki yaranı  Her gün dağlayacağım ...', ARRAY['Türk Edebiyatı','Şiir','Temel Bayarslan']::text[], 8.5, '{"poet":"Temel Bayarslan","poet_slug":"temel-bayarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/aysem-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bilemessin', 'sen-bilemessin-temel-bayarslan-qffm2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SEN BİLEMEZSİN

Sen bilebilir misin 

Bir kuş sesinin güzelliğini

Çeşit çeşit melodileri dinleyebilir misin? 

Bilemezsin dinleyemezsin güzelim sen

Sen belki kanaryaları 

Dinlemişsindir  oda belki

O da senin gibi olmuş zavallıcık

Her tarafı yapmacık

Neşe değil matemi andırır bana 

 Kendine göre değildir dünyası

Kafesi küçük parmaklıkları daracık 

Sesi yapmacık

Sevinç değil ağlamadır sesçiği

Senin kanaryan senin için öter 

İstediği zaman değil istediğin zaman

Her zaman

Senin çiçeklerin tutsaktır sana 

Zorlarsın onları

“çiçek aç yaprak doğur tohum  ver”

Benimki alabildiğine özgür.

Seninki istediğin zaman benim ki istediği zaman

Sen bir ananın doğururken ki feryadını duyamazsın 

Bir ağacın yaprak açışında

Çıkacak yaprağa izin veren 

Deri çatırdayışlarının verdiği sızıyı

Hissedemezsin göremezsin duyamazsın

Çünkü sende bir esirsin

Şu beton yığınlarına makinelere

Elin ayağın gözün kulağın  düşüncen fikrin

Şu şehrin esiri

Esir esire acımaz

Esir özgürlüğün ne olduğunu bilemez

Sen esirliğe tapıyor özgürlüğü tepiyorsun 

Bense ne bileyim

                                                1.05.1990', 'SEN BİLEMEZSİN Sen bilebilir misin  Bir kuş sesinin güzelliğini Çeşit çeşit melodileri dinleyebilir misin?  Bilemezsin dinleyemezsin güzelim...', ARRAY['Türk Edebiyatı','Şiir','Temel Bayarslan']::text[], 8.5, '{"poet":"Temel Bayarslan","poet_slug":"temel-bayarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sen-bilemessin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sadece Seviyorum', 'seni-sadece-seviyorum-temel-bayarslan-w4c2q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni Sadece Seviyorum

Sonsuzluk içerisinde sadece bir zerresini gördüğüm ve tanıdığım halde yıllardır kalbimde biriktirdiğim bütün sevgiyi verecek kadar.

Keremin Aslısına Ferhat ın Şirinine Arzunun kamberine Romeonun Jullietine beslediği sevginin tohumlarından ektiğim sevgi fidanını sana verecek kadar.......sadece seviyorum.

 “sevmek sevilmekten daha kutludur prensibince hiçbir şey beklemeden sadece seviyorum.

Bilmem ama karşılığınca söylenen iki çift kelimenin  bir merhabanın bir dokunuşun karşılaşan iki çift gözün insanın düşüncesini yalayıp geçen ılık bir ihtirasın sevginin kutsallığına zarar vereceğini  onun bir nevi sevenin sevilenden  aldığı bir karşılık olduğunu düşünüp  seni sadece yaşıyor ve sadece seviyorum.

 Senin yakınındayken yokluğunda seni sevmenin en kutsalı olduğuna inanıyor düşünüyor ve öylesine seviyorum. Senin beni sevmende sevgimin azalacağını düşünüyor ve irkiliyorum

      Sevenin sevilenden isteyeceği en büyük şey sevilenin sevmesidir.bunu hak ettiğime inandığım ana kadar seni sadece ama sadece seviyorum.

                                                                                           07.11.1990', 'Seni Sadece Seviyorum Sonsuzluk içerisinde sadece bir zerresini gördüğüm ve tanıdığım halde yıllardır kalbimde biriktirdiğim bütün sevgiyi v...', ARRAY['Türk Edebiyatı','Şiir','Temel Bayarslan']::text[], 8.5, '{"poet":"Temel Bayarslan","poet_slug":"temel-bayarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seni-sadece-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyi Kimi Neden Niçin', 'neyi-kimi-neden-nicin-temel-bayarslan-h9q98', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'NEYİ,KİMİ,NEDEN,NİÇİN? 

Karanlık Gecelerde Düşleriz 

Hep Aydınlığı

Gözleri kamaştırdığını bile bile

Mutsuz zamanlarda ararız

Mutluluğu

Mutluluğumuzda fark etmeyiz hiç

Kıymetini

Uzun yollarda seyahat 

Kaskatı kesilir insan

Nedense anılar hep neşelidir

Çok zaman

Şehrin mumya suratlı insanını

Medeni diye anarız

Issız doruklarda

Ne iyi ne kötü insana

Bilemeyiz

Mutluluk ile mutsuzluk

Farkını anlayamayız

Hep ararız ama

Neyi kimi neden niçin? 

Sendeleyerek gideriz

Bilinçsizce şuursuzca

Böbürlenerek bildiğimizi

Tutarsızca davranırız

Neyiz kimiz

Karamsarlık huzursuzluk

Benliğimizde

Suç değil gençliğimizde

Ararız ihtiyarlığımızda

Severiz çiçekleri

Koparırız yaşamdan

Çelişkilerle dolu yaşamımız

İnsanız bilemeyiz

                                                 13.05.1992', 'NEYİ,KİMİ,NEDEN,NİÇİN?  Karanlık Gecelerde Düşleriz  Hep Aydınlığı Gözleri kamaştırdığını bile bile Mutsuz zamanlarda ararız Mutluluğu Mutlu...', ARRAY['Türk Edebiyatı','Şiir','Temel Bayarslan']::text[], 8.5, '{"poet":"Temel Bayarslan","poet_slug":"temel-bayarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/neyi-kimi-neden-nicin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-temel-bayarslan-b9ryh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SANA

Ve bir mektup yazmalıyım sonsuza dek

Umutlarını hayallerini 

Silip süpürdüğün gecenin anısına 

Yazdığım anda o mektubu

Defalarca doğum sancısı çekmiş

Bir anne olmalısın

Anlaşılması imkansız olmalı

Bu mektup sence

Bu mektup sisli kitli bir gecede 

Beynin derinliklerinden gelen

Anıların kemiklerinden olmalı

Muhatabın ismini dahi duymamalısın

Bir  benzerlik haricinde

Mutlu günlerin yarattığı

Karanlık tabloyu simgelemeli

Eski hayalini düşünerek

Bir mektup yazmalıyım sana

Gücümün yettiğince isyankar olmalıyım

Mazideki mutluluğuma

Sessiz çığlığımın feryatlarını

Kulağını çınlatmak için 

Gücümün yettiğince haykırmalıyım

Karanlığa

Bu mektubu sana yazmalıyım

Anlıyor musun Allah’ın belası

Üzülmem hiçbir şeye de

Son sözüm sen olursun diye

Korkuyorum 

Sonsuzluğa ulaşırken

                                      05.11.1992', 'SANA Ve bir mektup yazmalıyım sonsuza dek Umutlarını hayallerini  Silip süpürdüğün gecenin anısına  Yazdığım anda o mektubu Defalarca doğum ...', ARRAY['Türk Edebiyatı','Şiir','Temel Bayarslan']::text[], 8.5, '{"poet":"Temel Bayarslan","poet_slug":"temel-bayarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sana-127-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-temel-bayarslan-uxe02', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'KEŞKE

Yalnızım ıp ıssızlıkta

Dışarıda toz halinde 

Uğuldayan kar

Yapayalnız duygularla

Ah keşke sen

Sen olsaydın yanımda

Birlikte kursaydık hayalleri

Özlemeseydim keşke

Yanımda olsaydın

Bir buse kondursaydım

Boyasız dudaklarına

Sevseydim

Yinede bir dünyasın bende

Benden uzakta

Hayalini düşünür

Yutkunur avunurum

Senden uzakta

Kaderimi değiştirebilsem

Hülyalarıma; sana

Ah keşke

Kavuşabilsem nerede

Hayalinde ben olsaydım keşke

Gök delenleri değil beni; 

Hayalimi görseydin.

                                               14.02.1993', 'KEŞKE Yalnızım ıp ıssızlıkta Dışarıda toz halinde  Uğuldayan kar Yapayalnız duygularla Ah keşke sen Sen olsaydın yanımda Birlikte kursaydık ...', ARRAY['Türk Edebiyatı','Şiir','Temel Bayarslan']::text[], 8.5, '{"poet":"Temel Bayarslan","poet_slug":"temel-bayarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/keske-117-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıpraşma', 'kiprasma-yasemin-sezer-tulgar-ol5y3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayrılığımız bile lapa

Sayenizde

Sevgili tual kafa

Paletimde bir bulamaç

Ressam

Bıkkın

Kanım da tiner

Bezir yağı tenim

Gülme

Gülme diyorum

İki fırça

ve

İşin tamam

Kalmış gibi bulanmadık yerin

Sallamaktayım spatula

Boşa

__________Boş

Sanki Picasso ruhumla

Çıkacak da bir Guernica

Şaşıracağız 

Boşa

_____________Boş

Dur

Hele 2 dakika

_______Kıpraşma

06 09 2005', 'Ayrılığımız bile lapa Sayenizde Sevgili tual kafa Paletimde bir bulamaç Ressam Bıkkın Kanım da tiner Bezir yağı tenim Gülme Gülme diyorum İk...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kiprasma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözler', 'sozler-nurten-tarim-mn10i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sözler gelir ise yürekten

Öz görünür bakıştır kanıtı

Dilden gelirse 

İnsanı yanıltır acısını yürek taşır

İnsan aynadır insana

Aynayı ayna yapan  sırrıdır arkasında

Kara sırrı görmez 

Unutur dış güzellik ile aldanan akıl

İnsanı insan yapan ruhtur 

Dümeni mantık ve akıl

Asıl ayna anlamak dogru yanlışı

İnsana insan aynadır

Gerisi yalan dolandır', 'Sözler gelir ise yürekten Öz görünür bakıştır kanıtı Dilden gelirse  İnsanı yanıltır acısını yürek taşır İnsan aynadır insana Aynayı ayna ya...', ARRAY['Türk Edebiyatı','Şiir','Nurten Tarım']::text[], 8.5, '{"poet":"Nurten Tarım","poet_slug":"nurten-tarim","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sozler-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlikte', 'sensizlikte-nazan-i-zmirli-nsf6d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'aynı   güneşe  gülümser   günaydın   deriz 

aynı  ayı  selamlar, laflarız  üç  beş kelime 

aynı  yıldızları  kucaklarız   kenetlenircesine

.......her gece.......................tek nefeste.......

aynı   evrende    ikimiz de  bir        bilmece 

aynı    düşle   güneşi   göndeririz   yarınlara

aynı  yıldızlarla   selam   yollar

          kaydırırız  bakışlara

          dünya   döndükçe   döner 

          tek  bir  dilek   tutarız

          ama   boşuna

          kavuşamadıkça........................beni hep hatırla..........

          aynı  değil  bulutlar 

          pembe maviler............  sende.............hadi gülümse....

          bendekiler  ağlamaklı  gri

          sensizlikte........................................................................

        

Nazan İzmirli-09-11-2005-antalya', 'aynı   güneşe  gülümser   günaydın   deriz  aynı  ayı  selamlar, laflarız  üç  beş kelime  aynı  yıldızları  kucaklarız   kenetlenircesine ....', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sensizlikte-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Unuttuktan Sonra', 'seni-unuttuktan-sonra-melih-coskun-7r542', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni unuttuktan sonra 

Seni anımsatan hiçbir şarkıya ağlamadım 

İçimde derin bir boşluk bıraktın sadece 

Kelimelerimi çalıp şiirlerimden 

Beni kendi hüznüme hasret bıraktın 

Seni unuttuktan sonra 

Seni değil 

En çok kendimi özledim ben 

Mısra döküp hala kanamakta olan yaralarımdan

Sabahlara kadar şiirler yazmayı 

Seni sevdiren 

Senden daha güzel bir şeyler vardı

Tanımlayamadığım 

Ve binlerce şairin adını koyamadığı 

Aşk kadar temiz 

Ekmek kadar kutsal 

Ve yaşamak kadar güzeldi 

Seni unuttuktan sonra 

Küsmedim hiçbir şehre 

Ve suçlamadım kimseyi kendimden başka  

Öyle göçebe gibi kentten kente savruluşum 

Alın yazımdır belki bilinmez

Seni unuttuktan sonra 

Taşlar savurmadım hiçbir denizin karaltısına 

İçinde adının geçtiği bütün muhabbetlerden 

Ayak izlerinin olduğu bütün yollardan koşar adım kaçtım 

Seni hatırlatacak her şeyden soyutladım kendimi 

Bir tek yüreğim kaldı 

Çıkartıp yerinden atamadım...

2004', 'Seni unuttuktan sonra  Seni anımsatan hiçbir şarkıya ağlamadım  İçimde derin bir boşluk bıraktın sadece  Kelimelerimi çalıp şiirlerimden  Be...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/seni-unuttuktan-sonra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmura Soruyorum', 'yagmura-soruyorum-nurten-tarim-6bpaz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yağmura soruyorum

Anlattığın nedir diye

Can veriririm canlılara

Denizlere ulaşırım

Kadınlara soruyorum 

Göz yaşınız nedir diye

Hüzünlere sevgilere akıyorum

Aynalara soruyorum

Güzellikler nedir diye

Duygularla kalbinize akıyorum

Yaşadığım dünyamıza soruyorum

Sevdalanmak sana durup bakıyorum

Giz perdesidir size armağanım

Aşkla güzel yaşıyorum', 'Yağmura soruyorum Anlattığın nedir diye Can veriririm canlılara Denizlere ulaşırım Kadınlara soruyorum  Göz yaşınız nedir diye Hüzünlere sev...', ARRAY['Türk Edebiyatı','Şiir','Nurten Tarım']::text[], 8.5, '{"poet":"Nurten Tarım","poet_slug":"nurten-tarim","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yagmura-soruyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılmaz İle Ali', 'yilmaz-i-le-ali-hatice-bediroglu-aibv2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Boyaları dökülmüş

Kalın kalın gıcırdayan

Paslı kapıdan girince

Gülerdi mutsuz ruhu

Kendisi gibiydi çünkü

Yurdun

250 mevcutlu nüfusu

Ziftli elleriyle

Yemeğe çalıştı Yılmaz

Bol taşlı bulgur pilavını

Çocukluğu umutlara gebe

Sevgiyi tanımamış yüreği

Sıcacık bir elin

Okşayışına hasret

18’inden sonra

Paslı kapının ardında

Belirsizliklerle dolu

Geleceği

Düş bile görmemiş

Geceleri

Bir bulsaydı kardeşini

Belki yaşatabilirdi

İçinde sıcacık sevgiyi

Dört yaşındaki Ali

Altını ıslatırdı her gece

Ve sopa kırılırdı belinde

Karanlığa aldırmaz

Koşardı Müdür Babaya

Elinde bir kartpostal

Avazı çıktığı kadar bağırır

Salya sümük ağlayarak

Annem nerede! 

Annem nerede! 

Gelecek derdi Müdür baba

Çok yakında gelecek annen

Dört yaşındaki Ali

Bilemezdi

Anlayamazdı

Anlatılamazdı

Annesinin

Neden geneleve düştüğü

Umutları

Bekleyişlerde saklı

Geleceği kapkaranlık

Anneciğinin resmini

Bastırırdı koynuna

Sımsıkı

Sıska parmakları

Gözünün yaşları

Islatırdı yastığını

Düşlerinde

Annesinin öpücükleri

Isıtırdı küçücük

Üşümüş

Etsiz yanaklarını.

www.haticebediroglu.net

-Aşkı Bulan Şiirler- Gündüz Kitabevi Aralık 2005', 'Boyaları dökülmüş Kalın kalın gıcırdayan Paslı kapıdan girince Gülerdi mutsuz ruhu Kendisi gibiydi çünkü Yurdun 250 mevcutlu nüfusu Ziftli e...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/yilmaz-ile-ali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
