INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gözetleme Deliği (Hugh Mac Diarmid)', 'bir-gozetleme-deligi-hugh-mac-diarmid-i-smail-aksoy-j9z8c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gözetleme deliği tanırım 

