INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarla: Bilinmeyen Çiçek', 'tarla-bilinmeyen-cicek-i-smail-aksoy-1oyju', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ah ışık-taşıyıcılar (ah böyle bir ışık hâlesi 

