INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağustos Söndürülür (Gennadiy Aygi)', 'agustos-sondurulur-gennadiy-aygi-i-smail-aksoy-0g0m9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sesten yapılmış 

meşe çalısından bir yerde 

ışık saçan bir salıncak 

gizlice kurulmuş 

alıkoyan - bozulmuş 

bir durumda: altın pırıltılı! 

bir kuş: bilmeden onu: izliyor 

yolu 

Gennadiy Aygi

(Çeviren: İsmail Aksoy)', 'sesten yapılmış  meşe çalısından bir yerde  ışık saçan bir salıncak  gizlice kurulmuş  alıkoyan - bozulmuş  bir durumda: altın pırıltılı!  b...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/agustos-sondurulur-gennadiy-aygi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazık', 'yazik-murat-nail-guney-fdyp7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine akın etti dertler sıralı,

Deşme derdim yürek zaten yaralı,

Selam vermez oldu dostun kralı,

Dost dost diye solan güllere yazık...

Paran kadar insansan şu alemde,

Paran yoksa elbet bitmez çilen de,

Muhtaç olma dosta sürün dilen de,

Paraya kul olan kullara yazık...

Tutup kaldırmazlar düşersen yere,

Erken çıkarırlar o son sefere,

En yakının derse git Allah vere,

Beş vakit zikreden dillere yazık...

Hangi dost için biz olmadık köle,

Aklımız estikçe düşerdik yola,

Dostluk seferinde vermedik mola,

Ömrümce uzayan yollara yazık...

Gönül eri olduk gönül yormadık,

İsteyene verdik sebep sormadık,

Kusur örttük hataları görmedik,

Alıp da vermeyen ellere yazık...

Muradım gücenme bu devir böyle,

Menzile varılmaz deliyle toyla,

Yine de sen hakça yaz hakça söyle,

Gönülde coşmayan sellere yazık...

murat nail güney

30.10.2005   İnebolu', 'Yine akın etti dertler sıralı, Deşme derdim yürek zaten yaralı, Selam vermez oldu dostun kralı, Dost dost diye solan güllere yazık... Paran ...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yazik-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Mutlaka', 'bir-gun-mutlaka-muhsin-yener-6l3y8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BİR GÜN MUTLAKA

İnsan,

eskiyi bırakmadıkça

yeni bir bahara açamaz yüreğini.

Bazen bir düşünceyi uğurlamak gerekir,

bazen yıllarca doğru bildiğin

bir yanlışa sessizce veda etmek…

Çünkü büyümek,

yalnızca yılların geçmesi değildir;

bazen kendi içindeki karanlığa

bir ışık yakabilmektir.

Her yeni fikir

eski bir duvara vurulan çekiç,

her özgür düşünce

gecenin kalbine bırakılmış

küçücük bir güneştir.

Ve insan,

en büyük devrimi

belki de kendi içinde yapar…

Yıllardır susturduğu sesini duyduğunda,

korkularını bir bir geride bıraktığında,

başkasının çizdiği yoldan değil,

kendi vicdanının izinden yürüdüğünde…

İşte o zaman

bir şeyler değişmeye başlar dünyada.

Bir çocuk daha özgür büyür,

bir kadın başını daha dik kaldırır,

bir insan umudunu yeniden hatırlar.

Ve bir yerde,

kimsenin görmediği bir yürekte

yeni bir dünya doğar.

Unutma, arkadaşım,

karanlık ne kadar uzun sürerse sürsün,

sabaha inanan bir yürek

içinde mutlaka bir ışık taşır.

Dünya değişecekse

önce düşüncelerimiz özgürleşecek,

sonra ellerimiz birbirine uzanacak,

sonra sevgi çoğalacak

ekmek gibi, su gibi,

gökyüzüne uzanan ağaçlar gibi…

Biz,

dünün küllerinden

yarının güneşini doğuracağız.

Yıkılan düşlerimizin yerine

yenilerini kuracağız,

yorulan kalbimizi umutla saracağız.

Çünkü hayat dediğin

yalnızca yaşayıp geçmek değil,

ardında daha güzel bir dünya

bırakabilmektir.

Ve bir gün…

belki uzak, belki çok yakın bir gün,

çocuklar korkusuzca gülecek,

insanlar birbirini anlamak için dinleyecek,

hiç kimse bir başkasının umudunu

karanlığa mahkûm etmeyecek.

O gün geldiğinde

anlayacağız ki

değişim bir kişinin yüreğinde başlamış,

umut elden ele taşınmış,

özgürlük bir düş olmaktan çıkıp

hepimizin ortak gerçeği olmuş.

İşte o gün, arkadaşım,

güneşe bakıp gülümseyeceğiz.

Ve diyeceğiz ki:

Biz karanlığa boyun eğmedik,

umudu yüreğimizde büyüttük.

Dünyayı değiştirmek için

önce kendimize inandık.

Çünkü her yeni gün

yeniden başlamak için bir neden,

her özgür düşünce

yarına bırakılmış bir tohumdur.

Ve ben inanıyorum:

Bir gün mutlaka

bu tohumlar çiçek açacak.

Muhsin Yener', 'BİR GÜN MUTLAKA İnsan, eskiyi bırakmadıkça yeni bir bahara açamaz yüreğini. Bazen bir düşünceyi uğurlamak gerekir, bazen yıllarca doğru bild...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener']::text[], 8.5, '{"poet":"Muhsin Yener","poet_slug":"muhsin-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/ask-477-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğim', 'sensizligim-ozan-ozel-1zp4v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sen gidince 

iklim değişir 

kış olur 

kar yağar yüreğime 

üşürüm... 

ve bir yanım 

titrer 

-ken diğer yanım 

kartopu oynar 

anlarım ki 

onlara eğlencedir 

sensizliğim...', 'sen gidince  iklim değişir  kış olur  kar yağar yüreğime  üşürüm...  ve bir yanım  titrer  -ken diğer yanım  kartopu oynar  anlarım ki  onla...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensizligim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ötede', 'otede-i-smail-aksoy-ucb9u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ötede 

bir uzak ses 

bir için 

çok küçük 

güzelim fulyalar 

git öyleyse 

işte orada 

işte orada 

işte oradan 

fulyalar 

yeniden 

git öyleyse 

bir uzak ses 

yeniden 

biri için 

çok küçük 

Samuel Beckett

(Türkçeye çeviren: İsmail Aksoy)', 'ötede  bir uzak ses  bir için  çok küçük  güzelim fulyalar  git öyleyse  işte orada  işte orada  işte oradan  fulyalar  yeniden  git öyleyse...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/otede-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alba (Samuel Beckett)', 'alba-samuel-beckett-i-smail-aksoy-al501', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sabahtan önce olacaksın burada 

ve Dante ve Logos ve bütün katmanlar ve gizemler 

ve yanık ay 

sabah öncesi burada yaratacağın 

müziğin beyaz yüzeyi arkasında 

adamakıllı yumuşak şarkılı ipek 

eğil hurma ağacının kubbesine 

yağ dumandan bambu çiçeklerine söğüt geçidi 

merhametli parmaklarla eğilsen bile 

yazmak için toza 

çoğaltmayacak zengin armağanlarını 

ki güzellikleri önümde beyaz bir örtü olacak 

kendi ifadesi kapanmış simgelerin fırtınasına 

bu yüzden hiç bir güneş ve açılım yok 

ne de ordu kalabalığı 

yalnız ben ve o örtü 

ve ölü yığın 

Samuel Beckett

Çeviren: İsmail Aksoy', 'sabahtan önce olacaksın burada  ve Dante ve Logos ve bütün katmanlar ve gizemler  ve yanık ay  sabah öncesi burada yaratacağın  müziğin beya...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/alba-samuel-beckett-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şey Orada', 'bir-sey-orada-i-smail-aksoy-m027z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir şey orada 

nerede 

ötede 

öte nerede 

dışarda 

ne 

kafa ne olacak 

bir şey orada bir yerde dışarda 

kafa 

solgun seste ne de kısa 

gitti ve bütün küre 

henüz taşımadı 

göz 

açılır kocaman 

kocaman 

en sona doğru 

hiç bir şey daha 

kapatır yeniden 

böylelikle bir zaman 

ötede 

bir yerde ötede 

sanki 

güyâ 

bir şey 

hayat değil 

ille de 

Samuel Beckett

(Türkçeye çeviren: İsmail Aksoy)', 'bir şey orada  nerede  ötede  öte nerede  dışarda  ne  kafa ne olacak  bir şey orada bir yerde dışarda  kafa  solgun seste ne de kısa  gitti...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-sey-orada-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adresi Belli Şiirler - X', 'adresi-belli-siirler-x-ugur-deniz-ulkegul-bzgik', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-I-

Sevimsiz sabah sancılarında

Eylemsiz can sıkıntısına yenik

Bir yanım…

Sensizlik kuytusunda

Parmak uçlarımda birikir canım

Bir sevişmelik………………….

-II-

Uzaksın

Zaman kör kuyusunda aşkın

-Kimse ne olacak bilmiyor-

Taşkın duygular belası yürek

Bütün kavgalar zorlu ölümcül

Ölüm dediğin sinemde gül arzu

Yenilir bazen hani insan..Bilerek…

Ben de kal! dediğim zaman

Ben de kalan düşlere uyanırsın

Bir asra değişilmez olur bir an…

Zor gelir sonrası, bazen

-Susmaya çok geç kalırsın-

Yasaksın

İçimin bütün doğruları şaşkın

-Hiç bir söz yüreğimden silinmiyor-

(Aşkın bir rengi olmalı diyorum

Arsız efkar dumanında sevişmeli

Köz olup yakmalı tenin, ruhum inlemeli)   

Tükürsem yüzüne çekip gitmelerin! ! ! ! ! 

Sırtıma ne zaman saplanır gözlerin? 

Bilinmiyor…..

-III-

Yoruldum artık

Kuşatılmış dört bir yanım

Sürgün akşamlardan kalma

Sana dokunmalarım………

Dudağımda seni özlemenin tadı

Tenimde senin sıcaklığın yar…

Ne bir adresi var bu aşkın, ne adı

Kırık bir güvercin kanadı

Sevdası gökyüzünde bir mavi kadar……….', '-I- Sevimsiz sabah sancılarında Eylemsiz can sıkıntısına yenik Bir yanım… Sensizlik kuytusunda Parmak uçlarımda birikir canım Bir sevişmelik...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/adresi-belli-siirler-x-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yankının Kemikleri (Samuel Beckett)', 'yankinin-kemikleri-samuel-beckett-i-smail-aksoy-4i202', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sığınık altında adımlarımın bütün bu gün 

sesi yalıtılmış cümbüşler gibi etin çözülüşü 

kazanç korkusuzca ya da ayrımsız bırakılır 

anlamla anlamsızlık arasındaki sivrikök 

kendileri için kurtçukların aldığı sona doğru koşmaya 

Samuel Beckett

Çeviren: İsmail Haydar Aksoy', 'sığınık altında adımlarımın bütün bu gün  sesi yalıtılmış cümbüşler gibi etin çözülüşü  kazanç korkusuzca ya da ayrımsız bırakılır  anlamla ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yankinin-kemikleri-samuel-beckett-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Yalnız İzleyicisi Gökyüzünün, İşitiyor musun?', 'ey-yalniz-i-zleyicisi-gokyuzunun-i-sitiyor-musun-i-smail-aksoy-7jhn3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey yalnız izleyicisi gökyüzünün, işitiyor musun 

Herşeyin uyuduğu bu saatte 

Gündoğumunun solgun kapıları açılsın diye 

Eros''a yakardıklarını gecenin 

Ve iççekişlerini harplerin? 

Ey yalnız, uyanıyor musun herşey uyurken 

Duymak için şirin harplerin tınısını 

Eros''a hoşgeldin şarkısını, 

Ve gece rüzgârının ilahiyle bildirdiğini 

Bitişini gecenin? 

Ey gizlenmiş harpler, şirin ışıkların 

Gelip gittiği şu anda 

Cennetteki yolu parıldayan Eros için sürdürün türküyü, 

Yayılsın şirin ve uyumlu ezgiler 

Toprağa ve buluta. 

James Joyce

(Türkçe''ye çeviren: İsmail Aksoy)', 'Ey yalnız izleyicisi gökyüzünün, işitiyor musun  Herşeyin uyuduğu bu saatte  Gündoğumunun solgun kapıları açılsın diye  Eros''a yakardıkların...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ey-yalniz-izleyicisi-gokyuzunun-isitiyor-musun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karfırtınalarından Sonra (Bir Dostun Ziyareti Üzerine)', 'karfirtinalarindan-sonra-bir-dostun-ziyareti-uzerine-i-smail-aksoy-lburh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sessizlikte yerken akşam yemeğimi 

(ruh - tipide gibi)

biliyorum ki: sen Karaya çıktın 

ve bu yüzden kar-yığınlarının enginliği 

ve aralarındaki gölgeler şöyle 

(ruh - tarlanın dinlenişi gibi)

bakarken birbirimizin gözlerine 

ve derken ''harika'' 

- kayarken bakışlar kendimize 

(ve sessizlikle birlikte)

açık gibi bir mutlulukla 

Gennadiy Aygi

(Türkçe''ye çeviren: İsmail Aksoy)', 'sessizlikte yerken akşam yemeğimi  (ruh - tipide gibi) biliyorum ki: sen Karaya çıktın  ve bu yüzden kar-yığınlarının enginliği  ve araların...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/karfirtinalarindan-sonra-bir-dostun-ziyareti-uzerine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gün mutluluk', 'bir-gun-mutluluk-muhsin-yener-qt9sl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün mutluluk

Kapını çalarsa

Sakın açamazlık yapma…

Çünkü o,

Senin en büyük özlemindir.

Bırak davetsiz bir misafir gibi gelsin,

Sessizce girsin içeriye.

Evinin duvarlarına sıcaklığını bıraksın.

Karına, çoluğuna, çocuğuna,

Annene, babana,

Sevdiğine umut olsun.

Çünkü insanın

Parası olmuş, pulu olmuş,

Ne fayda…

Eğer içinde

Bir damla mutluluk yoksa.

Dünya dediğin yerde

İnsanların en büyük arzusu,

Mutluluk güneşinin

Üzerlerine doğmasıdır.

Ve ben şimdi

Tüm kalbimle diliyorum ki

Arkadaşım, dostum kim varsa 

Üzerine doğsun o güneş.

İçini ısıtsın,

Yüreğine huzur olsun,

Ömrüne sevinç olsun.

Mutluluğu sadece görmesin,

İliklerine kadar yaşasın.

Muhsin yener', 'Bir gün mutluluk Kapını çalarsa Sakın açamazlık yapma… Çünkü o, Senin en büyük özlemindir. Bırak davetsiz bir misafir gibi gelsin, Sessizce ...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener']::text[], 8.5, '{"poet":"Muhsin Yener","poet_slug":"muhsin-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/asker-omer-gunaydin-a-yazilarim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Demirişi Üzerine Düşünceler', 'bir-demirisi-uzerine-dusunceler-i-smail-aksoy-9wcxl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Keşke bilediğiniz metale benzeseydiniz, 

Keşke demir ruhunuza ağsa, 

Keşke çelik olsaydınız kendi iyiliğiniz için! 

Hâlâ hamur gibisiniz zorba hükümdarlarınızın 

Parmakları arasında! Size çevrilecek tüfek ve tabancaları 

Üretiyorsunuz kendi ellerinizle! Kuşku yok bu silahların 

Sizleri yaralayıp öldüreceğinden - 

Düşmanlarınıza silah yapacak kadar aptalsınız! 

Hugh Mac Diarmid

(Türkçeye çeviren: İsmail Aksoy)', 'Keşke bilediğiniz metale benzeseydiniz,  Keşke demir ruhunuza ağsa,  Keşke çelik olsaydınız kendi iyiliğiniz için!  Hâlâ hamur gibisiniz zor...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-demirisi-uzerine-dusunceler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar', 'yollar-murat-nail-guney-1e4u9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mutluluk düşüm gibi uzayıp gider yollar,

Alnıma kader gibi gurbeti yazar yolar,

Kiminde ayrılıklar, kiminde kavuşmak var,

Ömür biter yol bitmez ömrünce uzar yollar...

Gecenin ayazında, fırtınanın sazında,

Bir garip beste yapıp ruhumdan süzer yolar.

Dağlar üstüme gelir, uykular gözlerime,

Üşütür yüreğimi, gönlümü üzer yollar...

Yazarım her seferde birer birer anımı,

Yardan ayrı koyunca acıtıyor canımı,

Söküyor içerimden o en çocuk yanımı,

Ne zaman buluşmasak darılır kızar yollar...

Muradım geçti ömür, hep azar azar yolar,

Kışı kar, çamur, boran, yaz günü tozar yollar.

Az gidince sevilir tezce geri dönülür,

Uzadıkça uzarsa kimyamı bozar yollar...

murat nail güney

İnebolu / Anamur yolculuğu hatırası

14.10.2005        Kalecik', 'Mutluluk düşüm gibi uzayıp gider yollar, Alnıma kader gibi gurbeti yazar yolar, Kiminde ayrılıklar, kiminde kavuşmak var, Ömür biter yol bit...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yollar-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Sapması', 'zaman-sapmasi-beyza-beyza-ump2k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonbahar tadında bir ilkbaharın sonundan

