INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Değilsin Beklediğim', 'sen-degilsin-bekledigim-birkan-demirci-ye6jx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen değilsin aradığım 

yollarını gözleyip dumanını çektiğim

kokun değil beklediğim

bana bıraktığın alışkanlıkları bekliyorum.

13.07.2004', 'sen değilsin aradığım  yollarını gözleyip dumanını çektiğim kokun değil beklediğim bana bıraktığın alışkanlıkları bekliyorum. 13.07.2004...', ARRAY['Türk Edebiyatı','Şiir','Birkan Demirci']::text[], 8.5, '{"poet":"Birkan Demirci","poet_slug":"birkan-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sen-degilsin-bekledigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter Artık Felek', 'yeter-artik-felek-hidir-altas-spzji', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Küçük yaşta kardeşimi aldın.

Askerdeyken babamı çaldın.

Şimdide defterimi aldın.

Yeter kahpe felek,uğraşma benimle.

Her acıyı tattırdın bana.

Hasret bıraktırdın beni sılama; 

Bir tas su bile döktürmedin babama; 

Yeter kahpe felek,uğraşma benimle

Birazcık mutluluğu çok gördün.

Turhani''mi dertlere gömdün.

Başıma ne çoraplar ördün; 

Yeter kahpe felek,uğraşma benimle.', 'Küçük yaşta kardeşimi aldın. Askerdeyken babamı çaldın. Şimdide defterimi aldın. Yeter kahpe felek,uğraşma benimle. Her acıyı tattırdın bana...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Altaş']::text[], 8.5, '{"poet":"Hıdır Altaş","poet_slug":"hidir-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yeter-artik-felek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirce', 'siirce-i-smail-aksoy-dahkw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu kırmızı bacadan geliyor

Bu beyaz duman.

Bu yeşil hıyar duruyor

Bir sarı tabakta.

Bu siyah bisiklette oturuyor

Bir mor adam.

Yol yükseliyor.

Bisiklet yükseliyor.

Yani yükseliyor adam.

Duman yükseliyor.

Duman da yükseliyor.

Hıyar kıpırdamıyor.

Netameli bir sessizlik.

Wassily Kandinsky

Türkçe''ye çeviren: İsmail Aksoy

Çevirenin notu: ''Lyrique''. Paris, Mart 1939. ''11 Tableaux et 7 Poemes'', (Amsterdam 1945)  adlı kitapta yayınlanmıştır.', 'Bu kırmızı bacadan geliyor Bu beyaz duman. Bu yeşil hıyar duruyor Bir sarı tabakta. Bu siyah bisiklette oturuyor Bir mor adam. Yol yükseliyo...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/siirce-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlıksız - Wassily Kandinsky-', 'basliksiz-wassily-kandinsky-i-smail-aksoy-hdb5e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saat sabahın beşini vuruyor

şimdi ortasındayken günün

kim bilmez ki pazartesileri

gerçekte çarşambadır

bugüne çok yakın ya da çok uzak

bir sincap iner tepeden aşağı

yukarı çıkarken yaptığı bir şey yapar

gerçekte utanç yüzünden

yadsımak söylenen şeyi,

görülmüş şeyi

kış izler sonbaharı

ya da bazen tam tersi

bu güzel çirkin bir şeydir

gece gündüzken

biraz azken ya da aynıyken.

Wassily Kandinsky

Türkçe''ye çeviren: İsmail Aksoy.', 'Saat sabahın beşini vuruyor şimdi ortasındayken günün kim bilmez ki pazartesileri gerçekte çarşambadır bugüne çok yakın ya da çok uzak bir s...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/basliksiz-wassily-kandinsky-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Gözlerin Kapalı Sevgilim', 'neden-gozlerin-kapali-sevgilim-selma-erdeviren-55bxw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neden gözlerin kapalı sevgilim,

Yoksa uyuyor musun? 

İşte o sevdiğin ses dudaklarımdan dökülen,

Duyuyor musun? 

Özlemine dayanamadı yüreğim,

Çok uzak yollardan geldim.

Aç gözlerini bak gülüyorum,

Gülüşümü ne kadar severdin.

Sevince insan unutamıyormuş,

İnandım artık, mümkün değil.

Eskiden biz vardık sadece,

Şimdi sen varsın ben varım,

Aşkımız bütün değil.

Bizi koparan şeylere kızdım,

İsyan ettim arasıra.

Hepsi unutulur onların,

Hepsi birer hatıra.

Bugüne dönelim biz şimdi,

Bak işte sevgilin gelmiş.

Aç ağzını bir kez de sen haykır,

Sevmek ne kadar güzelmiş.

Çok sevdiğin bir şarkı vardı,

Segah makamında.

Benim de segah şarkılarım var şimdi,

Duyacaksın yakında.

Her şeyi bırak konuşalım derdin bana,

Gözlerin kapalı, dua mı okuyorsun? 

İşte çoşkuyla  konuşuyorum şimdi ben,

Sen ise susuyorsun.

''Büyük bir insan olacaksın'' demiştin,

''O zaman beni beğenmezsin''.

Gerçekten acılar büyüttü beni,

Hem de nasıl, bilemezsin.

Gözlerimdi seni çeken ilk şey,

Hani şimdi o renkleri nerde? 

Kaybettiler güzelliklerini

Sana ağladığım gecelerde.

Ellerim yine yumuşak,

Bak tutuyorum ellerinden.

Dostluk sunmuşlardı sana,

Derinden, çok derinden.

Ya senin ellerin niye soğuk? 

Damarların donmuş gibi.

İçim ürperiyor inan,

Karlar üstündeki bir kuş gibi.

Üşüyorsan eğer

Sobayı yakarım sana.

Hastaysan üzülme,

Ben bakarım sana.

Ama ağzını açıp bir kez

Hoş geldin demelisin.

Susmak hiç yakışmıyor,

Sen hep gülmelisin.

İstersen şiir okurum sana,

Ya da şarkı söylerim.

Mutlaka senin olsun dersen,

İşte kendi bestelerim.

Seni düşünüp yazdım sözlerini

Ve sana adadım her birini.

Oysa sen burda susmuş

Saklıyorsun ellerini.

Neden gözlerin kapalı sevgilim? 

Aklıma kötü şeyler geliyor.

Bir acı hıçkırık kopuyor kalbimden,

Dudaklarıma yükseliyor.

Olamaz diyorum bu bir yalan; 

O beni bırakıp gitmez.

Haydi birlikte söyleyelim,

Sevda türküleri bitmez.

Neden gözlerin kapalı sevgilim,

Kimler aldı ferini? 

Işıl ışıl bakıyorum sana,

Ne olur aç gözlerini.', 'Neden gözlerin kapalı sevgilim, Yoksa uyuyor musun?  İşte o sevdiğin ses dudaklarımdan dökülen, Duyuyor musun?  Özlemine dayanamadı yüreğim,...', ARRAY['Türk Edebiyatı','Şiir','Selma Erdeviren']::text[], 8.5, '{"poet":"Selma Erdeviren","poet_slug":"selma-erdeviren","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/neden-gozlerin-kapali-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem Etme', 'sitem-etme-mehmet-akif-gulhan-jpfm5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sitem etme ne olur

Dayanamam ki buna 

Yürek taşımıyorum artık

Bin ton yük taşıyorum

Akıl zaten yoktu bende

Şimdi kafamın içi bulut dolu

Ve arada sırada gözüken

Hayalin ile avunuyorum

Pembelerde kızıl kana döndü

Sensiz,menekşelerde dikene

Batıyor acıtıyor

Issız limanlara bıraktım ruhumu

Gemilerde kalkmaz,ellerde sallanmaz

Öldüm mü ben ne

Pamuk prensesin yattığı yere

Uzanmak istiyorum

Sen gel artık,bir buse 

Yada bir kazık çak 

Seni yaşattığım yere

Mehmet Akif Gülhan  11.11.2005  Saat 22.19', 'Sitem etme ne olur Dayanamam ki buna  Yürek taşımıyorum artık Bin ton yük taşıyorum Akıl zaten yoktu bende Şimdi kafamın içi bulut dolu Ve a...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sitem-etme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamam ki', 'unutamam-ki-selma-erdeviren-4d9o0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bahtına mutluluk yıldızı olarak düşebilirdim,

Bir kocaman gözyaşı olarak düştüysem

Suçlusu ben değilim,

Sakın bana gücenme.

Sevmedi deme,

Unuttu deme,

Unutamam ki.

Beni yerden yere vurdu,

Dünyamı tersine çevirdi,

Yağmurla geldi

Rüzgarla gitti de

Ama unuttu deme,

Unutamam ki.', 'Bahtına mutluluk yıldızı olarak düşebilirdim, Bir kocaman gözyaşı olarak düştüysem Suçlusu ben değilim, Sakın bana gücenme. Sevmedi deme, Un...', ARRAY['Türk Edebiyatı','Şiir','Selma Erdeviren']::text[], 8.5, '{"poet":"Selma Erdeviren","poet_slug":"selma-erdeviren","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/unutamam-ki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereye Gitsen Alıp Başını', 'nereye-gitsen-alip-basini-selma-erdeviren-pum4j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nereye gitsen alıp başını,

Bilirim, yüreğindeki benim.

Acılar yaralasa en güzel düşünü

Bilirim, yüreğindeki benim.

Sen de bilirsin ki

Ben, seni en çok sevenim.', 'Nereye gitsen alıp başını, Bilirim, yüreğindeki benim. Acılar yaralasa en güzel düşünü Bilirim, yüreğindeki benim. Sen de bilirsin ki Ben, s...', ARRAY['Türk Edebiyatı','Şiir','Selma Erdeviren']::text[], 8.5, '{"poet":"Selma Erdeviren","poet_slug":"selma-erdeviren","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nereye-gitsen-alip-basini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Dizede', 'uc-dizede-devran-demir-8mawp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Üç dizede kadın:

Varlığı huzur yokluğu elem

Olduğu yer cennet

Olmadığı cehennem.

üç dizede çocuk

güneşten ödünç bir yüz 

denizden ödünç bir yürek

evrenden ödünç bir dil

üç dizede genç

engin bir duyuş

keskin bir görüş

metin bir duruş

üç dizede şiir

nereye dek 

kaçabilir ki insan

yüreğinin çığlığından

üç dizede şair

her an her yerde sevdalı

her an her yerde sancılı

bir dünyadır yaşadığı

2005', 'Üç dizede kadın: Varlığı huzur yokluğu elem Olduğu yer cennet Olmadığı cehennem. üç dizede çocuk güneşten ödünç bir yüz  denizden ödünç bir ...', ARRAY['Türk Edebiyatı','Şiir','Devran Demir']::text[], 8.5, '{"poet":"Devran Demir","poet_slug":"devran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/uc-dizede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam Umudu', 'yasam-umudu-ahmet-zeki-karali-ygkk2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşam bir mutluluk

Yaşanılabilirse

Güzellikse yaşamın parçası

Yitirilmezse

Hücreler doğanın ürünü

Ürün ise canlının

Can ise bizlerin

Ama umutlanılırsa

Yurdumda yaşama kastedenler

Ürünün gelişimini

Canlının doğumunu

Güzelliği ve yaşamı

Sonlayabileceklerini sandılar

Lakin öylece yanıldılar

Çünkü yaşam! ..

Onların sonlayamayacakları kadar

Bağımsız ve de özgür

Gelecek günler için de bir

UMUTTU

(5 Nisan)', 'Yaşam bir mutluluk Yaşanılabilirse Güzellikse yaşamın parçası Yitirilmezse Hücreler doğanın ürünü Ürün ise canlının Can ise bizlerin Ama umu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zeki Karali']::text[], 8.5, '{"poet":"Ahmet Zeki Karali","poet_slug":"ahmet-zeki-karali","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yasam-umudu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Çıktı', 'can-cikti-abdullah-yasar-erdogan-02q9j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kuldan niyaz eyledim hakkımı,

Doğruluk, hakikat benden de çıktı.

Güvenip sundum ona davamı,

Müfritte, serkeş zalim sultan çıktı.

Necat konusunda var bin müfrit,

Velakin zulmeti ayyuka çıktı.

Her devirde oldu bir müstebit,

Fakat kabirde kemikleri çıktı.

Şunu anladım hata bizdeymiş,

Ama letafet mütevazı çıktı.

Ne kadar  koşsak da nafileymiş,

Yorulan bedenimizden can çıktı.

İfratla tefrit girdi savaşa,

Ortalıkta mazlumun kanı çıktı.

İlim-irfanda oldu kargaşa,

Mektepte talebenin  adı çıktı.

Hane ahlakla olsun terbiye,

Lakin evlad-ı iyal dansa çıktı.

Ebeveynlerde muhtaç sevgiye,

Herc-ü merc içinde canları çıktı.

Bühtan içinde kalan güçlerle,

Fuhşiyat-ı zillet azamet çıktı.

Sehivi iş edinen beylerle,

Şeytan-ı racimde ortaya çıktı.

Münâfık hakim oldu dünyaya,

Masumun, muvahhidin canı çıktı.

Abid çekmedi nefsi sigaya,

Hukuk sisteminin çivisi çıktı.

Abdullah Yaşar beşaret ister,

Halet-i ruhaniye de fakir çıktı.

Akl-ı selime hidayet  göster,

İman-ı kâmilinde canı çıktı.

Müstebit: Baskıyla muamele eden.

Müfrit: Aşırı giden.

Necat: Kurtuluş.

Letafet: Yumuşaklık.

İfrat: İlerleme.

Tefrit: Orta yolun altında kalma.

Muvahhid: Allah’ın birliğine inanan.

Beşaret: Müjde.

Halet-i Ruhiye: Ruh hali, manevi durum.

Herc-ü  merc: Karmakarışık, altüst.

Sehiv: Yanlış, hata.

Şair: Abdullah  Yaşar  Erdoğan', 'Kuldan niyaz eyledim hakkımı, Doğruluk, hakikat benden de çıktı. Güvenip sundum ona davamı, Müfritte, serkeş zalim sultan çıktı. Necat konus...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/can-cikti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Legal Sevgili', 'legal-sevgili-ahmet-zeki-karali-qh5si', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dostlar hep yalnızlıktan

Arayıştan mutluluğu

Bahsettim ama

İnanın 95 per cent

Yalnız bence

Yani toplumun çoğunluğu

Siyasi birşeyler yazmak

İstiyor gönlüm

Ama o da yasak

Defol yasak oğlu yasak

Gel özlenilen

Gönülde aranan

Veya benim aradığım

Legal Sevgilim

YASALIM...

(Seksenli Yıllar)', 'Dostlar hep yalnızlıktan Arayıştan mutluluğu Bahsettim ama İnanın 95 per cent Yalnız bence Yani toplumun çoğunluğu Siyasi birşeyler yazmak İ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zeki Karali']::text[], 8.5, '{"poet":"Ahmet Zeki Karali","poet_slug":"ahmet-zeki-karali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/legal-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yiyin Birbirinizi', 'yiyin-birbirinizi-fevzi-kunucen-brobh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yiyin birbirinizi

İnsan kardeşlerim yiyin

Tepişin eşekler misali-tepişin

Mutlak günlük-güneşiklikti

Sizler yokken -bu dünya

Yazık

O güzelim gül bahçelerini

Ot bitmez çöle döndürdünüz

Korkunçtur hıncı toprağın

Gün gelir-alır altına sizi

Ne rütbeniz kalır omuzlarınıza

Ne de koltuklarınızda

Otombul kıçınızın izi

Sarar bir gün karanlıklar

Sarar sizi

Yiyin insan kardeşlerim-yiyin biri-birinizi...', 'Yiyin birbirinizi İnsan kardeşlerim yiyin Tepişin eşekler misali-tepişin Mutlak günlük-güneşiklikti Sizler yokken -bu dünya Yazık O güzelim ...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Künüçen']::text[], 8.5, '{"poet":"Fevzi Künüçen","poet_slug":"fevzi-kunucen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yiyin-birbirinizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğru mu?', 'dogru-mu-ahmet-zeki-karali-zozcm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine düşünüyorum kendimi

Eleştiriyorum benliğimdeki beni

Özümü, içremi, kendimi, bendemi

Acaba çok mu güçsüzüm olaylara

Yoksa genel tavır bu mu olmalı onlara

Ve Sen geliyorsun usuma böyle anlarda

Her nedense hiçbir zaman unutulmayan

Benliğimdeki güçsüzlüğü yaratan sen

''Ben''i sattım sana ben

Sen de aldın onu usulca

Hem de

Beş para ödemeden...', 'Yine düşünüyorum kendimi Eleştiriyorum benliğimdeki beni Özümü, içremi, kendimi, bendemi Acaba çok mu güçsüzüm olaylara Yoksa genel tavır bu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zeki Karali']::text[], 8.5, '{"poet":"Ahmet Zeki Karali","poet_slug":"ahmet-zeki-karali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dogru-mu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçer mi Zaman, Hastane Odalarında?', 'gecer-mi-zaman-hastane-odalarinda-kenan-mim-eryigit-vxsp6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni de boğar, beni de..

çaresizliğin kokusunu gel bana sor! . 

umarsız- umarsız bakar gözler

beklemek ne zordur, ne zor! .

_____________________geçer mi zaman,

_____________________hastane odalarında? 

              ***

derdi, derde düşen bilir

umutlarsa, bir bir kaybolur

kurumuş olsa da göz pınarları

yaşlar için için akar sel olur.

.____________________geçer mi zaman,

____________________ hastane odalarında? 

              ***

bu yatan, canımdan bir parça

şu yatan, benim canım..

bu benim, biricik babam,

şu benim, biçare insanım..

____________________geçer mi zaman,

____________________hastane odalarında? 

              ***

kavruk yüzler, kurumuş eller

her geçenden imdat diler.

silinmez yazıyla yazılmış yazıyı

bilmem ki, kim siler? 

_____________________geçer mi zaman,

_____________________hastane odalarında? 

             ***', 'seni de boğar, beni de.. çaresizliğin kokusunu gel bana sor! .  umarsız- umarsız bakar gözler beklemek ne zordur, ne zor! . ________________...', ARRAY['Türk Edebiyatı','Şiir','Kenan Mim Eryiğit']::text[], 8.5, '{"poet":"Kenan Mim Eryiğit","poet_slug":"kenan-mim-eryigit","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gecer-mi-zaman-hastane-odalarinda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Ortasında', 'gun-ortasinda-fevzi-kunucen-rbidz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seviler sızı

Seviler - ince bir duman

Merhametsiz bir buluttur sevi

Damar-damar çatlatır yüreğimizi

Ayak-bileklerimizde bukağıları

Düşeriz yollara yalınayak-başı açık

Şarha-şarha yarılır tabanlarımız

Ya alır götürür seviler

Ya da gün ortsında öldürür bizi...', 'Seviler sızı Seviler - ince bir duman Merhametsiz bir buluttur sevi Damar-damar çatlatır yüreğimizi Ayak-bileklerimizde bukağıları Düşeriz y...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Künüçen']::text[], 8.5, '{"poet":"Fevzi Künüçen","poet_slug":"fevzi-kunucen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gun-ortasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin gibi gülmüyor', 'senin-gibi-gulmuyor-nazan-i-zmirli-qkk3y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dağlar gezdim 

taşlar  gezdim

birçok diyar dolaştım

en mutlu anların fotoğraflarına baktım

.............................senin gibi gülmüyor

elimde son fotoğrafın

nerde    karelediğimi

hatırladım.................! 

baktıkça  bakıyorum

her bakışta

başka mana

arıyorum......

hadi ! saklama

merak ettin biliyorum.

dinleyemediğin

yüreğinin sesini,

içindeki     ateşi

bakışlarının dilini anlatıyor.

her  tebessümünde

hissetmen  onu  teninde

anlamına anlam katman 

yüreğinde.......................

z  i  r   v   e   l   e   r   e 

çıkmak seninle

dudaklarımız tebessümle kilitlenmeli

 ne olur! 

 ne olur!  hep gülümse.........................

Nazan İzmirli

11.11.2005-ant', 'dağlar gezdim  taşlar  gezdim birçok diyar dolaştım en mutlu anların fotoğraflarına baktım .............................senin gibi gülmüyor ...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/senin-gibi-gulmuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evrenin Gizemi', 'evrenin-gizemi-ahmet-zeki-karali-8xbvq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine insanı düşünüyorum

Dalıyorum gizemine evrenin

Sorunlarımı düşünüyorum birlikte

Sonsuzluğa varıyorum

Odam soğuk, rutubetli

Ayrıca dumanlı da nedense

Başımı döndürüyor artık ayrılıklar

Ve sensizliği  öğreniyorum

Sevenleri ben  mi sevmiyorum

Yoksa sevdiklerim beni mi,

Sevisiz kaldım gibi koca evrende

Düşüyorum bir boşluğa sanki

Yine de beklentilerim var gibi

Değişti işte zaman ve dünya

Beklentiler getiriyor insana yaşam

En umulmadık bir anda dahi

Değiştiriyor insanın yaşamını Y-A-Ş-A-M

(18.10.1981)', 'Yine insanı düşünüyorum Dalıyorum gizemine evrenin Sorunlarımı düşünüyorum birlikte Sonsuzluğa varıyorum Odam soğuk, rutubetli Ayrıca dumanl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zeki Karali']::text[], 8.5, '{"poet":"Ahmet Zeki Karali","poet_slug":"ahmet-zeki-karali","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/evrenin-gizemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-hidir-altas-vk47z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kardeşlerim  gidiyor birer birer

Canımdan parça kopuyor eyvah

Eller uzanmıyor bizlere

Kalmışım yalnız ve çaresiz eyvah

İsyan ediyorum yalnızlığa

Nerde zenginler ağalar heyy

İşi biten çekip gidiyor

Nerde vaat eden vefasızlar heyyy

Herkez başka başka alemde

Düşünen yok bizleri vah vah

Kimisi eğlencede barda

Kalmışım hastanede vah vah

Turhani der böylemi olmalı

Bir gün düşersin sende heyyy

Böyle sürmez sefanız

Biter bir gün neşeniz heyyyy', 'Kardeşlerim  gidiyor birer birer Canımdan parça kopuyor eyvah Eller uzanmıyor bizlere Kalmışım yalnız ve çaresiz eyvah İsyan ediyorum yalnız...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Altaş']::text[], 8.5, '{"poet":"Hıdır Altaş","poet_slug":"hidir-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/isyan-114-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Sıkılıyor Bu Gece', 'canim-sikiliyor-bu-gece-fethi-aslan-h1czw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Canim sıkılıyor bu gece.

Gece karanlığına bürünmüş yüreğim.

Ne yapsam kar etmiyor 

Durmadan yeni bir sigara daha yakıyorum,

biten sigaramın ardından.

Sigarayı degil sanki ucunda kendimi yakıyorum,

sızlıyor her tarafım.

Canım sıkılıyor bu gece

Televizyon`da hergün görünen zat-ı muhterem`e,

ağız dolusu bir küfür sallıyorum, ana-avrat.

Acıp pencereyi gece`yi izliyorum.

Gece`yi ve gelip gecen insanları,

kimi iki ekemek sıkıştırmıs koltuğunun altına,

kimi bir şişe şarap.

Olsaydı da içseydim diye geçiriyorum içimden

yanına biraz da beyaz peynir.

Canım sıkılıyor bu gece.

Hiç bir şey kar etmiyor, gece karanlığına bürünmüş yüregime.

Ne sigara,ne zat-ı muhterem`e ettiğim küfür,

ne de karsi pencereden el eden sarışın dilber.

Yağmur başladı dışarıda,

silah gibi patlıyor ardı ardına gök gürültüsü.

Rüzgar esiyor, dogudan esiyor bugün rüzgar.

Ülkem`den esiyor.

Senin kokun geliyor burnuma,memleketimin havasiyla.

Canim sıkılıyor bu gece,

binmek geliyor içimden dizelerimin üstüne.

Binip dizelerimin üstüne,

geçip dört Nal`a Ren`in üstünden,

Ülkem`e gitmek istiyor canim..

Canım sıkılıyor bu gece

Yüreğim düşürülmüş,teslim olmuş bir şehir.

Yüzbin kişilik bir ordu girmiş gibi.

Fırtınalar kopuyor yüreğimde,

bir yaprak kopar gibi dalından,

birşeyler kopuyor yüregimden.

Canım sıkılıyor bu gece,

hiçbir şey kar etmiyor yüreğime.

Ne sigara,ne zat-ı muhterem`e ettiğim ağızdolusu küfür,

nede karsı pencere`den el eden sarışın dilber.

Ülkemi istiyor bugün canım.....', 'Canim sıkılıyor bu gece. Gece karanlığına bürünmüş yüreğim. Ne yapsam kar etmiyor  Durmadan yeni bir sigara daha yakıyorum, biten sigaramın ...', ARRAY['Türk Edebiyatı','Şiir','Fethi Aslan']::text[], 8.5, '{"poet":"Fethi Aslan","poet_slug":"fethi-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/canim-sikiliyor-bu-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor ki', 'zor-ki-nazan-i-zmirli-m5ka0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sensizlik 

sensizlik

sensizlik

öylesine  zor ki! 

çöl.....................

..........susuzluğu

yıldızsız..............

..............gökyüzü

aysız..................

...............geceler

güneşsiz............

......................gün

gibi.....................

beni 

..........sensiz

.......................bırakma 

...........uzakta

olsa.

Nazan İzmirli

11.11.2005-ant', 'sensizlik  sensizlik sensizlik öylesine  zor ki!  çöl..................... ..........susuzluğu yıldızsız.............. ..............gökyüzü...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/zor-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yusufum', 'yusufum-hidir-altas-hxiko', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Antalya''nın dereleri kurudu

Yusuf''umda yetmezliğe tutuldu

Yusuf''um kara toprağa kondu

Anacığı Yusuf''una kahroldu

Dereler soğuk soğuk akarmı

Antalya''nın sıcakları yakarmı

Yusuf''um mezarından bakarmı

Babacığı Yusuf''una yanarmı

Turhani Yusuf''una ağladı

Yüreğini yokluğu dağladı

Çocukları Yusuf''umsuz kaldı

Makineler Yusuf''suz boş kaldı', 'Antalya''nın dereleri kurudu Yusuf''umda yetmezliğe tutuldu Yusuf''um kara toprağa kondu Anacığı Yusuf''una kahroldu Dereler soğuk soğuk akarmı ...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Altaş']::text[], 8.5, '{"poet":"Hıdır Altaş","poet_slug":"hidir-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yusufum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bozacıyla Şıracı', 'bozaciyla-siraci-kadir-soyturk-scz20', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Birisi bozacıydı, 

Birisi de Şıracı

Adalet umuyoruz

Biz onlardan, ne acı! 

Zakkum ağacında 

Yetişir mi nar? 

Onların bölücüye,

Eşcinsele,bilmem daha kimlere

Muhabbeti var.......

Boyalı, cilalı sözler

Çare olur mu derde! 

Hani insanlık nerde? 

İnsan hakları nerde?', 'Birisi bozacıydı,  Birisi de Şıracı Adalet umuyoruz Biz onlardan, ne acı!  Zakkum ağacında  Yetişir mi nar?  Onların bölücüye, Eşcinsele,bil...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bozaciyla-siraci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgür bırak', 'ozgur-birak-nazan-i-zmirli-6fnsj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'özgürsek biz ikimiz

zirvelerden 

aşkımızı

taşıyacak kadar

ö z gü r   b ı r a k

kuşlarını 

tatsınlar   aşkı

maviye  kavuşsunlar

bulutlarla  tanışsınlar

konsunlar   sensizlik

kokan

hanımelli pencereme

görsünler sensiz kalışlarımı

kucaklayıp,öpüp okşayayım

parmaklarının izlerini arayayım

zarif  ruhunu  taşıdığın her birini 

çocukların diye koklayayım.......

Nazan İzmirli

11.11.2005-ant', 'özgürsek biz ikimiz zirvelerden  aşkımızı taşıyacak kadar ö z gü r   b ı r a k kuşlarını  tatsınlar   aşkı maviye  kavuşsunlar bulutlarla  t...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ozgur-birak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdanın Marifetleri', 'sevdanin-marifetleri-nail-oruc-w0bfd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tutmalıyım kendimi seni sevmemek için

Gözlerine bakadurmamalıyım 

Biliyorum sonu olmayacak

Tanıyorum kendimi zaaflarım baş gösterecek yine.

Bir gülümsemen bile yetecek bana 

Ya da bir küçük merhaban

Küçük olan her şey büyüyecek gözümde

Bir küçük damla bile  ırmaklara dönecek

Bir yarısı boş alan bardağın

Dolu olan tarafı  görünecek bana

Ağlayacağım bazen nisanın yağmurlu gecelerinde 

Ama senin için değil,sevdanın acemileri için

Gecelerle karışık gündüzlere uyanacağım

Gündüzlerden kalan senleri biriktireceğim odamda

Konuşacağım onlarla bir bir hiç usanmadan

En güzel olanlarını rüyalarıma saklayacağım

Kaçırmak istesen de gözlerini gözlerimden

Buna gücün yetmeyecek

Bir tek orda bakarım gözlerine çünkü kulaklarım kızarmadan

Ellerimi yorgan ederim ellerine gözlerimi kaçırmadan

Bırakamam bir daha seni uyansam da 

Bazen yağmurlardan kalma bir damla olurum

Bazen de göz yaşlarımdan

Usulcana süzülürüm bedeninde

Saçlarından gözlerine, derken dudaklarına

Yüreğinin çarpıntılarıyla kıpırdanmaya başladığım yerde; 

Biriktikçe birikirim anaforlar çizerek

Ta ki bir çatlak bulup içine akıncaya dek…', 'Tutmalıyım kendimi seni sevmemek için Gözlerine bakadurmamalıyım  Biliyorum sonu olmayacak Tanıyorum kendimi zaaflarım baş gösterecek yine. ...', ARRAY['Türk Edebiyatı','Şiir','Nail Oruç']::text[], 8.5, '{"poet":"Nail Oruç","poet_slug":"nail-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sevdanin-marifetleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Akşamları', 'gurbet-aksamlari-huseyin-ozan-ozturk-h4upe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağır ağır çöker gönlüme hüzün,

Gecenin karanlığınca...

Bir ezgi yankılaşır kulaklarıma hazin,

Bir türkü duyulur inceden,

Acı.buruk...

Hep ağlamak gelir içimden,

Puslu geceler boyunca

İlmik ilmik dolanır boynuma gariplik.

Yumak yumak uçar göklerde; 

Hasret yüklü bulutlar...

Sessiz sessiz akar gözyaşlarım,

Güz yağmurlarınca...

Çığlık çığlık yükselir,

Gönlümden bir hıçkırık.

Şafaklar tuzlu gözyaşlarımla yıkanır; 

Ilık ılık.

Yalnızlık sırtıma çöker de çöker...

Evrenin ağırlığınca...

Yığın yığın düş görürüm, uyanık.

Sevdiklerim çalar kapımı,

Bir sürü el uzanır bana

Sarmak istercesine.

Hep düş görürüm gece boyu,

Gözlerim açık.

Haykırmak gelir içimden; 

Gücüm yetmez.

Ellerim bağlı,kollarımda pranga,

Bonumda zincir:FAKİRLİK.

Sırtıma çöker de çöker; 

Üst katında dans edilen bodrum,

Düşündükçe kahrolurum.

Mengeneyle sıkar beni,

Gün gömeyen,küf kokan odam; 

Kalkar şafaklaradek dolaşırım,

Koca kentin mermer kaldırımlarında...

Düşünür kahrolurum,gezer ağlarım,

Gurbet akşamlarında! gurbet akşamlarında!', 'Ağır ağır çöker gönlüme hüzün, Gecenin karanlığınca... Bir ezgi yankılaşır kulaklarıma hazin, Bir türkü duyulur inceden, Acı.buruk... Hep ağ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ozan Öztürk']::text[], 8.5, '{"poet":"Hüseyin Ozan Öztürk","poet_slug":"huseyin-ozan-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gurbet-aksamlari-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredeydiniz?', 'neredeydiniz-melih-coskun-c9475', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neredeydiniz? 

Kül olup yağarken

Yanan bedenimiz

Kış günü kar yerine. 

Katledilirken çocuk gülümseyişi 

Yedi yaşında bir kız çocuğunun... 

Kurşunlanırken meydanlarda 

Binlerce ve binlerce kez. 

Camlarımız tuzla buz edilirken 

Ve yıkılırken kürsülerimiz... 

Neredeydiniz? 

Yakılırken türkülerimiz.

Karışırken kara toprağa

Yazılmamış şiirlerimiz... 

İstiklal’de bir kapı eşiğinde

Açlığından ağlarken alın terimiz 

Kaldırımların kemirdiği ayakkabılarımız 

İçerken kana kana sonbahar yağmurlarını...

Neredeydiniz? 

Yok pahasına satılırken 

Doğmamış çocuklarımızın geleceği 

Emeğimiz 

binlerce, onbinlerce 

Kapı önüne atılırken

Yıkılırken evlerimiz başımıza

Eriyen kar suları akarken yatağımıza. 

Ve bütün kapılar kapanırken suratımıza

Neredeydiniz? 

Biz bu dünyada 

Sadece insan gibi yaşamaya çalışırken... 

2005', 'Neredeydiniz?  Kül olup yağarken Yanan bedenimiz Kış günü kar yerine.  Katledilirken çocuk gülümseyişi  Yedi yaşında bir kız çocuğunun...  K...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/neredeydiniz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni yaşamıyorum', 'beni-yasamiyorum-nazan-i-zmirli-fvcz1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sorma! 

neler oluyor 

bilmiyorum

beni yaşamıyorum

yüreğimde derinnn

iz  bırakan

yıldız   alacasını

ela   ela  bakan

bilmeceyi

sihirli

tebessümünü

...............adını

.......................tadını 

rüzğarın    boynunu

................yalayarak

getirdiği.................

...................kokunu

yaşıyorum...............ve...................... yazıyorum.

ben   tebessümlerinle   bana  taşıdığın   coşkunu

seni  yaşıyorum......................................................

benim suçum yok ki...............................................

Nazan İzmirli

11.11.20005-ant', 'sorma!  neler oluyor  bilmiyorum beni yaşamıyorum yüreğimde derinnn iz  bırakan yıldız   alacasını ela   ela  bakan bilmeceyi sihirli tebess...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/beni-yasamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-asima-azra-en64u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne yüzlerdeki manasız askı

Ne beyinlerdeki tazyikli baskı

Ne gözlerde saklı ayrıntılardı olay…

……………………………………...

Adamı ipe götüren dildeki alay!', 'Ne yüzlerdeki manasız askı Ne beyinlerdeki tazyikli baskı Ne gözlerde saklı ayrıntılardı olay… ……………………………………... Adamı ipe götüren dildeki a...', ARRAY['Türk Edebiyatı','Şiir','Asima Azra']::text[], 8.5, '{"poet":"Asima Azra","poet_slug":"asima-azra","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ne-den-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AyNI MI', 'ayni-mi-aysel-zengingul-1a0xh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beyaz satırlar çelişki yüklüyor anlamlarına,

Her şeyden her şey yapabilen biz,

Bi kendine yenik,

senin sahanda…

  

Düşünmekle - anlatmak aynı mı? 

    Yaşamakla- ölmek,

    Gece ve gündüz….

Düşlediğimiz gibi anlatamıyoruz,

Ölüyormuş gibi yaşıyoruz acıyı…

Gündüzlerde bile, 

zifiri bi karanlık olmuyor muyuz….? 

Sevmek ve ayrılmak aynı mı? …

Dokunmak ve hissetmek? …

30/10/2005 06; 27 ist.', 'Beyaz satırlar çelişki yüklüyor anlamlarına, Her şeyden her şey yapabilen biz, Bi kendine yenik, senin sahanda…    Düşünmekle - anlatmak ayn...', ARRAY['Türk Edebiyatı','Şiir','Aysel Zengingül']::text[], 8.5, '{"poet":"Aysel Zengingül","poet_slug":"aysel-zengingul","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ayni-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı tatmak', 'aski-tatmak-nazan-i-zmirli-4lnos', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'masum   bir   bebekten

ilk  tebessümü  görmek

ilk  öpücüğü  almak gibi

tanyeli   ağırmadan

güneşin tüm gücünü

yüreğinde  hissetmek gibi

gözlerini  açarsın  sabahlara

kuş  seslerinin  dinginliğinde

çağlayan suların bedenini sarması gibi

kalbindeki  sancı

filizlenen  yeni  umutlar

içindeki telaşı anlatır gibi

akşam  alacasında

gün batımını izlerken Eren dağında

ardı sıra bir kısrak gibi koşmak istersin

ekersin  dileklerini  vadiye  uzanan ovaya

bırakırsın  erenler diyarına

volkanik  bir  oluşumun ortasına

ıssız kalınca 

seninle  sensiz   kalınca

yıldızsız aysız gecelerde

için sıkılınca....................

onunla   olmak   istersin

uzak   yakın   ne    varsa

sesini   duymak  istersin

sarılırsın  telefona

alo

alo

alooooo  AŞKIM 

seni tatmak varya

12.11.2005-ant', 'masum   bir   bebekten ilk  tebessümü  görmek ilk  öpücüğü  almak gibi tanyeli   ağırmadan güneşin tüm gücünü yüreğinde  hissetmek gibi gözl...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/aski-tatmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuza Kadar', 'sonsuza-kadar-durdane-demirkoparan-8dzft', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin sessizliğinden çıkıp gelsen

Yaz yağmuru gibi yağsan üzerime

İçime ılık ılık huzur versen

Gözlerime baksan seviyorum seni desen

Desem ki seviyorum seni

Kapkara bulutlardan çıkıp gelsen

Dünyamı aydınlatsan 

Güneşim olsan

Sımsıcak sarsan beni

Ellerimi tutsan seviyorum seni desen

Desem ki seviyorum seni

Sonsuz yokluğundan çıkıp gelsen

Hep yanımda olsan

Uyandığımda yanıbaşımda   bir seni görsem

Kokunu duysam Seviyorum seni desem

Desen ki seviyorum seni…', 'Gecenin sessizliğinden çıkıp gelsen Yaz yağmuru gibi yağsan üzerime İçime ılık ılık huzur versen Gözlerime baksan seviyorum seni desen Desem...', ARRAY['Türk Edebiyatı','Şiir','Dürdane Demirkoparan']::text[], 8.5, '{"poet":"Dürdane Demirkoparan","poet_slug":"durdane-demirkoparan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sonsuza-kadar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşça kal', 'hosca-kal-durdane-demirkoparan-o9i2r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her şey  buraya  kadarmıydı

Söyle  nasıl  dayanırım  nasıl

Alışırsın  diyorsun  ya  hep  sevdiğim

Nasıl  alışacağımıda  söyle

Gittin bütün  hayallerim  ruhum  her şeyim  sende  kaldı

Birtek  yüzük

Bir tek  yüzük  kaldı  bende ikimizin yüzüğü

Onuda  alsaydın  giderken

Dayanamıyorum  görmeye 

Dayanamıyorum  bakmaya

Alışamıyorum  sensizliğe

Her acı  bir  gün biter  diyorlar

Zaman  her şeyin  ilacı  diyorlar

Hayır  öyle  değil  işte

Zaman  acıma  acı  katmaktan  başka  birşey   yapmıyor

Hiç  bir  şey  senin  yerini  doldurmuyor

Tek  çare var artık

Başka  türlü  başa  çıkılmaz  bu  acıyla

Ölüm

Zaten  sensiz  her gün  ölüyorum  ben

En  güzeli  bir kez ölmek 

Senin  yokluğun  acıtmayacak  artık  içimi

Kokunu  bile  özlemeyeceğim

Yalnız  seni severken  öleceğim

İşte  tek  tesellim bu  artık

Seni  çok  seviyorum  bitanem

Hoşça kal …

                                        7.11.2005

hoşçakal sevdiğim s.y', 'Her şey  buraya  kadarmıydı Söyle  nasıl  dayanırım  nasıl Alışırsın  diyorsun  ya  hep  sevdiğim Nasıl  alışacağımıda  söyle Gittin bütün  ...', ARRAY['Türk Edebiyatı','Şiir','Dürdane Demirkoparan']::text[], 8.5, '{"poet":"Dürdane Demirkoparan","poet_slug":"durdane-demirkoparan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hosca-kal-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Topladığı güller sen kokmalısın', 'topladigi-guller-sen-kokmalisin-nazan-i-zmirli-ju0zc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aşık  olmak  husutsuz  gönlünce

aşkı  yaşamak  tüm   benliğinde

aşkı taşımak bedeninde özgürce

diller  konuşmadan,gözlerin geceleri aydınlatmalı

seni her gören   güzelliğinden  anlamalı

korkmamalısın  biter  diye  bu  ışık

yerine heran yeni heyecan dolmalı

üşürken  ısınmalısın  onunla

ağlarken    gülmelisin

çıkmaz sokaklar açılmalı 

görmeyen gözler görmeli

kuş olup uçmalısın

bülbül olup gülüne konmalısın  bahçesinde

her sabah vazosu için, 

topladığı güller sen kokmalısın

aşkı  yaşamalı ve  yaşatmalısın

Nazan İzmirli

12.11.2005-ant', 'aşık  olmak  husutsuz  gönlünce aşkı  yaşamak  tüm   benliğinde aşkı taşımak bedeninde özgürce diller  konuşmadan,gözlerin geceleri aydınlat...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/topladigi-guller-sen-kokmalisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Seni Özler', 'hep-seni-ozler-cahit-pehlivan-dqm6g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ellerinde gonca gonca beyaz güller,

Yanağında sıcak sıcak tebessümler,

Diline yanık ezgili, sevgi dolu türküler,

Ah! ... bu deli gönlüm, hep seni, hep seni özler.

Uçan kuşlar, benim gibi neşeli, sevinçli,

Açan güller, benim gibi temiz, erdemli.

Akan sular, benim gibi coşkun, deli.

Ah! ... bu deli gönlüm, hep seni, hep seni özler.

Şimdi uzaklarda yaşıyoruz, beraber,

Özlem dolu bu anlar, yaşanmaya da değer.

Beni bir an olsun, unutacaksan eğer,

Al sende kalsın, hem anılarımız, hem resimler,

Biliyorum. O anlar tekrar hatırlanmaya da değer...

KARS', 'Ellerinde gonca gonca beyaz güller, Yanağında sıcak sıcak tebessümler, Diline yanık ezgili, sevgi dolu türküler, Ah! ... bu deli gönlüm, hep...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hep-seni-ozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O sensin,ama o sen değilsin.', 'o-sensin-ama-o-sen-degilsin-ercan-akbay-cgi7x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerin gözlerime bakıyor,

 Ellerin ellerimi tutuyor,

 Saçların yüzüm de savruluyor,

 Dudakların beni öpüyor,

 Yüzün de bir gülücük,

 Duruşun da bir endam,

 İçim de ateşler yakıyor,

 O sensin,

 Ama o sen değilsin.........

                                 11.11.2005 Yeniköy.', 'Gözlerin gözlerime bakıyor,  Ellerin ellerimi tutuyor,  Saçların yüzüm de savruluyor,  Dudakların beni öpüyor,  Yüzün de bir gülücük,  Duruş...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/o-sensin-ama-o-sen-degilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahrolan Bir Yaşam', 'kahrolan-bir-yasam-cahit-pehlivan-kc3xh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Göz yaşlarım damla damla  düşüyor,

Gönlüm yine, yine sana hüzünleniyor,

Aşkım artık burada son buluyor.

İşte, bir yaşantı daha böylesine,

Evet sevgilim böylesine kahroluyor.

Gönlüm artık seninle avunmayacak,

Ellerimde artık senin resmini tutmayacak.

Gözlerim ise, seni hiçbir yerde aramayacak,

İşte yaşamım böylesine kahrolacak.

Kulaklarım, aşk melodilerine kapalı, 

Evet sevgilim, neredeyse yıl oldu,

Kapıma postacı uğramayalı,

Her şeyden uzaklaştım. Uzaklardayım.

Şu anda da kahrolan bir yaşantımı,

Yaşamaktayım...

KARS', 'Göz yaşlarım damla damla  düşüyor, Gönlüm yine, yine sana hüzünleniyor, Aşkım artık burada son buluyor. İşte, bir yaşantı daha böylesine, Ev...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kahrolan-bir-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tövbe', 'tovbe-cahit-pehlivan-7qsvq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayır artık, hayır hayır sevgilim,

Bundan sonra, bende  kararımı verdim.

İnan ki artık, senden istemeyeceğim,

Evet, artık hiçbir şey istemeyeceğim.

Karanlıklardan, medet ummayacağım.

Kadehlere, deliler gibi sarılmayacağım.

Karanlık sokakların ucube köşelerinde

Senin ismini anarak, sızmayacağım.

Elimde artık ne şişeler, ne resmin olacak,

Dilim, seni şarkılarla da anmayacak,

Masamın başucunda ne mum yanacak,

Ne de elimdeki kalemim seni anlatacak.

Aşkımızın en son melodileridir diye,

Sahildeki dalgaların sesini de dinlemeyeceğim.

Senin yanaklarına benziyor diye,

Artık gonca gülleri dahi, sevmeyeceğim.

Sensiz olan her yer, şimdi benimdir.

O yaşanan olaylar, benim kaderimdir.

Kadere bir şey diyemem, boyun eğerim.

Artık bende, mutluluk denizinde bir yelkenliyim...

Kars', 'Hayır artık, hayır hayır sevgilim, Bundan sonra, bende  kararımı verdim. İnan ki artık, senden istemeyeceğim, Evet, artık hiçbir şey istemey...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tovbe-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İ s t i y o r u m', 'i-s-t-i-y-o-r-u-m-cahit-pehlivan-10lq8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen, güfteci kardeş, öyle bir güfte yaz ki,

İçerisinde, İrem bağlarından esintiler olsun.

Sen, besteci kardeş, öyle bir beste yap ki,

Dinleyen bütün insanlar, söyleyip coşsun.

Sen, ressam kardeş, öyle bir tablo yap ki,

İçerisinde yirmi sekiz renkli gök kuşağıyla, her renkten kırmızı,

Sen, heykeltıraş kardeş, öyle bir anıt yapacaksın ki,

Bakana yudum, yudum yaşatsın bütün hayatını,

Sen, imam kardeş, öyle bir dua yapacaksın ki,

Bütün sevenleri kavuşturup, ayrılanları da birleştirmelisin.

Sen ozan kardeş, öyle bir şiir yazacaksın ki,

Her hecende, mısran da, özlemi, sevgiyi dile getirmelisin.

Sen, aşık kardeş, öyle bir ah! ..  etmelisin ki,

Bütün aşıkları kabrinden kaldırıp, kendine zikrettirmelisin.

Sen, Cahit kardeş, öyle bir söz söylemelisin ki,

Geceleri dahi gündüz edip; bizleri ölümsüzleştirmelisin.

Kars', 'Sen, güfteci kardeş, öyle bir güfte yaz ki, İçerisinde, İrem bağlarından esintiler olsun. Sen, besteci kardeş, öyle bir beste yap ki, Dinley...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/i-s-t-i-y-o-r-u-m-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azıksız Çıkma Yola', 'aziksiz-cikma-yola-bahaettin-karakoc-o2fk7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir nehir geçeceksen, önce soyunmalısın,

Bir dağı çıkacaksan, soluklu olmalısın.

Madem ki niyetlisin, seferin kutlu ola! 

Caydırmayı düşünmem, ama derim ki sana:

Azıksız çıkma yola! ...

Seferin savaşaysa sağlam kuşanmalısın

Zaman öyle bir at ki ihmâle vermez mola! 

Erkenden daha erken uyan ki kazanasın

Mahmur “biraz daha”lar düğümü çok tuzaktır

Azıksız çıkma yola! ...

Pınarın gözü ise aradığın, sendedir.

Üzengiye sağlam bas, dizgini ele dola! 

Güz bahçelerinde gazel toplama, çiçek topla,

Boşa vakit öldürme, yarına kefilin yok

Azıksız çıkma yola! ...

Vuslatsa istediğin, in insanın içine

Ve çarşılarda dolaş Azrail’le kol-kola! 

Mezarlığa git düşün, düğünlere git ağla

Kanadın sızlasa da Uhud kadar ağır ol

Azıksız çıkma yola! ...

Öyle bir abdest al ki, su bile sarhoş olsun

Sen yaprak ve çiçek ol, gördüğün kuru dala

Hep gönül şehri onar, kâinata sevgi sun

Her ham söze sağır ol

Azıksız çıkma yola! ...

Nereye gidersen git, heybene gönül doldur

Bir kovan parçalama bir parmak acı bal’a! 

Yontuldukça yer kapla ve her zaman güzel kal,

Temiz ol, fazlanı at, eksiğini tamamla

Azıksız çıkma yola! ...

Bahaeddin KARAKOÇ (Ay Şafağı Çok Çiçek –Beyan Yay. İstanbul / 1998)', 'Bir nehir geçeceksen, önce soyunmalısın, Bir dağı çıkacaksan, soluklu olmalısın. Madem ki niyetlisin, seferin kutlu ola!  Caydırmayı düşünme...', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/aziksiz-cikma-yola-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çabuk yaşlandın sen çabuk', 'cabuk-yaslandin-sen-cabuk-sinan-aydindag-jry43', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '08 kasım 2004

Çabuk yaşlandın sen çabuk

Bu hayat seni erken çökertti

Daha saçların beyazlamadan,

Cigerlerin iflas etti

Biliyorum ki bu bunalımlar seni mahvetti

Oysaki yaşın yirmi dörttü senin

Güzel hayallerin umutlu gülüşlerin vardı senin

Kimseyi kırmazdı acı-tatlı sözlerin

Ama neylersinki

Bu hayat erken çökertti erken çökertti seni.', '08 kasım 2004 Çabuk yaşlandın sen çabuk Bu hayat seni erken çökertti Daha saçların beyazlamadan, Cigerlerin iflas etti Biliyorum ki bu bunal...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cabuk-yaslandin-sen-cabuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretle gelen karanlık', 'hasretle-gelen-karanlik-sinan-aydindag-9uyx5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '15 kasım 2004

Mutsuz bir yaşam sürüyorum

Yalnızlıktan sürüm sürüm sürünüyorum

Ne havanın tadı var ne de suyun

Yokluğunda kupkuru hayat kuyum

İnanki hasretin bir dağ gibi içimde

Tüm yaşantıma bir set çekmiş gibi önümde

Karanlık,karanllık ve herşey karanlık

Hayatımdan gittiğinden beri her yer

Karanlık', '15 kasım 2004 Mutsuz bir yaşam sürüyorum Yalnızlıktan sürüm sürüm sürünüyorum Ne havanın tadı var ne de suyun Yokluğunda kupkuru hayat kuyum...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hasretle-gelen-karanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gene de', 'gene-de-metin-yalti-wdo6q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir lokma aşk 

Bir yudum sevgi 

Biraz da gülümseme 

İstemiştim sadece

Bir lokma aşkı

Bir yudum suyu

Esirgedin benden

Esirgemediğinse 

Gülümsemendi sadece

Sevindim bilesin

Üstüme gülmek 

Alsam da…

Hem aç 

Hem susuz kaldık 

Desem de

Aldırma bana sen 

Gene de

11.11.05 saat11/11', 'Bir lokma aşk  Bir yudum sevgi  Biraz da gülümseme  İstemiştim sadece Bir lokma aşkı Bir yudum suyu Esirgedin benden Esirgemediğinse  Gülüms...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gene-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazim Hikmet`e Mektup', 'nazim-hikmet-e-mektup-fethi-aslan-u386o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Büyük usta Nazim Hikmet`in anısına

Sen yokken burada,

değişen birşey olmadı iyiden yana.

Halen ayaklarında ki ziciri servet,

iki büklüm olup papuc yalamayi nimet sayanlar var.

Devlet soygunculuğu,devlet terörü,devlet kumarhaneleri.

En yasalından pezevenklik.

Vurdu kaçtılar,çaldi çırptılar

kölelik,köçeklik-hatircılık,katırcılık.

Faili malum cinayetler-keşkeler,meşkeler.

Masa başında devrimler,

dönmeler,homolar,feministler,sadistler,mazoşistler,faşistler.

Belki yarınlar,Allah`a şükürler.

Hangi bakan`ın ayaği kokuyor tartişmalari,

meclis`te çiğ köfte sefalari.

Discolar,barlar,Cafeler,kerhaneler.

Orada burada konusulmakta yine,

mankenler,ibneler,Araba markaları.

Futbol,hentbol,basketbol,

yataklarda atılan kafakol.

Ağlamakli gözler

ve neyazık ki tepkisiz yüzler var.

Kendi dilimde en güzel sevda sözlerini bile söyleyememekteyim sevdigime.

Ve kolumda ki iz,kolumu kaplayan Altin kaplamali bir saatin degil,

kalem tutan ellerime vurulan  kelepçenin izidir.

Ve ayağımda ki zincir yarasıdır kalın ve derinden etimi kesen.

Ve bugün gülüşlerimiz mutluluktan değil,

acılara ve baskılara inat yaşama naralarıdır ustam.

Ve bugün en güzel sevda sözlerimiz,

özlemlerimiz ve sabırla bekleyişimiz,

bir sevgili icin değil.

O güzel yarınlar içindir.', 'Büyük usta Nazim Hikmet`in anısına Sen yokken burada, değişen birşey olmadı iyiden yana. Halen ayaklarında ki ziciri servet, iki büklüm olup...', ARRAY['Türk Edebiyatı','Şiir','Fethi Aslan']::text[], 8.5, '{"poet":"Fethi Aslan","poet_slug":"fethi-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/nazim-hikmet-e-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden hiçbirşey olmamalı', 'senden-hicbirsey-olmamali-sinan-aydindag-i26ix', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '26 kasım 2004

Herkesden ve herşeyden uzaklaşmak istiyorum

Belki bir işe girmeliyim

Belkide buralardan çekip gitmeliyim

Bir şekilde kendimi terk etmeliyim

Bir yol,bir iz,bir işaret gerek bana

Kararımı verdim buralardan çekip gitmeliyim

Senden hiçbirşey olmamalı,ondanda ve

Tabiki bendende.', '26 kasım 2004 Herkesden ve herşeyden uzaklaşmak istiyorum Belki bir işe girmeliyim Belkide buralardan çekip gitmeliyim Bir şekilde kendimi t...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/senden-hicbirsey-olmamali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen sensizlik nedir bilir misin?', 'sen-sensizlik-nedir-bilir-misin-sinan-aydindag-x7hgt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '26 aralık 2004

Sen sensizlik nedir bilir misin? 

Bilir misin? her an dirhem dirhem çürümeyi

Taşıya bilir misin? hasretin o ağır yükünü

Söyle taşıya bilir misin? 

Her su içtiğinde,yemek yadiğinde ya da

Uykuya dalıp gittiğinde

Hiç bir tat almadan yaşaya bilir misin? 

Söylesene yaşaya bilir misin? 

Ben gün,her saat,her an bilki

Bunları yaşıyorum

Sensizliğin kanserine tutuldum

Gün geçtikce çürüyorum

Hepsi ile yaşamaya alıştım ama

Gözlerinin ışıltısı olmadan yaşayamıyorum

Be yaşayamıyorum', '26 aralık 2004 Sen sensizlik nedir bilir misin?  Bilir misin? her an dirhem dirhem çürümeyi Taşıya bilir misin? hasretin o ağır yükünü Söyle...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-sensizlik-nedir-bilir-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir kuşluk vakti', 'bir-kusluk-vakti-sinan-aydindag-wi6yt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '28 Aralık 2004

                                                                                                                                   Bir kuşluk vakti dağlardan inen

Bahar esintileriyle geleceğim

Sabah güneş uyandığında

Yollarına kır çicekleri sereceğim

Hüzün,dert keder hiç birisi kalmayacak

Sen bana geldiğinde dünya duracak

Bütün her yer ihtiras ve aşk,aşk kokacak', '28 Aralık 2004                                                                                                                              ...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-kusluk-vakti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar - Ey Aşk -', 'ruzgar-ey-ask-i-sa-sari-fmgtu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Niçin ateşe varır kelebekler

Erlerin erdikleri cihanda ola.

Geminden gem,deminden dem

Kumundan kum tart

Balçığa koy

Ateşlere at, yak bizi

Kelebekler gibi...

Bize ayrılık masalları anlat

Hazin türküler söyle

Katranlara boya, 

Karanlıklara koy

Okyanuslara at, boğ bizi

Yunuslar gibi...

Ey aşk

Elini eteğini çektiğinde şehirlerden

Ve tüm günahlardan

Martılar gibi...

Uğultulu rüzgarlarla salıver bizi...', 'Niçin ateşe varır kelebekler Erlerin erdikleri cihanda ola. Geminden gem,deminden dem Kumundan kum tart Balçığa koy Ateşlere at, yak bizi Ke...', ARRAY['Türk Edebiyatı','Şiir','İsa Sarı']::text[], 8.5, '{"poet":"İsa Sarı","poet_slug":"i-sa-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ruzgar-ey-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyorum-Fethiye', 'usuyorum-fethiye-nazan-i-zmirli-rhnc2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'adsız kuşlar gecenin içinde

karşı   kıyıdan     yükseliyor

yorgunluk   kahkahaları

karanlığı delercesine.

koyda  uyuyan tekneleri titretiyor

ışık   selinin   yakomozları.

ince  bir  gitar özleminden ağlamaklı

yıldızlar kayıyor şovalye adası üzerinde

herşey  seni  anımsatıyor

tek bir dilek.....................sen olan

uyuyan enginin nefes alışlarında

seni arıyorum tuzlu tuzlu..............

seni özlüyorum............................

titriyorum.....................................

sıcak   gecenin   içinde

adsız   kuşlar     öttükçe

sensizliğimden  üşüyorum,üşüyorum,üşüyorum....

Nazan İzmirli

10.09.2004-fethiye', 'adsız kuşlar gecenin içinde karşı   kıyıdan     yükseliyor yorgunluk   kahkahaları karanlığı delercesine. koyda  uyuyan tekneleri titretiyor...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/usuyorum-fethiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne''ye', 'anne-ye-neslihan-i-sler-w9ubj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anne’ye

Yüzüne yılların yorgunlugu yerleşmiş

Gözlerinde yüreğin....

Her çizgide anıların belirmiş

Sözlerinde sevgin....

İlk düştüğümde 

İlk kalp ağrımda hep yanımda

Ağlamaktan gözlerin şişmiş

Ben yatarken hastene koridorlarında

Başım her düştüğünde 

Sadece gözlerinde sevgiyle hep başımda

Bazen zamana yenik ve hayata

Ama her seni kırdıgımda 

İçimde hep bir burukluk var ya

Her hırcınlıgımda

Yinede kucak acarsın ya

Bazen kızıp darılsın aslında

Ama bilirim hiç kıyamazsında

Belki şımarıklığım da bu yüzden

Ne olursa olsun hep yanımdasın ya

Ha unutmadan inatçılığımda senden aslında,

Ne yapayım sıgınacak tek limanım 

Hep sensin başucumda....

Öpülesi ellerin yürekten sevginle

Hiç ama hiç eksilme hayatımdan

Duaların eksilirse yanıbaşımdan

Zaten yetimim birde öksüz yarınlardan

Tek kazancım sensin bu hayattan....

Sevgi bir tüy kadar hafifse 

Eğer bir gün sizede değerse

Şefkat ve sıcaklığı da hissederseniz

Bir anne kucagına hasret ederseniz

Yaşınız başınız kaç olduğu mühüm degil

Zaten hiçbirzaman büyümezsiniz....', 'Anne’ye Yüzüne yılların yorgunlugu yerleşmiş Gözlerinde yüreğin.... Her çizgide anıların belirmiş Sözlerinde sevgin.... İlk düştüğümde  İlk ...', ARRAY['Türk Edebiyatı','Şiir','Neslihan İşler']::text[], 8.5, '{"poet":"Neslihan İşler","poet_slug":"neslihan-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/anne-ye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gün ve Yarın', 'bu-gun-ve-yarin-kadir-soyturk-7f68q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu gün konuşuyorsun

Doğru, yanlış demeden

Hep işine geleni...

Yarın dilin tutulacak

Doğrudan başka bir şey söyleyemiyeceksin

O en yakın, en dost bildiklerin bile

Kurtaramıyacaklar seni!', 'Bu gün konuşuyorsun Doğru, yanlış demeden Hep işine geleni... Yarın dilin tutulacak Doğrudan başka bir şey söyleyemiyeceksin O en yakın, en ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bu-gun-ve-yarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'bende Bilmiyorum', 'bende-bilmiyorum-cetin-ozyurek-n5utd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dökülürse gözünden 

Ansızın gözyaşların unutma

senin andığın kadar

Seni ananda vardır

Sarılmak istersen

Yanındaki yastıkları

İnan onlar bile anar seni

Paylaşır kahrolası yalnızlığını

Kırmadan kırılmadan

İstersen anlatmak içindeki

Duygularını her an beklerim seni

Sevmek kolay kolay ama

Kazanılan sevgi korumak zor

İstemem sevme beni

Dost kalalım ölesiye

Korkuyorum Sevgine

Saip çıkmaktan korkuyorum

Verdiğin sevgiyi yok etmekten

Eğer seviyorsan gerçekten

Söyleme bana sevdiğini

Belli etme o zaman dokunamam sana

Düşünemem seni korkarım 

Kırmaktan İnciltmekten

Eğer Seviyorsan beni

SÖYLEME', 'Dökülürse gözünden  Ansızın gözyaşların unutma senin andığın kadar Seni ananda vardır Sarılmak istersen Yanındaki yastıkları İnan onlar bile...', ARRAY['Türk Edebiyatı','Şiir','Çetin Özyürek']::text[], 8.5, '{"poet":"Çetin Özyürek","poet_slug":"cetin-ozyurek","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bende-bilmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı2', 'aci2-i-brahim-asli2-f2stf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani ilk defa yaparsın diye bir şeyleri

Ellerimde senin istediğin o acıklı yıllar

Hani son defa yaparsın diye bir şeyleri

Adının yazılı olduğu beyaz bir kağıt parçası avuçlarımda....

Hangi kentlerde arasam seni eskimeyen bir yılgınlıksın işte

Kollarımda zamanın  perdeleri gözlerimle açılıyor,gözlerimle kapanıyor. 

Bilmediklerine yaşıyorum şimdi, bildiğini düşünerek.

Burnum akıyor biliyor musun? Yine hasta oluyorum..

Bir tek seninle iyileşiyordum

İnan! 

Bir tek seni düşündükçe var ediyor toprağın üstünde kendini.

Bir de seni düşündükçe seni daha çok seviyor.

Ihlamur kokusunu özlemiştim,senden kalan o kavanozun içinde.

Eğmiş başını penceredeki akşam menekşen,su verdim...

Hani çok severdin ya, karşısına geçip annene dert yanardın.

Odan hala soğuk! 

Son söz savaşımızdan sonra bayağı eskimiş her şey.

	Bu ev sana alışmış, hiçbir şey yokluğundan çalışmıyor.

	Buradan gitme vakti akşam menekşesi.

	Buradan gitme vakit artık her şey yabancı.

	Sen bile eğdin boynunu ya! 

Sensizliğin bıraktığı yılgınlığımın yücelttiği ey aşk! 

Şimdi oradaysan ses ver biçare kuluna.

Adım yazılı engin dehlizlerde, 

Adı yazılı avucum her köşesinde.

Ulaştır sevdiğimi bana, ulaştır beni sevdiğimin yanına.', 'Hani ilk defa yaparsın diye bir şeyleri Ellerimde senin istediğin o acıklı yıllar Hani son defa yaparsın diye bir şeyleri Adının yazılı oldu...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Aslı2']::text[], 8.5, '{"poet":"İbrahim Aslı2","poet_slug":"i-brahim-asli2","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/aci2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeytan Masum', 'seytan-masum-suheyl-turkoglu-6fwnd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şeytana uymak

Fırtınalarda

Üşütüyor beyinleri.

Saldırganlık

Güçsüzleri ezip

Paralarını almak.

İmparator edasıyla

Dünyaya

Meydan okumak.

Demokrasi adına

Yalanlarla

Cinayetler işlemek.

Saldırmak

İnsanların maneviyatına,

Tek düze etmek.

Bütün bu kötülükler

Aklına gelmezdi,

Sen masumsun

Şeytan.', 'Şeytana uymak Fırtınalarda Üşütüyor beyinleri. Saldırganlık Güçsüzleri ezip Paralarını almak. İmparator edasıyla Dünyaya Meydan okumak. Demo...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seytan-masum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlüyor-Fethiye', 'ozluyor-fethiye-nazan-i-zmirli-3dgnl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'üşüyorum.......................

titrek bedenimi..............

kollarında ısıtmak..........

istedim.............................

her  yer karardı...............

kollarını bulamadım.........

sahilde dalgalar..............

kumsalı okşuyor..............

sevişmelerine tanığım....

sensiz sessiz.................

gecenin içinde...............

boynumu saran meltemde

kokunu    alıyorum.............

yıldızlarla bakışıyor............

seni daha..daha...daha çok 

özlüyor..............bekliyorum...

Nazan İzmirli-10.09.2004-fethiye', 'üşüyorum....................... titrek bedenimi.............. kollarında ısıtmak.......... istedim............................. her  yer kar...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ozluyor-fethiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğm günün', 'dogm-gunun-elazigli-mustafa-kaya-rb2k6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bugün benim doğum günüm

daha doğrusu tersinden okunduğunda

aylardan kasım 

tarih oniki..

ben her kasım gelişinde

iki doğum günüm olur sanki

öteki canım için yazarım bir

bir kendim için..

gözükara çıktın

bir başına

bu dünyayı öğreneceğim ben

ipte yürümek olsa da

dedin,

meğer yoluna çökmüş

hurda ilişkiler

ve yılan derisinden çıkan

korkularını besleyen pişmanlıklar..

oysa her gece düşleri

denize inerdi

yosun kokusu ve

martı sesleri

herkesin duygularını taşıyor şehir

kendinden başka

aileye kaçışın özleminde

yüzlerce dua,

depremler yaşayan bedeninde..

uçup gitmiş zaman

bir eski fotoğraf en mutlu günü

güz vurgunu yemiş gönlü

gökyüzüne bakınıp duran..

ve her oniki kasımlar da

bulutlardan medet uman...

bugün doğum günün

tanışabilseydik

kavuşabilseydik

yeni aşkımızı güzelleştirirdik

belki hüzünlenirdik..

sana dokunmak için geldim 

yosun kokusunda

kimse kıskanmasın ..

şafak sökerken indim ve,

şükrediyordun beni sevdiğine

gönlümce geldim sevgilim...gönlümce

oniki kasım doğum gününe....

mustafakaya

12.11.2005 / eyüp

www.mustafakaya.net', 'bugün benim doğum günüm daha doğrusu tersinden okunduğunda aylardan kasım  tarih oniki.. ben her kasım gelişinde iki doğum günüm olur sanki ...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/dogm-gunun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zehirli ırmak', 'zehirli-irmak-elazigli-mustafa-kaya-2xx96', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kalbimin değil

dilimin söyledikleri

zehirli bir ırmak olup

suları durmaz 

içine akmış

gözlerin kan çanağıymış

oysa seninle aynıyız

kır çiçeğim

ebrulim

sevgilim…

Mustafa kaya

12.11.2005

www.mustafakaya.net', 'kalbimin değil dilimin söyledikleri zehirli bir ırmak olup suları durmaz  içine akmış gözlerin kan çanağıymış oysa seninle aynıyız kır çiçeğ...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zehirli-irmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçurum', 'ucurum-elazigli-mustafa-kaya-7hzzf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çıldırtan arzular,

bir güz vurgunu.

bir yaşlı mendil.

göğsünü deliyor, 

sevdan..

uçurumun oldum

içime düşüyorsun

üşüyorsun

seninle üşüyorum..

şuranda bir ağrı

onu düşünüyorum

on iki kasım sabahı

kirpiklerin İstanbul

elini uzat sevgilim

aşkına hasretim

sevişlerine geldim…

Mustafa kaya

12.11.2005 / İstanbul

www.mustafakaya.net', 'çıldırtan arzular, bir güz vurgunu. bir yaşlı mendil. göğsünü deliyor,  sevdan.. uçurumun oldum içime düşüyorsun üşüyorsun seninle üşüyorum....', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ucurum-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensedim', 'sensedim-rahim-tas-f526z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sensedim 

Bugün sensedim 

Aniden 

Bir lokma oldu ağzımda 

Titreyen yüreğim 

Büyüdü bebekleri gözlerimin 

Daha önce de sensemiştim 

Ama bugün bir başkaydı sensemem 

Yoksa bir sıkıntın mı var? 

Senden başka kimseyi 

Düşünmüyorum ki ben 

Bugün sensedim 

Bir kanarya çınlattı kulaklarımı 

Soğuk kanlar aktı sıcak nefesimden 

Şakaklarımın sağanakları 

Avuçlarımda birikti 

Daha önce de sensemiştim 

Ama bugün bir başkaydı sensemem 

Yoksa geçmedi mi ağrıların? 

Senden başka kimseyi 

Merak etmiyorum ki ben 

Bugün sensedim 

Gözlerinin yeşilindeki pınarlar 

Serinletti yanan yüreğimi 

Güzel yüzünün çerçevesi 

Yaldızlı saçlarının ışıltısı 

Aydınlattı usumun zifirlerini 

Daha önce de sensemiştim 

Ama bugün bir başkaydı sensemem 

Yoksa yarın da mı gelmeyeceksin? 

Senden başka kimseyi 

Özlemiyorum ki ben

Bugün sensedim 

Sana geldim 

Sevdiğim 

Senden başka kimseyi 

Sevmiyorum ki ben…

12 Kasım 2005

Rahim TAŞ', 'Sensedim  Bugün sensedim  Aniden  Bir lokma oldu ağzımda  Titreyen yüreğim  Büyüdü bebekleri gözlerimin  Daha önce de sensemiştim  Ama bugün...', ARRAY['Türk Edebiyatı','Şiir','Rahim TAŞ']::text[], 8.5, '{"poet":"Rahim TAŞ","poet_slug":"rahim-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sensedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Solgun yüz', 'solgun-yuz-elazigli-mustafa-kaya-j0xjy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni çok korkutuyor

Uykular 

Rüyasız gece

Şafakları geç açan

Karanlık  gök

Dört bir tarafı yanlızlık

Uzaklık..uzaklık..

Kireç kokulu

Kerpiçten bir oda

Kimse duymaz sesimi

Hayatım bu olsun

Bir başıma..bir başıma..

Solgun bir yüzüm

Ve hiç solmasın seni gören

İki gözüm..



Mustafa kaya

12.11.2005

www.mustafakaya.net', 'Beni çok korkutuyor Uykular  Rüyasız gece Şafakları geç açan Karanlık  gök Dört bir tarafı yanlızlık Uzaklık..uzaklık.. Kireç kokulu Kerpiçt...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/solgun-yuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Modern Ağaç', 'modern-agac-kamil-at-f0ahn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşte sevda dalda sallanıyor

Yolunmuş maymun kıllanıyor

Başuçuna cani yollanıyor

Kuru sehpa bunu bilmez.

Hayvan insana fena çıldırır

Ağacın altında neler kıldırır

Beyinsiz bağnaz bize saldırır

Kuru sehpa onu bilmez.

Hayat yolunu bulmuş akışta

Cahilin iyisi bilinirmi bakışta

Gerçekler amansız yokuşta

Kuru sehpa konu bilmez

Yorula yorula yaptık ikibini

Bardağa katıp içtiler kinini

Satılmış Tv''de çektiler klibini

Kuru sehpa şanı bilmez.

Modern zamana süngü sokar

Mıhları dipsiz yerlere çakar

Ulan burunsuzlar kan kokar

Kuru sehpa kanı bilmez.

Son bakışlar bize bakar

Ateşte diri insan yakar

Sinsi olmasalar biraz sıkar

Kuru sehpa sonu bilmez.

Kamil At''a mehtap doğar

Bağnazlar yerine ancak sığar

Yiğitler hergün havadan yağar

Asidir pislik kanunu bilmez.', 'İşte sevda dalda sallanıyor Yolunmuş maymun kıllanıyor Başuçuna cani yollanıyor Kuru sehpa bunu bilmez. Hayvan insana fena çıldırır Ağacın a...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/modern-agac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesini duyuyor-Fethiye', 'sesini-duyuyor-fethiye-nazan-i-zmirli-sfbfu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'adsız kuşlarla.......................

denizle kumsalın sevişmesi

sensiz     gecenin     sessiz 

nefes alışlarıyla sabahladım

sessiz  sakin  sahilde koşmak

belkide  sana kavuşmak istedim

yürüdüm, yürüdüm, yürüdüm........

ıssızlığın,sessizliğin,ürkütücülüğün

sesini duyana dek yürüdüm............

ve sonra.............................................

bakire kıyılarla

bakir   mavinin

kaçamak sessiz kalışlarını yaşıyorum

gecenin titrekliğini hissettiren  çakıllarda

yürüyen   çıplak   ayaklarım

yüreğimin

güneşin

dalgaların

taşların

ve bana her an seni hatırlatan

bir çok  özgür   kuşların

sesini duyuyor............................

mutlu oluyor................................

gülümsüyorum............................', 'adsız kuşlarla....................... denizle kumsalın sevişmesi sensiz     gecenin     sessiz  nefes alışlarıyla sabahladım sessiz  sakin  ...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sesini-duyuyor-fethiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Yüreğimden', 'gitme-yuregimden-i-lknur-cekici-48sah', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gitme yüreğimden sevgili

Silemem izlerini

Zamansız yarınlarda solurum dertlerini

Gitme yüreğimden sevgili

Ezilirim hasretinle

Ulaşamam engin mavilere

Gitme yüreğimden sevgili

Kalırım karanlığa

Erişmez gecelerim tozpembe sabahlara

Parmak uçlarımda bile

Dolaşırken deli sevdan

Saçlarımın karasına

Gizlenmişken gönül yaram

Gitme yüreğimden sevgili

Düşürme gözümden sevmeleri

Yorma zamansız yeşeren kırılgan güvenimi', 'Gitme yüreğimden sevgili Silemem izlerini Zamansız yarınlarda solurum dertlerini Gitme yüreğimden sevgili Ezilirim hasretinle Ulaşamam engin...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gitme-yuregimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazlumun Allahı var', 'mazlumun-allahi-var-kadir-soyturk-xfyah', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zalimin zulmune, trene bakar gibi baksanız da

Sevinçten sarhoş olup, kınalar yaksanız da.....

Damlalar birikiyor, bir gün olacak deniz

Akan gözyaşlarında,boğulacak sizsiniz!', 'Zalimin zulmune, trene bakar gibi baksanız da Sevinçten sarhoş olup, kınalar yaksanız da..... Damlalar birikiyor, bir gün olacak deniz Akan ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mazlumun-allahi-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim', 'ogretmenim-i-shak-ozlu-yrxa6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün küçüğüm,

Yirmi yıl sonra büyük.

Okulun önemini anlat bana,

Yıllarım feda olsun sana.

Aile bağlarını anlat,

Anlat ki; güçlü bir ailem olsun,

Ülkemi anlat bana,

Sevğisi yüreğime dolsun.

Milletimi anlat bana,

Geçmişim geleceğime ayna tutsun.

Nedir Bayrak,neden Cumhuriyet? 

Kimdir ATATÜRK,niçin Hürriyet,

Bana bunları bir bir öğret,

Öğretki bileyim.

Dünyamız bir ateş topu,

Her yerde savaş ve gözyaşı,

Çocuklar ölüyor,

Anneler ağlıyor,

Babalar dönmüyor,

Neden öğretmenim neden? 

İnsanlığı anlat bana,

Sevmeyi öğret bana,

Suç nedir,ceza nedir? 

Adalet kimler içindir? 

Neden yaratıldım? 

Yaşam amacım nedir? 

Bilmiyorum öğretmenim,

Sana geldim.

Ali topu tut diyorsun ya,

Top uğruna eziliyordum,

Binecek Atımda kalmadı,

Dostluk kuracak arkadaşımda.

Gözlerim görmüyor,

Her yer karanlık.

Bir ışık aradım,

Sen çıktın karşıma.

Sen bir Güneş,

Ben ışığa hasret yıldız,

Aydınlat dünyamı,

Aydınlatalım dünyamızı.

Bugün belki küçüğüm,

Yirmi yıl sonra büyük.

Not:Tüm enerjilerini ve birikimlerini son kırıntısına kadar öğrencilerine aktaran eli öpülesi öğretmenlerimize ithaf olunur.', 'Bugün küçüğüm, Yirmi yıl sonra büyük. Okulun önemini anlat bana, Yıllarım feda olsun sana. Aile bağlarını anlat, Anlat ki; güçlü bir ailem o...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/ogretmenim-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecesel Su', 'gecesel-su-i-smail-aksoy-7ym8l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'At gözlü bir gece titrer geceleri,

su gözlü bir gecen var senin uyuyan toprakta

titreyen at gözlerinde,

sır dolu sulardan yapılı gözlerinde.

Gölge suyundan gözler,

kuyu suyundan gözler,

düş suyundan gözler.

Sessizlik ve yalnızlık,

ayın taşıdığı iki küçük hayvan,

içerler bu gözlerden,

içerler bu sulardan.

Gözlerini açarsan,

açar gece yosun kapılarını,

açar kendini suyun gizli ülkesine

ve gecenin ortasından çağlar.

Ve kaparsan gözlerini,

bir ırmak doldurur içini,

kör, suskun bir dalga atılır ileri

ve karartır seni:

nemlendirir gece ruhundaki kıyıları.       

Octavio Paz

Türkçe’ye çeviren: İsmail Aksoy', 'At gözlü bir gece titrer geceleri, su gözlü bir gecen var senin uyuyan toprakta titreyen at gözlerinde, sır dolu sulardan yapılı gözlerinde....', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gecesel-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Gövde', 'i-ki-govde-i-smail-aksoy-dcsq3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İki gövde yüzyüze

bazan iki dalgadır

ve gece bir okyanustur.

İki gövde yüzyüze

bazan iki taştır

ve gece bir çöldür.

İki gövde yüzyüze

bazan iki köktür

geceyle sarmalanmış.

İki gövde yüzyüze

bazan iki bıçaktır

ve gece bir anlık parıltı.

İki gövde yüzyüze

düşen iki yıldızdır

boş ve yalnız bir gökte.

Octavio Paz

Türkçe’ye çeviren: İsmail Aksoy', 'İki gövde yüzyüze bazan iki dalgadır ve gece bir okyanustur. İki gövde yüzyüze bazan iki taştır ve gece bir çöldür. İki gövde yüzyüze bazan ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/iki-govde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Dünyanın Akıl Ermez İşine', 'garip-dunyanin-akil-ermez-i-sine-atilla-gozukucuk-v1wfe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gelirsin şu yalan dünyaya, ölüm var, acı var,

Kimi padişah olmuş, kimi kral olmuş; başında tacı var,

Çekersin hayatın çilesini; derdi var, sancısı var,

Şu garip dünyanın, akıl ermez halına.

Bazen gülüp geçmek istersin; dünyan binbir türlü halına,

Bazen de bakarsın; ne çileler gelir kulun başına,

Bazen de sevdadan yanarsın, yârin aşkına,

Şu garip dünyada neler gelir, kulun başına.

Gün olur; düşersin derde, derman ararsın,

Gün olur; düşersin gurbete, sılayı sorarsın,

Gün olur; sevda çekersin, aşk ataşına yanarsın,

Şu garip dünyanın, akıl ermez işine.

Hayata küsersin, canından bezersin,

Düşersin yollara; diyar, gurbet gezersin,

Düz ovada gitsen de yolundan azarsın,

Şu garip dünya neler eyler, kulun başına.

Şu garip dünyada; kimi güler, kimi ağlar,

Kimisi çok umutlanır, kadere bel bağlar,

Kimisi coşar, sevinir; sel olur çağlar,

Kimi fani dünyada, yorulur birgün.

Yaşarsın, yaşarsın hayatın sonuna gelirsin birgün,

Ömrün tamam olur, vaden dolar, ölürsün birgün,

Konarsın musallaya, namazın kılınır birgün,

Ömrüyün hesabı, sorulur birgün.

12.11.2005', 'Gelirsin şu yalan dünyaya, ölüm var, acı var, Kimi padişah olmuş, kimi kral olmuş; başında tacı var, Çekersin hayatın çilesini; derdi var, s...', ARRAY['Türk Edebiyatı','Şiir','Atilla Gözüküçük']::text[], 8.5, '{"poet":"Atilla Gözüküçük","poet_slug":"atilla-gozukucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/garip-dunyanin-akil-ermez-isine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Ötesinde', 'sevginin-otesinde-i-smail-aksoy-54owa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her şey tehdit ediyor bizi:

zaman canlı kırıntılarda ayırır gibi

geleceğimle

şu anda olduğum şeyi,

palayla yılan gibi; 

bilinç, berrak, dolanır durur bir o yana bir öte yana,

bakış körleşmiş kendi dikbakışına bakmaktan; 

sözcükler, gri eldivenler, beyintozu çimlerin üstünde,

suda ve deride; 

adlarımız, Sen ve Ben arasında dolaşır,

çökertemez boşluğun duvarlarını hiç bir trombon.

Ne parçalanmış resimlerinin köyüyle düş

ne de yalvaçsı köpüğüyle sayıklayış

ne de dişleri ve pençeleriyle sevgi yeterli bize.

Kendi ötemizde, olmak ile bir yerde olmak arasındaki sınırda

çağırır bizi hayattan daha canlı bir hayat.

Soluk alır dışarda gece ve yayar kendini,

kocaman sıcak yapraklarıyla sarhoş,

birbirleriyle savaşan aynalarla:

yemişlerle, pencelerle, gözlerle, yapraklarla,

parıldayan sırtlarla,

başka gövdelerin arasından kendine yol açan gövdelerle.

Uzan buraya bütün bu köpüğün kıyısına,

kendini bırakırcasına, bilinçsiz, bütün bu hayatın kıyısına; 

yayıl, ey soluk alan beyazlık,

bırak işiteyim yürek çırpınışını, ey dağılmış yıldız,

ah sen çam, ah şafağın kıyısına doğru

teraziden ağır gelen ekmek,

sen bu zamanla sınırsız başka bir zaman arasındaki kanın molası.          

Octavio Paz

Türkçe’ye çeviren: İsmail Aksoy', 'Her şey tehdit ediyor bizi: zaman canlı kırıntılarda ayırır gibi geleceğimle şu anda olduğum şeyi, palayla yılan gibi;  bilinç, berrak, dola...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sevginin-otesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tersine Çevrilebilir', 'tersine-cevrilebilir-i-smail-aksoy-juzkt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzayda

ben

kendi içimdeyim

uzay

dışımda benim

uzay

hiç bir yerde

ben

kendi dışımdayım

uzayda

içinde

uzaydır

onun dışı

hiç bir yer

ben

uzaydayım

vesaire

Octavio Paz

Türkçe’ye çeviren: İsmail Aksoy', 'Uzayda ben kendi içimdeyim uzay dışımda benim uzay hiç bir yerde ben kendi dışımdayım uzayda içinde uzaydır onun dışı hiç bir yer ben uzayda...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/tersine-cevrilebilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köy', 'koy-i-smail-aksoy-p3o04', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Taşlar zamandır

Rüzgâr

rüzgârın yüzyılları

Ağaçlar zamandır

insanlar taştır

Rüzgâr

döner kendisine ve batar

taş günün içine

Su yok burada gözlerinin parıltısı için

Octavio Paz

Türkçe’ye çeviren: İsmail Aksoy', 'Taşlar zamandır Rüzgâr rüzgârın yüzyılları Ağaçlar zamandır insanlar taştır Rüzgâr döner kendisine ve batar taş günün içine Su yok burada gö...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/koy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Kimsiz Nerede', 'kim-kimsiz-nerede-i-smail-aksoy-cr3ly', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yok bir ruh

bu ağaçların arasında

Ve ben

bilmiyorum nereye gittiğimi

Octavio Paz

Türkçe’ye çeviren: İsmail Aksoy', 'Yok bir ruh bu ağaçların arasında Ve ben bilmiyorum nereye gittiğimi Octavio Paz Türkçe’ye çeviren: İsmail Aksoy...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kim-kimsiz-nerede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaşlık (Octavio Paz)', 'arkadaslik-octavio-paz-i-smail-aksoy-pfevr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beklenen saat bu

masadan düşen

sonsuzca

lambanın dağınık saçı

Gece döndürür pencereyi enginliğe

Kimse yok burada

isimsiz görüntü kuşatır beni.

Octavio Paz

Türkçe’ye çeviren: İsmail Aksoy', 'Beklenen saat bu masadan düşen sonsuzca lambanın dağınık saçı Gece döndürür pencereyi enginliğe Kimse yok burada isimsiz görüntü kuşatır ben...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/arkadaslik-octavio-paz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görüntü', 'goruntu-i-smail-aksoy-1q5mm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsan toz ise eğer

düzlükten geçen ne varsa

insandır

Octavio Paz

Türkçe’ye çeviren: İsmail Aksoy', 'İnsan toz ise eğer düzlükten geçen ne varsa insandır Octavio Paz Türkçe’ye çeviren: İsmail Aksoy...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/goruntu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manzara', 'manzara-i-smail-aksoy-05gsx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaya ve uçurum,

daha çok zaman kayadan, bu

zamansız madde.

Yaranın zarı içinden

düşer kımıltısız

sonsuz bakire su.

Enginlik dinlenir burada,

kaya üstünde kaya

kayalar üstünde hava.

Dünyanın bildirisi

olduğu gibi: bir güneş

kımıltısız, cehennemde.

Başdönmesinin dengesi:

kayalığın ağırlığı

gölgelerimizden fazla değil.

Octavio Paz

Türkçe’ye çeviren: İsmail Aksoy', 'Kaya ve uçurum, daha çok zaman kayadan, bu zamansız madde. Yaranın zarı içinden düşer kımıltısız sonsuz bakire su. Enginlik dinlenir burada,...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/manzara-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereye?', 'nereye-kamil-at-pdr2l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sellerin içinde bazen hayatta azar

Çaba vereyim derken şeklini bozar

Bedende organizma rotasını çizer

Uzun gider de fakat nereye? .

Dünya böyle oluşmuş çamurdan

Çölleri yoksun kalmış yağmurdan

Nice menüler yapılmış hamurdan

Zalim yer beyni sakat nereye? .

Kiminin yaşamı sadece rollarıdır

Mazlumlara uzanan kötü kollarıdır

İnsanı ağılayan zehirli mallarıdır

Gereksiz yere felaket nereye? .

Galapagos adaları''nın ispinoz kuşu

Kurnaz kimisi çok çürük duruşu

Kamil At dayanılmazdır pis kokusu

Suçu azamidir akat nereye? .', 'Sellerin içinde bazen hayatta azar Çaba vereyim derken şeklini bozar Bedende organizma rotasını çizer Uzun gider de fakat nereye? . Dünya bö...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nereye-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Kasım', '10-kasim-i-shak-ozlu-3j5gz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Atam,

Bugün 10 kasım.

Çocukların yüreklerinde ebedi yaşıyorsun,

Fikirlerinle çağın beyinlerini aşıyorsun.

Pahalıya aldıklarını ucuza satıyoruz,

Satsakta mirasınla medeniyete taşıyorsun.

Doğu cephesinde değişen bir şey yok.

Şark kurnazlığı her zamankinden çok.

Dost başa düşman ayağa misali,

Görmüşsündür yüzleri gözler zehirli ok.

Nur içinde yat.', 'Atam, Bugün 10 kasım. Çocukların yüreklerinde ebedi yaşıyorsun, Fikirlerinle çağın beyinlerini aşıyorsun. Pahalıya aldıklarını ucuza satıyor...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/10-kasim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mola', 'mola-i-smail-aksoy-85ric', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Pierre Reverdy’nin anısına

Geldiler:

bir kaç kuş

ve siyah bir düşünce.

Ağaçların mırıltısı,

trenlerin ve motorların mırıltısı,

şu an geliyor mu gidiyor mu? 

Gülüşün sessizliği

deler inleyişi ve gülüşü,

batırır mızrağını

derine kayaların kayasında çığlığa.

Güneş-yürek, çarpan kaya,

meyveye dönüşen kan kaya:

yaralar acısız açılır,

benzesen hayatım akar gider.

Octavio Paz

Türkçe’ye çeviren: İsmail Aksoy', 'Pierre Reverdy’nin anısına Geldiler: bir kaç kuş ve siyah bir düşünce. Ağaçların mırıltısı, trenlerin ve motorların mırıltısı, şu an geliyor...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mola-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özdeşlik', 'ozdeslik-i-smail-aksoy-v2s76', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Avluda bağırıyor acı acı bir kuş,

madeni bir para kasada.

Tüyleri biraz hava,

ve yok oluyor ani bir parıltıda.

Belki hiç kuş yok

ne de benden başka kimse avluda.

Octavio Paz

Türkçe’ye çeviren: İsmail Aksoy', 'Avluda bağırıyor acı acı bir kuş, madeni bir para kasada. Tüyleri biraz hava, ve yok oluyor ani bir parıltıda. Belki hiç kuş yok ne de bende...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozdeslik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oto Gar', 'oto-gar-nazan-i-zmirli-nvb3q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'akşam   alacası     düştü

gönlüme    bedenime

durgunlaştım, hırçınlaştım 

o an nedensizce

buldum kendimi

oto gar peronlarında yine

insanlar  pür  telaş

koşuşturuyorlar  bir ileri bir geriye

kimi   kahkahalar  atıyor

biten  ayrılıklara

kimi  karşı  koyamıyor

iki  gözü  iki  çeşme

başlayan sıla rüzgarlarına

kimi  hüzünlü , dalgın

kaldıramadığı gönül yükü altında

omuzlar birleşmiş çarpan  kalbini

saklar gibi

izliyorum olanı biteni olağanmış gibi

ben,neden buradayım,dev kolonlara sırtım dayalı

bir yolcumu beklediğim,yoksa kavuşmakmı istediğim.

ard arda dolup boşalıyor peronlar

an be an değişiyor suratlar

gecenin soğukluğunu hissediyorum

yüzümde,   ellerimde,   bedenimde

dizlerim çözülüyor,çöküyorum

yüreğimle dolu sırt çantamın üzerine

bir ince sızı düşüyor içime

beklesemde gelmeyecek sabah güneşlerine

gitmekten korkuyorum, sabah güneş

görmeyen o şehirlere

HEY! KAPTAN; diye haykırıyorum

son bir dakika sonra kalkacak

otobüsün  ardından..................

yolculuk yapacak gücüm kalmadı

şu sırt çantamı götürürmüsün

yare................................................

Nazan İzmirli-ant

12.10.204  / 1.11.2005', 'akşam   alacası     düştü gönlüme    bedenime durgunlaştım, hırçınlaştım  o an nedensizce buldum kendimi oto gar peronlarında yine insanlar ...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/oto-gar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız', 'kiz-i-smail-aksoy-yg1d3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Direnen öğleden sonralarıyla

toplayıcı gece arasında

genç bir kızın dik bakışı

Bırakıp gidiyor defterini ve yazmayı,

bütün varlığı tamamlanmış iki gözde.

Duvarda iptal ediyor ışık kendini.

Sonunu mu görür yoksa başlangıcını mı? 

Bir şey görmediğini söyleyecektir.

Berrak olgunlaşmadı daha.

Ne gördüğünü bilmeyecek asla.

Octavio Paz

Türkçe’ye çeviren: İsmail Aksoy', 'Direnen öğleden sonralarıyla toplayıcı gece arasında genç bir kızın dik bakışı Bırakıp gidiyor defterini ve yazmayı, bütün varlığı tamamlanm...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kiz-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kesinlik', 'kesinlik-i-smail-aksoy-6c7b9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eğer gerçekse beyaz

ışık su lambadan, gerçektir

yazan el, gerçek mi

yazdığıma bakan gözler? 

Bir sözcükten ötekine

kaybolur söylediğim.

Biliyorum yaşadığımı

iki parantez arasında

Octavio Paz

Türkçe’ye çeviren: İsmail Aksoy

Çevirenin notu: Bu çeviri Behçet Necatigil’in anısına adanmıştır.', 'Eğer gerçekse beyaz ışık su lambadan, gerçektir yazan el, gerçek mi yazdığıma bakan gözler?  Bir sözcükten ötekine kaybolur söylediğim. Bili...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kesinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaya', 'yaya-i-smail-aksoy-0qyrz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yürüyordu kalabalığın arasında

Sebastó bulvarında

düşünerek bir şeyler.

Kırmızı ışık durdurdu O’nu.

Baktı yukarı:

üzerinde

boz damların, gümüş

bir balık uçuyordu

kahverengi kuşların arasında.

Yeşil ışık yandı.

Caddeyi geçerken merak etti

ne düşünmekte olduğunu.

Octavio Paz

Türkçe’ye çeviren: İsmail Aksoy', 'Yürüyordu kalabalığın arasında Sebastó bulvarında düşünerek bir şeyler. Kırmızı ışık durdurdu O’nu. Baktı yukarı: üzerinde boz damların, güm...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burada (Octavio Paz)', 'burada-octavio-paz-i-smail-aksoy-z29jg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adımlarım bu cadde boyunca

yankılanır

başka bir caddede

ki işitirim

adımlarımı

geçerken bu cadde boyunca

ki

Yalnız sis gerçektir                  

Octavio Paz

Türkçe’ye çeviren: İsmail Aksoy', 'Adımlarım bu cadde boyunca yankılanır başka bir caddede ki işitirim adımlarımı geçerken bu cadde boyunca ki Yalnız sis gerçektir            ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/burada-octavio-paz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şafak (Octavio Paz)', 'safak-octavio-paz-i-smail-aksoy-bxwij', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Soğuk hızlı eller

çeker geri teker teker

karanlığın sargılarını

açarım gözlerimi

hâlâ

yaşıyorum

ortasında

henüz taze bir yaranın.

Octavio Paz

Çeviren: İsmail H. Aksoy', 'Soğuk hızlı eller çeker geri teker teker karanlığın sargılarını açarım gözlerimi hâlâ yaşıyorum ortasında henüz taze bir yaranın. Octavio Pa...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/safak-octavio-paz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahçedeki Dinleti (Octavio Paz)', 'bahcedeki-dinleti-octavio-paz-i-smail-aksoy-qd4pe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(Vina ve Mridangam)

Carmen Figueroa de Meyer için

Yağmur yağdı.

Saat olağanüstü bir gözdür.

İçine girer çıkarız yansımalar olarak.

Müziğin ırmağı

girer kanıma.

Beden dersem, rüzgâr der,

Dünya dersem, der ki nerde? 

Açılır dünya, çift katlı çiçek gibi:

gelmenin hüznü,

ve burada olmanın

neşesi

Kendi merkezimde yitirdim yolumu.

Octavio Paz

Çeviren: İsmail Haydar Aksoy', '(Vina ve Mridangam) Carmen Figueroa de Meyer için Yağmur yağdı. Saat olağanüstü bir gözdür. İçine girer çıkarız yansımalar olarak. Müziğin ı...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bahcedeki-dinleti-octavio-paz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefes Alış', 'nefes-alis-i-smail-aksoy-jlo0d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1

Beyaz günün gölgeleri

gözlerime karşı. Gördüğüm

beyaz yalnızca:

beyaz saat, ruh bağımsız

arzudan, saatten.

Usul suların sessizliği,

beyaz saat, açık gözlerin körlüğü.

çak çakmaktaşını, yak, bellek,

saate ve anafora karşı.

Bellek, yüzen alev.

2

Bağımsız bedenden, arzudan

bağımsız, geri dönüyorum arzuya, dönüyorum

bedeninin belleğine. Dönüyorum geriye.

Ve bedenin belleğimde yanıyor,

belleğim yanıyor bedeninde.

                            

Bir tanrı bedeniydi yanan

tanrıydı o beden ve yarattı tanrıyı beden

ve şimdi, yalnızdır, başka bedenlerden sadece

bağımsızlaşmış bir bedenin belleği sadece:

bedenin kemiklerimin belleği.

Güneş-orağın gölgesi fırlatıyor Güneş-gölgeyi

kederli kuyumun üstünden

çözüyor düğümlü ekinleri arzunun dibinden

tutuşturmaz bu sayrı yüreği

Ne ki parçalanmış bellek yüzer

hiçliğin doğum kaynaklarından

doğumun kaynaklarından

yüzer akıntıya ve yetkilere karşı

yüzer hiç’e doğru

suyun zaafı

dört fosforlu suyun dili

Paskalya’nın yedinci pazarının dünyasız sözcükleri

Farkında ol düşünmeden farkında olmanın

düşünce geri fırlatır belleği kendiliğinden

Gerisi bir avuç gösteriş

Octavio Paz

Türkçe’ye çeviren: İsmail Aksoy', '1 Beyaz günün gölgeleri gözlerime karşı. Gördüğüm beyaz yalnızca: beyaz saat, ruh bağımsız arzudan, saatten. Usul suların sessizliği, beyaz ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/nefes-alis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin Kez Öldüm Sevdanda', 'bin-kez-oldum-sevdanda-burhanettin-akdag-ttze9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Alnıma bir kurşun sıksalar da vurulsam

Bu kadar acı veremezdi hiçbir şey, inan

Ama, sen öylesine vurdun ki beni, acımadan

Ta kalbimden, can evimden, serildim boylu boyunca…

Koymadı hiçbir şey bana bu kadar

Sensizliğin yalnızlığına, mahkum ettiğinde beni

Tutmadın uzattığım elimi, bıraktın zalimce

Yolladın gizemli boşluğuna, sonsuzluğun…

Dert etmedim açlığını, yokluğunu hiçbir şeyin 

Issız çöllerde de kalsam, yanmazdım böylesine

Mahrum ettin beni sevginden, saygısızca

Esirgedin bir gülücüğü, tebessümü, kaçtın…

Sevemedin ki hiçbir zaman beni, ben gibi

Ne yürekten, ne gönülden, ne de içten, ölümüne

Buruşturup attın kağıt parçası gibi, umarsızca

Yıktın hayallerimizi, yaşadıklarımızı, yokettin...

Bin kez öldüm sana sevdamda, gülüm

Acımadın, açmadın ki sevgi kapılarını bana

Kardelenler gibi fışkırdım da bağrından

Kapattın yüreğini, koparttın filizleri, öldürdün...

Terkettin beni, hayallerimi, düşünmeden

Yandım, eridim, yok oldum günlerde, aylarda

Tek bir buseye hasretliğim varken, aşkında

Yaktı beni sensizliğin, yaraladı derinden, tükendim...

Bu nasıl sevdalıktır, anlayamadım gülüm

Sevmediğine mi yansam, yoksa boşverdiğine mi? 

Var olmuşken benim tenimde, gittin yaban ellere

Yırtarcasına perdeyi,ardına bakmadan, düşünmeden…

Sen! Sonsuzlukta sallanan, ihanetsin

Vur ama, dinle son bir kez, sonra git istersen

Yok etmeden, tüketmeden herşeyi, vakit varken

Sonlandırma, yıkma umut kalesini, temelinden…

Bu mudur ki adaleti senin aşkının? 

Sevdanın, yüreklerde sürüklenmesi, parça parça

Aşık olmak mıydı sana, tek suçum burada? 

Neden anlamadın, kayboldun ufkumdan, ağır ağr...

Silmedin gözyaşımı, okşamadın hüznümü hiç

Daraldım, ufaldım, nefessiz koşularında aşkının

Son bir kez, yalnızca bir kez olsun, öp beni ne olur

Vazgeç, ama hiç unutma gönlümdeki sana hicranımı…

Bin kez öldüm sevdanda, yiğitçe, adam gibi

Hep mavi soludum aşkını,indirmedim semalardan

İstemesen de, vermesen de bir umut kırıntısını, kalbime

Sevdim seni, şiir gibi dizelerde, ölümüne, vazgeçilmez...

(12.11.2005)', 'Alnıma bir kurşun sıksalar da vurulsam Bu kadar acı veremezdi hiçbir şey, inan Ama, sen öylesine vurdun ki beni, acımadan Ta kalbimden, can ...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/bin-kez-oldum-sevdanda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefretle Beslenen', 'nefretle-beslenen-ahmet-ozturk-00yxo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nefretim güzellikle beslenir 

Doğruyla yolunu şaşar

Şakaklarım kanla yoğrulur

Nefretimle beslenir

İki arayı, bir dereyi bulamam 

Bulduğuma yürek koyamam

Neresinden bakarsak bakalım 

İki dirhem, bir çekirdek  kalırım

Sevgi kuşatılmış bir kuş kafesi olur

Mermi yağar, hırs yağar, bülbül ağlar

Ötesi yoktur, nefretle beslenir

(Ekim 2005)', 'Nefretim güzellikle beslenir  Doğruyla yolunu şaşar Şakaklarım kanla yoğrulur Nefretimle beslenir İki arayı, bir dereyi bulamam  Bulduğuma y...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nefretle-beslenen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayşe Ana', 'ayse-ana-akin-akca-994q2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Genel geçer; atmasını çok gördük 

Militer bürokrat askerin, dayak eve dönünce. 

Oysa eğitime ihtiyacı yok, olmamalı siyasetin; 

İnanacak Atatürk’ü olduğu gibi orduda askerin. 

Ayşe Özgün dedi, 

“bir gece”; 

ama kaç sene öncesi var 

Kim bilir … 

“Doğa Ana” diyen biz tabiata 

Ne farkımız var Katrina, 

Rita, 

Çakmaktaş Wilma … 

Ama öyle Türk işte, 

Ölü toprağı var üzerinde Doğa Ana. 

Der ki, “Ben sindirildim” 

Hemen sonraysa bırakılır eklemek zorunda; 

Ayetler değil, 

Hadislere kurban yalan yanlış gelen hutbelerle 

(kısmetli akrabalığından çok 

hısımlık kaderciliği ile)

“Ne yapalım, 

hayat böyleymiş” kurbanlığıyla. 

Doğa Ana, ölü toprak borcuna; 

''ben hakettim'' asla diyemez! 

Beyaz güvercin başörtülü ninelerimize 

bağlayamayacaklar asla, 

Meksika''da mor türban kısvesi. 

Gene de ve yani, 

Hep kahraman köşe bucak, 

Sorumlucasına evde uyumlu. 

Çok kişi algılayamaz bu gücü; 

Çok yerde, çok kişide, 

(ortaya çıkmanız zamanı, 

on yılda on beş milyon genç!)

Otuz milyonun ellerindeyse 

Türkiye’nin geleceği. 

Mümtaz-sığıntı ana gündem ziyade, 

Atatürk’ün top taşıyan kadınlarında hikaye, 

sırtlarında... 

Karakucak güreşi

Şansa bırakılamaz bundan böyle.

- 

Ayşe Özgün ve Türk kadınına 

http://www.geocities.com/edipayvaz/siirler/ataturk_siirleri/onuncu_yil_marsi.html 

not: Meksika''da mor rengi, ölümle anlamlandırılır 

doğaçlama', 'Genel geçer; atmasını çok gördük  Militer bürokrat askerin, dayak eve dönünce.  Oysa eğitime ihtiyacı yok, olmamalı siyasetin;  İnanacak Ata...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ayse-ana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkıp Gittin İşte', 'cikip-gittin-i-ste-deger-ulas-turan-d1r02', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çıkıp gittin aniden, 

Bile bile sessizliğin seni buradan almasını 

Denedin yinede konuşmayı 

Sessizliğinle bırakıp gittin, 

Kulaklarımda tanıdık bir ezgi. 

Yalnızlık çok da kötü değil, 

Ama bilmediğin biriyse sendeki anlamsızlık 

Kötü oluyor zaman sessizlikle örtülüyorsa, 

Daha kötüsüyse bir yabancısın uzaklıkların içinde, 

Ama hiçte öyle gelmiyorsun. 

Anlaşılmaz bir duygu bu sen uzaksın sen bilinmezlik... 

Daha dün tanıştığım bir kadına tanışmadan el sürdüm 

Ellerim tutkuya dokundu, 

Ve çıkıp gittim sabahın köründe 

Kör olan bendim yine.. 

Tanımak bu değildi, 

Tanımak için sevişmek yetmiyordu 

Tanışmak için sahte sözcükler, 

Aşk başka bir şeydi, tanıyordum aşkı 

Bendeki sevgiyle avunan bir aciz değildi aşk. 

Aşk sesinde arandığım sessizliğine razılığımdı, 

Garip tesadüflerin insanı şaşırtmasıydı, hislerin karmaşalığıydı 

Ne olduğunu görmek isteğin bir İngiliz sokağıydı 

Sevmeden o ülkeyi o ülkenin içinde Jules Verne masalıydı

Sen olmayacak bir kavuşmasın, 

Bende olmayacak olan bir şarkı yazıyorum kendime 

Bilmediğim bir dilde, bilmediğin adreslerin içinde 

Ben seni yanlış anlamış olmak ihtimalindeyim 

Yanlış anlaşılmak belki de. 

Bu zamanda iyi insan yanlış anlaşılır, 

Bu zamanda duygusunu cebinde değil; başının üstünde taşıyan...', 'Çıkıp gittin aniden,  Bile bile sessizliğin seni buradan almasını  Denedin yinede konuşmayı  Sessizliğinle bırakıp gittin,  Kulaklarımda tan...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/cikip-gittin-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklima düsmeyecektin BABAM', 'aklima-dusmeyecektin-babam-yurdagul-kurnaz-l2ddf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Canim cananim, canyoldasim

Hayatta en sevdigim arkadasim

Aklima düsmeyecektin Babam

Cocukluguma gitti her an

Nasil calisirdin madende

Bos vaktinde bile cöp toplardin

Haram girmesin asimiza derdin

Yer altinda Sen ölümle göz göze

Yer yüzünde ben ölümüne Seninle

Her aksam saat on-bucugu beklerdim

Ellerim semada dualar ederdim

Yetimlikle, hastalikla 

Calismakla gecti ömrün

En cok sevdigin bir tek oglun 

Döndü sana sirtin

Biraz daha diren Babam

Hayalini ellerimle, yüregimle

Gerceklestirecegim

Insallah seninle

Seneye Mekkeye

Gidecegiz

Aklima düsmeyecektin Babam...

Hic aklimdan cikmiyorsun ki...!', 'Canim cananim, canyoldasim Hayatta en sevdigim arkadasim Aklima düsmeyecektin Babam Cocukluguma gitti her an Nasil calisirdin madende Bos va...', ARRAY['Türk Edebiyatı','Şiir','Yurdagul Kurnaz']::text[], 8.5, '{"poet":"Yurdagul Kurnaz","poet_slug":"yurdagul-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/aklima-dusmeyecektin-babam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Dostum', 'can-dostum-atilla-gozukucuk-boe3t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine bir hal gelmiş; dostumun başına,

Varıp halini niyaz eyleyim,

Uğrunda canım vereyim, can yoldaşıma,

Sorup derdine, derman olayım.

Can dostuma, daim iyilik edeyim,

Hasta ise, derdine merhem olayım,

Can dostum olmasa, bu dunyayı neyleyim,

Uğrunda ölüp, kurban olyım...

Dost dediğin, uğrunda ölmeli,

Seninle ağlayıp, seninle gülmeli,

Candan sevip, kadir kıymet bilmeli,

Can dostu dediğin, böyle olmalı.

12.11.2005', 'Yine bir hal gelmiş; dostumun başına, Varıp halini niyaz eyleyim, Uğrunda canım vereyim, can yoldaşıma, Sorup derdine, derman olayım. Can do...', ARRAY['Türk Edebiyatı','Şiir','Atilla Gözüküçük']::text[], 8.5, '{"poet":"Atilla Gözüküçük","poet_slug":"atilla-gozukucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/can-dostum-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damla damla', 'damla-damla-yurdagul-kurnaz-gfwlc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Damla damla akiyor

Gözlerden nur damliyor

Perdeler göz aciyor

Cemre düstü yaniyor

__________________Eridi buz-daglari

__________________Sel basti yaralari

__________________Köhnemis duvarlari

__________________Küf tutmus anilari

Gider oldu yarinlar

Bel baglamaz karalar

Yasadigim acilar

Alnimdaki yazilar', 'Damla damla akiyor Gözlerden nur damliyor Perdeler göz aciyor Cemre düstü yaniyor __________________Eridi buz-daglari __________________Sel ...', ARRAY['Türk Edebiyatı','Şiir','Yurdagul Kurnaz']::text[], 8.5, '{"poet":"Yurdagul Kurnaz","poet_slug":"yurdagul-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/damla-damla-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara', 'ankara-ruya-deniz-demir-l0tbl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalan bu inanma 

Çocuklar koşacak bir gün

Yorgun ıslak sokaklarında

Ey sevgili Ankara

Sıkı tut kendini ağlama

Yalan söyledim sana

Ne olur beni bağışla

Yalan bu inanma

Gidenler dönecek bir gün

Sessiz sakin sokaklarına

Ey sevgili Ankara

Kendini yollara bağlama

Gidenler dönmüyorlar

Sen onları da bağışla', 'Yalan bu inanma  Çocuklar koşacak bir gün Yorgun ıslak sokaklarında Ey sevgili Ankara Sıkı tut kendini ağlama Yalan söyledim sana Ne olur be...', ARRAY['Türk Edebiyatı','Şiir','Rüya Deniz Demir']::text[], 8.5, '{"poet":"Rüya Deniz Demir","poet_slug":"ruya-deniz-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ankara-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangi Gözle?', 'hangi-gozle-kadir-soyturk-et9az', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''Gerceği gör'' diyorsun

Hangi Gözle görecek? 

Var mı haktan nasibi,

Adil karar verecek? 

Yüz kara, vicdan kara,

Bir uzuvda bin yara...

Kucak açan onlara

Cennete mi girecek? 

Aka kara girdikçe

Şeytan akıl (!)  verdikçe

Bu cehalet sürdükçe

Bu keşmekeş sürecek!', '''Gerceği gör'' diyorsun Hangi Gözle görecek?  Var mı haktan nasibi, Adil karar verecek?  Yüz kara, vicdan kara, Bir uzuvda bin yara... Kucak ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hangi-gozle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-seher-gungor-1wnj5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kıyametler Kopuyor Gökyüzünde,

Yıldızlar,

Kara Gölgelerine Bürünmüş,

Dört Bir Yanda Ayrılıklar

Ayaz mı,Ayaz  Bir Sonbahar,

Bu Nebiçim Bi Mevsim Böyle......

                           Seher Güngör

(Küçük Pencerem30/10/2005)', 'Kıyametler Kopuyor Gökyüzünde, Yıldızlar, Kara Gölgelerine Bürünmüş, Dört Bir Yanda Ayrılıklar Ayaz mı,Ayaz  Bir Sonbahar, Bu Nebiçim Bi Mev...', ARRAY['Türk Edebiyatı','Şiir','Seher Güngör']::text[], 8.5, '{"poet":"Seher Güngör","poet_slug":"seher-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sonbahar-116-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün', 'huzun-seher-gungor-7v575', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kıyametler Kopuyor Gökyüzünde,

Yıldızlar,

Kara Gölgelerine Bürünmüş,

Dört Bir Yanda Ayrılıklar

Ayaz mı,Ayaz  Bir Sonbahar,

Bu Nebiçim Bi Mevsim Böyle......

                           Seher Güngör

(Küçük Pencerem30/10/2005)', 'Kıyametler Kopuyor Gökyüzünde, Yıldızlar, Kara Gölgelerine Bürünmüş, Dört Bir Yanda Ayrılıklar Ayaz mı,Ayaz  Bir Sonbahar, Bu Nebiçim Bi Mev...', ARRAY['Türk Edebiyatı','Şiir','Seher Güngör']::text[], 8.5, '{"poet":"Seher Güngör","poet_slug":"seher-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/huzun-131-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanır mı?', 'yasanir-mi-yavuz-bayram-caliskan-m30n1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Diken eksen gül biter mi? 

Altın toprakta yiter mi? 

Can cana ömür katar mı? 

Yaşanır mı yalnız, yalnız yaşanır mı? 

Soluksuz insan yaşar mı? 

Küreksiz sandal deniz aşar mı? 

Yaşam ölüme kendi koşar mı? 

Boşanır mı ömür, ömür boşanır mı? 

Kurumuş ağaç yaprak verir mi? 

Rüzgar eserse toprak kalır mı? 

Azrail’den başkası can alır mı? 

Yaşanır mı hasret, hasret yaşanır mı?', 'Diken eksen gül biter mi?  Altın toprakta yiter mi?  Can cana ömür katar mı?  Yaşanır mı yalnız, yalnız yaşanır mı?  Soluksuz insan yaşar mı...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasanir-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşadım Amma', 'yasadim-amma-yavuz-bayram-caliskan-uph5e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Doğayı sevdim, yaşadım.

İnsanı sevdim, yaşadım.

Aşkı tanıdım ama; 

Mutluluğu yaşayamadım...', 'Doğayı sevdim, yaşadım. İnsanı sevdim, yaşadım. Aşkı tanıdım ama;  Mutluluğu yaşayamadım......', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yasadim-amma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ödünç Sevgiler', 'odunc-sevgiler-ekrem-sama-dbnwy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anne baba sevgisi, olmalı yüksek, 

Hiç kimse sanmasın ki, bu bir övünç, 

Yarın çocuğumuza, biz ''büyük yük''sek; 

Haklıdır vermemişsek, bugünden ödünç... 

(İstanbul:06.05.2005)', 'Anne baba sevgisi, olmalı yüksek,  Hiç kimse sanmasın ki, bu bir övünç,  Yarın çocuğumuza, biz ''büyük yük''sek;  Haklıdır vermemişsek, bugünd...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/odunc-sevgiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızdı', 'yalnizdi-yavuz-bayram-caliskan-l6pla', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızdı bu gönlüm, ıssız bir ada gibi,

Yaşıyordum öyle ya da böyle.

Günün birinde gönlüme doğan güneşin,

Aydınlattı geleceğimi, gençliğimi, her şeyimi,

Umutla sevdim bir sonbahar gününde,

Terkedilsem de ağlamıyorum...', 'Yalnızdı bu gönlüm, ıssız bir ada gibi, Yaşıyordum öyle ya da böyle. Günün birinde gönlüme doğan güneşin, Aydınlattı geleceğimi, gençliğimi,...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalnizdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-yavuz-bayram-caliskan-pskk0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nar çiçeklerinden asma yapraklarına,

Birbirimizin ruhlarına dokunduk.

Taşlandım bakışlarla,

Tuale vurulan fırça ile,şiirlerle yıkandım.

Duvarlar soğuktu.

Umudumu yitirmedim.

Dişlerimle, tırnağımla kazıyarak,

Kirli hayatları yaşamadım.

Sevilmenize izin verir misiniz duldalarda? 

Avare düşler yaşıyorum.

Kuş lastikleriyle yalnızlıkları taşlıyorum.

Suç yaşamaksa ceza ağır,

Gün görmemiş ümitleri çiğnediler, ezdiler.

Gözler yaşa alıştı, ömür yasa.

Atıldığımız kuyulara kırgın kalbimiz.

İsimsiz yıldızlarla sayılıyoruz.

Bir göz kerpiç evdi sevdamız,

Zoruma gidiyor,

Biri üzümsüz bağlar,

Biri de ciğerimizi parçalayan hasret.

Kanımızı emen sülükler,

Buğulu mutluluklar,kimsesiz tepelerde,

İliklerime, yüreğime işleyen ayazlar.

Sana ağıtlar bırakıyorum,

Yüreğini yağmalayacak yalnızlıklar.

Yıkadım,duruladım ağıtlarımla özlemleri,

Sana kahroluşu bırakıyorum.

Tedirginim.

İhanetin resmini gördüm tualde.

Titreyen eller sarılır boğazına.

Güzün yapraklar hasrete yolcudur,ağaçlar hancı,

Aynaya bak ve hüznünü gör ağlayan ey yalancı,

Mevsim dökülüş mevsimi, mevsim güz,vakit sancı,

Göz yaşlarım inci dizeleri, dökülmeye hazır

Güneşin ışıkları ısıtmıyor beni soğuk mevsimlerde.

Gözlerden damlayan yalnızlık...', 'Nar çiçeklerinden asma yapraklarına, Birbirimizin ruhlarına dokunduk. Taşlandım bakışlarla, Tuale vurulan fırça ile,şiirlerle yıkandım. Duva...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yalnizlik-295-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vurgunum', 'vurgunum-yavuz-bayram-caliskan-x87yb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin denizinde yosunum,

Senin dalganda kumum.

Kız senin batışına değil, 

Doğuşuna  vurgunum...', 'Senin denizinde yosunum, Senin dalganda kumum. Kız senin batışına değil,  Doğuşuna  vurgunum......', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vurgunum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yandım Gidiyorum', 'yandim-gidiyorum-yavuz-bayram-caliskan-9pckh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sigarayı yakan ateş, dağları da yakar mısın? 

Damın ardında batan gün bu gün beni satar mısın? 

Başından dökülen perçem beni bayıltan eter misin? 

Bu ömre sen sığdın bu cana yeter misin? 

Baharım geçti geçiyor yazım beni yakar mı? 

Anlımdaki yazı, kara kader gibi akar mı? 

Bu aşkın tohumlarını söyle gönlün eker mi? 

Ben çektim yandım söyle senin kalbin çeker  mi?', 'Sigarayı yakan ateş, dağları da yakar mısın?  Damın ardında batan gün bu gün beni satar mısın?  Başından dökülen perçem beni bayıltan eter m...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yandim-gidiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Kasım''da Kafama Takılanlar', '10-kasim-da-kafama-takilanlar-metin-yalti-91ybm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KAFAMA TAKILANLAR 

Bakma sen 

On beş yılda yaptıklarını 

Yetmiş yıldır yapamadığımıza 

Bazen takılıyor da aklıma 

Sanmam ki sana inat olsun diye 

Bak yetmiş küsur üniversitemize 

Bazısı muhtaç hala Öğretim üyesine 

Sakın anlattıklarım sanma nazire 

Olanları da düşmüşler intihale 

Bu gün bile muhtacız hala sana 

Bu utançla yarın çıkarız huzura 

Bine bin katan söylemlerimizde 

Yanlışları doğru anlatırız baştan sona 

Ah Atatürk ah ne vardı gittin erkenden 

Geceyi gündüze kattın hep aceleciliğinden 

Sandın ki çağdaşlığı kaçıracak Türkiye 

Tabii haberin yoktu AB’ye aday üyelikten 

Biliyor musun Atam 

Hala gücün var senin 

Şöyle bir silkelesen 

Kurtaracaksın bizi 

Üstümüzdeki yılgınlıktan 

 10/11/05', 'KAFAMA TAKILANLAR  Bakma sen  On beş yılda yaptıklarını  Yetmiş yıldır yapamadığımıza  Bazen takılıyor da aklıma  Sanmam ki sana inat olsun ...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/10-kasim-da-kafama-takilanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlenen Ama Gelmeyen Birine', 'ozlenen-ama-gelmeyen-birine-pinar-bulduk-7pr7n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özledim seni yeter artık gel

Bu özleme bir son ver

Gelde bitsin bu yürek yangını

Sen olmadan bu hayat yaşanır mı? 

Özledim o kömür karası gözlerini

Özledim rüzgarda savrulan saçalarını

Özledim sımsıcak ellerini

Özledim sesini,yüzünü, yüreğini

Şimdi sensiz anlamsız hayat benim için

Anlasan zalim yapamıyorum sensiz

Bu yürek yapayalnız çaresiz,sensiz

Ne olur sanki dönsen bu özlemi sona erdirsen

Beni hayata yeniden döndürsen

Şimdi hayatta yapayalnızsan suçlu kim? 

Sen mi yoksa seni deliler gibi seven yüreğim mi? 

Suçlu benim suçum seni özlemek

Gelmeyeceğini bile bile seni beklemek

Duydumki dönmem artık ona demişsin

Beni unuttuğunu söylemişsin

Tanrı''dan tek dileğim

Benim gibi özlesiye özleyen biri olasın', 'Özledim seni yeter artık gel Bu özleme bir son ver Gelde bitsin bu yürek yangını Sen olmadan bu hayat yaşanır mı?  Özledim o kömür karası gö...', ARRAY['Türk Edebiyatı','Şiir','Pınar Bulduk']::text[], 8.5, '{"poet":"Pınar Bulduk","poet_slug":"pinar-bulduk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ozlenen-ama-gelmeyen-birine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yürek', 'bir-yurek-umit-yildiz-krqjr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'BİR YÜREK

Bir yürek sevdim.

Deli bir yürek hem deli, hem asi bir yürek; 

Benim olan ama yanımda olmayan yürek.

Yumuşacık elleri,şirin mi şirin sözleri olan yürek! 

Bakınca içimi eriten; ama ferahlatan bir yürek

Yanımda olan ama bana uzak bir yürek

Öyle bir yürek ki içinde volkanlar olan,

Dışında nehirler akan yürek.

Sevmesini bilen bir yürek

Ey yürek! sen her şeye değersin

Sen gülsün, sen nursun

Sen incisin, sen biriciksin

Sen içimi yakan, beni yaşatansın.

Gül yürek; hiç ağlama

Bu gönül sensiz bir hiç….. yürek.', 'BİR YÜREK Bir yürek sevdim. Deli bir yürek hem deli, hem asi bir yürek;  Benim olan ama yanımda olmayan yürek. Yumuşacık elleri,şirin mi şir...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yildiz']::text[], 8.5, '{"poet":"Ümit Yildiz","poet_slug":"umit-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-yurek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk bumudur acep', 'ask-bumudur-acep-ali-riza-unal-tdnup', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk saklanamaz elde değil.

Bir feryat ile duyurmak ister,

Meşk-e mecâl mümkün değil,

O leb-i badeye doyurmak ister..

Bir davet ile göz kırp yılda değil.

Gönül mihmanındır, buyurmak ister.

Vuslatın her dem olsun, dilde değil.

Aşığın visâle, buyurmak ister..', 'Aşk saklanamaz elde değil. Bir feryat ile duyurmak ister, Meşk-e mecâl mümkün değil, O leb-i badeye doyurmak ister.. Bir davet ile göz kırp ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-bumudur-acep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai 3...', 'rubai-3-omer-golge-6is3g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Saymaz ehl-i tasavvuf,yaran-ı zahir bizleri

Haykırarak zikr eder,titrer şehvetten dizleri

İçi boş fındık kabuğu,tesir etmez sözleri

Yanmayı ne bilsinler,buz tutmuşken özleri', 'Saymaz ehl-i tasavvuf,yaran-ı zahir bizleri Haykırarak zikr eder,titrer şehvetten dizleri İçi boş fındık kabuğu,tesir etmez sözleri Yanmayı ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Gölge']::text[], 8.5, '{"poet":"Ömer Gölge","poet_slug":"omer-golge","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai-3-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin İçin', 'gozlerin-i-cin-figen-aydogmus-u1cy3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Git diyor dilin, 

Kalmamı isterken gözlerin 

Bakışların izin vermezken dilinden dökülenleri nasıl dinlerim

Yakarım gurur denilen şeyi

Silerim bir çırpıda dilinden dökülen sözleri

Bırakmak kolay mı sanıyorsun 

Yalanlara yol almak kolay mı

Senli günlere çizgi çekmem için

Dilinden yüreğine ulaşmayan sözleri affettim

Sadece

Gözlerin için

                     12 Kasım 2005', 'Git diyor dilin,  Kalmamı isterken gözlerin  Bakışların izin vermezken dilinden dökülenleri nasıl dinlerim Yakarım gurur denilen şeyi Sileri...', ARRAY['Türk Edebiyatı','Şiir','Figen Aydoğmuş']::text[], 8.5, '{"poet":"Figen Aydoğmuş","poet_slug":"figen-aydogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerin-icin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve ben', 'sen-ve-ben-ali-riza-unal-3y68s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen ve ben bir garip hilkâtiz.ta ezelden.

Mevlanadan şemsten gayrımızmı,ola,

Bilmezmisin sen o nur-sun korkma zevâlden.

Nur dediğin bir Hakkındır ayrımızmı ola,

Cehaletin çöl koymaz boşa gezdirir,

İllâ mecnuna bir kamil kılavuz ola,

Aşk-sız naz, vermez haz candan bezdirir,

Neylersin taşrada arayan kendinde bula,', 'Sen ve ben bir garip hilkâtiz.ta ezelden. Mevlanadan şemsten gayrımızmı,ola, Bilmezmisin sen o nur-sun korkma zevâlden. Nur dediğin bir Hakk...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-ve-ben-143-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A.B Kahpe Tuzak', 'a-b-kahpe-tuzak-osman-karaarslan-0uxts', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Avrupa Birliği, pembe bir rüya.

Altın tasta zehri, iç diyorlar iç.

Katılım belgesi, bir kahpe tuzak.

Bin yıllık hesap var, öç diyorlar öç.

Yarım asır önce, düştük yollara.

Ne versek yetmedi, bu çakallara.

Önümüzdeki on, yirmi yıllara.

ABE’YE girmek çok. güç diyorlar güç

Timsah gibi gözyaşı döken  katil.

Diyor ki; dinime, Kur-an’a batıl.

Bunları unut da gel  öyle katıl.

Ay yıldız yerine, haç diyorlar haç,

Çerçeve belgesi,  aynısı Sevr’in.

Ne diyorsak mutlak, boyun eğersin.

Kırk katır mı kırk satır mı istersin.

Özgürsün gönlünce, seç diyorlar seç.

Basının bir çoğu, batıdan yana.

Yer yok tavrı Türk’ten, yana koyana.

Devleti sömürüp, halkı soyana.

Utanmadan başa, taç diyorlar taç.

Amaçları belli, vatanı bölmek.

Ege denizini, Kıbrıs’ı almak.

Şanlı Türk adını, tarihten silmek.

Papaz okulunu, aç diyorlar aç.

Atatürk’ün resmi, yasaklanmalı.

PKK, Ermeni, Rum aklanmalı.

Soykırım  suçunu, Türk yüklenmeli.

Suçsuzum demeye, suç diyorlar suç.

Osman Karaarslan', 'Avrupa Birliği, pembe bir rüya. Altın tasta zehri, iç diyorlar iç. Katılım belgesi, bir kahpe tuzak. Bin yıllık hesap var, öç diyorlar öç. Y...', ARRAY['Türk Edebiyatı','Şiir','Osman Karaarslan']::text[], 8.5, '{"poet":"Osman Karaarslan","poet_slug":"osman-karaarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/a-b-kahpe-tuzak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lale Bahçesine Gezdim Derdim İle', 'lale-bahcesine-gezdim-derdim-i-le-dilek-hokkaomeroglu-ztakz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Lale  bahçesini gezdim derdim ile

Bağladım gönlümü gönül direğine

Ey bülbül ne güzel şakırsın

İçimde yanar  aşk ataş ı

Ne Ferhat aşk ‘ı ne şirin feryadı

Kar eylemiyor bülbül  çaresiz dertlerdeyim

Diyar diyar gezmekteyim

Lale bahçesini gezdim derdim ile

Çöllerde kerem gibi yandım

Aslı gibi öldüm can_ı aradım

Neyleyim ben yarsız dostlar

Bu canı deyin hele neyleyim

Lale bahçesini gezdim derdim  ile

Bağrım yandı hasret ile  vurdum acı acı

Sazımın  tellerine  bağrım da aşk ataşı

Gecem gam ile dolu  ağlarım ömrüme

Ey!  bülbül duyar  mı yar feryadımı

Lale bahçesini gezdim derdim ile

Ne gardaş  ne bacı  hasretim yarime

Ferhat oldum susuz kaldım

Şirin oldum yarsız kaldım

Yüreğimde bir aşk ataşı

Ey! bülbül şakı bir hele sevda türküleri

Lale bahçesini gezdim derdim ile

Feyadım diyar diyar aştı

Yarimin yüreğine bir ok saplandı

Gel gör ki yarim  sevdalar garip

Ben garip sensiz  diyarlar da

Halim nicedir hasta yataklarda



Ey! bülbül şakı hele bir  de yarime 

Sevdan  öksüz kaldı susuz kaldı

Aşkı  dağlar da  çöller de  yüreğinde

Anlar mı dersin  bülbülüm

Bu garibi sevdam anlar mı dersin…

Sen bir şakı hele…', 'Lale  bahçesini gezdim derdim ile Bağladım gönlümü gönül direğine Ey bülbül ne güzel şakırsın İçimde yanar  aşk ataş ı Ne Ferhat aşk ‘ı ne ş...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/lale-bahcesine-gezdim-derdim-ile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Öykümüz...', 'bizim-oykumuz-ali-baksi-s6l0h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sevda öyküsü  aşk

Ne arkamda nede önümde izi

Sanki yaşanıyor içimizde

Dışarda hep başka dünyalar	

Bir geliyor bir gidiyor dünya

Ardını kovalıyor durmayan yaşamlar

Öykü yaşama dair yaşanmış	

Gidilmiş yollarda iz ararken

Buldugun hikaye senin olan

Kader dediğin tutkuysa

Aşk dediğin bulğu olmalıydı

Bir kez sevmedik''ki

İlk aşk degil bu dünyada

Okuduğum ilk kitap

Sevdiğim aşk şarkısı

Tatdığım meyve parçalarıydı aşk

Dışardaki başkası değildi

Senden öte bizdik paylaşmaya acık

Onların öyküsüde yoktu bizimdi öyküler

Ğidilmiş tozlu yollardı hikaye	

Varılmamış düş''tü sokağında umut

Seviyorduk aşktı ötesi

Mutluyduk mutsuzluğumuzda

Dışında bir dünya hic olmadı öykümüzde

Hep vardık hep bizlerdik aşk''la sevgimizdi ötesi

...', 'Bir sevda öyküsü  aşk Ne arkamda nede önümde izi Sanki yaşanıyor içimizde Dışarda hep başka dünyalar	 Bir geliyor bir gidiyor dünya Ardını k...', ARRAY['Türk Edebiyatı','Şiir','Ali Baksı']::text[], 8.5, '{"poet":"Ali Baksı","poet_slug":"ali-baksi","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bizim-oykumuz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Telgraf', 'telgraf-metin-yalti-ss5rz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Postacı bir haber getirse

''Yarın geliyorum.''

Nokta, Pınar

Gönlüme bahar gelecek

Pınar...', 'Postacı bir haber getirse ''Yarın geliyorum.'' Nokta, Pınar Gönlüme bahar gelecek Pınar......', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/telgraf-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UB-043 Değişim! ..', 'ub-043-degisim-mehmet-coban-jqz45', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Var oluştur görünümlerde

Varlıktan varlığa geçerken

“OL” dur tanrının sözünde

Görünümleri yaşarken

Dün, bugün, yarın

Zamanlarda varım

Ölürken doğarım

Doğumlarla yaşarım

Düşüncelerde gezerken

Kelimeleri hecelerken

Yaşam biçimleri seçerken

Benliklerde gezerim

Benlikler zalimdir 

Benlikler bencildir

Benlikler köledir

Benliklerden uzağım

Benlikler insancadır

Yürüyüşü kutsalcadır

Ulaşır özgürlüklere

Yürürüm adım, adım

Değişirim her an 

Kalıplarda duramam

Bilirim mutlaka

Vardır hesabını soran

12.11.2005-İzmir', 'Var oluştur görünümlerde Varlıktan varlığa geçerken “OL” dur tanrının sözünde Görünümleri yaşarken Dün, bugün, yarın Zamanlarda varım Ölürke...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ub-043-degisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biyoloji', 'biyoloji-hasan-cangir-fsptc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gelmiş de ders olmuş bize bir bilim olarak biyoloji 

Yabancı kelimelerle dolmuş yok efendim morfoloji ekoloji 

Tek anlamadığım konu olsa iskeletle kas sistemi 

Yetmez mi ki bize bilsek hücre ile fotosentezi... 

Virüsler çoğalırmış çoğalmazmış yahu bize ne bundan 

Bir de sınav girer araya sanki düşermiş gibi damdan 

Varsa bir de öğretmenin hiç durmadan ders anlatan 

Vallahi de yandın sen yardımcın olsun yaradan

Bide ramazan hoca olmazmı yok neymiş ekoloji

yok neymiş dna mış yok neymiş rna mış 

yok neymiş hasanın dna sı bozukmuş 

hasan eriyormuş

Yahu hocam dedim; sen erimişsin  dedi 

erimişler  bir şey bilmediklerinden konuşamaz

sadece boş boş dinler dedi ve 

bu yüzden bana 0 vermezmi

alsana bu dersten de kaldık', 'Gelmiş de ders olmuş bize bir bilim olarak biyoloji  Yabancı kelimelerle dolmuş yok efendim morfoloji ekoloji  Tek anlamadığım konu olsa isk...', ARRAY['Türk Edebiyatı','Şiir','Hasan Cangir']::text[], 8.5, '{"poet":"Hasan Cangir","poet_slug":"hasan-cangir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/biyoloji-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancısın sen zelom yalancı', 'yalancisin-sen-zelom-yalanci-hasan-cangir-w6fyq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hey sen 

umutlarımı çalan 

ve sonrada ortadan kaybolan 

sen sevgini hep yalan 

hile üzerine kuran yalancısın

hey sen 

karanlığıma ışık saçan 

yalan ışıkların uşağı 

kaç zaman saklanabilirsin 

kaf dağından yüce yalanlarına 

hey sen 

taş kalpli  kız 

sende ki kalp tüm 

varlıklarda da vardır', 'hey sen  umutlarımı çalan  ve sonrada ortadan kaybolan  sen sevgini hep yalan  hile üzerine kuran yalancısın hey sen  karanlığıma ışık saçan...', ARRAY['Türk Edebiyatı','Şiir','Hasan Cangir']::text[], 8.5, '{"poet":"Hasan Cangir","poet_slug":"hasan-cangir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalancisin-sen-zelom-yalanci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanmaki', 'sanmaki-hasan-cangir-p077o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'zelosuz dünyaymış neyleyim 

neyleyim zelom beni kabul etmedi

neyleyim dünya malını neyleyim

 zelosuz dünya değil

 zelolu bir dünyaydı tek ümidim

olmadı olmadı olmadı işte 

sanmasın ki onsuz yapacağımı 

bende bu dert taşıyacak  gibi deilim 

oysa ne hayaller kurmuştum kendi kendime 

zeloyla el ele tutuşup kırlarda gezecektik

sonra da bağıra bağıra seslenecektim ona 

seni seviyorum diye

olmadı olmadı olmadı işte 

ben bu dertlerin altında nasıl 

kalkabilirim ki 

bu benim sonum olmalı 

hissediyorum çünkü eridiğimi

hissediyorum 

oysa zelo bunun farkında bile değil

zelo 

seni sevdiğimi yazacam mezar taşıma', 'zelosuz dünyaymış neyleyim  neyleyim zelom beni kabul etmedi neyleyim dünya malını neyleyim  zelosuz dünya değil  zelolu bir dünyaydı tek üm...', ARRAY['Türk Edebiyatı','Şiir','Hasan Cangir']::text[], 8.5, '{"poet":"Hasan Cangir","poet_slug":"hasan-cangir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sanmaki-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanmaki unuturum zelo sanmaki', 'sanmaki-unuturum-zelo-sanmaki-hasan-cangir-z7rrv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dört mevsimin bir yazı var 

bir filiz gülün bin nazı var 

görüntüymüş neye yarar 

her güzellik senin içinde 

elimde tutuyorum gülü 

gülün acısı diken içinde 

sanmaki unuturum 

bu aşk varken benim içimde 

sanmaki unuturum zelo sanmaki

bu aşk varken içimde sanmaki 

unurum seni

sanmaki unurum seni zelo sanmaki...', 'dört mevsimin bir yazı var  bir filiz gülün bin nazı var  görüntüymüş neye yarar  her güzellik senin içinde  elimde tutuyorum gülü  gülün ac...', ARRAY['Türk Edebiyatı','Şiir','Hasan Cangir']::text[], 8.5, '{"poet":"Hasan Cangir","poet_slug":"hasan-cangir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sanmaki-unuturum-zelo-sanmaki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gittin -4-', 'sen-gittin-4-adem-uzun-ybdgj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen gittin sevmenin kalmadı adı.

Sen gittin yazımız hazana döndü.

Sen gittin yerin doldurulamadı; 

Senle geçen günler bir başka gündü.

Giderken ne güldün ne de bir veda,

Etmedin, gözümüz kaldı arkada.

Kırık kalpler ile viran bir oda...

Gidişin ölümden beter göründü.', 'Sen gittin sevmenin kalmadı adı. Sen gittin yazımız hazana döndü. Sen gittin yerin doldurulamadı;  Senle geçen günler bir başka gündü. Gider...', ARRAY['Türk Edebiyatı','Şiir','Adem Uzun']::text[], 8.5, '{"poet":"Adem Uzun","poet_slug":"adem-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-gittin-4-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-adem-uzun-kz9gp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sarı bir yaprak,

Dalından kurtularak,

Usul usul katılır,

Rüzgarların önüne.

Havada döne döne,

Öylece uçuşarak,

Karışır yalnızlığa.

Yalnızlık vurur toprağa.

Yalnızlık benim derdim.

Eğer bir yaprak olsaydım,

Ben de uçar giderdim.', 'Sarı bir yaprak, Dalından kurtularak, Usul usul katılır, Rüzgarların önüne. Havada döne döne, Öylece uçuşarak, Karışır yalnızlığa. Yalnızlık...', ARRAY['Türk Edebiyatı','Şiir','Adem Uzun']::text[], 8.5, '{"poet":"Adem Uzun","poet_slug":"adem-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yalnizlik-296-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmişşin', 'gitmissin-tayfun-yilmaz-u1f2o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yeni yeni anlıyorum gittigini

umudumda kalmadı ne fayda

yitirdigim sana üzülmüyorum

yitirdigim bana üzülüyorum

ardından geriye bakma 

bir damla gözyaşı

olmayacak 

ne umut etmişim ne bulmuşum

ne çok sevmişim ne çok

ama faydası yok gitmişssin

umudum kalmamış senden yana

tüketmişim bitirmişim bendeki seni

artık gitmişsin..

benden uzak benden ırak 

sende sensiz bende sensiz

kalmışım burada nefesssiz....

   tayfun yılmaz', 'yeni yeni anlıyorum gittigini umudumda kalmadı ne fayda yitirdigim sana üzülmüyorum yitirdigim bana üzülüyorum ardından geriye bakma  bir da...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Yılmaz']::text[], 8.5, '{"poet":"Tayfun Yılmaz","poet_slug":"tayfun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gitmissin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varsın Neyler Elem Üflesin', 'varsin-neyler-elem-uflesin-nuri-can-65fh5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '“Ey tabib elden gelirse yâremi gel emleme… 

Yar elinden gelmedir bu yâreyi merhemleme…” 

Varsın neyler elem üflesin

sazlar vedâ

kemanlar cefâ

alevden kor olsun

yaksın sinemi geda…

varsın bir ömre bedel olsun aşk

her durakta seni bekleyeyim

ey göğsümün nakışı

kalbimin atışı yar...

göğsüme bastırıp acılarımı

verip bağrımı ateşlere

beklerim ben...

ister hazan olsun

döksün yaprağını ağaçlar

ister çöle dönsün bahar

ey gözümün ışığı yar

beklerim ben...

varsın yokuşa sürsün  hayat

karanlığa dönsün gün

rüzgar esmesin

bahar gelmesin

kokmasın gül

küssün dünyaya gönül...

gözlerimde ay

ellerimde yıldızlar

kimsesiz bir buluta yükleyip hasretimi

melanet yağmurları da yağsa üzerime

beklerim ben

ey hüzünler güzeli

ömrümün gazeli yar...

varsın marjinale çıksın adım

boynu bükük çiçekler gibi

eğip başımı önüme

hep ağlayayım...

varsın saçlarım özlem

sakalım hüzün koksun

karda, kışta,

soğukta, darda kalayım...

sevgi acıtsa da içimi

 özlem acıtsa da

hep özleyeceğim

hep bekleyeceğim seni...

Yeterki, gelmesin ecel

dağ devrilmesin

beklerim ben

unutulmuş istasyonların

trenlerinde taşınan

kimselerin el sallamadığı

kimselerin karşılamadığı

yalnızlarımla...

beklerim ben........

Nuri CAN 

.', '“Ey tabib elden gelirse yâremi gel emleme…  Yar elinden gelmedir bu yâreyi merhemleme…”  Varsın neyler elem üflesin sazlar vedâ kemanlar cef...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/varsin-neyler-elem-uflesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kristal', 'kristal-elazigli-mustafa-kaya-ayhr6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ben atmalıyım 

kendimi sulara

ben günahkarım

gözyaşları sel olan sevgilim

sebebi benim..

ne kadar acı çekti

kimbilir

kristal şıklığında ruhun

annelerin annesi..

ve,

bir doğum günü

mimoza ağacı.

biliyorum ateşböceğim

biliyorum

seni çok seviyorum

bugün

hüzünleri unutma günü

hadi bırak avucuma

o sıcak öpücüğünü…

Mustafa kaya

12.11.2005

www.mustafakaya.net', 'ben atmalıyım  kendimi sulara ben günahkarım gözyaşları sel olan sevgilim sebebi benim.. ne kadar acı çekti kimbilir kristal şıklığında ruhu...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kristal-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne sen nede sensiz', 'ne-sen-nede-sensiz-hasan-cangir-vvtdw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ne sen nede sensiz

zelom inan sensiz olmuyor

ama sen le de olmuyor 

sana olan sevgimi 

anlayamacak kadar 

şımarıksın 

zelom ne sen nede sensiz

sana diyeceğim son söz budur işte

ne sen nede sensiz', 'ne sen nede sensiz zelom inan sensiz olmuyor ama sen le de olmuyor  sana olan sevgimi  anlayamacak kadar  şımarıksın  zelom ne sen nede sens...', ARRAY['Türk Edebiyatı','Şiir','Hasan Cangir']::text[], 8.5, '{"poet":"Hasan Cangir","poet_slug":"hasan-cangir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ne-sen-nede-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-tunahan-ermihan-ciumm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalansa tüm yaşananlar

En az sözlerin kadar gözlerinde yalan senin

Çünkü ben gördüm o deniz mavisinin

Gözlerinde nasıl çağladığını

Duygusaldın her daim

Beyaz bulut misali gözlerine

Kanın yerleşmesini seyrettim defalarca

Ağladın sen ve ben gördüm

Gözünden düşen her harfi 

Adım vardı her harfte 

Gururlandım umutlandım

Ama yalan diyorsan tüm yaşananlar

Bil ki en az sözlerin kadar gözlerinde yalan

Eğer yalansa tüm anılar ve kelimeler

Sana yazılmış bunca satırda yalan

Yemyeşil yaylalarda hissettiğim

Özgürlük duygusu misali

Gözlerine baktığımda hissettiklerimde yalan

Ve hatta

Mevsim diye sana taktığım namında yalan

Eğer yalansa tüm anılar ve kelimeler

Sana yazılmış bunca satırda yalan

Kırılıp kalmak düşecekse bunca yalanın ardından

Evet seni sevdiğimde yalan

Yılların,

Ayrılıkların,

Hasretlerin, kavuşmaların ardından

En az senin mazeretlerin kadar

Benim seni sevdiğimde yalan

Yalan sevdiğim kocaman ve aptal bir yalan', 'Yalansa tüm yaşananlar En az sözlerin kadar gözlerinde yalan senin Çünkü ben gördüm o deniz mavisinin Gözlerinde nasıl çağladığını Duygusald...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yalan-176-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Türkoğlu Türküm ben Atatürk’üm,', 'ben-turkoglu-turkum-ben-ataturk-um-halil-colak-z7hkk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çanakkale de Avrupalı palikaryaları doktuk sulara

Çatlamış ardamarları Avrupalıda utanmak nere

Ders almadılar tekrar saldırdılar bu kutsal toprağa

Kocatepe ten Atatürk’ten aldığı kutsal emirle

Egede palikaryayı tekrar Mehmet’im doktu sulara

Kocatepe Avrupa’nın içinde iyileşmez yaradır

Resmi dairelerden Atatürk’ün kaldırmak çaredir.

Avrupa utanmaz, arsız emperyalist bir ukaladır

O Karafatmaydı dadaş kızı palikarya dersini veren

Atatürk’le o kutsal savaşı kadın haliyle o görevi gören

Çıplak ayakla, karnı açken kurtuluş savaşı veren

Kimse unutturamaz palıkarya Atatürkü iyi öğren

İyi anlayın, iyi belleyin Türk’ün ebedi düşmanları

Biz Türkoğlu Türk üz emperyalistleri yenen Atatürk’üz

Asla dönmeyiz geri hep gideriz ileri

Hedefimiz Kızılelma Türkoğlu Türk ileri

Avrupa’nın yokmuş Atatürk’ün resmine tahammülü

Türk’ün gül bahçesinde ender güldür Atatürk’ü

Kimse silemez gönüllerde bitmeyen bu aşkı

Ben Türkoğlu Türküm ben Atatürk’üm,

Türkoğlu Türk artık ileri.

Halil ÇOLAK 12.11.2005 Ankara', 'Çanakkale de Avrupalı palikaryaları doktuk sulara Çatlamış ardamarları Avrupalıda utanmak nere Ders almadılar tekrar saldırdılar bu kutsal t...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ben-turkoglu-turkum-ben-ataturk-um-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Aklımıza Hep Geceleri Gelir', 'neden-aklimiza-hep-geceleri-gelir-dilek-hokkaomeroglu-cuvf6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neden aklımıza hep geceleri gelir

Bütün güzellikler ve pişmanlıklar

Aslın da ne sırasıdır bunların

Ne zamanı ne yeri

 

Gözlerimizde uyku kalmaz 

Düşüncelerimiz de bir noktada

Aklımıza gelir birden

Kim ne zaman neden niye? 

Nerde ne yapmış…

Yorganla savaşırız durmadan

Aslında uyumamak için bahane

Değil midir bunlar geceye..

Gözlerimizden uyku akar

Yine de direniriz  …

Bir sigara içimi zaman geçer

Sonra paket yarıya iner

Yanın da bir koyu kahve

Anılar gelir birer birer

Kimi ağlamaklı kimi tebessümle

Neden aklımıza  hep geceleri gelir

Ayrılıklar ölümler acılar

Anneler babalar evlatlar

Komşu hanımları ve beyleri

Gecede çığlık atan bekçi düdüğü

Alamadığmız kazak

Yiyemediğimiz yemek

Gidemediğimiz balık lokantası

Gezemediğimiz yaz tatili

Alamadığımız araba 

Neden geceleri hiç aklımıza gelmez

Varlığını bile hatırlamak dan aciz

Bizler için..

Kimsesizler…', 'Neden aklımıza hep geceleri gelir Bütün güzellikler ve pişmanlıklar Aslın da ne sırasıdır bunların Ne zamanı ne yeri   Gözlerimizde uyku kal...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/neden-aklimiza-hep-geceleri-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçsuz', 'ucsuz-omer-uzun-owzar', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kuşlar uçuyor 

yeşil gözlerimden 

maviye dalıp gidiyor 

bir gemi geçiyor 

ve sen gidiyorsun', 'kuşlar uçuyor  yeşil gözlerimden  maviye dalıp gidiyor  bir gemi geçiyor  ve sen gidiyorsun...', ARRAY['Türk Edebiyatı','Şiir','Ömer Uzun']::text[], 8.5, '{"poet":"Ömer Uzun","poet_slug":"omer-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ucsuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hocalarım', 'hocalarim-hasan-cangir-n65uz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'müdürümüz:

sınıfa girince müdür

lavaboya gidince müdür

taksitlerimiz yatırınca müdür 

coğrafya hocası:

coğrafya hocası kutuplarda basık ekvatorda 

şişkindir sınıfa girince dört mevsimi birden 

yaşıyoruz 

tarih hocası:

benim m.ö 1450 yılında mezopotamyada doğdumu söylüyor

göçebe haytımın oldugunu belgelerle tarif ediyor

osmanlı devletinin yüzkarası oldugumu söylüyor 

ve osmanlıyı batıran oldugumu imzalı belgelerle kanıtlıyor

matematik hocası:

matematik hocamız sınıfa girince 

x ler başımıza kral olur 

+ lar başımıza padişah olur

- ler başımıza sultan olur

matematik hocası ise başımıza

sıfırcı (0)  hoca olur

kimya hocası:

kimya hocamız bir elementtir

hiç kimseyle bileşik oluşturmaz

saftır', 'müdürümüz: sınıfa girince müdür lavaboya gidince müdür taksitlerimiz yatırınca müdür  coğrafya hocası: coğrafya hocası kutuplarda basık ekva...', ARRAY['Türk Edebiyatı','Şiir','Hasan Cangir']::text[], 8.5, '{"poet":"Hasan Cangir","poet_slug":"hasan-cangir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hocalarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tesettür', 'tesettur-ahmet-tevfik-ozan-3lidx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dalında güzel Çiçek, yaprak yeşil, meyve nur! 

Mektup o ki, mukaddes; sahibince okunur! 

Sen ey, En Güzel Çiçek; sevgi, şefkat pınarı

Kendi dalını kırma, meyveni çürütme, dur! ...', 'Dalında güzel Çiçek, yaprak yeşil, meyve nur!  Mektup o ki, mukaddes; sahibince okunur!  Sen ey, En Güzel Çiçek; sevgi, şefkat pınarı Kendi ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tesettur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teminat', 'teminat-ahmet-tevfik-ozan-ohb7u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir aşk mağarasından kaynayacak suyumuz

Toprağı ezmeyecek, yıkmayacak suyumuz..

Kayıklar yapacağım, sana gün ışığından

Tembel bir Okyanus’a varmayacak suyumuz! ..', 'Bir aşk mağarasından kaynayacak suyumuz Toprağı ezmeyecek, yıkmayacak suyumuz.. Kayıklar yapacağım, sana gün ışığından Tembel bir Okyanus’a ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/teminat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş Medrese Dedikleri', 'tas-medrese-dedikleri-ahmet-tevfik-ozan-ol5gg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir köpük yürek kadar, sıcak ve temiz burda

 Gölgemizi öpmekte, soğuk ve kirli taşlar...

 Çiçekleri yüreğin, bir kem sözle kurur da

  Bin bir çölle boğuşur, buzdan tolgalı başlar...', 'Bir köpük yürek kadar, sıcak ve temiz burda  Gölgemizi öpmekte, soğuk ve kirli taşlar...  Çiçekleri yüreğin, bir kem sözle kurur da   Bin bi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tas-medrese-dedikleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarifi Zor', 'tarifi-zor-ahmet-tevfik-ozan-xk8kw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Siyah bir gölge, bizi; yıllarca bırakmadı

Ellerimizi kesti, bir damla kan akmadı..

Esrarı çözmek için, kuşlara soru sorduk

Ağaçlar konuştu da, kuşlardan ses çıkmadı..', 'Siyah bir gölge, bizi; yıllarca bırakmadı Ellerimizi kesti, bir damla kan akmadı.. Esrarı çözmek için, kuşlara soru sorduk Ağaçlar konuştu d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tarifi-zor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençlerle Baş Başa', 'genclerle-bas-basa-mikdat-bal-5hs9s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dalmışsın eğlenceye, bu enerjik anında

Belli ki gençliğin var, delilik var kanında

Bir derde düşer isen, kimse kalmaz yanında

Gözünü aç, bu gençlik elinden uçar bir gün

Bulutlar küme küme, afakı sardığında

Rüzgarın sevkı ile tepene vardığında

Peşinden dolu yağıp kafanı yardığında

Artık iş işten geçer rahatın kaçar bir gün

Kaçacak yer ararsın, yok öyle yer kaçasın

Şemsiyen dahi olmaz, yok artık ne açasın

Toprağa giremezsin, kanadın yok uçasın

Gökte yerde ne varsa, tehlike saçar bir gün

Bu senin tavırların, bir zaman bende idi

Bana da eğlenceler, her şeyden önde idi

Yorulmak bilmiyordum, vucudum zinde idi

Zamanın keskin çarkı seni de biçer bir gün

Bunları bilemezsin, öğrenmek ister misin? 

Sana bir yol göstersem bu yoldan gider misin? 

Yoksa sen bana “yeter, kes artık, sus” der misin? 

Dersen de farketmiyor, bu fasıl geçer bir gün

Mikdadi bu memleket sizlere emanettir

Boşvermek, okumamak vatana ihanettir

Buarada yazdıklarım, sanma bir kehanettir

Bu halin bekle de gör başa dert açar bir gün', 'Dalmışsın eğlenceye, bu enerjik anında Belli ki gençliğin var, delilik var kanında Bir derde düşer isen, kimse kalmaz yanında Gözünü aç, bu ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/genclerle-bas-basa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Ölümlü Dünyada', 'su-olumlu-dunyada-ahmet-tevfik-ozan-tjgfb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her gözde bir damla yaş; kan ağlatan Feleğin(!) 

Dönmeyen bahtım gibi ta çarkına yanarım! ..

Bir ‘‘İman’’dan başka şey isteyecek dileğin

Suya aşık kor gibi, ta aklına yanarım! ...', 'Her gözde bir damla yaş; kan ağlatan Feleğin(!)  Dönmeyen bahtım gibi ta çarkına yanarım! .. Bir ‘‘İman’’dan başka şey isteyecek dileğin Suy...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/su-olumlu-dunyada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünce Denizi', 'dusunce-denizi-beyza-beyza-1bklq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düştüm düşünce denizine

Takılıp gittim düşlerimin peşine

Bir köpekbalığı gibiydi kaygılar

Hiç acımadan düşlerimi öldürünce

Ben de öldüm fikrimce

(15/08/2002)', 'Düştüm düşünce denizine Takılıp gittim düşlerimin peşine Bir köpekbalığı gibiydi kaygılar Hiç acımadan düşlerimi öldürünce Ben de öldüm fikr...', ARRAY['Türk Edebiyatı','Şiir','Beyza Beyza']::text[], 8.5, '{"poet":"Beyza Beyza","poet_slug":"beyza-beyza","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dusunce-denizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağınık Yatak', 'daginik-yatak-beyza-beyza-7hsuk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dağınık yatağın anlattığı ne çok şey var

Ne dürüst olmayan gerçekler

Ne de gerçekleşmeyen ümitler anlattıkları

Yansımaları.....

Daha farklı, daha tümsel bir beyin fırtınası

Dağınık yatağın anlattıkları

Yaşadığının ilk kanıtı...

(24/10/2002)', 'Dağınık yatağın anlattığı ne çok şey var Ne dürüst olmayan gerçekler Ne de gerçekleşmeyen ümitler anlattıkları Yansımaları..... Daha farklı,...', ARRAY['Türk Edebiyatı','Şiir','Beyza Beyza']::text[], 8.5, '{"poet":"Beyza Beyza","poet_slug":"beyza-beyza","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/daginik-yatak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-seher-gungor-dslar', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kalabalık bir kentin ortasında

sessiz çığlıklarımızla kalakalmışız

sen ve ben

birde benden içeri,bir sen....

selama durmuş yıldızlar

saf saf yolumuza..

kör dillerimizden dökülen,

memleketimizin türküleri kalmış

sadece kulağımızda....

bir de hasretini çektiğimiz,

yaşanmamış sevdalara

kuş gibi kanat çırpan

kalplerimiz.........

(öylesi bir yer-12/11/2005)', 'kalabalık bir kentin ortasında sessiz çığlıklarımızla kalakalmışız sen ve ben birde benden içeri,bir sen.... selama durmuş yıldızlar saf saf...', ARRAY['Türk Edebiyatı','Şiir','Seher Güngör']::text[], 8.5, '{"poet":"Seher Güngör","poet_slug":"seher-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/umut-214-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Gözlerim...', 'gozlerin-gozlerim-huseyin-karakaya-2qf4f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rüzgar olurdu bazen gözlerin,   

Gözlerime dolardı.

Dalgalanırdı gözlerim.

Yağmur olurdu bazen gözlerin,

Gözlerime yağardı.

Yaşarır,yeşerirdi gözlerim.

Yakamoz olurdu geceleri gözlerin,

Gözlerime şavkırdı.

Deniz olurdu gözlerim.

Güneş olurdu sabahları gözlerin,

Gözlerime doğardı.

Kamaşırdı gözlerim.

Irmak olurdu gözlerin,

Gözlerime akardı.

Derya olurdu gözlerim.

Ateş olurdu bazen gözlerin,

Gözlerimi dağlardı.

Kor olurdu gözlerim.

Çocuk olurdu gözlerin,

Gözlerimde oynardı.

Mutluluk olurdu gözlerim.

Sevgi olurdu bazen gözlerin,

Gözlerimi okşardı.

Çocuk olurdu gözlerim.

Taş olurdu bazen gözlerin,

Gözlerime fırlardı.

Yaralanırdı gözlerim.

Öfke olurdu bazen gözlerin,

Gözlerime kızardı.

Korkardı gözlerim.

Şirin olurdu gözlerin,

Dağlara bakardı.

Ferhat olurdu gözlerim.

Volkan olurdu gözlerin,

Gözlerime patlardı.

Duman olurdu gölerim.

Kuş olurdu gözlerin,

Gözlerimde uçardı.

Gökyüzü olurdu gözlerim.

Yük olurdu bazen gözlerin,

Gözlerime binerdi.

Taşıyamazdı gözlerim.

Soğuk olurdu bazen gözlerin,

Kar gibi,gözlerime yağardı.

Üşürdü gözlerim.

Sıcak olurdu bazen gözlerin,

Kıvılcımlar atardı.

Isınırdı gözlerim.

İlham olurdu gözlerin,

Şiir yazdırırdı.

Şair olurdu gözlerim.

Gözlerime değerdi bazen gözlerin.

 Felaketi olurdu.

Aklını bozardı gözlerim.

Ezgi olurdu gözlerin.

Gözlerime şakırdı.

Dinlerdi gözlerim.

Fırtına olurdu bazen gözlerin,

Gözlerime eserdi.

Tutunamazdı gözlerim.

Silah olurdu bazen gözlerin,

Sinemi/didemi delerdi.

Ölürdü gözlerim.

Şenlik olurdu gözlerin,

Gözlerimde coşardı.

Bayram ederdi gözlerim.

Özlem olurdu gözlerim,

Yollara bakardı.

Muştu olurdu gözlerin.

Gözlerim gibi olurdu bazen gözlerin

Gözlerime bakardı.

O anı anlatamıyorum.', 'Rüzgar olurdu bazen gözlerin,    Gözlerime dolardı. Dalgalanırdı gözlerim. Yağmur olurdu bazen gözlerin, Gözlerime yağardı. Yaşarır,yeşerird...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Karakaya']::text[], 8.5, '{"poet":"Hüseyin Karakaya","poet_slug":"huseyin-karakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/gozlerin-gozlerim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Yaz', 'o-yaz-ayhan-selim-s03bn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seninle tanıştığımız

O yazı unutamadım

Neşe dolup taştığımız

O yazı unutamadım

Yıl seksenbir mevsim yaz

Ederdin bana hep naz

Hatırlarsın düşün biraz

O yazı unutamadım

Seni hep düşünsem de

Kısmetim yokmuş sende

Unut beni desen de

O yazı unutamadım

Onsekizer yaşındaydık

Ömrümüzün başındaydık

Aşka henüz aşinaydık

O yazı unutamadım

''Biricik'' şu an nerdesin

Bilmiyorum kimlesin

Yabancı bir yerdesin

O yazı unutamadım

Ben burda yalnızım

Yalnızlık alın yazım

O yaz en güzel yazım

O yazı unutamadım.', 'Seninle tanıştığımız O yazı unutamadım Neşe dolup taştığımız O yazı unutamadım Yıl seksenbir mevsim yaz Ederdin bana hep naz Hatırlarsın düş...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Selim']::text[], 8.5, '{"poet":"Ayhan Selim","poet_slug":"ayhan-selim","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/o-yaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Kokulu Yarim', 'gul-kokulu-yarim-seher-gungor-2hbxq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bakmaya kıyamadığın güle,

doya doya bakarsın.

doyumsuzluğunla

derinden çekersin içine..

döker yapraklarını zamanı geldiğinde

dalında soldurursun.....

dayanamazsın bakmalara 

alırsın dalından..

koklayım dersin doya doya

okşarsın yapraklarını bir bir.

inciltip,kırmadan,

elinde soldurursun...

gülün yazgısıdır solmak.

dedim ya canözüm,

birtek sana,

''gülün ömrü az olurmuş'' diye..

seher güngör

öylesi biryer-12/11/2005', 'bakmaya kıyamadığın güle, doya doya bakarsın. doyumsuzluğunla derinden çekersin içine.. döker yapraklarını zamanı geldiğinde dalında solduru...', ARRAY['Türk Edebiyatı','Şiir','Seher Güngör']::text[], 8.5, '{"poet":"Seher Güngör","poet_slug":"seher-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gul-kokulu-yarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende sev', 'sende-sev-hilal-ozdemir-js9z0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mutuluğun penceresi hep açık

Sende aç yüreğini ona

Pencerenin önünde bir çiçek saksı

Bir fesleğen ağacı ol koku saç

Mutluluğu yakalamak zor değil

O hep senin gönlünde

Bir gülümse

Bir ağla

Ve bir yetimin başını okşa

İşte mutluluk yanı başında

Bir açı doyur

Bir ağlayanı avundur

Bir susuzu suya kandır

Ve bir çıplağı giyindir

Mutluluk işte

Dudaklarında ki tebessümde saklı

Ve bir minarenin ucunda

Okunan beş vakit ezanda saklı

Açıl insanlığın içine doğru

Ruhuna yepyeni mutluluklar sun

Birlikte bereket vardır

Sev sevbildiğin kadar

Ve sar sarabilidiğin kadar sinene

Mutluluğun penceresi hep açık..

(03-01-2005)', 'Mutuluğun penceresi hep açık Sende aç yüreğini ona Pencerenin önünde bir çiçek saksı Bir fesleğen ağacı ol koku saç Mutluluğu yakalamak zor ...', ARRAY['Türk Edebiyatı','Şiir','Hilal Özdemir']::text[], 8.5, '{"poet":"Hilal Özdemir","poet_slug":"hilal-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sende-sev-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Enkazım', 'enkazim-nurten-tarim-6ba25', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Enkazım bilmecem

Yetim duygumun haşin sahibi

Yaralıyım aşka susadı kalbim

Geceler kördüğümüm rüyalar götürüyorum  :

Uzaklara dalan bakışımın serabı 

Hevesim çölde kaktüs

Son hayalim umudumda masalım

Mevsimlerle açtim kalbimin kafesini

Duygularım azat dagıldı oraya buraya

Ne sen kaldın bu alemde nede ben 

Bakışın bakışıma dolandı

Aşkın heryanımı sardı

Canıma can  istedim olmadı

Seni aşktan daha yüce sevdim

Korkum kaybetmek oldu sevdiğim  

Rabbim seni ne güzel yaratmış

Kaderini banamı yazmış 

Sazlar çalar şarkılar seni söyler 

Yumdu kalp gözüm yokluguna 

Beni dertlere karan belalım 

Sarıp sarmaladığım rüyam

Beni benden alıp gittin 

Unutulmuş dünyamda beni yanlız bıraktın

Rüyalarıma kilit vurdum

Anıları  yastık yaptım

Aşkın oldum yoklugunu buldum

Yalan şerbetinle avundum

İçtim elinde kana kana

Dermanım bebeğim dedın

Dünyamda rengim oldun

Ayın şafkı yetmez güneşım oldun 

Sana hasret  bilki seninim 

Sebebim sensin sana göre adres benim

Kuşak oldu durdu zaman belimizde

Belalılar yazdı aşkı bu alem

Yazdım   yazmadı kalem ezdi ezildim 

Al yazmamı çattım başıma

Geldik  gıderız  dünyadan

Gelen elbet gideni aratır 

 Hatıralar gün gelir aşkı hatırlatır

 Arkamda kalırsan başka aşklar tessellin olur

 Anılarda kalan fotografım

 Güz serinliğinde sararır solar 

 Hayat bır nehır kurumadan akar

 Baharla solan umut 

 Rengarenk bınlerce çiçek  açar

 Senden tek istediğim

 Kalbinde öyle bir yer yapki 

 Güzle  mefta olan aşkım gömülsün', 'Enkazım bilmecem Yetim duygumun haşin sahibi Yaralıyım aşka susadı kalbim Geceler kördüğümüm rüyalar götürüyorum  : Uzaklara dalan bakışımın...', ARRAY['Türk Edebiyatı','Şiir','Nurten Tarım']::text[], 8.5, '{"poet":"Nurten Tarım","poet_slug":"nurten-tarim","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/enkazim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-seher-gungor-rtint', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dilinden dökülen, yalanların mı doğru,

gözlerinde okuduğum doğrular mı yalan..

hangisi bilme ki doğru olan..

yoksa benmiyim yalan olan..

özlemler mi çok güzel,

yoksa tek ben miyim özleyen..

özlemek güzel şey..

yüreğinde özelse özlenen...

güzeldir bazen uzayan mesafeler

ayrılıklar bile güzeldir inan.

usanmadan,hasretinle

bekliyorsa bekleyen.....

12/11/2005', 'dilinden dökülen, yalanların mı doğru, gözlerinde okuduğum doğrular mı yalan.. hangisi bilme ki doğru olan.. yoksa benmiyim yalan olan.. özl...', ARRAY['Türk Edebiyatı','Şiir','Seher Güngör']::text[], 8.5, '{"poet":"Seher Güngör","poet_slug":"seher-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalan-177-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tarihçiye', 'bir-tarihciye-i-smail-aksoy-b20ux', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey sen geçmişi yücelten

Araştıran görünüşü, yüzeyini ırkların,

kendini sergileyen hayatı,

Ey sen insanı politik bir varlık olarak algılayan,         

toplantılarda, hükümdar ve dinadamı olarak,

Ben, Alleghani-dağlarının yerlisi, davranıyorum insana

kendisi nasılsa kendi içinde kendi şartlarında,

çok ender görünen damarını sıkıyorum hayatın,

(çok gurur duyması insanın kendisiyle) ,

şimdiye değin yapılanların taslağını çiziyorum

Ben, Kişiliğin şarkıcısı, kurguluyorum geleceğin tarihini.

Walt Whitman

(31 Mayıs 1819 - 26 Mart 1892, A.B.D.)

Türkçeye çeviren: İsmail Aksoy

[''Inscriptions”dan]', 'Ey sen geçmişi yücelten Araştıran görünüşü, yüzeyini ırkların, kendini sergileyen hayatı, Ey sen insanı politik bir varlık olarak algılayan,...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-tarihciye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimlik', 'kimlik-beyza-beyza-v38qa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben mi sendim

Sen mi ben

Biz tek miydik

Yoksa sen ben

Ben de sen

Biz kimdik? 

(26/08/2005)', 'Ben mi sendim Sen mi ben Biz tek miydik Yoksa sen ben Ben de sen Biz kimdik?  (26/08/2005)...', ARRAY['Türk Edebiyatı','Şiir','Beyza Beyza']::text[], 8.5, '{"poet":"Beyza Beyza","poet_slug":"beyza-beyza","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kimlik-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalabalıkta', 'kalabalikta-i-smail-aksoy-4qejt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalabalıkta, arasında erkeklerle kadınların,

Farkına varıyorum birinin seçtiğine beni

gizli ve kutsal işaretlerle,

Benden başkası kabullenmiyor O’nu, babası bile, eşi, kardeşi,

çocuğu bile benden yakın değil O’na. 

Bazıları şaşırmış, O değil - O tanıyor beni.

Ah sevgili ve kusursuz eşit adam,

Düşündüm ki keşfedersin beni böyle zayıf, dolaylı işaretlerle,

Ve aynı işaretlerle tanıyacağım ben de seni karşılaştığımızda.

                

Walt Whitman

(31 Mayıs 1819 - 26 Mart 1892, A.B.D.)

Türkçeye çeviren: İsmail Aksoy

(”Calamus”dan)', 'Kalabalıkta, arasında erkeklerle kadınların, Farkına varıyorum birinin seçtiğine beni gizli ve kutsal işaretlerle, Benden başkası kabullenmi...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kalabalikta-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üçleme', 'ucleme-beyza-beyza-oymc7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'DUYGU fazla vericidir

MANTIK ise bencil

SAĞDUYU en adil! 

(14/04/2005)', 'DUYGU fazla vericidir MANTIK ise bencil SAĞDUYU en adil!  (14/04/2005)...', ARRAY['Türk Edebiyatı','Şiir','Beyza Beyza']::text[], 8.5, '{"poet":"Beyza Beyza","poet_slug":"beyza-beyza","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ucleme-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Dolu Şimdi', 'hayat-dolu-simdi-i-smail-aksoy-7r3pa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat dolu şimdi, yoğun, görünebilir,

Ben, kırk yaşında Birleşik Devletler’in sekseninci yaşında,

Yüzyıl sonra ya da yüzlerce yüzyıl sonraki birine bunlar

Henüz doğmamış olan seni arıyor bu dizeler. 

Bunları okuduğunda görünebilir olan ben görünmez olurum,

şimdi sensin, yoğun, görünebilir, şiirlerimi gerçekleştiren,

beni arayan,

Yanında olduğumu ve senin yoldaşın olduğumu düşünüp 

çok mutlu olacağını kurguluyorsun; 

Say ki yanındayım.

(Yanında olmadığım konusunda çok emin olma.) 

Walt Whitman

(31 Mayıs 1819 - 26 Mart 1892, A.B.D.) 

(“Calamus”dan) 

Türkçeye çeviren: İsmail Aksoy', 'Hayat dolu şimdi, yoğun, görünebilir, Ben, kırk yaşında Birleşik Devletler’in sekseninci yaşında, Yüzyıl sonra ya da yüzlerce yüzyıl sonraki...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hayat-dolu-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Üç', 'sonsuz-uc-i-smail-aksoy-fmeog', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İki erkek var dünyada

sürekli yoluma çıkan,

ilki benim sevdiğim

öbürü beni seven.

İlki karanlık havsalamda oturan

gecesel bir düşte,

öbürü yüreğimin kapısı yanında durur, asla almam onu içeri.

İlki bana gelip geçiçi

baharsı bir mutluluk soluğu verdi,

öbürü bütün ömrünü

ve tek bir saatini bile geri alamadı.

İlki sevdanın temiz ve özgür olduğu

kanın şarkısında çağıldar,

öbürü düşlerin boğulduğu

üzüntülü günle eşit.

Her kadın bu ikisi arasında durur,

sevmiş ve sevilmiş ve temiz -

her yüzyılda bir kez

erir bunların hepsi tek bir parçada.

Tove Ditlevsen (1918-1976, Danimarka,) 

(1942, ”Küçük Dünya” ’dan) 

Danca''dan çeviren: İsmail Aksoy', 'İki erkek var dünyada sürekli yoluma çıkan, ilki benim sevdiğim öbürü beni seven. İlki karanlık havsalamda oturan gecesel bir düşte, öbürü y...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sonsuz-uc-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık...', 'yalnizlik-ulvi-ziya-6xcgc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstesek de giremeyiz toz duman arasına...

Kitabımız merhemdir gönlümüzün yarasına...

Tabiatı seyrederiz,kâinatı okuruz; 

Boya îcâd ederiz bahtımızın karasına...

Dedikodulardan uzak,dinç kalan serimizdir....

Zevk bildik elemleri,kûşe-i uzlet bayram yerimizdir...

Cemaatta rahmet vardır,iyi biliriz; lâkin

Kalabalık boğar bizi, tenhâ yer hem-derdimizdir...', 'İstesek de giremeyiz toz duman arasına... Kitabımız merhemdir gönlümüzün yarasına... Tabiatı seyrederiz,kâinatı okuruz;  Boya îcâd ederiz ba...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalnizlik-297-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Sözü', 'hayat-sozu-i-smail-aksoy-dizz3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dümdüz çayırlardaki çiy gibi

Düşer hayat sözü

Hırıstiyanın hasta yatağına,

Umut bulutlarda,

Ve ölüme karşı büyürken avuntu

Ondan sonrası ilk hasat,

Kaybolur böylelikle

Ölümün bütün acılığı! 

Güneşin korunun ardında batması gibi

Denizde açık mavi,

Yaz akşamlarında,

Kuşlar cıvıldarken hafiften,

Gider bu ruh dinlenmeye,

Tatlı bir gülümseyişle yolunda

Duyumsar sözünde

Bizimledir Tanrı Baba.

Bedenlerimizin hafif ürpermesi gibi,

Yaz sabahlarının şafağında,

Parıldarken seher yıldızı

Ve müjdelerken yeni günü,

Yaz günü ağarırken

Beyaz sabah bulutlarının arasında,

Ki hayatın ışığıyla birlikte

Biter soğuktan ürpermemiz.

(1860) . 

N.F.S.Grundtvig (1783-1872, Danimarka)

Danca''dan çeviren: İsmail Aksoy', 'Dümdüz çayırlardaki çiy gibi Düşer hayat sözü Hırıstiyanın hasta yatağına, Umut bulutlarda, Ve ölüme karşı büyürken avuntu Ondan sonrası ilk...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hayat-sozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmem Birdaha', 'olmem-birdaha-ahmet-atmaca-8aey3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne hayalim kaldı nede bir gayem

Bedendeki candır bütün sermayem

Dert, çile, acıyla aldığım bu dem

Öldürmezse beni ölmem bir daha

Yorduğum yokuşları say teker- teker

Gece yalanlarsa, gün etmez inkar

Efkarımın üstüne ekle bir efkar

Öldürmezse beni ölmem birdaha

Geceler yoruldu günler yoruldu

Göz yaşım tükendi,gönlüm duruldu

Kırıldı kalemim darım kuruldu

Öldürmezse beni ölmem birdaha.', 'Ne hayalim kaldı nede bir gayem Bedendeki candır bütün sermayem Dert, çile, acıyla aldığım bu dem Öldürmezse beni ölmem bir daha Yorduğum yo...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Atmaca']::text[], 8.5, '{"poet":"Ahmet Atmaca","poet_slug":"ahmet-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olmem-birdaha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğaçlama Gemisi', 'dogaclama-gemisi-i-smail-aksoy-y8hqp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yakında ışıklı gecelerin geçecek zamanı

Ve yükselecek derin suların ardında karanlık

Ve dalga çalacak şimdi yalnızca

Boğazın sahili tarafından mırıldanan melodiyi.

Yakında yayacak kuş kanadını deniz üstüne

Ve kıracak dümeni uzak diyarlara

Yakında doğa yas içinde kalır gömütünde:

O zaman başka havalardan çalmalı.

Ama hâlâ yayılıyor yaz gecelerinin hâlesi

Deniz ve karanın üstüne o ışıklı kanatlar,

Ve hâlâ çiziyor yükseğe şafağın tanrısı adını

Orman ağaçlarının ardına, altın parmaklarıyla.

Ve hâla sürüklüyor gecenin rüzgârı teknemizi

Sessiz yollar boyunca sessiz bir gezgin

Ve hâlâ şarkı ve nağme var yedeğimizde,

Biz, ki sabah hâlesinin altınına sahibiz.

Şafağın tanrısına adıyoruz şarabın alazını,

Şaraptan sonra bir ilahi sana

Ve vuruyor saatimiz bizim, ver bize bir ölüm

Shelley’in Toscana Denizi’nin dalgalarındaki gibi! 

Holger Drachman (1846-1908, Danimarka) 

Danca''dan çeviren: İsmail Aksoy', 'Yakında ışıklı gecelerin geçecek zamanı Ve yükselecek derin suların ardında karanlık Ve dalga çalacak şimdi yalnızca Boğazın sahili tarafınd...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dogaclama-gemisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reklam Gemisi', 'reklam-gemisi-i-smail-aksoy-3y9nb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gemi kırıyor dümeni

kararan limana doğru.

Megafonu bir selâm kükrüyor kente,

elektrikli projektörleri saçıyor havaya beş parçalı

ışığını

bir kuyruklu yıldızın kuyruğu gibi

ve alazla yazıyor bulutlara:

BıR FORD ARABASI SATIN AL

................................

................................

Otto Gelsted (1888-1968, Danimarka) 

Danca''dan çeviren: İsmail Aksoy', 'Gemi kırıyor dümeni kararan limana doğru. Megafonu bir selâm kükrüyor kente, elektrikli projektörleri saçıyor havaya beş parçalı ışığını bir...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/reklam-gemisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuşma Benimle', 'konusma-benimle-i-smail-aksoy-gh3i9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sessizce

öylece-

söyleme! 

çok çok özenerek

gitmeliyim,

bir şey bulacaksam eğer-,

ve yalnız başıma gitmeliyim,

bulacaksam bir şey eğer-

şimdilik bir şey bulmadım daha-

ne evimi

ne sevgilimi

ne de tarlalarımı

bulabildim-

henüz varmadığım

bir yerlerde olmalı-

şimdiden epey yol aldım-

belki çok yolum

var daha gidecek-

ve yalnız başıma gitmeliyim

ve öyle korkunç özenle

gitmek zorundayım,

bir şey bulacaksam eğer-

benim de bir

yerim olmalı ama-

bir yerlerde bir evim olmalı-

biliyorum ki,

evim ve tarlalarım var

bir yerlerde-

sevdiğim sürekli beklemez ki-

şimdiden epey yol aldım-

söyleme bana-

eğer çok uzun yolum varsa daha gidecek,

belki de çok geç olur-

söyleme- sus-! 

bulmak zorundayım

kendi evimi-

Gustav Munch Petersen (1912-1938, Danimarka) 

Danca''dan çeviren: İsmail Aksoy', 'sessizce öylece- söyleme!  çok çok özenerek gitmeliyim, bir şey bulacaksam eğer-, ve yalnız başıma gitmeliyim, bulacaksam bir şey eğer- şimd...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/konusma-benimle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açıklama (Morten Nielsen)', 'aciklama-morten-nielsen-i-smail-aksoy-n8wgo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dürüst olmadığımı söylüyorsun.

Senden daha dürüstüm ben.

Senin yavaş yavaş aşındırdığın

Bağlılığa bağlıyım ben.

Çok uçucu olduğumu söylüyorsun.

Bak bu doğru, ve öyle olmalıydım da.

Taşıyacak bir şey vermediğinden,

Zayıf düştü ellerim.

Başka biriyle boğuştun

Ve biraz yalnız ve yorgundun.

Bense durdum ağırlığın yanında

Çok da kolay buldum bunu.

Ve bu utku senin işte,

Ve bu olağanüstü güç:

Ki her şey bitti. Ve hiç bir şey

Sonuna kadar sürüklendi.

Morten Nielsen (1922-1944, Danimarka)  

Danca''dan Çeviren: İsmail Aksoy', 'Dürüst olmadığımı söylüyorsun. Senden daha dürüstüm ben. Senin yavaş yavaş aşındırdığın Bağlılığa bağlıyım ben. Çok uçucu olduğumu söylüyors...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aciklama-morten-nielsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işık Var Orada, Ve Bekliyor Biri', 'isik-var-orada-ve-bekliyor-biri-i-smail-aksoy-fxu9q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Işık var orada, ve bekliyor biri.

Ama benim bekleme sürem dolmadı henüz.

Eğer verdiysem şimdi sana,

Boştu ellerim.

Yağmurun arasından düşer yüzüme

Güzelim damlalarca evrenin ışığı –

Ne ki döner geri bütün duyular yeniden

Çağıran bir sese doğru. 

Ve çağırır o ses - ve bağırır,

Ve yağmurun arasında kaybolmuştur senin ışığın.

Kaybolmamışcasına yapayalnız olmalıyım daha

Bir özlemle.

Işık var orada, ve bekliyor biri.

Yapayalnızım bir sesle birlikte boşlukta.

Bekleyen acımasızdı bana karşı,

Gelirsem eğer bekleme sürem dolmadan daha.

Morten Nielsen (1922-1944, Danimarka) 

Danca''dan çeviren: İsmail Aksoy

Çevirenin notu: Morten Nielsen, Danimarka’nın Alman işgalinden kurtulması için çalışan ”Direniş Hareketi”nde yer almıştır ve bir kaza kurşunu sonucu hayatını kaybetmiştir.', 'Işık var orada, ve bekliyor biri. Ama benim bekleme sürem dolmadı henüz. Eğer verdiysem şimdi sana, Boştu ellerim. Yağmurun arasından düşer ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/isik-var-orada-ve-bekliyor-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İflas Ettik', 'i-flas-ettik-nurcemal-ozturk-3q6eh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sermayeyi tükettik

Mutluluk dükkânında

Kepenkler indi tek tek

İflas ettik malesef.

Hayal kuramaz olduk

Mutluluklara dair

Gönlümüz küf bağladı

İflas ettik malesef.

Birbirimizi yedik

Saçma bahanelerle

Düşmanlığa yenildik

İflas ettik malesef.

Kin ve nefret büyüttük

Gönül bahçelerinde

Güzellikler kurudu

İflas ettik malesef.

İnsanlığı unuttuk

vahşiler gibi olduk

Bak ne hallere kaldık

İflas ettik malesef.', 'Sermayeyi tükettik Mutluluk dükkânında Kepenkler indi tek tek İflas ettik malesef. Hayal kuramaz olduk Mutluluklara dair Gönlümüz küf bağlad...', ARRAY['Türk Edebiyatı','Şiir','Nurcemal Öztürk']::text[], 8.5, '{"poet":"Nurcemal Öztürk","poet_slug":"nurcemal-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iflas-ettik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Öğretileri', 'yalnizlik-ogretileri-cetin-sancar-eny5p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'derin bir özlemdi kimliğim! 

sorgulandığımda kaybolan,

asık oldugunda kacan...

kacan yalnızlıktı bende! 

yürüyen ise umutsuzluğum...

sancıydı,

bir o kadar tatsız tebessüm...

sana neyi anlatsamda gitsen? 

gözlerimin kenarında biriktirdiğim

SEN le dolan öğretilerimin yarımlığını mı? ? 

sessiz bir özlemdi aksam! 

renkleri öldüren,

yalnızlıkla sevişen...

kacan SEN din bende! 

yürüyen ise duygusuzluğum...

acıydı,

bir o kadar güzel iklim...', 'derin bir özlemdi kimliğim!  sorgulandığımda kaybolan, asık oldugunda kacan... kacan yalnızlıktı bende!  yürüyen ise umutsuzluğum... sancıyd...', ARRAY['Türk Edebiyatı','Şiir','Çetin Sancar']::text[], 8.5, '{"poet":"Çetin Sancar","poet_slug":"cetin-sancar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yalnizlik-ogretileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatır Saymak Dostluğa Yatırım', 'hatir-saymak-dostluga-yatirim-necmi-unsal-yf70o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir fincan kahvenin kırk yıl hatırı varmış.

Hatır saymayana bu bir utanç, bir  armış.

Hep ölçülü olmak seviyeden kararmış.

Ölçüsüz sevgi ve  buğuz  akla zararmış.

Kahveyi içelim bende, olsun hatırım.

Hatır saymak dosta, dostluklara yatırım.

Senden dostluk kalır, benden şiir satırım.

Senin kahveni ben çağlara anlatırım.

13 Temmuz 2004 Salı, Danimarka-Koge 01.48 *6+7', 'Bir fincan kahvenin kırk yıl hatırı varmış. Hatır saymayana bu bir utanç, bir  armış. Hep ölçülü olmak seviyeden kararmış. Ölçüsüz sevgi ve ...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hatir-saymak-dostluga-yatirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akçaağaç (Thorkild Björnvig)', 'akcaagac-thorkild-bjornvig-i-smail-aksoy-qx4nt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Haylidir duruyor, şimdi akçaağaç sapsarı; 

her sabah sis, soğuktan bir demet

altında yaprak ormanının bütün gün,

hınzır soğuk bir nem,

yapışkan, kemirgen, karanlık çökerken,

tadı gibi demirin dil üzerinde,

yaprakları gevşeten bu gece ayazı

ve sapları aşındıran - erkenden gene

bir kırağı örtüsü o katı çimde

ve güneş önünde çarçabuk yükselen buğu,

garip ve havadar her şey, ayrılıkla

yanar durur. Acısız ayrılık,

üzüntüsüz mis kokulu özgürlük

ve ardından hiçlik, plansızlık - 

Duyduğumda bir sığırcık sürüsünü

Bir çok rüzgârın hiddetli seğirtmesi - 

Bir anda duruyor o sarı ağaç

kıvançla tutuşmuş! Bu kuşlar,

ağaca değgin değil,

fakat kirece ve balçığa ve havaya ve renge değgin

ve hakkında bir şey bilmediğimize: sevince

ne ki dolduruyorlar ağacı

isterik çığlıklarla, dinle ağaç şarkı söylüyor,

ateşten diller, ateşten gırtlaklar,

sesten depremler, - bir mutluluk

ki alazlanıyor hava - ayrılık, ayrılık; 

fakat acı olanaksız burada,

kulaktaki bu vahşi çığlıkla

bilirim ki sevinç hayatta kalır,

hadi benim sevincimi de al - uzak ihtimal

ihtiyacınız olması fakat sevinç

toplanmalı bütün coşkunlukla

kıskançlıkların solduğu

kıskançların, farkın ve kinin yok olduğu orada,

çünkü herkes bunda, - bölen

bölünmeyen coşkun sevinçte

bu yer var; bundan sonrası da hayat

Çünkü kimse değildir sahibi sevincin, ben

değilim, ağaç da değil, kuş da,

fakat galiba ağaç, kuş biraz daha fazla hâlâ - 

sarı ağaçtan metalik bir karanlık,

başka bir ağaç tutuşuyor şimdi,

tutuşuyor dışardan - çok sessizce

yanıyor hâlâ akçaağaç,

kendi sessizliğiyle o denli dolu ki,

içsel bir güneşten, ki sallanıyor tacı -

tamamlanmışlık, açıklık, sessizlik fırtına öncesi,

kasım karanlığı, kış dinlenişi

ve topraktaki yaprakların günışığı gibi ışıldadığı

sonraki soğuk akşamlar öncesi

yayılmış altına ağacın,

güzelim bir günışığı: bende ve

alnımı dayadığım ağaçta, karanlık büyürken

ve büyürken yürek, güneşle dolmuş.

Thorkild Bjørnvig (d. 1918, Danimarka) 

Danca''dan Çeviren: İsmail Aksoy', 'Haylidir duruyor, şimdi akçaağaç sapsarı;  her sabah sis, soğuktan bir demet altında yaprak ormanının bütün gün, hınzır soğuk bir nem, yapış...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/akcaagac-thorkild-bjornvig-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alman Askerleri (İlkyaz 1945) - [Tove Ditlevsen]', 'alman-askerleri-i-lkyaz-1945-tove-ditlevsen-i-smail-aksoy-vjsnc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yorgun Alman askerleri

geçiyorlar yabancı bir kentten

alınlarında ilkyaz güneşiyle; 

bakmıyorlar birbirlerine.

Yorgun, düşünceli, ürkek,

gidiyorlar yıkıma doğru

yabancı bir kentin ortasından.

Nefreti öğrenmiştik onlardan,

anlamıyor kimse onların dillerini,

ve bakışlarıyla  karşılaştığında

kapalı bir kitap oluyor bizim bakışlarımız.

Alman askerleri, bitkinler,

arkadaş mı acaba onlar,

yoksa bir başına mı herkes

ki konuşur dilini kendince? 

En son ilkyazda gidiyorlar,

yağmurda ve fırtınada gelmişlerdi buraya-

o zamanlar daha az kötüydü,

çirkin gri üniformaları.

O zaman tiksinmiştik daha çabukca

kötü bulduğumuz her davranışlarını,

merak içindeyiz şimdi,

acaba bulunur mu düşünceli bir ruh aralarında? 

Dilleri sert ve hızlı 

yorgun Alman askerleri,

yürürler şimdi yıkık ve yabancı bir kentte,

- yavaşca ölür gider sesler

bizi ve çizmelerimizi çiğneyen

sürüklenen çizmelerinden.

Öldürümlerden ve korkudan yaşlanmış

yorgun Alman askerleri.

Belki de ister gözleri

bir yıldızın izini izlemeyi,

belki de ister usları

ilkbaharın tatlı serinliğinden

bir ezgi yakalamayı,

bitmeden daha herşey? 

Ne ki yakındır titreyen Danimarka’yı

özenle özgürleştirmemiz,

ve yakındır gitmesi çalıntı çizmelerin

geçmesi ölümün son kez toprağımızdan,

- ve yakındır yalnız nefretin kalması geriye

altı yıllık yokedici savaştan.

Derine saklanmalı şimdi temizlenmiş silah

Danimarka toprağında,

- herkesin bıçağı hazır öldürmeye,

alınır çünkü kanın öcü kanla -

ne ki bitkin Alman askerleri

yürürler karanlık şafakta,

ortasında en son ilkbaharın,

ortasında yabancı bir kentin.

Tove Ditlevsen (1918-1976, Danimarka) 

Danca''dan Çeviren: İsmail Aksoy', 'Yorgun Alman askerleri geçiyorlar yabancı bir kentten alınlarında ilkyaz güneşiyle;  bakmıyorlar birbirlerine. Yorgun, düşünceli, ürkek, gid...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/alman-askerleri-ilkyaz-1945-tove-ditlevsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Ve Çile', 'ask-ve-cile-nurcemal-ozturk-v89i9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ateşine yanmayanlar ne bilsin

Aşk dediğin ne menem bir çiledir

Cilvesine kanmayanlar ne bilsin

Aşk dediğin ne menem bir çiledir.

Bülbüllerin intizarın artırır

Gonca gülü kederinden soldurur

Âşıkları yâr yâr diye öldürür

Aşk dediğin ne menem bir çiledir.

Leylâ için çöle attı mecnunu

Ferhat aşktan dağa vurdu yolunu

Allah hayır etsin bunun sonunu

Aşk dediğin ne menem bir çiledir.', 'Ateşine yanmayanlar ne bilsin Aşk dediğin ne menem bir çiledir Cilvesine kanmayanlar ne bilsin Aşk dediğin ne menem bir çiledir. Bülbüllerin...', ARRAY['Türk Edebiyatı','Şiir','Nurcemal Öztürk']::text[], 8.5, '{"poet":"Nurcemal Öztürk","poet_slug":"nurcemal-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-ve-cile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sivrisinek Şarkısı (İvan Malinovski)', 'sivrisinek-sarkisi-i-van-malinovski-i-smail-aksoy-pg88d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bu düş haziran gecesinde

ev kiraz ağaçlarının köpüğüyle göçmüş

körfezin aynasından daha narin bir çanın altında

kuşların çağıldayan dalgalarına

bir çalıkuşu yumurtası benim uykum: kireçten

bir duvar ve dağınık ılgım

titrer karanlıkta dikilmiş o beyaz orak

ve sessizce doğrar görünmez bir gaga

rüzgârlı ve tuzlu aynanın zarında

birazdan çatlar her şey

İvan Malinovski (1926-1989, Danimarka)

Çeviren: İsmail Haydar Aksoy', 'bu düş haziran gecesinde ev kiraz ağaçlarının köpüğüyle göçmüş körfezin aynasından daha narin bir çanın altında kuşların çağıldayan dalgalar...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sivrisinek-sarkisi-ivan-malinovski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düet-2-Hep Bir Eksikle', 'duet-2-hep-bir-eksikle-vedat-koparan-sg2d8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hep bir eksikle,kırıklarla başlarım yaşama 

nedir diye sorulmasın gizlenirim kuytulara

saklarım söyleyemem canda can dostlarıma

söylesem bilirim düşer payımdan onlarada

vay ki vay

ben ki kırgın mıyımdır aslında hayata

hayat yüreğimde koskocaman pranga 

kilitsiz/sualsiz/ cesur ama

dimdik kalabilmek hayatta

işte bu sen

işte bu ben

işte bu biziz hayatın ta ortasında

yürek yanar/köz olur, bizde söz candan olur

tortusu kumu dibe çökende akar gider sel olur

güneş her gün doğar doğmasına 

gerçek ısınma uğramaz buraya

ekseninde insana mavi pusulamız

erteler ısıtmalarını yüreklerde

hep kutuptadır sanki yaşamımız

can yakar şimal rüzgarı gecede

an gelir eser fırtınalar çağlar içdenizlerimizde

çekilir karanlığa perde varılır aydınlık geleceğe 

Sezer Nişancı-Vedat Koparan 02.11.2005', 'hep bir eksikle,kırıklarla başlarım yaşama  nedir diye sorulmasın gizlenirim kuytulara saklarım söyleyemem canda can dostlarıma söylesem bil...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/duet-2-hep-bir-eksikle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neler Gördü Bu Dünyâ...', 'neler-gordu-bu-duny-ulvi-ziya-mgw65', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nice gönül erleri arz''a duhul ettiler...

Mânada birer arslan,sarsılmaz yiğittiler...

Mertliğin,adâletin timsaliydi her biri; 

Azraille hoşsohbet ede ede gittiler...

Çok nâmert geldi geçti zorbalıkla birlikte...

Ne mertlikte gözleri; ne yiğitlik,erlikte...

Mutluluğu,huzuru sürdüler yeryüzünden; 

İnatla yarıştılar iblisle,liderlikte...

Kim kaldı ayaküstü,hepsi toprak oldular...

Şeddad,Nemrut,Firavun; düşün hele,noldular? ...

Şehri yakıp keyfeden Neron hani,nerede? ...

Cengiz,Hulâgû,Haccac; yerlerini buldular...

Rahatlık ver,neşe saç,kâbus yaratıp durma...

Özgür olan ruhlara prangalar hiç vurma...

Durmadan sallanıyor,dünyâ geniş bir elek; 

Kazık çakar dururum diye hayaller kurma...

Bildiğimi okurum deyip aldanma sakın...

Azrail gün sayıyor,ölüm herşeyden yakın...

Çalış adın dillerde hep rahmetle anılsın; 

Kukla libasını at,adam kisvesi takın...', 'Nice gönül erleri arz''a duhul ettiler... Mânada birer arslan,sarsılmaz yiğittiler... Mertliğin,adâletin timsaliydi her biri;  Azraille hoşso...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/neler-gordu-bu-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Disjecta Membra (İvan Malinovski)', 'disjecta-membra-i-van-malinovski-i-smail-aksoy-9s2f8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bakış arıyor bir barış gezegenini ne ki hiç bir

birlik en sonuncu hiç bir sınır kımıldatılmaz değil

sonsuzda bile bölünür sevdalılar köklerine dek

sadece ateş yatağına aç girmez

yemişin her bir parçası dışlar ötekini

ve sevinçten geberir her biri kendince

ve göz atarsın panikten ve kandan bir mahzene

mehtap ansızın bırakırken maskeyi düşsün diye

her şeyin aşırı uçlardan oluştuğu

hiç bir şeyin kalıcı olmadığı

alazlı ısırganotu ve tozdan bir güneşin

metallerin birliğinin bedeli olduğu yerde ve hiç bir şey

olduğu yerde durmuyor acından ve hasretinden başka

saman damların altındaki göçmen suların yanında

ne çözüm var ne de denge

hiç bir mesken de yok dünyada

ne ki bu dağılmış kan ölmek istemiyor

ve kemiğe sarılmış bu et bükülmez 

İvan Malinovski (1926-1989, Danimarka)

Çeviren: İsmail Haydar Aksoy', 'Bakış arıyor bir barış gezegenini ne ki hiç bir birlik en sonuncu hiç bir sınır kımıldatılmaz değil sonsuzda bile bölünür sevdalılar kökleri...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/disjecta-membra-ivan-malinovski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diktonius (İvan Malinovski)', 'diktonius-i-van-malinovski-i-smail-aksoy-b4pa1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ama yangından sonra

nerdeyse heceleyebilir

insan kendini çimenin damarlarına

bir kaç gün yaşayan sineğin yolu

örümcek ağı

ne de varsıl bir yıkım

ne güzel bir nefret

(orda çiğnenmiş kağıt yuvalarında

oturuyor onlar

anlamıyor onları ölüm

utanç gelip yitiriyor

en basit ölçüsünü)

evet tanıyorum bunu

caddedeki bu çığlığı

açlığın ateş atılımlarını

sıçramaya hazır

bu duvarlara doğru

bu çirkin dünya

şimdi ne güzel ne temiz en sonunda

senin şiirlerinin sıcak küllerinde.

İvan Malinovski (1926-1989, Danimarka)

Çeviren: İsmail Haydar Aksoy', 'Ama yangından sonra nerdeyse heceleyebilir insan kendini çimenin damarlarına bir kaç gün yaşayan sineğin yolu örümcek ağı ne de varsıl bir y...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/diktonius-ivan-malinovski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Yine...', 've-yine-adem-tok-qlvqp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yine yankılanıyor bağırışlarınız

tel örgülerin

taş duvarların

demir parmaklıkların ardından

yine geliyor bağırışlarınız

meydanlardan

çınlıyor kulaklarım

duyuyorum

tüylerim diken diken

yine görüyorum

şafakların dalgalanan

kıyılarına kalkan dumanı

kor alevler sıçrıyor 

kurumlu yüzlere

yine karanlık çöküyor

güneşse avluya düşmeden

hücreyi aydınlatmadan batıyor

ve yine bizler

halaya durup

türküler söylüyoruz

hayasız iklimlerde

                                                              (21.03.01) 

                                                               f tipi hapishane TEKİRDAĞ', 'yine yankılanıyor bağırışlarınız tel örgülerin taş duvarların demir parmaklıkların ardından yine geliyor bağırışlarınız meydanlardan çınlıyo...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ve-yine-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erenler Kapısı', 'erenler-kapisi-nurcemal-ozturk-e060o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bunca günahımı sırtıma vurup

Ben hangi kapıya yalvaracağım

Elpençe bağlayıp,huzura durup

Ben hangi kapıya yalvaracağım.

Günahlar bir yığın olmuş sırtımda

Secdeden eser yok kara alnımda

Kim bana yer verir ki divanında

Ben hangi kapıya yalvaracağım.

Bin tövbe etsem de az gelir bana

Feryadım yayılmış bütün cihana

Varıp el açayım hangi sultana

Ben hangi kapıya yalvaracağım.

Ses verin sesime cümle erenler

Allah''a dost olup,O''na varanlar

Çevrilmezmiş kapınıza gelenler

Ben hangi kapıya yalvaracağım.

Duamı reddetme,kabul et Rabbim

Düşmüşüm günaha ne olur halim

İmdâda yetişsin bir velî kulun

Ben hangi kapıya yalvaracağım.', 'Bunca günahımı sırtıma vurup Ben hangi kapıya yalvaracağım Elpençe bağlayıp,huzura durup Ben hangi kapıya yalvaracağım. Günahlar bir yığın o...', ARRAY['Türk Edebiyatı','Şiir','Nurcemal Öztürk']::text[], 8.5, '{"poet":"Nurcemal Öztürk","poet_slug":"nurcemal-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/erenler-kapisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Sen Varsın,Ne İzin Var Duvarda', 'ne-sen-varsin-ne-i-zin-var-duvarda-ali-osman-yilmaz-npy4b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Daraldıkça yüreğim,

Bir kasvet sardı ki,

Sormayın gitsin.

Uzanmışım divana,

Gözlerim duvarlarda,

Senden kalan,

İzleri aramakta.

Nafile artık,

Ne sen varsın,

Ne izin kalmış duvarda.

Böyle sensizliğe hayıflanırken,

Dişlerim kenetlenmiş öfkeye,

Gecenin bir vakti,

Vurdum kendimi kırlara.

Aklımda yine sen varsın,

Sen olmayınca yanımda,

Bu yürek,bu gönül,sensizliğe,

Nasıl dayansın a gülüm.

Kaldırıp başımı göklere,

Dişlerim kenetli,

Kaşlarım çatık,

Yıldızlara çevirdim,gözümü,

Karanlık gecenin koynundayım,

Pırıl pırıl parlıyor,

Gökteki yıldızların,

Bana gülümseyen yüzü.

Bir umut kıprıdadı içimde,

Ya Allah,Ya settar diyerek,

Gökyüzüne,demir çapa niyetine,

Fırlattım umudumu,

Yarın yine geleceğim,

Göklere bıraktığım,

Umudu vira edip,

Hayaline yelken açarak,

Yine seni düşleyeceğim.', 'Daraldıkça yüreğim, Bir kasvet sardı ki, Sormayın gitsin. Uzanmışım divana, Gözlerim duvarlarda, Senden kalan, İzleri aramakta. Nafile artık...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ne-sen-varsin-ne-izin-var-duvarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaprak Mevsimi', 'yaprak-mevsimi-adem-tok-iitar', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'cemre düştü üç göğe

çıktı yuvasından kumrular

atlas yandı

eridi yüceltilerdeki karlar

bu zaman:açlıkları bastırma

emiyor özsuyunu yeşil

damarlar canlanıyor

önce tomurcuk doğanın yasası

sonra serpiliş

açılarak demet demet

varılmayan köye

çatlar zemheriyi atlatan kabuk

masumiyet çıkar özgeliğinde

hava kenger kokar...

                                                                  (13.04.05) 

                                                                     sarıgazi', 'cemre düştü üç göğe çıktı yuvasından kumrular atlas yandı eridi yüceltilerdeki karlar bu zaman:açlıkları bastırma emiyor özsuyunu yeşil dama...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yaprak-mevsimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yazın Anısına (İvan Malinovski)', 'bir-yazin-anisina-i-van-malinovski-i-smail-aksoy-ec1fr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'her şey olanaklı sanılır ağustos gibi geç bir zamanda

hayat bile kanın kana sığınması bile

hiç bir midye süngülerle açılmadı

hiç bir resim izlemedi bizi gözkapaklarımızın ardına dek

katırtırnağı çiçekleri hışırdadı sarı güneş altında

ve kuşku fırlatmayı düşündü sargı bezini

arasıra getirdi rüzgâr her zamanki gibi

henüz sıcak külden bir mektup: ne ki

yoktu güvercinlerin bildirebileceği önemli bir şey

duvar sıvaları ya da ufuktaki yüksek basınç hakkında

belki daha iyi biliyordu uçurtma gölgeleri duyargaları

belki kendimiz görmeliydik bunu: aralıksız

izledi yakıcı bir göz umudumuzu ve yüreksizliğimizi

İvan Malinovski (1926-1989, Danimarka)

Çeviren: İsmail Haydar Aksoy', 'her şey olanaklı sanılır ağustos gibi geç bir zamanda hayat bile kanın kana sığınması bile hiç bir midye süngülerle açılmadı hiç bir resim i...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-yazin-anisina-ivan-malinovski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oynayın,Oynayın Kızlar.', 'oynayin-oynayin-kizlar-ali-osman-yilmaz-g0mfs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oynayı Oynayı gelin kızlar,

Sallayı sallayı gelin kızlar,

Çalkayı çalkayı,oynayın kızlar,

El ele verip,halkayı sarın kızlar,

Oynayı,oynayı halayı kurun kızlar,

Geliyor düğün alayı,oynayın kızlar,

Vursun davullar,çalsın zurnalar,

Şenlensin düğün alayı, kızlar.

El ele verin kızlar,

Öte köyden duyulsun sazlar,

Sizi seyreden gençlerin,

Vallahi inanın, yürekleri sızlar.', 'Oynayı Oynayı gelin kızlar, Sallayı sallayı gelin kızlar, Çalkayı çalkayı,oynayın kızlar, El ele verip,halkayı sarın kızlar, Oynayı,oynayı h...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/oynayin-oynayin-kizlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancılaştırılmışlar (İvan Malinovski)', 'yabancilastirilmislar-i-van-malinovski-i-smail-aksoy-83nbj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yürüyorlar caddede geliyorlar ve gidiyorlar

Bilmiyorlar birbirlerine baktıklarını

Birlikte yatıyorlar zaman öldürmek için

Bilmiyorlar mağazalarda bir şeyler satın aldıklarını

Eve gidip kahve içiyorlar hepsi bu işte

Çok alçakgönüllüler bilmiyorlar

Çok alçakgönüllü bir sayıda çarpı işareti oluşturuyorlar

Çok alçakgönüllü bir sayıdaki seçim pusulalarında ekmek-karnelerinde

Kendilerine yetiyor bu geliyorlar ve gidiyorlar

Torna tezgahlarındalar bir çamaşır ipinin yanındalar

Görmüyorlar her gün yapı iskelesininn yanında durduklarını

Dilsiz onlar ayrık bakıyorlar gökyüzüne

Giysileri içinde oldukça şıklar yürüyorlar caddede

Nerdeyse her şeyleri var açıklar her bir şeye

Geliyorlar ve gidiyorlar bir öyküleri yok onların

İz bırakmıyorlar yok gölgeleri

Renkleri orman toprağına düşen kurumuş yaprakların renkleri

Kumun ya da küçük kumul hayvanların renkleri gibi

Düşünürler düşünmesine ne ki çoğunlukla yanlış

Duyumsadıkları çoğunlukla başkalarının istedikleridir

Kendilerine ve başkalarına yabancılaşmışlar

Nerdeyse yaşamıyorlar geliyorlar ve gidiyorlar

Birbirlerine satıp alıyorlar alıp satıyorlar birbirlerini

Birbirlerini öldürebilirler zaman öldürmek için

Her şey için kullanılabilirler bu onların suçu

Ne ki birileri suçsuz bulunacaksa gene de onlardır

Dilsizler onlar bilmiyorlar ki sürekli konuştuklarını

Yürüyorlar caddede yakışıyor giyitleri onlara

Geliyorlar ve gidiyorlar çok az çıkıyorlar gazetelere

”Bir çeyrek milyon düştü bugün” dendiğinde onlardır bu

Bilmiyorlar birbirlerine çok yakın yürüdüklerini

Seçim ya da Pazar isimleri altında yürüyorlar

Ne ki bilmiyorum haddinden çok fazla mı yoksa yeterinceler mi

Oltaya takılmış yemle besleniyorlar

Bak şuradaki bakkalda duran şeye görmüyorlar kancayı

Bak şuradaki mağazalarda duran şeylere yetiyor bu onlara

Bilmiyorlar eve gidip kahve içtiklerini

Kimse düşlemiyor onlara karışmaya

Çok uzaktalar başka bir dünya emmiş onları

Ayrılmışlar ne ki kim tarafından bilmek isterdim

Geliyorlar ve gidiyorlar düşündüklerinden daha güçlüler

Her halikârda onlardır koruyan ölüm sıcaklığını ve leş kokusunu

Belki hiç duymamışlardır bunu ne ki işte böyle bu

İz bırakmıyorlar gölgeleri yok

Her bir şey için doğabilirler

Her bir şey için kullanılabilirler bir şeyler yanlış bunda

Dünyaya getirilirler yürürler bir zaman caddede

Pencere pervazında otururlar bir zaman sonra çokca uyurlar

Yakılırlar ya da gömülürler

Ya da boğulurlar suda bir kazada

İşte bütün bunlar kast edilmiştir

Yaşayıp ölürler bir hayat yaşamadan

Geberirler gezip görmeden

Harzen Malmö Mallorca belki yeterlidir onlara

Düşüneceklerine ve duyumsayacaklarına kendileri karar veremiyor

Sevinç tükenmek bilmez doğru değil mi

Hiç bir şansları yok başka birini tanımalarının

Belki ağlarlar ne ki asla sevinçten değil

En acılı sevinçlerinden koparılmışlar

Ne de şıklar giysileri içinde yürüyorlar caddede

Nerdeyse yaşamıyorlar geliyorlar ve gidiyorlar

Ve kimsenin yok onlara güveni.

İvan Malinovski (1926-1989, Danimarka)

Çeviren: İsmail Haydar Aksoy', 'Yürüyorlar caddede geliyorlar ve gidiyorlar Bilmiyorlar birbirlerine baktıklarını Birlikte yatıyorlar zaman öldürmek için Bilmiyorlar mağaza...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/yabancilastirilmislar-ivan-malinovski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgülü Mürekkep', 'surgulu-murekkep-adem-tok-p9spo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-ellerimi öpme yeşil olurum

maviyi sevdikçe-

sabah senle kalkıyorum

akşamım seninle

bir özlem türküsü tutturan dizelerim

çıktıkça denizden ağlar ağlar

çiy tutan aşkların kaymağında

tepe taklak açılan tutku tanelerinin çekirdeği

vurur gönlüm çatısına

katmer katmer açan sevda çiçeği

açma kirpiklerini ey şafağım

sende kalsın konuşan-konuşmayan hallerim

sende kalsın tüm anılar

taşırsın dahasını dev yüreğinle

sınırlarını bilirim

en koyu karanlık sökmenden önceki ansa

bahtiyarlığına az kaldı! 

çiy tutan aşkların kaymağında

tepe taklak açılan tutku tanelerinin çekirdeği

vurur gönlüm çatısına

katmer katmer açan sevda çiçeği

umuda yazıyorum şiirlerimi

nasıl ki suya iz düşerse

silme avuçlarını

bırak nemli kalsın...

                                                (11.04.04) 

                                                 f tipi hapishane EDİRNE', '-ellerimi öpme yeşil olurum maviyi sevdikçe- sabah senle kalkıyorum akşamım seninle bir özlem türküsü tutturan dizelerim çıktıkça denizden a...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/surgulu-murekkep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eleştirel Kurbağa (Benny Andersen)', 'elestirel-kurbaga-benny-andersen-i-smail-aksoy-3e8ed', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düzeltiyor aynadaki görüntüsünü ördek

özenle gece için.

Nihâyet gerçek bir dikkat

Saz şarkıcısının yalazlı sedaları için.

Sus pus olmuş millet ve dinliyor patikayı,

sokuyor sivrisinekler herkesi evde,

savarken su-sıçanı özenle

gürültücü palazları.

Yalnızca tıknaz genç bir kurbağa sakladı heyecanını

bir geğirtinin arkasına.

[”Ahenkli Yılanbalığı”ndan, (1960)  ]

Benny Andersen (d.1929, Danimarka)

Çeviren: İsmail Haydar Aksoy', 'Düzeltiyor aynadaki görüntüsünü ördek özenle gece için. Nihâyet gerçek bir dikkat Saz şarkıcısının yalazlı sedaları için. Sus pus olmuş mill...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/elestirel-kurbaga-benny-andersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahenkli Yılanbalığı (Benny Andersen)', 'ahenkli-yilanbaligi-benny-andersen-i-smail-aksoy-h5w3r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dövüyor külü güneş.

Derin hürmetle dönüyor salyangoz gözü:

amma da mesafe! 

Pikapta çalınacak plağın üstündeki

iğne gibi gürültüyle

konuyor ördek göle

Yılanbalığı terkediyor gölü gelmemek üzere bir daha.

Bir çok kez bakınıyor geriye hiddetle.

[”Ahenkli Yılanbalığı”ndan, (1960)   ]

Benny Andersen (d.1929, Danimarka) 

Danca''dan Çeviren: İsmail Aksoy', 'Dövüyor külü güneş. Derin hürmetle dönüyor salyangoz gözü: amma da mesafe!  Pikapta çalınacak plağın üstündeki iğne gibi gürültüyle konuyor ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ahenkli-yilanbaligi-benny-andersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat (Benny Andersen)', 'hayat-benny-andersen-i-smail-aksoy-a615v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hepimizin bildiği bir şey

hayat

çok şey getirir beraberinde

çok şey götürür beraberinde

hayata karşı bir garezim falan yok

benim için o kadar da doğal değil artık

şimdiye iyi hazırlanmalı

daha çok ısınma süresi gerekli her sabah

ne de olsa

bir koşu bütün bu her şey

ve sıçrayacağı zaman insan

ölesiye bitkindir

çaresi yok

kendi kendini kandırmaktan başka

dayanabilmek için

başlangıç çizgisine gitmeli

vermeli kendini saatlerce sürecek koşuya canla başla.

[”İçteki Melon Şapka” ’dan (1964)  ]

Benny Andersen (d.1929, Danimarka)

Çeviren: İsmail Haydar Aksoy', 'Hepimizin bildiği bir şey hayat çok şey getirir beraberinde çok şey götürür beraberinde hayata karşı bir garezim falan yok benim için o kada...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hayat-benny-andersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatunlar (Benny Andersen)', 'hatunlar-benny-andersen-i-smail-aksoy-lxhz5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Onlarsız olmaz

onlarla da biraz sıkıntılı

ama onlarsız hiç mi hiç olmaz

derisiz düşünülemez kıl dediğin

ateş olmadan tütmez duman

hatunlar olmadan da

bütün işler durur bir anda

onlarla da biraz sıkıntılı ya

ama onlar olmadan hiç mi hiç olmaz

nabız daha yavaş atar

katılaşır ense

kafayı çevirip bakacak kimse olmazsa

...

...

[”İçteki Melon Şapka” ’dan (1964)  ]

Benny Andersen (d.1929, Danimarka)

Çeviren: İsmail Haydar Aksoy', 'Onlarsız olmaz onlarla da biraz sıkıntılı ama onlarsız hiç mi hiç olmaz derisiz düşünülemez kıl dediğin ateş olmadan tütmez duman hatunlar o...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hatunlar-benny-andersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyilik Dinletisi (Benny Andersen)', 'i-yilik-dinletisi-benny-andersen-i-smail-aksoy-fs6j1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İşsiz kara karga

elleri ceplerinde zıplayıp duruyor

dibinde bir çakıl ocağının

Yaşlı köhne araba

tıngırdıyor iki paslı telle

uyumlu bir tınıyla.

Bir hakaretle havalanıyor karga

Ama köhne araba eğiliyor zorunda olmaksızın

uçurumun kenarına.

[”Mutfak Girişli Kamera” ’ dan (1965)  ]

Benny Andersen (d.1929, Danimarka)

Çeviren: İsmail Haydar Aksoy', 'İşsiz kara karga elleri ceplerinde zıplayıp duruyor dibinde bir çakıl ocağının Yaşlı köhne araba tıngırdıyor iki paslı telle uyumlu bir tını...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/iyilik-dinletisi-benny-andersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağımsız (Benny Andersen)', 'bagimsiz-benny-andersen-i-smail-aksoy-cvr7f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir düğmeye bastığımda

beyaz lamba sarılaşıp olgunlaşıyor.

Bilincimi etrafı lastikli

desteler halinde sakladığım

çekmeceyi açıyorum.

Bu odanın ağası benim.

Masamın altında kendi ayağım.

Bir sandalyeye toplu iğne yerleştirip

bir başkasına güvenle oturabilirim.

Pencere pervazında

bitkiler elele tutuşuyorlar

ve öyle bir ağ oluşturuyorlar ki

düşmüyorum pencereden aşağıya.

Ama gözlerimi kapattığım zaman

gördüğüm yüzler

yüzler

yüzler.

(1962) , [”Mutfak Girişli Kamera” ’ dan (1965)  ]

Benny Andersen (d.1929, Danimarka)

Çeviren: İsmail Haydar Aksoy', 'Bir düğmeye bastığımda beyaz lamba sarılaşıp olgunlaşıyor. Bilincimi etrafı lastikli desteler halinde sakladığım çekmeceyi açıyorum. Bu odan...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bagimsiz-benny-andersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yerde (Benny Andersen)', 'bir-yerde-benny-andersen-i-smail-aksoy-35bbo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sürükleyen kuşlar altında

hüsrâna uğramış köprüler altında

mağrur ağaçlar altında

arasında alaylı sandalye sıralarının

arasında ukala arkasayfaların

ayarlanmış merdivenlerin içinde ve dışında

bir yer bulmak için.

Çişe boğulmuş arka sokaklar arasından

yeni boğuntulara

kül mağaralarına

kendi kendilerini boğan dans çiftine

geriye yaslanmış bunaltıya

edepsiz mikrofonlara

her yerde var

anahtarlarla düşünen insanlar

duygularını arananlar

(kesinlikle eminim ki bu cebime

koymuştum)

gizli bir zenciyle karşılaşmış insanlar

iklimi mâhkemeye şikâyet eden insanlar

muhabbet kuşları hakkında her şeyi bilen insanlar

durmadan insanlar diyen insanlar

sevgilim biz sadece

ellerimizle birlikte olmalıyız

ama daha çok şeyimiz var

ellerimizden başka

ve öyleyse git

git verimi bereketli ilhâm-perileri arasından

kaypak parkların arasından

üzerinden rayların

üzerinden çatıların

üzerinden levhâların

her yerde

bulmak için bir yer.

[”Mutfak Girişli Kamera” ’ dan (1965)  ]

Benny Andersen (d.1929, Danimarka)

Çeviren: İsmail Haydar Aksoy', 'Sürükleyen kuşlar altında hüsrâna uğramış köprüler altında mağrur ağaçlar altında arasında alaylı sandalye sıralarının arasında ukala arkasa...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bir-yerde-benny-andersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutunabilse Göz Yaşlarıma', 'tutunabilse-goz-yaslarima-murat-berk-7n8z8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir güzel var usumda; 

Oturmuş iki kaşımın arasına,

Ağlayacağım

Tutunabilse göz yaşlarıma,

Ve sonra

Kaysa  dudaklarımın arasına,

Bir güzel var usumda; 

Tutunmuş saçlarıma

Sallanıyor 

Etekleri havada,

O güzel dizleri

Ne kadar da uyumlu ayaklarına,

Bir güzel var usumda; 

Boş ver dedim

Sağına soluna

Gözüne kaşına,

Bak yakın mı? 

Aklı aklıma.

Ahh ah! 

Evet yakın,

Ama  aradaki seneler

Olmasa…', 'Bir güzel var usumda;  Oturmuş iki kaşımın arasına, Ağlayacağım Tutunabilse göz yaşlarıma, Ve sonra Kaysa  dudaklarımın arasına, Bir güzel v...', ARRAY['Türk Edebiyatı','Şiir','Murat Berk']::text[], 8.5, '{"poet":"Murat Berk","poet_slug":"murat-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/tutunabilse-goz-yaslarima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şafak:Gündoğumu', 'safak-gundogumu-adem-tok-919pj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ne kaldı şurda gündoğumuna

ağırlaşsada adımları saatlerin

kapanmasada gözleri...

baykuş bakışlı şafakları

ne vakit bu kadar bekleye durdun

ne vakit erken kalkıp ranzandan

uyanışını seyrettin

bir bu vakit:

özlemin

endamı görülmemiş

ne kaldı şurda gündoğumuna

kar soluklu bir romanın ömrü

lekensiz çıkma yolculuğa

uzatırsın tahammülünü

nereye götürecek bu heyecanın

kaldığın dizeler hasret tutmuş

tirbuşon vurulmuş tozalmadan

bıraktığın şaraplara

dil dökmez gayrı kimseye balıkçına uğrayan

yalıçapkını; 

kursağına takılsada üç-beş lokmanın hayali

unutmadı zira vefasız ayrılığını

geda yine kelepçeli

ne kaldı şurda gündoğumuna

gelindiğinde imgelerin sonuna

bu ayak sesleri yabancı değil

tırmanırken kuzguncuğa

                                                             (16.04.04) 

                                                              f tipi hapishane EDİRNE', 'ne kaldı şurda gündoğumuna ağırlaşsada adımları saatlerin kapanmasada gözleri... baykuş bakışlı şafakları ne vakit bu kadar bekleye durdun n...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/safak-gundogumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Svante’nin Mutlu Günü (Benny Andersen)', 'svante-nin-mutlu-gunu-benny-andersen-i-smail-aksoy-2r6k2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Amma da sabah, bak! 

Güneş kızıl ve yuvarlak.

Banyoya gidiyor Nina’m.

Oturmuş peynir ekmek yiyiyorum.

Hayat insanın en kötü şeyi değildir

ve birazdan hazırdır kahve.

Çiçekleniyor çiçekler.

Köşede bir örümcek gidiyor.

Eğer varsa yeterince,

Uçuyor kuşlar sürü halinde.

Mutluluk insanın en kötü şeyi değildir

ve birazdan hazırdır kahve.

Çimen yeşil ve ıslak.

Arıların keyfine yok diyecek.

Ciğerler susamış havaya.

Ah, ne güzel mis hava! 

Sevinç insanın en kötü şeyi değildir

ve birazdan hazırdır kahve.

Duşun altında şarkı.

Mutlu olduğunu anlamalı.

Gökyüzü de öyle bir mavi ki.

Bense anlıyorum çok iyi.

Mutluluk insanın en kötü şeyi değildir

ve birazdan hazırdır kahve.

Nina geliyor işte

çıplak, öpüyor sevgiyle,

gidiyor odaya ıslak tenle

saçlarını düzeltmeye.

Hayat insanın en kötü şeyi değildir

ve birazdan hazırdır kahve.

[1972, ”Svante’nin Şarkıları”’ndan]

Benny Andersen (d.1929, Danimarka)

Çeviren: İsmail Haydar Aksoy', 'Amma da sabah, bak!  Güneş kızıl ve yuvarlak. Banyoya gidiyor Nina’m. Oturmuş peynir ekmek yiyiyorum. Hayat insanın en kötü şeyi değildir ve...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/svante-nin-mutlu-gunu-benny-andersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Svante’nin Siyah Şarkısı (Benny Andersen)', 'svante-nin-siyah-sarkisi-benny-andersen-i-smail-aksoy-0tvbj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bıktım kendimden ve diş dolgularımdan.

Top yekün karşıyım bedenime.

Neye yarar ciğerin giderek küçülmesi

kabarırken midesi adamın.

Kişisel nefretten çekiyorum

Keşke birazcık beğenebilsem kendimi.

Adımdan ve düşüncelerimden üzüntü duyuyorum.

Ve işe yaramıyor burda dua.

Neye yarar yüreğin çarpması

uğruna çarpacak kimsesi yoksa.

Kişisel nefretten çekiyorum

Keşke birazcık beğenebilsem kendimi.

Pişmanım geçmişimden ve hiç neşe yüzü

görmediğim doğumumdan ötürü.

Tabiat vallahi de müsrif davranmış olurdu

süzülmeseydim hemencecik.

Kişisel nefretten çekiyorum

Keşke birazcık beğenebilsem kendimi.

Bıktım elyazımdan ve sesimden

ve beynim tıkanmış kurşunla.

Ne de hoş olurdu unutsaydı insan

kim olduğunu ve doğsaydı yeni baştan

kurtulmuş olarak kişisel nefretten

ve birazcık da kendini beğenmişlikten.

[1972, ”Svante’nin şarkıları”’ndan]

Benny Andersen (d.1929, Danimarka)

Çeviren: İsmail Haydar Aksoy', 'Bıktım kendimden ve diş dolgularımdan. Top yekün karşıyım bedenime. Neye yarar ciğerin giderek küçülmesi kabarırken midesi adamın. Kişisel n...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/svante-nin-siyah-sarkisi-benny-andersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nina’ya Küçük Bir Şarkı (Benny Andersen)', 'nina-ya-kucuk-bir-sarki-benny-andersen-i-smail-aksoy-c56xb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim hayatım handiyse bir şişe değerinde

depoziti için bekliyorum burada,

sen yanımda olduğunda başka ama

sen hûri-melek.

Göbeğimin etisin, başıma bela olan

şişko işkembem,

hoşlandığını söylüyorsun kesin bir şekilde-

sen bana her zaman sevgili! 

Ama nasıl yaraşayım ki

senin fidan boyuna? 

İçiyorum ruhu bedeninde

geniş kalça-tasta.

Sen benim nefesim, oksijenim,

sen benim canımın canânı.

Bir alık yarışatı-çocuğuyum ben,

sana haddinden çok yakın duran.

Biliyorum, sürüp gitmez bu böyle.

Başka bir sevdiğin var senin.

Ama sen öğrettin bana sevdayı,

sen bana her zaman sevgili.

[1972, ”Svante’nin şarkıları”’ndan]

Benny Andersen (d.1929, Danimarka)

Çeviren: İsmail Haydar Aksoy', 'Benim hayatım handiyse bir şişe değerinde depoziti için bekliyorum burada, sen yanımda olduğunda başka ama sen hûri-melek. Göbeğimin etisin,...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/nina-ya-kucuk-bir-sarki-benny-andersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidelim', 'gidelim-erhan-demirci-fagc9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dostum Gökan ÖZTÜRK'' e ithafımdır... 

Yazacaksak doğruyu adaleti, 

Kalemi kağıdı al da gidelim... 

Çekeceksek varlığı sefaleti, 

Hakk'' ka uzanacak yolda gidelim... 

Besmeleyle çıktık biz bu sefere, 

Ne tesir eder imanlı nefere? 

Varacaksak mübarek bir zafere, 

Gel de çilekeş bir halde gidelim... 

Gardaşım dosdoğru bir insan ol da, 

Yüreğin yeşersin bir lâhza solda, 

Muvaffak olmak istersen bu yolda, 

Kılı kırk yaracak elde gidelim... 

Aslolan mânayı bulmakmış meğer, 

Gönlü bir hançerle yarmaya değer, 

Sevda türküsü yakacaksak eğer, 

Gönlü çalan sazda, telde gidelim... 

Gözlerde perde, kulaklarda yama, 

Eh hisset, hissedemiyorum deme, 

Elbet birgün kapılacağız ama, 

Günahları alan selde gidelim... 

Bana göre öyle çok ki yararın, 

Böyle iken dokunmaz hiç zararın, 

Benimle gelmekse en son kararın, 

Ama, sen orda kal; kal da gidelim... 

Söz- Müzik: Erhan DEMİRCİ', 'Dostum Gökan ÖZTÜRK'' e ithafımdır...  Yazacaksak doğruyu adaleti,  Kalemi kağıdı al da gidelim...  Çekeceksek varlığı sefaleti,  Hakk'' ka uz...', ARRAY['Türk Edebiyatı','Şiir','Erhan Demirci']::text[], 8.5, '{"poet":"Erhan Demirci","poet_slug":"erhan-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gidelim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsimler (En Son Biçiminde) - (Benny Andersen)', 'mevsimler-en-son-biciminde-benny-andersen-i-smail-aksoy-p0n80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çamaşır rüzgârda dalgalanır

Bebelerin yüzlerinde açar goncalar

Kızlara sataşılır

ve futbol oynanır

çünkü yazdır şimdi Danimarka’da.

Günler kasvetle düşer

Söz dinlemez okul çocukları.

Eskir giysiler

ve gözyaşları dökülür

çünkü sonbahardır bu Danimarka’da.

Boşanmalar. Ölümler. Romanlar.

Öksürük ve dondurulmuş tasarılar.

Burun damlar

Oluklar suya batar

çünkü kıştır şimdi Danimarka’da.

Çiçekler otlakta ve saksılarda.

Şölen bir çok dileğe dönüşür.

Çayırlar ekilir

ve anlaşılır şiirler

çünkü ilkbahardır şimdi Danimarka’da.

[1972, ”Svante’nin şarkıları”’ndan]

Benny Andersen (d.1929, Danimarka)

Çeviren: İsmail Haydar Aksoy', 'Çamaşır rüzgârda dalgalanır Bebelerin yüzlerinde açar goncalar Kızlara sataşılır ve futbol oynanır çünkü yazdır şimdi Danimarka’da. Günler k...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/mevsimler-en-son-biciminde-benny-andersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burada Dışarıda Bırakılamaz Bütün Umutlar (Benny Andersen)', 'burada-disarida-birakilamaz-butun-umutlar-benny-andersen-i-smail-aksoy-bnb71', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Burada zihnin bu kaygan

hiç bir söz ulaşmayan yokuşlarında

