INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köy', 'koy-octavio-paz-w9ntw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Taşlar zamandır 

Rüzgâr 

rüzgârın yüzyılları 

Ağaçlar zamandır 

insanlar taştır 

Rüzgâr 

döner kendisine ve batar 

taş günün içine 

Su yok burada gözlerinin parıltısı için 

Octavio Paz 

Türkçe’ye çeviren: İsmail Aksoy', 'Taşlar zamandır  Rüzgâr  rüzgârın yüzyılları  Ağaçlar zamandır  insanlar taştır  Rüzgâr  döner kendisine ve batar  taş günün içine  Su yok b...', ARRAY['Türk Edebiyatı','Şiir','Octavio Paz']::text[], 8.5, '{"poet":"Octavio Paz","poet_slug":"octavio-paz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/koy-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tersine Çevrilebilir', 'tersine-cevrilebilir-octavio-paz-oq2ud', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzayda 

ben 

kendi içimdeyim 

uzay 

dışımda benim 

uzay 

hiç bir yerde 

ben 

kendi dışımdayım 

uzayda 

içinde 

uzaydır 

onun dışı 

hiç bir yer 

ben 

uzaydayım 

vesaire 

Octavio Paz 

Türkçe’ye çeviren: İsmail Aksoy', 'Uzayda  ben  kendi içimdeyim  uzay  dışımda benim  uzay  hiç bir yerde  ben  kendi dışımdayım  uzayda  içinde  uzaydır  onun dışı  hiç bir y...', ARRAY['Türk Edebiyatı','Şiir','Octavio Paz']::text[], 8.5, '{"poet":"Octavio Paz","poet_slug":"octavio-paz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/tersine-cevrilebilir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahçedeki Dinleti', 'bahcedeki-dinleti-octavio-paz-nqo5o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(Vina ve Mridangam)

Carmen Figueroa de Meyer için 

Yağmur yağdı. 

Saat olağanüstü bir gözdür. 

İçine girer çıkarız yansımalar olarak. 

Müziğin ırmağı 

girer kanıma. 

Beden dersem, rüzgâr der, 

Dünya dersem, der ki nerde? 

Açılır dünya, çift katlı çiçek gibi: 

gelmenin hüznü, 

ve burada olmanın 

neşesi 

Kendi merkezimde yitirdim yolumu. 

Octavio Paz 

Türkçe’ye çeviren: İsmail Aksoy', '(Vina ve Mridangam) Carmen Figueroa de Meyer için  Yağmur yağdı.  Saat olağanüstü bir gözdür.  İçine girer çıkarız yansımalar olarak.  Müziğ...', ARRAY['Türk Edebiyatı','Şiir','Octavio Paz']::text[], 8.5, '{"poet":"Octavio Paz","poet_slug":"octavio-paz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bahcedeki-dinleti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecesel Su', 'gecesel-su-octavio-paz-bpfqa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'At gözlü bir gece titrer geceleri, 

su gözlü bir gecen var senin uyuyan toprakta 

titreyen at gözlerinde, 

sır dolu sulardan yapılı gözlerinde. 

Gölge suyundan gözler, 

kuyu suyundan gözler, 

düş suyundan gözler. 

Sessizlik ve yalnızlık, 

ayın taşıdığı iki küçük hayvan, 

içerler bu gözlerden, 

içerler bu sulardan. 

Gözlerini açarsan, 

açar gece yosun kapılarını, 

açar kendini suyun gizli ülkesine 

ve gecenin ortasından çağlar. 

Ve kaparsan gözlerini, 

bir ırmak doldurur içini, 

kör, suskun bir dalga atılır ileri 

ve karartır seni: 

nemlendirir gece ruhundaki kıyıları. 

Octavio Paz 

Türkçe’ye çeviren: İsmail Aksoy', 'At gözlü bir gece titrer geceleri,  su gözlü bir gecen var senin uyuyan toprakta  titreyen at gözlerinde,  sır dolu sulardan yapılı gözlerin...', ARRAY['Türk Edebiyatı','Şiir','Octavio Paz']::text[], 8.5, '{"poet":"Octavio Paz","poet_slug":"octavio-paz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gecesel-su-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Gövde', 'i-ki-govde-octavio-paz-wmmls', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İki gövde yüzyüze 

bazan iki dalgadır 

ve gece bir okyanustur. 

İki gövde yüzyüze 

bazan iki taştır 

ve gece bir çöldür. 

İki gövde yüzyüze 

bazan iki köktür 

geceyle sarmalanmış. 

İki gövde yüzyüze 

bazan iki bıçaktır 

ve gece bir anlık parıltı. 

İki gövde yüzyüze 

düşen iki yıldızdır 

boş ve yalnız bir gökte. 

Octavio Paz 

Türkçe’ye çeviren: İsmail Aksoy', 'İki gövde yüzyüze  bazan iki dalgadır  ve gece bir okyanustur.  İki gövde yüzyüze  bazan iki taştır  ve gece bir çöldür.  İki gövde yüzyüze ...', ARRAY['Türk Edebiyatı','Şiir','Octavio Paz']::text[], 8.5, '{"poet":"Octavio Paz","poet_slug":"octavio-paz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/iki-govde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kesinlik', 'kesinlik-octavio-paz-7esja', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eğer gerçekse beyaz 

ışık su lambadan, gerçektir 

yazan el, gerçek mi 

yazdığıma bakan gözler? 

Bir sözcükten ötekine 

kaybolur söylediğim. 

Biliyorum yaşadığımı 

iki parantez arasında 

Octavio Paz 

Türkçe’ye çeviren: İsmail Aksoy 

Çevirenin notu: Bu çeviri Behçet Necatigil’in anısına adanmıştır.', 'Eğer gerçekse beyaz  ışık su lambadan, gerçektir  yazan el, gerçek mi  yazdığıma bakan gözler?  Bir sözcükten ötekine  kaybolur söylediğim. ...', ARRAY['Türk Edebiyatı','Şiir','Octavio Paz']::text[], 8.5, '{"poet":"Octavio Paz","poet_slug":"octavio-paz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kesinlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız', 'kiz-octavio-paz-lvuko', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Direnen öğleden sonralarıyla 

toplayıcı gece arasında 

genç bir kızın dik bakışı 

Bırakıp gidiyor defterini ve yazmayı, 

bütün varlığı tamamlanmış iki gözde. 

Duvarda iptal ediyor ışık kendini. 

Sonunu mu görür yoksa başlangıcını mı? 

Bir şey görmediğini söyleyecektir. 

Berrak olgunlaşmadı daha. 

Ne gördüğünü bilmeyecek asla. 

Octavio Paz 

Türkçe’ye çeviren: İsmail Aksoy', 'Direnen öğleden sonralarıyla  toplayıcı gece arasında  genç bir kızın dik bakışı  Bırakıp gidiyor defterini ve yazmayı,  bütün varlığı tamam...', ARRAY['Türk Edebiyatı','Şiir','Octavio Paz']::text[], 8.5, '{"poet":"Octavio Paz","poet_slug":"octavio-paz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kiz-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manzara', 'manzara-octavio-paz-97c0p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaya ve uçurum, 

daha çok zaman kayadan, bu 

zamansız madde. 

Yaranın zarı içinden 

düşer kımıltısız 

sonsuz bakire su. 

Enginlik dinlenir burada, 

kaya üstünde kaya 

kayalar üstünde hava. 

Dünyanın bildirisi 

olduğu gibi: bir güneş 

kımıltısız, cehennemde. 

Başdönmesinin dengesi: 

kayalığın ağırlığı 

gölgelerimizden fazla değil. 

Octavio Paz 

Türkçe’ye çeviren: İsmail Aksoy', 'Kaya ve uçurum,  daha çok zaman kayadan, bu  zamansız madde.  Yaranın zarı içinden  düşer kımıltısız  sonsuz bakire su.  Enginlik dinlenir b...', ARRAY['Türk Edebiyatı','Şiir','Octavio Paz']::text[], 8.5, '{"poet":"Octavio Paz","poet_slug":"octavio-paz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/manzara-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mola', 'mola-octavio-paz-xvhbd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Pierre Reverdy’nin anısına 

Geldiler: 

bir kaç kuş 

ve siyah bir düşünce. 

Ağaçların mırıltısı, 

trenlerin ve motorların mırıltısı, 

şu an geliyor mu gidiyor mu? 

Gülüşün sessizliği 

deler inleyişi ve gülüşü, 

batırır mızrağını 

derine kayaların kayasında çığlığa. 

Güneş-yürek, çarpan kaya, 

meyveye dönüşen kan kaya: 

yaralar acısız açılır, 

benzesen hayatım akar gider. 

Octavio Paz 

Türkçe’ye çeviren: İsmail Aksoy', 'Pierre Reverdy’nin anısına  Geldiler:  bir kaç kuş  ve siyah bir düşünce.  Ağaçların mırıltısı,  trenlerin ve motorların mırıltısı,  şu an g...', ARRAY['Türk Edebiyatı','Şiir','Octavio Paz']::text[], 8.5, '{"poet":"Octavio Paz","poet_slug":"octavio-paz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mola-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özdeşlik', 'ozdeslik-octavio-paz-u85an', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Avluda bağırıyor acı acı bir kuş, 

madeni bir para kasada. 

Tüyleri biraz hava, 

ve yok oluyor ani bir parıltıda. 

Belki hiç kuş yok 

ne de benden başka kimse avluda. 

Octavio Paz 

Türkçe’ye çeviren: İsmail Aksoy', 'Avluda bağırıyor acı acı bir kuş,  madeni bir para kasada.  Tüyleri biraz hava,  ve yok oluyor ani bir parıltıda.  Belki hiç kuş yok  ne de ...', ARRAY['Türk Edebiyatı','Şiir','Octavio Paz']::text[], 8.5, '{"poet":"Octavio Paz","poet_slug":"octavio-paz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozdeslik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaya', 'yaya-octavio-paz-r54an', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yürüyordu kalabalığın arasında 

Sebastó bulvarında 

düşünerek bir şeyler. 

Kırmızı ışık durdurdu O’nu. 

Baktı yukarı: 

üzerinde 

boz damların, gümüş 

bir balık uçuyordu 

kahverengi kuşların arasında. 

Yeşil ışık yandı. 

Caddeyi geçerken merak etti 

ne düşünmekte olduğunu. 

Octavio Paz 

Türkçe’ye çeviren: İsmail Aksoy', 'Yürüyordu kalabalığın arasında  Sebastó bulvarında  düşünerek bir şeyler.  Kırmızı ışık durdurdu O’nu.  Baktı yukarı:  üzerinde  boz damları...', ARRAY['Türk Edebiyatı','Şiir','Octavio Paz']::text[], 8.5, '{"poet":"Octavio Paz","poet_slug":"octavio-paz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yaya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Ötesinde', 'sevginin-otesinde-octavio-paz-b1syj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her şey tehdit ediyor bizi: 

zaman canlı kırıntılarda ayırır gibi 

geleceğimle 

şu anda olduğum şeyi, 

palayla yılan gibi; 

bilinç, berrak, dolanır durur bir o yana bir öte yana, 

bakış körleşmiş kendi dikbakışına bakmaktan; 

sözcükler, gri eldivenler, beyintozu çimlerin üstünde, 

suda ve deride; 

adlarımız, Sen ve Ben arasında dolaşır, 

çökertemez boşluğun duvarlarını hiç bir trombon. 

Ne parçalanmış resimlerinin köyüyle düş 

ne de yalvaçsı köpüğüyle sayıklayış 

ne de dişleri ve pençeleriyle sevgi yeterli bize. 

Kendi ötemizde, olmak ile bir yerde olmak arasındaki sınırda 

çağırır bizi hayattan daha canlı bir hayat. 

Soluk alır dışarda gece ve yayar kendini, 

kocaman sıcak yapraklarıyla sarhoş, 

birbirleriyle savaşan aynalarla: 

yemişlerle, pencelerle, gözlerle, yapraklarla, 

parıldayan sırtlarla, 

başka gövdelerin arasından kendine yol açan gövdelerle. 

Uzan buraya bütün bu köpüğün kıyısına, 

kendini bırakırcasına, bilinçsiz, bütün bu hayatın kıyısına; 

yayıl, ey soluk alan beyazlık, 

bırak işiteyim yürek çırpınışını, ey dağılmış yıldız, 

ah sen çam, ah şafağın kıyısına doğru 

teraziden ağır gelen ekmek, 

sen bu zamanla sınırsız başka bir zaman arasındaki kanın molası. 

Octavio Paz 

Türkçe’ye çeviren: İsmail Aksoy', 'Her şey tehdit ediyor bizi:  zaman canlı kırıntılarda ayırır gibi  geleceğimle  şu anda olduğum şeyi,  palayla yılan gibi;  bilinç, berrak, ...', ARRAY['Türk Edebiyatı','Şiir','Octavio Paz']::text[], 8.5, '{"poet":"Octavio Paz","poet_slug":"octavio-paz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sevginin-otesinde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefes Alış', 'nefes-alis-octavio-paz-hnpvf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1 

Beyaz günün gölgeleri 

gözlerime karşı. Gördüğüm 

beyaz yalnızca: 

beyaz saat, ruh bağımsız 

arzudan, saatten. 

Usul suların sessizliği, 

beyaz saat, açık gözlerin körlüğü. 

çak çakmaktaşını, yak, bellek, 

saate ve anafora karşı. 

Bellek, yüzen alev. 

2 

Bağımsız bedenden, arzudan 

bağımsız, geri dönüyorum arzuya, dönüyorum 

bedeninin belleğine. Dönüyorum geriye. 

Ve bedenin belleğimde yanıyor, 

belleğim yanıyor bedeninde. 

Bir tanrı bedeniydi yanan 

tanrıydı o beden ve yarattı tanrıyı beden 

ve şimdi, yalnızdır, başka bedenlerden sadece 

bağımsızlaşmış bir bedenin belleği sadece: 

bedenin kemiklerimin belleği. 

Güneş-orağın gölgesi fırlatıyor Güneş-gölgeyi 

kederli kuyumun üstünden 

çözüyor düğümlü ekinleri arzunun dibinden 

tutuşturmaz bu sayrı yüreği 

Ne ki parçalanmış bellek yüzer 

hiçliğin doğum kaynaklarından 

doğumun kaynaklarından 

yüzer akıntıya ve yetkilere karşı 

yüzer hiç’e doğru 

suyun zaafı 

dört fosforlu suyun dili 

Paskalya’nın yedinci pazarının dünyasız sözcükleri 

Farkında ol düşünmeden farkında olmanın 

düşünce geri fırlatır belleği kendiliğinden 

Gerisi bir avuç gösteriş 

Octavio Paz 

Türkçe’ye çeviren: İsmail Aksoy', '1  Beyaz günün gölgeleri  gözlerime karşı. Gördüğüm  beyaz yalnızca:  beyaz saat, ruh bağımsız  arzudan, saatten.  Usul suların sessizliği, ...', ARRAY['Türk Edebiyatı','Şiir','Octavio Paz']::text[], 8.5, '{"poet":"Octavio Paz","poet_slug":"octavio-paz","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/nefes-alis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunlar', 'bunlar-mikdat-bal-5zj37', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Memleketi parsel parsel eyleyip

Satarak milleti kandırdı bunlar

Öz kaynağı kara delik söyleyip

Tüten bacaları söndürdü bunlar

Sözleri hayaldir düşleri yoktur! 

Doğruyla gerçekle işleri yoktur

Yalan söylemede eşleri yoktur

Gideni rahmetle andırdı bunlar

Açları hiç kimse anlamaz tokken

Tüccarlar iş yapmaz malları stokken

Milletin cebinde beş kuruş yokken

Sözde enflasyonu dondurdu bunlar

Cem evinden kaçmış, kilise açmış

Milletin arzusu kim demiş haçmış

Bilmezler mi bu halk neye muhtaçmış

Kimin yarasını dindirdi bunlar

Bal der bu halk uyur acaba niçin

Sadaka bir aylık mümkünse geçin

Yaptıkları kanun IMF için

Hak talep edeni sindirdi bunlar', 'Memleketi parsel parsel eyleyip Satarak milleti kandırdı bunlar Öz kaynağı kara delik söyleyip Tüten bacaları söndürdü bunlar Sözleri hayald...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bunlar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Karanlık Zambinella', 'ay-karanlik-zambinella-yavuz-bayram-caliskan-bh8l9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sekiz Mayıs bin dokuz yüz seksen dört,

Saat on dokuz suları,

Seni yağmurlar getirir Antep’in akşamlarına,

Urfa’da görse de gözler, yaşasa da umutlar.

Bir deli rüzgar eser on yedilerde,

Ayşegül kirlenir,tozlanır, isyanları oynar,

Umutlarına dokunamaz çeker zehri içine,

Zemheri ayazlarında titrer,

Baksan da göremezsin,

Ay karanlık Zambinella.

Denizine düşmüş ay ışığıyla,

Gökyüzündeki yıldızları saymış,

Martı kanadında umutları,

Menfaatlerin cici yüzü,

Cılız ve masum yüreklere güldüğü zaman,

Ezilir havanda güzel yüzler,

Bakma seni gösteren aynalara,

Ay karanlık Zambinella.

Pişmanlıklar bitmez bu zamanda,

Kim çaldı umudunu,

Dil durur yaşlar konuşur,

Şeytan düşleri gıdıklar,

İhtiraslar zincirlenir,

Kara trenler gibi gelip geçer,

Yaşanmaya değer mi bilinmez,

Yüreği güzel bir şiir gibi,

Yarınıma cici kız olur mu? 

Her gelen bir parça koparmış,

Yüreğini almışlar, belki de çalmışlar,

Açmamış bir gül gibi,

Yirmibir yıllık Zambinella.

Umursamaz kendini ve yarınını,

Ciddiye almaz her bir şeyi,

Sadece bana göre iyi olan,

Benim şiirlerimi pek okumayan,

Bir kız hatırlarım.

Ay karanlık Zambinella.

Umudumu paylaş artık,

Sana bakan yeşil gözlerim var,

İçindeki cici kızı çıkar ortaya,

Yoksa ay karanlık Zambinella.

Geceler karanlıklarda kalsın,

Seni bu yüreğim alsın,

Ay karanlıklarda,

Ay karanlıklarda kalsın Zambinella.', 'Sekiz Mayıs bin dokuz yüz seksen dört, Saat on dokuz suları, Seni yağmurlar getirir Antep’in akşamlarına, Urfa’da görse de gözler, yaşasa da...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/ay-karanlik-zambinella-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Minibüs', 'minibus-elazigli-mustafa-kaya-jh2hr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '..…yardımcı olalım ağabeyler

      arkayı beşliyelim

      çocuğu kucağa al sana abicim

      kaptan parasını verdim oturacak çocuk benim..

      abi basamakta durma

      yer mi var yaa..

      ve dopdolu gidiyoruz

      çık abi.. bak bir ayak yer var 

      yanaş..yanaş abi…yanaşalım 

      koltuklar..aralar..tavana vuran kafalar

      inen yok binen çok

      minibüs her durakta insan alıyor

      bindik bir alamete gidiyoruz kıyamete..

      evet  ücretini vermiyenler..

      bizim on milyon üstü gelmedi..

      abi beş milyon da ben vermiştim

      bozuk verin ağabeyler…abla bozuk yok mu..? 

      yaa kardeşim ineceğiz paranın üstü..

      ücretini vermeyen kaldı mı..? 

      uzatır mısın kardeş? 

      müsaade eder misin..? 

      ya çek şu çantanı..? 

      kaptan dursana inecek var..

      inecek vaarrr..

      yaa ne memleket be..! 

      bunlara laf söyleyende yok

      sahipsizlik…gardaş memleket sahipsiz..

      yok yaa…ne sahipsizliği arkadaş suçlu hepimiz

      biz de duyarsızlık var…şu halimize bak nerde tepkimiz 

      bacı çocuğun ayakkabılarına sahip çık

      o çocuk  ne bilsin..bilse yapar mı..

      Allah…Allah….ya kardeşim içimiz dışımıza çıktı

      acelen mi var…ecele mi götürüyon bizi

      taşımacılık konusunu halledemiyen bir toplum olduk

      bu memleket adam olmaazzzz….zor adam oluruz

      adam yaptırmam dedi  ya köprüyü..? hatırladın mı..? 

ya bizde olumlu bir şey olsa öbürü tam zıddını söyler

ücretini vermeyen..

para üstü almayan kaldı mı..? 

abi zam mı geldi..? 

bir milyon ikiyüzelli oldu

eee komşu zorlaştı işler

ya bıldır daha mı bereketliydi ne 

yetmiyor komşu..hangi birini kapatayım yamanın

çeşme….çeşme de inecek var mı..? 

var..varrr…var var..

ağabeyler çabuk olalım

dur yaa..inen var

ya bu şöförlerin hepsi böyle

bir bakıyon yeni ehliyet almış gençten çocuk

uçurup duruyor tepelerden…aralardan…oradan buradan

bir bakıyon kağnı mübarek yürümüyor ağırdan

adam var kaba saba medeniyet yok

bir bakıyon kibar ve bakımlı nazik insan evladı

bir ortası olmalı yahu…dedik ya sahipsiz memleket

ya bırak şu sahipsizlik nakaratını

tepkisiz insanlarız biz

vatan-millet-sakarya deriz

birbirimizi yeriz..yasakları…haksızlıkları kutsal biliriz

yaa  oralar siyaset

ulaaan sana ehliyet veren tuuuu..

kırmızı yandı kaptan…..yaa kırmızı da geçti adam

ne yapsın o da haklı bu kadar insanız işe yetişeceğiz..

öğrenci kıyafetli olana yüzde elli…

sen gamzelim..

kıskanırım ben…

ela gözlerini sevdiğim..

müşteri velinimetimdir..

bismillahirrahmanirahiim

ferdi Tayfur (resim..) 

peşin veren…veresiye veren(resim) 

abi biraz öyle..vitese dikkat..(..motorun üzerindeki müşteriye) 

depo da var mıı..var mı inceek..

var..var..

çabuk olalım ağabeyler…dur abla acele etme…

ooo mümtaz akşam nerdeydin

ali’nin kahvesindeydik…ya yine  batak ta battık akşam

ollum ne bilirsin sen batak matak…sen benimle eşleş

ya sizin arkadaş satıyomu 98’i

sattı bile..

ya kaptan ne bekliyoruz..

karşı yoldan minibüsle konuşuyo adam

hem bize acele diyo hem kendileri….ya memleket sahipsiz ha

yanaş abi…yanaş abi

buradan ne kadar…ne kadar oldu durak

800…800…..yaaa ne zaman

İki haftadır abi sen hiç duymadın mı..? 

……………..

kaç durak kaldı inmiştim ben

uzayıp giden bir serüven

ve kaç yıldır  da bitmeyen

minibüsler de toplumun ahlak-medeniyet

kültür seviyesi..nabzı atar

halkın ta kendisidir yaşanan

ve iyilikler…öfkeler…dayanışma..yardımlaşma yatar

bir minibüsün içinde

kah gülerim olanlara

kah içim burkulur yaşananlara

tıklım tıklımdır günün belli saatleri

risk dolu..tehlike yüklü..

dar  ve virajlı yollar

savrula savrula bazı yol alınan hızlar

ve sağ salim inmişseniz

sapasağlamsa sinirleriniz

şükretmelisiniz…şükretmelisiniz….

Mustafa kaya

13.11.2005 / istanbul 

www.mustafakaya.net', '..…yardımcı olalım ağabeyler       arkayı beşliyelim       çocuğu kucağa al sana abicim       kaptan parasını verdim oturacak çocuk benim.. ...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":108,"source_url":"https://www.antoloji.com/minibus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudum bırakma beni', 'umudum-birakma-beni-tolunay-karabulut-r37h3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Küçük balıkların dünyasıdır 

Akvaryumlar

Yürekte o kor ateş yandıkça

Nice fidanlar yeşerir

Sığmaz dağlara

Umudum dağlara

Direnişin en saygın 

Ateşinde

Karanlığı beyaza boyayıp 

Bir parçada görmek için 

Bütünü

Metriste

Diyarbakırda

Söylerken türkülerimizi

Dalga dalga 

Süzülecek kızıl saçlı 

Şafak

Yıldız –yıldız

Poyraza yemiş şafaklar sökerken

Yasadışı sevmişliğim

Filinta gençliğim

Yangın yüreklim

Yüreğimi 

Avuçlarına vereceğim

Çocuk gözlerimde

Güneşi sunar gibi

Sallanan bende olabilirim

Bir türkünün söylenişide

Kör karanlık bir gecede

Bir İngiliz siciminin ucunda

Hemde sana bu kadar tutsakken

Umudum bırakma 

Beni

Bilki

Dalga dalga

Yeniden dirileceğiz', 'Küçük balıkların dünyasıdır  Akvaryumlar Yürekte o kor ateş yandıkça Nice fidanlar yeşerir Sığmaz dağlara Umudum dağlara Direnişin en saygın...', ARRAY['Türk Edebiyatı','Şiir','Tolunay Karabulut']::text[], 8.5, '{"poet":"Tolunay Karabulut","poet_slug":"tolunay-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/umudum-birakma-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka neler yapıyorsun deme', 'baska-neler-yapiyorsun-deme-tolunay-karabulut-okqy8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Başka neler yapıyorsun? 

Her yere gidiyorum anne,güneşe bile binip uçurtmama salınıyorum gökyüzüne,ünüformalı  genaraller yok iğrenç gülüşleriyle,hiç kimse kimliğimi kontrol etmiyor,çocukluğumun uçurtmalarında…

    Ne kadar ıslatmaya çalışsada hüznün yağmurları,şimşikleri ne kadar kanatsada çocuk çıplaklığımı yinede ellerimde karanfillerle türkümü söylüyorum.Gökyüzünde,gökyüzüne salıyorum ,uzak diyarların çocuklarını kucaklıyorum,kardeşlerimi …Afrikada  açlığımla kalıyorum hep kara bir gecede,kara tenli kardeşlerimle,filistinde  köşebaşlarında vuruluyorum,emperyalizmin mermileri patlıyor yüreğimde,çok yorgunum koşamıyorum,kaçamıyorum hayattan sarıp sarmalıyor beni tüm vucudum kanarken,esmer tenli bir kürt kadını…Pis  sidik kokan bir müteferrikanın tuvaletinden içiyorum suyumu,ateşimi bastırıyorum duvaları kazıyıp kireçler emiyorum,böcekler yiyorum ve hiç iğrenmiyorum sarı dişleriyle sırıtan generallerden iğrendiğim kadar bile…Hitlerin fırınlarında yanıyorum,her sürgünün metal sesleriyle çalıyorlar uykularımı…

    Islak betonda kıvrılmış yatan cenin gibiyim,zincirlerimden kurtulup ayağa kalkmak istedikçe,dipcikler iniyor üzerime,postal sesleri geliyor kapıma,kapılar korumuyor düşlerimi bile…

   Adamlar görüyorum gardiyanın yanındaki sivil sesiyle tarıyor geceyi,bir mitralyöz patlıyor…Güneşi görüyorum,güneşi,kırmızı gülleri ve çocuk zevinçlerinde çığlık çığlığa bir koroyu mutluluk şarkıları söyleyen…

     Üç yada otuz üç ne önemi varki! uzun ve namuslu bir yaşamdı,çocukluğum olmadı  ama çocuklarım oldu ve ben ne kadar üşümüşsem,çocuklarımız serecekler bedenlerini ülkemin yitik güneşine-Dizi dizi mor karanfiller öyle güzeller ki…

   Bunca yıllık tutsaklığımın dostu olmuşlar kilitler,kapılar ve korku…

   Senmi geldin barışşşşşşş senmi geldin ülkemeeeeee

  Güneşi görüyorum 

  Başka neler yapıyorsun deme bana 

 Ranzamda upuzun yatarken,evine ekmek götüren babalar geçiyor gözlerimden…', 'Başka neler yapıyorsun?  Her yere gidiyorum anne,güneşe bile binip uçurtmama salınıyorum gökyüzüne,ünüformalı  genaraller yok iğrenç gülüşle...', ARRAY['Türk Edebiyatı','Şiir','Tolunay Karabulut']::text[], 8.5, '{"poet":"Tolunay Karabulut","poet_slug":"tolunay-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/baska-neler-yapiyorsun-deme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba Yüreğim', 'merhaba-yuregim-tolunay-karabulut-28h0a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Merhaba yüreğim merhaba

Kara yüzlü

cellatların 

bir sabahın katledildiğini 

haykırmadığı 

günlere

merhaba...merhaba 

ülkem

güneşin yediverenlerinin doğuşuna

bir kardelenin

açışına merhaba', 'Merhaba yüreğim merhaba Kara yüzlü cellatların  bir sabahın katledildiğini  haykırmadığı  günlere merhaba...merhaba  ülkem güneşin yediveren...', ARRAY['Türk Edebiyatı','Şiir','Tolunay Karabulut']::text[], 8.5, '{"poet":"Tolunay Karabulut","poet_slug":"tolunay-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/merhaba-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Gözlüm', 'gece-gozlum-derbeder-koylu-irkqj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözünden süzülen yaş denizi ıslatıyor.

Sezda kilim, hasret gönül derdi dokuyor.

Çatlayası deli yürek SEN SEN diye atıyor.

OOfff gece gözlüm off...

Bu lanet köy 

                      ...SEN KOKUYOR...', 'Gözünden süzülen yaş denizi ıslatıyor. Sezda kilim, hasret gönül derdi dokuyor. Çatlayası deli yürek SEN SEN diye atıyor. OOfff gece gözlüm ...', ARRAY['Türk Edebiyatı','Şiir','Derbeder Köylü']::text[], 8.5, '{"poet":"Derbeder Köylü","poet_slug":"derbeder-koylu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gece-gozlum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boyacıköy''de Yitik Zaman Hikayeleri 4', 'boyacikoy-de-yitik-zaman-hikayeleri-4-cenk-aksal-syop6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'belli belirsiz 

delik deşik düşler görüyorum,

düşlerimde garip insanlar

solgun yüzlerine:

salgın bir hastalık gibi yapışmış,

sevgisiz sevgisizlik...

--------------

birisi gülüyor,

çökmüş gözlerinde acının izleri..

yüreğine yapışmış yalnızlıklara

isyanlarda belliki...

---------------

adın ne diyorum:

vuslat diyor belli belirsiz,

adım gibi olamadım kavuşamadım,

canım gibi sevdiğime diyor..

---------------

bir başkası takılıyor gözüme,

bir kova dolusu gözyaşı biriktirmiş,

litre hesabı satıyor,yüzelli kuruşa

acıdan kavrulup ta,yanıp da

bir damla yaş dökemeyenlere.

garibandan para da almıyor sevabına....

---------------

bu kadar mutsuz insanın içinde:

mutlu bir yüz arıyorum,

saatlerce dolaşıp da bulamayınca,

moralim iyice bozuluyor benim de,

bir ağacın altında oturan adama:

buranın muhtarı kim diyorum,

aha diyor şu kavak ağacının üzerindeki,

ilerliyorum ağaca doğru,

adamın biri yani muhtar,

taaa ağacın tepesinde oturuyor,

muhtar diye sesleniyorum

buyur yabancı diyor,derdin ne? 

boyacıköy neden mutsuz insanların

acıların gözyaşının köyü diyorum:

ah evladım sorma diyor:

zamanın birinde:birbirini seven 

hemde ölesiye delice seven 

iki genç varmış,boyacıköyde yaşarlarmış:

evlenmek istemişler aileleri razı olmamış,

kaçmışlar bütün köy peşlerine takılmış,

yakalanmışlar:

köy heyeti ceza için toplanmış,

adama ölüm cezası vermişler,

kalbini yerinden çıkarıp,

kuşlara yem etmişler,kızıda bırakıp

deli divane etmişler:

işte o günden beri bu köyde:

ne mutluluk nede mutlu insanlar var,

deyipte ağlamaya başladı muhtar..

gözlerim doldu bende ağladım,

sonra sessiz adımlarla köyden 

çıkıp kendi yoluma yollandım..

yol boyu ağladım ağladım ağladım.....', 'belli belirsiz  delik deşik düşler görüyorum, düşlerimde garip insanlar solgun yüzlerine: salgın bir hastalık gibi yapışmış, sevgisiz sevgis...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/boyacikoy-de-yitik-zaman-hikayeleri-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Düşle Beni', 'sende-dusle-beni-salim-erben-irqtx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aklına düşerde  hani olurda

Ararsan beni 

Gecenin yalnızlığın da saklı

Gizemli bakışlardan sor

Hayal gücünde bak

Başını yastığıma bırak

Gözlerini yum ve düşle 

Beni göreceksin

Bilirim çare değil ama

Umut işte düşle 

Ben nasıl düşlüyor 

Nasıl seviyorsam seni

Sende öyle düşle, 

Öyle sev, zalım  beni', 'Aklına düşerde  hani olurda Ararsan beni  Gecenin yalnızlığın da saklı Gizemli bakışlardan sor Hayal gücünde bak Başını yastığıma bırak Gözl...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sende-dusle-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhabbet', 'muhabbet-mehmet-sait-akkus-tbtp1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Muhabbeti dost edindiğim

Kendime yol edindiğim

Benim yalnızca bildiğim

Doğruluktan zarar gelmez

Muhabbeti dost aşkına

Satmıyalım başkasına

Girsek dahi yüz yaşına

Doğruluğu yol edinelim

Kötülüğe tapanlardan

Dostlukları satanlardan

Mahkemesiz asanlardan

Bizleri yapma Allahım

Muhabbeti kuş misali

Olalım dostluk timsali

Bulunmaz böyle emsali

Daim olsun bu muhabbet', 'Muhabbeti dost edindiğim Kendime yol edindiğim Benim yalnızca bildiğim Doğruluktan zarar gelmez Muhabbeti dost aşkına Satmıyalım başkasına G...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/muhabbet-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutsam', 'unutsam-nuray-acar-wisew', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Alıp başımı gitsem 

hiç kimse bilmese 

neden gittiğimi 

Kendimi yola vursam 

neden gidiyorum diye 

sorgulamadan 

Tam aradığım yerdeyim 

dediğim anda 

zamanı 

.................unutsam. 

nuray67 

[email protected]', 'Alıp başımı gitsem  hiç kimse bilmese  neden gittiğimi  Kendimi yola vursam  neden gidiyorum diye  sorgulamadan  Tam aradığım yerdeyim  dedi...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutsam-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüş', 'donus-burak-killioglu-ut3es', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsan bekler olduysa kışı, nerde diye ölesiye

Geçip giden günleri hiç istemeden yaşıyorsa

Ya da takvimdeki çentiklerin insafına kalıyorsa

Sayılı gün derdindedir, bekler ki geçiversin.

Sanki yitip giden ömür değil, insan değil

O denli sabırsızdır, zaman akıp gitmelidir.

Akrep mi kovalar yelkovanı,

Usulca akan kum saatinin kumları mı 

titreşmelidir idam mahkumuna dömüş zihninde,

Bilemez olur insan! 

Bilemez ne akrep, ne yelkovan! 

Önce yapraklar sararmalı, teker teker düşmeli her biri

Her düşen yaprakla bir kalp atışı zaman geçmelidir

Sonra da süpürmelidir rüzgar binbir türlü hışırtıyla

Yüreği yanık kaldırımları.

Gelmeli artık kış, bir an önce gelmeli

Hayat, insana bir pusu; bazen kıştır beklenen, 

Bazen de bir sevgili...

Gün olur, bir kışa avuç açar yürek,

Soğuk, donuk bir kışa...

Ve bu kış bir asker daha eve dönecek,

Bir asker daha!', 'İnsan bekler olduysa kışı, nerde diye ölesiye Geçip giden günleri hiç istemeden yaşıyorsa Ya da takvimdeki çentiklerin insafına kalıyorsa Sa...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/donus-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke Bir Diyeceğim Olsaydı', 'keske-bir-diyecegim-olsaydi-hilal-tugba-yod7j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'keşke bir diyeceğim olsaydı

keşke ağzımdan bir çift söz çıksaydı

içimdeki felaketten geriye

keşke birkaç kelime kalsaydı

ama olmadı işte, bitti herşey

-yangın yeri 

çamurlar yığılı sokaklar

depremden sonra izmit-

hepsi artık içimde heryerde

keşke diyeceğim birşey olsaydı sana

bir çift kelime

ne kadar üzüldüğümü söyleyebilseydim

keşke hıçkırıklarla ağlayıp 

kahkahalarla gülseydim

keşke böyle tükenmiş olacağıma

....

....

ölseydim...

kış''05- ank', 'keşke bir diyeceğim olsaydı keşke ağzımdan bir çift söz çıksaydı içimdeki felaketten geriye keşke birkaç kelime kalsaydı ama olmadı işte, bi...', ARRAY['Türk Edebiyatı','Şiir','Hilal Tuğba']::text[], 8.5, '{"poet":"Hilal Tuğba","poet_slug":"hilal-tugba","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/keske-bir-diyecegim-olsaydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapayalnız', 'yapayalniz-hilal-tugba-fxjct', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '....

yapayalnızdım 

yapayalnızdık

işte yapayalnızlık buydu...

benim yalnızlığımın seni ilgilendirmeyişindeydi büyük boşluk, büyük acı

seninkinin bende iz bırakmayışındaydı

camın üzerinden kayan bir su damlası gibi

iz bırakmadan geçen suydu bir başkasını mutsuzluğu...

...

senin ateşinin beni yakmayışındaydı

yanan ateşlerin yakamayışındaydı

her ateşin tek bir yeri yaktığı, 

her suyun tek bir ateşi söndürdüğü mantıkdaydı hata

hata senin sözlerinin benim harflerimle yazılamayışıydı yüreğine

yüreğinin beni okumayı bilmeyişindeydi o hata

benim yalnızlığımın seni ilgilendirmeyişindeydi büyük boşluk büyük acı! 

bu yüzden yalnızdım,

	      yalnızdık....

                                            kış''98-ist', '.... yapayalnızdım  yapayalnızdık işte yapayalnızlık buydu... benim yalnızlığımın seni ilgilendirmeyişindeydi büyük boşluk, büyük acı senink...', ARRAY['Türk Edebiyatı','Şiir','Hilal Tuğba']::text[], 8.5, '{"poet":"Hilal Tuğba","poet_slug":"hilal-tugba","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yapayalniz-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana Kucağı', 'ana-kucagi-alper-kuruk-6b88v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni saran kollar

Bunlar değildi önce,

Şevkatle sarılan o kollar 

Vücuduma değince

Ana sevgisi kalbimi yakardı...

Başımı koyduğum bu diz 

Eski diz değil 

Ki o beşikti benim için,

Ağladığımda o iki ayak

Beni sallardı.

Şimdi sarılan kollar

Şimdi açılan kucak

Aşk karışmış bir ömrü paylaşmak için

Beni sarar,bana açık.

Kollar var,dizler var yine

Ama,bambaşka sevgisiyle

Nerde o analık?', 'Beni saran kollar Bunlar değildi önce, Şevkatle sarılan o kollar  Vücuduma değince Ana sevgisi kalbimi yakardı... Başımı koyduğum bu diz  Es...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ana-kucagi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkes Herşeyi Kaybetti', 'herkes-herseyi-kaybetti-hilal-tugba-wdf7h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'herkes birşeyini kaybetmişti

ben sevgiye olan inancımı

sen beni 

artık biliyordum ki herkesin içinde kısık gözlü bir kedi

herkesin elleri pençe

....

bilmeye aşık biriydim ben

bilmenin acı vereceğini bilmeyerek

herşeyi bilmeyi diledim Tanrı''dan

ve O da öğretti işte bana

herkesin içinin neye benzediğini....

bir tek bunu öğrendiğime pişmanım...

.....

kısık gözlü kedilerin gece parlayan gözleri

kimse kimseyi sevemez

artık biliyorum

artık biliyorum ki herkes birtek içindeki kediyi ve pençelerini seviyor

artık biliyorum ki herkes seviyorum diyerek

bir başkasının kanıyla içindeki kediyi besliyor

artık biliyorum ki kimse kimseyi sevemez 

artık biliyorum ki ben de kimseye bir daha aşık olamam

içlerini görmemek için gözlerimi kapayamam

-ki herkesin kedisinin gözleri açık-

ben artık onlara aynı gözle bakamam

artık biliyorum ki herkes birşeyini kaybetti

ben sevgiye olan inancımı

sen beni

artık biliyorum ki herkesin içinde kısık gözlü bir kedi 

herkesin elleri pençe...

...bir bunu öğrendiğime pişmanım! 

						                                            kış''98-ist', 'herkes birşeyini kaybetmişti ben sevgiye olan inancımı sen beni  artık biliyordum ki herkesin içinde kısık gözlü bir kedi herkesin elleri pe...', ARRAY['Türk Edebiyatı','Şiir','Hilal Tuğba']::text[], 8.5, '{"poet":"Hilal Tuğba","poet_slug":"hilal-tugba","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/herkes-herseyi-kaybetti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-orhan-turhan-kunwc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnızlık…

İnsanın ilk sermayesi.

Kalabalıkla birlikte artar kimi zaman,

Paylaşıldıkça azalır geçici de olsa.

Doğuştan tek yadigardır bize bahşedilen.

Eşit bir sunu gibi görünse de ademoğluna

Anlayana yaşamla ilgili bir ipucudur oysa.

Ölümden beterliği ispatlanır her isyanda.

Çırpınıp dururuz her solukta onsuzluğa,

Bilmeyiz onsuzluk da bir yalnızlıktır oysa.

Tek çare gibi yöneltir bizi aşka.

Heybemizdeki en güzel demetleri sunarız ona,

Aşk, ikinin  bir yalnızlıkta buluşmasıdır oysa.

Sessizliği dinlemek için bazen özlemdir ayrılığa.

Anlatıp dururuz kan ter içinde keşkelerimizi,

Saatlerce konuştuğumuz koskoca  bir boşluktur oysa.

Yalnızlık…

Sermaye olamasa da ölüme, aşka, ayrılığa…

Onda  hep olacaksın yaşamın sonu da olsa…

Orhan Turhan

11.11.2005', 'Yalnızlık… İnsanın ilk sermayesi. Kalabalıkla birlikte artar kimi zaman, Paylaşıldıkça azalır geçici de olsa. Doğuştan tek yadigardır bize b...', ARRAY['Türk Edebiyatı','Şiir','Orhan Turhan']::text[], 8.5, '{"poet":"Orhan Turhan","poet_slug":"orhan-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yalnizlik-298-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varlık Yokluk', 'varlik-yokluk-ahmet-tevfik-ozan-x7cdl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uyandım; bin yerinden, bir gecenin birinde:

Hep yokluk, yokluk, yokluk! .. Yalnız şu garip Başım

Şu garip Başım yalnız, bir kainat kadar var! ..

Ve cehennemlerde pişmiş, kendi beynimden aşım! ..', 'Uyandım; bin yerinden, bir gecenin birinde: Hep yokluk, yokluk, yokluk! .. Yalnız şu garip Başım Şu garip Başım yalnız, bir kainat kadar var...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/varlik-yokluk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Küçük Şiir', 'uc-kucuk-siir-ahmet-tevfik-ozan-3k63t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'I

Ve bir gün sarsılarak, canlansa hatıralar 

Bir nahoş ürpertiydi diyecek, dudaklarım.. 

Bir hayal rüzgarında savrulan yıllarımla

Gözümde yeşerecek, bir bir unuttuklarım..

II

Bir yağmur sonrasında

Nasıl kokarsa toprak

Öylesine serin gel

Temiz gel öylesine...

Ne ümit ver, bir avuç 

Ne bir tek, hayal götür

Toprak kok, yağmur yağmur

Çamur çamur, toprak kok! ...

Gideceğin gibi gel

Geldiğin gibi gitme! ...

III

Ölürsek, bir Fatiha dileğimiz..

Kalırsak, gönül rızası

Başka dilek ne haddimiz

Şu dünyadan; yıkılası (!)', 'I Ve bir gün sarsılarak, canlansa hatıralar  Bir nahoş ürpertiydi diyecek, dudaklarım..  Bir hayal rüzgarında savrulan yıllarımla Gözümde ye...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/uc-kucuk-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyur Uyanık', 'uyur-uyanik-ahmet-tevfik-ozan-nvcw7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çizmiş de suretini, bir damla suya Rabbim..

Demek ki: denizlere çizilenler, bir dehşet! 

Seni hem, zerre zerre katmış uykuya Rabbim

         Demek ki: uyandırmak, beni; uykudan vahşet! ...', 'Çizmiş de suretini, bir damla suya Rabbim.. Demek ki: denizlere çizilenler, bir dehşet!  Seni hem, zerre zerre katmış uykuya Rabbim         ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/uyur-uyanik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyku Ne', 'uyku-ne-ahmet-tevfik-ozan-68kwl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölüm, ne büyük dostsun, şu yalancı Dünya’da..

Her gece kapım çaldın, her sabah kalkıp gittin! 

Bin bir Alem getirdin her gece, bir rüyada..

Sen ebedi ölümü, imanımda erittin! ..', 'Ölüm, ne büyük dostsun, şu yalancı Dünya’da.. Her gece kapım çaldın, her sabah kalkıp gittin!  Bin bir Alem getirdin her gece, bir rüyada.. ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/uyku-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utangaç', 'utangac-ahmet-tevfik-ozan-7tk4p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sözlerim, gözlerime benzemez

Gözlerim, sözlerime...

Nasıl anlatsam, bilmem ki? ! ...', 'Sözlerim, gözlerime benzemez Gözlerim, sözlerime... Nasıl anlatsam, bilmem ki? ! ......', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/utangac-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tuzlu Su', 'bir-tuzlu-su-ahmet-tevfik-ozan-xkxv4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Su ve tuz Deniz''in terkibi, belli..

Ne suda, ne tuzda hayatın izi

Ne mümkün var demek., m''uhal mi muhal! ..

Kudret''in eliyle gör ki acı su:

Yemyeşil, rengarenk hayat denizi! ..', 'Su ve tuz Deniz''in terkibi, belli.. Ne suda, ne tuzda hayatın izi Ne mümkün var demek., m''uhal mi muhal! .. Kudret''in eliyle gör ki acı su: ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bir-tuzlu-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çakıl Taşı Yalnızlığımız', 'cakil-tasi-yalnizligimiz-selahattin-yetgin-50ip9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sessiz ve soluksuz bir gecenin

Kırık yansımalarıydı içimizdeki

Avuçlarımızdan kirli, kırık

Çakıl taşları kayıyordu durmadan

Açılmıştı yalnızlığın çeşmeleri

Anılara tutsaktık, güvercinler gibi.

Isınsın diye üşümüş içimiz

Tutup güneşi çevirdim gönlüne

Kollarımı başının altına koydum

Şiirlerimizi serdim üzerimize

Yüzüyorduk  bir hayalet kentte

Ay dönüyor, yıldızlar yol gösteriyordu

Sesimiz sularda iniltiye dönmüştü

Kıpkırmızı bir bahçede aşkı arıyorduk.

Sevdanın yunus bakışlı, mahzun güzeli

Geleceği gören başka dünyanın özeli

Bir kuğu kanatlarıyla okşadı yüreğimi

Irmaklara çevirdi hışımla gözyaşlarını

Ormanlara serdi gece gibi siyah saçlarını

Aşındı, devrildi, yuvarlandı dağın taşları

Yüreğinin sonsuzluğunda büyüdü sancıları.', 'Sessiz ve soluksuz bir gecenin Kırık yansımalarıydı içimizdeki Avuçlarımızdan kirli, kırık Çakıl taşları kayıyordu durmadan Açılmıştı yalnız...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cakil-tasi-yalnizligimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tövbe', 'tovbe-ahmet-tevfik-ozan-4ojqy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerin aklıma geliyor

“Vursam..vursam mı? ” diyorum...

Allah, hayırlısını versin

Günaha mı giriyorum? ...', 'Gözlerin aklıma geliyor “Vursam..vursam mı? ” diyorum... Allah, hayırlısını versin Günaha mı giriyorum? ......', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tovbe-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmgeleri Kıskandırır Gözlerin', 'i-mgeleri-kiskandirir-gozlerin-selahattin-yetgin-7jo6c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kökü bahçemde büyüyen nazlı çiçek

Güzelliğini ruhumda büyüten sözcük şairesi

İmgelerin kurtarılmış bölgesidir gözlerin

Kendi çölümüzde büyür gölgesi, büyür hecesi.

Asmalara simli salkımlar sakladım bulasın diye

Karlı yüce dağlara lacivert düşlerimi sakladım

Kanatlarında sevgi taşıyan yırtıcı şahinleri

Gömütlüklerin en eskisine, en ulusuna astım.

Çingene gözlü bir gecenin zilli oynayışlarında

Ruhumuzun kış günlerinde tümceli bir sevdayla

Yalnızca sesimizi aradık geceleri üşümelerimizde

Venüs güzelliğinin sarmaşıklarıydı aradığımız.

Kapıları hep kapalı kalan takvim yalnızlığımızın

Bu kaçıncı sonbaharı, kaçıncı hercai menekşesi

Bir sigara dumanıdır ölüm, her nefeste savrulur

Terimizi ısıtacak kavuşmalardır özlediğimiz.', 'Kökü bahçemde büyüyen nazlı çiçek Güzelliğini ruhumda büyüten sözcük şairesi İmgelerin kurtarılmış bölgesidir gözlerin Kendi çölümüzde büyür...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/imgeleri-kiskandirir-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birlikte Tamlanalım', 'birlikte-tamlanalim-selahattin-yetgin-b7fad', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sıkılan avuçlarımdaki kader çizgisi notlarında

Üzerimdeki bu hantallığı da atacağım elbet

Hiçbir şeyin yoktan var edilmediği bu atlasta

Senin için zırdeli, senin için hidayda olacağım.

Demli bir çay dinginliğinde, ıhlamurlar altında

Sesini yüzüme vurmandan, canıma can katmandan

Hiçbir yaramın iyileşmediği bu hasta yatağından

İğnesiz, neştersiz çığlık çığlığa nasılsa kalkacağım.

Bastır dişlerini göğsüme, yol ellerinle şair düşlerimi

Ölümden önceki bir mevsimde seninle bütün olalım

Hayatın küskünlüğüne, gelgitlerine asla aldırmadan

Bu rezil dünyanın deminde, aşkla birlikte tamlanalım.', 'Sıkılan avuçlarımdaki kader çizgisi notlarında Üzerimdeki bu hantallığı da atacağım elbet Hiçbir şeyin yoktan var edilmediği bu atlasta Seni...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/birlikte-tamlanalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavuşmayı Diliyordunuz....', 'kavusmayi-diliyordunuz-adil-nevzat-6xuza', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kavuşmayı diliyordunuz. 

Kavuştunuz. 

Sarılıp yatalım diyordunuz. 

Liseli aşıklar gibiydiniz… 

Yetmedimi…..

Eğer ki bu bir macera ise,

Bir gün bitmeyecek mi? 

Benim duygularım da var. 

Sizler bilmesenizde.. 

Benim de dayanma sınırım var.

Bilmesemde…

Sevginin de bir ruhu  var….

Hissetmesende….

                             Adil Nevzat', 'Kavuşmayı diliyordunuz.  Kavuştunuz.  Sarılıp yatalım diyordunuz.  Liseli aşıklar gibiydiniz…  Yetmedimi….. Eğer ki bu bir macera ise, Bir g...', ARRAY['Türk Edebiyatı','Şiir','Adil Nevzat']::text[], 8.5, '{"poet":"Adil Nevzat","poet_slug":"adil-nevzat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kavusmayi-diliyordunuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgarım ol..', 'ruzgarim-ol-taner-nisanci-628go', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüzgarım ol,savur beni sevdiğim

Divane desinler inan razıyım

Leyla''nın dengi bilip de sevdiğim

Mecnunu desinler inan razıyım

Bana cennet,bütün dünya seninle

Sarhoş ettin,içirmeden dilinle

Zülfün telini tarayan elinle

Rüzgarım ol,savur beni sevdiğim

At yerden yere,parala ezerek

Aşkım ayan olsun dilde gezerek

Dağda taşta hoyrat hoyrat esrek

Rüzgarım ol savur beni sevdiğim

Ceylan misali sekerek gelişin

Nede yakışır yüzüne gülüşün

Coşsun gönülde yalazlı ateşin

Rüzgarım ol savur beni sevdiğim

Bir Garip benim; Derdime lokmansın

Elimden tutup feryadı duyansın

Ten kafeste,can otağa sultansın

Rüzgarım ol savur beni sevdiğim

                          22/03/2005

Anadolu sevdası adlı şiir kitabımdan-(Gündüz kitabevi yayınları-2005)', 'Rüzgarım ol,savur beni sevdiğim Divane desinler inan razıyım Leyla''nın dengi bilip de sevdiğim Mecnunu desinler inan razıyım Bana cennet,büt...', ARRAY['Türk Edebiyatı','Şiir','Taner Nişancı']::text[], 8.5, '{"poet":"Taner Nişancı","poet_slug":"taner-nisanci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ruzgarim-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rahmetli babamdan bir anı', 'rahmetli-babamdan-bir-ani-munevver-senol-64cw5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rahmetli babamdan bir anı.

Rahmetli çerkez mahmut kalfa çokmukallit,yeni adıyla espirili bir insandı,elinden,bırakmadığı,mızıkasını,yani akordionun küçüğü,her yere onunla giderdi,parmaklarının ucunda kazaska oynar,tam bir cemiyet adamıydı,insanların küçüğü büyüğü saygı duyar çok severlerdi,bir gün sakaryanın,çaybaşı köyüne,ailesinigörmeye gittiğinde,akşamda arkadaşları

onu ağırlamak için,sofralar kurulmuş,sohbet başlamış tabi mızıka eşliğinde,

çerkez oyunları,ama mahmut kalfa kendi akranlarıyla,özel sohbeti özlemiş öbürlerinide kırmak istemiyor,dedikya çok mukallit,hemen sivri zekasını çalıştırıyor,biliyormusunuz ben aslında ticaret yapmaya geldim,herkes merakla dinliyor,eğer sizde isterseniz beraber yaparız,ben,kaplumbağaticaretine başladım tanesi,şukadardan,alıyorum,adapazarında,yeni caminin orada  aman canım binalbant mehmet ustaya veriyorum,ordanda haftada bir kamyon gelip alıyor yutdışına gidiyor,aranızda bu işe talip kim varsa alın şukadar avans 

gençerin hepsi talip,mahmut kalfanın aradığıda o zaten hepsine,üçbeş herneyse veriyor,topladıklarını nalbant mehmet ustaya götürüp paranın tamamınıda ondan alıcaklar,tabi çok seviniyorlar OOO,köyde kaplumbağadan bol ne var, vay miğdesiz gavurlar demek kaplumbağayı bile yiyiyorlar,aman canım bizene,yesinler bizde para kazanırız diye seviniyorlar köy yerinde,para sıkıntısı her zaman yaşanır çünki seneden seneye hasat zamanı elleri kıt kanaat para görür,o gece sabaha kadar üç çuvaldolusu kaplumbağa toplarlar herkes kaçtane toplamış yazarlar,sabahta hemen sarı öküzühazırlar iki kişideyardımcı alıp doğru adapazarına,yeni caminin ordaki nalbant mehmet ustanın dükkanına,neyse havada çok sıcaktır,ama inşallah kaplumbağalar ölmemiştir,selamun aleyküm,biz geldik,hayrola? bir çırpıda anlatıyorlar meseleyi,mehmet usta içinden neler demiyorki mahmut kalfaya onun bu vukuatı bir değil beş değil,ama bozuntuya vermemek için çocuklar,geç kaldınız sabah kamyon hareket etti, şimdi üç çuval için,araba kalkmaz siz şimdi gidin bunu mahmuta verin o bir yolunu bulur gönderir,gençler,neyapacağını,şaşırmıştır,okadar zahmetle topladıkları hayvanlar köyde hevesle kendilerini bekleyen arkadaşları,bu hayvanlara günah dönünceye kadar ölürler en iyisi salalım gitsin zaten mahmut abi parasınıda ödemişti,derler çuvalların ağızını açar salarlar,ama oda ne,kaplumbağalar çimenlere değil asvalta doğru giderler,trafik durur polis gelir,çabuk bunları toplayın trafiği felç ettiniz,gençler bir yandan toplayıp çuvala koyarken isyanda ediyorlardı,bilmedikleri işe kalktıkları için ama bunun,mahmut abilerinin şakası olduğnu tahmin etmeleri lazımdı,ama güldü geçildi,anı olarak anlatıldı yıllarca bakın şimdide bunu sizlerle paylaşıyorum,şimdi olsa alimallah adamı,mahkemeye verirler,rahmetli,cem karacanın,MAKEMEYE  VERSEM SENİ ASARLAR,şarkısındaki gibi.

 Bugün 13.11 2005.pazar  bu anıyı sizinle paylaşayım istedim', 'Rahmetli babamdan bir anı. Rahmetli çerkez mahmut kalfa çokmukallit,yeni adıyla espirili bir insandı,elinden,bırakmadığı,mızıkasını,yani ako...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/rahmetli-babamdan-bir-ani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tesekkür ediyorum', 'tesekkur-ediyorum-serpil-maglicoglu-cmo19', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Insan kendisini her gün yeniden yaratir

Dogan günesle yeniden dogar

Her nefes verisiyle bir ölüm yasar

Yasananlarla yogrulur, ögrenir

Bir sonraki güne hazirlanir, güclenir

Tecrübeleriyle filizlenir, dallanir.

Zamanla sevincin ve acinin

Ayni kazanda kaynadigini görür

Secim hakki oldugunu fark eder

Ve gün gelir, sabah uyandiginda

Ben bugünümü mutlu bir insan olarak

Gecirecegim, kararim budur der.

Ve gün gelir, karsilastigi her insanin 

Bir vesile olduguna inanir

Kendi gölgesinin bir yansimasi

Hüzün ve aci yerine

Tesekkür etmenin dogru oldugunu

Yolunun kesistigi her CAN in önünde

Saygiyla egilmek gerektigini', 'Insan kendisini her gün yeniden yaratir Dogan günesle yeniden dogar Her nefes verisiyle bir ölüm yasar Yasananlarla yogrulur, ögrenir Bir so...', ARRAY['Türk Edebiyatı','Şiir','Serpil Maglicoglu']::text[], 8.5, '{"poet":"Serpil Maglicoglu","poet_slug":"serpil-maglicoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/tesekkur-ediyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürce', 'ozgurce-serpil-maglicoglu-69b3m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ölürüm, yapamam, yasayamam sensizleri

Hic sevemedim ben.

Insan hakkini alabilmeli yasamdan

Kendi dengesini saglamali

Aglamali, aglamak istediginde

Ve gülmeli, gülebildiginde

Doyasiya sevmeli

Ve gidebilmeli özgürce

Gitmek gerektiginde', 'Ölürüm, yapamam, yasayamam sensizleri Hic sevemedim ben. Insan hakkini alabilmeli yasamdan Kendi dengesini saglamali Aglamali, aglamak isted...', ARRAY['Türk Edebiyatı','Şiir','Serpil Maglicoglu']::text[], 8.5, '{"poet":"Serpil Maglicoglu","poet_slug":"serpil-maglicoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ozgurce-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düsünceler', 'dusunceler-serpil-maglicoglu-2mz2p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dev dalgalar misali

Beni kaplayan duygularim da

Bogulabilirim korkusuna

Kapilmistim bir an

Oysa duygular degil

Insani bogan

Körce düsünülen 

Düsünceler', 'Dev dalgalar misali Beni kaplayan duygularim da Bogulabilirim korkusuna Kapilmistim bir an Oysa duygular degil Insani bogan Körce düsünülen ...', ARRAY['Türk Edebiyatı','Şiir','Serpil Maglicoglu']::text[], 8.5, '{"poet":"Serpil Maglicoglu","poet_slug":"serpil-maglicoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dusunceler-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-hasan-cangir-ljffs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seni sevdiğimi 

sana  nasıl anlatayım 

geceler boyu uykusuz kalışım

hiç bir şey düşünmeyip seni 

düşünmem akılmdan çıkmaman yeterli deilmi

sence  o zaman

soruyorum sana şimdi 

seni sevdiğimi 

sana nasıl anlatayım

evet 

hiç bir şey diyemiyorsun deil mi 

o zaman seni sevdiğimi neden inkar ediyorsun 

neden neden zelom neden

   Seni Sevdiğim Kadar İbadet Etseydim Şu Anda:

Cennette Köşküm  Olurdu......

dün  gece boyunca bilgisayar başında kaldım ve 

 bu şiiri sana gece saat 2 de yazdım zelom', 'seni sevdiğimi  sana  nasıl anlatayım  geceler boyu uykusuz kalışım hiç bir şey düşünmeyip seni  düşünmem akılmdan çıkmaman yeterli deilmi s...', ARRAY['Türk Edebiyatı','Şiir','Hasan Cangir']::text[], 8.5, '{"poet":"Hasan Cangir","poet_slug":"hasan-cangir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/neden-196-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günün Kutlu Olsun', 'gunun-kutlu-olsun-hidir-altas-22lor', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün sizlerin anacığım

Günün kutlu ve mutlu olsun

Sen her zaman gül,neşeli ol

Oğlum gurbette diye üzülme

Koşarda gelirim anacığım

Koşup elini öpmek isterim

Sana bir demet çiçek vermek

Halini hatrını sormak isterim

Yollar uzun,dağlar engel bana

Üzülme anacığım sen hiç

Yolları geçer,dağları aşar gelirim

Ben burda kızın başka yerde

Sense koskoca ıssız bir evde

Kader bu birgün elbet bitecek

Birgün elbet sende güleceksin

Ama yıllar geçecek,bir asır gibi

Hasret bitecek,kavuşacağız anacığım

Turhani hap yanında olmak ister

İsterde eli kolu bağlı,çaresiz

Oturur,elinde kalem yazar,çizer

Ancak elinden bu gelir anacığım

Bugün anneler günü haberin olsun

Günün kutlu ve mutlu olsun.', 'Bugün sizlerin anacığım Günün kutlu ve mutlu olsun Sen her zaman gül,neşeli ol Oğlum gurbette diye üzülme Koşarda gelirim anacığım Koşup eli...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Altaş']::text[], 8.5, '{"poet":"Hıdır Altaş","poet_slug":"hidir-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gunun-kutlu-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsimler Değişmeden Gel', 'mevsimler-degismeden-gel-salim-erben-n45ae', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Soğuk bir kış günü dokunursa

Yüreğine sıcak bir dost eli 

Kor ateşler kül olmadan gel

Duru bir şiir gibi

Dilden düşmeyen namelerle gel

Feryadın acıdır bilinmez yönleri

Sen yine 

Temiz firar sız duygularınla gel

Umuda yelken açar gibi

Bir kez olsun görmek için gözlerini 

Son arzuyu yerine getirmek için gel

Gel

Düşürmeden toprağa bedenimi 

Aldığım nefeste bir sen varsın 

Son nefesim beni terk etmeden gel 

Gel zalım gel', 'Soğuk bir kış günü dokunursa Yüreğine sıcak bir dost eli  Kor ateşler kül olmadan gel Duru bir şiir gibi Dilden düşmeyen namelerle gel Ferya...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mevsimler-degismeden-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-hidir-altas-l6an4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aldım sazı elime

Düştüm gurbet iline

Gahu ağlar gahu güler

Düştüm gurbet ililne

Gurbet beni dal eyledi

Yaktı yaktı kül eyledi

Hasret ile özlem ile

Beni harap eyledi

Gözümden aktı yaşlar

Eğildi öne başlar

Ben gurbette yar sılada

Gece gündüz durmaz ağlar

Vurdum sazın teline

Yar oldum gurbet iline

Hasret kaldım ben gurbette

Yarin tatlı dillerine

Aşık Turhani diyor ki; 

Gam yüklü benim gönlüm

Gahu ağlar gahu güler

Biter gurbette ömrüm', 'Aldım sazı elime Düştüm gurbet iline Gahu ağlar gahu güler Düştüm gurbet ililne Gurbet beni dal eyledi Yaktı yaktı kül eyledi Hasret ile özl...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Altaş']::text[], 8.5, '{"poet":"Hıdır Altaş","poet_slug":"hidir-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gurbet-101-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf-ı Kusur', 'i-tiraf-i-kusur-abdullah-odabas-u6l0v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hamdü sena sana Yarab,            		

Tamam oldu işte kitap,			

Çoktur hata yoktur sevap,               		

Bağışla cürmüm İlahi.                   		

Halefime hizmet olsun,                 	 	

Beni rahmet ile ansın,                  		

Ecdadıma hisse varsın,                  		

Bağışla cürmüm İlahi.                   		

Rızana olsun vesile,                    		

Gitsin kitap elden ele,                 		

Ka''rilerim kılsın dua,                  		

Bağışla cürmüm İlahi.                   		

Yoktur kapı başka gidem,              		

Gönül hasta ağlar didem,              		

Kime bu halim arzedem,                		

Bağışla cürmüm İlahi.                   		

İsmi Azam hürmetine,                   		

Levh-i kalem hürmetine,               		

Arz-ı sema hürmetine,                   		

Bağışla cürmüm İlahi.                   		

Habibine resullere,                     		

Sahabi ve has kullara,                  		

Doğru giden Hak yollara,              		

Bağışla cürmüm İlahi.                   		

Velilere, tuyur, kuşa,

Seherlerde akan yaşa,

Beyti azam Hacer taşa,

Bağışla cürmüm İlahi.

Safa, Merve koşanlara,

Arafat''da coşanlara,

Aşk-ı Hakla pişenlere,

Bağışla cürmüm İlahi.

Tavaf döner gece gündüz,

Ne mutludur gören o göz,

Ceset yanar tutuşur öz,

Bağışla cürmüm İlahi.

Medine-i Münevvere,

Gönder bizi Peygambere,

Bu dertliye ilaç vere,

Bağışla cürmüm İlahi.

Dünya uhra ver selamet,

Salim geçelim o sırat,

Nardan halasa ver berat,

Bağışla cürmüm İlahi.

Meftuni''yem biçareyem,

Baştan ayağa yareyem,

Medet pirim ümit varam,

Bağışla cürmüm İlahi.', 'Hamdü sena sana Yarab,            		 Tamam oldu işte kitap,			 Çoktur hata yoktur sevap,               		 Bağışla cürmüm İlahi.             ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/itiraf-i-kusur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalp Yolları', 'kalp-yollari-abdullah-odabas-2fs86', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalp yolunu temizlemek,                		

Gayet müşkil, hayli emek,              		

Gaflet geyirmiştir gömlek,             		

Halas eyle Yarabbena.                   		

Hubbi siva hubbi zenan,                		

Bu nefs elinden elaman,                		

Gitmez başımdan duman,              		

Halas eyle Yarabbena.                   		

Nefis dağı cebelleri,                   		

Karlı duman hep belleri,                		

Gayet hatarlı yolları,                  		

Halas eyle Yarabbena.                   		

Her tarafı vahşi dolu,                  		

Göstermezler sağı solu,                 		

Saptırırlar doğru yolu,                 		

Halas eyle Yarabbena.                   		

Nefis şeytan şerik olmuş,               		

Hak yoluna tuzak kurmuş,             		

Aklı kamil anı bilmiş,                  		

Halas eyle Yarabbena.                   		

Enis eyle kamillere,

Munis eyle amillere,                    		

Tevhidin ver bu dillere,

Halas eyle Yarabbena.             		

Geçtik cüz-ı iradeden,

Kaldır perdeyi aradan,

Kurtar nefsi bed-hareden,

Halas eyle Yarabbena.

Ağlaşalım derdimize,

Şad varalım yurdumuza,

Düşman gezer ardımıza,

Halas eyle Yarabbena.

Müyesser kıl cemalini,

Göster bize didarını,

Mağfiret kıl kullarını,

Halas eyle Yarabbena.

Sözüm çoktur yüzüm yoktur,

Aşk oduna beni yaktır,

Hırs dağını bize yıktır,

Halas eyle Yarabbena.

Ne amel var ne icrası,

Günahkarım gayet asi,

Götür kalbimden bu pası,

Halas eyle Yarabbena.

Meftuni''yim bed-hevahım,

Alemlere çıkar ahım,

Ümidim sen padişahım,

Halas eyle Yarabbena.', 'Kalp yolunu temizlemek,                		 Gayet müşkil, hayli emek,              		 Gaflet geyirmiştir gömlek,             		 Halas eyle Yar...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/kalp-yollari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muradım Ver', 'muradim-ver-abdullah-odabas-5oxjj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ateş düştü özüme,                       		

Yaşlar doldu gözüme,                    		

Bakmam oğul kızıma,                     		

Muradım ver ilahi.                      		

Yansın ateşe özüm,                      		

İsmindir heran sözüm,                   		

Kabul et bu niyazım,                    		

Muradım ver ilahi.                      		

Sivadan beni kurtar,                    		

Gittikçe derdim artar,                  		

Gaflet gözümü örter,                    		

Muradım ver ilahi.                      		

Aklım fikrim bir eyle,                  		

Nefsim gözün kör eyle,                 		

Dost eline yol eyle,                    		

Muradım ver ilahi.                      		

Dostta vuslat bulayım,

Aşkın ile dolayım,

Bahçede gül olayım,

Muradım ver ilahi.

Binbir ismin Hürmeti,

Hem Muhammet Hazreti,

Cehimde ver beratı,

Muradım ver ilahi.

Pirler elinden kadeh,

 Gönlümüz bulsun felah,

Nefs(i)  emmareye silah,

Muradım ver ilahi.

Meftuni kapı döğer,

Huzurda boyun eğer,

Bilmem melul şad döner,

Muradım ver ilahi.', 'Ateş düştü özüme,                       		 Yaşlar doldu gözüme,                    		 Bakmam oğul kızıma,                     		 Muradım ver...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/muradim-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelime-i Tevhid', 'kelime-i-tevhid-abdullah-odabas-nv5nr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sür gönülden sivayı,                    		

Olma sakın mürai,                       		

Zikreyle hem Hüda''yı,                  		

Lailahe illallah.                       		

Oku Kur''an, yasinden,                   		

Su iç ihlas tasından,                   		

Kurtar gönül pasından,                  		

Lailahe illallah.                       		

Kır bu gaflet taşını,                   		

Dök yere göz yaşını,                    		

O yola koy başını,                      		

Lailahe illallah.                       		

Pirler izini izle,                      		

Şeyhin gözünü gözle,                    		

Gel kardaş ol bizimle,                  		

Lailahe illallah.                       		

Kır bu arı çal yere,                    		

Varalım Peygambere,                    		

Dertlere derman vere,                   		

Lailahe illallah.                       		

Tevhid oku, aretme,

Yerini sen naretme,

Aşk ile güzaf etme,

Lailahe illallah.

Tevhid oku kalp açar,

Şeytan kafesten kaçar,

Gel, olma böyle naçar,

Lailahe illallah.

Pirimiz Nakşıbendi,

Memleket Semerkandi,

Çizilsin kalbin bendi,

Lailahe illallah.

Semerkandi Buhara,

Hep yandılar bu nara,

Ara bul derde çare,

Lailahe illallah.

Derviş olup derde düş,

Allah deyip yanda piş,

Kalmasın kalpte teşviş,

Lailahe illallah.

Meftuni, insaf eyle,

Derun-ü dilden söyle,

Can ravzasın nur eyle,

Lailahe illallah.

.', 'Sür gönülden sivayı,                    		 Olma sakın mürai,                       		 Zikreyle hem Hüda''yı,                  		 Lailahe illa...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/kelime-i-tevhid-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Münacat', 'munacat-abdullah-odabas-bbx61', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gönlümü sivadan kes,                    		

Meylimi hevadan kes,                    		

Zikrim olsun her nefes,                 		

Lailahe illallah.                       		

Kurtar beni hakeyle,                    		

İçim dışım pakeyle,                    		

Başka gelmesin dile,                    		

Lailahe illallah.                       		

Kalbimin kapısın aç,                    		

Bu derdime ver ilaç,                    		

Bende olayım Hallaç,                    		

Lailahe illallah.                       		

Aşk darına as beni,                     		

Bende bulayım seni,                     		

Neyleyim gayri yari,                    		

Lailahe illallah.                       		

Visale ersem mi ya,                     		

Vechini görsem mi ya,                  		

Billahi değil riya,                     		

Lailahe illallah.                       		

Mustafa hakkı olsun,

Saraya canan gelsin,

Dertlere derman versin,

Lailahe illallah.

Himmeti enbiyalar,

Rifati evliyalar,

Caryari ba safalar,

Lailahe illallah.

Cümle mahluk yüz suyu,

Etme beni rüsvayı,

Birlemişem Hüdayı,

Lailahe illallah.

Hüda birdir gayri yok,

Seni seven kullar çok,

Münkirlerle işim yok,

Lailahe illallah.

Nefyi isbat eylerem,

Dilde ismin söylerem,

Meftuni sen yeme gam,

Lailahe illallah.', 'Gönlümü sivadan kes,                    		 Meylimi hevadan kes,                    		 Zikrim olsun her nefes,                 		 Lailahe ill...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/munacat-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kulunu Mahrum Eyleme', 'kulunu-mahrum-eyleme-abdullah-odabas-d0649', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mevlayı seven can-ı gönüller,           	

Her gece seher nöbeti bekler,          	

Sanma ki zayi olur emekler,            	

Kulunu mahrum eyleme Yarab.   	

Mevla''yı seven sıdg ile sadık,          	

Şüphesiz olur her seher ayık,           	

Uyumaz çünkü ciğeri yanık,               	

Kulunu mahrum eyleme Yarab.             	

Mevla''yı seven dalmaz uykuya,           	

Dünyanın gamını atar arkaya,            	

Nasıl uyusun düşmüş korkuya,            	

Kulunu mahrum eyleme Yarab.             	

Mevla''yı seven aheder gezer,            	

O Lain şeytanın bağrını ezer,           	

Cennette makamın bağını bezer,          	

Kulunu mahrum eyleme Yarab.             	

Mevla''yı sevenin budur efkarı,

Her zaman düşünür ahirki günü,

Dilinde bulunur Hakkın zikiri,

Kulunu mahrum eyleme Yarab.

Mevla''yı seven şadolur herdem,

Haliktan ister derdine merhem,

Söylemez esrarı bir kere sorsam,

Kulunu mahrum eyleme Yarab.

Mevla''yı sevenler sararup solar,

Gahi ağlar ise gahide güler,

O vahdet bağının güllerin derer,

Kulunu mahrum eyleme Yarab.

Seversen Meftuni sende Mevla''yı,

Çıkar şu kalbinden ücb-i riyayı,

Olasın Mevla''nın sıdg ile yari,

Kulunu mahrum eyleme Yarab.', 'Mevlayı seven can-ı gönüller,           	 Her gece seher nöbeti bekler,          	 Sanma ki zayi olur emekler,            	 Kulunu mahrum ey...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kulunu-mahrum-eyleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhabbet-i Meşayıh', 'muhabbet-i-mesayih-abdullah-odabas-oqe0f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şeyhim şanın olsun ali,                 		

Gösterirsen doğru yolu,                 		

Dost bağının bir bülbülü,               		

Kurban olam şeyhim sana.            		

Menam''ında methin gördüm,     		

El bağlayıp divan durdum,            		

Bu derdime merhem buldum,       		

Kurban olam şeyhim sana.               	

	

İsmin duyan eder hicap,                 		

Yandı ciğer oldu kebap,                		

Müyesser kıl bizi Yarab,                		

Kurban olam şeyhim sana.               	

Şeyhim: himmet buyur bize,              	

İlaç eyle, bu kör göze,                 		

Aşık oldum taban yüze,                  		

Kurban olam şeyhim sana.                	

Himmet buyur, bir miskinem,            	

Nefs(i)  emmare deldi sinem,             	

Aşkınla kül olup yanam,                 		

Kurban olam şeyhim sana.                 	

Sohbetinden dur olmayam,

Aşk içinde hor olmayam,

Rah-i Hakdan ayrılmayam,

Kurban olam şeyhim sana.

Sohbetindir safa cana,

Dursun dervişler divana,

İçlerinde bir divane,

Kurban olam şeyhim sana.

	

Tarık-i Nakşi''de şahsın,

Gökyüzünde sanki mahsın,

Şarkı garbı ruşen etsin,

Kurban olam şeyhim sana.

Yolu yanlış giden kişi,

Mürşitlere atma taşı,

Mürşitler bir Hak güneşi,

Meftuni, bir abdal derviş,

Cehdeyle sen dosta eriş,

Aşk-ı Hakla yanıp da piş,

Kurban olam şeyhim sana', 'Şeyhim şanın olsun ali,                 		 Gösterirsen doğru yolu,                 		 Dost bağının bir bülbülü,               		 Kurban olam...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/muhabbet-i-mesayih-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Soru Bir Cevap Yahut Ya O Kurşun', 'i-ki-soru-bir-cevap-yahut-ya-o-kursun-adem-tok-sjiiz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-sen ölmemişmiydin

-her çağrılan yere gitmek 

mecburiyetinde miyim...

                                                (12.11.05) 

                                                 sarıgazi', '-sen ölmemişmiydin -her çağrılan yere gitmek  mecburiyetinde miyim...                                                 (12.11.05)            ...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/iki-soru-bir-cevap-yahut-ya-o-kursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çeşitleme', 'cesitleme-selma-erdeviren-0v8x5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Okumayı seversin,

Bir büyük tutku olur içinde.

Koparıp atamazsın,

İçine içine girersin.

Küçüldüğünü farkedersin gitgide

Onun yüceliğinde.

Suyu emen sünger gibi

Yavaş yavaş yutar seni ilim dediğin.

Gün gelir seversin, masal güzelliğinde.

Kanatlanmıştır duyguların bir kez,

Dünya daralır daralır bir şey yapamazsın.

Yalnız o vardır senin için; 

Bir gül olur düşlerinde, hayallerinde.

Erirsin kaderin ellerinde.

Hayal kırıklığı insan içindir,

Bir gün diken olup batar sana gülüm dediğin.

Dünya senin içindir hep; 

Ölüm uzakta çok uzakta bir nokta,

Daha görünmedi bile ufukta dersin.

Oysa o davulla zurnayla gelmez.

Bir gece sessizliğinde adım adım yaklaşır,

Düşünmek bile istemediğin karanlıklar diyarında

Dilsizler kervanına katar seni ölüm dediğin.', 'Okumayı seversin, Bir büyük tutku olur içinde. Koparıp atamazsın, İçine içine girersin. Küçüldüğünü farkedersin gitgide Onun yüceliğinde. Su...', ARRAY['Türk Edebiyatı','Şiir','Selma Erdeviren']::text[], 8.5, '{"poet":"Selma Erdeviren","poet_slug":"selma-erdeviren","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/cesitleme-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak (I)', 'yasamak-i-selma-erdeviren-y132z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsanlar özgür, hayvanlar değil; 

Böyle bir ortamda

Yaşamak bir saltanattır.

Sevince insan,

Kalbini açınca bir kişiye

Yaşamak bir çift kanattır.

Zaman önde biz arkada

Koşuyoruz hergün ayrı bir hızla.

Bu koşullar içinde

Yaşamak bir büyük sanattır.', 'İnsanlar özgür, hayvanlar değil;  Böyle bir ortamda Yaşamak bir saltanattır. Sevince insan, Kalbini açınca bir kişiye Yaşamak bir çift kanat...', ARRAY['Türk Edebiyatı','Şiir','Selma Erdeviren']::text[], 8.5, '{"poet":"Selma Erdeviren","poet_slug":"selma-erdeviren","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yasamak-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Öğretmenden', 'bir-ogretmenden-selma-erdeviren-qogml', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sizin için yaşıyorum ben,

Sizin için çocuklarım.

Rüzgarın sesinde sizi

Güneşin sıcağında ellerinizi

Mavi denizlerde gözlerinizi görüyorum.

Geleceğinizi görüyorum, pırıl pırıl...

Günleriniz aydın, günleriniz ak.

Bir ışıklı gelecek berrak mı berrak.

Yürüyün, arkanızda ben varım.

Haydi, daha ileri çocuklarım.

Küçük fidanlarım benim

Görüyorsunuz, size açık kollarım.

Biliniz ki çalıştıkça

Bugünden daha güzel yarın.', 'Sizin için yaşıyorum ben, Sizin için çocuklarım. Rüzgarın sesinde sizi Güneşin sıcağında ellerinizi Mavi denizlerde gözlerinizi görüyorum. G...', ARRAY['Türk Edebiyatı','Şiir','Selma Erdeviren']::text[], 8.5, '{"poet":"Selma Erdeviren","poet_slug":"selma-erdeviren","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-ogretmenden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç', 'hic-umut-aygun-fmt4i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben bir hiçim, der dururum; 

Hiçliği yerinden kaldırmaz uyuturum....

Umut Aygün', 'Ben bir hiçim, der dururum;  Hiçliği yerinden kaldırmaz uyuturum.... Umut Aygün...', ARRAY['Türk Edebiyatı','Şiir','Umut Aygün']::text[], 8.5, '{"poet":"Umut Aygün","poet_slug":"umut-aygun","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/hic-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak (II)', 'yasamak-ii-selma-erdeviren-xf3yg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşamak bin bir güçlükle dolu

Ve seninle aramızda binlerce duvar.

Her şeye rağmen çok seviyorum

Yaşamayı seni sevdiğim gibi,

Seni yaşamak kadar.

Gelir takılır bazen aklıma

Acı dolu hatıralar.

Gözlerin gözlerime saatlerce bakar,

Hasret koymuşlar adını bir şey var içimi yakar.

Yine de çok seviyorum seni

Yaşamayı sevdiğim kadar.', 'Yaşamak bin bir güçlükle dolu Ve seninle aramızda binlerce duvar. Her şeye rağmen çok seviyorum Yaşamayı seni sevdiğim gibi, Seni yaşamak ka...', ARRAY['Türk Edebiyatı','Şiir','Selma Erdeviren']::text[], 8.5, '{"poet":"Selma Erdeviren","poet_slug":"selma-erdeviren","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yasamak-ii-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman...', 'zaman-pinar-koc-qvz6y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Z A M A N

Zamanından önce doğdu sıcak güneşim,

Zamanından sonra geldim dünyaya…

Zamanından önce üşüdü ellerim,

Zamanından sonra tutuştu yüreğim…

Ya zamanlı ya zamansız sevdim! 

Ya zamanlı  zamansız terk edildim…

Zamanından önce kaybolduysa benliğim,

Zamanından sonra buldum seni sevdiğim…

                                                                            06.09.2005    23:44', 'Z A M A N Zamanından önce doğdu sıcak güneşim, Zamanından sonra geldim dünyaya… Zamanından önce üşüdü ellerim, Zamanından sonra tutuştu yüre...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zaman-254-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne', 'ne-umut-aygun-hsrm2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'mum nedir, ben ne,

aradaki fark ne..

ben biterim, mum biter,

etrafı aydınlatan ne...', 'mum nedir, ben ne, aradaki fark ne.. ben biterim, mum biter, etrafı aydınlatan ne......', ARRAY['Türk Edebiyatı','Şiir','Umut Aygün']::text[], 8.5, '{"poet":"Umut Aygün","poet_slug":"umut-aygun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ne-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm ne zaman seveceksin beni', 'gulum-ne-zaman-seveceksin-beni-i-sa-tekin-nkdzz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülüm 

Ne zaman seveceksin beni? 

Saati, günü, gecesi

Haftası, ayı, bellimi

Söyle öyle geleyim

Gülüm beni hangi 

Renkte seveceksin

Kırmızı, mavi

Siyah, beyaz

Yeşil, sarı

Rengini söyle öyle geleyim gülüm

Gülüm

Beni gecemi, gündüz mü? 

Kardamı, yağmurda mı? 

Güneşte mi, fırtınada mı? 

Ne zaman seveceksin beni

Ne zaman gülüm

Söyle gülüm

Söyle öyle geleyim', 'Gülüm  Ne zaman seveceksin beni?  Saati, günü, gecesi Haftası, ayı, bellimi Söyle öyle geleyim Gülüm beni hangi  Renkte seveceksin Kırmızı, ...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gulum-ne-zaman-seveceksin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum', 'biliyorum-selma-erdeviren-djcg4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayların değil yılların sevdası, biliyorum,

Yüreğinde bir türlü küllenemeyen.

Ayların değil yılların sevdası, biliyorum,

Dilinin ucuna gelip gelip de söylenemeyen.

Seni her gün bu dünyadan biraz daha uzaklara iten

Ayların değil yılların sevdası, biliyorum,

Biliyorum.', 'Ayların değil yılların sevdası, biliyorum, Yüreğinde bir türlü küllenemeyen. Ayların değil yılların sevdası, biliyorum, Dilinin ucuna gelip ...', ARRAY['Türk Edebiyatı','Şiir','Selma Erdeviren']::text[], 8.5, '{"poet":"Selma Erdeviren","poet_slug":"selma-erdeviren","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/biliyorum-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzlerlmi bıraktım tırnaklarımla...', 'i-zlerlmi-biraktim-tirnaklarimla-pinar-koc-alliw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İzlerlmi bıraktım tırnaklarımla

Kahpe gecelerin derin çığlıklarına! 

Yalnızlığın tek başına olmak olduğunu anladım.

Hak verdim akvaryumdaki balığıma.

Yalnızlığın,

Ölümün öbür adı olduğunu anladım…

Ve insanların neden ölmekten korktuğunu,

Ve insanların neden yalnız öldüğünü,

Ve ölülerin neden yalnız olduğunu…

İzlerimi bıraktım tırnaklarımla,

Kahpe gecenin derin çığlıklarına…

                                                                   22.06.2002        

                                                                   cumartesi', 'İzlerlmi bıraktım tırnaklarımla Kahpe gecelerin derin çığlıklarına!  Yalnızlığın tek başına olmak olduğunu anladım. Hak verdim akvaryumdaki ...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/izlerlmi-biraktim-tirnaklarimla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Aşkları...', 'bahar-asklari-pinar-koc-1vkfl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'BAHAR AŞKLARI…

Pembe bir baharın yine akşamındayım…

Yine papatyalar solmaya yüz tutmuş…

Ve yine bir ilkbahardan bir sonbahara…

Yazları yaşanmıyor artık senin ardından.

Hiç hava hep güneşli kalmıyor,

Ve yine hiç yüzüm gülmüyor…

Ağaç dalında bir kuru yaprak,

Geçen sonbahardan kalma sanki… 

ve hiç yazı görmeden 

bir ilkbahardan yine bir sonbahara daha…

kalbimin sıkıştığını hissettiğim anlarda

hep gülümsemeli oluyor yüzüm.

Bir yüzüm hayata bir yüzüm öte dünyaya…

Sarı bir sonbaharın yine akşamındayım..

Yine gelinciklerim açmaya yüz tutmuş.

Ve yine sarı bir sonbahardan,

Pembe bir ilk bahara….

23.03.2004	17:25

k.d.h', 'BAHAR AŞKLARI… Pembe bir baharın yine akşamındayım… Yine papatyalar solmaya yüz tutmuş… Ve yine bir ilkbahardan bir sonbahara… Yazları yaşan...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bahar-asklari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgür''ün Kirpikleri', 'ozgur-un-kirpikleri-selma-erdeviren-99t9r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '- Özgür Kurga için

Özgür bir küçük çocuk; 

Sarışın, tatlı mı tatlı.

Miniminicik elleri,

Ama en ilginci

Uzun, upuzun kirpikleri.

Çok çocuk gördüm ben ve kirpikler,

Her biri bir başka güzel.

Bambaşka bi şey bu çocuk dedikleri

Ama hepsinden başka Özgür''ün kirpikleri.

Kız kardeşim geçen gün

Uzun uzun Özgür''e baktı

Sonra birden elini uzattı.

Özgür''ün kirpiklerine değdirip ellerini

Dedi: Ben aldım kirpiklerini.

Çocuk kızdı, sonra da güldü,

Kardeşimin eline uzandı.

Yalandan kopmuş kirpiklerini eline alıp

O baygın gözlerine taktı.

Sonra gözlerini elleriyle kapattı.

Dedi: Ben aldım işte, taktım onları geri.

Manalı gözlerini çevreledi kirpikleri.

Anladım ki çocuklar

Şakayı gerçeği biliyor.

Kirpik denince aklıma Özgür,

Özgür denince kirpikleri geliyor.', '- Özgür Kurga için Özgür bir küçük çocuk;  Sarışın, tatlı mı tatlı. Miniminicik elleri, Ama en ilginci Uzun, upuzun kirpikleri. Çok çocuk gö...', ARRAY['Türk Edebiyatı','Şiir','Selma Erdeviren']::text[], 8.5, '{"poet":"Selma Erdeviren","poet_slug":"selma-erdeviren","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ozgur-un-kirpikleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksa', 'yoksa-emrah-kanik-y0hm7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Susulmalı mı bu gece? 

Yoksa söylenmeli mi herşey? 

Askıda mı kalmalı mı ''''Seni Seviyorum''''

Yoksa inmeli mi Yureklere

Ağızlar neden kapalı kalmalı? 

Neden susulmalı Bu gece? 

Acı çekmekten mi korkuyosun? 

Yoksa unutulmaktan mı? 

Vazgeçtim ben bu gece

nefretlerimden,kinimden ve nice duydularımdan 

Bu gece yalnızca sevmek olmalı 

Yoksa ÖLMEK?', 'Susulmalı mı bu gece?  Yoksa söylenmeli mi herşey?  Askıda mı kalmalı mı ''''Seni Seviyorum'''' Yoksa inmeli mi Yureklere Ağızlar neden kapalı k...', ARRAY['Türk Edebiyatı','Şiir','Emrah Kanık']::text[], 8.5, '{"poet":"Emrah Kanık","poet_slug":"emrah-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yoksa-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şeyim Yarım Kalacak', 'her-seyim-yarim-kalacak-celal-topo-xhq5p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu sevda bu aşk bu duygular

Anlaşılmadan mısralarımda yarım kalacak

Bilinmeyen bir zamanda çekip gideceğim

Gidişimden hiç kimsenin haberi olmayacak....



12 / 11 / 2005  Antalya', 'Bu sevda bu aşk bu duygular Anlaşılmadan mısralarımda yarım kalacak Bilinmeyen bir zamanda çekip gideceğim Gidişimden hiç kimsenin haberi ol...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/her-seyim-yarim-kalacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peri', 'peri-kemal-guzel-q52y4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'zamanı gelmedimi mutluluğun

istanbul gibi düşünür

diyarbakır gibi seviyorum seni eyy

peri.

rüzgarlara selam yükledim 

sevdiğimi fısıldadım 

sana duyduğum aşkı haykırdım

almadınmı eyy

peri.

sen gelecektin ya

seni mutlu etmek için 

ne şiirler yazdım yazılarım solmakta nerdesin eyy

peri.

yeşil yapraklar 

sararacak nerdeyse

nerdesin eyy

peri.

son defa yıldızlarla konuşacam bu akşam

son defa şiir yazacam bu gece

son defa seher vakti gülecem kuş seslerine

ve son defa doğan güneşle yolunu gözlüyecem

ne olur kendini bana unutturma gel gel

eeyyy peri.

                                           K.G', 'zamanı gelmedimi mutluluğun istanbul gibi düşünür diyarbakır gibi seviyorum seni eyy peri. rüzgarlara selam yükledim  sevdiğimi fısıldadım  ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Güzel']::text[], 8.5, '{"poet":"Kemal Güzel","poet_slug":"kemal-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/peri-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geliyor', 'geliyor-mustafa-yazka-q5wo7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Serin olur salkım söğüt gölgesi,

Kadir gecesi doğurmuş Annesi,

Algüller içinde bir gül destesi,

Bostanlar içinde sekip geliyor.

Deli gönül gece gündüz sayıklar,

Haşhaş tarlasında ot,un ayıklar,

Gençlerin kalbinde derin oyuklar,

Farkında olmadan açıp geliyor.

Çayır ovasında sığırın güder,

Orağı elinde biçmeye gider,

Ekin tarlasında hasadın eder,

Onsekiz yaşına basmış geliyor.

Mustafa bağrı yanık seslenir,

İştahı yok keder ile beslenir,

Çölde su gibi haber beklenir,

Yari tebessümü vermiş geliyor.', 'Serin olur salkım söğüt gölgesi, Kadir gecesi doğurmuş Annesi, Algüller içinde bir gül destesi, Bostanlar içinde sekip geliyor. Deli gönül g...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yazka']::text[], 8.5, '{"poet":"Mustafa Yazka","poet_slug":"mustafa-yazka","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/geliyor-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerimin Baharı', 'hayallerimin-bahari-nilsu-ak-w6wls', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayaller var ya o hayaller

Arzu edipte

Yürekten istersin ya

Oluyor biliyor musun

Buldum kendimi hayallerimde

Ama çok ama az

Bence de kendimce buldum

Sana inat mı

Yoksa 

Bu düzene mi inat

Kurgu içindeki senaryolardaki rollere mi inat

Omuz silkip şımarık çocuk misali

Hayallerimde

Yüzüyorum

Vicdanım kanasa da

Ona da inat

Boğulsam da mantığıma da inat

Bu yalancı bahar 

Herkese inat benim

O 

Hayallerimin baharı', 'Hayaller var ya o hayaller Arzu edipte Yürekten istersin ya Oluyor biliyor musun Buldum kendimi hayallerimde Ama çok ama az Bence de kendimc...', ARRAY['Türk Edebiyatı','Şiir','Nilsu Ak']::text[], 8.5, '{"poet":"Nilsu Ak","poet_slug":"nilsu-ak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hayallerimin-bahari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyan Atam', 'uyan-atam-hidir-altas-criup', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '29 ekim günlerden salı

Polis kurşunlanır, asker öldürülür

Gençlik paramparça, benliğini unutmuş

Uyan Atam; bak gör halimizi

Dost sandığımız Alman bile düşman

İngiliz''i anlatamam sen bilirsin

Fransız''ı Amerikas''ı zaten belli

Uyan Atam; bak gör halimizi

Lozan''ı bitmiş, sevr başlamış sanki

Rum''u Kıbrıs''ı Emeni doğuyu ister

Kardeşimiz Kürtler güneyi ister

Uyan Atam bak gör halimizi

Büyüklermi Atam, onlar oldu çorba

Birisi Cumhurbaşkanıyla uğraşır

Birisi millete küsmüş köşesinde

Uyan Atam; bak gör halimizi

Turhani der Türklük ölüyor

Milliyetçiliğin adı oldu faşistlik

Dinin ise değeri kayboldu şimdi

Uyan Atam; bak gör halimizi', '29 ekim günlerden salı Polis kurşunlanır, asker öldürülür Gençlik paramparça, benliğini unutmuş Uyan Atam; bak gör halimizi Dost sandığımız ...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Altaş']::text[], 8.5, '{"poet":"Hıdır Altaş","poet_slug":"hidir-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uyan-atam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alamazsın', 'alamazsin-selma-erdeviren-no0zu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O gördüğün gülen gözler ardında

Bir acı gerçek vardır, bilemezsin.

Bir şey benliğini kemiri durur,

Herkes gülüyorken sen gülemezsin.

Mutluluğu kazanmak kolay değil,

Elini uzatıp da alamazsın.', 'O gördüğün gülen gözler ardında Bir acı gerçek vardır, bilemezsin. Bir şey benliğini kemiri durur, Herkes gülüyorken sen gülemezsin. Mutlulu...', ARRAY['Türk Edebiyatı','Şiir','Selma Erdeviren']::text[], 8.5, '{"poet":"Selma Erdeviren","poet_slug":"selma-erdeviren","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/alamazsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Mış...Miş', 'mis-mis-mustafa-yazka-6ucit', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu gök neden gürlüyor:Ya aç kalmış ya gaz yapmış.

Peki bu niye hırlıyor:Ya kudurmuş ya uykuya dalmış.

Güneş neden kızarıyor:Ya utanmış ya iftiraya uğramış.

Niye hapse girmiş:Ya iftira yemiş ya öfkeye yenilmiş.

Bunlar niye içiyor:Ya derdi deşilmiş ya kadehe sinmiş.

Bu niye kaçıyor:Ya zılgıdı yemiş ya suçunu bilmiş.

Mustafa ne gülüyor:Ya kök sükmüş ya içini dökmüş.', 'Bu gök neden gürlüyor:Ya aç kalmış ya gaz yapmış. Peki bu niye hırlıyor:Ya kudurmuş ya uykuya dalmış. Güneş neden kızarıyor:Ya utanmış ya if...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yazka']::text[], 8.5, '{"poet":"Mustafa Yazka","poet_slug":"mustafa-yazka","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/mis-mis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Azından', 'en-azindan-selma-erdeviren-miog4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaslı bir kuş gibi

Bu susuşun niye? 

Konuş, bir şeyler söyle; 

İster dereden tepeden

İster havadan sudan olsun.

Kenetleme dudaklarını öyle

Bir iki kelime dökülsün ağzından,

Mutluyum demelisin en azından.', 'Yaslı bir kuş gibi Bu susuşun niye?  Konuş, bir şeyler söyle;  İster dereden tepeden İster havadan sudan olsun. Kenetleme dudaklarını öyle B...', ARRAY['Türk Edebiyatı','Şiir','Selma Erdeviren']::text[], 8.5, '{"poet":"Selma Erdeviren","poet_slug":"selma-erdeviren","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/en-azindan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla İşte!', 'anla-i-ste-mehmet-bicik-bdspy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözüm gözünün içine bakıyorsa,

Kulaklarımdan sesin gitmiyorsa,

Canım hep senle olmak istiyorsa,

Anla işte! Seni seviyorum…

Seni yabancı gözlerden kıskanıyorsam,

Başkalarıyla konuşmanı çekemiyorsam,

Her zaman sana karşı gülümsüyorsam,

Anla işte! Seni seviyorum…

Seni başkasıyla görünce kahroluyorsam,

Başkasının ismini andığında hasta oluyorsam,

Ben hep senin iyi biri olmanı istiyorsam,

Anla işte! Seni seviyorum…

Senin mutlu olman, beni mutlu ediyorsa,

Senin dertlerin beni de üzüyorsa,

Senin yanında güllerim açıyorsa,

Anla işte birtanem! Seni seviyorum…

23 Nisan 1993, Gaziantep', 'Gözüm gözünün içine bakıyorsa, Kulaklarımdan sesin gitmiyorsa, Canım hep senle olmak istiyorsa, Anla işte! Seni seviyorum… Seni yabancı gözl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/anla-iste-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul musun Sevgili?', 'i-stanbul-musun-sevgili-gokhan-seyyit-328gw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ah! istanbul mudur 

bu yar gibi diyar? 

her tarafta senden emareler var.

gün seninle doğar,seninle dolar

ah! istanbul mudur

bu yar gibi diyar? 

Üsküdar''a güneşin doğuşunda gülüşün,

temmuz sıcağının Şile''yi kavuruşu öpüşün,

duruşun; Fatih dilencisine has masum duruşun.

gülüşün,

öpüşün

ve duruşun

her yerde bir parça sen varsın

istanbul yaşadıkça var olacaksın

Eyüp Sultan maneviyatı gibi mahremiyetin,

Beyoğlu geceleri kadar ışıl ışıl gözlerin.

mahremiyetin...

ve kalbinin güzelliğini mahrem tutamayan gözlerin.

her yerde bir parça sen varsın, 

İstanbul yaşadıkça var olacaksın.

Beyazıt mitinglerinde ateşli gençlik sloganları,

Eminönü''nde balıkçı nidaları,

Kadıköyde aşkını haykıran fener taraftarları,

tüm yüksek seslerde gizli heybetli konuşmaların,

İstanbul kadar heybetli,

İstanbul kadar karmaşıksın,

ve İstanbullu kadar ona aşıksın.

her yerde bir parça sen varsın,

İstanbul yaşadıkça var olacaksın.', 'ah! istanbul mudur  bu yar gibi diyar?  her tarafta senden emareler var. gün seninle doğar,seninle dolar ah! istanbul mudur bu yar gibi diya...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Seyyit']::text[], 8.5, '{"poet":"Gökhan Seyyit","poet_slug":"gokhan-seyyit","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/istanbul-musun-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-adnan-durmaz-8oy0x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özlem 

  



gül üşür 

ben yanarım 

tül bulut 

silemez yüzümden kederi 

umut acır- umut kanarım 

ısıtamaz içimi ufktumda solgun güneş 

düşlerim diken üstünde 

bir gülüşün kaldı 

gülüşün 

dağ dağ dağlayan ateş 

kördür gece 

ellerim kollarım kırık 

özlemin çıban kesmiş bağrımda 

acı bu 

yürek kavlarım 

uçamam 

kanadım yanmış gamla 

kan sızar 

umut sızlar 

gözlerim alışamaz karanlığına 

gül açar 

ağlarım yokluğuna 

gecenin yanaklarında yıldızlar damla damla 

ve gün solar uzaklarda 

bekleyişin deli suyu sürükler yüreğini 

için için yanarsın 

şimdi gövdesini 

taştan taşa hışımla çarpan 

bu deli yağmurum ben 

bu ne demek 

sen anlarsın... 

94 

adnan durmaz,yarın yeniden,gerçek sanat yay,ist', 'Özlem     gül üşür  ben yanarım  tül bulut  silemez yüzümden kederi  umut acır- umut kanarım  ısıtamaz içimi ufktumda solgun güneş  düşlerim...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ozlem-275-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk Sonatı', 'mutluluk-sonati-adnan-durmaz-a1rzp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mutluluk Sonatı 

onun beğenisiyle seçmek kendi beğenisinin giysilerini 

onun yalnızca kendisinin bildiği gülümseyişini düşünerek 

ama hiç farkında olmadan 

tıpkı yatağını okşayarak akan bir ırmak gibi 

kanında aktığını bilerek onun gün boyu 

ama farkında olmadan 

ve kendisi olarak konuşmak hayata dair 

kendisi olarak karşı çıkmak zulme 

kendisi olarak bakmak yıldızlara 

ve onu bulmak bir büyük bahçede dolaşırken 

her adımda duyulan çiçek kokuları gibi 

bir bakışla söylemek sevdiğini 

sitemini bir gülüşte saklamak 

ama anlaşılmak 

sevdada yaşamak bu değil mi 

her kadının... 

yemek masasında gülen insanlara dair düşleri karışır 

yaptığı yemeklere 

ev... 

ve onun güzelliklerinin tanrıçası olmak 

ve mimarı olmak oradaki gülümseyişlerin 

yaramaz bir çocuğa bağırılan öfkenin dalındaki gül 

ocaktaki yemeğin müziği-komşu kadınlarla kahve falı 

ve geçerken yan gözle bakılan ayna 

mutluluk bu değil mi 

her kadının güzel perdeleri vardır 

sabahları okşayarak açar onları... 

o tüllerin başka ve anlatılmaz kokusu... 

sabahın ışıkları usulca değdiğinde 

tülü aşıp kendiliğinden dağılıverir 

ve o tülleri okşayan ışıkla yeniden doğar kadın 

mütevazı hayatında... 

yeniden doğurur sevgiyi 

tül yumuşaklığını da ekleyip gün ışığına 

kocaman bir gülümseyişe dönüştürerek 

evdekilerin yüzünü aydınlatır... ki aşk bu olmalı 

ya da aşkın bir anı: 

“her şey anlarda gizli değil mi 

varsın aşkın bir anı olsun 

sessizce bir dünyaya yayılsın 

rutubet kokulu bir ev gül kokar olsun” 

çünki o günü sevgiyle örer 

çocuğuna ördüğü bir kazak gibi baştan sona 

ve her ilmiği ayrı bir an''ı dır aşkın... 

adnan durmaz,bilirsin aşk da serseri,art yay,ank', 'Mutluluk Sonatı  onun beğenisiyle seçmek kendi beğenisinin giysilerini  onun yalnızca kendisinin bildiği gülümseyişini düşünerek  ama hiç fa...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/mutluluk-sonati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-adnan-durmaz-tchn8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sitem 

  



namuslu yosmam benim-asaletli çingenem 

ömrüne bahis tutmuş kumarbaz meryem 

boş yataklar-loş bakışlar-fuhuş-ikiyüzlülük 

kahvaltı-bulaşık-çamaşır-dedikodu 

seçilmemiş zamanlarca nefret içinde 

gizemli bir lir 

sevişmek yılda bir 

ve kırk kilit altında gizlenen şiir... 

namuslu yosmam benim-asaletli çingenem 

niye bıraktın beni yırtılmış bir yürekle 

sonu gelmez bozkırlarda yitmiş bir çocuk gibi 

niye sustun-açlığıma-kıtlığıma-yetimliğime 

bak işte imgelerim çiğnenir-düşlerim yağmalanır 

sazım taşlara çalınır-sözüm yellerde savrulur 

niye bıraktın beni yırtılmış bir yürekle 

güneş iner kan kırmızı sulara 

deniz şehvetle titrer 

sen sonsuza dalarım gözlerinde gemiler 

bilinmez yerlere giden gemiler 

yürekleri zoka yemiş 

yüzleri bakırdan denizciler 

sokaklara bakarsın 

kıvıl kıvıl insanlar 

sovandan suratları 

kabuk üstüne kabuk 

maske üstüne maske 

koşarlar gözü doymaz hırslarının peşinde 

yaşarlar bir şeylerden kaçarak 

ve son derece masum 

özveri tellalı-namus simsarı 

yaşarlar irin saçarak... 

namuslu yosmam benim-asaletli çingenem 

eşkin indi akşam deli bozkıra 

indi gözlerime çoban yıldızı 

ayrılıklar kanadı 

ve boşuna yaşamlar 

çıban dağlar zonkladı ıssızlığın bağrında 

beni niye bıraktın yırtılmış bir yürekle 

sürüden ayrı düşmüş bir emlik kuzuyum ben 

sınırsız ıssızlarda kurt sağnağı gecede 

niye bıraktın beni yağma sofralarında 

namuslu yosmam benim-asaletli çingenem 

sanadır şimdi dargın gözlerimde kırık düş 

yüreğimde sanadır birikip sızlayan nem 

küskünlüğüm bir sana 

sanadır bunca sitem... 

2.7.l995 

adnan durmaz,ben gidersem ay sen-deler,art yay,ank', 'Sitem     namuslu yosmam benim-asaletli çingenem  ömrüne bahis tutmuş kumarbaz meryem  boş yataklar-loş bakışlar-fuhuş-ikiyüzlülük  kahvaltı...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/sitem-203-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-celal-topo-8pyug', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne olur bu gece göz kırp yıldızlara

Kırp ki uzaklardan selamını duyayım

Unutarak şu yalnızlığımı

Seninle hayallere dalayım......

Ne olur bu gece göz kırp yıldızlara

Kırp ki gözyaşlarımı sileyim ellerinle

Ilık bir melteme sarılıp

Mutluluktan uçayım gözlerinde....

Ne olur bu gece göz kırp yıldızlara

Kırp ki saçlarına dokunayım bulutlarda

Yağan yağmurlara karışıp

Damla damla düşeyim avuçlarına.....

Ne olur bu gece göz kırp yıldızlara

Kırp ki seni almaya geleyim yanına

Ellerinden sıkıca tutup

Gidelim çok ama çok uzaklara......



Antalya  /    2005', 'Ne olur bu gece göz kırp yıldızlara Kırp ki uzaklardan selamını duyayım Unutarak şu yalnızlığımı Seninle hayallere dalayım...... Ne olur bu ...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-gece-166-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılıklar Adresin', 'ayriliklar-adresin-adnan-durmaz-nm329', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Müstezat 

  



bir yangın soluğu uykusuzluklarda nefesin 

gecenin neresindesin 

bir ayrılık mevsiminde durmadan gazel dökersin 

ağlarsın duyulmaz sesin 

kaç insan geldi geçti- kaç ayrılık- kaç hasret 

sevginin arkası nefret 

şimdi yaşanmadan yakılmış şiirler ertesindesin 

kederlerdesin 

terkedilmek durmaksızın- çarpılmak duvarlara 

bir yürek dolusu yara 

yağmalanmış bir yaşamın biıinmezliklerindesin 

ayrılıklar adresin 

93 

adnan durmaz,yarın yeniden,gerçek sanat yay,ist', 'Müstezat     bir yangın soluğu uykusuzluklarda nefesin  gecenin neresindesin  bir ayrılık mevsiminde durmadan gazel dökersin  ağlarsın duyul...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ayriliklar-adresin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seçim', 'secim-adnan-durmaz-vgk5y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seçim 

kar yağdı 

trenler rötar yaptı 

ıslak sokaklarda yürüdüm bilmediğim kasaba gecelerinde 

gidecek yersiz ve telaşsız... ayaklarım üşümüş 

ve hayatta daha kötü şeyler var diye düşünerek 

sabahçı kahvelerine sığındım-sigara ve yurtsuzluk kokan 

salaş masalarda akşamdan kalma çaylar 

sakalı uzamış karanlık adamlar vardı 

kar yağdı rötar yaptı tren 

yurtsuzluğun rezil uykularını istemem ak çarşaflı yataklarda 

uyumak istemem bilmediğim soğuk otellerde 

bu gece gideyim-bir şeyler olsun 

istemediği yaşamlarda kaç insan var-istemediği evlerde 

istemediği sokakların gülüşüne alışmış 

ömrünün yamaçlarından aşksızlık yürür 

telaşına alışmış seçmediği akşamların 

bir taşın bağrında koyu yeşil bir yosun 

bir milim ne büyür ne küçülür 

ve alır gider istemediğin hayatlar senden 

alır gider sana ait ne varsa 

geriye bir başkası kalır 

alışkanlıklarıyla yaşayan bir hiç 

ezber bir hayatın fotokopi günlerinde 

bir kez bile kendisi olmayı beceremeden 

sümsük-yalak-kişiliksiz-onursuz-ilkesiz 

kendisi çoktan ölmüş yaşayan sureti bile değil 

aynalarda başka yüz 

başka söz... yaşadığı kurallara uygun 

olmak istediği insana çocuklarını benzetme sevdasında 

yıldızları unutmuş 

belki de hiç duymamış kuş seslerini 

öyle bir dünyanın ortasındayım şimdi 

bütün azapları seçtim-taşlanmaları yuhalanmaları seçtim 

kimse demesin bana 

sen sevecek adam mısın demesin 

ben aşkı seçtim 

filmlerden kitaplardan araklanmış sözlerle falan değil 

bir rezillik olarak bir hastalık olarak delilik falan olarak 

böyle bir dünyanın tersini seçtim 

işte sürgünlük dedikleri bu 

bunca iğrenç ve kendisi çoktan ölmüş 

suretlerin arasında yaşamak 

ben kendimi seçtim ve aşkı seçtim kendime vatan olarak 

varın kalem kırın gayrı umrumda değil 

ben beni seçtim 

ADNAN DURMAZ,bilirsin aşk da serseri,art yay,ank', 'Seçim  kar yağdı  trenler rötar yaptı  ıslak sokaklarda yürüdüm bilmediğim kasaba gecelerinde  gidecek yersiz ve telaşsız... ayaklarım üşümü...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/secim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tomurcuk', 'tomurcuk-adnan-durmaz-nd2ue', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tomurcuk... 

  



gülüşü küküm 

yüreği kör 

elleri gözleri şaki 

tekinsiz devranlardır 

nice gül bahçesi tarumar olmuş 

herkesin yüzüne böyle yürekten 

böyle sarsa sarsa yıldızlı maviliği 

gülme tomurcuk 

şimdi gam vaktidir 

hüzün pusu düşer bakışlarına 

yitik sevdalar yorgunu 

fukara bir çingeneyim 

bir karışlık yaşamda 

yaşlıyım 

ferhad bile benden toy düşer 

yorgunum yitirmelerden 

yüreğimin yükü ağır 

- bunu nasıl anlatsam - 

kambur gibi taşırım yenilgilerimi 

var açıl 

has bahçede 

bülbüller sarhoş olsun alımına edana 

şu benim gönlümü 

çelme tomurcuk 

çok şarkılar dinledim 

uzak sevgililere 

çok kanadım 

kaç umudum talan oldu 

kaç sevgili kaldı ardımda ağlayarak 

koştum da varamadım 

vardım da bulamadım 

bozkırlar ortasında bir taş gibi 

bekledim bin yıllarca 

artık kabullendim 

sevdalar olmayacak hayatımda 

ardımsıra sakın gelme tomurcuk 

bulanık kurt havası iklimindesin 

ayaz çalar 

yel vurur 

deli olma tomurcuk... 

adnan durmaz,ben gidersem ay sen-deler,art yay,ank', 'Tomurcuk...     gülüşü küküm  yüreği kör  elleri gözleri şaki  tekinsiz devranlardır  nice gül bahçesi tarumar olmuş  herkesin yüzüne böyle ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/tomurcuk-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluk Dediğimiz Nedir Ki', 'dostluk-dedigimiz-nedir-ki-celal-topo-fi59h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ömür dediğimiz nedir ki

Bir an kadar kısa

Dostluk dediğimiz nedir ki

Cebimizde para yoksa....



1978 / Elazığ', 'Ömür dediğimiz nedir ki Bir an kadar kısa Dostluk dediğimiz nedir ki Cebimizde para yoksa.... 1978 / Elazığ...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dostluk-dedigimiz-nedir-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşin Kökleri  Işığın Tohumları', 'atesin-kokleri-isigin-tohumlari-adnan-durmaz-l3fwd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece-Deniz–Hüzün... 

  



gece 

deniz 

bir de hüzün 

kuytu dalgınlığında 

bir çift gözün 

ekim dağlarında ateşler bir başka yanar 

yorgun yılkılar konuğu ömrümüzün 

dalında sararan yapraklar 

belki bekleyişlerdir yaşamak 

bekleyiş 

her şeyi sarar... 

her şey kabullenilmiştir 

ölüm kadar olağan 

önceden bilinircesine 

su-ateş-kül ve rüzgâr 

fırtınalar bile durağan 

o türküler ki 

bir başka söylenir dağ başlarında 

büyük yolculuklar arifesinde 

yarım bir şeyler kanar boşuna 

gidecektim 

biliyordun 

bir şeyler söyleseydin 

çiseleyen yağmurla 

bağlar kursaydın yüreğimize 

gitme kal deseydin bilmediğim yanlarınla 

gizemin aşikar olsaydı 

gece 

deniz 

bir de hüzün 

kanamasaydı kirpiklerinde 

suskunluğun olgunlaşan bir ağrı 

çatlattı kozasını en kör zamanda 

en azından düşlerini saplasaydın yüreğine 

belki yollar kavuşurdu bir zaman 

aramızda uçurum imkansızlıklar 

hicran noktasında ölmeseydik 

o anlar 

ki 

yeniden doğduğumuzda 

acı dölütünün ıslaklığı kaldı geriye 

şimdi ekim geldi 

ateşin kökleri var 

aşkın ve ışığın tohumları 

kurumuş yürek vadilerinden 

yorgun atlılar geçmekte 

gidişim sonradan infilak edecek 

biliyorum 

ağlayacaksın 

gecene dikenler batar bir zaman 

hüznünü bir yara gibi 

dağlayacaksın 

uykuya varır gibi sev bundan böyle 

belki mevsimler geçer de üstünden 

uyanamazsın... 

ekim. 97- Güzelyalı 

adnan durmaz,ben gidersem ay sen-deler,art yay,ank', 'Gece-Deniz–Hüzün...     gece  deniz  bir de hüzün  kuytu dalgınlığında  bir çift gözün  ekim dağlarında ateşler bir başka yanar  yorgun yılk...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/atesin-kokleri-isigin-tohumlari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dur Palikarya!', 'dur-palikarya-hidir-altas-t5wtb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karşında çaresiz insan var diye

Ürme fani köpekleri gibi

Eli silahsız zavallı insan var ise

Arkada ellibeşmilyon var Palikarya

Sessiz sanma bizleri sen

İzmir''i Kıbrıs''ı unutma

Kükrersek aslan gibi aniden

Kaçacak delik ararsın Palikarya

Kedinin yarında fare gibiyizdir

Masum dururuz bir kenarda

Koca düvel çıktıda karşımıza

Onlara sor bizi sen Palikarya

Turhani der; Atayı öldü sanma

Onun gençliği var şimdi heyyyy

Bizi küçük görme büyürüz

Dağ olurda çıkarız karşına Palikarya', 'Karşında çaresiz insan var diye Ürme fani köpekleri gibi Eli silahsız zavallı insan var ise Arkada ellibeşmilyon var Palikarya Sessiz sanma ...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Altaş']::text[], 8.5, '{"poet":"Hıdır Altaş","poet_slug":"hidir-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dur-palikarya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözüm Gül Olsun Saçlarında', 'sozum-gul-olsun-saclarinda-adnan-durmaz-j6pa6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gül Söze Gazel 

  



şimdi bütün dillerim l’ âl 

bir yanık gönül söylerim 

cümle mizanları yıktım 

bir başka şakul söylerim 

haksızlığa isyan yasak 

isyansız gönüller sarsak 

dil kesti gözlerim bile 

ayrı bir usül söylerim 

ulur kuduz bir karanlık 

can koparır-kan sarhoşu 

onlara tüm dillerimle 

alazlanan kül söylerim 

zındanları zingirdeten dirençlerde 

tek yumruktuk 

gökyüzünde yersiz kalan 

bir yanık bülbül söylerim 

duvar yıkan isyan benim 

dağyaran derler namıma 

kaya deler çıkarım da 

sözlerimi gül söylerim... 

7.6.96 İzmir', 'Gül Söze Gazel     şimdi bütün dillerim l’ âl  bir yanık gönül söylerim  cümle mizanları yıktım  bir başka şakul söylerim  haksızlığa isyan ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sozum-gul-olsun-saclarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bencillik Aynaları', 'bencillik-aynalari-adnan-durmaz-6iduo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bencillik Aynaları... 

  



sevinç bir kelebekti 

yüreklerde dolaşan 

gözbebeklerine konan 

onu da öldürdünüz 

tozu bile kalmadı parmak uçlarınızda 

artık bütün aşklar güz 

coşkular topal mavi 

duygular yalnızlık sarı 

çıldırın ıssızlıktan 

bakarak görmeden birbirinizi 

sokaklar dolusu yüz 

bencillik aynaları... 

26.7.97. 

adnan durmaz 

ben gidersem ay sendeler,art yay,ank', 'Bencillik Aynaları...     sevinç bir kelebekti  yüreklerde dolaşan  gözbebeklerine konan  onu da öldürdünüz  tozu bile kalmadı parmak uçları...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bencillik-aynalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllardır Ağlarım', 'yillardir-aglarim-celal-topo-xipkj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllar var ki ağlarım

Bir kenar mahallenin ahşap evinde

Kapımı açıp ta gözyaşımı silen olmadı

Ben sevgimi anlatamadım

O da bakışlarımı anlayamadı......

1975 / Elazığ', 'Yıllar var ki ağlarım Bir kenar mahallenin ahşap evinde Kapımı açıp ta gözyaşımı silen olmadı Ben sevgimi anlatamadım O da bakışlarımı anlay...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yillardir-aglarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 20', 'guncel-beyitler-20-huseyin-avdic-0jt8w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tesadüf Ve Ihtimallerle Evren Kurulmaz

Ihtimallerle degil, cok ince hesaplarla kurulur bu evren.

Tesadüfe birakilan bir i$de, ne denge olur, ne de düzen.

Berlin, Kasim 2005.', 'Tesadüf Ve Ihtimallerle Evren Kurulmaz Ihtimallerle degil, cok ince hesaplarla kurulur bu evren. Tesadüfe birakilan bir i$de, ne denge olur,...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guncel-beyitler-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlar Sandığında Saklar', 'kadinlar-sandiginda-saklar-kamil-aydemir-v7ga0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yaşamın varoşlarından eksilmez yarın korkusu

annemin sandığında çiçek kokusu

gamzelerinde yazılmamış imgeler

yüzünde yalnızlığına akan ırmaklar vardı

karanlıklarımıza güneşi sağardı

annem sevgi pınarı

                               güzelliklerin ambarıydı

bastığı toprağa yük olmayan dağlardı

yalnızlığı devleştirir geceler

annem gecelerin koynunda ağlardı

yoksulluğun önüne kendisini atan

yabanelde emeğini satan

babamın mektuplarıydı annemin baharı

dallarda cilveleşen kuşlar gibi

       mutluluk motifleri çizerdi

sözcükleri sanki yüreğine dizerdi

dudaklarından düşürmezdi gurbet türkülerini

annemden öğrendim

türkülerin insana arkadaş olduğunu

türkülere yasladım omuzumu

hayat ünversitesinde öğretmendi annem

çiçekçe

             kuşça

                       yıldızca

                                     otça konuşuyordu

dikenler batmıyordu

annem ısırgan otunu da okşuyordu

ısırgan otu bile annemin ellerini ısırmıyordu

bence sevgi buydu

yarım olur sevdiği gurbette olanın gülüşleri

kadınların sandığında saklıdır nice düşleri

sırdaşı işlemeli sandığını 

arasıra açardı annem

anı defterine

ya da bir resim albümüne bakar gibi

bakardı sandğındaki  gizlerine

dalar giderdi bazılarının izlerine

bazılarında da sis çökerdi bahar gözlerine

çaresizlik kurşun gibi saplanırdı yüreğine

uzanır ama tutunamazdı babamın sevgisine

yenilirdim annemin çaresizliğine

ben utanırdım ayrılığın yerine

purtlanmış*  iplik yumağı gibi hayatı

kadınlık sabriyle çözerdi annem

annem de sandığında saklardı

                  nice hüzünleri

                                          sırları

yoksulluk ve gurbet girince araya

mutluluğa uzak geçti annemin gençlik yılları

işlemeli sandığı da sarardı 

                                       kendisi gibi

sofrasına emeğini koyanlara acımasızdı hayat

beni erken terketti çocukluğum

çocukluğuma uzanır gurbete soğukluğum

ayrılık çıkmaz sokağıdır mutsuzluğun

hayatın çoraklığında bile  sararmadı anne

senin sevgindir yüreğimde büyüttüğüm

babam da yanıbaşında

gurbeti yüreğime sokmadım

anne sayende anladım 

tanımak için bir kadını

konuşturmak gerek sandığını

kadınlar sandığında saklar kendini

*: Ayırtlanması oldukça zor olan, karışmış iplik yumağı.

 Yöresel bir sözcüktür.', 'yaşamın varoşlarından eksilmez yarın korkusu annemin sandığında çiçek kokusu gamzelerinde yazılmamış imgeler yüzünde yalnızlığına akan ırmak...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/kadinlar-sandiginda-saklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilenci', 'dilenci-celal-topo-aa1xu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ömür boynum bükük

Ellerimi uzatarak bir dilenci gibi

Gözlerimdeki yalvarışlı bakışla

Bir sevgi dilendim durdum....

1976 / Elazığ', 'Bir ömür boynum bükük Ellerimi uzatarak bir dilenci gibi Gözlerimdeki yalvarışlı bakışla Bir sevgi dilendim durdum.... 1976 / Elazığ...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dilenci-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Şehir', 'ey-sehir-adnan-durmaz-0og5g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey Şehir 

 	 

ey şehir unutma beni 

yalnızlığını giderdim senin 

acılarını omuzladım-boğuldum kederlerinde 

bütün sokakların uyudu 

bütün ışıkların söndü 

imbatın bile kesildi 

bir ben kaldım paramparça bir yürekle 

nice tekinsiz gecende 

hep koştum 

ter içinde 

düşe kalka 

bıkmadan 

bütün kapılarını çaldım şu insan yüzlerinin 

bakışların ötesinde duvarlar zorladım 

kapaklandım gülüşlerin sınır çizgilerinde 

bütün uçurumlarından düştüm ey şehir 

denizlerini sevdim 

gözyaşlarım aktı dalgalarına 

aşklarım çiğnendi 

fesleğen kokulu kaldırımlarda 

yüreğimi kemirerek çektim kahrını 

ve tüm sevgilerim 

yağmalandı ortalık yerde 

katlandım 

yine de küsmedim yaşamadığım güzelliklere 

neyleyim bilinmedi kıymetim 

buralardan gidiyorum 

ey şehir unutma beni 

kimsenin sevmediği yanlarını da sevdim... 

2.7.97 

adnan durmaz,ben gidersem ay sen-deler,art yay,ank', 'Ey Şehir   	  ey şehir unutma beni  yalnızlığını giderdim senin  acılarını omuzladım-boğuldum kederlerinde  bütün sokakların uyudu  bütün ış...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ey-sehir-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Şair', 'o-sair-adnan-durmaz-yig3v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O Şair... 

 	 

ne bir yüzü vardı 

ne elleri 

ne adı 

bir şair şiir dokudu akşamları 

hiç kimse anlamadı 

ağaçlar çiçek açtı ha bire 

rüzgârda kız kokusu 

bir ışık ormanıydı 

denizde gümüş selviler 

gökte salkım salkım yıldız 

o bir yeraltı ırmağıydı 

için için kanadı 

şimdi varıp sorsan 

kimse tanımaz 

yaşam bağışlamaz 

aşk bağışlamaz 

o şair 

buralarda 

hiç yaşamadı... 

8.6.97.. Güzelyalı/İZMİR 

adnan durmaz 

ben gidersem ay sendeler,art yay,ank', 'O Şair...   	  ne bir yüzü vardı  ne elleri  ne adı  bir şair şiir dokudu akşamları  hiç kimse anlamadı  ağaçlar çiçek açtı ha bire  rüzgârd...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/o-sair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar Sonra Kente Döndüğün Zaman', 'yillar-sonra-kente-dondugun-zaman-adnan-durmaz-a0yey', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıllar Sonra Kente Döndüğün Zaman 

 	 

Kar üstüne düşen kınalı keklik 

Kardelen dedikleri kanındır belki 

Kursağında kalmış bahara sevdan 

Çevrilmiş yıldızlara boncuk gözlerin 

Sonsuzlardan hesap sormakta sanki.. 

Yedi dağ üstüne damlar kurdular 

Talan oldu kuş yuvası-gül dalı 

Sevda pavyonlara barlara düştü 

Dilim eğri hançer oldu ağzımda 

Konuşmam suç sayıldı. 

İçki bardaklarının kulpuna dikildi kurtuluş bayrakları 

Sarhoşlara meze oldu devrimci marşlar 

Dürüstlük; 

“Seksen öncesine dönmek'' sayıldı 

İşkenceden yeni çıkmış kızlara 

Barlarda bardak bardak epiktir 

Ve kirli yataklarda meme bacak freut 

terapiler çekildi 

Kucak kucak dolaştı sığınaksız kalanlar... 

Ey kocakent 

Su berrağı gün aydını coşkular büyüttüm 

puşt acılı karanlıklarda sana 

Pusulu- pusatlı- puslu 

Nice dağ başında düşüp düş oldum 

Gökkuşağı türküler çağladı cehennem yüreğimden 

Ölümü parka yaptım kocakent. 

Ve türküm 

Tükenmiş yüreklerde alkolle karılıp 

Kız tavlama malzemesi yapıldı. 

Vakitsiz biten aşklar bilirim 

Tomurcukta kopan güller gibidir 

Kuş kanadı kalem olsa 

Denizler mürekkep 

Gökyüzü kağıt 

Ayrılığın acısını yazamaz... 

Yaşlı dalları kesilmiş gün 

Kanlı yapraklar dökerken 

Bir başka ayrılıktır akşam 

Bir başka kavuşmadır 

Yıllar sonra kente döndüğüm zaman... 

''Bu kentte en güzel anılar 

Bir anı oldukça öldürür beni...”* 

Diyen bir arkadaş vardı 

Vuruldu okul yolunda 

Son bakışı bende kaldı 

Bende kaldı inci mercan gözyaşı 

Her yağmurda ağlayan o hüzün gözlü kızın 

Şimdi her adımda cana gelir anılar 

Yaşanır yeni baştan tüm ayrılıklar 

O anılar ki nerede olursan ol 

Kapaklanan deli taylar 

Damarları kesilmiş ırmaklar gibi kanar... 

Yeşil parkalı gülüşlerle aydınlanan 

Alanlar-bulvarlar-varoşlar cana gelir 

En güneşli gülüşlerin kurşunlandığı yerde 

Onurların satıldığı mezatlar 

Entel barlar 

Ve gettolar yükselir... 

Ey sevdayı pavyonlara düşüren 

Ölümü parka yaptığım kent 

Ayrılık dedikleri sana dönmekmiş meğer 

Ve titreyen ellerinin 

''Güneşin battığı yere 

Dört nal giden atların...'' 

Bayrak gibi dalgalanan yelelerine 

Sımsıkı yapışacak dermanı kalmamış gayri 

Dilerim utancın yeşertsin seni 

Çiçekler patlasın yaralarından 

Hasretimin yetim kalmış çocuğu 

Kuru memelerinde yeniden dirim bulsun 

Çözülsün onurunun boynundaki kördüğüm 

Beni sevdalara çağır kocakent 

Gayri bitsin hasretlik 

Bitsin şu sürgünlüğüm... 

9.7.1992 

* Mehmet Gemici (1955-1983... 

(şiirde geçen iki dizenin ozanı)

adnan durmaz,fısıltılarla da olsa söyle,saypa yay,ank', 'Yıllar Sonra Kente Döndüğün Zaman   	  Kar üstüne düşen kınalı keklik  Kardelen dedikleri kanındır belki  Kursağında kalmış bahara sevdan  Ç...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/yillar-sonra-kente-dondugun-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek Sözleşmesi', 'yurek-sozlesmesi-adnan-durmaz-bhqtc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yürek Sözleşmesi 

 	 

“gel seninle aht-ı peyman edelim” 

sal olsun kavlimiz zaman denizlerinde 

yalnızlığın kalesini viran edelim 

bir pencere açalım uzağın ötesine 

beni gör baktığın yerde 

tutuşsun gülüşün elleri 

yalnızlıkta yanarken gecenin teni 

kasvet bulutlarına rüzgar kıl düşlerimi 

yavuklu yadigarı oyalı mendil gibi 

bakışın gözlerimde kalsın 

“ikimiz de bir ikrarı güdelim” 

dağ dağ dağlanırken acı 

“ne sen beni unut-ne de ben seni... ” 

tarih gördü 

kudurmuş karanlığın alanlarında 

onurun bayrağını bırakarak kaçmadık 

entel mezatlarında 

içki bardaklarının kulpuna dikmedik kurtuluş bayraklarını 

devrimci söylemlerle ahkam kesip 

cilalanmış sözlerle militan görüntüler çizerek 

yeniyetme kızlara 

ruhsuz sevişmeler yaşamadık utanç yataklarında 

alnımızda ışıyan lekesiz umut 

yürekte masumiyet... 

varsın dedik 

yarsiz kalsın yürek... 

suskumun külleri altında 

sönmeyen hüzün 

bir yangın yeri kadar kırgın ve yaralıyım 

bakışımdan yüreğime kurulan isyan köprüsü 

son kez bakarken yaşama 

denizin gözlerinden kalan 

zamanı yakan anlam... 

kovulduk tüm kapılardan doğrudur 

kör yüreklerde kanadı ışığımız 

sevdaya dair yazdığımız dizeler 

atıldı sokaklara 

saçıldı sözcükler 

ölü karıncalar gibi yerlere 

şimdi ferhadın külüngü 

yürekler kanırtır olmuş dağ diye 

çöplüklerde dolaşır sevgililer 

kanı sömrülürken iliklerine kadar 

kör-sağır-dilsiz sürü 

birbirini boğazlar her biri can havliyle 

şimdi aşk 

hoyrat bir şaki dağlarda 

şimdi aşk 

yeni yetme oğlanın 

kırmızı tokalı kıza 

bakıp ağlamasıdır 

uçurtmanın tellere takılmasıdır 

sürüye katılmamaktır şimdi aşk 

demir parmaklıkların ardında 

göçmen kuşlar havalanan 

bir yüreğin yakılmasıdır 

bu yangın yerinde 

susarak konuşmaktır 

bakmadan görmektir 

elleri bağlıların 

kolları kopukların 

sarılmasıdır 

şimdi aşk 

bir isyan bombasıdır 

bütün kapılardan kovulmaktır 

yalnız 

ve dimdik yaşamaktır şimdi aşk... 

“gel seninle ahd-ı peyman edelim 

ne sen beni unut-ne de ben seni... ” 

Ekim 2001 

adnan durmaz,bilirsin aşk da serseri,art yay,ank,2003', 'Yürek Sözleşmesi   	  “gel seninle aht-ı peyman edelim”  sal olsun kavlimiz zaman denizlerinde  yalnızlığın kalesini viran edelim  bir pence...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/yurek-sozlesmesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Borç', 'borc-i-smail-hakki-kavurmaci-klwjd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sabah uyansam ki

Gün odamın ortasında.

Masamda kahvaltım,

Tepside iki dilim kızarmış ekmek,

Zeytin, peynir, reçel.

İnce belli bardakta

Tavşankanı çay…

Ve bir de kıpkırmızı bir gül..

Can yoldaşım tepeden tırnağa

Huzur içinde..

Bahçede çocuklarla serçelerin cıvıltısı; 

Etrafı kır çiçekleriyle süslü

Dupduru dingin akan bir gümüş derenin

Şırıltısı tadında..

Çok şükür Ya Rabbim çok şükür

Dağ olup yolumu kesen

Çığ olup yüreğimi ezen

Sel olup bilinmezlere sürükleyen

Borç belası bir kabusmuş meğer, desem..

          Tarih:14.10.2005

          Saat: Gece 01.15', 'Bir sabah uyansam ki Gün odamın ortasında. Masamda kahvaltım, Tepside iki dilim kızarmış ekmek, Zeytin, peynir, reçel. İnce belli bardakta T...', ARRAY['Türk Edebiyatı','Şiir','İsmail Hakkı Kavurmacı']::text[], 8.5, '{"poet":"İsmail Hakkı Kavurmacı","poet_slug":"i-smail-hakki-kavurmaci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/borc-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Bulursun', 'beni-bulursun-aziz-pinar-4p43z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kapıyı kapatıp gidersin sanma

Çıktığın yollarda beni bulursun

Geçmişi unutup silersin sanma

Kaçtığın yerlerde beni bulursun...

Rüzgara versende kapıp götürmez

Deryaya atsanda alıp eritmez

Sellere katsanda silip süpürmez

İçtiğin sularda beni bulursun...

Ayrılık acısı kalbe vurdukça

Son bakılan ışık gözde kaldıkça

Geçmişe ağlamak günü geldikçe

Döktüğün yaşlarda beni bulursun...

Sevdam bulutlarda yüklü duracak

Karlarla,yağmurlar benle yağacak

Aşkım her baharda çiçek kalacak

Açtığın dallarda beni bulursun...

Çıktığın yollarda beni bulursun...', 'Kapıyı kapatıp gidersin sanma Çıktığın yollarda beni bulursun Geçmişi unutup silersin sanma Kaçtığın yerlerde beni bulursun... Rüzgara verse...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/beni-bulursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küllenmiş Bir Sevda', 'kullenmis-bir-sevda-celal-topo-v0681', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Unuttuğumu sandığım

Küllenmiş bir sevdaydı o

Öyle Bir bakış baktı ki 

Yıllar sonra yeniden

Kalbimde alevlendi

1978 / Elazığ', 'Unuttuğumu sandığım Küllenmiş bir sevdaydı o Öyle Bir bakış baktı ki  Yıllar sonra yeniden Kalbimde alevlendi 1978 / Elazığ...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kullenmis-bir-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamın Yollarında', 'yasamin-yollarinda-necibe-sucuoglu-jkyzr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşamın yollarında,

İki ayak üzerinde yürüdüm,

Ayaklarım yere bastı hep.

Diken doluydu yollarım.

Eğildiysem,dikenleri derledim.

Eğildiysem,mücadelem için eğildim; 

Bel bükmek,aman dilemek için değil.

Kollarıma battı dikenler,bacaklarıma battı da,

Yine de aman dilemedim.

Bilirim,aman dilediklerin yüreğini acıtır.

Ve daha acıdır,

Yürek acısı diken acısından.

Bu nedenlerdir ki,

Acımla,mücadelemle özgür yaşadım hep.

Zaman zaman 

Dikenin ucunda bir çiçek gibi hissettim kendimi.

Zaman zaman

Gökte uçan kuşun serbestliğini duydum içimde.

Zaman zaman ısıttı güneş,

Zaman zaman yaktı kavurdu beni.

Yine de umut bağladım her doğan güne

Umutlarım,düşlerim,

Hayallerim de oldu kısacası

Ama ayaklarım hep yere bastı.', 'Yaşamın yollarında, İki ayak üzerinde yürüdüm, Ayaklarım yere bastı hep. Diken doluydu yollarım. Eğildiysem,dikenleri derledim. Eğildiysem,m...', ARRAY['Türk Edebiyatı','Şiir','Necibe Sucuoğlu']::text[], 8.5, '{"poet":"Necibe Sucuoğlu","poet_slug":"necibe-sucuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yasamin-yollarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluk', 'dostluk-aziz-pinar-0h696', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben bir zamanlar

Yirmi yıl kadar

Paşabahçe''de

Satış memuru,

Satış şefi,

Ve Satış müdürüydüm...

Türkiye''nin dört bir yanından

Edirne''den Kars''a 

Sinop''tan Mersin''e kadar

Tüccar dostlarım vardı...

Şimdi emekliyim

Çok şükür hala dostlarım var

Gördükçe tanıyıp selam veriyorlar

İnsanlıktan başka bir beklentileri yok

Ama iki elin parmakları kadar...', 'Ben bir zamanlar Yirmi yıl kadar Paşabahçe''de Satış memuru, Satış şefi, Ve Satış müdürüydüm... Türkiye''nin dört bir yanından Edirne''den Kars...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dostluk-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perde çekse de güneşe bulutlar', 'perde-cekse-de-gunese-bulutlar-necibe-sucuoglu-akbcv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Perde çekse de güneşe bulutlar,

yağmur döküyorlar toprağa,

Çekinmeden bir damlasını.

İşte böyle hüzünlü bir havada

Gebe kalıyor toprak ana.

Yeşilliklere gebe,rengarenk çiçeklere gebe,

Sebzelere,meyvelere,başaklara,

Berekete gebe kalıyor toprak ana...

Gece karanlık,

karanlık ürkütücü...

Yıldızlar var gücüyle delmeye çalışıyor karanlığı.

İşte böyle bir karanlıkta gebe kalıyor gece.

Yepyeni bir güne,

Pırıl pırıl bir güne; 

Kısaca umutlara gebe kalıyor gece.

Ve bir çocuk doğuyor bir gün; 

Karanlığa inat,bulutlara inat,

Güneşi hissederek.

Bir çocuk doğuyor çığlık çığlığa,

Varlığını kanıtlamak istercesine.

Büyümeye çalışıyor yavaş yavaş

Sevgiyle bir ananın kucağında; 

Sevgiyi,şevkati tadarak.

Sokakta bir arkadaşından dayak yiyor bir gün

Ağlamayı öğreniyor,

Kavgayı öğreniyor.

Büyüdükçe insanları tanıyor,

Dünyayı tanıyor.

Günler, aylar derken

Geçiyor yıllar da.

Ve gebe kalıyor çocuk.

Mutlaka ikiz doğuracak

Biri sevgi olacak,biri nefret...', 'Perde çekse de güneşe bulutlar, yağmur döküyorlar toprağa, Çekinmeden bir damlasını. İşte böyle hüzünlü bir havada Gebe kalıyor toprak ana. ...', ARRAY['Türk Edebiyatı','Şiir','Necibe Sucuoğlu']::text[], 8.5, '{"poet":"Necibe Sucuoğlu","poet_slug":"necibe-sucuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/perde-cekse-de-gunese-bulutlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar Tanıdım', 'i-nsanlar-tanidim-celal-topo-kji84', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsanlar tanıdım 

Sevmekten sevilmekten yorulmuş

İnsanlar tanıdım

Sevmeden sevilemeden ölmüş....

1978 / Elazığ', 'İnsanlar tanıdım  Sevmekten sevilmekten yorulmuş İnsanlar tanıdım Sevmeden sevilemeden ölmüş.... 1978 / Elazığ...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/insanlar-tanidim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinmez Aydınlık', 'dinmez-aydinlik-birkan-demirci-bkft8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gözlerin gördüğünü diller söylemez.

kanadı kırılan serçe ne yapsın uçamazsa.

umudun penceresi olmaz sevgili! 

karanlığın içinde kaybolmuşsan; 

dilsiz kuyulara derdini açma.

13.11.2005/Çorum', 'gözlerin gördüğünü diller söylemez. kanadı kırılan serçe ne yapsın uçamazsa. umudun penceresi olmaz sevgili!  karanlığın içinde kaybolmuşsan...', ARRAY['Türk Edebiyatı','Şiir','Birkan Demirci']::text[], 8.5, '{"poet":"Birkan Demirci","poet_slug":"birkan-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dinmez-aydinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanmaz bir yaşamın ortasında', 'yasanmaz-bir-yasamin-ortasinda-necibe-sucuoglu-jay22', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşanmaz bir yaşamın ortasında,

Kıyısında korkuların,

Acıların sahilinde yaşadım hep.

Mutluluk,arkasından kovaladığım

Bir türlü yakalayamadığım bir olgu

Sevgilerim karşılıksız oldu.

Ya sevdim sevilmedim,

Ya sevildim sevemedim.

Ne meyler oldu avuntum,ne meyhane

Engin denizlerde bir maceraperest gibi

Teselli aramadım değişik kalplerde

Elbette aradım,istedim ben de

Bir teselli, bir avuntu gönlüme

Tesellim kalemim,avuntum sigaram oldu.

Evet...

Yaralı kalbim,kendi kendini teselli etti,

Kendi kendini avuttu.', 'Yaşanmaz bir yaşamın ortasında, Kıyısında korkuların, Acıların sahilinde yaşadım hep. Mutluluk,arkasından kovaladığım Bir türlü yakalayamadı...', ARRAY['Türk Edebiyatı','Şiir','Necibe Sucuoğlu']::text[], 8.5, '{"poet":"Necibe Sucuoğlu","poet_slug":"necibe-sucuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yasanmaz-bir-yasamin-ortasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yaz Daha', 'bir-yaz-daha-aziz-pinar-s2p4s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yaz daha olmadı seninle

Ne terin terime karıştı

Ne rüzgarın yüzümde dolaştı

Bir yaz daha olabilseydi

Mutluluk gelip bizi seçerdi

Tuttuğumuz ateşle

Bir ömrün kışı geçerdi...

Güneşin ısıttığı ümitlerimizi

Bir yaz daha sürdüremedik

Ne ılık deniz esintileri vurdu yüzüme

Ne köpük köpük dalga damlacıkları

Bir yaz daha olabilseydi

Mutluluk gelip bizi seçerdi

Öptüğümüz dudaklarla

Bir ömrün susuzluğu geçerdi...', 'Bir yaz daha olmadı seninle Ne terin terime karıştı Ne rüzgarın yüzümde dolaştı Bir yaz daha olabilseydi Mutluluk gelip bizi seçerdi Tuttuğu...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-yaz-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Kimseler Tutmamıştı', 'hani-kimseler-tutmamisti-birkan-demirci-tqzat', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'daha öpüşmedik 

elin elime değmedi bile.

birde çocuğumuz oldu vakitsiz; 

hani kimseler tutmamıştı elini.

12.11.2005/Çorum', 'daha öpüşmedik  elin elime değmedi bile. birde çocuğumuz oldu vakitsiz;  hani kimseler tutmamıştı elini. 12.11.2005/Çorum...', ARRAY['Türk Edebiyatı','Şiir','Birkan Demirci']::text[], 8.5, '{"poet":"Birkan Demirci","poet_slug":"birkan-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hani-kimseler-tutmamisti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçekler', 'gercekler-necibe-sucuoglu-9f4rs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gerçekler,gerçekler

Yeter,yeter artık dikilmeyin önüme.

Biraz da yol verin hayallerime.

Herkesin başında kavak yelleri esen yaşlarda; 

Güneşli günlerim oldu,

Yağmurlu günlerim oldu,

Fırtanalar koptu,yeller esti hayatımda ama,

Kavak yelleri esmedi hiç başımda.

İşte,ılık bir Nisan gecesi,

Yeni aşkların doğduğu bir ayda,

Gençliğim geldi aklıma.

Hiç İlkbaharda başlayıp,

Sonbaharda biten aşklarım olmadı benim.

Yaşadım elbet her canlı gibi

İlkbaharın neşesini.

Papatya tarlalarında

Tahla atıp yuvarlanırken,

Fallar bakmadım

Seviyor sevmiyor diye.

Çoğu zaman dayak yedim anamdan hatta,

Üstümü kirlettiğimn için.

Bazan bir balarısı yaktı canımı çayırlarda.

Bir eksiklik mi,

Yoksa gerçeklik mi,bilemiyorum? 

Umutla beklediğim bir sevgilim olmadı

O yaşlarda.

Umudum hayat oldu,

Umudum gerçeklik oldu hep.

Gerçekler,gerçekler ne olur,

Ne olur engel olmayın bana.

Biterken hayatımın ilkbaharı; 

Ilık bir Nisan sabahı,

Yaşayamadığım baharı

Hayallerimde yaşayayım.

Takla atıp yıuvarlanayım

Papatya tarlalarında.

Giysilerim kirlendi diye

Kızan kimse olmasın.

Arıların çayır çiçeklerinden

Bal toplayışını seyredeyim.

Gelincikler derleyeyim,

Kır çiçekleri derleyeyim

Ve yanımda olsun sevdiğim de; 

El ele verip koşalım,

Coşalım biraz da.

Unutalım yaşamı,

Yaşamın zorluklarını,mücadelesini.

Sevgisini söylesin bana,

Çiçeklerden taç yapıp taksın başıma...

Gerçekler,

Gerçekler bırakmıyor ki beni asla.

Ilık bir Nisan sabahı; 

Kocam işe gidecek,

Çocuğum ise okula; 

Kahvaltı masası hazır değil hala.', 'Gerçekler,gerçekler Yeter,yeter artık dikilmeyin önüme. Biraz da yol verin hayallerime. Herkesin başında kavak yelleri esen yaşlarda;  Güneş...', ARRAY['Türk Edebiyatı','Şiir','Necibe Sucuoğlu']::text[], 8.5, '{"poet":"Necibe Sucuoğlu","poet_slug":"necibe-sucuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/gercekler-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
