INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi beklenir sevgiden', 'sevgi-beklenir-sevgiden-mustafa-sucu-39y39', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dolunay beklenir duygusallığın dan

Yağmur beklenir ihtiyaç tan

Güneş beklenir sıcaklık tan

Sevgi beklenir sevgiden

Düğün olmuş sevgiler den

Bayram olmuş neşeler den

Özel günler olmuş hasretler den

Sevgi olmuş  sevgi den', 'Dolunay beklenir duygusallığın dan Yağmur beklenir ihtiyaç tan Güneş beklenir sıcaklık tan Sevgi beklenir sevgiden Düğün olmuş sevgiler den ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sucu']::text[], 8.5, '{"poet":"Mustafa Sucu","poet_slug":"mustafa-sucu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgi-beklenir-sevgiden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
