INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece De Ay Yok', 'gece-de-ay-yok-tulay-sustam-fnm2p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir yıldız kaydı

peşinden bütün yıldızlar intihar etti

gece

gözlerini açtığında

karanlığın içinde bir ay''ı gördü

ay 

ne söylediyse ispatlayamadı

ve ışığı 

karanlığı aydınlatmaya yetmedi

bütün suçları üzerine aldı

ışığını söndürdü 

gece hepten karanlıkta kaldı

...artık gece de ay yok...

ey gökyüzü! ...

bundan böyle ihanetinle kal...

hadi şiir tut ellerimi gidiyoruz...', 'bir yıldız kaydı peşinden bütün yıldızlar intihar etti gece gözlerini açtığında karanlığın içinde bir ay''ı gördü ay  ne söylediyse ispatlaya...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gece-de-ay-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adamın Biri! ! !', 'adamin-biri-saim-bastik-hb4tt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çapı yok, çupu yok, bilgisiz ama

Herif başımıza, BAŞBAKAN oldu! 

Büyük ikramiye çıktı adama

Herif başımıza, BAŞBAKAN oldu! 

Muhtarlığa bile, aklı ermezdi

Normal toplum arasına girmezdi

Rüyasında görse, hayra yormazdı

Herif başımıza, BAŞBAKAN  oldu! 

Değişe, değişe, dört köşe oldu

Müslümanı attı, gâvuru buldu

Şu güzel memleket, bak kime kaldı! 

Herif başımıza, BAŞBAKAN oldu! 

Tek başına, dağdan eve gelemez

Dil bilmiyor, sorup yolu bulamaz

Sınava soksalar, çoban olamaz

Herif başımıza, BAŞBAKAN oldu! 

Onu anlatmaya, lügatım yetmez

Danışmanı yoksa, helâya gitmez

HARÎMÎ''yim; satsam, beş para etmez

Herif başımıza, BAŞBAKAN oldu! 

15/11/2005', 'Çapı yok, çupu yok, bilgisiz ama Herif başımıza, BAŞBAKAN oldu!  Büyük ikramiye çıktı adama Herif başımıza, BAŞBAKAN oldu!  Muhtarlığa bile,...', ARRAY['Türk Edebiyatı','Şiir','Saim Bastık']::text[], 8.5, '{"poet":"Saim Bastık","poet_slug":"saim-bastik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/adamin-biri-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cesaret', 'cesaret-gulsen-gonenc-lhvsp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaybederim diye korkmadıkça

Emeksiz kazanılmış aşk; 

Dönüşmez sevgiye.

Umurunda olacağı gün:

Cesaretimin olacağı,

Geç kalınmış bir gündür.

Cesaretim yok değil aslında.

Sana üzülüyorum,

Bulamazsın böyle aşkı ve türevlerini.', 'Kaybederim diye korkmadıkça Emeksiz kazanılmış aşk;  Dönüşmez sevgiye. Umurunda olacağı gün: Cesaretimin olacağı, Geç kalınmış bir gündür. C...', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cesaret-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli mavi (Dörtlük)', 'deli-mavi-dortluk-ahmet-bektas-9wlrs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senden ayrı kaldım gülüm,özlemin yüreğimde.

Arar gezerim gündüzde,karanlık gecelerde.

Bir umut bildim sarıldım,teselli niyetiyle;

Dostluğun mekanı olan,deli mavi sevdama.', 'Senden ayrı kaldım gülüm,özlemin yüreğimde. Arar gezerim gündüzde,karanlık gecelerde. Bir umut bildim sarıldım,teselli niyetiyle; Dostluğun ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bektaş']::text[], 8.5, '{"poet":"Ahmet Bektaş","poet_slug":"ahmet-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/deli-mavi-dortluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sobe', 'sobe-cemil-aygen-xxf2f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mavinin yarısı

Bitti

Şimdi Göğün tam karası

Senin sayendeyim ben

Elalemin maskarası

Neredeysen çık 

Akşam oldu...Saklambaç bitti

Gel 

Sobe demiyeceğim

Tamam...Tövbe diyeceğim

Hadi dön artık 

Yoksa ben gelip

Sobeleyeceğim', 'Mavinin yarısı Bitti Şimdi Göğün tam karası Senin sayendeyim ben Elalemin maskarası Neredeysen çık  Akşam oldu...Saklambaç bitti Gel  Sobe d...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sobe-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaş', 'savas-gulsen-gonenc-73e57', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İsyan edemiyorum ilk kez.

Tek taraflı savaşlar daha zormuş.

Gerçek bir savaş istiyor canım:

kıran kırana, 

kazananı kaybedeni belli olmayan; 

tüm savaşlar gibi.

Şiddetsizliğinin şiddetinden ölüyorum.', 'İsyan edemiyorum ilk kez. Tek taraflı savaşlar daha zormuş. Gerçek bir savaş istiyor canım: kıran kırana,  kazananı kaybedeni belli olmayan;...', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/savas-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzüntü', 'uzuntu-gulsen-gonenc-gleek', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni üzmek istemiyorum deme.

Beni üzmüyorsun; 

Sana üzülüyorum.', 'Seni üzmek istemiyorum deme. Beni üzmüyorsun;  Sana üzülüyorum....', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/uzuntu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Hiç Kendini Özledin mi', 'sen-hic-kendini-ozledin-mi-memed-ayaz-nmnqm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'elleri bağlı huzur 

                kıyam etmede ayakucunda

tan ağarıyor.

gözlerin; 

        üstüne titrediğim mezar taşları..

sen hiç karanlığı kokladın mı

hapsedip ciğerlerinde eze eze 

varabildimi tadına...

yapmadınsa nerden bileceksin

yanlızlığın kıymetini...

sen hiç kendini özledin mi.', 'elleri bağlı huzur                  kıyam etmede ayakucunda tan ağarıyor. gözlerin;          üstüne titrediğim mezar taşları.. sen hiç karan...', ARRAY['Türk Edebiyatı','Şiir','Memed Ayaz']::text[], 8.5, '{"poet":"Memed Ayaz","poet_slug":"memed-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-hic-kendini-ozledin-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fısıltı', 'fisilti-nurcemal-ozturk-gplr4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün esen rüzgâra

Birkaç şey fısıldadım

Yakında duyarsın

Kulağın rüzgârda olsun

Aklın bende

Kalbin yerinde dursun

Onsuz yaşayamazsın

Gönlünü ver sadece

Yüreğinin içini

Gözlerin senin olsun

Manâsını bana ver

Bahçendeki güllerin

Yaprağını sen sakla

Dikenlerini gönder

İncitmesin elini

Ben gönlümde saklarım

Parçalasın bağrımı

İşitirsin ahımı

Duyarsın eyvahımı

Sana bülbülün sesi

En güzel nağmelerle

Ben kargayı dinlerim

Bağrıma taş basarak

Sen yeterki incinme 

Gidiyorum işte bak

Ciğerim kan kusarak.', 'Bugün esen rüzgâra Birkaç şey fısıldadım Yakında duyarsın Kulağın rüzgârda olsun Aklın bende Kalbin yerinde dursun Onsuz yaşayamazsın Gönlün...', ARRAY['Türk Edebiyatı','Şiir','Nurcemal Öztürk']::text[], 8.5, '{"poet":"Nurcemal Öztürk","poet_slug":"nurcemal-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/fisilti-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vebalim Kolye Olacak Boynuna', 'vebalim-kolye-olacak-boynuna-cafer-tayyar-ozkan-3qcxy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artık boşuna ağlama…

Umut deryasına murat tohumları atan,

Kor ateşten hülyaları anlatan, sendin…

Bensiz geçen her gecene sardığın vebalim,

Kolye olacak boynuna…

Hani sevdan mahşere kadardı? 

Artık boşuna ağlama…

Daha kaç hazan geçti ki andından,

Benim bildiğim bedenin,

Kaderine köle olmuş ezelden…

Kalbime dövülen sıfatın

Silinmez, koparıp öldürmeden.

Çekip git ihanet yolundan,

Çıkma gayri bir daha,

Seviyorum sözüyle karşıma.

Can koymuştum senin uğruna,

Sense yaşarken koydun mezara…

Hele sen sus! hiç ağlama; 

Vebalim kolye olacak boynuna…

30 Ocak 2005 Ankara, Pazar', 'Artık boşuna ağlama… Umut deryasına murat tohumları atan, Kor ateşten hülyaları anlatan, sendin… Bensiz geçen her gecene sardığın vebalim, K...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vebalim-kolye-olacak-boynuna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Bana Sor', 'gel-bana-sor-mehmet-sait-akkus-8vnzj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkın dalına bir gün konar isem

Aşkın narına bir gün yanar isem

Ateş olupta bir gün yakar isem

Yanıyorum amma sen gel bana sor

Deler isen,yüreğimi delersin

Hem akıldan,hem fikirden edersin

Bu benim sonum,ne olur dersin

Delirecem amma sen gel bana sor

O gülüşün,bakışın mest eyledi

O fikrin,güzelliğin zay eyledi

Sana hep yandığımı kim söyledi

Bitiyorum amma sen gel bana sor

Ben sana gönülden vede yürekten

Ayrılırmı sandın sen et kemikten

Yanıyorum seni hep düşünmekten

Eriyorum amma sen gel bana sor', 'Aşkın dalına bir gün konar isem Aşkın narına bir gün yanar isem Ateş olupta bir gün yakar isem Yanıyorum amma sen gel bana sor Deler isen,yü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gel-bana-sor-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Genelde İzmirli''ye Güvenmem', 'genelde-i-zmirli-ye-guvenmem-munevver-senol-qhn3a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsan İzmir''de günde tam dört mevsim yaşıyor

İnsanlarıda, havasına uymuş canım, gören buna şaşıyor.

Bir kere oruç tuttuğuyla, bayram etmiyor.

Cebinde akrep var sanki, eli hiç cebine gitmiyor.

Sizde yiyip içelim, bizde gülüp söylüyelim.

İyi de canım, şimdi buna güç yetmiyor.

Durup dururken, seni çok seviyorum derse, sakın inanma.

Arkandan çekiştirirken, gördüğünü farkedince seni.

Gülerek,

AAA, bizde senden konuşuyorduk.

İyi insanda lafının üzerine gelirmiş hani.

Vay Allah''sız kertenkele! , 

Vay yalanın batsın emi? 

İşine gelirse sana der, hay hay! 

Bir de işine gelmezse,

Sana der bay bay! 

Bende biletini kestim senin.

Hadi git gidebildiğin yere, bendende sana çavvv...', 'İnsan İzmir''de günde tam dört mevsim yaşıyor İnsanlarıda, havasına uymuş canım, gören buna şaşıyor. Bir kere oruç tuttuğuyla, bayram etmiyor...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/genelde-izmirli-ye-guvenmem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yerlerde Buluşalım', 'bir-yerlerde-bulusalim-mehmet-sait-akkus-evpgn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senin sevgin bana yeter

Gel beraber konuşalım

Baksana ömür geçiyor

Bir yerlerde buluşalım

Ben bir şey istemiyorum

Gönül kapın açık kalsın

Sana bir şey demiyorum

Bu yürek hep seni ansın

Yanar ise ben yanyım

Yandığım aşkın olsun

Sabah akşam yanındayım

Amaç sevgimiz solmasın', 'Senin sevgin bana yeter Gel beraber konuşalım Baksana ömür geçiyor Bir yerlerde buluşalım Ben bir şey istemiyorum Gönül kapın açık kalsın Sa...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-yerlerde-bulusalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkma', 'korkma-alper-kuruk-9geaa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ölümün kul,kölesi ölene dek korkanlar

Onlar ancak öldükten sonra korkusuz yaşar.

Cesur üç günlük ömür uzundur yüz yıl kadar

Yaşanan o ömürde ölümsüz bir lezzet var.

Korkak kendinden kaçar,sığınır bir korkağa

Gölgesinden ürperir,güvenmez sola,sağa,

Düz yolda tökezlenir,mümkün mü çıkmak dağa? 

Son değil ilk düşen o kaçıp korktuğu ağa.

Gel korkuyla yaşama şu kısacık ömründe

Gerçek cesur olmasan sen de cesur görün de

Göreceksin diz çöker korkuların önünde,

Yarını yaşar kalbin,korkular kalır dünde...', 'Ölümün kul,kölesi ölene dek korkanlar Onlar ancak öldükten sonra korkusuz yaşar. Cesur üç günlük ömür uzundur yüz yıl kadar Yaşanan o ömürde...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/korkma-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapattım', 'kapattim-ali-dost-aydin-4kphk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasıl kaçsam bilmiyorum 

Gelip, gelip çalıyor kapımı 

Nasıl açsam bilmiyorum

Çok çekmişim acını 

Kapatmışım bir kere 

Neden uslanmaz gönlüm

Ne olur hiç açılmasa 

Yok, yok olmuyor işte 

Bir yanlışlık var bu gidişte 

Her kaptırıp gidişte

kendimi

Acılar içinde buluyorum yüreğimi 

Ama bu gönül yok mu

Bu gönül

Kor yüreğimi ateşte 

Kor gibi 

Yakar işte 

Bu kez dinlemiyorum

Gönül seni

Titretsen de dizlerimi 

Yaksan da aşk ile gözlerimi

Bu kez dinlemiyorum

Seni

Alıp başımı giderim

Gerekirse 

Kaparım gözlerimi 

Dalıp giderim

Eski aşklarıma

Gene de gelmem 

oyununa bir daha 

Çekmem acılarını 

Dondurmak pahasına 

Hayatımı 

Gelmem gönül

Senin  oyununa 

Kanmam gönül sana 

Kanmam bir daha', 'Nasıl kaçsam bilmiyorum  Gelip, gelip çalıyor kapımı  Nasıl açsam bilmiyorum Çok çekmişim acını  Kapatmışım bir kere  Neden uslanmaz gönlüm ...', ARRAY['Türk Edebiyatı','Şiir','Ali Dost Aydın']::text[], 8.5, '{"poet":"Ali Dost Aydın","poet_slug":"ali-dost-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kapattim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Seninle Nede Sensiz', 'ne-seninle-nede-sensiz-munevver-senol-7pjnd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seninle biryerlere sığamıyorum.

Tıpkı yaramaz bir çocuk gibisin.

Senide bırakıp gidemiyorum,

Ne yapayım ben? 

Şeytan diyor ki, 

al başını çek git bu dünyadan.

Allah kahretsin genede yapamıyorum.

Bazan aklıma geliyor bana yaptığın haksızlıklar,

Ammaa

Şimdi bakıyorumda, 

Arkamdan ağlayan, çocuk gibisin.

Şeytan diyor ki, 

al başını çek git bu dünyadan.

Allah kahretsin, genede yapamıyorum.

Vicdanım elvermiyor, 

seni terkedip gidemiyorum.

Sen benim alın yazımsın silemiyorum...', 'Seninle biryerlere sığamıyorum. Tıpkı yaramaz bir çocuk gibisin. Senide bırakıp gidemiyorum, Ne yapayım ben?  Şeytan diyor ki,  al başını çe...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-seninle-nede-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Seher Vaktinde', 'bir-seher-vaktinde-nuri-ozoglu-do6m4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir seher vaktinde açtım yelkeni,

Sular coşar, ben de hayli coşarım.

Seveceksen, ta içerden sev beni,

Yoksa, yadellere doğru koşarım.', 'Bir seher vaktinde açtım yelkeni, Sular coşar, ben de hayli coşarım. Seveceksen, ta içerden sev beni, Yoksa, yadellere doğru koşarım....', ARRAY['Türk Edebiyatı','Şiir','Nuri Özoğlu']::text[], 8.5, '{"poet":"Nuri Özoğlu","poet_slug":"nuri-ozoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-seher-vaktinde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Ne Olsun', 'daha-ne-olsun-muhsin-altintas-3safh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşktan yara aldıksa şehit değiliz

Bugün biz mutluyuz, daha ne olsun? 

Gölgelerde Güneşe hasret kaldıksa biz,

Yarından umutluyuz daha ne olsun? 

Boyun''mu bükmedik, sitemmi etmedik? 

Bizmi ağlamadık, çile çekmedik? 

O sonsuz deryada bizmi batmadık? 

Bundan böyle rotadayız daha ne olsun? 

Artık bir mazi o kederler, hüzünler,

Ya uykusuz geçen sonsuz, zalim geceler,

Bir dilence misali beklenen, karşılıksız sevgiler,

Ben o ben değilim daha ne olsun? 

Sanmaki hüsranlar gelip geçmezmiş,

Zannetme pişmanlık fayda etmezmiş,

Onsuz yaşamakmı, ölüm demekmiş,

Bak ben yaşıyorum daha ne olsun? 

İnsaf beklenirmi bir zalim kuldan? 

Her seven geçer mutlak bu yoldan,

Tek hatıra acı o günden kalan,

Artık geçmiş geçti daha ne olsun? 

Gönül huzur, mutluluk, sevinçle dolsun...', 'Aşktan yara aldıksa şehit değiliz Bugün biz mutluyuz, daha ne olsun?  Gölgelerde Güneşe hasret kaldıksa biz, Yarından umutluyuz daha ne olsu...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Altıntaş']::text[], 8.5, '{"poet":"Muhsin Altıntaş","poet_slug":"muhsin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/daha-ne-olsun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Pazarında', 'can-pazarinda-nuri-ozoglu-s19ft', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her nereye baksam, can pazarında,

Her yanımda cansız beden kol gezer.

Her nedense derim dost nazarında,

İyi günde kötü günüm yol gezer.', 'Her nereye baksam, can pazarında, Her yanımda cansız beden kol gezer. Her nedense derim dost nazarında, İyi günde kötü günüm yol gezer....', ARRAY['Türk Edebiyatı','Şiir','Nuri Özoğlu']::text[], 8.5, '{"poet":"Nuri Özoğlu","poet_slug":"nuri-ozoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/can-pazarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Adımda Ölüm Var', 'her-adimda-olum-var-nuri-ozoglu-riu2r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yollar kesik kesik, gözlerimde uçurum,

Eğer ölmek yakınsa, yaşamakla bodurum.

Her adımda ölüm var, dönen var mı bu yoldan? 

Gündüzler bana zindan, gecelere vurgunum.', 'Yollar kesik kesik, gözlerimde uçurum, Eğer ölmek yakınsa, yaşamakla bodurum. Her adımda ölüm var, dönen var mı bu yoldan?  Gündüzler bana z...', ARRAY['Türk Edebiyatı','Şiir','Nuri Özoğlu']::text[], 8.5, '{"poet":"Nuri Özoğlu","poet_slug":"nuri-ozoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/her-adimda-olum-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Dair', 'sana-dair-fethi-aslan-2f80b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabah kalıkiyorum,seninle başlıyorum güne

ilk kelimem Seni Seviyorum

kahvaltıda,yolda,otobüste,

düşüncelerimde haykırıyorum Seni Seviyorum

Seni Seviyorum,seviyorum,seviyorum.....

Sekiz onbeş otobüsünü kaçırıyorum,

herkes küfürler sayıyor otobüsün arkasıdan,

ben sana sevgimi haykiriyorum,

seni seviyorum,seni seviyorum.....

Dolmuşa atlıyorum...

Emirgan diyemiyorum,seni seviyorum diyorum

Paramin üstünü alıyorum...seni seviyorum

Muavin ters ters bakıyor gözlerime,

Ineceğim,müsayit bir yerde dur diyemiyorum

Seni seviyorum`da diyorum.

Okkalı bir yumruk yiyorum.

Ama ne yapayım elimde degil,

Seni seviyorum,seni seviyorum….

Işte,sokakta,ellerim cebimde seni sayıklıyorum,

Seni seviyorum,seni seviyorum.....

Bir Taksi hızla geçiyor yanımdan,baştan aşagı çamurlu su,

dönüyorum,kaldırıyorum elimi havaya,

olanca kuvvetimle haykırıyorum,

Seni seviyorum....

Bakkal,kasap,manav yolumu kesiyor,para istiyor 

Ben  sevdamın sonunda diyorum,

ev kirası,sevdamın sonunuda

elektirik parası,sevdamın sonunda

telefon parası,sevdamın sonunda

mırıldanarak delirdiğimi söylüyorlar

oysa ben,seni seviyorum.

Bazen dostları görüyorum,

iki laf edelim diyorlar, ben seni düşünüyorum yine

başımı eğiyorum öne,seni düşünüyorum

kelimeler kaybediyor birer birer anlamlarını,soluklaşıyorlar herşey gibi.

iki şey kalıyor sadece

iki kelime herşeyden öte

seni seviyorum...', 'Sabah kalıkiyorum,seninle başlıyorum güne ilk kelimem Seni Seviyorum kahvaltıda,yolda,otobüste, düşüncelerimde haykırıyorum Seni Seviyorum S...', ARRAY['Türk Edebiyatı','Şiir','Fethi Aslan']::text[], 8.5, '{"poet":"Fethi Aslan","poet_slug":"fethi-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sana-dair-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir şarkılar biliyor', 'bir-sarkilar-biliyor-bunyamin-aslan-n1fjh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir şarkılar biliyor

bir şarkılar biliyor 

içimde uzayan zamanı

benden daha çok

yağmur alevi düştüğünü göklere

bir ağlayanlar

bu kadar mı derin ey sevgili

gözlerinde kuyu

bu kadar mı çıkmaz yollarım

bir anneler biliyor

kanına gül damladığını yavruların

gökler üstüne titriyor

diken batıyor yavruların ellerine

annelerin kalbine mızraklar

bıçak gibi kesiyor duları

kadınların nazarlarını

bir resimler biliyor

kaderiyle yüzleştiğimi yaralarımın

göz kapakalarım açılmaya yakın

açmaya korkuyor insan

bir Allah biliyor

neden terkettiğini 

yüreğini adressiz şehirlere

adını andığımda yittiğimi

yetmedi mi yar yüzü haram

düşler duyduğum

bir sonun var mı senin 

seni sensiz sevmelerimin', 'bir şarkılar biliyor bir şarkılar biliyor  içimde uzayan zamanı benden daha çok yağmur alevi düştüğünü göklere bir ağlayanlar bu kadar mı de...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Aslan']::text[], 8.5, '{"poet":"Bünyamin Aslan","poet_slug":"bunyamin-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-sarkilar-biliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dualar olmasa', 'dualar-olmasa-bunyamin-aslan-rxacs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dualar olmasa

hangi rüya uyanıyor gözlerinde

hangi düş uyanıyor

çehrende su aydınlığı

ey vefam yalnızlığım benim

geceler boyu bilsen

topraklar çekiyor beni

gök çöküyor üstüme

bilmezsin duvarlar sıkışıyor

her taraf daralıyor

dualar olmasa ölüyor insan

her gece', 'dualar olmasa hangi rüya uyanıyor gözlerinde hangi düş uyanıyor çehrende su aydınlığı ey vefam yalnızlığım benim geceler boyu bilsen toprakl...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Aslan']::text[], 8.5, '{"poet":"Bünyamin Aslan","poet_slug":"bunyamin-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dualar-olmasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haram', 'haram-bunyamin-aslan-9vdf7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sana aydınlık haram çocuk

ışıklarını çaldılar merhemetlerin

boşuna kırılmadı gökler

bulutlar boşuna yumulmadı içine', 'sana aydınlık haram çocuk ışıklarını çaldılar merhemetlerin boşuna kırılmadı gökler bulutlar boşuna yumulmadı içine...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Aslan']::text[], 8.5, '{"poet":"Bünyamin Aslan","poet_slug":"bunyamin-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/haram-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hal', 'hal-bunyamin-aslan-4b0ui', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hal

hasretin birikiyor

bilmiyorsun gözlerin batıyor uykularıma

mesafelere tahammül kader mi

yüreğini kusuyor şairler

gurbet şiirlerine

senin yüreğin sılasız

kalemlerimi duy

kanıma damlamasın gözyaşların

gel de yaşa yaşanmazlığını

pencerenin ardında dar hayat

sıkıştı karanlıklar

akşamlar boğuluyor

güeşi yutuyor ufuklar

yetim dualrı tutuyor kaldırımları

gök çöküyor üstüme

toprak çekiyor bir yanımı

ne kadar dar hayat

ölüm ne kadar geniş', 'hal hasretin birikiyor bilmiyorsun gözlerin batıyor uykularıma mesafelere tahammül kader mi yüreğini kusuyor şairler gurbet şiirlerine senin...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Aslan']::text[], 8.5, '{"poet":"Bünyamin Aslan","poet_slug":"bunyamin-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hal-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doluyum', 'doluyum-bunyamin-aslan-dqmt9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'geri dönülür mü

maviliğini yitirmiş okyanuslara

açın yağmurları ey merhametler

gökler yağmalı bu gece

yoksa ben doluyum......', 'geri dönülür mü maviliğini yitirmiş okyanuslara açın yağmurları ey merhametler gökler yağmalı bu gece yoksa ben doluyum.........', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Aslan']::text[], 8.5, '{"poet":"Bünyamin Aslan","poet_slug":"bunyamin-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/doluyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pencereler', 'pencereler-bunyamin-aslan-lqyi1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'pencereler

kanına giriyorlar ışıkların

akşamların karanfil aydınlığı sönüyor

yarin gözlerinde ölümler

ateşe pervane

bir bir ölüyor kelebekeler

pencereler açmıyor', 'pencereler kanına giriyorlar ışıkların akşamların karanfil aydınlığı sönüyor yarin gözlerinde ölümler ateşe pervane bir bir ölüyor kelebekel...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Aslan']::text[], 8.5, '{"poet":"Bünyamin Aslan","poet_slug":"bunyamin-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/pencereler-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Girdap', 'girdap-bunyamin-aslan-i1s53', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'girdap

geç oldu vakit

kalemlere çekiyor 

içini doldurduğun kelimeler

içini boşalttığın

karanlık cezbediyor insanı

güneş haram

bu yalnızlık ağır

kanıma yumuyor ellerini

üstüme vuruluyor kapılar

topraklar daralıyor

bu uğultulu rüzgar bana

sağanaklar gtiriyor

bulutların kanatlarından

bir kadın ölümleri çağırıyor

ve toprağı elleri

yüzünü okuyorum dualara

nefesim kesilmeye yakın', 'girdap geç oldu vakit kalemlere çekiyor  içini doldurduğun kelimeler içini boşalttığın karanlık cezbediyor insanı güneş haram bu yalnızlık a...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Aslan']::text[], 8.5, '{"poet":"Bünyamin Aslan","poet_slug":"bunyamin-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/girdap-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbime bağladım', 'kalbime-bagladim-bunyamin-aslan-sfrx1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kalbime bağladım

ya al yüreğine beni

ya azad et sevdadan

iplik iplik damarlarımla

kalbime bağladım seni', 'kalbime bağladım ya al yüreğine beni ya azad et sevdadan iplik iplik damarlarımla kalbime bağladım seni...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Aslan']::text[], 8.5, '{"poet":"Bünyamin Aslan","poet_slug":"bunyamin-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kalbime-bagladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş', 'gunes-bunyamin-aslan-lhzgi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'GÜNEŞ

Gözlerin derin bakıyor,kuyular

Kuyuda Yusuf güzelliği ateş

Dirilir bir bir Züleyha soylular

Sevdalar kime zindanlar kime eş

Üşüyen bir ateş yanan su gönül

Kanadım boyuna hançeremde gül

Sırrımı aşikar etmesin bülbül

İçimde dirilsin ölsün çilekeş

Nereye gidersen kader seninle

Bir anne ruhunun sesini dinle

Dualar kalbine aksın serinle

Çekil aynalara kendinle yüzleş

Ellerine çekilir gül ve hançer

Hayat bu gün olur Yusuf su ister

Gün olur Yusuf''a sultanlık düşer

Ağlar sırtında bir bıçakla kardeş

Şimdi söz yetmiyor bildim bir daha

Gördüm sevaplar karıştı günaha

İçimde sorular çıktım sabaha

Artık kalbimize doğsun bir GÜNEŞ', 'GÜNEŞ Gözlerin derin bakıyor,kuyular Kuyuda Yusuf güzelliği ateş Dirilir bir bir Züleyha soylular Sevdalar kime zindanlar kime eş Üşüyen bir...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Aslan']::text[], 8.5, '{"poet":"Bünyamin Aslan","poet_slug":"bunyamin-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gunes-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz yetmiyor', 'soz-yetmiyor-bunyamin-aslan-jr71c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SÖZ YETMİYOR

Güneş çekilir yüreğime

Işıktan mızraklarıyla

Yüzümde yar aydınlığı

Yine bir hal var bende

söz yetmiyor

Yanımda olsaydın bu kadar

Esrarlı olmazdı gözlerin

Kirpiklerin kanıma batmazdı

Sen bin karanlık öte

Bir aydınlık yakın

Yokluğunla varsın

Bilsen yokluğun...

Bilme seni de tutmasın

Kalbine iğne gibi batmasın

Şarkıların ritimleri

Uykularını sancılar basmasın

Yalnızlık zor tesellisiz

Bir başıma yaşarım

Duyma seni de tutmasın

Buna hakkı yok sevmelerimin

Sen dağ ol

Ben dağa küseyim

Hadi sen de çek bıçaklarını

Kanıma bilensin gözlerin

Ya hayat ver ya...

İnsan kendi düşmez sevdaya

Dualar çekiyor gecelere

Ve tanrı böyle buyurdu

Söz yetmiyor...', 'SÖZ YETMİYOR Güneş çekilir yüreğime Işıktan mızraklarıyla Yüzümde yar aydınlığı Yine bir hal var bende söz yetmiyor Yanımda olsaydın bu kada...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Aslan']::text[], 8.5, '{"poet":"Bünyamin Aslan","poet_slug":"bunyamin-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/soz-yetmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Pamuk Baba*', 'pamuk-baba-kubilay-enginol-s4lwq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sabah

Pamuk saçlarını taradı yine

Terso olunca, kahvede yatardı

Buruşmuş ceketi,pantolonu

O günün kötü olduğunu ispatlardı

Oturdu herzamanki gibi masaya

Birazdan damlardı,kumarbazlar yine kumara

Kupa papazı,maça yedilisi

Ne denk gelirse,ellisi,yüzellisi

Sigaradan sararmış elleri

Görmüştü elbet,güzel günleri

Hele evlenmek isteyen rum dilberi

Hayıflanırdı şimdi,soğuk geceleri

Sular,seller gibi akmıştı ömrü

Her sabah karşılar oldu hüznü

Akşam....

Yine kaybetmişti

Sandalyelere uzandı

Gözlerini yumdu,sabaha çok vardı', 'Sabah Pamuk saçlarını taradı yine Terso olunca, kahvede yatardı Buruşmuş ceketi,pantolonu O günün kötü olduğunu ispatlardı Oturdu herzamanki...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/pamuk-baba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gün', 'bir-gun-bunyamin-aslan-5914d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BİR GÜN

bir gün çeker gider içimizden

iplik iplik damarlarımızla 

kalbimizi bağladığımız sevgili

gider de güç geçer

yarsız yarenlik zor ağır

şimdi nereye göçer gönül

sensiz sıla gurbet

vuslat arar iken ben

kendime gurbet oldum

ey sevdiğim vefam

kalbimi duy 

duymuyorsan yazık', 'BİR GÜN bir gün çeker gider içimizden iplik iplik damarlarımızla  kalbimizi bağladığımız sevgili gider de güç geçer yarsız yarenlik zor ağır...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Aslan']::text[], 8.5, '{"poet":"Bünyamin Aslan","poet_slug":"bunyamin-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-gun-133-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgim Sımsıcak Sarsın Seni', 'sevgim-simsicak-sarsin-seni-hulya-arikan-gur4t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Toprak anadır gönlüm; besler bağrında yeşerttiğini

Canından can katar, teninden tin

Bakmam yok oluşuma…

Nadasa kalmışım kime ne…

Seni büyütmektir görevim…Seni yüceltmek tek gaye

Sen büyüdükçe kabarır coşar toprağım

Yeşilin uzadıkça gökyüzüne,

Meyvelerin toplandıkça bir bir

Dellenir bu yürek …Bir garip olur yatağım…

Uzaktayım diyorsun…

Bıraktım ellerini...Dalım koptu gövdemden…

Alıp başını gitsen de toprağından 

Rakamları silinmiş zaman, kopuk mesafeler girse de aramıza

Daima yüzümdedir nefesin

Tenimdedir sıcacık gülüşün...

Şimdi vuruyor olsa da duvarlarıma sağanak yağmurlar

Hırsını çıkarırcasına …delercesine bağrımı…

Bilesin ki yine de sökülmeyecek bu sevda bu gönülden

 Sen gül bi tanem 

Sen mutlu ol yeter ki…

Sen güldükçe ben büyürüm inan.

Adını andıkça çoğalırım kat kat

Gün be gün sardıkça sevdan bedenimi

Sımsıcak sevgim kuşatır karanlık düşlerini', 'Toprak anadır gönlüm; besler bağrında yeşerttiğini Canından can katar, teninden tin Bakmam yok oluşuma… Nadasa kalmışım kime ne… Seni büyütm...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arıkan']::text[], 8.5, '{"poet":"Hülya Arıkan","poet_slug":"hulya-arikan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevgim-simsicak-sarsin-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir başına bir kız', 'bir-basina-bir-kiz-bunyamin-aslan-qfjfo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BİR BAŞINA BİR KIZ

bir başına bir kız

kendi başına

dört duvar daralıyor üstüne

kalbi geniş bir kız

dünyalar sığar içine

kız sığmaz dünyaya

bir başına bir kız

körpe bebeler ellerinde

bebeler masum

gözleri merhametler dilenir

yüreği derya deniz kız

şefkatler kol kanat

bir başına bir kız 

çiçek

sanırsın kar çiçeği

mevsimsiz zamansız

toprağı aydınlatır bir yüzü

bir yüzü suya yakın

zamansız fermansız

bir başına bir kız

güneş olup doğuyor

içinde gül yangınları

nazarlar ateşten ok

ibrahimin atıldığı ateş bu

yakmıyor serin

bir başına bir kız

varlığında huzur

bilmeyen bilmez

bilen hakkıyla bilmez

duy ve ağla huzuru

kan yaş olsun gözlerim

bir başına bir kız

rüzgarın önünde

sanırsın gül yaprağı

duymaya engel mi mesafeler

zaman engel mi yitmeye

bir başına bir kız 

kendine ana

mağrur

dualar sağanak üstünde

bir başıma bir ben

çekilirim yalnızlığıma

yar aydınlığı haram

soframda kuşlar

ekmeğimi bölüşürüm

kuşlar bi vefa

bir başıma bir ben 

anne dualarından mahrum

oyuncağını kırmışlar içimdeki çocuğun

büyümemişim

ne geceler avutur beni

ne yar hasreti karanlıklar

bir topraklar avutur

bir başıma bir ben

aklımda birbaşına bir kız', 'BİR BAŞINA BİR KIZ bir başına bir kız kendi başına dört duvar daralıyor üstüne kalbi geniş bir kız dünyalar sığar içine kız sığmaz dünyaya b...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Aslan']::text[], 8.5, '{"poet":"Bünyamin Aslan","poet_slug":"bunyamin-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/bir-basina-bir-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben bu çığlıklara yenildim...', 'ben-bu-cigliklara-yenildim-ayfer-ersoy-9audr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yanımda yalnızlığım cıktım yola

içimde kalabalığımla...

ayaklarımın götürdüğü yer 

yüreğimin götürdüğü yer...

ellerim kabullendi boynu bükük güle..

gözlerime kaldı imbat güneşi....

yanımda yalnızlığım çıktım yola

içimde kalabalığımla....

sessizken...

çığlıklar uyandırır beni...

ben bu çığlıklara yenildim........

16/11/2005 izmir sabahı....', 'yanımda yalnızlığım cıktım yola içimde kalabalığımla... ayaklarımın götürdüğü yer  yüreğimin götürdüğü yer... ellerim kabullendi boynu bükük...', ARRAY['Türk Edebiyatı','Şiir','Ayfer Ersoy']::text[], 8.5, '{"poet":"Ayfer Ersoy","poet_slug":"ayfer-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-bu-cigliklara-yenildim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Beklemek', 'seni-beklemek-sedat-gurleyik-u9nw8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlıkları delen bir ışık hüzmesi,

Suları hırçınlaştıran bir kamçı sanki.

Zaman beni sana hapsetti

Gel gör ki aşkın kül etti beni.

Sana kavuşmak için çok bekledim,

Yüreğimin ateşine su serptim.

Biliyorum birgün geleceksin.

Çünkü sevmeyi bana sen öğrettin 

Saçlarının sarısı gözlerinin yeşili,

Mecnunun Leylası Ancak bu kudar güzeldi

Sensiz geçen her günüm ömre bedeldi.

Ne olursun gel ne olur gel ey sevgili', 'Karanlıkları delen bir ışık hüzmesi, Suları hırçınlaştıran bir kamçı sanki. Zaman beni sana hapsetti Gel gör ki aşkın kül etti beni. Sana ka...', ARRAY['Türk Edebiyatı','Şiir','Sedat Gürleyik']::text[], 8.5, '{"poet":"Sedat Gürleyik","poet_slug":"sedat-gurleyik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-beklemek-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-bunyamin-aslan-q1xvn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'aradan günler geçti

bak takvimlere

kaçıncı günü yalnızlığın

yüreğime sorma zamanı

biri iki yaşadım

yaşamaksa adı', 'aradan günler geçti bak takvimlere kaçıncı günü yalnızlığın yüreğime sorma zamanı biri iki yaşadım yaşamaksa adı...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Aslan']::text[], 8.5, '{"poet":"Bünyamin Aslan","poet_slug":"bunyamin-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalnizlik-300-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-bunyamin-aslan-qfoa9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'biz

biz severiz 

biz sevilir gizliden

kimseler bilmez

ateşten yüreğimiz

buselerinden hayatın

yeni aldık nasibimizi

bir fidanlık ömür ömrümüz

cemreler yeni düştü yüreğimize

iki meleğiz

birbiri için yaratılmışlığı kaderin

kaderin sevdası

sevdanın kaderi

kaderimize sevdalandık', 'biz biz severiz  biz sevilir gizliden kimseler bilmez ateşten yüreğimiz buselerinden hayatın yeni aldık nasibimizi bir fidanlık ömür ömrümüz...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Aslan']::text[], 8.5, '{"poet":"Bünyamin Aslan","poet_slug":"bunyamin-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/biz-94-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni unutmak', 'seni-unutmak-bunyamin-aslan-0wzm8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seni unutmak

seni unutmak 

ölmek kadar kolay olsa

unutulmak kadar 

zor olurdu yaşamak

acı düşmemiş zamanlara sevda uyutmak

beyhude gönül seni avutmak

sular uyudu 

kullar uyudu

sen hala uyumadın

Güneş

senin de içine bir Güneş düşsün

içine bir gonca ateş düşsün

sen de yan

kolaysa yanmak

seni unutmak 

gülmek kadar kolay olsa

yüreğime kundakladığım sevdayı

ölesiye yaşardım

lakin zor gülmek

bu yüzden gülmeziye yaşıyorum

ölmeziye

sen yeminler veriyorsun gelmeziye

seni unutmak 

solmak kadar kolayolsa

gül kurusu yanaklarına yazgı olurdum

kalemine ezgi', 'seni unutmak seni unutmak  ölmek kadar kolay olsa unutulmak kadar  zor olurdu yaşamak acı düşmemiş zamanlara sevda uyutmak beyhude gönül sen...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Aslan']::text[], 8.5, '{"poet":"Bünyamin Aslan","poet_slug":"bunyamin-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/seni-unutmak-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgünüm Sevdanla', 'surgunum-sevdanla-kamil-soylemez-pnqen', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sürgünüm istanbulda

Sensiz gece ve sabaha

Sürgün...! 

Başım gözüm üstüne sevdam

Sanadır sadaka

Gelip,gitmelerim sana

Bazan olurum fukara 

Aşkınla çıkmışım istanbul sokaklarına

Bir bulutki karası gözlerimde

Dokunsan inicek yağmur olup sokaklara

Sevgin özlemin yarasıyla

Seni sorar seni ararım bu diyarda

Çıksan sokak ucuma

Seviyorum seni dergibi gözlerin

Sarıp sarmalasa

Bilki bahar olurum sana

Haydi çık bitanem çıkta gel sokak ucuma

Bıraktığın yerde bekliyorum seni hağla', 'Sürgünüm istanbulda Sensiz gece ve sabaha Sürgün...!  Başım gözüm üstüne sevdam Sanadır sadaka Gelip,gitmelerim sana Bazan olurum fukara  Aş...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/surgunum-sevdanla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Affetmezse', 'ask-affetmezse-tijen-karabina-cm8hj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gecelerden saklanırdım, 

Utanırdım,

Korkardım. 

Güne ihanet gibi gelirdi 

Hiç gülümsemezdim geceleri 

Karanlık olunca erken yatardım 

Çabucak sabah olsun diye. 

Sabahın ilk ışıklarıyla 

Derin bir nefes alırdım. 

O gecenin gidişine sevinirdim 

Aşık olmadan, ağlamadan,

Yıldızlara donuk donuk bakmadan 

Aydan medet ummadan geçen bir gece.

Zamanla günlerin geliş sevinci 

Yerini gecelere bıraktı.

Ve ben Geceleri arar oldum.

Utandım gecelerden saklandığımdan, 

Daha çok korktum.

Geceler beni affeder de 

Ya Aşk affetmezse...', 'Gecelerden saklanırdım,  Utanırdım, Korkardım.  Güne ihanet gibi gelirdi  Hiç gülümsemezdim geceleri  Karanlık olunca erken yatardım  Çabuca...', ARRAY['Türk Edebiyatı','Şiir','Tijen Karabina']::text[], 8.5, '{"poet":"Tijen Karabina","poet_slug":"tijen-karabina","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ask-affetmezse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Defasında', 'her-defasinda-tijen-karabina-ycxs3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her defasında 

Yumruk gibi iniyor göğsüme 

Sözlerin 

Hep o yalnızlığı çağrıştırıyor 

İliklerime kadar işliyor 

Gecenin soğukluğu 

Her defasında 

İçim kanıyor 

Bir koysan kendini 

Benim yerime 

Utanırdın tek kelime etmeye 

Öyle sessiz, öyle sakin 

Sevmiştim seni 

Her defasında 

Gök kubbe gibi düşüyorsun 

Üstüme...', 'Her defasında  Yumruk gibi iniyor göğsüme  Sözlerin  Hep o yalnızlığı çağrıştırıyor  İliklerime kadar işliyor  Gecenin soğukluğu  Her defası...', ARRAY['Türk Edebiyatı','Şiir','Tijen Karabina']::text[], 8.5, '{"poet":"Tijen Karabina","poet_slug":"tijen-karabina","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/her-defasinda-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Biz Olmadık', 'hic-biz-olmadik-tijen-karabina-609df', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana sen değerlisin 

Bana ben

Bize biz olmadık hiç

Ya hepimiz, ya hiçbirimiz 

Olmalıydı

Ya boşta kalmalıydı 

Ya tam dolmalıydı

Yarım bıraktık hep

Olmadı...', 'Sana sen değerlisin  Bana ben Bize biz olmadık hiç Ya hepimiz, ya hiçbirimiz  Olmalıydı Ya boşta kalmalıydı  Ya tam dolmalıydı Yarım bıraktı...', ARRAY['Türk Edebiyatı','Şiir','Tijen Karabina']::text[], 8.5, '{"poet":"Tijen Karabina","poet_slug":"tijen-karabina","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hic-biz-olmadik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-savas-dincbas-ynqea', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir serüvendir yaşamak

başladın mı bir kez

sonunu getireceksin mutlaka

her adımından zevk alarak

öğrenerek

ve öğretiler bırakarak

yılmadan,usanmadan

tek tek atacaksın adımlarını

öyle sağlam basacaksın ki

senden sonrakilere

seni hatırlatacak ayak izlerin

sakın geriye dönüp bakma

önündeki yol daha çetin

ve daha net

izler bırakmak olsun hedefin...', 'bir serüvendir yaşamak başladın mı bir kez sonunu getireceksin mutlaka her adımından zevk alarak öğrenerek ve öğretiler bırakarak yılmadan,u...', ARRAY['Türk Edebiyatı','Şiir','Savaş Dinçbaş']::text[], 8.5, '{"poet":"Savaş Dinçbaş","poet_slug":"savas-dincbas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yasamak-174-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüyorum Sensizlikde', 'oluyorum-sensizlikde-i-lknur-cekici-22olq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerim saatte

Aklım telefonda

Bekliyorum umudu yaşamayı

Karanlıklardan aydınlığa giden yola

Seninle ulaşmayı

Saniyeler tükeniyor ceplerimde

Zaman akıyor yüreğimde

Herşey sönüyor sensizlikle

Yılların özlemi çöküyor üzerime

Fısıldaşıyor gökyüzü

Yıldızlar eteğimde

Birde hasretin karası

Doğuyor gözlerime

Boğuluyorum bilmiyorsun

Ölüyorum sensizlikde

Saçlarıma dolanıyor

Gölgeler gecelerde', 'Gözlerim saatte Aklım telefonda Bekliyorum umudu yaşamayı Karanlıklardan aydınlığa giden yola Seninle ulaşmayı Saniyeler tükeniyor ceplerimd...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/oluyorum-sensizlikde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şükür', 'sukur-abdullah-odabas-j0k2q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalbimiz kan ağlar nemlidir gözler,     	

Kudret güneşine dayanmaz buzlar,        	

Gün gelip gülecek kederli yüzler,       	

Bu günkü fırsatı verene şükür.          	

Bu günler, yarınlar, mutlu gelecek,     	

İmanı olanlar anı görecek,              		

Münkirler hakikat nedir bilecek,         	

Bu günkü fırsatı verene şükür.          	

İman güneşini balçık sıvamaz,

Kalbi kara olan Hakkı duyamaz,

Üçleri beşleri birbir sayamaz,

Bu günkü fırsatı verene şükür.

İman ile İslam öz amalimiz,

İmansızla yoktur kıylü kalimiz,

Her seher yazılır arzu halimiz,

Bu günkü fırsatı verene şükür.

Gam çekme Meftuni keder taşıma,

İçteki dertleri dökme dışına,

Dünya dar olacak münkir başına,

Bu günkü fırsatı verene şükür.', 'Kalbimiz kan ağlar nemlidir gözler,     	 Kudret güneşine dayanmaz buzlar,        	 Gün gelip gülecek kederli yüzler,       	 Bu günkü fırsa...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sukur-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sıkılıyorum*', 'sikiliyorum-gulcan-sakal-4t223', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sıkılıyorum...

Senin olmadığın her yerde sıkılıyorum

Sıkıldığım yerde yarım kalıyorum

Ben olamıyorum! 

Senin olmadığın yerde 

Bende yokum.

Beden bir hiçse...

Burda durma git diyor yüreğim

Beklemek niye? ? ? 

Ne kaldı ömürde yaşanacak

Bu anları yaşayamadıktan sonra

Suç bendemi bilmiyorum

Ama...

Sevmiyorum! ! ! Bu sayfayı sevemiyorum', 'Sıkılıyorum... Senin olmadığın her yerde sıkılıyorum Sıkıldığım yerde yarım kalıyorum Ben olamıyorum!  Senin olmadığın yerde  Bende yokum. B...', ARRAY['Türk Edebiyatı','Şiir','Gülcan Sakal']::text[], 8.5, '{"poet":"Gülcan Sakal","poet_slug":"gulcan-sakal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sikiliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teşekkürname', 'tesekkurname-abdullah-odabas-qqvd2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey hocam, vasfına olmuşam hayran,       	

Kapında kul olam yolunda kurban,        	

Cami-i Ümmide eyledim devran,           	

Teşekkür eylerem, sağol efendim.        	

Karada, denizde nasihat ettin,          	

Kazandın cevheri yerinde sattın,        	

Bağ-ı Firdevside makamın tuttun,        	

Teşekkür eylerem, sağol efendim.        	

Beytullah önünde eğdin başını,          	

Akıttın gözünden kanlı yaşını,          	

Bus eyledin hemen Hacer Taşını,         	

Teşekkür eylerem, sağol efendim.        	

Arafat dağında Vakfeye durdun,          	

Cüşedip deryanın dibine daldın,         	

Va''z-ı nasihatle ciğerler deldin,       	

Teşekkür eylerem, sağol efendim.        	

Taşladın şeytanı kestin kurbanı,        	

Tavaftan sonraysa açtın ihramı,         	

Elveda çağırdın Beytül Haramı,          	

Teşekkür eylerem, sağol efendim.        	

İçine düştü aşk-ı Medine,

Doyulur mu visalinin tadına,

Şefaat vacip oraya gidene,

Teşekkür eylerem, sağol efendim.

Huzur-ı Resulde eyledin zarı,

Yanında beraber hem cariyari,

Sarfettin orada olanca varı,

Teşekkür eylerem, sağol efendim.

Kalkınca vaaza titredi yerler,

Arap uleması yerinde terler,

Coştu bir derya sanki gök gürler,

Teşekkür eylerem, sağol efendim.

Türkistan namını eyledin ali,

Herkese gösterdin o doğru yolu,

İki cihanda görme müşkil suali,

Teşekkür eylerem, sağol efendim.

Hak razı olsun Peygamber şefi,

Cennette makamın eylesin terfi,

Dokunur dar günde bize de nef-i

Teşekkür eylerem, sağol efendim.

Meftuni, sen eyle Halika şükran,

Bulunur cihanda böyle bir burhan,

Olmazsa alimler halimiz yaman,

Teşekkür eylerem, sağol efendim.', 'Ey hocam, vasfına olmuşam hayran,       	 Kapında kul olam yolunda kurban,        	 Cami-i Ümmide eyledim devran,           	 Teşekkür eyler...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/tesekkurname-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar..', 'yillar-nurdane-diken-rndz9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senden hesap soruyorum 

Ne yaptın, benim için. 

Ben senin için, 

Mücadele ederken, 

Sen yaptıklarımı yıktın. 

Hayat yolunda, 

Sevdiğimi elimden aldın. 

Hayallerimi yıktın

Çaldığını bana geri ver! 

Daha yaşamadıklarım var. 

Bilsen, ne hayallerim var. 

Yıllarımı geri ver! 

Sana hesap soruyorum. 

Ben şimdi ne olacağım? 

Yeniden nasıl başlayacağım? 

Çizgiler yüzümde, derinleşmişken. 

Ruhumun gençliğini, 

Nasıl anlatacağım. 

Acımasızca ezdin, beni. 

Söylesene, mutlu musun? 

Sen, doymaz bir canavarsın. 

Mutluluğa bir adım kaldı. 

Onu bana ver. 

Ey! yıllar 

Bana sevdiğimi ver....... 

(09.01.1999-00.30-Aydın)', 'Senden hesap soruyorum  Ne yaptın, benim için.  Ben senin için,  Mücadele ederken,  Sen yaptıklarımı yıktın.  Hayat yolunda,  Sevdiğimi elim...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yillar-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tapındım Gözlerine', 'tapindim-gozlerine-serdar-erdemir-ttat7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yalnızlığın süzgecinde

utangaç bir gece

gözlerin; 

gökyüzü maviliğinde

Tanrıya taptım gözlerinde! 

bir avuç topraktın ellerimde

kokunu; 

çektim ta ciğerlerime

mum alevi sıcaklığında

gözlerimi

gözlerinin renginde yaktım

yakamoz serinliğinde

utangaç bir gece

gökyüzü maviliğinde

gözlerini

düş sokaklarında aradım

yalnızdım yapayanlız

efkârlı mı efkârlı

kadeh kadeh gözlerinden

mavilikler yudumladım

doymadım mavice

doymadım gözlerine

gökyüzü maviliğinde

Tanrıya taptım gözlerinde! 

eski bir mabetti

sanki gözlerin

dayanamadım 

bağışla 

bağışla nolur

tutamadım kendimi 

gecenin son deminde

günahkâr bir kul gibi 

tapındım gözlerine!', 'yalnızlığın süzgecinde utangaç bir gece gözlerin;  gökyüzü maviliğinde Tanrıya taptım gözlerinde!  bir avuç topraktın ellerimde kokunu;  çek...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/tapindim-gozlerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmekle Bitmiyor Sevda', 'gitmekle-bitmiyor-sevda-tunahan-ermihan-4lyae', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yazılmış tüm sözlerin şiirlerin hikayelerin ötesinden

Sana haykırmak istediklerim vardı

Senin asla bilemediğin hayata yenik düşmüş

Çok istedim sana her seferinde anlatmayı

Ama öyle dolambaçlı yolların ardına saklı kalmıştı ki sevdan

Ne sözlerim yetişti ömrüne

Ne kelimelerim varabildi gönlüne

Bütün bu yaşanmış yalanların ardından

İçerimde ağlayan

Bedenimde kanayan

Özümde azap çeken bir sen hala var

Her nerede ne halt ediyorsan bil

“ Gitmekle bitmiyor sevda ”', 'Yazılmış tüm sözlerin şiirlerin hikayelerin ötesinden Sana haykırmak istediklerim vardı Senin asla bilemediğin hayata yenik düşmüş Çok isted...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gitmekle-bitmiyor-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yedi Bitirdi...', 'yedi-bitirdi-nurdane-diken-yje5p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Deli gönül, neyi istemedi ki? 

Neyi arzu ederek, ummadı ki? 

Her çiçeğe el uzattı, kokladı. 

Her gülden bir har aldı, usanmadı. 

Elinde olan gülle, yetinmedi, 

Arkasındaki gülü merak etti. 

Hep herşeyi merak etti, istedi 

Bir türlü doymak nedir, bilemedi. 

Sevda yollarında tükendi, bitti. 

Yine de aramaktan bıkmadı. 

Her duyguyu doyasıya, yaşadı. 

Yine de bunlarla yetinemedi. 

Aşkın içinde eridi, tükendi. 

Her seferinde yeniden, dirildi. 

Bir bedeni heder etti, yok etti. 

Yokuşlarda nefessizce bıraktı. 

Yine de doymadı, doymadı gitti. 

Bir ömrü böylece, yedi bitirdi.....', 'Deli gönül, neyi istemedi ki?  Neyi arzu ederek, ummadı ki?  Her çiçeğe el uzattı, kokladı.  Her gülden bir har aldı, usanmadı.  Elinde olan...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yedi-bitirdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayan Ölü...', 'yasayan-olu-nurdane-diken-gour7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Belki! bir gün döneceksin 

Herkese beni soracaksın 

-Nerede o? diye sorduğun zaman 

-Öldü! diyecekler 

Bir esmer uğruna 

Kahrından, çektiği ıstıraptan 

Onun hasretinden öldü 

Diyecekler sana. 

Yana, yakıla beni arayacaksın 

Gözlerinde hatıralarımız canlanacak

Öldüğüme inanmayacaksın 

Üzülme yavrum! ağlama değmez

Ölen öldü, giden gitti, bir kere. 

Bir daha geri dönmeyecek 

Onun da bir kalbi vardı, ufacık

Nereden bilecekti 

Onu birgün sana kaptıracağını 

Hasretine fazla dayanamayacak 

Birgün ansızın, duruverecekti. 

Ve sen onun, 

Senin uğruna öldüğünü, 

Çok geç anlayacaksın! .... 

(12.8.1980)', 'Belki! bir gün döneceksin  Herkese beni soracaksın  -Nerede o? diye sorduğun zaman  -Öldü! diyecekler  Bir esmer uğruna  Kahrından, çektiği ...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yasayan-olu-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayan Kim? ...', 'yasayan-kim-nurdane-diken-v80kh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu ışık sönmez 

Bu Vatan gitmez 

Bizler dururken 

Evlâtlar ölmez. 

Haydi! durmayın öyle! 

Atama deyin hele! 

Çanakkale hiç durmaz 

Türk''e bu yol hiç tutmaz. 

Türk''leri hiç sevmemiş, 

Ekmeğiyle büyümüş 

Bayrağını sevmemiş 

Nesepsizce yetişmiş. 

Din, iman kalkanı olmuş 

Attıkça atmış, coşmuş 

Garip halkı kandırmış 

Taptığı para olmuş. 

AB''nin kulu olmuş 

Topraklarını satmış 

Tarihe çalım atmış 

Bu yol ona yakışmış 

Köylüsünü darıltmış 

Esnafını batırmış 

Yasaları kaldırmış

Azınlığı yaratmış. 

Evliyalar, şehitler, 

Uyanın demiş, yeter 

Ölümüsünüz sizler? 

Yaşayan, bizler miyiz? .......', 'Bu ışık sönmez  Bu Vatan gitmez  Bizler dururken  Evlâtlar ölmez.  Haydi! durmayın öyle!  Atama deyin hele!  Çanakkale hiç durmaz  Türk''e bu...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yasayan-kim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan....1', 'yalan-1-nurdane-diken-mkxyb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalan dünyaya geldiğim, yaşadığım 

Senin gibi....... 

Yalan yediğim, içtiğim 

Seni gördüğüm gibi... 

Yalan mevsimlerin değiştiği 

Bakışın gibi... 

Yalan evrendeki canlılık 

Ellerin gibi.... 

Yalan sonbaharda döküldüğü, yaprakların. 

Gözyaşların gibi.... 

Yalan esen rüzgardaki 

Saçların gibi.... 

Yalan sensiz yaşadığım 

İsmin gibi.... 

Yalan aynı evrende olduğumuz 

Kalbimdeki sen gibi.... 

Yalan dünyadaki tüm kadınlık 

Erkeklik gibi.... 

Yalan bunların hepsi yalan 

Sen ve Ben gibi........', 'Yalan dünyaya geldiğim, yaşadığım  Senin gibi.......  Yalan yediğim, içtiğim  Seni gördüğüm gibi...  Yalan mevsimlerin değiştiği  Bakışın gi...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalan-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatandaşın çagrısı', 'vatandasin-cagrisi-zeynep-aydinlioglu-cishy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bagırıyor birisi 

kendisi bile duymaz sesini 

belliki, doldurmuş testisini 

arada yol şov yapar deniz efendi 

ne isterki... oturdugu yerden 

yapıştımı kalkmaz koltuktan 

saçı  sırma...dişleri mercandan 

arada bir gürler deniz efendi 

zevklıdir...en nadide yeleri seçer 

işine gelmezsse... tebessüm eder geçer 

iltifat olunca, herkesi sever 

arada bir mılleti korur deniz efendi 

gücendik  biz  çol çocuk hepmiz 

çoğaldıkça çogalıyor kederimiz 

sag sol yapmaktan yoruldu beynimiz 

hayretler içindeyiz deniz efendi 

kale dedğimiz... yerlerde yok oldu 

cesur olanlarda yanında savruldu 

güneş batıyor...bak gün bitti 

ikindiye yetiş barı deniz efendi 

zeynep AYDINLIOGLU 

07.11.2005', 'bagırıyor birisi  kendisi bile duymaz sesini  belliki, doldurmuş testisini  arada yol şov yapar deniz efendi  ne isterki... oturdugu yerden ...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Aydınlıoğlu']::text[], 8.5, '{"poet":"Zeynep Aydınlıoğlu","poet_slug":"zeynep-aydinlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/vatandasin-cagrisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşluk', 'hosluk-mehmet-ayhan-gunaydin-1ej18', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'HOŞLUK

Bir hoşum şu son günlerde

Yüreğim kıpır kıpır.

Doğan her güne,

Ve 

Her şeye

Sevgi beslemekteyim.

Mevsim kış.

Ama ben

Bahar başlangıcında gibiyim.

Ne dersin.

M. Ayhan Günaydın.

     21 Aralık 2004

        Ankara', 'HOŞLUK Bir hoşum şu son günlerde Yüreğim kıpır kıpır. Doğan her güne, Ve  Her şeye Sevgi beslemekteyim. Mevsim kış. Ama ben Bahar başlangıcı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hosluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamadığım', 'anlatamadigim-serdar-erdemir-f92yu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'alışmışım sana 

tütüne alıştığım gibi; 

içmeden duramam.

ben vurgunum sana

dava aşkım gibi; 

hasretine dayanamam.

sen benim Ana sevgim

asla paylaşamam.

sen, sen gençlik yaşım

ilk göz ağrımsın,

tuhaftır unutamam.

sen alışkanlığım

sen paylaşılmazım

ilk göz ağrımsın

sen benim

             sen benim

anlatamadığımsın', 'alışmışım sana  tütüne alıştığım gibi;  içmeden duramam. ben vurgunum sana dava aşkım gibi;  hasretine dayanamam. sen benim Ana sevgim asla ...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/anlatamadigim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük Sınırlar Koymaktır Bazen', 'ozgurluk-sinirlar-koymaktir-bazen-guzin-eye-dundar-6sxra', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Özgürlük sınırlar

..........................koymaktır bazen

sınırları kaldırmak

...........................yeterince

solumak payına düşen 

...........................mutluluğu

ayağa kalkabilmek 

...............................düşünce

kucaklamaktır sevgileri

seçme şansını kullanmak 

..............................biteviye

bir insanlık hakkını

........................tutmak elinde

bırakmak sınırların olduğu yerde

dostça kardeşçe yaşamak

paylaşımı dengelemek

.................................kardeşçe

hakkın hukuk un olmadığı yerde

savaşmaktır özgürlük.', 'Özgürlük sınırlar ..........................koymaktır bazen sınırları kaldırmak ...........................yeterince solumak payına düşen  ....', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ozgurluk-sinirlar-koymaktir-bazen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teraziye Ayna Yalan Söyledi', 'teraziye-ayna-yalan-soyledi-orkun-isik-9udkm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni inliyorken gecenin sedasına, 

İçime kanayan gözyaşı sağanağımda ıslanıyordun, 

İnadına olacak ya! 

bilmiyordun hep damlıyordun…

A/sırlar gibi ben oluyordu yanağıma konan bu/sen,

Kurumuyordu güneşe inat ummanlarca halâ ıslak

Gözlerin bir büyü/y/ordu tutunmalarıma, 

parlak mı parlak…

Hani vardı ya!  dili olmayan özleyişlerim 

Soğuk mu soğuk şimdi vicdan denen sıratın ipinde

Bir bir düşüm de artık  kar/ar/lar, yokluk  tipinde…

Sana uzayan yollar pranga oluyordu ayaklarıma

Yürü yürü bitmiyordu toprak denen sürgünlüğüm.

Gözlerimin önünde dikiliyordu idam önlüğüm…

Ve kurtuluyordu adamın artık kurulan celseleri

Bir ömür mahkum oluyordu, soruyordu! ..

Nefesten alnına vurulan buseleri…

Karartma gecelerde B/asılıyordu bir adam

P/uslu bir rüya sabahında,

Hep sürgün düştü içine her çağında…

Bilirim, göçerken senin gözlerinden 

Ölmeyecektim,  bakışların olacaktı duaların

Toprağım kurumayacaktı, 

ıslatacaktı ağlayışların … 

Şimdi gidiyorum vaktidir ey sevgili! 

Düşlerin, öpüşlerin ve gülüşlerin 

Kapanıyor gözlerim, başlıyor ölüşlerin …

______Ayna Teraziye Yalan Söyler mi ki? ..._________________', 'Seni inliyorken gecenin sedasına,  İçime kanayan gözyaşı sağanağımda ıslanıyordun,  İnadına olacak ya!  bilmiyordun hep damlıyordun… A/sırla...', ARRAY['Türk Edebiyatı','Şiir','Orkun Işık']::text[], 8.5, '{"poet":"Orkun Işık","poet_slug":"orkun-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/teraziye-ayna-yalan-soyledi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Dair', 'aska-dair-mehmet-kemal-tumac-d94eu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'aşka dair ne söylense

dudakların gelir aklıma

her aşk hikayesini

seninle yaşarım

hep seni anımsarım kavuşamayan

sevgililer masalında

oysa kadınım hep yanımdasın...

hep uzaktasın.', 'aşka dair ne söylense dudakların gelir aklıma her aşk hikayesini seninle yaşarım hep seni anımsarım kavuşamayan sevgililer masalında oysa ka...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kemal Tumaç']::text[], 8.5, '{"poet":"Mehmet Kemal Tumaç","poet_slug":"mehmet-kemal-tumac","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aska-dair-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmen', 'ogretmen-ayhan-gulsoy-dekv2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Babama

Düşerken ekimde

Buğday yere

Suladın sevgi çeşmesinden

Uzanıp aldığın dalı

Öptün kokladın

Bilmezken anası babası

Büyüdü boy saldı

Çiçek açtı dalın

Taşlasa da kapını

Bir haylaz öğrenci

Öpüp yanağını usulca

Sevgiyi öğrettin

İçinde dar bir tünelin

Kaldın kimi zaman

Yapayalnız zifiri karanlıkta

Cesareti öğrettin

İki kere iki

Ne ki

Hayatı öğrettin', 'Babama Düşerken ekimde Buğday yere Suladın sevgi çeşmesinden Uzanıp aldığın dalı Öptün kokladın Bilmezken anası babası Büyüdü boy saldı Çiçe...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Gülsoy']::text[], 8.5, '{"poet":"Ayhan Gülsoy","poet_slug":"ayhan-gulsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ogretmen-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba', 'baba-mehmet-pamuk-s2ncu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(ölümünün onuncu yıldönümünde babama) 

ben geldim,

arada onca zaman

onca hasret kıvılcımı varken...

hani baba tadında sevemediğin oğul

ellerinin şefkatini

saçlarımdan kıskandığım adamım ben.

ne çok susmuşuz birbirimize

beni duyduğunu biliyorum şimdi,

nerden bilirdik ki

baba-oğul en uzun konuşmamızı

burada; 

bedenine taş diktiğin mezarda

ve onca zaman sonra yapacağımızı...

oysa beni ne kadar sevdiğini biliyorum

biliyorum ki:

ben senden düşmüş bir damlayım...

şimdi şimdi anlıyorum seni:

o büyük sevdaya 

nasılda kıymışlar,

annemden önceki kadın ve sana

kırık sevdalardan öğrendim baba.

sonrası,

kendine yaptığın zulümlerin kataloğu,

hiçbir resim albümünde yok bunlar

benim içimde sergileniyorlar

ben görüyorum baba.

düşünüyorum da,

benim annem,

senin sevdiğin kadın olsaydı eğer

bir babam

bir annem

ve mtlu bir çocuk olurdu

bunu da biliyorum baba

üzme kendini artık...

kendi emeğinle yaptığın herşeyi

hani o,mahir marangoz ellerinden çıkardığın

tüm maddi ve manevi eserleri

nasıl bir sevda öfkesinde

ve tek bir yumrukta dağıttığını anlıyorum.

sen ki civan,

o delikanlı adam

şişelerin yalpalı adımlarına esir ettin kendini

nasıl da yalnız başına bir ölümü seçtiğini

mezarını kaplayan çalılarda görüyorum...

ben geldim,

sana benzememek için verdiğim uğraşlarımın hebasıyla

bende yalnızlığı seçtim baba.

sadece şiirlerle ve

iki satır arası boşluklara yaşayabiliyorum artık.

bak tüm çalıları temizliyorum

senin sevdana yakışır,apak bir mezar

ellerim yırtıldı,

bak hasretim damlıyor mezarına

onu kokla baba

senin kanın gibi kan,beni anla baba...

kendini kimseye anlatmadın

onun içindir ki 

hep yadırgandın

ve gittikçe

daha da uzaklaştın...

belki paralel bir kaderde

o sevdiğin kadın; 

senin sevgini yaşıyordur hala

bilemem,

belki onun da mezarında,bir evlat ağlıyordur

bilemem...

işte bu adam

mezarına sığmayan bu babayiğit

kendi sevdasında,

kendini müebbete veren bu mahkum

bu namus bekçisi ellerin sahibi

ayaklarını; içinden başka bir yola vurmayan

öfke değil aslında,

hep yüreğine doğru ağlayan

bu sessiz mezardaki adam

BENİM BABAM

ellerim duada,gözlerim yaş

öpüyorum; 

ellerin niyetine

bir avuç toprağını,

seni seviyorum baba...

oğlun Mehmet...

(amasra-2004)', '(ölümünün onuncu yıldönümünde babama)  ben geldim, arada onca zaman onca hasret kıvılcımı varken... hani baba tadında sevemediğin oğul eller...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Pamuk']::text[], 8.5, '{"poet":"Mehmet Pamuk","poet_slug":"mehmet-pamuk","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/baba-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu gece', 'bu-gece-okan-nar-sjn06', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir başkayım be ceylan bakışlım bu gece.! 

Hasretin çöktü yine her bir yana. 

Sensizlik,tıpkı ölüm  gibi bu gece.

Mızraptan çıkan her bir melodi,

Yüreğime saplanır hançer gibi bu gece. 

Hem çok yakınsın,hemde çok uzak bana. 

Tüm istek parçaları,sadece senin için bu gece.! 

Tüm  mezarlar ise,sadece benim için bu gece.!', 'Bir başkayım be ceylan bakışlım bu gece.!  Hasretin çöktü yine her bir yana.  Sensizlik,tıpkı ölüm  gibi bu gece. Mızraptan çıkan her bir me...', ARRAY['Türk Edebiyatı','Şiir','Okan Nar']::text[], 8.5, '{"poet":"Okan Nar","poet_slug":"okan-nar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bu-gece-167-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dörtlük de Sen Yaz / BU BAYRAMDA', 'bir-dortluk-de-sen-yaz-bu-bayramda-siir-perisi-grubu-jiau2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/BU BAYRAMDA'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun ŞİİR PERİSİ GRUBU yetkili şairlik sayfasında yayınlanmasına izin vermiş sayılmaktadır. Kendi dörtlüğü dışında, şiirin bir kısmını yada tamamını sayfasında yayınlamak isteyen şairler, diğerlerinden izin almak zorundadır...(Yasal Uyarı) 

Kokusu gül kokuyor, bakın esen yeline 

O gülün kokusunu SÜRELİM bu bayramda. 

Hak yoluna gidenin, gül verirler eline 

O kapıdan içeri GİRELİM bu bayramda.....................(Ayak Dörtlüğü)   

1. 

Lâf ile bırakmadık, dinimizi kimseye 

Herkesi sardıracak, o beyaz elbiseye 

Hazır fırsat var iken, dokunalım keseye 

Hayır, hasanatını VERELİM bu bayramda..................Tuncay Akdeniz 

2. 

Fitreler, sadakalar, düşkünlerle buluşsun 

Yetimler giydirilip, nur yüzleri gülüşsün 

Şevkat ve merhamete, tüm insanlık alışsın 

İçten yardımlaşmayı GÖRELİM bu bayramda................Turan Orak 

3. 

Boynu bükük olanın kapısında duralım, 

Buruk bakışlarına mutluluğu kuralım, 

Dudağa tebessümü mühür gibi vuralım, 

Hasret kalan elleri SARALIM bu bayramda.................Feride Özmat 

4. 

Biliyorum hep beni, düşlerinde aradın 

Sende bil ki ey kadın, gözlerim de ar adın 

Sen Bakarım zamana, yüreğime yar_adın 

Haydi, Aşkın Sırrına Erelim Bu Bayramda.......….........ORKUN IŞIK 

5. 

Küsülüler barışır kucaklar birbirini, 

Atarlar kör kenara kin nefret zehirini, 

Bakın içten gülüyor gör gözlerin rengini. 

Sevginin şerbetini DERELİM bu bayramda..................İsmail Doğan 

6. 

Bayramlarda ellerim sıkacak el arıyor 

Dostlarımın gönlünde bakacak hal arıyor 

Şu mübarek günlerde tutacak dal arıyor 

Dost bağından gülleri DERELİM bu bayramda................Mehmet TEKECİ 

7. 

Mübarek Ramazan''ın farkına varmış mıyız? 

Günahkar ruhumuza, ruhundan almış mıyız? 

Kalbimize imanın nurunu sarmış mıyız? 

Nefsimizle bir hesap GÖRELİM bu bayramda..................İbrahim Usta 

8. 

Bayramı bayram yapan değerleri görmeli 

Öksüzün ve yetimin hakkını hep vermeli 

Yaşasınlar tadını onlara göstermeli 

Gariblerin yanına VARALIM bu bayramda.....................Sevil Nizamoğulları 

9. 

Sen yoktun ki yanımda bayram gelmiş bana ne 

Arandım İstanbul''da yalnızlığa bahane 

Gözlerin üzerimde bakmadım hiç bir yöne 

İstemiştim yanıma GELESİN bu bayramda.....................M.Yaltı 

10. 

Dostun dosta olamaz ne garezi ne kastı, 

İnsan nasıl yaşar ki olmaz ise hiç dostu? 

Kaldıralım yerinden, serilen eski postu, 

Tertemiz gönülleri SERELİM bu bayramda....................Mustafa Erkenekli 

11. 

Boyun eğmek ne demek, şeref ile şan varken! 

''Gel sen de gül'' diyorlar, ölümden nişan varken 

Nasıl bayram yapılır, bunca perişan varken 

Şu nefsin defterini DÜRELİM bu bayramda...................Zülfikar Yapar Kaleli 

12. 

Hepsi birer aslandı, hepsi birer er''diler 

Hepsi de şu toprağa, çok zamansız girdiler 

Onlar, bu VATAN için canlarını verdiler 

Onların hatırını SORALIM bu bayramda.......................Saim Bastık 

13. 

Kovalım gitsin artık yergiyi ve yargıyı 

Sokmayalım akıla endişeyi kaygıyı 

Kalplere serpilecek sevgiyi ve saygıyı 

Gönül dantelamıza ÖRELİM bu bayramda........................Ali IŞIK 

14. 

Bayram sabahı çıktım camiden eve doğru 

Yürürken canı tuttu, çekilmedik bir ağrı 

Zulümden yanar bunca mağdur insanın bağrı, 

Sebep ne kafa gönül YORALIM bu bayramda....................Hasan ULUSOY 

15. 

İnsanlar birbirini, incitiyor üzüyor, 

Güçlü olan mazlumu,zevki için eziyor, 

Dostu dosta düşürüp, araları bozuyor, 

Şeytanı aramızdan, SÜRELİM bu bayramda.....................K.Tahir ÖZCAN 

16. 

Analar camda bekler, babalar hasret çeker. 

Akşam bir gonca iken, sabah gözyaşı döker. 

Uzatsan ellerini hasret dağlara seker. 

Gelsem de sen yoksun ki, GÜLELİM bu bayramda..............Suna Doğanay 

17. 

Hepimiz bir şekilde, birşeylere esiriz 

Ya ruhlarımız tutsak, ya da özden veririz 

Mademki özgürlüğe yazılan bir şiiriz 

Esaret zincirini KIRALIM bu bayramda.......................gül_i_zar 

18. 

Siyami Ersek''teki hasta ziyaretimde 

telaş ve hüzün gördüm herkesin gözlerinde 

Bakınınca çevreye hüzün buldum kendimde 

Can tenden ayrılmıştı Gördüğüm bu bayramda...................Metin Yaltı 

19. 

Kimi eşinden ayrı, kimi bakıma muhtaç 

Kimisi güler yüze,kimisi sevgiye aç 

Unutma düşkünleri,şefkât ile kucak aç 

Huzur evi ziyaret, EDELİM bu bayramda......................Berrin CİVGİN 

20. 

Gözlerimiz kapıda, yüreğimiz mevlada 

Gurbette bekliyoruz, ellerimiz duada 

Unutmayın bizleri, gelin her tür havada 

Ana Baba''nızız biz GÜLELİM bu bayramda....................Sevim E.Tezel 

21. 

Bugün kapıdan bakan dün gözlenen bir candı, 

Ak düştü saçlarına gençlik kısa bir andı. 

Arifeye ermeyen her günü aynı sandı, 

Ana baba hatırı SORALIM bu bayramda........................İshak ÖZLÜ 

22. 

''Deliye her gün bayram'' der atalar velâkin, 

Hemen kızma a canım, şöyle oluver sâkin. 

Öyle sevilen ol ki, herkes olsun tiryâkin. 

Gönlü gönle sevdayla SARALIM bu bayramda...................Necmi ÜNSAL 

23. 

Varlık maverasında yokluğun sesi inler 

Merhamet potasında eritilir tüm din''ler 

''Düşenin'' her halinden, yine ''düşenler'' anlar 

Yıkılan Pakistan''ı, KURALIM bu bayramda.....................Dr.Barış DOĞAN', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/BU BAYRAMDA'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun...', ARRAY['Türk Edebiyatı','Şiir','Şiir Perisi Grubu']::text[], 8.5, '{"poet":"Şiir Perisi Grubu","poet_slug":"siir-perisi-grubu","theme":"Türk Şiiri","is_hero":false,"total_lines":120,"source_url":"https://www.antoloji.com/bir-dortluk-de-sen-yaz-bu-bayramda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-serdar-erdemir-e2r4r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ey! sevgili; 

ben seni, bir resmin tuvalinde,

Tanrıkulu’nun şiir dizelerinde; 

eski bir İstanbul  albümünde

siyah - beyaz renksiz bir filmde

karşılıksız sevdim.

ey! sevgili; 

ben seni, Mozartın son bestesinde

Oğuzcan’ın gönül süzgecinde.

Parisin tinsel hareminde

denizlerin dalgasız olduğu bir günde.

habersiz sevdim.

ey! sevgili; 

ben seni, Gülce de, Venedik’te

Nil nehrinin kıyısında, Piramit’te

çağlar öncesinde Babilde, Hititte

tarihin seyirsel gergefinde

harbiden sevdim.

ey! sevgili; 

ben seni, gece - gündüz gözüyle

Harputun şiirsel musikisiyle

bir kuşun titrek yüreğiyle

tapınaklarda ibadet hissiyle

delicesine sevdim.

ben seni; 

sen olduğun için sevdim…', 'ey! sevgili;  ben seni, bir resmin tuvalinde, Tanrıkulu’nun şiir dizelerinde;  eski bir İstanbul  albümünde siyah - beyaz renksiz bir filmde...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sevgiliye-135-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Ezgi', 'son-ezgi-adem-tok-0872y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kavgayla yaşamak

en güzeliydi emeklerimin

soluyanı sevmek

en yücesiydi değerlerimin

son ezgim olsun

kanat çırpışları kelebeklerin

son ezgim olsun

naraları esriklerin

en ilginç anılarım

hapishane anılarımdı

en büyük hayalim

firari olmaktı:

sevdamın koynunda

son ezgim olsun

adanmış ömrümün dost belası

ilknur çehresi

son ezgim olsun

mavi suskunun 

kardelen direnci

                                                (10.11.03) 

                                               f tipi hapishane EDİRNE', 'kavgayla yaşamak en güzeliydi emeklerimin soluyanı sevmek en yücesiydi değerlerimin son ezgim olsun kanat çırpışları kelebeklerin son ezgim ...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/son-ezgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı: Aşk', 'adi-ask-adem-uzun-o8kvt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O ilk bakış

Belki bir nefeslik kadar

Belki daha kısadır

Gözlerinde çok farklı

Bir ışık olmalıdır

O ilk bakış

Belki bir nefeslik kadar 

Belki daha kısa

O ilk bakışın adı var

O ilk bakış

Sıcak bir akşam yeli

Dudaklarını kurutup

Gözlerin nemlenmeli

Birkaç saniye şöyle

Ellerin titremeli

O ilk bakış

Belki bir nefeslik kadar

Belki daha kısa

O ilk bakışın adı var', 'O ilk bakış Belki bir nefeslik kadar Belki daha kısadır Gözlerinde çok farklı Bir ışık olmalıdır O ilk bakış Belki bir nefeslik kadar  Belki...', ARRAY['Türk Edebiyatı','Şiir','Adem Uzun']::text[], 8.5, '{"poet":"Adem Uzun","poet_slug":"adem-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/adi-ask-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçarı Gönül', 'ucari-gonul-omer-arslan-6gbdo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bizi alır gider gönlümüz terkisine

	Bazen sahralara mecnun 

	Ferhat eder dağlara bazen 

	Elimize kazma vererek

	Bazen da denizlere yelken açar

	Hasret limanlarında demirler bazen de

	İşte o zaman zıpkın yemiş balık gibidir

	Bazen denizkızlarıyla konuşur

	Çekik gözlü deniz kızlarına

	Çince sevdiğin söyler

	Bazen kuş olur 

	Göklere kaç kanat çırpar bilinmez

	Direksiz kubbelere şifreli yazılar yazar

	Başıboş uçurma olur bazen de

	Çine ipeğe Hint ‘e kumaşa gider

	Kaybolmuş bir ülkeden yola çıkarak

	Suskun yürek ve dille

	Kendini arar bir yürek buruntusuyla

	Kendinde……………

	Kaç zaman sonra duyar

	Ektiği çiçekleri  dolu vurduğunu

	İçine alçı konulmuş bir vicdanla

	Tüm çiçeklere kahreder

	Ve dahası gül diye ısırgan basar bağrına

	Kaybolur gönlümüzün sesi

	Karanlık rüzgarın kollarında', 'Bizi alır gider gönlümüz terkisine 	Bazen sahralara mecnun  	Ferhat eder dağlara bazen  	Elimize kazma vererek 	Bazen da denizlere yelken aç...', ARRAY['Türk Edebiyatı','Şiir','Ömer Arslan']::text[], 8.5, '{"poet":"Ömer Arslan","poet_slug":"omer-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ucari-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sehbaya Doğru', 'sehbaya-dogru-omer-arslan-7cu9o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tam düşünürken rahatsız edildim

	Bir gürültüyle kendime geldim

	Baktım bir mazlumun kafasını kırıyorlar

	Kalbini söküyorlar

	Duygularını silmek için

	Korktum, ürperdim kendime kızdım

	Sonra topladım cesaretimi

	Ve meydanlara indim

	Yabani güvercin kanadı renginde bulutlara baktım

	Ve zalimlere duygusuzlara 

	Parmak gösterdim

	Buna misilleme olarak

	Paslı kelepçelerini gösterdiler 

	Sevda düşmanları,bana

	Kol gezdi üstümde korkular

	Kortum açıkçası

	Ve çareyi ayaklarım buldu

	Sonra yuhaladım kendimi

	Yüreğimin diplerine dindim

	Bir gül yaprağı buldum oracıkta

	Yine topladım tüm cesaretimi

	İndim meydanlara

	Aşk düşmanlarıyla hesaplaşmaya

	Tek başımaydım

	Mağlup oldum ve yakalandı	

	Umutlarımı,sevdalarımı,geçliğimi

	Mitralyözle taradılar 

	Küf kokan mahzenler oldu yerim

	Bilmem kaç asır çile doldurdum

	Tırnaklarımla yazdım taş duvarlara

	Sevdamızı

	Ve kaç zaman sonra  kapının paslı kilidi açıldı

	Anladım yol görünmüştü bana 

	Yürü dediler yürüdüm başım dimdik

	Bir bulut  beni selamladı 

	Zannedersem arkamdan bitek o ağladı', 'Tam düşünürken rahatsız edildim 	Bir gürültüyle kendime geldim 	Baktım bir mazlumun kafasını kırıyorlar 	Kalbini söküyorlar 	Duygularını sil...', ARRAY['Türk Edebiyatı','Şiir','Ömer Arslan']::text[], 8.5, '{"poet":"Ömer Arslan","poet_slug":"omer-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sehbaya-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-omer-kucukkaya-wn9xi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmurun düştüğü gülsün sen; 

güneşin üzerine titrediği goncasın..

sen bir kelebeksin sadece bir gün yaşabilecek olan; 

ve tanrının üzerine dünyadaki tüm sevgi renklerini koyduğu 

bir gökkuşağısın sen…

adına kimileri umut derken senin

sen; toprağa düşen yağmurlarla beslenen 

ve her soldurulduğunda tekrar yeşeren

bir ekinsin…

adı umut olan! ...', 'Yağmurun düştüğü gülsün sen;  güneşin üzerine titrediği goncasın.. sen bir kelebeksin sadece bir gün yaşabilecek olan;  ve tanrının üzerine ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Küçükkaya']::text[], 8.5, '{"poet":"Ömer Küçükkaya","poet_slug":"omer-kucukkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/umut-215-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizsiz', 'denizsiz-ayhan-gulsoy-77076', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Bir of çeksem karşıki dağlar yıkılır''

Bunu ben mi söyledim

Ağır bir ter bunaltısında

Üşüyen yüreğim mi, ellerim dondu

Sıcak bir ağustosun deniz sularında

Zaman o bildik sessizliği içinde

Kaç deniz süremi yalnız bıraktı beni

Su sattım yol üstlerinde karpuz sergiledim

El salladım taşıtlara kimse görmedi

Hiç gezindim mi ben, deniz inciten

Kılıçlı yalıların çiçeksiz bahçelerinde

Kim aldı buzlu içkileri, kim içti

Kanlı şarabı titrek ellerden

İçmek ve almak üstelik

Bunca uzakken birbirlerine

Hey delikanlım sen içtin içkileri

Onlarsa aldı, işte anlaşamayan

Dil aranızdaki

Yalı çocukları ince uzun dal gibi

Su üstünde kalırlarmış elin yalancısıyım

Hangi dul göleklerde kir tuttu sırtım

Vallahi unuttum yurdumun yabancısıyım

Tuzlu su denizde değil alnımda benim

İner kaşlarım arasından sabahtan akşama

Uzanmışlar kuma yanmışlar benim gibi

Bir farkla, gün değil gön karası benimki

Uzatma sözü delikanlım hadi çağır

Yoksul çaylara gelsinler yosunlu göleklere

Görsünler denize nasıl girilir', '''Bir of çeksem karşıki dağlar yıkılır'' Bunu ben mi söyledim Ağır bir ter bunaltısında Üşüyen yüreğim mi, ellerim dondu Sıcak bir ağustosun d...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Gülsoy']::text[], 8.5, '{"poet":"Ayhan Gülsoy","poet_slug":"ayhan-gulsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/denizsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöz Tanrısal Dilini Bulutlarla', 'coz-tanrisal-dilini-bulutlarla-guzin-eye-dundar-2psgh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaprakları okşayan 

rüzgara fısıldadım

çöz Tanrısal dilini 

..............................bulutlara

fısılda gizemini atlasın

tek armağanı doğaya 

nasıl ihanet etti insan

titresin yürekler 

......................tepeden tırnağa

zamansız kadere 

döndü kuraklık

yandı toprak

haykırdı  orman

.................çok az  kaldı hasata

yanık yüzler ölgün  bakışlar

unutuldu denize koşan ırmaklar

çekildi küskün kaynağa

.................   yanmakta toprak 

yakıcı soluk dönüştü yokluğa

yaşanmış  o laneti  anlat

çok bilinen  ve unutulan

çöz Tanrısal dilini doruklarda...', 'Yaprakları okşayan  rüzgara fısıldadım çöz Tanrısal dilini  ..............................bulutlara fısılda gizemini atlasın tek armağanı do...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/coz-tanrisal-dilini-bulutlarla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutur San', 'unutur-san-gulsum-tanriverdi-im6ry', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mesafeler uzatıp araya, yürek aşkı unutur san.

Ne vazgeçer doğmaktan güneş, 

Ne kaynakta kurur sular.

Yalnızca bir yürek susar, sen beni unutursan.

İst. 16.Kasım.2005', 'Mesafeler uzatıp araya, yürek aşkı unutur san. Ne vazgeçer doğmaktan güneş,  Ne kaynakta kurur sular. Yalnızca bir yürek susar, sen beni unu...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Tanrıverdi']::text[], 8.5, '{"poet":"Gülsüm Tanrıverdi","poet_slug":"gulsum-tanriverdi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/unutur-san-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğamızı koruyalım', 'dogamizi-koruyalim-zeynep-aydinlioglu-llc62', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'doğamızı koruyalım 

bana doğayı anlatabilir misin? 

üzerine basılan çiçeğin çığlığını 

tepesi yok olan ağacın feryadını 

anlatabilir misin? 

bana yok olan ağaçları anlatabilir misin? 

işte dalgınlığım bu sebeptendir 

ormandaki balta sesleri acıtır yüregimi 

kıyımın nedenini anlatabilir misin? 

bana yeşilin ve gırinin fakını anlatabilir misin? 

dizilen parke taşları gibi keyifli degilim 

üzüntüm tek taraflı yeşil kalan ırmak içindir 

yaban ördekleri sığınmasız kalmış,nedendir? 

anlatabilir misin? 

çigdem çiçekleri çiğ düşmüş ğonca güller 

türkbelenının,parfüm kokulu ormanı 

acaba hedeftemi? 

kozalak ve tırtıl manzaralı ormanı 

koruyacagına söz verebilir misin? 

08.08.2001', 'doğamızı koruyalım  bana doğayı anlatabilir misin?  üzerine basılan çiçeğin çığlığını  tepesi yok olan ağacın feryadını  anlatabilir misin? ...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Aydınlıoğlu']::text[], 8.5, '{"poet":"Zeynep Aydınlıoğlu","poet_slug":"zeynep-aydinlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dogamizi-koruyalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter ki', 'yeter-ki-omer-arslan-vghgc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bütün defterlerinden sil  adımı

	Gönül defterinden silme yeter ki

	Şeker ile  anmasan da adımı 

	Dertle acıyla bir bilme yeter ki

	Duygu yüklü bulut gibi yağarım

	Bazen deli poyraz bazen de karım

	Üşürse elin, avucumda  yakarım

	Perişan halime, gülme yeter ki

	Kapkaranlık bir gecede yitersem

	Yanıp siyah duman gibi tütersem

	Senden habersiz çekipte gidersem

	Sen benim peşimden gelme yeter ki

	Gönlüm acıya olsa da tiryaki

	Yanık  sevdaya,su dağıtan saki

	Ben ölürüm aşkım olsa da baki

	Sen benden önce, ölme yeter ki', 'Bütün defterlerinden sil  adımı 	Gönül defterinden silme yeter ki 	Şeker ile  anmasan da adımı  	Dertle acıyla bir bilme yeter ki 	Duygu yük...', ARRAY['Türk Edebiyatı','Şiir','Ömer Arslan']::text[], 8.5, '{"poet":"Ömer Arslan","poet_slug":"omer-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yeter-ki-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her dünde yarın ol..', 'her-dunde-yarin-ol-ece-ozbek-jspcj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her dünde

seni seviyorum

istiyorum

her dünde

yarın ol

her yarında

dün', 'Her dünde seni seviyorum istiyorum her dünde yarın ol her yarında dün...', ARRAY['Türk Edebiyatı','Şiir','Ece Özbek']::text[], 8.5, '{"poet":"Ece Özbek","poet_slug":"ece-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/her-dunde-yarin-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkmaz sokak', 'cikmaz-sokak-elazigli-mustafa-kaya-7z9s7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'başıma yıkıldı 

beklediğim saatler 

dev oldular

büyüyen karanlıklar 

ışıkları söndü şehrin 

yine sokaklardayım

sensizlik acıtıyor

bu gece sen

çıkmayan mehtabım

gülmeyen bahtımsıın

çıkmaz bir sokak

ne tarafa çıksam

kaldırım taşları

tünemiş kuşlar

sokak kedileri

evsizler

hepsi üzerime geldiler...

Mustafa kaya

16.11.2005 / sarayburnu

www.mustafakaya.net', 'başıma yıkıldı  beklediğim saatler  dev oldular büyüyen karanlıklar  ışıkları söndü şehrin  yine sokaklardayım sensizlik acıtıyor bu gece se...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cikmaz-sokak-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Uzun Tören', 'bu-uzun-toren-cemal-sayan-iow30', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıpranmış bir bulut getirsen diyorum

mutlaka biraz ben

masalarda bırakılmış ağır uyku

Kıpırdamadan öyle öyle dingin

yağmur nasıl iniyorsa yalın

geceleri biryerde buluşup yüreğine koy beni

gökyüzü kopsun mu kopsun mu dünya 

kalkıp gidecek oluyor deniz ayakuçlarımdan

-ne zaman güzellik tutacak olsa beni

Kuruyan dallarıma neft sürgün

kaşlarıma sürme 

nasılsa hain ve yaralıyım şimdi

Seni iyi diyarlara seni nehirlere 

ama neden ben hep yadırgarım ölümü

adım geçince', 'Yıpranmış bir bulut getirsen diyorum mutlaka biraz ben masalarda bırakılmış ağır uyku Kıpırdamadan öyle öyle dingin yağmur nasıl iniyorsa ya...', ARRAY['Türk Edebiyatı','Şiir','Cemal Sayan']::text[], 8.5, '{"poet":"Cemal Sayan","poet_slug":"cemal-sayan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bu-uzun-toren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhabbet', 'muhabbet-ahmet-aykol-cd2qk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep ama hep yalan

Ayrı mekanlarda yaşanan 

Başka bir oyun başka bir dolan

Benim kabul ettim,yüreğimde kaybolan

Susulur      

Ve başka bir mekanda

Başka bir muhabbetin ucu tutulur

Ölünür 

Ve başka başka kimliklerde

Yeni kaleler kurulur', 'Hep ama hep yalan Ayrı mekanlarda yaşanan  Başka bir oyun başka bir dolan Benim kabul ettim,yüreğimde kaybolan Susulur       Ve başka bir me...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aykol']::text[], 8.5, '{"poet":"Ahmet Aykol","poet_slug":"ahmet-aykol","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/muhabbet-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunmak Sana...', 'dokunmak-sana-askin-ceylan-g8883', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nadide bir çiçek gibisin,

Narin, kırılgan...

Sanki dokunsam incineceksin,

Yitip gideceksin ellerimin arasından,

Dokunamıyorum.

(Nisan 2002,İstanbul)', 'Nadide bir çiçek gibisin, Narin, kırılgan... Sanki dokunsam incineceksin, Yitip gideceksin ellerimin arasından, Dokunamıyorum. (Nisan 2002,İ...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Ceylan']::text[], 8.5, '{"poet":"Aşkın Ceylan","poet_slug":"askin-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dokunmak-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudum', 'umudum-sedat-gurleyik-n8qvl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüzüne hasretim bir bilsen 

Sensiz geçen her gün zordur 

Yaralı bir kuş gibi seni beklerken 

Görmezsem cemalini yüzüm hep soluktur

Ayrılık bulutları çökmüş şehrime 

Mutluluk fidanları diktim ellerimle 

Umut aşıladım solmasınlar diye

Büktü boynunu gösterdi bulutları gökyüzünde

Biliyorum birgün bitecek bu hasret 

Zor geçen günlerim seninle sona erecek 

Ayrılırken bulutlar güneş bize gülecek

Ne güzel şeysin sen sevilecek

                           

                                                       seni seviyorum...', 'Yüzüne hasretim bir bilsen  Sensiz geçen her gün zordur  Yaralı bir kuş gibi seni beklerken  Görmezsem cemalini yüzüm hep soluktur Ayrılık b...', ARRAY['Türk Edebiyatı','Şiir','Sedat Gürleyik']::text[], 8.5, '{"poet":"Sedat Gürleyik","poet_slug":"sedat-gurleyik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/umudum-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Ayna', 'kirik-ayna-sedat-gurleyik-tf1wu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eski bir otel odasında 

Seni aradım anılarımın arasında 

geçmese de senden sonra hayatım 

geçmişi aramak boşuna

Yalnızlığıma eş bir dostum var.

Rüyalarımı anlatırım sabahları

dertlerimi dinler akşamları

hiç konuşmadan öylece bekler karşımda 

Kim derdi ki bir gün dostum olacak 

Bu kırık ayna', 'Eski bir otel odasında  Seni aradım anılarımın arasında  geçmese de senden sonra hayatım  geçmişi aramak boşuna Yalnızlığıma eş bir dostum v...', ARRAY['Türk Edebiyatı','Şiir','Sedat Gürleyik']::text[], 8.5, '{"poet":"Sedat Gürleyik","poet_slug":"sedat-gurleyik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kirik-ayna-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokaklar İşgal Edilmiş', 'sokaklar-i-sgal-edilmis-salim-erben-qpjlv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bütün sokakları isgal edilmiş

Yıkık bir kenttir dolaştığım

Sokakları karanlık ve soğuk...

İşgalciler kol gezer

Zavallı kentin zaferi; 

Kabullenmektir yenilgiyi

Madalyasını kaptırmış gazi 

Masumdur gözleri

Ve son sözleri:

İç isyanının ele başına

''sevdam  dedi.....

Gönül yıkıldığı yerde ölmelidir

Kimse yazmasın seceresini 

mezar taşına

Gidilecek yeri olmayanın 

Sığınmasıdır korkularından 

Toprağın kokusuna zalım', 'Bütün sokakları isgal edilmiş Yıkık bir kenttir dolaştığım Sokakları karanlık ve soğuk... İşgalciler kol gezer Zavallı kentin zaferi;  Kabul...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sokaklar-isgal-edilmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşündüm', 'seni-dusundum-askin-ceylan-blxgy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkı düşündüm,

Sevmeyi,sevilmeyi,

Teninden iliklerine hissetmeyi seni,

Düşündüm ve lanet ettim kendime

Ve sensiz geçen bunca zamana.

(2003,İstanbul)', 'Aşkı düşündüm, Sevmeyi,sevilmeyi, Teninden iliklerine hissetmeyi seni, Düşündüm ve lanet ettim kendime Ve sensiz geçen bunca zamana. (2003,İ...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Ceylan']::text[], 8.5, '{"poet":"Aşkın Ceylan","poet_slug":"askin-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seni-dusundum-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-saziye-aylin-uyanik-8o3wf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kırık ayna me acıtıyor canını? 

Sen istemez miydin  yıllarca  görüntünü  sana veren bu  aynadan kurtulmayı? 

Ben kendimi bilmiyor muyum derdin.

Yaşadıklarımda bulurum kendimi belki  parça parça

Ama ihtiyacım yok şimdiki  yansımama 

çünkü ben daha  sindirmedim  bu anı derdin.

Al işte alabildiğine yanlızsın artık bu  odada. 

Kırık cam parçaları  eklemiş  yansımalarda

dört duvarlı odana duvarlar.

Sen de bekliyordun  yanlızlığınla yüzleşeceğin  bu günü.

Kendine kanıtlamak istercesine

 kaç kere yeltendin  aynayı kırmaya.

Ama  kendin  de olsa 

aynadaki tek  dostunu  yok edemezdin.

Mantarlar şarap şişelerinde kaç kere dibe vurdu sen benden daha iyi bilirsin.

İçini boşalttığın  şişe hayatların

boş  mantar seslerini sen benden daha çok duydun.

Korkmadın hiç 

 ama hep bekledin şişenin kırılmasını.

Ölümü beklemenin  kayıtsızlığıyla 

 takvim yapraklarını şarabınla ıslattın.

Sokakta yürüyen insanlara hayatın aynasındaki görüntüler gibi

Dokunamadın hiç gerçekçe.

Sadece bildin edalarını.

Yanlızlığın kendindendi; 

kendinliğin yanlızlığından.

Yelkenliden adaya vuranlar,

şişeden umutlarını daha kesmeden önce

Sen şişenin içindeki yelkenliden umudunu çoktan  kesmiştin. 

Kolaydı  tercihlerin.

Ölümün de kolay olacak sanırdın.

Ama beni  hep unuttun. 

Odandaki, şişendeki havaydım ben.

Vücudundaki can.

Gördüklerin; duydukların dışında ruhundum ben.

Ve ben ölmeden asla ölemezdin.

Nasıl farklı  olabilirdi diye düşündüm hep.

Besleseydin beni  diğer ruhlarla; 

Yok olamayacak kadar büyür; gördüklerin ve duydukların da olurdum belki.

Ama  hiç istemedin küçük yenilgilerden dolayı.

Açılamadın büyük dalgalı denizlere şişen ile.

Küçük  sularda  da bulamadın kendini.

Lakin ölüm beni  hatırladığın zaman  bulacak seni.

Çünkü  beni farkettiğinde  beni yok etme yolu da gelecek aklına..

Ayna  daha da kırılacak belki

Ve küçük sıyrıklar  olacak  yanlızlığından sorumlu  her  bedende.

(İstanbul; 05/2000)', 'Kırık ayna me acıtıyor canını?  Sen istemez miydin  yıllarca  görüntünü  sana veren bu  aynadan kurtulmayı?  Ben kendimi bilmiyor muyum derd...', ARRAY['Türk Edebiyatı','Şiir','Şaziye Aylin Uyanık']::text[], 8.5, '{"poet":"Şaziye Aylin Uyanık","poet_slug":"saziye-aylin-uyanik","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/ayna-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümün En Güzel Sabahı', 'omrumun-en-guzel-sabahi-askin-ceylan-aaxdo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nisandı,

Güneş solmuş bir çiçeği andırıyordu,

Ayazlı bir Eskişehir sabahı,

Yağmur çiseliyordu,

Usulca vurdum kapıyı

-üzerinde mahmurluğun ve en sitemli bakışların-

''''Niye uyandırdın beni deli'''' dedin ve sustun,

Gözlerini ovuşturdun,

bebekler kadar güzeldin,

Şükrettim tanrıya,

Ömrümün en güzel sabahıydı.

(Kasım 2002,İstanbul)', 'Nisandı, Güneş solmuş bir çiçeği andırıyordu, Ayazlı bir Eskişehir sabahı, Yağmur çiseliyordu, Usulca vurdum kapıyı -üzerinde mahmurluğun ve...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Ceylan']::text[], 8.5, '{"poet":"Aşkın Ceylan","poet_slug":"askin-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/omrumun-en-guzel-sabahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biraz', 'biraz-askin-ceylan-nhml1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biraz şiirden, romandan,

Biraz masallardan,

Biraz da anlatamadıklarımdan ibaretim galiba.

- Çokça yaşayamadıklarımdan -

Her insan kadar yalnız, hüzünlü; 

Her insan gibi sıradan bir fani...

(Ocak 2004,İstanbul)', 'Biraz şiirden, romandan, Biraz masallardan, Biraz da anlatamadıklarımdan ibaretim galiba. - Çokça yaşayamadıklarımdan - Her insan kadar yaln...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Ceylan']::text[], 8.5, '{"poet":"Aşkın Ceylan","poet_slug":"askin-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/biraz-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben seni kaybetmek için sevmedim', 'ben-seni-kaybetmek-icin-sevmedim-coskun-aksoy-hfz41', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlık sayfalarda kara sevdamı arama

Hissetmedilmedik yürekte barınamam

Beni kaybettiğinide sanma sakın

Unutmaki Seni kaybetmek için sevmedim

Acıyı kederi yüreğimde tuttum

Gözyaşlarımı senin için sızlattım 

Ben bu işe kalbimi canımı koymuştum 

Unutmaki seni kaybetmek için sevmedim

Yara almış yüreğim ağlasın bırak

Sakın ola ona acımaya kalkma

Çünkü o acıyı fazlasıyla haketti sanırım

Oysaki ben seni kaybetmek için sevmedim

Sevmedim terkedemedim 

Yolun açık ola............... 

Aslında ben veda etmek hoşlanmam

Sebebini sorarsan 

Mısralarımı tekrar okursun

Seni Unutmak için sevmediğimi anlarsın', 'Karanlık sayfalarda kara sevdamı arama Hissetmedilmedik yürekte barınamam Beni kaybettiğinide sanma sakın Unutmaki Seni kaybetmek için sevme...', ARRAY['Türk Edebiyatı','Şiir','Coşkun Aksoy']::text[], 8.5, '{"poet":"Coşkun Aksoy","poet_slug":"coskun-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ben-seni-kaybetmek-icin-sevmedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al bendende o kadar', 'al-bendende-o-kadar-coskun-aksoy-kdc8s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayat hep güzelliklerle doludur

Yaşamasını bilirsen ki yaşıyorsan

Sen sen oldukça yaşamak gelir içinden

Kokma sen kendine güven

Ümitsizliğe kapılmana gerek yok

Sen üzülmedikçe ne seni üzen olur

Nede sen üzülürsün yeterki yaşa

Yeterki gül yeterki mutlu ol sev sevil

Koca cihan dururken daralma

Hayattaki her yaşantıyı genelleme

Bir hayatı bil birde yaşamayı 

Her yapılan yanlış hayat değildir

Umutlar dururken umutsuzluk yaratma

Kendi kendini asla kandırma

Şunuda unutma 

Hayat seni değil sen hayatı yaşa

07/11/2005', 'Hayat hep güzelliklerle doludur Yaşamasını bilirsen ki yaşıyorsan Sen sen oldukça yaşamak gelir içinden Kokma sen kendine güven Ümitsizliğe ...', ARRAY['Türk Edebiyatı','Şiir','Coşkun Aksoy']::text[], 8.5, '{"poet":"Coşkun Aksoy","poet_slug":"coskun-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/al-bendende-o-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan Mevsimi', 'hazan-mevsimi-zahide-handan-erengil-0lwp7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günün  yorgun ışlıkları,

Ağaçlar arasından süzülür,

Ayaklarına serilir,

Güz yaprakları dökülür.

Merhaba derken,

Yazdan sonbahara.

Hatırlarsın yaz gecelerinin

Doyulmaz  dost sohbetlerini,

Hoş bir serinlik sarar,

Sessiz ve yalnız gecelerini.

Fark edersin tabiatın,

Yorgundur olağan üstü süsü,

Alır götürür seni renklerin,

Coşkulu, ihtişamlı büyüsü

Bakarken sisli camın ardından,

Yanlız sen değilsindir baharla vedalaşan

Kuşlar da göç etmiştir artık yuvalarından.

Kaçıncı hazandır ruhları saran? 

Kaçıncı göç mevsimidir yaşanan? 

Çağlayan nehir,çoşan deniz durgun,

Tabiat yorgun sen yorgun,

Merhaba derken,

Yazdan sonbahara

Güneş yanağından öpsün,

Benim yerime seni,

Uyandırsın güz sabahlarına.

Bak yine bir balıkcı teknesi geldi

Limana demirlendi,

Hüzün yüklü gönüller,

Hazanla büyülendi.', 'Günün  yorgun ışlıkları, Ağaçlar arasından süzülür, Ayaklarına serilir, Güz yaprakları dökülür. Merhaba derken, Yazdan sonbahara. Hatırlarsı...', ARRAY['Türk Edebiyatı','Şiir','Zahide Handan Erengil']::text[], 8.5, '{"poet":"Zahide Handan Erengil","poet_slug":"zahide-handan-erengil","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hazan-mevsimi-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Migren Hali', 'migren-hali-firat-acikgoz-03b3j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İki hali var migrenin

ya dolduracaksın boşluğu,

masa lambalarını sığdıracaksın dibine

ya da iki delik, bir kapak yaptıracaksın

tornacıların hülyalarında.

Burhan, tırnakları atmış kalfada başlar,

Ve bardakları kırmış garson kadar titrek

Bekliyor seni

Cebindeki nazar taşlarını satmaya kalkar evliyalara,

Korkmuş düşünceleri, 

Biz suçsuzuz koyunu bacağından asanlar kadar

Yani ta şu kadar

Sütçünün olmuş 

Belli ki tüpçünün kıvılcımları,

Ummaya karmış, 

Maya tutmamış.

Belli ki görmüş geçirmiş

Badiresiz, sokaklarda

bakirelerin ellerini tutmuş.

Hiç istifini bozmamış, 

sırtı hala boş.

Helal-i hoş olsun çadır altında yatan

Boyuna dönen sütçüye

Kırmızı tüpleri fodul tüpçülerin

sokak lambalarına sövüyor

yüklemler bir eyleme yönelmiş

habire giriyor.

Geliyor da geliyor

Belli ki iktidarı vermiş kendi elleriyle

Belli ki ateşe verilen her şey

kırmızı tüpler kadar gerçek.

Kopar altıncı parmağını,

Yok olup gitmeden. 

Arife tarif gerek belli ki

Odada yedi Bektaşi var

Yedisi de belli

Yedikleri önünde 

Yemedikleri ciğerlerinde belli ki

Döne döne durdukları yok

Çektikleri çok.

Zeytin çekirdeklerine kazırlar serzenişleri

Arife tarif gerek belli ki

Döne döne durdukları yok

nereye kadar? 

Her şey 

bir yere kadar.', 'İki hali var migrenin ya dolduracaksın boşluğu, masa lambalarını sığdıracaksın dibine ya da iki delik, bir kapak yaptıracaksın tornacıların ...', ARRAY['Türk Edebiyatı','Şiir','Fırat Açıkgöz']::text[], 8.5, '{"poet":"Fırat Açıkgöz","poet_slug":"firat-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/migren-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ece''msin', 'ece-msin-yavuz-dogan-kjswp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hangi sözle başlanır Ece’yi anlatmaya

Yıldızı hiç sönmemiş geceyi anlatmaya? 

Ne yazsam eksik kalır sözcük neyi anlatsın

Sen ilkbahar soluklum sen özlenen muratsın.

Hangi şiirin sözü sende saklı değil ki

Hangi hasret başka bir tende saklı değil ki? 

Sen ki şaire kalem şiire can verensin

Sen kaktüs bahçesinden gönlüme gül derensin.

Sen ki gerçek hayattan koparılmış sol yanım

Sen diyeti ödenmez paha biçilmez canım.

Sen ki mistik düşlerin en yaramaz cadısı

Sen koskoca bir şehrin kanun bilmez kadısı.

Sen ki sabahsız bir düş karanlığa dolansın

Sen Taç Mahal’de bir gül yaklaştıkça solansın.

Sen ki bilinmezimi birer birer keşfeden

Sen gönül sarayımı içten içe fetheden.

Sen ki onmaz bir derdin deva bilmez acısı

Sen virane bir ömrün en yeni kiracısı.

Sen ki soğukta donan elimi ısıtansın

Sen kararmış ömrüme vakitsiz doğan tansın.

Sen ki kırgın bir cana gülümse diyen melek

Sen kayan yıldızlardan tuttuğum en son dilek.

Sen ki kırılgan çiçek koklarken sakındığım

Sen yakınken özlemim uzakken yakındığım.

Sen ki lirik bir aşkın yaşanmamış bir demi

Sen haksız bir savaşta yakılmış en son gemi.

Sen ki soluksuz kalmış cana candan ötesi

Sen tükenmiş bir ömrün tazelenmiş nefesi.

Sen ki dün bildiğimi bugün unutturansın

Sen hasreti alnının ortasından vuransın.

Sen ki çölde bir vaha yeşermiş bir tomurcuk

Sen kirlenmiş dünyada tertemiz kalmış çocuk.

Sen ki unutulmuş söz verilmiş en son vaat

Sen yürek yangınının hatırlandığı saat.

Sen ki ferman tanımaz baş kaldırmış bir vezir

Sen tutulmuş kamerin yarattığı med cezir.

Sen ki bölünmüş uyku sen yorumsuz rüyasın

Sen karanlık geceyi aydınlatan ziyasın.

Sen ki dün güldüğüme bugün sert bakışımsın

Sen suskun bir nehirden denize akışımsın.

Sen cevapsız bilmecem sen sabahsız gecemsin

Sen hasret kokan hecem sen sultanım, ECE’msin.', 'Hangi sözle başlanır Ece’yi anlatmaya Yıldızı hiç sönmemiş geceyi anlatmaya?  Ne yazsam eksik kalır sözcük neyi anlatsın Sen ilkbahar solukl...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Doğan']::text[], 8.5, '{"poet":"Yavuz Doğan","poet_slug":"yavuz-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/ece-msin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar Sonra', 'yillar-sonra-ahmet-tevfik-ozan-18ecf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gördüm sevdiğim güzeli; sevdiğim güzel, O değil! 

Ne yüzünde O’ndan eser; ne sesinde, teninde...

Demek yıllar mezar olmuş; gül hayali, bir diken

Velhasıl, bir kabristan taşımış bedeninde! ..', 'Gördüm sevdiğim güzeli; sevdiğim güzel, O değil!  Ne yüzünde O’ndan eser; ne sesinde, teninde... Demek yıllar mezar olmuş; gül hayali, bir d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yillar-sonra-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oldu', 'oldu-firat-acikgoz-xw1au', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nasılsa Salı oldu

Kolumun ağrısı ilk günkü gibi

Nereye baksan nasılsa o var

Kol ağrısı da başıma bela oldu.

Doksan dokuzda doğdu 

Kumruların arka bahçesinde

Soğuktu, nereye gitsen nasılsa O,

Parmaksız eldivenler daha yoktu

Cebimizde para da yoktu

Lakin nereye baksan nasılsa O vardı.

Ankara’da yedi güne sığmayacak kadar ev gezdi,

Altın günleri, bakırda, sahanda hep o vardı.

Yumurtanın akını sarısından öyle bir ayırırdı ki, 

Yıllar geçti kumrular böylesini görmedi.

Otuz sekiz yıl geçti

Lakin hiçbir erkeğin hayalarında ki teri hissedemedi,

Altmış sekiz anayasası kadar bakirdi.

Nasılsa o vardı

Balkondan balkona kumru misali.

Yoğurtsuz bakla yemek kadar zordu

Doksan dokuzda doğdu

Salıydı Cuma oldu

Kolumun ağrısı hayalarıma vurdu.

Beytepe, sevgili babama, 2004

Aralık 28', 'Nasılsa Salı oldu Kolumun ağrısı ilk günkü gibi Nereye baksan nasılsa o var Kol ağrısı da başıma bela oldu. Doksan dokuzda doğdu  Kumruların...', ARRAY['Türk Edebiyatı','Şiir','Fırat Açıkgöz']::text[], 8.5, '{"poet":"Fırat Açıkgöz","poet_slug":"firat-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/oldu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
