INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarınımız olmayacak', 'yarinimiz-olmayacak-tevfik-karinca-5i6ut', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Korkulan oldu

Umudun yüzüstü kalması

Gerçeklerin beklenen kasırgası

Ellerinde sımsıkı tut

Bunlar yaşadıklarımızn hatırası

Dönüp eksenimiz etrafında

Düştüğümüz zor pusuda

Söylenebilecek en kötü söz elveda

Yarınımız olmadı hiç olmayacak bizim

Güneş belki doğmayacak

Alabora olmuş bu gemide

Hangi iskele sancak

Tenimizde dolaşan o sıcaklık

Başka bir şey değil yalnızlık ancak

Ne bir bıçak yaraladı bizi

Ne de bir silah vurdu

Gizlendiğimiz o son kuytu

Yitirdiğimiz son umuttu

Sevdamız adına', 'Korkulan oldu Umudun yüzüstü kalması Gerçeklerin beklenen kasırgası Ellerinde sımsıkı tut Bunlar yaşadıklarımızn hatırası Dönüp eksenimiz et...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yarinimiz-olmayacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babil Fahişesi', 'babil-fahisesi-sukriye-arslan-yxm8f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I

Yok izi asmaların,

Ama ağırdır bedeli, Babil''de yaşananların,

Ve hâlâ bombalar yağar kente,

Sırası gelmekte işlenen tüm günahların,

Ve taşlayalı beri insanoğlu,

Tanrı''nın sevgililerini,

Babil''e taşlar inmekte,

Ve taş altında taşlar inlemekte...

                             II

Bilirim tadını eski şairliğimden,

Yeni bir Karma örmekte,

Taştan ve kemikten,

Çocukluğumuzun o düşsel şehri,

Babil''in bakire hali,

Bugün Dersaadet''te zuhur etmekte...', 'I Yok izi asmaların, Ama ağırdır bedeli, Babil''de yaşananların, Ve hâlâ bombalar yağar kente, Sırası gelmekte işlenen tüm günahların, Ve taş...', ARRAY['Türk Edebiyatı','Şiir','Şükriye Arslan']::text[], 8.5, '{"poet":"Şükriye Arslan","poet_slug":"sukriye-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/babil-fahisesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-adem-tok-uj9z8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bozkırlara renkler düşerken

esmeray gülümserken

yollara bakıp

seni düşünürken GEL

GEL! 

şafak aynı canlılığıyla söküp

tütünüm benden ayrılmaya ant içmişken

hâlâ kabuğundayken gözler GEL

sığınacak limanım çalınırken

yağmurlardan kaçıp

düşerken yapraklar tüketip zamanlarını

üşüyorken GEL

GEL sar beni mevsimine

tozan karların arasından

özgürlüğe koşarken

                                                                   (10.06.02) 

                                                                  f tipi hapishane TEKİRDAĞ', 'bozkırlara renkler düşerken esmeray gülümserken yollara bakıp seni düşünürken GEL GEL!  şafak aynı canlılığıyla söküp tütünüm benden ayrılma...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gel-227-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben kerem değilim/ve sende aslı/taşla örülmez/aşkın binası', 'ben-kerem-degilim-ve-sende-asli-tasla-orulmez-askin-binasi-engin-akbaba-6rhmj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(can çeker

ten  kavurur

yel çıkar

kül savurur)  

sevgilim! ! 

bu yaz da erken bitti

güzle birlik geldi son mektubun

''bana şiirler yazıyor musun? ''

diyorsun...

ahhhhh! ! ! 

azdı laf anlamaz yüreğim

çığlık çığlığa uzuyor gece

çığlık çığlığa...

Ayırıyorlar bizi kardeşlerimizden bitanem

Dikenli teller ile bölüyorlar dünyayı

Sonra nöbet kuleleri

Ağır silahlar

Sınır boyları....

Birde parmaklıklar arkasında bir çoğu

Kırlangıç kokulu düşler taşırlar

Ota, karıncaya hasret

Çarparlar yüreklerini

Karanlıklara

Kanatları kanar

Akılları yaldırdar 

Kör duvarlarda...

Sevgilim

Bir de mermilerle

mutlu edenler var kendini

Şehirleri bombalıyorlar...

Zıbınsız bebeler

Beş parasız babalar

Umutlarının 

Kara kışında

Öldürülüyorlar....

Sonra kadınlar geliyor aklıma

 Ahhh kadınlar........

Ak duvağa girmeden daha

gelinlik kızlar.....

kocasız onlar,

oğulsuz,

babasız kalan onlar..

ya onları düşman bilmek niye

niye yıkılan kentlerin 

kadınları iğfal edilir

ahhhhhhhh içerim yanıyor... içerim

sırtlanlara yedirin ciğerlerimi

sessiz kalıyoruz.. 

ölenler bizden değil diye...

bizim değil diye

kana batan çocuklar

kumalara gömüyoruz başımızı bitanem...

hayatın telaşı..

banka kuyruğu... 

dolmuş sırası

takılıyor ayaklarımıza

bin bir türlü yaşam

ezip geçiyoruz...

bana “ duygu yüklü 

şiirler yaz” diyorsun

“aşkımızı anlatsın”

yeni yetme bir şairim ben

ne gelirse kalemimden yazarım

imgedir falan filan

ardına saklanmadan

(ben kerem  değilim

ve sende aslı

taşla örülmez

aşkın binası)  

mektubuma burada son verirken

yüreğinin en kanlı yerinden

öperim.

16/11/2005

e. akbaba.. umut ilke kurtuluş', '(can çeker ten  kavurur yel çıkar kül savurur)   sevgilim! !  bu yaz da erken bitti güzle birlik geldi son mektubun ''bana şiirler yazıyor mu...', ARRAY['Türk Edebiyatı','Şiir','Engin Akbaba']::text[], 8.5, '{"poet":"Engin Akbaba","poet_slug":"engin-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/ben-kerem-degilim-ve-sende-asli-tasla-orulmez-askin-binasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Kalbim Yok', 'artik-kalbim-yok-umut-ulbegi-2ob8d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bedenim ufku sorguluyor

uçabilir miyim

onbeş kilo fazlama rağmen

iki kanadım var

çelebi dedemden kalma

çırpabilir miyim

yetmiyor rüzgar gibi geçmen

sıkıntılı yollar var

yaşlı trenler

son otobüsü kaçırmış bekleşenler

yağmur var

gece var

soğuk var

ne aramazsan var

dargınlar

Tanrı''ya darılmışlar

Bedenim ufku sorguluyor

yollara elveda

bacaklarım iki kırık ok

neşter bedenimi aralıyor

onbeş kilo fazlamı alıyor

yağmur yok

gece yok 

soğuk yok

seni bırakıyorum

artık kalbim yok', 'Bedenim ufku sorguluyor uçabilir miyim onbeş kilo fazlama rağmen iki kanadım var çelebi dedemden kalma çırpabilir miyim yetmiyor rüzgar gibi...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/artik-kalbim-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Karşılıksız aşk*', 'karsiliksiz-ask-serkan-turna-a0xo2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'karşılıksız aşk değil bana yaşattığın

ben, karşılıksız seviyorum seni…

bir anlam vermenide beklemiyorum 

önümüzdeki beş, on yıl içinde 

hele, sahte aşklar  tükensin gönlünde

yalancı dostlar birer birer kaybolsunlar ömründe 

saçlarına aklar düşsün 

geri dönülmez yollara gir hele.

karşılıksız aşk değil bana yaşattıkların 

gelecek günlerine bir emanettir sadece...', 'karşılıksız aşk değil bana yaşattığın ben, karşılıksız seviyorum seni… bir anlam vermenide beklemiyorum  önümüzdeki beş, on yıl içinde  hele...', ARRAY['Türk Edebiyatı','Şiir','Serkan Turna']::text[], 8.5, '{"poet":"Serkan Turna","poet_slug":"serkan-turna","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/karsiliksiz-ask-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gülüversen', 'bir-guluversen-huseyin-pelit-k6z37', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkın hududundan geçerken bizler

Seni gören gözler hep gülmek ister

Sevgilim yanıma yanıma gelsen

Çaresiz aşkına bir gülüversen

Ayrılık seni de benimle vurur

Ümitsiz sevgisiz aşkında gurur

Alışır zamanla hudutta sınır

Duygusal aklına bir gülüversen

El bilir kadrimi sen bilmesende

Sevgilim sen bana hiç gelmesende

Çaresiz aşkına sen gülmesende

Sevgilim kendine bir gülüversen

Namludan çıkan bir kurşun emsali

Yardıma muhtaç bir öksüz timsali

Yaralı kanadım bir kuş misali

Koparılmış güllere bir gülüversen

Sanma ki yüreğim çelikten yelek

Senin sözlerinse kurşundan felek

Bu yüzden kalbimse kalburdan elek

Solmuş yüreklere bir gülüversen', 'Aşkın hududundan geçerken bizler Seni gören gözler hep gülmek ister Sevgilim yanıma yanıma gelsen Çaresiz aşkına bir gülüversen Ayrılık seni...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Pelit']::text[], 8.5, '{"poet":"Hüseyin Pelit","poet_slug":"huseyin-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-guluversen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Helal Ettim Diyerek', 'helal-ettim-diyerek-kadir-albayrak-nbjv2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sensiz esen rüzgarın sesini dinliyorum

Senden bana bir haber getirdi mi diyerek

Seni beklemek bile ibadet biliyorum

Aldığım her nefesim sevabımdır diyerek

Her sabah gün doğarken ufku seyrediyorum

Belki bir gün oradan sen doğarsın diyerek

İnan ki seni dünden daha çok seviyorum

Belki yarın bu beden toprak olur diyerek

Gözlerimi sımsıkı kapattım bekliyorum

Gelipte dudağımdan sen öpersin diyerek

Şu esen rüzgarlara sormaktan korkuyorum

Uyandırırsa beni bu bir rüya diyerek

Nihayet kaderime boynumu büküyorum

Alın yazımda bile kalem sensin diyerek

Senin için az ama ömrümü veriyorum

Tanrını huzurunda helal ettim diyerek', 'Sensiz esen rüzgarın sesini dinliyorum Senden bana bir haber getirdi mi diyerek Seni beklemek bile ibadet biliyorum Aldığım her nefesim seva...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/helal-ettim-diyerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gün', 'bu-gun-sair-mustafa-turani-809gd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensizinim 

Dostum bu gün.

Sensizliğe

Küstüm bu gün.

Serde aşk var

Akla zarar

Fıtınalar

Estim bu gün.

Aşka inat

Aşkı anlat

Aşka surat

Astım bu gün.

Aşkı zahir

Ettin zehir

Güne kahır

Kustum bu gün.

Gönül şahit

Sende işit

Candan ümit

Kestim bu gün.

Vakit akşam

Bitti yaşam

Konuşamam

Sustum bu gün.

Vade yetti

Ecel dürttü

Toprak örttü

Üstüm bu gün.

TURANî   yan

Maziyi an

Kırıldı can

Testim bu gün.

16.11.2005', 'Sensizinim  Dostum bu gün. Sensizliğe Küstüm bu gün. Serde aşk var Akla zarar Fıtınalar Estim bu gün. Aşka inat Aşkı anlat Aşka surat Astım ...', ARRAY['Türk Edebiyatı','Şiir','Şair Mustafa Turani']::text[], 8.5, '{"poet":"Şair Mustafa Turani","poet_slug":"sair-mustafa-turani","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bu-gun-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Duvar', 'dort-duvar-kadir-albayrak-dfkce', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Istanbul zindanım dardayım darda

Hayalin yeter be yaşamak için

Başımı göğsüne koyamasam da

Dört duvar yeter be ağlamak için

Ben yandım bilirim bilmez kimisi

Yalanmış gül yüzlüm yalan gerisi

Erkekler ağlamaz demiş birisi

Dört duvar yeter be ağlamak için

Ne kadar dert varsa topladım bir bir

Tatmadığım acı var mı kim bilir

Sen unutsan bile yaradan bilir

Dört duvar yeter be ağlamak için

Sitem doloyum ya! Söz bulamadım

Aradım senden bir iz bulamadım

Başımı koyacak diz bulamadım

Dört duvar yeter be ağlamak için', 'Istanbul zindanım dardayım darda Hayalin yeter be yaşamak için Başımı göğsüne koyamasam da Dört duvar yeter be ağlamak için Ben yandım bilir...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dort-duvar-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-sair-mustafa-turani-xz0tn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aklımı başımdan aldı götürdü

Beni sevdalara çekti gözlerin.

Benliğimi benden çaldı götürdü

Bakınca bir seher vakti gözlerin.

Melekler el edip  gökçe katından

Yerde süvariler indi atından

Ayça hilâl kaşlarıyın altından

Şimşekler misali çaktı gözlerin.

Bir bakışın beni benden geçirdi

Aşkı kadeh kadeh sundu içirdi

Aşkın semasına çekti uçurdu

Sanki sihirli bir oktu gözlerin.

Ayça bakışlarındaki derinlik

Serinlik kattı ruhuma serinlik

Bakışların gelin zülfün gelinlik

Yıldızlardan tacın taktı gözlerin,

Gözlerin gök yüzü gözlerin sema

Işık ışık yıldız kayar ufkuma

Belki sen inanmayacaksın ama

Yıldızlardan gökçe çıktı gözlerin,

Gözlerini farklı kılmış Yaradan

Rengin vermiş, aktan gökten, karadan

Alemler boyutlar kaltı aradan

Ufuklar, ufkuna dikti gözlerin,

Nedir ey sevgili nedir bu  bakış

Ufuklar ki alkış tuttular alkış

Bir bakışın bahar, bir bakışın kış

Mevsimden mevsime aktı gözlerin,

Gözlerim, bendedir sanma sevgili

Belki de bendedir diye teselli

Alemden aleme uçtu besbelli

İnan gözlerinde yoktu gözlerin,

Turani'' yim ayça gözlere selâm

Ayça gözlerinde esirin kalam

Safa geldin ayça gözlü ay balam

Ne iyi etti de baktı gözlerin.

Baba 0cağı -2005 Sayfa 158', 'Aklımı başımdan aldı götürdü Beni sevdalara çekti gözlerin. Benliğimi benden çaldı götürdü Bakınca bir seher vakti gözlerin. Melekler el edi...', ARRAY['Türk Edebiyatı','Şiir','Şair Mustafa Turani']::text[], 8.5, '{"poet":"Şair Mustafa Turani","poet_slug":"sair-mustafa-turani","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gozlerin-199-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gün - 2', 'bu-gun-2-sair-mustafa-turani-qthl3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kul sefil

Aç bu gün

Kim kefil

Seç bu gün

Kul Memiş

Ne demiş

Gülmemiş

Hiç bu gün

Kul Ahmet

Gün vahşet

Bi zahmet

Kaç bu gün

Kul Yunus

Gün kabus

Ar namus

Suç bu gün

Kul İsa

Ev arsa

Ne varsa

Saç bu gün

Kul Musa

Aşk suysa

Koy tasa

İç bu gün

Kul garip

Muzdarip

Seyredip

Geç bu gün

Kul T u r a n

Soldu can

Dünyadan

Göç bu gün,

Baba ocağı -2005 Sayfa 132', 'Kul sefil Aç bu gün Kim kefil Seç bu gün Kul Memiş Ne demiş Gülmemiş Hiç bu gün Kul Ahmet Gün vahşet Bi zahmet Kaç bu gün Kul Yunus Gün kabu...', ARRAY['Türk Edebiyatı','Şiir','Şair Mustafa Turani']::text[], 8.5, '{"poet":"Şair Mustafa Turani","poet_slug":"sair-mustafa-turani","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bu-gun-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan', 'vatan-sair-mustafa-turani-o7lc7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir uçtan bir uca vatan

Şereftir, yârdır, namustur.

Uludur uğrunda yatan

Ya Mevlâna ya Yunus''tur.

Gönlümde canandır yaşar

Sevdası serime düşer

Yurt sevgim taştıkça taşar

Hudutsuz bir okyanustur.

Bu yurt için ölebilmek

Ölümü kâr bilebilmek

Esareti çile bilmek

Yiğit olmaya mahsustur.

Varlığında gözü olan

Dirliğinde gözü olan

Birliğinde gözü olan

Ya alçaktır ya deyyustur.

Akıllı ol akıl taşı

Oku okut okul taşı

Yurdumun bir çakıl taşı

Yurtçadır yurttur ulustur.

Dünden ibret almayanın

Gönlü aşkla dolmayanın

Vatan nedir bilmeyenin

Varlığı binbir kabustur.

Turani '' yim canda vatan

Damarımda kanda vatan

Bir sevdadır bende vatan

Gönlüm sevdasına dosttur.

Baba Ocağı 2005-Sayfa; 118', 'Bir uçtan bir uca vatan Şereftir, yârdır, namustur. Uludur uğrunda yatan Ya Mevlâna ya Yunus''tur. Gönlümde canandır yaşar Sevdası serime düş...', ARRAY['Türk Edebiyatı','Şiir','Şair Mustafa Turani']::text[], 8.5, '{"poet":"Şair Mustafa Turani","poet_slug":"sair-mustafa-turani","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/vatan-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınım', 'kadinim-cem-cagman-mxyn9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seni soruyorum kendime ellerin ellerimde

ansızın bulmuştum seni ararken şişe diplerinde

zor oldu birleşmemiz  yazılıymış kaderde

işte benim için kapanmıştı son perde

çok acılar çektim sen yokken hayatımda

varlığınla uyanmak gecenin sabahında

tatlı sözler nağmeler çınlıyor kulağımda

huzurluyum mutluyum sen varken yatağımda

dertlerim seninle diner  kollarımda kadınım

cem arzu lar seni çatlasın düşmanlarım

kaderimsin kadınımsın her şeyimsin sen benim

limanımsın hasretimsin varmı bundan haberin', 'seni soruyorum kendime ellerin ellerimde ansızın bulmuştum seni ararken şişe diplerinde zor oldu birleşmemiz  yazılıymış kaderde işte benim ...', ARRAY['Türk Edebiyatı','Şiir','Cem Çağman']::text[], 8.5, '{"poet":"Cem Çağman","poet_slug":"cem-cagman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kadinim-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gün - 3', 'bu-gun-3-sair-mustafa-turani-cgatr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Derdim bir idi

Yüz oldu bu gün

Derdimden özüm

Köz oldu bu gün.

Bülbülüm ağlar

Gözyaşı çağlar

Baykuşa bağlar

Yaz oldu bu gün.

Özlerim görsen

Değerin versen

Kabuklar dersen

Öz oldu bu gün.

Zikri boşlamak

Fikri taşlamak

Günah işlemek

Haz oldu bu gün.

Eğriler pek çok

Eğri olmaz ok

Doğrularsa pek

Az oldu bu gün.

Bir cüz''ü hariç

Kalanı bir hiç

Ümmet yetmiş üç

Cüz oldu bu gün.

Nerde bir garip

Görsen müzdarip

Birde sen vurup

Ez oldu bu gün.

Hep siz biz deyip

Yol kol iz deyip

Biz bir acayip

Biz oldu bu gün.

Yüreğim uçtu

Yarlan buluştu

Eller konuştu

Söz oldu bu gün.

Bir yolumuz var

Mevlâya kadar

Yollarımız kar

Buz oldu bu gün

Turani''m bence

Dertler var nice

Zamlan işkence

Baz oldu bu gün.

Baba Ocağı- 2005 Sayfa 135', 'Derdim bir idi Yüz oldu bu gün Derdimden özüm Köz oldu bu gün. Bülbülüm ağlar Gözyaşı çağlar Baykuşa bağlar Yaz oldu bu gün. Özlerim görsen ...', ARRAY['Türk Edebiyatı','Şiir','Şair Mustafa Turani']::text[], 8.5, '{"poet":"Şair Mustafa Turani","poet_slug":"sair-mustafa-turani","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/bu-gun-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu sevdada bir gariplik var gülüm', 'bu-sevdada-bir-gariplik-var-gulum-ali-galip-sari-70l5d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir çift göz ağlıyor bin bir hüzüne,

Bu sevdada bir gariplik var gülüm.

Bir ömür harcamak gönülsüzüne,

Bu sevdada bir gariplik var gülüm.

Biri konuşur da biri hep susar,

Biri canım ol der biriyse küser,

Bir yanı virane, bir yan şaheser,

Bu sevdada bir gariplik var gülüm...', 'Bir çift göz ağlıyor bin bir hüzüne, Bu sevdada bir gariplik var gülüm. Bir ömür harcamak gönülsüzüne, Bu sevdada bir gariplik var gülüm. Bi...', ARRAY['Türk Edebiyatı','Şiir','Ali Galip Sarı']::text[], 8.5, '{"poet":"Ali Galip Sarı","poet_slug":"ali-galip-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bu-sevdada-bir-gariplik-var-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utansın', 'utansin-sair-mustafa-turani-jd1nf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hakkın yolundan

Sapan utansın

Zulmün elinden

Öpen utansın.

Baktığı yönden

İslâmdan dinden

Öz benliğinden

Kopan utansın.

Seçip zulmeti

Yayıp zilleti

Halkı milleti

Tepen utansın.

Haktan sapmadık

Halkı tepmedik

Zulüm yapmadık

Yapan utansın.

Yanlış bu  rota

Devrile bata

Rab diye puta

Tapan utansın.

Turani'' yim tez

Ez zulmeti ez

Haksızlığa göz

Kırpan utansın,

Baba Ocağı-2005  Sayfa, 114', 'Hakkın yolundan Sapan utansın Zulmün elinden Öpen utansın. Baktığı yönden İslâmdan dinden Öz benliğinden Kopan utansın. Seçip zulmeti Yayıp ...', ARRAY['Türk Edebiyatı','Şiir','Şair Mustafa Turani']::text[], 8.5, '{"poet":"Şair Mustafa Turani","poet_slug":"sair-mustafa-turani","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/utansin-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Marifet', 'marifet-sair-mustafa-turani-vj9ys', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerim görüyor

Görüyorsam nasıl

Marifet değil ki

O''nu görsem asıl.

Yetime ikram edip

Yedirtmekte marifet

Ve nefse Rabbim Allah

Dedirtmekte marifet.

Baba Ocağı (2005)  Sayfa-23', 'Gözlerim görüyor Görüyorsam nasıl Marifet değil ki O''nu görsem asıl. Yetime ikram edip Yedirtmekte marifet Ve nefse Rabbim Allah Dedirtmekte...', ARRAY['Türk Edebiyatı','Şiir','Şair Mustafa Turani']::text[], 8.5, '{"poet":"Şair Mustafa Turani","poet_slug":"sair-mustafa-turani","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/marifet-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seyri Kâinat', 'seyri-k-inat-sair-mustafa-turani-fspox', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşündüm şöyle derince

Her bir şey  yerli yerince

Aman Ya Rab bu ne ahenk

Bu ne ölçü, bu ne mihenk

Hepsi uyum içindeler

Nedendeler, niçindeler

Her biri kendi halince

Seni anmakta dilince

Kudretini nakış nakış

İşleyen Rabbedir akış

Nazar ettiğim her nokta

Varlığını haykırmakta

Baktıkça baktım ağladım

Boynumu büktüm ağladım

Ya Rab mutlak varış sana

Sayısız yalvarış sana

Rabbim demeye ehil et

Ve kulluğuna dahil et

Rabbim ben sensiz yapamam

Açtım ellerimi kapamam.

Baba Ocağı (2005)  Sayfa-22', 'Düşündüm şöyle derince Her bir şey  yerli yerince Aman Ya Rab bu ne ahenk Bu ne ölçü, bu ne mihenk Hepsi uyum içindeler Nedendeler, niçindel...', ARRAY['Türk Edebiyatı','Şiir','Şair Mustafa Turani']::text[], 8.5, '{"poet":"Şair Mustafa Turani","poet_slug":"sair-mustafa-turani","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/seyri-kainat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Kara Gecelerde*', 'kara-gecelerde-ramazan-ates-9zyci', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uykularımın kaçtığı çok oluyor,

Seni düşünüyorum kara gecelerde.

Yalnızlık ve soguk ürpertiyor beni,

Yapayalnızım bilsen kara gecelerde.

Aslında üzülmüyorum olmayışına,

Sana göre sende haklısın belki.

Benim üzüntüm yalnızlığıma,

Ve anlaşılamamak kara gecelerde.

İçim üperdikce kendime sarılıyorum,

Yalnızlığımı kendimle paylaşıyorum.

Ya birde ben beni terk edersem,

Ne eylerim öyle, kara gecelerde.

Bazen kurşun gibi işliyor ciğerime sessizlik,

Bazen dayanılmaz oluyor, zor geliyor sensizlik.

İçin için ağlıyorum bilmem farkındamısın? 

Gel desem, benimle ol desem kara gecelerde,

İstersen canımı al desem, kara gecelerde.

Ramazan Ateş/Enschede, 14.11.2005', 'Uykularımın kaçtığı çok oluyor, Seni düşünüyorum kara gecelerde. Yalnızlık ve soguk ürpertiyor beni, Yapayalnızım bilsen kara gecelerde. Asl...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kara-gecelerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Köy', 'bizim-koy-sair-mustafa-turani-l5tp3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çıkmıyor yadımdan evim ocağım

Anam yollarıma bakardır şimdi.

Nemlidir gözleri, buruktur kalbi

Yavrum derde bağrın yakardır şimdi.

Bir başka kutlanır, düğünü toyu

Yeşil yaylalarda otlar diz boyu

Gökçe pınar, Ulupınar, Körkuyu

Suların bir başka akardır şimdi.

Onlardır hedefi hicran okunun

Onlardır hamalı çile yükünün

Kara saban ile babam ekinin

Saçmıştır tohumun, ekerdir şimdi.

Bekir emmim bağın bozdu mu bilmem

Küfelerin tek tek dizdi mi bilmem

Elif kız bohçasın düzdü mü bilmem

İpliğin iğneye takardır şimdi.

Naçardır umudu yoktur yarından

Gülmemiş hiç yüzü, dertten sorundan

Bir of çekip, ta yürekten derinden

Sinan sigarasın yakardır şimdi.

Açılır elleri Hakk''ın katına

Yürekler ter temiz benzer altına

Öğle vakti çöküp ardıç altına

Soğanı ekmeğe sıkardır şimdi.

Çalışır yıl boyu gelin, kız, kadın

Feryad etse duyan olmaz feryadın

Kışın yakmak için dağlardan odun

Koşmuştur merkebin çekerdir şimdi.

Istarında dokur çulun torbasın

Kaynar  ocağında yayla çorbasın

Kirli çamaşırın, kirli urbasın

Ninem küllü suyla yıkardır şimdi.

Bilirim zor olur köylerde geçim

Kalmadı diyordu takatim gücüm

Tandırın yakmış sa Zahide bacım

Duramı bacadan çıkardır şimdi.

Tahminim altmışa vardı Ak Hoca

Ne evlat ne de eş gördü Ak Hoca

Hurilerden olsun derdi Ak Hoca

Evlenmemiş halâ bekardır şimdi.

Bilmem daha başka nasıl demeli

İşte böyle bizim köyün ahvali

Duydum çoban olmuş Topal Cumali

Sürünün ardından sekerdir şimdi.

Turani ''yim tacımdır başımda onlar

Hayalimde onlar, düşümde onlar

Bir gölge misali peşimde onlar

Ağaçlar yaprağın dökerdir şimdi,

Baba Ocağı(2005)  Sayfa; 47-48', 'Çıkmıyor yadımdan evim ocağım Anam yollarıma bakardır şimdi. Nemlidir gözleri, buruktur kalbi Yavrum derde bağrın yakardır şimdi. Bir başka ...', ARRAY['Türk Edebiyatı','Şiir','Şair Mustafa Turani']::text[], 8.5, '{"poet":"Şair Mustafa Turani","poet_slug":"sair-mustafa-turani","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/bizim-koy-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uslan Gönül', 'uslan-gonul-sair-mustafa-turani-4npzj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Belki yar duyar sesini

Seslen ki gönül yar gelsin

Giyip aşk elbisesini

Süslen ki gönül yar gelsin.

Yüzünü yara döndükçe

Yanasın gönül yandıkça

Geçen günleri andıkça

Hislen ki gönül yar gelsin.

Her denene kanma artık

Her güzele yanma artık

Daldan dala konma artık

Uslan ki gönül yar gelsin.

Yar düşende gurbet ele

Özlemini getir dile

Özlem yağmurları ile

Islan ki gönül yar gelsin.

Turani''yim otağına

Gonca gülün et bağına

Dolu dizgin aşk dağına

Yaslan ki gönül yar gelsin.

Baba Ocağı (2005)  Sayfa; 165', 'Belki yar duyar sesini Seslen ki gönül yar gelsin Giyip aşk elbisesini Süslen ki gönül yar gelsin. Yüzünü yara döndükçe Yanasın gönül yandık...', ARRAY['Türk Edebiyatı','Şiir','Şair Mustafa Turani']::text[], 8.5, '{"poet":"Şair Mustafa Turani","poet_slug":"sair-mustafa-turani","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/uslan-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-sabahattin-keskin-s5a58', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özlem                                                                                                                                                                                                        Sesin özlem 

 Özlemim sen 

  İçimde düğümü çözülmüş

  Yaban tayları

  Kabına sığmayan

  Ve kirpiklerin 

   Eyeleri eskiten 

   Parmaklık

   Yorgun kalbimin

   Volta attığı avluda

   Ben gözlerinin 

   Muhabbetine müebbet

   Hüküm giymeden

   Kalem kırılmadan

                      26.11.1997 İst.', 'Özlem                                                                                                                                       ...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Keskin']::text[], 8.5, '{"poet":"Sabahattin Keskin","poet_slug":"sabahattin-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ozlem-276-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni rüyalarımdan vur', 'beni-ruyalarimdan-vur-mehmet-solak-ebggd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'vuracaksan eğer

demiş miydim sana hiç

rüyalarımdan: sımsıcak 

kaynayan kan kuyumdan

tek atım kaderimden

rüyalarımdan vur

beni vuracaksan eğer

son seferinde tiril tiril

nefesimden değil ama

kaktüs gölgesi bakışlarımdan

kumul hülyalarımdan hiç

ama hiç

değil dilimden

haydi vur

vuracaksan eğer, rüyalarımdan

esrarî uykularımda şafak sökmeden

kırağı çözmeden, kirpiklerimde

çalımlı kısraklar kişnemeden daha

vur 

rüyalarımdan beni

ne şamanım bozkırda kemikleri tütsüyen

ne mansur ilkin cisminde ölen

şairim ben kalbimle bütün derdim

ömrüm heder olacak nasılsa böyle

ateşle barut arasında

vur beni

rüyalarımdan vur, tek

atımda, yazgıma dokunup şöyle', 'vuracaksan eğer demiş miydim sana hiç rüyalarımdan: sımsıcak  kaynayan kan kuyumdan tek atım kaderimden rüyalarımdan vur beni vuracaksan eğe...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Solak']::text[], 8.5, '{"poet":"Mehmet Solak","poet_slug":"mehmet-solak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/beni-ruyalarimdan-vur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme/sen', 'gitme-sen-mehmet-solak-h3if2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'o da gitti gibi gitme sen

gitmesen,bırakmasan kendini seferî rüyalarda

yazdan kalma lâcivert dokunuşlarla

cengâver süvarilerle başbaşa içinde

dingin yalnızlıklardan uzak

gitme.sarı yalnızlığı bilirsin sen

yalnızlık da seni kâlûbelâdan beri

kime kokar gidersen içindeki karanfil

kimi yakar hançerende boğulan söz/cük/ler

nemli balkonlara çöreklenmiş geceyi mi

o kızargın yanaklarıyla toprağa öpülen

öpüldükçe doğuran başakları mı yoksa

bir faydası olur mu desem ki gitme/sen

gitmese seninle dondurulmuş heveslerimiz

gammaz duruşumuz fettan sesimiz

o koyu sabıkalı gölgemiz

olmaz bilirim gideceksin

sana yer yok bu yılışık fotoğrafta

herkesin  bir masalı var 

karsız kafdağı safran göğü burada

git.tasalanma sen.uğurlar olsun

el sallar su dökeriz ardından

geçmişi çapak geleceği balçık

biz salaş şehirliler', 'o da gitti gibi gitme sen gitmesen,bırakmasan kendini seferî rüyalarda yazdan kalma lâcivert dokunuşlarla cengâver süvarilerle başbaşa içind...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Solak']::text[], 8.5, '{"poet":"Mehmet Solak","poet_slug":"mehmet-solak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gitme-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsun', 'olsun-ugur-aydin-2-wlknn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gidenler yerini bulur...

gidenlere kelam  olsun....

kalanları keder  sarar......

kalanlara selam olsun.....

vade biter zaman dolar...

gidenlere kelam olsun....

gönüllere keder dolar....

kalanlara selam olsun.....

haktan ise ayrılıklar.....

gidenlere kelam olsun.....

gönülere sabır dolar....

kalanlara  selam olsun......', 'gidenler yerini bulur... gidenlere kelam  olsun.... kalanları keder  sarar...... kalanlara selam olsun..... vade biter zaman dolar... gidenl...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olsun-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Gidebilirsen', 'git-gidebilirsen-ramazan-ates-t7ia2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Artık beni sevmez isen,

Bir gün geri dönmez isen,

Asla pişman olmaz isen,

Haydi git, uğurlar olsun.

Sevgim yalan sanıyorsan,

Aldatıldım ben diyorsan,

Başka bir yol arıyorsan,

Haydi git, uğurlar olsun.

Sen beni unutacaksan,

Başkasını bulacaksan,

Onla mutlu olacaksan,

Haydi git, uğurlar olsun.

İyi bak sen gözlerime,

Kulak ver şu sözlerime,

Sözün geçerse gönlüne,

Haydi git, uğurlar olsun.

Ramazan Ateş/Enschede-18.09.1998', 'Artık beni sevmez isen, Bir gün geri dönmez isen, Asla pişman olmaz isen, Haydi git, uğurlar olsun. Sevgim yalan sanıyorsan, Aldatıldım ben ...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/git-gidebilirsen-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al kiraz', 'al-kiraz-mehmet-solak-unddf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '“bir dalda iki kiraz

  biri al biri beyaz”

                            /mış

ol dervişin abdest duası

çoğalan bir hüzün bakışları

elif yalnızlığında: aaah

/kendinden bir yaz(ı) sın sen, beklenen

 yetim baharların son menzili ey oğul

 bu kaçıncı korku bu kaçıncı ümit

 mezamir kokusu dudaklarında

 ağulu bir ilâhi harfsiz seslerden

 yak kandili bekleme. ağarsın çöl

 dökülsün biatı karargın yüzlerin

 bakıver hırkasız sırtlarda 

 kaç sırtlan hırlamakta, yırtlaz

 gecede gözleri  aç/

kırk yaren kırk kandil

her kandil hüseyin

hüseyin: al kiraz

	   B

                   i i

                  r   r

                 i      i

             al         bey

             al           az', '“bir dalda iki kiraz   biri al biri beyaz”                             /mış ol dervişin abdest duası çoğalan bir hüzün bakışları elif yalnız...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Solak']::text[], 8.5, '{"poet":"Mehmet Solak","poet_slug":"mehmet-solak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/al-kiraz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisan', 'nisan-mehmet-solak-wf4b7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'nisan! 

ortanca kızı ilkyazın

bir harf istesem senden satar mısın

hayır ikincisi...eksilmezsin onsuz

yadigâr azabıma keffaretin olsun

onu kendim kıldığım bir koku/ sun

derince bir kâse: nun

ben de bir harf vereyim sana

sırt sırta iki n, istersen

ilk harfim benim senin sonuncun olsun

ben hamdeden sen sırsız aynam

portakalçiçeğim: aylardan

nisan', 'nisan!  ortanca kızı ilkyazın bir harf istesem senden satar mısın hayır ikincisi...eksilmezsin onsuz yadigâr azabıma keffaretin olsun onu ke...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Solak']::text[], 8.5, '{"poet":"Mehmet Solak","poet_slug":"mehmet-solak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nisan-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahtiyar', 'bahtiyar-sair-mustafa-turani-8tf3k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ö

                                               Ve

                                             Zaman

                                            Tarumar,

                                           Fani ömrüm,

                                          Elinden bizar.

                                      Bir günüm bin figan,

                                     Zarar   üstüne  zarar.

                                Yok mu ardımdan ağlayan? 

                                Bana dar gelme de bu diyar.

                               Ey gölge zaman, çekil aradan

                               Benim gölgeler ile ne işim var.

                              Ölümsüzlüğe uçuş vaktidir bu an,

                          Yaşayanlar mutsuz, ölenler se bahtiyar.

                          Yaşayanlar mutsuz, ölenler se bahtiyar

                              Ölümsüzlüğe uçuş vaktidir bu an

                                  Benim gölgeler ile ne işim var.

                                  Ey gölge zaman çekil aradan

                                   Bana dar gelmekte bu diyar

                                    Yok mu ardımdan ağlayan? 

                                            Zarar üstüne zarar

                                            Bir günüm bin figan

                                               Elinden bi zar

                                                Fani ömrüm

                                                  Tarumar

                                                    Zaman

                                                       Ve

                                                         Ö.', 'Ö                                                Ve                                              Zaman                                      ...', ARRAY['Türk Edebiyatı','Şiir','Şair Mustafa Turani']::text[], 8.5, '{"poet":"Şair Mustafa Turani","poet_slug":"sair-mustafa-turani","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bahtiyar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süslü maskeler', 'suslu-maskeler-guler-atas-tzggh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalancı kaçış dönemlerinin

Kandırmaca sı içindeyiz.

Gittiğimiz her yere 

Süslü maskelerimizi götürdük 

Kandırdık kendimizi / başkalarının gözlerinde 

Dünyayı  /maskeli baloya çevirdik.

Kendimizi ayıramadık /Tanıyamadığımız yüzlerden.

Ne kadar benziyoruz artık biri birimize.

Ne kadar sık bakıyoruz aynalara

Ne kadar çok konuşuyoruz aynalara.

Ayna

Söyle bana

Kaç yalancı kaldı/Kendi yüzüyle bakan sana.

Biliyorum

Yalancı bir kaçış sürecindeyiz/

Aynalarda yalan söyler/

Bütün maskelerimi verip eskiciye/

Gerçek yüzümle dolaşacağım/

Aynalar utanmasın diye/.

                                                                19/10/2004', 'Yalancı kaçış dönemlerinin Kandırmaca sı içindeyiz. Gittiğimiz her yere  Süslü maskelerimizi götürdük  Kandırdık kendimizi / başkalarının gö...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/suslu-maskeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Parça', 'bir-parca-kadir-albayrak-7z6gq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O kadar öfke doluyum ki sana

Anlatamam! ..

Seni bin parçaya ayırsam da 

Hırsımı alamam! ..

Fakat; 

Bir parçan kaybolursa

İşte o zaman

Yaşayamam! ....', 'O kadar öfke doluyum ki sana Anlatamam! .. Seni bin parçaya ayırsam da  Hırsımı alamam! .. Fakat;  Bir parçan kaybolursa İşte o zaman Yaşaya...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-parca-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye Yaptın?', 'niye-yaptin-ramazan-ates-xg0lj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Böylemiydi kız kavlimiz? 

Bumuydu bizim vadimiz? 

Yalanmıydı sözlerimiz? 

	Niye yaptın bana niye? 

	Öldürmek mi kastın söyle? 

El ele tutuşarak biz,

Göz gözeyken hep ikimiz,

Ayrılmakmıydı kavlimiz? 

	Niye yaptın bana niye? 

	Öldürmek mi kastın söyle? 

Sade bir sevgimiz vardı,

Aramıza kimler girdi? 

O hayaller yalan mıydı? 

	Niye yaptın bana niye? 

	Öldürmek mi kastın söyle? 

Küçücük bir yuva kursak.....

Çoluk çocuk mutlu olsak.....

Yakışır mı kız ayrılmak? 

	Niye yaptın bana niye? 

	Öldürmek mi kastın söyle? 

Sana artık güle güle,

Seni gömdüm ben sevgimle,

Kardeşimsin bu biline,

	Niye yaptın bana niye? 

	Kaça sattın onu söyle? 

Ramazan Ateş/Enschede-10.06.1997', 'Böylemiydi kız kavlimiz?  Bumuydu bizim vadimiz?  Yalanmıydı sözlerimiz?  	Niye yaptın bana niye?  	Öldürmek mi kastın söyle?  El ele tutuşa...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/niye-yaptin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Ne Bilsin?', 'kim-ne-bilsin-ramazan-ates-0zx3g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hasretinle yandığımı,

Derdin ile dolduğumu,

Seni ne çok sevdiğimi,

Kim ne bilsin ne bilsin? 

Gel deyince gelmiyorsun,

Hiç halimi sormuyorsun,

Belkide hiç sevmiyorsun,

Kim ne bilsin ne bilsin? 

Sen beni öldüreceksin,

Eritip bitireceksin.

Belkide çok seveceksin,

Kim ne bilsin ne bilsin? 

Belki yuva kuracagız,

Çok da mutlu olacagız,

Beraberce öleceğiz,

Kim ne bilsin ne bilsin? 

Ramazan Ateş/Enschede-26.01.1996', 'Hasretinle yandığımı, Derdin ile dolduğumu, Seni ne çok sevdiğimi, Kim ne bilsin ne bilsin?  Gel deyince gelmiyorsun, Hiç halimi sormuyorsun...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kim-ne-bilsin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-cihan-kaya-tuojq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sordular bana; ''Nedir şiir? '',

Dedim; ''Görmeyi bakan bilir! ''.

12.11.2005', 'Sordular bana; ''Nedir şiir? '', Dedim; ''Görmeyi bakan bilir! ''. 12.11.2005...', ARRAY['Türk Edebiyatı','Şiir','Cihan Kaya']::text[], 8.5, '{"poet":"Cihan Kaya","poet_slug":"cihan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/siir-136-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dünya', 'bir-dunya-ramazan-ates-yj2b9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir dünya istiyorum,

Sevginin bol olduğu

Bir gönül istiyorum,

Gönlümün vurulduğu.

Bir düzen istiyorum,

Sevgi ile kurulmuş

Bir sevgi arıyorum,

İnsanlığa mal olmuş.

Bir dünya istiyorum,

İnsanlar mutlu olsun,

Herkese söylüyorum,

Bu savaşlar son bulsun.

Çocukları sevelim,

Dünyaya neşe gelsin,

Sevelim sevilelim,

İstemiyen sevmesin..

Ramazan Ateş/Enschede-13.05.1991', 'Bir dünya istiyorum, Sevginin bol olduğu Bir gönül istiyorum, Gönlümün vurulduğu. Bir düzen istiyorum, Sevgi ile kurulmuş Bir sevgi arıyorum...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-dunya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısırlaşan Döngü', 'kisirlasan-dongu-okan-cil-wflth', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerimi kapatıp,

ruhumun kapısını zorluyorum.

Dahası zorlamaya, zorluyorum kendimi...

Hayat,

Bayat(lamış)  bir iç çekişmelerinden iberettir

çoğu zaman.

Gezdiriyorum düşüncelerimi bazen,

uçsuz uçurumların gölgesinde.

Yükselme dürdüsüyle dolup taşıyor her yanım.

Aşağılara doğru yükselme,

yükseldikçe derinlerle bütünleşme...

Hani gözaltında

işkence görüyormuşcasına baskı altında, 

yorgun da olsam,

''Dayanmalıyım! '' diye inletiyor her yanı

her bir uzvum,

sorgulamaya başladığımda benliğimi...

Kim şuçlu, kim suçsuz? 

kim dost, kim düşman? 

hangisi doğru, yanlış hangisi? ...

Beynimi zorlayan sorularlarla beraber

sürükleniyorum

bilmediğim yerlere.

Yine de kurtulma çabası içindeyim,

yuvarlanırken boşluklara.

Suya düşmüş,

Ya da koca bir hortuma yakalanmış,

üzerine nice notlar iliştirilen 

kağıt parçacıkları gibiyim.

Bu güçlüklere karşı koyamasam da

üzerimdeki yazıların değeri

karşı koymaya zorluyor beni.

''Acı çekmemeliyim.

Sadece özgür olmak istedim...'' diye

bağıran Sartre''ın çığlaklarıyla

bütünleşiyor çığlıklarım.

''Sadece özgür olmak istedim.''

diye haykırıyorum ben de

tüm tabuların suratına.

Adeta bir yankılanma gibi

göründü gözlerime bu paslaşma.

Bomboşluklaki sessiliğin

kulakları tırmalaması ya da...

Açıyorum gözlerimi ara ara

O küçük yarıklardan çağlayan damlalar

bırakıyorum son sözü

her şeyden sonra.

Boğuyorlar ağzımdan çıkmaya çalışan

tüm sözcükleri çünkü.

Yaşlı bir bedevinin

çölde rastladığı bir sahraya

iştahla atılmasının ardından

yaşadığı trajedi gibi.

Yalnız koca bir ''off! '' çıkıyor

dudaklarımı araladığımda,

sigara dumanıyla kol kola.

Zaten tüm iç-dış savaşı günlerinde

iyi yoldaş olmamışlar mıdır? 

Elle tutulur bir şeylerle dönemedim yine

iç gezintilerimin ardından.

Bu bir kısırdöngü! 

Döne döne durur

dura dura döner...

Taa ki bedenimde

kurtçuklar oluşana dek.

başlar, hiç bitmemiş olanlar....', 'Gözlerimi kapatıp, ruhumun kapısını zorluyorum. Dahası zorlamaya, zorluyorum kendimi... Hayat, Bayat(lamış)  bir iç çekişmelerinden iberetti...', ARRAY['Türk Edebiyatı','Şiir','Okan Çil']::text[], 8.5, '{"poet":"Okan Çil","poet_slug":"okan-cil","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/kisirlasan-dongu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerim Özlemişse', 'ellerim-ozlemisse-guzin-eye-dundar-gn5qo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ellerim özlemişse 

şakaklarındaki beyazları

bilmez yolların

bir ömür uzadığını

düşlerimde sen varsın 

dersem her an

inanma yalan

senin benden uzak güzelliğini

düşlerime koyamam', 'Ellerim özlemişse  şakaklarındaki beyazları bilmez yolların bir ömür uzadığını düşlerimde sen varsın  dersem her an inanma yalan senin bende...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ellerim-ozlemisse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buradayım..', 'buradayim-ece-ozbek-ji16l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Buradayım

artık

olmam gereken 

yerdeyim

içindeyim

artık

kendimdeyim

buradayım

artık 

seninleyim', 'Buradayım artık olmam gereken  yerdeyim içindeyim artık kendimdeyim buradayım artık  seninleyim...', ARRAY['Türk Edebiyatı','Şiir','Ece Özbek']::text[], 8.5, '{"poet":"Ece Özbek","poet_slug":"ece-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/buradayim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüş', 'donus-guzin-eye-dundar-sl47b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıllar boyu  ömrümün

çorak  toprağında  ben

yalan sevgilere hep

boşa kürek çekmişim

Tanrının  bahçesinde

yazık  ondan  bihaber

aynı yolları her gün 

tekrar tekrar gezmişim

ne yeşil gözlü doğa

ne kuşlar  kelebekler

bunca  yıl  daha  fazla

kaçamazdı  uzağa

çiçekler  kokusuyla 

sıradan  bir  vazoda

ürkütürdü  gönlümü 

solmaya  başlayınca 

büyülü bir  el beni 

çekti   aldı    doğaya

mucizelerden gün gün

başlıyorum korkmaya

gözlerim yeşillerde

yedi rengi görüyor

gün batımında güneş

mehtaba  gülümsüyor.', 'Yıllar boyu  ömrümün çorak  toprağında  ben yalan sevgilere hep boşa kürek çekmişim Tanrının  bahçesinde yazık  ondan  bihaber aynı yolları ...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/donus-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Hayalimsin', 'sadece-hayalimsin-munevver-duver-waujp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karaoğlan..

Uzaklarda.

Ne durumdasın..

Bana yakın

Beynimdesin..

Alaylı bakışlarınla

Kalbimin köşesindesin.

Kavuşmanın en ucunda.

Sen sadece beynimdesin..

Hayalimsin....

Ulaşılmazımsın..

16-11-2005/ saat:10.57

Güzelyalı/ADANA

Çarşamba', 'Karaoğlan.. Uzaklarda. Ne durumdasın.. Bana yakın Beynimdesin.. Alaylı bakışlarınla Kalbimin köşesindesin. Kavuşmanın en ucunda. Sen sadece ...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sadece-hayalimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Başımın çaresine bakarım', 'ben-basimin-caresine-bakarim-gencer-bakan-3etu6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kafana takma sözlerimi boş ver 

ardına bakma hiç gidersen eğer 

yaş olurum yüreğine akarım 

ben başımın çaresine bakarım...

gencer bakan', 'kafana takma sözlerimi boş ver  ardına bakma hiç gidersen eğer  yaş olurum yüreğine akarım  ben başımın çaresine bakarım... gencer bakan...', ARRAY['Türk Edebiyatı','Şiir','Gencer Bakan']::text[], 8.5, '{"poet":"Gencer Bakan","poet_slug":"gencer-bakan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ben-basimin-caresine-bakarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir resim (rahmetli babamın hatırasına)', 'bir-resim-rahmetli-babamin-hatirasina-cem-cagman-q4jph', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'boynu bükük hüzünlü resmin solmasın diye

görmek istemesem bile seni o halinle

bıraktığın o resim bana senden hediye

beni üzmek için biraktığın belli o resmi

hüzünlü olarak boyun bükmüşsün

bakmayada doyamıyorum ben o resmine 

çünkü ağlayıp gözyaşı dökmüşşün', 'boynu bükük hüzünlü resmin solmasın diye görmek istemesem bile seni o halinle bıraktığın o resim bana senden hediye beni üzmek için biraktığ...', ARRAY['Türk Edebiyatı','Şiir','Cem Çağman']::text[], 8.5, '{"poet":"Cem Çağman","poet_slug":"cem-cagman","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-resim-rahmetli-babamin-hatirasina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzun veda', 'uzun-veda-berrak-su-vm8cf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tarifsiz, müzmin yolculuklardı,

Varılası, inadına bilinmezlere.

Gemiler, alın beni,

Lodos akşamlarında.

Titretin fakir bulutlar,

Kara küsmüş kardelenlerimi.

Ayak üstü düşmüş iki kafadar,

Biri ben, 

Biri benden beter.

Gemiler, alın beni,

Kıyısına yaşamın,

Bir tek soluk yeter..

Berrak Su', 'Tarifsiz, müzmin yolculuklardı, Varılası, inadına bilinmezlere. Gemiler, alın beni, Lodos akşamlarında. Titretin fakir bulutlar, Kara küsmüş...', ARRAY['Türk Edebiyatı','Şiir','Berrak Su']::text[], 8.5, '{"poet":"Berrak Su","poet_slug":"berrak-su","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/uzun-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı Gül', 'kirmizi-gul-hamit-pala-ls09y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ulaşmaktı tek dileğim sana ey kırmızı gül! 

Sadece seninle olabilmek

Sana kavuşmaktı.

Ezdiğim kır çiçekleriydi 

Birer birer bilmeden

Bilerek papatyaydı ezilen...

Ne boş hevesmişsin meğer sen kırmızı gül! 

Asla olmayacak bir dua

Sonsuz ümitler gibi...

Yaşadığım sensizlikti seninle

Her gün haberli habersiz

Bir ayrılıktı yaşanan...

06.12.1993 Bursa', 'Ulaşmaktı tek dileğim sana ey kırmızı gül!  Sadece seninle olabilmek Sana kavuşmaktı. Ezdiğim kır çiçekleriydi  Birer birer bilmeden Bilerek...', ARRAY['Türk Edebiyatı','Şiir','Hamit Pala']::text[], 8.5, '{"poet":"Hamit Pala","poet_slug":"hamit-pala","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kirmizi-gul-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Üzerine Şiirce Konuşmalar', 'ask-uzerine-siirce-konusmalar-metin-yalti-qtz0q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk Üzerine Şiirce Konuşmalar 

emin ol 

sevmek daha da güzel 

sevilmekten 

vazgeçilmez sevmekten 

insanı sevmek 

bir kişiyi sevmekten geçer 

her an 

her şeyi 

onunla paylaşmak istemek 

hep sürer, 

adı değişir bir zaman sonra 

dış etkenlerle 

riyakarlıktır bu aslında 

ama dünyanın yadsımadığı 

hep birlikte onay verdiği 

tek riyakarlıktır. 

mutlu eder insanı sonuçta.. 

sevgi de yada riya 

onun sürdürülmesi 

tarafların hoşgörüsüyledir 

ancak 

taraflar bu konu üzerinde 

durup düşünmeliler zira… 

hoşgörünün sınırı 

karşıdakinin anlayışıncadır. 

yaşadıklarımız farklı 

deneyimlerimizde desen de 

tez, antitezini oluştur ya 

farklılıklarımız 

farklı bir aşk üretir sadece 

hadi nazlanma evet de 

sana önerilen aşka 

yaşanacak aşklardan 

daha büyük olacak 

bu aşk 

belki de… 

aşka 

insanlara 

duygulara 

kısaca inan 

konusu aşksa her şeye 

şefkatli ol, 

karşılaştığın her kes 

zor bir mücadele veriyor: 

sevilince şımarmak geçer içimden 

derdin her defasında 

öğrenmelisin ki seven için 

sevdiğinin şımarıklığını 

yaşamaktır güzel olan… 

biliyor musun? 

en kötüsü 

eğer ki reddeder 

inancın yitmesi dersen buna 

aşkolsun derim sana 

aşk olsun 

sadece… 

16/11/2005', 'Aşk Üzerine Şiirce Konuşmalar  emin ol  sevmek daha da güzel  sevilmekten  vazgeçilmez sevmekten  insanı sevmek  bir kişiyi sevmekten geçer ...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/ask-uzerine-siirce-konusmalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgörüp Sevmek', 'hosgorup-sevmek-guzin-eye-dundar-48x6z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmek...

alışılmışın dışında

gören bir yürekle

gözleyip kusurları

hoş görüp sevmek

güzel bir evrenin

koyu karanlığında

bulabilmek aydınlığı

öylece sevmek....', 'Sevmek... alışılmışın dışında gören bir yürekle gözleyip kusurları hoş görüp sevmek güzel bir evrenin koyu karanlığında bulabilmek aydınlığı...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hosgorup-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayak', 'dayak-umut-gul-awi3i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çıktı geldi cennetten

Kondu alimin eline 

Alimin gülleri bitiverdi yüzümde

Nush ile yetinmedik ettiler tekbir

Tekbir de sökmedi

Buyurdu Hazret hakları kötekdir

Etmedik  mahrum avradı 

Karnında sıpadan

Sırtında sopadan

Neyleyelim el mecbur

Böyle gördük atadan

Desturumuzdu mektepte falaka

Asta dayak atmaktı askerde fiyaka

Meşhurdur bizde Osmanlı tokadı

Bu yüzden hep anamızı sorar mahkemede kadı

(Haydi gençler yine iyisiniz Avrupa Birliğine giriyoruz)', 'Çıktı geldi cennetten Kondu alimin eline  Alimin gülleri bitiverdi yüzümde Nush ile yetinmedik ettiler tekbir Tekbir de sökmedi Buyurdu Hazr...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dayak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmeden Ölmek', 'olmeden-olmek-guzin-eye-dundar-jks66', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstanbul derler

gölge  vurur  yüzüme

düşmek  ister

gözyaşlarım  düşemez

unutmak

tek mutluluğunu  gönlümün

unutulmaz...

yaşamak bir hiç gibi

günden  güne

ölmeden-ölmek......', 'İstanbul derler gölge  vurur  yüzüme düşmek  ister gözyaşlarım  düşemez unutmak tek mutluluğunu  gönlümün unutulmaz... yaşamak bir hiç gibi ...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olmeden-olmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk Anaları', 'turk-analari-husnu-avci-nc86v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tanrı dağlarını bilirmisiniz hani geldiğimiz yer 

İşte orda başlar analarımın akan göz yaşları 

Oradan beri akar yiğitlerin kanları 

Tek amaç ise vatandır huzur içinde yaşayacak

Nedendir bilinmez o günlerden beri sataşırlar bize

Medeniyet görmemiş milletler dahası açkalmış itler 

Kızdınız demi bu lafıma ikibin sene şehit doğurduk 

Biz bu vatana bide böyle bak bu anlattığıma 

Şamanisttik baştan yaranamadık barbarsınız dediler 

Müslüman olduk adaletle yönettik ve yaşadık yine yaranamadık 

Şimdide tekrar inancımızı bozmaya çalışıyolar açıkçası kaşınıyolar

Olmuyo bozamıyolar terör örgütüne destek veriyolar 

Kırkbeşbin şehit verdik siz haksızssınız diyolar 

Benim anam ağlamış umrundamı şerefsizlerin

Bana kızan varsa bi düşünsün bu türk analarının 

Ne günahı var ikibin senedir kurban doğuruyolar

Ben düşünüyorum ve ağlıyorum dayanamıyorum 

Ya oğlu şehitler nasıl dayanır düşünsünler 

Bütün türk analarının ellerinden öpüyorum 

Cennet anaların ayakları altındadır O analarda türk anaları 

Biliyor ve iman ediyorum 

NOT:

ANALARIMIZIN HAKKINI ÖDEYEMEYİZ AMA Bİ SERZENİŞTE BENDEN İŞTE', 'Tanrı dağlarını bilirmisiniz hani geldiğimiz yer  İşte orda başlar analarımın akan göz yaşları  Oradan beri akar yiğitlerin kanları  Tek ama...', ARRAY['Türk Edebiyatı','Şiir','Hüsnü Avcı']::text[], 8.5, '{"poet":"Hüsnü Avcı","poet_slug":"husnu-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/turk-analari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım kalmış dörtlükler (rahmetli babamın anısına)', 'yarim-kalmis-dortlukler-rahmetli-babamin-anisina-cem-cagman-qxh07', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tüm acılarımı içime attım

zannetme gece gündüz hasretinle yandım

geri döner diye bekleme beni

ben o sayfayı çoktan kapattım

*

benim senden beklediğim sadece insanlık

başka bir şey istemiyorum artık

ikimizin yaşıda birhayli yaklaştı 

devam ederse huyların bana karşı

sonumuz yine karanlık

seni çocuk gibi avuttum nuriye

beni kendinden soğuttun nuriye

beni uykudan uyartma sakın

önümüze değil sonumuza bakın

onada sen bir karar ver nuriye

*

unut unut beni unutta desen

unutamam seni bir gün gelirsen

maziide kalıyor geçen o günler

acırmısın bana bir gün ölürsem

takarsam başıma o kara tacı

yaşamak tatlıda ölmekmi acı

birbirimize olmuşuz iki yabancı

selam ver mahşerde beni görürsen

****

yorgun adımlarla geçtin kapımdan

bir kere bana dönüp bakmadın

gül dolu balkonun parmaklığından

bir demet gülde atmadın

sahilde dalgalar vururken kuma

masum bir bakışla girdin uykuma

yıllar boyu yanan hasta ruhuma

bir tebessüm edipte neşe katmadın

********

geçen her acı günümüz ömürden gidiyor

bıraktığın resimde beni kahrediyor

çünkü çok güzeldin benziyordun huriye

istersen o resmide bendel al nuriye

******

içimden çıkmayan acı bir sorusun

tanrım sade seni değil cümlemizi korusun

sen yaradanın ilahi bir nurusun

bırakın çiçekleri dallarında kurusun

******

rahmetli babam Mümşat Çağman tarfından yazılmış  dörlükler', 'tüm acılarımı içime attım zannetme gece gündüz hasretinle yandım geri döner diye bekleme beni ben o sayfayı çoktan kapattım * benim senden b...', ARRAY['Türk Edebiyatı','Şiir','Cem Çağman']::text[], 8.5, '{"poet":"Cem Çağman","poet_slug":"cem-cagman","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/yarim-kalmis-dortlukler-rahmetli-babamin-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seslendim sana', 'seslendim-sana-halil-colak-0dyft', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağmurlarda ıslandım sevdan yüzünden

İliklerime kadar ıslandım seni beklerken 

Seni görünce titremem geçerdi aniden

Bir ateş basardı bütün bedenimi

Kalbimin çarpıntısı duyulurdu

Çok uzaklardan

Gönlümde çiçekler açardı

Renk renk demet demet

Bir sevda kokusu sardı etrafı

Çiçeklerden daha güzel kokardı

Mest ederdi beni

Güzel kokun sarhoş ederdi

Kendimden geçerdim

Uçar giderdim mutluluklar dünyasına

Bu mutluluk uzun sürmezdi

Uyandığımda rüyadan

Mutluluğum biterdi

Çünkü sen yok olurdun yanımdan

cananım sevdiğim sevgilim benim

  

Halil Çolak 16.11.2005 Ankara', 'Yağmurlarda ıslandım sevdan yüzünden İliklerime kadar ıslandım seni beklerken  Seni görünce titremem geçerdi aniden Bir ateş basardı bütün b...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seslendim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Bir Kentten Mektup Var', 'kucuk-bir-kentten-mektup-var-guzin-eye-dundar-ulvep', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bu kentin yalıboyları 

üzgün bakar

belliki bir  sevdiği

beklediği var

gurup öksüz

güneş dul

bekleyen her gece

sabahı bulur

hep yalnızlıktan yana  şarkılar

belki birazdan inecek yağmur

deniz  sessiz

gök sevdalı

bir rüzgar 

hoyratça okşar saçlarımı

senden habersiz

ne yollar  dayanır mahzunluğuma

ne eller güler

bilirsin sevdiğim

İnsan bir kez sever.', 'bu kentin yalıboyları  üzgün bakar belliki bir  sevdiği beklediği var gurup öksüz güneş dul bekleyen her gece sabahı bulur hep yalnızlıktan ...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kucuk-bir-kentten-mektup-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dualarla seslendim sana', 'dualarla-seslendim-sana-halil-colak-06mv2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dolularla seslendim sana

Yağmurlarda ıslandım sevdan yüzünden

İliklerime kadar ıslandım seni beklerken 

Seni görünce titremem geçerdi aniden

Bir ateş basardı bütün bedenimi

Kalbimin çarpıntısı duyulurdu

Çok uzaklardan

Gönlümde çiçekler açardı

Renk renk demet demet

Bir sevda kokusu sardı etrafı

Çiçeklerden daha güzel kokardı

Mest ederdi beni

Güzel kokun sarhoş ederdi

Kendimden geçerdim

Uçar giderdim mutluluklar dünyasına

Bu mutluluk uzun sürmezdi

Uyandığımda rüyadan

Mutluluğum biterdi

Çünkü sen yok olurdun yanımdan

Sevgilim benim

  

Halil Çolak 16.11.2005 Ankara', 'Dolularla seslendim sana Yağmurlarda ıslandım sevdan yüzünden İliklerime kadar ıslandım seni beklerken  Seni görünce titremem geçerdi aniden...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dualarla-seslendim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Sevdası', 'gul-sevdasi-ufuk-bayraktar-xpjew', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seni gördüm bu sabah durakta

gözyaşı şarabından içtim yine.

kalbimi kırık bir kadeh gibi şerefine kaldırıp

kendimden geçtim yine.

bakmak istedim  gülen gözlerine; 

bir ateş yaktı, donup kaldı bakışım.

ah bir bilsen, bu kaçıncı yakarışım! 

radyodaki ses benden yana

o hazan şarkıyı söyler

sesim ulaşırsa ben de söyleyeyim.

bir isimsiz sevda var bu yürekte; 

sen ''gonca'' de, ben ''gül'' diyeyim.

korkma, unuturum seni belki bir gün

nerden bileyim...

********************************************

*''sen goncasın gül diyemem

çok severim söylemem

sorma güzel ne olursun''  şarkısından esinlenilerek yazılmıştır.', 'seni gördüm bu sabah durakta gözyaşı şarabından içtim yine. kalbimi kırık bir kadeh gibi şerefine kaldırıp kendimden geçtim yine. bakmak ist...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gul-sevdasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıralar (rahmetli babamın anısına)', 'hatiralar-rahmetli-babamin-anisina-cem-cagman-xastb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yalan oldu sözlerim hep yalan

hatıramızdır mazide kalan

sen değilmisin kalbimi çalan

geçen günlerle sende oyalan

nice yıllar ggeçsede aradan

bende biri değilim sıradan

kavuşturursa bir gün yaradan

sanki ben oldum seni aldatan

unutma sakın geçen günleri

meskenmi tuttun gurbet elleri

durmak bilmiyor gözüm selleri

durdurur belki birgün yaradan

karanlık gece olmuyor seher

buluşacaksak ahirette eğer

işte o zaman ölmeye değer

bu dünya yalancıymış meğer

yaşamak tatlıda ölmek mi zor

senki onu yaşayanlara sor

içimdeki ateş yanan o kor

bu derdi çeken candan bıkıyor

dağlar dayanmıyor çektiğim derde

bülbül sesi dinlerdik seherde

baykuşlar ötüyor şimdi seherde

ararım sevgilim nerdesin nerde', 'yalan oldu sözlerim hep yalan hatıramızdır mazide kalan sen değilmisin kalbimi çalan geçen günlerle sende oyalan nice yıllar ggeçsede aradan...', ARRAY['Türk Edebiyatı','Şiir','Cem Çağman']::text[], 8.5, '{"poet":"Cem Çağman","poet_slug":"cem-cagman","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hatiralar-rahmetli-babamin-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret (rahmetli babamın anısına)', 'hasret-rahmetli-babamin-anisina-cem-cagman-q496j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gittin gideli sanma unuttu

her günüm ağlamakla geçiyor

verdiğin sözler bana umuttu

bir ömürde beni böyle biçiyor

ayrılsak ta ben küsmedim sana

duyursam feryadımı cihana

gelecek dedim ben seni sorana

benim günlerimde böyle geçiyor

hep geçecekmi feleğin ahı

uykusuz ediyorum sabahı

affet sen işlediğim günahı

ettiğim dualarda geçmiyor

hasretine ben dayanamaz oldum

seni gelip gidenlere sordum

sanma derdinden uyku uyudum

geçen her yılda bizi içiyor

gelince su döksem ayağına

buseler kondursam dudağına

düşürdün beni feleğin ağına

günlerim hayalinle geçiyor', 'gittin gideli sanma unuttu her günüm ağlamakla geçiyor verdiğin sözler bana umuttu bir ömürde beni böyle biçiyor ayrılsak ta ben küsmedim sa...', ARRAY['Türk Edebiyatı','Şiir','Cem Çağman']::text[], 8.5, '{"poet":"Cem Çağman","poet_slug":"cem-cagman","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hasret-rahmetli-babamin-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık (rahmetli babamın anısına)', 'ayrilik-rahmetli-babamin-anisina-cem-cagman-n5muc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çok beklettin beni dönde gel artık

gönlüm seni gözlerimden soruyor

takvimden bir yaprak daha koparttık

bu gündemi sensiz akşam oluyor

ne olur bir haber göndersen bana

verdiğin o süre çoktan doluyor

dayanamazdım bir yokluğuna

bıraktığın her şey öyle duruyor

halimi düşünde karar ver artık

sensiz geçen her gün bir yıl geliyor

unutma mazide neler bıraktık

deme o günler mazide kalıyor

********

her gün

sormayın derdimi söyleyemem

yazmaz oldu elimde kalem

vermesende uzaktan selam

aç kucağını bana bir gün

ne bahçem kaldı nede korum

tüm sevenlerden soruyorum

bende sevgili arıyorum

barışalım ne olur bir gün

inanılmazmı yad ellere

hasret kaldım geçen günlere

bülbülde konmadı güllere

seninle ayrıldığımız gün

değil kader Allah yarattı

böylemidir sevenin bahtı

gözyaşlarım içime aktı

akıtma göz yaşımı hergün', 'çok beklettin beni dönde gel artık gönlüm seni gözlerimden soruyor takvimden bir yaprak daha koparttık bu gündemi sensiz akşam oluyor ne olu...', ARRAY['Türk Edebiyatı','Şiir','Cem Çağman']::text[], 8.5, '{"poet":"Cem Çağman","poet_slug":"cem-cagman","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ayrilik-rahmetli-babamin-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Z Raporu', 'z-raporu-piranli-zaza-xbmjx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yatıyor yatakta, 

Herkes ayakta; 

Okuyor Fatiha

Garip ruhuna.

Gözünde adeta

Bir film şeridi; 

Devirdiği yıllar,

Deviren yıllar.

Kendisi yatakta; 

Herkes ayakta,

Alıyor hayatın 

''Z Raporu''nu...

13.11.2005

Bolu', 'Yatıyor yatakta,  Herkes ayakta;  Okuyor Fatiha Garip ruhuna. Gözünde adeta Bir film şeridi;  Devirdiği yıllar, Deviren yıllar. Kendisi yata...', ARRAY['Türk Edebiyatı','Şiir','Piranli Zaza']::text[], 8.5, '{"poet":"Piranli Zaza","poet_slug":"piranli-zaza","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/z-raporu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Azgın Fillere Kapıldı', 'en-azgin-fillere-kapildi-kamil-at-e9e39', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şerefsizin dışında şerefli yaşarken 

Bedenim çamurlu sellere kapıldı

Yakamdan tutarken bütün Cahiller

Özgür kuş gibi yellere kapıldı.

Bizim insanlıksa kendini satmış

Bunca dağ bulup bedeni dayatmış

Çirkefi sevmiş güzelliğe çatmış

Fazla karanlık illere kapıldı.

Avcı değildir elinde keskin kama

Yiğitlerin vücudunda var yama

Dedim ki farenin sesine oynama

İnadıyla en azgın fillere kapıldı.

Nice kafadan boş ses yükselir

Berbat fikirler kuşak bitince düzelir

Şerefsizler hileyle zirveye yücelir

Geldi de bizim dillere kapıldı.

Cahiller azıyor güveni yerinde

Çoğaldılar hakkım hangi birinde

İnsanın düşüncesi birazcık derinde 

Öyle kanlı dikenli tellere kapıldı.

İnsan dedim, nadan para getirdi

Kişiliği yoktu olanınıda yitirdi

Kendini Kamil At güzelliğe batırdı

Hayli boyanmış güzellere kapıldı.', 'Şerefsizin dışında şerefli yaşarken  Bedenim çamurlu sellere kapıldı Yakamdan tutarken bütün Cahiller Özgür kuş gibi yellere kapıldı. Bizim ...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/en-azgin-fillere-kapildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durgun Sularda', 'durgun-sularda-guzin-eye-dundar-37m7b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneş in  yorulup

solduğu  anda

en  durgun sularda

sığ  kıyılarda

takılıp  kalmışım

can  noktasında

ne  kalmak  elimde

ne gitmek mümkün

bulutlar  çözülüp 

deysin  tenime

gölgeler  girmesin

sevda   evime

gitmek  tek dileğim

kalmak  yerine

ne kalmak  elimde 

ne gitmek mümkün...', 'Güneş in  yorulup solduğu  anda en  durgun sularda sığ  kıyılarda takılıp  kalmışım can  noktasında ne  kalmak  elimde ne gitmek mümkün bulu...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/durgun-sularda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nar Ekşi Geceler', 'nar-eksi-geceler-bekir-mutlu-gokcesu-26hkt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nar ekşi gecelerde

Dökülür sırlarım birer birer

Aynada eski ben, senmişim

Bir bakmışım benmişsin...

Sonra karışır siluetler

Tanıdık, tanımadık çehreler

Çoğaldıkca çoğalır resimler

Seslenmek isterim yoksun

Ağlamak isterim yokum

Bir biz yiteriz nar ekşi gecelerde

Belki de çoğalırken içimizde

Ama yokuz işte, yokuz ikimiz de...', 'Nar ekşi gecelerde Dökülür sırlarım birer birer Aynada eski ben, senmişim Bir bakmışım benmişsin... Sonra karışır siluetler Tanıdık, tanımad...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nar-eksi-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-gulseren-onay-mxdy8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevilmenin yıllarca hayallerini kurdum

Elbet bir gün severim diye bekledim durdum

Gün oldu isyan edip başımı taşa vurdum 

Tutamadım ucundan uzaktan güldü  sevgi 

Çabuk geçti bu ömür, düşlerin rengi soldu

Yalnızlık gecelerde, bana arkadaş oldu.

Sonsuz sevgi ararken, saçlarım akla doldu,

Tam her şey bitti derken,seninle geldi sevgi..', 'Sevilmenin yıllarca hayallerini kurdum Elbet bir gün severim diye bekledim durdum Gün oldu isyan edip başımı taşa vurdum  Tutamadım ucundan ...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgi-221-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebebim Olsun', 'sebebim-olsun-mustafa-alpaydin-k2kgm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönül seni sevmiş ayrılmaz senden 

Kesilse kan akmaz sararmış tenden 

Ruhum isyan etse çıksa bedenden 

İsterim ki sevdan sebebim olsun. 

Hasretin acıdır yüreğim yanar 

Halimi görenler mecnunum sanar 

Yaram derindedir sol yanım kanar 

İsterim ki sevdan sebebim olsun. 

Ferhat Şirin için deldi dağları 

Sevda hasta etti nice sağları 

Viraneye döndü gönül bağları 

İsterim ki sevdan sebebim olsun. 

Kesilir nefesim tutmuyor elim 

Titriyor dizlerim doğrulmaz belim 

Sana ah etmeye varmıyor dilim 

İsterim ki sevdan sebebim olsun.', 'Gönül seni sevmiş ayrılmaz senden  Kesilse kan akmaz sararmış tenden  Ruhum isyan etse çıksa bedenden  İsterim ki sevdan sebebim olsun.  Has...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Alpaydın']::text[], 8.5, '{"poet":"Mustafa Alpaydın","poet_slug":"mustafa-alpaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sebebim-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HapishaneGünleri (rahmetli babamın anısına)', 'hapishanegunleri-rahmetli-babamin-anisina-cem-cagman-6yt1f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kızılcaörende içtik rakıyı yedik kebabı

kasaba da verdik ağır ağır hesabı

kimidi bilmiyoruz bu işlerin sahabı

işte maceraya burdan başladık a dostlar

avrupadan geldik vatana izne

bizde uyduk şu cemilin sözüne

sana güveniyordum lan ikram

biber ektin sen gözümüze

kızılcaörene vardık kestiler seyisi

böyle olur insanların iyisi

her yerden çıkıyo şu tekkenin reisi

kaderi öyle imiş ona ne deyim

katı yayaylada süt ile viskiyi içtik

fereske hacıköyünden geçtik

sonunda hapishaneye düştük

kaderimiz böyle imiş kime ne deyim

savcımızda geldi nasihat eyledi

sabahleyin peynirli börek yaptıracağını söyledi

peyniride yokmuş ikramdan istedi

şansımız yokmuş kime ne diyek

ikram derki yaşım kırkiki boyum bir seksen

ah ulan mesut ben nerelere gitsem

şu hakim ekremin ettiğini bir bilebilsem

hakimde düşmanmış kime ne deyim

sıtkı derki ben o viskiyi içmez olaydım

bozulsa rabamızda yolda kalaydım

ikramda ben hayırlısıyla evime varaydım

başımıza bu işlerde gelecekmiş a dostlar

mümşat ekrem arkadaşlar bizi yolda ektiler

kasabaya girince polisler bize silah çektiler

anladık ki cebimizdeki marka göz diktiler

ne yazıkki emekleri boşa çıktı dostlar

bizde uğradık bir hezimete

bir şeyler oldu şu azamete

dilekçesi ile başvurdu hükümete

hükümette bize bakmaz kime ne deyim

doktor murat geldi tansiyonunu ölçtü

arkadaşı mesut kendinden geçti

şu sıtkıda mümşatın holtasını kesti

hapishanede böyle imiş kime ne deyim

ibrahim derki nerde kaldı kulübüm

iflah olmam ben bu dertten ölürüm

bir daha düğüne gidersem yüzüme tükürün

düğünün günahı yok kime ne deyim

neyimize idi kızılcaörenin düğünü

dostlarımız üzülür düşmanlarımız öğünü

analarımız evde evlat diye döğünü

kaderimiz böyle imiş anne ne deyim

yedi arkadaş hapishanede düşünür

pertekli hilmide yemeğimizi pişirir

şu azamet ne yapacağını şaşırır

kaderimiz böyle imiş kime ne deyim

en sonunda çifte avukatlar geldiler

suçsuz olduğumuzu onlarda bildiler

tahliye dilekçesini elimize verdiler

bakalım sonuç ne olacak a dostlar', 'kızılcaörende içtik rakıyı yedik kebabı kasaba da verdik ağır ağır hesabı kimidi bilmiyoruz bu işlerin sahabı işte maceraya burdan başladık ...', ARRAY['Türk Edebiyatı','Şiir','Cem Çağman']::text[], 8.5, '{"poet":"Cem Çağman","poet_slug":"cem-cagman","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/hapishanegunleri-rahmetli-babamin-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efsunluyum', 'efsunluyum-sefer-yesilyurt-5p1o8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'efsunluyum.... 

yolu yitik bir göçmen 

saman kağıda meftun 

.......................bir kurşun kalem 

üç beş pile 

..........sonradan yapıştırılmış yüzüme 

................................................yazanım yoktur... 

ve 

......sahipliğim 

..........sahipsiz kalmış üç beş dize 

......................bir cami avlusunda bulduğum', 'efsunluyum....  yolu yitik bir göçmen  saman kağıda meftun  .......................bir kurşun kalem  üç beş pile  ..........sonradan yapıştı...', ARRAY['Türk Edebiyatı','Şiir','Sefer Yeşilyurt']::text[], 8.5, '{"poet":"Sefer Yeşilyurt","poet_slug":"sefer-yesilyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/efsunluyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gamzende ki sır', 'gamzende-ki-sir-elazigli-mustafa-kaya-3w653', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ahh o gülen yüzün

ya gamzende ki sırrın

sevimli küçük bir balık gibi

ne demeli yüzüne..

ya..! nereye saklayacağın

telaşındaki o masum arayış,

ve mutlu bir çehre bırakış

günlüğünün sende…. 

Mustafa kaya

17.11.2005 / Çengelköy

www.mustafakaya.net', 'ahh o gülen yüzün ya gamzende ki sırrın sevimli küçük bir balık gibi ne demeli yüzüne.. ya..! nereye saklayacağın telaşındaki o masum arayış...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gamzende-ki-sir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzülüyorum', 'uzuluyorum-abdulvahap-ates-gflpt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben kendimi şair sanıp yazdığım,

Dizelere bakıp üzülüyorum.

Faydasızı iğne iğne kazdığım,

Yıllarıma bakıp üzülüyorum.

Umut yoğurmayan bileklerime,

Menzili  bulmayan dileklerime,

Değer üretmeyen emeklerime,

Zahmetime takıp üzülüyorum', 'Ben kendimi şair sanıp yazdığım, Dizelere bakıp üzülüyorum. Faydasızı iğne iğne kazdığım, Yıllarıma bakıp üzülüyorum. Umut yoğurmayan bilekl...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Ateş']::text[], 8.5, '{"poet":"Abdulvahap Ateş","poet_slug":"abdulvahap-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uzuluyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şelale', 'selale-elazigli-mustafa-kaya-7dips', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'uzakta ki yalnızlığın

sık sık dalışların 

ve,

seni bekleyen o mavi dünya

yağmur sonrası kokuları gibi

senden içime akan

küçük bir şelale..

ve ne zordur

hüznün vekarı.

oysa,

bir tebessümüne

dünyalar değer.

o sessiz ağlayışların

bir kuyudan gelir gibi.

maviye tutkun dünyan

düşer aklıma

içimde

sessiz iniltiler.

bir yalnızlık rüzgarı

eser de eser.

sabırla geleceğin yer elbet

yeşil ve sonsuz bir cennet…

Mustafa kaya

17.11.2005 / fatih

www.mustafakaya.net', 'uzakta ki yalnızlığın sık sık dalışların  ve, seni bekleyen o mavi dünya yağmur sonrası kokuları gibi senden içime akan küçük bir şelale.. v...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/selale-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavaş', 'yavas-orhan-eren-uncu-dgy7a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bakma öyle

Kocaman

Yeşil gözlerinle

Bu yürek yorgun

Çok güneşle battı

Dur

Dalgalanmasın 

Buğday rengi saçların

Yüreğime esiyor

Esin, esin

Çok yapraklar döktü

Yavaş 

Tutma beni

Pamuk, pamuk

Bu eller aşk’a yorgun

Nasırlı, incinmiş

Çok yağmurda eridi

Bekle

Sarılma bana candan

Nefesim kesilir

Sıcak, sevecen

Bu yürek yıpranmış

Yorgun

Çok üşüdü

Kırılır

Yavaş

16.11.2005', 'Bakma öyle Kocaman Yeşil gözlerinle Bu yürek yorgun Çok güneşle battı Dur Dalgalanmasın  Buğday rengi saçların Yüreğime esiyor Esin, esin Ço...', ARRAY['Türk Edebiyatı','Şiir','Orhan Eren Uncu']::text[], 8.5, '{"poet":"Orhan Eren Uncu","poet_slug":"orhan-eren-uncu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yavas-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seneler Geçer Nasılsa', 'seneler-gecer-nasilsa-ahmet-altintas-su6m2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen gelmesen ne olur sanki

Ezbelemiştim geleceğn vakti inan ki

Nasılsa geçer zaman durdurmak mümkün mü sanki

Elveda demeden gitmek istedin belki

Lütfunla ayrılık gözyaşını birlikte dökelim isterdim

Elveda ayrılmalıyız desende hep yüreğimde hissedeceğim

Razıyım kavuşamasamda sağlık haberin bileyim

Gselmesen ne olur canım Meleğim

Elveda ben gidiyorum demesen ne olur Kardelen Çiceğim

Çok özleyip haretinle kavrulsam ne olur Biriciğim

Ezberledi o güzel gözlerini nakış nakış yüreğim

Razı olamaz alışır dökerken gözyaşlarını yüreğim

Ne olur bak gözlerime bırakıp gitme

Alışamam çekemem sensizliği cansın ruhum ve yüreğime

Suayan gül misali su veriyosun benliğime

Isırırken dudağımı akmasın gözyaşım derken kan damlar gözlerime

Lal olur taş bağlarken sensizliği anlatamam yüreğime

Susamam cevap bulamazken kendime

Acı çekmeye razıyım yeter hüzün değmesin Meleğime....', 'Sen gelmesen ne olur sanki Ezbelemiştim geleceğn vakti inan ki Nasılsa geçer zaman durdurmak mümkün mü sanki Elveda demeden gitmek istedin b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altıntaş']::text[], 8.5, '{"poet":"Ahmet Altıntaş","poet_slug":"ahmet-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seneler-gecer-nasilsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürü Köylü Çocuğu', 'yuru-koylu-cocugu-melih-coskun-e57sx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yürü köylü çocuğu 

Yürü ki bu dağ senindir 

Okulun dağlar ardında bırakılmışsa 

Mevsim kışsa 

Donup kalmak varsa 

Kuytuluk boğazlarda

Öğrenmek adına abc sini hayatın, 

Ölmek varsa 

Hayatı öğrenmek adına, 

Yürü ki bu dağ senindir 

Bu yollar senin...

Yaz öğretmenim 

Bu kara tahta senindir 

Siyah üzerine ak bir şeyler yazmalısın 

Umudu çizmelisin tebeşirinle 

İnanmışsan iyiye, doğruya, güzele

Savunmuşsan inandıklarını

Sürgündeysen 

Yaz öğretmenim 

Yaz ki bu kara tahta senindir...

Bekle köyü kadın 

Bekle ki senindir bu çeşme 

Kilometrelerce taşıyacaksın belki bu yükü 

-Yıllar boyu taşıyacağın ömrünün yükü hariç-

Belki sancılanacaksın bu çeşme başında 

Kalacaksın hastane yollarında

Bekle köylü kadın 

Bekle ki bu çeşme senindir.

Yürü emekçim

Yürü ki senindir bu meydan 

Yine sabahlayacaksın vardiyalarda

Yine vermeyecekler hakkını 

Yürüyeceksin 

Yürü ki bu meydan senindir

Haykır delikanlım

Haykır ki senindir bu ülke 

Belki sessiz kalacaksın yine

Belki Amerika’ya asker edecekler seni 

Ölmen ve öldürmen istenecek 

Çare yok artık baş kaldıracaksın

Haykıracaksın delikanlım 

Haykır ki senindir bu ülke...

10 Ocak 2003

(O günün gündeminden kağıdıma düşen)', 'Yürü köylü çocuğu  Yürü ki bu dağ senindir  Okulun dağlar ardında bırakılmışsa  Mevsim kışsa  Donup kalmak varsa  Kuytuluk boğazlarda Öğrenm...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/yuru-koylu-cocugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimşek', 'simsek-elazigli-mustafa-kaya-h4px1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'tuhaf bir  şimşekti

içime bıraktığın ışık

sevmenin berraklığını

ve,

aşkın eriticiliğini gördüm..

ağır darbeler altındayım

karanlıklara  gizlenen kederler

içindeyim

bir güvercin yavrusu gibi

beni bekleyen

ve üşüyen sevgilim

sen olmayınca her şey

daha karanlık..

Mustafa kaya

17.11.2005 / Üsküdar

www.mustafakaya.net', 'tuhaf bir  şimşekti içime bıraktığın ışık sevmenin berraklığını ve, aşkın eriticiliğini gördüm.. ağır darbeler altındayım karanlıklara  gizl...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/simsek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-arafat-arik-und9d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tutunduğun candan medet beklerken,

Bir anı gün edip güne eklerken,

Ruhun sorgusuz mahkûm, uğrarken cendereye,

Direniş ah direniş, kabul edilmez şeye.

Bir şimşek, bir çekim, bir kara buğu,

Haydi, tut cisminle, saran boşluğu.

Arala gözlerini açılan pencereye,

Bir gidiş ki; malumu meçhul iken, nereye? 

Gidiş ki; olmazın olur olduğu,

Renk, edâ, iklimin ansız solduğu…

Ferah bulduğun, zaman ve tepetaklak mekân,

Hani gül edâlı can, hani damarında kan? 

Güneş nerde doğar, şimdi vakit kaç? 

Çizilen rotadan bir yol bul da kaç.

Perdelemiş, perdeler ötelerinden bakan,

Bir bedene sır verip, yine kendinde yakan.

İrade mecâlsiz, atamaz kulaç,

Bilir mi eczâlar, bu hâle ilâç.

Perdenin arkasından bekliyorsan ipucu,

Gönül sâdık kılavuz; akıl aciz, çapulcu,

Varsın şemâlini köpürtsün halaç,

Sen öz varlığına, mutlak bir yol aç,

Bu gidiş ki; fânide, aslen, aslına rücû,

Bir tükenişin değil, asıl hayatın ucu…

15-KASIM-2005', 'Tutunduğun candan medet beklerken, Bir anı gün edip güne eklerken, Ruhun sorgusuz mahkûm, uğrarken cendereye, Direniş ah direniş, kabul edil...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/olum-227-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A-rabbim –dua-', 'a-rabbim-dua-mikdat-bal-b7gcx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rabbim –Dua-

Yeri ve gökleri yaratan, Allah!

Dirilt kalbimizi, görelim, Rabbim!

Mahl?katı yoktan var eden Allah

Nasip et yoluna girelim, Rabbim!

Kendini hakiki Mümin sananlar

Derde düştüğünde seni ananlar

Yediden yetmişe, hep inananlar

İslam şuuruna erelim, Rabbim!

Mağfiret kapına dayanalım biz

Aşkınla sevginle hem yanalım biz

Hidayet eyle de uyanalım biz

Bu gaflete bir son verelim, Rabbim!

İnandık kazana hem kaderine

Bırakma bizleri nefsin şerrine

Cehenneme düşüp zakkum yerine

Cennet güllerinden derelim, Rabbim!

Peygamber gönderdin, kitap indirdin

Kendini tanıttın bize andırdın

Nice zalim ıslah ettin, sindirdin

İzan ver de zulmü yerelim, Rabbim

Sevişsin insanlar, bitsin cinayet

Her şey sana ayan, eyle inayet

Yolundan ayırma, sen ver hidayet

Her şeyi yoluna serelim, Rabbim!

Şair Mikdat Bal', 'Rabbim –Dua- Yeri ve gökleri yaratan, Allah! Dirilt kalbimizi, görelim, Rabbim! Mahl?katı yoktan var eden Allah Nasip et yoluna girelim, Rab...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dirilt-kalbimizi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Batar Akılsız Başa', 'dunya-batar-akilsiz-basa-kamil-at-kcioy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bütün ölenler başlar mı sıfırdan

Beyni kıtlar gelişmez küfürden

Belirsiz yola giren cayar mı birden

Dünya nedensizdir akılsız başa.

Tarih kirlidir çok hayvan geldi

İnsanlık birleşecekti böldü

Tarihte leşi bitti, onursuz öldü

Şerefsiz varken bitmez tamaşa.

Gördüğün insana benzeyen ayı

Türeyip doğdular bilinmez sayı

Yüzüne küs bilirler insani aynayı

Birde bakın bardaki ayyaşa.

Suçlu dolu çok gizli parlament

Gerçeği görene yağlı eski kement

Dürüst kişiden oluşmaz hükümet

Satılmış rezil pazarlanır savaşa.

Kamil At yokuşu aşarsa kindar

Geberdi gitti bunca hükümdar

İnsanı robote etti alçak bilimdar

Ondandır dünyamız kargaşa.', 'Bütün ölenler başlar mı sıfırdan Beyni kıtlar gelişmez küfürden Belirsiz yola giren cayar mı birden Dünya nedensizdir akılsız başa. Tarih ki...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dunya-batar-akilsiz-basa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırılgan ruhum', 'kirilgan-ruhum-elazigli-mustafa-kaya-08ng7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yalnız rüzgarlara döndüm 

mavi gök

kırılgan ruhumu gezdirir 

bu yeryüzünde

adını bilmediğim yüzler tanıdım

kıştan daha soğuk

dostlara da rastladım

sanmıştım ki 

mutlu geçecekti hayatım

çareyi yalnızlıkta buldum

martılarla

kuşlarla 

bulutlarla 

yağmurla 

arkadaşlığı seçtim..

Mustafa kaya

15.11.2005 / İstanbul

www.mustafakaya.net', 'yalnız rüzgarlara döndüm  mavi gök kırılgan ruhumu gezdirir  bu yeryüzünde adını bilmediğim yüzler tanıdım kıştan daha soğuk dostlara da ras...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kirilgan-ruhum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Pati', 'pati-feride-senturk-p4hvc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kayan bir hayalsin kırık kalbimden,

Kurşuni dünyama pembe toz serpen,

Sokak kedisinin bilinmezinden,

İki pati izi bandırıp giden.', 'Kayan bir hayalsin kırık kalbimden, Kurşuni dünyama pembe toz serpen, Sokak kedisinin bilinmezinden, İki pati izi bandırıp giden....', ARRAY['Türk Edebiyatı','Şiir','Feride Şentürk']::text[], 8.5, '{"poet":"Feride Şentürk","poet_slug":"feride-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/pati-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bingol', 'bingol-zeki-savci-4v6p6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bahar yuzunu gostermis daglardan, 

Ovasinda seller cosar Bingol''un.

Gunes selam verir ayin ardindan, 

Dogasindan renkler tasar Bingol''un. 

Köroglu''na destan yazmis daglari 

Tarihi bagrina ekmis baglari, 

Sakli kalmis yasanacak caglari, 

Gonlünde define yatar Bingol''un. 

Rüzgarlari islik calar yürürken, 

Türkü söyler caylar karlar erirken, 

Hele bahar ayi yaza varirken, 

Yaylasinda taylar kosar Bingöl''ün...', 'Bahar yuzunu gostermis daglardan,  Ovasinda seller cosar Bingol''un. Gunes selam verir ayin ardindan,  Dogasindan renkler tasar Bingol''un.  K...', ARRAY['Türk Edebiyatı','Şiir','Zeki Savci']::text[], 8.5, '{"poet":"Zeki Savci","poet_slug":"zeki-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bingol-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-sair-unrealist-20qhf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneş doğdukça her sabah

Yağmur yağdıkça sonbaharda

Hele birde gökkuşağı görünürse ardından

Ve üzerine bastığın yaprakların sesi hala yüreğimdeyse

Benim hala umudum var.

Kapadokyada aynı güzellikte batıyorsa güneş

Ahmet Kaya dinlerken hala ağlıyorsam

Ve rakı sarhoş ediyorsa 

Benim hala umudum var.', 'Güneş doğdukça her sabah Yağmur yağdıkça sonbaharda Hele birde gökkuşağı görünürse ardından Ve üzerine bastığın yaprakların sesi hala yüreği...', ARRAY['Türk Edebiyatı','Şiir','Şair Unrealist']::text[], 8.5, '{"poet":"Şair Unrealist","poet_slug":"sair-unrealist","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/umut-216-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gavur Virüsü', 'gavur-virusu-suheyl-turkoglu-66whf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İpek Yolu''nda

Mezapotamya''da

Medeniyetler anası,

Anadolu''da

Gavur virüsü var,

Nefeslerden bulaşıyor,

Yayılıyor halk arasında.

Mikrop değil,

Aşısı yok,

Vuruyor sinsice,

Manyaklaştırıyor,

Kardeşi, kardeşe,

Düşman ediyor.

Biriken kinler

Cumalarda,

Cami önlerinde,

Elini uzatana,

Sebil niyetine

Veriliyor.

Ağıtlar yükselirken,

Evlat acısıyla,

İçi yanan analardan.

Çığlıklarına,

Kadeh kaldırılıyor,

Keyifleniyor

Gavurun virüsü.

Tek çaresi direnmek,

Direnci arttırmak,

Omuz omuza,

Gönül gönüle,

Yürek yüreğe,

Kardeşliğe yürümek.

Böyle öldürürüz,

Gavurun virüsünü,

Dedim ya,

Mikrop değil bunlar,

Her kılığa girerler,

Kenetlenirsek,

Emellerinde boğulup,

Yok olurlar.', 'İpek Yolu''nda Mezapotamya''da Medeniyetler anası, Anadolu''da Gavur virüsü var, Nefeslerden bulaşıyor, Yayılıyor halk arasında. Mikrop değil, ...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/gavur-virusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soğuktu Gözleri', 'soguktu-gozleri-orhan-eren-uncu-2l8d4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Soğuktu gözleri,

Saçında ki beyaz gibi

Yorgundu yüreği

Yakasına taktığı, solmuş gül gibi

Gökyüzü neden maviydi

Beyaz niye soğuktu onun için

Biçare,

Sokaklar da,gezerken

Soğuktu gözleri,

Beyazdı artık saçları

08.03.2005', 'Soğuktu gözleri, Saçında ki beyaz gibi Yorgundu yüreği Yakasına taktığı, solmuş gül gibi Gökyüzü neden maviydi Beyaz niye soğuktu onun için ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Eren Uncu']::text[], 8.5, '{"poet":"Orhan Eren Uncu","poet_slug":"orhan-eren-uncu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/soguktu-gozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Panikle Yüzleşme', 'panikle-yuzlesme-birsen-ates-l9wz3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nerede tutacak yüreğimden bilinmez

garip bir ironi

tam giderken bir yerlere

tutunacakken yaşama

başlar bir iç sıkıntısı

sanki kalbim kanatlanıp uçacak

ruhum kulaklarımdan çıkacak

çoktan başlamıştır ölüm

aslında hüznüm doğuştan

istemiyorum mutluluk haplarını

öleceksem öleyim diyorum 

ölünmüyor ki

hüzün ektim olmadı

alemlere aksam uymadı

şiir yazdım tutmadı

aşık oldum sarmadı

ölümle yaşam arası çizgide

tam bir kabus kısırdöngüde

çoktan başlamıştır ölüm

aslında hüznüm doğuştan

istemiyorum mutluluk haplarını

öleceksem öleyim diyorum 

ölünmüyor ki', 'Nerede tutacak yüreğimden bilinmez garip bir ironi tam giderken bir yerlere tutunacakken yaşama başlar bir iç sıkıntısı sanki kalbim kanatla...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/panikle-yuzlesme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar', 'yildizlar-orhan-eren-uncu-7wy22', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Basamak olsa yıldızlar

Koşarak çıksak sonsuza

Gökkuşağına renk olsak

Hırçın durumlarda, dalga olsak

Patlasak dağlara taşlara

Durulsak, dursak

Filiz açsak yabani tarlada

Çiçek olsak

Bal olsak bereket misali

Damak da, tat olsak

10.10.2004

Ankara', 'Basamak olsa yıldızlar Koşarak çıksak sonsuza Gökkuşağına renk olsak Hırçın durumlarda, dalga olsak Patlasak dağlara taşlara Durulsak, dursa...', ARRAY['Türk Edebiyatı','Şiir','Orhan Eren Uncu']::text[], 8.5, '{"poet":"Orhan Eren Uncu","poet_slug":"orhan-eren-uncu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yildizlar-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Karası', 'gecenin-karasi-orhan-eren-uncu-2ncnb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecenin karası, Antalya’da

İlk buluşma heyecanı

Saat kulesi yanın da

Heyacanlar, umut olur yarinlere

Akar sevgi seli, kıyıya

El ele, kol kola

Heyecan sarar

Gecenin karasın da, Antalya da

Denizin dalgası kıyıda

Hüzün çöker gözlerine

Soğuklaşır bakışlar, korkutur

Yarinler, mucadele büyür

Ufukta, dalgalarda

Antalya da, kıyıda

Kale içi eşya olur, anı olur

Ara sokaklar dolar

Aşıklar el ele, kol kola

Duygular, dalga dalga

Gülücük olur, öpücük olur

Gecenin karasın da Antalya’da

2004', 'Gecenin karası, Antalya’da İlk buluşma heyecanı Saat kulesi yanın da Heyacanlar, umut olur yarinlere Akar sevgi seli, kıyıya El ele, kol kol...', ARRAY['Türk Edebiyatı','Şiir','Orhan Eren Uncu']::text[], 8.5, '{"poet":"Orhan Eren Uncu","poet_slug":"orhan-eren-uncu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gecenin-karasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alçak Türleri', 'alcak-turleri-kamil-at-kvh7l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu dünyada madem ki insanım

Kötülüğü tutup bedenime sarmam

Nice suç işleyip tanrıya yalvarmam

Böyle yapıp yalvaran alçak.

Zaman benimle ölene kadar gelir

Nedir bedenim toprağa yükselir

Nice insan ölür köpekler alçalır

İnsan yiğidi vuran alçak.

Zalim doğru yaparsa neden gizler

Atomlar kudurur taşarsa denizler

Ölüm kıyısına yaklaşırsak bizler

Pişmanım deyip kaytaran alçak

Otoriteyi kirli elinde bulunduran

Yiğit insana köpeklerince saldıran

Yaptığı pislikleri dua ile kaldıran

İnsanlık soyunu gizli kıran alçak.

Kamil At fikir bulmayan nadan

Sormaz filosof insanlık kırmadan

Yobazına yaptırıp kendini yormadan

Tarihte ki cahilleri kandıran alçak.', 'Bu dünyada madem ki insanım Kötülüğü tutup bedenime sarmam Nice suç işleyip tanrıya yalvarmam Böyle yapıp yalvaran alçak. Zaman benimle ölen...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/alcak-turleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanarım', 'yanarim-suheyl-turkoglu-rlbm0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sarıp sarmalarım,

Ayaklarına dolaşırım,

Cebime koyarım

Dünyayı,

Hayallere uçarım.

Biçare gönüllerde,

Kahrolurum,

Yanarım,

Çocuklar gibi,

Ağlarım.

Giderim,

Başım uzanır,

Bakarım geriye,

Hatalarıma,

Yanarım.', 'Sarıp sarmalarım, Ayaklarına dolaşırım, Cebime koyarım Dünyayı, Hayallere uçarım. Biçare gönüllerde, Kahrolurum, Yanarım, Çocuklar gibi, Ağl...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yanarim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Viran', 'viran-nazan-i-zmirli-ul8c0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '............acımasız 

....................karanlık

..........................geceler

ıssız

sessiz

sensiz

soğuk

...............................viran

.....................dolunay

............idamlarda

yanık

yetim

yaşlı

yalnız

bu  yürek,  yenilginin 

tam   kıyısında

sana inat 

kıristal bir 

denizatıyla

küskün   dolunayın

yakamozlarını   boğduğu

okyanusları  aşmayı  deneyecek

başaramazsa   ne    farkeder ki; 

kaybolmuşluğun..........................

tam   ortasında................................

varla   yok   arasında.........................

viran.......................................bu yürek

......................sana................................

Nazan İzmirli-16.11.2005', '............acımasız  ....................karanlık ..........................geceler ıssız sessiz sensiz soğuk ................................', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/viran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yosun Gözlüm', 'yosun-gozlum-mustafa-bilal-kutsal-9d3f0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yosun gözlüm.

Yaşamından sevgi,

yüzünden gülümseme eksik olmasın,

ama sende benim gibi

güldükce mahsun,

sevdikce yalnız kalasın...', 'Yosun gözlüm. Yaşamından sevgi, yüzünden gülümseme eksik olmasın, ama sende benim gibi güldükce mahsun, sevdikce yalnız kalasın......', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bilal Kutsal']::text[], 8.5, '{"poet":"Mustafa Bilal Kutsal","poet_slug":"mustafa-bilal-kutsal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yosun-gozlum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız & Sen', 'yildiz-sen-sezen-akoluk-big46', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '..........Ah bebeğim o gülüşün var ya, 

..............insani uzaklara götürüyor. 

..........Aynı yıldızlara baktığım gibi. 

Onun için yıldızlarla aranızda pek fark göremiyorum. 

.........Hem yanımda – hem uzağımdasın. 

Hem beni ağlatıyorsun – hem de güzel düşüncelere götürüyorsun. 

.........Hem beni sevindiriyorsan – hem de üzüyorsun. 

Ama sana bakmak, yıldızlara bakmaktan çok daha güzel. 

..............................NEDENMİ? 

........Yıldızlar sırf geceleri görünür, ama sen hep: 

AKLIMDA, BEDENİMDE; HER DK YANIMDASIN

..................gece ve gündüz yanımdasın…

...........................................sezen akoluk', '..........Ah bebeğim o gülüşün var ya,  ..............insani uzaklara götürüyor.  ..........Aynı yıldızlara baktığım gibi.  Onun için yıldız...', ARRAY['Türk Edebiyatı','Şiir','Sezen Akoluk']::text[], 8.5, '{"poet":"Sezen Akoluk","poet_slug":"sezen-akoluk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yildiz-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masallar', 'masallar-mirac-durmus-ulkhj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Rüzgarda uçuşan yapraklar kadar özgür ol! 

Haydi koş! 

Koş arzularına! 

Ve ufukta kaybol...

ßir melek gibi uç masallara,

Yalnızlığın olmadığı diyarlara...

Git ve Mutlu ol! 

Ardında kalanlara aldırış etmeden...

Masallara emanet ol!', 'Rüzgarda uçuşan yapraklar kadar özgür ol!  Haydi koş!  Koş arzularına!  Ve ufukta kaybol... ßir melek gibi uç masallara, Yalnızlığın olmadığ...', ARRAY['Türk Edebiyatı','Şiir','Miraç Durmuş']::text[], 8.5, '{"poet":"Miraç Durmuş","poet_slug":"mirac-durmus","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/masallar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamızın üzerine', 'sevdamizin-uzerine-nazan-i-zmirli-uh5ds', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu gece 

..............dolunaya

..............................sevgimi

...........................................yükledim

yakamozları  bomba

kucaklaşıyor   denizde

sevdamızın üzerine............................

dalgalar,aşkımızı fısıldıyor.................

kumsal  mutluluk  gözyaşlarına.........

boğuluyor............................................

sen..............................................deniz

........ben.........................kumsal..........

                      olsam

sevdamız   kavuşurmuydu  ebebiyete

Nazan İzmirli-16.11.2005-antalya', 'bu gece  ..............dolunaya ..............................sevgimi ...........................................yükledim yakamozları  bomba...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevdamizin-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyemedi... Hiç!', 'diyemedi-hic-yasemin-sezer-tulgar-ljzy7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sorguda şimal dağlarını sevdi şehir’in yetim’i

Kırıntı oldu kuytularına cürmü hacmi’n

Yitebilmeyi bekledi, çok bekledi

Kim bilir, “belki” dedi, “belki”; 

“Yiten de sevebilir...”

Yırtıklarını gözyaşlarına bandırdı, kanamalarını azdırırcasına,

Arsızca, kansızca...

Sövdü...Sövdü...

Doğrusu şu ya; 

İçiyle ovdu ırak yanlarını haksız sövülen’in.

Akıttı dünya gücüyle asıldığı damarlarının kanını

Aralara dizilen, uzayan tüm yollara, akıbetsiz.

Uzattığı tırnakları kadar uzayamadı nefesi 

Ses verircesine; 

“Kahrolayım,

_GEL” diyen...

Diyemedi

Hiç.

Erdemdi ya susmalar

Molla sayacaklardı aşüfteyi

17.11.05', 'Sorguda şimal dağlarını sevdi şehir’in yetim’i Kırıntı oldu kuytularına cürmü hacmi’n Yitebilmeyi bekledi, çok bekledi Kim bilir, “belki” de...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/diyemedi-hic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahu gözlüm', 'ahu-gozlum-mikdat-bal-y4rqg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ahu gözlüm hilal kaşlım gül yüzlüm

Seni benden  ayıranlar gülmesin

Sırma saçlım, tatlı dillim bal sözlüm

Beni senden ayıranlar gülmesin

Çekilmiyor hasta etti bu sevda

Yine de vaz geçmem olsam bir mevta

Kayıp ettim hayat denen sinavda

Seni benden  ayıranlar gülmesin

Sevmem artık senden başka birini

Hiç kimse alamaz senin yerini

Bu dünya da yoktur senden şirini

Seni benden  ayıranlar gülmesin

Mikdat der ki yandı sinem kül oldu

Sana vuslat bana engin yol oldu

Dünya batsın artık her yer çöl oldu

Seni benden  ayıranlar gülmesin', 'Ahu gözlüm hilal kaşlım gül yüzlüm Seni benden  ayıranlar gülmesin Sırma saçlım, tatlı dillim bal sözlüm Beni senden ayıranlar gülmesin Çeki...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ahu-gozlum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiğinde', 'gittiginde-hasan-sahin-rh1fu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiç bu kadar eksilmemiştim ben

Birileri kapıyı vurup çıktığında

Ve hiç bu kadar hızlı

Düşmemiştim

Tırmandığım o heybetli 

Yükseklikten

Hiç bu kadar üşümemiştim

Odaların çıplaklığında...

Şimdi artık 

Her yer mahşer yeridir

Ve artık her bakış

Kuytu bir orman

Ne sen sen olalı

Bu kadar yalnız

Nede ben ben olalı 

Bu kadar kalabalığız

Kendi çaresizliğimizde', 'Hiç bu kadar eksilmemiştim ben Birileri kapıyı vurup çıktığında Ve hiç bu kadar hızlı Düşmemiştim Tırmandığım o heybetli  Yükseklikten Hiç b...', ARRAY['Türk Edebiyatı','Şiir','Hasan Şahin']::text[], 8.5, '{"poet":"Hasan Şahin","poet_slug":"hasan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gittiginde-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çılgın Şair', 'cilgin-sair-celal-topo-c6bhd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğimin iniş çıkışlarında

Bir çılgın ben var

Bir ben bilirim o çılgınlığımı

Bir de sevdiğim kadın

Ellerim ceplerimdedir akşam vakitleri

Islak sevda şarkılarımı

Karanlığın dudaklarında söylerim

Silinmiş bir gölge olur

Arkamda unuttuğum gün ışıkları

Mehtaba uğrarım ara sıra

Dedim ya çılgınlık var serde

Yasemini gıdıklarım koklayarak

Çoban yıldızına selam veririm

Takılırım şaka yollu

Eski parlaklığın nerede

Neden öyle donuksun

Kafamı bozma attırma tasını

Satarım seni ölü bir deniz yıldızına

Çılgınlık  bu ya..............

Geri gelirim tekrar kürkçü dükkanına.....



16 / 11 / 2005  Antalya', 'Yüreğimin iniş çıkışlarında Bir çılgın ben var Bir ben bilirim o çılgınlığımı Bir de sevdiğim kadın Ellerim ceplerimdedir akşam vakitleri Is...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cilgin-sair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıymetimi Bilemedin', 'kiymetimi-bilemedin-sahin-erturk-dt1uc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin kölen,hizmetcindim

Üzerine titriyordum

Her dediğini yapıyordum

Kımetimi bilemedin

İhanetin belgesini

Kendi gözlerimle gördüm

Yazık ettin aşkımıza

Kıymetimi bilemedin

Kollarına atıldığın

Bir sarhoşun ta kendisi

Hergün kokla nefesini

Böyle anla kıymetimi

Seni candan seviyordum

Aşkı bilen sanıyordum

Sevgi yokmuş yüreğine

Kıymetimi bilemedin

(17.11.2005-Yeni)', 'Senin kölen,hizmetcindim Üzerine titriyordum Her dediğini yapıyordum Kımetimi bilemedin İhanetin belgesini Kendi gözlerimle gördüm Yazık ett...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kiymetimi-bilemedin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretinden Çatlayan Dudaklarıma Merhem Oluver', 'hasretinden-catlayan-dudaklarima-merhem-oluver-huseyin-erdogan-2dj18', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'eğer yüreğine alırsan beni

göreceksin sıcacık edeceğim seni

sevgimi de yorgan yaparsan üzerine

karakışta bile hiç üşümeyeceksin ömrünce

haydi sevdiğim geç kalma sen de dene

uzaklardan da olsa uzatıyorum ellerimi sana

ne olursun tut onları sakın bırakma havada

ben  de senin  güzel yüreğinde varsam eğer

hasretinden çatlayan dudaklarıma merhem oluver

sen hep bendesin,benimlesin,inan ki benimsin

seni hiç üşütmeden yüreğimde uyutuyorum her gece

bil ki sevgili şiirim sen gönlümde esen bir meltem yelisin

hiç solmayan rengarenk bir bahar olarak kal bende ömrümce

                                                                    17.11.2005

                                                                  Hüseyin Erdoğan', 'eğer yüreğine alırsan beni göreceksin sıcacık edeceğim seni sevgimi de yorgan yaparsan üzerine karakışta bile hiç üşümeyeceksin ömrünce hayd...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hasretinden-catlayan-dudaklarima-merhem-oluver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '))) Gecenin Gözü Kördü (((', 'gecenin-gozu-kordu-i-brahim-dikmen-2-7cqkm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Böyle karanlıklara alışık değilim ben

Ne yıldızlar var gökyüzünde

Ne de geceye küsmüş

Sokak lambaları

Gecenin gözü kördü

Anlıyacağın.

Bütün bedenim esirdi

karanlığa

Ümitlerim,hayallerim ve aşkım da

Sonu gelmek bilmiyordu nedense

Bir türlü güneş doğmuyordu

Puslu gözlerime.

Karanlığın içerisinde kaybolup gitti

Bütün masumca düşlerim

Baykuşun alaycı ötüşü vardı

kulaklarımda.

Sen işe yaramaz adamın tekisin

Der gibiydi uğursuz

Ve kaybettin diyordu alaycı

Karanlığı yırtan sesiyle.

Durdurmayı başaramadım

Gözlerime yağan

Hazan yağmurlarını.

Dalıp gittim yine düşler ülkesine

Ötüşen böceklerin o''muhteşem

O''eşsiz senfonisiyle.

Kayboluşumu,tükenişimi gördüm

Ve karanlığın dev cüssesine çarpıldım

Ne benim onu görecek halim vardı

Ne de siyaha bürünmüş gecenin beni

Gecenin gözü kördü

Anlıyacağın.

                       Kaybettiklerime isyanımdır........

17/11/2005

Aydınlı İbrahim Dikmen', 'Böyle karanlıklara alışık değilim ben Ne yıldızlar var gökyüzünde Ne de geceye küsmüş Sokak lambaları Gecenin gözü kördü Anlıyacağın. Bütün ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gecenin-gozu-kordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Marisa (Bursa''ya Sevgilerle)', 'marisa-bursa-ya-sevgilerle-yavuz-bayram-caliskan-4m95m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sıcaklığını içimize gönülden işleyen, 

Ve yaşam boyu gülmeyi seven, özleyen, 

Güneşimiz, baharımız, biten ömrümüz canımız, 

Umutlardaki hüznümüz, geleceğimiz, 

Kısacık bir an gibi yaşanır Marisa. 

Bir gül doğar ömür, çiçek ile, 

Yaşanır bir can ile aşk ile, 

Zaman tanıyamaz doğan her güle, 

Kader her şey, ağlayan Marisa, 

Beklentiler yıkar, yaşamak bağlar, 

Gülen gözler aşkına ağlar, 

Kader bu, kader her şey, 

Tutar ömrüne karalar bağlar, 

Hayatı zor yaşar, zor yaşar Marisa. 

Gülerken yüzlere ağlar gönüllere, 

Ağlamak mı? , yaşamak mı? ,seçemez, 

Bir dünya tatlısı yavrusundan vazgeçemez, 

Gönüllerde açar bir gül Marisa.', 'Sıcaklığını içimize gönülden işleyen,  Ve yaşam boyu gülmeyi seven, özleyen,  Güneşimiz, baharımız, biten ömrümüz canımız,  Umutlardaki hüzn...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/marisa-bursa-ya-sevgilerle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Necla Hanım', 'necla-hanim-omer-ekinci-micingirt-9tcxd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seninle gece gündüzüm

Neredesin Necla Hanım

Sana açık gönül gözüm

Neredesin Necla Hanım

Rüyalarda ağlıyorsun

Yüreğimi dağlıyorsun

Gam kedere bağlıyorsun 

Neredesin Necla Hanım

Sana benzer dört biryanım

Neredesin benim canım

Vuslat yakın gel kurbanım

Neresin Necla Hanım

Senden sonra yaralıyım 

Yas bürümüş karalıyım 

De Alex’sin maralıyım

Neredesin Necla Hanım

Bu şiir Buzuky  Alex KARATHANU beyin isteği  üzere yazılmıştır. 12.01.12', 'Seninle gece gündüzüm Neredesin Necla Hanım Sana açık gönül gözüm Neredesin Necla Hanım Rüyalarda ağlıyorsun Yüreğimi dağlıyorsun Gam kedere...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/necla-hanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum', 'dostum-nusret-turan-tapzn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülmüştük eğlenmiştik

Dere tepe gezmiştik

Çok da mutlu olmuştuk,

Ne oldu sana DOSTUM? 

Kuyunu hiç kazmadım

Laf etmedim arkandan

Suratın iki karış

Ne oldu sana DOSTUM? 

Sen akıllı adamsın

Fitneliği kim yaptı? 

Yolun çok açık olsun

Sen bilirsin has DOSTUM.

Yersin ondan tekmeyi,

Ya bugün ya da yarın

Yalanla doymaz karın,

Göreceksin sen DOSTUM.

BODRUM

15.11.2005 Saat: 04.13', 'Gülmüştük eğlenmiştik Dere tepe gezmiştik Çok da mutlu olmuştuk, Ne oldu sana DOSTUM?  Kuyunu hiç kazmadım Laf etmedim arkandan Suratın iki ...', ARRAY['Türk Edebiyatı','Şiir','Nusret Turan']::text[], 8.5, '{"poet":"Nusret Turan","poet_slug":"nusret-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dostum-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Yok Mu?', 'i-nsan-yok-mu-nusret-turan-mf7fi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen ağlama dertli anam

Gözyaşına dayanamam

Fakirliğin gözü çıksın

İnsan yok mu hiç yanında? 

Dertler sarmış dört yanını

Sormamışlar hiç hatrını

Adam olan yardım eder

İnsan yok mu hiç yanında? 

BODRUM', 'Sen ağlama dertli anam Gözyaşına dayanamam Fakirliğin gözü çıksın İnsan yok mu hiç yanında?  Dertler sarmış dört yanını Sormamışlar hiç hatr...', ARRAY['Türk Edebiyatı','Şiir','Nusret Turan']::text[], 8.5, '{"poet":"Nusret Turan","poet_slug":"nusret-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/insan-yok-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem bitecek', 'ozlem-bitecek-nusret-turan-m2ttd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sensiz geçen bir günün ardından

Antalya’da yine akşam oldu

Gecelerim bitmek bilmeyecek

Battaniyeye sarılacağım amma

Sensizlikten yine üşüyeceğim

Yine gözlerim tavanda

Seni arayıp duracak

Bakıyorsun bana öylesine

Konuşmuyor, hep susuyorsun

Ağlıyorsun yokluğuma

Kokumu özledin biliyorum

İnan ki bin katı benden

Geçecek diyorum ayrılıklar

Bitecek çocukların özlemi

Bitecek sensizlik

Yine gözlerine bakacağım

Fakat, konuşmadan ben

Ne istediğimi bileceksin

“Şu saatte yemek yenir mi? ”

Diyeceksin.

Yalvarırcasına bakarken

Gözlerine

Yine dayanamayacaksın

Kalkıp “YUMURTA” pişireceksin

Yanında

Acı pul biber

Biraz da soğan

Bir taraftan yememi isterken,

Bir yandan da “MUTLU”

Olacaksın…

ANTALYA

15.05.1997 Saat:02.12', 'Sensiz geçen bir günün ardından Antalya’da yine akşam oldu Gecelerim bitmek bilmeyecek Battaniyeye sarılacağım amma Sensizlikten yine üşüyec...', ARRAY['Türk Edebiyatı','Şiir','Nusret Turan']::text[], 8.5, '{"poet":"Nusret Turan","poet_slug":"nusret-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ozlem-bitecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar', 'i-nsanlar-nusret-turan-7ooe9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geldi geçti şu ömrüm,

Çözemedim insanı..

Verince çok överler,

Vermeyince söverler..

Yalakalık bin para,

Menfaatler uğruna

Vicdanları sızlatır,

Bu vefasız insanlar

Doğruya lafım olmaz

Baş üstünde yerleri

Tez geberip gitsinler

Şu riyakar insanlar

Kendi düşüncesini

Çarpıtarak söylerler

Tutunca mayaları

Sinsi sinsi gülerler

Gariptir, çok gariptir

Fitne baz şu insanlar

BODRUM

15.11.2005 Saat: 05.15', 'Geldi geçti şu ömrüm, Çözemedim insanı.. Verince çok överler, Vermeyince söverler.. Yalakalık bin para, Menfaatler uğruna Vicdanları sızlatı...', ARRAY['Türk Edebiyatı','Şiir','Nusret Turan']::text[], 8.5, '{"poet":"Nusret Turan","poet_slug":"nusret-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/insanlar-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Gibi', 'adam-gibi-nusret-turan-4io8w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ana-baba biliyorsan

Hatırını soruyorsan

Ellerini öpüyorsan

Adam gibi bir adamsın

Allah’ını biliyorsan,

Ondan daim korkuyorsan

Böyle mutlu oluyorsan

Adam gibi bir adamsın

Yetim hakkı yemiyorsan

Ona yardım ediyorsan

Yüzlerine gülüyorsan

Adam gibi bir adamsın

Fabrikalar kuruyorsan

İşçileri koruyorsan

Beddualar almıyorsan

Adam gibi bir adamsın

Dedikodu yapmıyorsan

Yapanları kınıyorsan

Hep barışık oluyorsan

Adam gibi bir adamsın

Tabiatı koruyorsan

Gözün gibi bakıyorsan

Ateş atıp yakmıyorsan

Adam gibi bir adamsın

Artı eksi biliyorsan

Onları not ediyorsan

Bir ekside kaçmıyorsan

Adam gibi bir adamsın

Köpekleri seviyorsan

Ondan örnek alıyorsan

Sadakati biliyorsan

Adam gibi bir adamsın

Irk ayrımı yapmıyorsan

Siyah beyaz seviyorsan

Herkesi dost biliyorsan

Adam gibi bir adamsın

Yüze bakıp gülüyorsan

Sonra küfür etmiyorsan

Fitne-fesat ekmiyorsan

Adam gibi bir adamsın

Sen ustanı biliyorsan

Ona şükran diliyorsan

Takdir edip övüyorsan

Adam gibi bir adamsın

Kul hakkını biliyorsan

Gizli gizli çalmıyorsan

Beddualar almıyorsan

Adam gibi bir adamsın

BODRUM 

15.10.2005 Saat: 05.00', 'Ana-baba biliyorsan Hatırını soruyorsan Ellerini öpüyorsan Adam gibi bir adamsın Allah’ını biliyorsan, Ondan daim korkuyorsan Böyle mutlu ol...', ARRAY['Türk Edebiyatı','Şiir','Nusret Turan']::text[], 8.5, '{"poet":"Nusret Turan","poet_slug":"nusret-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/adam-gibi-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce', 'i-nce-aysin-ulug-lmjai', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnce biz sızıdır bu sessizlik

Yaşamak dediğimiz belirsiz geçişte

Bir can beklemektir

Sabırla



İnce bir düşünüştür bu bekleyiş

İnce hesaplar üzerine kurulu ilişkilerimizle

İncelikler umarak yaşamak



Oysa koca şehirlerde derin gürültüler bekler bizi

Derin yalnızlıklar saklanır yaşantılarımıza

Bir can bekleyiş yerini bin can çekişmelerine

Sabır, telaşlı haykırışlara terk eder



Bir hayattır sürüp gideceğimiz

Ne niye geldiğimizi biliriz adam akıllı 

Ne de nereye gideceğimizi



İnce bir hüzüne terk eder bizi gece yarıları

Kaçan uykular

İşte o saatlerde anlar insan

Sessizliklerin sızısını', 'İnce biz sızıdır bu sessizlik Yaşamak dediğimiz belirsiz geçişte Bir can beklemektir Sabırla İnce bir düşünüştür bu bekleyiş İnce hesaplar ü...', ARRAY['Türk Edebiyatı','Şiir','Ayşin Uluğ']::text[], 8.5, '{"poet":"Ayşin Uluğ","poet_slug":"aysin-ulug","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ince-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam ve Nergis Çiçekleri', 'babam-ve-nergis-cicekleri-aysin-ulug-9u7kr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Masamda nergis çiçekleri

Önümde yığılı işler

Tatlı bir tını kulağımda

Babamın sesi

Huzurluyum



En sevdiği çiçek babamın nergisler

En sevdiği çiçekti

O zamanlarda hayatım yine bu kadar yoğun

Önümde yığılı işler

Yine bir telefon ucunda babamın sesi

O zaman bir telefon mesafesi,

Dört saatlik yolda babamın gözleri



Şimdi kulağımın bir yerlerinde sesi

Ne zaman sığınmak istesem gözlerimde hayali

Bir demet nergis yetiyor onu yanıma getirmeye

Bir kaç saatlik bir uyku kavuşturuyor kucağına



Yaşım geçmiş otuzu 

Tıpkı yirmiyedimdeki gibi 

Yine ihtiyacım dizlerinde oturmak

Beni sımsıkı saran, sırtımı sıvazlayan kolları özlediğim

Ve ben ağlarken, bu son olsun diyen sesi



Babam geçti gitti hayatımdan

Aynı koşturmaca

Aynı telaş yaşantımda

Aynı nergisler mi bunlar masamda

Her kış evine giderken aldığım.

Aynı ben değilim artık

Büyümem gerekti, büyüdüm mü

Kabul etmem gerekti yokluğunu, ettim mi

Gitti babam bu dünyadan

Gerçekten artık yok mu



Nergis çiçekleri yanımda babam

Gece melek uykular yanımda babam

Ne yaşanmış ne tükenmiş ne kalmış geriye demeden

Özlediğim babam



Bir Pazar günü,

Kimileri ailesiyle, annesi, babası

Belki çocukları eşi sevgilisi

Ben işimde

Masamda yığılı işlerim

Masamda bir demet nergis çiçeği

Sevgilimin aldığı



Bekle desem bekler mi beni hayat

Yaşım otuzu geçerken

Sormalımıyım kendime

Neresindeyim hayatın

Hayat benim neremde', 'Masamda nergis çiçekleri Önümde yığılı işler Tatlı bir tını kulağımda Babamın sesi Huzurluyum En sevdiği çiçek babamın nergisler En sevdiği ...', ARRAY['Türk Edebiyatı','Şiir','Ayşin Uluğ']::text[], 8.5, '{"poet":"Ayşin Uluğ","poet_slug":"aysin-ulug","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/babam-ve-nergis-cicekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni unut sevdiğim', 'beni-unut-sevdigim-aysin-ulug-had92', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni unut sevdiğim

Ben bir gece vakti

Sabaha hazırlanan günün 

kuş seslerine vuruldum



Şehir uyurken

Sen uyurken gecenin dördünde

Şehrin göbeğinde arabalar geceyi gündüz ederken

Bu şehirde hiç gece olmaz mı derken

Bir kuş sesine vuruldu kalbim



Beni unut sevdiğim



Aşk denizinde

İki yürek ellerimde

Şimdi ne sen ne o

Çaresiz bir girdaba düştüm



Beni unut sevdiğim

Gece sabah olmadan

Dönmeden geriye

Bir kuş misali çekip giderken

Beni yaralı yüreğine bağlama



Sevdalandığım sen

Bir hayatı dipsiz denizlerde oltalara yem ettiğim

Hayatım

Taşıyamadığım yüklerle debelenirken yaşantımda

Kuş seslerine vuruldum



Gece

Hain yalnız ıssız sanarken

Bir kuş sesi

Gençliğime veda ederken

Deli bir ırmak çağlıyor içimde



Gökyüzü lacivert sabaha dönerken

Gece mavi tepelerin ardında

Sen yatağında uyurken

Sabah oluyor sevgilim



Beni unut sevdiğim

Bırak unutabildiğin yerde...', 'Beni unut sevdiğim Ben bir gece vakti Sabaha hazırlanan günün  kuş seslerine vuruldum Şehir uyurken Sen uyurken gecenin dördünde Şehrin göbe...', ARRAY['Türk Edebiyatı','Şiir','Ayşin Uluğ']::text[], 8.5, '{"poet":"Ayşin Uluğ","poet_slug":"aysin-ulug","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/beni-unut-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Biterken Başlar', 'gun-biterken-baslar-salim-erben-lk264', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçinde yıkık bir kent saklı

Fer kalmamış gözlerinde 

Karanlık sokakları suskun

Kaldırımlarında göz yaşları

Başlamış içindeki isyan

Kimi zaman sakin 

Kimi zaman kudurgan

İsyanın ele başı bilinmez 

Belki içinde saklı olan

Senin sevdan zalım

Belki de alenen benim sevdam', 'İçinde yıkık bir kent saklı Fer kalmamış gözlerinde  Karanlık sokakları suskun Kaldırımlarında göz yaşları Başlamış içindeki isyan Kimi zama...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gun-biterken-baslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümü Bekliyorum', 'olumu-bekliyorum-sahin-erturk-i5uq1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İşte yine gelmedin

İşte yine sensizim

Belkide gelemedin

Aşamadın dağları

İşte yine gelmedin

Gözüm seni aradı

Kalbim seni aradı

Beynim seni aradı

İşte yine gelmedin

Elimde soldu güller

Tuz,buz oldu umutlar

Dünden daha kötüyüm

İşte yine gelmedin

Umudu kestim senden

Artık gelmeni değil

Ölümü bekliyorum

(17.11.2005-Yeni)', 'İşte yine gelmedin İşte yine sensizim Belkide gelemedin Aşamadın dağları İşte yine gelmedin Gözüm seni aradı Kalbim seni aradı Beynim seni a...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olumu-bekliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeyh Sait isyanında size ders veren Çılgın Türkleriz.', 'seyh-sait-isyaninda-size-ders-veren-cilgin-turkleriz-halil-colak-fqioe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kabartmayın ayranımızı taşarız yine

Dağ tepe demeden aşarız yine

Bütün kalelerinizi yıkarız yine

Biz tarihe yön veren çılgın Türkleriz

Tarihte karadan bizler gemi yüzdürdük

Bizanssı yıkıp Çağları kapatıp çağları aştık

İstiklal Savaşında yedi düvelle savaştık

Savaşta yenilgi bilmeyen çılgın Türkleriz

Karnımız aç aynı zamanda susuzda olsa

Ayağımızda ayakkabısız çıplak da olsa

Topa karşı elimizde tırpan orakta olsa

Meydan muhaberesi kazanan biz çılgın Türkleriyiz

O İmandı ateşe karşı göğsü siper ettiren

O azimdi savaşarak düşmanı yok ederek yurttan attıran

O vatan sevgisi idi Mehmet’e Şahadet şerbeti içtiren

Allah’tan başka bir şeyden korkmayan çılgın Türkleriz.

Kurt, Tüktür bütün tarihler böyle yazıyor

Bedi_u zaman Türk’e Kılıç çeken iflah olmaz diyor

Tarih Türk’e meydan okuyan milletlerin akıbetini yazıyor

Kanımızla destanlar yazan biz çılgın Türkleriz

Horasan ereni Allah Huzurunda sizi ikaz ediyor

Ayrıklıkçılar sizin sonunuz felakettir bunu iyi biliyor

Ermeni Kürtler güneş doğuda Türk’e kafa tutuyor,

Şeyh Sait isyanında size ders veren  Çılgın Türkleriz.

Halil ÇOLAK 17.11.2005 Ankara saat 04.10', 'Kabartmayın ayranımızı taşarız yine Dağ tepe demeden aşarız yine Bütün kalelerinizi yıkarız yine Biz tarihe yön veren çılgın Türkleriz Tarih...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seyh-sait-isyaninda-size-ders-veren-cilgin-turkleriz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski plak', 'eski-plak-seref-manav-yt3jb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayır,hayır istemem,

Yenilikleri,teknolojiyi ve diğer her şeyi

İstemem…! 

Geri sarın geri sarın bu plaklar

Eskileri çalsın,

Eski yıllarımı.

Doğumumu,çocukluğumu

Koştuğum,düştüğüm yıllara 

Sarın bu plağı

Uçurtmalarıma da…', 'Hayır,hayır istemem, Yenilikleri,teknolojiyi ve diğer her şeyi İstemem…!  Geri sarın geri sarın bu plaklar Eskileri çalsın, Eski yıllarımı. ...', ARRAY['Türk Edebiyatı','Şiir','Şeref Manav']::text[], 8.5, '{"poet":"Şeref Manav","poet_slug":"seref-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/eski-plak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Gecesi', 'yaz-gecesi-mehmet-cafer-4y72m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ilık bir yaz gecesinde,önümde hesap defterm,

Herkesinki gibi kara kaplı

İçinde hüzünlerim,kavgalarım,ağrıyan yanlarım.

Bir labirent gibi, karşımda duran salkım söğüt misali,

Döndükçe hep başladığım yerdeyim,

Yanıyorum,kuru otlar gibi sararıyor tenim,

Aklımda hep aynı masal,önümde hesap defterim.

Açtığımda birkaç sayfayı,kararmakta gece gibi,

Üzerine hayaller kurduğum yollar.

İçinde her dertten yüz gram bulunan bir yemeği,

Yememek elde olsa,

Ama önümde kara kaplı hesap defterim,

Açılınca,kesik bir bilekten akan kan gibi,

Kanamamak olmasa,

Bir meyve ağacı kadar da mutlu olamamak hele,

Kısır çıkmazların içinde,çıkmaz sokaklarda,

içinden çıkamadığım o kör kuyu ve ellerin ve gözlerin,

Sıcaklığını CİZRE''den alan.

Birbaşıma önümde hesap defterim,

içinde bütün geçmişim,

Kuşkular içinde beklediğim geleceğim,

Ilık bir yaz gecesinde,

Elimde hesap defterim,

İçinde hüzünlerim,

Bu Benim...', 'Ilık bir yaz gecesinde,önümde hesap defterm, Herkesinki gibi kara kaplı İçinde hüzünlerim,kavgalarım,ağrıyan yanlarım. Bir labirent gibi, ka...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Cafer']::text[], 8.5, '{"poet":"Mehmet Cafer","poet_slug":"mehmet-cafer","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yaz-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın', 'sakin-mehmet-postalli-nqd0q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hilal kaşlarını bir yana eğip; 

Gamzeli yüzünü azdırma sakın

Bunca yıllık, sadık dostu çiğneyip

Yâd ellerde gönül gezdirme sakın

Açık yürekli ol söyle derdini

Çok severim insanların merdini

Vefalı ol, sev de sevdir kendini

Seveni yanından tezdirme sakın

Çok naza gerek yok, halden bilirim

Gönlün yoksa defterimden silerim

Selâmı, sabahı keser giderim

Adamı canından bezdirme sakın

Susup ta  içime düşürme şüphe

Doğru söz, kulakta eskimez küpe

Gözüme görünmez ova, dağ, tepe

Durmam buralarda kızdırma sakın', 'Hilal kaşlarını bir yana eğip;  Gamzeli yüzünü azdırma sakın Bunca yıllık, sadık dostu çiğneyip Yâd ellerde gönül gezdirme sakın Açık yürekl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sakin-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çivili Takunyalar', 'civili-takunyalar-ender-aslan-dogxu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdiye dek sevdiğim bütün kadınları,

Kalbime hapsettim

Ve çivili takunyalar giydirdim ayaklarına.

Bir de..

Bütün oturakları kaldırıp attım!

O günden beri,

Sevdiğim bütün kadınlar,

Ayaklarında çivili takunyalar,

Kalbimin dört bir yanında

Gezer tozarlar..', 'Şimdiye dek sevdiğim bütün kadınları, Kalbime hapsettim Ve çivili takunyalar giydirdim ayaklarına. Bir de.. Bütün oturakları kaldırıp attım!...', ARRAY['Türk Edebiyatı','Şiir','Ender Aslan']::text[], 8.5, '{"poet":"Ender Aslan","poet_slug":"ender-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/civili-takunyalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim için Hasretti İstanbul', 'benim-icin-hasretti-i-stanbul-aysin-ulug-s27b9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'benim için hasretti İstanbul

biraz hüsran

beni bana uzaklaştıran acılar

biraz huzurdu İstanbul

beni bende sağ tutan anılar..

ruhumu teslim ettiğim deniz kokusuyla

saçlarımı esir ettiğim meltemiyle

bir başkaydı benim için

İstanbul

gözlerine bakardım

gözlerimize

İstanbul olurdun olurduk gizlice

sesini duyardım

martılar kanat çırpardı

eski sahillerde

sesin bir martı çığlığı kadar yakın

bir martı kadar çabuk kaçardı

sesin

aklımı çok uzaklara götürürdü

Ankara sessizliğinde

benim için hayattı İstanbul

denizine vuran ayışığı gibi

yeditepesinde yedigün

yedigece aşık olmak gibi

benim için biraz sen

biraz bendi İstanbul

benim sen

sende ben olduğum gibi

yıllar mı geçti bilmiyorum

saymadım

sensiz dolaştım yine

ama hep sen vardın

hani bir gece iki çılgın

kaçıvermiştik ya bir mavi trenle

Beyoğlu ne kadar ışıklı

ne kadar farklı gelirdi

Kalamış ne kadar huzurlu

Moda bir o kadar sakindi

ve İstanbul hep kalabalık

korkmazdık

yaban bir şehre gelmiş olsak da

bilirdik İstanbul biraz sen

biraz da ben

şimdi yok o İstanbul

şimdi denizde tuz

melteminde huzur da yok

şimdi yoksun

ne sakin Moda

ne de farkı kaldı Beyoğlunun

yaralı kalbimizden başka

benzer bir martılar hala

martılar hala çığlık çığlığa..', 'benim için hasretti İstanbul biraz hüsran beni bana uzaklaştıran acılar biraz huzurdu İstanbul beni bende sağ tutan anılar.. ruhumu teslim e...', ARRAY['Türk Edebiyatı','Şiir','Ayşin Uluğ']::text[], 8.5, '{"poet":"Ayşin Uluğ","poet_slug":"aysin-ulug","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/benim-icin-hasretti-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aladağ', 'aladag-mehmet-postalli-mlzvg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gelecekler diye yollarımıza; 

Çimenlerden halı serdin Aladağ.                                                        

Hoş geldin diyerek, kollarımıza; 

Kucak kucak çiçek verdin Aladağ.

Sayısız pınarlar kaynar döşünden

Boranı pişirip, içtik aşından

Kimler gelip, geçmedi ki  başından

Anlat bize neler gördün  Aladağ

Bir yanın Dişdöken bir yanın Suna

O tertemiz havan, can katar cana

Dünyada hiçbir yer denk değil sana

Cennete misaldir yurdun Aladağ

Katar katar araç düşer yoluna

Gören hayran kalır Yedigölüne

Doyulur mu kaymağına, balına

Ekmeğime katık sürdün Aladağ

Göğcün’ le, Göktepe yamaç yamaca

Kızlar bazlamayı döşerler saca

Taze sütyüzüyü sürer sıkmaca

Kaç gencin düşünü yordun Aladağ

Mantarları en sarp yere gizlersin

Sevenlerim gelsin diye gözlersin

Bizler seni, sende bizi özlersin

Bütün gönüllere girdin Aladağ

Her zaman yanına varamıyoruz

Kış günü karları yaramıyoruz

Biz, seni görmeden duramıyoruz

Öldürecek bizi derdin Aladağ

Çıkın Yedigöz’ e  yaylayı  görün

Suları bengisu,  havası  serin

Fadime pınarı  toplanma yerin

Yahyalı’ ya  şenlik kurdun Aladağ', 'Gelecekler diye yollarımıza;  Çimenlerden halı serdin Aladağ.                                                         Hoş geldin diyerek, ko...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/aladag-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neye Tutunmak Gerek', 'neye-tutunmak-gerek-aysin-ulug-jr85s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neye tutunabilir insan

Bir nehrin iki kıyısından birinde

olmayı başaramamış

kendini nehirde bulmuşken

Neye değer eli

deli azgın sular sürüklerken denize bedenini

hangi dal sağlam kalır

neleri alır gider zaman

neleri bırakır yanında

gökyüzü kapkara

rüzgar alabora

neden bunca karanlık

mavi sularda....', 'Neye tutunabilir insan Bir nehrin iki kıyısından birinde olmayı başaramamış kendini nehirde bulmuşken Neye değer eli deli azgın sular sürükl...', ARRAY['Türk Edebiyatı','Şiir','Ayşin Uluğ']::text[], 8.5, '{"poet":"Ayşin Uluğ","poet_slug":"aysin-ulug","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/neye-tutunmak-gerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende Aşk', 'bende-ask-aysin-ulug-2d4nv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Korkularım beyaz kalsın 

ellerimde yaş 

umutlarım sende kalsın 

bende aşk 

gidiyorsun 

düşündün mü bilmem beni 

gidiyorsun ne kadar özlersin ki 

gecelerim koyuymuş 

varsın daha da koyulaşsın 

günlerim güneşsiz 

yağmurlu bir rüzgar olsun 

duvarlarda aynı afişler 

yarınları sen al 

bende aşk 

denizlere yağmur düşünce 

çoğalır mı dalgalar 

ya da güneşe bir mum yaksan 

neye yarar? 

gidiyorsun 

bende aşk... 

bir deli aşık olmuşum 

ne günüm 

ne gecem belli 

bir deli hasrete vurulmuşum 

ne dünüm 

ne yarınım belli 

gidiyorsun diyorum sürekli 

bende aşk 

sahi sevgilim 

sen geldin mi ki?', 'Korkularım beyaz kalsın  ellerimde yaş  umutlarım sende kalsın  bende aşk  gidiyorsun  düşündün mü bilmem beni  gidiyorsun ne kadar özlersin...', ARRAY['Türk Edebiyatı','Şiir','Ayşin Uluğ']::text[], 8.5, '{"poet":"Ayşin Uluğ","poet_slug":"aysin-ulug","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bende-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vicdansız', 'vicdansiz-mehmet-postalli-0pps3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkın ile tutuşturdun sinemi

İçin için yaktın behey vicdansız

Ben çekerken ızdırabı, elemi

Bir el gibi baktın behey vicdansız

Ağarmadık saç koymadın başımda

Belim yaya döndü şu genç yaşımda

Yürüyordum bir umudun peşinde

Hayallerim yıktın behey vicdansız

Sımsıkı sarıldın kuzu postuna 

Dost görünüp neler yaptın dostuna 

Hançer vurup yaraların üstüne

Birde kezzap döktün behey vicdansız

Yar dediğin kara günde bilinir

Gerekirse, yar  yoluna ölünür

Yar olmayan zor günlerde silinir

Yılan gibi aktın behey vicdansız

Sebat edip duramadın sözünde

Utanma duygusu yokmuş yüzünde

Sezemedim, özür varmış özünde

Çarmıhlara çaktın behey vicdansız

Sırf senin yüzünden düştüm bu derde

Mazlumların âhı kalmazmış yerde

Hakkımı alırım yarın mahşerde

Çok vefasız çıktın behey vicdansız.', 'Aşkın ile tutuşturdun sinemi İçin için yaktın behey vicdansız Ben çekerken ızdırabı, elemi Bir el gibi baktın behey vicdansız Ağarmadık saç ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/vicdansiz-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanayan Yara', 'kanayan-yara-ender-aslan-spcw2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonu olmalımıydı diyorum bazen.

Seni sevmelerimin bir sonu olmalımıydı? 

Açtığın yara kanarken

Akan kanımı bir kovada biriktirmen

İşe yaramayacak fark edemedin..

Sustum işte

Anlamlı bir sessizlik bu

Ve.. Yaramda bir tuzluk

Kapağı açık..! ! 

Depremler oldukça yüreğimde

Sallanır dökülür

Saçılır yarama

Belkide hep bu yüzdendir yaramın kapanmayışı..

Sonu olmalımıydı diyorum bazen.

Seni sevmelerimin bir sonu olmalımıydı?', 'Sonu olmalımıydı diyorum bazen. Seni sevmelerimin bir sonu olmalımıydı?  Açtığın yara kanarken Akan kanımı bir kovada biriktirmen İşe yarama...', ARRAY['Türk Edebiyatı','Şiir','Ender Aslan']::text[], 8.5, '{"poet":"Ender Aslan","poet_slug":"ender-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kanayan-yara-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük', 'ozgurluk-cemaleddin-ozmen-ka9ox', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'durma kayıkçı çek kürekleri,at ağlarını denize

ya nasip...

bakarsın özgürlükte takılır ağlarda ki balıklara...

özgürlüğün uğultusu içimde ürperiyor.

bir hüsran sesiyle ağıtlar yükseliyor.

sonsuzluğa giden yolda tek sesim

kararsızlıkta bıraktı bir geceyle gündüz arası...

hangi yolun sonunda,hangi yolun başındayım.

içimde sesler kesildi.avuçlar göğe yükseldi.

özgürlüğün tatlı pembesi zifiri karanlığa eşit sayıldı.

titretiyor içimi bir uçurum kenarı

rüzgar arkamda nefesim çimde çırpınıyor.

özgürlüğün mavi uykusu göz kapaklarıma kapanıyor.

apansız aşağı atıyor,özgürlüğü göğe bırakarak.

güneş geldiği gibi geri gidecek,birazdan...

özgürlüğün ışığı gözlerimden düşmüş olacak.

ne o benim kolumda,ne ben onun kolunda olacağım.

özgür olmayan bütün isimlerin yanına,bir de benim adım eklenecek.

yaşam su gibi akar,suyun üstünde ışıklar birden söner.

yaşam su gibi akar,yeraltında ışıklar birden yanar...

durma! kayıkçı çek kürekleri,at ağlarını denize

ya nasip...

bakarsın özgürlükte takılır ağlarda ki balıklara...', 'durma kayıkçı çek kürekleri,at ağlarını denize ya nasip... bakarsın özgürlükte takılır ağlarda ki balıklara... özgürlüğün uğultusu içimde ür...', ARRAY['Türk Edebiyatı','Şiir','Cemaleddin Özmen']::text[], 8.5, '{"poet":"Cemaleddin Özmen","poet_slug":"cemaleddin-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ozgurluk-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-ender-aslan-6rhx0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Başlangıç

Parlak bir ışık ve ağlama sesi

Uzun bir yol

Sonunda karanlık 

Ve suskunluk

Işığı gördüm

Ağladım...

Yol 

Bir labirent

Sonuna bakınıyorum

Arıyorum

Biliyorum ki

Sonu karanlık...

Yolda yürüyen 

O Bendim! 

Diye bağırabilmek için karanlıkta

Prangalar vurdum arzulara

Soğuk...

Nihayet ışık söndü

Işığı gördüm

Ağladım...

Karanlık...

Karanlığın sonu aydınlık...', 'Başlangıç Parlak bir ışık ve ağlama sesi Uzun bir yol Sonunda karanlık  Ve suskunluk Işığı gördüm Ağladım... Yol  Bir labirent Sonuna bakını...', ARRAY['Türk Edebiyatı','Şiir','Ender Aslan']::text[], 8.5, '{"poet":"Ender Aslan","poet_slug":"ender-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yasamak-175-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümü Yarıladı', 'omrumu-yariladi-mehmet-sait-akkus-tzc7l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül seni görmek ister

Yanağından öpmek ister

Buralardan gitmek ister

Aşkına yandıktan sonra

Ben duramam gideceğim

Yollarında öleceğim

Yüreğime gömeceğim

Sevdana taptıktan sonra

Gönül beni yaraladı

Kapıları araladı

Ömrümü yarıladı

Yüzüne baktıktan sonra', 'Gönül seni görmek ister Yanağından öpmek ister Buralardan gitmek ister Aşkına yandıktan sonra Ben duramam gideceğim Yollarında öleceğim Yüre...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/omrumu-yariladi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-mehmet-postalli-y1poh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gönül tutuldu mu bir vefasıza? 

Kolay kolay geçilmiyor arkadaş

Bir derdin var ise, ulaşır yüze

Dert çok ama açılmıyor arkadaş

Sırlıdır çözülmez gönül kitabı

Bir kalemde yapılmıyor hesabı

Zehirden keskindir aşkın şarabı

Dolu dolu içilmiyor arkadaş

Aldanırsın cilvesine, sözüne

Bilmeden düşersin sevda közüne

Süresi dolmadan çıkar izine

Zaman, sınır biçilmiyor arkadaş

Mecnun’ u çöllerde gezdirende o

Ferhat’ a dağları kazdıranda o

Şaire, şiirler yazdıranda o

Bu sevdadan kaçılmıyor arkadaş

Zincir vurulmuyor gönül tahtına

Acı, tatlı o yiğidin bahtına

Eğer inanmazsan birde sen sına

Seçilmiyor seçilmiyor arkadaş.', 'Gönül tutuldu mu bir vefasıza?  Kolay kolay geçilmiyor arkadaş Bir derdin var ise, ulaşır yüze Dert çok ama açılmıyor arkadaş Sırlıdır çözül...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/arkadas-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter ki', 'yeter-ki-nagahan-orbay-akay-gxr7z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hepimiz için doğuyor Güneş

Gülüyor gece dünyamıza Ay

Şu koca ömür tek bir ana eş

Şöyle bir baktım, geçiyorum say.

Kalp kırma, hoş gör, sevil, sev durma

Tüm güzellikler sevgide saklı

Aklını yalan yanlışla yorma

Gerçeğe dair söz eden haklı.

Sayısız alem, Dünya ne, geçit

Ben, ben mi o kim? Ne değil? Neyiz

Biinmez neden; nereye gel, git

Yeter ki kalsın silinmez bir iz.', 'Hepimiz için doğuyor Güneş Gülüyor gece dünyamıza Ay Şu koca ömür tek bir ana eş Şöyle bir baktım, geçiyorum say. Kalp kırma, hoş gör, sevil...', ARRAY['Türk Edebiyatı','Şiir','Nagahan Orbay Akay']::text[], 8.5, '{"poet":"Nagahan Orbay Akay","poet_slug":"nagahan-orbay-akay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yeter-ki-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay koynunda ışık', 'ay-koynunda-isik-selma-sengoren-o4yb7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıldızlar öpsün seni

Ay koynunda ışık

Günler can olsun

Her gün tazelenen

Yeni bir sen 

Dünden daha kalıcı 

Daha bir anlamlı

Koksun her yan

Tenin gibi can

Canım sana armağan

Yıldızlar öpsün seni 

Bu gece ay var

Yıldızlar armağan...', 'Yıldızlar öpsün seni Ay koynunda ışık Günler can olsun Her gün tazelenen Yeni bir sen  Dünden daha kalıcı  Daha bir anlamlı Koksun her yan T...', ARRAY['Türk Edebiyatı','Şiir','Selma Şengören']::text[], 8.5, '{"poet":"Selma Şengören","poet_slug":"selma-sengoren","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ay-koynunda-isik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardımda', 'ardimda-turk-oger-koc-xw392', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'binerken otobüse

ne kadar çok şeyler

bırakıyorum ardımda

benim olmayan

koskoca binalar

yollar kaldırımlar

bir cümle ile

sırtına vurmuş

umut dolu heybelerini

koşuşturan insanlar

yanaklarımdaki 

sıcaklığı alıp

oturuyorum koltuğa

el sallamaya hazır

ne kadar çok şey

bırakmışım ardımda

yanağım yanıyor

2005-11-17', 'binerken otobüse ne kadar çok şeyler bırakıyorum ardımda benim olmayan koskoca binalar yollar kaldırımlar bir cümle ile sırtına vurmuş umut ...', ARRAY['Türk Edebiyatı','Şiir','Türk Öğer Koç']::text[], 8.5, '{"poet":"Türk Öğer Koç","poet_slug":"turk-oger-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ardimda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaratan Seçti Seni', 'yaratan-secti-seni-mehmet-postalli-4t20n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bekliyor cümle âlem, büyük bir hazırlık var

Bin yıllık ateş söndü, yüzüstü düştü putlar

Yeryüzü nurla doldu, o gece fecre kadar

	Bir ilkbahar sabahı, Rabbim buyurdu ihsan

	Dünyaya şeref verdi, kadri yüce O, insan

Haşim oğullarının en güzide evladı

Dedesi tarafından Muhammed kondu adı

Mevla’m, susuz çölleri, rahmetiyle suladı

	Mekke’de çiçek açtı güllerin en goncası

	Gerçeğin taa kendisi, yalanın yabancısı

Nur dağında göz verdi abıhayat çeşmesi

Beytullahın damından yükseldi ezan sesi

Yırtıldı cehaletin zift karası  perdesi

	Devrildi birer birer, muhkem denen yapılar

	Kapandı mesafeler, aralandı kapılar

Ayet ayet inerek, Allah’ın emirleri

İnsanların zihninden arındırdı kirleri

Kuran’ın belâgatı susturdu şairleri

	Yaşantınla, sözünle hem rehber hem örneksin

	Yaratan seçti seni, iki cihanda teksin

Acının, ızdırabın en katısını tattın

Katı yüreklilere, yine sen el uzattın

Ve onların nesline hayır dualar ettin

	Peygamberler serdarı, âlemlere rahmetsin

	Müminlerin umudu, göz nuru Muhammed’sin

Gül kokulu, nur yüzlü, dili inciler saçan

İnsanlığın önüne yeni bir devir açan

Mekke’den çıkarılan ve Medine’ye göçen

	Muhacirler ulusu, ensarın mihmanısın

	Mazlumun sığınağı, dertlinin dermanısın

Yerlerde ve göklerde övülen emin kişi

Güzel huylu, pak soylu, yoktur başka bir eşi

Allah’ın sevgilisi, kâinatın güneşi

	Çekme üzerimizden, bereketli elini

	Gönül peteklerine, dolduralım balını

Yoksul bir zenci gibi, eşiğinden girseydim

Kapında köle olup, gül yüzünü görseydim

Bastığın topraklara baş koyup, yüz sürseydim

	Köleliğim kabul et ey Rasül’ ü -zişanım

	Sana ümmet olmakla arttı şerefim, şanım

Yolunun yolcusuyum hiçbir güç döndüremez

İçimin yangınını ummanlar söndüremez

Açlığım, susuzluğum hiç kimse dindiremez

	Şu sevdalı yüreğin canısın, cananısın

	İki cihan serveri, gönüller Sultanısın

Doğduğum topraklarda yaşıyorum gurbeti

Efendim, sen öğrettin sevgiyi, merhameti

Rabbim nasip eylesin, evinde ziyareti

	Cennet bahçene varıp eşiğine kapansam

	Gözyaşımla yıkanıp, senin aşkınla yansam', 'Bekliyor cümle âlem, büyük bir hazırlık var Bin yıllık ateş söndü, yüzüstü düştü putlar Yeryüzü nurla doldu, o gece fecre kadar 	Bir ilkbaha...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/yaratan-secti-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç', 'hic-nagahan-orbay-akay-4at7g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sakın, besleme kalbinde kin

Tüm sevgilerin özüne in

Ruhun kalsın saf, yürek pak, dinç

Kendi değerin sen, kendin biç.

Laf etme olur olmaz şeyi

Allah bilir kul, ağa, beyi

Dinle bilgece has kişiyi

Sonra, yolunu düz, doğru seç.

Duruca, gören gözle bakın

Güzel, candan, hoş tavır takın

Sev, sevil, güldür, gül, neş''elen, 

Heyecan duy, coş, mutlan, ye, iç.

Koşar, koşturur zalim zaman

Yorar yıpratır, hem pek yaman

Gerçekleşmez her özlem, sevdan

Şu yaşam adlı sınavdan geç..

Bir gün olunca vakit tamam

Hani köşk, saray, hani hamam

Kalan yalnızca adın ve nam

Yanında sevap, günah yükün

Götürdüğün ne var başka? Hiç..', 'Sakın, besleme kalbinde kin Tüm sevgilerin özüne in Ruhun kalsın saf, yürek pak, dinç Kendi değerin sen, kendin biç. Laf etme olur olmaz şey...', ARRAY['Türk Edebiyatı','Şiir','Nagahan Orbay Akay']::text[], 8.5, '{"poet":"Nagahan Orbay Akay","poet_slug":"nagahan-orbay-akay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hic-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimdeki Sızı', 'kalbimdeki-sizi-mehmet-postalli-ivwze', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bağrıma taş bastım, gözüme mendil; 

		Kalbimdeki sızı susmadı yine.

		Ya söndü, sönecek şu cılız kandil; 

		Kalbimdeki sızı susmadı yine.

		Dertlerimi açtım birçok hekime

		Dediler içinde dert küme küme

		Aldırma diyordum kendi kendime; 

		Kalbimdeki sızı susmadı yine.

		Başımı yasladım beton duvara

		Uykusuz gözlerim döndü pınara

		Buz koydum içimi kavuran nara; 

		Kalbimdeki sızı susmadı yine.

		Bir türlü gönlümü avutamadım

		Âlemin dilinde mecnundu adım

		Unuturum diye kurban adadım; 

		Kalbimdeki sızı susmadı yine

		Sımsıcak duygular bir bir pustu da 

		Düşlerim buz kesti mermer kutuda

		Umutları yıkan, tufan sustu da; 

		Kalbimdeki sızı susmadı yine

	               Diyar diyar kaçtım, koşar adımla

	               Çığ oldu hasretle düşen her damla

	               Ben, sevdamı yargıladım idamla; 

	               Kalbimdeki sızı susmadı yine.

                          Toprağa Bir Can Düştü isimli kitabımdan alınmıştır ve bu kitap Gündüz Yayınevi tarafından çıkartılmıştır.

www.gunduzkitabevi.com.tr', 'Bağrıma taş bastım, gözüme mendil;  		Kalbimdeki sızı susmadı yine. 		Ya söndü, sönecek şu cılız kandil;  		Kalbimdeki sızı susmadı yine. 		...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kalbimdeki-sizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cananım', 'cananim-mehmet-postalli-7wueh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben senin sevdana düştüm düşeli			

Göz yaşlarım durulmuyor cananım		

Sevda yolu, kara çalı döşeli			

Kıvrım kıvrım varılmıyor cananım			

Adını zihnime yazdı kalemim			

Bir saat görmesem artar elemim			

Seni uçurursam boş kalır elim			

Yalnız yuva kurulmuyor cananım			

İflah olmaz işler açtın başıma			

Mecnuna döndürdün, gezdim düşüme		

Acı söz söylersen gitmez hoşuma			

Dil yarası sarılmıyor cananım			

Fırtınalar koparırsın içimde				

Unutamam ak kıl bitse döşümde			

Sakın niçin deme, bu zor seçimde		

Kalbe sual sorulmuyor cananım			

Sırrını açmaktan haya ederim			 

El yanında gayretini güderim			

Eğer, hayır dersen çeker giderim; 			

Ama, sensiz durulmuyor Canan’ ım.', 'Ben senin sevdana düştüm düşeli			 Göz yaşlarım durulmuyor cananım		 Sevda yolu, kara çalı döşeli			 Kıvrım kıvrım varılmıyor cananım			 Adı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cananim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Örtünmeye Dair', 'ortunmeye-dair-alper-kuruk-lqyao', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karşı değilim asla örtün emrine hâşâ! 

İtirazım türbana! ne örtüye,ne başa...

Gün gelir kendi çözer türbanı kafasından

Endişem:kurtulamaz kısır saplantısından...

Allah örtün diyorsa beynini ört demiyor

Sana örtünsün diye tek tip örtü vermiyor.

Kusur örten Râb bile önüne set germiyor

Sana yol gösteriyor,türbanı önermiyor...

Örtün ki görünmesin tahrik eden süslerin

Süs diye tanımlanan takı ve göğüslerin.

Abdestin uzuvları açık kalsın ruhsat var

Bu yerler açık iken kul Huzura da çıkar...

Abdestte yıkanır yüz,eller dirseğe kadar

Ya mesh ya da yıkanır ayak bileğe kadar.

Bir de başa mesh ile bir abdest tamamlanır,

Abdestin organları örtü dışında kalır.

Sen bunları bilip de örtünüyorsan eğer

Bu örtünüş gerekli ve de matluba değer.

Baş örtüsü bu diye kendince yaratırsan

Bunun adı türbandır diye adlandırırsan...

Senin niyetin belli:dinî simge yaratmak

Bu kalkana sığınıp laikliğe su katmak...

Karanlıklar örterse nasıl ki kusurları,

Aydınlıklarsa açar ufuktaki surları.

Gel beynini açık tut,teslim ol Yaratan''a

Hizmetin böyle olur Vatana ve İmana.

Böyle yapmazsan senin eline birşey geçmez

Kadınlık onurunsa yüceliğe erişmez.

Sen anamsın, eşimsin,bacımsın ve kadınsın

Seni siyaset için araç eden utansın! 

Siyaset taciri o,örtüyü türban eder

Saltanatı uğruna o başı kurban eder...

Siyasî ol,kaptırma yakanı bezirgâna

Us kullanmak yaraşır '' SALİHAT - I  NİSVAN ''a...', 'Karşı değilim asla örtün emrine hâşâ!  İtirazım türbana! ne örtüye,ne başa... Gün gelir kendi çözer türbanı kafasından Endişem:kurtulamaz kı...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ortunmeye-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Kıydınız', 'nasil-kiydiniz-mehmet-postalli-rld4b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gelir, geçer gözlerimle severdim

Yazın gölgesinde hep serinlerdim

Kesilmiş  görünce  yıkılıverdim

          İdamına kimler vermiş kararı

          Faydasından çok mu idi zararı? 

Suçları ne boyunları vurulmuş? 

Dalı, kolu kaldırıma serilmiş

Bakmadı yüzüme, bana darılmış

          Bütün insanlara küsmüş sanırım

          Herkes seyre bakmış ona yanarım

Kelaynak yapmışlar, tavus kuşunu 

Yoluk yoluk yoldurmuşlar döşünü

Koparmışlar kanadını, başını

          Durun diyememiş bir duyarlı ses

          Çınarlar sahipsiz kes arkadaş kes

Yanından geçerken inilti duydum

Yaralı bağrına, başımı koydum

Kendimden utandım,sanki ben kıydım

          Sana değil, esas  bana kıydılar

          Yeşil gözlerinden mahrum koydular 

Çınarlar gururlu içinden ağlar

Mahzun duruşları yüreği dağlar

TEK çıkar yol katletmek mi ağalar? 

          Sanıyorum telinize dokunmuş! 

         Çınarların canlarına okunmuş

Başka yerden geçemez mi bu teller? 

Ziynetinden yoksun caddeler,yollar

İnfazına  imza  koyan  o  eller; 

          Selvi boylulara nasıl kıydınız? 

          Defteri kebire geçti kaydınız

Varsa arka çıkan bir ses, bir yürek

Özür dileyelim hem merhem sürek

Duygusuz olanın nesine gerek

         Eğer sorarsanız, neyin nesiyim

        Mazlumların, sessizlerin sesiyim.', 'Gelir, geçer gözlerimle severdim Yazın gölgesinde hep serinlerdim Kesilmiş  görünce  yıkılıverdim           İdamına kimler vermiş kararı    ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/nasil-kiydiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurban Ettik Sevgimizi', 'kurban-ettik-sevgimizi-celal-topo-9b7ae', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Korkunun koynundan çaldığımız

Bir aşk tı bizim ki

Doyasıya yaşayamadık

Kilitler vurduk karanlıkların

Aydınlığa açılan kapılarına

Suskun çığlıklarımız çürümeye terkedildi

Kurban verdik bir sevgiyi bir yalana

Sorguyu bekleyen günahlarımızda..

Hiç kendimiz için yaşamadık

Yasak pençeler arasında

Can çekişti bedenimizden kopan ruhumuz

Duvarlara dayadık düşlerimizi

Haberci güvercinler uçuramadık

Gökyüzü dar geldi bize

Şimdi ağlıyor çok yazık

Kurban ettik sevgimizi

Bir korkunun ellerinde.....



17 / 11 / 2005   Antalya', 'Korkunun koynundan çaldığımız Bir aşk tı bizim ki Doyasıya yaşayamadık Kilitler vurduk karanlıkların Aydınlığa açılan kapılarına Suskun çığl...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kurban-ettik-sevgimizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayende', 'sayende-seyfettin-bilal-ozluk-gu4ts', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nefes almak şimdi daha hoş

Bu aşkımın değerini anlamasanda

Varoldun şimdi bir başka heyecanlıyım

Seni kalbimle paylaştıkça daha mutluyum

Kokunu hissetmesemde burnumda tütsende

Biliyorum ki dünyanın en güzel kokuları sende...

Bu aşk benim yarınım

Gelip gelmeyeceğini bilmesemde

Bir nefes içime çekmesemde

Bir Allah''a birsana tapıyorken

Şimdi yaşamak seninle daha güzel...

Çekersem kokunu içime

Bir masum öpücük konduracağım alnına

Hayalimde de olsa başucuna oturup

Seni uyandırmak geçiyor içimden

Bunlar olmayacak hep süyadasın desende

Seninle nefes almak inan çok güzel...

Bir anlık heves hiç olmadın

Bedenine muhtaç değilim

Affet türtülerim hiç değilsin

Sen taptığım, kutsal saydığım mabedimsin

Bilirsin mabette günaha girilmez

Sen benim sevabımsın

Sen...

Sen''lerle başlayan en güzel varlığımsın

Dur bir daha nefes alayım

Sayende nefes almak şimdi daha güzel...', 'Nefes almak şimdi daha hoş Bu aşkımın değerini anlamasanda Varoldun şimdi bir başka heyecanlıyım Seni kalbimle paylaştıkça daha mutluyum Kok...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sayende-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum De', 'seni-seviyorum-de-seyfettin-bilal-ozluk-q06rr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Göğsünde bir noktalık yer aç

Sevmiyorsan da belli etme

Bir ufak tebessüm bana yeter

Sahte olsa da seni seviyorum de! 

Kelebek misali hafiftir yüreğim

Ne zaman miadım dolacak belli olmaz

Ona bir kaç saat özgürlük yeter

Yalan olsa da seni seviyorum de! 

Tutuklu bedenim birgün sana kalacak

Yolcusunu almış bu gemi limana demir atacak

Zincirleri sana ulaşırsa

İstemeden de olsa seni seviyorum de! 

Prangalarımı kopardım, isyan ettim

Lekesiz rüzgarlarımı bile hatırlamıyorum

Sev demem sevme demem

Bir kerecik seni seviyorum de!', 'Göğsünde bir noktalık yer aç Sevmiyorsan da belli etme Bir ufak tebessüm bana yeter Sahte olsa da seni seviyorum de!  Kelebek misali hafifti...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-seviyorum-de-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustukça', 'sustukca-seyfettin-bilal-ozluk-wh8ry', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sustukça eriyorum

Ben eridikçe herkes haykırıyor.

Sustukça yoruluyorum

Ben yoruldukça herkes koşuyor.

Sustukça derinleşiyorum

Ben derinleştikçe kalıyor.

Sustukça kopuyorum

Ben koptukça herkes asılıyor.

Sustukça kaybediyorum

Ben kaybettikçe herkes seviniyor.

Sustukça yoruluyorum

Ben sustukça herkes dinleniyor.

Sustukça yapraklanıyorum

Ben yapraklandıkça herkes buduyor.

Sustukça bitiyorum

Ben bittikçe...

Geriye ne kaldı ki ben bitince...', 'Sustukça eriyorum Ben eridikçe herkes haykırıyor. Sustukça yoruluyorum Ben yoruldukça herkes koşuyor. Sustukça derinleşiyorum Ben derinleşti...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sustukca-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Bu Söz Dinlemez...', 'gonul-bu-soz-dinlemez-alper-kuruk-18bon', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gibiler benzetmedir,yaşamım neye benzer? 

Gönlüm başını almış o da gönlünce gezer.

Ben çekerim bir yana, o çeker öte yana

Gönlüm takılmış kalmış gönülden anlayana.

İkimiz bir araya ah bir de gelebilsek

Bir daha ayrılmayız asla biz ölene dek.

Birinin yaptığını diğerimiz bozuyor

Ben gerçeğin peşinde,gönlüm ise tozuyor...

Birgün gelip geçecek ya ben ondan,o benden

Gönül tüm kurtulacak şu köhnemiş bedenden...

Ben de rahat edecek, o da rahat edecek

O uçup yükselecek,ben yerde dinlenecek...

Gönül bu...hep uçarı...daldan dala konacak

Bu gönlümün hâlinden hâlim nice olacak?', 'Gibiler benzetmedir,yaşamım neye benzer?  Gönlüm başını almış o da gönlünce gezer. Ben çekerim bir yana, o çeker öte yana Gönlüm takılmış ka...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gonul-bu-soz-dinlemez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldığım Nefessin', 'aldigim-nefessin-seyfettin-bilal-ozluk-du8gl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sensiz kalmak sana ulaşamamak beynimi yedikçe

Olduğun gibi kal değişme dedikçe

Seni her daim düşündükçe

Nefes almak bu kadar zor olmamıştı...

Bir damla dökülen gözyaşlarımı sildikçe

İsmin dilimin ucuna geldikçe

Seni sevdiğimi düşündükçe

Nefes almak bu kadar zor olmamıştı...

Izdırabım dinermi yanına gelince

Sana sarılıp kokunu içime çekince

Sen beni ''Seni Seviyorum'' deyince

Nefes almak bu kadar zor olur mu?', 'Sensiz kalmak sana ulaşamamak beynimi yedikçe Olduğun gibi kal değişme dedikçe Seni her daim düşündükçe Nefes almak bu kadar zor olmamıştı.....', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aldigim-nefessin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sen Değil', 'bu-sen-degil-ozan-turk-8h5v4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Burada,

Bir kış telaşesidir,

Sen, hiç kış olabilir misin? 

Baştan aşağı yaz,

Sen baştan aşağı baharsın

Bu sen değil.

Burada,

Fakir çocuklar gocuk siparişinde,

Onlar sende hiç üşür mü? 

Sende yalın ayak koşar çocuklar,

Senin dikenlerin bir tek onlara batmaz.

Belli ki

Bu sen değil.

Ben,

İlk defa korkuyorum,

İlk defa,

Bu kadar kanadığım,

Sen hiç korkutabilir misin? 

Senle, ben bambaşka bir ömürüm

Ölenlere

Yook

Bu sen değil,

Bu sen değil

ki

Bu ben yok.', 'Burada, Bir kış telaşesidir, Sen, hiç kış olabilir misin?  Baştan aşağı yaz, Sen baştan aşağı baharsın Bu sen değil. Burada, Fakir çocuklar ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bu-sen-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmzayla Vurulan Kuşlar', 'i-mzayla-vurulan-kuslar-hikmet-kavas-whnw2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yanlış makasa giren trenin sakar makinistiyim

içimden bir ses atla diyor pencereden

nerde o c-esaret

yalancıktan uygarcılık oynuyorum

çevremde sevilen bir kişiyim

içimden milyon kere afaroz edilmiş

yanlış makasa giren trenin sakar makinistiyim

düşlerini bir önceki istasyonda unutmuş

söyle ey hayat ben kimin nesiyim

bütün kuşlarım bir imzayla vurulmuş', 'yanlış makasa giren trenin sakar makinistiyim içimden bir ses atla diyor pencereden nerde o c-esaret yalancıktan uygarcılık oynuyorum çevrem...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Kavas']::text[], 8.5, '{"poet":"Hikmet Kavas","poet_slug":"hikmet-kavas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/imzayla-vurulan-kuslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakit birlik vakti', 'vakit-birlik-vakti-selim-basar-rlhku', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu sükunet bu huzur 

Ermeni yi kudurtur

Her fırsatta kardeşi

Kardeşime vurdurtur

Biz böylemiydik evvel

Kırılsın bu hain el 

“Türk Kürt” gardaştır bilin 

Gelmesin buna halel 

Analar benim anam 

Yiğitler benim canım 

Deyin hele gardaşlar 

Hangi birine yanım

Bilmezki kandırılan

Hangi davaya hizmet 

Burada azab-ı vicdan 

Ahirette hezimet', 'Bu sükunet bu huzur  Ermeni yi kudurtur Her fırsatta kardeşi Kardeşime vurdurtur Biz böylemiydik evvel Kırılsın bu hain el  “Türk Kürt” gard...', ARRAY['Türk Edebiyatı','Şiir','Selim Başar']::text[], 8.5, '{"poet":"Selim Başar","poet_slug":"selim-basar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/vakit-birlik-vakti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimin Sesinden', 'yuregimin-sesinden-gulcan-sakal-s4mr5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçim acıyor yine bu gece 

Anlamıyorum sensizlikmi daha zor

Senle olan hayatım mı? 

Ben umudumu kattım önüme

Arkasında yanmış yüreğimle,

Sana geliyorum

Uzat elini ne olur

Bitsin bu acı demiyeceğim

Bitmeyecek...

Dinmeyecek sevdam

Neden en güzel anılar geride kalır

Ve neden taşır geleceğe bütün hüznünü

Yüreğimin sana ihtiyacı var

Bırakma sevgimi yanlız başına

Benim değil onun ihtiyacı var sana

Al sevgimi al artık', 'İçim acıyor yine bu gece  Anlamıyorum sensizlikmi daha zor Senle olan hayatım mı?  Ben umudumu kattım önüme Arkasında yanmış yüreğimle, Sana...', ARRAY['Türk Edebiyatı','Şiir','Gülcan Sakal']::text[], 8.5, '{"poet":"Gülcan Sakal","poet_slug":"gulcan-sakal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yuregimin-sesinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zannetme ki Sen! ..', 'zannetme-ki-sen-ahmet-tevfik-ozan-jedze', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zikrinde yanmış gönül; yar ey, ateş bilmezsin! 

Bir nur ki gönül, latif; ona ne eş bilmezsin! 

‘‘Aksi, belki gözlerin; bir damla suda berrak

Yıkayan kainatı nedir Güneş? “Bilmezsin! ...', 'Zikrinde yanmış gönül; yar ey, ateş bilmezsin!  Bir nur ki gönül, latif; ona ne eş bilmezsin!  ‘‘Aksi, belki gözlerin; bir damla suda berrak...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zannetme-ki-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman İpinde Zerre', 'zaman-i-pinde-zerre-ahmet-tevfik-ozan-pilwc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir berrak suya baktım: ‘‘Hayat’’tan bir elbise

Giydi, çıktı; bir güle, gonca gonca al oldu! 

Tuttu Güneş, elinden; kainat sarayında

Bir zehirli böceğin dudağında bal oldu!', 'Bir berrak suya baktım: ‘‘Hayat’’tan bir elbise Giydi, çıktı; bir güle, gonca gonca al oldu!  Tuttu Güneş, elinden; kainat sarayında Bir zeh...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zaman-ipinde-zerre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-ahmet-tevfik-ozan-01ev4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilmem ki, yelkovanın süpürdüğü kadranda 

Alnımı hangi çizgi, ansızın parçalamış? 

Hangi beyaz güvercin, küçücük kanadıyla

Tülden bir perde gibi bahtımı paralamış? ..

En kuytu bir kaldırım köşesinde boy atmış

Hangi baldıran otu, kök salmış gözlerime? 

Ve hangi kırlangıçlar gece gündüz durmadan

Bir yaşlı kaya gibi üşüşmüş ellerime? ..

Bir sevgi bulutundan dalga dalga yayılan

Bir hüzün yağmurudur, gözlerimdeki mezar..

Bir kanlı hançer gibi kanla sevişen kalbim

Bir uysal sevgilide, ne bulur... neyi arar?

Artık kızıl bir tütsü, yaksın bedenimizi

Akşamlar, bir yarayı hançerlemekten bıksın

Bir sonsuz bekleyişte bulalım kendimizi

Saatler avcumuzdan nehirler gibi aksın...', 'Bilmem ki, yelkovanın süpürdüğü kadranda  Alnımı hangi çizgi, ansızın parçalamış?  Hangi beyaz güvercin, küçücük kanadıyla Tülden bir perde ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zaman-257-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Hayat', 'ey-hayat-gulcan-sakal-mcd8s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Öyle boşum ki sana karşı

Ama senden bekliyorum birşeyleri

Biliyorum yok sende de yarın

Sen de bekliyorsun emri 

Sen de boyun eğiyorsun benim gibi''', '''Öyle boşum ki sana karşı Ama senden bekliyorum birşeyleri Biliyorum yok sende de yarın Sen de bekliyorsun emri  Sen de boyun eğiyorsun beni...', ARRAY['Türk Edebiyatı','Şiir','Gülcan Sakal']::text[], 8.5, '{"poet":"Gülcan Sakal","poet_slug":"gulcan-sakal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ey-hayat-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilerim Son Olsun', 'dilerim-son-olsun-zahide-handan-erengil-j9mqp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ana,baba,çocuk,eş,hep gözü yaşlı,

Gönüller umulmaz acı ile yaslı,telaşlı.

Sel olmuş,gözlerden akan yaşlar,

Kasılmış bedenler,çatılmış kaşlar.

Hala eğilmemiş dimdik başlar.

Bayrağa sarılı,bir tabut gidiyor.

Bir ağıt,bir hıçkırık,yürekleri inletiyor.

Yine kör olası terör aldı yiğidi,

İşte bir yuva daha sönüyor.

Yaşamının baharında,gencecik,

Yiğidim toprağa giriyor.

Bu terör ne zaman bitecek? 

Bu millet daha kaç şehit verecek? 

Hasretle alev,alev yanan gönüller,

Analar,babalar hep evlat yolu bekler.

Kim bilir onları ne zaman görecekler? 

Belki de hiç göremeyecekler.

Ya kocasız gelinler,babasız yetimler? 

Onlara ne olacak? 

Dertlerine kim çare bulacak? 

Daha can yanmadan,terör son bulsun,

Dilerim bu şehit artık son olsun.', 'Ana,baba,çocuk,eş,hep gözü yaşlı, Gönüller umulmaz acı ile yaslı,telaşlı. Sel olmuş,gözlerden akan yaşlar, Kasılmış bedenler,çatılmış kaşlar...', ARRAY['Türk Edebiyatı','Şiir','Zahide Handan Erengil']::text[], 8.5, '{"poet":"Zahide Handan Erengil","poet_slug":"zahide-handan-erengil","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dilerim-son-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunda Sen', 'yoklugunda-sen-ahmet-tevfik-ozan-jkom6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen kahve köşelerinde, sigara dumanı 

Çatlayan dudaklarımdaki kuruluk...

İçimden böyle geldi, sevgilim..

Yoksa, sana bir dargınlığım yok...', 'Sen kahve köşelerinde, sigara dumanı  Çatlayan dudaklarımdaki kuruluk... İçimden böyle geldi, sevgilim.. Yoksa, sana bir dargınlığım yok......', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yoklugunda-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunda', 'yoklugunda-ahmet-tevfik-ozan-fkoog', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir rüzgar esmektedir kapılardan

Rüyalar, darmadağındır! 

Türküler bir başka hüzünlü..

Yalnızlık, düğüm düğümdür! ...

Bir sıcak kar yağmaktadır, gönlüne

Gözlerin öylesine dolu

Gönlün öylesine karadır..

Gözyaşın, sessiz geceler boyunca yapayalnız 

Denize, denizlere uzanmaktadır! ...

Bir sevgi kaynamaktadır içinde

Yağmurlar onunla yağacaktır..

O taşıp yağmur olmazsa

Bir gün seni boğacaktır! ...

Bırak onu, yokluğunda yaşasın..

Var olduğu gibi ölmeyecektir! ...

Kimseler bilmez iken varlığını

         Her şey, yokluğunu söyleyecektir! ...', 'Bir rüzgar esmektedir kapılardan Rüyalar, darmadağındır!  Türküler bir başka hüzünlü.. Yalnızlık, düğüm düğümdür! ... Bir sıcak kar yağmakta...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yoklugunda-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoklar Arasında', 'yoklar-arasinda-ahmet-tevfik-ozan-236c2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüzyıl öncesinde; yoktum… hakikat! 

Yüzyıl sonrasında, olmayacağım...

Yer yüzünde zerre zerre bir feryat:

Yoklar arasında, Ben nasıl varım? ! ...', 'Yüzyıl öncesinde; yoktum… hakikat!  Yüzyıl sonrasında, olmayacağım... Yer yüzünde zerre zerre bir feryat: Yoklar arasında, Ben nasıl varım? ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yoklar-arasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalvarış', 'yalvaris-abdullah-odabas-72vrf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüzüm tuttum dergahına,                 	

Hidayet kıl bize yarap,                 		

Gönül evim perişandır,                  		

Hidayet kıl bize yarab.                 		

Evlat ayal hep aldandık,                		

Zalim nefs narına yandık,               		

Dünya baki kalır sandık,                		

Hidayet kıl bize yarab.                 		

Bağışla ismi azama,			

Hem kabeyi muazzama,			

Bağışla ab-ı zemzeme,			

Hidayet kıl bize yarab.			

Uyandır gönül gözümü,

Uyandır oğul, kızımı,

Yad eyle açmam razımı,

Hidayet kıl bize yarab.

Münacatım kabul buyur,

Hikmet sözün bize duyur,

Yanar gönlüm cayır cayır,

Hidayet kıl bize yarab.

Meftuni bir sefil kuldur,

Lutfunla sen anı güldür,

Rızan olan yolu buldur,

Hidayet kıl bize yarab.', 'Yüzüm tuttum dergahına,                 	 Hidayet kıl bize yarap,                 		 Gönül evim perişandır,                  		 Hidayet kıl ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yalvaris-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalemim Ayrılıkta Rehin....', 'kalemim-ayrilikta-rehin-dilek-egri-0bl8l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '/..sana yazarken bile içim yanıyor, şiirlerim buyüzden is kokuyor../

tutuşuyor 

kağt, kalem

hayaller, sitemler

/..gözlerim başlayın ağlamaya şiirim elden gidiyor../

avazım çıktığı kadar susuyorum

parmaklarım dişlerimin arasında

nasıl oldu diyorum / nasıl oldu 

hani seviyordu? 

/..anılar getirin yalancı şahitleri

...gözleri, sözleri, hani birde utangaç öpüşü yüreğim inanmıyor.../

pembe elbiseler seçiyorum kendime pembe düşlerde

üstüme siyah ayrılık dökülüyor

yıkıyorum bembeyaz umutlarla 

/..aşk leke almış eskisi gibi olmuyor.../

gidiyorum bu yangın yerinden

ne filiz biter ne tomurcuk

uykusuzluğun içinden geçip geceye

ardından bir tarafı yalnızlık sabahlara gidiyorum...

/..geceler kaldırın acıları üstümden,ayrılığın altında kaldım../

yüreğim kırıldı 

şiirlerim akıyor...

sendeledim sende...', '/..sana yazarken bile içim yanıyor, şiirlerim buyüzden is kokuyor../ tutuşuyor  kağt, kalem hayaller, sitemler /..gözlerim başlayın ağlamaya...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kalemim-ayrilikta-rehin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zerreler ve Sen', 'zerreler-ve-sen-ahmet-tevfik-ozan-g0zn1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ermez aklım, bir zerrenin yoktan var olduğuna

Sen ki bir can, sen ki canan, sen ki fidan gibisin! 

Nasıl ersin, zerrelerden bin hayat doğduğuna? 

Sen ki bir can, sen ki canan, sen ki fidan gibisin! ...', 'Ermez aklım, bir zerrenin yoktan var olduğuna Sen ki bir can, sen ki canan, sen ki fidan gibisin!  Nasıl ersin, zerrelerden bin hayat doğduğ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zerreler-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarab', 'yarab-abdullah-odabas-ul929', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Er geç sana varacağız,                  		

Yüzüm kara etme yarap,                  	

Katiplerim günüh yazar,                 		

Defterimde yoktur sevap.                	

Nefs-i heva evim yıkar,                 		

Düşündükçe aklım çıkar,                 	

Aman yarap bizi kurtar,                 		

Yandı ciğer oldu kebap.                 		

Aklı kamil nesib eyle,

Nur-ı iman refik eyle,

Halime bak şefik eyle,

Yoksa işim oldu harap.

Etme bizi senden cüda,

Ya vahid-ü samet Hüda,

Nefis zalim ben bir geda,

Aşk abından ver bir şarap.

Leyl-ü nehhar hep yanayım,

Şarabı aşka kanayım,

Meftuni, ben ağlayayım,

Gönlüm gözüm oldu harap.', 'Er geç sana varacağız,                  		 Yüzüm kara etme yarap,                  	 Katiplerim günüh yazar,                 		 Defterimde y...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yarab-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Ver Gözlerini', 'hadi-ver-gozlerini-sahin-karakulunc-dg60b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerin,

Gözlerime değdiğinde,

Bir umut,

Bir umut büyür yüreğimde

Tutunurum,

Tutunurum da kirpiklerine

Düşmeden yürürüm.

Gözlerin,

Gözlerime aktığında,

Bir çığlık,

Bir çığlık yükselir kulaklarımda

Avunurum

Sığınırım da sesine

Ansızın gelirim.

Gözlerin,

Gözlerin alır  beni

Bir yelken,

Bir yelken açılır  gönlümde

Binerim

Binerim de yelkenine

Rüzgarın olurum.

Gözlerin,

Gözlerin benim olduğunda

Bir kahve,

Bir kahve pişer  bakışlarında

İçerim,

İçerim de gözlerinden

Kırk yıllık dostun olurum.

Hadi,

Hadi ver gözlerini

İçerim kahvesinden.

19 Eylül 2005, Devrek

(Geçmiş olsu O Gözlere, şimdi sağlığı daha iyi olacak)', 'Gözlerin, Gözlerime değdiğinde, Bir umut, Bir umut büyür yüreğimde Tutunurum, Tutunurum da kirpiklerine Düşmeden yürürüm. Gözlerin, Gözlerim...', ARRAY['Türk Edebiyatı','Şiir','Şahin Karakulunç']::text[], 8.5, '{"poet":"Şahin Karakulunç","poet_slug":"sahin-karakulunc","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hadi-ver-gozlerini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Yüzlüme...', 'ay-yuzlume-i-brahim-ethem-bingul-dmn4k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nerde kalmış gülen yüzün

Gözlerine sürme artık hüzün

Acıtır oldu her sözün

Ay ışığında ağlatma beni...

Hayat acı, tatlı göründüğü kadar

İnsanlar dönek,dost oldukları kadar

Ölüm aşikâr, hayat gerçeği kadar

Ay ışığında söyletme beni...

Mutluluğun yel misali esti

Gençlik bir rüyaydı, uyandın bitti

Koskoca bir ömür geldi ve geçti

Ay ışığı yüzlüm daha söyletme beni...

www.iebingül.com', 'Nerde kalmış gülen yüzün Gözlerine sürme artık hüzün Acıtır oldu her sözün Ay ışığında ağlatma beni... Hayat acı, tatlı göründüğü kadar İnsa...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ay-yuzlume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuz Bir Kaçış...', 'umutsuz-bir-kacis-pinar-koc-38wji', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Buralardan kaçtığımı zannediyorum

Senide yanımda götürdüğümün 

Farkında bile değilim…

Ölümsüzlüğü taşıyorum belki kalbimde,

Belki yarınlarımı veriyorum avuçlarına! 

Umutsuz haykırışlarımda

Sesimi duyuyor musun? 

Sensizliği yaşadığım günleri

Hissediyor musun? 

Öldüğümü duyuyor musun? 

Sessiz derinden…

Buralardan kaçtığımı zannediyorum

Senide yanımda götürdüğümün 

Farkında bile değilim aslında…

Sevgini taşıyorum belki kalbimde

Belki umutlarımı veriyorum avuçlarına…

                                                             6.9.2001

                                                          Perşembe   18:15', 'Buralardan kaçtığımı zannediyorum Senide yanımda götürdüğümün  Farkında bile değilim… Ölümsüzlüğü taşıyorum belki kalbimde, Belki yarınlarım...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/umutsuz-bir-kacis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözün Aydın', 'gozun-aydin-mehmet-postalli-7illz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğimden, can  bağımı  kopardın

Gözün aydın dostum, dediğin oldu

Ne yaptın da canı, candan ayırdın

Gözün aydın dostum, dediğin oldu

Bundan sonra, açık gitmez gözlerin

Çok morfinden tesirliymiş sözlerin

Hiç hakkı, hukuku yokmuş bizlerin

Gözün aydın dostum, dediğin oldu

En  acı  biberi  ağzıma  sürdün

Doktora yaptırdın, büyük ders verdin

Türlü oyunlarla, ipe un serdin

Gözün aydın dostum, dediğin oldu

Kanaryamı efsunladın, susturdun

Umudumu  kar suyuna bastırdın

Yıktın beni, bu dünyaya küstürdün

Gözün aydın dostum, dediğin oldu

İki gülü vardı, bizim  bahçenin

Değeri olmazdı malın, akçenin

Kırdın kanadını,  sessiz serçenin

Gözün aydın dostum, dediğin oldu

Bir daha yürümem, gittiğin yoldan

Şüphelenir oldum artık her kuldan

Çok hoştu, tatlıydı kaymaktan, baldan

Gözün aydın dostum, dediğin oldu

Sevgi saygı vardı her şeyden öte

Toplattın  bohçayı  yüklettin  ata

Gayrı, bizim ocak yanmaz ki, tüte

Gözün aydın dostum, dediğin oldu

Bulut olmayınca kar, dolu yağmaz

Rüzgar  esmeyince  dalları  eğmez

Senin yaptıkların, dostluğa sığmaz

Gözün aydın dostum, dediğin oldu

Can Çiçeğim İsimli Kitabımdan alınmıştır.', 'Yüreğimden, can  bağımı  kopardın Gözün aydın dostum, dediğin oldu Ne yaptın da canı, candan ayırdın Gözün aydın dostum, dediğin oldu Bundan...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gozun-aydin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz gecelerde...', 'sensiz-gecelerde-ercan-akbay-2ybp9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne sen git,ne ben ışıksız kalayım

        Biliyorsun karanlıktan korkarım

        Sensiz gecelerde.........

                                      17.11.2005 B.evler.', 'Ne sen git,ne ben ışıksız kalayım         Biliyorsun karanlıktan korkarım         Sensiz gecelerde.........                                 ...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sensiz-gecelerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelimelerimin Bittiği Yer...', 'kelimelerimin-bittigi-yer-cigdem-simsek-8gdjj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölümün soğuk dudakları öperken bedenini, 

Ellerini tutmak isterdim, öylece...

Yanında durup cennet  bahçelerinin güzelliklerini anlatlmak isterdim sana...

Korkmayasın diye karanlıktan...

Yüreğim unutmayacak seni ve hep gülümseyerek hatırlayacak...

Bileceğim ki kelimelerimin bittiği yerde sen günahsız çıktın yolculuğuna...', 'Ölümün soğuk dudakları öperken bedenini,  Ellerini tutmak isterdim, öylece... Yanında durup cennet  bahçelerinin güzelliklerini anlatlmak is...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kelimelerimin-bittigi-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairler / Şiir Perisine', 'sairler-siir-perisine-i-brahim-usta-izrl7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaleminin ucunda içindeki duygular

Beyaz kâğıt üstünde düşünceler, kurgular

Birkaç satır içinde kendine dünya kurar

Elinde kelimeler, resim çizer şairler...', 'Kaleminin ucunda içindeki duygular Beyaz kâğıt üstünde düşünceler, kurgular Birkaç satır içinde kendine dünya kurar Elinde kelimeler, resim ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Usta']::text[], 8.5, '{"poet":"İbrahim Usta","poet_slug":"i-brahim-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sairler-siir-perisine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Olma Erki', 'i-nsan-olma-erki-abdulvahap-ates-5mvt9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zulümden tırstığında! ? E? 

Ve kaçacak zamanın kalırSa

Ha zor gelirse erkekliğe Bu

Lut’un sabrını gösterecek değilsin Ya

Ya da,sürünerek te kaçarSan

Ki güdülmeye elverişli-y-Sen

Delemeden makus talihiNi

Kah aktini unutursan

ademliğinLe

Şşşt dikkat farkın kalmaz hayvandan', 'Zulümden tırstığında! ? E?  Ve kaçacak zamanın kalırSa Ha zor gelirse erkekliğe Bu Lut’un sabrını gösterecek değilsin Ya Ya da,sürünerek te ...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Ateş']::text[], 8.5, '{"poet":"Abdulvahap Ateş","poet_slug":"abdulvahap-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/insan-olma-erki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigara', 'sigara-oguzkan-bolukbasi-6qv8b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tutuşmamış bir sigara 

Parmak uçlarımı yakıyor

Acıya tapınıyor sanki yürekler

Bir sevinç dalgası gelecek korkusu sarıyor atardamarlarını aşkın

Kim söyleyecek yanlış olanı

Doğruyu duymaya ürkekler bin yıldır

Haydi kaldır başını bana bak desem

Gözlerin uzaklara kaçıyor

Ardında yalnızlıkları bırakıp

Tutuşmamış bir sigara

Parmak uçlarımı yakıyor

Bir utanma duygusuyla avuç içimde saklıyorum ateşi

Dumanı görünmesin yanmamış tütünün

Yarama bastığım yeri onaracak demiştin

Haberini bile alamayacaksın öldüğümün

Acıya bu denli dost olmak nedendir

Yaşamın hangi şeklidir mutluluk

Hangi toprakta yeşerir solmayan çiçekler

Kim sonsuzluğu bekler ufka dalıp her ölüm üstü

Renkler niye küstü, hep siyahtan gidiyor dokuması hayatın

Gülüşlerimi ağzıma tıkıyor bu kötülükler

Asıp geziyorum ki suratımı

Deli demesinler

Bari çocuklar gülebilseler

Tutuşmamış bir sigara

Parmak uçlarımı yakıyor

Ağlamaya çanak tutuyor gazeteler

Hangi hakkını alacaksın, yaşama hakkın sokaklarda kapkaça düşmüş

Mutluluk yalnızlıkta saklanıyor

Yalnızlık kentin en orta yerinde

Ben senin gözlerinde

Haydi yak sigaramı…….', 'Tutuşmamış bir sigara  Parmak uçlarımı yakıyor Acıya tapınıyor sanki yürekler Bir sevinç dalgası gelecek korkusu sarıyor atardamarlarını aşk...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sigara-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Araba Ateşi (hüzünlü bir Paris hikayesi)', 'araba-atesi-huzunlu-bir-paris-hikayesi-sait-muharrem-say-l2dmg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duvar koydukça

kendini kapatan

FRANSA! 

Elitlerin Fransa''sı

koltukaltına sıkıştırdığın

salıncaksız göçmen çocuklarını göster

banliyö gençlerinin

araba ateşi akıtmasaydı yüzündeki boyayı

bilmeyecektik 

her kıvrımını kuşkusuz görebilelim diye

dön güneşe

göster yüzünü,

yepyeni gökkuşakları tasarlamak için 

akan boyalarından,

göster yüzünü....

#17 Kasım 2005#', 'Duvar koydukça kendini kapatan FRANSA!  Elitlerin Fransa''sı koltukaltına sıkıştırdığın salıncaksız göçmen çocuklarını göster banliyö gençler...', ARRAY['Türk Edebiyatı','Şiir','Sait Muharrem Say']::text[], 8.5, '{"poet":"Sait Muharrem Say","poet_slug":"sait-muharrem-say","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/araba-atesi-huzunlu-bir-paris-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmaz Güzelim', 'olmaz-guzelim-seyhmus-sait-aydin-tjcwt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'OLMAZ GÜZELİM

Ben topraktan geldim ona dönerim, 

Sana eyvallahım olmaz güzelim. 

Dalından kopmuşsun elde kalmışsın, 

Dalında koklanan gül, solmaz güzelim 

Pişman olup dönüp bana gelsen''de 

Sevgilim,birtanem,aşkım desen''de 

karşımda elpençe divan dursan''da 

Ben kansam yüregim kanmaz güzelim 

Boz bulanık akan sele dönmüşsün 

Esip buz tutturan yele dönmüşsün 

Yanar dag gibiydin küle dönmüşsün 

Sönmüş kül tutuşup yanmaz güzelim 

Çok kalp kırıp döktün vermedin aman 

sevenin kalmadı bak oldun duman 

Şu fani dünyadan göçtüğün zaman 

Hiç kimse adını anmaz güzelim 

14.06.2005', 'OLMAZ GÜZELİM Ben topraktan geldim ona dönerim,  Sana eyvallahım olmaz güzelim.  Dalından kopmuşsun elde kalmışsın,  Dalında koklanan gül, s...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/olmaz-guzelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak kalsın..', 'birak-kalsin-ece-ozbek-ortos', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzaklarda

çok uzaklardasın

bilmediğim zamanda

düşlediğim 

anlardasın

sakın gelme! 

bırak..

kalsın

bırak.

kalsın', 'Uzaklarda çok uzaklardasın bilmediğim zamanda düşlediğim  anlardasın sakın gelme!  bırak.. kalsın bırak. kalsın...', ARRAY['Türk Edebiyatı','Şiir','Ece Özbek']::text[], 8.5, '{"poet":"Ece Özbek","poet_slug":"ece-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/birak-kalsin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader ne yapsın', 'kader-ne-yapsin-cem-cagman-21izy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dalmışım derinlere çıkamıyorum

gözlerim seni arıyor bulamıyorum

bağlandığımda kolay kopamıyorum

seni sevmelere doyamıyorum

alnımıza yazılan böyleymiş kader

doğmasa güneş olmasa seher

oraya yazdıkların doğruysa eğer

yıllarca beklemeye senin için değer

kaderin önüne geçmek ne mümkün

sevgiliyi iyilerden seçmek ne mümkün

bahtın karayılsa olacak acılı türkün

ben gibi memleketinde yaşarsın sürgün

şiirlerde kadere hep vurulurmuş

kadere kızıpta seven ne yapsın

dengini sevmeyen hep kovulurmuş

kalbi söz dinlemeyen cem ne yapsın

en güzel aşklar gözlerde başlar 

ellerin titrer yanar kavrulur tenler

aramaya başlar seven o gözler

kalbinden beynine akar değerli sözler

eli eline değse yakar tenini

bir dokunuşuyla eritir seni

kulağında çınlar ettiği sözler

onu görmek için fırsat ararsın

aynı şeyleri yaşarsın onun ardından

değişmeyen kanun bu aşk kitabından

sarılmak istersin hemen boynundan

ellerin titrer sesin kısılır beceremezsin

aşkı aşığı yaradan koymuş bu kanunu

söyleyemezsin sevdiğini düşünürsen sonunu

acabalar la geçirinsin kalan ömrünü

senin suçundur bu kader ne yapsın', 'dalmışım derinlere çıkamıyorum gözlerim seni arıyor bulamıyorum bağlandığımda kolay kopamıyorum seni sevmelere doyamıyorum alnımıza yazılan ...', ARRAY['Türk Edebiyatı','Şiir','Cem Çağman']::text[], 8.5, '{"poet":"Cem Çağman","poet_slug":"cem-cagman","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kader-ne-yapsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Matruşka', 'matruska-ece-ozbek-2s4ra', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana matruşka olayım

böl

beni

dağıt

beni

topla

beni', 'Sana matruşka olayım böl beni dağıt beni topla beni...', ARRAY['Türk Edebiyatı','Şiir','Ece Özbek']::text[], 8.5, '{"poet":"Ece Özbek","poet_slug":"ece-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/matruska-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dargınım', 'darginim-fatih-atar-2n8w8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk destanını okuyan bülbülü

Anlamayan güle dargınım artık

Bir ateş ki yaktı gitti gönülü

Savrulmayan küle dargınım artık

Pes etmek belki yok bu yolda

Ancak bir tahammül olur her kulda

Darılan yaprak durmazmış dalda

Koparmayan yele dargınım artık

Gönül terazisinde her şeyi tarttım

Dünyalık ne varsa hepsini attım

Aşkın şarabından bir kere tattım

Tekrar tadan dile dargınım artık

                         Fatih Atar

                      27/01/2004', 'Aşk destanını okuyan bülbülü Anlamayan güle dargınım artık Bir ateş ki yaktı gitti gönülü Savrulmayan küle dargınım artık Pes etmek belki yo...', ARRAY['Türk Edebiyatı','Şiir','Fatih Atar']::text[], 8.5, '{"poet":"Fatih Atar","poet_slug":"fatih-atar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/darginim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Anlatır', 'seni-anlatir-fatih-atar-m6a4e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güz mevsiminin hüzülü yeli

Seni söyler bana seni anlatır

Dertli yüreklerin şakıyan dili

Seni söyler bana seni anlatır

Çileli bir kışın masum baharı

Dertli türkülerin çöken efkarı

Yalçın dağların hoyrat rüzgarı

Seni söyler bana seni anlatır

Kapanmazmış hasretliğin yarası

Şimdi geldi özlemenin sırası

Dadaloğlu Koçköroğlu narası 

Seni söyler bana seni anlatır

                     Fatih Atar

                   13/11/2005', 'Güz mevsiminin hüzülü yeli Seni söyler bana seni anlatır Dertli yüreklerin şakıyan dili Seni söyler bana seni anlatır Çileli bir kışın masum...', ARRAY['Türk Edebiyatı','Şiir','Fatih Atar']::text[], 8.5, '{"poet":"Fatih Atar","poet_slug":"fatih-atar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-anlatir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbetten Sürgün', 'gurbetten-surgun-koksal-akar-ktgwq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Takılır gölgesine ayaklarım, her günün, 

Gözyaşında gözüm var, gurbetlerden sürgünün.', 'Takılır gölgesine ayaklarım, her günün,  Gözyaşında gözüm var, gurbetlerden sürgünün....', ARRAY['Türk Edebiyatı','Şiir','Köksal Akar']::text[], 8.5, '{"poet":"Köksal Akar","poet_slug":"koksal-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/gurbetten-surgun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler (104) ''Oy Nazile Nazile...''', 'maniler-104-oy-nazile-nazile-abdullah-atay-4h3sb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Oy Nazile Nazile

Şimdi gelir saz ile

Sazı sözü bırakıp

Göbek atar naz ile...

Kızın adı Müyesser

Tablo gibi şaheser

Huyu, güzelliğiyle

O tanrıdan bir eser...

Oy Mahmure Mahmure

Gözü benzer kömüre

Cilveli bakışıyla

Ömür katar ömüre...

Kızın adı Münevver

Yüzün bana dönüver

El dalına değil de

Gül dalıma konuver...

Oy Adile Adile

Çıkalım biz tatile

Sarmaş dolaş olalım

Uzanalım sahile...

O yarin adı Güzin

Geçmedi ona sözüm

Bu sevdanın yüzünden 

Eridi,soldu yüzüm

Oy Atiye Atiye

Bu gece gel yatıya

Candarmalar gelince

Saklanırız çatıya...

Kızın adı Dürüye

Dön de bir bak geriye

Ben canımı veririm

Senin gibi huriye...

Oy Cevriye Cevriye

Boyu benzer serviye

Onca bekar dururken

Gönül vermiş evliye...

Haber salın Fatma’ya

Gece gelsin yatmaya

Bende öyle yürek yok

Elin bile tutmaya....', 'Oy Nazile Nazile Şimdi gelir saz ile Sazı sözü bırakıp Göbek atar naz ile... Kızın adı Müyesser Tablo gibi şaheser Huyu, güzelliğiyle O tanr...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/maniler-104-oy-nazile-nazile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-zeynep-aydinlioglu-yw80q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir yaşamdır sözlerin 

devadır bakışların 

seni sevdim 

bir gün gidersen 

sensiz öksüz kalırım 

ellerime dokunamasanda 

saçlarımı okşayamsanda 

seni sevdim 

birakıp gitme 

ben sensiz öksüz kalırım. 

29.10.2005', 'bir yaşamdır sözlerin  devadır bakışların  seni sevdim  bir gün gidersen  sensiz öksüz kalırım  ellerime dokunamasanda  saçlarımı okşayamsan...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Aydınlıoğlu']::text[], 8.5, '{"poet":"Zeynep Aydınlıoğlu","poet_slug":"zeynep-aydinlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gitme-137-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek Tutmak', 'dilek-tutmak-emre-saricicek-28ozj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kum nasılda ışıldıyor.

Deniz pırıl pırıl oluyor sabahları.

Güneşin batışındaki gizemi,

Birbirini seven iki insanın izlemesi ne güzel.

Ya gece olunca.

O güzelim ay''ın denize yansıyan ışığı,

İşte en sevdiğim yakamoz.

Sevgilinin dizlerinde, gökyüzünü seyre dalmak.

Kayan her yıldızda, dilek tutmak.

Ve sabah olurken.

Gecenin ayazında sevgiliye sarılmak.

Güneşin doğuşunu tüm güzelliğiyle izlemek.

Yeni bir güne gökyüzünün verdiği mutlulukla başlamak.', 'Kum nasılda ışıldıyor. Deniz pırıl pırıl oluyor sabahları. Güneşin batışındaki gizemi, Birbirini seven iki insanın izlemesi ne güzel. Ya gec...', ARRAY['Türk Edebiyatı','Şiir','Emre Sarıçiçek']::text[], 8.5, '{"poet":"Emre Sarıçiçek","poet_slug":"emre-saricicek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dilek-tutmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delilik Bu Ya! ...', 'delilik-bu-ya-nurdan-elver-s3fpv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hoş bir duygu seli akan,

Bir o yana, bir bu yana.

Arada bir coşan,

Çalkalana çalkalana.

Adeta bir altüst oluş,

Çıldırmışcasına...

Yeniden varoluş,

Doymamışcasına.

Tutmak, yakalamak istiyorum

Bütün kaosları,

Alaşağı etmek istiyorum

Bütün çalkantıları,

Ve doyasıya yaşamak

Tüm anıları...', 'Hoş bir duygu seli akan, Bir o yana, bir bu yana. Arada bir coşan, Çalkalana çalkalana. Adeta bir altüst oluş, Çıldırmışcasına... Yeniden va...', ARRAY['Türk Edebiyatı','Şiir','Nurdan Elver']::text[], 8.5, '{"poet":"Nurdan Elver","poet_slug":"nurdan-elver","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/delilik-bu-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum kendimi', 'seviyorum-kendimi-ece-ozbek-0se5v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen

ben

olduğun günden beri

seviyorum

kendimi', 'Sen ben olduğun günden beri seviyorum kendimi...', ARRAY['Türk Edebiyatı','Şiir','Ece Özbek']::text[], 8.5, '{"poet":"Ece Özbek","poet_slug":"ece-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seviyorum-kendimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynadaki', 'aynadaki-hikmet-uzun-2vnov', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu aynadaki zat yokmu, beni çok eskiden tanır.

Yediğimiz ayrı gitmezdi, farklı tastan içmezdik.

Ne haltlar karıştırdık, bir söylesem şimdi utanır.

Felek çemberinden geçtik,birbirimizden geçmezdik.

Her kime ne nasip kısmet olsa böler, bölüşürdük.

Gözümüz gönlümüz birdi,tavrımız sözümüz birdi.

Bu ne garip bir ayrılık derdik,bakıp gülüşürdük.

Ayna denen bu sırlı cam, aramıza nasıl girdi?', 'Şu aynadaki zat yokmu, beni çok eskiden tanır. Yediğimiz ayrı gitmezdi, farklı tastan içmezdik. Ne haltlar karıştırdık, bir söylesem şimdi u...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Uzun']::text[], 8.5, '{"poet":"Hikmet Uzun","poet_slug":"hikmet-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aynadaki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-nurdan-elver-yuz5t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Keşke yazabilsem birşeyler sana,

Ya da çizebilsem düşündüklerimi.

Biraz daha zor belki benim tarzım,

Biraz daha karmaşıkta olabilir aslında.

Belki boştur endişelerim,

Belki de saçma...

Oysa hiçbir sevgi ne boş,

Ne de saçma,

Sadece anlaşılmaz olabilir.', 'Keşke yazabilsem birşeyler sana, Ya da çizebilsem düşündüklerimi. Biraz daha zor belki benim tarzım, Biraz daha karmaşıkta olabilir aslında....', ARRAY['Türk Edebiyatı','Şiir','Nurdan Elver']::text[], 8.5, '{"poet":"Nurdan Elver","poet_slug":"nurdan-elver","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/keske-119-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bosnalı Çocuk', 'bosnali-cocuk-mehmet-postalli-z1w35', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Minik yüreğine yüklenen acın; 

Senden beter, beni yakıyor çocuk

Annen, baban şehit kamptadır bacın

Avrupa pislikten kokuyor çocuk

Ürkek ceylanısın boş sokakların

Korkudan ağarmış al yanakların

Ağlamaktan şişmiş göz kapakların

Gözlerinden inci akıyor çocuk

Akşam olup baban eve gelince

Öper, koklar boğulurdun sevince

Yanağında gül açardı gülünce

Şimdi solgun solgun bakıyor çocuk

Çelik çomak oynar kumda koşardın

Küçük kuzuları sever okşardın

Kendi toprağında özgür yaşardın

Feryadın gökleri yıkıyor çocuk

Bu yükü taşımaz körpe bedenin

Gel, ortak olayım derdine senin

Duydum, öç almaya etmişsin yemin

Sırp itine meydan okuyor çocuk.', 'Minik yüreğine yüklenen acın;  Senden beter, beni yakıyor çocuk Annen, baban şehit kamptadır bacın Avrupa pislikten kokuyor çocuk Ürkek ceyl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bosnali-cocuk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluk Perdesi Bu Perde', 'yokluk-perdesi-bu-perde-nuri-ozoglu-n6dys', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yokluk perdesi bu perde,

Bir kere kapanmayagörsün.

Göz alabildiğine görüyorda,

Kimse görmüyor o gözü.

Dar hanemde pişirirdim aşımı,

Yolumuza hoyratlar çıkarda, 

Göz dikerler azığımıza...

Hep o korkuyla yaşadım işte.

Gelene abimsin, ağamsın, 

Velhasıl, eyvallah dedim.

Lakin yüzümü kızartmadım.

Kızartacak bir iş yapmadım.

Sevdim sevilmeye değer insanları,

Sevilmesemde...

Muhannetin derdi çetin,

Bir dilim ekmeğe muhtaç olmak var,

Ne kadar sevsende, sevilsende...

Üzerinden yıllar geçti, körüklenmiş anıların.

Tadına doyamadığım,

Hatırladıkça o sıcacık tandır lavaşını,

Yanında da yeşermeye yüz tutmuş küp peynirini,

Gurbette de yemek varmış büyük bir iştahla...

Hiçbir vasıtasız, o kendimi bulduğum yuvama,

Düşünce masrafıyla gidip geliyorum.

Belki bin yerde yaşıyorum,

Yaşatırlarsa gönüllerinde.

Yaşatmazlarsa, Yaşadıklarını asla unutmasınlar...', 'Yokluk perdesi bu perde, Bir kere kapanmayagörsün. Göz alabildiğine görüyorda, Kimse görmüyor o gözü. Dar hanemde pişirirdim aşımı, Yolumuza...', ARRAY['Türk Edebiyatı','Şiir','Nuri Özoğlu']::text[], 8.5, '{"poet":"Nuri Özoğlu","poet_slug":"nuri-ozoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yokluk-perdesi-bu-perde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bardakta Beton Yoğurduk', 'bardakta-beton-yogurduk-kamil-at-gkq4a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mağaraya benzer bir ev yaptık

Hırsıza büründük harç kaptık

Balyozla bütün duvarları öptük

Bardakta beton yoğurduk.

Fidanımız gizliden söküldü

Çok acı yerine çıkra dikildi

Yukardan halimize takıldı

Verimsiz yıldız doğurduk.

Hırsız yaptık hedef komşuyu

Erken yayıldı olunmaz duyu

Kendimize kaptık dipsiz kuyu

Dibinde davul zurna kurduk.

Sonsuz sinmiş içinde kiminin

Güzelliği bilinmez gizli kinin

Dostluğa havalanan güvercinin

Arkasından küfür uçurduk.

Sel içinde selamladık girdabı

Üzümü yaktık olmadı şarabı

İnanmadık sıcağına yaktık kitabı

Hergün daha da soğurduk.

Kimine çatlar diye açtık arayı

Yanlış tuttu gizledik numarayı

Konak bitmeden çaldılar parayı

''Hesap'' diye Kamil At''a vurduk.', 'Mağaraya benzer bir ev yaptık Hırsıza büründük harç kaptık Balyozla bütün duvarları öptük Bardakta beton yoğurduk. Fidanımız gizliden söküld...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bardakta-beton-yogurduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Özgürdür', 'sevgi-ozgurdur-savas-dincbas-bv8vf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aç yüreğini

tutsaklık yakışmaz sevgiye

özgür bırak

o konacağı dalları bilir

peşinden git

uç onunla

kanatlarında sonsuzluğa dek...', 'aç yüreğini tutsaklık yakışmaz sevgiye özgür bırak o konacağı dalları bilir peşinden git uç onunla kanatlarında sonsuzluğa dek......', ARRAY['Türk Edebiyatı','Şiir','Savaş Dinçbaş']::text[], 8.5, '{"poet":"Savaş Dinçbaş","poet_slug":"savas-dincbas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sevgi-ozgurdur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-mehmet-postalli-asxjl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gurbette yaşayan hemşehrilerime ithaf ediyorum.

Ocağıma düştün diye; 

Sinsi sinsi güler gurbet.

İçerini kemirmeye; 

Beklemeden dalar gurbet

Hasretlik içine çöker

Gözyaşı bendini yıkar

Od düştüğü yeri yakar

Yüreğine dolar gurbet

Garipten alır hıncını

Erken kocatır, gencini

Kimseler duymaz sancını

Dertten derde salar gurbet

Kuşları da hissiz öter

Gecesi gündüzden beter

Yatak diken gibi batar

Uykuları böler gurbet

Güneş bile yaslı doğar

Kasavet, sevinci boğar

Yazın, başına kar yağar

Saçlarını yolar gurbet

İster para içinde yüz

Bulamazsın aşina yüz

Bir derdine eklenir yüz

Ömrünü de  çalar gurbet.', 'Gurbette yaşayan hemşehrilerime ithaf ediyorum. Ocağıma düştün diye;  Sinsi sinsi güler gurbet. İçerini kemirmeye;  Beklemeden dalar gurbet ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gurbet-102-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-huseyin-sigirtmac-adl9y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşamak! 

Hür ve mutlu yaşamak.

Duyguları esir etmeden,

Kin ve nefret gütmeden.

Kısa ömür bitmeden.

Sevenler el çekip gitmeden,

Sevgiyle bakmalı,

Ecel cana yetmeden.

Barışa kucak açmalı,

İnsanlığa kafa tutmadan,

Savaş gelip çatmadan.

El ele verip kucaklaşmalı,

Bu gemi batmadan.

Yapıcı olmalı,

Yıkıcı el katmadan.

Yaşamak bu işte,

Hür ve mutlu yaşamak.', 'Yaşamak!  Hür ve mutlu yaşamak. Duyguları esir etmeden, Kin ve nefret gütmeden. Kısa ömür bitmeden. Sevenler el çekip gitmeden, Sevgiyle bak...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yasamak-176-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamın Amacı', 'yasamin-amaci-nuh-tufan-polat-vto2m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir tanrıya bir sana bir sana yalvarmak

Bir suya bir sana muhtaçlık,

Gecenin en karanlık yerinde bir umut ışığı yakmak,

Ve o ateşin içinde yanmak ,

Seni sevmek seni sevmek,

Hayata bir kazıksa başka bir beden,

Öpüşmek çılgınca sevişmekse,

Sen yaşa ben ölüyüm! ..

Senin olmadığın her şehirde,

Sesim kaybolur hengamesinde,

Sahte yıldızlarla süslü bir umutlar çölü var burada,

Tam ortasında aşkının ateşiyle yanan bir beden,

Ellerinin yaktığı bedenim ağır geliyorsa hayata,

Ellerime kelepçeler vuruyorsa yarınlar,

Sebebi sensin! ...

Yaşamak bir çekimlik nefes daha almak için geceler boyu uyumadan,

Umutlarımla yaptığım köprüler

Sensizliğin seline direniyorsa,

Sebebi sensin! ...

Gözlerimin çağlayan nehirleri var biliyor musun? ...

Ürkek yüreğimi dolduran; 

Azgın denizler hırcın fırtınalar

Evreni yakan ateş cehennemi dolduran günah,

Cenneti taşıran aff var! ..

Sen eyy sevgililer sevgilisi,

Yaşamın amacı sen,

Umutların ağacı sen,

Yastığımdaki çukur sen ,

Söz verdim tanrıya bir gün döneceğim diye,

Sözüm sen yeminim sen,

Bakamadığım gözlerin,

İncinir diye okşayamadığım saçların,

Üşür diye tutamadığım ellerin ,

Tinimi aldı yaktı kor etti,

Bilir misin sana ait bir bedenin neler çektiğini,

Bilir misin her nazınla nasıl çıldırdığımı,

Bir  tanrıya yalvardım bir sana,

Bir suya muhtaçtım bir sana,

Bir sana ağladım bir aynadaki yokluğuma,

Saçından bir tel bağlar bedeni hayata,

İşte ben o telin ucunda bağlanıyorum hayata,

Nolur biraz daha kal yanımda,

Güneşi utandıran ateş,

Merih''i usandıran tufan,

Peygamberi kıskandıran aşk var bende,

Hayatın namussuzluğunu yenen inat,

Seni sevmek seni sevmek,,,

Eyyy sevgililer sevgilisi,

Ben seviyorsam senin için

Sen seviyorsan ALLAH için,

Bir canı AZRAİL''e vermemek için,

Bu can bu adam

Bu yakarış bu  çığlık,

Bu göz yaşı bu sevda

İnan ki LEYLADA MECNUNDA,

FERHATTA ŞİRİNDE

Bu yaşlı çocukta senin için! ....', 'Bir tanrıya bir sana bir sana yalvarmak Bir suya bir sana muhtaçlık, Gecenin en karanlık yerinde bir umut ışığı yakmak, Ve o ateşin içinde y...', ARRAY['Türk Edebiyatı','Şiir','Nuh Tufan Polat']::text[], 8.5, '{"poet":"Nuh Tufan Polat","poet_slug":"nuh-tufan-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/yasamin-amaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Şair Olma', 'sen-sair-olma-nuh-tufan-polat-tpfrq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıldızlar düştü yüreğime

Kapkara gök yüzünden

Alev, alev yanan yıldızlar! ...

Yüreğimi yaktılar ellerimi yaktılar,

Senin göz yaşların gibi tutamadım,

Düştüler yandılar yüreğimde! ...

Gece vurdu bedenimi

Bir kurşun gibi oydu içimi,

Bir tunç mermi ilerledi içimde,

Yandı yanan yıldızın içinde,

Sen susma çiçeğim,

Sen akıtma göz nurunu,

Ben ikimizin de yerine ağlıyorum her gece,

Bilemezsin gecelerin nasıl geçtiğini,

Yazamasın benim gibi,

Sen şair olma sevdiğim,

Şairlerin geceleri haramdır sevdiklerine,

Sana haram lokma yedirmem şiirlerimde,

Bilemezsin dedim ya! ...

Sakın ha sen şair olma sevdiğim,

Ben ağlıyorum  ikimizin yerine! ...

Her gece bir yıldız asıyorum gök yüzüne,

Bir umut daha yakıyorum sonsuz isteklerime,

Bir damla daha düşüyor yüreğime,

Gene tutamıyorum gene iniyor gene oyuyor içimi,

Ellerimi yakan göz yaşlarım değil sevdiğim,

Tuzluda olsalar yastığım yaksa da yüzümü,

Yanan bir şey var içimde o da yüreğim,

Yana bir şey var içimde o da yüreğim,

Yanan bir şey var içimde o da yüreğim,

Dedim ya inci tanem sen sakın şair olma,

Ben ikimizin yerine de ağlıyorum sabahlara,

Sabahlar olmuyor yıldızlar kayıyor ama,

Sen gelmiyorsun düşlerime,

Beni orada da yalnız bıraktın,

Ben hep yalnızım, sen sakın şair olma sevdiğim! ...

Sen sakın şair olma! ...', 'Yıldızlar düştü yüreğime Kapkara gök yüzünden Alev, alev yanan yıldızlar! ... Yüreğimi yaktılar ellerimi yaktılar, Senin göz yaşların gibi t...', ARRAY['Türk Edebiyatı','Şiir','Nuh Tufan Polat']::text[], 8.5, '{"poet":"Nuh Tufan Polat","poet_slug":"nuh-tufan-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sen-sair-olma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksik kaldı', 'eksik-kaldi-zeynep-ece-arabul-xr8cw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Masada elin yerine sımsıkı tuttuğum çayımla

Isını alamadım eksik kaldı..

Çocuklarımızdan konuştuk

Oyunlarımızdan

Seyirciydik yaşamlarımıza 

Sözler eksik kaldı..

Kurulmamış kalemizin taşları ayaklarımızda

Olmayan kulelerde dalgalanan yüreğimiz; 

Kırgın, sinirli, isyankar bakışlarımızda,

Korkak bir sevgi kırıntısı

Eksik kaldı..

Dalga dalga çekildik dolunayda kendimize,

Kötücül bir boşluk gece yatağımda 

Sınırlı zamanlara zorlanmış iki yabanıl sözcükte 

Ortak ne varsa eksik kaldı..', 'Masada elin yerine sımsıkı tuttuğum çayımla Isını alamadım eksik kaldı.. Çocuklarımızdan konuştuk Oyunlarımızdan Seyirciydik yaşamlarımıza  ...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Ece Arabul']::text[], 8.5, '{"poet":"Zeynep Ece Arabul","poet_slug":"zeynep-ece-arabul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/eksik-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnadına', 'i-nadina-nuh-tufan-polat-0ihc8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir şehrin bütün ışıkları söner mi? 

Evet sönüyormuş sen gözlerini kapayınca,

Beden ruhtan çeker gider mi? 

Evet gidiyormuş sen gidince! ...

Bir kırlangıcın kanadında sevdam,

Daha kaç fırtınaya dayanır bu yürek,

Daha kaç bahar dolaşır sevda ülkesinde? ...

Ellerimde alev alev yanan hatıralarla

Yapayalnızım hayatın çölünde.

Güneş serin gölgedir aşkımın ateşine,

Gözlerini kaçırma utangaç bakma yüzüme,

Sıra dağlar gibi en aşılmaz, en fırtınalı

Okyanus dalgasını aşar gibi

 Yılmadan koşuyorum sana! ....

Aşkımın adı yok anası babası yok! ..

Bir yetim sevda büyüttüm sana! ....

Şimdi sığınacak bir liman bir gönül arıyor,

Akrebin zehri dolaşır damarımda,

Durmuyor hayat bir kum gibi akıp gidiyor avuçlarımdan,

Yalnızım ve sen yoksun! ...

Bir hayat var bütün silahlarıyla üstüme yürüyen,

Toplama kamplarında aç bıraktım hayallerimi,

Prangalara vurdum yüreğimi,

Bekliyorum gün ışığını zindandaki mahkum gibi,

Ne zaman doğup geleceksin dağların ardından? ...

Üşüyorum, ruhum bir buz kalıbının içinde,

Korkuyorum sabahın olmasından,

Güneş değil sen doğmalısın odama

Karanlığın hükümdarıyım ben! ...

Karanlıktır benim yüreğim

Bir damla ışık sızmadı senden başka! ...

Ölümü düşündüm senden arda kalan gece yarılarında! ...

Hayallerimi umutlarımı düşündüm,

Bir nehir misali akıyorum yüreğine,

Bazen bulanık bazen coşkun,

Bazen bir bakraç süt kadar temiz! ...

Kapkara gök yüzünde

Nasıl umut verirse bir yıldız insana

O umutla bağlandım sana! ...

Ve bir yıldız seçtim kendime iyi bak ona

Nasıl yanar aşkının ateşiyle

Ölünce orada yaşayacağım,

Belki arınırım günahlarımdan

Belki affeder Rab! ...

Bir kahpe kurşun vuracak can evimden

Biliyorum artık gitmem gerek

Çok hasret çektim

Cehennemin en karanlık odasından

Seni dileyeceğim af günü

Yalnızlık yakıyor yüreğimi,

Yalnızlık yakıyor bedeni,

Her gece bir kefen misali geçiyor üstüme yatak! ...

Ellerim bomboş kaldı yine,

Kokun sinmiş üstüme,

Nolur nolur gitme! ..

Bak ayaktayım direniyorum hayata inadına,

Firavunun zulmü olsa sevdan kabul

Çünkü seni seviyorum

               Seni seviyorum! ...', 'Bir şehrin bütün ışıkları söner mi?  Evet sönüyormuş sen gözlerini kapayınca, Beden ruhtan çeker gider mi?  Evet gidiyormuş sen gidince! ......', ARRAY['Türk Edebiyatı','Şiir','Nuh Tufan Polat']::text[], 8.5, '{"poet":"Nuh Tufan Polat","poet_slug":"nuh-tufan-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/inadina-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fal', 'fal-fevzi-kunucen-d66ov', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen hep düşlere inandın

Ve kötüye yordun falımızı

Bulutlar aldı götürdü -  umutlarımızı

Dibinde 

Telvesi kaldı fincanımızın.', 'Sen hep düşlere inandın Ve kötüye yordun falımızı Bulutlar aldı götürdü -  umutlarımızı Dibinde  Telvesi kaldı fincanımızın....', ARRAY['Türk Edebiyatı','Şiir','Fevzi Künüçen']::text[], 8.5, '{"poet":"Fevzi Künüçen","poet_slug":"fevzi-kunucen","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/fal-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-askin-ceylan-eumy4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk:

Dokunmak senin düşlerine,

Düşlerimle

ve

Çağırmak ölümü

son nefese,

Düşlerine dokunduğum yerde.

(Mayıs 2002,İstanbul)', 'Aşk: Dokunmak senin düşlerine, Düşlerimle ve Çağırmak ölümü son nefese, Düşlerine dokunduğum yerde. (Mayıs 2002,İstanbul)...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Ceylan']::text[], 8.5, '{"poet":"Aşkın Ceylan","poet_slug":"askin-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-480-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**ŞARAP YALNıZLıK Ve BeN', 'sarap-yalnizlik-ve-ben-aysel-zengingul-wp33r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şarap

Yalnızlık,

Ve ben..

Üçümüz bi arada

Bide ortada

Küçük bi masa..

Şarap efkarlı; 

………….yalnızlığa yükleniyor,

Yalnızlık da kimsesiz ki; 

 …………..bana denk geliyor….

Biz böyle her gece,

Üçümüz bi arada,

Bide ortada küçük bi masada,

Sorhoşluğa çekiliyoruz…

Lakin,

....Fakat,

........Ama; 

............Bizi de çeken olmuyor…

 29/10/2005   03; 36', 'Şarap Yalnızlık, Ve ben.. Üçümüz bi arada Bide ortada Küçük bi masa.. Şarap efkarlı;  ………….yalnızlığa yükleniyor, Yalnızlık da kimsesiz ki; ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Zengingül']::text[], 8.5, '{"poet":"Aysel Zengingül","poet_slug":"aysel-zengingul","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sarap-yalnizlik-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Müjdesi', 'ask-mujdesi-yavuz-bayram-caliskan-6elcz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerinden yüreğime damlayan bakışlar,

Bir can, bir atış, bir kıpırtı bu akışlar,

Gözlerinden anlayamadığım yakarışlar,

Bir aşk müjdesi veriyor bana.

Gönül tarlam, nadas dönüşü,

Bir heyecan fırtınası, aşk yanışı,

Gözlerimdeki gizeme sarılıp kanışı,

Bir aşk müjdesi veriyor sana.

Gözlerin gözlerime kilitlenirse,

Kalplerimiz yüreğimizde birlenirse,

Bu dünyada iki isim sırlanırsa,

Bir aşk müjdesi verir ikimize.', 'Gözlerinden yüreğime damlayan bakışlar, Bir can, bir atış, bir kıpırtı bu akışlar, Gözlerinden anlayamadığım yakarışlar, Bir aşk müjdesi ver...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-mujdesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Şairsin', 'sen-sairsin-nuh-tufan-polat-ufem7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaç gecedir uykusuzum,

Gözlerim yüreğimden süzülen çağlayanlarla kan çanağı,

Sen gece uçan kelebek misali,

Kaç gece, sönen bir yangının enkazında,

Bir umutla bekledim nefesini,

İdamlık mahkumlar gibi bekliyorum Azrail''i,

Üstümde öyle ağır bir gömlek var ki ,

Sanki dünyanın bütün günahları bedenimi sarmış,

Yanıyorum yıkılıyorum bir çınar gibi,

Yapraklarım rüzgara direniyor,

Fırtınanın tam ortasında nasıl dayanır bu ürkek yürek,

Katip yaz, kalem yaz,! ....

Belki sesini duyan olur, yalancıda olsan yaz! ...

Şiirlerin okunmasa da yırtık bir yelkenle açılsan da deryaya

Yelkenler fora! ... Yazz

Devam edecek hayat kaç tufan gördü dünya kaçından geçtin sen! ....

Dedim ya yelkenler fora

Ne zaman olur teknen alabora? ...

İşte ilk fırtınan ufukta bekliyor Azrail nefesi omzunda

Sen şair değil misin? Yazz sadece yaz yüreğini koymadın mı mısralarına,

Nasıl bir sevda yaşadın şimdi yüreğinde ne kaldı,

Tüm sermayen bu kadar mıydı? ....

Bir ışıkta mı yok bu sonsuz labirentte

Hiç gök yüzünü göremeyecek misin? ...

Sen karanlıktan korkmayan cesur çocuk,

Bedenin mi soğudu? 

Sen yenilmez Donkişot

Sen sen yuvasız kırlangıç

Uç şimdi başka bir bahara kanadın kırık

Dayan hadi o içindeki tufana kat et yollarını sevdanın

Hadi sen şairsin sen yapardın sermayen bumuydu? 

Uç hadi yelkenler fora dayanır salın bu fırtınaya da? 

Üşüdün mü sarılıp yatmayı unut yalnızlığına

Oda yok şimdi sakın ağlama tut yüreğindeki seli ileride, çölde bir

vaha yaparsın göz yaşlarınla

Yaz sen şairsin yüreğini sermayeni koy mısralarına

Tükenmedin mi hala? ...

Bitmedi mi içindeki ateş yanıyor mu hala? 

Yakıyor mu bedenini yalnızlık ,

Yakıyor mu bahçıvan gazelleri,

Mevsim son bahar yazzz sen şairsin

Yıldızın ölümü gibi, big bang gibi sevdanın sonu

Önce sessizlik sonra kıyamet

Kaç mahşerin var ki ömründe

Sevgilini sevdiğini bilmem arar mısın orada,

Sen şairsin yaparsın! ....

Bilmiyordum! ...

Hani yoktu ayrılık

Hani hayat güzeldi benimle

Hani nerde bana verdiğin sözler

Hani geçen ömrüm hani dualarım nerde hani

Hani nerde kokun! ..

Kendi içimde çıkan isyansa sevdam

Bende isyancıyım bende şairim o zaman

Bu son perde oyundu yöneten ben oyuncu ben seyirci sen,

Sen şairsin yazzzz yazdıkların yalanda olsa yazzz,

Sen yönettin sen oynadın sen yazdın

Okunmasa da yazdıkların sen şairsin

Çünkü sen sevdin hala sevdin ileride sevdin şimdi sevdin

Belki son çığlıktır bu sigaraya boğarken nefesimi

Belki son şiirindir belki son uykusuz gecen

Belki son olur sevdan belki okurlar şiirlerini

Belki duyarlar boğuk sesini

Belki yine melek olur uçarsın gök yüzüne

Kabul edilmese de duaların sen yaz çünkü sen şairsin yazzz

Yazdıkların yalanda olsa yüreğini koydun sermayeni koydun mısralarına', 'Kaç gecedir uykusuzum, Gözlerim yüreğimden süzülen çağlayanlarla kan çanağı, Sen gece uçan kelebek misali, Kaç gece, sönen bir yangının enka...', ARRAY['Türk Edebiyatı','Şiir','Nuh Tufan Polat']::text[], 8.5, '{"poet":"Nuh Tufan Polat","poet_slug":"nuh-tufan-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/sen-sairsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Doğuşu', 'askin-dogusu-yavuz-bayram-caliskan-9s0v3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıldız gibidir, gündüz görünmez,

Bekler akşamı …

Hasretler kucaklanır,

Tatlı bir bakışla akar gönüle,

Damla damla dolar yüreklere,

Sonra, bekler sabahı …', 'Yıldız gibidir, gündüz görünmez, Bekler akşamı … Hasretler kucaklanır, Tatlı bir bakışla akar gönüle, Damla damla dolar yüreklere, Sonra, be...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/askin-dogusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte', 'i-ste-nuh-tufan-polat-4zi1j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İşte yine odamda,

Yine kendi dünyamda.

Bomboş sokaklarında,

Köşe başlarını tutan,

Zalimler ordusuyla baş başa.

Kilitlenmiş kapısı umutlar evinin,

Pencereleri kırılmış,

Mühürlenmiş yarınlara! ...

Bir eski ayakkabı ayağımda

Yürüyorum gönlümün boş sokaklarında.

Biliyorum bir seven var,

Hissediyorum her nefeste,

Titrek mum ışığında,

Çiziyorum resmini.

Soluk soluğa kalınca beden

Anlıyor uzaklarda olduğunu! ....

Terler süzülürken,

Alnımda kucağıma.

Gözler nemlenirken ufukta

Anlıyor uzaklarda olduğunu! ...

Her gece selâlar verilir yüreğimde

Rüyalarımda ölü umutlar gömülür,

Ben gömülürüm yüreğine,

Bir aşkı gömerim göğsüne.

Yıldızlar seçerim,

Başına taç yapmaya.

Goncalar toplarım,

Koynuna koymaya.

Badeler seçerim,

Dudaklarına.

Ve bir delikanlı seçerim koluna takmaya! ....

Ne acıdır ayrı kalmak,

Yarınları sevmemek,

Yenilmek yürek yüreğe

Yıkılmak, yüz üstü kalmak…

Bir omuz bulunur elbet,

Bir beden sarar seni sıcacık,

Bir söz çalar kalbide,

Bir gün yaşanmaz olur sensiz! ...

İşte yine sensiz! ....

Bakacak resmim olmasa bile,

Hayalinle sevişiliyor rüyalarda! ....

Güneş doğarken,

Virane gönlümün sokaklarına.

Umutlar seli doldururken yüreği,

Martılar çığlık çığlığa selamlar,

Gönlümün limanından geçen gemileri! ...

Sessizlik bavuluyla göçerken kentten,

Bir anka kuşu masalından uyanıyorum.

Baş ucumda hayalin beliriyor,

Sararak yaralarımı iyi ki varsın diyorsun! ...

İyi ki varsın! ....

İyi ki varsın! ....', 'İşte yine odamda, Yine kendi dünyamda. Bomboş sokaklarında, Köşe başlarını tutan, Zalimler ordusuyla baş başa. Kilitlenmiş kapısı umutlar ev...', ARRAY['Türk Edebiyatı','Şiir','Nuh Tufan Polat']::text[], 8.5, '{"poet":"Nuh Tufan Polat","poet_slug":"nuh-tufan-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/iste-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Faltaşı', 'faltasi-aytekin-ozan-d18nj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üç gözü var aşkın

Biri kör,

Biri şaşı,

Üçüncüsü korur bizi beladan; 

Faltaşı!', 'Üç gözü var aşkın Biri kör, Biri şaşı, Üçüncüsü korur bizi beladan;  Faltaşı!...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Ozan']::text[], 8.5, '{"poet":"Aytekin Ozan","poet_slug":"aytekin-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/faltasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın ki;', 'askin-ki-yavuz-bayram-caliskan-hodcl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şiirlere döküşümde seni,

İncitirim diye korkarım.

Her satırda yinelenen, 

Aşkını sayıklarım.

Aşkın ki; 

Ateşinden yazılan kağıtlar yanar,

Kalbimin yandığı gibi.

Aşkın ki; 

Hasretinden gözlerimde yaş bırakmaz,

Islatır seni haykıran, seni inleyen sokakları.

Aşkın ki; 

Anlatılmaz… 

Eritiverir ışıl ışıl parlayan,

O yemyeşil bakışların.

Yağan yağmurlar,

Düşerken saçlarıma, 

Gözümdeki yaşlarla

Birleşip sel olur sokaklara...', 'Şiirlere döküşümde seni, İncitirim diye korkarım. Her satırda yinelenen,  Aşkını sayıklarım. Aşkın ki;  Ateşinden yazılan kağıtlar yanar, Ka...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/askin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Olur', 'cok-olur-yavuz-bayram-caliskan-furt6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaydan çıkan ok olsa, 

Sevda bize kalsa,

Sevilecek eğer else

Tutacak çok olur...', 'Yaydan çıkan ok olsa,  Sevda bize kalsa, Sevilecek eğer else Tutacak çok olur......', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cok-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Ver', 'yol-ver-yavuz-bayram-caliskan-nig70', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yürek yorgunuyum,

Nefsimin katiliyim.

Avuçlarıma doldur yüreğini,

Gözlerinden bir yol ver.

Ağladığımı sana yazılan şiirler bilirler,

Dağılır satırlar bir şiir defterinde.

Bir yol ver bana,

Katil olmadan yüreklerde...', 'Yürek yorgunuyum, Nefsimin katiliyim. Avuçlarıma doldur yüreğini, Gözlerinden bir yol ver. Ağladığımı sana yazılan şiirler bilirler, Dağılır...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yol-ver-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilki Severdin', 'bilki-severdin-askin-ceylan-cydht', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anlatabilseydim seni sana,

Geceye,yıldızlara,yağmurlara

Belki severdin beni,

Anlatabilseydim

Suya,toprağa,rüzgarlara

Belki severdin beni,

Anlatabilseydim

Dağlara,taşlara,imkansız aşklara

Belki severdin beni,

Ve bilseydin sensizliğin ne demek olduğunu,

Tatsaydın sevgimin şehvetini

Bilki severdin beni

Çıldırasıya.

()   Kasım 2002,İstanbul)', 'Anlatabilseydim seni sana, Geceye,yıldızlara,yağmurlara Belki severdin beni, Anlatabilseydim Suya,toprağa,rüzgarlara Belki severdin beni, An...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Ceylan']::text[], 8.5, '{"poet":"Aşkın Ceylan","poet_slug":"askin-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bilki-severdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir tanem', 'bir-tanem-tahsin-dagli-zu7a4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim kır çiçeğimsin

Benim gökyüzümsün

Benim kır kokuşlumsun

Benim kalbimsin

Benim en sevdiğim tepesin

Benim sıcak yatağımsın

Benim fırtınalarda sığındığım limanımsın

Benim en değerli armağanımsın

Benim en duygusal anımsın

Benim en yakın arkadaşımsın

Benim ilham kaynağımsın

Benim kaderimsin

Benim ışığım

Benim gecem,gündüzümsün

Benim kalbim,ruhumsun

Benim dualarımın yanıtısın

Benim yüreciğimin ilecısın

Benim öfkemin gidericisisin

Benim ağrı gidericimsin

Benim ateşimsin

Benim nadide mücevherimsin

Benim kalp atışımsın

Benim nefes alışımsın

Benim hayatımı hayat yapansın

Benim kutsalımsın

Benim moral kaynağımsın

Benim en büyük şansımsın

Benim son dansımsın

Benim hayat enerjimsin

Benim yazmadan duramadığımsın

Benim sabah güneşimsin

Benim kalbimin bekçisisin

Benim kahkahalarımın kaynağısın

Benim şarkılarımsın

Benim şiirlerimsin

Benim iştah açıcımsın

Benim sonsuzumsun

Benim yanan ateşimsin

Benim en büyük arzumsun

Benim ruhumun eşisin

Benim yarınlarımsın

Benim rüyalarımsın

Benim her şeyden önce gelenimsin

Benim sağduyumsun

Ölene kadar sebebimsin

Bunu böyle bilesin...', 'Benim kır çiçeğimsin Benim gökyüzümsün Benim kır kokuşlumsun Benim kalbimsin Benim en sevdiğim tepesin Benim sıcak yatağımsın Benim fırtınal...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Dağlı']::text[], 8.5, '{"poet":"Tahsin Dağlı","poet_slug":"tahsin-dagli","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/bir-tanem-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '&Son&', 'son-sanem-deniz-zxpn4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yum gözlerini

Düşün,melodiler eşliğinde

Kaybediş öykülerini,

Uyut duygularını.

Yetmedi mi? 

............................

Bir avuç toprak at!', 'Yum gözlerini Düşün,melodiler eşliğinde Kaybediş öykülerini, Uyut duygularını. Yetmedi mi?  ............................ Bir avuç toprak at!...', ARRAY['Türk Edebiyatı','Şiir','Sanem Deniz']::text[], 8.5, '{"poet":"Sanem Deniz","poet_slug":"sanem-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/son-108-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatlar Eskiyordu Eskişehir''de', 'hayatlar-eskiyordu-eskisehir-de-askin-ceylan-8a0r9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayatlar eskiyordu Eskişehir''de,

Dilenenler de vardı, direnenler de,

İliklere işleyen ayaza

Ve acımasızca akan zamana,

Ben eskiyordum, sen de öyle,

Aşklarımız eskiyordu

Ve eskidikçe

Daha bir iliklerime işliyordu

Sana olan sevdam,

Ayazı kıskandırırcasına.', 'Hayatlar eskiyordu Eskişehir''de, Dilenenler de vardı, direnenler de, İliklere işleyen ayaza Ve acımasızca akan zamana, Ben eskiyordum, sen d...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Ceylan']::text[], 8.5, '{"poet":"Aşkın Ceylan","poet_slug":"askin-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hayatlar-eskiyordu-eskisehir-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklımızın Ermediği', 'aklimizin-ermedigi-fevzi-kunucen-4urh8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben bu istasyon da 

Bunca yıldır neler gördüm

Nereye gidiyor bu yolcu

Hem neden  böyle sarı-mor

 Yavrum diyor bir ana

Öte de evlat babayı uğurluyor

Gemiler geliyor ruhtıma

Bacaları dumansız

Düdüksüz-pusulasız gemiler

Komışları-çocukları

Eli kınalı gelinleri götürüyor

Ki sevileri vardı içlerinde

Yarım kalıyor yaşantıları belki tatlı yerinde 

Kader

Ne göz yaşı dinliyor ne de ağıt

Çığlık-çığlığa bir şarkı besteliyor

Madem 

Bütün renkler silinecek-rüzgar dinecekti

Ne lüzum vardı bu    

Ya da değermiydi uğramıya

Bu köhne limana

Bir şarkı besteliyor', 'Ben bu istasyon da  Bunca yıldır neler gördüm Nereye gidiyor bu yolcu Hem neden  böyle sarı-mor  Yavrum diyor bir ana Öte de evlat babayı uğ...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Künüçen']::text[], 8.5, '{"poet":"Fevzi Künüçen","poet_slug":"fevzi-kunucen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aklimizin-ermedigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni ara', 'beni-ara-tahsin-dagli-02xpb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hepimizin aradığı huzur! 

Etrafına huzur saçan

Gözlerinin içi gülen insanlar istiyoruz.

Hani şu eskilerin tabiri ile,

Öyle dostlar,arkadaşlar arıyoruz.

Ömrümüze ömür katsın

Onları yalnız bu dünyada değil,

Onları öte dünyada da isteyelim.

Yani ahretliğimiz olsun...

Bir gün bunalırsan dostum,

Ve sıkıntını paylaşmak istersen beni ara.

İmi elim kanda da olsa gelir

Sıkıntını yok ederim...

Bir gün ağlayacak olursan da ara

Seni belki güldüremem ama

Söz veriyorum! 

Seninle birlikte ağlayabilirim.

Bir gün, uzaklara kaçmak istersen

Beni aramaktan çekinme.

Seni belki durduramam ama,

Seninle birlikte koşabilirim....

Bir gün yüksek bir köprüden atlamaya

Kalkışırsan da ara beni.

Seninle birlikte atlayamam ama,

Aşağıda bekler,seni tutabilirim...

Bir gün herhangi bir konuda

Kararsız kalırsan,ara beni

Seni,senden fazla düşünür

Acizane fikirler verebilirim

Bir gün kimseyi dinlememeye karar versen de ara beni

Ağzımı açmayacağımı,

Söylemediklerini bile dinleyeceğimi bil...

Bir gün,beni üzdüğünü düşünürsen de,

Çekinmeden ara beni! 

Göreceksin,sana kıyamam,kıramam,üzemem seni

Bir gün beni ararsan,

Ve benden karşılık alamazsan

Söz ver; 

O zaman sen ulaşmalısın bana.

Çünkü o an,

Bir meleğe gereksinim duyduğumu bilmelisin

Seni seviyorum dostum!', 'Hepimizin aradığı huzur!  Etrafına huzur saçan Gözlerinin içi gülen insanlar istiyoruz. Hani şu eskilerin tabiri ile, Öyle dostlar,arkadaşla...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Dağlı']::text[], 8.5, '{"poet":"Tahsin Dağlı","poet_slug":"tahsin-dagli","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/beni-ara-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitti', 'gitti-i-sa-erkol-0sw7c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdana yandığım fani dünyada

Ne talihsizmişim, ölmedim gitti

Dinecek sanmıştım gözümün yaşı

Bir günden bir güne gülmedim gitti

Hasreti basarsın artık bağrına

Göz yaşı dökersin sende ağrına

Ömrümü bitirdim sevda uğruna

Ben bu bilmeceyi bilmedim gitti

Yüreğimin ateşi bak artık söndü

Sevdamız maziymiş, sevmekse dündü

Bir damlaydı, şimdi deryaya döndü

Gözlerimden yaşı silmedim gitti

Sözde tesir yoksa dilden ne gelir

Bülbül konmuyorsa gülden ne gelir

Alnıma yazılmış, elden ne gelir

Kaderin önünde yelmedim gitti

Uslandı yüreğim, tefekkür etti

Çektiğim dertlerim bedene yetti

Yaşadıklarım hep tekerrür etti

Hayattan dersimi almadım gitti

Bu dünyada bir gün gülmedi yüzüm

Yirmi bir senedir ağlıyor gözüm

Beyhude yazmışım, değersiz sözüm

Bir değerli kelam olmadım gitti

Kader dedim hep katlandım gelene

Aldırmadım ben hiç bana gülene

Ömrümü verirdim halden bilene

Bekliyorum her gün yılmadım gitti

Leyla bırakıp da benden gidince

Bedene hasretten sızı düşünce

Çiçekler misali mevsim dönünce

Bahta razı olup solmadım gitti

Durulmazdı amma yüreğim sakin

Fırtınalar durdu, meltemler essin

Sevdalar şaşırttı amma velakin

Saçlarımı bir gün yolmadım gitti

Üç günlük dünyada aldandım durdum

Hep sahte sevdaya bağlandım durdum

Boşu boşuna hep eğlendim durdum

Hakkın deryasına dalmadım gitti.', 'Sevdana yandığım fani dünyada Ne talihsizmişim, ölmedim gitti Dinecek sanmıştım gözümün yaşı Bir günden bir güne gülmedim gitti Hasreti basa...', ARRAY['Türk Edebiyatı','Şiir','İsa Erkol']::text[], 8.5, '{"poet":"İsa Erkol","poet_slug":"i-sa-erkol","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/gitti-183-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağdat''lı Çocuk', 'bagdat-li-cocuk-kerim-aksu-734f0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aksütünü emiyorken sütün soğudu

Kızıl renge boyandı niyeki anne

Ilık nefesini hissetmiyorum

Ses versene seni duyamıyorum anne.

Bu silah sesleride ne

Akşam neden puslandı böyle 

Üşüyorum bana sarıl

Sıcacık ellerin nerede anne.

Gökyüzündeki bu gürültülerde neden

Kuşlarda konmadı penceremize bu akşam

Susma ne olur ses ver

Benide koynuna alıver anne.

Heryer Kerbelamı 

Bu zaman ne zaman anne

Yaşamak ne demek ölümde neki

Kucağın soğudu üşüyorum ben anne.

Aksütünü emiyorken sütün soğudu

Kızıl renge boyandı niyeki anne

Ilık nefesini hissetmiyorum

Ses versene seni duyamıyorum anne.', 'Aksütünü emiyorken sütün soğudu Kızıl renge boyandı niyeki anne Ilık nefesini hissetmiyorum Ses versene seni duyamıyorum anne. Bu silah sesl...', ARRAY['Türk Edebiyatı','Şiir','Kerim Aksu']::text[], 8.5, '{"poet":"Kerim Aksu","poet_slug":"kerim-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bagdat-li-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşkın Yürek Gazeli', 'saskin-yurek-gazeli-metin-dikec-lxg6p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '“Bana sensiz  cihan, ey can gerekmez

                                  Visalin var iken hicran gerekmez”

                                                    SEYYİD NESİMİ

Şaşkın Yürek Gazeli

Yaşamın ustura köşelerinde uzuvlarımız 

Yar yolunda cism ü candan bıkanlarız biz

Kan çeker gibi gelişi üstümüze belaların,

Aşktandır.Yürek yakıp seyrine bakanlarız biz

Yırtık ruhumuzdan girilir  A’rafa.Öyle biline

Her mevsime  inanan, her çocuğa kananlarız biz

Denizini yitirmiş kör ırmaklar  gibiyiz akarız kendimize

Yedi vadiyi aşıp yokluğa varanlarız biz

Biz Tanrı’nın öbür kulları, içimiz hep haytalık

Kızıp engin denizlerde, gemileri yakanlarız biz



metin dikeç', '“Bana sensiz  cihan, ey can gerekmez                                   Visalin var iken hicran gerekmez”                                    ...', ARRAY['Türk Edebiyatı','Şiir','Metin Dikeç']::text[], 8.5, '{"poet":"Metin Dikeç","poet_slug":"metin-dikec","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/saskin-yurek-gazeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirden Çocuklar / A.Uluç-Y.İgret', 'siirden-cocuklar-a-uluc-y-i-gret-aynur-uluc-odljm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ne çok '' şiirden çocuklar'' yaptık birlikte

piç çocuklar 

asla sahibinin sahiplenmediği

kaşını senden aldı, gözünü benden

edebiyat içinde yalnız bir makam

ne çok sancı biriktirdi 

satırbaşları tutulmuş dizeler içinde

korkuyla karılmış ne çok kelime

kalem, tarama ucuyla sağa sola çizerken 

ne çok '' şiirden çocuklar'' yaptık 

birbirine dokunmadan iki beden

dününü senden aldı, yarınını benden

her şiir biraz yalan aslında

her şiir biraz düş

sıra dışı bir dünya

her şiir inadına gerçek öte yandan 

belki de bu yüzden rengini yitirdi

kâğıt yanağına kara öpücükler kondurup

yeni desenlere koşarken

Aynur Uluç

Yavuz İgret 

Bireylikler - Temmuz, Ağustos 2006', 'ne çok '' şiirden çocuklar'' yaptık birlikte piç çocuklar  asla sahibinin sahiplenmediği kaşını senden aldı, gözünü benden edebiyat içinde yal...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/siirden-cocuklar-a-uluc-y-igret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deprem sonrası', 'deprem-sonrasi-esref-uzulmez-5gsro', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I

giderken yıkık bir kenttim deprem sonrası

şimdi yüzümdeki akşamları siliyorum

II

çalınmış bütün saatler durduruldu

bekleyen gecelerin son şafağıyım

III

bu son parağraf

mükellefim artık,tüm yazılmamış zamanların sararan sayfalarına', 'I giderken yıkık bir kenttim deprem sonrası şimdi yüzümdeki akşamları siliyorum II çalınmış bütün saatler durduruldu bekleyen gecelerin son ...', ARRAY['Türk Edebiyatı','Şiir','Eşref Üzülmez']::text[], 8.5, '{"poet":"Eşref Üzülmez","poet_slug":"esref-uzulmez","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/deprem-sonrasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Bir Ceza Verdim', 'sana-bir-ceza-verdim-kadir-albayrak-2ao7d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gün içimden geldi sana kem söz yok ama

Sana bir ceza verdim

                                     -Ben ölünce ağlama

Bu ceza ölene dek prangan olsun senin

Hakikat kilidinse gözyaşı zincirlerin

Yüreğin ağlasın! Sen; Sana yasak! Sakın ha

Helal etmem hakkımı yemin verdim Allah-a

Yakana yapışırım ötelerde hesap var

Çaresi yok, kabir dar, kaçamayacak kadar

Ilık ılık akıyor içinde bir şey şimdi

Sıkma kendini ağla! Mecnun daha ölmedi

Can vermeden ceza yok önce canım çıkacak

Benim cezam biterken senin ki başlayacak

Her ne çektimse çektim sitem etmedim ama

Sana bir ceza verdim

                                    -Ben ölünce ağlama

İster dua say bunu istersen bir beddua

Ne sayarsan say ama bu gönlümde tek dua

Unutma; Ne bu ceza bir cezaya benziyor

Asıl ceza içinde anlarsan delirtiyor

Bilirmisin ki acı ne ateş ne de külmüş

Ha yüreğe bir sevda ha ten-e kezzap düşmüş

Acı odur ki; Akrep, takınca o kıskacı

Ben azap arıyordum acıdan daha acı

''Öldü'' haberim gelir, yavaş yavaş hazırlan

Dayanmak zorundasın ''cezanı unutmadan''

Seni üzmek istemem sana acı yok ama

Sana bir ceza verdim

                                    -Ben ölünce ağlama

Sabır tavsiye etsem! ..Derdim yardımcı olmak

Kan ağlasanda sana göz yaşı dökmek yasak

Belki düşünüyorsun! Neden ''bu ceza'' neden

Ben gitmiş olacağım sana cevap vermeden

''Ağla'' demiyorum ki, sen ağlama diyorum

''Ben öldüm'' gözyaşını, artık hak etmiyorum

Hani ''gel'' demiştim de hiç kimse gelmemişti

Ben bu gün ölmedim ki hayat o gün bitmişti

Şimdi herkes ağlasın, yalan doğru fark etmez

Acım sır-dır, ölmezsem, kimse göz yaşı dökmez

Ya sen! .. Sen öyle misin? Gönlüme en yakın kul

Ceza sana kesilmiş, sebebini de sen bul

Çok üzgünüm sevdiğim sana kıyamam ama

Sana bir ceza verdim

                                    -Ben ölünce ağlama', 'Bu gün içimden geldi sana kem söz yok ama Sana bir ceza verdim                                      -Ben ölünce ağlama Bu ceza ölene dek pra...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/sana-bir-ceza-verdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cenevar', 'cenevar-sadik-altinkaynak-qcgsi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Cenevar

Bizim oralarda 

Canavara derler

Cenevar

Yıllar önce vardı 

Şimdi gene var

Arada bir şenlendirir 

Van Gölünü

Yakından gören yok

Gavurun dölünü

Neyin nesidir

Kimin fesidir

Erkek mi yoksa dişi mi

Tek başına mı gezer

Yoksa örgüt işi mi

Belli değil kabilesi aşireti

Kimi der Bırukidir

Kimi der Hertoşi

Kimi der tekdir kimi der ikidir

Bilmem kim kurcalar bu işi

Yoksa Bekiranlı mı

Ya da Kürhesini

Duyan var mı acep sesini

Bazısı der Hemoyidir

Bazısı der Celoyi, yok Celali

Diyorlar onun yüzünden 

Azaldı İncikefali

Doğru mu yalan mı bilmem 

Söyleyene  vebali

Bir görünür 

Bir kaybolur Cenevar

Gayet normal

Bunda garip olan ne var

İster erkek olsun ister dişi

Arada bir gezsin

Elcevaz Ahlat Erdişi

Hangi aşiretten olursa olsun

Seviyoruz onu canı sağ olsun

				Sadık ALTINKAYNAK', 'Cenevar Bizim oralarda  Canavara derler Cenevar Yıllar önce vardı  Şimdi gene var Arada bir şenlendirir  Van Gölünü Yakından gören yok Gavur...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/cenevar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam ve Babam', 'anam-ve-babam-sinan-karakas-hoya0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Muhatabı bi hitabı evladü iyal,

Bütün dertlerine olurum ben de meyal,

Mebde i men yanar idin tüm dertlerime,

Asla istemezsin bela gelsin serime,

Ben de yanarım ki severim mutlak seni,

Sen fazla yanarsın  seversin elbet beni,

Hastalandım mı hiç eksilmessin başımdan,

Yandığını görürüm akan göz yaşından,

Bilirim ki sensin bi sebebi vücudum,

Mümkün müdür de bana nisyan etsin ruhum,

''Bende''olurum anamın şahsı önünde,

Bilirim bin letafet var onun sözünde,

Allah rahmet etsin benim kibar babama,

Allah selamet versin nazenin anama,

Parlayan bir ay gibi veya güneş gibi,

Nur ve hikmet saçar kımıldadıkça lebi,

Öyle bir insandı severdi insanları,

Kafir Mümin demez verirdi selamları,

İnsanlığa hizmetten öyle zevk alırdı,

Amir ve memuru hep hayrette kalırdı,

Derdi büyük Allahım beni öyle büyüt ki,

Cehennem benle dolsunkimseye yer kalmasın,

Sanki insanlık için yaratılmış babam,

İnsanlığa bir delil göndermiş yaradan,

Dünyadan göçünce bıraktı babalığı,

Hem analık hem de sürdürdü babalığı,

Ne cefalar çektin benim vefakar anam,

Başka kim yanar ki evlada böyle yanan,

Kimisi her şeyi madde diye görürler,

Dokuz ay gebeliğe nedir yani derler,

Bunlara insan demek hatadan da öte,

Çiğ süt emmişiz derler emdikleri süte,

Çok şeyler yazılır analıkla ilgili,

Anadan daha kutsal, var mı bir sevgili,

O olsaydı bir damla uykuyu görmezdi,

Gözündeki yaşı kimseye göstermezdi,

Analık öylesine derin bir mana ki,

Analar evlatlarının hamisi san ki,

Bir Allah''ı düşün birde sebebi vücut,

Ateş verse sana ateşi elinle tut.', 'Muhatabı bi hitabı evladü iyal, Bütün dertlerine olurum ben de meyal, Mebde i men yanar idin tüm dertlerime, Asla istemezsin bela gelsin ser...', ARRAY['Türk Edebiyatı','Şiir','Sinan Karakaş']::text[], 8.5, '{"poet":"Sinan Karakaş","poet_slug":"sinan-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/anam-ve-babam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuşma', 'konusma-kadir-albayrak-h3605', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir Dünyam var benim düş-ten hayalden

Tasavvura sığmaz gerçekten ırak

Tercümesi zordur bunu mealden

Çözmeye çalışma, uğraşma, bırak

Yorma aklın hey dost! Hal Kadirce-dir

Bu yürek ki; grift bir bilmecedir

Gönlümüz sevdaya düşmüş nicedir

İzana çalışma, uğraşma, bırak

Taş yerinde ağır, öylece kalsın

Anlayan payına düşeni alsın

Ne olup bittiyse sırra bulansın

Bulmaya çalışma, uğraşma, bırak

Ben çok kelam etmem! Heybemde ki bu

''AŞK'' dedin mi durur! Zaman, rüzgar, su

''Kara sevda''  belki cevap olurdu

Çözmeye çalışma, uğraşma, bırak

Çözdüysen konuşma! Mevlaya bırak! ...', 'Bir Dünyam var benim düş-ten hayalden Tasavvura sığmaz gerçekten ırak Tercümesi zordur bunu mealden Çözmeye çalışma, uğraşma, bırak Yorma ak...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/konusma-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efkar', 'efkar-ali-gencay-o2ks8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecenin bana ne zoru var

Beni bu kinimle kim tutar

Göğü kaplasa da yıldızlar

Bulut çıkar tılsımını bozar

Yürek aşk elinden tarumar

Beden hasret narına yanar

Soyundum da gelen mi var

Bir gecelik aşk beni boğar

Kuşanmış dört yanım, dar

Sigaradan tüten sarı efkar

Kah gülmüşüm neye yarar

Parmaklarımdan acı sızar

Cebimdeki yuvarlak taşlar

Aklım çocukluğuma uyar

Kuşlar sapanımdan kaçar

Allahsız bana da ölüm var', 'Gecenin bana ne zoru var Beni bu kinimle kim tutar Göğü kaplasa da yıldızlar Bulut çıkar tılsımını bozar Yürek aşk elinden tarumar Beden has...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/efkar-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabullenişin Yıldönümü', 'kabullenisin-yildonumu-melih-coskun-o46zy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tam bir yıl geçti üzerinden 

Bugün daha iyi anlıyorum

Kabullenmenin ne demek olduğunu 

Bazı acılarım evcilleşti 

Bazıları ise her zamanki gibi tazeledi kendini.

Zayıf yanlarım vardı benim de herkes gibi 

Kimselere gösteremediğim 

Gün ışığı görmemiş kederlerim vardı 

Alkollü akşamların bile dindiremediği 

Tam bir yıl geçti üzerinden 

Bazı şarkıları gözlerim dolmadan dinleyebiliyorum artık 

Daha az hayal kuruyorum 

Rüyalarımdan düşüp kan revan içinde kalmamak için 

Oysa okuduğum kitaplarda; 

Direnmenin onuru her şeyden daha kutsaldı 

Ve insan inanmışsa bir davanın haklılığına 

Sonuna kadar gitmeliydi 

Bedeli ne olursa olsun. 

Yani gülü dikenine rağmen sevebilmek 

Ve bir yüreğin çıkmazına ömrünü koyabilmekti bütün mesele 

O kitaplar yazmamışlardı oysa 

En büyük kavgaların içinde bile aşık olunabileceğini 

Tam bir yıl geçti üzerinden 

Hiçbir mermi bu kadar öldürmemişti beni şimdiye kadar 

Kırmaktan daha zordu bir oyuncağı tamir etmek

Yani kırılmak ve hiç tamir edilmemek 

Birbiriyle bağıntılı iki yıkıcı eylemdi

Ölmüş kuşlar uçamazlardı bir daha rüyalarında bile 

Ayağa kalmak değiştirmezdi 

İnsanın düşmüş olduğu gerçeğini.

Vazgeçmek kaderi olmuşsa insanın 

Yüreğini fırlatıp atmalıydı uzak bir yere...

2004', 'Tam bir yıl geçti üzerinden  Bugün daha iyi anlıyorum Kabullenmenin ne demek olduğunu  Bazı acılarım evcilleşti  Bazıları ise her zamanki gi...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kabullenisin-yildonumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen', 'bazen-kadir-albayrak-98sl3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazen tepem atıveriyor

Şeytan diyor ki; 

Kır, dök eline ne geçerse

Lanetler yağdır önüne gelene

Cam şıkırtıları

Kemik çatırtıları

Sarsın ortalığı

                   -Peki ama! ..Niye? 

                   -Kime bunca öfke? 

Kim bilir! ..

Çok uzaklarda

Herşeyden habersiz

Belki masum(!)  birine

Verdiğim mal mülk değil

Borç para da vermedim

Zira bunlar geri alınmasada

                           -Yine edinilir! 

Benim asıl derdim

''ALÇAKÇA ÇALINMIŞ GENÇLİĞİM''

Geri alamıyorum

Ve çok sinirleniyorum

Bazen de dayanamıyor

Gizli gizli ağlıyorum', 'Bazen tepem atıveriyor Şeytan diyor ki;  Kır, dök eline ne geçerse Lanetler yağdır önüne gelene Cam şıkırtıları Kemik çatırtıları Sarsın ort...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bazen-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeytan Ayrıntıda Gizli', 'seytan-ayrintida-gizli-kerem-kayar-4r6ol', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mum alevinin titrek gölgesinde

Duvara yansıyan düşünceler

Ve....................şeytan ayrıntıda

Nefes ile gölgenin sıkıştığı nokta

Sisteme karşı çağrışımdı isyan

Baş kaldırmaydı bedensel

Değil

Düşünsel

Şeytanın antropolojisi, insancasına

Devşirme duygular öteden, zamana

Yaşamaksa mücadele, realite

Neydi sorun? 

Bir bıçak uçundan akana mı muhtaç

Kan çiçeklerinin susuzluğu? 

Yoksa vücuda ait 

görünmez izleri mi? 

Analitik

Genetik

Metafizik karmaşa

Güneşin karanlık yüzü

Ve ahlaksız teklif görülmeyen 

La Fonteine masalları sanan yaşamı

fiesta uykusunda bulur ölüm

Geceyi yaşa_! 

Cesaretini odakla

Ölümse korkmadan 

Nereye şeytan? 

Güne daha var

.........................Korktu da kaçtı mı? 

İşte

Gerçek gelip gider, hakikat kalır*

Gece bitimine az kala

.....................................Bitmemişti oysa

Bu kadardı gücü

Bilmediği yaraladı

Çünkü çok biliyordu...

Gerçek gelip gider, hakikat kalır*. Socrates', 'Mum alevinin titrek gölgesinde Duvara yansıyan düşünceler Ve....................şeytan ayrıntıda Nefes ile gölgenin sıkıştığı nokta Sisteme ...', ARRAY['Türk Edebiyatı','Şiir','Kerem Kayar']::text[], 8.5, '{"poet":"Kerem Kayar","poet_slug":"kerem-kayar","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gece-seytan-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım İzmir''im', 'canim-i-zmir-im-munevver-senol-op4em', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bulutmu kaplamış, İzmir''i bu gün.

Yoksa benim içim mi kararmış? 

Dokunsalar, ha ağladım, ağlıyacağım.

Bulutmu kaplamış İzmir''i bu gün.

Ben alışkınım, senin gülen yüzüne.

Yağsan bile, ardından doğar güneşin.

O kadar yer gezdim amma,

Dünyada yok bir eşin.

Bulutmu kaplamış, İzmir''i bu gün.

Dokunsalar, ha ağladım, ağlayacağım.

Gerek kalmadı dokunmanıza.

Dolan gözlerim boşaldı,

Ağlıyorum, ağlıyacağım...', 'Bulutmu kaplamış, İzmir''i bu gün. Yoksa benim içim mi kararmış?  Dokunsalar, ha ağladım, ağlıyacağım. Bulutmu kaplamış İzmir''i bu gün. Ben a...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/canim-izmir-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Ne Yaparsa Kendine Yapar', 'i-nsan-ne-yaparsa-kendine-yapar-fatih-mehmet-karaca-ko2x2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu dünyada ne ekersen

Karşılığını Ahirette biçersin

Bunu unutmayasın hiçbir zaman

İnsan ne yaparsa kendine yapar

Şunu yaparım,bunu yaparım,asarım,keserim

Olmaz böyle şey, yapamazsın

Yaptığını zannedersin kendini kandırırsın

İnsan ne yaparsa kendine yapar

Hayırda yaparsan kendine,şerde yaparsan kendine

Kullanmalısın akıl nimetini güzel şeylerde

Nankör olma elini aç Rabbine

İnsan ne yaparsa kendine yapar

Hani nerede atan deden yok

Sen varsın şimdi bundan ders almalısın

İyilik yap iyilik bul,hayır yarışında bulun

İnsan ne yaparsa kendine yapar

İnsan akıllıdır vardır bunda bir hikmet

ilim,irfan öğren öğret çalış çabala

Karageyik sende uy bu güzel nasihatlere

İnsan ne yaparsa kendine yapar

                                  Fatih Mehmet Karaca

                                  17.11.2005 Aktepe Kasabası

                                                           Hassa/Hatay', 'Bu dünyada ne ekersen Karşılığını Ahirette biçersin Bunu unutmayasın hiçbir zaman İnsan ne yaparsa kendine yapar Şunu yaparım,bunu yaparım,a...', ARRAY['Türk Edebiyatı','Şiir','Fatih Mehmet Karaca']::text[], 8.5, '{"poet":"Fatih Mehmet Karaca","poet_slug":"fatih-mehmet-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/insan-ne-yaparsa-kendine-yapar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Deniz-Ana Deniz', 'kara-deniz-ana-deniz-seref-ozturk-usta-hi5cy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karadeniz ana deniz

Severiz seni hepimiz 

Espirin de felsefe var

Aydın dır az bileniniz

Temiz havan bol ağacın 

Çalışkandır anan bacın 

Göğün altın,yerin bakır

Ondan olmaz sizde fakir

Sinop Samsun Ordu  Rize

Hepsi bakardı denize

Ekmek sudan taştan çıkar

Artvin''li den kültür akar

Ünye bölgenin Paris''i 

Yoktur mıhlama gibisi

Fındık süper çay kalite

etişmekteymiş kivi si 

Uzun göl de alabalık

Mesireler kalabalık

Yaylarda kurulurmuş

Genellikle akrabalık

Çok insanlar  tanımıştım

Tanımış mutlu olmuştum

Aydın''ından cahiline

Hepsiyle kardeş olmuştum   

Elektrikçi Anzer Yılmaz 

Artist kardeşi Yıkılmaz 

Of''tan Adalet kardeşim

Beni mektupsuz bırakmaz 

Hikmetinden sual olmaz

Hikmet''siz şiir okunmaz

Bayburt''lu Zihni olmadan

Aydın kadrosu kurulmaz 

Şeref usta emek verir

Emekle sevgi beslenir

Dostlarının arasından

Emekten sevgi seslenir.', 'Karadeniz ana deniz Severiz seni hepimiz  Espirin de felsefe var Aydın dır az bileniniz Temiz havan bol ağacın  Çalışkandır anan bacın  Göğü...', ARRAY['Türk Edebiyatı','Şiir','Şeref Öztürk Usta']::text[], 8.5, '{"poet":"Şeref Öztürk Usta","poet_slug":"seref-ozturk-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kara-deniz-ana-deniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsa İdik', 'olsa-i-dik-seref-ozturk-usta-03jvk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiç utanmadım ekmek istemekten acıktığım da

Yolumu kaybettiğimde adres sormaktan birilerine

Hayıflanmadım param olmadığında içememekten

Ne kadar sevdiğimi söylemekten utandığım kadar.

Sen kandırılarak büyütüldün bu güne değin

Annen,baban, kardeşlerin öğretti ilk yalanı

Sonra arkadaşların yalan aşklara ettiler kurban

Yalan söylemeyi henüz bilmeyen kalbine inat.

Aşk demek ayıp sevda demek günahı boynumuza

Avuçlarımızdan kayan yıllardır sebep yalanımıza

Yaşadığımızı bildiğimiz kendi çaresiz yalnızlığımıza

Seni de katmak istedik istemesen de günahlarımıza

Büyüdükçe sen yalanlarda büyüdü seninle birlik

Gençlerden gelen doğrular bile yalanlar kadar eğik

Çünkü büyük yalanları büyüklerden öğrendik

Doğrular bile artık yalanlar kadar olsun istedik.

Onuncu köy kurulmazdı böyle bencil olmasaydık

Sizler doğru kalırdınız bizler yalan bilmeseydik

Sarsılmazdık hiç bir zaman kendimizi bulsa idik

Olduğumuz gibi görünsek göründüğümüz olsa idik.', 'Hiç utanmadım ekmek istemekten acıktığım da Yolumu kaybettiğimde adres sormaktan birilerine Hayıflanmadım param olmadığında içememekten Ne k...', ARRAY['Türk Edebiyatı','Şiir','Şeref Öztürk Usta']::text[], 8.5, '{"poet":"Şeref Öztürk Usta","poet_slug":"seref-ozturk-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olsa-idik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Kötü Bilme', 'beni-kotu-bilme-lokman-hamitoglu-q1xhj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'BENİ KÖTÜ BİLME

Beni öyle kötü bilme

Ben kötü değilim

Benimde çok iyi yanlarım var

Seni çok seven kalbimi bencil bilme

Ellerini tutmak isteyen ellerimin

                            kanlı yönü yok

Gözlerim yollarını gözlüyor diye

                            beni akbaba sanma

Gel

Gel de beni karanlığımda gör

Bak sürmeli(!)  şevkatli gözlerim var

Gel de sensizliğimde beni duy

Duy nasıl vefalı (!)  kalp sesim var

Gelip gönül tahtımı gör

Bak seni nasıl erişilmez etmişim

Beni kötü bilme...

                              .   .   .  .  .  .  .

Çok iyi yanlarım var

      Lokman HAMİTOĞLU', 'BENİ KÖTÜ BİLME Beni öyle kötü bilme Ben kötü değilim Benimde çok iyi yanlarım var Seni çok seven kalbimi bencil bilme Ellerini tutmak istey...', ARRAY['Türk Edebiyatı','Şiir','Lokman Hamitoğlu']::text[], 8.5, '{"poet":"Lokman Hamitoğlu","poet_slug":"lokman-hamitoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/beni-kotu-bilme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben ''Ben'' Olurum', 'ben-ben-olurum-semsettin-arik-fq9ph', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kanatlansa gönlüm bin hızla ötelere 

Belki ben''Ben'' olurum o zaman 

Duymasa kulaklarım,görmese gözüm 

Belki ben ''Ben'' olurum o zaman 

Tutup da nefsimi vursam zincire 

Yol versem içimden müzmin kibire 

Aklımı kurtlar yese ha bire 

Belki ben ''Ben'' olurum o zaman 

Kurtarsam gönlümü ikbal elinden 

Doldursam testimi aşkın selinden 

Ruhuma bir darbe yersem derinden 

Belki ben ''Ben'' olurum o zaman 

Tam olsam! olamam,yarıyım her dem 

Aczime sığınıp saçmalıyorum ben 

Tutup da kolumdan kaldırabilsen 

Belki ben ''Ben'' olurum o zaman 

Bilirim varılmaz sözle menzile 

''İman insanda öz de gerektir 

Özümü bulursam yardımın ile 

Belki ben ''Ben'' olurum o zaman 

Görünüp de hemen versen haberi 

Bekliyorum çünkü o günden beri 

Kapından kendimi atsam içeri 

Belki ben ''Ben'' olurum o zaman 

Işığını görürsem ey irşat edecim 

Dayanır takatım toplanır gücüm 

Yaparım o zaman vuslat''a hücüm 

İşte ben ''Ben'' olurum o zaman.', 'Kanatlansa gönlüm bin hızla ötelere  Belki ben''Ben'' olurum o zaman  Duymasa kulaklarım,görmese gözüm  Belki ben ''Ben'' olurum o zaman  Tutup ...', ARRAY['Türk Edebiyatı','Şiir','Şemsettin Arık']::text[], 8.5, '{"poet":"Şemsettin Arık","poet_slug":"semsettin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ben-ben-olurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Adım TÜRKİYE', 'benim-adim-turki-ye-lokman-hamitoglu-sdh95', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BENİM ADIM TÜRKİYE

Ebubekir’den Sıddıkı

Ömer Faruk’tan Ahak’ı

Osman’dan aldım Ahlakı

Benim adım; TÜRKİYE! ..

Ali’den gizli ilimi

İbn-i Sina’dan bilimi

Ahyara verdim elimi

Benim adım; TÜRKİYE! ..

Şehit kanından bayrağım

Durmadan akan ırmağım

Akdemden gelen toprağım

Benim adım; TÜRKİYE! ..

Şadırvanımda izazlar

Camilerimde namazlar

Gönlümde olmaz marazlar

Benim adım; TÜRKİYE! ..

Küfürlerle savaşanım

Zalimlerle çatışanım

Abdallarla barışanım

Benim adım; TÜRKİYE! ..

  Lokman HAMİTOĞLU', 'BENİM ADIM TÜRKİYE Ebubekir’den Sıddıkı Ömer Faruk’tan Ahak’ı Osman’dan aldım Ahlakı Benim adım; TÜRKİYE! .. Ali’den gizli ilimi İbn-i Sina’...', ARRAY['Türk Edebiyatı','Şiir','Lokman Hamitoğlu']::text[], 8.5, '{"poet":"Lokman Hamitoğlu","poet_slug":"lokman-hamitoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/benim-adim-turkiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazım Hikmet', 'nazim-hikmet-levent-ecemis-0pl84', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'YATAR BURSA KALESİNDE

Sevdalınız komünisttir,

on yıldan beri hapistir,

yatar Bursa kalesinde.

Hapis ammâ, zincirini kırmış yatar,

en âlâ mertebeye ermiş yatar,

yatar Bursa kalesinde.

Memleket toprağındadır kökü,

Bedreddin gibi taşır yükü,

yatar Bursa kalesinde.

Yüreği delinip batmadan,

şarkısı tükenip bitmeden,

cennetini kaybetmeden,

yatar Bursa kalesinde.', 'YATAR BURSA KALESİNDE Sevdalınız komünisttir, on yıldan beri hapistir, yatar Bursa kalesinde. Hapis ammâ, zincirini kırmış yatar, en âlâ mer...', ARRAY['Türk Edebiyatı','Şiir','Levent Ecemiş']::text[], 8.5, '{"poet":"Levent Ecemiş","poet_slug":"levent-ecemis","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/nazim-hikmet-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beşinci Nisan', 'besinci-nisan-lokman-hamitoglu-ljcgm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BEŞİNCİ NİSAN

Sensiz geçen beşinci nisanımda bitiyor

Karabulutlar gezdiğim yerlere

İlticada bulunuyor

Hasretinden yağan her yağmur

Beni sırılsıklam edene dek ıslatıyor

Her tarafta senden izler var gibi

Oysa sen hiç buralı olmadın

Baktığım duvardan

Tebessümlü resmin 

Melülce bana bakar

Ve gönlüm

Yiğitçe 

Hoyratça yanar! .. 

............... 

Belki de uzayan zamanlarda

Sen de beni düşünüyorsun

Hatta beni düşünmekten

Hiç vazgeçmedin

Belki de resmime baktığın tüm anlarda

Ağladın

Beni canında can gibi özledin

Geceler boyu uyumadın

Belki de her yağmur yağdığında

Dışarı çıkıyorsun

Ve sırılsıklam olana dek geziyorsun

Sokaklara

Caddelere

Banklara

Çimenlere resmimi çizip izliyorsun

Ve

Beni halen çok özlüyorsun

BELKİDE! ? ! 

Lokman HAMİTOĞLU', 'BEŞİNCİ NİSAN Sensiz geçen beşinci nisanımda bitiyor Karabulutlar gezdiğim yerlere İlticada bulunuyor Hasretinden yağan her yağmur Beni sırı...', ARRAY['Türk Edebiyatı','Şiir','Lokman Hamitoğlu']::text[], 8.5, '{"poet":"Lokman Hamitoğlu","poet_slug":"lokman-hamitoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/besinci-nisan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Davadır Aşk', 'bir-davadir-ask-lokman-hamitoglu-qudxm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'BİR DAVADIR AŞK

Hançerden keskin kurşundan hızlı

Aslandan vahşi cerenden nazlı

Ballardan tatlı iksirden hazlı 

       Bir  yaşamdır aşk...

Soğukta sıcak sıcakta yağmur

Gönülde kanat omuzda kambur

Gündüzde batın gecede zinnur

        Bir esrardır aşk...

Gözlerde tufan yürekte ateş

Ellerde dua bakışta güneş

Vuslatta hep yek fırkatta düşeş

         Bir oyundur aşk...

Yaşama sebep ölüme neden

Denize kumsal toprağa çimen

Bir tarafta sen bir tarafta ben

           Bir davadır aşk...

       Lokman HAMİTOĞLU', 'BİR DAVADIR AŞK Hançerden keskin kurşundan hızlı Aslandan vahşi cerenden nazlı Ballardan tatlı iksirden hazlı         Bir  yaşamdır aşk... S...', ARRAY['Türk Edebiyatı','Şiir','Lokman Hamitoğlu']::text[], 8.5, '{"poet":"Lokman Hamitoğlu","poet_slug":"lokman-hamitoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-davadir-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ses', 'bir-ses-lokman-hamitoglu-0j1y2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BİR SES

Bir ses duydum öteden 

Bana diyordu... hey sen! 

- Nedir bu azametin? 

- Bu gurur, kibir neden? ! ? 

Bir ses duydum öteden 

Bana diyordu... hey sen! 

- Okumadın mı şunu? 

- Nefsin öldür ölmeden! ? ! 

     

   Lokman HAMİTOĞLU', 'BİR SES Bir ses duydum öteden  Bana diyordu... hey sen!  - Nedir bu azametin?  - Bu gurur, kibir neden? ! ?  Bir ses duydum öteden  Bana diy...', ARRAY['Türk Edebiyatı','Şiir','Lokman Hamitoğlu']::text[], 8.5, '{"poet":"Lokman Hamitoğlu","poet_slug":"lokman-hamitoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-ses-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakma Beni', 'birakma-beni-lokman-hamitoglu-8p5bu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'BIRAKMA BENİ

Sağına bakarsan beni görürsün

Sana öyle yakınım ki...

Kulağını açsan beni duyarsın

Sana öyle yakınım ki...

Elini uzatsan beni tutarsın

Sana öyle yakınım ki...

Bırakma beni ateşlerde 

Öyle güzel gözlerin varken

Gözlerinde yüzerim...

Bırakma beni falezlerde

Öyle pamuk dizlerin varken

Dizlerinde yatarım...

Bırakma beni zulümlerde 

Öyle güzel ellerin varken

Ellerinde kalırım...

 Lokman HAMİTOĞLU', 'BIRAKMA BENİ Sağına bakarsan beni görürsün Sana öyle yakınım ki... Kulağını açsan beni duyarsın Sana öyle yakınım ki... Elini uzatsan beni t...', ARRAY['Türk Edebiyatı','Şiir','Lokman Hamitoğlu']::text[], 8.5, '{"poet":"Lokman Hamitoğlu","poet_slug":"lokman-hamitoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/birakma-beni-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biraz Bizgibi', 'biraz-bizgibi-lokman-hamitoglu-x3uvx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'BİRAZ BİZ GİBİ

Zincirlerle mi gökten indi? 

Yerden Kaarun’un hazineleriyle mi çıktın? 

Sen mi yarattın şu küçük dağları? 

Büyükler babanın mirası mı? 

Neden burnunun havadarlığı? 

Neden bu laf cambazlığı? 

Bu kör olası gözlerin hep göğün 

   yedinci katına mı çıkmak istiyor? 

Seninle şu vadilerde gezsek kıyametmi kopar? 

Sahillerde yürüsek

Sana ellerimle karanfiller,

Papatyalar,

Güller kesip versem,

Bu güzel çiçekleri ellerimden alsan,

Koklasan

Bana doğru bir adım atsan

Saçlarını düzeltir gibi yüzüme dokunsan

Biraz sen / den gibi

Biraz benden gibi

Biraz biz gibi

Biraz biz olsak kıyamet mi kopar? . .

               Lokman HAMİTOĞLU', 'BİRAZ BİZ GİBİ Zincirlerle mi gökten indi?  Yerden Kaarun’un hazineleriyle mi çıktın?  Sen mi yarattın şu küçük dağları?  Büyükler babanın m...', ARRAY['Türk Edebiyatı','Şiir','Lokman Hamitoğlu']::text[], 8.5, '{"poet":"Lokman Hamitoğlu","poet_slug":"lokman-hamitoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/biraz-bizgibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Gibisin', 'siir-gibisin-ayse-tosun-9x7zo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'şiir gibisin

şiir gibisin sevdam şiir gibi

dudakların; 

yaşamayı,saygıyı,mutluluğu,,aşkı,

haykırır şiir gibi,

duyarım,coşkulu,gizemli sesini çocuklar gibi,

sevdam,

sormadan sevdim seni şiir gibi,

gözlerin 

alır götürür beni enginlere,

bakarsın çimen çimen,

yatıp uyumak gelir içimden ürkek bir ceylan gibi,

bazen de gök gök atlas gibidir,

gezmek,sana dokunmak,sana uçmak isterim kuşlar gibi,

üzüldüğünde kararır bulutlar gibi,

yağar  yağmur gibi,

şiir gibisin sevdam şiir gibi,

ah.. ah..o deniz olduğu anlar,

beni o anlar yakar,

dalgalanır,kabarırsın, beyaza çalarsın,

çıldırırsın coşarsın deryalar gibi,

sonra,  çarşaf gibisindir, yatmaya açılırsın,

işte o an.......

senle çimmek,senle ıslanmak,senle oynamak, 

senle bir vücut olma arzusu yakar  beni,

yakarsın bedenimi,

bazen tattır petekteki bal gibi,

tadarım seni alev alev volkan gibi

akarım gözlerimden gözlerine sevdan gibi,

of.....of...

sarar sorunların gözlerini,

karışıktır kafan anlatmazsın,

saklarsın onları şifren gibi,

şiir gibisin sevdiğim şiir gibi,

sonbahar rengi saçların onlar gamlı çınar,

sarar kokusu estikçe rüzgar rüzgar,

sana hasret kaldığım anlar,

şiir gibisin sevdam şiir gibi,

üşür ellerim hüzünlendiğim zamanlar,

tutarsın ellerimi,ısıtırsın, öpersin,koklarsın,

yumuşacık  şiir gibi,

sarıp sarmalarsın bebek gibi, kalbinde saklarsın

can gibi,

seni satırlara anlatmak öyle zor ki,

sevdam, şiirim, 

evet şiir gibisin sevdiğim şiir gibi,

korkuyorum yaşayamamaktan,

yazamamaktan seni şiir gibi,

sen öyle bendesin ki

şiir gibi.            07.11.2005 a.tosun', 'şiir gibisin şiir gibisin sevdam şiir gibi dudakların;  yaşamayı,saygıyı,mutluluğu,,aşkı, haykırır şiir gibi, duyarım,coşkulu,gizemli sesini...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tosun']::text[], 8.5, '{"poet":"Ayşe Tosun","poet_slug":"ayse-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/siir-gibisin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz İnsanlar', 'biz-i-nsanlar-lokman-hamitoglu-6lujr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BİZ İNSANLAR

Ne ben ilk mahkumum

Nede son mahkumum 

Hapishanelerin göreceği

Biz insanlar

Biz insanlar dünyanın efendileri olarak

Önce zalim olmayı

Sonra zulüm etmeyi öğrendik

Hapishaneler inşa ettik

Özgürlüğümüz için! ...

       Lokman HAMİTOĞLU', 'BİZ İNSANLAR Ne ben ilk mahkumum Nede son mahkumum  Hapishanelerin göreceği Biz insanlar Biz insanlar dünyanın efendileri olarak Önce zalim ...', ARRAY['Türk Edebiyatı','Şiir','Lokman Hamitoğlu']::text[], 8.5, '{"poet":"Lokman Hamitoğlu","poet_slug":"lokman-hamitoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/biz-insanlar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nesnelerle Konuşmalar / Küçük Çınar', 'nesnelerle-konusmalar-kucuk-cinar-metin-yalti-akzj4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yürürken İstiklal’de 

Çarpıştım sandım biriyle 

Şöyle bir baktım omzumdan 

Göz göze geldim birden 

Karşımdaki bir fidandı 

Kim bilir kaç yüz yıl sonra 

İstanbul’u anlatacak gencecik bir çınardı… 

Yüzü düşüktü yere 

Başını kaldırmadan 

—Kusura kalma dedi 

Dalgınım bu günlerde 

Engelliyormuşum diye 

Kesecekmiş bizi 

Bakımımızdan yükümlü belediye. 

Hiç olur mu dedim, hiç öyle? 

Farkındaysan İstiklal Caddesi bura. 

Dernekleri var, Hem Baroda burada 

Sonra çevreciler duruyor ne güne? 

Hadi aldırma sen boş sözlere 

Rahatla 

Islığını çal rüzgârlarla… 

Bu gün aklıma düşünce 

Yürüdüm gene Taksim’den Tünel’e 

Çıplak kalmıştı İstiklal 

Ağaçlarından soyununca… 

Beni omuzlayan çınar yoktu sahiden 

Sordum köşedeki büfeden 

Belediyece kesildi dedi üçgün önce 

Soluğum kesildi birden 

Sen o olmalısın dedi, o çevreci 

Yüzüme bakınca köşedeki büfeci 

Hani sesiniz çıkacaktı gür 

Direnecektiniz bu kesimlere

Hani ağaçlarımız büyüyecekti özgür. 

Sustum. Utancım yayıldı yüzüme 

Büfeci elini koyup omzuma 

Üzülme dedi seni anlamıştı o gene de 

İki üçgün olsun yaşadı ümitle 

Selam da söyledi sana son nefeste… 

TEPKİ ŞİİRLER 

16 /11 / 2005', 'Yürürken İstiklal’de  Çarpıştım sandım biriyle  Şöyle bir baktım omzumdan  Göz göze geldim birden  Karşımdaki bir fidandı  Kim bilir kaç yüz...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/nesnelerle-konusmalar-kucuk-cinar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhammed Mustafa (s.a.v.)', 'muhammed-mustafa-s-a-v-lokman-hamitoglu-nue8w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'MUHAMMED MUSTAFA (S.A.V.) 

İyilik anahtarı kötülükler kilidi

Fisku Fücura karşı mazlumların ümidi

Tarihler gıptasıyla Bağdat’ın Can mevlidi

Müslümanlar direği ya MUHAMMED MUSTAFA. . . 

Aşık olmak isteyen hep ismini söylüyor

Huzurunu kaybeden yollarında buluyor

Senin için yürekler sağnak - sağnak ağlıyor

İçin - için yanıyor ya MUHAMMED MUSTAFA... 

Kış akşamlarımızın batmayan güneşisin

Yaz ortası çöllerde on parmakla zemzemsin (!) 

Bize şefaat eyle Sen şefaatçimizsin

Canımızın içisin ya MUHAMMED MUSTAFA... 

Ağlayan gözlerimde ıslanan kirpiğimde 

Titreyen dudağımda karıncalı elimde

Sen rehberim olmuşsun ben istikametinde

Gösterdiğin yoldayım ya MUHAMMED MUSTAFA... 

Adını andığımda yaşam gücüm uyanır 

Yoluna koştuğumda tayy-ı mekan yaşanır

Sende çare bulmuşum umutlarım katlanır

Huzurlarım şahlanır ya MUHAMMED MUSTAFA 

Kurban olayım Sana  ya MUHAMMED MUSTAFA. . .

		

				Lokman HAMİTOĞLU', 'MUHAMMED MUSTAFA (S.A.V.)  İyilik anahtarı kötülükler kilidi Fisku Fücura karşı mazlumların ümidi Tarihler gıptasıyla Bağdat’ın Can mevlidi ...', ARRAY['Türk Edebiyatı','Şiir','Lokman Hamitoğlu']::text[], 8.5, '{"poet":"Lokman Hamitoğlu","poet_slug":"lokman-hamitoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/muhammed-mustafa-s-a-v-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam', 'sevdam-ayse-tosun-pj3yy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevdam

Uyumadan uyandım yine bu gece,

saat 05.45 ''de rüyanın etkisiyle; 

Ne garipti 

Sevdiğimi bile bile vermedin

kırmızı gülleri niye

Sende kalsın güller,

Suskun yüzünü güldürsün,

Aşk penceren canlansın,

karamsarlığı  alsın,

Seni tekrar bana versin diye; 

Versin.

Çünkü ben; 

Sen gülersen, gülerim,

Sen  ağlarsam ağlarım,

Sen mutluysam mutluyum,

Sen dertliysen dertliyim,

Sen özgürsen özgürüm,

sen sevdalıysan sevdalanırım

Sen yazarsan yazarım,

Sen okursan okurum,

Sen uyursan uyurum

Sen hasretsen Hasretim.

Sen (..............) 

Ama ben Sen sevmesen de severim.', 'Sevdam Uyumadan uyandım yine bu gece, saat 05.45 ''de rüyanın etkisiyle;  Ne garipti  Sevdiğimi bile bile vermedin kırmızı gülleri niye Sende...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tosun']::text[], 8.5, '{"poet":"Ayşe Tosun","poet_slug":"ayse-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevdam-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Kız', 'kucuk-kiz-ayse-tosun-hhh7e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Küçük kız çocuğu

Bilmiyordu.

başlamıştı kız çocuğu okula ilk gündü

minik yüreği pır pırdı

Tanışacaktı öğretmeniyle öyle söylüyorlardı

Baktı etrafına  çocuktan çok anne vardı.

Yasemen yalnızdı.

Yoktu Annesi, babası

düşündü; çocuk aklıyla; 

sordu benimkiler nerede; 

Biliyordu; 

annesi okuyor babası çalışıyordu.

Yüreği yerinden çıkacak gibiydi.

Öğretmenini bilmiyordu,

Dizilmişti çocuklar arka arkaya

Boyu kısa olduğu için düşmüştü  en on sıraya; 

Düşünüyordu kendi dünyasında

Birden..Bir el dokundu saçlarına

Korktu! 

Kim diye yüzüne baktı

Değildi tanıdık.

Çekindi, ürkekçe,

Yürüdüler birlikte 

Burası sınıftı duvarları resimler kaplı.

Yalnız değildi artık,

Biliyordu  O sıcak el öğretmeni 

O’na yol olacaktı. 27.10.2005 Ayşe TOSUN', 'Küçük kız çocuğu Bilmiyordu. başlamıştı kız çocuğu okula ilk gündü minik yüreği pır pırdı Tanışacaktı öğretmeniyle öyle söylüyorlardı Baktı ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tosun']::text[], 8.5, '{"poet":"Ayşe Tosun","poet_slug":"ayse-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kucuk-kiz-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemim', 'ozlemim-ayse-tosun-z02vx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'özlemim:

bak aşkım yine oradayım,

beni ilk öptüğün ağacın altındayım,

onunda dalları bükük,

benim boynumun  olduğu gibi,

öksüzüm sen gittin gideli

yalnızım sen gelmeyeli,

aşkım,

birlikte yürüdüğümüz yolu yürüyorum,

sensiz, yalnız, tek başıma,

seninle gezdiğimiz köyden geçtim,

el salladım kırmızı damlara,

özlemlerin yüreğimi yaka yaka

aradım seni sokaklarında

canım yandı ağladım,hüzünlendim,

bir kelebek kondu. camın kenarına

bin bir renk vardı kanatlarında.

birden...............

evet buldum.

yüreğimin en özel yerindeydin oysa

demiştin özlemek güzel 

hele sonunda kavuşmak varsa,

özlüyorum,hem de çok.........

o günü bekliyorum..........

özlüyorum.

bak şimdi sahildeyim,

hayallerimiz,

denizde sen ve ben

ayaklarımız ıslanırken,

birleşirken ellerimiz,

gök üstümüzde şahitken,

kumlar yorgan gibi sararken bedenimizi

söz vermiştik...

hep özleyeceğiz.........

Özlüyorum ben hep seni.', 'özlemim: bak aşkım yine oradayım, beni ilk öptüğün ağacın altındayım, onunda dalları bükük, benim boynumun  olduğu gibi, öksüzüm sen gittin ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tosun']::text[], 8.5, '{"poet":"Ayşe Tosun","poet_slug":"ayse-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ozlemim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlık', 'i-nsanlik-engin-turk-52kse', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaradan yarattı bizleri insan,

        Ayrı ayrı verdi herkese lisan

        Hayvandan kendini ayırıyorsan 

        İnsana insanca davran kardeşim.

       Bu dünya fanidir, kimseye kalmaz.

       Ettiği kimsenin yanına kalmaz,

       Değil insanlara, tüm mahlûkata,

       İnsansan insanca davran kardeşim.

       Aklını iyiye güzele kullan.

       Zulmetmeyi bırak gel sen de uslan.

       Vatana millete hizmette varsan,

        İnsana insanca davran kardeşim.

        Gaflet uykusundan geç kalma uyan,

       Kılavuz istersen yetmez mi kur’an? 

       Var mı Yakıp, yıkıp ayakta duran? 

        İnsansın insanca davran kardeşim.

	

                                                    17.11.2005 21:01', 'Yaradan yarattı bizleri insan,         Ayrı ayrı verdi herkese lisan         Hayvandan kendini ayırıyorsan          İnsana insanca davran ka...', ARRAY['Türk Edebiyatı','Şiir','Engin Türk']::text[], 8.5, '{"poet":"Engin Türk","poet_slug":"engin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/insanlik-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hukuksuz Vatandaşa', 'hukuksuz-vatandasa-cafer-yilmaz-1xojt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kere delmemi istiyorsun yasayı...

hemde Anayasayı...

Tamam, deleceğim bir şartla; 

nikahına alacaksın

bir kere sabahlara dek

seviştiğim kadını....

                           09.03.2005', 'Bir kere delmemi istiyorsun yasayı... hemde Anayasayı... Tamam, deleceğim bir şartla;  nikahına alacaksın bir kere sabahlara dek seviştiğim ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hukuksuz-vatandasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orman', 'orman-engin-turk-2uhl2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Orman yurdun canıdır.

Memleketin servetidir, malıdır.

Onu kesen insan değil canidir.

Sevgi ile koruyalım ormanı.

Senin geleceğin ondadır,

Onunki sende.

Onu yakan uslu değil delidir.

Şefkat ile koruyalım ormanı.

Orman ruhun besinidir, kanıdır.

Tüm canlının, nebatatın evidir.

Onsuz hayat faniden de fanidir.

İçtenlikle koruyalım ormanı.

Beşikten mezara gerekli odur.

Hayatımız için önemi boldur.

Bu ara çoğaldı ormanda bodur.

Hep beraber gürletelim ormanı.

                                                  

                                                           02.24.2002', 'Orman yurdun canıdır. Memleketin servetidir, malıdır. Onu kesen insan değil canidir. Sevgi ile koruyalım ormanı. Senin geleceğin ondadır, On...', ARRAY['Türk Edebiyatı','Şiir','Engin Türk']::text[], 8.5, '{"poet":"Engin Türk","poet_slug":"engin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/orman-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik Hayat', 'yitik-hayat-engin-turk-j6ptc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayat yaşıyorum sandım dünyada,

Hayatı harcadım ona yanarım.

Haniya nerede benim gençliğim! 

Ararım bulamam ona yanarım.

Şunu da bunu da yapayım derken,

Bir baktım saçlara ak düştü erken,

Haniya nerede arkadaş, akran! 

Ararım bulamam ona yanarım.

                                       01.04.2005', 'Hayat yaşıyorum sandım dünyada, Hayatı harcadım ona yanarım. Haniya nerede benim gençliğim!  Ararım bulamam ona yanarım. Şunu da bunu da yap...', ARRAY['Türk Edebiyatı','Şiir','Engin Türk']::text[], 8.5, '{"poet":"Engin Türk","poet_slug":"engin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yitik-hayat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumhuriyet', 'cumhuriyet-engin-turk-ff3dl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Atatürk’ün eseridir, bu cumhuriyet.

Yüceltmeye, yükseltmeye gayret et.

Onsuz olmaz bu dünyada hürriyet.

Ebedi sen yaşa ey cumhuriyet.

Erdemli insanlar onda çok olur.

Karanlık, hurafe onda yok olur.

Bütün toplum onda mutluluk bulur.

Sonsuza dek yaşa sen cumhuriyet.

Hak, hukuk, adalet cumhuriyette.

 Bağımsızlık yaşar cumhuriyette.

İnsana değerde ve de hizmette.

Eşine rastlanmaz ey cumhuriyet.

Kolay kurulmadı bu cumhuriyet.

Atam az mı çekti bunda eziyet.

Kazanıldı zafer ve de nihayet.

Kuruldu şerefle bu cumhuriyet.

                                      

                                       

	 29.10.04', 'Atatürk’ün eseridir, bu cumhuriyet. Yüceltmeye, yükseltmeye gayret et. Onsuz olmaz bu dünyada hürriyet. Ebedi sen yaşa ey cumhuriyet. Erdeml...', ARRAY['Türk Edebiyatı','Şiir','Engin Türk']::text[], 8.5, '{"poet":"Engin Türk","poet_slug":"engin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cumhuriyet-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsim Koymaya Gerek Yok!', 'i-sim-koymaya-gerek-yok-ayse-birgul-yilmaz-bbgsc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç bu kadar sevilmedim

Hiç bu kadar mutlu olmadım

Şimdiye kadar nerelerdeydin

Aradığım beklediğim sendin

Böyle içten böyle çok sevdiğim

Öyle iyisin ki iyi ki seni tanıdım

Bu kaçıncı bu son artık dediğim.

Hiç mi aşkta huzur bulmayacağım

Hep ben mi hatalıyım anlayamadım

Olmadı seninde kalbini kazanamadım

Çocuk gibi davranıyorsun diyorsun

Yoruldum, kırıldım, soğudum..

Ne söylediğini anlasam sormayacağım

Nereye gittiğimi bilsem durmayacağım

Bir ağlayabilsem belki susmayacağım

Boş hayaller peşinden koşmayacağım

Nereye kadar hep kaybet kaybet 

Bu günlerde dikkatsizim dikkat et

Ne senden itibarenim ne senden ibaret

Ne de oyuncağın,

İşine geldiği gibi olmayacağım.

Olmazları oluruna bıraktım

Geçmişin perdesini aralayıp,

Mutlu bir zamanları hatırlayıp,

Mutlu olmaktan mutsuzum, bıktım.

Artık aşka dair konuşmayacağım.

Ayşe Birgül Yılmaz

13/11/2005', 'Hiç bu kadar sevilmedim Hiç bu kadar mutlu olmadım Şimdiye kadar nerelerdeydin Aradığım beklediğim sendin Böyle içten böyle çok sevdiğim Öyl...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/isim-koymaya-gerek-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atam', 'atam-engin-turk-iwszp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu millete kurtuluş yolunu sen gösterdin.

Yaşam boyu durmayıp vatan için çalıştın.

Yurt sevgisi için de cihan ile savaştın.

İleri, hep ileri gitmek için uğraştın.

Atam, ne mutlu sana amacına ulaştın.

Bu millete her şartta, her durumda güvendin.

Her tür olumsuzluğu, kararlılıkla yendin.

En büyük eserini Türk gençlerine verdin.

İlkelerinle bize çağdaş ufuklar açtın.

Atam ne mutlu bize, yaşıyor emanetin.

                                 10 Kasım 2005', 'Bu millete kurtuluş yolunu sen gösterdin. Yaşam boyu durmayıp vatan için çalıştın. Yurt sevgisi için de cihan ile savaştın. İleri, hep ileri...', ARRAY['Türk Edebiyatı','Şiir','Engin Türk']::text[], 8.5, '{"poet":"Engin Türk","poet_slug":"engin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/atam-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik Sevdam', 'yitik-sevdam-fethi-aslan-vuky8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Siz hiç Deniz kızına aşık oldunuz mu? 

Ve onun yolunu bekledinizmi,

saatlerce gözlerinizi dikip enginlere

Bir hayal belki onunla beraber olmak,

biliyorum benimkisi imkansızı,olmayanı aramak.

Hicbir zaman tutamayacağım ellerini,

hiç bakamayacağım gözlerini,

hiç dokunamayacağım tenini,

ve hiç tadamayacağım terini arzulamak.

Aslında çok yakınımda,

ama yakın olduğum kadar da uzak.

Ama aşk zaten, değilmidir imkansızı arzulamak.

Bir ihtimaller toplamıdır yaşamak,

ve yaşama kuvvet vermez mi ummak. 

Biliyorum bu imkansızı,olmayanı aramak,

ama benimkisi kendi algıladığım bir Dünya`da,

olgular evreninde yaşamak.

Ama zaten aşk,değilmidir ulaşılamayanı azulamak.

Hep şiirler yazdım ona,

birgün, gözlerine bakarak okuyacağımı umarak.

Ama biliyordum şiirlerim hep öksüz kalacak.

Çünkü o benden uzakta,hep ulaşılmazımda,

ve aşkı bende  yitik bir sevda olarak kalcak.

O bende her zaman  ihtimaller toplamının bir parçası 

                                          -olarak kalacak', 'Siz hiç Deniz kızına aşık oldunuz mu?  Ve onun yolunu bekledinizmi, saatlerce gözlerinizi dikip enginlere Bir hayal belki onunla beraber olm...', ARRAY['Türk Edebiyatı','Şiir','Fethi Aslan']::text[], 8.5, '{"poet":"Fethi Aslan","poet_slug":"fethi-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yitik-sevdam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse Sormaz Bana', 'kimse-sormaz-bana-ramazan-ates-p75te', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben içinde yaşıyorken,

Niye gelip sormaz bana? 

Cennet diye anlatırken,

Niye fikir sormaz bana? 

Sorsa bile inanmaz ya! ..

Avrupa’yı cennet sanan,

Bir kaç bakan, bir başbakan.

Nedir bilmem cennet olan,

Niye halim sormaz bana? 

Sorsa bile inanmaz ya! ..

Milletimi aldatarak,

İştahları kabartarak,

Maksat koltuklarda kalmak,

Nedir diye sormaz bana.

Sorsa bile inanmaz ya! ..

Ekonomisi çöküşte,

Huzur muzur yok kimsede.

Biz canımızdan bezdikte,

Kimse gelip sormaz bana.

Sorsa bile inanmaz ya! ..

Çoğu insan aç geziyor,

Çocuklar esrar içiyor,

Avrupa içerden çürüyor,

Kimse görüp sormaz bana

	Sorsa bile inanmaz ya! ..

Bakanlar, ey başbakanlar! 

Ne varsa vatanda var.

Sözümüze kulak verin,

Yurdun kıymetini bilin,

              O dur en iyi Avrupa! ...

Ramazan Ateş/Enechede-17.11.2005', 'Ben içinde yaşıyorken, Niye gelip sormaz bana?  Cennet diye anlatırken, Niye fikir sormaz bana?  Sorsa bile inanmaz ya! .. Avrupa’yı cennet ...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kimse-sormaz-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapma', 'yapma-volkan-yoruc-lzutu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dur

Sakın öyle yapma

Bakma bana uzaktan usulca

Manzaramı oldum artık

Yoksa yırtık bir resimli eski hatıra? 

Oysa sevmiştim 

Sende öyle demiştin

Hayır 

Bana öyle uzak durma

Aralara hayalleri koyma

Düşen her yaprağı bana denk düşme

Güz geldi diye sendemi gidiceksin böyle? 

Neden bu hüzün? 

Yapma

Sakın dönme ardını bana

Ve susma

Suskunlukla vurma bana usulca

Dön, dön yüzünü bana

Bak ağlarsam kötü ağlarım

Susmam

Tıkanır boğazım

Yıldızlarla yalnız bırakma beni böyle

Onlar kalmasın senden hatıra

Her gece ölüm olur artık bana

Dön bana

Atma adımlarını o yola

Yapma

...

Gittin

Artık yoksun

Senden armağan kaldı o bayramlar

O yıldızlar, o yollar, o bakışlar

Ve elimde senden kalan o hayali hoş hatıralar', 'Dur Sakın öyle yapma Bakma bana uzaktan usulca Manzaramı oldum artık Yoksa yırtık bir resimli eski hatıra?  Oysa sevmiştim  Sende öyle demiş...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yapma-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabır nasıl olur?', 'sabir-nasil-olur-mikdat-bal-8oq3b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabrın diğer manası nefse hakim olmaktır.

Her hangi bir olayda, soğukkanlı kalmaktır

Gazap, öfke anında, bazen alttan almaktır

Sabır zordur velakin, neticesi çok hoştur

Sabırsızlık ayrıca, geçici bir cinnettir

Şeytan her an kışkırtır, o ne büyük lanettir

Sabredenin dünyası, ahireti cennettir

Nefis kördür ayrıca, kuruntusu bomboştur

Gazabını yenenler, güçlü diye anıldı

Sert davranan kaybetti, hata etti yanıldı

Aşırı uysal olmak, iyi bir şey sanıldı! 

Böyle zordur yaşamak, o enayi bir kuştur! 

Mikdat Bal der her zaman, orta yolu tutmalı

Mesela bir lokma ol, alan seni tatmalı

Alan seni atmasın, ne de seni yutmalı 

Zillet hordur arkadaş, aşılmaz bir yokuştur', 'Sabrın diğer manası nefse hakim olmaktır. Her hangi bir olayda, soğukkanlı kalmaktır Gazap, öfke anında, bazen alttan almaktır Sabır zordur ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sabir-nasil-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kul Azarsa', 'kul-azarsa-ramazan-ates-5fi4a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kişi aklın eteğine,

Düşürürse hayır gelmez.

Koşarsa nefsin peşine,

Artık doymak nedir bilmez.

Haram tatlı gelir ona,

Saldırır ki sağa sola.

Dön deseler doğru yola,

Hiç kimseye kulak vermez.

Gününü gün edip yaşar,

Kumar oynar, içki içer,

Cami görse ordan kaçar,

Abdest alıp namaz kılmaz.

Kul azarsa işi kötü,

Şeytanlarla geçer günü,

Ömür kısa, vade sonu,

Gelir diye hiç düşünmez.

Allah korusun bizi,

Şaşırtmasın yolumuzu.

Oğlumuzu, kızımızı,

İnşallah kötülük bulmaz,

Şeytana oyuncak olmaz.

Ramazan Ateş/Enschede-17.11.2005', 'Kişi aklın eteğine, Düşürürse hayır gelmez. Koşarsa nefsin peşine, Artık doymak nedir bilmez. Haram tatlı gelir ona, Saldırır ki sağa sola. ...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kul-azarsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurban', 'kurban-engin-turk-bwkxq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Allah''ın yolunda kesilen candır.

İbrahim''le İsmailden kalandır.

İnan ki bu dünya küllen yalandır.

Yaptığınla gideceksin oraya.', 'Allah''ın yolunda kesilen candır. İbrahim''le İsmailden kalandır. İnan ki bu dünya küllen yalandır. Yaptığınla gideceksin oraya....', ARRAY['Türk Edebiyatı','Şiir','Engin Türk']::text[], 8.5, '{"poet":"Engin Türk","poet_slug":"engin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kurban-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunmayacağım', 'dokunmayacagim-sefer-yesilyurt-h7meb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ben dokunmadım. 

.......................kendisi değdi... 

ben demedim 

..................rüzgar dedi... 

kırıldı dokuz yerinden... 

.............................uyuyan gözler.. 

söylemeyen diller utandı kendinden 

gül kokmaz 

............kuşlar ötmez 

.........................yelsiz gece 

.................................tutsağım... 

.......................................kendi demir parmaklığımda 

yalnızım... 

.................yağlı urganımda 

asılmayan yüreğe 

................çekilmeyen pime 

...........................söz verdim geceye 

............................................dokunmayacağım....', 'ben dokunmadım.  .......................kendisi değdi...  ben demedim  ..................rüzgar dedi...  kırıldı dokuz yerinden...  ...........', ARRAY['Türk Edebiyatı','Şiir','Sefer Yeşilyurt']::text[], 8.5, '{"poet":"Sefer Yeşilyurt","poet_slug":"sefer-yesilyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dokunmayacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Kızına Özlem', 'deniz-kizina-ozlem-soner-kose-jcnm9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kelimeler boğazımda takılıp kalıyor.

Seni düşündüğümde…

Durmadan yalnızlık dalgalarıyla boğuşuyor

Sensizliğe isyan eden kalbim.

Yenik düşüyorum dalgalara çoğu zaman

Senin yokluğunda.

Suskun değil kalbim 

Durmadan seni haykırıyor aslında.

Duymuyor deniz kızı, 

Duymuyor kimse beni,

Sen gittiğinden beri.', 'Kelimeler boğazımda takılıp kalıyor. Seni düşündüğümde… Durmadan yalnızlık dalgalarıyla boğuşuyor Sensizliğe isyan eden kalbim. Yenik düşüyo...', ARRAY['Türk Edebiyatı','Şiir','Soner Köse']::text[], 8.5, '{"poet":"Soner Köse","poet_slug":"soner-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/deniz-kizina-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Düş Kur', 'bir-dus-kur-volkan-yoruc-dcl9f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir düş kur

Kur ki hayat aksın gönlünden

Nehir olsun çağlasın

Çağlasın ki yüreğin ferahlasın

Bir düş kur

Öyle olsunki kimse ulaşamasın sana

Mavi gökyüzünde uçurtma misali

Süzülesin semalarda

Bir düş kur

Senin olsun o düşler

Kimse daha görmemiş olsun öylesini

Yemyeşil kırlardan fışkırsın sevdan

Çiçekler gibi

Açsınlar yüreğinden göğsüne 

Kimsede olmasın o düşler

Bir düş ol hatta

Açılıversin sana olmayan şehirler

Gir içeride selam yolla sevdalılara

Filizlensin sendede aşk ateşi

Bir düş kur 

Ve kur ki dağlansın seni istemeyen sevdasız gönüller', 'Bir düş kur Kur ki hayat aksın gönlünden Nehir olsun çağlasın Çağlasın ki yüreğin ferahlasın Bir düş kur Öyle olsunki kimse ulaşamasın sana ...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-dus-kur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanın En Zor İşi Kendisini Bilmesi', 'i-nsanin-en-zor-i-si-kendisini-bilmesi-ahmet-nural-ozturk-op6gu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'insanın en zor işi kendisini bilmesi

gerisi yaşamın hikayesi

bugün üç kuruş yarın beş yarından sonra yok kuruş

kolay bir duruş

beceremeyen de yok galiba bu işi

ama kendini bilmek 

hele bir de vaktinde

zor adam işi

tıpkı bir çiçeği sevmek gibi

ama öyle adam gibi

adam kim sen kim mi

beceremen mi

üç günlük dünyada istediğin kolay bir iş mi

yorulmadam geçip gitmek mi

kim bilirse bilsin mi kendini

eğer çok meraklıysa 

senin için de biliversin mi seni

Ah küfür etmek günah olmasaydı keşke

bilirdim ben sana diyeceğimi

ne yazık ki

aslında mevsim de geçti', 'insanın en zor işi kendisini bilmesi gerisi yaşamın hikayesi bugün üç kuruş yarın beş yarından sonra yok kuruş kolay bir duruş beceremeyen d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/insanin-en-zor-isi-kendisini-bilmesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Çiçeklerim', 'benim-ciceklerim-engin-turk-u8bjg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimi şeker gibi, kimi ballıdır.

Kimisi sarıdır, kimi allıdır.

Hepsinde ayrı bir hüner vardır.

Benim çiçeklerim başka başkadır.

Kimi az gelişmiş, narin bir haldır.

Kimisi tombulca, kimi cılızdır.

Kimisi uzunca kimi kısadır.

Benim çiçeklerim başka başkadır.

Kimi rahat olur, kimi coşkundur.

Kimi atılgandır, kimi durgundur.

Kimi pek nazlıdır, kimi suskundur.

Benim çiçeklerim başka başkadır.

Çisem, Gizem, Ecem farklı farklıdır.

Nusret, Samet, Mehmet fazla rahattır.

Alihan, Batuhan, Oğuzhan, Can’dır.

Benim çiçeklerim başka başkadır.

Özge ile Sermin açmamış güldür.

Merve, Olcay Yonca Pek de süslüdür.

Ece, Zeynep ile çok uyumludur.

Benim çiçeklerim başka başkadır.

Mustafa Gökay’da hazine boldur.

Şahin durma öyle destini doldur.

İbrahim eğitim uzun bir yoldur.

Benim çiçeklerim başka başkadır.

Fırat deli akar, bentleri yıkar.

Elmas inci mercan gerdana takar.

Bilal’ın yazısı çoğunu yakar.

Benim çiçeklerim başka başkadır.

Helin sanki gelin, Ayşenur durgun.

Ebru ile Cansu birazcık yorgun.

Bartu hiç duramaz fazla atılgan.

Benim çiçeklerim başka başkadır.

Oktay çok has hastır, ince düşünür.

Ali, Fatih ile iyi geçinir.

Özgür Cem, Süleyman güzel görünür.

Benim çiçeklerim başka başkadır.

Buğra, Burak, Ömer hep mekik dokur.

Şiiri en güzel Anabel okur.

Perihan gururlu, Ezgi son olur.

Benim çiçeklerim başka başkadır

01062005', 'Kimi şeker gibi, kimi ballıdır. Kimisi sarıdır, kimi allıdır. Hepsinde ayrı bir hüner vardır. Benim çiçeklerim başka başkadır. Kimi az geliş...', ARRAY['Türk Edebiyatı','Şiir','Engin Türk']::text[], 8.5, '{"poet":"Engin Türk","poet_slug":"engin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/benim-ciceklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melekler ve Şeytanlar', 'melekler-ve-seytanlar-ahmet-turan-altunsu-x9e0r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '“Eceli gelen it cami duvarına işer…/ Türk Atasözü”

biliyorum ki bu sondur! 

önce, “kaldır” diyecekler,

sonra “güle güle! ”

yaşasın özgür yorumlar! ! ! 

anlatabilmek mi? .. nafile! 

var git sen sonuna yan, dur! 

vedamı parmaklar belirleyecekler…

ardımdan, sözcükler ağıtlar yakacak,

dizelerim kim bilir daha nerelerde,

nice şiirlerde öfkeyle gürleyecekler! 

şimdi sizden beklediğim, basit bir destur! ..

(avlaklar alabildiğine geniştir…

hazırlansın sahipler, şahitler…

dişlerimiz bir bir bileylenmiştir…

“heil Hitler! ..”

eyvah! .. neden zincirlerimiz bağlı? 

…………………..Hencher Dogle…)    

Sivridirler! Sivrileri sivriliklerinde mukîm…

Bir meleğin kafasına şeytan sokmaktır işleri…

Sanırlar ki “ Bu dünyâyı biz yarattık, biziz hâkîm! ”

Aldanmasın sakın dostlar; keskindir bütün dişleri…

İstisnalar kaideyi bozmaz: Sözüm han sözüdür,

Sivri dillerin sahibi hangi damın dansözüdür? ..

And olsun ki siz yazmadan hissettiğim önsezidir; 

Türklük mü, Müslümanlık mı? Riyâ bütün deyişleri…

Mahfiliniz hayır olsun: Kimleri kefil ettiniz,

Hünkârımın buyruğunu desturuyla ilettiniz? 

Yazık! Daha düne kadar varlığımla elittiniz; 

Ölen öldü, sağdır kalan; gömdünüz özleyişleri…

Hâlâ süt kokuyorsunuz: Adam olmak çok mu zor iş? 

Lira’ nın mı ufku büyük ki hedefinizdir kuruş? ..

Haritanızı çıkarttım dolaşarak karış karış; 

Şimdi artık av zamanı; hazırladım kayışları! ! ! 

14.11.2005 / Güdül / Ankara

Ahmet Turan Altunsu', '“Eceli gelen it cami duvarına işer…/ Türk Atasözü” biliyorum ki bu sondur!  önce, “kaldır” diyecekler, sonra “güle güle! ” yaşasın özgür yor...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/melekler-ve-seytanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '23 Nisan', '23-nisan-engin-turk-n1e2g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '23 Nisan''da açtı Büyük Meclisi.

Meclise oldu başkan Atatürk''ün kendisi.

Dedi: Kendin yönetir halkın kendi kendisi.

Bu millete yakışan en iyi demokrasi.

29 Ekim 2004', '23 Nisan''da açtı Büyük Meclisi. Meclise oldu başkan Atatürk''ün kendisi. Dedi: Kendin yönetir halkın kendi kendisi. Bu millete yakışan en iyi...', ARRAY['Türk Edebiyatı','Şiir','Engin Türk']::text[], 8.5, '{"poet":"Engin Türk","poet_slug":"engin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/23-nisan-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahverengi', 'kahverengi-dogan-i-nceman-dr1bu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gittin; 

Tadı kaldı gülüşünün 

Kahverengi. 

Bir düştün ki koynuma 

Akıp,tüm hücrelerime 

Kahverengi. 

Dalıp,gidiyorum boyuna… 

Bir lisede 

Düşmüştüm bu hastalığa 

Bir de şimdi, 

Kahverengi. 

Bakarsan ne yaşım uygun, 

Nede mevcut durumum. 

Peki bu kalbi ne yapmalıyım 

Kahverengi? 

Derler ya atsan atılmaz. 

Sonra niye satayım ki 

Kahverengi. 

Seni sevene ihanet eder miyim? 

Kasılıp duracağına 

Seni atıp,seni dolaşsın 

Kahverengi. 

Belki diye bir şey var hayatta, 

Bakarsın başucuma 

Geliveririsin usulca... 

Öyle değil mi? 

Kahverengi.', 'Gittin;  Tadı kaldı gülüşünün  Kahverengi.  Bir düştün ki koynuma  Akıp,tüm hücrelerime  Kahverengi.  Dalıp,gidiyorum boyuna…  Bir lisede  D...', ARRAY['Türk Edebiyatı','Şiir','Doğan İnceman']::text[], 8.5, '{"poet":"Doğan İnceman","poet_slug":"dogan-i-nceman","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kahverengi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönüllerde', 'gonullerde-gozem-basak-2pamd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Rüyalarda, gerçeklerde,

Bitmek bilmez ümitlerde,

Acı, tatlı hayallerde,

Yaşar aşklar gönüllerde.

Şarkı, şiir, anılarda,

Edilen tüm dualarda,

Saklı kalan duygularda,

Yaşar aşklar gönüllerde.

Niçin, neden bilinmezken,

Kimdir, nedir sorulmazken,

Sorulara yanıt bulunmazken,

Yaşar aşklar gönüllerde.

Geçer gider koca ömür,

Hatırlanan sanki dündür,

30 sene tek bir gündür,

Yaşar aşklar gönüllerde.', 'Rüyalarda, gerçeklerde, Bitmek bilmez ümitlerde, Acı, tatlı hayallerde, Yaşar aşklar gönüllerde. Şarkı, şiir, anılarda, Edilen tüm dualarda,...', ARRAY['Türk Edebiyatı','Şiir','Gözem Başak']::text[], 8.5, '{"poet":"Gözem Başak","poet_slug":"gozem-basak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gonullerde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız gel,geleceksen!', 'yalniz-gel-geleceksen-tekin-tayanc-cze61', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnız gel,geleceksen! 

Çırılçıplak bir gecenin koynunda

Tüm güzelliğinle…

Bırak kalsın gökyüzünde  yıldızlar 

Sen, kendi yıldızını al da gel. 

Sana hasret

Sana özlem gecelere

Sarılıp kalırken ben yokluğunda 

Sen, gündüzünü al da gel 

Dudaklarımda,

Yarım kalmış bir busenin sıcaklığı 

Yakarken gönlümü

Böyle anlarda güzeldir özlem

Ve sen  özlediğimde gel…

Yalnız gel,geleceksen! 

Sensizliğe 

Volta atarken yüreğim her gece 

Esmer bir yağmur pencereme… 

Sırılsıklam ıslanmış bir sonbahar günü

Hüznüne ağlarken gözlerim 

Hiç düşünmeden dönerken bana; 

Sen, yalnızlığını alda gel...', 'Yalnız gel,geleceksen!  Çırılçıplak bir gecenin koynunda Tüm güzelliğinle… Bırak kalsın gökyüzünde  yıldızlar  Sen, kendi yıldızını al da ge...', ARRAY['Türk Edebiyatı','Şiir','Tekin Tayanç']::text[], 8.5, '{"poet":"Tekin Tayanç","poet_slug":"tekin-tayanc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yalniz-gel-geleceksen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Kurşun', 'son-kursun-kadir-albayrak-l7hll', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tetik düşürmedin lakin dilinden

Çok darbe yemiştim ama son du bu

Öyle bir vurdun ki beni derinden

Silahından çıkan son kurşundu bu

Aldın bu bahtsızın aldın ahını

Gayrı kılıfına koy silahını

Affederdim belki her günahını

Anamı ağlatan son kurşundu bu

Sükut-u hayaldin ta baştan beri

Ağlama! .Ben sevmem ''yalan haberi''

Ne gözün ne gönlün sözünün eri

Dünyamı karartan son kurşundu bu

Yenildim gözlerin saltanatına

Yanağımda aşkın ifrazatına

Acı,dert,hüzün ne varsa, altına

İmzanı attığın son kurşundu bu

Vuracak neyin var? Ne kaldı sahi

Gayrı ya yalandır ya da mizahi

Bir gün hesabını sorar ilahi

Yılları yaktığın son kurşundu bu

Kadir-ce sevmenin işte bedeli

Susmadı silahın gittin gideli

Nihayet ardında ağlayan deli

Eyvah ki can verdi! Son kurşundu bu', 'Tetik düşürmedin lakin dilinden Çok darbe yemiştim ama son du bu Öyle bir vurdun ki beni derinden Silahından çıkan son kurşundu bu Aldın bu ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/son-kursun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmalıyım sevdiceğim seni', 'unutmaliyim-sevdicegim-seni-sinan-aydindag-65nhk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '03 Nisan 2005

Şimdi şu anda delirmek üzereyim

Kafamı şu duvara vurarak parçalamalıyım

Yok etmeliyim içindeki herşeyi

Belki o zaman seni unutabilirim

Çıkarabilirim beynimden seni

Herşeyini unutabilirim

Acını,tatlını,bana tattırdıklarını silebilirim

Sen beni bıraktın,

Ben seni bırakamadım...

Ne kadar istediysemde şu zavallı yüreğimden

Seni, seni söküp atamadım

Şimdi halim harap...

Her gece sen diye bir gölgenin peşinden gidiyorum

Gidiyorum da dünyayı tekrar başıma yıkıyorum

Ne gölgeyi yakalayabiliyorum nede sahibini

Bıktım, her defasında yeni bir yenilgi

Onun için kafamı duvara vurarak 

Parçalamalıyım bu beynimi

Unutmalıyım sevdiceğim unutmalıyım seni.', '03 Nisan 2005 Şimdi şu anda delirmek üzereyim Kafamı şu duvara vurarak parçalamalıyım Yok etmeliyim içindeki herşeyi Belki o zaman seni unut...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/unutmaliyim-sevdicegim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Anka Gibi...', 'bir-anka-gibi-i-brahim-nazim-ulker-jda7a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerin vardır...

Gözlerin öylesine mavi; 

Onlarda kaybolmuştur atlantis belki...

Saçların vardır saçların...

Nil onda saklıdır kimbilebilir ki? 

Sende bir muamma ben varım hissedemediğin,

Sende saklı bir ben...

Bende bir sen varsın ki bilemediğin,

Korkarsın içimde ki o devi görsen...

Seni her seferinde yitirip, bitirsem,

Seni her seferinde ateşe versem,

Bir anka gibi; 

Tekrar canlanırsın kendi küllerinden...', 'Gözlerin vardır... Gözlerin öylesine mavi;  Onlarda kaybolmuştur atlantis belki... Saçların vardır saçların... Nil onda saklıdır kimbilebili...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Nazım Ülker']::text[], 8.5, '{"poet":"İbrahim Nazım Ülker","poet_slug":"i-brahim-nazim-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-anka-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kireç Duvarlı Gecenin Kara Başlıklı Yüreği', 'kirec-duvarli-gecenin-kara-baslikli-yuregi-ali-aydogdu-vi21q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'içinde bir köpek dolaşıyor  zamanın

vakitsiz lâkin ayrıntılı yürüyorum 

zaman gece

gece sever yalnızlığı 

arı kovanının bir köşesinde 

köpeğin derdi yalnızlık 

yakınması anlaşılmasız 

biri zehirler 

biri it''eler 

yine  de vardır herkesin  serüveni 

ağacın kabuğunda kirli ismi 

duvarlara çizdiği egoist resmi 

 bebeğinin teninde rengi 

sevdiğinin içinde cismi 

köpeğinin  gözünde sahipliği

tek kalem değil ki dünyanın derdi 

ve köpeğin yalnızlığı  her dem başkaldırı 

yoktur mekânsızlığı

uzağından geçer insanlar 

oysa gururludurlar 

onlar ki; 

en mükemmeli yaratılmışlardan 

sen sokak köpeği,

keskinleştirme sesini 

gösterme dişlerini 

homurdanacaksan 

uzağından geçeni bekle 

korkmuyorum yalnızlıktan 

sen köpeğin sokağı 

geçicisin 

ya şimdi 

ya birazdan terkedecek seni 

yine öyle ıssız  kalacaksın 

pay çıkaracaksın sokak lambasının yarı aydınlığından 

sen çöp tenekesi 

hani körpeyken tekmelerdim seni 

ispatın güneşini çılgınlıkta arardım 

şimdi bir tekir kedi 

peşinde sokak köpeği 

şikayetçisin kömür dumanından 

sen kara benizlim

hatırlar mısın bu sokağı hızlı geçişimizi? 

kolumun altında ki güveni 

gördükçe köpeği tersimden yürümeyi 

ve çöpü tekmelediğin seneyi....

sol yanında kuduran efkârından 

sen mağrur  duruyorsun ya  sokak lambası 

sen de değiştin

bu kadar parlak değildin eskiden 

küçük sarı birşeydin 

ve daha seyrektin

boşa yanıyorsun durmadan 

ya sen gece 

hani toplamaya kalksan  herkesi bir araya diyorum 

süt kokan çocukları, elinde örgüsü kadınları 

bizim sümüklü ayşe''yi, sulu gözlü mustafa''yı 

şeker bayramını, kandil simidi kokularını 

kuytularda yeşeren sevdaları 

ispiyoncu rıza''yı

sarı kırmızı bayrağımı 

yarı final telaşımı 

kartopunu, kardan adamı 

kömür gözlü kadını 

ferdi''nin ağlamaklı sesini çarpan duvarlarına

toprak yolunun yağmur sevdasını 

gitarsız türkülerinin ruh okşamasını 

ve güneşin umut eşliğinde uyanışını 

balıkçı remzi''nin kükreyişini 

ya sen diyorum gece

neden korkuyorsun bu sorudan? 

bak köpeğine.......... 

çağır dolunayı 

vardır elbet bir öyküsü ümide dair 

ve yarınlar güzel olacak der gelişigüzel atılmış mecmuâ kaldırımında 

ya tutarsa bir çocuğun dileği? 

ya nasrettin boşuna çabalamadıysa ibret için 

ya acırsa bir despotun yüreği 

bir göçmen kuş vazgeçerse göçünden

orta yerine düşerse cansız 

 varsa bunun bir bedeli.......

yeniden çoğalmak için kapatırsak kara yürekli defteri

oynamadan sağlı sollu insanoğlu 

gün olur dövüşmeden sevişirse köpeğin 

vazgeçerse kartal ak güvercinin lezzetinden 

değiştirmekten vazgeçersek doğa denileni 

sen toprağından fışkıran yediverenleri gör o zaman 

deli dumruldan ötelerde  bir mekândır özveri 

................................uyumak değil bak gece olmanın tek bedeli

.................................................güneş ile birlikte doğanları düşün 

.....................o magandanın  kurşunu delecek olsada  avucumu 

............................................................................................ver elini', 'içinde bir köpek dolaşıyor  zamanın vakitsiz lâkin ayrıntılı yürüyorum  zaman gece gece sever yalnızlığı  arı kovanının bir köşesinde  köpeğ...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydoğdu']::text[], 8.5, '{"poet":"Ali Aydoğdu","poet_slug":"ali-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/kirec-duvarli-gecenin-kara-baslikli-yuregi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsterdim', 'i-sterdim-abdullah-gencay-f44ir', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İsterdim! 

Yıkmak ne varsa kökten, yeniden yapılmamak üzere

Kaçmak yıkıntılardan ve herşeyden uzaklara

Zamanı çevirmek senin yönüne

Ulaşmak senin zamanına, değiştirmeden rotayı

Birleşebilmek aynı noktada ayrılmamak üzere', 'İsterdim!  Yıkmak ne varsa kökten, yeniden yapılmamak üzere Kaçmak yıkıntılardan ve herşeyden uzaklara Zamanı çevirmek senin yönüne Ulaşmak ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gençay']::text[], 8.5, '{"poet":"Abdullah Gençay","poet_slug":"abdullah-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/isterdim-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi kahrolma vaktidir', 'simdi-kahrolma-vaktidir-sinan-aydindag-awai6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '03 Nisan 2005

Şimdi kahrolma vaktidir

Kahrolupta kaybolma vaktidir

Sen onca saat bekle gelsin diye

Tam kavuşmanın vakti geldiğinde

Bir telefonla satsın seni

Olacak iş mi? be

Bütün duygularını yıksın

Onca muhabbeti bir çırpıda yok saysın

Anlaşılan onun gözünde sen,

Değersiz bir varlıksın

Şimdi kaybolmanın zamanıdır

Kendi kabuğunda yalnızlıkla yaşama zamanıdır

Saklan,git,kaç ne yaparsan yap,

Kimse bulmasın seni

Bir tek yalnızlığını al yanına 

Bir tek ondan fayda var sana

yalnızlıgını al ve git

Sakın onu buralarda bırakma

haydi git ve mutlu olmaya çalış

Yanlızlığının ızdırabıyla.', '03 Nisan 2005 Şimdi kahrolma vaktidir Kahrolupta kaybolma vaktidir Sen onca saat bekle gelsin diye Tam kavuşmanın vakti geldiğinde Bir telef...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/simdi-kahrolma-vaktidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir Yazıyorum...', 'bir-siir-yaziyorum-i-brahim-nazim-ulker-zf498', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir şiir yazıyorum...

Dolunay dağın alnında,

Tekbir yıldız varken göğün ortasında.

Dağların etekleri yanıyorken ay ışığında...

Bir şiir yazıyorum.

Kasım''ın on altıncı akşamında...

Hayal edemiyorum seni.

Aklımdan gelip geçerken; 

Tutamıyorum gölgelerini.

Sesin varken kulaklarımda...

Bir şiir yazıyorum; 

Beklerken gelecek mektubunu,

Hediye bekleyen çocuklar gibi...

Daha bir heycanlanıyorum kapı çalındığında

Posta kutularını öyle arıyorum yüreğim dururcasına...

Bir şiir yazıyorum.

Ellerim tutarken ellerini,

Beni alırken gözlerinin derinliği,

Ruhumda buldum seni,

Öğrendim seninle görmeden yaşayabilmeyi...

Bir şiir yazıyorum,

Sadece duyarak sesini,

Hiç görmeden seni,

Hissederek...

Bir şiir yazıyorum.

Kasım''ın onaltıncı akşamında.

Haziran gibi...

Mektubunu beklerken,

Hediye bekleyen çocuklar gibi...

Bir şiir yazıyorum.

Senin sefilliğinde,

Bir şiir senin yoksulluğunda.

Fakirinim...

Bir şiir yazıyorum.

Bir ölüm sessizliğinde.

Odam sarı hüzün renginde,

Bir aşk oturmuş sesinde,

Bir aşk oturmuş yüreğime...

Bir şiir yazıyordum,

Şimdiyse bir şiir yazıyoruz!', 'Bir şiir yazıyorum... Dolunay dağın alnında, Tekbir yıldız varken göğün ortasında. Dağların etekleri yanıyorken ay ışığında... Bir şiir yazı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Nazım Ülker']::text[], 8.5, '{"poet":"İbrahim Nazım Ülker","poet_slug":"i-brahim-nazim-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bir-siir-yaziyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Önemi Var', 'ne-onemi-var-kadir-albayrak-zmzat', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Siz benim ömrümün sahibisiniz

Götürün yılları ne önemi var

Gönlümde savaşın galibisiniz

Canım size feda ne önemi var

Aldığım nefesin yarısı sizin

Kalbimin bal yapan arısı sizin

Baharın yeşili sarısı sizin

Hazan benim olsun ne önemi var

Ah gönlüm bu gönlüm saadet ister

Siz bana bir ümit lütfedin yeter

Olsa da yarınım bu günden beter

Sitem bile etmem ne önemi var', 'Siz benim ömrümün sahibisiniz Götürün yılları ne önemi var Gönlümde savaşın galibisiniz Canım size feda ne önemi var Aldığım nefesin yarısı ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-onemi-var-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhuma', 'ruhuma-abdullah-gencay-slepr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayrılmasan olmazmı yanımdan

Hiç    ama    hiç

Belki sorsam imkansız derdin

Ama    deme! 

Ruh bedenden ayrılırsa ölüm olurmuş

Ayrılma!', 'Ayrılmasan olmazmı yanımdan Hiç    ama    hiç Belki sorsam imkansız derdin Ama    deme!  Ruh bedenden ayrılırsa ölüm olurmuş Ayrılma!...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gençay']::text[], 8.5, '{"poet":"Abdullah Gençay","poet_slug":"abdullah-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ruhuma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorsunuz', 'biliyorsunuz-kadir-albayrak-r6abx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Alıştım hem de çok alıştım size

Sebebini siz de biliyorsunuz

O gece mehtapta sizle göz göze

Çılgınca seviştik biliyorsunuz

Yıldızlar nasıl da gülümsüyordu

Sıcacık bir buse verin diyordu

Sevdalar geceyi kucaklıyordu

Vuslata ermiştik biliyorsunuz

Başım göğsünüzde düşler kurarken

Bir dilek tutmuştuk yıldız kayarken

El ele tutuşup güneş doğarken

Biz yemin etmiştik biliyorsunuz', 'Alıştım hem de çok alıştım size Sebebini siz de biliyorsunuz O gece mehtapta sizle göz göze Çılgınca seviştik biliyorsunuz Yıldızlar nasıl d...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/biliyorsunuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sis', 'sis-abdullah-gencay-hvlu2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bazen,

Birisini sevmek

Ona karşı duyulan sevgi

Sis içinden çıkan, güzel bir manzaraya benzer

Farkında olmadan yavaş yavaş', 'Bazen, Birisini sevmek Ona karşı duyulan sevgi Sis içinden çıkan, güzel bir manzaraya benzer Farkında olmadan yavaş yavaş...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gençay']::text[], 8.5, '{"poet":"Abdullah Gençay","poet_slug":"abdullah-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sis-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Televizyon', 'televizyon-soner-kose-sh30a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonsuz bir cehennem...

Oldu aleme dem.

Küçük, siyah bir kutu.

Kötülüğü nerde, kuytu.

Aslını yok etmek için gelen,

İnan ki buydu.', 'Sonsuz bir cehennem... Oldu aleme dem. Küçük, siyah bir kutu. Kötülüğü nerde, kuytu. Aslını yok etmek için gelen, İnan ki buydu....', ARRAY['Türk Edebiyatı','Şiir','Soner Köse']::text[], 8.5, '{"poet":"Soner Köse","poet_slug":"soner-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/televizyon-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erik ağacı', 'erik-agaci-elazigli-mustafa-kaya-5yizi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'senin

yalnızlığının resmi,

bir bahçe

bir erik ağacı

ve köyün kuşları..

herkes uyurken 

ağlayışların,

kesilmeyen öksürüklerin

hasta oluşların

başını dayadığın bir yastığın

uyku tutmaz gecelerin

ve kimsesizlik hissi

gözünden damlayan

acıların..

ve,

senin 

yalnızlığının resmi

bahçemin kuşu

orada duruyordu

bir güz damlası gibi

bir aşığın kirpiği..

Mustafa kaya

18.11.2005 / İstanbul

www.mustafakaya.net', 'senin yalnızlığının resmi, bir bahçe bir erik ağacı ve köyün kuşları.. herkes uyurken  ağlayışların, kesilmeyen öksürüklerin hasta oluşların...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/erik-agaci-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düğünümüz Var', 'dugunumuz-var-necati-keceli-kh1kg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düğün yapmak adet, gelenek bize

  Damatlık Gelinlik giyildi bugün

  Hep beraber oynayalım diz, dize

  Çalsın davul Zurna düğünümüz var

  Mutlu yuva kurmak günün anlamı

  Bırakın dertleri, bırakın gamı

  Eğlenip coşmaktır düğün kavramı

  Oynasın güzeller düğünümüz var

  El ele tutarak yan, yana durun

  Haydi, gençler Çorum Halayı kurun

  Vurun davulcular, halayı vurun

  Çekelim halayı, düğünümüz var

  Kız anasının gözyaşın durulsun

  Gelinin beline kuşak sarılsın

  Halkalar oluşsun oyun kurulsun

  Çalsın davul Zurna düğünümüz var

  Bu gençlere nazar etmeyin sakın

  Damatla geline, kınalar yakın

  Haydi, damat gelin ortaya çıkın

  Eğlensin dostlarım düğünümüz var

  Necati KEÇELİ

  ADANA  18.11.2005', 'Düğün yapmak adet, gelenek bize   Damatlık Gelinlik giyildi bugün   Hep beraber oynayalım diz, dize   Çalsın davul Zurna düğünümüz var   Mut...', ARRAY['Türk Edebiyatı','Şiir','Necati Keçeli']::text[], 8.5, '{"poet":"Necati Keçeli","poet_slug":"necati-keceli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dugunumuz-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanç çeşmesi', 'utanc-cesmesi-elazigli-mustafa-kaya-b9okz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'uzaktaki sessizliğini

düşünüyorum

masum ve mukaddes dudakların

gülmeye kapalı sanki

ellerin mi..? bana küsmüş

gözlerin mi? 

yere çakılıp kalan

bir kuş gibiyim.

bakışlarımı,

yıldızlarla dolu göklere salıyorum

ve kalbim sana 

ne  kadar ağlıyor

bir utanç çeşmesi gibi..

Mustafa kaya

18.11.2005 / Sarayburnu

www.mustafakaya.net', 'uzaktaki sessizliğini düşünüyorum masum ve mukaddes dudakların gülmeye kapalı sanki ellerin mi..? bana küsmüş gözlerin mi?  yere çakılıp kal...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/utanc-cesmesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahşerim', 'mahserim-elazigli-mustafa-kaya-dm25u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mahşerim 

benim 

mahşerim 

hastane bahçesi 

ölüm gibi karanlık 

haldeyim 

uçmayı unutan 

bir kelebeğe döndüm 

bir düşünce alevindeyim 

gözümden 

uykularım kaçtı 

her gece 

bir gölge

yanıma uzanıyor 

ve 

ruhumun derinliklerine 

bir sevgi yayılıyor 

hayat dalım 

mehtabım 

sen yoksun 

herşey 

herkes 

karanlık kalıyor… 

Mustafa kaya

18.11.2005 / Haydarpaşa

www.mustafakaya.net', 'Mahşerim  benim  mahşerim  hastane bahçesi  ölüm gibi karanlık  haldeyim  uçmayı unutan  bir kelebeğe döndüm  bir düşünce alevindeyim  gözüm...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/mahserim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı bende', 'adi-bende-abdullah-gencay-dey10', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adını,

Bilmediğim adını, bir balığa verdim

Adı, bende kalsın olacak

Özlemini,

Gecelere sakladım

Yıldızlarla dertleşe bilmek için

Sevgini,

İçime ta derinlere attım

Parçalanmadan, eldeğmeden yaşayacak

Taki ben yok olana kadar', 'Adını, Bilmediğim adını, bir balığa verdim Adı, bende kalsın olacak Özlemini, Gecelere sakladım Yıldızlarla dertleşe bilmek için Sevgini, İç...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gençay']::text[], 8.5, '{"poet":"Abdullah Gençay","poet_slug":"abdullah-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/adi-bende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pencere', 'pencere-ceyhan-bektasoglu-z0zik', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'penceremden çocuklar geçiyor

kışla birlikte

sanki sıcak memleketlere göç eden arı kuşları gibi

arada sırada el sallıyor kimi

kimi ise hiç farketmiyor

sandalyemin üzerindeki anemonları

sana azıcık daha bekle diyorum 

anne bak

kuşlar geçti kaç zaman önce

yunuslar daha sonra

şimdi ise çocuklar

sana azıcık daha bekle diyorum

anne bak

çocuklar

penceremin önünden bazen

kış geçiyor

çocuklar gibi

sarsan hani

sarmak istesen

kocaman kollar ister senden

kaçmak istesen koşamazsın

böyle çocuklar

kaçak

kayıp

göçmen

size azıcık daha bekleyin diyorum

çocuklar

kışlar

daha pelerinimi geçirmedim hayatıma

daha güzel görünebilmek için

daha gücenmedim kimselere burdan ayrılırken

kalbini kırmadım

kristal kalpli bir fahişenin

size azıcık daha bekleyin diyorum 

çocuklar

daha tutamadım tüm dileklerimi

yapmak istediklerimi anlatamadım

bir daha ki kışa kadar', 'penceremden çocuklar geçiyor kışla birlikte sanki sıcak memleketlere göç eden arı kuşları gibi arada sırada el sallıyor kimi kimi ise hiç fa...', ARRAY['Türk Edebiyatı','Şiir','Ceyhan Bektaşoğlu']::text[], 8.5, '{"poet":"Ceyhan Bektaşoğlu","poet_slug":"ceyhan-bektasoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/pencere-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aradıkça Bulur,Buldukça Ararım', 'aradikca-bulur-buldukca-ararim-sener-ozdemir-vm7es', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her satırın arasında ararım

Bulamam da varır ötede ararım

Düştüğüm kuyuda ararım

Bulamam da varır ötede ararım

Suni yüzlerde ararım

Meleklere,perilere sorarım

Dağ,taş,ova,deniz gezerim

Bulamam da varır ötede ararım

Başımı eğer ararım

Kaldırır döner ararım

Özüme varır ararım

Bulamam da varır ötede ararım

Leyla’da ararım Mecnun’da ararım

Nihal’e uğrar Nafiz’e yanarım

Gider ‘çoban çeşmesi’ne sorarım

Bulamam da varır ötede ararım

Neyle Hakk’a yakarırım

Firaktan şikayet ederim

Feraha hasret, huzur dilerim

Aradıkça bulur,buldukça ararım…

(5 Kasım 2005 Cumartesi)', 'Her satırın arasında ararım Bulamam da varır ötede ararım Düştüğüm kuyuda ararım Bulamam da varır ötede ararım Suni yüzlerde ararım Melekler...', ARRAY['Türk Edebiyatı','Şiir','Şener Özdemir']::text[], 8.5, '{"poet":"Şener Özdemir","poet_slug":"sener-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aradikca-bulur-buldukca-ararim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle', 'seninle-rengin-alacaatli-isg63', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seninle bir şarkının sözlerinde buluşmayı özledim

Bir gitarın tınısındaki hüzünde ağlamayı

Omuzuna yaslanıp sadece seninle olmayı

Ve senin olduğumu bilerek sevilmeyi...

Seninle bir duanın tılsımında buluşmayı özledim

Bir yakarışın çığlığındaki çaresizlikte ağlamayı

Kollarına kendimi koyverip senin derinlerinde olmayı

Ve benim olduğunu bilerek sevişmeyi...', 'Seninle bir şarkının sözlerinde buluşmayı özledim Bir gitarın tınısındaki hüzünde ağlamayı Omuzuna yaslanıp sadece seninle olmayı Ve senin o...', ARRAY['Türk Edebiyatı','Şiir','Rengin Alacaatlı']::text[], 8.5, '{"poet":"Rengin Alacaatlı","poet_slug":"rengin-alacaatli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seninle-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-abdullah-gencay-02tvm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sonu ne olursa olsun

Siyah, beyaz veya renkli

En usta ressamda bile  Kötü

Ayrılığın resmi

Sözleri kim yazarsa yazsın

Müziği kim çalarsa çalsın

En usta yorumcu da bile  Kötü

Ayrılığın türküsü

Yaşanmış yada hayal olan

Geçmişteki  veya gelecekteki

En iyi yazarın kaleminde bile  Kötü

Ayrılığın hikayesi', 'Sonu ne olursa olsun Siyah, beyaz veya renkli En usta ressamda bile  Kötü Ayrılığın resmi Sözleri kim yazarsa yazsın Müziği kim çalarsa çals...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gençay']::text[], 8.5, '{"poet":"Abdullah Gençay","poet_slug":"abdullah-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayrilik-308-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklı Kent', 'sakli-kent-umur-orkmez-elhn3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saklı bi kent gibiydin içimde..

Gözlerin düşünce gözlerime

yeşerdi tüm Kuraklarım..

Sana ait şimdi tüm coğrafyam,Anayurdum,Başkentim..

Büründüm senin için tüm güzelliğimi,

ne kadar yaralı olsa da toprağım..

Bilirdin aslında beni,sezerdin ya da sana olan düşlerimi..

Ama ben bilemedim..

Bilemediğim; neden yasaktın bana,

neden ellerin ellerime dökülemiyordu,

oturamıyordu gözlerim gözbebeklerine? 

Bilemedim,yüreğin yüreğimde atsın mıydı istediğin? 

Ama eğer aramak istersen benliğimi,

olmak isterse yüreğin yüreğimde,bulamazsan ama; 

bil ki ben sende kaybolduğum yerdeyim..', 'Saklı bi kent gibiydin içimde.. Gözlerin düşünce gözlerime yeşerdi tüm Kuraklarım.. Sana ait şimdi tüm coğrafyam,Anayurdum,Başkentim.. Bürün...', ARRAY['Türk Edebiyatı','Şiir','Umur Örkmez']::text[], 8.5, '{"poet":"Umur Örkmez","poet_slug":"umur-orkmez","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sakli-kent-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiire Saklanan Aşk', 'siire-saklanan-ask-mehmet-ozcelebi-iuey1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimseye söyleyemedi 

Söyleyemezlerdi...

Ne O nede Aşkı

Sadece O ve Aşkı bilsin diye duygularını 

Adam Yazdı Yazdı Yazdı

Fakat saklayamadı

Bilmemeliydi kimse

Sadece O ve Aşkı

Yırtmak zorundaydı duygu dolu sayfaları

Silinmesin

 Hatırlansın

  Unutulmasın diye duyguları

Buraya

Tam buraya

 Şiire Sakladı', 'Kimseye söyleyemedi  Söyleyemezlerdi... Ne O nede Aşkı Sadece O ve Aşkı bilsin diye duygularını  Adam Yazdı Yazdı Yazdı Fakat saklayamadı Bi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özçelebi']::text[], 8.5, '{"poet":"Mehmet Özçelebi","poet_slug":"mehmet-ozcelebi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/siire-saklanan-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişman değilim', 'pisman-degilim-abdullah-gencay-5h21s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen! 

Hayalim ve imkansızım

Biliyorum,  yaşananlar yanlış

Ama! 

Hislerim samimi ve gerçek

Ben pişman değilim

Sen! 

Kopartılmamış tomurcuk gül

Ben! 

Uzanıpta tutamayan bir çif el

Unutamadığım rüyam

Çözemediğim bulmacamsın

Yinede pişman değilim', 'Sen!  Hayalim ve imkansızım Biliyorum,  yaşananlar yanlış Ama!  Hislerim samimi ve gerçek Ben pişman değilim Sen!  Kopartılmamış tomurcuk gü...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gençay']::text[], 8.5, '{"poet":"Abdullah Gençay","poet_slug":"abdullah-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/pisman-degilim-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapımın önünden', 'kapimin-onunden-ayhan-ulusoy-z82bf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir sokak geçiyor 

Kapımın önünden

Bir sessiz serçe bakışıyla

süzüyorum

Islak ve sıcak yalnızlığı

Ben her neye baksam

gözlerine dokunup geçiyorum

Sen yanan gözlerinle

Sokağa bakıyorsun

Yaralı bir kuş gibi

tutunuyorum bakışına

Orda kalsaydım

kimseye bakmasaydım..

Bir deniz geçiyor 

kapımın önünden

Uslanmadığım bir o..

sesini duyduğum 

Kalakaldığım

Oysa içinde 

bir kum tanesi 

olmaya  razıydım..

Bir sen geçiyorsun 

Kapımın önünden

İçeri buyur etsem

bir kahvemi içsen..

İşte bu,yüreğim desem

Ne varsa bende kalan

ne düştüğüm har ateşi

ne ilk gençliğimin bitişi

ne varsa duymadığın

ne varsa....

             

Bir sen geçiyorsun

Kapımın önünden

Gözucuyla bile

bakmadan içeri...', 'Bir sokak geçiyor  Kapımın önünden Bir sessiz serçe bakışıyla süzüyorum Islak ve sıcak yalnızlığı Ben her neye baksam gözlerine dokunup geçi...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Ulusoy']::text[], 8.5, '{"poet":"Ayhan Ulusoy","poet_slug":"ayhan-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kapimin-onunden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emanet', 'emanet-abdullah-gencay-ylbfq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğime attığın emanet sevdan

Söndü,  fakat hala sıcak

İnan ki hep sıcak kalacak

Çok narin emanet olarak

Karaladığın kağıdı

Silmek kadar kolay olsaydın

Düşünmeden parçalardım

Nefretin, sürsün! 

Ben taşırım emanetini

Bir gün,

Senden önce ölürsem

Al, emanet sevdanı

Ama, hemen alma sakın! 

Bedenim de yok olana kadar söz ver

Kalsın emanetin', 'Yüreğime attığın emanet sevdan Söndü,  fakat hala sıcak İnan ki hep sıcak kalacak Çok narin emanet olarak Karaladığın kağıdı Silmek kadar ko...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gençay']::text[], 8.5, '{"poet":"Abdullah Gençay","poet_slug":"abdullah-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/emanet-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyı', 'kiyi-ayhan-ulusoy-vgy3f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kıyı

Bu gecesi ışımayan gün

hangi seviyi çaldı

Ben kimdim? 

Hangi aşkı kiminle yitirdim? 

Nereye yattım

Adresi olmayan

       nerde uyandım? 

O deniz kıyısında

Beklediğim sen miydin? 

Kim sevdi; 

O denizi,o balığı

ağacı,tarlayı

kumu, ateşi

senin yerine kim sevdi? 

Yüreğimin atışı

Yüzümün ateşi

ol diye bekledim,

         gelmedin...', 'Kıyı Bu gecesi ışımayan gün hangi seviyi çaldı Ben kimdim?  Hangi aşkı kiminle yitirdim?  Nereye yattım Adresi olmayan        nerde uyandım?...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Ulusoy']::text[], 8.5, '{"poet":"Ayhan Ulusoy","poet_slug":"ayhan-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kiyi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Hey Gidi Gençlik*', 'hey-gidi-genclik-ramazan-ates-9y7gh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilmezsiniz belki siz,

Ben eskiden avcıydım.

Aslan falan avlardım,

Kurtlar ile oynardım.

Ayı benden korkardı,

Kaplan aklın şaşardı.

Panterler av köpeğim,

Çakal emir erimdi.

Korku nedir bilmezdim,

Hiç elim boş dönmezdim.

Avladığım filleri,

Karıncaya yüklerdim.

Keklikler tek sırada,

Hepsi beni beklerdi,

Tavşanlarsa el ele,

Bizde gelelim derdi.

Bazen bir kaç geyiği,

Koyardım ben torbama,

Tuz yerine ördeği,

Katardım ben çorbama.

Agustosda kar yağdı,

Yine nefsim kabardı.

Kapıverdim tüfeği,

Giydim delik çizmeyi.

Tüfeğim bir tahtadan,

Mermilerim bakladan,

Delik çizmem su aldı,

Karlar beni boyladı.

Birden bir gürültü duydum,

Hemen mevziyi kurdum.

Baktım ki fare gelen,

Korkudan ölüyordum.

Fare düştü peşime,

Dedi avda işin ne? 

Tabanları yağladım,

Hiç arkama bakmadım.

Bir solukta evdeydim,

Hey gidi gençlik dedim.

Bakın laf aramızda,

Eski bendim aslında,

Hep aynıydım aslında.

Ramazan Ateş/Enschede-25.03.1998', 'Bilmezsiniz belki siz, Ben eskiden avcıydım. Aslan falan avlardım, Kurtlar ile oynardım. Ayı benden korkardı, Kaplan aklın şaşardı. Panterle...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/hey-gidi-genclik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakışır', 'yakisir-ayhan-ulusoy-2gxup', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yakışır

          Şimdi buradan geçti

          rüzgarın biri

          yüzüne dokundu

          sonra eline

          Çenendeydi elin

          Bir güzel baktın ki

          Kim görse nefesi sıkışır

          Bir el bir yüze

          Bu kadar mı yakışır?', 'Yakışır           Şimdi buradan geçti           rüzgarın biri           yüzüne dokundu           sonra eline           Çenendeydi elin      ...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Ulusoy']::text[], 8.5, '{"poet":"Ayhan Ulusoy","poet_slug":"ayhan-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yakisir-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunda', 'yoklugunda-abdullah-gencay-yvqkh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her tarafım insan dolu

Ben yalnızım yokluğunda

Gece tek başına kalmış

Çaresiz yıldızım

Kendisini dahi ışıtamayan

Körelen duyguların anahtarı

Sendeymiş 

Açtın kapıları birer birer

Senden sonra kapatamadım

Leylayı sildim, yok artık

Mecnun dağıldı paramparca

Her şey yüzeysel, sıradan

İnan ki senin yokluğunda', 'Her tarafım insan dolu Ben yalnızım yokluğunda Gece tek başına kalmış Çaresiz yıldızım Kendisini dahi ışıtamayan Körelen duyguların anahtarı...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gençay']::text[], 8.5, '{"poet":"Abdullah Gençay","poet_slug":"abdullah-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yoklugunda-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgunum', 'yorgunum-abdullah-gencay-6jzfp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Susmuşken gecenin ortasında herşey

Donarım sensizliğin soğuğunda

Düşünürüm geçmiş zamanı

Dalarım karanlığa  izin almadan

Takip ederim aheste çekilen küreklerle

Gecenin içindeki sessizlği

Zaman zaman buğulanır gözlerim

Titrek, ürkek yüreğime inat

Geleceksin diye haber gelir yaz rüzgarından

Yorgunum, kırılır kolum kanadım

Yeniden sarmak değil, görmektir amacım

Sen, sende kalsın

Dokunma bende kalanı alma sakın', 'Susmuşken gecenin ortasında herşey Donarım sensizliğin soğuğunda Düşünürüm geçmiş zamanı Dalarım karanlığa  izin almadan Takip ederim aheste...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gençay']::text[], 8.5, '{"poet":"Abdullah Gençay","poet_slug":"abdullah-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yorgunum-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-abdulvahap-ates-tuutc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Divit sana kanadı,

Hep sana yandı kalem.

Sesini yankıladı,

Senle bezeli alem.

Cıvadradaki direk,

Sana çırpınan yürek,

İnanan diz çökerek,

Hep seni arzuladı.

Boduçta boğulan su,

Çatlaklara dolan su,

Yeşertip yoğalan su,

Semana tütsülendi.

Dağlar yivli bir desen,

Rüzgar yivlerde esen,

Her zerrede hendesen,

İsmini sayıkladı.

Orda döndü rahmete,

Zerreye merhamete,

Her oluş emanete,

Hep seni muştuladı.', 'Divit sana kanadı, Hep sana yandı kalem. Sesini yankıladı, Senle bezeli alem. Cıvadradaki direk, Sana çırpınan yürek, İnanan diz çökerek, He...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Ateş']::text[], 8.5, '{"poet":"Abdulvahap Ateş","poet_slug":"abdulvahap-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-680-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Çeyrek', 'ceyrek-gul-ozan-ov1zd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çeyrek asır 

sürüklenen

bir

ihtimalsin

.

.

.

Artık

gerçekleşme zamanın

gelsin!', 'Çeyrek asır  sürüklenen bir ihtimalsin . . . Artık gerçekleşme zamanın gelsin!...', ARRAY['Türk Edebiyatı','Şiir','Gül Ozan']::text[], 8.5, '{"poet":"Gül Ozan","poet_slug":"gul-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ceyrek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Candide, Oblomov, İsa ve Polyanna Üzerine Bi Deneme', 'candide-oblomov-i-sa-ve-polyanna-uzerine-bi-deneme-mehme-arslan-fpyth', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hala candide''im sana

kalbimi ne kadar kırıp parçalasan da

oblomov''um yitip giden

aşkımın karşısında

isa''yım, tokat atsan

öbür yanağımı dönerim sana

bırakıp beni çekip gitsen

polyanna

17/11/2005', 'hala candide''im sana kalbimi ne kadar kırıp parçalasan da oblomov''um yitip giden aşkımın karşısında isa''yım, tokat atsan öbür yanağımı döner...', ARRAY['Türk Edebiyatı','Şiir','Mehme Arslan']::text[], 8.5, '{"poet":"Mehme Arslan","poet_slug":"mehme-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/candide-oblomov-isa-ve-polyanna-uzerine-bi-deneme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yirmi Yıl Önce', 'yirmi-yil-once-kadir-albayrak-5de3v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sokakları dolaştım yağmur gibi sessizce

Hiç bir şey değişmemiş sanki yirmi yıl önce

Hani ilaçtı zaman diyordun ki tek çare

Bu gönlüm bu sokaklar hala yirmi yıl önce

Yine gözlerimden yaş akıyor yavaş yavaş

Gönlümde aynı telaş sanki yirmi yıl önce

Yıllarda körükledi içimde ki yangını

Kokun hasret salgını hala yirmi yıl önce

Kapanmış perdelerin belli burda değilsin

Sen yine ellerinsin tıpkı yirmi yıl önce

Gözlerim ağlamaklı dolaştım sokakları

Burada başlamıştı her şey yirmi yıl önce', 'Sokakları dolaştım yağmur gibi sessizce Hiç bir şey değişmemiş sanki yirmi yıl önce Hani ilaçtı zaman diyordun ki tek çare Bu gönlüm bu soka...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yirmi-yil-once-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'D ü ş m ü y d ü n', 'd-u-s-m-u-y-d-u-n-birsen-ates-ckpej', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yürüyorsun ruhuma doğru 

yeniden 

aşktan öldüm mü bilemedim

kaldım hayallerin kıyısında

unutturacak belki

yaşanırsa  zaman

bilmediğim duygular sarıyor

senden geriye kalan

yüreğime dolan sar beni 

sıcaklığında 



donuk gülüşüm üşütüyor güneşi

işlemiş içime soğuk yokluğun

gecede kasım sensiz

ben gibi öksüz yüreğim

düş müydün 

gece dönünce güne 

siliniyor gerçek değilsin

yaşattığım seni

seni istiyorum

bilmediğim duygular sarıyor

senden geriye kalan

yüreğime dolan sar beni 

sıcaklığında', 'yürüyorsun ruhuma doğru  yeniden  aşktan öldüm mü bilemedim kaldım hayallerin kıyısında unutturacak belki yaşanırsa  zaman bilmediğim duygul...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/d-u-s-m-u-y-d-u-n-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anasını Satayım', 'anasini-satayim-kadir-albayrak-ycjtt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Olmadı be olmadı olması kabil değil

Uyku bile çalmadı şu kapımı yatayım

Bir ''zor'' deyişi var ki dayanmak mümkün değil

Duymak kolay olmadı anasını satayım

İşte aşk dedikleri yolu çöle düşecek

Sevdaya varmak için ham ne varsa pişecek

Akıl! ..Ama rakibi yürekle dövüşecek

Vurupta yıkamadı anasını satayım

Sevgi dediğin kalmış Yunus dilinde mahpus

Kalan ağlayadursun gülmek gidene mahsus

Unutmak var unutmak! ..Önemliydi bu husus

Gönül başaramadı anasını satayım

Gayrı sitem sermaye gam yüklü gecelerin

Sen aşkı anlat şair! Yaldızlı hecelerin

Diz boyu çaresizlik yazdığın vecizlerin

Birini okumadı anasını satayım

Kalp kalbe karşı deyip kim söylemiş bu lafı

Sevenin kalbi kalpte taş mı öte tarafı

Ne menem şey şu gönül sanki altın sarrafı

Ayar tutturamadı anasını satayım

Ah aşk! .Sana aşk olsun! Sen çarpı koy hanene

İşte bir enkaz daha eklendi harabene

Bu yüreğim ki senin her yalan bahanene

İnandı, anlamadı anasını satayım

Şimdi ''zor'' diyor çok zor! sevda zoru doğurur

Barikatsız bir yolda sevdalar mı yoğrulur

Devrilirken bedenim sandım bir gün doğrulur

Ayağa kalkamadı anasını satayım

Üç vardiya yetmedi ömür tükendi lakin

Kudurmuştu dalgalar şimdi nasıl da sakin

Tebessüm etmek vardı! Vardı amma velakin

Yüzüme yakışmadı anasını satayım', 'Olmadı be olmadı olması kabil değil Uyku bile çalmadı şu kapımı yatayım Bir ''zor'' deyişi var ki dayanmak mümkün değil Duymak kolay olmadı an...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/anasini-satayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Garip', 'cok-garip-kadir-albayrak-o6d9g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana inanmak mı? İstedim ama

Bende sorun yokta gönlüm muzdarip

Sevmekten kastı ne? Bilmedim ama

Bunu senden duymak, duymak çok garip

Bir yanım ''he'' dese bir yanım karşı

Öyle korkmuşum ki kaplamış arşı

Az mı aramıştım ben çarşı çarşı

Onu sende bulmak, bulmak çok garip

Yılların yükü var yükü yılların

Tozunu yutmuşum toprak yolların

Benim için düş-tü saran kolların

Bunu senden ummak, ummak çok garip

Mevsimde sen bahar yaz mı bıraktın

Ardında sen beni az mı bıraktın

Vuslata duyacak haz mı bıraktın

Onu sana sunmak, sunmak çok garip

Ben sevdim! Derim! Sen söyleyemezsin

Bu aşkın hakkını ödeyemezsin

Gayrı inanmamı bekleyemezsin

Sana böyle vurmak vurmak çok garip

Sen beni sevme be! .. Hiç zahmet etme

Bana vurdun yeter! Aşka zulmetme

Ben seni affetmem! Sende affetme

Artık senle olmak, olmak çok garip', 'Sana inanmak mı? İstedim ama Bende sorun yokta gönlüm muzdarip Sevmekten kastı ne? Bilmedim ama Bunu senden duymak, duymak çok garip Bir yan...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cok-garip-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Yine Seveceğim', 'seni-yine-sevecegim-emin-akduman-wi6zu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyor! 

Biliyor musun? heryağmur yağdığında.. 

Hiç yaşamadığımız, yaşayamadığımız günlerin öfkesiyle 

İçimde buruk bir hüzün dolaşıyor... 

Seninle şu yağmurda ıslanmak isterdim şimdi... 

Caddelerde yürümedik yanyana. 

Şöyle içimizden geldiğince ağlamak göklerle birlikte.. 

Yâ da çılgın âşıklar gibi koşup eğlenmek. 

Seninle zaten neyi yaşadık ki biz,? 

Hep sen ve ben olduk uzak diyarlarda.. 

Özlenen,acı çeken.. 

Zamana kızdık neden geç kaldın diye! 

Bize hep yasaktı aşk! 

Şöyle hesapsızca, 

Başını koyupta göğsüme, yüzümde uyumadı yüzün. 

Özgürlüğü alınmış bakışlarla, 

Gözlerimle hep gizlice buluşurdu gözün. 

Ah! Sevgili Mavi... 

Uzaklarda çok uzaklarda içimi kavuruyor özlemin. 

Şu an pencereme vuran yağmurla birlikte 

Hüzünler yağsada yüreğime.. 

Söndürmüyor içimi yakan yokluğunu.. 

Hani ellerimdeyken ellerin 

Göğsün nasılda yüreğine dar gelmişti... 

Ve benim boğazıma bir yumruk gibi takılıp kalmıştı, nefesim. 

Sıcaktın, sımsıcak. 

Varsın ıslatmasın yağmur bizi... 

Varsın caddelerde başka sevgililer gezsin el ele 

Seninle yan yana ıslanmasak ta 

Bu aşk bizim yüreğimizi zaten ıslatmıyor mu? 

Onun için yağmura aldırma sen bitanem! ... 

Yağmurun olmadığı günlerde seni nasıl sevdimse.. 

Senin olmadığın yağmurlu günlerde, 

SENİ YİNE SEVECEĞİM.

