INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paradoks', 'paradoks-guler-ilgaz-tzu60', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Merhaba bebeğim

Ben de yeniden doğdum

Sen bende doğduğunda

Ben de yeniden baktım

Sen bana baktığında

Ben ilk kez korktum

Senle ben parmak uçlarımızda

Birbirimize dokunduğumuzda

Benle sen öyle içiçe

Dokunmanın ötesine geçtiğimizde

Dokuduk niyetimizi birlikte', 'Merhaba bebeğim Ben de yeniden doğdum Sen bende doğduğunda Ben de yeniden baktım Sen bana baktığında Ben ilk kez korktum Senle ben parmak uç...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/paradoks-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ş i i r', 's-i-i-r-hikmet-elitas-zo9mm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayatıma şekil vermiş,

Nizamım, yolumdur şiir.

Beni sarmalamış sarmış

Ayağım elimdir şiir.

Kirpiğimde yaşım olur

Suyum olur, aşım olur

Kırk senelik eşim olur

Hanemde gülümdür şiir.

Anadilimdir, Türkçedir

Hakikattir ve hakçadır

Mehmetbey''ce dir, mertçedir

Lisanım, dilimdir şiir.

Şu serimde duman duman

Tüter durur demem aman

Yaşamaktır çoğu zaman

Bazı gün ölümdür şiir! ..

Sanki alınyazım gibi

Ekmeğimde tuzum gibi

Oğlum gibi, kızım gibi

Peteğim, balımdır şiir.

Hikmetî söz pazarına

Borç kılınmış üzerime

Yazılmazsa mezarıma

En büyük zulümdür şiir.

Uyanış Gazetesi-14.09.2004', 'Hayatıma şekil vermiş, Nizamım, yolumdur şiir. Beni sarmalamış sarmış Ayağım elimdir şiir. Kirpiğimde yaşım olur Suyum olur, aşım olur Kırk ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Elitaş']::text[], 8.5, '{"poet":"Hikmet Elitaş","poet_slug":"hikmet-elitas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/s-i-i-r-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıra Sende', 'sira-sende-kadir-albayrak-jqyq5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Arındım kirlerden pislikten bu gün

Yıkayıp kefene sardılar beni

''Gelecek başına'' dediler bu gün

Musalla taşına koydular beni

Daracık bir tabut hareketsizim

Nimetim kesilmiş hem nefessizim

Hayattaymış gibi yine sessizim

''Nasıldır'' diyerek sordular beni

Bir sela okunda yanık ses ile

Cemeat toplandı şaşkınlık ile

Kıbleye dönüldü bir tekbir ile

''Akılda tutarak'' yordular beni

Yükseldim omuzda arş-ı ala-ya

Dualar yükseldi kul-dan Mevla''ya

Ne gerek vardı sahte yaşlara

''Sen yoktun'' melekler kovdular beni

Bir çukur açılmış bir tümsek toprak

Tabutun üstünden açıldı kapak

Çevreye göz attım yılışık kaypak

Bir kara dehlize soktular beni

Bir acele ile kürekler kalktı

Topraklar üstüme kudurdu aktı

Bu kadar telaşa ne gerek vardı

Çivileyip yere çaktılar beni

Sen niye gelmedin? Yollar mı uzak

Üzdü mü gönlünü kurduğun tuzak

Yüzün mü kalmadı bana bakacak

Utanmaz gözlerin yaktılar beni

Bir kalbi durdurup zül-e varışın

Kahpelik yükünü ziynet takışın

Gözümün önüne geldi bakışın

Mezarın içinde güldürdü beni

Kirlerin yok artık duygularımda

Nihayet pisliğin kaldı bak,  sana

''ŞİMDİ SIRA ONDA'' dediler bana

Sevinçten deliye döndürdü beni', 'Arındım kirlerden pislikten bu gün Yıkayıp kefene sardılar beni ''Gelecek başına'' dediler bu gün Musalla taşına koydular beni Daracık bir tab...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sira-sende-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dümeni Kilitlenmiş Gemi...', 'dumeni-kilitlenmis-gemi-ulvi-ziya-l6jwt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kim görmüş ki; ufka duman salan,bu geminin gittiğini...

Kim görmüş taş yüreklilerin mâsumları eğittiğini...

Aydınlar,güvenlik kuvvetleri ve toplum ayrı tellerde; 

Hangi düşman eder bu milletin kendisine ettiğini? ...

Biri yapar,diğeri bozar,isyancı duygular hep azar...

Zorbaların elindeki kalem çok tuhaf şeyleri yazar...

Buluşmak imkânsız gibidir; îmânın,ilmin ışığında,

Zıt kuvvetler çıldırmışçasına öz canına kuyu kazar...

Anayasa üst raftadır,korkunç birileri ön saftadır...

Siste,pusta kaybolmuş bir gemi; bilmem kaç gün,kaç haftadır...

Kaptan eski kaptan değil,gidip hayâletlere karışmış; 

Bunalmış yolcular şiddetten,yaşamaları insaftadır...

Toplum:enerji kaynağı; insan hakları:rota; hareket...

Bunlar aynı istikamette seyrederse,olur bereket...

Birtakım şuursuzlar acep neden birbirinden ayırır? ...

Bu ne gaflet uykusudur ey millet,bu ne yanlış siyâset? ...', 'Kim görmüş ki; ufka duman salan,bu geminin gittiğini... Kim görmüş taş yüreklilerin mâsumları eğittiğini... Aydınlar,güvenlik kuvvetleri ve ...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dumeni-kilitlenmis-gemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaderin Kendi Elinde', 'kaderin-kendi-elinde-vedat-koparan-b920x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'masallar dinlenirdi yıldız düşlerde 

yaşanılan alnına yazılı bir tarih değildi

söylenirdi sahipli sahipsiz türkülerde

kuşlar yaralı, boynu bükük  kırık sesleri

ay kayıp yakamozlu vurgun gecelerde

çocukluğu çalınmış ağıtlarda dinlenirdi

sarı sevinçleri buruk kalandı gamzelerinde

sen büyüdün mü çocuk annen büyüdün desede sana

arar mısın eski zaman sevinçlerini /güneş ardı saklanmalarında

kaç cinayetin vurgunudur / vurulmuşluğun/ vurduğunda

bir sevdaya tutulmuşluğunda/ sevgidir açan /yüreğin kilitli sanduka

açar bir yüzünde Fırat bir yüzünde Dicle

kırıktır gülüşlerin ay doğarken gamzende 

yalancı sevgilerdir büyüttüğün kendinde

yok artık avunmak teselli kalır geçmişte

Vedat Koparan 13.11.2005', 'masallar dinlenirdi yıldız düşlerde  yaşanılan alnına yazılı bir tarih değildi söylenirdi sahipli sahipsiz türkülerde kuşlar yaralı, boynu b...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kaderin-kendi-elinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadına Dair', 'kadina-dair-adem-tok-wse01', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'senin avuçlarından içiyor suyu  toprak

senin gözlerinden alıyor gün ışığını

çekme gögüslerini doymadı henüz vatan

alma karanfil kokulu dağlardan bakışlarını

tebessümleri kırılır

düşerse bakışların yana

toplar pılını-pırtını yol alır şafaktan önce

hayat veren o eşsiz kaynak yabana

senin sol yanından batıp sol yanından doğuyor

karanlığın tek katili

senin damarlarından besleniyor

emeğin kudreti

örtme sol yanını

tıkama damarlarını

geçte olsa merak etme

sevi bulur arkadaşını...

                                                            (01.03.03) 

                                                            f tipi hapishane TEKİRDAĞ', 'senin avuçlarından içiyor suyu  toprak senin gözlerinden alıyor gün ışığını çekme gögüslerini doymadı henüz vatan alma karanfil kokulu dağla...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kadina-dair-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Turnam', 'gitme-turnam-murat-akbas-1iunb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gitme turnam.

Yollar çamurdur.

Sular bulanıktır.

Havalar toz dumandır.

Gitme turnam.

İnsanlar bozuktur.', 'Gitme turnam. Yollar çamurdur. Sular bulanıktır. Havalar toz dumandır. Gitme turnam. İnsanlar bozuktur....', ARRAY['Türk Edebiyatı','Şiir','Murat Akbaş']::text[], 8.5, '{"poet":"Murat Akbaş","poet_slug":"murat-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gitme-turnam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha İleri', 'daha-i-leri-adem-tok-v4xxk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seviyorum seni

seviyorum dediğim gibi

soluk alıp vermekten daha ileri...

                                                               (24.05.03) 

                                                             f tipi hapishane TEKİRDAĞ', 'seviyorum seni seviyorum dediğim gibi soluk alıp vermekten daha ileri...                                                                (24....', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/daha-ileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasım Dalları', 'kasim-dallari-vedat-koparan-9h6xg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'zaman sudaki sırdan sağarken kendini 

sarı sevinçler yerine hüzünde

bu günde Seni dinledim 

sağanak yağmurun sesinde

gözlerim bir öğlen dinlencesinde

yapıştı uçuşan kısık bakışlarım 

hazan rüzgarının eteğine

özlemin ne halde gel gör seni bende

yokluğun yakıcılığında ne derin ne derince

sendeki ben kadar yağmurlar gönderdim 

sen de hissedip dinledin mi sesinde

içime oturmuş senli bir ağrı 

bir sağanak ki yıkasın bizi bizde 

silinsin bulutların isi 

alsın götürsün gök denizce

eski bir siyah beyaz film karesinde 

savruluyor gözlerimde bir sen 

yunsun kirini döksün bizi bize 

ah nasıl bir salınım bu böyle 

döktün dağlarca seni içime

gün verdin yine hüznü gözlerime 

kasım dalları eğdi boynunu

ayak sesinde

-Ay  Dolun Gecenin Gözlerinde, Işığa Yürüyüşte

Gözlerin Ki Ay Dolun Gecede,Benliğim Sevginle-

Vedat Koparan 17.11.2005', 'zaman sudaki sırdan sağarken kendini  sarı sevinçler yerine hüzünde bu günde Seni dinledim  sağanak yağmurun sesinde gözlerim bir öğlen dinl...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kasim-dallari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kusura Bakma', 'kusura-bakma-kadir-albayrak-d5meg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben sana hakkımı helal etmiştim

Bu gece vazgeçtim kusura bakma

Tanrıya şikayet etmem demiştim

Çok büyük laf ettim kusura bakma

Dilimde beddua çıktı bu gece

İsmini sitemle andım bu gece

Allah-a elimi açtım bu gece

Yalvardım, affetme! . Kusura bakma

Gözlerin nemine kader demiştim

Suçunu gizledim kusura bakma

Düşünmem diyerek yemin etmiştim

Kefaret ödedim kusura bakma

Gönlümü bir hicran sardı bu gece

İsyanım sözüme çattı bu gece

Yanağımdan yaşlar aktı bu gece

Yalvardım affetme! .. Kusura bakma

Boş bulunup sana mutlu ol dedim

Hakkın yok diyorum kusura bakma

Dillerim kurusun ben tövbe ettim

İçime sinmedi kusura bakma', 'Ben sana hakkımı helal etmiştim Bu gece vazgeçtim kusura bakma Tanrıya şikayet etmem demiştim Çok büyük laf ettim kusura bakma Dilimde beddu...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kusura-bakma-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eleştirmen', 'elestirmen-kadir-albayrak-4ss17', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adam''a mesleğini sordum

''Eleştirmen'' buyurdu! ..

Eğer ''adam'' olsaydı,

Doğru dürüs işi olurdu! ...', 'Adam''a mesleğini sordum ''Eleştirmen'' buyurdu! .. Eğer ''adam'' olsaydı, Doğru dürüs işi olurdu! ......', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/elestirmen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Şehit', 'ey-sehit-mehmet-postalli-ia2vb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Al bayrağa sarılıp gidiyorsun ey şehit

Din için, Millet için, Vatan için can verdin

Tabutunu taşıyan bütün melekler şahit

Sen yaptın görevini, güzel imtihan verdin

Türk’ü hor görenleri cephelerde yanılttın

Kalleş düşmanlarına kimliğini tanıttın

Şanlı tarihimize altın bir sayfa kattın

İmanlı sinelere coşku, heyecan verdin

Kahramanca çarpıştın, baş eğmedin namerde

Mezarına, semadan nur iner perde perde

Sayende, nazlı bayrak dalgalanır göklerde

Ay-yıldızla süslenmiş eşsiz bir vatan verdin

Peygamber müjdesine mazhar oldun Mehmedim

Öldü diyorlar ama, sen aslında ölmedin

Kanınla suladığın toprağa gömülmedin

Cennet karşılığında canını kurban verdin

Şehit asker yazıyor şimdi mezar taşında

Annen, baban gururla duruyorlar başında

Aslanım rahat uyu, milyonlar var peşinde

Yüreklendirdin bizi, güç verdin derman verdin

Toprağa Bir Can Düştü isimli kitabımdan alınmıştır ve bu kitap Gündüz Yayınevi tarafından çıkartılmıştır.

www.gunduzkitabevi.com.tr', 'Al bayrağa sarılıp gidiyorsun ey şehit Din için, Millet için, Vatan için can verdin Tabutunu taşıyan bütün melekler şahit Sen yaptın görevin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ey-sehit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doruklarda', 'doruklarda-vedat-koparan-jhhnt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-Yansın Aşkla Zaman Yarılsın Dalgalarda Kiraz Dudaklar Gecenin Duldasından Günü Kopar.-

daral gelir yükle yükümüze sessiz bir ırmak gibi ak, su çiçekleri gezinsin üzerinde

kaçak zaman kuşlarıyız nasılsa, susarım susuşlarda sinirler boşalır damarlar çatlar

sal gitsin yelkenler fora aldırma  onca fırtınaya, ılıman rüzgarlar essin anlara

şehvetin doruklarında yapışır gerilimle dudaklarına harında kanar yoksun zaman 

 

ondan aldığımız enerji ve güçleyiz güneş tam tepemizde, sımsıcak

ışıltılarıyla görkeminde.

sen bir adasın ben bir deniz atlas bir çarşaf gibi salındım parıltılı kıyılarına, geziyorum okşarcasına yalayarak kayalarını, folklorik bir sesle dalgalar dolanarak etrafında bir gün aydınlığı öpücü kondurmakta.

ağaçlar saçların gibi mis kokularıyla,dallar rüzgarda hareket ediyor kollarını anımsatırcasına son yapraklar uçuşurken hazan sarısı bir hüzünle baharı beklemek üzere,ağaçların gövdesi  gecenin renginde, denizden çıkan bir deniz kızı güzelliğinde Afrodit’le özdeşte, denize  akseden gölgen suyun yüzeyinde  kıvrıntılarla yakamoz parıltılarında, şehvete davet eden çırılçıplak bir kadın gibi..ada ve sen birde deniz..

adada yeni bir gün gibi adeta canlı bir heykel duruyor huşu içinde,kayaların göğsü kabaran geceyi yaran bir halde ve  lahitlerde  bir yazıt can buluyor.

dalgalar kıyılarına her varışta, birbirine akan bir iç deniz gibi birbirini tamlayan,vurdukça gün kopartıyor dudaklarını geceden, adanın çıkıntısı dudakların sanki,rengini gün kızıllığından alan bir yarma gül gibi,girmiş denizin içine, burnu yarım ay sanki tüm ihtişamıyla aslan ağzı çiçekleri gibi duruyor  yarma gül  dudakları dalgaların kabarıp içlerinde gezindikçe …

venüs ne sıcak ne yakıcı her dokunuşta dağılıyor kozmik kromozomlar,tepelerin estetik birer heykel abidesi doğanın şekillendirişinde,işlenmeyi bekleyen çok kıratlık  bir zümrüt çıkıntılar ne kadar cazip oval güzelliğinde…

psikolojik-gerilimli  bir film şehveti doruklarda izlercesine bir romana başlar gibi macerası içdenizlerinde derin bir gelgit  beklenmede kan kızılı demini almayı bekleyen bir çay tavında zaman.

-Sen Bana Geldin Geleli Dinmez İçimin Senli Sesi.-

gecenin saçlarına yapışmalı,yelesi bir yılkı atı olmalı 

an harasından boşalan bir doru atı gibi, şaha kalkmalı 

derin denizler kabarırken,volkanlar patlayıp boşalmalı

sen bana ben sana,en yalın en uçkun halimizle akmalı

ak pınarlar dağların oyuklarından, nehirlere çağlamalı

ten buluşunca tende yanmalı, öpüşlerden gün uyanmalı 

Vedat Koparan 12.11.2005', '-Yansın Aşkla Zaman Yarılsın Dalgalarda Kiraz Dudaklar Gecenin Duldasından Günü Kopar.- daral gelir yükle yükümüze sessiz bir ırmak gibi ak,...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/doruklarda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamadım Der Gibi', 'yasamadim-der-gibi-murat-akbas-7u4rn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İtiraflarla dolu bir hayat

Akıp gitti önümden,

Hep arkasından baktım.

Bir kuş gibi uçamazken; 

Sularda buldum kendimi...

Korkumdan açılamadım.

Sığ denizlere, derinlere

Bildik sularda, koylarda yüzdüm.

Yaşamak denen bu deryada; 

Yaşamadım der gibi....', 'İtiraflarla dolu bir hayat Akıp gitti önümden, Hep arkasından baktım. Bir kuş gibi uçamazken;  Sularda buldum kendimi... Korkumdan açılamadı...', ARRAY['Türk Edebiyatı','Şiir','Murat Akbaş']::text[], 8.5, '{"poet":"Murat Akbaş","poet_slug":"murat-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yasamadim-der-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalem Kırıldı', 'kalem-kirildi-kadir-albayrak-78uee', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalem kırıldı gülüm, 

Silginin gözü aydın

Bana sensizdi ölüm,

Sana bensiz ''Günaydın! ''', 'Kalem kırıldı gülüm,  Silginin gözü aydın Bana sensizdi ölüm, Sana bensiz ''Günaydın! ''...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kalem-kirildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Denilen Meçhul...', 'i-nsan-denilen-mechul-ulvi-ziya-7480d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimi Haccâc-ı Zâlim gibi zulmeder,gönüller yıkar...

Kimi Neron misâli yangın çıkarıp bir şehri yakar...

Kimi de toplumda sessiz bir nûr ırmağı gibi akar...

Hepsinin hammaddesi aynı ve üflenen nefes aynı; 

İnsan var şeytana göz kırpar,insan var RAHMAN''a bakar...', 'Kimi Haccâc-ı Zâlim gibi zulmeder,gönüller yıkar... Kimi Neron misâli yangın çıkarıp bir şehri yakar... Kimi de toplumda sessiz bir nûr ırma...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/insan-denilen-mechul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçek', 'cicek-fatma-karakoyun-qncxg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin adın ne çiçek bilmiyorum 

Belki mevsimsiz açtığın için 

Kim bilir belki açmazsın çiçek 

Açmazsan ne olacak 

Özendim sevenlere bırakıp gidenlere 

Yapamadım çiçek bir sen kaldın aklımda 

Senin adın ne çiçek bilmiyorum 

Aşkla açtın aramı neden bilmiyorum 

Senin adın ne çiçek 

Bir sen kaldın aklımda 

04.10.2005', 'Senin adın ne çiçek bilmiyorum  Belki mevsimsiz açtığın için  Kim bilir belki açmazsın çiçek  Açmazsan ne olacak  Özendim sevenlere bırakıp ...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cicek-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Epiktotes''in Emri', 'epiktotes-in-emri-mehmet-akif-tiryaki-bjdt5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artık açıldı kalemim,

Başladım şiirlerimi damardan zerk etmeye,

Güncel sıkıntılarımı da terk etmeye

Yazdıkça yazıyorum aldım zamanı esir,

Kimbilir sizede ediyorumdur bazen tesir.

Anılarım içimden fırlıyor, çıkıyor, haykırıyor:

-''Homo homini dipus''

Biz burada yokuz.

Seviyoruz insanları Remarque  öğretti,

Bir ressamın tablosuna bakar gibi

Sevgiyle bakacaksın Epiktotes''in emri

''Seveceksen topraktan bir vazo sev,

Kırılırsa üzülmezsin'' dedi

O, topal filozof bana,

Bunları neden anlatıyorum ki sana.

Sen zaten biliyorsun bunları,

Ben hatırlıyorum eski anılarımı.

Artık açıldı kalemim yazıyorum,

Aklımdan geçenleri defterime kazıyorum.

Sevgisiz kalanlara kızıyorum.', 'Artık açıldı kalemim, Başladım şiirlerimi damardan zerk etmeye, Güncel sıkıntılarımı da terk etmeye Yazdıkça yazıyorum aldım zamanı esir, Ki...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/epiktotes-in-emri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar', 'daglar-murat-akbas-ifal0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dağlar, dağlar 

Yüreğimi dağlar

Gözlerimi bağlar

Dağlar, dağlar

Taş duvarları örter

Giyinirde çimen bağlar.

Çıksa şu yücelere; 

Baksa enginlere; 

Bir koy verse kendini...

Sevdiğine uçar mısın...? ...', 'Dağlar, dağlar  Yüreğimi dağlar Gözlerimi bağlar Dağlar, dağlar Taş duvarları örter Giyinirde çimen bağlar. Çıksa şu yücelere;  Baksa enginl...', ARRAY['Türk Edebiyatı','Şiir','Murat Akbaş']::text[], 8.5, '{"poet":"Murat Akbaş","poet_slug":"murat-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/daglar-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle', 'soyle-fatma-karakoyun-lf9uu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Acıyorum sensizlik içinde geçen yıllarıma 

Söyle neden geç geldin 

Bunca ayrılıklardan sonra söyle ne verdin

Geceler boyu beklediğim duamdın

Söyle neden geç geldin

Sevmiyorum sensiz olacak sabahları

Senin gözlerinde doğar güneş

Ben sılayı sende yaşadım

Söyle neden geç geldin

İlk defa seviyorum başkasını

İlk defa bu kadar tedirgin değilim

Seni beklerken öğrendim

Sensiz olamayacağımı

Söyle neden geç geldin

         Fatma KARAKOYUN

                      11.10.2005', 'Acıyorum sensizlik içinde geçen yıllarıma  Söyle neden geç geldin  Bunca ayrılıklardan sonra söyle ne verdin Geceler boyu beklediğim duamdın...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/soyle-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutunma', 'tutunma-adem-tok-kmdu9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-bugunlerde eksiğimiz:

çocuksu yanımız-

kaderim değil

kuyudan seyretmek aydınlığı

tutsaklığım:

o gürül gürül akan yabancılığın aslında

(karartılmamış gecelerde) 

dönüşüm var -yanmadı gemiler-

dönmüyorum! 

küllerinden doğar o

adı ankadır

düşüncemden doğan ben insan 

ağarsın girilmeyen yollar

özgürlüğü uçuruyorum

yangın olur hep asi

enkazından bir çift kanat havalanan

tutunun

birlikte çıkalım

bırakıp giysilerimizi

bakmadan arkaya

yapraklarımda yanık kokusu

dizelerim savruluyor

veda etmeden yaralarıma

gelecek birgün gelecekle

tanıyorum kendimi

ELVEDA DEMEDİM! ..

                                                       (14.05.04) 

                                                     f tipi hapishane EDİRNE', '-bugunlerde eksiğimiz: çocuksu yanımız- kaderim değil kuyudan seyretmek aydınlığı tutsaklığım: o gürül gürül akan yabancılığın aslında (kara...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/tutunma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On Kasım', 'on-kasim-fatma-karakoyun-xwu54', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'On kasım olmasın öğretmenim

Gelmesin on kasım

Atatürk’üm ölmesin öğretmenim

Ölmesin Atatürk’üm

Bak yavrum Atatürk ölmez

Dinle yavrum

Rüzgarın sesi

Türk öğün çalış güven

Atatürk ne der yavrum

‘Türk çocukları ecdadını tanıdıkça daha büyük işler yapacaktır.

Medeniyet ufkunda yeni bir güneş gibi parlayacak ve tarih sayfalarına yine

Türk adı ile yazacaktır.’

Batıl arkadaşlar uzaktan el eder

Vaktimiz dar çocuklar

Toplandınız mı Baş başa verdiniz mi 

Atatürk ölmez çocuklar

Bakın etrafınıza

Her çocukta bir Atatürk dirilir çocuklar

Sakın unutmayın çocuklar Atatürk ülkesinde 

Ölmeden önce yüce divan kurulur

Belki çıkacağız yine savaşa

Bilin ki sizi öpmek için Mustafa kemal yolda

                  Fatma KARAKOYUN 

                                  01.11.2005', 'On kasım olmasın öğretmenim Gelmesin on kasım Atatürk’üm ölmesin öğretmenim Ölmesin Atatürk’üm Bak yavrum Atatürk ölmez Dinle yavrum Rüzgarı...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/on-kasim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Hâle Geldi Dünyâ...', 'ne-h-le-geldi-duny-ulvi-ziya-s42gh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kokuşmuş bir bataklık sanki uzanır önümüzde...

Nûrlu,uğurlu istikâmet bulunmaz yönümüzde...

Havâ bozuk,su bozuk,bunalım geçirmekte rûhlar; 

Huzmeler bile,kirlenerek yol alır günümüzde...', 'Kokuşmuş bir bataklık sanki uzanır önümüzde... Nûrlu,uğurlu istikâmet bulunmaz yönümüzde... Havâ bozuk,su bozuk,bunalım geçirmekte rûhlar;  ...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ne-hale-geldi-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçim', 'i-cim-murat-akbas-siqg0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçim içime sığmıyor.

Kalbim coşmakta; 

Akmakta şelaleler...

Sevinç yaşlarım dinmiyor.

Okyonuslar dolmakta...', 'İçim içime sığmıyor. Kalbim coşmakta;  Akmakta şelaleler... Sevinç yaşlarım dinmiyor. Okyonuslar dolmakta......', ARRAY['Türk Edebiyatı','Şiir','Murat Akbaş']::text[], 8.5, '{"poet":"Murat Akbaş","poet_slug":"murat-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/icim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Yeni Doğan Bebek', 'her-yeni-dogan-bebek-mehmet-akif-tiryaki-s958j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllar,

Aylar,

Günler,

Saatler,

Dakikalar,

Saniyeler geçiyor,

Bitti dediğimizde herşey

Yeniden başlıyor.

Hayat başlıyor, bitiyor.

Her yeni doğan bebek Allah''ın 

Dünyadan umut kesmediğini belirtiyor.

Güneş doğuyor batıyor,

Hayat başlıyor bitiyor.

Sevgiler bitmiyor....', 'Yıllar, Aylar, Günler, Saatler, Dakikalar, Saniyeler geçiyor, Bitti dediğimizde herşey Yeniden başlıyor. Hayat başlıyor, bitiyor. Her yeni d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/her-yeni-dogan-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçime Dert Oldun', 'i-cime-dert-oldun-murat-akbas-kdf9k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzun zaman oldu.

Öfkeler yumak oldu.

İçime dert oldu.

Suskunluğum hep bundan

İsyan ettim suskunluğuma; 

Gözlerine bakacağım yerde...

Karanlıklara baktım.

İçime dert oldu.

Hem de çıkmamacasına....', 'Uzun zaman oldu. Öfkeler yumak oldu. İçime dert oldu. Suskunluğum hep bundan İsyan ettim suskunluğuma;  Gözlerine bakacağım yerde... Karanlı...', ARRAY['Türk Edebiyatı','Şiir','Murat Akbaş']::text[], 8.5, '{"poet":"Murat Akbaş","poet_slug":"murat-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/icime-dert-oldun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atam', 'atam-fatma-karakoyun-j609r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nerde bir mavi deniz görsem

Gözleri gelir aklıma 

Işığım olur karanlıklara

Yobazların cahillerin ayakları 

Ankara’ya ulaşamaz	

Emanetine hıyanet edenler yaşamaz

İnsanlığa barış getirdin

Evrenselliğe önem verdin

Kalpağının altında mavi gözlerin gülüyor 

Bıraktığın emanetin seninle ilerliyor

Nerde bir mavi deniz görsem

Gözleri gelir aklıma 

Işığım olur karanlıklara

Öyle yücesin ki

Seni anlatmaya kelimeler yetmez ATAM

                      Fatma  KARAKOYUN

                                             27.10.2005', 'Nerde bir mavi deniz görsem Gözleri gelir aklıma  Işığım olur karanlıklara Yobazların cahillerin ayakları  Ankara’ya ulaşamaz	 Emanetine hıy...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/atam-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Bende ki Ben Nerde', 'o-bende-ki-ben-nerde-kadir-albayrak-o6wmd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nerde çocukluğumun pas değmemiş düşleri

Karanlığa nur veren ezan seslerim nerde

Saçlarım da meleğin gezen şefkat elleri

Gerdanın da tesbihim seccadelerim nerde

Nerde o ayetlerden yükselen huzurlu ses

İman dolu gönlüme ördüğüm çelik kafes

Hicap ile tövbede Rab-bi zikreden nefes

Arş-tan arz-a dökülen konfetilerim nerde

Nerde ey adem oğlu yürekte ki berraklık

Nerde gönül köşkümde hüküm süren sultanlık

Fidanken sevgi idi büyüyünce düşmanlık

O günahsız bedenim masumiyetim nerde

Nerde büyük vecd ile tevhide dönen dilim

Başucumda ki Kur-an sırılsıklam gözlerim

Bu necis bataklık ne söyleyin ben nerdeyim

Kadrini bilmediğim gül bahçelerim nerde

Nerde ana kucağım tüten baba ocağım

Secde edip öptüğüm o kıblem namazgahım

Eteğine kirlerin değmediği yıllarım

Başıma taç ettiğim kar tanelerim nerde

Nerde gerçek olan ben bende ki ben ben değil

Kul idik Yaradana kula kulluk hoş değil

Nedamettir süzülen gözlerimden yaş değil

Sonsuz iştiyak ile mürtekiplerim nerde', 'Nerde çocukluğumun pas değmemiş düşleri Karanlığa nur veren ezan seslerim nerde Saçlarım da meleğin gezen şefkat elleri Gerdanın da tesbihim...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/o-bende-ki-ben-nerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz olmuyor', 'sensiz-olmuyor-nadire-gulcicek-oc0o7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yok,olmaz böyle çekip gitmek arkadaş.

Sevenler.dostlar bırakılmaz ne yazda.ne kışta

Sen seven yüreklere ışık tutan, 

Gönüllerde med cezir olan

Sen  Pamuk yürek

Dostluklarda  sevdalarda

Vurgun yemiş yaralanmış yüreklede

Zaman zaman yağmur oldun şiirlerinle

zaman zaman ilaç gibi sardın sözlerinde

Sen Pamuk yürek duy sevenlerini

Bekliyor sevenlerin dostların seni

Tıpkı içimizi ısıtan güneş gibi

Bekliyoruz eski günlerdeki gibi

Sen dost canlısı sen arkadaş sevgili YAHYA PAMUK! ! ! 

Bekliyoruz bekliyeceğiz unutma sevenlerini….', 'Yok,olmaz böyle çekip gitmek arkadaş. Sevenler.dostlar bırakılmaz ne yazda.ne kışta Sen seven yüreklere ışık tutan,  Gönüllerde med cezir ol...', ARRAY['Türk Edebiyatı','Şiir','Nadire Gülçiçek']::text[], 8.5, '{"poet":"Nadire Gülçiçek","poet_slug":"nadire-gulcicek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sensiz-olmuyor-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tanem', 'bir-tanem-murat-akbas-cc6mj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Göz yaşları anlatamaz.

İçimdeki isyanı...

Yanımda olmanı isterdim.

Anılarda değil...

Sensiz geçen günlere nispet.

Dolu dolu seni içerim.

Doymamacasına...

Bir tanem...', 'Göz yaşları anlatamaz. İçimdeki isyanı... Yanımda olmanı isterdim. Anılarda değil... Sensiz geçen günlere nispet. Dolu dolu seni içerim. Doy...', ARRAY['Türk Edebiyatı','Şiir','Murat Akbaş']::text[], 8.5, '{"poet":"Murat Akbaş","poet_slug":"murat-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-tanem-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hacılar', 'hacilar-mehmet-postalli-5njbh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hak nasip eyledi düştünüz yola

Kazasız, belasız varın hacılar

Mevla nasip etsin haccı her kula

Mekke’de ihrama girin hacılar

Mavi semalarda kuş gibi uçun

Kibirden, gururdan, gıybetten kaçın

Lebbeyk diyerek elleri açın

Arafat’ta bir an durun hacılar

Sefa ile Merve arası koşun

Zemzemi içerek aşk ile coşun

Mübarek beldede yare  kavuşun

Dünyada murada erin hacılar

Hak rızası için kesin kurbanı

Günahlar dökülür, düşerken kanı

Medine’de yatan Yüce Sultanı

Gezdiği yerlerden sorun hacılar

Bir selamda benden söylen Resule

Perişan halimi getirin dile

Yüzü aya benzer, kokusu güle

Muhabbet gülünü derin hacılar

Gözümde tütüyor mukaddes Kâbe

Habibin aşkından gönlüm harabe

Onulmaz hislerim, yıkık kitabe

Yaralı gönlümü sarın hacılar

Sevgiliden haber verin hacılar', 'Hak nasip eyledi düştünüz yola Kazasız, belasız varın hacılar Mevla nasip etsin haccı her kula Mekke’de ihrama girin hacılar Mavi semalarda ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hacilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram', 'bayram-fatma-karakoyun-xh52a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dostluğu arkadaşlığı sevgiyi anlat

İlkbaharda çiçeklerin açışını anlat

Yüreğin deki damla damla umutları anlat

Bugün bayram bayramın kutlu olsun

Bayramlar yaşamlarımızın bize verdiği armağan

Güzellik beraberlik insanlık kokan

Ekmeğimizi suyumuzu paylaştığımız 

Bugün bayram bayramın kutlu olsun

Eskileri yaşatan bir gülücük

Mistik hava yaşat bugün

Öyle içten öyle samimi bizleri birleştir bugün

Bugün bayram bayramın kutlu olsun

Sevgi ve saygıyı perçinle bugün

İlkbaharda çiçeklerin açışını anlat

Sevdiklerimiz yanımızda umutlarımız çok olsun 

Bugün bayram bayramın kutlu olsun

                  Fatma KARAKOYUN

                                               02.11.2005', 'Dostluğu arkadaşlığı sevgiyi anlat İlkbaharda çiçeklerin açışını anlat Yüreğin deki damla damla umutları anlat Bugün bayram bayramın kutlu o...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bayram-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senle Geçen O Günlerimi', 'senle-gecen-o-gunlerimi-murat-akbas-lxhb2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gökyüzünde bulutlar

Yağmur olup düşer.

Senden çıkan her sitem

Sihirli ok olur.

Senden bana koşar

Yüreğime saplanır.

Gelde çıkar çıkarabilirsen.

Senle geçen günlerimi....', 'Gökyüzünde bulutlar Yağmur olup düşer. Senden çıkan her sitem Sihirli ok olur. Senden bana koşar Yüreğime saplanır. Gelde çıkar çıkarabilirs...', ARRAY['Türk Edebiyatı','Şiir','Murat Akbaş']::text[], 8.5, '{"poet":"Murat Akbaş","poet_slug":"murat-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/senle-gecen-o-gunlerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esmer Karanfil', 'esmer-karanfil-adem-tok-qqjsq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-gitsem bir fırtına kopar dalından

kalsam çöl sessizliği-

kandırmam beni

seni duymayacağım:

toprağıma ekilince sen

dünü getirince dudaklarında

bana seninleyken anlat

sesin ulaşıyorken yırtıp jiletli telleri

sızıp demirden

duvardan

anlarım ayaktayım

konuş...

sen benden ne istersin

sevgi sözcüğümü; 

bir,bin,her gün...

afişe boğarım bu kenti

bakışının düştüğü her yerde

bir kalp görürsün (AÇAN) 

konuşan (BİR KALP) 

bakışının düştüğü her yer sarsılır

beni görürsün...

                                                                   (22.10.04) 

                                                                   f tipi hapishane EDİRNE', '-gitsem bir fırtına kopar dalından kalsam çöl sessizliği- kandırmam beni seni duymayacağım: toprağıma ekilince sen dünü getirince dudakların...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/esmer-karanfil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-fatma-karakoyun-dashy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özlem duyarda ararsan bil ki buradayım

Özlem nedir ben senleyken bile sensizim

Sorma sakın sorma özlem nedir

Söyletme sakın özlemin ne olduğunu bana

Sesini duyamadım sesimi duyamadın

Nefes bile alınmaz sensizlik ve bensizlikte

Sensiz geçen her saniyede canımı acıtıyor

Yollar bitmek bilmiyor

Zaman geçmek bilmiyor

Nedenini bilmediğim bu arzuyu

Bugün her zamankinden daha çok istedim yanımda olmanı

Seviyormuş özlüyormuş yalan 

Var mı sevgisinin arkasında duran

Ne zaman göstereceksin asıl yüzünü

Ne pahasına olursa olsun sözünde durmak özlemi yok etmektir sevgi………………

                                                                                                   05.11.2005', 'Özlem duyarda ararsan bil ki buradayım Özlem nedir ben senleyken bile sensizim Sorma sakın sorma özlem nedir Söyletme sakın özlemin ne olduğ...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozlem-278-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınım', 'kadinim-kadir-albayrak-m1hvd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayat denen bu yolu

Ben çoktan yarıladım

Hazan yerleşmişti gönül bahçeme

Ve ''SENİ TANIDIM KADINIM''

Şafak oldun sabah oldun

Hayal oldun serap oldun

Eğilmiştim solmuş çiçek misali

Baharım oldun kadınım! ..

Köklerim kucakladı toprağı

Saçılıverdim yediveren misali

İşte dedim denizim, işte benim dağlarım

Yürek diye içimde 

Sen atarsın kadınım

Elimde kalemsin duygu yüklü

Kağıdım da şiir

Nefessin solukladığım

Ve... Düşlerimde sen varsın kadınım

Göğün yedi rengi gibi

Saçını okşadığım

Gönül zindanlarımda

Sır diye sakladığım

Gecenin bir vaktinde

''Can'' diye aradığım

Çok sevmişim seni,

Çok sevmişim kadınım', 'Hayat denen bu yolu Ben çoktan yarıladım Hazan yerleşmişti gönül bahçeme Ve ''SENİ TANIDIM KADINIM'' Şafak oldun sabah oldun Hayal oldun serap...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kadinim-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve O Bir Yazar', 've-o-bir-yazar-mehmet-akif-tiryaki-s2q9t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eskilerden güzel bir yazar tanıyorum,

Onu her gün salı hariç anıyorum.

Öğreneceğim o kadar çok şey varki ondan

Anlattıkça anlatıyor, esirgemiyor okurlarından.

Bir de ençok sevdiği Köyceğiz''ini düşürmez dilinden

Pek de çabuk özler uçakla devamlı gidip geldiğinden.

Göztepe''yi dilinden hiç düşürmez,

Hayattan bıktığı hiç görülmez.

En önemli tenbihi aklımdan hiç çıkmaz,

-''Enseyi karartmayın''

Dertlerinizi de hiç yabana atmayın.

Artık bildiniz o yazarımızı değilmi? 

Bize güç verir fıkraları, nesirleri,

Onunla hergün buluşmak ne büyük hazdır,

Türkiye''mde artık böylesi azdır.

Fikirlerin beni ilgilendirmiyor,

Lakin edebiyatın....bana ''gel gel'' diyor.

Teşekkür ederim tüm yazıların için zatına

Çok şey öğrettin vatandaşlarına ve de bana.

Yaşa sağlıcakla çocuklarınla,

Çetin Altan saygımız edebiyatına ve sana.', 'Eskilerden güzel bir yazar tanıyorum, Onu her gün salı hariç anıyorum. Öğreneceğim o kadar çok şey varki ondan Anlattıkça anlatıyor, esirgem...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ve-o-bir-yazar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamana Karşı', 'zamana-karsi-fatma-karakoyun-n13uq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonradan söylemek boşuna 

Söyleyeceksen başında 

Konuş konuşabildiğince

Özgür bırak düşüncelerini

Kelimeler anlatmalı seni

Sanki otantik bir tatil yeri

Anlat sadeliğini

Olmasın lüksün yeri 

Doğal olmalı sevgi………

              Fatma Karakoyun

                                7.11.2005', 'Sonradan söylemek boşuna  Söyleyeceksen başında  Konuş konuşabildiğince Özgür bırak düşüncelerini Kelimeler anlatmalı seni Sanki otantik bir...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zamana-karsi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ani ve Derin', 'ani-ve-derin-murat-akbas-4ym6q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senden bana; 

Hiçbir şey kalmadı.

Konuşmalar yok artık.

Sevinçler, öfkeler

Hele yok mu o gülüşler...

Masum ve şehvetli öpücükler...

Ani ve derin dokunuşlar...

Dalgın bir o kadarda içten bakışlar..

Sonra iç çekişler.

Sanki bir daha yaşanmayacak gibi...

Göz kapaklarından süzülen damlacıklar...

Usulca uzaklara akar, akar, akar da,

Sanki yaşanmamış gibi...', 'Senden bana;  Hiçbir şey kalmadı. Konuşmalar yok artık. Sevinçler, öfkeler Hele yok mu o gülüşler... Masum ve şehvetli öpücükler... Ani ve d...', ARRAY['Türk Edebiyatı','Şiir','Murat Akbaş']::text[], 8.5, '{"poet":"Murat Akbaş","poet_slug":"murat-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ani-ve-derin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-fatma-karakoyun-zm1n3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiç bir şey sonsuza dek sürmez

Bütün mevsimleri bir günde

Bütün yılları bu mevsimde yaşamaya razıyım senle,

Gözlerin sözlerini anlatıyor baktığımda

Uykudan uyandığımda uyanmak istemediğim olur

Ağır bir duygu bu taşıyamaz bunu gece

Titriyorum üşümüyorum

Seni unutmak istedim yapamadım 

Titriyorum üşümüyorum

Ne dünden az ne yarından daha çok titriyorum..

                               Fatma KARAKOYUN

                                                             8.11.2005', 'Hiç bir şey sonsuza dek sürmez Bütün mevsimleri bir günde Bütün yılları bu mevsimde yaşamaya razıyım senle, Gözlerin sözlerini anlatıyor bak...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gece-190-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Doğru', 'sana-dogru-murat-akbas-p36va', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özlemler bitmiyor.

İsyanlar öfke...

Göz yaşlarım yakarış

Çığlıklar hep olan

Çağlayanlar gibi yakarır.

Sana doğru....

            Sana doğru...', 'Özlemler bitmiyor. İsyanlar öfke... Göz yaşlarım yakarış Çığlıklar hep olan Çağlayanlar gibi yakarır. Sana doğru....             Sana doğru....', ARRAY['Türk Edebiyatı','Şiir','Murat Akbaş']::text[], 8.5, '{"poet":"Murat Akbaş","poet_slug":"murat-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sana-dogru-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz', 'deniz-fatma-karakoyun-cmkyo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensiz denizin tadımı olur

Sahiller insanlarla dolsa bile

Sen yoksun neye yarar

Yüzmeyi bilsem de boğar

Sensiz denizin tadımı olur

Geçse de yıllar

Sensiz denizin tadımı olur

Islak kumlarda ayaklarının izleri olmayınca

Senden benden tek kalan 

Bizi hatırlatan mavi yeşil

Sensiz denizin tadımı olur

Sahiller insanlarla dolsa bile

Dudaklarının kristal kadehlerde izleri olmayınca 

Sensiz denizin tadımı olur

Sahiller neşeyle çınlıyor

Sen yoksun neye yarar….

                                                       Fatma KARAKOYUN

                                                10.11.2005', 'Sensiz denizin tadımı olur Sahiller insanlarla dolsa bile Sen yoksun neye yarar Yüzmeyi bilsem de boğar Sensiz denizin tadımı olur Geçse de ...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/deniz-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim Seni', 'ozledim-seni-fatma-karakoyun-cq6gv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gitarım seni tıngırdatıyor

Müzikler sana çalıyor

Ben susuyorum onlar sana çalıyor

Dudaklarımda bildiğin o şarkı

Denizi gördüm gözlerinde

Sen bakarken aya

Ben çıkarım mehtaba

Hiç ummadığın bir yerde  ben seninleyim…

                     Fatma KARAKOYUN

                                   14.11.2005', 'Gitarım seni tıngırdatıyor Müzikler sana çalıyor Ben susuyorum onlar sana çalıyor Dudaklarımda bildiğin o şarkı Denizi gördüm gözlerinde Sen...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ozledim-seni-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melekte Sensin, Şeytanda', 'melekte-sensin-seytanda-murat-akbas-za33i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zorluklar güzellikleri yarattı.

Güzellikler ise kötülükleri...

İyi ve kötü istekler

Herşey içimizde; 

Zaten var olan var.

Yok olan ise yapılmayanlar.

Var olan mı, yoksa yok olan mı

Doğru veya yanlış? 

Sonuç; 

Melekte sensin, şeytanda...

Hadi kolay gelsin.

Zaman akıp gidiyor...

Sen ne yapsanda....', 'Zorluklar güzellikleri yarattı. Güzellikler ise kötülükleri... İyi ve kötü istekler Herşey içimizde;  Zaten var olan var. Yok olan ise yapıl...', ARRAY['Türk Edebiyatı','Şiir','Murat Akbaş']::text[], 8.5, '{"poet":"Murat Akbaş","poet_slug":"murat-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/melekte-sensin-seytanda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşa', 'yasa-fatma-karakoyun-w6ydb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öyle bir aşk yaşa ki korkut aşksızları

Öyle güzel son aşk olsun ki 

Savrulurken rüzgar kokusu yayılsın cümle aleme

Sevinç ve hüzünlerin aşk olsun

Alaturka olmasın aşk

Aşkı yalnız yaşayanlar yaşar 

                          Fatma KARAKOYUN

	14.11.2005', 'Öyle bir aşk yaşa ki korkut aşksızları Öyle güzel son aşk olsun ki  Savrulurken rüzgar kokusu yayılsın cümle aleme Sevinç ve hüzünlerin aşk ...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yasa-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Düştü Mehmet', 'can-dustu-mehmet-kadir-albayrak-kgbi0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geceler sabahla boğuşur iken

Dağların ardına kan düştü mehmet

O bayrak naz ile uçuşur iken

Toprağa bir har, can düştü mehmet

Anadolu hüzün analar da yas

Ağlıyor Edirne ağlıyor Sivas

Alnın da bir yara gül-den müşahhas

Gencecik bağrına kar düştü mehmet

Yağarken her yandan küfrün mermisi

Bayrağı başın da aslan yelesi

Dilinde tekbirdi en son nefesi

Gönlüne hem vatan, yar düştü mehmet

Çanakkale, İzmir, Yemen misali

Kavramış silahı pençe misali

Öyle bir iman ki; Umman misali

Sığmadı kabrine dar düştü mehmet

Bir yudum şahadet dudağında nem

Sarılmış toprağa ''Düşmana vermem''

Bin defa düşerim bayrak düşürmem

Haykırdı! Haine kor düştü mehmet

Albayrak semada duvaksız gelin

Sanki nişanıdır ebediyyetin

Yüzünde tebessüm kanlı şehidin

Dağlara taşlara ''nar'' düştü mehmet', 'Geceler sabahla boğuşur iken Dağların ardına kan düştü mehmet O bayrak naz ile uçuşur iken Toprağa bir har, can düştü mehmet Anadolu hüzün a...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/can-dustu-mehmet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükeniş', 'tukenis-murat-akbas-ye9wi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dalgalar vuruyor kıyılarıma

Her dalga vuruşda acıtıyor içimi...

Göz yaşlarım kalmadı.

Umutlarım tükeniyor.

Gece oldu.

           Hüsran çöktü.

Karanlıklar kucak açtı.

Hoşgeldin dercesine...', 'Dalgalar vuruyor kıyılarıma Her dalga vuruşda acıtıyor içimi... Göz yaşlarım kalmadı. Umutlarım tükeniyor. Gece oldu.            Hüsran çökt...', ARRAY['Türk Edebiyatı','Şiir','Murat Akbaş']::text[], 8.5, '{"poet":"Murat Akbaş","poet_slug":"murat-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tukenis-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emek', 'emek-fatma-karakoyun-lkbuz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sonbaharın ilk yağmuru

Bir öğrencinin kitabı

Bambu ağacının oluşumu

Her şey değimlidir emek

Geçen yılları 

Bir çocuğun gözünden okumak

Seni seziyorum

Yaşadığım yaşamda…..

                  Fatma KARAKOYUN

                                  15.11.2005', 'Sonbaharın ilk yağmuru Bir öğrencinin kitabı Bambu ağacının oluşumu Her şey değimlidir emek Geçen yılları  Bir çocuğun gözünden okumak Seni ...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/emek-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-fatma-karakoyun-zfexf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rüyada sayıkladım seni duyan olmadı

Dağlara haykırdım ismini cevap veren olmadı

Islak kumlara yazdım ismini okuyan olmadı

Buğulu camlara yazdım ismini gören olmadı

Tuvale çizdim resmini bakan olmadı…..

                              Fatma KARAKOYUN

                                             15.11.2005', 'Rüyada sayıkladım seni duyan olmadı Dağlara haykırdım ismini cevap veren olmadı Islak kumlara yazdım ismini okuyan olmadı Buğulu camlara yaz...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ruya-212-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Aramak', 'seni-aramak-murat-akbas-15jdl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her şehre inişimde

Sanki seni görecekmişim gibi...

Sokaklarda, kaldırımlarda

Her an sen çıkacakmışsın gibi...

Gözlerim hep seni arar...

Başka yüzlerde, gözlerde...', 'Her şehre inişimde Sanki seni görecekmişim gibi... Sokaklarda, kaldırımlarda Her an sen çıkacakmışsın gibi... Gözlerim hep seni arar... Başk...', ARRAY['Türk Edebiyatı','Şiir','Murat Akbaş']::text[], 8.5, '{"poet":"Murat Akbaş","poet_slug":"murat-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seni-aramak-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selamın Hello', 'selamin-hello-mehmet-akif-tiryaki-3ppi1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İşte geldim gene

Merhaba,

Selamın hello hepinize,

Bir gün daha katlayın koyun cebinize.

En güzel anınız olsun şimdi,

Dün geçti, yarın kimbilir gelirmi? 

Selamın hello hepinize,

Bir gün daha katlayın koyun cebinize.

Ara sıra savurup atın cebinizden kağıtları havaya,

Karşı koymayın esen fırtınaya.

Umarım yarın sabah güneş yeniden erken doğacak,

Selamın hello, hav ar yu? 

Ayemi soracak olursanız: -''tenkyu tenkyu''

Selamın hello hav ar yu? 

Bay bay,

Tektar görüşürüz, si yu.', 'İşte geldim gene Merhaba, Selamın hello hepinize, Bir gün daha katlayın koyun cebinize. En güzel anınız olsun şimdi, Dün geçti, yarın kimbil...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/selamin-hello-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devletler ve Ülkeler...', 'devletler-ve-ulkeler-ulvi-ziya-1fe8q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Devletler yükselmiş; yüzyıllar boyu,nice devletler batmış...

Her geçen millet,öz rûhundan.insanlığa birşeyler katmış...

Îmânı olan; uğrunda can verip,yüceltmiş ülkesini...

Kanıbozuk ise,kalleşler pazarında düşmana satmış...', 'Devletler yükselmiş; yüzyıllar boyu,nice devletler batmış... Her geçen millet,öz rûhundan.insanlığa birşeyler katmış... Îmânı olan; uğrunda ...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/devletler-ve-ulkeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmezsin', 'bilmezsin-cihan-bayat-9mnv6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilmezsin bu güzellik

Gözlerindeki ışıltıda hayat bulur.

Benim o hayata ihtiyacım var

Sana baktıkça gülümsemek için

Sevinçten ağlamak için

Seni delicesine sevmek için

Ve

Sevdiğimi anlatabilmek için

Bu yollara, bu hayata…

Bilmezsin

Güzelliklere giden tüm yollar

Senin gözlerinden geçer…

Güzel koklandıkça güzeldir.

Sevildikçe güzeldir.

Senin gibi…', 'Bilmezsin bu güzellik Gözlerindeki ışıltıda hayat bulur. Benim o hayata ihtiyacım var Sana baktıkça gülümsemek için Sevinçten ağlamak için S...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bilmezsin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şampiyon', 'sampiyon-fatma-karakoyun-kn1yw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gerçekler tarihtedir

Avrupa hep fatihtedir

Siyah beyaz 

Sarı lacivert 

Sarı kırmızı 

Kardeş bugün

Babaları fatih bugün

Milletin tacı ay yıldız

Şampiyon bugün…

          Fatma KARAKOYUN

        16.11.2005', 'Gerçekler tarihtedir Avrupa hep fatihtedir Siyah beyaz  Sarı lacivert  Sarı kırmızı  Kardeş bugün Babaları fatih bugün Milletin tacı ay yıld...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sampiyon-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-murat-akbas-bbvzx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kırma gülüm kırılırsın.

Yollarda ezilirsin.

Yıllar geçer unutulursun.

Ömür biter yaşayamazsın...', 'Kırma gülüm kırılırsın. Yollarda ezilirsin. Yıllar geçer unutulursun. Ömür biter yaşayamazsın......', ARRAY['Türk Edebiyatı','Şiir','Murat Akbaş']::text[], 8.5, '{"poet":"Murat Akbaş","poet_slug":"murat-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gulum-164-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneciğim', 'annecigim-mehmet-postalli-jyzlm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Günlerim geçiyor senden uzakta

Kapadı yolları kar, anneciğim

Gurbet ellerinde kaldım tuzakta

Beni turnalardan sor anneciğim

Evimizin önü bir sıra kavak

Yüzünde çizgiler, saçlarında ak

Beni yakıp bitirecek  bu firak

Hasretin içimde kor anneciğim

Senin gül yüzüne olmuşum hasret

Var mı ayrılıktan başka büyük dert? 

Kuş tüyünde yatsam olur taştan sert

Sensiz dünya bana dar anneciğim

Değişmem dünyaya bir annemsin sen

Hakkını ödemez canımı versem

Tek isteğim hakkın helal edersen

Eşsiz merhametin var anneciğim.

1986

Can Çiçeğim İsili Kitabıdan alınmıştır.', 'Günlerim geçiyor senden uzakta Kapadı yolları kar, anneciğim Gurbet ellerinde kaldım tuzakta Beni turnalardan sor anneciğim Evimizin önü bir...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/annecigim-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu gece', 'bu-gece-cihan-bayat-5iivd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gece uzandım aya karşı

Derin bir nefes çektim içime

Kapadım gözlerimi.

Gözlerini hayal ettim

Baktım doyasıya

Saçlarını hayal ettim

Okşadım doyasıya

Ellerini hayal ettim

Tuttum doyasıya

Sonra açtım gözlerimi birden

Ve yokluğunu fark ettim 

Çocuk gibi

Hüngür hüngür ağladım…', 'Bu gece uzandım aya karşı Derin bir nefes çektim içime Kapadım gözlerimi. Gözlerini hayal ettim Baktım doyasıya Saçlarını hayal ettim Okşadı...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-gece-168-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına', 'firtina-fatma-karakoyun-33h3p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Fırtınadan önceki sessizlikti gelişin

Korkuyorum sahte sözcüklerden

Rüzgar’ın içinden gelen sıcak bedenim

Sana gelme diyemem

Yarınlara küskünüm

Sensiz geçen ömrümden bir parça var olan

Fırtınadan önce sessizlik

                     01.11.2005', 'Fırtınadan önceki sessizlikti gelişin Korkuyorum sahte sözcüklerden Rüzgar’ın içinden gelen sıcak bedenim Sana gelme diyemem Yarınlara küskü...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/firtina-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyebilsem', 'diyebilsem-cihan-bayat-4m6ax', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaderinin kalemi olsam

Yazsam yüreğine aşkımı.

Gecelerce uykusuz kalsam

Yazsam gözlerini yıldızlara

Baksam doya doya…

Ellerimi dokunsam hayaline

Kendimden geçsem.

Nefesini çeksem içime

Delicesine koşsam kumsalda

Karışsam deryalara

Doyasıya boğulsam yüreğinde

Buluşsa ruhumuz ufukta

Kapılsam rüzgârlara

Götürse beni aşkın diyarına

Uzansam batan güneşe karşı

Dudakların gelse sonra dudağıma

Öpsem…

Hayalini yazsam yollara

Hep seninle yürüsem

Hep sana yürüsem.

Cesareti yazsam dudağıma

Dursam karşına

Alsam ellerini ellerime

Yüreğimi sarsam yüreğine

Seni seviyorum diyebilsem…', 'Kaderinin kalemi olsam Yazsam yüreğine aşkımı. Gecelerce uykusuz kalsam Yazsam gözlerini yıldızlara Baksam doya doya… Ellerimi dokunsam haya...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/diyebilsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-fatma-karakoyun-mk5wv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Umutla yaşamak zor

Umut etmek yarınları

Yeşile yakın günleri beklemek

Yeşil günlerden daha zor

Gelecek bir gün umut edilen günler

Umut edilen zamanda

Çözebilecek beni umut edilen günler 

Sen anlatmasan da

Zaman mekan meselesidir hani umut

Sen unutsan da unutmasan da

Beklemek umut etmek  gelecek yarınları

                                 Fatma KARAKOYUN

                                                               29.10.2005', 'Umutla yaşamak zor Umut etmek yarınları Yeşile yakın günleri beklemek Yeşil günlerden daha zor Gelecek bir gün umut edilen günler Umut edile...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/umut-217-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelsen', 'gelsen-cihan-bayat-jhjlh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerini bir dağ gibi büyüttüm hayallerimde

Hep aynı sözcük dudaklarımda

Yüreğimi acıtıyor yine soğuk rüzgâr

Kan kırmızı güller ayaklarımda

Gelsen…

Sabahları bir masum gülüş

Hüzünlü bir bakış bekliyor seni

Gözlerimin içinde kopacak bir çığlık ve

Yüreğimin serseri pırıltıları

Gelsen…', 'Gözlerini bir dağ gibi büyüttüm hayallerimde Hep aynı sözcük dudaklarımda Yüreğimi acıtıyor yine soğuk rüzgâr Kan kırmızı güller ayaklarımda...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gelsen-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani', 'hani-cihan-bayat-qe4ix', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani uzanırdık çimlere sere serpe

Tozpembe hayaller kurardık senle

Küçük bir kulübemiz olsa

Asırlarca yaşardık hani

Beraber güler beraber ağlardık

Geç anladık

Geç fark ettik siyahı beyazı

Hayat beyazda tomurcuklanır

Siyahta toprak olurmuş

Siyahla beyaz arasında

Koşturup durmuşuz yıllarca

Şimdi sen orada yalnız

Ben burada yalnız

Yaşıyoruz işte…', 'Hani uzanırdık çimlere sere serpe Tozpembe hayaller kurardık senle Küçük bir kulübemiz olsa Asırlarca yaşardık hani Beraber güler beraber ağ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hani-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurşun', 'kursun-cihan-bayat-thxht', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kurşunun kalbi yoktur gülüm

Yaralarken acıyor mu diye sormaz

İnsafsızdır.

Bazen öldürür, bazen süründürür.

Bazen de güldürür! 

Kurşunun dostu yoktur gülüm

Amacı zarar vermektir.

Bilmez acımayı

Acımasızdır.

Sevmez kimseyi

Bazen yüreğinden

Bazen de sırtından vurur insanın

Kalleştir.	

Sormaz, kimsin? nesin? diye

Tanımaz büyüğü, küçüğü

Amacı yok etmektir sevgileri! ..', 'Kurşunun kalbi yoktur gülüm Yaralarken acıyor mu diye sormaz İnsafsızdır. Bazen öldürür, bazen süründürür. Bazen de güldürür!  Kurşunun dost...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kursun-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Neden', 'soyle-neden-fatma-karakoyun-e4cd9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıllar var ki unutamadın mı beni sen

Uzun zamandır aklındayım neden

Benimle mi yaşıyorsun hep sen

Söyle neden geç geldin

Seçmen mi lazım sözcükleri

Gösteremez misin bir kez de olsa kendini

Benimle mi yaşıyorsun hep sen

Söyle neden geç geldin

Bu kadar ayrı kalmak doğrumuydu sence

Unutmak olur muydu bunun adı

Benimle mi yaşıyorsun hep sen

Söyle neden geç geldin

Ben unutamadığın 

Ben canında yaşadığım

Benimle mi yaşıyorsun hep sen

Söyle neden geç geldin...

                         Fatma Karakoyun

                               25.10.2005', 'Yıllar var ki unutamadın mı beni sen Uzun zamandır aklındayım neden Benimle mi yaşıyorsun hep sen Söyle neden geç geldin Seçmen mi lazım söz...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/soyle-neden-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-cihan-bayat-8l6y9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazen ağlamaktır mutluluk

Bazen ölmektir…

Gülmektir bazen

Bazen susmaktır günlerce

Çılgınca bağırmaktır bazen

Doyasıya koşmaktır bazen

Ama, anlatamamaktır.

Çünkü mutluluk

Delicesine sevmektir…', 'Bazen ağlamaktır mutluluk Bazen ölmektir… Gülmektir bazen Bazen susmaktır günlerce Çılgınca bağırmaktır bazen Doyasıya koşmaktır bazen Ama, ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mutluluk-118-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece sana', 'sadece-sana-cihan-bayat-du611', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her şey sende neşe bulur.

Sensizlik hayal kadar uzak

Rüyalar kadar sahtedir! 

Ve sana hiç unutamayacağın

Bir çığlıkta sesleniyorum

Eşin benzerin yok! ..', 'Her şey sende neşe bulur. Sensizlik hayal kadar uzak Rüyalar kadar sahtedir!  Ve sana hiç unutamayacağın Bir çığlıkta sesleniyorum Eşin benz...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sadece-sana-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-fatma-karakoyun-vpux8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu sabah uyandım sonbahar

Bilmezdim sonbaharın bu kadar

Güzel olduğunu

Yaşamadan önce

Dışarıda yağmur

İçimde sen

Yaşamak gerekirmiş 

Önceden sezinlediklerini

İnceden inceden

Dışarıda yağmur aklımda sen

Düşünmen gerekirdi beni sen

Sonbaharı yaşamadan geçemez insan

Mevsimlerden sonbahar aklımda sen

Dışarıda yağmur

Aklımda sen

Nerdesin....

                    Fatma Karakoyun

                                  25.10.2005', 'Bu sabah uyandım sonbahar Bilmezdim sonbaharın bu kadar Güzel olduğunu Yaşamadan önce Dışarıda yağmur İçimde sen Yaşamak gerekirmiş  Önceden...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sonbahar-117-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç yazar', 'kac-yazar-cihan-bayat-m0f4q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünya sapına kadar mert olsa

Kaç yazar! 

İnsanları kahpe olduktan sonra

Sen bana yıldızlar kadar uzak olsan

Kaç yazar! 

Seni,

Ruhumdan daha fazla sevdikten sonra!', 'Dünya sapına kadar mert olsa Kaç yazar!  İnsanları kahpe olduktan sonra Sen bana yıldızlar kadar uzak olsan Kaç yazar!  Seni, Ruhumdan daha ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kac-yazar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islak Ceset', 'islak-ceset-kadir-albayrak-jh87e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Caddeler başıboş yağmursa oluk oluk

Her damlada bir kasvet bir intizar bir soluk

Dallar karmakarışık yapraklar yerde, cansız

Müjdelenen bahardı hazan geldi zamansız

Simsiyah bir gelinlik giymişti sanki dünya

Çırpınış boşunaydı ne hayaldi ne rüya

Ne gül kokusu vardı cıvıltısı bir kuşun

Bir motor gürültüsü bomboş geçen dolmuşun

Bir yalnızlık sarmıştı her yanı katmer katmer

Yağmur nazlanıyordu topraksa onu bekelr

Bir adam yürüyordu ağır ve düşünceli

Esir etmişti onu  o sürünen gölgesi

Çıldıran şimşeklerle ilgilenmedi bile

Başını kaldırıp da bakmadı gökyüzüne

Kasırga içindeydi lakin beden çok sessiz

Hıçkırık sesi geldi birden belli belirsiz

Belli ki ağlıyordu kim bilir neydi derdi

Bu garibi hangi kul acılara terk etti

Yağmur yavaşlıyordu dinecekti nasılsa

Yığıldı kaldı birden soğuk parke taşına

Kurtarmıştı ruhunu vererek nefesini

İbret diye bıraktı o ıslak cesedini

Terkedip gitmişlerdi kalmıştı tek başına

Tabut bile yalnızdı o musalla taşında

Ne ağlayan göz vardı ne de sızlanan yürek

Mezar kazan iki kişi bir kazma bir de kürek

Yalnız gelen o yağmur çekip gitmişti bile

Giderken beraberdi o garibin kalbiyle', 'Caddeler başıboş yağmursa oluk oluk Her damlada bir kasvet bir intizar bir soluk Dallar karmakarışık yapraklar yerde, cansız Müjdelenen baha...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/islak-ceset-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bursa 1', 'bursa-1-feyza-nur-cengiz-t77k5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç usanmıyorum,

Hergece yaşadığımız onca yılın her gününü,

Saniye saniye yaşıyorum....

Hani Ulucamii''nin havuzunda buluşurduk.

Sen hep geç kaldırdın,

Arasıra bende bekletirdim kızdımak için seni.

Yağmurlu bi havada Garaj ın orta yerinde kavga etmiştik,

Sertçe kolumu tutup çekmiştin,

Öyle çok kızmıştım ki sana,

Koşarak tek kişilik yer kalan dolmuşa binmiştim.

Ve seninle her zaman gittiğimiz cafeye gidip oturmuştum.

Sözde sende kaçıp kurtulmuştum.

Daha siparişimi vermeden çay getirmişti garson

Sonrada seni göstermişti.

İlk Sevgililer gününde postanenin önünde buluşmuş,

Birbirimize göstermeden hediyelerimizi açmıştık.

Sonra sanki ruhlarımız kördüğüm olurcasına sarılmıştık.

Tophaneye çıkıp bakışlara aldırmadan haykırmıştık aşkımızı

Meydan okumuştuk be Bursa''ya........

Ve ilk öpücüğümü vermek istemiştim sana 

Sen utangaç başını çevirdin başka yöne 

En çok KültürPark''a gitmişizdir.

Giriş paralarıla rahat bi araba alırdık.

Nedense oraya girince daha bi sıkı tutardım elini,

Bi  an bıraksam kapacaklarından korkardım.

Çarşı ya her gidişimizde kızardın bana

Paramız olmasa herşeyin fiyatını sorar,

Hatta pazarlık bile yapardım.

İkimizin doğum gününü bir gün aralıklarla kutlardık.

Şubatta.Hele bide kar yağdımı bayram yapardık.

Burç sinemasında izlediğimiz ilk filmi hatırlamıyorum

Film boyunca yüz hatlarını çizdim gözlerime,

Filmdeki bütün adamlar sen,bütün kadınlarda bendim..

Bi keresinde arkadaşlarım görmüştü bizi Heykelde gezerken,

''Nereye götürüyor seni sürükleyerek''diye dalga geçmişlerdi

Senin boyun uzun,benim kısa yanyana yürüyemezdik

Bi İkindi namazından sonra Ulucamide yüzük takmıştık 

Ve sen bana söz vermiştin; 

                        ''BEYAZ GELİNLİKLERLE DE............''

Devlet Hastanesinin karşısındaki küçük caminin banklarında,

Bi akşam yemeği yemiştik,

Senin ki peynirli benimki patatesli iki pağça...

Yorgun bi iş çıkışı tutturmuştun

İlla Tophaneye merdivenlerinden çıkalım diye 

Bende mızmızlık yapınca kendimi bulutlara yakın bulmuştum.

Olur olmaz yerlerde kucağına alırdın beni.

Kızar gibi yapar ama öyle mutlu olurdum ki.

Daha neler neler yaşadık bu Bursa da,

Ama işte bizim de öykümüzün sonu geldi.

Kimbilir belki mutluluğumuz göze geldi.

Bu şehir verdi seni bana.

Bi otobüsün içinde uzaklaşırken sadece el sallayabildim.

Hiçbirşey bıraktığın gibi kalmadı.

Döndün ama o kadar geç kaldın ki bana...

Bursa seni bana. beni sana çok gördü,

Bir emanet gibi zamanı geldiğinde,

Almasını çok iyi bildiği bir aşk verdi bize.

**********--************--*************', 'Hiç usanmıyorum, Hergece yaşadığımız onca yılın her gününü, Saniye saniye yaşıyorum.... Hani Ulucamii''nin havuzunda buluşurduk. Sen hep geç ...', ARRAY['Türk Edebiyatı','Şiir','Feyza Nur Cengiz']::text[], 8.5, '{"poet":"Feyza Nur Cengiz","poet_slug":"feyza-nur-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/bursa-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seçmeler', 'secmeler-cihan-bayat-qlc95', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-1-

Aklımdan çıkaramadım seni

Dokunduğum rüzgârlarda sen kokuyorsun

Duvarlar saklamaya çalışıyor hayalini

Aşkının gölgesi hep kalbimin üzerinde.

-2-

Pencerenin altında

Ağlayan bir gölge görürsen

Bil ki beni çok incitmişsin.

Eğer, odana vuran ay ışığında

İnce bir tebessüm varsa

Bil ki seni beklemekteyim…

-3-

Bitmeyen aşkımın uyku damlacıkları

Gözlerinde dans edip

Kalbimde büyür

Sonsuza kadar…

-4-

Hatırlamaktan vazgeçmedi saatler

Unutur mu sandın seni bu geceler

Engel olur mu sandın sana ulaşmama mesafeler

Peki biliyor musun? 

Bizi bekleyen şey güzel mevsimler…

-5-

Güller sende

Hüzünler bende

Geceleri ayaklarımızın altına alıp

Koparıp hayatı

Bu yüce dağlardan

Paylaşalım sonsuza kadar…', '-1- Aklımdan çıkaramadım seni Dokunduğum rüzgârlarda sen kokuyorsun Duvarlar saklamaya çalışıyor hayalini Aşkının gölgesi hep kalbimin üzeri...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/secmeler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ebruli', 'ebruli-fatma-karakoyun-n09m2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sade renkler çözebilir beni

Yaşamıma renkler yön verir

Bugün bitiğinde bugün ne renkti

Hangi renk yaşanmıştı bugün

Yağmurun bile rengi var yaşamda

Karın olduğu kadar

Sadece sen olduğunda

Renkler karışıyor o kadar

Ebruli yaşıyoruz o zaman

                      24.10.2005', 'Sade renkler çözebilir beni Yaşamıma renkler yön verir Bugün bitiğinde bugün ne renkti Hangi renk yaşanmıştı bugün Yağmurun bile rengi var y...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ebruli-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden sonra', 'senden-sonra-cihan-bayat-m5u6i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tadım kalmadı senden sonra

Gülmüyor yüzüm, sus pus oturuyorum.

Konuşmuyorum boşuna

Her zaman ki gibi yine aklımda sen

Sadece düşünüyorum.

Gözlerim yorgun, dizlerim yorgun,

Yüreğim yorgun senden sonra…

Mevsim yaz olsa da soğuk ruhum

Kulağımda sesinin izleri

Bedenimde teninin yankıları! 

Yorgun bir günde yaşayan

Yorgun bir adamım senden sonra

Umutlarım kaybolmuş gitmiş

Dualarım denizde boğulmuş sanki

Çaresizim.

Çok uzaklardasın

Aramızda dağlar, yollar var

Ama unutmam yüreğim seninle

Benden aldığından beri

Bittim, tükendim senden sonra

Sevmek kaybetmekse

Kaybedenlerdenim öyleyse…', 'Tadım kalmadı senden sonra Gülmüyor yüzüm, sus pus oturuyorum. Konuşmuyorum boşuna Her zaman ki gibi yine aklımda sen Sadece düşünüyorum. Gö...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/senden-sonra-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil', 'yesil-fatma-karakoyun-t9c1o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünya nasıl görünüyor bilmiyorum size 

Bana yeşil

Yaşam nasıl görünüyor size bilmiyorum 

Bana yeşil

Doğa size nasıl görünüyor bilmiyorum 

Bana yeşil

Biliyor musun sözlerinde

Bana yeşil

Biran bakıyorum karanlıklarda 

Bana yeşil

Benim gözlerimden her yer yeşil..

                                            24.10.2005', 'Dünya nasıl görünüyor bilmiyorum size  Bana yeşil Yaşam nasıl görünüyor size bilmiyorum  Bana yeşil Doğa size nasıl görünüyor bilmiyorum  Ba...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yesil-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin olsun', 'senin-olsun-cihan-bayat-jighk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mutluluk benim kalbimde

Gözlerimde, ellerimde

Sana biriken gözyaşlarımda

Ne olur,

Ne olur anla

Bak gözlerime

Tut ellerimi

Sil gözyaşlarımı.

Sen her zaman kalbimdesin! ..

Çabuk ol! 

Oradaki sevdanın sana ihtiyacı var.

Yaklaş ruhuma

Eksikliğini hisset

Ruhumda senin olsun…', 'Mutluluk benim kalbimde Gözlerimde, ellerimde Sana biriken gözyaşlarımda Ne olur, Ne olur anla Bak gözlerime Tut ellerimi Sil gözyaşlarımı. ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/senin-olsun-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun', 'yorgun-fatma-karakoyun-0do9u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yorgunum çok yorgunum 

Yıllar geçti ben yoruldum

Benim sonum belli

Sen ise bana kıyamadığın

Elinden gelse dünyayı durdurup 

Yeniden başlattığın

Yorgunum çok yorgun

Sen kader değil sen tutunamadığımsın

Sana uzanıyorum yakalayamıyorum

Yorgunum çok yorgunum

Şimdi ne umutlarım vardı kalmadı aklımda

Sen kader değil sen tutunamadığımsın

Seni umut etmek çok güzeldi

Fotoğraflar ne diyor bilmiyorum

Zaman konuşuyor biliyorum

Bundan sonra ne yaparım

Cesaret bulamıyorum

Kendime neden böyle yapıyorum bilmiyorum

Bildiğim tek şey bunları hiç hak etmediğim

Geç anladım yaşadıklarımı 

Kimseye ödün vermedim

Sadece inanmaktı günahım

Yorgunum çok yorgunum

Yıllar geçse de üzerinden

Yaşadıklarımı unutmamam gayem

Şimdi daha iyi biliyorum geçmiş geleceğin üstüne kurulur

Bunu hiç unutmadım

Unutmak için değil hatırlamak için yaşadım

Yorgunluğu unutmak ona yenilmek değil amacım

Sadece yaşama ödün vermediğim..

                                                       24.10.2005', 'Yorgunum çok yorgunum  Yıllar geçti ben yoruldum Benim sonum belli Sen ise bana kıyamadığın Elinden gelse dünyayı durdurup  Yeniden başlattı...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yorgun-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle başlar seninle biter', 'seninle-baslar-seninle-biter-cihan-bayat-cathu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ellerim eskisi kadar sıcak değil artık

Geceleri resmini koynuma almadan uyuyamıyorum

Sanki her an kapım açılacak

Sen gireceksin içeriye

Ama yinede biliyorum ki yoksun artık! ..

Her sabah ismini haykırarak uyanıyorum

Hayalin yüreğimde başlıyor gökyüzünde bitiyor…

Yalnız çıkıyorum dışarıya

Bir derya gibi salıyorum kendimi sokaklara

Gözüm yolun sonuna takılıyor,

Yürüyorum sana gidercesine! 

Bilisin yine aynı parktayım

Aynı bank, aynı çam, aynı şehir

Bir yamacımda hayalin

Çok uzaklarda gülen yüzün ve

Aynı rüzgârın koynunda

Aynı titreyen ellerim

Ama üşümüyorum biliyor musun? ..

Ara sıra koşuyorum, yüreğimde seni konuşuyorum

Nedense bitmiyor yollar, geçse de yıllar

Zaman su gibi

Bıraktın mı akıp gider, durduramazsın

İçtin mi seni de götürür içinde

Kaybolur gidersin.

Anlıyorsun ya, sık sık seni düşünüyorum

Akşamları sahile iniyorum

Güzelliğini yakamozda arıyorum

Ama biliyor musun

Hiçbir şey senin yerini tumuyor…', 'Ellerim eskisi kadar sıcak değil artık Geceleri resmini koynuma almadan uyuyamıyorum Sanki her an kapım açılacak Sen gireceksin içeriye Ama ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/seninle-baslar-seninle-biter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şekerdeki Tuzumsun', 'sekerdeki-tuzumsun-hikmet-kavas-wysqb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şekerdeki tuzumsun

ömrümdeki otuzum

sana haksızlık ettim

biliyorum

bunu biliyorum kuzum

benim bilmediğim şey

neden helalinden sevmek varken

kendi kendime hırsızım', 'şekerdeki tuzumsun ömrümdeki otuzum sana haksızlık ettim biliyorum bunu biliyorum kuzum benim bilmediğim şey neden helalinden sevmek varken ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Kavas']::text[], 8.5, '{"poet":"Hikmet Kavas","poet_slug":"hikmet-kavas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sekerdeki-tuzumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mi Kiyamo Ako', 'mi-kiyamo-ako-mehmet-akif-tiryaki-jj8c6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kom ti ki yamo? 

Mi ki ya mo Ako.

Hav ar yu duing,

We ar uyuyoring.

Morning morning

Nasıl veyk ap arım? 

Yavaş yavaş may şopa akarım.

Lap topumu açıp,

İki meil atarım.

Kim tutar seni Ako

İki saatlik yol Monoko, Portoriko

Kom ti kiyamo? 

Mi kiyamo Ako.

Hav ar yu duing? 

We ar uyuyoring.

Ti bırak bana firendim,

Artsın biraz tirendim.

Hah gelmiş may meillerim,

Riding yapıp mutlu olurum,

Saat 18 of olur kaybolurum.', 'Kom ti ki yamo?  Mi ki ya mo Ako. Hav ar yu duing, We ar uyuyoring. Morning morning Nasıl veyk ap arım?  Yavaş yavaş may şopa akarım. Lap to...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mi-kiyamo-ako-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi içinde', 'sevgi-icinde-cihan-bayat-msp8e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kuşun kanadında sessizce büyümüşüm yıllarca

Umut etmeyi, sevmeyi, özlemeyi taşımışım, bıkmadan

Acımamış yüreğim hayatın yalancı sillelerinden

Duyguları aldatmamayı öğrenmişim nede olsa

Anlatmaya çalışmışım karanlık yüreklere, yılmamışım

Sabırla beklemişim adımlarını sayan zamanı

Yolumu gözümde büyütmüşüm kutsal demişim

Yürümüşüm kaderimin mevsiminde doğan güneşe

Hayal yağmurlarında ıslandıkça artmış sevincim

Yüreğimin göklerine çizmişim umutlarımı

Gecelerce uyumamışım pencereye takılmışım

Başımı indirmemişim namert nefretin ayaklarına

Gözlerimi ayırmamışım ağlayan gökyüzünden

Korkusuzca geçmişim cehaletin ateşinden

Kapmışım çiçekleri vermişim göçüp giden kışa

Üzülmemişim, kırılmamışım, ağlamamışım,

Kendimi vermişim bahara dalmışım sevmeye

Etrafımdaki güzelliklerin farkına varmışım

Meğer bu ana kadar yokmuşum, körmüşüm

Sonra şükretmişim sahip olduklarıma

Sevgi içinde yürüdükçe büyütmüşüm sevgiyi içimde…', 'Bir kuşun kanadında sessizce büyümüşüm yıllarca Umut etmeyi, sevmeyi, özlemeyi taşımışım, bıkmadan Acımamış yüreğim hayatın yalancı silleler...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevgi-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benzemez Kimse sana', 'benzemez-kimse-sana-muharrem-karaman-fo8h7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güzelsin,

Dudakların, saçların, bakışların,

Bir başkaydı senin,

Duruşun, ağlayışın, sevişin

Ve bir başkaydı öpüşün.

Hani tanıştığımız gün

Demiştim ya güzelsin diye,

Gerçekten öyleydi güzeldin...

Sen farklıydın,

Çünkü ansızın gelmiştin bana,

Ve ben biliyordum.

Her güzelin bir çirkini,

Her dirilişin sonunda bir ölümün olduğunu,

Her gelmenin bir gitmek olduğunu,

Biliyordum.

Ve şimdi sen ansızın gidiyorsun........

Hani ayrılırken güzelsin demiştim ya,

Gerçekten öyleydi güzeldin.

Bir başkaydı öpüşün ve dudakların,

Bir başkaydı sarılışın ve kollarımın arasında ağlayışın,

Gerçekten öyleydi ayrılığın acı bir tatı vardı.

Ama ayrılıken bile güzeldin,

Çünkü severdin..............', 'Güzelsin, Dudakların, saçların, bakışların, Bir başkaydı senin, Duruşun, ağlayışın, sevişin Ve bir başkaydı öpüşün. Hani tanıştığımız gün De...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Karaman']::text[], 8.5, '{"poet":"Muharrem Karaman","poet_slug":"muharrem-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/benzemez-kimse-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umuduyla', 'umuduyla-cihan-bayat-kcy0l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adını bahçemdeki

Bütün ağaçlara kazıyacağım

Bir gün sana

Kavuşacağım umuduyla! 

Gözlerini

Bütün duvarlara çizeceğim

Baktıkça

Mest olayım umuduyla! 

Güzelliğini

Bütün yıldızlara anlatacağım

Sonsuza kadar

Unutulmaması umuduyla…', 'Adını bahçemdeki Bütün ağaçlara kazıyacağım Bir gün sana Kavuşacağım umuduyla!  Gözlerini Bütün duvarlara çizeceğim Baktıkça Mest olayım umu...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umuduyla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heyecanım var', 'heyecanim-var-cihan-bayat-9sqh2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Heyecanım var

Yanıma yaklaştıkça

Nefesini hissettikçe

Heyecanım var

Adını duydukça

Benden kaçtıkça

Heyecanım var…', 'Heyecanım var Yanıma yaklaştıkça Nefesini hissettikçe Heyecanım var Adını duydukça Benden kaçtıkça Heyecanım var…...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/heyecanim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uludağ', 'uludag-fatma-karakoyun-5lr1a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bursa’nın eşsiz güzel uludağı

Yazın soğuk akan suyu

Kışın dondurur gökyüzünde yıldızları

Kayak yapanlar,piknik yapanlar

Kirazlı yaylada ızgara

Doymadın mı yoğurt ekmek

Sende yaşanmış sevdalar

Sende sadelik beyazlık

Sende mutluluk örtüsü

Sende doğada yaşanmış olan güzellikler

Kuşlar nasıl özgür doğanda 

Bende sende özgürüm

Bursa’da bir gelin gibi süzülürsün öyle

İnce, narin bir o kadarda yüksek

Bursa’ ya yakışmışsın nede olsa

İlk uyandığımda sana bakarım

Nazarlarımı sende atarım

İyi ki varsın yüce Uludağ

Gecende yıldızlara yakın akşamlar yaşanır

Gündüzünde şampanya rengi güneşin

Gecenle gündüzünle yine bir örtüsün uludağım

                         22.10.2005', 'Bursa’nın eşsiz güzel uludağı Yazın soğuk akan suyu Kışın dondurur gökyüzünde yıldızları Kayak yapanlar,piknik yapanlar Kirazlı yaylada ızga...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/uludag-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adının sen koy', 'adinin-sen-koy-cihan-bayat-qqynk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneş ufka yaklaşmış güzel akşamı seyrediyor

Bense tatlı rüyamı…

Dünya karanlığa gömülmüş çiçekler uykuya dalmış

Ortalığı bir sessizlik bürümüş…

Yaşananlar hayale gömülmüş

Güneş derin bir uykuya dalmış…', 'Güneş ufka yaklaşmış güzel akşamı seyrediyor Bense tatlı rüyamı… Dünya karanlığa gömülmüş çiçekler uykuya dalmış Ortalığı bir sessizlik bürü...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/adinin-sen-koy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlatılmış sevdalar', 'aglatilmis-sevdalar-cihan-bayat-nk60u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağlatılmış sevdalar mühürlenmiş mevsimlere

Koşup duruyor gözlerimin önünde

Beklesem mi? Yoksa koşup gitsem mi? 

Peşinden, bana esir yıllara…

Ağlatılmış sevdalar mühürlenmiş mevsimlere

Deşip duruyor acılarımı

Ağlasam mı? Yoksa karalar bağlasam mı? 

Anlatsam gecelere

Sonra seni arasam mı? 

Ağlatılmış sevdalar mühürlenmiş mevsimlere

Savurup duruyor başımı sağa sola

Atsam mı kendimi yerlere? 

Yoksa yumruklasam mı duvarları? 

Geri gelir miydi  eski sen? ..', 'Ağlatılmış sevdalar mühürlenmiş mevsimlere Koşup duruyor gözlerimin önünde Beklesem mi? Yoksa koşup gitsem mi?  Peşinden, bana esir yıllara…...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/aglatilmis-sevdalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yudum Yudum', 'yudum-yudum-fatma-karakoyun-rwjvc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akşam çığlık çığlığa sesi yayılıyor odama

Neden niçin geldin yanıma

Sensizlik kadar zor yanımda olman

Sanki beni koparırcasına

Yudum yudum içmelisin beni

Kadehten akarcasına

Sadece senin için buradayım

Sensiz geçen akşamlarda

Bir tek sen vardın aklımda

Sanki beni koparırcasına

Şarap olmalıyım dudaklarında

Yudum yudum içmelisin beni

Kadehten akarcasına

Sensizlik kadar zor yanımda olman 

Sanki beni koparırcasına

      Fatma KARAKOYUN

                                      20.10.2005', 'Akşam çığlık çığlığa sesi yayılıyor odama Neden niçin geldin yanıma Sensizlik kadar zor yanımda olman Sanki beni koparırcasına Yudum yudum i...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yudum-yudum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah bir dönebilsem', 'ah-bir-donebilsem-cihan-bayat-m1idh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yol açılır sonsuzluğa

İnsanı nereye götüreceği hiç belli değildir

Belki mutlu günlere

Belki hüzünlü günlere

Belki umutların birleştiği yere

Beklide mezara! 

Hayat kimileri için çok değerli anlar taşır

Kimileri içinse ıstıraplar bütünlüğüdür

İnsan yapmak istediklerini hiçbir zaman

Zamanında yapamaz.

Tekrar, tekrar geriye dönmek ister

Zaman ilerledikçe toprağa yaklaştığının

Farkında bile değildir.

Hayıtının son noktasına gelince de

Geriye kalan tek bir feryat olur

Ah bir dönebilsem...', 'Bir yol açılır sonsuzluğa İnsanı nereye götüreceği hiç belli değildir Belki mutlu günlere Belki hüzünlü günlere Belki umutların birleştiği y...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ah-bir-donebilsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melankoli', 'melankoli-fatma-karakoyun-v49x8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Melankolik akşamlarda 

Bir sen vardın aklımda 

Çözemediğin bilmecemdin 

Yalanlar istiyorsan incinirsin 

Yinede sen bilirsin

Zavallı hayallerim yıkılmış sensiz

Melankolik akşamlarda

Bir sen vardın aklımda

Yine de sen bilirsin

Sensiz yarım kaldım

Unuttun gittiğin yerde beni

Sen  çözemediğin bilmecem din 

Yine de sen bilirsin..

                Fatma KARAKOYUN

                                           19.10.2005', 'Melankolik akşamlarda  Bir sen vardın aklımda  Çözemediğin bilmecemdin  Yalanlar istiyorsan incinirsin  Yinede sen bilirsin Zavallı hayaller...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/melankoli-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk''tan yana', 'ask-tan-yana-cihan-bayat-u9dav', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk’tan yana bir umut diliyorum hayattan

Güller yeniden açsın, çiçekler yeniden koksun

Aşk’tan yana bir ışık bekliyorum hayallerimden

Kuşlar hep ötsün, hiç durmadan tatlı tatlı…', 'Aşk’tan yana bir umut diliyorum hayattan Güller yeniden açsın, çiçekler yeniden koksun Aşk’tan yana bir ışık bekliyorum hayallerimden Kuşlar...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-tan-yana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birsen', 'birsen-fatma-karakoyun-iybqo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayrılmak ister mi bu kalbim senden

Ayrılır mı seven sevenden

İstersen vaz geç benden

Kalbini kopar kalbimden 

Sen ben mutlu olacak mıyız bir gün

Söyle anlatacak mıyız birbirimize olan sevdamızı

Bir hayaldin hükmedemediğim

Bir sendin merhaba deyip de elveda demediğim

Bulmaca olmalıyım sende beni sen çözmelisin

İpucun olmalıyım ki rahatlıyabilesin

Bir sen varsın ki adını koyamadığım

Birsen birsen …

                               18.10.2005', 'Ayrılmak ister mi bu kalbim senden Ayrılır mı seven sevenden İstersen vaz geç benden Kalbini kopar kalbimden  Sen ben mutlu olacak mıyız bir...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/birsen-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımı ararım bucak bucak', 'askimi-ararim-bucak-bucak-cihan-bayat-90blh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şehirde kasabada köyde

Aşkımı ararım bucak bucak

Hep gezerim ilden ile

Aşkımı arım bucak bucak…

Ulu dağlar aşarım

Uzun yollar teperim

Ben aşkımsız ne ederim

Aşkımı ararım bucak bucak…

Urfa, Malatya, Bolu

Aşkımı gören oldu mu? 

Ben bu yolların toprağı tozu

Aşkımı ararım bucak bucak…

Nice insanlar gördüm

Aşkımı yıldızlarda gördüm

Ben aşkım için ölürüm

Aşkımı ararım bucak bucak…

Çiçeğimi ararım bucak bucak

Kalbim sevgi dolu kucak kucak

Benim sonum ne olacak

Aşkımı ararım bucak bucak…', 'Şehirde kasabada köyde Aşkımı ararım bucak bucak Hep gezerim ilden ile Aşkımı arım bucak bucak… Ulu dağlar aşarım Uzun yollar teperim Ben aş...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/askimi-ararim-bucak-bucak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk''tan sana', 'ask-tan-sana-cihan-bayat-2p63l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazen gece  olurum bakarım pencerenden

Bazen su olurum akarım çeşmenden

Bazen alev olurum yanarım aşkından

Bazen yaş olurum akarım gözlerinden

Bazen gül olurum düşerim ellerinden

Bazen toprak olurum tanırım seni izlerinden

Bazen yaprak olurum düşerim gözlerinin önünden

Bazen hayal olurum geçerim aklının derinliklerinden

Bazen ağaç olurum veririm sana meyvelerimden

Bazen korku olurum titrerim bedeninden

Bazen sevgi olurum parlarım gözlerinden

Bazen rüya olurum tutarım ellerinden

Bazen şarkı olurum uçarım dudaklarından

Bazen türkü olurum girerim kulaklarından

Bazen rüzgâr olurum tutarım saçlarından

Bazen bülbül olurum hiç gitmem pencerenden

Bazen taş olurum düşerim yüreğinden

Bazen kuş olurum uçarım ellerinden

Bazen bulut olurum bakarım sana gökyüzünden

Bazen mutluluk olurum okunurum yüzünden

Bazen hayat olurum yaşatırım içimde seni…', 'Bazen gece  olurum bakarım pencerenden Bazen su olurum akarım çeşmenden Bazen alev olurum yanarım aşkından Bazen yaş olurum akarım gözlerind...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bayat']::text[], 8.5, '{"poet":"Cihan Bayat","poet_slug":"cihan-bayat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ask-tan-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunabilseydim Gözlerine', 'dokunabilseydim-gozlerine-ufuk-coban-70031', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnızlık dolmuyor senden başka bir kokuda,

Hasret bitmiyor senden başka bir sarılışta,

Gelmeye niyetin de yok şu yalnızlar şehrine,

Kader bu razı olmayı bilmek gerek çaresizliğine.

Seni sevmeyi nasıl yok ederim bedenimden? 

Sensiz, sesin olmadan nasıl katlanırım yaşamaya? 

Sen alıştın mı sanki bensizliğin sessizliğine,

Katlanmak gerek, hayatın dikenli günlerine.

Yılların aynı olacağını bilsem de yalnızlıkla,

Bir umut kalsa da seni beklemekte,

Herşeye katlanılır, yüreğim taş olurdu,

Bir kere dokunabilseydim gözlerine.

12/11/2005 09:10', 'Yalnızlık dolmuyor senden başka bir kokuda, Hasret bitmiyor senden başka bir sarılışta, Gelmeye niyetin de yok şu yalnızlar şehrine, Kader b...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dokunabilseydim-gozlerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geyik Muhabbeti', 'geyik-muhabbeti-kadir-albayrak-8mcn9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Oturduk meyhaneye

Bir içtik.... bir içtik

Laf lafı açtı! ...

''Geyik muhabbeti'' işte

Aklımızca ''Kafayı bulucaz''

Sonra da,

Gönlümüzde ki kahpeyi unutucaz! ...

Manyaklık bu be! ......

Ulan! .... Gönülün ''kafayla''  işi ne? ? ? ! ! ! 

............

Sonra ne mi oldu? 

Ayılınca anlatırım! .......', 'Oturduk meyhaneye Bir içtik.... bir içtik Laf lafı açtı! ... ''Geyik muhabbeti'' işte Aklımızca ''Kafayı bulucaz'' Sonra da, Gönlümüzde ki kahpe...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/geyik-muhabbeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dar Han', 'dar-han-adem-tok-8bncg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'çekinme

bu can senin

rahat solu

içine dolacağı

fidan yeşerince

bakmaz kimseye

açar türlü türlü

dalında meyveye

görünmez tabiatın iç yasaları

duyulmaz insan duyguları

böyle değildi doğarken var olan

yaşlandıkça sarardı sayfaları

çekinme

bu can senin

itaat et doğana

nasılsa için

fidan serpilince bakmaz kimseye

alanı bellidir

gönül verince ancak

iş değişir

uzan 

kollarında saydığına

fidan ol

zaman dar

han dar

belli olmaz odanın ne vakit değişeceği

                                                                         (10.02.04) 

                                                                         f tipi hapishane EDİRNE', 'çekinme bu can senin rahat solu içine dolacağı fidan yeşerince bakmaz kimseye açar türlü türlü dalında meyveye görünmez tabiatın iç yasaları...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dar-han-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cam Silecekleri', 'cam-silecekleri-kadir-albayrak-95fcs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '05.00....... Ben bilmiyorum

Saatler öyle diyor! ...

dünü yaşamamışken henüz, bu gün başlıyor! 

Karanlıklar yorgun,

Gece; Vedanın mahzunluğunu yaşıyor

Suskun mahcup ve durgun

.....................

Siyah kalemle

Simsiyah gecenin bağrına

Çizdiğim yüzün dalgalı, belirsiz ve flu

Ben bitkin,

Resmin gece yorgunu

.......................

Sabahın ilk ışıkları dökülüyor! ..

Dökülesi yıldızlar gibi

Tek tek! ...

Dün de böyleydi, önce ki gün de

N e olurdu sanki? Ne olurdu bir gece bekleyebilsek? ! 

...................

Çoraplarımı çıkaracak kadar vaktim

Ve seninle ebediyyete aktim

Olmadı hiç! ....

Zaman kahpe, zaman zalim

Zaman piç! ......

.................

05.30........... 

Gem-i azıya almış yelkovan

Akrep tutsak! 

Kaç kez dua ettim kim bilir

Gecenin sonsuzluğunda ''Kaybolsak''

Şafaklar atarken dinlediğim

O kıpkızıl güneşin,

Öldüresi bestesinden kurtulsak! ...

............................

Yeni bir gün

Bembeyaz bir yorgan örtüyor yıldızlara

Soluyor gecemin kan çiçekleri

Ve..... Hatıralarımın üstünde

Yine o.....

Yine o ''Cam silecekleri''', '05.00....... Ben bilmiyorum Saatler öyle diyor! ... dünü yaşamamışken henüz, bu gün başlıyor!  Karanlıklar yorgun, Gece; Vedanın mahzunluğun...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/cam-silecekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çala Gelir', 'cala-gelir-nuri-ozoglu-jkvrx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşım otuzbeşse moruk mu oldum? 

Ben onsekizinde bahar isterim.

Eski sevdiğim yok, yenisin buldum,

Daha şu gönlümde neler beslerim.

Deli gönül sağa sola sataşır,

Galiba içinde bir sevgi taşır,

Her bakışta üzerime bulaşır,

Sağ yanak altından bir yol isterim.

Geçmiyorki günler hasret giderem,

Yar yüzünü görüp gönül eyleyem,

Ey sevdiğim doğrusunu söyleyem,

Sana uzatılan dili keserim.

Hayalin gitmezse gözüm önünden,

Başka geçmemesi lazım gönülden,

Yalan değil inan senin sevginden,

Ferhat gibi dağı taşı delerim.

Eğer insan sever ise birkere,

İkincisi çala gelir gönlüne,

Özoğlu kıyamaz kendi gülüne,

Başkasını el vurmadan severim.', 'Yaşım otuzbeşse moruk mu oldum?  Ben onsekizinde bahar isterim. Eski sevdiğim yok, yenisin buldum, Daha şu gönlümde neler beslerim. Deli gön...', ARRAY['Türk Edebiyatı','Şiir','Nuri Özoğlu']::text[], 8.5, '{"poet":"Nuri Özoğlu","poet_slug":"nuri-ozoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cala-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelecek Gibi', 'gelecek-gibi-kadir-albayrak-suk3p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlık sokakta yalnız başıma

Dolaşır dururum deliler gibi

Başımı kaldırıp baksam semaya

Yıdızlar resmini çizecek gibi

Dalgada köpükte sen varsın diye

Dalmışken masmavi engin denize

Bir yolcu gemisi acı sesiyle

Ümidi gönlümden silecek gibi

Ruhumda amansız yorgunluk başlar

Çılgınlık anıdır süzülen yaşlar

Geçmişi süsleyen o hatıralar

Gözümün önüne gelecek gibi

Bir garip alemde bir garip mekan

Hapsolur maziye seninle zaman

Uzanıp saçını tutacağım an

Aniden bir rüzgar esecek gibi

Hıçkırık bir düğüm sinemde yumruk

Hükmeder ruhuma koskoca boşluk

İsmini anmadan aldığım soluk

Kahredip ölüme gidecek gibi', 'Karanlık sokakta yalnız başıma Dolaşır dururum deliler gibi Başımı kaldırıp baksam semaya Yıdızlar resmini çizecek gibi Dalgada köpükte sen ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gelecek-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Nokta', 'kor-nokta-guzin-eye-dundar-ypl6h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnsanın  özünde ne   tutkular  var

yükselme  hırsıyla  çıkmaza   dalar

kendinden  verdikçe  çoğu  yakalar

aza kanaat  etmez  ruhunu  boğar

keskindir  kılıncı her  yükselişin

sonu  yok derdi  çok bu  kör  gidişin

kısa  bir  yaşamda her  seslenişin

bilinmez  boyutları kör  noktası  var...', 'İnsanın  özünde ne   tutkular  var yükselme  hırsıyla  çıkmaza   dalar kendinden  verdikçe  çoğu  yakalar aza kanaat  etmez  ruhunu  boğar k...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kor-nokta-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İroni', 'i-roni-miri-arpaci-5kbif', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bulutlar altında bir adamım,

yağmuru beklerim.

Gariptir, herkes kaçar—

sanki bir ben kirliyim.

Eskidi yüzler,

eskidi yüzüm;

ve çığlık çığlığa

yaşadığım şimdi...

Bulutlar altında bir adamım,

ölümü bekliyorum.

Gariptir, herkes gülüyor—

sanki bir ben yaşıyorum.', 'Bulutlar altında bir adamım, yağmuru beklerim. Gariptir, herkes kaçar— sanki bir ben kirliyim. Eskidi yüzler, eskidi yüzüm; ve çığlık çığlığ...', ARRAY['Türk Edebiyatı','Şiir','Miri Arpacı']::text[], 8.5, '{"poet":"Miri Arpacı","poet_slug":"miri-arpaci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ironi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günün Kutlu Olsun Öğretmenim', 'gunun-kutlu-olsun-ogretmenim-fikret-kuscuoglu-wev5v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben seni

Edirne’de, Van’da, Gevaş’ta 

Bir kara tahta başında 

Kutsal vatan topraklarında 

Cumhuriyetin ilk harcı atılırken görmüştüm 

Bir kararlılık bir yaratıcılık vardı bakışlarında 

Güven veriyordu duruşun,

İnanç vardı gözbebeklerinde …

Taşa çamura uzanıyordu

Kalem tutan ellerin …

“Bu memleket, bu çocuklar benim” dedin

Günün kutlu olsun öğretmenim 

Ben seni,

Gencecik bir yedek subayken 

Menemen’de görmüştüm

Baş koymuştun çağdaşlığın yoluna

“Yeni biçilmiş bu gök ekin”

“Bu taptaze fidan”

“Bu gencecik cumhuriyet şehidi, kim” dedim

Hep bir ağızdan Mustafa Fehmi Kubilay dediler

Sonra, 

Yediden yetmişe

Cehaletle savaşı anlatırken görmüştüm seni.

Bir baktım, tohumu ıslah eden ziraatçı,

Bir baktım, ilkyardımı öğreten hemşire,

Bir baktım,barışın elçisi

Cumhuriyetin bekçisi olmuş,

Gönüllere dolmuşsun …

Günün kutlu olsun öğretmenim

Ben seni,

Güneydoğuda,

Bir dağ köyünde

Bir ilköğretim okulunun önünde

Karanlıkla nefes nefese bir gece yarısı,

Göğsünü teröre siper ederken görmüştüm.

Zar zor çıkıyordu ağzından kelimeler …

Seni pür dikkat ile dinledim …

“Bayrak dalgalanacak” dedin 

“İstiklal Marşı söylenecek” dedin 

Vatan uğruna, bayrak uğruna

153 şehit verdin …

Şimdi, bayrak da sensin

Vatan da sensin

Sana sadece öğretmen değil,

Kahraman densin …

Uykuların rahat,

Geleceğin umutlu

Günün kutlu olsun öğretmenim', 'Ben seni Edirne’de, Van’da, Gevaş’ta  Bir kara tahta başında  Kutsal vatan topraklarında  Cumhuriyetin ilk harcı atılırken görmüştüm  Bir ka...', ARRAY['Türk Edebiyatı','Şiir','Fikret Kuşçuoğlu']::text[], 8.5, '{"poet":"Fikret Kuşçuoğlu","poet_slug":"fikret-kuscuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/gunun-kutlu-olsun-ogretmenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollara Salan..', 'yollara-salan-nurdane-diken-1qibx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen benim 

Arzularımın tomurcuğusun 

Sevdamsın 

Gönül yaramsın 

Kanayan 

Yarınımsın, yaşanmayan 

Sen benim 

Hayat kaynağımsın 

Susuz kalan 

Sen güneşimsin 

Asla ısıtmayan 

Sen benim, kanımsın 

Damarlarımda dolaşan 

Asla bana ait olmayan 

Sen, kimin yârisin 

Benim olmayan 

Dillerde sürükleyen

Mecnun olup, yollara salan......', 'Sen benim  Arzularımın tomurcuğusun  Sevdamsın  Gönül yaramsın  Kanayan  Yarınımsın, yaşanmayan  Sen benim  Hayat kaynağımsın  Susuz kalan  ...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yollara-salan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazret-i Mevlânâ’ ya', 'hazret-i-mevl-n-ya-fikret-kuscuoglu-3e7x1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Erenlere danıştım, sana yüz sürmek için

Diller hasret çekiyor Hazret-i Mevlâna’ya

Nefsime savaş açtım,vuslata ermek için

Çöller susadım diyor Hazret’i Mevlânâ’ya

Esir aldı gönlümü Yunus’lar Mevlânâ’lar

Yanar yüreğim yanar, sönmez mahşere kadar

Yeme yetim hakkını, alma sakın intizar

Eller el amin diyor Hazret-i Mevlânâ’ya

Kulak verin Allah’a  yol şaşırıp azanlar

Gök kubbe boşluğunda yükseliyor ezanlar

Vecd ile sonsuzlukta, dönüyor semazenler

Dallar secde ediyor Hazret-i Mevlânâ’ya

Taşkın sellere döndü, sevenler coşa coşa

İnsan sevgisi denen gönüldeki buluşa 

Yüzler hepten çevrilmiş ilâhi kurtuluşa

Güller boyun eğiyor Hazret-i Mevlânâ’ya

Sihrine varmak için geldik şeb-i arusa

Şems-i Tebrizi aşkı, sığmaz evrene usa 

Seni hatmetmek için,zaman az,ömür kısa

Kullar rahmet diliyor Hazret-i Mevlânâ’ya', 'Erenlere danıştım, sana yüz sürmek için Diller hasret çekiyor Hazret-i Mevlâna’ya Nefsime savaş açtım,vuslata ermek için Çöller susadım diyo...', ARRAY['Türk Edebiyatı','Şiir','Fikret Kuşçuoğlu']::text[], 8.5, '{"poet":"Fikret Kuşçuoğlu","poet_slug":"fikret-kuscuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hazret-i-mevlana-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaş..', 'yas-nurdane-diken-oc2aw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Doğan güne hükmüm geçmez 

Aşk''ı anlamayanlara, nefesim yetmez 

Bu dünyaya gelen, ne yaptığını bilmez 

Ağlarım, gözlerimden yaş gelmez. 

Kaderin önünde bir yaprağım 

Savrulur giderim 

Kendime sözüm geçmez 

Bu deli gönül, halden anlamaz. 

Yıkar perişan eder, bentleri 

Sular dayanmaz 

Sevgide kılmış kararı 

Arar da bulamaz.

Bıktım, usandım senden 

Bir karar ver, geç kalmadan! 

Viran ettin, gönül bağını 

Kendinle, savaş hiç edilmez. 

Vazgeç aşk''ı aramaktan 

Yoruldun, bunca savaşlardan 

Mağlup oldun, yaşından 

Bir sevgili, bekleme telaşından.....', 'Doğan güne hükmüm geçmez  Aşk''ı anlamayanlara, nefesim yetmez  Bu dünyaya gelen, ne yaptığını bilmez  Ağlarım, gözlerimden yaş gelmez.  Kade...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yas-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Basit -deve, aslan, çocuk-', 'basit-deve-aslan-cocuk-miri-arpaci-xutp8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '–deve, aslan, çocuk-

Uzansam, gökyüzüne dokunacağım.

Ağlasam, eriyip deniz olacağım.

Bu kadar basit olasılıklar:

Konuşsam, boşalıp yel olacağım.

Yürüyorum, sokak misali zamanda.

Dursam, kök salıp ağaç olacağım.

Israrla reddedip önüme bakıyorum,

Bir dönsem, patlayıp dağ olacağım.

O kadar sıradanlaştı ki basitlik;

Mükemmel hissediyor insan.

Yaşıyorum diye aşığım —

Sadece aşığım diye yaşayacağım.

Bıraksam yüreğimin zincirini,

Yüklenip evreni deve olacağım.

Biliyorum artık:

Kesişmeyecek hiçbir zaman

Düşlerimle gün.

Yine de yatıp kalkacağım,

Kırsam beynimin prangasını,

Saldırıp kin ile aslan olacağım.

Bir cebimde güneş,

Bir cebimde ay —

Bir dönsen,

Yeniden çocuk olacağım.', '–deve, aslan, çocuk- Uzansam, gökyüzüne dokunacağım. Ağlasam, eriyip deniz olacağım. Bu kadar basit olasılıklar: Konuşsam, boşalıp yel olaca...', ARRAY['Türk Edebiyatı','Şiir','Miri Arpacı']::text[], 8.5, '{"poet":"Miri Arpacı","poet_slug":"miri-arpaci","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/basit-deve-aslan-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolu Boşluk', 'dolu-bosluk-adem-tok-ost7m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hücremden neler çıkarabilirim sana

dur şöyle bir bakim:

bana bürünen cansız bir beden

ve ''görülmüştür''lü bir davetiye; 

gel diye...

defne yapraklarım fısıldıyor mu hâlâ

arasında defterlerimin

onlara mavilik yükleyecektim

içerdekim için

için için...

bana mersinlerden bahsetme

var olsunlar

-küskünlüklerim çok

aramıyorlar...-

yıldızların soluk alışı sende kalsın

yorgun uykuların doruklarından

bir demet kır çiçeği uzatırsın

görülmezin dışını bilirim...

sevgilerim intihar ediyor bir bir

dur bakim kim kaldı:

BİRSEN! ..

-SENSİZLİKLERİMİ TENİNDE ERİYİP GİTMEYE ARZULADIM-

ölüm değil hücreler

çakılınmaz boşluk

aktıkça dolan irtifa...

kırılmayı özledim

bir kaç damla

sarya...

-yüreğinde taşımadığını memleketinde de taşıma-

                                                                           (10.06.04) 

                                                                           f tipi hapishane EDİRNE', 'hücremden neler çıkarabilirim sana dur şöyle bir bakim: bana bürünen cansız bir beden ve ''görülmüştür''lü bir davetiye;  gel diye... defne ya...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/dolu-bosluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlar Rıhtımı..', 'yalnizlar-rihtimi-nurdane-diken-cid1i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gidenlerin, gelmediği 

Sevenlerin, sevilmediği bir rıhtım 

Yalnızlar rıhtımı. 

Uçsuz, bucaksız denizlerin çevrelediği 

Dağların geçit vermediği 

Sevenlerin, sefâ görmediği 

Azgın dalgaların, cılız tahtaları ezdiği 

Sevenlerin, sevilenleri beklediği 

Ne bir mendilin, sallandığı 

Ne bir haberin, gönderildiği 

Aşk''ların bitirilip de, bitmediği 

Bir ümit kırıntısı için, beklendiği 

Yağmurların yağıp, aşıkların ıslanmadığı 

Karın ve tipinin değmediği 

Hala gidenlerin, beklendiği 

Yalnızlar rıhtımı. 

Hangi giden döndü, bu rıhtıma 

Hangi vurgun yiyen çıktı, bu denizden 

Hangisi sonunda zehiri, yutmadı ki! 

Bu rıhtıma girildi mi, bir daha dönüş yok 

Sevmek için, zaman çok 

Zamanı kullanan yok 

Sevenlerin diyarında da 

Yalnızlar rıhtımı çok.......', 'Gidenlerin, gelmediği  Sevenlerin, sevilmediği bir rıhtım  Yalnızlar rıhtımı.  Uçsuz, bucaksız denizlerin çevrelediği  Dağların geçit vermed...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yalnizlar-rihtimi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözbebekleri', 'gozbebekleri-gulseren-onay-ltc2m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Oysa 

İnanacaktım sana...

Her kaçamak

Bakışında,

Geçmeseydi

Yaşanmışlıklarının 

Film şeridi...

Derinde, 

Gözbebeklerinde 

Gizleyebilseydin 

Gerçekleri...', 'Oysa  İnanacaktım sana... Her kaçamak Bakışında, Geçmeseydi Yaşanmışlıklarının  Film şeridi... Derinde,  Gözbebeklerinde  Gizleyebilseydin  ...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gozbebekleri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıktım Aşkın İle Dağlara', 'ciktim-askin-i-le-daglara-kamil-soylemez-78nbd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çıktım aşkın özleminle dağlara

Bayrak astım geceden sabahlara

Dalga dalga sen gezdim yaşlarımla

Sen süzdüm dudağımda damağımda

Çıkıp gelmedin sense hayatıma

Ne çıktı yoluna neydi engelin

Seni ne üzdü söyle be dilberim

Yoksa bilki kör olucak gözlerim

Dilim tutulup,düşüp öleceyim

Sen gelmezsen bilki ben geleceyim

Sevgin özlemin zembili sırtımda

Haydi çıkta gel bu garip adama', 'Çıktım aşkın özleminle dağlara Bayrak astım geceden sabahlara Dalga dalga sen gezdim yaşlarımla Sen süzdüm dudağımda damağımda Çıkıp gelmedi...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ciktim-askin-ile-daglara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan oldun..', 'yalan-oldun-nurdane-diken-0dahr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalan, ellerinin sıcaklığı ellerimde. 

Yalan, sarfettiğin söyleyeceğin sözlerin. 

Yalan, tüm arzulayışların, ihtirasların. 

Yalan, beni daim seveceğin, sevgilerin. 

Yalan, varlığınla hep yok olmaların senin. 

Yalan, geceler boyunca hep yalvarışların. 

Yalan, geceler boyunca hep sevişmelerin. 

Yalan, sahte tavırların, duygu sunmaların. 

Yalan, beni kandıracağın, kandırışların. 

Yalan, varlığınla hep yok olmaların senin. 

Yalan, sonsuz isteyeceklerin, isteklerin. 

Yalan, sevip de sevildiğini, bilmediğin. 

Yalan makinesine döndün sen bir sevgilim. 

Yalanlarınla, kendin kendin kandın, sevgilim. 

Yalancı dünyada, sen yalan oldun sevgilim.....', 'Yalan, ellerinin sıcaklığı ellerimde.  Yalan, sarfettiğin söyleyeceğin sözlerin.  Yalan, tüm arzulayışların, ihtirasların.  Yalan, beni daim...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yalan-oldun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkadır Aşıklığım', 'askadir-asikligim-zeki-ergin-wx4h3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yağmurlu dağlardan gelmişim ben

susuz topraklara

sevdalı pınarlaradır 

özlemi 

çorak yüreğimin

susuzluğum   bundandır can

sevgiye sevdaya

ve aşkadır  aşıklığım

_gülpınar 18kas05

_dağlara ver sırtını haz09', 'yağmurlu dağlardan gelmişim ben susuz topraklara sevdalı pınarlaradır  özlemi  çorak yüreğimin susuzluğum   bundandır can sevgiye sevdaya ve...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/askadir-asikligim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aferin', 'aferin-recep-uslu-2uzkj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gencecik körpe kızlar

Güzel mi güzel kadınlar

Şiire sahip çıkmışlar

Hey şuna bak yahu

Hani biz erkektik.

Doğa bizden yana

Fizik olarak güçlüyüz

Tanrı bizden yana

Onlardan

Bir.iki.üç.dört tane alabiliriz

Hatta...

Cariye yapabiliriz.

Hey! Arkadaş

Şuna bak yahu...

Gencecik gencecik kızlar

Güzel mi güzel kadınlar

Şiire sahip çıkmışlar.

Hani biz erkektik? 

Yürürken bile

Bir adım geriden geleceklerdi

Kara çarşafa bürünüp

Kendilerini gizleyeceklerdi.

Birilerinin dediği gibi

Soframızda koca öküzden sonra

Konuşulacaktı.

Öyle demediler mi yıllarca? 

Hala da öyle değil mi? 

Şuna bak ya hey! 

Gencecik körpe kızlar

Güzel mi güzel kadınlar

Şiire sahip çıkmışlar.

Babamdan değil

Dedemden de değil

Büyük dedemden bana

Bir aferin vardı

Onu da size verdim

07.12.2000', 'Gencecik körpe kızlar Güzel mi güzel kadınlar Şiire sahip çıkmışlar Hey şuna bak yahu Hani biz erkektik. Doğa bizden yana Fizik olarak güçlü...', ARRAY['Türk Edebiyatı','Şiir','Recep Uslu']::text[], 8.5, '{"poet":"Recep Uslu","poet_slug":"recep-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/aferin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçemem Senden....', 'vazgecemem-senden-nurdane-diken-qoe1v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni düşündüm, batan günün üstüne 

Seni düşündüm, yağan nur''un üstüne 

Seni düşündüm, güzel sözün üstüne 

Çağlayanım oldun, yağansın üzerime. 

Şansım açan güneşler üzerine 

Hayaller kuruyorum, yarınlar üzerine 

Yıldızlar yağıyor, hep üzerime 

Sevgini taşıyorum, tüm bedenimde. 

Yemin ettim, seni sevmek üstüne 

Bütün haramiler gelse üstüme 

Vazgeçemem senden, Allah üstümde 

Ellerin ellerimde, mutluluğun içimde......', 'Seni düşündüm, batan günün üstüne  Seni düşündüm, yağan nur''un üstüne  Seni düşündüm, güzel sözün üstüne  Çağlayanım oldun, yağansın üzerime...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vazgecemem-senden-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vapurdaki Bebek...', 'vapurdaki-bebek-nurdane-diken-wmd99', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen her sabah, gel otur karşıma. 

Dünyamı yıka, gülüşünle. 

Gözlerin, gözlerime değsin, 

Bin öldür, beni bakışınla.. 

Limanda gemiler ağlasın. 

Sevinçle dolsun, kalbimin içi. 

Ve sen benim, şiirim ol bebek. 

Öptüğüm zaman, gözlerin parlak.. 

Okşadığım anlar, dumanlı olsun. 

Öylesine gül ki fûtursuz, mat, 

Yaşadığımı duymak istiyorum......', 'Sen her sabah, gel otur karşıma.  Dünyamı yıka, gülüşünle.  Gözlerin, gözlerime değsin,  Bin öldür, beni bakışınla..  Limanda gemiler ağlası...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/vapurdaki-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyku..', 'uyku-nurdane-diken-9o3zv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yıldız gibi, üstüme yağdın 

Mutluluk verdin 

Ümit ettim 

Sevindim 

Huzur buldum 

Arzu ettim 

Hislerimi uyandırdın 

Makus talihimi, yendim dedim 

Işığını, çok sevdim 

Ama nasıl oldu, bilmiyorum 

Birden, sabah oldu 

Uyandım 

(10.7.2004-00.25)', 'Bir yıldız gibi, üstüme yağdın  Mutluluk verdin  Ümit ettim  Sevindim  Huzur buldum  Arzu ettim  Hislerimi uyandırdın  Makus talihimi, yendi...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/uyku-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyanamadım....', 'uyanamadim-nurdane-diken-gcvc4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne çok sevgiler tattım. 

Tuzu hala dilimde. 

Ne sevgiler yaşadım. 

İzi hala kalbimde. 

Ne güzel günler, gördüm. 

Resmi var gözlerimde. 

Ne acılar yaşadım. 

Tortusu var, ruhumda. 

Ne neş''eler yaşadım. 

Coşkusu hala bende. 

Ne dost''luklar gördüm. 

Acısı var, içimde. 

Ne kışlar gördüm, dondum. 

Bahara eremedim. 

Ne çok rüyalar gördüm. 

Gündüzleri şaşkındım. 

Ne vurgunla sarsıldım. 

Hemen ayağa kalktım. 

Ne bu dünyaya doydum. 

Ne sevgiden usanmadım. 

Bir ömrü heder ettim. 

Yine uyanamadım.....', 'Ne çok sevgiler tattım.  Tuzu hala dilimde.  Ne sevgiler yaşadım.  İzi hala kalbimde.  Ne güzel günler, gördüm.  Resmi var gözlerimde.  Ne a...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/uyanamadim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayacağı dilden', 'anlayacagi-dilden-kadir-albayrak-vsipx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şarlatanın biri kalabalık içinde

Bir sual sormuş aksakallı alim-e

Kendince zor bir soru ''Alim tekleyecek''

Halka gösterip onu haliyle eğlenecek

Demiş ki; Ey alim kişi; Sen li ulemasın

Soracağım sorunun cevabını bulmalısın

''Cenab-ı Allah insanı yarattığı zaman,

Maya olarak kullandığı çamura koydu mu saman? ''

Alim kişi imamların hatırlatıp sözlerini

''O çamur saftır'' dedi ''yoktur başka bir nevi''

Şarlatan olmaz dedi...,Beni tatmin etmedi

Daha inandırıcı ol bizi ikna et dedi

Alim Resulullahın söyledi hadisini

''İman inanç işidir herkes kabullenmeli''

Şarlatan alaylı bir bıyık altı gülüşle

''Bu adam yalancı'' dedi dönüpte ahaliye

Alim kişi düşündü! ... Ayeti okumalı

Çünkü ayet kul değil o Allahın kelamı

Herşey tartışılır belki ama ayetler asla

Anladığı dilden konuşurum buna da inanmazsa

Alim ayetleri baştan sona okudu

Okurken kafasında bir başka ''dörtlük'' kurdu

Şarlatan cık cık dedi.. anlamak değil niyeti

Cevabı zayıf bulup rezil etmek alimi

Alim gayet sakin doğruldu göz attı ahaliye

''Cevap vereceğim'' dedi ''Ben bu hınzır zübüğe''

Sizler sakın alınmayın söyleyeceklerimden

Konuşacağım onunla ben ''Anlayacağı dil-den''

''Ey tıynet-i Ademin çamurun da saman var mı diyen

Gel etme bana bu sual-i ham-ı

Eğer olsaydı beşeriyetin çamurun da saman

Çatlayıp ta yarık olmazdı ananın a.....', 'Şarlatanın biri kalabalık içinde Bir sual sormuş aksakallı alim-e Kendince zor bir soru ''Alim tekleyecek'' Halka gösterip onu haliyle eğlenec...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/anlayacagi-dilden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttun..', 'unuttun-nurdane-diken-qdizs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Unutmam gözlerinin güzelliğini, 

Bu renklerini derdin''... 

Ne oldu ayrıldın da sanki 

Unutmadın mı? ... 

Unutmadınsa beni değil,gözlerimin 

Rengini arasaydın, 

Orada beni bulurdun. 

Ama ne yazik ki onu da unuttun...', 'Unutmam gözlerinin güzelliğini,  Bu renklerini derdin''...  Ne oldu ayrıldın da sanki  Unutmadın mı? ...  Unutmadınsa beni değil,gözlerimin  ...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/unuttun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Çay Hali', 'askin-cay-hali-ulas-guleviz-fdibx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'tam  demimdeyim

kaynamakta  olan  bir  çay  gibi

çağımız  geçmeden  hani

ekle  deme  kendini

bekle  deme

acırım', 'tam  demimdeyim kaynamakta  olan  bir  çay  gibi çağımız  geçmeden  hani ekle  deme  kendini bekle  deme acırım...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Güleviz']::text[], 8.5, '{"poet":"Ulaş Güleviz","poet_slug":"ulas-guleviz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/askin-cay-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unut Beni..', 'unut-beni-nurdane-diken-595b9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bana öyle bakma, ne olur! 

Suçlama beni. 

Ayrılık çanı çaldı, 

Ne mendil sallayan var. 

Gözyaşları içe akan bir sel gibi 

Boynunu bükme ne olur! 

Bir gün seni de, seven bulunur. 

Benim sana verdiğim sevgi, 

Bizi birbirimizden ayırdı. 

Yanıma otur deme, ne olur! 

Aşk ateşi bu, ikimizi de kavurur. 

Kalbim dayanamaz buna 

Güzel günler, gecelerdi 

Hadi git, durma ne olur! 

Yalnızlığımın içine, bırak beni 

Girdapların içinde kaybolan, 

Bir zerre gibi, unut beni. 

Git hadi, durma git! 

Unut beni...............', 'Bana öyle bakma, ne olur!  Suçlama beni.  Ayrılık çanı çaldı,  Ne mendil sallayan var.  Gözyaşları içe akan bir sel gibi  Boynunu bükme ne o...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/unut-beni-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Handa bir yolcu.', 'handa-bir-yolcu-i-shak-ozlu-pocyd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün gelir,

Handa bir yolcu,

Bırakır ekmeğini suyunu,

Yetişmek için öncekilere.

Sıcak değildir yatağı,

Görünmez aynalarda suratı.

Telaşlı handakiler,

Farketmezler eksilen bir yolcuyu.

Sıranın gelmesinden habersiz,

Oynayan gölgelerde,

Kimi gözyaşlarında,

Kimi kahkahalarda,

Girer sonsuz karanlıklara,

Ruhlarının aydınlığında.

Eksilen bir yolcu,

Farkedilmez handa.

Ha bir eksik,

Ha bir fazla,

N e farkeder ki,

Dünde böyleydi,

Yarında............', 'Gün gelir, Handa bir yolcu, Bırakır ekmeğini suyunu, Yetişmek için öncekilere. Sıcak değildir yatağı, Görünmez aynalarda suratı. Telaşlı han...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/handa-bir-yolcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Fakirin Değişti Huyu', 'bu-fakirin-degisti-huyu-mehmet-akif-tiryaki-qzvcu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu fakirin değişti huyu,

Sevdiğim yerler; Levent Zincirlikuyu

Metro city de birşeyler atıştıralım,

Ak merkezden ayakkabı alalım.

Etiler Venüs''te yiyelim pasta,

Nasıl olsa hisse senetleri takasda.

Çbs bu gün tavan yapacak,

Bizim brokır çakdıkça çakacak.

Bu fakirin değişti huyu,

Sevdiğim yerler; Levent Zincirlikuyu

Kabirhizmetini açtım site paralar gelsin,

İstinye''de öğlen yemeğine ne dersin? 

Bebek''ten badem ezmesi alalım,

Akşama doğru dövizciye dalalım.

Bozduralım doları alalım Tl,

Senin devlet tahvili neyine? 

Yatır hepsini Çbs ye, tavan yapacak neredeyse.

Hava kararıyor dönelim haydi eve,

Yarın gene gezecek yer buluruz nasıl olsa,

Ah senetlerimde tavan olsa? 

Olmasa da acelem yok,

Nasıl olsa cepte para çok.

Bu gün alamadım bir plaza dairesi,

Yarın inşallah alırım yaşasın toki,

Halkalı toplu konut gerekmez kroki.

Günler alış veriş yapmadan geçmiyorki.', 'Bu fakirin değişti huyu, Sevdiğim yerler; Levent Zincirlikuyu Metro city de birşeyler atıştıralım, Ak merkezden ayakkabı alalım. Etiler Venü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bu-fakirin-degisti-huyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Ötesi', 'mavi-otesi-ulas-guleviz-ebrdd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Odamı  doldursaydı  gözlerin, yalnızlığımı.

Bakışların,  inseydi  yüreğimin  gizemine 

ve  mavi  ötesi  bir  dünya  olsaydık  seninle.

  Beyazın  masumiyetini  çalmış  ve  üzerine  giymişsin.

Bu  özellik  benim  zayıf  yanım, sen  belki  bilmezsin.

Sen  benim için, çiçeklerde  gezinen  bir  kelebeksin.

Ve  bilmelisin ki  mavi  ötesi  bir  gezintidesin, bendesin.

  Senin, kırmızı  ötesi  bir  sıcaklığın  var.

Ve  korkuların...

Korkuların, sonbaharın  bu  şehirden  gitmesiyle  son  bulacak,

Ama  benimkiler  belki de  hep  benimle  kalacak.

Biliyorsun, çiçekler  sonbahardan  sonra  yeniden  açacak.

Ve  umarım, kelebeğim  mavi  ötesine  uçacak...', 'Odamı  doldursaydı  gözlerin, yalnızlığımı. Bakışların,  inseydi  yüreğimin  gizemine  ve  mavi  ötesi  bir  dünya  olsaydık  seninle.   Bey...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Güleviz']::text[], 8.5, '{"poet":"Ulaş Güleviz","poet_slug":"ulas-guleviz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mavi-otesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ulaşamadığım...', 'ulasamadigim-nurdane-diken-30eal', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ellerimi uzatıyorum, sen yoksun 

Rüyalarımda dokunuyorum, kaçıyorsun! 

Kalbine, taht kurmak istiyorum, itiyorsun 

Söyle küçüğüm, sen bana ne yapıyorsun! 

Seni sevgimle, büyütmek istiyorum. 

Kırlardan, papatyalar toplayıp, vermeliyim 

Benim kralım,sen olmalısın 

Özgür''ce beni sevmelisin 

Tahtının önünde, diz çökmeliyim 

Saygı yerine, sonsuz sevgimi sunmalıyım 

Güneşi yerinden koparıp, ellerine vermeliyim 

Gücüne, güç katıp, seni yüceltmeliyim 

Sen, benim mabudum''sun 

Bense, mabuden 

Söyle, küçüğüm 

Kraliçen senin için, ne yapsın 

Sen, benim ulaşamadığım 

Zamanların, gerisindesin 

(15.01.97_ist)', 'Ellerimi uzatıyorum, sen yoksun  Rüyalarımda dokunuyorum, kaçıyorsun!  Kalbine, taht kurmak istiyorum, itiyorsun  Söyle küçüğüm, sen bana ne...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ulasamadigim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-guzin-eye-dundar-bl9jj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yutacak   beni  birgün

bu   beton   şehir

kafeste  tutsak

maddeye  esir

her  soluk   zehir

soluk  renkler  içinde

...... İnadına  yeşil', 'yutacak   beni  birgün bu   beton   şehir kafeste  tutsak maddeye  esir her  soluk   zehir soluk  renkler  içinde ...... İnadına  yeşil...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/korku-104-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yengen', 'yengen-gul-ozan-vi7yu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ufacık bir kadındı yengen,

çoğalırdı baktıkça, 

öyle sevimli...

Ve bu fotoğraftaki gibi,

sen hep öyle uzak görünür,

yakın duyulurdun...

Başka şey yoktu, şiirler için,

senle bakışmak kadar verimli...', 'Ufacık bir kadındı yengen, çoğalırdı baktıkça,  öyle sevimli... Ve bu fotoğraftaki gibi, sen hep öyle uzak görünür, yakın duyulurdun... Başk...', ARRAY['Türk Edebiyatı','Şiir','Gül Ozan']::text[], 8.5, '{"poet":"Gül Ozan","poet_slug":"gul-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yengen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İktidar', 'i-ktidar-guzin-eye-dundar-javkd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İktidar  yüksekte  huma  kuşudur

küçük  bir hayatta  zorlu  koşudur

altın  tepelerin  sarp  yokuşudur

ellerini  yakar  tutmasını  bil

sakın  ola  uğruna  verme  bendini

çok  sevmekten  kaçın  kolla  kendini

yüreğine  iner   yakar  tenini

kıymetini  bilene  sunmasını bil...', 'İktidar  yüksekte  huma  kuşudur küçük  bir hayatta  zorlu  koşudur altın  tepelerin  sarp  yokuşudur ellerini  yakar  tutmasını  bil sakın ...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/iktidar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesaj', 'mesaj-murat-demir-qg4i4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mesajları popüler edenlerce

Okunmazsa şiirlerim ne yazar,

Kusura bakmayınız 

Beni antoloji yapar mısın diyenler,

Bu pazar beni bozar.', 'Mesajları popüler edenlerce Okunmazsa şiirlerim ne yazar, Kusura bakmayınız  Beni antoloji yapar mısın diyenler, Bu pazar beni bozar....', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mesaj-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aç Ya da Kapat', 'ac-ya-da-kapat-kadir-albayrak-navvx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Arada bir yerde ''sıkışıp kalmak'' istemem

Vurmuşsam gönül kapını

Ya ''sonuna kadar açacaksın''

Ya da ''Kapıdan kovacaksın''

Karar vereceksen eğer,

Bu ''vicdanının'' değil

''Yüreğinin'' sesi olmalı

Ve... Konuşurken duyulmalı

Her yürekte dost ta barınır yaren de

Lakin her biri  ''farklı yerlerde''

Ev sahibi isen adil olacaksın

Ve herşeyi yerine oturtacaksın

Kapını çalan misafir de olabilir

Dilenci de! .... Yorum senin

İkram da gerekebilir sadaka da

Karar senin! ....

Lakin mecbursun! ..Ya kapıyı çarpacaksın

Ya da alabildiğina açacaksın

Kapının ardın da asla ama asla

Saklanmayacaksın! ....

Unutma ki; Kapıda bekleyenler,

Açılmayan kapıların ardını,

Çok iyi bilirler! ..

Ve...Boyunlarını bükmeyi de! ....

Kovulmak ''Bilinmemekten''

Reddedilmek ''Beklemekten''

Daha evladır! ..

Çünkü; Her yolun bir sonu vardır! ..', 'Arada bir yerde ''sıkışıp kalmak'' istemem Vurmuşsam gönül kapını Ya ''sonuna kadar açacaksın'' Ya da ''Kapıdan kovacaksın'' Karar vereceksen eğer...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ac-ya-da-kapat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rabbime Şikayet', 'rabbime-sikayet-cavidan-kadioglu-4wwwu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nice dert yüklendi bu ondokuz yaşa

Yana yıkıla geldim ben tek başa

Ayağım takıldı hep çakıla taşa

Affet beni isyankar değilim, haşa! 

Daha çok sürer bu karmaşa

Bunca emek heba oldu gitti boşa

Güven olmaz ne dosta ne kardaşa

Affet beni isyankar değilim, haşa! 

Söz söylendi gözüm üstünde kaşa

Zehir katıldı ekmeğe, aşa

Neden taç olamam hiç bir başa

Affet beni isyankar değilim, haşa! 

Bu halimi duyanlar bana şaşa

Garibin sırtından olunur paşa

Belki anam ağlar benim naaşa

Affet beni isyankar değilim, haşa! 

Mayıs,1999', 'Nice dert yüklendi bu ondokuz yaşa Yana yıkıla geldim ben tek başa Ayağım takıldı hep çakıla taşa Affet beni isyankar değilim, haşa!  Daha ç...', ARRAY['Türk Edebiyatı','Şiir','Cavidan Kadıoğlu']::text[], 8.5, '{"poet":"Cavidan Kadıoğlu","poet_slug":"cavidan-kadioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/rabbime-sikayet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göremezsin Sevdiğim', 'goremezsin-sevdigim-guzin-eye-dundar-ppd29', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Körelmiş  duyuların  ivintisinde  yitirdin

en saf  en güzel  sevgileri

en bakir yaşlarla 

nemlendi  dudakların

seni ne  büyük  umutlar

ne  mutluluklar  yokladı

bilmezsin....

ve... öylesine değiştim

bir gün dönümü  mesafede

ne  temiz  duyguları

ne de sana sakladığım  sevgilerin

göremezsin  parıltılarını 

gözlerimde  sevdiğim

göremezsin...

                                          .kültür kitapçılıkve yayın şti.ANKARA 1962 Antoloji', 'Körelmiş  duyuların  ivintisinde  yitirdin en saf  en güzel  sevgileri en bakir yaşlarla  nemlendi  dudakların seni ne  büyük  umutlar ne  m...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/goremezsin-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Angaryasın', 'angaryasin-kadir-albayrak-xucrd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu kez de başkasına

Şiir yazacağım

İçinde sen,

Ve senden hç bir şey olmayacak! 

Adını bile sormayacağım

Şiir bitene dek

Belki de seni unutacağım! 

Zaten sen de başkası değil misin? 

Hatta herhangi biri 

                               -Cevap verir misin? 

Bu defa başka biri olarak,

Şiirimdesin! 

Ama sen o değilsin Lütfen haddini bil! ..

Şiirlerimden gider misin? 

Sana uymuyor satırlarım

Uysaydı hatırlardım! 

Çağıran bendim seni

                                  -Kovmakta benim hakkım! ..

Direnirsen sen bilirsin! 

Kırarım kalemi

Yırtarım tüm kağıtları

Silinirsin! ...

Sen ''şiirlerimle varsın''

Ben yazarsam yaşarsın! ..

Yazmıyorum artık anasını satayım

İşte ''ANGARYASIN! ......''', 'Bu kez de başkasına Şiir yazacağım İçinde sen, Ve senden hç bir şey olmayacak!  Adını bile sormayacağım Şiir bitene dek Belki de seni unutac...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/angaryasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '## Kasım ##', 'kasim-sanem-deniz-dmudb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tozunu alamadan

Geçen senenin

Yine omzuma düştü

Kirli nefesin

Kaçmalı kovalandıkça,

hızlan izzet-i nefsim,

Durursan düşeceksin

yaman kollara...

Şimdi...

Gökkuşağına sarıpta

Hediye ettiğin hüzünleri

Gel de geri al...

Yetmedi mi? ? 

Gökten yağan damlalar...

İnsaf eyle  be Kasım! !', 'Tozunu alamadan Geçen senenin Yine omzuma düştü Kirli nefesin Kaçmalı kovalandıkça, hızlan izzet-i nefsim, Durursan düşeceksin yaman kollara...', ARRAY['Türk Edebiyatı','Şiir','Sanem Deniz']::text[], 8.5, '{"poet":"Sanem Deniz","poet_slug":"sanem-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kasim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Unutma Arkanı', 'hey-unutma-arkani-nuri-ozoglu-ywvdv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hey unutma arkanı önüne bak,

Zaman gelecek, gökten inecek ak,

Sana engel olan yolları yak,

Kurumuş, kül olmuş, zarar veremez.

Ol milletinin bir hadimi,

Müstenit etki, kaçır zalimi,

Bırakırsan yaban elde talimi,

Gittiğin yollara hain giremez.

Şuurunu yitirme, simanı gör,

Seni görmeyen gözler bile kör,

Hakikatı inkar eden sayfaları dür,

Bir daha seni de inkar edemez.', 'Hey unutma arkanı önüne bak, Zaman gelecek, gökten inecek ak, Sana engel olan yolları yak, Kurumuş, kül olmuş, zarar veremez. Ol milletinin ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Özoğlu']::text[], 8.5, '{"poet":"Nuri Özoğlu","poet_slug":"nuri-ozoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hey-unutma-arkani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-fatma-karakoyun-p2y53', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güller bahçesinde geçse de yıllarım

Senden başkasının olmaz kalbim

Seni ve sensizliği düşünüyorum yine

Gündüze dönmeyen geceler gibi

Sensizliği anlatmam çok zor

Ben seni bir tesadüfle tanıdım

Sensizliği ise seni tanıyınca

Kimi zaman yağmurdan sakladım göz yaşlarımı

Gecelerin gizeminde aradım aşkımı

Bak bu gece sahilde

Denizle buluştu mehtap

Bir sağnak yağmur yıkarsa yaralarımı

Yumuşayacak gecenin vakti

Sensizliği anlatmam çok zor

Yağmur yıkasa da yaralarımı

              Fatma KARAKOYUN

                                          16.10.2005', 'Güller bahçesinde geçse de yıllarım Senden başkasının olmaz kalbim Seni ve sensizliği düşünüyorum yine Gündüze dönmeyen geceler gibi Sensizl...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sensizlik-219-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum', 'korkuyorum-fatma-karakoyun-02ki7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen benim gökyüzümdeki

Yıldızımsın diyemiyorum 

Kayar bir gün düşersin diye korkuyorum

Güneşimsin diyemiyorum

Batarsın diye korkuyorum

Sen öyle büyüksün ki sana

Nazar değmesinden korkuyorum

Hayatın mum ışığında kurulmuş

Bir tılsım sen tılsımlardan oluşmuş kıvılcım

Sönersin diye korkuyorum

Korkularım kadar gerçek

Dudaklarım titriyor konuşamıyorum

Sensin ümidim sensin yarınlarım

Seni seviyorum demeye korkuyorum...

                                 14.10.2005', 'Sen benim gökyüzümdeki Yıldızımsın diyemiyorum  Kayar bir gün düşersin diye korkuyorum Güneşimsin diyemiyorum Batarsın diye korkuyorum Sen ö...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/korkuyorum-122-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lüzum Kalmadı', 'luzum-kalmadi-kadir-albayrak-dz8ly', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yarasın içim de usul usul kanayan

Geri döneceğinden hiç umudum kalmadı

Nasılsa senden sonra ne arayan ne soran

Olmasa da fark etmez artık lüzum kalmadı

Sonbaharımsın benim yaprak yaprak sararmış

Dalımda tomurcuğum çiçeklerim olmadı

Öyle bir güneşsin ki sabahlarda kararmış

Doğmasan da fark etmez artık lüzum kalmadı

Sen çok uzaklardasın tıpkı mutluluk gibi

Seni öpüp koklamak bana kısmet olmadı

Olur da eşe dosta sual ederek beni

Sormasan da fark etmez artık lüzum kalmadı', 'Bir yarasın içim de usul usul kanayan Geri döneceğinden hiç umudum kalmadı Nasılsa senden sonra ne arayan ne soran Olmasa da fark etmez artı...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/luzum-kalmadi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Menekşe Gözlüm', 'menekse-gozlum-fatma-karakoyun-v6iar', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bebeğim senden sonra sevmem imkansız

Ölürümde vaz geçmem senden 	

Bebeğim menekşe gözlüm

Gözlerin esir ediyor kendine

Kapama gözlerini bir ömür ak içime

Bebeğim kollarımda hoplatırım

Ölürümde vaz geçmem senden

Bebeğim menekşe gözlüm

Bir seni görüyorum bir senle yaşıyorum

Rüyalarımdaki hasretimdin sen

Bebeğim senden sonra sevmem imkansız

Ölürümde vaz geçmem senden 

Bebeğim menekşe gözlüm

Bebeğim bebeğim..

                   12.12.2005', 'Bebeğim senden sonra sevmem imkansız Ölürümde vaz geçmem senden 	 Bebeğim menekşe gözlüm Gözlerin esir ediyor kendine Kapama gözlerini bir ö...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/menekse-gozlum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-fatma-karakoyun-cfrca', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gece dokunsalar ağlayacağım 

Bu gece hoşça kal demeyeceğim

Çok yalvardın gitme diye

Gözlerimde anılar hala yeşil ise

Bu gece hoşça kal demeyeceğim

Denize dökülen ırmak gibiyim gözlerinde

Bu gece dokunsalar ağlayacağım

Hasret dolu her yanım

Bu sensizlik mahvediyor beni canım

Gökyüzünde bir bulut olduğumu düşün ve kaybolduğumu

Karanlık gitgide çekiyor beni

Bu gece hoşça kal demeyeceğim

Sevdamızdan kimseye bahsetmeyeceğim

Aşkım ipekböceğim

Sana son kez sarılacağım

Bu gece hoşça kal demeyeceğim

Şimdi ne yaparsan boş

Karanlık gitgide çekiyor beni

Sevdamızdan kimseye bahsetmeyeceğim

Aşkım ipekböceğim

Sana son kez sarılacağım

Bu gece hoşça kal demeyeceğim...

               Fatma KARAKOYUN

                                            12.10.2005', 'Bu gece dokunsalar ağlayacağım  Bu gece hoşça kal demeyeceğim Çok yalvardın gitme diye Gözlerimde anılar hala yeşil ise Bu gece hoşça kal de...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-gece-169-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var mısın', 'var-misin-ozan-ozel-8ihj5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sen, içimde taşıdığım 

canlı bir bombasın 

sevmemden patlayacaksın 

biliyorum; öleceğiz... 

ben, içinde taşıdığın 

canlı bir bombayım 

sevmenden patlayacağım 

biliyorsun; öleceğiz... 

var mısın daha çok sevmeye 

birlikte yaşamaya var mısın', 'sen, içimde taşıdığım  canlı bir bombasın  sevmemden patlayacaksın  biliyorum; öleceğiz...  ben, içinde taşıdığın  canlı bir bombayım  sevme...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/var-misin-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affettim mi Bilmeyeceksin', 'affettim-mi-bilmeyeceksin-kadir-albayrak-c8egd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gün olur da sana dön desem bile

Nasılsa geriye dönmeyeceksin

Fırtınalar esen şu yüreğimde

Neler yıktı neler bilmeyeceksin

Tükenir içimde her akşam umut

Biterse bir daha vermeyeceksin

Dört kişi omzunda gider bir tabut

İçinde kim vardır bilmeyeceksin

Gururun sevgine engel olacak

Belki de göz yaşı dökmeyeceksin

Korkarım ki aklın bende kalacak

Seni affettim mi bilmeyeceksin', 'Gün olur da sana dön desem bile Nasılsa geriye dönmeyeceksin Fırtınalar esen şu yüreğimde Neler yıktı neler bilmeyeceksin Tükenir içimde her...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/affettim-mi-bilmeyeceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay', 'ay-fatma-karakoyun-hmibp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gizemli bir akşamüstü 

Pencereme uğradın 

Anıların mıydı depreşen

Neden sormadın

Sen gökte ben yerde

Buluşmamız imkansız

Sana gök yaraşır

Bana ise seni izlemek

Sen dolunay olduğun bir akşam

Yüksek tepelere çıkar sana ulaşırım

Bulutlu akşamlarda gizem yaşarım

Sen gökte ben yerde

Söyle sana nasıl ulaşırım....

                              24.10.2005', 'Gizemli bir akşamüstü  Pencereme uğradın  Anıların mıydı depreşen Neden sormadın Sen gökte ben yerde Buluşmamız imkansız Sana gök yaraşır Ba...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ay-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeye Utanma Sakın', 'sevmeye-utanma-sakin-kadir-albayrak-1i4yr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün olur göz göze geliriz yine

O buruk vuslatın zamanı yakın

Anılar dilini düğümlese de

Merhaba demeye utanma sakın

Yıllardır hatıran ile yaşarım

Her soluk her nefes seni yaşarım

Sevgiyi tatmamış kula şaşarım

Sev gülüm sevmeye utanma sakın

Gönlün de mazinin közü yansa da

O bir kaç saniye asır olsa da

Hasretten ağlamak ayıp değil ya

Göz yaşı dökmeye utanma sakın', 'Gün olur göz göze geliriz yine O buruk vuslatın zamanı yakın Anılar dilini düğümlese de Merhaba demeye utanma sakın Yıllardır hatıran ile ya...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevmeye-utanma-sakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklımda sen..', 'aklimda-sen-ece-ozbek-jbeqp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bugün 

yağmurla

yıkandım

...

aklımda

sen

...

bugün

yağmuru

sen sandım', 'bugün  yağmurla yıkandım ... aklımda sen ... bugün yağmuru sen sandım...', ARRAY['Türk Edebiyatı','Şiir','Ece Özbek']::text[], 8.5, '{"poet":"Ece Özbek","poet_slug":"ece-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aklimda-sen-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ramazan', 'ramazan-fatma-karakoyun-q815x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir zamanı sevdi yüreğim

Bir gülü aşkı tattı ilk yaşadığında

Diğer aylardan farksızdı

Çiçeği başka sevdi yüreğim 

Seni bir başka

Güllerin ağladığı zamanda

Geceler saklardı gözyaşlarını

Ramazanı bir başka sevdi yüreğim

Gülü bir başka

Gülde sen varsın baharda,

Yazda, kışta sen her mevsim açacaksın

Karanlıklar seninle aydınlanır

Işık saçarsın güneş gibi

                            10.10.2005', 'Bir zamanı sevdi yüreğim Bir gülü aşkı tattı ilk yaşadığında Diğer aylardan farksızdı Çiçeği başka sevdi yüreğim  Seni bir başka Güllerin ağ...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ramazan-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Borcunu Buseyle Ver', 'borcunu-buseyle-ver-kadir-albayrak-kkk2m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aklımdan geçeni bir bilebilsen

Belki de dağları aşar gelirsin

Gelipte halimi bir görebilsen

Gönlümden hasreti silebilirsin

Kül altında korlar gibi yüreğim

Gizli gizli yanar sana sevdiğim

Allah-a odur ki arzum dileğim

Duyupta geriye dönebilirsin

Teselli vermiyor her şey nafile

Farkı yok gündüzün geceler ile

Rüyamı paylaşıp uyusam bile

Kulağıma geldim diyebilirsin

Seyreyle yüzümde derin çizgiler

Sana neler neler söyleyecekler

Yılları geriya isteyecekler

Borcunu buseyle verebilirsin', 'Aklımdan geçeni bir bilebilsen Belki de dağları aşar gelirsin Gelipte halimi bir görebilsen Gönlümden hasreti silebilirsin Kül altında korla...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/borcunu-buseyle-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birazdan ağlayacağım', 'birazdan-aglayacagim-kadir-albayrak-3mint', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zamansız bir an da bilmem ki niye

Sen geldin aklıma çıldıracağım

Gözlerim yanmaya başladı yine

Galiba birazdan ağlayacağım

Kağıda bir şeyler yazıp bıraktım

Nasılsa bir daha yazmayacağım

Derdimi ben sana anlatamadım

Galiba birazdan ağlayacağım

Hasretin ağıyla örülmüş her yer

Belki de ölünce kurtulacağım

Gönlümde fırtına başladı yer yer

Galiba birazdan ağlayacağım

Bu gece bir garip oldu yüreğim

Korkarım sabaha çıkmayacağım

Mendille buluştu yine ellerim

Galiba birazdan ağlayacağım', 'Zamansız bir an da bilmem ki niye Sen geldin aklıma çıldıracağım Gözlerim yanmaya başladı yine Galiba birazdan ağlayacağım Kağıda bir şeyler...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/birazdan-aglayacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökkuşağı', 'gokkusagi-guzin-eye-dundar-thr4g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Siz  bir  gökkuşağı  çizdiniz  çevreme

renkleri  bağladı   ellerimi

en  güzel  armağanıyla evrenin

göklerce  dansettim.

bulutların üstünde

siz... verdiniz  gözlerime 

... ilk  ışıkları 

siz...  beni  bir solukta

tutsak  aldınız

gökkuşağı  altında

yapayalnız

renk, renk  düşler içinde

kayıp  küçük  kız

zamansiz ve mekansız

sevdi bu yürek

sevgisizlikten ölen

küçük bir kızım ufak tefek...', 'Siz  bir  gökkuşağı  çizdiniz  çevreme renkleri  bağladı   ellerimi en  güzel  armağanıyla evrenin göklerce  dansettim. bulutların üstünde s...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gokkusagi-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gole Bak Gole', 'gole-bak-gole-mehmet-akif-tiryaki-0grfu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaptın gene numaranı arap çocuğu

Gole bak gole 

Aslında hayatımız bir televole.

Heyy diyelim hey huu,

Maşukiye''de Hakkı verdi avukata atomu(helva) 

Avukat Sapanca''yı seviyordu,

Sapanca sevgisi pirinden geliyordu.

Pirimiz Sapanca''da yaşıyordu,

Dertleri dertlerimizi aşıyordu.

Ama yüzü hep gülerdi,

Konuştukça insanın kalmazdı derdi.

Bana koskoca bir ceviz ağacını hediye verdi.

Avukat güngörmüş bir adam, sırdaşımdı,

Hem babam hem arkadaşımdı.

Derdi bize-''çocuklar neşenizi kaybetmeyin''

''Hiç bir şeyi kendinize dert etmeyin.''

O zaman versene biraz para avukat derdim,

Gole bak gole

Her şey parayla olmaz hey hat

Yaptın gene numaranı arap çocuğu

Derdi bana rahmetli 

Şimdi ona dua rica ediyorum sizden,

Allah rahmet eylesin dua bizden.

Allat''da razı olsun emi sizden.

Şimdi olsa derdi bana rahmetli; 

Yaptın gene numaranı arap çocuğu,

En son golü o attı,

En son numarayı o yaptı.', 'Yaptın gene numaranı arap çocuğu Gole bak gole  Aslında hayatımız bir televole. Heyy diyelim hey huu, Maşukiye''de Hakkı verdi avukata atomu(...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gole-bak-gole-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'K e l i m e', 'k-e-l-i-m-e-koksal-akar-chcn4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şair ağlamaz gülüm, etseler lime lime.

Yeter ki gülümsesin ona bir tek kelime.', 'Şair ağlamaz gülüm, etseler lime lime. Yeter ki gülümsesin ona bir tek kelime....', ARRAY['Türk Edebiyatı','Şiir','Köksal Akar']::text[], 8.5, '{"poet":"Köksal Akar","poet_slug":"koksal-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/k-e-l-i-m-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satranç', 'satranc-fatma-karakoyun-bv6sg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oynuyorsun yine mat olmadan

Bunu bil ki bende mat olmadım

Yeniyorum diye seviniyorsun

Bil ki daha mat olmadım

Piyonlar bitti biliyorum

Onlar rutindi ve bitti

Sırada cezbetmek

Bu taşı zorunlu oynadım 

Savunmanın yok edilmemesi için

Biraz rok yaptım

Örnek bir maç oluyor tebrik ederim

Ne zaman biter merak ederim

Mat olursam sana söylerim

Şimdi sana şah derim

                          24.10.2005', 'Oynuyorsun yine mat olmadan Bunu bil ki bende mat olmadım Yeniyorum diye seviniyorsun Bil ki daha mat olmadım Piyonlar bitti biliyorum Onlar...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/satranc-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nezaket', 'nezaket-kadir-albayrak-yel62', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ah nezaket nezaket seni sevmek felaket

 Nerden çıktın karşıma çakır gözlü nezaket

Nezaketli nezaket kaşın gözün bir afet

Bak ne hale getirdin çarptın beni nezaket

Ah vicdansız nezaket gel de beni mutlu et

Her yerine meftunum üzme beni nezaket

Bembeyazsın nezeket güneş çıktı dikkat et

Süte benzeyen tenin bozulmasın nezaket

Çok güzelsin nezaket her yerinde asalet

Oran buran oynuyor kötü oldum nezaket

Yaklaş bana nezaket dudaklarını lütfet

Bir buseni çalayım çok fettansın nezaket

Sen neymişsin nezaket sanki herşeyin servet

Bir geceye razıyım hediye et nezaket

Haydi tatlı nezaket yatağıma gel park et

Beden tir tir titriyor gel de durdur nezaket

Bir şiirsin nezaket satırların kaç adet

Bir kaçını okudum sonu nerde nezaket

Allah-tan kork nezaket öderim nedir diyet

Çıldırmak üzereyim ''kapat onu'' nezaket', 'Ah nezaket nezaket seni sevmek felaket  Nerden çıktın karşıma çakır gözlü nezaket Nezaketli nezaket kaşın gözün bir afet Bak ne hale getirdi...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nezaket-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş', 'tas-sadik-altinkaynak-s6r36', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Taş

	“Taş Gazeli” isimli şiire nazire

Taş taş değil yüreğindir taş senin

Kurumuş gözünden akmaz yaş senin

Gece gündüz yandığım ataş senin

Sevgi yoksunu yüreğin taş senin

Kaskatı kesilen kalbin taş senin

Can evimden vuran gözle kaş senin

Başımı belaya sokan baş senin

Değmesin hiç ayağına taş senin

Her sözün kalbimi kıran taş senin

Can verir gözünden aksa yaş senin

Ölsem kefen olacak kumaş senin

Mezarıma dikilecek taş senin

				Sadık ALTINKAYNAK', 'Taş 	“Taş Gazeli” isimli şiire nazire Taş taş değil yüreğindir taş senin Kurumuş gözünden akmaz yaş senin Gece gündüz yandığım ataş senin Se...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/tas-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çark', 'cark-sinan-karakas-zrnhc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne günlerdi yarab

Bir kızıl kıyamet kopmuştu sanki

Hortum mu desem 

Yoksa tufan mı

Bir rüzgar kasırga misali

Çatısı uçmuş kiminin

Kökünden sökülmüş ağaçlar

Kimininde

Yeri değişmiş evlerinin

Duymamış bazısı 

Estiğini rüzgarın

Bir yağmur

Suladı çiçeklerini bazısının

Kiminin damladı tavanından

Seline kapıldı eşyaları evlerinin

Bir göl oluştu yağmurdan

Bir ada misali

Kimisi balık tuttu

Kimisi yüzdü

Kimiside boğuldu o yağmurdan

Bir yangın

Mahşeri andırır

Cehennem mi desem

Yoksa volkan mı

Isıttı bazısının yemeğini

Alevleri göründü kimi evlerde

Simsiyah kömür kalmıştı

Beride bir yığın kül

Hafif bir de duman

Geride kalan buydu

Etkilenmedi kimi hiç yangından

Ne günlerdi yarab

Bir kızıl kıyamet kopmuştu sanki

Deccal mı desem 

Yoksa tufan mı

Çekirge sürüsü gibi koşuşuyorlardı

Yetişmek istiyorlardı bir an önce

Ezilenler ölenler ve yetişemeyenler

Görmüyordu ana kızı

Farketmiyordu kardeş kardeşi

Kadın erkek diye bir şey yoktu

Sanki herkes

Erkek veya kadındı

Bir tiyatroydu

Orta oyunmu desem

Yoksa tüluat mı

Sahnede bir sürü oyuncu

Hayret ediyordum

Niçin yoktu seyirci

Bir sürü ip perde arkasından

Kılıçlar silahlar ve kalemler

Oynuyorlardı sahnede birer birer

Kanlar sahnede soğumadan

Kuklacılar göründü perde arkasından

Bir eser kalmadı artık

Ne sahne ne de tiyatrodan', 'Ne günlerdi yarab Bir kızıl kıyamet kopmuştu sanki Hortum mu desem  Yoksa tufan mı Bir rüzgar kasırga misali Çatısı uçmuş kiminin Kökünden s...', ARRAY['Türk Edebiyatı','Şiir','Sinan Karakaş']::text[], 8.5, '{"poet":"Sinan Karakaş","poet_slug":"sinan-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/cark-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Narın Hikmeti', 'narin-hikmeti-sadik-altinkaynak-r7zcg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Narın Hikmeti

Açılsın da saçılsın ortaya nar

Narı tefekkür et onda hikmet var

İnci gibi taneler incecik bir zar

Bu intizama ibretle kıl nazar

Derler ki bir çiçekle gelmez bahar

Bahara bak onda da çok hikmet var

Güzde ölen nebat canlanır tekrar

Çiçeğe durur elma ayva ve nar

Evet sağlık lezzet hikmet var narda

Nardan tatlıdır vefa varsa yarda

Bülbül de bir yar için ah-u zarda

Umarım Mevla yakmaz bizi narda

                         Sadık ALTINKAYNAK', 'Narın Hikmeti Açılsın da saçılsın ortaya nar Narı tefekkür et onda hikmet var İnci gibi taneler incecik bir zar Bu intizama ibretle kıl naza...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/narin-hikmeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluk', 'cocukluk-kadir-albayrak-apf99', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerim de tütüyor  lunapark

Bir bilet bir liraydı galiba

Önce çarpışan otolara

Sonra da dönme dolaba binmeliyim

Ahtapotla balerini de ihmal etmemeliyim

Sonra kalan beşyüzlükle de kağıt helva yerim! ..

Çevremdekiler,

Birbirlerine gösterecekler beni

''Çocuk galiba'' diyecekler! ..

Bir süre onlara aldırmam belki

Sonra yavaş yavaş sinirlenirim

Belki de bağırırım,

''Size ne ulan! .....''

Bir daha bakmazlar mı acaba? ! ..

Bakarlar.. bakarlar

Hayvan oğlu hayvanlar! ...

Gençtik! .. Birini sevdik

Çanımıza ot tıkadılar! ..

Başka işleri yokmuş gibi 

Bununla uğraştılar! ...

Yeter be! ..... Yeter! ....

Gençlik ''Çocukluktan beter! ...''

Şu önde ki kokana bana bakıp bakıp ne dedi? ...

''Herif...herif...'' saçından sakalından utan! ....

Vay sünepe vay! ....

Çatlayın ulan! .... Şimdi de

Atlı karıncaya da binicem

Kokana; Senin binilecek tarafın mı kaldı? ......

Şunlara inat 

Bir de emzik bulmalıyım! ...

Bu gece gönlümce ''Çocukluğumu yaşamalıyım''

Bir de şapka takayım,

Önünde spot ışığı olan

Yuppiiiiiiiiiiiiiiiiiiiiiii

Çocuğum işte! ... Çocuğum bu gece

Hastırın ordan

Size ne ulan! .....', 'Gözlerim de tütüyor  lunapark Bir bilet bir liraydı galiba Önce çarpışan otolara Sonra da dönme dolaba binmeliyim Ahtapotla balerini de ihma...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/cocukluk-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Analiz', 'analiz-i-brahim-kilinc-b46bi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gül ki gülizarda güller açılsın

Gönlümüze bahar, neşe saçılsın

Mümkün mü gül yüze değer biçilsin

.....................Sen gökte yıldızsın, yerde kalmazsın

.....................Selâm versem, selâmımı almazsın

Karar vermiş felek beni yormaya

''Tamam! '' desen, bir gün gelsem almaya

Vaktin olsa birkaç sual sormaya

.....................Sen Tanrı''nın nûru, kulda kalmazsın

.....................Hatır sorsam, hatırımı sormazsın

Varam desem bizim il''de olmazsın

Seni bulacağım yerde durmazsın

Süründürürsün de çekip vurmazsın

.....................Sen gökte yıldızsın, yerde durmazsın

.....................Selâm versem, selâmımı almazsın

Bu bir sır, bu bir giz, dillerden öte

Bir yanı eksiktir, bir yanı hata

Doldurdun gönlümü dert ata ata

...................Sen Tanrı''nın nûru, kulda kalmazsın 

...................Hatır sorsam, hatırımı sormazsın', 'Gül ki gülizarda güller açılsın Gönlümüze bahar, neşe saçılsın Mümkün mü gül yüze değer biçilsin .....................Sen gökte yıldızsın, y...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/analiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alınyazım', 'alinyazim-seher-gungor-o4e8a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşadığım yıllar boyu içimde bana kalan bir yerdir sen.

Acılarımın içinde açan bir tomurcuktun daha filizlenmemiş..

Günden güne bir bebek gibi büyüttüm içimde seni.

Gözyaşlarımla yoğurdum hamurunu,hasretimle büyüttüm...

Umutlarla,hasretle karışık türkülerimdin dilimden düşmeyen.

Öyle birşeydin sen. Acılarım,kederlerimle suladığım bir çiçektin.

Ne su verdim,ne besleyebildim ne de güneş yüzü gösterebildim.

İçimde sakladığım bahçeme bir isim bulamazken,

çıkıverdin apansızın karşıma..

seni okadar aradım ki alınyazım.

Ben dahi anlayamadım arayışlarımı...

      Yokluğunu anlatamadım kimseciklere,

anlatsamda anlayacak  kimsem yoktu ki yanımda..

Yargısız,infazsız kim dinlerdi ki beni.

Bir ben,bir de içimde varolan senle aradım ben seni..

      Sustum,sessizliğim oldu isyanlarım.

Konuşamadım ki alınyazım,düğümlendi bişeyler boğazımda.

Haykırışlarımı  duyanım olmadı kalabalık arasında...

Seni sensiz,sessiz günlerde  yaşadım ben.

Okuduğum romalarımın baş kahramanıydın resimsiz,isimsiz..

Yazamadığım,birtürlü birleşmeyen şiirlerimin mısralarıydın sen.

     Yaşama sebebimdin.Senelerdir su gibi içtiğim şiirler,romanlarım

 boşuna değildi.

Birgün evet birgün...Son günümde olsa ogün gelecekti birgün.

O umut ışığımdı yaşama sebebim.

Sensiz günlerimde gözyaşlarımı yağmura verdim,

isyanlarımı şarkılarıma.kimsecikler anlamasın diye..

Hiç seyerettin mi bilmem.En çok selvi boylum alyazmalıma 

ağlardım ben çocukluğumdan kalan..

Daha sen yokken varlığını

dahi bilemeden yazdım ben o mektubumu biliyomusun alınyazım..

Sana yazgım dedim,sendin benim alınyazım.

Senin ne varoluşu ne de yokluğundaki ızdırabımı,

anlatabileceğim kimsem olmadı yanımda.

Olsalarda anlarlarmıydı ki benim seni anladığım gibi....

Sen geldin.Bana sormadan sana  kapılarım açıverdi kilitlerini.

Onlarda bildi kilitli kapıların sahibini...

    Belki Yokluğunda hayaldin.Ama varlığında tüm hayallerim gerçekleşti senle..

Bir elmanın iki yarısıydık aslında..Farklı Yollara ayrılmış..

Gün geldi birleşti işte yine yollarımız.Rüyalarım,düşlerim,

yolum hep sana çıkarken onca kaçışlarda,

ben nasıl yazgım demem sana alınyazım..

    Yollarını çok bekledim.usanmadım.Sakın ha kırıldığımı sanma.

İnsan canına kırılabilirmi ki alınyazım..Baktığım yerde sen,

ekmeğimde aşımda sen,ben olrmuşken sen, 

nasıl vazgeçebilirim ki senden....

     Bak umutlarım,şiirlerim,okuduğum ramanlarım boşuna değilmiş.

Boşuna değilmiş dualarım..Dualarımın adı,yaşama sevincim,Alınyazım.

Yüreğimin bahçesini sensiz mi bırakacaksın böyle ansızın..

Gözlerinde kendimi bulduğum çocuk...

Hele bir bak gözlerime öyle git,gideceksen.......

Seher Güngör

(küçük pencerem-23:30)', 'Yaşadığım yıllar boyu içimde bana kalan bir yerdir sen. Acılarımın içinde açan bir tomurcuktun daha filizlenmemiş.. Günden güne bir bebek gi...', ARRAY['Türk Edebiyatı','Şiir','Seher Güngör']::text[], 8.5, '{"poet":"Seher Güngör","poet_slug":"seher-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/alinyazim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai Tolunay', 'rubai-tolunay-nihat-yucel-0nsax', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Söz dinlemiyor sanki zaman bir deli tay

geçmişte geçen günleri sen dopdolu say

Dostlar görünüz bir-mavinin en hasını

Emzirmededir-gök memesinden tolunay', 'Söz dinlemiyor sanki zaman bir deli tay geçmişte geçen günleri sen dopdolu say Dostlar görünüz bir-mavinin en hasını Emzirmededir-gök memesi...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai-tolunay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-didem-yildirim-yruhb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dilim söylemesede

Gönlümün intizarı var

Duydun ses yalnızlığımın sesi

Yalnızım,kalabalıklar içinde yalnız

Şarkılara konu olmuş yıldızlar kadar yalnız

Yalnızım,mesai saati dışındaki bir işyeri kadar

Süper marketlere yenik düşmüş 

                                   bir bakkal kadar yalnız

Yalnızım,

Seyredilmeyen bir video,

Dinlenmeyen bir kaset,

Söylenmeyen bir şarkı kadar yalnız

Mahalleli karar vermiş,koymuşlar bir çuvala,götürmüşler kediyi

O kedi nekadar yalnızsa, bende okadar yalnız

Gidilmeyen mezarlar,

Okunmayan Kuranlar,

Edilmeyen dualar kadar yalnız.

Tavan arasında kırık dökük eşyalarDüşkün bir ihtiyarın çaresizliğinde akşam

Cevap yazılmayan mektuplar kadar yalnız

Unutulan anılar,tozlanan fotoğraflar,

Okunmayan şiirler kadar yalnızım

Ve unutulan şairler kadar...

Yaşıyorum amave üşüyorum bu şehirde

Üstelik birde yalnızım.

Yalnızlığımla başbaşa,bir temmuz akşamı İstanbul da

Kimse okusun diye yazmadım bu satırları

İşte bu yüzden ben,

Bu satırlar kadar da yalnızım............', 'Dilim söylemesede Gönlümün intizarı var Duydun ses yalnızlığımın sesi Yalnızım,kalabalıklar içinde yalnız Şarkılara konu olmuş yıldızlar kad...', ARRAY['Türk Edebiyatı','Şiir','Didem Yıldırım']::text[], 8.5, '{"poet":"Didem Yıldırım","poet_slug":"didem-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yalnizim-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanat Olmalı Yaşamak', 'sanat-olmali-yasamak-sair-vuslat-33305', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sanat olamlı yaşamak

Her gün aynı sahnede

Aynı rutin melodiyle

Hayata aşık rolü oynamak

Sanat olmalı adı hayatın

Mutlaka sanat', 'Sanat olamlı yaşamak Her gün aynı sahnede Aynı rutin melodiyle Hayata aşık rolü oynamak Sanat olmalı adı hayatın Mutlaka sanat...', ARRAY['Türk Edebiyatı','Şiir','Şair Vuslat']::text[], 8.5, '{"poet":"Şair Vuslat","poet_slug":"sair-vuslat","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sanat-olmali-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askıdayım', 'askidayim-sair-vuslat-urxkc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Askıdayım

Hazır, amade...

Ölçülerim sadece senin,

Sadece senin boyutuna göre...', 'Askıdayım Hazır, amade... Ölçülerim sadece senin, Sadece senin boyutuna göre......', ARRAY['Türk Edebiyatı','Şiir','Şair Vuslat']::text[], 8.5, '{"poet":"Şair Vuslat","poet_slug":"sair-vuslat","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/askidayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bişkek''te Mevsimler', 'biskek-te-mevsimler-adnan-serifoglu-kcet9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yaz, alır ağır yükünü düşüncelerin

tez  döker  terini obez günlerin

güz, bütün resimleri siler

kızıl altından akşamlar çizer

gelir birer birer unutulmuş hüzünler

bahçeler bir yâr için solup gider

kış,alıcı kuş gibi iner

gün ışığı hasadı çabuk biter

ağaçlar dertli  yakup’a benzer

gözyaşını batıni döker

gözlerden çekilirken fer

gözlere beyaz perdeler iner

kenan’dan bir haber gelir

mevsim  ondan  bahara döner

                                 bişkek,20 ekim 2002', 'yaz, alır ağır yükünü düşüncelerin tez  döker  terini obez günlerin güz, bütün resimleri siler kızıl altından akşamlar çizer gelir birer bir...', ARRAY['Türk Edebiyatı','Şiir','Adnan Şerifoğlu']::text[], 8.5, '{"poet":"Adnan Şerifoğlu","poet_slug":"adnan-serifoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/biskek-te-mevsimler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim Mutluluğumu Çaldın', 'sen-benim-mutlulugumu-caldin-sair-vuslat-ufv36', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen benim mutluluğumu çaldın

Bir aşk evliliğimi yapıp

Mutlu olacaktım

Bu yaştan sonra şimdi ben

Nasıl aşkı yakalacağım

Seni kaç üçyüzaltmışbeş günde unutacağım

Sen benim hayatımı çaldın', 'Sen benim mutluluğumu çaldın Bir aşk evliliğimi yapıp Mutlu olacaktım Bu yaştan sonra şimdi ben Nasıl aşkı yakalacağım Seni kaç üçyüzaltmışb...', ARRAY['Türk Edebiyatı','Şiir','Şair Vuslat']::text[], 8.5, '{"poet":"Şair Vuslat","poet_slug":"sair-vuslat","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sen-benim-mutlulugumu-caldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bişkek''te Gurbet', 'biskek-te-gurbet-adnan-serifoglu-r4650', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'imbiklerinden  süzülürken

yabancı bir ülke akşamında anılarınız

yakıcı bir alev dolaşır damarlarınızda

ana sütü diliniz uzak bir rüzgar esintisidir

karanlık tez iner gün ışığı geç gelir

kanar derinlerinizde mecnun sevdası güller

anayurt bir adadır  uzak denizlerde

yelkeniniz yoktur açıp gidesiniz

babanızın atı kıtay’da vurulmuştur gelemez

kardeşleriniz kendi derdiyle sarhoş

anneniz uzak memlekete kız vermiş

yüksek tepelere ev kurmuştur inemez

umutlarınız küçüktür büyüyemez

anılarınız en korkunç karabasandır gecelerde

güneşli günleriniz kaldı sıcak düşlerde

bir güldünüz o çiçeği solmaz bahçelerde

artık her şey ötelerde çok ötelerde

bülbülleriniz uzak ikliminizin seherinde

şarkılar söyler en ince perdelerde

ataların ruhu tüter suzinak bestelerde

memleket eski baharlardan bir nisan yağmurudur  içinizde 

hey dostlar şu gurbet ne kötü keder

künyemize ne yaman işlemişler

sılaya da gitsek bizimle beraber

                                  bişkek,8 ekim 2002', 'imbiklerinden  süzülürken yabancı bir ülke akşamında anılarınız yakıcı bir alev dolaşır damarlarınızda ana sütü diliniz uzak bir rüzgar esin...', ARRAY['Türk Edebiyatı','Şiir','Adnan Şerifoğlu']::text[], 8.5, '{"poet":"Adnan Şerifoğlu","poet_slug":"adnan-serifoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/biskek-te-gurbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşuna Ağlama', 'bosuna-aglama-muhsin-altintas-mv5nd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir akşam daha oldu

Hayat ağacından bir yaprak 

Sarardı düştü akşamla birlikte

Yine yüreğimizde o eski sevgiler

Ta derinlere bir hançer misali sokulu

Umutsuz, Çaresiz, Yapayalnız.

Ve yine akşam oldu

Acı hisler, Buruk yüzlerle

Gökyüzü sanki halimize ağlarcasına 

Dukunsan yağacak

Rüzgar bir tuhaf esiyor

Aslında biliyorum ne demek istediğini

Ama

Anlamak istemiyorum

Evet işime gelmiyor anlamak

Oysa kim bilmezki rüzgarın

Boşuna ağlama dediğini

Ve geçmişin asla geri gelmeyeceğini...', 'Bir akşam daha oldu Hayat ağacından bir yaprak  Sarardı düştü akşamla birlikte Yine yüreğimizde o eski sevgiler Ta derinlere bir hançer misa...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Altıntaş']::text[], 8.5, '{"poet":"Muhsin Altıntaş","poet_slug":"muhsin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bosuna-aglama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-sair-vuslat-3k9oz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün geçti şükür

Bu gün yaşıyorum

Ya yarın! 

Yarınlar ne olacak

Dün acılar çoktu

Bitti şükür! 

Bu gün de yaşamaya çalışıyorum

Bu günü de atlatırsak; 

Ne güzel! 

Belki yarın! Belki yarın!', 'Dün geçti şükür Bu gün yaşıyorum Ya yarın!  Yarınlar ne olacak Dün acılar çoktu Bitti şükür!  Bu gün de yaşamaya çalışıyorum Bu günü de atla...', ARRAY['Türk Edebiyatı','Şiir','Şair Vuslat']::text[], 8.5, '{"poet":"Şair Vuslat","poet_slug":"sair-vuslat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zaman-258-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bişkek''te Ölüm Düşüncesi', 'biskek-te-olum-dusuncesi-adnan-serifoglu-aw2vb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sevdamız al bir ata bindi

gönlümüz ardı sıra gider oldu

göçüp konduğumuz yaylalar

kışlağa döner oldu

ipek esintili rüzgar

tenimizde ateş oldu

hey dostlar

ölüm bize yakın oldu

yaşamak her gün korku dolu

umut beklenen misafir oldu

ömrümüz bilmem ne zaman nasıl

kimler var kimler yokken yanımızda

kanmadan içilen  bir  yudum  su oldu

hey dostlar

ölüm bir adım oldu

şu bişkek’in insan pazarında

canımız bizim bir serçecik kuş gibi

bir sıcak nefese susamış gibi

azrail aleyhisselam kabzında

birazcık hırıldamış gibi

yele binip gider oldu

hey dostlar

siz kalın bu gurbette

ölüm bizi alır oldu

                                                  bişkek,27 ekim 2002', 'sevdamız al bir ata bindi gönlümüz ardı sıra gider oldu göçüp konduğumuz yaylalar kışlağa döner oldu ipek esintili rüzgar tenimizde ateş old...', ARRAY['Türk Edebiyatı','Şiir','Adnan Şerifoğlu']::text[], 8.5, '{"poet":"Adnan Şerifoğlu","poet_slug":"adnan-serifoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/biskek-te-olum-dusuncesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-sair-vuslat-r3rz1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hepimizin hayatı düş

Biraz var belki düşünüş

Hani nerde yapış, iş

Düşüne düşüne hep düş

Yüzde kalmadı gülüş

Düşlerin sonu hep çöküş', 'Hepimizin hayatı düş Biraz var belki düşünüş Hani nerde yapış, iş Düşüne düşüne hep düş Yüzde kalmadı gülüş Düşlerin sonu hep çöküş...', ARRAY['Türk Edebiyatı','Şiir','Şair Vuslat']::text[], 8.5, '{"poet":"Şair Vuslat","poet_slug":"sair-vuslat","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dus-142-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bişkek Sabahı Cumartesi', 'bir-biskek-sabahi-cumartesi-adnan-serifoglu-w9f5k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir bişkek sabahı  cumartesi...

ayyaş gecelerden kalmış sabahın sakinliği

yaşar donmuş kuzey zamanları içinde

manas caddesi sıradan bir cumartesi

kar mı  düşer bir gelinin konfetileri mi

nerde düğün  nerde sıcak kırgız gözleri

yaşadığımız yabancılık korkuları içinde

büyük bir yalnızlıktır belki

bir bişkek sabahı cumartesi...

evvel zamanlarda giderken

ardımızdan su döken kardeşler

şimdi nerdeler nerde kümbözdörü

bin yılın uğru yaban elleri

bugün dost onlara kardeş sevgili

yağın üstüme kar taneleri kefenleyin beni

yaşamak istemiyorum kardeş ellerinde

böyle sefil böyle yalnız böyle korkular içinde

bir vatansız gibi sünepe,serseri

bir bişkek sabahı cumartesi...

bu iklimde yasaklı zamanlardır yaşadığımız

yıldızlarını da göremediğimiz gecelerde

körebe oynuyoruz yaşamak diye evlerde

güvensizlik bir kurttur kemirir canevini

alıp götürür içimizde gizlenmiş bizi

söylüyoruz bildiğimiz bütün sıcak türküleri

bir araya gelince dost üç beş kişi

gelsin diye eski güzel günler geri

bir bişkek sabahı cumartesi...

                                                        bişkek,10 ocak 2003', 'bir bişkek sabahı  cumartesi... ayyaş gecelerden kalmış sabahın sakinliği yaşar donmuş kuzey zamanları içinde manas caddesi sıradan bir cuma...', ARRAY['Türk Edebiyatı','Şiir','Adnan Şerifoğlu']::text[], 8.5, '{"poet":"Adnan Şerifoğlu","poet_slug":"adnan-serifoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bir-biskek-sabahi-cumartesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey İnsan', 'ey-i-nsan-abdulkadir-i-lyas-9vcmi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dunya yalan hayat fani yarın ne olacak bilinmez..

Yürekte yaşanan şeyler baki öğrenemeden hissedilmez 

Yratılanlar değer ister yüreğe akan kan silinmez 

Bedenin birden yok olup gider akıbetini kimse bilmez..

Feda etmeli hepsini hayatın bizi yaratan yüce Hüda''ya

Yine de şükrü bilinmez affın ulaşmada evvel ulu Mevla''ya

Rabbim kuluna eziyet etmez adasan kendini bu dünyaya

Sanma ki yakarışlar kabul görmez anlarsın kadrini erince rüyaya..

Hayatı anlayamadan herkes yaşar öyle yaşa ki unutulmasın

Kırma birini bir ömür yakar için sızlar anlayasın

Beterin beteri sana gelmeden uyuyan aklın biran uyansın

Fani hayat sona ermeden biricik yüreğin yok olmasın...

Güven yeter ki sen Allah''a yoksa yüreğin iflah olmaz 

Öyle hale gelmiş ki dünya dost dostuna dahi acımaz 

Vesveseler zavallı içini karartır kimseler derdine derman olmaz 

İnan değerler değer yaratır pişman olmaya zaman kalmaz......

                                                                  (2005)', 'Dunya yalan hayat fani yarın ne olacak bilinmez.. Yürekte yaşanan şeyler baki öğrenemeden hissedilmez  Yratılanlar değer ister yüreğe akan k...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir İlyas']::text[], 8.5, '{"poet":"Abdulkadir İlyas","poet_slug":"abdulkadir-i-lyas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ey-insan-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharın Bişkek''i', 'baharin-biskek-i-adnan-serifoglu-tzo6v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kırılır kış kuşunun kanadı,düşer

yeşil mavi cemreler ortasına

sessizce  ağır ağır can verir...

hülyalar iner melek kanatlarında

baharla beraber bişkek  meydanlarına

yalnızlığımın arsızca koynuma girdiği akşamlarda

gece muhteşem günahlar kol gezer sokaklarda

açlar,çaresiz sarhoşlar uyur duraklarda

ihtişam ve sefalet bayrak açmış ortalıkta

prezervatifler dolusu insan ayak altlarında

beyinler, dört mevsim damıtılan araklarla

derin,deliksiz,unutulmuş uykularda

ağla ey apake,közkaman oğullarına

ağla roza amanova’nın hüzünlü ırlarıyla

ağla  umuda   çağıran gözyaşlarıyla

ulaşırız  kurtuluşa baharla Kuday buyurursa...

                                                      bişkek, 03.04.2003', 'kırılır kış kuşunun kanadı,düşer yeşil mavi cemreler ortasına sessizce  ağır ağır can verir... hülyalar iner melek kanatlarında baharla bera...', ARRAY['Türk Edebiyatı','Şiir','Adnan Şerifoğlu']::text[], 8.5, '{"poet":"Adnan Şerifoğlu","poet_slug":"adnan-serifoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/baharin-biskek-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''a Özlem', 'i-stanbul-a-ozlem-soner-kose-gc10x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senden uzak bu diyarlarda ağladım durdum.

Ne olur bitsin artık bu hasret güzel yurdum.

Ufukların hayalimden kaybolup gideli,

Bu çaresiz ruhumun kararır her daim şekli.

Bende kayıp oldu her şeyin anlamı sensiz.

İnan ki senden ayrılalı bu garip öksüz.

Yüreğim kanar o günler gözümde tüttükçe. 

Senden ayrı geçen her saat bana işkence.

Arzumanım kaldı cennet-i diyar vatandan.

Şimdi sual eylerim seni, uçan her kuştan.

Gelir mutlaka sana kavuşacağım günler.

Seni görmezse eğer, açık gider bu gözler.

Yabancısıyım bu yerin, tadı yok tuzu yok.

Gezdim tüm diyarları İstanbul gibisi yok.', 'Senden uzak bu diyarlarda ağladım durdum. Ne olur bitsin artık bu hasret güzel yurdum. Ufukların hayalimden kaybolup gideli, Bu çaresiz ruhu...', ARRAY['Türk Edebiyatı','Şiir','Soner Köse']::text[], 8.5, '{"poet":"Soner Köse","poet_slug":"soner-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/istanbul-a-ozlem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma', 'unutma-sair-vuslat-wbckj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni unuttum sanma,

Unutmadım, unutmamam asla,

Şu uçup giden yıllara bakıp da,

Araya zaman kavramını sokma

Zaman seni unutturamaz bana

Unutmadığımı unutma...

Unutma....

Anılması gerektiğinde hatırla

İçinde taşı sevgiyi yaşanması gerektiğinde yaşa

Bir kalbin en güzel yerinde taşındığını,

Ve o yerin daim kalacağını unutma.

Sen de değerimle taşı beni,

Gönülden verdiğin değerimle,

Oradan oraya savurma atma,

Saplantı yapma takma,

Yaşanması gerektiği gibi yaşa

Bir bilmecenin kendisiyken hayat,

Bir de sevgiyi labirent yapma

Bulamadıklarını aramakta zorlanma,

Kahredip de bunalma sapma,

Gerçekleri gör, gerçekleri yaşa,

Düşleri gerçeklere katma.

Sevgilere sarıl, sevgilerle yaşa,

Sevgilerin birleştiğini unutma,

Unutma unutulmadığını unutma,

Yüreğinin yanındaki yüreği hatırla,

Ne zaman sınıra gelse yaşam, 

Yüreğini uzat yüreğime bırakma,

Olması gerektiğinde olabildiğince sana

Uzanacaktır elim unutma.

Unutma! ... Unutmadığımı unutma

Unutma! ... Umutla yaşa....', 'Seni unuttum sanma, Unutmadım, unutmamam asla, Şu uçup giden yıllara bakıp da, Araya zaman kavramını sokma Zaman seni unutturamaz bana Unutm...', ARRAY['Türk Edebiyatı','Şiir','Şair Vuslat']::text[], 8.5, '{"poet":"Şair Vuslat","poet_slug":"sair-vuslat","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/unutma-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbaharın Bişkek''i', 'sonbaharin-biskek-i-adnan-serifoglu-j6v29', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'mevsim, sarardı soldu  bütün şehrin viran caddelerinde

geldi  büyük can sıkıntısı, girdi eylül kapısından yine 

parklar, bahçeler,köçöler örtünmüş altın örtülerle

canım yaz, bir abdal gibi çekip gittiğinden beri öyle

melekler, hüzün eler üstümüze  yaprağın ateş renklerinde

bu gamlı yangın, bu  mevsimde bir de yedi göllerde

kuşlar gitmiş; seherler sessiz; solmuş  güneş bile

hazırdır her yer; uzun,kasvetli  geceler mevsimine

hayat; gece gün ağlamaklı pişmanlıklar içinde

türlü dillerdeki, içli, garip,  yorgun insan seslerinde

umut,yeni yakılmış bir anız gibi kararmış insan yüzlerinde

dört bir yana savrulan isli duman kokusu siner üstünüze

bir şehir düşünün,kuzeyin bütün  başkentleri içinde

insanlar şimdiye inat yaşar, saat bile yok bileklerde

oğlun ağacından koparılmış bir yapraktır  şimdi anne

yaşar rahminden anılar denizinde hazan içinde şu bişkek şehrinde

                                                                   bişkek-2003-Kasım', 'mevsim, sarardı soldu  bütün şehrin viran caddelerinde geldi  büyük can sıkıntısı, girdi eylül kapısından yine  parklar, bahçeler,köçöler ör...', ARRAY['Türk Edebiyatı','Şiir','Adnan Şerifoğlu']::text[], 8.5, '{"poet":"Adnan Şerifoğlu","poet_slug":"adnan-serifoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sonbaharin-biskek-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Seni Yaşadım', 'yine-seni-yasadim-savas-dincbas-ex4vc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sensizliği, sensiz yaşamak için

çıktım yola

otobanda kendimle yarıştım

kaçmadım

sensizliği sensiz yaşamak istedim

bir köye girdim yolda

zehra ninenin ayranını içtim

ineklerinin peşinden gittim onunla

dağ başında anılarını dinledim

sevgilerini anlatırken

seni yaşadım

dağlara çıktım

vadileri seyrettim seninle

balcılığı öğrendim, toprağı öğrendim

tabiatla kucaklaştım

seninle kucaklaşır gibi

saçlarını koklar gibi kokladım

yaban çiçeklerini

köy odasında sohbetlere katıldım

sorunlarını paylaştım

çocukları sevdim köy yollarında

senin çocukluğunu sever gibi

sensizliği, sensiz yaşamak istedim

fakat ne çare, benimleydin yine...', 'sensizliği, sensiz yaşamak için çıktım yola otobanda kendimle yarıştım kaçmadım sensizliği sensiz yaşamak istedim bir köye girdim yolda zehr...', ARRAY['Türk Edebiyatı','Şiir','Savaş Dinçbaş']::text[], 8.5, '{"poet":"Savaş Dinçbaş","poet_slug":"savas-dincbas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yine-seni-yasadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman-2', 'zaman-2-sair-vuslat-91bxh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne olur aksın, durmasın zaman,

Ne çıkar? 

Çizilsin yüzüm, başım görünmesin aktan,

Alacağımı almışsam zamandan 

Yersizdir geçmesin diye yakınmam.

Ne olur aksın, durmasın zaman,

Ne çıkar? 

Ümitlerin bittiği yerde yaşayan 

Kurtulmak ister, kurtulamaz zamandan

Çabuk geçsin, kurtulsun bocalayan.

Ne olur akmasın, dursun zaman

Yeşeren umutlarım dağlar kadar,

Daha görecek mutlu günlerim var,

Bunun içindir zamanla yarışmam

Beni benden zamansız alma zaman.', 'Ne olur aksın, durmasın zaman, Ne çıkar?  Çizilsin yüzüm, başım görünmesin aktan, Alacağımı almışsam zamandan  Yersizdir geçmesin diye yakın...', ARRAY['Türk Edebiyatı','Şiir','Şair Vuslat']::text[], 8.5, '{"poet":"Şair Vuslat","poet_slug":"sair-vuslat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/zaman-2-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bişkek''te Ölüm', 'biskek-te-olum-adnan-serifoglu-w1a5c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'solgun bir gül yaprağıdır bişkek’te ölüm

saklanır can suyunu yitirmiş çiçekler gibi

soyuzdan kalma eski kitap içlerinde

                          

gezer  büyükçe ve içi geçmiş bir köyün

bakımsızlıktan avazınca bağıran caddelerinde

moskoftaki nazım hikmet yalnızlığı içinde

 hayat her an sönmeye ayarlı bir ışıkken bedende

ölüm uhrevi bir lekedir sessizce büyür içimizde

ve sessizce alıp saklar bizi derin,dipsiz dehlizine

kirlenmeyelim diye terkedilmiş çocuk yüzlerinde 

                                                                             10.09.2004', 'solgun bir gül yaprağıdır bişkek’te ölüm saklanır can suyunu yitirmiş çiçekler gibi soyuzdan kalma eski kitap içlerinde                     ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Şerifoğlu']::text[], 8.5, '{"poet":"Adnan Şerifoğlu","poet_slug":"adnan-serifoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/biskek-te-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bişkek''te Hüzün', 'biskek-te-huzun-adnan-serifoglu-eg8n0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir yaralı ceylan bakışıdır bişkek’te hüzün

 varlığımızı on iki şiddetinde amansızca sarsar

 küçük bir çocuk olur,bizi  her daim Allah’a bağlar

karışır giderken en umulmaz duygular birbirine

hüzün bir deyme güzelliktir sevincin yerine

hiç eskimeden,kirlenmeden hiç durur üstümüzde

yaşanan som bir rüyadır ruhun  derinliklerinde

semanın mavi bahçelerinden süzülüp gelen

kuru bir yaprak olur düşer sarı denizlere

aldırmayın siz kimsiniz, başkalarından size ne 

yaktığınız geminin dumanı hala tüterken üstünde

yol  alın  siz de iç ülkenizin güzden ikliminde

                                                                          eylül 2004-bişkek', 'bir yaralı ceylan bakışıdır bişkek’te hüzün  varlığımızı on iki şiddetinde amansızca sarsar  küçük bir çocuk olur,bizi  her daim Allah’a bağ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Şerifoğlu']::text[], 8.5, '{"poet":"Adnan Şerifoğlu","poet_slug":"adnan-serifoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/biskek-te-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bişkek''te Zaman', 'biskek-te-zaman-adnan-serifoglu-qtipd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'uyandırılmaktan hoşlanmayan bir sudur bişkek’te zaman, ağır ağır akar

gardroplardan kovulmuş eski bir kent soyludur,üstü başı naftalin kokar

mossovyet yaz-kış demeden güneşte sere serpe umarsız bir yılan gibi yatar

toktogul-sovyetskaya’da nüfustan düşülmüş,zulmet yorgunu,tinerci çocuklar 

avazınca bağırır ingiliz kılıklı bir dilenci çon meçit’te gogolya’da

sesi küllenmiş bir ateşi yeniden ve usulca yakar dimağınızda

içinizden bir ses,ama kırgızca ‘caşaybız şükür gerek kudayga’

dolup taşar meçit cuma namazında caş müsülmanlarla

beyaz evi bekleyen cooker  uzanmış yatar yaka bağır açık çimende

revalutsiya bir saatte olur yüz kişiyle, diğerleri işte, bir sokak ötede

çüyde gitar, saksafon sovyetskayada, akordeon sesleri akemmirde 

azmış tenlerin vahşete uyan çağrısı yankılanır hemen güneş gözükse

akşam oldu mu çifter çifter kapanır ardı ardına soyuz artığı  suratsız kapılar

gece kararmış ruhlar gibi sokaklarda  bayram eder yedi bela alkaşlar

nerede kim ölür kim kalır,kim kimi boğazlar,kimin umurunda; yaşasın sağlar! 

bişkek’te zaman budur, böyle yaşanır boğucu yazlar,böyle geçer dondurucu kışlar

                                                                                               2004-2005 bişkek', 'uyandırılmaktan hoşlanmayan bir sudur bişkek’te zaman, ağır ağır akar gardroplardan kovulmuş eski bir kent soyludur,üstü başı naftalin kokar...', ARRAY['Türk Edebiyatı','Şiir','Adnan Şerifoğlu']::text[], 8.5, '{"poet":"Adnan Şerifoğlu","poet_slug":"adnan-serifoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/biskek-te-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkiyem 1', 'turkiyem-1-mustafa-yazka-8zbxe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ekmeğini yiyip yudunda durur,

Asker,Öğretmen Çocuğun vurur,

İyiliğin görende iftira vurur,

Her türlü insanlar yaşar Türkiyem.

Dağların çoğu bakire daha,

Yarıdan çoğu ekili saha,

Çoğunu hedava besliyor haalâ,

Birazcık yorgun solur Türkiyem.

Mustafa Türklükle duyuyor gurur,

Terörü cahili darbeler vurur,

Bazı seçilen hortumlar durur,

Yinede ayakta durur Türkiyem.', 'Ekmeğini yiyip yudunda durur, Asker,Öğretmen Çocuğun vurur, İyiliğin görende iftira vurur, Her türlü insanlar yaşar Türkiyem. Dağların çoğu ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yazka']::text[], 8.5, '{"poet":"Mustafa Yazka","poet_slug":"mustafa-yazka","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/turkiyem-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Yok mu', 'ah-yok-mu-kadir-albayrak-26x72', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Başımı yastığa koyduğum zaman

Gelipte rüyama girişin yok mu

Sarılıp boynuna öptüğüm zaman

Ardını dönerek gidişin yok mu

Gözlerin sevgiyi anlatıyorken

Susarak başını eğişin yokmu

Dön diye ısrarla yalvarıyorken

İmkansız dönemem deyişin yok mu

Bir ümit ararken bakışlarında

Hıçkırıp göz yaşı döküşün yok mu

Buseye hasretken dudaklarında

Acıyla burkulup gülüşün yok mu

Elimi elinde  sımsıcak tutup

O mahzun o bitkin duruşun yok mu

Bilmem ki sevmekte ne günah bulup

Hesabını benden soruşun yok mu

Kollarım özlemle seni beklerken

Ellerin koynun da yatışın yok mu

Aleme mutluluk bağışlıyorken

Ömrümü bitirip yakışın yok mu

Hatıra ararken senden bir parça 

Vedayı hediye  edişin yok mu

Güneşe meftunken kızıl şafakta

Geceyi gönlüme verişin yok mu

Sensizlik zor ama alıştım derken

Nur gibi yüzüme vuruşun yok mu

Atışı isminle haşır neşirken

Kalbimi boş yere yoruşun yok mu

Allah-a elimi açtığım an da

Dudağım da amin oluşun yok mu

Yalnızlık ararken karanlıklar da

Hicranla dünyama doluşun yok mu

Çılgına çevirir, öldürür beni', 'Başımı yastığa koyduğum zaman Gelipte rüyama girişin yok mu Sarılıp boynuna öptüğüm zaman Ardını dönerek gidişin yok mu Gözlerin sevgiyi anl...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ah-yok-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asiyâr', 'asiy-r-adem-tok-50x5h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hep bir şey söylemeni isterim

asiliğinden

inatçılığından söyle

varsın inanmasın kimseler

gülsün

inatçılığından

asiliğinden söyle

yalnız geçen günler

her gün biraz daha öldürür

ben seni düşünürüm

konuşmasanda bilirim

kalbime akan gizli nehirlerinden:

sen beni düşünür...

hissediyorum boğulduğunu

sen yakınsın sen uzak

sevgilimsin hayata bağlayan

yoldaşım

arkadaşım

kopmayı dahi beceremediğimiz

bekliyorsun

bekliyorum

sırdaş edip bir ezgiyi voltada (uğrini uğrini) 

sen ne diyorsun ASİYÂR

söyle

inatçılığından

kendinden hep bir şeyler...

                                                              (10.09.04) 

                                                             f tipi hapishane EDİRNE', 'hep bir şey söylemeni isterim asiliğinden inatçılığından söyle varsın inanmasın kimseler gülsün inatçılığından asiliğinden söyle yalnız geçe...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/asiyar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kararsızlık', 'kararsizlik-kadir-albayrak-j2l4c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim değilsen bile

Uzaklar da bir yerde yaşıyorsun

Birileri tenine dokunuyor olsa bile

Biliyorum ki nefes alıyorsun! ...

Ya bir gün seni; 

''ÖLDÜ'' diye duyarsam 

Ne yaparım? ....

Seni topraklara nasıl koyarım? 

Tek dostum ''ÜMİT'' kaldı dünya da

Onun yüzüne nasıl bakarım? ....

.................

.................

Benim değilsen bile

Biri doldurmuş gönül boşluğunu

Beni bir köşeye sıkıştırsa bile

Gösterip dünyanın kaç bucak olduğunu! ..

Ya bir gün seni; 

''DÖNDÜ'' diye duyarsam

Ne yaparım? ....

Ümidi kalbimden nasıl kovarım? ..

Senden daha çok sevmişim onu

Senin yüzüne nasıl bakarım? ! ......', 'Benim değilsen bile Uzaklar da bir yerde yaşıyorsun Birileri tenine dokunuyor olsa bile Biliyorum ki nefes alıyorsun! ... Ya bir gün seni;  ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kararsizlik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dertleştim', 'dertlestim-mustafa-yazka-pq170', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Selvi kavak nazlı nazlı sallanma,

Bu civarda kesinlikle yok dengin,

Herşeylerden yanı fakirim sanma,

Dertten yanı deli gönül çok zengin.

Kışı görünce ateşe yanma,

Ateşlerden sonra kül olur benzin,

Herkesleri samimi dostun sanma,

Ayran içincede yanıyor genzin.

Mustafanın derdi deryadan geniş,

Herkesin derdini kendinin bilmiş,

Zalimle cahilin hedefi imiş,

Mazlumların yaşamı her an düzgün.', 'Selvi kavak nazlı nazlı sallanma, Bu civarda kesinlikle yok dengin, Herşeylerden yanı fakirim sanma, Dertten yanı deli gönül çok zengin. Kış...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yazka']::text[], 8.5, '{"poet":"Mustafa Yazka","poet_slug":"mustafa-yazka","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dertlestim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım sıkılıyor', 'canim-sikiliyor-hidir-dastan-1eev4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Canım sıkılıyor bu gün

ve sitem dolu kelimeler

dökülüyor dudaklarımdan.

Canım sıkılıyor,

İçim yanıyor bu gün.

Torosları devirmek

ve Fırat''ın azgın sularını

kucaklamak geliyor içimden.

Haykırmak istiyorum

Tüm Dünya''ya

''Seni seviyorum'' diye

Yüreğim yanıyor bu gün.

Fırtına gibi esiyor gözlerimin dumanı

Kelimelere isyan ediyorum

Duygularımı yansıtamadıkları için

Oysa neler var yüreğimin derinliklerinde...

28.11.1990', 'Canım sıkılıyor bu gün ve sitem dolu kelimeler dökülüyor dudaklarımdan. Canım sıkılıyor, İçim yanıyor bu gün. Torosları devirmek ve Fırat''ın...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Daştan']::text[], 8.5, '{"poet":"Hıdır Daştan","poet_slug":"hidir-dastan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/canim-sikiliyor-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Camlar kırıldı', 'camlar-kirildi-kadir-albayrak-gzzgw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hasreti mi anlatsam sana

Yoksa asırlık özlemi mi? 

Yere göğe sığdıramadığım sevgiyi mi,

Ya da bu garip rezilliği mi? 

Kah tebessüme yamanıyor dudaklarım

Kah bir nehir göz pınarlarım

Ya da azap tohumlarıyla birlikte ekildiğim

Tarlalardan mı bakmalıyım? .....

......................

Belki de biraz seninle uğraşmalıyım! 

Sen ''SUÇUM YOK'' de! ...

Öyle bir günah denizindesin ki! 

Haksız mıyım? ....

Beni anlasaydın ellere yar olmazdın

Gece karanlığın da kör bir kurşun gibi kaçmazdın

Ve değersizliği öğretip beni satmazdın! ..

Yirmi yıldır ağlatmazdın! ...

Suçun yok! ... Öyle mi? ...Boşversene

Sahi; Gözlerinde ki ne? ..

Pişmanlığın kol gezdiği nedamet mi,

Ya da sermayesi arttırılmiş lanet mi? 

Anlamak öyle zor ki! .....

Oysa gönül diyor ki; 

Keşke gökten damlayan billurlar gibi

Sevgi olsaydı! ..

Ve beni tepeden tırnağa ıslatsaydı! 

Dilin o cümleyi kullansaydı

..............................

Mazi yapraklarında bir şeyler paylaşılırdı

Nerede benim hissem? 

Ümitlerim, geleceğim, gençliğim, ellere dağıttığın sevincim...

Boşluklara mı astın ''kolye'' diyerek

Hem de insafsız, hem de bilerek! ...

Bir koltuk değneğim vardı, onu da kırdın,

''MUTLUYUM''  diyerek! ...

Suçun yok! .. Öyle mi? .. Belki de haklısın! 

Suçlu olsaydın bu cezayı sen çekerdin

Faturayı ben ödediğime göre ''Suçlu benim''

Ve cezamı çekiyorum! 

Çünkü seni ceza çektirmeyecek kadar

ÇOK SEVİYORUM! ......

.......................

Sahi unutmadan,

İdam sehpası ne tarafta? ! ...........', 'Hasreti mi anlatsam sana Yoksa asırlık özlemi mi?  Yere göğe sığdıramadığım sevgiyi mi, Ya da bu garip rezilliği mi?  Kah tebessüme yamanıyo...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/camlar-kirildi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum', 'seviyorum-hidir-dastan-qqrwo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni düşündüm dün gece

Ve içimi bir sitem kapladı

Yüreğinde yaşamak isterken delice

Kana bulandı gözlerim.

Dün ''seviyorum'' sözcükleri

dökülürken dudaklarımdan

Bu gün sitemler yağıyor kaderime

Karanlığa bakıyorum artık

Yüreğim de susmuş.

Sessizliği dinliyor

Sessizce...

Ama böylesine kırılmamıştım

böylesine sarsılmamıştı

bedenim ve ruhum

Şimdi

Üşüyorum ve yalnızım artık

Belki mahkumum yalnızlığa

Belki de seni severken

Sensizliği yaşamaya.

Olmadı işte

Unutacağım derken seni

Büsbütün bağlandım.

Ama

Biraz olsun düşünseydin beni

Ardında kırılmış bir kalp

Ve boş bir beden bırakmazdın.

Yinede seni çook seviyorum...

29.11.1990', 'Seni düşündüm dün gece Ve içimi bir sitem kapladı Yüreğinde yaşamak isterken delice Kana bulandı gözlerim. Dün ''seviyorum'' sözcükleri dökülü...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Daştan']::text[], 8.5, '{"poet":"Hıdır Daştan","poet_slug":"hidir-dastan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/seviyorum-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesleğim:Yaşatmak', 'meslegim-yasatmak-adem-tok-b9ilv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ben bir şair sen bir imge

benim mesleğim yaşatmak

gün olur akarım

bal çekene bakarım

kovan alır elime

acıya uzanırım

ben bir şair sen bir kalem

benim mesleğim yaşatmak

kalem ol ki

düşüncemi yaz

avucuma dokun

çalsın dalımda saz

ben bir şair sen bir mısra

benim mesleğim yaşatmak

emeğe gönül verenlerin

okuduğudur mısra

mısram kalasın ki

umut aya olsun yapraklara

ben bir şair sen bir ana

benim mesleğim yaşatmakl

ana olasın ki

büyüsün çocuklar

onlar öğretsin harfleri

yok olsun sinsice sızan ağular

DEVRİMCİ:

kaç ihtilal yaptım içimde

felsefem hep doğru

tarihin akışından

rüzgârın yağışından okyanus kurdum

deryalar taşıyan

-nehirler öksüz değil! dökülüyor-

GÜNEKEN:

hasada şafAk olan günü eken çiftçiyim

Saban değmeyen iliğe

nakışLarım deste deste nakş olur yurduna

ferhat benim kadAr sevdimi

vurdukça gürzü dağına...

                                                                     (23.03.04) 

                                                                    f tipi hapishane EDİRNE', 'ben bir şair sen bir imge benim mesleğim yaşatmak gün olur akarım bal çekene bakarım kovan alır elime acıya uzanırım ben bir şair sen bir ka...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/meslegim-yasatmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baş Çelişki', 'bas-celiski-adem-tok-rm1sn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'cennet öbür yakaysa

cennetböceklerinin işine burda...

                                                                 (23.03.04) 

                                                                 f tipi hapishane EDİRNE', 'cennet öbür yakaysa cennetböceklerinin işine burda...                                                                  (23.03.04)           ...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bas-celiski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deliliğe Methiye', 'delilige-methiye-necip-gulecer-oycus', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Demirden kuyruklar takarım

Şeytan uçurtmalarına

Sersemliğine getirir rüzgârın

Yük ederim sırtına,

İpin ucunda çektiğim ne varsa...

Şapkalar inşa ederim

Konserve kutularından beş kuruşa

Temelinden kuşağına

ama o kadar olur..

Hasırlara Yaslar gövdemi 

kendim bile şaşarım şapkalığına 

Büyük eserimin

Fazladan basarım

notalarına 

Sessizlik senfonisinin

Çakana aşk olsun,

Sonra mahşer diye koşalar

bazı zaman kıpırdamam

O zaman anla

Molasıyım

Kaçırılan posta trenlerinin.', 'Demirden kuyruklar takarım Şeytan uçurtmalarına Sersemliğine getirir rüzgârın Yük ederim sırtına, İpin ucunda çektiğim ne varsa... Şapkalar ...', ARRAY['Türk Edebiyatı','Şiir','Necip Güleçer']::text[], 8.5, '{"poet":"Necip Güleçer","poet_slug":"necip-gulecer","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/delilige-methiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz''e', 'deniz-e-i-brahim-kilinc-eq8uw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevinçli bir haber aldık Deniz''den

Fırtınalar geçmiş, dalgalar durmuş

Sevda ateşiyle yanıp dururken,

Gönlündeki karşı ateşi bulmuş

Beden bir, yürek bir,olmuşlar bir can

Yorulduklarında sevdaları han

''Benzer''ken tanıdık sıcacık bir can

Ne mutlu ki ona olmuş ''Ardahan''', 'Sevinçli bir haber aldık Deniz''den Fırtınalar geçmiş, dalgalar durmuş Sevda ateşiyle yanıp dururken, Gönlündeki karşı ateşi bulmuş Beden bir...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/deniz-e-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkiyem', 'turkiyem-orhan-eren-uncu-df6vz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Türkiyemin eli kınalı

Doğduğundan beri var altından tacı

Ne badareler atlattı,kimlere baş kaldırmadı

Ata ocağı,bereketi bol Türkiyem

Türkiyemin, her bir yeri kale

Onurlu şehitlerimin ruhu ile,sarılmış çelik gibi bedeni

Denizler gibi yüreği

İnsanlarınla,ne büyüksün Türkiyem

Savaşlara, savaş demedin

İhtiyar çocuk genç,yoklukla inşaa ettin

İnsanınla yoğurdun,kanla sıvadın

Ata ocağısın Türkiyem

Dünyaya şerit çektin

Benim vatanım burası dedin

Ülkeler arası köprüsün sen 

Ata ocağı, bereketi bol Türkiyem

2004', 'Türkiyemin eli kınalı Doğduğundan beri var altından tacı Ne badareler atlattı,kimlere baş kaldırmadı Ata ocağı,bereketi bol Türkiyem Türkiye...', ARRAY['Türk Edebiyatı','Şiir','Orhan Eren Uncu']::text[], 8.5, '{"poet":"Orhan Eren Uncu","poet_slug":"orhan-eren-uncu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/turkiyem-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklermisin', 'beklermisin-guler-atas-p8jrc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çocukluğuma döndüm seninle,

Sanki / zaman değildi aramızdaki

Bu coşku/  düşerken kaldırdı yeniden.

Sen miydin / sessizce süzülen içime.

Yoksa / adı hasret bir sevdamıydı,

Kapı ağzında bekler gibi duran.

Hiç kapanmayacak bir yaranın,

Üstüne oturdu gelişin.

Gözlerimdeki / seli silebilir misin? 

Bekler misin? 

Sabırla.', 'Çocukluğuma döndüm seninle, Sanki / zaman değildi aramızdaki Bu coşku/  düşerken kaldırdı yeniden. Sen miydin / sessizce süzülen içime. Yoks...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/beklermisin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana türkü söyle', 'bana-turku-soyle-ali-cevat-876t1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aklına düşersem eger; 

Baba bana türkü söyle.

Ayrılık zor imiş meger,

Baba bana türkü söyle.

Ademle havvadan beri,

Sen ögrettin kardeşiligi,

Olsun insanlık eseri,

Baba bana türkü söyle.

Dinleyenler mestin olsun,

Tüm insanlar dostun olsun,

Felege de restin olsun,

Baba bana türkü söyle.', 'Aklına düşersem eger;  Baba bana türkü söyle. Ayrılık zor imiş meger, Baba bana türkü söyle. Ademle havvadan beri, Sen ögrettin kardeşiligi,...', ARRAY['Türk Edebiyatı','Şiir','Ali Cevat']::text[], 8.5, '{"poet":"Ali Cevat","poet_slug":"ali-cevat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bana-turku-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gece', 'o-gece-tuncay-akdeniz-4rec9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönüller coşunca akıttı seller

Damladan deryaya döndüm o gece

Dünyadan semaya kalkınca eller

Teslimiyet hakka sundum o gece

Melekler semadan inmişler  hacca

Muhammedi vuslat etmiş mirac''a 

Oruç''a  başlamış bakın ağaca

Ruh bedenden çıkmış sandım o gece

İftar sofrasına  sundular hurma

Hasretine kanat çırpan o turna

Kevser havuzunda altın bir kurna 

Zemzem pınarından kandım o gece

Künde varlığına bir karar kıldım

Faniyim aşkına lâli- zar  oldum

Arzından arşına seyrana daldım

Can  beden içinde nemdim o gece

Bu yazıyı yazan  levh-i  o kalem

İsmini niyazla andı tüm alem

Kadir gecesiydi alınan selam

Hakkın dergahında demdim o gece

Tuncay  otur kendi haline ağla

Gönlünü o lütfu güzele bağla

Hakkın ateşiyle yüreğin dağla

İbrahim narıyla yandım o gece', 'Gönüller coşunca akıttı seller Damladan deryaya döndüm o gece Dünyadan semaya kalkınca eller Teslimiyet hakka sundum o gece Melekler semadan...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/o-gece-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençliğim', 'gencligim-orhan-eren-uncu-00bd2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir dünya var; gençliğim

Yaşayamadığım, yorgun

Kan ve zulümle beslenen

Mesken temeli, can olmuş

Oyun alanları morg olmuş

Bir dünya var gençliğim

Sürekli kaynayan

Umutsuz gençliğe, yük olmuş

Zamanı umutsuzlukla

Yoğurmuş gençliğim

2004', 'Bir dünya var; gençliğim Yaşayamadığım, yorgun Kan ve zulümle beslenen Mesken temeli, can olmuş Oyun alanları morg olmuş Bir dünya var gençl...', ARRAY['Türk Edebiyatı','Şiir','Orhan Eren Uncu']::text[], 8.5, '{"poet":"Orhan Eren Uncu","poet_slug":"orhan-eren-uncu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gencligim-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönderemediğim mektup-2', 'gonderemedigim-mektup-2-guler-atas-5k9ur', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönderemediğim mektup-2

Her gün bir yaprak düşürüyorum takvimlerden

Sonbahar havasıdır.

Günler böyle dökülür çaresiz.

Baharda böyle düşer 

Bir ağacın dallarından.

Zaman yaprak sanır kendini yüreğimizde

Yazda geçer

Cehennem sanır kendini temmuz

Bir avuç kor atar içimize.

Her mevsim dönümü esen rüzgar.

Uçurur küllenmeyen acının tozlarını

Aklımızdan çıkmaz

Acı

     Ateş

            Temmuz

Zaman sadece akar takvimlerde

Ben kum tanesi 

Kendime akar gözlerim

Irmak olur coşar

Yıkar içimi dışımı

Zaten kum tanesiyim 

Kum saati zamanda

Akar 

       Akar

              Akar

Her ay temmuza bakar

                                               24/09/2005', 'Gönderemediğim mektup-2 Her gün bir yaprak düşürüyorum takvimlerden Sonbahar havasıdır. Günler böyle dökülür çaresiz. Baharda böyle düşer  B...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gonderemedigim-mektup-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönderemediğim mektup-3', 'gonderemedigim-mektup-3-guler-atas-4bekl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep seni düşünüyorum

Sol göğsümün altına bıraktığın acı

Ya acı seni hatırlatıyor

Ya sen acıyı

Beynimden yüreğime giden yollardasın

O kadar kısaldı ki 

Sana giden yollar

İçimdeki hasret kadar yakınsın

Hasret özlemekse

Özlemin sağanak her gün gözlerimde

Sessiz çığlıklar atıyor içim

GEL

Her fırsatta bağırıyorum

DUY

Gelemiyorsun duyamıyorsun biliyorum

Ama ben yinede 

Her gece açık bırakıyorum penceremi

Düşlerime gir

Hayal meyal uğruyorsun

Gecelerimin  kıyısına 

Sesini özledim

Cevap ver

Dün seni aradım

Hala silmedim numaranı

ÇALDI

           ÇALDI

                       ÇALDI

Bu sessizlik cinnet

Çıldırtan bir sükunettesin

Sadece mutlu ol istiyorum

Gidenlere alışığım

Gelmeyenlere asla 

Beyazlarla gidenlerin gelmediğini öğrendim

O yüzden sevmem beyazı

Siyahlar matemdir

Bu yüzden giymem siyahı

Bak sana pembe getirdim

Huzurdur dönüş yolunda

Bu gece açık bırakıyorum 

Bütün kapıları davettir

Düğüne gelir gibi GEL

Bütün sitemim hasrettendir

Bağışla beni ama

                    GEL

                                      30/08/2005', 'Hep seni düşünüyorum Sol göğsümün altına bıraktığın acı Ya acı seni hatırlatıyor Ya sen acıyı Beynimden yüreğime giden yollardasın O kadar k...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/gonderemedigim-mektup-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlı Akşamlar', 'yildizli-aksamlar-orhan-eren-uncu-bo61u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıldızları sar bana

Diz, tek,tek yürek acıma

Sarıl, sarıl, sar bana

Canım yanmaz, alışkındır acıya

Acıyı da, aşkı da görürüm ben

Yıldızların parıltısın da

Buğulu yalnız, akşamlarda

Aşkı karıştır yıldızlarla, 

sar bana

Sev beni, derin, derin

Gör beni, yeşil, yeşil

Yıldızlar,

Kararmaya başladı

Yıldızları yak bana

Akşam, yıldızlarda  yaşar oldum

Gecenin karanlığında

Seni yıldızlar da arar oldum

Yıldızım, parla bana

Keskin ucunla sarıl bana

Gökyüzün de, yıldızların arasında

Parla bana

Sarıl bana

12.04.2004', 'Yıldızları sar bana Diz, tek,tek yürek acıma Sarıl, sarıl, sar bana Canım yanmaz, alışkındır acıya Acıyı da, aşkı da görürüm ben Yıldızların...', ARRAY['Türk Edebiyatı','Şiir','Orhan Eren Uncu']::text[], 8.5, '{"poet":"Orhan Eren Uncu","poet_slug":"orhan-eren-uncu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yildizli-aksamlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olaydım', 'olaydim-i-lhan-kirbac-fb497', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bedr''in aslanlarından biri olaydım,

Son peygamberin kalkanı,

Ayağının tozu olaydım.

Bilal''in okuduğu ezan olaydım.

Yunus''un asası olaydım,

Anadolu''da dolaşan.

Yıldırım''ın atı olaydım,

Niğbolu''da.

Ulubatlı''nın elindeki sancak,

İstanbul surlarında,

Barbaros''un gemisinde yelken,

Preveze önlerinde.

M.Kemal''in saati olaydım,

Anafartalarda.

Sigarası olup yanaydım,

Kocatepe''de kar üstünde.

Vatan aşkıyla yanan,

Bu aşkla şiirler yazan,

Sevdaya düşüp yazan,

Şairin kalemi olaydım.

Mermi olaydım,

Mehmet''imin silahında.

Bizi birbirimize düşürenlerin,

Hainlerin,akreplerin,

İki kaşının tam ortasında,

Mermi olaydım.', 'Bedr''in aslanlarından biri olaydım, Son peygamberin kalkanı, Ayağının tozu olaydım. Bilal''in okuduğu ezan olaydım. Yunus''un asası olaydım, A...', ARRAY['Türk Edebiyatı','Şiir','İlhan Kırbaç']::text[], 8.5, '{"poet":"İlhan Kırbaç","poet_slug":"i-lhan-kirbac","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/olaydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimdeki Zenginlik', 'yuregimdeki-zenginlik-orhan-eren-uncu-ahup0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün..! 

Bir zenginliğim olursa eğer

Bir yuva kuracağım

İçin de sen olacaksın

Beyaz bir gelinlikle süslediğim

Bir gün,

Bir zenginliğim olursa eğer

O yüreğimdeki zenginlik, sen olacaksın

Delicesine sevdiğim

Bir Gün..! 

17.03.2005', 'Bir gün..!  Bir zenginliğim olursa eğer Bir yuva kuracağım İçin de sen olacaksın Beyaz bir gelinlikle süslediğim Bir gün, Bir zenginliğim ol...', ARRAY['Türk Edebiyatı','Şiir','Orhan Eren Uncu']::text[], 8.5, '{"poet":"Orhan Eren Uncu","poet_slug":"orhan-eren-uncu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yuregimdeki-zenginlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Gidi Gençlik’e Cevap', 'hey-gidi-genclik-e-cevap-ramazan-ates-ypohu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O günlerim ne oldu,

Yüreğim ona yandı.

Gençliğim tozup gitti,

Bana hatıra(m)  kaldı.

Şimdi ağardı saçlar,

Döküldü bitti dişler,

Avlanmak şöyle dursun,

Zor gelir bütün işler,

Deli dolu günlerdi

Bir anda gelip gitti,

Şimdi oyuncak oldum,

Dizimde derman bitti.

Ava gitsem avlanlar,

Deli diye bağlarlar,

Geçen güne yanmam da,

Bu gün beni yorarlar.

Hayırlı ömür olsun,

Gelen hayırlı gelsin,

Öldümden kaygım yok da,

Yeter ki adam bilsin,

İyi adamdı desin.

Ramazan Ateş/Enschede-18.11.2005', 'O günlerim ne oldu, Yüreğim ona yandı. Gençliğim tozup gitti, Bana hatıra(m)  kaldı. Şimdi ağardı saçlar, Döküldü bitti dişler, Avlanmak şöy...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hey-gidi-genclik-e-cevap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zor Bilemezsin', 'ne-zor-bilemezsin-i-lknur-cekici-udy14', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni silmek yazgımdan

Adını unutmak gecelerde

Ağlayamamak sessizce

Ne zor bilemezsin

Yaşamak varken doyasıya

Hissetmek varken sevdanı

Yollarında ölmek, sana uyanmak,

Koklamak varken gül kokunu

Seni bitirmek yüreğimde

Solmamak kör gecelerde

Ne zor bilemezsin

Gözlerine baktıkça erimek

Akan yaşlarında sönmemek

Kendimi sensizliğe itmek

Ne zor bilemezsin

Sen hayatıma giren

İmkansız yürek

Sen darmadağın eden

Bahar yeli

Santim santim soluyorken seni

Yokluğuna alışmak

Ne zor bilemezsin

Seni bensizliğe mahkum etmek

Yalan sözlere sevgi demek

Kara gecelerde sensiz gülmek

Ne zor bilemezsin', 'Seni silmek yazgımdan Adını unutmak gecelerde Ağlayamamak sessizce Ne zor bilemezsin Yaşamak varken doyasıya Hissetmek varken sevdanı Yollar...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ne-zor-bilemezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır Veriyorum Sadece Sana', 'sir-veriyorum-sadece-sana-bahri-yildirim-o6yje', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyor musun? 

Benim seni  neden bu kadar sevdiğimi? 

Susuyorsan,korkuyorsan söylemekten

Ben söyleyeyim o zaman

İkimizin yerine.... 

Ben seni:

Sevda denen kavganın

Ne kadar zor

Ama o kadarda onurlu olduğunu

Görüp bilesin diye sevdim.

Bu yüzdendir, gönül gözlerinde saklandığım

Düşlerinde yaşlandığım.

İyi ki seni sevdim...kadınım

İyi ki seni sevdim.', 'Biliyor musun?  Benim seni  neden bu kadar sevdiğimi?  Susuyorsan,korkuyorsan söylemekten Ben söyleyeyim o zaman İkimizin yerine....  Ben se...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sir-veriyorum-sadece-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönderemediğim mektup-4', 'gonderemedigim-mektup-4-guler-atas-ndemv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayat seni terk etti değil mi gülüm

Gülümsüyordun

Hayatla dalga geçer gibi yaşamıştın

Çaldığım zamanlar der gibiydin

Şans sana ikinci bir hayat vermişti

40” aşmış gözaltılar

Yaşamının yarısını gasp etmiş işkenceler

Ölüm oruçları

Direnişler

İnançların mı sarsılmıştı bu gün

Yoksa uğruna ayakta kalacak

Amaçların mı bitmişti ki

Açıverdin avuçlarını

Kuş gibi uçsun diye hayat ellerinden

Ölüm biyolojik bir şey

Biyolojik ölümlere hazırlıklıydın

Talimliydin zaten

Ramak kala dönmüştün 

Tutunduğun düğümlerin son halkasından

Hep dünyalı olmak ağır basmıştı

O gün ne oldu neden vazgeçtin

Neden  en zor görevi bıraktın bize

Ayaklarım nasıl taşıdı bedenimi

Bilemezsin 

Aklım sana  yer beğenirken

İnanmadı yaptıklarıma', 'Hayat seni terk etti değil mi gülüm Gülümsüyordun Hayatla dalga geçer gibi yaşamıştın Çaldığım zamanlar der gibiydin Şans sana ikinci bir ha...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gonderemedigim-mektup-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkinci İzmir Cinayeti', 'i-kinci-i-zmir-cinayeti-nermin-altindag-0bh0r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İbrahim

Gönlünü put sanıp da kıran kim

	

		Asaf Halet Çelebi

İKİNCİ İZMİR CİNAYETİ

- Abdullah Uğur ve Ebu Bekir Derda’ya - 

Reyhan kokusuna inat küflü yosunlar

Ellerin eziyor altın varaklı çerçeveleri

Süzgün sözlerimi şeytan dürtüklüyor

Susmalıyım, konuşursam ağlarım

Reyyan yüzüne inat küflü ağıtlar

Efsunu bilgeliğin şair mi etmiş seni de

Bu kadar çabuk mu büyütmüşsün içindeki yılanı

Yılan yalana tâbi, ayakları yok

Yok oğlu gök, rahmet ok

Efsunlu omuzu kadının erkek mi etmiş seni de

Ceplerimde yatıramadığım hacılar ve eksikliği zülmun

Sarhoş bardaklar çağırıyor, gitmeliyim

Ölü sineklerle dansım var, bu gece yitmeliyim

Zillere ve zurnalara eşlik etmeliyim

Ceplerimde okumadığım şiirler ve cinayeti İzmir’in

Elbisesi süslü gelin, kanıyor ciğerlerin

Elleri sıcak ölümün, gidemem gidemem

Pencerede saksı ağlıyor, ağlıyor Aze’m

Elleri sıcak Azrailin, sevemem sevemem

Elbisesi kanlı gelin, kanıyor gelinliğin

Parlıyor otuzüçüncü dişim, cinayetin tek şahidiyim

Hem maktulum, hem katilim, hem şahidim

Bilseydim türkü söylemesini hiç sönmezdi ateşim

Hem kadınım, hem erkeğim, hem meleğim, hep iblisim

Patlıyor otuzüçüncü dişim, cinayetin tek sebebiyim

Misketimi kaybettim, ütülen hep benim

Mesnetimi kaybettim, kimliğim hükümsüz

Melekemi kaybettim, kayıtsız köşelerdeyim

Mirasımı kaybettim, evsizim, döşeksizim

Misketimi kaybettim, ütülenen hep benim

Eyvahlara karıştım, ervaha bulaştım

Dolunayla yarıştım, dişlerimi parlattım

Eldivensiz ellerle cinayete karıştım

Dolunayla bakıştım, bulutlarla yarıştım

Eyvahlara alıştım, eyvanlarda kan karışığım

Rahvan yürüyüşleri çöllerde bıraktım

Çölüme bir damla su ol, merhametsiz rahibim

Karaağaç gölgesiyim, bozkırda gelin-ciğim

Susuzum, sussuzum, kepezsiz gelinim

Rahvan yürüyüşleri çöllerde oynattım

Vakit sabaha ermez, hiç batmaz güneşsin

Gözlerimi yakan kar taneleri sözlerimi serinletmez

Çalmadım kaburga kemiğini, elmayı da ben dişledim

Bütün suç benim, kalbimi hep dinledim

Vakit sabaha ermez, hiç bitmez güne eşsin

Anlamaz dilim süslü kelimelerden

Bilgelikten vazgeçtim, hele şair hiç değilim

Uhud’da Halid’e dokunabilseydim

Dikilitaş’a yazardım sesini, suretini, siretini

Ağlar dilim puslu sözlerinden

Nedenliyim, neden hep sendeyim, ben nerdeyim

Nerde başladım, nerde bittim, neden bu kadar biçareyim

Gururu taş edip çekince burnuma

Kangrenlerle nimetlendim, cenazemin başını çektim

Nedenliyim, hep sendeyim, sen nerdesin

Takvimlerden kopan her bir yaprak toprağa karışan

Bilmediğim yollarda rüyalarımla dalaşan

İzdüşümleri yalan yılların, gerçeğim yok

Kandırmacası yaşlanan yüzümün ve çirkinliğimin

Takvimlerden kopan her bir yaprak toprakla kucaklaşan

Olmasaydı ellerim bu kadar hain

Varsaydım menziline peşine takıldığım trenin

Çekmeseydim frenini yorgun yüreğimin

Tek suçlu ben miyim, hep deli sen misin

Olmasaydı yüreğin bu kadar hain

Kokmazlığına aşinalığım kaktüslerin

Eski zamanların efsanesi, Asya’da Hazar’ım

Hazarım, hazanım, harmanım, ahuzarım

Gülizarım dağlarda, iniyim eşkıyanın

Korkmazlığına aşinayım korkaklığımın

Sus, uyanmasın serçeler, buhuruna gebeyim

Yak bütün gemileri, Endülüs’te rakkaseyim

Düğünlerde dua eden tozlu gelinim

Sarıkız’ ın tekkesinde ayin yapan meczup çirkinim

Sus, uyanmasın serçeler, buhranına gebeyim

Olmasın, cenazemde kimse ağlamasın, etimi akbabalar kemirsin

Dolmasın mezarım, toprağım olmasın, olmasın mezarım

Cinnet mahalli kayıtlara geçmesin, adımı kimse bilmesin

Adını herkes bilsin, sahi, adın neydi senin

Olmasın cehennemde başka kimseye yer, Tanrı zebanileri azad etsin

Yokluğun zehirden aş, varlığımdan bihabersizimsin

Habersizim, ajanslara dolunay vakti geçmişim

Serseri mayınım, kim bilir nerde patlarım

Gülizarımı Bornova’da polislere ben ihbar ettim

Ege’yi intiharınla neden kirlettin

Bu cinayeti de kayıtlara ben geçtim

Kendim çaldım, kendim oynadım, kendim söyledim

Dokuz sekizlik çingeneyim, kemanımın kopuk teliyim

Yokluğunu varlığıma sebep bildim, seni hep sevdim

Hep sevdim

Hep sevdim 

Hep sevdim

Hep sevdim

Hep sev…….

Hep……..

…………..

15.11.2005 (16:00 20:41)    Dolunay vakti KADIRGA', 'İbrahim Gönlünü put sanıp da kıran kim 	 		Asaf Halet Çelebi İKİNCİ İZMİR CİNAYETİ - Abdullah Uğur ve Ebu Bekir Derda’ya -  Reyhan kokusuna ...', ARRAY['Türk Edebiyatı','Şiir','Nermin Altındağ']::text[], 8.5, '{"poet":"Nermin Altındağ","poet_slug":"nermin-altindag","theme":"Türk Şiiri","is_hero":false,"total_lines":102,"source_url":"https://www.antoloji.com/ikinci-izmir-cinayeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar Bilirim', 'i-nsanlar-bilirim-abdullah-yasar-erdogan-iqfxo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İNSANLAR     BİLİRİM

Dün dünyayı sahiplenip yaşayan,

Okunur oldu tarih sayfasından,

Fıtrat-ı kalemin kan damlayan,

Ne insanlar bilirim, pulunu sermiş.

Hak – hukuk yolunda bihaber olan,

Hanesi dünyalıkla dolup taşan,

Mazlumun ahını almış utanmadan,

Ne insanlar bilirim, yüzünü germiş.

İlmi irfanla ayrılmış divandan,

Nefis yüzünden kopmadı dünyadan,

Münafık şuuru sardı hülyadan,

Ne insanlar bilirim, bigane ermiş.

İmanlı olup dosta etmiş bühtan,

Bihaber kalmıştı Hakk’a kulluktan,

Daim haberdar olsa da yokluktan,

Ne insanlar bilirim, cendere vermiş.

Herc-ü merc içinde yok ki insicam,

Bin çile çekse de halifeyi can,

Gideceğini bilir elbet üryan,

Ne insanlar bilirim, gururu germiş.

Gönülden secde eden ol ki insan,

İlm-i nâfiye dalıp almış ihsan,

Hakk divanına Allah deyip varırsan,

Ne insanlar bilirim, irfana gelmiş.

Zulmette doruğa çıkıp putlaşan,

Yalan yanlış despot hayat yaşayan,

Ani dönüşle aşkı kucaklayan,

Ne insanlar bilirim, fermane olmuş.

Medet beklemiş şakiden ahmaktan,

Çok yaralar almış beşer davadan,

Geçte olsa haberdar olmuş nurdan,

Ne insanlar bilirim, dermane gelmiş.

Burçlarda bayrak olmuşsa davan,

İnandığı yolda olur itminan,

Boş olmamalı, olamaz da Müslüman,

Ne insanlar bilirim, murada ermiş.

İnkiyad ile nail olmuş nihan,

Selama gelecek, gelmeli cihan,

Rücû edecek saâdeti devran,

Ne insanlar bilirim, zamane gelmiş.

Muti ruh düzeninde var intizam,

Hakk yolundakine uğramaz hazan,

Sağında solunda var halin yazan,

Ne insanlar bilirim, mağruru yermiş.

Dünya malını hepten hiçe sayan,

Allah deyip, Allah diye yaşayan,

Var gayesini aşkıyla anlayan,

Ne insanlar bilirim, imana gelmiş.

Bühtan: İftira.

Bigane: Bildik olmayan, yabancı.

Cendere: Baskı ve basınç sağlayan alet.

Herc-ü merc: Karışıklık, intizamsızlık.

İnsicam: Tutarlılık.

İlm-i Nâfi: Faydalı ilim.

İtminan: İnanma, emin olma.

İnkiyad: İtaat, boyun eğme.

Muti: itaatkâr, itaat eden.

Şair: Abdullah Yaşar Erdoğan', 'İNSANLAR     BİLİRİM Dün dünyayı sahiplenip yaşayan, Okunur oldu tarih sayfasından, Fıtrat-ı kalemin kan damlayan, Ne insanlar bilirim, pulu...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/insanlar-bilirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadırga''ya/Ağlayan Aşk', 'kadirga-ya-aglayan-ask-nermin-altindag-nybhi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Baskınlar ve yağmalar

Bir gecelik aşklar

Ağlamayı bilmeyen kadınkızlar

Erkekliği bir duvar dibinde kalmış

Esrarkeşliğine arabesk 

	Bir aldanışı delil sunan

		Yanlış delikanlılar

Bu nasıl bir hayat ki 

Yitirilen her şafakta

Güneşin kızıl ağıtlarına

	Çarpan deniz dalgaları

		Arındırmaya yetmez

			Bu cenabetliği

Ölüm de aşk gibi 

Bir avuç kile muhtaç

Küllerimden bir şehir yarat

Devreleri yanmış bir radyonun

	Çıkartamadığı cızırtıları arasında

		Hapsolmuş bir bilgenin çocuklarıdır

			Kaldırımlarda oynaşan

				Serseri mayınlar

Kravatlı okul talebelerinin elinde

	Damarlarımı döven 

		Havyanın

			Yanık kokusuna karışmış

Özgürlüğün 

Ve 

Barışın simgesi kuşlar

Resmedilmiş her akbabanın 

Tüyünde

Kanımdan dökülen 

Kangrendir

Bu şehir ve bu kaldırımlar

Mini eteklerinde 

Bakir bir saflığı 

Taşımaya inat eden

Liseli kızlar

Sokak aralarında 

Sarmaş dolaş 

özgürlüğün elinde rehin

Biz seni nerede kaybettik

Ve nerede bulacağız 

Ey aman veren korku

Ey bulutlar 

üstü ütopyalarda kalmış

Gelecek kaygısı

Ey minarelerine

Yorgun güvercinler konan 

Yağmalanmış şehir

Ey ufkumun genişliği

Ey sefilliğe bulanmış ruhum

Nerdesin

Tanrım! 

Korkunu içimden alma…', 'Baskınlar ve yağmalar Bir gecelik aşklar Ağlamayı bilmeyen kadınkızlar Erkekliği bir duvar dibinde kalmış Esrarkeşliğine arabesk  	Bir aldan...', ARRAY['Türk Edebiyatı','Şiir','Nermin Altındağ']::text[], 8.5, '{"poet":"Nermin Altındağ","poet_slug":"nermin-altindag","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/kadirga-ya-aglayan-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadırga''ya/Yunus''a Ağıt/Utandıran Aşk', 'kadirga-ya-yunus-a-agit-utandiran-ask-nermin-altindag-9p8qq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-	küstürdüm gönülü güldüremedim

baharım güz oldu, yazım kış oldu – 

		

Neşet Ertaş türküsü

Bir de martılar var 

çöplüklerde dolaşan

Serçe kanatlarını kıran

Ve ekmek kırıntılarını 

Toplayan

Esrarkeş gecelerin şaşal

Diplerine sinmiş şahidi

Ve belki de balıkçı teknelerine 

Yağmur vurmuş gecelerde

Tek arkadaş

Sessizliğe kaçmış alacakaranlık

Aydınlıklarda habercisi

Gürültülü şehrin

Kollarında kesikleriyle sokaklarda 

Dolaşan Aziz’in ve Necmettin’in

Alem ortağı Yunus’un evden 

Kaçtığına ağlayan martılar

Yunus bu 

Söz dinler mi

Sözü dinlenir mi

Gece üşüyor diye 

tasasına düşülür mü

Babasıyla kapışıp 

İt gibi sürttüğü sokaklarda

Almazken kokusunu burnumuz 

	Yaktığı pankartların

Tuttuğumuz oruçları bozduran bir kibirle

Sabahın altısında açtığımız kapının

Arkasında sığındığı 

Çatının altında

Çektiği baliye yanmak

Merhametin

	Hangi ayağının altındadır? 

Merhamet 

Marazlı merhamet

Düşüren insanın insanlığını

İzlediğim her senaryoya

Parmak ısırtacak 

Yaşamlar

Yemek yediği sofranın 

Duasına amin derken

Bilmediği anlamına

Ve isyanıdır bu bilgeliğe 

	Bulanmış küfrün 

bedeli aşklar

Sarhoşum işte

Bundandır sokaklara 

Vuruşum bedenimi

Labirentlerinde kaybettiğim

	Bekaretimi 

		Belki bulurum umududur

			Aşk üzerine 

				Bunca söyleşim

Dağılmış ve kaybolmuş 

	Bir geleceğin parçalarından

		Bir hayat yaratma 

			Umududur

				Küllerini gözlerine 

					Gömdüğüm 

						Şiirlerim 

Bunca şeyin ardında kalan

	Bilgisiz ve bilinçsiz 

		Öfkesidir

			Yunus’un annesinin…', '-	küstürdüm gönülü güldüremedim baharım güz oldu, yazım kış oldu –  		 Neşet Ertaş türküsü Bir de martılar var  çöplüklerde dolaşan Serçe ka...', ARRAY['Türk Edebiyatı','Şiir','Nermin Altındağ']::text[], 8.5, '{"poet":"Nermin Altındağ","poet_slug":"nermin-altindag","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/kadirga-ya-yunus-a-agit-utandiran-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz gemi', 'sessiz-gemi-suleyman-yavuz-eq6b9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sessiz bir gemi gibi ayrıldım limandan 

Açıldım umman-ı deryaya 

Bu sefer ayrılığadır

Dönmek zor olur bir daha 

Belki dağılır yelkenim salım

Bir gün olur dibe batarım 

Ama dönmem o limana 

Boylarım deryanın dibini

Ama unutun beni

Çektim pimimi 

Patlamaya hazır bir bomba gibi 

Batırırım en dibe kendimi 

Ama dönmem daha gayrisi yok 

Kırıldı zincirlerim

Tutulmam bundan sonra 

Arkama bakmadan giderim

Ben sildim sizleri

Unutun gitsin sizde beni', 'Sessiz bir gemi gibi ayrıldım limandan  Açıldım umman-ı deryaya  Bu sefer ayrılığadır Dönmek zor olur bir daha  Belki dağılır yelkenim salım...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sessiz-gemi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salıngaç', 'salingac-yunus-isikoglu-skwlr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sağımda acılar

Solumda acılar

Acılardan acılara ip germişim

ip germişim de sallanmışım

Salıngacım ne güzel

Salıngacım ne zevkli

Sağ yanım acı

Sol yanım acı

Ortası salıngacım

Ben

Salıngacın üstünde

Keyife bak be...', 'Sağımda acılar Solumda acılar Acılardan acılara ip germişim ip germişim de sallanmışım Salıngacım ne güzel Salıngacım ne zevkli Sağ yanım ac...', ARRAY['Türk Edebiyatı','Şiir','Yunus Isikoglu']::text[], 8.5, '{"poet":"Yunus Isikoglu","poet_slug":"yunus-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/salingac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlatır Beni', 'aglatir-beni-kadir-albayrak-jls13', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnız sabahlarken ayaz geceler

Gökler yıldız yıldız ismin heceler

Gözümün önünde ah neler neler

Canlanıp canlanıp ağlatır beni

Yol aldı geceler sabaha sensiz

Hayalin canlandı belli belirsiz

Semada yıldızlar sendan habersiz

Kararıp kararıp ağlatır beni

Elveda dediğin o akşam var ya

Yer etmiş gönlümde derin bir yara

Hasretin rüzgarı sanki dört yana

Savurup savurup ağlatır beni', 'Yalnız sabahlarken ayaz geceler Gökler yıldız yıldız ismin heceler Gözümün önünde ah neler neler Canlanıp canlanıp ağlatır beni Yol aldı gec...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aglatir-beni-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-elif-sude-engl8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalbime doldun yine bu gece

Buram buram tüttü sevda tomurcukları

Bitmeyen hasret, vuslat özlemiyle sardı içimi

Yine eritti içimi geceleri yakan o gözler...

Kara gözlerinde mi bulmalı hayata küsen umut ışığını

Yoksa duaya açılan ellerinden yükselmeli mi yeni yeni ufuklara

Hissedebilmeli mi seni her çaresiz gözyaşında...

Kalbime doldun yine bu gece

Pırıl pırıl yıldızlar kaydı gökyüzünden

Sonsuzluğa haykırdığım şarkı düştü dilimden

Yine buldum kendimi yüzünün aydınlığında

Ama bu masal sona ermeli burda

El ele kırlarda dolaşmak mı aşk

Yoksa hasreti buram buram çekerek iç geçirmek mi

Dalıp gitmek mi denizin ağlayışına

Ben seni yokluğunda buldum

Kaybetmek istemem

Bırak değmesin gözlerin gözlerime

Bırak güzel yüzün solmasın gecelerimde

Benimki sizin yalan aşklarınıza pek benzemez

Bir aşk ki uğrunda koşulur ölüme

Bırak ki seveyim! bırak ki öleyim! 

                                         İLELEBET SENİNLE.....', 'Kalbime doldun yine bu gece Buram buram tüttü sevda tomurcukları Bitmeyen hasret, vuslat özlemiyle sardı içimi Yine eritti içimi geceleri ya...', ARRAY['Türk Edebiyatı','Şiir','Elif Sude']::text[], 8.5, '{"poet":"Elif Sude","poet_slug":"elif-sude","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ozlem-279-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönderemediğim mektup-5', 'gonderemedigim-mektup-5-guler-atas-z3v7n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yorgun düşmüş 

Yara almış gibi düşünmek istedim

Her an iyileşip 

Aşkıııım ne haber demeni bekledim

Kendimi aldata aldata

Vasiyet yerine getirdim

Nasıl zordu bilemezsin 

Seni istanbula vermek

Anla işte kabullenemiyorum gidişini

Bize güzel anılarını bırakmak için 

Sadece gittin

Her kavgada en öndeydin

Şimdide öndesin

Ama arkanda göz yaşları

Son yolculuk diyor bazıları

Sonsuzluğa yolculuk olmalı

Güzel bir uykuya dalmak

Rahat uyu kardeşim

Midemin altındaki

Hıçkırık yumağıyla sessizliğine 

Sessiz çığlıklar attım

Yıllardır her haberinde

Sadece midemdeki yumruyla konuştum

Hep sessiz akıttım gözlerimdeki nemi

Dostlarımız anlardı ama düşmanlar asla

kaç kez itilip kakılmıştık 

Her engele baş kaldırdık

Başa çıktık hepsiyle

Bu çok acıydı  kardeşim

Küfredecek o kadar şey bıraktın ki bize

Neye isyan edeceğimi bilemedim

Neydi seni aniden 

Hiç bilmeden

Hiç beklemeden koparan bizden

Vebalini almış herkeste kalacak tırnaklarım

Kızgınım öfkeliyim

Gözyaşlarım seni sonsuzlukla buluştururken

Hesap soramamanın acısı aslında

Bilirim böyle olsun isterdin çıktığın yolculuklar da', 'Yorgun düşmüş  Yara almış gibi düşünmek istedim Her an iyileşip  Aşkıııım ne haber demeni bekledim Kendimi aldata aldata Vasiyet yerine geti...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gonderemedigim-mektup-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Borçlusun', 'borclusun-ramazan-ates-b8jbh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ülkücünün ülkücüye,

Borcu vardır bilmelisin.

Öz kardeşin olmasada,

Onu candan sevmelisin.

Selam sevgi hürmet ona,

Toz kondurma candaşına.

Sana sahip olan odur,

Destek ol sen gardaşına.

Ülkümüzü büyütelim,

Davamızı yüceltelim,

Bu dava emanet bize,

Hem sevelim, sevdirelim.

Aç kalanın varsa ara,

Ülküdaşın koyma dara.

Bu gün ona yarın sana,

Gönüldaş ol ülküdaşa.

Allah yolun açık etsin.

Kutlu davan hep sevilsin.

Unutma hiç şehitleri,

Dua et ruhlarına varsın,

Tanrı Türkleri Korusun. (amin) 

Ramazan Ateş/Encshede, 18.11.2005', 'Ülkücünün ülkücüye, Borcu vardır bilmelisin. Öz kardeşin olmasada, Onu candan sevmelisin. Selam sevgi hürmet ona, Toz kondurma candaşına. Sa...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/borclusun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtiyacım Var', 'i-htiyacim-var-kadir-albayrak-0uhkw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dinleyin dostlarım dinleyin beni

Şu an da sizlere ihtiyacım var

Öyle bir çaresiz derde düştüm ki

Teselliye şimdi ihtiyacım var

Bana cevap verin bir cevap dostlar

Ayrılık şart diye bir kanun mu var

Bahara doymadan geldi sonbahar

Teselliye şimdi ihtiyacım var

Doğacak sanırken sabah güneşim

Ömrüme zamansız esti bir rüzgar

Nasılsın diyen bir sese hasretim

Teselliye şimdi ihtiyacım var', 'Dinleyin dostlarım dinleyin beni Şu an da sizlere ihtiyacım var Öyle bir çaresiz derde düştüm ki Teselliye şimdi ihtiyacım var Bana cevap ve...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ihtiyacim-var-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykırış', 'haykiris-elif-sude-zvwbc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana muhtacım Ya Rab

Merhametinle sar, sür beni diyar-ı aşka

Yalan sevgilerle kuşanmış şu kalbim

Bir nebze huzur dolsun şanınla

Boğuldum Sultanım,al kurtar beni

Şu yalan dünya hüzünler seli

Kimi zaman yari,kimi yareni

Kaybolur gider, kalır matemi.

Yetiş çarem, ağlatma beni

Burası ne sevgi ne de aşk yeri

Çıkar heves intikam gibi

Şeytanın zaferi sardı çevremi.

Yalnızlık diz boyu, özlem çığ gibi

Siyahlar içinde,kalbim lekeli

Benim için tek umut mağfiret eli

Ey çaresizin çaresi, mertin yaveri

Kucakla artık beni,sil gözlerimi

Ana baba şefkati; hepsi geçici

Birgün aydınlıksa birgün zifiri

Varsa sevdanın tek bir örneği

Vuslatına nail et, kavuştur bizi...', 'Sana muhtacım Ya Rab Merhametinle sar, sür beni diyar-ı aşka Yalan sevgilerle kuşanmış şu kalbim Bir nebze huzur dolsun şanınla Boğuldum Sul...', ARRAY['Türk Edebiyatı','Şiir','Elif Sude']::text[], 8.5, '{"poet":"Elif Sude","poet_slug":"elif-sude","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/haykiris-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varmısın Islanmaya?', 'varmisin-islanmaya-ramazan-ates-8td82', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben yağmuru seviyorum,

Çisil çisil yağıyorsa.

Göz yaşından korkmuyorum,

O sevğiyle akıyorsa.

Çisil çisil yağan yağmur,

Cama vurur ince ince.

Tadına doyum mu olur? 

Yağmasını seyredince.

Çisil çisil yağmur yağar,

Kuşlar dururlar altında,

O an ıslanmak isterim,

Sen gelirmisin yanıma? 

Varmısın gel ıslanmaya? 

Ramazan Ateş/Enschede-18.11.2005', 'Ben yağmuru seviyorum, Çisil çisil yağıyorsa. Göz yaşından korkmuyorum, O sevğiyle akıyorsa. Çisil çisil yağan yağmur, Cama vurur ince ince....', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/varmisin-islanmaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azap', 'azap-mehmet-akif-gulhan-uxoob', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kör olası, yıkılası duvarlar

Gelin üstüme üstüme

Kabir azapları yaşatın bana

Kör ışık kör kuyu

Arada sırada gelen yar sesi

Makber başında dua eden 

Vefakarın sesi gibi

Ne secdem var yaradana

Nede talkım sesi  geldi

Sadece karanlığı gördüm

Ve kabir azabını yaşamda

Ölmekten ne anlarsın sen

Son suyum son nefesim

Sayılı günümde yok benim

Sadece ak bezlere sarın beni

Ah! İstemem be onu da

Issız, bilinmeyen yerlere 

Gömün beni

Mehmet Akif Gülhan  18.11.2005 Saat 21.52', 'Kör olası, yıkılası duvarlar Gelin üstüme üstüme Kabir azapları yaşatın bana Kör ışık kör kuyu Arada sırada gelen yar sesi Makber başında du...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/azap-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Extase', 'extase-mim-ahmir-rengi-a4nqr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Extasdayım sana ey sevgili,çekerken dumanını cigaranın,

Terennümüne varıyor dudaklarım,bir satır nakaratın...', 'Extasdayım sana ey sevgili,çekerken dumanını cigaranın, Terennümüne varıyor dudaklarım,bir satır nakaratın......', ARRAY['Türk Edebiyatı','Şiir','Mim Ahmir Rengi']::text[], 8.5, '{"poet":"Mim Ahmir Rengi","poet_slug":"mim-ahmir-rengi","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/extase-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönderemediğim mektup-6', 'gonderemedigim-mektup-6-guler-atas-6xmim', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Daha çok ihtiyacım var sana

Ana dilimle 

Yüreğimle

Her gün daha çok özlüyorum

Daha çok odaklanıyorum 

Bakıp göremediğim

Durduğun yere

Önünden geçtim dün

Gözyaşı yolladım son ilticana

Yumuşacık bir el sildi yanaklarımı

Senin ellerin miydi

Çok yolcu geçmişti içimdeki yollardan

Çok trene elveda demiştim

Çok denizlerde 

Ufuklara güle dedi ellerim

Baktıkça uzuyor ufuk çizgisi

İçimdeki yolcu edemediğim

Seni arıyor gözlerim

Ne kadar uzağımda 

Ne kadar yakınımda 

Olduğunu bilmiyorum

Her ürperdiğimde

İçimden geçtin gibi geliyor saniyelerle

Ve hep ürperiyor duygularım

Gitmek yakışmazdı bu kadar sevgiye

Kalsaydın biraz daha

Daha çok erkendi be gülüm

Yarım bıraktın her şeyi

Çok yorgundun ama 

Hiç bıkkın olmamıştın hayattan

Hiç bu kadar uzun uyumazdın

Uyan artık

Her sabah öpüyorum seni gözlerinden

Bir ses bekliyorum

Her şey çok sessiz

Çıldırtıyor bu sessizlik

Eşyalardaki genleşme tıkırtısı

Uzun bir ayrılığın sesi sanki

Susun 

Yalnızlığın kokusu var bu sessizlikte

Renk körü gözlerimde

Siyah beyaz bir fotoğraf karesi oluyorsun

Umutlarımı yitirdiğim anda

Renksiz bir siluette boyuyorum yüzünü

Canlanıveriyor bütün anılarım

Yeniden yaşıyorum 

Çocuk gözlerimde çocukluğunu

Açılıveriyor göz kapakların

Hayat kuyusunu örten bulut gibi

Kayboluyorsun sonra

Giderken emanet aldın sol yanımı

Her şeyi olduğu gibi

İkizini de yarım bırakıp gittin

Bilinmeyen yollara

Dön diyemiyorum

Rahat uyu

Bir daha uyandırmayacağım

                                                   30/10/2005', 'Daha çok ihtiyacım var sana Ana dilimle  Yüreğimle Her gün daha çok özlüyorum Daha çok odaklanıyorum  Bakıp göremediğim Durduğun yere Önünde...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/gonderemedigim-mektup-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adresi Belli Mektuplar - XII', 'adresi-belli-mektuplar-xii-ugur-deniz-ulkegul-f5dpe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ah sevdalım..Göç bakışlar sarmış yine hüznünden arta kalan zamanı..

Yüreğin kadar çok yalnızlığa kafa tutan direncin, hasretin kadar yenik..

Yorgunsun yine..Elleri iki yana düşmüşlüğün, saçın başın dağınık..

Öfken hesabı yarım sırlar taşır  içinde..Hıçkırık sesinde boğulur acıların…

Yüzünde eğreti bir tebessüm, sesinde aykırılık…

Dik durmalı insan yine de..Hepimizin ölen bir yanı var..Geçmişin fitil tutmaz yarasından arta kalan sızıları..Çocukluğuna ve bazen adamlığına, bazen de kadınlığına sessizce gömdüğü umutları..Geç kaldığı kim bilir kaç bahar ve

erkenci dal kırıklığında mahkum olduğu kaç sonbaharı..Yine de sevmeli işte..

Hani elini uzattığında dokunmaya değer bir düşü olmalı..Yüzünde umut dolu

gülüşüyle bir çocuk bulmalı sokakta, yol üstü kaldırım sohbetinde rastladığı

bir dosta merhaba diyebilmeli, elini tutup ısıttığı bir ihtiyar, saçını okşadığı

sevdalı bir yar..

Hepimizin kendi içinde saklanan korkuları var…Elleri kan revan girdiği

amansız kavgaları..Yitirdiği sevdaları, yengileri, olmazları..Bir yerinden

tutmalı yine de yaşamı..Bazen en zor anında kavganın, gökyüzüne bakmalı..

Kırmızının öfkesine inat, maviye dokunmalı..

Bir dostum aradı geçen gün..Uzaklardan bir yerden..

”Bu sefer Oyun büyük” diyor..İlk kez endişe sezdim konuşmasında, ilk kez öfke vardı kelimeleri seçip tonlamasında…

Diyor ki, 

“Birbirimize düşürüyorlar bizi..Kapı komşusu olan düşman kesiliyor diğerine..Aynı toprağın insanı, aynı gökyüzünün, aynı havanın, suyun..

Ayrı düşler kuruyor büyük bir kavganın öncesinde..Alın teri soysuzun

bardağında meze, namus dediğin yoksul kelamı..Direncin belini kırmış

Erdemin boynunu bükmüş, Onurun katline ferman demiş düzen..Şimdi

bekliyoruz an’ı..Artık susmak zamanı..”

Hepimizin sancıyan bir yanı var…Olmasaydı keşke dediğimiz..Eylül hiç

gelmeseydi mesela, dar ağaçlarına asılmasaydı taze gül yaprakları..

Dağlarda kurşun sıkılmasaydı hani, umut dediğimiz mavi çocuk, keşke

hiç kanamasaydı..Kimin gölgesiydi toprağa düşen, kimin gövdesiydi ayaz

gecelerde öfkenin koynuna sarılıp üşüyen? ..

Hangi Mehmet, Hangi Mehmet’in namlusunda can verir..Kurşun dediğin

bir kahpe ölüm anı..Yalnız düşmana çevrilir…

Sevmeli yine de..Hani zordur ya bu dediğim..Aşık olmayı denemeli insan..

Özlemeyi hatırlamalı, kavuşmayı istemeli..Bir şiir yazamıyorsa, eli kaleme

gidip,üç satır mektup gönderemiyorsa, ya da yazacak bir şiir, mektup gönderecek bir insan bulamıyorsa..Arada bir sigara yakıp, efkarlanıp, gözleri sessizce dolup ağlayamıyorsa..Kısacası gülüm..Yüreğinde sevmeye

dair bir şey yoksa..

Kaybedecek bir kavgası bile olmayan zavallıdır artık..Konuşmasa da olur..

Hiç pişman olmadım seni sevmekten..Uzaklığın ne kadar acıtsa da canımı..

Sana gelen bir yolum vardı hep..Geri dönüşlerim olduğu kadar, sana gelişlerimdi sevmek belki..Zamansız sona erişlerin, sana dokunmalarımı

erteleyişlerin özleminde yaşamaktı seni..Her bitişe inat, yeniden başlamaktı bir yerlerden..Umut ki o mavi çocuk..Eksilmedi yüreğimizden..

Öylesi düştü yüreğimden sözler..

Biliyorsun, hiç bir zaman hepsini anlatamadım sana..Sustuğunu bilmeyi senden öğrendim..Sustum şimdi..

Sar düşlerinde tenimi kadın..Ben geldim………..', 'Ah sevdalım..Göç bakışlar sarmış yine hüznünden arta kalan zamanı.. Yüreğin kadar çok yalnızlığa kafa tutan direncin, hasretin kadar yenik.....', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/adresi-belli-mektuplar-xii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslanlar', 'aslanlar-kamil-at-r7wk2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uyuduğu yer güzel çayırdı

Kurşun geldi döşünü sıyırdı

Yavrusu kaldı çakallar ayırdı

Soyu tükenmez dostum.

Aslanlar bilmez pis kanunu

Kendi bilir kendi sonunu

İhanet etse keser her yanını

Soyu tükenmez dostum.

Dünyada aslan yalnız birdir

Bunu bilmez çakal kördür

Dünyada sağlam onur ile esirdir

Soyu tükenmez dostum.

Kendini yakaladı bizim aslan

Çıldırır bundan çakal sırtlan

Birgün küsersen dağa yaslan

Soyu tükenmez dostum.

Kamil At yiğitleri sevendi

Kavgasına sağlam diye güvendi

Korkak çakal kendini yendi

Korkudan sakınmaz dostum.', 'Uyuduğu yer güzel çayırdı Kurşun geldi döşünü sıyırdı Yavrusu kaldı çakallar ayırdı Soyu tükenmez dostum. Aslanlar bilmez pis kanunu Kendi b...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aslanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-i-brahim-ugur-toprak-1nn33', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Demek gidiyorsun

Bir gülümsemenle açtığın

Bütün kapıları

Tek tek yüzüme çarparak 

Gidiyorsun

Demek gidiyorsun

Beni yarsız

Beni kavgasız

Beni dalda yapraksız koyup gidiyorsun

Gitme! Gidersen

Sesim sessiz

Sözlerim kifayetsiz kalır

Gel de sözümü sessiz bırakma

Gidersen

Gözlerim ışıksız

Düşlerim yarınsız kalır

Gözlerimi sensiz bırakma

Gitme

Yağmur buluta

Bulut bana küser

Yağmur alıp başını gider

Beni de yanına katmak ister

Yağmura kanıp

Sebepsiz bir rüzgara kapılıp gitme

Gidersen

Aç kalır martılar

Ne yağmur yağar şehre

Ne de güneş açar

Gökkuşağı renksiz

Ceylanlar kimsesiz kalır

Sen gidersen

Sen gidersen

Ne bir yolcu kalır

Karşıyaka - Alsancak vapurunda

Ne de bir mektup

Postacının eskimiş çantasında

Gitme! Gidersen

Bu şiir, bu şarkı bu adam 

Yarım kalır

Sen yarım kalırsın

Hem zaten

Fazla da yaşamazmış

Gül dalından ayrı düşerse

Gitme! 

Sol yanımı alıp götürme

Söylesene! 

Neyi değiştirecek ki

Her şeyi ardında bırakıp gitmen? 

Nasıl olsa

Giden de sen olacaksın

Kalan da sen

Evet sevdiceğim

Eğer

Bunca söze ragmen 

Kararlıysan hala gitmekte

Bari, hiç olmazsa

Beni de götür yanında

Beni de götür de

Üstadın bahsettiği

O hayatı beraber bölüşelim

Çünkü,

''Çok Uzakta Öyle Bir Yer Var

O Yerlerde Mutluluk Var

Paylaşılmaya Hazır Bir Hayat Var! ..''

18 Kasım 05

İZMİR', 'Demek gidiyorsun Bir gülümsemenle açtığın Bütün kapıları Tek tek yüzüme çarparak  Gidiyorsun Demek gidiyorsun Beni yarsız Beni kavgasız Beni...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/gitme-138-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimde kanlı yaşlarla ağlıyorum', 'gozlerimde-kanli-yaslarla-agliyorum-sinan-aydindag-t0ny7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '14 KASIM 2005

Bak şimdi hep yaşlar akıyor gözlerimden

Nasıl atacağımı bilmiyorum ki seni yüreğimden

Nasıl bir kötülük ettim ki sana

Bari bunu çok görme  bana

Hadi ellerini aldın gittin

Hadi gözlerini aldın gittin

Hadi bundan sonra nefessiz yaşa 

Yaşa yaşayabilirsen dedin

Oysa ki...

Bilmiyordun sen,senin için ne Romalar yaktıgımı

Bilmiyordun sen,sana nasılda taptığımı

Belki de bilmek istemiyordun

Ve sen, çektin gittin

Ve ben, hala gözlerimde kanlı yaşlarla ağlıyorum

Yinede yolun gülle dolsun

Mutluluk her daim seninle olsun...', '14 KASIM 2005 Bak şimdi hep yaşlar akıyor gözlerimden Nasıl atacağımı bilmiyorum ki seni yüreğimden Nasıl bir kötülük ettim ki sana Bari bun...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gozlerimde-kanli-yaslarla-agliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün dünden daha çok seviyorum seni', 'bugun-dunden-daha-cok-seviyorum-seni-sinan-aydindag-btcx9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '16 Kasım 2005

Bugün düne göre daha soğuk

Yarın bugüne göre daha soğuk olacak

Bugün sevgim dağlar kadar

Yarınsa sevgim okyanuslara sığmayacak

Bugün dünden daha çok seviyorum seni

Yarın bugünden daha çok seveceğim

Dün esintilerle bugün rüzgarlarla geldin

Bilki yarın sana kasırgalarla döneceğim

Hep, hep ama hep seni seveceğim.', '16 Kasım 2005 Bugün düne göre daha soğuk Yarın bugüne göre daha soğuk olacak Bugün sevgim dağlar kadar Yarınsa sevgim okyanuslara sığmayacak...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bugun-dunden-daha-cok-seviyorum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim dünyam gel gitlerle dolu', 'benim-dunyam-gel-gitlerle-dolu-sinan-aydindag-fy5jn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '17 Kasım 2005

Benim dünyam gel gitlerle dolu

Bir geliyorsun bir gidiyorsun

Yoksa sadece hayallerimde mi? yaşıyorsun

Bakma duruşumun sert olduguna

Bakışlarıma aldırma

Bir bilsen içimde nasıl bir sırça köşk yaşatıyorum

Bu ketumluğum onun kırılmasından korktuğum için

İçinde sen varsın

İçinde ben varım

Ve içinde kocaman duygusal bir dünya

Sende bırak istersen yalnızlığımla

Ben o dünyada yalnız yaşamayada alıştım

Bilmem kaç asırdır yalnızım

Sende git, sende kaç sende,sende,sende

Bırak beni sırdaşımla yalnızlığımla.', '17 Kasım 2005 Benim dünyam gel gitlerle dolu Bir geliyorsun bir gidiyorsun Yoksa sadece hayallerimde mi? yaşıyorsun Bakma duruşumun sert old...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benim-dunyam-gel-gitlerle-dolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgimi Sevgisizlikmi...', 'sevgimi-sevgisizlikmi-atil-kesmen-hcruq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalp atışlarıma gizlenmiş

Çaresiz acılarımı soluyordum

Bir yerlerim kopuyor, kendim de kayboluyordum

Zaman tüneline esirmi düşmüştüm

Gerçekler yanıp söndükçe 

Ben benden gidiyordum

Karanlıklar 

Evet karanlılar benim olsun

Aydınlıklar ise senin olsun

İnan gönül koymam 

Tek sen mutlu ol

Bu bana yeter

Gidişin

Muhteşem olacaksa 

Git ne olur git

Bu gönül sofrasında sana yer yok

Görülmez bilinmez 

Göz yaşı sancıları arasın da 

Ve kök salmış sevgimin umutsuzluğunu yaşatma bana

Düşüncelerim de artık

Bir hüzün kokusu

İrkilen bedenim

Terleyen tenimi

Parçalara ayırıyor

Ve bir bedel ödüyor 

Seni gerçekten seven gönlüm

Bilemiyorum

Belki……..

Sevgimi

Sevginin değerini bilene vermeliydim

Sevgi dallarına tutunup

Isıtan güneşinde aydınlanmak

Güç almak

Ve mutlu yaşamı bulmak olmalıydı 

Gerçek sevgi

Oysa şimdi……

Sayfalarım karanlık noktalara kilitlenmiş

Suskun kalemimi teselli ediyor

Bir bardak su da boğulmanın

Yaprak sarılığına bürünmenin

Severken 

Sevilmemenin Köleliğine saplanmanın

Acılarını

Darbe almış gönlüm de yaşıyorum

Ama….Artık

Şunu çok iyi biliyorum

Gözlerim de bir boşluk uçurumu

Kanatsız kalmış sevgimi uçururken

Güneş keskin doğsa da sabahlara

Isıtmaz bedeni

Ve gecelerden kalma bir yıldız saplanır tene

Lime lime keser düşünceleri

İz bırakır yıllanmış yaşam kesitlerine

SEVGİMİ, SEVGİSİZLİKMİ

Karışmıştır biribirine

Ve bir yol oluşur akşam serinliğine

Bir daha 

Bir daha, güneşe kavuşmak üzere……', 'Kalp atışlarıma gizlenmiş Çaresiz acılarımı soluyordum Bir yerlerim kopuyor, kendim de kayboluyordum Zaman tüneline esirmi düşmüştüm Gerçekl...', ARRAY['Türk Edebiyatı','Şiir','Atıl Kesmen']::text[], 8.5, '{"poet":"Atıl Kesmen","poet_slug":"atil-kesmen","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/sevgimi-sevgisizlikmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğum', 'cocuklugum-murat-odemis-u2xei', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çocukluğum

Tiren istasyonlarında

Köprü altlarında geçti çocukluğum

Sizlerin neşe ile oynadığı o parklar varya,

İşte geceleri ben hep orada uyurdum.,

Köpek havlamaları

Bazen bir bekci düdüğü bölerdi uykumu

Sizlerin sıcacık yataklarınız varya

Onları ben sadece düşünürdüm

Açlık gördüm çocukluğumda

Sefalet ve acı gördüm

Sizlerin yemeyipte attığı o ekmekler varya

İşte ben onlarla büyüdüm', 'Çocukluğum Tiren istasyonlarında Köprü altlarında geçti çocukluğum Sizlerin neşe ile oynadığı o parklar varya, İşte geceleri ben hep orada u...', ARRAY['Türk Edebiyatı','Şiir','Murat Ödemiş']::text[], 8.5, '{"poet":"Murat Ödemiş","poet_slug":"murat-odemis","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cocuklugum-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döneceksin', 'doneceksin-kadir-albayrak-x1511', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '.......Ve bir gün döneceksin

Gittiğin gün ki gibi genç ve mutlu değil

Belki üzgün, belkü yaşlı, belki yıkık dökük

Ama döneceksin! ....

Adına inandığın gibi inan buna

Ne alın yazını okudum senin

Ne bir rüra gördüm ortasın da gecenin

                     -Gaibi bilmem falcı değilim

                     -Sorma! ..Cevabı yok ki vereyim

Lakin; Döneceksin! ...Bilirim! ..

.......................

Gittiğin gün ki gibi heyecanlı değil 

Hatta biraz yorgun, çizgiler belirgin

Sahip olduğu her şeyi kaybeden 

Bir insanın kahrını taşıyarak! .. Ezgin ve bitkin

Ama döneceksin! ....

Gidişin kadar gerçek! .. İnan buna

Ne yıllar sonrasını yaşadım zaman tünellerinde

Ne arşa yükselip konuştum meleklerle

                       -Ati-yi bilmem, ermiş te değilim

                       -Sorma! ..Cevabı yok ki vereyim

Lakin ''DÖNECEKSİN'' bilirim! ....', '.......Ve bir gün döneceksin Gittiğin gün ki gibi genç ve mutlu değil Belki üzgün, belkü yaşlı, belki yıkık dökük Ama döneceksin! .... Adına...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/doneceksin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğumdaki acılar', 'cocuklugumdaki-acilar-murat-odemis-b8zhg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çocukluğum

Tiren istasyonlarında

Köprü altlarında geçti çocukluğum

Sizlerin neşe ile oynadığı o parklar varya,

İşte geceleri ben hep orada uyurdum.,

Köpek havlamaları

Bazen bir bekci düdüğü bölerdi uykumu

Sizlerin sıcacık yataklarınız varya

Onları ben sadece düşünürdüm

Açlık gördüm çocukluğumda

Sefalet ve acı gördüm

Sizlerin yemeyipte attığı o ekmekler varya

İşte ben onlarla büyüdüm', 'Çocukluğum Tiren istasyonlarında Köprü altlarında geçti çocukluğum Sizlerin neşe ile oynadığı o parklar varya, İşte geceleri ben hep orada u...', ARRAY['Türk Edebiyatı','Şiir','Murat Ödemiş']::text[], 8.5, '{"poet":"Murat Ödemiş","poet_slug":"murat-odemis","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cocuklugumdaki-acilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Z-el-Z-ele', 'z-el-z-ele-gul-ozan-2yuzx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sallanıyor yer ve sallıyor bizi

uyandıracak mı acaba hepimizi? 

Gece oturması ve gündüz uykusu

bunlar çare mi; deprem korkusu! 

Yürekler sallanmıyor, gönüller uyanmıyor, 

aynı sarhoşluk ve aymazlık devam.

Bu kadar didaktik olmak istemezdim 

ama beynimi sıkıştırıp dökülüyor kelam. 

-Aç bakalım Semra Hanım eski kocasına dönecek miymiş? 

-Sözde güzellik kraliçesi ama bak meğer ne rüküş şeymiş! 

Bahçede zeytin ağacının dibinde otursan ve düşünsen bir,

o zaman diyeceksin, yaşamak gerek, televizyon neymiş! 

Sallanıyor yeryüzü, uyan ey insan! 

dünya cennet olacak eğer yaşarsan 

Korkuyla büzülürsen durduğun yerde

ve saklanırsan popüler olan şeylerde

görememek var cennet yeryüzünü

ama bil ki O unutmaz sözünü!', 'Sallanıyor yer ve sallıyor bizi uyandıracak mı acaba hepimizi?  Gece oturması ve gündüz uykusu bunlar çare mi; deprem korkusu!  Yürekler sal...', ARRAY['Türk Edebiyatı','Şiir','Gül Ozan']::text[], 8.5, '{"poet":"Gül Ozan","poet_slug":"gul-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/z-el-z-ele-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakışacak', 'yakisacak-gul-ozan-tae8c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gel inat etme bak, 

Bu sevda sana çok yakışacak! 

Gel bu sevdayı tut, 

Kaçıp gitmesin… 

Bu sevda sana dost olsun, 

Hiç terketmesin… 

Çağır sevdayı yanına, 

Çok özlemesin… 

Sevdayı besle büyüt

Hiç ölmesin… 

Bu sevda ile sen…

Ebediyen… 

Ne dersin?', 'Gel inat etme bak,  Bu sevda sana çok yakışacak!  Gel bu sevdayı tut,  Kaçıp gitmesin…  Bu sevda sana dost olsun,  Hiç terketmesin…  Çağır s...', ARRAY['Türk Edebiyatı','Şiir','Gül Ozan']::text[], 8.5, '{"poet":"Gül Ozan","poet_slug":"gul-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yakisacak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Caddeyi Geçsene', 'caddeyi-gecsene-gul-ozan-iux3g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hayır

o gün caddeyi geçseydin de...

taksiye binmeseydim de...

yağmur yağmasaydı da...

... kalamazdım

evet

caddeyi geçeceğim,

otobüse bineceğim,

yağmurda ıslanacağım,

...kalacağım

belki

beraber yürürüz,

kolkola gideriz,

güneş açar belki diye...', 'hayır o gün caddeyi geçseydin de... taksiye binmeseydim de... yağmur yağmasaydı da... ... kalamazdım evet caddeyi geçeceğim, otobüse bineceğ...', ARRAY['Türk Edebiyatı','Şiir','Gül Ozan']::text[], 8.5, '{"poet":"Gül Ozan","poet_slug":"gul-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/caddeyi-gecsene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat beşe geliyor', 'saat-bese-geliyor-gul-ozan-6lny3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saat beşe geliyor...

Gün, Ağustos 6 ya...

Sene 89 a...

Uyku gözüme... bu ne uzun geliştir..! 

Uyusam da uyansam...

Uyansam da unutsam...

Unutsam da utansam...

Bütün kuşkularımdan...

(Bir daha deneyelim :) 

Saat beşe geliyor.

Sevda boşa gidiyor.

Elimden ne geliyor? 

Ne gelen var, ne giden!', 'Saat beşe geliyor... Gün, Ağustos 6 ya... Sene 89 a... Uyku gözüme... bu ne uzun geliştir..!  Uyusam da uyansam... Uyansam da unutsam... Unu...', ARRAY['Türk Edebiyatı','Şiir','Gül Ozan']::text[], 8.5, '{"poet":"Gül Ozan","poet_slug":"gul-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/saat-bese-geliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SiS', 'sis-gul-ozan-2miow', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin üçü...

Marmaris...

Şiir yazmaya uyandım...

Çok zaman ve yer birikmiş,

ama yazarken zorlandım, 

duruyor yine aynı sis...', 'Gecenin üçü... Marmaris... Şiir yazmaya uyandım... Çok zaman ve yer birikmiş, ama yazarken zorlandım,  duruyor yine aynı sis......', ARRAY['Türk Edebiyatı','Şiir','Gül Ozan']::text[], 8.5, '{"poet":"Gül Ozan","poet_slug":"gul-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sis-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırı Vardır', 'hatiri-vardir-kadir-albayrak-vzhpx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ay oldu yıl oldu gittin gideli

Yüreğin belki yaz belki bahardır

Unutmuş olsan da ''sevgimi'' hani

Bir fincan kahvenin hatırı vardır

Selamın gelseydi sen gelmesen de

O selam gönlüme ab-ı hayattır

Köprüden çok sular aktı desen de

Bir fincan kahvenin hatırı vardır

Balli ki gittiğin o yaban elde

Pembe bulutlarda mutluluk vardır

Ne olursa olsun ''hani bir yerde''

Bir fincan kahvenin hatırı vardır

Ben seni nakşettim hep şiir şiir

Derdimi anlatan bir satır vardır

Sen bilmesen bile yaradan bilir

Bir fincan kahvenin hatırı vardır

Gönül bu isyankar söz geçiremem

Bir kutlu emanet bir sevgi vardır

Ben seni Mevlaya şikayet etmem

Bir fincan kahvenin hatırı vardır', 'Ay oldu yıl oldu gittin gideli Yüreğin belki yaz belki bahardır Unutmuş olsan da ''sevgimi'' hani Bir fincan kahvenin hatırı vardır Selamın ge...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hatiri-vardir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadir Baba', 'kadir-baba-kadir-albayrak-9wa0x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her sabah umutla yola bakarsın

Gelenin gidenin yok Kadir baba

Her gece gözlerin ıslak yatarsın

Dertlerin ummandan çok Kadir baba

Bu gece sabaha kadar sendayim

Sen anlat ben seni dinleyeceğim

Kovsan da buradan gitmeyeceğim

                Bende çok dertliyim çok Kadir baba

                Benimle göz yaşı dök Kadir baba

Şuraya iskemle koy benim için

Doldur kadehimi ver Kadir baba

Sanma ki dünya da tek dertli sensin

Derdine ortağım ben Kadir baba', 'Her sabah umutla yola bakarsın Gelenin gidenin yok Kadir baba Her gece gözlerin ıslak yatarsın Dertlerin ummandan çok Kadir baba Bu gece sab...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kadir-baba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tereddüt üzerine bir fon müziği', 'tereddut-uzerine-bir-fon-muzigi-gul-ozan-gvlai', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tereddüt

Şu şiirdeki zerafeti sizinle paylaşmak istedim. 

Şiirin duygusu ve müziği çok hoşuma giderdi, 

Orhan Seyfinin olduğunu bilmezdim, şarkısı da var hatta...

bir şiir - bir tablo - bir müzik var - tanımlamaya çalışacağım:

Fonda 1950lerin sonları... 

Tramvaydan inmişler, yanyana yürüyorlar. 

Fötr şapkalı pardesülü bey şemsiye taşıyor. 

Yağmur çisildiyor.

Ama sonbaharın İstanbuldaki ender aydınlık yağmurlarından... 

Genç hanım da şarabi renkte bir manto ve şapka giymiş. 

Aslında uzun yıllardır tanışıyorlar. 

Belki aynı mahallede oturuyorlar veya aynı semtte işleri var. 

Tramvayda her gün rastlıyor ve ara sıra sohbet ediyorlar. 

Günlük olaylardan, sanattan, sinemadan vb... 

İşte bu gün beyefendi ilk defa cesaretini topluyor 

ve duygularını açmaya çalışıyor, ama...

- - - - - - - - - - - -Tereddüt 

Sarahaten, aceba söylesem darılmaz mı? 

Darılmak adeti, bilmem ki, çapkının naz mı? 

Desem ki: ’’Ben seni...’’ Yok dinlemez ki... hiddet eder. 

Niçin? Bu sözde ne var? Sanki hiddet etse ne der? 

Desem ki: ’’Ben, seni pek...’’ Ya küser konuşmazsa? 

Derim: ’’Bu çektiğim insaf edin, eğer azsa? ... 

Desem ki: ’’Ben, seni pek çok...’’ Hayır, kızar, bilirim; 

Tereddüdüm, acebâ, hiddetinden az mı elim? 

Desem ki: ‘’Ben seni pek çok...’’ Sakın gücenme emi? 

‘’Sakın gücenme, eğer anladınsa sevdiğimi’’ 

- - - - - - - - - - - Orhan Seyfi Orhon', 'Tereddüt Şu şiirdeki zerafeti sizinle paylaşmak istedim.  Şiirin duygusu ve müziği çok hoşuma giderdi,  Orhan Seyfinin olduğunu bilmezdim, ş...', ARRAY['Türk Edebiyatı','Şiir','Gül Ozan']::text[], 8.5, '{"poet":"Gül Ozan","poet_slug":"gul-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/tereddut-uzerine-bir-fon-muzigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılgı', 'yanilgi-gul-ozan-dg7dn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sen

aşkı

bir durum

sanıyorsun

oysa

aşk

her durumda

ve 

her yerdedir

sen 

aşkı

biri

ve bir an

sayıyorsun

oysa

aşk

asıl

her zaman

ve

hep 

sendedir.', 'sen aşkı bir durum sanıyorsun oysa aşk her durumda ve  her yerdedir sen  aşkı biri ve bir an sayıyorsun oysa aşk asıl her zaman ve hep  send...', ARRAY['Türk Edebiyatı','Şiir','Gül Ozan']::text[], 8.5, '{"poet":"Gül Ozan","poet_slug":"gul-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yanilgi-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yatacak Yerin Yok Senin', 'yatacak-yerin-yok-senin-kadir-albayrak-e1i4r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmedin giderken ayrılık günah

Bağrıma açtığın yara çok derin

Öyle bir çıktı ki yüreğimden ah

Sevgilim yatacak yerin yok senin

Sana çok kırıldım dön diyemem ki

Mutluluk ne demek ben bilemem ki

Yemin ettim seni affedemem ki

Sevgilim yatacak yerin yok senin

Nelerden vazgeçtim bilsen nelerden

Ne senden ümit var ne gecelerden

Mazide bu kadar göz yaşı varken

Sevgilim yatacak yerin yok senin', 'Bilmedin giderken ayrılık günah Bağrıma açtığın yara çok derin Öyle bir çıktı ki yüreğimden ah Sevgilim yatacak yerin yok senin Sana çok kır...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yatacak-yerin-yok-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençlikten İlham', 'genclikten-i-lham-ramazan-ates-4vnwz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güzel, güzel gülüyorsun,

Bana ilham oluyorsun.

Hem güzelsin, hem akıllı,

Niye uzak duruyorsun? 

Geleceğin umut dolu,

Sen bulursun doğru yolu,

Güzel terbıye almışsın,

İncitmezsin onurunu.

Senden ilham alıyorum,

Senle huzur buluyorum.

Sen gibiler tanıdıkca,

Çokda mutlu oluyorum.

Tatlım yolun açık olsun,

Başarılar seni bulsun.

Kötülük bulmasın seni,

Allah seni hep korusun.

Ramazan Ateş/Enschede-18.10.2003', 'Güzel, güzel gülüyorsun, Bana ilham oluyorsun. Hem güzelsin, hem akıllı, Niye uzak duruyorsun?  Geleceğin umut dolu, Sen bulursun doğru yolu...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/genclikten-ilham-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adresi Belli Şiirler - XII', 'adresi-belli-siirler-xii-ugur-deniz-ulkegul-w2t25', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne zaman düşlerinden öpsem

Mavi tadında bir nem kalır dudağımda..

Issız gölgesi düşer üstüne yorgunluğumun

Saçlarının kokusu sancır korkularımda…

Kusursuz yokluğunda kısır zamanlar

Ayrışık suskularda yoksul direncim

Ne zaman düşlerine usulca gelsem

Yarım kalır sevincim, sorgularımda..

Gitmek kadar yengi zamansız süreç

Sonu belli olmayan bir mavi umman

Sığ öfkeler çoğalır dalgalarımdan

Ölü aşklar birikir kumsallarımda…

Yazdığım şiirler sahipsiz üryan

Zincire vurulmuş kahır, zindanlarımda

Hani şu Eylül zamanı çocukluğumun

Dar ağacına asılmış uykularımda…..

Kaldırım taşlarında ayak seslerim

Çıkmaz sokaklarında sızdığım efkar

Teninden kayıp düşen sevişmelerim

Sana öykünmelerim, kuytularımda…

Ne zaman düşlerinden öpsem

Mavi tadında bir sen kalır dudağımda..

Arsız suçlar saklarım ellerimde o an

Sensizliğe inat..Çoğalırım yokluğunda…', 'Ne zaman düşlerinden öpsem Mavi tadında bir nem kalır dudağımda.. Issız gölgesi düşer üstüne yorgunluğumun Saçlarının kokusu sancır korkular...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/adresi-belli-siirler-xii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum', 'bekliyorum-hafid-tarhan-p1nmo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmurlar yağıyordu bu şehre dün gece

Yağmurun sesinde duyuyordum sesini

Açtım penceremi 

Uzattım ellerimi

Yakalamak istedim seni

Hissetmek için seni ellerimde

Yakaladığım her yağmur tanesinden

Seni sordum, gördünüz mü diye

Tanıyanlar da oldu tanımayanlar da

Arıyordu seni gözlerim 

Her yağmur damlasında seni

Sonra tanıdık bir yağmur damlası

Söyledi bana yerini

O başka bir şehre yağıyor, dedi

Başkasının ellerine düşecek 

Demek duyduğum ses sen değilmişsin

Her yağmur yağışında bu şehre 

Bekliyorum seni 

Açıyorum yine ellerimi,

Ne olur bu şehre de yağ 

Bir kez olsun....

Bekliyorum tamam mı 

Göz yaşlarımla seni...', 'Yağmurlar yağıyordu bu şehre dün gece Yağmurun sesinde duyuyordum sesini Açtım penceremi  Uzattım ellerimi Yakalamak istedim seni Hissetmek ...', ARRAY['Türk Edebiyatı','Şiir','Hafid Tarhan']::text[], 8.5, '{"poet":"Hafid Tarhan","poet_slug":"hafid-tarhan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bekliyorum-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Tesellim Seccadem', 'tek-tesellim-seccadem-kadir-albayrak-nyh2a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir şey zorluyor beni ya akli muvazenem

Ya da şu deli yürek tek tesellim seccadem

Arasında kalmışım bu tuhaf cenderenin

Dün kayıp bu gün garip yarın kim bilir kimin

Gölgelerin aslı yok beyni zorlayan düşler

O düşler ki suların aynasına düşmüşler

Gönlüm sur yıkan gülle beynim duvar,kerpiçten

Dövüyor var gücüyle müdehale hariçten

Alnım öper secdeyi Hak-ka akar arzuhal

Gayrısında huzur yok hepsi boş hep ham hayal

Sevda bu! Acı grift, ne yol var ne bir çare

Akıl! ..Lakin etmiyor yürekle istişare

Gel! diyemem gelemez o çözülmez kördüğüm

O hayalimde yumak örüp örüp çözdüğüm

Mantık; Ölçü kalıbı, oval dikdörtgen kare

Şekiller emri vaki tepe çizgi ve tane

Hissiyatım toz duman her şey ölçüsüz sakil

Gidip gelir durmadan mem de aletsiz nakil

Zahir de akıl benim! .. Yürek benim yüreğim

Peki! ..Bu kavga niye? Lakin bana soran kim? ! 

Aklı oynatır mıyım? Belli olmaz korkarım

Kimin için? Değer mi? Bilmem! . Bilsem sorarım

Neden soracağım ki Benim gibi kim bilir

Bu öyle bir sevda ki ''Ölü görse dirilir''

Akıl! ..Kabuğunda kal! Dur saldırma her yere

Zirvedesin bu yeter! .. Zavallı küçük fare

Ömrümü kemir benim ötesine güç yetmez

Nafile! ..Bu yüreği hiç bir güç bitiremez

Ömür; Gönül ve aklın arasında med-cezir

Gönül padişah olmuş akıl kapıda vezir

Padişaha taht benim vezire kapı kulu

Gece gündüz eğitim sanki ''meczup'' okulu

Ey başım deli başım! .. Sen kalkma o secdeden

Hak-ka tevekkül et ki kan gelsin yüreğinden

Bir şey zorluyor beni ya akli muvazenem

Ya da bu deli yürak! .. Tek tesellim seccadem', 'Bir şey zorluyor beni ya akli muvazenem Ya da şu deli yürek tek tesellim seccadem Arasında kalmışım bu tuhaf cenderenin Dün kayıp bu gün gar...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/tek-tesellim-seccadem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derlerki İnsan Bir Kez Ölür', 'derlerki-i-nsan-bir-kez-olur-nuri-can-q5rib', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Derler ki insan bir kez ölür 

ben bin kez öldüm yaşarken

elimde kalbimin kırıkları

ekmeğim yok diyen herkese 

ekmeğimi verdim

sevgisiz kaldım diyen herkese 

sevgimi

kimsesiz, ekmeksiz, sevgisiz kaldım...

insan oğlu nankör

insan oğlu hain

vefa yalandır balam 

dostluk yalan

yaşamak yalan

boşa gitti emeğim, alınterim, ekmeğim.

derler ki insan bir kez ölür 

ben bin kez öldüm yaşarken

bir  umut gönder ay balam

bir düş

bir ses

bir ışık 

bir nefes

darda kaldım...', 'Derler ki insan bir kez ölür  ben bin kez öldüm yaşarken elimde kalbimin kırıkları ekmeğim yok diyen herkese  ekmeğimi verdim sevgisiz kaldı...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/derlerki-insan-bir-kez-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Ayın Yirmi Dokuzu', 'her-ayin-yirmi-dokuzu-hafid-tarhan-qt4xi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hesapsız geldi bu bahar seninle

Pembeler öyle bir açtı ki

Renklerin ahengine 

Takılıp gitti gönlüm

Öyle bir andı ki bana gelişin

Ne dur diyebildim,ne de vazgeçebildim

Zamanlara sığmayan zamansız sevdamızdan

Beni de ekle artık şu yalan dünyaya

Dünün de var olmuştum ya

Bu günün de yok et beni

Sadece her ayın yirmi dokuzunda

Hatırla beni.....', 'Hesapsız geldi bu bahar seninle Pembeler öyle bir açtı ki Renklerin ahengine  Takılıp gitti gönlüm Öyle bir andı ki bana gelişin Ne dur diye...', ARRAY['Türk Edebiyatı','Şiir','Hafid Tarhan']::text[], 8.5, '{"poet":"Hafid Tarhan","poet_slug":"hafid-tarhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/her-ayin-yirmi-dokuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Göz İle Bakan Bakana', 'bos-goz-i-le-bakan-bakana-kamil-at-80ddd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu ne biçim müzik nasıl bir sözdür

Beni alır götürür girdaplı bir bara

Geriye kalan içi boşalmış özdür

Boş göz ile bakan bakana.

Fakir zengin ikisi açıktan düşman

Yoksul paraya ermemiş değil pişman

Egoist, kucak bilmez akılsız hayvan

Kariyer dalına çıkan çıkana.

Dünya birkaç kişinin diğerleri zanlı

Biri çöpten geçinir biri yobaz şanlı

Cihanda ceza verir insana kanlı

Birgün candan bıkan bıkana.

Çoğaldı gitti dünyada itler sürüsü

Bunu teper gider dönemin birisi

Dünya zor düzelir beladır gerisi

İnsan olanı yakan yakana.

Öyle dünya içinde işim güçtür

İnsanlığı kıran, uyuz kargaya taçtır 

Kamil At''a bomba atan hain hiçtir

Çatlamış dişi sıkan sıkana.', 'Bu ne biçim müzik nasıl bir sözdür Beni alır götürür girdaplı bir bara Geriye kalan içi boşalmış özdür Boş göz ile bakan bakana. Fakir zengi...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bos-goz-ile-bakan-bakana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elini Vermiyor Hayat!', 'elini-vermiyor-hayat-nuri-can-d3vdp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yerde kıvranan kalbimin üstünde dansediyor acılar

koparıp göğsümden yerlere fırlattığım kalbimin

kimse dönüp bakmıyor

görmüyor ateşler içinde kıvrandığını kalbimin

eğilip almıyor ateşler içinde

yanıyor kalbim! 

kalbim ahhh! ! ! 

Yaprakları acılı rüzgarlada ürperen 

yorgun bir dağ lalesiyim bir yol başında 

yaralı ceylanların gözlerinde inliyor bedenim

ruhum bir cellâtınki kadar soğuk ve tedirgin

kirli bir hayatın karanlık odalarında

mil çekiliyor gözlerime

kör oluyorum! 

dost bildiklerim hançerini saplıyor göğsüme

yaralanıyor canevim

kan damlıyor her yerimden

yüreğimden

ellerimden

gözlerimden

dudaklarımdan...

ahhh! ! ! 

Zifir karası gecelerin acısı zaptediyor ruhumu

kalbimin en ince sızısından vuruyor hayat

ne güneş ısıtıyor üşüyen anılarımı artık

ne de insanlardan kaçıp sığındığım tenhalar

çıkmaz sokaklarda yitirdim yolumu, şaşkınım

şimdi yüreğim çırpınan yaralı bir kuş gibi çaresiz

kış kadar soğuk bedenim şimdi

param parça her yerim

bir ihanet sisinde yitirdim herşeyimi

yıldızlar göz kırpmıyor, ay küs 

sisli geçen her gecenin ardından yağmuru bekliyorum 

Ah! ! ! Diyorum,

keşke bende duygusuz yaşamayı becerebilseydim 

yalanlar sıralayabilseydim, yalanların ardından

aç çocukların gözlerine bakıp utanmasaydım

yanmasaydım bu kadar dünyanın acısına

gözlerime perde çekip, unutabilseydim her olup biteni

ihanetlere incitmeseydim yüreğimi bu kadar

Ey ömrüm ödedim borcunu acıların, azad eyle beni

anladımki söz geçmiyor yüreğe tufandan sonra 

bağışlamıyor hayat yüreğiyle oynayanı

el yordamıyla yürüyorum şimdi yürüdüğüm yerde

yalanlardan örülmüş bir duvarın kenarından tutunarak,

onurlulara mahsus acılı taşlara yürüyorum...

bir sümüklüböceğin kabuğunu sürüklediği çaresizlikle

sürüklüyorum bölük pörçük hayatımı ardımdan.

Ey kalbe saplanan hançer

ey ciğere işlenen kurşun

bu yürek artık ağlamamalı,

yanmamalı acılara bu kadar

ağır geliyor onurlu bir ömrün çekilen yükü 

bir yanım deniz, bir yanım uçurum, bir yanım ateş

yalnız bir yolcuyum meçhule giden dümensiz bir gemide

gözlerimde kaç bin yıllık ah! 

yüzme bilmediğini bile bile denize atıyorum kalbimi

alıp götürsün diye upuzun yanlızlıklara dalgalar 

Yorgun bir dağ lalesinin hazin hikayesi hayatım 

yaşama sevincimi yıllar önce

çiçekleri çiğnenen bir bahçede yitirdim

ağrılar içindeyim şimdi ah! mavi kuş

yorgunum, bitkinim, dargınım! 

elini vermiyor hayat! 

bir uçurum kenarında

ha düştüm düşeceğim

her gece bir yıldız kayıyor gözlerimden

yüreğimden bir dilek sönüyor her gece

bu yüzden hep yetimdir bir yanım

bir yanım aşka ve acıya ayarlı

enkaz oldum, toz oldum, duman oldum

(*) ''ben bu kahrı çeke çeke yoruldum''

kara bir dumanla boğuluyorum şimdi

şimdi kara gecelerin kör kelebeği gözlerim

karanlıklar içindeyim dipsiz bir kuyuda

dolunay

bulutların arkasından

bakar

bakar

darılır...

ben

dolunaya

bakar

bakar

utanırım...

.', 'Yerde kıvranan kalbimin üstünde dansediyor acılar koparıp göğsümden yerlere fırlattığım kalbimin kimse dönüp bakmıyor görmüyor ateşler içind...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/elini-vermiyor-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasbihal', 'hasbihal-kadir-albayrak-ssnnn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Menşe-i bilinmez bizden sanırız

Türkçemin canına okur velhasıl

Aslında biz bizi iyi tanırız

Sırları gizem yaptı velhasıl

Azeri yabancı kafkas yabancı

Yaban etti dostu karın gardaşı

Yirminci asırın sinsi düşmanı

Koskoca kültürü yaktı velhasıl

Hazineydi dilim gördü fukara

Rezillik yarattı dedi avrupa

Uydurup uydurup bir yığın zırva

Getirip dilime taktı velhasıl

Geçmişle bağları kopardı önce

Anlaşamaz oldu dedeyle cüce

Olanak saptamak sözler de tümce

Olunca salyası aktı velhasıl

Dil ki bozuldu mı kalmaz gelenek

Din de gider eldfen istemeyerek

Hesabını yapmış kafir bilerek

Küfrün yumruğunu çaktı velhasıl

Basın da tv. de bir yığın hile

Can çekişir ahlak sahip yok diye

Namussuz edepsiz hırsızı bile

Resmedip ekrana astı velhasıl

Yok oldu bir kültür şehr-i hümayun

Türbeler harabe camiler mahzun

Haçlısı dinsizi bir avuç melun

Fatihle aramı açtı velhasıl

İçimizde nice ''aydın'' geçinen

Kitap karalamış ''merkep yüküylen''

Kuduz itler gibi ağzı köpüren 

Mikrobu millete saçtı velhasıl

Sahip ol diline bu son kalene

Kitabın bayrağın yedi ceddine

Yetişen imanlı şu genç nesline

Dikkat et gözünü dikti velhasıl', 'Menşe-i bilinmez bizden sanırız Türkçemin canına okur velhasıl Aslında biz bizi iyi tanırız Sırları gizem yaptı velhasıl Azeri yabancı kafka...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/hasbihal-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Omuz', 'omuz-elazigli-mustafa-kaya-nhveh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hüznünü bekleyen ağaçlar

senin kadar yalnızlar

ve  çevreleyip seni

yıllarca seninle yaşadılar..

bir kalem ve,

yalnızlığını götüren

sayfalar

durup durup karaladığın..

ve yağmurla kendini salıp

hayalin

yürümek sessizlikler içinde.

bir bankta,

başına yastık bir omuz

senin en mutlu düşlerin..

güneş,

seni görmek için

gökkuşağını uzatır

ve gamzeli gülüşün

uçuşur

ışık ve aşk dolu

yağmur olsam gerek

seni sevmenin yolu…

Mustafa kaya

19.11.2005 / kandilli

www.mustafakaya.net', 'hüznünü bekleyen ağaçlar senin kadar yalnızlar ve  çevreleyip seni yıllarca seninle yaşadılar.. bir kalem ve, yalnızlığını götüren sayfalar ...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/omuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağrı', 'cagri-bilge-karamehmet-0i0el', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dolmayan boşluklara destek; 

Silikon sevdalarımız var. 

Değerini farketmediğimiz. 

Yitince de ağlamaktan utanmadığımız, 

Hayasız aşklarımız var açık arttırmada, 

Sahte gözyaşlarına talip olan zavallı duygularımız... 

Okudukça kahredecek cümlelerimiz var bir yerlerde. 

Anlaşılmasını bekleyemediğimiz, 

Nice renkli duvar fotoğrafları.. 

Yok mu arttıran! ! ? 

Satıyorum hayallerimi... 

Duygularım, 

Yok pahasına gidiyor.. 

Sevdalar, göbek deliğinde başlayıp, 

Ayak parmağında bitiyor! 

Yok mu anlayacak yüreği olan! ? 

Gözlerin etrafı sigara dumanı.. 

Bir kaç kelime yetiyor kara sevda mahlasına. 

İki kelimelik aşkları satıyorum! ! ! 

Tükeniyor bir anda anlayamıyorum.. 

Anlamıyorlar... 

Tükeniyorum...... 

Yazık oluyorum.......', 'Dolmayan boşluklara destek;  Silikon sevdalarımız var.  Değerini farketmediğimiz.  Yitince de ağlamaktan utanmadığımız,  Hayasız aşklarımız ...', ARRAY['Türk Edebiyatı','Şiir','Bilge Karamehmet']::text[], 8.5, '{"poet":"Bilge Karamehmet","poet_slug":"bilge-karamehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/cagri-92-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Timsah Gözyaşları', 'timsah-gozyaslari-i-brahim-emin-sahin-9g83w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen,

Timsah gözyaşları akıtırken

gözlerinden

Bütün inandırıcılığına rağmen

İkiyüzlülüğün 

Belli oluyordu

sözlerinden

Kandırma kendini

dostum

Kandırma kendini

asil soylum

Bir sevda türküsü söylemeye çalışıyorsun

O da 

ezberinden', 'Sen, Timsah gözyaşları akıtırken gözlerinden Bütün inandırıcılığına rağmen İkiyüzlülüğün  Belli oluyordu sözlerinden Kandırma kendini dostum...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Emin Şahin']::text[], 8.5, '{"poet":"İbrahim Emin Şahin","poet_slug":"i-brahim-emin-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/timsah-gozyaslari-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cam kırıkları', 'cam-kiriklari-elazigli-mustafa-kaya-oyiwd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir şarkı

.cam kırıkları..’’

ikimiz için çalıyor

o ıslak saçların

uçup geliyor

uykusuz

ve susuz günlerdir

kalbimin aşkına..

ateşlerden gül çıkaran

sevgilim,

dalgalarla boğuşan

kararsız bir martı gibiyim

resmini çiziyor

sesiz bir akşam ve,

şarkının içindeyiz

durmadan yağan yağmurlarla

bir yürek birlikteyiz….

Mustafa kaya

19.11.2005 / Sarayburnu

www.mustafakaya.net', 'bir şarkı .cam kırıkları..’’ ikimiz için çalıyor o ıslak saçların uçup geliyor uykusuz ve susuz günlerdir kalbimin aşkına.. ateşlerden gül ç...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cam-kiriklari-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-kadir-albayrak-dld38', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şiir yazdım beğenmedi

                         -Sanki umurumdaydı

Hem sen kimsin şiir kim

                          -Dış kapının mandalı', 'Şiir yazdım beğenmedi                          -Sanki umurumdaydı Hem sen kimsin şiir kim                           -Dış kapının mandalı...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/siir-138-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözleri kapalı', 'gozleri-kapali-kadir-albayrak-9dfvr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adam Istanbulu dinlemiş

Gözleri kapalı! ..

Görmekten korkmuş zahir! ...

Gördüğümü görseydi

Zor yazılırdı o şiir! ..', 'Adam Istanbulu dinlemiş Gözleri kapalı! .. Görmekten korkmuş zahir! ... Gördüğümü görseydi Zor yazılırdı o şiir! .....', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gozleri-kapali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Geçen Zamanda', 'sensiz-gecen-zamanda-i-sa-tekin-liqds', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensiz geçen zamanda

Sol yanımın acısını

Dindirmek kolay olmadı

Eğer gözlerinde

Yüreğin gibiyse

Tıpkı eskisi gibi

Sevdamızın sadakatine

Güvenen yüreğim

El değmemiş sevgimizi

Gülücüklerin ile

Bana verebilirmisin? 

Filizlerini kırmadan

O zaman güneş yeniden doğar

Karanlıklara inat

Umut fidelerim

Bağrımda fışkırır yeniden

Umudumla berabar

Aydınlanır yüreğim

işte o zaman 

Bu yürek senin için

Sevdam için

Umudumuz için çarpar', 'Sensiz geçen zamanda Sol yanımın acısını Dindirmek kolay olmadı Eğer gözlerinde Yüreğin gibiyse Tıpkı eskisi gibi Sevdamızın sadakatine Güve...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sensiz-gecen-zamanda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar Sancıları', 'sonbahar-sancilari-abdulvahap-ates-9r5w1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yılların yorgunluğu,

Damlıyor gözlerimden.

Onmayan vurgunluğu,

Kanıyor sözlerimden.

Bir kemik bir de deri,

Yokluğunun ederi,

Sonbaharın kaderi,

Yağıyor saçlarımdan.

Sonbahar: Yapraklarım,

Uçuşur dallarımdan.

Doyduğum topraklarım,

Sıyrılır kollarımdan.

Her yaz sonunda hazan,

Gün gelir susar azan,

Vakit gelmiş çağırır,

Ayrılıkları yazan.', 'Yılların yorgunluğu, Damlıyor gözlerimden. Onmayan vurgunluğu, Kanıyor sözlerimden. Bir kemik bir de deri, Yokluğunun ederi, Sonbaharın kade...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Ateş']::text[], 8.5, '{"poet":"Abdulvahap Ateş","poet_slug":"abdulvahap-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sonbahar-sancilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bankerim', 'bankerim-kadir-albayrak-5vevf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akşam vakti birine

Sevdiğimi söyledim

Ne kalmışsa heybemde

Birer birer kaybettim

Dilim paslı zannetme

Gönül çorak neyleyim

Kulları sevmemeye

Yeminliyim bebeğim

Farzet ki ben bankerim

Ve farzet iflas ettim

Alacağın var belki

Nah alırsın bebeğim', 'Akşam vakti birine Sevdiğimi söyledim Ne kalmışsa heybemde Birer birer kaybettim Dilim paslı zannetme Gönül çorak neyleyim Kulları sevmemeye...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bankerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delitmeyin Ya! ..', 'delitmeyin-ya-kadir-albayrak-qtb56', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benden tebessüm bekliyor yüzümden gülüşü çalanlar

''Hüznün'' benimle özdeş olduğunu ifade ederek! ..

Kör bir insana renkleri anlatır gibi,

Mutluluğu tarif etmekte gaflete düşmüş biri

Hayal sınırlarımın içine nüfuz etmeye çalışırken gerçek dünyanın bir gaib-i

Savrulmakta yüreğimin tufanıyla

tövbe tövbe! ....

Kangren olmuş hastaya apandist ameliyatı olur mu ya! ...

Sapla,  kara saplı hançeri tam hançereye

Al sana kesin sonuç! ...

Çevreciler de sevinir.

Ağırlamasını bilmiyorsan bari ''kovmasını'' bil! ...

Çünkü  bu ''yaşamak'' değil! ....', 'Benden tebessüm bekliyor yüzümden gülüşü çalanlar ''Hüznün'' benimle özdeş olduğunu ifade ederek! .. Kör bir insana renkleri anlatır gibi, Mut...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/delitmeyin-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Yalanı', 'ask-yalani-kadir-albayrak-3lps4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seninle aramda dağlar var dağlar

Anlatma tepenin öte yanını

Şu gönül bahçemde kuruyan bağlar

Yanık yanık yazdı aşk yalanını

Ben sevda taşıdım ağırdı ton-dan

Büküldüyse belim sebebi bundan

Heybesinde yükü sevda olandan

Gönlüm alıp yazdı aşk yalanını

Aşka söz mü? Haşa! .. Yüce çok yüce

Diken olup sarmış bir yığın cüce

Yürekte sayfayı bomboş görünce

Satır satır yazdı aşk yalanını

Gönlümde bir kapı kapıda nefer

Açılmaz içerden çalsa bin sefer

Adı ister Leyla ister Nilüfer

Gayrı gönül tattı aşk yalanını

Aşkı yaz eden de yoz eden de kul

Kaldı mı Yunustan başka bir okul

Dedi gayen aşksa Mevlaya sokul

Yazdı kulun kula aşk yalanını

Yanmış ağzım dostlar gayrı karnım tok

Üflemeye bile cesaretim yok

Bir zaman kalbime saplanan bir ok

Acı acı yazdı aşk yalanını

Nihayet ben vardım ilahi aşka

İstemem aramam dilemem başka

Aşkı Hak ta buldum aşk ki bambaşka

İşte o aşk yazdı aşk yalanını', 'Seninle aramda dağlar var dağlar Anlatma tepenin öte yanını Şu gönül bahçemde kuruyan bağlar Yanık yanık yazdı aşk yalanını Ben sevda taşıdı...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ask-yalani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceyle Aydınlandım,Gecelerde Varım Ben', 'geceyle-aydinlandim-gecelerde-varim-ben-semsettin-arik-k65av', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geceyle aydınlandım,gecelerde varım ben

Bir çocuk kadar günahsız değilken

Hayallerim.

Aşkın vasıtasını tahrip ederdi

duygularım.

Henüz yeniydim ben,

İkbal üzerinedüşlerim vardı.

Şiirler yazardım vuslat ihtivali,

gün ortasında.

toz pembeydi dünya 

Seni görürdüm ben

güzelliklerde

gözlerimin gördükleriyle sınırlı sanardım

Kainat denen umanı

zevkten başka hazzın oldugunu

bilmedigim günlerde ben..

Geceyle tanıştım

derindi geceler

alabildiğince.

Karanlıgın sonsuzlugunu

Keşfetim,

Gecenin koynunda büyürken ben..

evrende bir zerre olan  cismim

devleşti gecelerde

ötelerin ötesini hissettim

İşe yaramayan gözlerimi

devre dışı bıraktım gecelerde

ruhumla görmeye alıştım

Uzaklar yakınlaştı gönlümce

Karanlıgın sonsuzlugunca hayallerim oldu.

Tüm sevdiklerim benimleydi

Kaprissiz,ihtirassız

ve bir resim kadar itaatkar

ışıga düşman degildim  ama...

Güneşin aydınlıgında görülenler

Herkesin gördüğüydü

farklığı gecenin aydınlıgında buldum

geceyle aydınlandım, geceyle varım ben.', 'Geceyle aydınlandım,gecelerde varım ben Bir çocuk kadar günahsız değilken Hayallerim. Aşkın vasıtasını tahrip ederdi duygularım. Henüz yeniy...', ARRAY['Türk Edebiyatı','Şiir','Şemsettin Arık']::text[], 8.5, '{"poet":"Şemsettin Arık","poet_slug":"semsettin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/geceyle-aydinlandim-gecelerde-varim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin?', 'nerdesin-semsettin-arik-hr07m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neredesin? 

Yaşayabiliyor musun bilinmezlikleri? 

Dibi olmayan ummanda

Fark edebiliyor musun incileri? 

Dokunabiliyor musun onlara? 

Var olmayı hissedebiliyor musun? 

Her insanın bir dünya, olduğunu bilerek

Ben birey degil şahsiyetim

diyebiliyor musun? 

Sonsuzluğu gördüğün pencere

açık mı hala? 

Gözlerin kamaşmadan

Baka biliyor musun o ışığa? 

Çelişkilerini yendiğin pusulan

elinde mi hala? 

ruhun mahzenindeki ziya

aydınlatıyor mu esrarengizlikleri? 

Ben aşkım, sevgiyim...

arkadaş ve dostum...

Merhamet ve şevkatim

 insanım...hakikatim....

diye yükselen büyülü sesleri

duyabiliyor musun? 

Ötelerden gelen davet için

hazır mı zümrüt-ü Anka

Kanatlana bilir miyiz yücelere? 

Sen ve ben

Sen: Gerçek,    Ben: Rüya', 'Neredesin?  Yaşayabiliyor musun bilinmezlikleri?  Dibi olmayan ummanda Fark edebiliyor musun incileri?  Dokunabiliyor musun onlara?  Var olm...', ARRAY['Türk Edebiyatı','Şiir','Şemsettin Arık']::text[], 8.5, '{"poet":"Şemsettin Arık","poet_slug":"semsettin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/nerdesin-132-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş yine doğacak', 'gunes-yine-dogacak-mikdat-bal-gdq8q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Belki yarın kim bilir bel ki ondan da yakın

Mutlaka ve mutlaka, ödenecek her hakkın

Bu günlük sen sabreyle, şiddetten de çok sakın

Bu karanlık bitecek, güneş yine doğacak

Sema nura bürünüp, karanlığı boğacak

Bir gün düze çıkarız, bize kalır bu meydan 

Hedefi bulacağız, çıktı artık ok yaydan

Adaletli olunca, ne cin kalır ne şeytan

Bu fırtına dinecek, yine rahmet yağacak

Karanlıklar bitecek, güneş yine doğacak

Torpil rüşvet bizleri, mutsuz etti, bitirdi

Dayanılmaz bir çok dert başımıza getirdi

Çoğu bundan dolayı, umudunu yitirdi

Ümitvar ol ey gencim, güneş yine doğacak

Sen gönlünü geniş tut, ona cihan sığacak', 'Belki yarın kim bilir bel ki ondan da yakın Mutlaka ve mutlaka, ödenecek her hakkın Bu günlük sen sabreyle, şiddetten de çok sakın Bu karanl...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gunes-yine-dogacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahzende Aydınlık', 'mahzende-aydinlik-semsettin-arik-5p6yk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalkıyor   perdeler

Şafak   sökmek   üzere

Bir  kıpırtı,  bir   hareket

Müphem  şekiller   beliriyor

Ruhun    mahzeninde.

Sevinç   heycanları...

tanıdık   çehreler     beliriyor

Acaba   tanıdık  mı? 

Biraz    daha  vakit...

Aydınlığı  beklemeli

Yılların  aşinalığı;   fakat...

veya  '' şahsen  tanırım,  adını   bilmem''

Bir   kadın   suleti  mi? 

Zerafet,  estetik  abidesi

Cinsiyet  yok   ama  insani

Bir   boyutuyla  esrarengiz

Rahman-i...

Tanır   gibiyim

Adını   hatırlasam

Biliyor muydum  ki? 

Zannederim

Kiminle  ve  ne  ile   gelmişti

Yoksa   elinde  kitap  mı?  vardı

Bezm-i   elest''de   mi  tanıştık? 

Biraz   daha  aydınlık

KELİME  ''miydi  acaba

Belki   de...

Evet  ''o''

Tanıyorum   seni  artık

Sen   mukaddesten  bir    parça

Beşerden  ses  ve  nefes,

Doğadan    esinti,

Vahdet-i  vücudun   vasıtası,

Sen, bedene  ruh   verensin

Zelil   ve    perişan   insanı

Eşref-i  mahlukat   yapansın,

Evet  seni  tanıyorum

     Aşksın Sen', 'Kalkıyor   perdeler Şafak   sökmek   üzere Bir  kıpırtı,  bir   hareket Müphem  şekiller   beliriyor Ruhun    mahzeninde. Sevinç   heycanlar...', ARRAY['Türk Edebiyatı','Şiir','Şemsettin Arık']::text[], 8.5, '{"poet":"Şemsettin Arık","poet_slug":"semsettin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/mahzende-aydinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Parçası Ömrümün', 'bir-parcasi-omrumun-kadir-albayrak-r8qub', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nerdesin bilmiyorum zamanın neresinde

Kim anıyor adını kimedir tebessümün

Ne zaman yola çıksam bitti her seferinde

Sonunda ziyan oldu bir parçası ömrümün

Ne mümkün yıldızlardan gittiğin yönü bulmak

Pusula mı bıraktın hasreti okşayacak

Yalvardım Yaradana bu halim ne olacak

Sordukça ziyan oldu bir parçası ömrümün

Sevdan bana okuldu ben sevdana kul oldum

Mezun etmedin beni ne verdinse okudum

Her nefeste ismini ilmek ilmek dokudum

Andıkça ziyan oldu bir parçası ömrümün

Bu yürek ki senindi ya şad et ya da beter

Ya silahını indir ya son kurşunu gönder

Közüne üflediğin ela renkli ateşler

Yandıkça ziyan oldu bir parçası ömrümün

Hasret senin bebeğin benim celladım oldu

Zaman zaman vururdu şimdi zaman da durdu

Bulutlar isyan kustu rüzgarlarsa kudurdu

Estikçe ziyan oldu bir parçası ömrümün

Senden kaçmak kolaydı başarırdım istesem

Yeter ki ben kendimden kendimden kaçabilsem

Lakin dua etmiştim ''Sevdaya varabilsem''

Sevdikçe ziyan oldu bir parçası ömrümün

Vur! ..Acırsa nağmerdim vur ki görevin bitsin

Gayrı hiç bir gecenin sabahı sen değilsin

Geldikçe uzaklardan  ''Mutluyum''  diyen sesin

Geldikçe ziyan oldu bir parçası ömrümün

Düşmedi ya göğsüne toprağa düşer başım

Anlattım anlamadın anlatır mezar taşım

Barikatlar yıkıldı yola çıktı göz yaşım

Aktıkça ziyan oldu bir parçası ömrümün', 'Nerdesin bilmiyorum zamanın neresinde Kim anıyor adını kimedir tebessümün Ne zaman yola çıksam bitti her seferinde Sonunda ziyan oldu bir pa...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bir-parcasi-omrumun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal Gönlümün Nazlısı', 'hoscakal-gonlumun-nazlisi-nuri-can-wtkzy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gidiyorum buralardan yalınayak ve üzgün

önümdeki uçurumlara aldırmadan...

asi... onurlu... ve ümitsiz...

Bu şehri, bu yıldızları, bu düşleri

bu hüznü, bu kederi terk ederek gidiyorum

onurumu koyup başımın üstüne

kör bakışlardan, sahte dostluklardan

yalan hesaplardan uzaklara gidiyorum

hoşça kal ayak izim, gönül gizim, yürek sızım

hoşçakal...

Varsın hayallerim kurduğum yerde kalsın

o gerçekleşmeyen hayallerim.

ardımda yaralı bir yürek

kederli bir ömür

ve yoksul anılar bırakarak

çocuklara veremediğim umudum

yarınlara taşıyamadığım sevdamla çekip gidiyorum işte

hoşçakal gönlümün nazlısı, bağrımın sızısı hoşçakal...

Gidiyorum başım önümde, gözümde nem

duramam artık ey aşk, ey sevdiğim

hüzne ve kedere boğulduğum bu şehirde duramam.

hiç bir anı kabul etmiyor beni

bedenim buz gibi soğuk

yüreğim paramparça keder

kış kadar soğuk ellerim

ardımda yoksul bir sevda

ve bana ait ne varsa bırakıp ardımdan gözü yaşlı

çekip gidiyorum işte

hoşça kal anlımın yazısı, kaderimin küskünü

hoşçakal...

Bütün yaprakları dökülmüş

dalları kırılmış bir ağaç gibi hıçkırarak

ve bırakarak ardımdan sırtımı yasladığım

çınar ağacını yaslı

meçhule giden acılar yüklü bir gemide

uğuldayan rüzgarlara sarıp sesimi

şarkıların sustuğu, aşkların vurulduğu

limanlara gidiyorum sevdiğim

hoşça kal kırık sazım, sevdamın yaralı türküsü

hoşçakal

Bir yıldız daha kaymadan gözlerimden

sönmeden yüreğimde bir arzu daha

ıssız bir köşede bırakıp kırgın gülüşlerimi

düşlerimi hüzünlü bir fotoğrafa yükleyip

çekip gidiyorum işte ey aşk, ey sevdiğim...

Bir daha yağmamalı bu ihanet yağmurları

ağlamamalı bu yürek bir daha

yüreğimdeki acıları başka bir acıyla sarıp

alıp dağların ve yıldızların gölgesini yanıma

yüzümde kış, bakışlarımda kar

yorgun akan bir ırmak misali

kimsesiz sokaklara bırakıp yalnızlığımı

gidiyorum sevdiğim

hoşça kal gecelerimin yıldızı, karlı dağların yalnız kızı,

canımın özü, gönlümün gözü yar 

hoşça kal...

Bütün borçlarını ödedim bu sokakların, alacağımı aldım

geri dönmez bir mevsimdeyim artık

 duramam ey aşk

bu şehre sığamam bu hüzünle

yoksa acılar üşütür beni

kar kavurur anılarımı

donar bakışlarım

üşürüm... üşürüm ey aşk

Sorma nereye, hangi dağın ardına? 

ne kadar uzağa varır yolum? 

kim yoldaş olur bana? 

dönüp gelir miyim yine bahar geldiğinde? 

çiçek açtığında mor dağlar

sorma! ...

Bak akşam

vakit tamam

uzak yıldızlara gözlerimi

ayışığına sessiz gölgelerimi bırakıp

yazıp gözyaşlarımı sabah çiğlerine

sazımdaki hüznü, içimdeki sızıyı

boynu bükük karanfilimi basarak bağrıma

yüreğimin yangınını bırakıp rüzgarlara

çekip gidiyorum buralardan

hoşçakal nazlı çocukluğum, sevdalı gençliğim

bağrımın ateşi, kalbimin ahı, mühür gözlü yar

hoşçakal...

hoşçakal...', 'Gidiyorum buralardan yalınayak ve üzgün önümdeki uçurumlara aldırmadan... asi... onurlu... ve ümitsiz... Bu şehri, bu yıldızları, bu düşleri...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/hoscakal-gonlumun-nazlisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayılıştaki Ben', 'ayilistaki-ben-semsettin-arik-q6sat', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ardımdaki  dağı   çekseler

Sırt  üstü  yuvarlansam  boşluğa! 

Ardımdaki  dağı  çekseler

düşünmeye  fırsat  bulamadan! 

Anmaya   adını  yüzüm  yokken,

Sırtüstü  yuvarlanıp  boşluğa.      

Uzasa  uzasa

ta   haşre   dek

düşsem,  düşsem

rüzgardan   bir  el

ıslıklarıyla  tutmaya   çalışsa

Beynimin  yokluğuna   sevinirken  ben; 

yokluğun   sevincini

Aklımla  yakaladığımı anlayınca

Tekmeler  ve  yumruklar

Varlığımı  maddeleyen  çehresinde

patlasa   patlasa

ve  ben  ben  olduğumu

Birisi  bana   hatırlatmadan

Sende  erisem,  koybolsam

ve  senin  bendeki  halinle.....', 'Ardımdaki  dağı   çekseler Sırt  üstü  yuvarlansam  boşluğa!  Ardımdaki  dağı  çekseler düşünmeye  fırsat  bulamadan!  Anmaya   adını  yüzüm...', ARRAY['Türk Edebiyatı','Şiir','Şemsettin Arık']::text[], 8.5, '{"poet":"Şemsettin Arık","poet_slug":"semsettin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ayilistaki-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simit', 'simit-hekim-coskun-1je7u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sırtımız da düşman nefesi

yaşama takılı çelmeler

takke-külah bir yaşam

gecelerimiz dinamitlenmiş.

gündüzlerimiz yok gibi

yakalayamadığımız adımlarımız bize küs.

karartılan topraklardayız

takvimler bağnaz

matematik yalnız

renksiz

siyah beyaz resimlerdeyiz

çukurdan alçak bir yaşam

b-a-n-a-n-e

s-a-n-a-n-e

b-i-z-e-n-e

devlet

siyaset

sokaktan aldığımız simit.', 'sırtımız da düşman nefesi yaşama takılı çelmeler takke-külah bir yaşam gecelerimiz dinamitlenmiş. gündüzlerimiz yok gibi yakalayamadığımız a...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/simit-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güldü', 'guldu-sair-sekillreis-2zmqu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güldü derde keder aglayamadi...

Güldü yandiginda yangin izi kaldi diye...

Güldü carenin bicareligine...

Güldü amacsizlik icinden aldigi amacina güldü...

Aska gülebilmek icin güldü oysa onun gülümsemesi degildi...

Komik olan aglarken askini gülümsetmeye calismasiydi', 'Güldü derde keder aglayamadi... Güldü yandiginda yangin izi kaldi diye... Güldü carenin bicareligine... Güldü amacsizlik icinden aldigi amac...', ARRAY['Türk Edebiyatı','Şiir','Şair Sekillreis']::text[], 8.5, '{"poet":"Şair Sekillreis","poet_slug":"sair-sekillreis","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/guldu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şekillendik-şekillendirildik, Adı Aşk''sa', 'sekillendik-sekillendirildik-adi-ask-sa-his-kaybi-mk-pedri', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şekillendirdik

Bir düzlemde desteksiz durdu duygular

Az genişce bir tas''a sığdı sevda 

koparılmıştı çiçek 

Hiç Gocunmadı toprak

İmdadına yetişti - Bahçıvan -

Ömür. -ölür-

Galib''in Halinden bir Malup Gelir

Bütün hesaplar aynı neticedir

Az biraz Sevdiysen

Hesabı bitmez gecelerin

Ve gün ne yenidir nede ekstra''ya çıkmıştır bizim için

Bir intihar modudur yaşam

Damarlarında dolaşır Şeytan ve de acılar...

Yaşarsan SEN...! ! !

Hadi Sabret Gözlerim...

Hadi Diren Yüreğim...

Uzağım Üsküdar... 

Yakınımda kalan Acı..! ! !

SEN...

H.K Ulcnlr czv.3 04/10/2005..', 'Şekillendirdik Bir düzlemde desteksiz durdu duygular Az genişce bir tas''a sığdı sevda  koparılmıştı çiçek  Hiç Gocunmadı toprak İmdadına yet...', ARRAY['Türk Edebiyatı','Şiir','His Kaybı Mk']::text[], 8.5, '{"poet":"His Kaybı Mk","poet_slug":"his-kaybi-mk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sekillendik-sekillendirildik-adi-ask-sa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmuru Severim Ben', 'yagmuru-severim-ben-cemal-tekmen-titi5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmuru severim ben,yağmurlu havayı

Ağlarken belli olmaz biliyormusun? 

Yağmuru severim ben,yağmurlu havayı

Yağmurlar biriktiririm içimde.

Ağlarım sonra bulutlarla beraber

Yağmur yağarken belli olmaz,dedim ya,

Ağlarken anlamaz kimse ağladığını,

Yağmurun kokusunu duyunca,

Başlar gözlerim nemlenmeye,

Düşüncelerim bir bulut sanki,yağmura gebe.

Yağmurlar anlar beni bilirim.

Ağlarken çığlıklarıma eşlik eder gökgürültüsü,

Ne izi kalır bir ara dertlerin,

Ne de kabuklaşmış tortusu.

Dedim ya sayın abim,severim yağmurları

Yağmur durur usulca, toprak kokar sonra

Benim nefesimde yanık ciğerlerim gibi.

Bağrımı açar yürürüm sonra ıslak yolda.

Ne güzel,temizlenmiştir sokaklarda günahlardan.

Ah be gözlerim sen arındın mı acaba cefalardan? 

Dert etme, elbet tekrar yağar yağmur,

Biriktir sen yine ey gözlerim yağmurlarını,

Bekle,tekrar yağınca yağmur,

Ağlaşırız yine bulutlarla.

Bari sen bekle gözlerim,

Nasıl olsa ağlamamı bekleyen yok,

Bu zemheri karanlıkta.

Yağmurla birikti artık gözlerimde,

Damlalar sel oldu bedenimde,

Yağ artık yağmur,

Yağ artık yağ! 

Sen yağmazsan tam olamıyorum.

Çabuk yağ hadi görmüyormusun? 

Sen yağmadan ağlayamıyorum.', 'Yağmuru severim ben,yağmurlu havayı Ağlarken belli olmaz biliyormusun?  Yağmuru severim ben,yağmurlu havayı Yağmurlar biriktiririm içimde. A...', ARRAY['Türk Edebiyatı','Şiir','Cemal Tekmen']::text[], 8.5, '{"poet":"Cemal Tekmen","poet_slug":"cemal-tekmen","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yagmuru-severim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben sende hep hüzün buldum', 'ben-sende-hep-huzun-buldum-guzin-osmancik-gw3rs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben sende hep hüzün buldum

Belki zamansızdı seni buluşum

Rahat bir aşk değildi bizmkisi

Hep hüzün

Gözyaşı ve

Ayrılık vardı....

Ümit Yaşarı okur,

Şarkılar dinlerdik

Aşk üzerine

Hiç ümitlenmedik

Biliyorduk ayrılık kaçınılmazdı

Hep hüzün,

Gözyaşı 

Ümitsizlik vardı

Ne kadar çok anlatacak şeyimiz vardı

Hiç bitmedi zaten hep yarım kaldı

İkimizde biliyorduk

Sonu yoktu bu aşkın

Hiç mutlu olamadık biz.

Birlikteyken bile

Ayrılığı konuşurduk

Başka bir şey düşünmezdik ki

Beraber de olamazdık zaten

Yasaklıydık ikimiz.

Aşkımızda hüzün,

Gözyaşı, acı vardı

Hiç kavuşamadık zaten

Sonunda 

Ayrıldık işte biz.......

          evvelim', 'Ben sende hep hüzün buldum Belki zamansızdı seni buluşum Rahat bir aşk değildi bizmkisi Hep hüzün Gözyaşı ve Ayrılık vardı.... Ümit Yaşarı o...', ARRAY['Türk Edebiyatı','Şiir','Güzin Osmancık']::text[], 8.5, '{"poet":"Güzin Osmancık","poet_slug":"guzin-osmancik","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ben-sende-hep-huzun-buldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanışma', 'tanisma-metin-yalti-x2ugq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '.............................................................''Feride Özmat''la'' 

Seni görmeseydim de eğer 

severdim yine inan bu kadar.. 

Bazı tanışmalarımda 

Genellikle... 

bir merak oluşurdu bende 

Bu gün seni beklerken 

Farkettim de.. 

Hiç bir merak yoktu 

Kırk yıllık dostum gelecek gibi 

Az önce gitmişde dönmüşsün gibi 

Gelmiştin buluştuğumuz da... 

Seni görmeseydim eğer 

ne ruj yerine içtenliği 

ne allık yerine dostluğu 

ne de rimel yerine gülümseme 

süründüğünü de bilemiyecektim asla... 

Gri bulutlar yüklüydü kasvetliydi hava 

Kimbilir ki? 

Belki dostluğumuzu sindiricesine 

çiseliyordu yağmur ince ince 

belki de kadeh kaldırmasıydı bu yağmur 

Kız kulesiyle Galata kulesinin tanışıklığımıza? 

Seni sevdiğimde 

yüzünde 

.........ne ruj 

...............ne rimel 

.....................ne allık 

yoktu güzelliğin adına... 

ama büründüğün 

dostluk 

........sevecenlik 

................ve içtenlik 

öylesine yakışmıştıki benliğine 

Güzelliğinden de öte... 

 18/11/2005 Üsküdar.', '.............................................................''Feride Özmat''la''  Seni görmeseydim de eğer  severdim yine inan bu kadar..  Baz...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/tanisma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustum', 'sustum-cemal-tekmen-y41oq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ve sustu gece,

Sustum.

Sırtımı dayayıp duvara,

Dönüp yalnızlığıma,sustum.

Titrek ellerimle bir sigara daha yaktım.

Söyle bir silkelenip etrafı süzdüm.

Duvarlarım boş,duvarlarım loş.

Rutubetli ölüm maviliğinde her yer.

Ah ne güzeller, ne güzel

Sessiz ve karanlık odam.

O da sustu, ben de sustum.

Bir ara doğruldum yerimden.

Buğulanan camımdan baktım etrafa.

Sokak ta susmuş,köpekler de,

Etraf sus-pus olmuş yine.

Ayyaşlar da susmuş, polis telsizleri de.

Oysa konuşulmadık onca şey varken,

Susturulması koca bir yüreğin ne zor? 

Yaşanılacak onca anlar varken,

Kötürüm edilmesi umutların ne de ağır? 

Zor kardeşim zor.

Sen de sustun biliyorum.

Zor dedim ya,çok zor.

Üşüyor gece, üşütüyor gece.

Duvarlarım üşüyor bir de ellerim.

Her yerim üşüyor bir de yüreğim.

El titremelerim ve nikotin nöbetlerim artoıyor,

Duvarlarım susuyor hala

Gece susuyor,

Ben susuyorum.

Gözlerim artık yatmamı söylesede,

Yüreğim dur diyor,ben titriyorum.

Sokaktan geçen arab sallıyor evi,

Camlar titriyor,

Bedenim tiriyor,

Ben titriyorum.

Ve yorgun düşüyor ellerim,

Sigaram da yorgun, ciğerlerim de.

Yüreğim yine sitem etse de,

Yoruldu artık gözlerim,

Yoruldu bedenim,

Ben yoruldum.

Ve sustu gece,

Sustum.

Sırtımı dayayıp duvara,

Susuyorum...', 'Ve sustu gece, Sustum. Sırtımı dayayıp duvara, Dönüp yalnızlığıma,sustum. Titrek ellerimle bir sigara daha yaktım. Söyle bir silkelenip etra...', ARRAY['Türk Edebiyatı','Şiir','Cemal Tekmen']::text[], 8.5, '{"poet":"Cemal Tekmen","poet_slug":"cemal-tekmen","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/sustum-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmek Kavuşmaksa Sevgiliye', 'olmek-kavusmaksa-sevgiliye-mehmet-ali-yapici-nc4ue', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnsan oğulları ağlar niye,

Sevdiği yakını öldü diye,

Peki ölümden korkulur niye? 

Ölmek kavuşmaksa sevgiliye...', 'İnsan oğulları ağlar niye, Sevdiği yakını öldü diye, Peki ölümden korkulur niye?  Ölmek kavuşmaksa sevgiliye......', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Yapıcı']::text[], 8.5, '{"poet":"Mehmet Ali Yapıcı","poet_slug":"mehmet-ali-yapici","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/olmek-kavusmaksa-sevgiliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toparlan Vakit Dolmadan', 'toparlan-vakit-dolmadan-mehmet-ali-yapici-zem9o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabır işidir beklemek,

Zamana zaman eklemek,

Zaman katletmek demek; 

Boşa zaman tüketmek.

Çok önemli kavram, zaman,

Geri dönmez geçen bir an,

Ey ömrü boş geçen insan,

Toparlan vakit dolmadan...', 'Sabır işidir beklemek, Zamana zaman eklemek, Zaman katletmek demek;  Boşa zaman tüketmek. Çok önemli kavram, zaman, Geri dönmez geçen bir an...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Yapıcı']::text[], 8.5, '{"poet":"Mehmet Ali Yapıcı","poet_slug":"mehmet-ali-yapici","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/toparlan-vakit-dolmadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünceden Hissiyata', 'dusunceden-hissiyata-utku-demir-oeshc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşünmekten zevk alıyor

Onsuz ben olamam diyorsan

Düşünce dağında bir çiçek

Beklentisiz yaprakları 

Her mevsimde yeşil kalan

Fırtılara karşı koyarken 

Gövdesiyle güven sunan

Hayatı umudun ötesini taşıyışında

Acının değeri öğrettiğini unutmayışında

Düşünce dağını üzerime kurup

Sevgi çiçeğini açtırabilir misin? 

Duygularını ertelemeden anı tadıp

Gerekirse herkese meydan okurken

Sağanak bir yağmurda şemsiyesiz

Sırılsıklam gülüşünde gözler

Dokunup narince hüzünlerime

Yaralarıma ilaç olan merhemi

Varlığınla gönlüme koyan

Başını sınırsız gökyüzüne kaldırışında

Havasız fanusun içine sokuluşunda

Düşünceden hissiyata geçip 

Gözlerini yüreğime koyabilir misin?', 'Düşünmekten zevk alıyor Onsuz ben olamam diyorsan Düşünce dağında bir çiçek Beklentisiz yaprakları  Her mevsimde yeşil kalan Fırtılara karşı...', ARRAY['Türk Edebiyatı','Şiir','Utku Demir']::text[], 8.5, '{"poet":"Utku Demir","poet_slug":"utku-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dusunceden-hissiyata-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerden bilirdim.', 'nerden-bilirdim-i-shak-ozlu-29q8i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nerden bilirdim,

Gözlerinden süzülen,

Sıcak bir bakışın,

Cemre olup yüreğime düşeceğini.

Nerden bilirdim,

Dudağından dökülen gülüşün,

Volkanlara dönüşüp,

Bedenimi yakacağını.

Nerden bilirdim,

Adına türküler yakılan,

Uğruna gurbete çıkılan,

Sevda ateşinin saracağını.

Nerden bilirdim,

Seni düşünmenin,

Seni sensiz yaşamanın,

Sonsuz kaderim olacağını.

Ya o kara gün,

Yedi dağın ardında,

Yetmiş kilit altında tutulan,

Ayrılıklar dünyasının gurur savaşçıları,

Dalga dalga gelip,

Sardılar dünyamızı,

Esir aldılar tabiatı.

Ne bir güneş,

Ne bir gül,

Ne bir yol,

Yok yok yok.

Yok olup,

Yedi kat yerin dibine girdiler.

Düşüncelerim,

Dünyamla birlik,

Ağır ağır esir olurken,

Gurur fırtınasının,

Kahrolası bir silaha dönüşüp,

Umutlarımızı,

Bir bir vuracağını,

Nerden bilirdim.

Nerden bilirdim,

Gül bahçemizin ışıksız zindanlara döneceğini,

Nerden bilirdim.

İki yüreğin yaşarken öleceğini.', 'Nerden bilirdim, Gözlerinden süzülen, Sıcak bir bakışın, Cemre olup yüreğime düşeceğini. Nerden bilirdim, Dudağından dökülen gülüşün, Volkan...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/nerden-bilirdim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur sonralarına (-1-)', 'yagmur-sonralarina-1-nazan-i-zmirli-y4y01', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'düşünüyorum,

..birlikte     yaşamadık

...................yağmurları

.....yağmurdan   sonra 

.......toprak  buğularını

ama............................

.her yağmurdan sonra

.........çılgınca arzuladık

.............birlikte   olmayı

kah! dizelerde buluştuk

kah!    tellerin    ucunda

yürüdük...............................

yürüdük...............................

umut yolculuğunda.............

kuru yanımız kalmadı..........

parmaklarımızın  ucunda ki

................kalemden  başka

oysa o da severdi...............

............................yağmurları

parmaklarımıza sıkışmadan 

acılarımıza...........................

özlemlerimize...................... 

.....................şahit olmadan

ar-tık......................................

yağmurları bize bıraktı.........

.......ruhlarımızı endişelerden

arındırmadan........................

yağmur,

yağmurum,

her yağmurla gel bana..........

ne dizeler, ne tellerin ardı......

yetmiyor..................................

yağmur sonralarına................

Nazan İzmirli-18.11.2005', 'düşünüyorum, ..birlikte     yaşamadık ...................yağmurları .....yağmurdan   sonra  .......toprak  buğularını ama......................', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yagmur-sonralarina-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi ki yoktur', 'i-yi-ki-yoktur-mikdat-bal-iymua', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mutluluk iksiri, yok ki elimde

Hemen kullanırdım iyi ki yoktur

Çünkü her şey gerçek, hayat ölüm de

Hayalde yaşardım, iyi ki yoktur', 'Mutluluk iksiri, yok ki elimde Hemen kullanırdım iyi ki yoktur Çünkü her şey gerçek, hayat ölüm de Hayalde yaşardım, iyi ki yoktur...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/iyi-ki-yoktur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ortadoğu Kan Çekiyor', 'ortadogu-kan-cekiyor-kamil-at-umrm2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu savaşta çok köpek öldü

Dünyayı gerçekten böldü

Malını canını satan yüceldi

Ortadoğu kan çekiyor kan.

Kimin vücudu kavruldu boşa

Newyork''ta yürür hele sarhoşa

Rey veriyor busha yazıktır kuşa

Ortadoğu kan çekiyor kan.

Sokakta toplayıp savaşa saldı

Bir anda kamera otorite oldu

Çok satılmışlar tarihe daldı

Ortadoğu kan çekiyor kan.

Kimi ülkeye candan ambargo

Kendi ülkesinde askeri kargo

Hastaneler doldu kokuyor sargı

Ortadoğu kan çekiyor kan.

Sizler uçağını onlar da katırını

Der Kamil At inersen verir satırını

Karanlık despotlar görür hatırını

Ortadoğu kan çekiyor kan.', 'Bu savaşta çok köpek öldü Dünyayı gerçekten böldü Malını canını satan yüceldi Ortadoğu kan çekiyor kan. Kimin vücudu kavruldu boşa Newyork''t...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ortadogu-kan-cekiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yağmuR', 'yagmur-asima-azra-b1kur', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senelerce yükü damıtıp içime

gözlerimden aşağıya bıraktım

__________yüzümde el izlerin yıkansın diye...

İstanbul''u düşman edip kendime

bütün gece avurtlarından aktım

___________yağmurun faili de ıslansın diye...', 'Senelerce yükü damıtıp içime gözlerimden aşağıya bıraktım __________yüzümde el izlerin yıkansın diye... İstanbul''u düşman edip kendime bütün...', ARRAY['Türk Edebiyatı','Şiir','Asima Azra']::text[], 8.5, '{"poet":"Asima Azra","poet_slug":"asima-azra","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yagmur-239-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salkım Söğüt', 'salkim-sogut-kadir-albayrak-r47uu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dalı bile bize öğüt boynu bükük salkım söğüt

Sana bakar kahrolurum kaldır başın salkım söğüt

Kaderimiz aynı bizim gölgelerde kaldı izim

Şarkı oldu sazım sözüm rüzgarlarda salkım söğüt

Yelde değil selden değil sonbahardan kıştan değil

Bu eğilmen boşa değil sevdadandır salkım söğüt

Senin halin nice böyle boyun uzar hem göklere

Uzadıkça dalın yere hasret duyar salkım söğüt

Ol boynumuz kıldan ince düşer kalkar hak deyince

Hak yoluna yüz sürünce toprak baldır salkım söğüt

Hakka aşık kula aşık dargın dağil hep barışık 

Öbek öbek bir sarmaşık oluverdik salkım söğüt

Benim gönlüm yara bere dağılmışım dört bir yere

Çok sevmişken yoktan yere aşka küstüm salkım söğüt

Senin sesin rüzgar ile çığlık olmuş gecelere

Seninle biz bir hecede buluşmuşuz salkım söğüt

Sen ulusun halin ibret yoktur başka söze hacet

Dünya üç günden ibaret dert  ortağım salkım söğüt

Başını eğ başım gibi bir kaç damla yaşım gibi

Varım yoğum aşım gibi eşim oldun salkım söğüt', 'Dalı bile bize öğüt boynu bükük salkım söğüt Sana bakar kahrolurum kaldır başın salkım söğüt Kaderimiz aynı bizim gölgelerde kaldı izim Şark...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/salkim-sogut-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aktivite', 'aktivite-abdulvahap-ates-r8zle', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaç-göç zamanı geçti,maslahat aktivite,

Üret,yönet,adam et,aban artık divite.', 'Kaç-göç zamanı geçti,maslahat aktivite, Üret,yönet,adam et,aban artık divite....', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Ateş']::text[], 8.5, '{"poet":"Abdulvahap Ateş","poet_slug":"abdulvahap-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/aktivite-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sevda Adamız Olsaydı Bizim', 'bir-sevda-adamiz-olsaydi-bizim-nesrin-gocmen-esacx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Okyanusun saklı köşelerinde 

Ak mavi sedamız kalsaydı bizim 

Dalgaların çılgın neşeleriyle 

Dolan bir adamız olsaydı bizim 

. 

Sevgiyle inlese gizli koyları 

Yeşiller giyinse dere boyları 

Umutsuz mevsime uzanan rayı 

Silen bir adamız olsaydı bizim 

. 

Işıkla raks etsin sevdanın kızı, 

Gecelere dalsın ah lar ve sızı 

Saçımın telinden yaptığın sazı, 

Çalan bir adamız olsaydı bizim 

. 

Dirilsin düşlerle hayalin gizi 

Korusun maviler kem gözden bizi 

Eksilmiş kalplere gizlenmiş izi 

Delen bir sevdamız olsaydı bizim 

Yalan bir adamız kalsaydı bizim 

.

19 Kasım 2005', 'Okyanusun saklı köşelerinde  Ak mavi sedamız kalsaydı bizim  Dalgaların çılgın neşeleriyle  Dolan bir adamız olsaydı bizim  .  Sevgiyle inle...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-sevda-adamiz-olsaydi-bizim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gevezedir o', 'gevezedir-o-mikdat-bal-chxhg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kendini metheder, bana ne derim

Hoşuma gitmezse çeker giderim

Ne yüzüne vurur ne ses ederim

Bu tavrına şaşmam, gevezedir o

Binlerce dostu var meşhurdur adı

İyilik yapmakmış bütün hayatı

Denizde yatı var sahilde katı

Hiç ardına düşmem gevezedir o

Bir oğlu hakimmiş, kızı profesör

Yemin Billah eder, der istersen sor

Bir oğlu doktormuş değilken masör

Onunla uğraşmam, gevezedir o

Sana fırsat vermez, ne susmak bilir

Sözleri yutulmaz geri tepilir

Ona yalancısın, diyesim gelir

Hududumu aşmam, gevezedir o', 'Kendini metheder, bana ne derim Hoşuma gitmezse çeker giderim Ne yüzüne vurur ne ses ederim Bu tavrına şaşmam, gevezedir o Binlerce dostu va...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gevezedir-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayanamıyorum Anne.', 'dayanamiyorum-anne-yavuz-bayram-caliskan-rc1gs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kucağında bahardı gözlerim,

Öpücüklerin  taze kır çiçekleri,

Meleklerin en kutsalı,insanların güzeli,

Biz seninle neler yaşadık,

Dayanamıyorum anne.

Öperdim gül yüzünü,

Kucaklardım seni doyasıya,

Isıtırdın, güneşim gibiydin,

Biz ne yağmurlarda ıslandık,

Dayanamıyorum anne.

Rüzgarlara göğüs gerdin,

Yokluklara saçlarını süpürge ederdin,

Yatağımda neler söylerdin,

Biz ne günler geçirdik,

Dayanamıyorum anne.

Dünyaya baktık bir anlık,

Şimdi yoksun her yer karanlık,

Biz ne azaplar yaşadık,

Dayanamıyorum anne.

Ağlasam da geri gelmezsin,

Yağmurlarla inip gülmezsin,

Bak yavrun anasız mı,? bilmezsin,

Biz ne ağlayışlar yaşadık,

Dayanamıyorum anne.

Yaşadığım dünya sesizliğe büründü,

Yağan kar damlardan yüreklere küründü,

Gecem gündüzün gidiş haberinle öründü,

Biz ne yıllar yaşadık,

Dayanamıyorum anne.

Döndüm baktım geriye ne kaldı,

Bir güzel annemi Allah''ım aldı,

Dünyalarca sevdiğim bir güldü,

Sevgin canıma yürek oldu,

Biz ne ruhlarla yaşadık,

Dayanamıyorum Anne.', 'Kucağında bahardı gözlerim, Öpücüklerin  taze kır çiçekleri, Meleklerin en kutsalı,insanların güzeli, Biz seninle neler yaşadık, Dayanamıyor...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/dayanamiyorum-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai Ben', 'rubai-ben-nihat-yucel-vfdim', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir sel gibi çoşsam yıkarım bendimi ben

Elbet gün olur gösteririm fendimi ben

Bir sır küpüyüm kendimi bildim bileli

İfşa ediversem asarım kendimi ben', 'Bir sel gibi çoşsam yıkarım bendimi ben Elbet gün olur gösteririm fendimi ben Bir sır küpüyüm kendimi bildim bileli İfşa ediversem asarım ke...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yaptın...', 'ne-yaptin-ruya-deniz-demir-9oadk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum ne yaptın seni bana bu kadar sevdirecek

Belki sade bir güzellikti karşımda duran

Birden bire hayatımın anlamı olmaya aday

Birden içimde o dingin fırtınaları coşturan

Birden bire her şeyi dünyayı yakmamı fısıldayan

Neyse her neyse güzel bir o kadar şiddetli…

Bilemiyorum ne yaptım seni bu kadar sevmek için

Belki yalnızca bir hayal görme isteğimdi

Birkaç saniyelik bir rüyanın ardından

Bütün gün görmeye devam etmek istediğim

Her neyse seni bana sevdiren o kadar güzel…

Bilmiyorum ki ne yaptın beni sana aşık edecek

Belki bir durgun göl misali dinginliğinde

Belki de dağ havası hırçınlığında bir şey

Belki yalandan sevişmelerle dolu bir yağmur

Belki ıslak ayakla sevda romansı

Ama her neyse sevdim yine de ağlamayı…

Bilmiyorum ne zamandır girdin hayatıma

Kim bilir ki ne zaman gideceksin

Ama yine de ne yaptın ki bana 

Beni böyle delirtecek bu denli sevdirecek

Bu kadar aşık edecek ve hayatıma yerleşecek

Çığ düşüp söndürmeyecek yangınlara

Sonu gelmeyen koridorlara 

Sonsuz çıkmazlara gömecek

Yine de her şeyi hoş gösterecek

Her neyse o yaptığın yine de çok güzel…

Şimdi yarım yamalak kalmış bu sevdayı

Kendi kendime çözmeye çalışıyorum

Bütün bilmecelerini çözdüm ama

Çözemiyorum bana ne yaptın

Bu düğümü, bu soruyu, bu bilmeceyi

Bu garip şekil şemali bir türlü

Çok uğraşsam da çözemiyorum…', 'Bilmiyorum ne yaptın seni bana bu kadar sevdirecek Belki sade bir güzellikti karşımda duran Birden bire hayatımın anlamı olmaya aday Birden ...', ARRAY['Türk Edebiyatı','Şiir','Rüya Deniz Demir']::text[], 8.5, '{"poet":"Rüya Deniz Demir","poet_slug":"ruya-deniz-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ne-yaptin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Ayrı Beden', 'i-ki-ayri-beden-ayse-meltem-dogan-8be05', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İki ayrı beden

İki ayrı ucunca oturuyordu kanepenin.

İçlerini ısıtan,

Bir bardak demli çay değildi şüphesiz...

Konu konu üstüne 

Konular ise bahane

Hayli gülüştüler,

Bahaneler üzerine...

Derken; 

Doğaçlama  oyunun

Kahramanları oldular

Gerçeğin Kendisinden habersiz...

Biri, ''Alıngan Sevgili''

Diğeri “İdare” eden.

Konu, konu üstüne 

Konular ise bahane...

Hayli gülüştüler,

Bahaneler üzerine...

“İdare” eden; Affet! 

                            Dedi...

“Alıngan”; Asla! 

Üşümüş,

Donmak üzere olan

Pamuk Kardeşleri,

Avuçlarının arasına aldı...

Minik bir buse kondurdu 

Ilık rüzgar eşliğinde...

Sonra...

Defalarca yineledi, affedilme arzusunu...

Bulutlara değmesine rağmen

Pes etmedi “Alıngan”...

İrade zerreciklerini, 

Alelacele topladı bir köşeye...

Derin bir nefes çekti Ciğerlerine...

Neden sonra...

Olmaz! Diyebildi, işitmeden...

Yağmur bulutu yüklü

Şimşek bakışlarını

Yaramaz, yavru ceylanın

Buğulanmış, zeytin taneciklerine

Yaklaştırdı...

Ilık, taze nefesi

İksir misali, estikçe yüzünde...

Güya; 

Final sahnesi bu ya

Sarıldılar sıkıca birbirlerine...

Ruhların dansı başlamıştı...

Meğer ne yakınmış bulutlar...

Medcezirler arasında

Oyunları, geldi akıllarına...

Eşzamanlı refleks halinde

Çevirdiler yüzlerini

Birbirlerine...

Yağmur bulutu yüklü

Şimşek bakışlarını

Yaramaz, yavru ceylanın

Buğulanmış, zeytin taneciklerine

Yaklaştırdı...

Ilık, taze nefesi

İksir misali, estikçe yüzünde...

....

Ayşe Doğan', 'İki ayrı beden İki ayrı ucunca oturuyordu kanepenin. İçlerini ısıtan, Bir bardak demli çay değildi şüphesiz... Konu konu üstüne  Konular ise...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Meltem Doğan']::text[], 8.5, '{"poet":"Ayşe Meltem Doğan","poet_slug":"ayse-meltem-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/iki-ayri-beden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demek Gidiyorsun', 'demek-gidiyorsun-celal-topo-he0ig', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gidiyorum diyorsun

Yarım mı kalacak sana olan mısralarım

Dudaklarımda solgun bir gül gibi

Renksiz mi duracak gülüşlerim? 

Demek gidiyorsun

Hoşça kal yahut bir elveda demeden

Eski dost yeni düşmanına

Ben karanlıkları hangi renkle boyayacağım

Kime şiir yazıp 

Kimi imgelerle anlatacağım

Gidişin vanasıyla kapatarak

Suyunu kesiyorsun çeşmelerin

Şimdi ben

Yanan yüreğimi nerede soğutacağım

Demek gidiyorsun

Sanal kapıyı yüzüme kapatıp

Beni yalnızlığın kucağına bırakarak

Tuz basıp ta kanayan şu yarama

Demek gidiyorsun.....

Ne diye bilirim....Yolun açık olsun...



18 / 11 / 2005   Antalya', 'Gidiyorum diyorsun Yarım mı kalacak sana olan mısralarım Dudaklarımda solgun bir gül gibi Renksiz mi duracak gülüşlerim?  Demek gidiyorsun H...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/demek-gidiyorsun-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybetmek Bana Göre Değil', 'kaybetmek-bana-gore-degil-gizem-yurdakul-fjync', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dört duvar arasında kayboldum.

Artık tek ağlama günüm Cuma değil.

Cuma günü ağlamımın nedeni

Bütün hafta acılarımı biriktirip 

Bukete gözyaşlarımı anlatıyorum belki,

Onlar beni anlatıyor, bilmiyorum…

Ama artık tutamıyorum beş gün acımı.

Mutluluk bedenimi ve ruhumu bırakmış

Düşünceler denizinde sürüklüyor.

Bir hata her şeyimi aldı götürdü.

Belki her şeyimi değil ama olsun.

Kaybetmek bana göre değil! 

Ailem ve akrabalarım var.

Hala bir odaya sahibim.

Ama arkadaşlık? Hiç sanmıyorum…

Hayat beni, benim bamyayı sevdiğim kadar seviyor

Ben asla alınyazım diyemem.

Asla sığınamam bu yazının arkasına

Dedim ya kaybetmek bana göre değil.

Yardım edin boğuluyorum duygular denizinde

Yardım et kalbimin en temiz bölgesinden çıkardığım sevgi

Yardım et boğulmak istemiyorum.

Dedim ya kaybetmek bana göre değil…..', 'Dört duvar arasında kayboldum. Artık tek ağlama günüm Cuma değil. Cuma günü ağlamımın nedeni Bütün hafta acılarımı biriktirip  Bukete gözyaş...', ARRAY['Türk Edebiyatı','Şiir','Gizem Yurdakul']::text[], 8.5, '{"poet":"Gizem Yurdakul","poet_slug":"gizem-yurdakul","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kaybetmek-bana-gore-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Yarim', 'gel-yarim-galip-sari-hma1t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geceler karanlık, uykum gelmiyor. 

Sensiz doğan günler ışık vermiyor. 

Mektupların, hasretim gidermiyor

Hasretinden ölmeden dön gel yarim.

Gündüzün tadı yok, gecenin sonu.

Ruhumda yaşıyorum yokluğunu.

Hiç bir şey doldurmuyor boşluğunu.

Boşlukta savrulmadan dön gel yarim.', 'Geceler karanlık, uykum gelmiyor.  Sensiz doğan günler ışık vermiyor.  Mektupların, hasretim gidermiyor Hasretinden ölmeden dön gel yarim. G...', ARRAY['Türk Edebiyatı','Şiir','Galip Sarı']::text[], 8.5, '{"poet":"Galip Sarı","poet_slug":"galip-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sensiz-140-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takılır aklıma (02 -Aydın)', 'takilir-aklima-02-aydin-mehmet-coban-prf2y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aydın görürüm

Ben aydınım diye dolaşan

Toplumundan uzak

Toplumuna yabancı

Kendi bireyine kapanmış

Paylaşımcılıktan uzak

Kendi kendine olan

Kendinden başkasını 

Beğenmeyen, kabul etmeyen

Herkesi, her şeyi 

Biçimlendirmeye çalışan

Toplumunun acılarından uzak

Toplumun geleceğinden uzak

Toplumun kimliğinden uzak

Gözleri başka yerlerde

Gönlünü başka şeylere kaptırmış

Kuvvetliye alkış tutan

İçinden çıktığı topluma nankör

Anasına babasına nankör

Ailesine, çevresine nankör

Sanki ne oldum delisi

Sanki güçlünün oyuncak kedisi

Tek bildiği maşalar efendisi

Kaptırmış efendilerinin ellerine 

Görmez bir türlü aynada kendini

Derim, aydın bu değil

Aydın, bilginin aydınlığıyla

Aydın, zayıfın yanında

Aydın, ezilenin yanında

Aydın, ezenlere düşman

Aydın, toplumuyla yaşayan

Aydın, ağlayan çocukların gözlerinde akan yaş

Aydın, çöplüklerden geçinen çocuklarla aç

Aydın, mazluma atılan bombalarla savaşan

Aydın, her türlü yardakçılığa meydan okuyan

Aydın, uzak her türlü çıkardan çıkarcılıktan

Aydın, yaşamıyla zulüm edenleri korkutan

Aydın, zulüm görenlerin gözünde kahraman

Takılır aklıma

Hani nerede? 

Aydın değil hiçbir zaman

Kuvvetlinin sözcülüğüne soyunan

Zayıfı iten, kakan, horlayan

İstisnadır aklıma takılanlara

Gerçekten aydın olan

19.11.2005-İzmir', 'Aydın görürüm Ben aydınım diye dolaşan Toplumundan uzak Toplumuna yabancı Kendi bireyine kapanmış Paylaşımcılıktan uzak Kendi kendine olan K...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/takilir-aklima-02-aydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kudret Eli', 'kudret-eli-hikmet-uzun-moano', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yed-i kudretin tutmuştur ben-i Adem perçemini,

Muradın olmadan hiç mümkünmüdür bir iş işlemek,

Vuslatından gayrısı kandırmaz aşkın sersemini,

Farklı bir fikir varsa zandır elzemdir kişkişlemek.', 'Yed-i kudretin tutmuştur ben-i Adem perçemini, Muradın olmadan hiç mümkünmüdür bir iş işlemek, Vuslatından gayrısı kandırmaz aşkın sersemini...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Uzun']::text[], 8.5, '{"poet":"Hikmet Uzun","poet_slug":"hikmet-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kudret-eli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özendiğim Herşey Hüsran Olmuştur', 'ozendigim-hersey-husran-olmustur-munevver-senol-euu9o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayatta neye özendiysem, utlaka bir aksilik olmuştur,pendikte oturduğumuz gecekondunun sahibi,makinist hasan amcanın tam,9 kiracısı vardı kocaman çevirdiği bahçenin etrafına derme çatma konduları dizmiş,evmi? evişte,istanbulmu? istanbul taşı toprağı altın diyen gelmiş, her yöreden insan vardı, ama hepimiz bir aile gibitdik,annem işe giderken kardeşimle beni onlara emanet eder gözü arkada kalmazdı çünki kendi evlatları gibi gözetir kollarlardı,.Bir bayram ben gene artist mecmuasından belgin doruğun kıyafetinden,çizdim modeli mahalle terzimiz meryem teyzeye,götürdüm o zaman konfeksiyon pek yoktu,kalın kemerli kalçadan büzgülü,leylak rengi akfilden eteğim altında tabiki kolalı dantelli jiponum üstünede beyaz karpuz kollu kare yakalı önünde inci düğmeli bulüzüm,

ayağımdada beyaz rugan çaça topuklu ayakkabılarım,pekte havalıydım doğrusu,ozaman saçlarım çok uzundu annemden yalvar yakar kahkül için izin almıştım,ama belgin doruk yanlardanda yanağına doğru ay gibi kıvırıp,cina yapmıştı,bende bir cesaret kestim limonlu suylada ıslatıp cina yaptım o zamanlar jöle falan yoktu,tabi annem işten geleceğine yakın,kestiğim cinaları uzun saçların arasına katardım,taki bayramda saçlarımı topuz,yaptırana dek,ama anneme berber yanlışlıkla kesti,uzar canım kökü bende değilmi? dedim bayram diye birşey demedi,ozaman mizampile vardı saçlar bügodelerle sarılır kocaman bir makinada saatlerce beklersin şimdiki gibi saçları yola yola fön yoktu,bayram sabahı önce annemle kardeşimle bayramlaştım,annem belli etmemeye çalışsada ben  babamızın yokluğundan burukluğunu hissedebiliyordum,sırayla komşularla bayramlaşmak için önce yan komşumuz kayserili kezban teyzelere gireceğim,ama kapıda çarpışmamız,onun elindeki bulaşık suyu dulu tasın üzerime dökülmesiyle ikimizin attığı çığlığa herkez geldi,lavobası bozulmuş oda bulaşık suyunu bahçeye dökmeye gidiyormuş,ben hıçkırarak ağlarken kezban teyze gadalarını alırım ağlama şimdi gider sana yeni alırım diyor,ben aynısından bulamassın biliyorsun ben bunu diktirdim derken,elazığlı sevim teyze kezban ellerin kırıla,çağanın bayramını haram ettin derken kızı tülin,annesini çekerek hahın işine karışma diyor,sivaslı melek teyze göz yaşlarımı silerken kurban olurum o göz yaşlarına ağlama kurban,diyor rizeli emine teyze uşağım haçan şimdi gider aynısından alurum da diye teselli ediyor evet ben birdaha o kıyafetimi giyemedim malesef,ama sonraları ben onların hepsinin taklitini yapıyordum onlarında çok hoşuna gidiyordu sanki bir tiyatro oyunu gibi,anıyoduk.', 'Hayatta neye özendiysem, utlaka bir aksilik olmuştur,pendikte oturduğumuz gecekondunun sahibi,makinist hasan amcanın tam,9 kiracısı vardı ko...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ozendigim-hersey-husran-olmustur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takılır aklıma (03 -Dönek)', 'takilir-aklima-03-donek-mehmet-coban-cr49f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir acı gerçek

Zayıfken ezilmişken

Delikanlı bir yürek

Büyüyüp kuvvetlenince

Sanki tam bir dönek

Unutur eskiden olanları

Unutur eski arkadaşlıkları

Unutur eski sevdalarını

Unutur eski kavgalarını

Bir dilim ekmek için

Koştuğu yıllarda 

İnsanlık ve umut için

Kavga verdiği yollarda

Eski arkadaşları

Eski kavgaları

Hala oralarda

Sorarım kendime

Kolay mı bu kadar

İnsan eski benliğine

Uzak kalır mı bu kadar

Dün savaş verdiği 

Tüm kutsal duygularıyla

Bu gün unutmuş kendini

Savaşır eski kavgasıyla

19.11.2005-İzmir', 'Bir acı gerçek Zayıfken ezilmişken Delikanlı bir yürek Büyüyüp kuvvetlenince Sanki tam bir dönek Unutur eskiden olanları Unutur eski arkadaş...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/takilir-aklima-03-donek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayri Bey', 'hayri-bey-ozkan-gonlum-1giq0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayri bey dostumuz 

Öyle iyi bir insan ki. 

Bu devirde az bulunan 

‘’Adam gibi adam’’ inan ki. 

Evleri huzur dolu 

Mutluluğu yerindedir. 

Eşine, çocuklarına düşkün 

Sevgisi derindedir. 

Eşi Aynur hanım 

Çocuklarına adamış ömrünü 

Gözü gibi bakar onlara 

Ayırmaz hiçbirini. 

Tomurcuk gül gibidir GÜLŞAH 

Güzelliği dillerde söylenir 

Sevgiyle candan bakar gözleri 

Kısmet olunca acep 

Kimleri yakar gözleri. 

Yakışıklı mı yakışıklı 

CANER abiyi sorarsanız 

Böyle oğul dostlar başına. 

Tam bir ’’beyefendidir’’ o 

Bakmayın siz genç yaşına. 

‘’HERGÜNER’’ ailesi için dostlarca 

Hep güzel şeyler söylenir. 

ALLAH sağlık, mutluluk versin 

Daha başka ne denir.', 'Hayri bey dostumuz  Öyle iyi bir insan ki.  Bu devirde az bulunan  ‘’Adam gibi adam’’ inan ki.  Evleri huzur dolu  Mutluluğu yerindedir.  Eş...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hayri-bey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takılır aklıma (04 -Alın teri)', 'takilir-aklima-04-alin-teri-mehmet-coban-b2t9d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Demişse ki peygamberi

Çalışanın tüm emeğini

Ver alnının teri kurumadan 

Demişse ki peygamberi

Haklının, yetimin, fakirin 

Yanında ol her zaman

Hakta bil kuvveti 

Bu hakkın daveti

Böyle bil böyle yaşa

Olma zulme zalime maşa

Ama gel gör ki, 

Olur, bunların tersi

Nedendi ve niçindi bilinmez

İmana döneklikten geçilmez

Çalıştırır yanında kardeşini

Vermez hiçbir zaman emeğini

Çok laf edene kapıyı gösterir

Gücüyle hep dersini verir

Yetimlerden haberi yoktur

Etrafında zengin dostları çoktur

Yapar dualarla âminlerle hoş sohbet

Gel de sen onun mürailiğine sabret

Konuşmaya gelince 

Mangalda kül bırakmaz

Bir gün olsun hak için

Zulmün karşısına çıkmaz

Kardeş olur zulümle zalimle

Süsler sözlerini riyakâr sözlerle

Dayanağı geçmişten gelen fetvalardır

Bilmez ki, o fetvaların dayanağı sultanlardır

Herhalde dün de bu günde 

Sanki olanlar yazılı bu kaderde

İnsanlığın düşüncesi yanlış yerde

Ne derse desin peygamber insanlığa

Deniyor hep beraber sultanım çok yaşa

Allah nifak, münafıklık diyor bu yaşayışa

19.11.2005-İzmir', 'Demişse ki peygamberi Çalışanın tüm emeğini Ver alnının teri kurumadan  Demişse ki peygamberi Haklının, yetimin, fakirin  Yanında ol her zam...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/takilir-aklima-04-alin-teri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Global Yutulma', 'global-yutulma-ayse-gul-z1dcq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Köşesiz bir dünyada

köşe kapmaca...

Yetmedi

köşeler Devlere...

GLOBAL BİR DÜNYA

................................. Devlerin MİDESİNDE...

005/İst.A.G.Nisan_ca', 'Köşesiz bir dünyada köşe kapmaca... Yetmedi köşeler Devlere... GLOBAL BİR DÜNYA ................................. Devlerin MİDESİNDE... 005/...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Gül']::text[], 8.5, '{"poet":"Ayşe Gül","poet_slug":"ayse-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/global-yutulma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hikmet Sanatı', 'hikmet-sanati-hikmet-uzun-1k466', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bin kez baksa da gözler,bir küçük hata bulamaz.

Bu ne sanat-ı hikmettir,devri deveran ediyor.

İsteyen arasın,senden gayrıyı kat''a bulamaz.

Vird olmuş ismin dillerde cevli cevelan ediyor.', 'Bin kez baksa da gözler,bir küçük hata bulamaz. Bu ne sanat-ı hikmettir,devri deveran ediyor. İsteyen arasın,senden gayrıyı kat''a bulamaz. V...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Uzun']::text[], 8.5, '{"poet":"Hikmet Uzun","poet_slug":"hikmet-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hikmet-sanati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar', 'yollar-muhsin-altintas-hmtcn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kavuşturan tek şeydir, sevenleri sevdiğine

Sevda yüklü, Umut yüklü, Neşe yüklüdür YOLLAR

Acımaz hiçbir zaman isan denen bizlere,

Sitem yüklü, İsyan yüklü, acı yüklüdür YOLLAR

Kimi zaman gözlerde akan yaş olur, 

Bazende kahkahalar onda can bulur,

Mart ayı gibidir değişir durur,

Sarı yüklü, mavi yüklü, Beyaz yüklüdür YOLLAR.

Anlaşılmaz bir bilmece çüzene aşk olsun,

Arayan aradığın hep yolda bulsun,

Acılar kederler biryana dursun,

Servet yüklü, araç yüklü, insan yüklüdür YOLLAR

Akıl almaz bir duygu, erişilmez düşünce

Şah damar kadar yakın ecel yollarda bize 

Kopamayız biz ondan, ağlasakta gülsekte,

Mantık yüklü, Fikir yüklü, İlim yüklüdür YOLLAR...

(Küçüklü büyüklü onlarca trafik kazası görmüş biri olarak 

bu şiirimi ''Türkiyede ve hatta dünyada Trafik kazasında 

hayatını kaybeden binlerce insana ithaf ediyorum.)', 'Kavuşturan tek şeydir, sevenleri sevdiğine Sevda yüklü, Umut yüklü, Neşe yüklüdür YOLLAR Acımaz hiçbir zaman isan denen bizlere, Sitem yüklü...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Altıntaş']::text[], 8.5, '{"poet":"Muhsin Altıntaş","poet_slug":"muhsin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yollar-79-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Yürek İster(serbest)', 'sevmek-yurek-i-ster-serbest-i-brahim-yavuz-bnaai', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimseye düşman olmadım

Zerresini bulaştırmadım yüreğime kinin

Gözümü kırpmadan bütün ömrümce

Üstüne üstüne gittim sevginin', 'Kimseye düşman olmadım Zerresini bulaştırmadım yüreğime kinin Gözümü kırpmadan bütün ömrümce Üstüne üstüne gittim sevginin...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz']::text[], 8.5, '{"poet":"İbrahim Yavuz","poet_slug":"i-brahim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevmek-yurek-ister-serbest-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ve Düş', 'ask-ve-dus-haydar-okur-gwrt4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bitmez geleceğe dair hayaller ve düşler

Bitmez yaşama dair şu inişler ve yokuşlar

Ya çıkar bir düzlüğe basamaklar aşk olur

Ya iner derinlere bin bir renkli düş olur', 'Bitmez geleceğe dair hayaller ve düşler Bitmez yaşama dair şu inişler ve yokuşlar Ya çıkar bir düzlüğe basamaklar aşk olur Ya iner derinlere...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-ve-dus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilara', 'dilara-haydar-okur-tm3dj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşlere damlayan periler gibi

İnceden süzülür kalbe Dilara

Limansız denizde yıldız ay gibi

Adını söyletir ufka Dilara

Rengi gök mavisi meltemdir dili

Ateş olur bazen eser Dilara

Dilara düşlerin gökçek perisi

İsmi hecelense bin dil Dilara

Leylalar, Aslılar, Arzular gibi

Aşkı al kor olur yanar Dilara

Ruhundan akışır mavice sevgi

Açar binbir çiçek gonca Dilara

SENİ SORDUM AYA, YILDIZLARI GÖSTERDİ

YILDIZLARA SORDUM O PERİDİR DEDİLER

KALEME DAYANDIM DİLE YASLANDIM

ONLAR DA DİLARASIZ ŞİİR OLMAZ DEDİLER', 'Düşlere damlayan periler gibi İnceden süzülür kalbe Dilara Limansız denizde yıldız ay gibi Adını söyletir ufka Dilara Rengi gök mavisi melte...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dilara-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız Çiçeği Sevda', 'yildiz-cicegi-sevda-haydar-okur-emfjg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzanır ellerin, el uzatırım. 

Uzatırım da 

Yakar beni alev alev düşlerim 

Gel, gel eden çağrılara kanatlanırım 

Kanatlanırım da... 

Ürkütür beni unutuluşlar.. 

Uçamam 

Masmavi gönlümde goncalanır 

Arzular renk renk, biçim biçim... 

Beklemelerde billurlaşır duygular 

Sevdiğim bengisu akışlı, bin gözeli pınar 

Dizelere nakışlarım, şeftali çiçeği sevdamı 

Örülür gergefinde zamanın  nakış nakış

Oylum oylum bakışlara, umutlanırım 

Ve beklerim 

Beklerim, yıldız çiçeği sevdamı 

KÖMEN', 'Uzanır ellerin, el uzatırım.  Uzatırım da  Yakar beni alev alev düşlerim  Gel, gel eden çağrılara kanatlanırım  Kanatlanırım da...  Ürkütür ...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yildiz-cicegi-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulur Şafak Ninnileri', 'unutulur-safak-ninnileri-haydar-okur-crsko', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şafak uykularında bir ninnidir

Mavi salkımlı düşlerim

Bıçak sırtında gezinirken yeniden 

Kozasını çatlatır en soylu umutlarım

Ufkumun burçlarında masmavi düşlerim

Bir alev kuşatmasında devinir için için

Dalgalanır yalımı, sindikçe siner derinliklere

Çeker içine çavdar kılçığı gibi aşkına bir ateşin

Gün başlarken bir evecenlik çöker yollara

Yollar yar, yollar ağyar, yollar çetin

Unutulur gecelerde kalan ninniler

Şafağın mavisinde günaydınlarla kendime gelirim', 'Şafak uykularında bir ninnidir Mavi salkımlı düşlerim Bıçak sırtında gezinirken yeniden  Kozasını çatlatır en soylu umutlarım Ufkumun burçla...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutulur-safak-ninnileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Çocuğu', 'i-stanbul-cocugu-yasemin-sezer-tulgar-bxyjy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu şehrin 

yar sarnıçlarından 

dilek çeşmesine süzülen 

orman özlemli 

beton çocuğum 

ser felaketlerinden 

ak sayfalara yazılan 

medeniyet yontusu 

hamur çocuğum 

kıtalara sabah/akşam 

sularla düğümlenen 

seferi topuklu 

parfüm çocuğum 

bu şehrin 

pejmür bataktan 

ak kardelen gülümseyen 

tekil kalabalıklarının 

o yalnız çocuğuyum 

ben 

hası kalmamışların 

tek tas çorbasından içenlerin 

yedi cet İstanbul''um

ki hala çocuğum...

18 09 2005', 'bu şehrin  yar sarnıçlarından  dilek çeşmesine süzülen  orman özlemli  beton çocuğum  ser felaketlerinden  ak sayfalara yazılan  medeniyet y...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/istanbul-cocugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürekle Sevmek', 'yurekle-sevmek-celal-topo-tdqx4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevmek zamansız esen bir rüzgardır

Azgın bir dalgadır yürek kıyılarına vuran

Korkunun uçurumunda

Düşmeyi bekleyen heyacandır

Sevmek

Bir çiy tanesidir kirpiklerde

Yapışıp ta düşmeyen

Yürek yürek gezen

Bir heves bir arzu değil

Sevmek

Bir ömür tek bir gönülde

Yaban ellerden uzak

Solmayı bekleyen kır çiçeğidir...



16 / 11 / 2005   Antalya', 'Sevmek zamansız esen bir rüzgardır Azgın bir dalgadır yürek kıyılarına vuran Korkunun uçurumunda Düşmeyi bekleyen heyacandır Sevmek Bir çiy ...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yurekle-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erdek İskelesinde', 'erdek-i-skelesinde-haydar-okur-03io1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Erdek iskelesindeyim, seni bekliyorum

Gün batımı Marmara

Ufuk al kor olmuş alev alev yanıyor

Ve iskelede ben yanıyorum...

Ah! bir bilebilsen

Bir duyabilsen içimden geçen pusatlanmış umutları

Ya gelmezse, ya tutmazsa 

Ellerine susayan ellerimi diyorum.

Erdek iskelesindeyim, seni bekliyorum

Dalgalar küçülerek tükeniyor önümde

Ilık bir rüzgar esiyor Marmaradan

Ve yolcular birer birer çekiliyor

Yapayalnız kalıyorum/ Sen yoksun

Erdek iskelesinde ben, seni bekliyorum

Martılar da kanat çırparak uzaklaşıyor benden/

Bir özlemdir ki sorma gitsin

Alev alev içime doluyor

Ve seni soruyorum her geçenden

Erdek iskelesinde seni bekliyorum

Delişmen bir bun çöküyor içimin derinliklerine

Gözlerim bulutlanıyor

Ellerimce titrek bir bekleme duvarı oluyorum

Ne olur gel artık, tut beni ellerimden

Erdek iskelesinde seni bekliyorum

Güneşin en son alevini de yutuyor Marmara

Son yolcu da uzaklaştı bak, iskeleden

Martılar yuvaya çekildi,

Suskunlaştı Erdek, uykuya dalıp gitti insanlar

Ben hala seni bekliyorum

Erdek iskelesinde bir garip yolcu

Aya, yıldızlara, Marmaraya sorar seni

Bir suskun çığlıktır içinde yankılanan

Düşer umutsuzluk girdabına

Ve günün ilk ışığında gözden kaybolur', 'Erdek iskelesindeyim, seni bekliyorum Gün batımı Marmara Ufuk al kor olmuş alev alev yanıyor Ve iskelede ben yanıyorum... Ah! bir bilebilsen...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/erdek-iskelesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Rapsodisi', 'yalnizlik-rapsodisi-atilla-guler-8o5va', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I

bezgin ayak sesleri 

bir adamın

boşluklara düşmüş 

çınladı ıssız sokakta

ayazında gecenin

miyavladı kara bir kedi bir diğerine

gerilmiş ayakları üzerinde

hazır parçalamaya/kan revan 

bir köpek

öfkeli adamakıllı

havladı ardından hızla geçen bir arabanın

kayboldu sesi tekerlerin arasında

bir bebek

uyurken sıcacık odasında

yapayalnız...mışıl mışıl

derin düşler diyarında

başladı ağlamaya aniden

koştu sessiz adımlarla uyku mahmuru anne

kucağına alıp bastırdı kendi sıcağına…göğsüne

sardı annesini benliğinde bebek…sustu

kalp atışlarının melodisinde dinledi sessizliğin melodisini

...sustu

II

ıssız sokaktaki yalnız adam

bağırdı/haykırdı geceye öfkesini

ağladı katıla katıla

kendine sarıldı yorgun...bitkin...üşümüşçesine...

gece çalmaya başladı

tükenmişliğinde adamın

o bildik melodiyi(!) 

yalnızlık rapsodisini

III

yırtık bir defter sayfası

havalandı yerden

kargacık burgacık bir şeyler yazılı üzerinde

uçtu yumuşacık...kayboldu bilinmezlerde...

gözlerine adamın/doluştu toz parçacıkları iğneden 

kızardı...sulandı...bir damla yaş süzüldü

kapadı göz kapaklarını rahatsız

dayanamayıp acısına

dilinde o melodi/hafif bir titremeyle

sallanmaya başladı usulca

bir sola...bir sağa

sola...sağa

dönmeye başladı olduğu yerde sonra

yavaş alabildiğine

kendinden geçmiş

kulağında sarhoş edici tınısı üflenen neyin

bir semazen gibi

göğe uzattı ellerini

çekti kopardı bir yıldızı yerinden

bırakıverdi onu sonra

alev alev...yangınlar içinde elleri

bir kadına dönüştü yıldız

yaklaştı adama…usulca

gözlerinde tüm dişiliği...sımsıcak sardı adamı

kolları arasına

kıvrak bedenini sardı adam kadının

yüreğine koydu sıcağını...inceliğini

iyiden iyiye! 

dans etmeye koyuldular...doyumsuz sevilerle

bir başka yıldız...aktı...düşüverdi

yakınlarda bir yere

bir başka adam belirdi düştüğü yerde yıldızın

kadından ayırdı kollarını yalnızın

öfkeli...tehdit dolu şimşek şimşek gözleri

aldı götürdü kadını

gecenin kapkara yorganında/ulaşılmazlara

yalnız...kolları kendine sarılı

kulağında/tükenmişliğine çağlayan o bildik melodi

...nota nota

sürdürdü dansını...daha önce hiç yaşamadığınca

alabildiğine uzak gözlerden

kollarını açtı her iki yanına

yalnızlık rapsodisini haykıran

üzerine gerilmiş

koyu lacivert gecede

döndü...döndü...döndü

IV

ceketini fırlattı önce

kravatı...gömleği...

attı herşeyi gelişigüzel

tek...tek

kalakaldı anadan üryan

duyarsız…soğuğa karşı,

yandı...tutuştu birden

koşma istemiyle dopdolu

...koştu…koştu...koştu

...yorulmaksızın

sahip olduğu olanca hızı bacaklarında

koştu kendi seçtiği yöne

bir iki damla yağmur çiseledi ardından adamın

ışımaya döndü gün

döküldü son notaları rapsodinin

dipsiz bir sessizlik çukuruna düştü dünya

kendini denize bıraktı adam...masmavi

her kulaçta sıçrayan su damlalarında

yepyeni bir melodi çalmaya geldi gün

şehrin üstüne bestelenmiş...kalabalığın karmaşasında çağlayan

çılgın bir senfoni', 'I bezgin ayak sesleri  bir adamın boşluklara düşmüş  çınladı ıssız sokakta ayazında gecenin miyavladı kara bir kedi bir diğerine gerilmiş ay...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":101,"source_url":"https://www.antoloji.com/yalnizlik-rapsodisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar', 'cocuklar-savas-dincbas-gfnfh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'çocuklar,masum yüzler

onları çok seviyorum

bir de sokakta

ciyak ciyak bağırmasalar

düşüncelerimi dağıtmasalar

hele sevgi adına

bir şeyler yazmak üzereyken

analarını

camdan,kapıdan bağırtmasalar...', 'çocuklar,masum yüzler onları çok seviyorum bir de sokakta ciyak ciyak bağırmasalar düşüncelerimi dağıtmasalar hele sevgi adına bir şeyler ya...', ARRAY['Türk Edebiyatı','Şiir','Savaş Dinçbaş']::text[], 8.5, '{"poet":"Savaş Dinçbaş","poet_slug":"savas-dincbas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cocuklar-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haydi İşin İş', 'haydi-i-sin-i-s-haydar-okur-02up0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Barışık akan iki ırmak 

Biri deli dolu, coşkun mu coşkun

Ya öteki, dingin, durgun ve suskun

Merhaba, nasılsın 

Ben iyi, ya sen

Ben de iyiyim

Belli ki mutlusun

Ah dost!   coşkunluğum yanıltmasın 

Şu çağlayanca akışım 

Nedendir bilirmisin

Mutluluğu denizlere 

Bir an önce ulaşmak için

Sus! itiraz istemem

Yoksa! ...

Ağzını bir güzel kilitlerim', 'Barışık akan iki ırmak  Biri deli dolu, coşkun mu coşkun Ya öteki, dingin, durgun ve suskun Merhaba, nasılsın  Ben iyi, ya sen Ben de iyiyim...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/haydi-isin-is-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KörDÜĞÜM', 'kordugum-tugba-yuksel-bmh9x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ucu yoktu seni sevmemin,

Akıllara durgunluktu seni bekleyişim! 

Yüreğimde acıydın artık olmayacağını bildiğim.

Sevmek seni özlemekti çoğu kez,

Kimi zaman korktuğum bi dönme dolaptın..

Bazen ezberleyemediğim bi şarkı..

Belkide tadını hala alamadığım bir yemek

Zordu senle geçen yıllar

Bir ömürdü seninle geçen günler,

Kördüğümdü bağlanan ipler

Çözülemeyen problemler...

Sonu yoktu biliyodum

Sadece seni kaybediyodum!', 'Ucu yoktu seni sevmemin, Akıllara durgunluktu seni bekleyişim!  Yüreğimde acıydın artık olmayacağını bildiğim. Sevmek seni özlemekti çoğu ke...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Yüksel']::text[], 8.5, '{"poet":"Tuğba Yüksel","poet_slug":"tugba-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kordugum-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben hayata yenik tüştüm', 'ben-hayata-yenik-tustum-durmus-karakus-mfpum', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Küçük yaştan beridir hep,

Dert çekerek büyümüştüm,

Ne sevdaya ne de aşka,

Ben hayata yenik düştüm.

Önce kolum sonra elim,

Kırık dökük gönül telim,

Genç yaşım da ondan kelim,

Ben hayata yenik düştüm.

Onlarca iz yüzlerim de,

Sızılar var dizlerim de,

Görmez oldu gözlerim de,

Ben hayata yenik düştüm.

Sanma aklım az noksandı,

Tehlikesi hiç yok sandı,

Bir gol yedim tam doksan dı,

Ben hayata yenik düştüm.', 'Küçük yaştan beridir hep, Dert çekerek büyümüştüm, Ne sevdaya ne de aşka, Ben hayata yenik düştüm. Önce kolum sonra elim, Kırık dökük gönül ...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Karakuş']::text[], 8.5, '{"poet":"Durmuş Karakuş","poet_slug":"durmus-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-hayata-yenik-tustum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesiniz', 'nerdesiniz-celal-topo-o5sch', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir çığlık düştü yüreğime ansızın

Karanlığın dudaklarından kopup ta gelen

Nasıl titriyorum bir bilseniz

Gecenin soğuk avuçlarında

Yalnızlığın koynunda ısıtıyorum nefesimi

Ömrümün son demi

Nerdesiniz dostlar nerdesiniz? 

Ceplerim sevda külleriyle dolu

Ellerim hasret yanığı

Şarkılar dudaklarımda kızıl kan

Acılara düğümlüyorum gidişleri

Yılların verdiği bir özlem var

Hiç gelmez oldu sesiniz

Nerdesiniz dostlar nerdesiniz....? 



16 / 11 / 2005   Antalya', 'Bir çığlık düştü yüreğime ansızın Karanlığın dudaklarından kopup ta gelen Nasıl titriyorum bir bilseniz Gecenin soğuk avuçlarında Yalnızlığı...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/nerdesiniz-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tınmıyorum', 'tinmiyorum-haydar-okur-y7y2q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğimin içinde kor alev bir korku var

Dört bir yanım oyma mermer afrodit

Halime güler oldu baharlar, yazlar

Tınmıyorum kimseyi ve yaşamı

Nasıl olsa ocunda ölüm var', 'Yüreğimin içinde kor alev bir korku var Dört bir yanım oyma mermer afrodit Halime güler oldu baharlar, yazlar Tınmıyorum kimseyi ve yaşamı N...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tinmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güven Bana', 'guven-bana-seyfettin-bilal-ozluk-uq9c5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şüphem yok sevginden

Olmadı olmayacakta

Kendime güveniyorum sana güvendiğim kadar

Ama sen bana güvenmiyorsun.

Tutacağım ellerini diyorum

Ama tutmam diyorsun

Canım deyip içime çekip sana sarılıyorum diyorum

Ama ben sarılmam diyorsun.

İçimde ne gururum olur ne kinim

Asla sana sözüm olmaz

Tutmasanda ellerimi sarılmasanda bana

Belli etmem gözümden içime dökülen yaşları

Affeder mi yüreğim senin beni sevdiğin gibi

Benim seni sevmemi...', 'Şüphem yok sevginden Olmadı olmayacakta Kendime güveniyorum sana güvendiğim kadar Ama sen bana güvenmiyorsun. Tutacağım ellerini diyorum Ama...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/guven-bana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçeğini Bulmak Üzeresin', 'cicegini-bulmak-uzeresin-haydar-okur-ageqa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Fırtınalar sonrası yüreğimin güneşinde

Sen iyiliksin, sen güzellik, sen sevgi

İçimde coşkunca akan ses ırmağım

Korku duvarlarının ötesinde

Bir koşudur başlıyor uzun mu uzun 

Hazır ol  ey yüreğim

Çiçeğin bulmak üzeresin', 'Fırtınalar sonrası yüreğimin güneşinde Sen iyiliksin, sen güzellik, sen sevgi İçimde coşkunca akan ses ırmağım Korku duvarlarının ötesinde B...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cicegini-bulmak-uzeresin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güveniyorum Seni', 'guveniyorum-seni-seyfettin-bilal-ozluk-bmaed', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayat müşterekse

Al canım senin olsun,

Sevgi paylaşmaksa

Senin sevgin bana

Benim yüreğim sana yeter.

Uzansak sahile

Tutuşsak el ele

Güç yeter mi bu sevgiye

İçimizden çıkarıp atmaya

Kopmaz bu yürekler

Senin sevgin olduğu sürece.

İnanıyorum sevgine

Kendimin var olduğu kadar

Çıkar beynindeki yontukları

İçinde kalmasın dürtüler

Güven bana

Güveniyorum seni...', 'Hayat müşterekse Al canım senin olsun, Sevgi paylaşmaksa Senin sevgin bana Benim yüreğim sana yeter. Uzansak sahile Tutuşsak el ele Güç yete...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/guveniyorum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göç Zamanı mı', 'goc-zamani-mi-haydar-okur-pcbww', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızım susuz kaldım

 Şu kurşuni bozkırda

  Bir damlacık su yağmur

 Uğramaz mı bu yurda

 Göç tayını tutmak gerek

 Bir dost olusun kalmadıysa

 Yüreği taşımalı artık suskunca

Adı bilinmedik bir diyara', 'Yalnızım susuz kaldım  Şu kurşuni bozkırda   Bir damlacık su yağmur  Uğramaz mı bu yurda  Göç tayını tutmak gerek  Bir dost olusun kalmadıys...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/goc-zamani-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Y/önünde', 'ask-y-onunde-yasemin-sezer-tulgar-2z49k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Terkedebildiğimiz şiirlerimiz kadarken

Yüzümüzün acısı ki halen gülümseyebilen

Gücü barajlardaki sulardan bekleyenlere 

Akar aynanın şeffaf sorgusu

Mum titremelerinden fısıldar

Karanlık odaların sırnaşık korkusu

Dökülür yırttığı duvar sıvalarından

Vazgeçilmişlerin aşk kokusu

Hadi uyan diyen patileri pembe kedinin

Başucundan içtiği bir kaç damla sudur

Sabaha ayar umuduyla beklettiğin bardağın

Dibine vurmuş dolgusu

İnanç ile devinen pembe yüzünün

Yansımaları doğumundan öte ödünde

Tevekkül giysisinden çıplak

Dans’a dönüyor aşk y/önünde

19.11.05', 'Terkedebildiğimiz şiirlerimiz kadarken Yüzümüzün acısı ki halen gülümseyebilen Gücü barajlardaki sulardan bekleyenlere  Akar aynanın şeffaf ...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-y-onunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alevi İçimdedir Sevinin', 'alevi-i-cimdedir-sevinin-haydar-okur-55ys4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adımlarım ışık ışık bir aşka doğru

Açılır yollara küskün yüreğim

Güzelliği gök mavi sevdaya değer

İçimi kuşatan Aleve doğru

Dokunur telime mızrabı aşkın

Sarar benliğimi gökçe bir Alev

Dalgalar üstünde sallantısının 

Varmıdır benzeri esrikliğimin', 'Adımlarım ışık ışık bir aşka doğru Açılır yollara küskün yüreğim Güzelliği gök mavi sevdaya değer İçimi kuşatan Aleve doğru Dokunur telime m...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/alevi-icimdedir-sevinin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paslı Ümitlerim', 'pasli-umitlerim-selda-ozturkmen-poqhf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim unutmaya vaktim yok...

Titrerim yorgan döşek.

Küskün çiçeklerim,açmaz nevbaharda.

Yok mecalim yıllara meydan okumaya.

Benim beklemeye vaktim yok...

Hapsedilmiş buseler böler düşlerimi.

Ayrılığın kısır toprağında,

Saklarım tek perdelik aşkımın küllerini.

Benim dayanmaya gücüm yok...

Elemimdir yokluğun.

Paslıdır ümitlerim,saklanır bakışlarda.

Sökülmez kelepçeleri dilimin,

Anahtarı olmayınca.

Benim ağlamaya vaktim yok...

Sessizdir, yürekte çığlıklarım.

İçerim gece gündüz ekşimsi tebessümleri,

Yakama takarım, broş misali hüzünlerimi.

Ey yar! 

Siyahtır şu ömrüm.

Sense, ona düşen tek beyaz.

Silmeye gerek yok...

Can katsın dünyama biraz...

(18.11.2005)', 'Benim unutmaya vaktim yok... Titrerim yorgan döşek. Küskün çiçeklerim,açmaz nevbaharda. Yok mecalim yıllara meydan okumaya. Benim beklemeye ...', ARRAY['Türk Edebiyatı','Şiir','Selda Öztürkmen']::text[], 8.5, '{"poet":"Selda Öztürkmen","poet_slug":"selda-ozturkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/pasli-umitlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alev Alev Yak Beni', 'alev-alev-yak-beni-haydar-okur-62jie', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülüşünde o ateşten dudaklar

Gönül kazanında sevda kaynatır

Sessiz bir şarkıdır Işıkkuşları

Dumansız şiirler yazdırır alev

Yakar alev alev, yandırır alev

Aşkı küllendirir kandırır alev

Ateşi bitimsiz bir sonsuz şiir

Yazmakla tükenmez, yakar kor alev

Yanağına vurur al al renkleri

Yalımı yürekten savrulur alev

Sevdayı bir bakışla kondurur alev

Yandım alev, yaktın alev, yak alev

Bütün şiirlerim ona adaklı

Magması içinde bir hardır alev

Susuşu öldüren işvedir onun

Dumansız bir ateşle konuşur alev

Aman alev, canan alev, can alev

Iğlım ığlım erit beni yak alev

Gökçe gözler sevdasının dilidir

Yalımı bin körük estirir alev

Allah nice güzellikler yaratmış

Aleve özenmiş nurundan katmış

Kül et beni, öldür beni göm beni

Yanar gönül, yanar yürek, yak alev

KÖMEN', 'Gülüşünde o ateşten dudaklar Gönül kazanında sevda kaynatır Sessiz bir şarkıdır Işıkkuşları Dumansız şiirler yazdırır alev Yakar alev alev, ...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/alev-alev-yak-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alev Alev', 'alev-alev-haydar-okur-uhseq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağışmaya görün sevdasını alevin 

Laleler kıskanır güller tutuşur

Ekseninden vuran yalımlarının

Vezninde var olur gönlü alevin

Alkımlanır güneş göksu bağrında

Lebleri akkordur dili alevin

Esrikliği yaşam verir acuna

Vurgun yüreklerde yanan alevin

Suya özlem duyan sevdalıların 

Açın bakın yüreğinde alev var

Canlı cansız bütün nesnelerin 

İçlerinde yanan birer alev var', 'Ağışmaya görün sevdasını alevin  Laleler kıskanır güller tutuşur Ekseninden vuran yalımlarının Vezninde var olur gönlü alevin Alkımlanır gün...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/alev-alev-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gamzeli Nakışları Düşün', 'gamzeli-nakislari-dusun-haydar-okur-g78m8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzanır toprağa özlemle titreşen yorgunluğumuz 

Yükselen dallarının altında günlerin 

Ne ağır yükleri ve nasıl çekmiş bu omuz 

Nasıl da karanlıklara sokmuş beni, bu ölümcül hüzün

Yeniden yaşam kattı ve aldı bulunmaz yerini 

Düşünen duyguların en güzeli ve en derini 

Kızaran gölgeli yaz günlerinde 

Sararan umutları ve düşleri 

Baharıyla dolduruverdi yüzün

Ben ki yeniden açılan yaşamın ak defterine 

Seni yazdım, yalnız seni nefes almak yerine 

Kanımın kırmızı mermerlerine ığlım ığlım akışınla 

Günlerce işlediğim gamzeli nakışlarını düşün', 'Uzanır toprağa özlemle titreşen yorgunluğumuz  Yükselen dallarının altında günlerin  Ne ağır yükleri ve nasıl çekmiş bu omuz  Nasıl da karan...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gamzeli-nakislari-dusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Silüet', 'siluet-seyfettin-bilal-ozluk-5nlpp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yürüyorum boş sokakta

Hafif rüzgarla yağmur, ıslak saçıma düşüyor

Aklımda sen varsın

Üşüyorum...

Sendeliyorum ayağıma takılan taşla

Yalpalıyorum tekrar yürüyorum

Gitmeliyim uzaklara

Ürperiyorum...

Az kaldı geliyorum evime

Yürüyorum hala sokakta

Kol kola iki sevgili görüyorum

Düşlüyorum...

Geldim kapıya arıyorum anahtarı bulamıyorum

Anahtar elimdeymiş boşuna ceplerimi karıştırıyorum

Bir kedi miyavlıyor

Gülümsüyorum...

Aldım duşumu uzandım yatağıma

Pencereden ışık yansıyor

Duvarda sanki senin silüetin yansıyor

Seyrediyorum...

Boş yatağımda yine yalnızım

Üşümüyorum, ürpermiyorum

Seni düşlüyorum ve gülümsüyorum

Çünki SENİ SEVİYORUM...', 'Yürüyorum boş sokakta Hafif rüzgarla yağmur, ıslak saçıma düşüyor Aklımda sen varsın Üşüyorum... Sendeliyorum ayağıma takılan taşla Yalpalıy...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/siluet-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel gayrı', 'gel-gayri-durmus-karakus-jz7ig', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne köyün köy senin ne şehrin şehir,

Mahalle cadde si  sokağı ayrı.

Hasretin içimde keskin bir zehir,

Bitir şu gurbeti bitir gel gayrı. 

Hasretin ok gibi saplı bağrımda,

İlaç merhem kar etmiyor ağrımda,

Sana anla sana bütün çağrımda,

Bitir şu gurbeti bitir gel gayrı. 

Ey deli kısrağım tayım arsızım, 

Kanser etti beni bendeki sızın,

Ecel can almaya gelir ansızın,

Bitir şu gurbeti bitir gel gayrı.', 'Ne köyün köy senin ne şehrin şehir, Mahalle cadde si  sokağı ayrı. Hasretin içimde keskin bir zehir, Bitir şu gurbeti bitir gel gayrı.  Hasr...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Karakuş']::text[], 8.5, '{"poet":"Durmuş Karakuş","poet_slug":"durmus-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-gayri-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devenin Belini Çökerten Son Saman Çöpü', 'devenin-belini-cokerten-son-saman-copu-erdinc-ozdemir-imeek', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çökertince belini son saman çöpü

Şaşırmadı

Anlamaya çalıştı

Birden

Tutkallaşan düşüncelerinde

Tutkallaşan görüntüler oluştu

Sokakların kralı

Harita yüzlü genç bir kaptanı gördü

Denizlere açılmayan, kendisi gibi

Oysa,

Sözcükleri yaralayan

Yaralı sözcüklerden

Kendine hayatlar kuranlardan değildi.

Beraber ve solo şarkılarda

Birbirini tanımayanlar gibi yaşamıştı hayatı.

''''Siz sıradakiler'''' denmişti hep ona,

''''Yaşamımızda münhal bir pozisyon olmadığı için

Lütfen bekleyiniz'''' denmişti.

Acısı beyniyle tokalaştığında

Yere çöktü

Rüzgarın havaya uçurduğu

Son saman çöpünü gördü.

Deve kimseye kin tutmadı

Saman da.', 'Çökertince belini son saman çöpü Şaşırmadı Anlamaya çalıştı Birden Tutkallaşan düşüncelerinde Tutkallaşan görüntüler oluştu Sokakların kralı...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Özdemir']::text[], 8.5, '{"poet":"Erdinç Özdemir","poet_slug":"erdinc-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/devenin-belini-cokerten-son-saman-copu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Od Yüreğe Düşünce', 'od-yurege-dusunce-haydar-okur-3rho9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşünce cananın odu yüreğe 

Masmavi alevi sarar her yanı

Kıvılcımlar ağıştıkça havaya 

Yıldız şölenice başlar bir anı

Gönül ocağına çıngısı düştü

Külü alevlendi çiçeklendi nar

Kızıl saçlarına güneş vurdukça 

Tutşur gündüzler geceler yanar

Ateş bastırmasın gönlü bi kere

İçin için yanar alkor bir alev

Gökçe düşler yağmurlandıkça

Büyülenir seven bengileşir yar 

Bir tebessüm ki bin ömre bedel 

Baharda alevdir, gökkuşağı yar

İpek tenli okşayan bir bakışla 

Yandıkça mut veren güzelliği var

KÖMEN', 'Düşünce cananın odu yüreğe  Masmavi alevi sarar her yanı Kıvılcımlar ağıştıkça havaya  Yıldız şölenice başlar bir anı Gönül ocağına çıngısı ...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/od-yurege-dusunce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arar Gözlerim', 'arar-gozlerim-haydar-okur-xyp4x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir bahar muştusu arar gözlerim

Gönül bahçesinde gül bana yeter

Mavi duyguların derinliğince

Yitik ufuklara dalar gözlerim

Onu sorar, arar yürek yangınım

Küllenmiş anılar bağı yaşamın

Anıları koysam ucu ucuna

Bitmiyor arayış dalar gözlerim

Uçuşsa kelebek, kuşlar böcekler

Uzaklaşır gider beden öteye

Depreşir içimde bir ince sızı

Dinmez umutlara dalar gözlerim

Bu arayış bitmez, bitmez özleyiş

Çıkagelir diye her an bekleyiş

Çiçekler aşk bekler, aşk ile açış

AAçılmaz bahtıma dalar gözlerim

Nice sevdalara aşk iksiriyim

Benliğimde tek sen ile diriyim

Yaratn a aşkın coşkun seliyim

Taşsam da aranır dalar gözlerim', 'Bir bahar muştusu arar gözlerim Gönül bahçesinde gül bana yeter Mavi duyguların derinliğince Yitik ufuklara dalar gözlerim Onu sorar, arar y...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/arar-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Sıcaklığı', 'dost-sicakligi-haydar-okur-9z0eb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hemen hergün bir ileti alacağım 

Can dostu ile kavlimiz bu 

Ellerimde çiçekler açacak 

En güzellerinden 

Ve bunlardan dostluk demeti yapıp 

Çiçekçe sözcüklerle 

Bir ak güvercin kanadında

Dosta göndereceğim 

Günlerim erinçlenecek 

Günlerim mutlanacak 

Sevgim selamım 

Sevgi kelebeklerine renk verecek

Gurbetm gönüllerimizde 

Ve sis bastıran ufuklarımızda 

Her gün Gökkuşağı olacağız 

Dost demişim bir kez, dahası varmı 

Kara saçlarıma ak düşürse de 

Can dost demişim yüreğimce 

Can uçsa da bedenden 

Yine dostumla bir olacağız 

Ruhum onunla birlikte yaşarken 

Dualarla konuşacağız

KÖMEN', 'Hemen hergün bir ileti alacağım  Can dostu ile kavlimiz bu  Ellerimde çiçekler açacak  En güzellerinden  Ve bunlardan dostluk demeti yapıp  ...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/dost-sicakligi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılıkları Sayıklamanın Zamanı mı', 'ayriliklari-sayiklamanin-zamani-mi-haydar-okur-uqcmo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabahın kuşlar korosunu dinliyorum

Bir çağlayanın uğultusu yanıbaşımda

Müthiç bir uçurum sesi

Gecelerin burukluğundan kalma

Yeni sabahlarda yeller sel oluyor

Boşluk, genişlik, uzaklık...

Ürperti diyorum

Durup beklemek... 

Hep beklemek diyorum 

Binektaşları gibi bir köşede...

Yokoluş diyorum sonra

İlla da bir şey mi demeliyim? 

Ya da zamanı mı şimdi

Ayrılıkları sayıklamanın', 'Sabahın kuşlar korosunu dinliyorum Bir çağlayanın uğultusu yanıbaşımda Müthiç bir uçurum sesi Gecelerin burukluğundan kalma Yeni sabahlarda ...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ayriliklari-sayiklamanin-zamani-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burda Bitsin', 'burda-bitsin-ahmet-ozyilmaz-zw8p1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gönlümü gergefe koyup delme

yüze ayrılığı vurda bitsin

yarana merhemim diye gelme

gözlerimden uzak durda bitsin

sen bilmezsin bu aşka devayı

boş havanda döversin havayı

azrail kirpiğinin alayı

eceli bugüne kurda bitsin

gün göstermedin, her günüm gece

seni okudum da hece hece

bilinmedi sendeki bilmece

vadesi yok, bu aşk burda bitsin.

19 Kasım 2005

AFYON KARAHİSAR', 'gönlümü gergefe koyup delme yüze ayrılığı vurda bitsin yarana merhemim diye gelme gözlerimden uzak durda bitsin sen bilmezsin bu aşka devayı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özyılmaz']::text[], 8.5, '{"poet":"Ahmet Özyılmaz","poet_slug":"ahmet-ozyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/burda-bitsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Yürek Oldu Grup', 'tek-yurek-oldu-grup-deli-mavi-7rg25', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'DELİ MAVİ SEVDALAR Grubunun 1 nci yaş gününü doldurmasından dolayı kutluyorum..Gerek Hatice hanımın ve gerekse yönetimdeki arkadaşlarımızın özverili çalışmaları sayesinde şiir ve şairler adına verimli çalışmaları yakinen izliyorum.Dileğim o ki onlu yıllarda yaş günlerini görürüz. 

Saygı ve selamlarımla.

İshak Özlü

******************************

Sevgili Şiir Dostları 

Bugün gerçekten çok güzel ve önemli bizim için çünkü sizlerle birlikte tam bir yaşına girdik ne mutlu ki bize sizler varsınız ve hep birlikteyiz 

Sn kurucumuz Hatice Ak Hanımefendiye bizi böyle güzel bir ortamda topladığı için buradan teşekkür ederim. 

Geçen sene bugün doğdu Deli Mavi Sevdalar 

Bugün bir yaşına girdi, doğum günümüz var 

Ne mutlu bize ki güzel dostluklar kurduk 

Mutluyuz, onurluyuz, burada sevdamız var... 

Feride Ömür

******************************

Bugün bizler için çok anlamlı ve güzel bir gün. Grubumuzun 1. kuruluşunu kutluyoruz bugün. Ne mutlu bizlere, böyle adı gibi güzel ve güzide bir grubun üyesiyiz. 

Bu vesileyle herkesi kutluyorum, tebrik ediyorum.) Nice güzel yıllarda birlikte paylaşımlarımızın sürmesini dilerim, gönülden gönüle. 

Saygıyla. 

Burhanettin Akdağ

******************************

Daha nice uzun yıllarda burda güzel şiirleri paylaşmak, okumak, dost ve güzel insanların yüreklerinden gelen sesi duymak,dinlemek, gerçekten çok güzel,bu bir yıllık süre içinde emeği geçen herkese çok teşekkür ederim.

Saygılarımla 

Adnan Şahin

******************************

Senden ayrı kaldım gülüm,özlemin yüreğimde. 

Arar gezerim gündüzde,karanlık gecelerde. 

Bir umut bildim sarıldım,teselli niyetiyle; 

Dostluğun mekanı olan,deli mavi sevdama. 

Ahmet Bektaş

******************************

Birgün,ansızın,bir davet geldi SEVDALAR ülkesinden. 

Bir MAVİ çaldım geceden ve sardım kalbimin kırılmış tarafına. 

Çıkardım iliklerimden yedek aşkı,bundan sonra mutluluk var 

Yanlız değilim bundan böyle,yanımda DELİ MAVİ SEVDALAR var... 

DOĞUM GÜNÜNÜZ KUTLU OLSUN 

RAMAZAN SAĞLAM

******************************

Gönül verdik,bağlandık biz sevdana 

Bir yıl değil,bin yıl gecsin istiyoruz. 

Sevgi yumağı kalplerdeki şiir sıcağına, 

Hergün gönlümüzdeki ateşi sunuyoruz.. 

Adnan ŞAHİN

******************************

NİCE YILLARA DELİ MAVİ SEVDALAR 

DOĞUM GÜNÜN KUTLU OLSUN 

NİCE YILLARA 

İYİKİ VARSIN

Dilek HOKKAÖMEROĞLU

******************************

Tebrik ediyoruz Sn. Ak, 

Böyle güzel bir grubu kurarak sanatın ve şiirin hizmetine sunduğunuz için. 

Nice yıllarda güzel paylaşımlar dileğimle kutluyorum sizi. 

Saygıyla. 

Burhanettin Akdağ

******************************

Deli Mavi Sevdalar grubunun 1.yaş yılını kutlar, gönül semanızın daima esenlikler, güzellikler, yeni sevdalar yağdırmasını dilerim.Muhabbetle kalın...

Veysel KOŞAR

******************************

Değerli Deli Mavi Sevdalılar, 

Sn kurucum Hatice Ak hanımefendiye, böyle güzel bir grupta, güzellikleri paylaşabilme şansını bizlere verdiği için teşekkür etmek isterim. 

Grubumuzun birinci yıldönümü nedeni ile sn Hatice Ak ve yönetimdeki arkadaşlarımı kutlar, nice yıllar bir arada olup, paylaşımlara devam edebilmeyi dilerim. 

Değerli üyelerimize, her konuda katılım ve destekleri için ayrıca teşekkür ederim. 

Mavi Dünyanız bir yaşında... hepimize kutlu olsun. 

Saygılar 

Hülya Ekmekçi

******************************

BU GURUBA DAVET EDİLDİĞİMDE SICACIKBİR KARŞILAMA OLDU 

HİÇ BEKLEMİYORDUM, BURASI AİLE GİBİ ŞİİR TADINDA ŞİİR ADINDA 

VE DELİ MAVİ SEVDALAR GERÇKDENDE BU BAŞKA BİR SEVDAALIŞILMIŞIN DIŞAINDA 

İYİKİ VARSINIZ HATİCE HANIM 

İYİKİ VARSINIZ 

BURHANNETTİN BEY 

İYİKİ VRSINIZ 

FERİDE HANIM 

VE DİĞER YÖNETİCELER 

DOĞUM GÜNÜNÜZ KUTLU OLSUN 

NİCE YILLARA 

NİCE ŞİİR PAYLAŞIMLARINA 

HEP BERABER,, 

SAYGILAR VE SEVGİLERİMLE 

DİLEK HOKKAÖMEROĞLU

******************************

Grubumuzun yeni yaşını kutlar, siz değerli dostlarla beraber Sn. Ak ve değerli grup yöneticileriyle daha nice paylaşımlrda birlikte olmak dileğiyle saygılarımı sunarım... 

Umut Bozkuş.

******************************

Serpilmişse yüreklere umutlar, 

Bulutlar bile sevinir,raks yapar. 

Kimine yağmur olur,kimine kar 

Bu öyle bir sevdaki kalplere akar. 

Adnan ŞAHİN

******************************

SEVGİLİ..DELİ MAVİ SEVDALAR..GURUBUNUN... 

ESKİ YAŞINI ŞUTLAR YANİ YAŞINI KUTLARIM...... :)))))

DAHA NİCE GÜZEL ŞİİR PAYLAŞIMINI BÖYLESİNE GÜZEL VE GÜÇLÜ KALEMİN ARASINDA....UZUN YILLAR.GEÇİRMEK ÜZERE SEVGİ VE SELAMMLAR....

BERRİN CİVGİN

******************************

ACİZ 

Bilemiyorum: 

Sözcükler mi? 

Ben mi acizim. 

Seni nasıl sevdiğimi, 

Sana anlatamıyorum... 

Deli mavi Sevdamı, 

Uykusuz gecelerimi; 

Susuyorum, 

Çaresiz! ... 

Kemal Doğular/Alanya

******************************

Hatice Hanim kutlarim ve nice güzel yillara gurup arkadaslariyla imza atmanizi dilerim.Yolunuz acik olsun....

Hatice ENER

******************************

DELI MAVI SEVDALAR HEP COSSUN 

YÜREKLER SEVGI HUZUR BULSUN 

GELIN HEP BERABER KUTLAYALIM 

DOGUM GÜNÜMÜZ KUTLU OLSUN

Fatma ÇAĞLAYAN

******************************

KUTLARIM...SEVGİNİN, DOSTLUĞUN, PAYLAŞIMIN YIL DÖNÜMÜNÜ...SAYGIYLA...

NURDAN ÜNSAL

******************************

DOĞUM GÜNÜNÜZ KUTLU OLSUN 

AK BİR GÜVERCİNLE BAŞLADINIZ YOLA 

AK GÜVERCİ''NİN SEVGİ BARIŞ ŞİİR,KANATLARINDA 

KONDU AK GÜVERCİN YİNE 

AK BİR DAĞ''A BİR ÖMÜR ALDILAR 

DEVAM ETTİLER YOLA 

NİCE UZUN ÖMÜRLER 

DELİ MAVİ SEVDALAR SANA 

SAYGILARIMLA 

AFFINIZA SIĞINARAK 

DOĞUM GÜNÜ ARMAĞANI 

KABUL BUYURURSANIZ 

SAYGILAR

DİLEK HOKKAÖMEROĞLU

******************************

Bunca güzel paylaşımlarla, dostlukla, sevgiyle bu güne gelen grubumuzu; kurucusu, yöneticiler ve üye arkadaşlarımız nezdinde kutluyorum. 

Nice yıllara 

Selam ve Sevgilerimle

Hatice BEDİROĞLU

******************************

Yıldönümü Nedeniyle Yüreğimden Dökülenler:

Var Mı Benden ''Mavi''si? 

Ömrümü adadım sana, görmem gayri kimseyi 

Delisiyim sevdaların, var mı benden ''mavi''si? 

Divaneyim avareyim, görmem başka kimseyi 

Delisiyim sevdaların, var mı benden ''mavi''si? 

Yüreğimi verdim sana, sevmem gayri kimseyi 

Aşkına oldum pervane, sundum sana maviyi 

Yoktur başkası gözümde, sende buldum sevgiyi 

Delisiyim sevdaların, var mı benden ''mavi''si? 

Yaşatacağım kalbimde, sana yaptım besteyi 

Aramam başka sevdayı, kıyaslamam kimseyi 

Gönlümde en güzel yerde, sende tattım sevmeyi 

Delisiyim sevdaların, var mı benden ''mavi''si? 

(Deli Mavi Sevdalar Grubunun 1. Kuruluş Yıldönümüne Atfen Yazılmıştır.)

(16.11.2005)

Burhanettin Akdağ

******************************

Bir davet sonucunda 

Ansızın girdim bu gruba 

Öyle bir girdin ki yaşantıma 

Eksikliğini hisseder oldum yokluğunda 

Deli mavi sevdalar grubuna 

Emeği geçen tüm dostlara 

Sevgilerimi sunuyorum 

Yaşanılacak tüm paylaşımlar adına... 

DOĞUM GÜNÜMÜZ KUTLU OLSUN DOSTLAR, PAYLAŞIMLARIMIZIN ARTARAK GRUBUMUZUN BÜYÜMESİ DİLEĞİYLE... 

SEVGİLERİMLE...

Şengül ACAR

******************************

Biraz gec yaziyorum ama 

GRUBUMUZUN BIRINCI YIL DÖNÜMÜ KUTLU OLSUN! 

Sidem GÜNGÖREN

******************************

Deli Mavi Sevdalar Grubanun 1.yıl dönümünü en içten dileklerimle kutlarım.... 

Sayın başkan daha nice güzelliklerle dolu nice yıllar diliyorum...tüm yaşanacak güzellikler deli mavi sevdalarla olsun....

Emrah Çetinkaya

******************************

Ben de GURUBUMUZUN 1.YAŞINI YÜREKTEN KUTLUYORUM.

Ahmet Sefer Koçer

******************************

Deli Mavi Sevdalar grubuna kuruluşunun 1. yılının dolmasına az kala katılmış olmaktan mutluyum. 

Öncelikle kuruculara ve bu günlere getiren dostlara sevgilerle merhaba demek istedim.. 

Nice nice Dostça Yıllara..

Hasan Ekrem

******************************

kabul buyurursanız...... 

gül bana da..........atılsana..............mavi sevda...........bebeğim 

atılsana................gülüşündür.........ilhamıma..............direğim 

mavi sevda............ilhamıma...........kutlu olsun............dileğim 

bebeğim.................direğim..............dileğim............... ereğim

Veysel KOŞAR

******************************

Bu ne güzel bir coşku, ne güzel bir mutluluk ve ne hoş bir sevinç. Bütün grup arkadaşlarıma beraber nice yıllara diyorum :)

İyi ki doğdun DELİ MAVİ SEVDALAR... 

Deli bir mavi sevda saldın yüreklerimize...

Özgür KÖKTÜRK

******************************

Güzel dörtlüğünüz gül gibi geldi 

Aldı kabul etti gönül beğendi 

Grup bir yaşında murada erdi 

Her gece buraya bekleriz sizi.

Mustafa ALPAYDIN

******************************

Arkadaşlar, 

Bugün grup genelinde yazılan her mesajı tek tek okudum...Hepsine ayrı ayrı cevap vermek yerine tek bir mesajla tüm dostlarıma şu anda hissettiklerimi anlatmak istedim... 

AĞLIYORUM...Ama mutluluktan...Bir çok gruba üyeyim ama inanın hiç bir grupta böylesi güzel bir günün, böylesi bir dayanışmanın ve böylesi birleşen yüreklerden çıkan duyguların sesinin yüksekliğini yaşamadım... 

Bir grubu grup yapan bu hale getiren kurucusu değildir. O grubu paylaşan yüreklerdir. Ancak gördüm ki bugün burada yürekler birleşmiş tek bir beden, tek bir yürek olmuş... 

İnanın kelimelerin kifayetsiz kaldığı noktadayım...Hepinize güzel mesajlarınız, dörtlükleriniz, paylaşımlarınız ve yanında dünyanın tüm elmaslarının sönük kalacağı muhteşem güzellikteki duygularınız için teşekkür ederim... 

İyi ki varsınız...Sizler olmasaydınız DELİ MAVİ SEVDALAR olmazdı.... 

HATİCE AK', 'DELİ MAVİ SEVDALAR Grubunun 1 nci yaş gününü doldurmasından dolayı kutluyorum..Gerek Hatice hanımın ve gerekse yönetimdeki arkadaşlarımızın ...', ARRAY['Türk Edebiyatı','Şiir','Deli Mavi']::text[], 8.5, '{"poet":"Deli Mavi","poet_slug":"deli-mavi","theme":"Türk Şiiri","is_hero":false,"total_lines":209,"source_url":"https://www.antoloji.com/tek-yurek-oldu-grup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sude Yasemin', 'sude-yasemin-haydar-okur-yittb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Su,rüyamdaki çocukluğumdur akıp giden zaman gibi

Uçarsular, ırmaklar gibi damarlarımda

Deniz olur, okyanus olur aşk, çılgınca döver kıyılarımı

Ellerimle tutacak ve avuçlarıma dolacak gibi...

Yasemin kokulu sevdalara adımlar ilkyaz

Ayva, şeftali narçiçeği gibi

Suzinat bir şarkıdır o şimdi

Esrik bir gönülde eksik olmayan bir tını

Mor dağlarda bir turnanın kanadı 

İlmek ilmek işlenen en seçkin nakışlar gibi

Nazende bir sevgidir o, dillerden düşmeyen şarkılar gibi', 'Su,rüyamdaki çocukluğumdur akıp giden zaman gibi Uçarsular, ırmaklar gibi damarlarımda Deniz olur, okyanus olur aşk, çılgınca döver kıyıları...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sude-yasemin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiğinde Yanımda Kal', 'gittiginde-yanimda-kal-atilla-guler-ozows', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yittiğini düşündüğünde hayatın

elinden kayıp giden zamana bakıp

ıslak gözlerinin neleri ıskaladığı bilinmez

yüreğin nerelerde kaybolduğundan bihaber

geçip giden

tırnaklarını yemiş çocukluğundaki saflığın izleri

el sallar

alır başını gider sevdalar…kan damlar en acı sevdadan

kuru dudakların dinmeyen safsatasında

hızla yol alan ayaklara dur demek ne mümkün

koşar adım geçer yüzler bir bir

dualara sığınmış ruhun ezikliğinde açan çiçeğe tutunur hayat

fırtınalarda harabe…paramparça

duygusal bir türküde gözlerine bakar dost gözler

suskun

sessiz

ağlamaklı

ellerinin sıcağını unutmuş

gidersin

dünya veda eder

sen kalırsın

sen giderken

sözlerin yürekte ok

hoşça kal deme

hoş kal

hoş

kal

yanımda kal', 'yittiğini düşündüğünde hayatın elinden kayıp giden zamana bakıp ıslak gözlerinin neleri ıskaladığı bilinmez yüreğin nerelerde kaybolduğundan...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gittiginde-yanimda-kal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
