INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda....', 'sevda-nurdane-diken-phylj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Bir sevda yarattım, 

İkimiz için'' 

Gülen gözlerinde 

Yaşamak için. 

Dertlenip derdinle 

Yaşamak için 

Ayaz gecelerde, 

Isınmak için. 

Ateşinle yanıp 

Erimek için 

Köz olup külünle, 

Savrulmak için. 

Gecemi gündüze 

Çevirmek için 

Bir ömür seninle, 

Geçirmek için. 

Bir sevda yarattım 

Kül olman için 

Gönül ateşiyle, 

Kavrulman için..', '''Bir sevda yarattım,  İkimiz için''  Gülen gözlerinde  Yaşamak için.  Dertlenip derdinle  Yaşamak için  Ayaz gecelerde,  Isınmak için.  Ateşi...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevda-121-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle..', 'seninle-nurdane-diken-edtzw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Altmışdört milyon hücrem, seninle 

Sen kiminle, nerede? 

Nasıl bırakırsın, bir kalemde! 

Bulabilir misin benliğini, bensiz de 

Yaşayabilir misin, altmışdört milyon hücresiz de........', 'Altmışdört milyon hücrem, seninle  Sen kiminle, nerede?  Nasıl bırakırsın, bir kalemde!  Bulabilir misin benliğini, bensiz de  Yaşayabilir m...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seninle-78-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahiretlik Can Kırığı', 'ahiretlik-can-kirigi-tulay-sustam-f5wew', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'usumun

duvarlarına resmini çizdim

gözlerimde rengin 

sen 

her kalemi eline alışında

güneşi yüreğime çizdin 

ne zaman 

hayalini düşlesem

hayatın rafından 

çıkarırım tozlu anıları

doya doya öperim

yosun / deniz / toprak gözlerini

göz yaşın düşer,

çatlamış dudağıma

kurumuş toprağa can verirsin 

dudak kıvrımlarım da

unuturum seni özlemeyi

17 kasım

derin aşk kırıntıları', 'usumun duvarlarına resmini çizdim gözlerimde rengin  sen  her kalemi eline alışında güneşi yüreğime çizdin  ne zaman  hayalini düşlesem haya...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ahiretlik-can-kirigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin..2....', 'senin-i-cin-2-nurdane-diken-fqxir', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bahar dalları açmış 

Tabiatta bir hareket başlamış 

Ama sen yoksun... 

Koyunlar yavruları ile oynaşmış 

Doğa birbiriyle barışmış 

Ama sen yoksun.. 

Güneş ay''a sarılmış 

Yıldızlar birbiriyle öpüşmüş

Ama sen yoksun... 

Fırtınalar bile hızını kaybetmiş 

İnsanlara huzur sunmuş 

Ama sen yoksun.... 

Kalbim bir çöle dönmüş 

Susuz kalan bir fidan gibi solmuş

Ama sen yoksun.... 

Hadi gel! 

Bahar yağmurlarıyla barış! 

Bütün evren sana, sevgi duyacakmış 

Ve herşey senin içinmiş 

Döndüğün gün herşey, 

Mutlulukla dansedecekmiş.......', 'Bahar dalları açmış  Tabiatta bir hareket başlamış  Ama sen yoksun...  Koyunlar yavruları ile oynaşmış  Doğa birbiriyle barışmış  Ama sen yo...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/senin-icin-2-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçiyorum (!) Bu Can''dan..', 'geciyorum-bu-can-dan-evina-berfin-i14yd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'can dediğim haber salmış … 

gelmeyecekmiş.. bu son demiş …

güzel dursun diye de maviye boyamış her söylemi

öyle de olsa, 

mavi  arınmışlığıdır ruhumun

hesapsız.. yalansız..pusatsız …

hem de hiç kuytusuz …insan gibi insan işte 

mavi,

can damarı yüreğimin

yüreğimden vuruldum can...

ben yine sustum 

bu son susmalarım …..

can olmak buysa eğer, ben canda ki canı, candan eyledim …

yanacaksa yürek, ihaneti söker, 

yürekten de geçerim …

eyvah! 

yine dostluğun ölmek sabahı

yine cenazeler  … yine kapanan kepenkler

buruş buruş kağıtlara

eğri büğrü yazılarla kapılarda asılı 

minik ilanlar

‘Cenaze nedeniyle, kapalıyız ‘

taşlayın bu cenazeyi, 

güller yaralamasın bu son yolculukta ….. 

 ………………… Basınız sağ olsun can dediklerim,

ve can kalanlar  … 

şimdi dibe vurmanın tam zamanı

susuyorum.. ve boyuyorum siyaha

geriye kalmış her mavi harfi 

ölüm bile olsa 

yaşanası her şey İNSAN içinmiş …. 

22 KASIM 200 

10:30', 'can dediğim haber salmış …  gelmeyecekmiş.. bu son demiş … güzel dursun diye de maviye boyamış her söylemi öyle de olsa,  mavi  arınmışlığıd...', ARRAY['Türk Edebiyatı','Şiir','Evina Berfin']::text[], 8.5, '{"poet":"Evina Berfin","poet_slug":"evina-berfin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/geciyorum-bu-can-dan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin..', 'senin-i-cin-nurdane-diken-dr95m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nasıl hayaller kurdum, senin için. 

Ulaşılmaz tabûsun, benim için. 

Bir gül bahçesi oldum, senin için. 

Sözlerin zehir olur, benim için. 

Güzellik vazgeçilmez, senin için. 

Güzellik sözde kalır, benim için. 

Her gelen kabûlündür, senin için. 

Görmezse göz sevemez, benim için. 

Sevgi abidesiyim, senin için. 

Gönül mihrabı yıktın, benim için. 

İçtiğin şarap zehir, senin için. 

Yıllar uçuverir de, benim için. 

Ne ben anladım seni, senin için. 

Ne sen anladın beni, benim için. 

Ne de ben varım sana, senin için. 

Ne de sen varsın bana, benim için.....', 'Nasıl hayaller kurdum, senin için.  Ulaşılmaz tabûsun, benim için.  Bir gül bahçesi oldum, senin için.  Sözlerin zehir olur, benim için.  Gü...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senin-icin-131-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünüyorum..', 'seni-dusunuyorum-nurdane-diken-y7yo7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum, geceler boyu 

Karanlığı yırtan, kahkahaları 

Odalardan, kaldırımlara düşen ışıkları 

Birbirlerinin kollarında, mest olan aşıkları 

Seni düşünüyorum, geceler boyu sevişmelerimizi 

Çılgınca ruhumda, her dokunuşunu öpüşünü 

İhtiras fırtınalarından, yorgun düşen, bedenimizi 

Sonra, bırakıp beni gitmeni, çaresizliğimi 

Geçmiyor sevgilim, gece bitmiyor 

Senle olup, sensizlik çekilmiyor 

Duyamıyorum, sesini, sıcaklığını 

Nefesini, öpüşünü, seni düşünüyorum 

Seni düşünüyorum, koşup kollarıma 

Arzuyla, bedenime sarılışını 

İşte geldim, sevgilim deyişini 

Her seferinde, yeniden, yorgun uyanışımı 

Seni düşünüyorum, asırlar sonra da olsa 

Seni bekliyorum, seni düşünüyorum.. 

03.02.1996-Aydın....', 'Seni düşünüyorum, geceler boyu  Karanlığı yırtan, kahkahaları  Odalardan, kaldırımlara düşen ışıkları  Birbirlerinin kollarında, mest olan a...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-dusunuyorum-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senfoni..', 'senfoni-nurdane-diken-vztbx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir orkestra kur bana 

Müziğin en ulaşılmazını ver 

Do sesinden başla 

Yedi renkte, tünamiyi sun 

Renklerle müzik dansetsin 

Doldursun tüm evreni 

Duygulardan, duygular yaratsın 

Hicaz peşrev başlasın 

Salamon''un tülleri raksetsin 

Bir senfoni başlasın 

Bitmeyen bestenin, sol notasında 

Yol bulsun, bitirilmemecesine 

Kendimizden geçelim 

Bedenimiz erisin 

Do sesinden başlayıp 

Sûr sesinde, bitirelim......', 'Bir orkestra kur bana  Müziğin en ulaşılmazını ver  Do sesinden başla  Yedi renkte, tünamiyi sun  Renklerle müzik dansetsin  Doldursun tüm e...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senfoni-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sence Neydim..', 'sence-neydim-nurdane-diken-x5uz3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen''mi iyiydin, ben''mi kötü? 

Seven''miydin, sevilen''mi? 

Arzu''mu güzeldi, ihtiras''mı? 

Aşk''mı geçerliydi? 

Sadakât''mi? 

Güven''miydi, güven''sizlik''mi? 

Yalan söyler miydin? 

Yoksa, dürüst müydün? 

Söyle, sahi sen neydin? 

Bunlardan hangisi, sen''din? .. 

Ben, sence neydim....', 'Sen''mi iyiydin, ben''mi kötü?  Seven''miydin, sevilen''mi?  Arzu''mu güzeldi, ihtiras''mı?  Aşk''mı geçerliydi?  Sadakât''mi?  Güven''miydi, güven''s...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sence-neydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koşulsuz', 'kosulsuz-asude-gediz-ybdnd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu umursamaz boşluğa 

Ne zaman düşsem 

yanımda bir ses,bir nefes olsun isterim

koşulsuz..........

umutsuzluğa yelken açmış  yüreğim

koskoca bin karanlık

boşluğa dayanmışım ne yazık

ses isterim….bir nefes

koşulsuz.........', 'Şu umursamaz boşluğa  Ne zaman düşsem  yanımda bir ses,bir nefes olsun isterim koşulsuz.......... umutsuzluğa yelken açmış  yüreğim koskoca ...', ARRAY['Türk Edebiyatı','Şiir','Asude Gediz']::text[], 8.5, '{"poet":"Asude Gediz","poet_slug":"asude-gediz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kosulsuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nehirler de Susar', 'nehirler-de-susar-suna-doganay-flcim', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saymadım...

On yıl mı, onbeş mi..

Sahi kaç yıl oldu, görüşmeyeli? 

Küsmüşsün aynalara ben görmeyeli..

Söyle canım, söyle bu kadar kötü mü dünya! 

Ne kaldı şunun şurasında,

Zaten hafif bir uyku değil midir? 

Bir ölüm...

Bir mevsim..

Bir seçim....

Belki seviyorum sabah güneşini,

Belki...

Ölü bir gecenin yalan gülümseyişini..

Belki de varoluşun kaynağı olan..

Uzak geçmişimizi...

Kayıp geceleri..

Ve belki de, şafakla uyanan,

Altın topun sararan yüzünü.

İşte, uzun bir hikayenin dağılan parçaları,

İşte, dört nehrin hazin öyküsü..

Biri gitti, sustu biri..

Üç kaldı, üç yorgun gemi..

Ayrılmaz dörtlü sanırdık kendimizi.

Bir gülüp bir ağlardık,

Ölü gecelere...

Dayanmak çok güç..

Bedeli, birkaç damla gözyaşı.

Sabır taşıydı üçüncü nehir.

Sabrı vurdu beni,

Satırlar vurdu beni..

Sustu üçüncü nehir..

Sustu güneş yanığı eller.

Sustu İstanbul''un saklı sokaklarında,

Tüm şehir..

Sıra sana da gelecek, bana da..

Gökyüzü solacak birgün.

Kış otları gibi, dün, bugün...

Yürüyecek ve düşecek...

Susacak zamanı geldiğinde, belki yarın.

Susacak yarım kalan umutlar...

Nehirler de susacak..', 'Saymadım... On yıl mı, onbeş mi.. Sahi kaç yıl oldu, görüşmeyeli?  Küsmüşsün aynalara ben görmeyeli.. Söyle canım, söyle bu kadar kötü mü dü...', ARRAY['Türk Edebiyatı','Şiir','Suna Doğanay']::text[], 8.5, '{"poet":"Suna Doğanay","poet_slug":"suna-doganay","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/nehirler-de-susar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sence..', 'sence-nurdane-diken-xl9jw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Söyle bana, güzeller güzeli 

Söyle! 

Aşk mı bu? Yoksa tutku mu? 

Hiddetin neden, söyle! 

Aramızdaki, cam parçaları niye 

Kanatırsın, beni her titreyişte 

Gel, gör ki isyandasın bana 

Ekşi elma yedinse, suçu kime 

Söyle, bana söyle! 

Kendini tarttın mı, bir kere 

Kilo ile gram arasındayım, bu kere 

Söyle ay parçası, söyle! 

İçerde mi hüzün var, dışarıda mı

Bu kış ayazı sence, niye! .', 'Söyle bana, güzeller güzeli  Söyle!  Aşk mı bu? Yoksa tutku mu?  Hiddetin neden, söyle!  Aramızdaki, cam parçaları niye  Kanatırsın, beni he...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sence-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varsın...1', 'sen-varsin-1-nurdane-diken-lnrl8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen benim, bir tanemsin. 

Nabzımda atan nabızsın. 

Yürüdüğüm yollarda, sen varsın. 

Aldığım her nefeste, sen varsın... 

Seninle doluyum, her anımda. 

Canımda, kanımda, sen varsın. 

Sağımda, solumda, sen varsın. 

Yanımda, canımda, sen varsın... 

Nasıl anlatsam, sana seni. 

Benliğinde, görmelisin beni. 

Bulmalısın o aynada seni. 

Hayatımın merkezinde, sen varsın.. 

Sana duyduğum bu sevgi 

Menfaatsiz besbelli. 

Rüzgarın, yağmura özlemi, 

Yağmurumda, tipimde sen varsın.. 

Sen benim bir tanemsin. 

Can evimde sensin. 

Bir tek sevdiğim sensin... 

Hayatımda, sen varsın....', 'Sen benim, bir tanemsin.  Nabzımda atan nabızsın.  Yürüdüğüm yollarda, sen varsın.  Aldığım her nefeste, sen varsın...  Seninle doluyum, her...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-varsin-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Sevgili..', 'sen-sevgili-nurdane-diken-v4ygg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen sevgili 

Erişilmez olan, ama bende olan 

Sen sevgilerin özü 

Sen sevenin gözü 

Sen miski amber kokulu 

Sen şefkatlerin hası 

Sen huzur çiçeği 

Sen içimde bir ışık 

Sen zümrüt dünyanın 

Zümrüt parçası 

Sen güzellerin, güzeli 

Ulaşılamayan sevgili 

Sen aşk ateşinin harı 

Sen yarınlarımda saklı 

Sen görmeyen, gözüm 

Duymayan kulağım 

Sen içimdeki alev 

Hiç bir güzelle kıyaslanamayan 

Eşi, benzeri olmayan sevgili 

Duy sesimi, yak aşk ateşini 

Al kollarına beni, sıkıca 

Bırakma beni yaban ellere 

Sevgisiz, sahipsizce 

Allah''ım salma beni, girdaplara

Sensiz bırakma.....', 'Sen sevgili  Erişilmez olan, ama bende olan  Sen sevgilerin özü  Sen sevenin gözü  Sen miski amber kokulu  Sen şefkatlerin hası  Sen huzur ç...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-sevgili-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Bir Gün Lazım', 'bana-bir-gun-lazim-fidan-bulut-bay82', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kara hüzünler yağıyor

Eziliyor ruhum üşüyorum

Karabasanlar gecemde

Yalanlara feda aşkın ömrü

Şimdi bana bir gün lazım

Aç lacivertin kapılarını

Bir yıldız beklentim sana dair

Gökyüzünü gece geçe zamanlarda

Burada aynı yerinde kaç gecedir

Uçuşta gönül feneri

Firarda hayata duruşumun sen yanı

Söz dinlemez yanlarım sinsi taktiklerde

Sarıl bana sevgili gelinmez uzağından

Öyle yorgunum ki

Kollarım ıssız, ellerim soğuk

Buz dağında yangın düşlerim

Savunmasız eğreti duruşlardayım

Senli benli caddelerde

Bir gün bir gün izinde usum

Hani zamansızlık özlemi gibi

Dünü bu günü olmayan

Çok uzak değil yarının resmi

Bu günün aksi eksik takvimlerde

Yürüyorum sen izli karelerde

Sarıl sevgili şimdi sarıl sımsıkı

Ve sen de dünsüz bugünsüz bir 

                              Gün dile................', 'Kara hüzünler yağıyor Eziliyor ruhum üşüyorum Karabasanlar gecemde Yalanlara feda aşkın ömrü Şimdi bana bir gün lazım Aç lacivertin kapıları...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bana-bir-gun-lazim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmen', 'ogretmen-mahmut-gider-h8p12', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsanlığa gül sunar,

Gül yüzüyle öğretmen.

Aydınlanırken insan,

Tükeniyor öğretmen.

Asaleti varlığı, 

Yaşar bazen darlığı,

Aşar her barbarlığı,

Vakarıyla öğretmen.

Erdemdir onun adı,

Ahlaktır dili, tadı.

İlimle savsakladı, 

Kötülüğü öğretmen.

Barış onunla barış,

Savaş feleket, alış.

Bahara döner güz, kış.

Anlaşılsa öğretmen.

Cehaletle kavgası,

İnanç,sabır mayası.

Kabul olsa duası,

Dünya cennet öğretmen.', 'İnsanlığa gül sunar, Gül yüzüyle öğretmen. Aydınlanırken insan, Tükeniyor öğretmen. Asaleti varlığı,  Yaşar bazen darlığı, Aşar her barbarlı...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Gider']::text[], 8.5, '{"poet":"Mahmut Gider","poet_slug":"mahmut-gider","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ogretmen-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firar', 'firar-fidan-bulut-f7chx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir garip firardayım

Tam tabiri başı boştayım

Günlerim küpünü doldurmuş

Gecelerim kör kuyular...

Assalar boynum,kesseler kanımyok

Aklım havada,kalbim sarhoş...

Serseri hülyalardayım.

Yorgunum yanılmışım,

İzden çıkmış şaşırmışım.

Yeri göğü harmanlamış,

Seyre dalmışım.

Elimde sapsız balta

Dilim türü belli laflarda

Ah be güzelim dünya! 

Bir bana yer açamadın ya............

    Ben hala bulutlardayım! ! !', 'Bir garip firardayım Tam tabiri başı boştayım Günlerim küpünü doldurmuş Gecelerim kör kuyular... Assalar boynum,kesseler kanımyok Aklım hava...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/firar-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döküldü İçime Çöl Sıcağı', 'dokuldu-i-cime-col-sicagi-guzin-eye-dundar-dh5hf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şu acı  beyazları

yazdı  dört  mevsim

aşk ve  özlem  arası

..............soldu nefesim 

kısa bir  öykü

ömürlük sevda şarkısı

bardağın son damlası

....................sanki bir içim

ah...kıvırcığım  ak benizlim

döküldü  içime çöl sıcağı 

pusuda beklermiş  ayrılık

...................bilmedim

düşlerle  ölümsüzlüğe

giydirdim sevda türkülerini

bir baharlık sevda güneşi

sardı tenim

bir bahar yaşadı

.............sanki dört mevsim', 'Şu acı  beyazları yazdı  dört  mevsim aşk ve  özlem  arası ..............soldu nefesim  kısa bir  öykü ömürlük sevda şarkısı bardağın son da...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dokuldu-icime-col-sicagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuran-ı Kerim', 'kuran-i-kerim-yavuz-unler-1p5mu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kelamullahtır o, hiç şüphesiz

Uğruna can feda, nihayetsiz

Rabbin emridir, tüm kullarına

Acı son var uymayanlarına

Nar''ı da anlatıyor, nuru da

Islah olsun nefis okuyupta.

Kelamullahtır o, bize inen,

En hoş insandır, onu hıfseden

Resulullaha onu vahyeden

İlk ayetle ona ''ikra'' diyen

Melek-i cibrildi onu söyleyen.', 'Kelamullahtır o, hiç şüphesiz Uğruna can feda, nihayetsiz Rabbin emridir, tüm kullarına Acı son var uymayanlarına Nar''ı da anlatıyor, nuru d...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ünler']::text[], 8.5, '{"poet":"Yavuz Ünler","poet_slug":"yavuz-unler","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/akrostis-10-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerindeki Beyaz Perde...', 'gozlerindeki-beyaz-perde-ruya-deniz-demir-gl9sh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Belki umutsuzluğa dönüşür umut

Belki kararır gökyüzü yine

Düşünceler kaybolur

Beyin solmaya başlar belki

Belki hiçbir film 

Bu hayatı bu kadar hüzünlü anlatamaz

Belki de senin oynadığın rol

Sana hiç bu kadar ağır gelmez…

Durup dururken hıçkırıklara dönüşür

Gözlerinden akan yaşlar asılı kalır

Gözlerin kurur belki baharları

Belki beklediğin her şey

Yalan bir beyaz perdeyi aydınlatır

Belki anlamazsın hiçbir şeyi

Yaşadıkların başlar geçmeye

Gözlerinin beyaz perdesinde…

Belki hiçbir aktör oynayamaz

Bu bilinmez hıçkırıklı

Yalnızlık müptelası biraz da deli

Çok zeki ama bir o kadar ahmak

Hem kel hem fodul bu adamı…

Karakter çözümlemesini yapamamış

Hiçbir karaktere sığmamış 

Ve belki hiçbir giysi üstüne oturmamış

Oynanmayacak bir karaktere

Hiçbir oyuncu bu kadar yakışmamış

Belki bir daha yakışmayacak…

Hiçbir Kel Oğlan karakteri

Hiçbir Dördüncü Murat

Hiçbir Kara Murat 

Ve hiçbir Şaban uymayacak

Hiçbir karakter oyuncusu

Bu role asla uymayacak belki…

Belki yağmur yağar az sonra

İlmeklerden oluşan bir örtü

Bütün dünyayı kaplar az sonra

Yeni bir film başlar 

Gözlerinin beyaz perdesinde

Ve sen hiç kimseyi yakıştıramazsın

Bu role kendinden başka…', 'Belki umutsuzluğa dönüşür umut Belki kararır gökyüzü yine Düşünceler kaybolur Beyin solmaya başlar belki Belki hiçbir film  Bu hayatı bu kad...', ARRAY['Türk Edebiyatı','Şiir','Rüya Deniz Demir']::text[], 8.5, '{"poet":"Rüya Deniz Demir","poet_slug":"ruya-deniz-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/gozlerindeki-beyaz-perde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seversem', 'ben-seversem-guzin-eye-dundar-wp363', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben seversem

güneş düşer alnıma

karanlıklar koşar 

gün ışığına

sonuna dek açılır kapılar

gökkuşağına koşar yıldızlar

ve yakın olur uzaklar 

yüreğiniz üşümez

dersem...inanırmısınız?', 'Ben seversem güneş düşer alnıma karanlıklar koşar  gün ışığına sonuna dek açılır kapılar gökkuşağına koşar yıldızlar ve yakın olur uzaklar  ...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ben-seversem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yük', 'yuk-abdulvahap-ates-trirc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben  bana  yük  olalı,

Bakışlarım  değişti.

''Ben''i  sorgulayalı,

Fikirlerim çelişti.

Süzüldü birer,

Rol aldığım resimler,

Kopardıgım  takvimler,

Bir sağnağa dönüştü.

Sermayemi yokladım,

Azığı  ayıkladım,

Saçlarımı akladım,

Karlı kışa dönüştü.

Döndüm baktım ardıma,

Bir nefeslik yurduma,

Yapışan  avurduma,

Bir bedbinlik üşüştü.

Tek kurtuluş ölümden,

Ölüp doğmak yeniden,

Bu bitmez hengameden,

Artık beynim uyuştu.', 'Ben  bana  yük  olalı, Bakışlarım  değişti. ''Ben''i  sorgulayalı, Fikirlerim çelişti. Süzüldü birer, Rol aldığım resimler, Kopardıgım  takvim...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Ateş']::text[], 8.5, '{"poet":"Abdulvahap Ateş","poet_slug":"abdulvahap-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yuk-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuru yaprak ve ben', 'kuru-yaprak-ve-ben-ali-kilic-jy5gh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kuru yapraklarla kardeşim ben

Tenim ıslak ruhum kuru

Toprak oldu yolumun sonu

Bilinmezliktir  Alinin yol dostu

Yüreğim geniş ulu çınar gibi

Kollarım dalları gibi sarmallar herkesi

Bir damla suyla bile orman yeşertir

Nice sevdalara gölge yapar

Sarmalarım herkesi

Zordur aslında tek ağaç olamak bozkırda

Verebilirken sevgiyi 

Sen bir damla bulamamış olmak

Eğer yazılmışsa kaderime

Kalemin mürekkebi damarlarımda', 'Kuru yapraklarla kardeşim ben Tenim ıslak ruhum kuru Toprak oldu yolumun sonu Bilinmezliktir  Alinin yol dostu Yüreğim geniş ulu çınar gibi ...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç']::text[], 8.5, '{"poet":"Ali Kılıç","poet_slug":"ali-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kuru-yaprak-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayamam Ben', 'yasayamam-ben-yusuf-onder-bahceci-rq2mf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu derdin elinden ağlar gezerim,

Başıma karalar bağlar gezerim,

Ovalar, bayırlar, dağlar gezerim,

Onu sevmeden yaşayamam ben.

Bu sevda başıma bela getirse,

Onulmaz yaralar, dertler yetirse,

Onun uğrunda ömür tükense,

Onu sevmeden yaşayamam ben.

Her nereye baksam onu görürüm,

Düşündükçe onu hergün ölürüm,

Bu derdin çaresi yoktur bilirim,

Onu sevmeden yaşayamam ben.

İçimde özlemin çeşidi çoktur,

Ayrılık acısının ilacı yoktur,

Gözünü seveyim uzak dur doktor,

Onu sevmeden yaşayamam ben', 'Bu derdin elinden ağlar gezerim, Başıma karalar bağlar gezerim, Ovalar, bayırlar, dağlar gezerim, Onu sevmeden yaşayamam ben. Bu sevda başım...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasayamam-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zeytin Dalı Gibidir Çocuklar', 'zeytin-dali-gibidir-cocuklar-ulas-guleviz-pjdw3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'zeytin  dalı  gibidir  çocuklar 

barış  dolu

ve  yeşildir  yaprakları

özgürlüktür

paylaşımdır

düşleri  vardır

maviye  uzanan

minik  elleriyle 

ve  güldürmek  için  insanlığı

buldurmayı  görev  edinmiş 

içimizdeki  sakin  duyguları

[email protected]', 'zeytin  dalı  gibidir  çocuklar  barış  dolu ve  yeşildir  yaprakları özgürlüktür paylaşımdır düşleri  vardır maviye  uzanan minik  elleriyl...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Güleviz']::text[], 8.5, '{"poet":"Ulaş Güleviz","poet_slug":"ulas-guleviz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zeytin-dali-gibidir-cocuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalındaki Taze Çocuk', 'dalindaki-taze-cocuk-ulas-guleviz-cwmad', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dalındaki  taze  çocuk

kopar  sen  de

şu  hayatın  ucundan

somurtkan  diye  hayat 

ve  bir  kaşık  suda  boğacak  diye  seni

ürpermek  olur  mu  ondan 

yeşil  bir  yapraksın  sen

ağacın  fırtınadan  koruduğu  saçları

saçlarına  sığınmış  tomurcuksun

tazesin  daha

çocuksun

koparsın

sen  de  bu  hayattan

ama  acelen  ne

neden  bu  isyanın

kime

bu  konuşmalar

fayda  mı  bilemiyorum 

o  taze  çocuğu

dalında  bırakıp  gidiyorum

sonra  duyuyorum

ve  görüyorum

önceleri  gördüğüm  çocukları

dalından  düşmüş  meyveler  olduğunu  sanıyorum

ama  şimdi  biliyorum

neden  büyümediklerini 

ve  neden  öldüklerini

tazeyken 

ve  neden  kemirdiklerini

benliklerini

ölürken  düşündüklerini

biliyorum

“ dalından  düşmüş  çocukları

bu  yüzden  mi  bilmem

çok  seviyorum ”

[email protected]', 'dalındaki  taze  çocuk kopar  sen  de şu  hayatın  ucundan somurtkan  diye  hayat  ve  bir  kaşık  suda  boğacak  diye  seni ürpermek  olur ...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Güleviz']::text[], 8.5, '{"poet":"Ulaş Güleviz","poet_slug":"ulas-guleviz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/dalindaki-taze-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dışıma Vuramadıklarım', 'disima-vuramadiklarim-ulas-guleviz-nhlv3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dışa  vurduğum  duygularımdan  çok  var  içimde

Hem  üstelik  dışımdakilerden  masum  içimdekiler

Ve  üstelik  daha  yalnızlar

Daha  sakin

Yıllar  geçtikçe  büyüyor  muyum 

Yoksa  yalnız  duyguları  mı  büyüyor 

Ve  yalnızlığım 

İçimi  yakan  sebebi  bilmemek  üzer  beni

Yani  sebepsiz  gibi  olmak  ama  üzülmek  üzer

Kızarım  ve  kızılır  hayata  hep

Ve  hep  üzülür  birileri

Yani  bu kısır  döngü  hep  sürer

Ve  beni  boğan  bu  hayat

elbet  benden  sonrada  sürer

Benim  korkum  içimdekiler

Yani  dışıma  vuramadıklarım

Kendimden  bile  gizlediklerim

Ve  sebebini  bilmeden  yandıklarım

Bilemiyorum

Hep  benimle  mi  gelecekler

[email protected]', 'Dışa  vurduğum  duygularımdan  çok  var  içimde Hem  üstelik  dışımdakilerden  masum  içimdekiler Ve  üstelik  daha  yalnızlar Daha  sakin Y...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Güleviz']::text[], 8.5, '{"poet":"Ulaş Güleviz","poet_slug":"ulas-guleviz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/disima-vuramadiklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk tür bu tarihte yenilmez olan nesil', 'turk-tur-bu-tarihte-yenilmez-olan-nesil-halil-colak-yrgop', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Türk tür bu tarihte yenilmez  olan  nesil

Yaseften bu yana vardır da bu Türklük

Oğuz han, Gültikin han,Mete han beri

Tarihe yön veren işte bu Türklük''tür

Kubilay han dır kırımda hanların hanı

Tarih unutamaz o muhteşem Cengiz Hanı

Timurlenk ki titredi kendi cağını

Dünyayı titreten işte bu Türklük''tür

Selçuklu ile Anadolu’da sürdü saltanat

Anadolu Hanlarla Hamamlarla doldu

Haçlılara boyun eğmeyen Kılıç Aslanlar vardı

Haçlılara dersini veren işte bu Türk''tür

Osman Gazi ki imparatorluk Ulu çınar dikti.

Bütün Rumi diyarı bir  bir fethetti.

Dünyaya hak ve adaleti onlar öğretti

Vatanı canından çok seven işte bu Türk''tür

Yavuz gibi cengaver Sina yi geçti

Cihan hakanı olduğunu o ispat etti

Türkün tarihine şan şöhret kattı

Müslümanların başına geçen işte bu Türk''tür

Halil Çolak 22.11.2005 Ankara', 'Türk tür bu tarihte yenilmez  olan  nesil Yaseften bu yana vardır da bu Türklük Oğuz han, Gültikin han,Mete han beri Tarihe yön veren işte b...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/turk-tur-bu-tarihte-yenilmez-olan-nesil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varlığım Yokluğum Sen', 'varligim-yoklugum-sen-guzin-eye-dundar-s67yu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'her yeni doğan gün ışığında

sen  varsın

tohumun sırrı sen

ekmeğin sabrı 

baharın  uyanışı 

yazın  vurucu sıcağı

toprakta şekillenen

çiçeklerde renklenen

varlığım... yokluğum sen

bebek  yatağımda 

tutan elimden

ölüm  döşeğinde... 

yine sen...', 'her yeni doğan gün ışığında sen  varsın tohumun sırrı sen ekmeğin sabrı  baharın  uyanışı  yazın  vurucu sıcağı toprakta şekillenen çiçekler...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/varligim-yoklugum-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-guzin-eye-dundar-p27sp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kara  gözlerinin

tılsımlı  güzelliğinde

tek  mutluluğumsun 

sessiz  gece

sana  adadım

yorgun  bedenimi

ona  tasasız  düşlerini  sun

bir  gece  olsun  / gönlünce  yaşat

bir  gece  olsun /  rahat  uyusun

ne  sessizliğini bozmak   isterim 

ne  aramak  esrarlı boşluğunu

geçtiğim  yolların  uzunluğunu

unutmak 

yeniden  doğmak  isterim...', 'Kara  gözlerinin tılsımlı  güzelliğinde tek  mutluluğumsun  sessiz  gece sana  adadım yorgun  bedenimi ona  tasasız  düşlerini  sun bir  gec...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gece-191-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adın Gözdesi Gönlün', 'adin-gozdesi-gonlun-ali-aydogdu-3rcv4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'adın hırstı...

inadına dumansızlığım ile kessemde nefesini

çıkarırdın içimden, o  anlaşılmasız  iğrenç dilini 

adın gizemdi...

muallâ yansıman 

yollarına düştüğüm güzel gerili 

sayfalar bile örtemedi  belini

yediğin önünde, yemediğin ardında şiirdi 

onu hazmeder, onu boşaltırdın sisteminden

içine ederdin 

hırs namluya girerdi gözlerinin ferinden 

kaçmaya meyilli

sonsuzluk menzili 

ve yedeğindeydi ellerim 

öyle ki....

muallâ sana rastlasa sevgili 

hatırlatır batan geminin farelerini

adın gözde''si gönlün

sözün öznesi ömrün

çok olur gibiyim', 'adın hırstı... inadına dumansızlığım ile kessemde nefesini çıkarırdın içimden, o  anlaşılmasız  iğrenç dilini  adın gizemdi... muallâ yansım...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydoğdu']::text[], 8.5, '{"poet":"Ali Aydoğdu","poet_slug":"ali-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/adin-gozdesi-gonlun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Siyah noktalar :-) tehlikeli mi?', 'siyah-noktalar-tehlikeli-mi-gul-ozan-iwisz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben bu kara sevdayla

sana rağmen

çeyrek asırdır

sürüklendiysem...

Yüreğimin daha büyük olduğundandır

senin boşluğundan! 

Hani bir kere hayatına

sevdiğini alabilmişler

sonradan

''yerin dolmadı'' derler ya

ayrılınca...

Ben de doya doya

''hiç yerin olmadı'' diyebilirim

''hayatımda''

Bir de var ya

hiç bir şiir

şairinden öte

yüzde yüz okunabilmiş değildir...

ve çok sıkıştırırsan eğer gölgeyi

siyah ve görünmez bir noktaya

dönüşebilir...

-siyah noktaların neler saklayabildiklerini bütün genç kızlar bilir-

Bak gel bul beni burada,

iki yanımdan sık,

dikkat et, çok dolu yüreğim

hem aklım da karışık...



not: Yassi''nin yorumu çok güzel - teşekkür ederim', 'Ben bu kara sevdayla sana rağmen çeyrek asırdır sürüklendiysem... Yüreğimin daha büyük olduğundandır senin boşluğundan!  Hani bir kere hayat...', ARRAY['Türk Edebiyatı','Şiir','Gül Ozan']::text[], 8.5, '{"poet":"Gül Ozan","poet_slug":"gul-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/siyah-noktalar-tehlikeli-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli Özleyiş', 'gizli-ozleyis-guzin-eye-dundar-6xv0d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Günler  uzar

gecelerim  yalnızlığa  saplanır

dinmez  sızısı  gönlümün

gizli  özleyiş

her  varlıkta  sizden öte

birşey  var

bunca   sevmek   ve   yakarmak

Tanrıya  her yeni gün

neye   yarar

ölmez   sevgiyle   büyür

mutlu   bekleyiş

bir  an  yitirir

tüm  umudu  ayrılık

tek  birşey  kalır

sizden  bir  boşluk

büyür  yalnızlık

ve  hergün  sararan  bir  çiçek  gibi

gizli özleyiş...', 'Günler  uzar gecelerim  yalnızlığa  saplanır dinmez  sızısı  gönlümün gizli  özleyiş her  varlıkta  sizden öte birşey  var bunca   sevmek   ...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gizli-ozleyis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Uzaktan Geldiler', 'cok-uzaktan-geldiler-kamil-at-m7ggf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok uzaklardan geldiler

Önce aç olduklarını söylediler

Anlaşılmıyordu dedikleri anlamıyordun

Daha sonra aç olduklarını

Söylediler yalvardılar acıdın

Birden baktınki yerini elinden kapmışlar

Yetmedi seni yerinden sürdüler

Şimdi dileniyorsun, seni kovalıyorlar

Yatacak yerin yok, üşüyorsun donuyorsun

Titriyorsun, dilin küfürüde bırakmış artık

Faydasını belirtmedi

Bu dünyada neye doğdum diyorsun 

Geziyorsun geziyorsun,

Aklına yatmıyor çözümler

Benden küçük bir nasihat sana

üzülmen fayda etmez 

ağlamak hele

Belkide naciz bir çözümü var

Mutlu olman dünyaya nasıl baktığına bağlı

neyi nasıl gördüğüne bağlı....

Kamil At', 'Çok uzaklardan geldiler Önce aç olduklarını söylediler Anlaşılmıyordu dedikleri anlamıyordun Daha sonra aç olduklarını Söylediler yalvardıla...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cok-uzaktan-geldiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Komando', 'komando-osman-taspinar-et6o4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Babam askermiş ben doğduğumda

Ninniler söylemiş anacığım baş ucumda

Vatan borcunu ödemekte babanda

Rahat uyu güzel yavrum sen kucağımda.

Hasret çekmişler birbirine aylar boyu

Mektuplar,nameler yazılmış sayfalar dolu

Gözyaşları dökülmüş mendillere koyu koyu

Sevdiğim askerdir,beklediğim asker yolu.

Şimdi ben askerim,yarın benim çocuğum

Az kaldı benim de yakında yolcuyum

Vatan''a helal gelmesin buna hep duacıyım

O na canım fedadır; Ben bir komando''yum.', 'Babam askermiş ben doğduğumda Ninniler söylemiş anacığım baş ucumda Vatan borcunu ödemekte babanda Rahat uyu güzel yavrum sen kucağımda. Has...', ARRAY['Türk Edebiyatı','Şiir','Osman Taşpınar']::text[], 8.5, '{"poet":"Osman Taşpınar","poet_slug":"osman-taspinar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/komando-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Yangınları', 'eylul-yanginlari-evina-berfin-tcke1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'vurgun yedi yüreğim 

lacivert bir gecenin yarısında 

şiirle dillendi 

yüreğe aktı en durusu sevdanın 

ve özlemler pesi sıra 

yanıyor sol yanım 

acıtıyor avuçlarımı usulca bıraktığın 

ortanca kokan hasretliğin 

sana koşuyor her deli rüzgar 

ve gül yaprağında yüreğim 

Eylül’ü çoktan geçmiş 

vakit sevdayı beş geçe 

gözlerimde yeşermiş bahar 

meydan okuyan bir tamam uzaklığa 

penceren de bir kus 

kanadında sevda şarkısı... 

yar kapına dayandım... 

yüreğim ellerimde... 

Eylül’ün sürgün gülleri... 

sevilesi midir? 

yoksa kanayan eski bir yara mi gül yaprağına sarmalanan? 

yaşandı.. 

geriye kalan,

avuçlarımızda hala kanayan üç beş gül yaprağı 

biri diğerine sevdalı... 

Merhaba Eylül Sürgünü Gül Yaprağı..

20 Kasım 2005', 'vurgun yedi yüreğim  lacivert bir gecenin yarısında  şiirle dillendi  yüreğe aktı en durusu sevdanın  ve özlemler pesi sıra  yanıyor sol yan...', ARRAY['Türk Edebiyatı','Şiir','Evina Berfin']::text[], 8.5, '{"poet":"Evina Berfin","poet_slug":"evina-berfin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/eylul-yanginlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanımaz Olsaydım', 'tanimaz-olsaydim-fatih-demir-pe051', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmiştim seni bu yalan dünyada

Biliyorum sen beni takmadın umruna

Boş yere sokmuşum seni hayatıma

Keşke seni tanımaz olsaydım

Tek hayalim sendin benim

Seni ölünceye kadar sevecektim

İki günde bebi deliye çevirdin

Keşke seni tanımaz olsaydım

Boş yereymiş kurduğum hayaller

Kalbimin acısı derinden inler

N eyaptımda bana kötü dediler

Keşke seni tanımaz olsaydım

Gençliğimi harcadım senin uğruna

Aldırmıyorsun döktüğüm göz yaşına

Dönüp bakmıyorsun bile ardına 

Keşke seni tanımaz olsaydım...', 'Sevmiştim seni bu yalan dünyada Biliyorum sen beni takmadın umruna Boş yere sokmuşum seni hayatıma Keşke seni tanımaz olsaydım Tek hayalim s...', ARRAY['Türk Edebiyatı','Şiir','Fatih Demir']::text[], 8.5, '{"poet":"Fatih Demir","poet_slug":"fatih-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tanimaz-olsaydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şüphe....', 'suphe-mustafa-celebi-cetinkaya-3z0ax', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '...	

Ben aslında hiç doğmadım ya 

Konuştuğumda başlı başına bir yalandı.

Kimse görmedi mutlu olduğumu 

ve gözlerim hiç yaşla dolmadı. 

Daha olmadan öldüğümü yazdı şiirler,

Ben aslında hiç itiraz etmedim hayata

Tek düşmanımda hayattı; 

		     Hep duran, karşımda...

Aldığım her nefes nefessiz bıraktı beni,

Umutlandığım her düş hevessiz...

Her haykırışımda sessizliğimle boğuldum,

Aleme baba oldu yüreğim, çileye evlat oldum.

Dolup taşan varlığıma yok dedim,

Hiç kalmamış kendiliğime çok dedim.

Öyle karışıktı ki her şey; karışıktım

Gün oldu ya güneş doğmadı evrene 	... Alışıktım.

Ben aslında hiç susmadım ya,

Konuştuğumda oldum olası yalandı.

Hayatta en çok koktuğum şeydi yaşamak; 

Yaşamak yalanlarla donatılmış bir insandı.

Ben bile geldiğime inanmazken dünyaya,

Bana hüviyet vermiş nufüs dairesi...

Eğer çileyse kainatın yaşama kuralı 

Benim inanmadığım bu dünyanın benim tek efendisi! ....

Sustum şimdi........

18 Temmuz 2004 Pazartesi 02:28', '...	 Ben aslında hiç doğmadım ya  Konuştuğumda başlı başına bir yalandı. Kimse görmedi mutlu olduğumu  ve gözlerim hiç yaşla dolmadı.  Daha ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çelebi Çetinkaya']::text[], 8.5, '{"poet":"Mustafa Çelebi Çetinkaya","poet_slug":"mustafa-celebi-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/suphe-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mayakovski selamı', 'mayakovski-selami-i-brahim-asli2-u7yup', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gün geçince avucumda

senden kalan saç telleri.

gecelerimi bilmem hangi boşluklar dolduruyor.

yüreğim serseri 

bir avuntunun telaşında gerçekliğini 

aramaya çıkmış bir peri kızı,

yolum uzun, mektuplarım  uzun

an deyip 

zamana terkedilen, 

düşlerin gömüldüğü bir bahçede 

bir sürü ölü düşler 

gerçek se hangisi sahte.

Lili''de sahteymiydi ey sevenler.

Kaybedenler ordusunda tek kalan adlar olur,

bir sürü de beyaz defter yaprağı.

Sonum böyle olacaksa varsın olsun

gün gelip akşamlar olmazsa onlar için

benim için güneş doğacak bir daha

benim için akşam olacak bir daha

ebedi karanlık huzurumdan yanlız çıkacağım 

en  alttan.', 'Gün geçince avucumda senden kalan saç telleri. gecelerimi bilmem hangi boşluklar dolduruyor. yüreğim serseri  bir avuntunun telaşında gerçek...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Aslı2']::text[], 8.5, '{"poet":"İbrahim Aslı2","poet_slug":"i-brahim-asli2","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mayakovski-selami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözleri Yarınlarla Işıl Işıl Çocuk', 'gozleri-yarinlarla-isil-isil-cocuk-ediz-karaoglu-20p6p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey gözleri yarınlarla ışıl ışıl çocuk,

Bak,elimde bir davetkar sevgiden başka hiçbir şey yok,

Gözlerim hep sende,ellerim soğuk,

Kalan son takatimi seni kazanmaya harcayacağım,

Sen,elleri tutulası,mutlu edilesi çocuk…

Akdeniz’in değildi sanki dalgaları hırçın,

Görüyorsun,yavaş yavaş dalgalar bentleri aşmakta,

Sen beni anlamıyorsun ve ben bir yirmilik bıçkın,

Sana halimi anlatmaya ömrümü adayacağım,

Bana bırak yüreğini,bundan böyle bende kalsın…

Ey geçmişini geleceğinden atamayan yaslı çocuk,

Bak,gümrah ırmaklarda savrulan bir beden var,

Düşünceler hep senle,son adımlarım ateşten yanar,

Olsun yine de bu ateşe basacağım,

Sen,ölüm bize gelinceye kadar iyiliği bırakmayan çocuk…

Uykularım böyle delik deşik değildi her şeye karşın,

Bakarsan görürsün geceleyin daha az uyku uyunmakta,

Sen beni tanımıyorsun ve ben tezcanlı hırçın,

Sana kendimi tanıtmaya ömrümü adayacağım,

Bana bırak gözlerini,ağlayacaksa bundan böyle benimki ağlasın…

22.KASIM.2005

SAAT:17:05

ANTALYA', 'Ey gözleri yarınlarla ışıl ışıl çocuk, Bak,elimde bir davetkar sevgiden başka hiçbir şey yok, Gözlerim hep sende,ellerim soğuk, Kalan son ta...', ARRAY['Türk Edebiyatı','Şiir','Ediz Karaoğlu']::text[], 8.5, '{"poet":"Ediz Karaoğlu","poet_slug":"ediz-karaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gozleri-yarinlarla-isil-isil-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrı Düştüğümüze Yanarım', 'ayri-dustugumuze-yanarim-mustafa-sami-1mu5d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Acı bir kahveyi yudumladığımda

Issız bir limana duyduğum özlemim

Zamanın süzgecinde akıp giderken

Bir ömür ayrı düştüğümüze yanarım

Hangi mevsim gönül evim tutuşsa 

Beyhude bir ömrün hatırasına kanarım', 'Acı bir kahveyi yudumladığımda Issız bir limana duyduğum özlemim Zamanın süzgecinde akıp giderken Bir ömür ayrı düştüğümüze yanarım Hangi me...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sami']::text[], 8.5, '{"poet":"Mustafa Sami","poet_slug":"mustafa-sami","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ayri-dustugumuze-yanarim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetiş', 'yetis-i-smail-dogan-x57k4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir güzel sevdim bak dünya güzeli,

Ataşından yanıp tozmadan yetiş,

Pirler  Piri  Hacı  Bektaşi  Veli,

Şerler düzenimi bozmadan yetiş.

Sizden başkasına hacet duymadım,

İnsanlık  dışına  gönül  yaymadım,

Ölüm tuzağına mayın koymadım,

Azmanlar derimi yüzmeden yetiş.

Doğruluk  ışığı  yaydın  vatana,

Hızır  sensin  arayıp da  bulana,

Sevgi tohum ektin yaşayan cana,

Hayattan yaşamdan bezmeden yetiş.

Irak gitme benden sana muhtaçım,

Öğüdün meşalen başımda taçım,

İlim  bilim  irfan  yolunda  ilaçım,

Cehalet anlıma yazmadan yetiş.

Asıldım yüzüldüm geldim bugüne,

Soyan çalan çırpan ezen ezene,

İsyan  ediyorum  bu şer düzene,

Zalimler kurşuna dizmeden yetiş.

Özüm buldum Hacı Bektaş Veli''de,

DOĞANİ  Pir''iyle  yüzer deryada,

Senden başka kimim vardır dünyada,

Dostlar mezarımı kazmadan yetiş.

22.11.2005', 'Bir güzel sevdim bak dünya güzeli, Ataşından yanıp tozmadan yetiş, Pirler  Piri  Hacı  Bektaşi  Veli, Şerler düzenimi bozmadan yetiş. Sizden...', ARRAY['Türk Edebiyatı','Şiir','İsmail Doğan']::text[], 8.5, '{"poet":"İsmail Doğan","poet_slug":"i-smail-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yetis-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Aziz Dostum...', 'sana-aziz-dostum-nurdan-elver-nttrr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimi zaman...

Kimi zaman derinleşir umutsuzluklar,

ALABİLDİĞİNE...

Kimi zaman keşfedilir sorumsuzluklar,

DERİNLEMESİNE...

Kimi zaman...

Kimi zaman perçinlenir dostluklar,

SEVECENLİĞİNDE...

Kimi zaman dengelenir düşünceler,

YAŞANDIĞINDA...

İnsan,

YAŞADIĞINDA

	SEVECENLİĞİ,

	ALABİLDİĞİNE

	DERİNLEMESİNE,

İnsan olur.

Böyle bir insan var, inanın.

Bir dost, can dostu.

Bir terazi çırpıntısında yüreği...

Bir geyik estetiğinde duyguları...

Ya düşünceleri? 

Onlar mı? ..

Bırakın onlar ONUN olsun; 

Değmeyelim...', 'Kimi zaman... Kimi zaman derinleşir umutsuzluklar, ALABİLDİĞİNE... Kimi zaman keşfedilir sorumsuzluklar, DERİNLEMESİNE... Kimi zaman... Kimi...', ARRAY['Türk Edebiyatı','Şiir','Nurdan Elver']::text[], 8.5, '{"poet":"Nurdan Elver","poet_slug":"nurdan-elver","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sana-aziz-dostum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört YapraklıYonca', 'dort-yaprakliyonca-alper-kuruk-xq1wc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Evimiz vardı yoncalığın yanında,

Evleri vardı yoncalığın başında,

Sabah-akşam oynardık

İkimiz yoncalıkta.

İnanırdım efsanelere

Ki inanç hakikat yolunun kılavuzudur,

Derlerdi dört yapraklı yoncayı bulursan

Çıkarmış altından

Çil çil,sarı sarı altınlar...

Dört yapraklı yoncayı

Beraberce aradık...

Günler,aylar geçtikçe

Birbirimize bağlandık.

Büyümüştük de artık...

Yoncaların köküne takılı kalmış

Eski anılarımızı söküp çıkarmak için

Bu kez gittik onunla

Hayalimizin yoncalığına...

Yine aradık...

Sarışın kız dört yapraklı yoncayı buldu...

Ben dibinden altın çıkacak sandım

Ama birşey yoktu...

Fakat ne çıkar? 

Sarışınım benim oldu....', 'Evimiz vardı yoncalığın yanında, Evleri vardı yoncalığın başında, Sabah-akşam oynardık İkimiz yoncalıkta. İnanırdım efsanelere Ki inanç haki...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dort-yaprakliyonca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman Diyebileceğim?', 'ne-zaman-diyebilecegim-alper-kuruk-1dr86', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu görünen kara dağlar

Eskiden de böyle değildi.

Basmıştı her yanı eşkiyalar

Korkudan nice başlar eğildi.

Kar yerine kan vardı bu dağlarda

Hergün birkaç ölü bulunurdu eteklerinde,

Soyulanlar yana yakara ağlar da

Yine birkaç kuruş kalmazdı yeleklerinde.

Kurşun yoktu,fakat korku çok,

Herkes canından bıkmış,

Dağda adam öldürene hiçbir ceza yok,

Eline bir silah alan doğruca dağa çıkmış...

Her taraf kan,ateş içinde yüzüyordu,

Her saat başında bir silah sesi,

Bir ölüm haberi herkesi üzüyordu

Silah sesiyle söndü nice insan nefesi.

Aradan aylar,yıllar geçti...

Bir efsane oldu kanlı dağlar,

O dağlar şimdi karlı dağlar...', 'Şu görünen kara dağlar Eskiden de böyle değildi. Basmıştı her yanı eşkiyalar Korkudan nice başlar eğildi. Kar yerine kan vardı bu dağlarda H...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ne-zaman-diyebilecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençlik Efsanesi', 'genclik-efsanesi-ahmet-sureyya-durna-jqg25', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anafor gibiydik gönül tasında,

Gençliğimiz,bizden farımadan önce.

Çiğ düşerdi üstümüze şafakta,

Bağrımıza deli rüzgar eserdi,

Sararıp kurumadan önce! .

Göğ ekin gibiydik şu hayat tarlasında,

Heyhat! .

Ayağı sekili,gözü sürmeli,

Alnı sakar haşarı tay gibiydik! .

Durup/dinlenmek nedir ki,

Yorulmak nedir; 

Bilmezdik nicedir.

Ve adeta bir çelik yay gibiydik.

Heyhat! .

Sığmazdık kabımıza/kabuğumuza,

Heyecanlıydık.

Kalaycı körüğünden farksızdı yüreğimiz,

Patlamaya hazır volkan gibiydik,

Beyine sıçrayan kan gibiydik,doğrusu! .

Tabir-i caizse eğer; 

Çiçeği burnunda delikanlıydık.

Heyhat! .

Düşünce ufkumuz/tahayyülümüz,

Sonsuza açılan kapıydı sanki! .

İhtilal yapardık sıfır-üç sularında,

Ay ışığında.

Devlerin uykuya daldığı anda; 

Vira kamçılanan cesaretimiz,

Göğsümüzde kargir yapıydı sanki.

Heyhat! .

Biz idik Zaloğlu Rüstem,evet! .

Şah-ı Merdan Ali biz idik ahey.

Ya öyle inanırdık,

Yada kendimizi öyle sanırdık.

Dik bakışlı aslanların yatağı,

Yiğitlerin merkez üssü otağı; 

Köroğlu''nun çamlıbeli biz idik ahey! .

Şahbazları gözünden/gölgesinden tanırdık,

Heyhat! .

Sonunda anlaşılan,görünen vechesiyle,

Hazin ve gerçek olan; 

Silüetten ibaretmiş o netameli hayat! .

Gayrısı yalan.

Ömür yıldızımız kaymak üzere,

Tadı yok böylece bitkisel yaşamanın; 

Hava kirli,ekmek küflü,su bayat.

Hasılı gidipde dönmeyenlerin; 

Bizde gideceğiz,gittiği yere,

Heyhat! .', 'Anafor gibiydik gönül tasında, Gençliğimiz,bizden farımadan önce. Çiğ düşerdi üstümüze şafakta, Bağrımıza deli rüzgar eserdi, Sararıp kuruma...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Süreyya Durna']::text[], 8.5, '{"poet":"Ahmet Süreyya Durna","poet_slug":"ahmet-sureyya-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/genclik-efsanesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldin', 'hosgeldin-ozge-torun-pxbwb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşamadım senden önce,

Yaşam denen şu kargaşada

 Kendimi kaybettim,

Görmeden aradım seni kalbimle

Ruhum bana rehber oldu

Seni çıkardı karşıma

Hoş geldin gecemin efkarı

Hoş geldin bağlamanın teli

Hoş geldin türkümün en sevdiğim yeri

Hoş geldin…', 'Yaşamadım senden önce, Yaşam denen şu kargaşada  Kendimi kaybettim, Görmeden aradım seni kalbimle Ruhum bana rehber oldu Seni çıkardı karşım...', ARRAY['Türk Edebiyatı','Şiir','Özge Torun']::text[], 8.5, '{"poet":"Özge Torun","poet_slug":"ozge-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hosgeldin-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayan Asma', 'aglayan-asma-alper-kuruk-n8m90', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vaktiyle bir asma vardı

Küçücük kulübenin önünde.

Yeşildi,körpeydi önce...

Koruğunu mahalle çocukları çalardı.

Salkım salkım üzümlerini yiyen 

Evdeki lâf anlamazlardı.

Her sene gittikçe azaldı

Yiyecekleri üzüm,

Birgün geldi vermez oldu

Artık bir yaprakcık bile...

Ana bir taraftan üzgün

Eksik oldu sofradan 

Nefis yaprak sarması,

Vermediğinden şimdiye dek

Taze yaprağa para

Baba üzgün öte yandan.

Kestiler orasından,burasından...

Geçerken bir sabah baktım

Kesik yerlerinde su damlacıkları vardı

Sandım asma ağladı...', 'Vaktiyle bir asma vardı Küçücük kulübenin önünde. Yeşildi,körpeydi önce... Koruğunu mahalle çocukları çalardı. Salkım salkım üzümlerini yiye...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aglayan-asma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Ben Ona Vuruldum', 'i-ste-ben-ona-vuruldum-ozge-torun-x793i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ruhunun inceliği varya,

 Kalbiminin sıcacıklığı

 İşte ben ona vuruldum

Mavi gözlerinin derin bakışı

İnsanı kendinden alması,kalbine işlemesi

İşten ben ona vuruldum,

Soruyorsun bana bende ne buldun? 

Sende kendimi buldum Sevgilim

Mavi gözlerinde mutluluğu, sevinci

Tertemiz kalbinde aşkı buldum

İşte ben bunların hepsine vuruldum

Korkmadan,utanmadan tüm kalbimle söylüyorum

SENİ ÇOOOOOOOOOK SEVİYORUM', 'Ruhunun inceliği varya,  Kalbiminin sıcacıklığı  İşte ben ona vuruldum Mavi gözlerinin derin bakışı İnsanı kendinden alması,kalbine işlemesi...', ARRAY['Türk Edebiyatı','Şiir','Özge Torun']::text[], 8.5, '{"poet":"Özge Torun","poet_slug":"ozge-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/iste-ben-ona-vuruldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam', 'sevdam-ozge-torun-rv4xm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevda vadisinde ki  aşk denen çöl de

Yar denizimi arıyorum.

Olmuşum bit acemi kaptan 

Denizde salımla seni arıyorum

Mürettebatım tutkum,

Dümenim kokun

Kendimi arıyorum

Buldum buldum buldum.

Senden önce yaşanmadım 

Senle başladım…', 'Sevda vadisinde ki  aşk denen çöl de Yar denizimi arıyorum. Olmuşum bit acemi kaptan  Denizde salımla seni arıyorum Mürettebatım tutkum, Düm...', ARRAY['Türk Edebiyatı','Şiir','Özge Torun']::text[], 8.5, '{"poet":"Özge Torun","poet_slug":"ozge-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevdam-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geriye Kalan', 'geriye-kalan-murat-tali-npuel', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kırılma noktasından içre olur sevdalar.

Kanar, 

düşülen yerdeki acıların toplamı.

hücresel bölünmeler yaşar insan denen canlı

ve 

aşk olur 

can can içindeyken.

yol uzun,

gidilecek yerler ise 

yürek çağrısı mesafelerde

iki kişi doğar ve iki kişi ölür içerde

bize kalan bir demet gül olur.', 'kırılma noktasından içre olur sevdalar. Kanar,  düşülen yerdeki acıların toplamı. hücresel bölünmeler yaşar insan denen canlı ve  aşk olur  ...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/geriye-kalan-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'I was seven years of age (Deneme)', 'i-was-seven-years-of-age-deneme-mikdat-bal-soym8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'I was seven years of age 

I went to the zoo,and i had seen a cage 

There was  sitting a black body,

and was eating a banana 

I wanted to talk with him 

I Bend down and looked in 

My mother began to cry 

I thought it is now good-bye 

Father said: you stupid wife 

Don’t play with our son’s life 

Don’t agitate the monkey! 

Don’t be a silly donkey! 

I heard everything he said 

And then, I felt,I was dead 

So, I began with crying 

And was not trying anything

Than the monkey looked at me 

As if he was saying, forget me 

He took me up to the air 

I was hanging on his hair 

He gave me to my father 

As if there was not any matter 

The police said: keep off please! 

No one could believe it 

There was not  any harm  done to me

Tercümesi

Yedi yaşında idim

Hayvanat bahçesine gittim

Siyah bir adam gördüm, oturuyordu

Bir muz yiyordu

Onunla konuşmak istedim

Eğildim içine düştüm

Annem bağırmaya başladı

Ben ise sonumun geldiğini zannettim

Babam dedi ki: aptal karı

Çocuğun hayatıyla oynama! 

Maymunu kızdırma! 

Ahmak bir eşek olma

Dediği her şeyi duydum

Öldüğümü zannettim

Dolayısıyla ağlamaya başladım

Ve hiç bir şey denemiyordum

Sonra maymun bana baktı

Sangi bana beni unut diyordu

Beni alıp havaya kaldırdı

Ben kıllarına yapışıyordum

O beni babama verdi

Sangi hiç bir şey olmamış gibi

Polis dedi ki Lütfen bırakınız onu

Hiç kimse inanamıyordu

Bana hiç bir şey olmadığına', 'I was seven years of age  I went to the zoo,and i had seen a cage  There was  sitting a black body, and was eating a banana  I wanted to tal...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/i-was-seven-years-of-age-deneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lacivert Taçlı Gelin', 'lacivert-tacli-gelin-mehmet-akif-tiryaki-fdwd9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Lacivert Taçlı Gelin

Kartepe beyaz şalını atmış omzuna, 

Bürünmüş kalın kürk mantosuna. 

Fosforlu sarı yapraklarda bitti artık 

Bıraktı yerini kar fırtınasına. 

Sapanca dağlarında Geyve bağlarında 

Bir beyaz gelinlik, 

Soğucak yaylasında. 

Her sene gelin olur bu ulu tepeler, 

Olurda gene yepyeni, mükemmel. 

Yeşil olur, sarı olur, kararır, aklaşır, 

Filiz olur, ağaç olur, koca çınarlaşır. 

Her sene bu mevsimde gelin olur bu tepeler, 

Baharla tekrar meyve verir yemiş ağaçları 

Oksijeni sever, dağ kırlangıçları. 

Sapanca''nın kalbi delen yeşili, 

Ya fosforlu sarı yapraklara ne demeli? 

Çikolata rengi olur kararır, 

Düğün zamanı hepsi biter, aklanır. 

Sapanca''da düğün var dostlar, 

Seyre gelin, 

Alın eliniz bir demet kartopu da 

Siz derin. 

Kartepe beyaz şalını atmış omzuna, 

Bürünmüş kalın kürk mantosuna. 

Akşam olduğunda gölün mavisi 

Vurmuş tacına, 

Lacivert taçlı gelin 

Mor salkımlı bağın nerde? 

Seni seyretmek buram buram 

Çaredir her derde.', 'Lacivert Taçlı Gelin Kartepe beyaz şalını atmış omzuna,  Bürünmüş kalın kürk mantosuna.  Fosforlu sarı yapraklarda bitti artık  Bıraktı yeri...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/lacivert-tacli-gelin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzü', 'gokyuzu-seref-manav-khscv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey gökyüzü! 

Al beni yanına 

Çok mu gelirim enginliğine? 

Duy yalvarışlarımı.

Söz,

İncitmem seni.

Çok şeyde istemem

Biraz maviliğinden, biraz bulut.

Üşüyorum.

Sar beni beyaz yorganına,

Hasretim sıcak dostluklara...

Ey güneş! 

Olur mu sensiz? 

Yetmez sıcaklığı bulutların 

Al beni yanına.

Ey yağmur! 

Nerdesin? 

Pınarlarım kurumuş,

Karaları sar

Aksın gözyaşlarım.

Kurumuş toprağım

Islansın.

Tohumlar filiz,

Filizler başak olsun.

Bu şiir; güzel insan,Dilâşup a  izafeten yazılmıştır', 'Ey gökyüzü!  Al beni yanına  Çok mu gelirim enginliğine?  Duy yalvarışlarımı. Söz, İncitmem seni. Çok şeyde istemem Biraz maviliğinden, bira...', ARRAY['Türk Edebiyatı','Şiir','Şeref Manav']::text[], 8.5, '{"poet":"Şeref Manav","poet_slug":"seref-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gokyuzu-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yedi Renkli Çocuklar', 'yedi-renkli-cocuklar-bahri-yildirim-n1f9g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Onlar  da çocuktular

Yetimdiler Dünyanın gözbebeğinde

Hemde göz göre göre

Herkes  kendi göbeğini kesmelidir

Kimilerine göre.

Dünyanın dört bir köşesinde

Ortak bir kader gibidir kimsesizlik 

Acıdır küçücük yüreğimde benimde.

Onlar da çocuktular

Öncesinde onlarında maviydi düşleri

Çöktü karanlık omuzlarına

Yoksulluk öldürdü

Güllerindeki güzelim kırmızıyı.

Onlara dikenleri bile haramdı güllerin

Yazanlar böyle buyurmuş yazıyı! ! ! 

Onlara göre Dünya yemyeşildi hep

Büyükler el ele verip

Karalar giydirdiler 

Çocukların yeşillerine.

Ve kıydılar gözlerini kırpmadan

Adı bile konmamış milyonlarca bebeye

Onlar da en çok beyazları severdi

Onlar içinde  öyleydi

Umuttu,sevdaydı,gelecekti beyaz

Aşın,ekmeğin,suyun rengi beyazdı

Beyaz atlıların uğrak yerleri olacaktı 

Genç kızların düşleri

 Olmadı, olamadı oysa; 

Bir gün insan olmanın bile

Hesabının sorulduğunu

Beyaz gelinliklerini

Silahlar gölgeleyince anladılar

Ne renktir gözyaşı; 

Ateşe mi çalmalı özgürlüğün rengi? 

Sular karalar mı giymeli? 

Sararıp solmalı mı benzimiz? 

Her korkulu sabahta.

Gerçek yüzü ne renktir barışın? 

Bana onu göster öğretmenim.

Yönümü  ona döndür.

Sararıp solmasın

Hiç bir daldaki yaprak.

Toprağımız kirlenmesin kara lekelerle

Üzülüyorum öğretmenim.

Hüzün veriyor bana

Kahrediyor beni her sabah  her sabah

Umutlarımda mor menekşelerin açmayışı.

Kendi tadında kokmayışı çiçeklerin.

Bunu ancak,sen engellersin öğretmenim.

Biliyor musun  öğretmenim? 

Ben sadece senin bahçende özgürüm.

Sadece sende gerçeğim.

Sadece senleyken

Kendi doğallığında rengim.

Sevginin rengi sensin öğretmenim

Bende bütün Dünyanın 

Küçük çiçeklerinden biriyim.

Elinde tomurcuğunum

Büyürüm yüreğinde

Renkten renge girerim.

Büyüt beni  öğretmenim

Ben de sana  en güzel çiçekleri derip

Yıldızlar toplayıp gökkuşaklarıyla

Yollarına sereyim.

Annem gibi kucağın

Babam gibi ocağın

Sana Dünyanın çiçeklerini  vereyim

Yeter,değil mi öğretmenim! ! !', 'Onlar  da çocuktular Yetimdiler Dünyanın gözbebeğinde Hemde göz göre göre Herkes  kendi göbeğini kesmelidir Kimilerine göre. Dünyanın dört b...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/yedi-renkli-cocuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Ağacı', 'hayat-agaci-sultan-duran-q9c7q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir insan düşünün, yanlız tek başına

Uzaklaşmış insani ilişkilerden

Sevgisizliğe, mutsuzluğa,

Ümitsizliğe,yanlızlığa terketmiş kendini

Sararmış, solmuş tıpkı bir gül gibi

Taşlaşmış kalbi

Aşk denen şeyi görmemiş

Körlenmiş duyguları

Çürümüş yüreği

Unutmuş acımayı

Ve sonunda kurumuş

Yok olmuş hayat ağacı', 'Bir insan düşünün, yanlız tek başına Uzaklaşmış insani ilişkilerden Sevgisizliğe, mutsuzluğa, Ümitsizliğe,yanlızlığa terketmiş kendini Sarar...', ARRAY['Türk Edebiyatı','Şiir','Sultan Duran']::text[], 8.5, '{"poet":"Sultan Duran","poet_slug":"sultan-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayat-agaci-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merak Eyleme', 'merak-eyleme-sultan-duran-e33cq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gurbet diye diye hasret eyleme

Yüreğine köz koyup ateş eyleme

Üzüntüme üzüntü katıp figan eyleme

Gözyaşlarına boğulup sel eyleme

Umut ellerinde kendine dert eyleme

Yaralayıp kendini harap eyleme

Ayrılığı besteleyip hitap eyleme

Uzak diyarlarda keder eyleme

Düşünme beni merak eyleme', 'Gurbet diye diye hasret eyleme Yüreğine köz koyup ateş eyleme Üzüntüme üzüntü katıp figan eyleme Gözyaşlarına boğulup sel eyleme Umut elleri...', ARRAY['Türk Edebiyatı','Şiir','Sultan Duran']::text[], 8.5, '{"poet":"Sultan Duran","poet_slug":"sultan-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/merak-eyleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmaz Olsun', 'olmaz-olsun-sultan-duran-gmjgu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kin nefret hakimse bu koca dünyada

Düşünmek delilikse susmak acizlik

sararıp solmaksa bu güneşsizlik

İstemem olmaz olsun böyle insanlık

Eğer direnmekse ayakta kalmak

Özgürlük çabalamaksa bu hayatta hapislik

Tutsak olmaksa evrende tabiatsızlık

İstemem olmaz olsun böyle insanlık

Hep ezilmekse hayattan beklentilerimiz

Bir karınca kadar küçük olmaksa çaresizlik

Yaşamak haram ölüm kurtuluşsa sonsuzluk

İstemem olmaz olsun böyle insanlık', 'Kin nefret hakimse bu koca dünyada Düşünmek delilikse susmak acizlik sararıp solmaksa bu güneşsizlik İstemem olmaz olsun böyle insanlık Eğer...', ARRAY['Türk Edebiyatı','Şiir','Sultan Duran']::text[], 8.5, '{"poet":"Sultan Duran","poet_slug":"sultan-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olmaz-olsun-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umuda Çağrı', 'umuda-cagri-sultan-duran-n2ghg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sen varsın bir de ben

Sevgi var, hasret ve özlem

Işıksız bir ümit solgun ve üzgün

Sızlatır kalbimi derinden ve suskun

Bir resmin var bir de elbisen

Sarılır koklarım gözyaşlarımla hergün yeniden

Yaşamak isterim geçmişi yeniden

Haykırmak isterim gönlüm ferman dinlemezken

Hayat anlamsız geçse hüzün kalsa yüreğimde

Kalp teklemeye başlasa buruk ve küskün

Yaşamaya mecali kalmasa sabrı vücudun

Kelimeleri tüketse ömrüm baharım', 'Bir sen varsın bir de ben Sevgi var, hasret ve özlem Işıksız bir ümit solgun ve üzgün Sızlatır kalbimi derinden ve suskun Bir resmin var bir...', ARRAY['Türk Edebiyatı','Şiir','Sultan Duran']::text[], 8.5, '{"poet":"Sultan Duran","poet_slug":"sultan-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umuda-cagri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varsın', 'sen-varsin-sultan-duran-y94tb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akan her göz yaşımda 

Yüreğimin her sızısında

Kalbimin her atışında 

Sen varsın

Oynadığım mutluluk oyununda

Şarkılarda türkülerde

Neşemde üzüntümde 

Sen varsın

Benliğimde arzularımda

Duygularımda acılarımda

Yaşadığım her anımda 

Sen varsın', 'Akan her göz yaşımda  Yüreğimin her sızısında Kalbimin her atışında  Sen varsın Oynadığım mutluluk oyununda Şarkılarda türkülerde Neşemde üz...', ARRAY['Türk Edebiyatı','Şiir','Sultan Duran']::text[], 8.5, '{"poet":"Sultan Duran","poet_slug":"sultan-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-varsin-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemim', 'ozlemim-sultan-duran-5806a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Özlem dolu günler çok olsa da

Gözlerim pınar olup ağlasa da

Yüreğim isyankar olsa da

Hep senin dönmeni bekleyeceğim

Senin hasretinle yansa da yüreğim

Senin yokluğunla kaybolsa da benliğim

Patlamaya hazır volkan olsa da gönlüm

Hep senin dönmeni bekleyeceğim', 'Özlem dolu günler çok olsa da Gözlerim pınar olup ağlasa da Yüreğim isyankar olsa da Hep senin dönmeni bekleyeceğim Senin hasretinle yansa d...', ARRAY['Türk Edebiyatı','Şiir','Sultan Duran']::text[], 8.5, '{"poet":"Sultan Duran","poet_slug":"sultan-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozlemim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Ekmek Çarpsın Alışkanlık', 'ekmek-carpsin-aliskanlik-mehme-arslan-6qgy0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ne olur kızma

yerden kaldırdıktan sonra

seni dudağından öptüğüm için

bizde âdettendir

yere düşen nimet

hemen kaldırılıp üç defa öpülür

22/11/2005', 'ne olur kızma yerden kaldırdıktan sonra seni dudağından öptüğüm için bizde âdettendir yere düşen nimet hemen kaldırılıp üç defa öpülür 22/11...', ARRAY['Türk Edebiyatı','Şiir','Mehme Arslan']::text[], 8.5, '{"poet":"Mehme Arslan","poet_slug":"mehme-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ekmek-carpsin-aliskanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Misafir Olduğum Kalbinden Göçüyorum', 'misafir-oldugum-kalbinden-gocuyorum-i-lknur-er-g3yam', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyor üzerime

Kaçıyorum sığınaklara bir başıma

Avuçlarım acıyor sensizlikte

Gözlerimde yaşlarım asılı kalmış

Nicedir hasret türküleri ezberimde

Her gün biraz daha kendime dönüyorum

Yağmur yağıyor üzerime

Her bir damla sen ol istiyorum

Yağ üzerime sırılsıklam et

Ne zaman gökyüzüne baksam

Yıldızlar gözlerini hatırlatır 

Öyle parlak öyle canlı öyle içten

Ve kahretsinki öyle uzak

Yağmur yağıyor üzerime

Ellerim acıyor sensizlikten 

Gölgem kayboluyor kaldırımlarda

Kendimdende geçiyorum öylesine

Adım adım gidiyorum bu şehirden

Misafir olduğum kalbinden

Göçüyorum bu gece

22.11.2005 / 19:58', 'Yağmur yağıyor üzerime Kaçıyorum sığınaklara bir başıma Avuçlarım acıyor sensizlikte Gözlerimde yaşlarım asılı kalmış Nicedir hasret türküle...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/misafir-oldugum-kalbinden-gocuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sobe', 'sobe-i-lknur-er-fodmt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gece sabaha dönerken

Bende rabbime dönsem

Küsse bu dünyaya tenim

Sonra misafir gelsem

Sobelesem

Sahtelikleri

22.11.2005 20:00', 'Bu gece sabaha dönerken Bende rabbime dönsem Küsse bu dünyaya tenim Sonra misafir gelsem Sobelesem Sahtelikleri 22.11.2005 20:00...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sobe-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu''ya Doğru', 'anadolu-ya-dogru-mehmet-ali-kalkan-2xo1n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Toprak ile akt''olanda,

Tohumlar ağaca döner.

Hal ehline vakt''olanda,

Hedefler kıskaca döner.

Beklenirken kutlu doğum,

Birliğe varmalı çoğum,

Söz odur ki dokuz boğum,

Dil üstünde hece döner.

Olan yaşanır zamanda,

Etraf görünmez dumanda,

Gece olmaz göz yumanda,

Gün üstüne gece döner.

Gülünmez öksüz gülmeden,

Yol bulunmaz gidilmeden,

Değirmen döner bilmeden,

Un,hamurdan saca döner.

Sabır beklerken gününü,

Rahmet ışıtır önünü,

Anadolu''ya yönünü,

Yesi''den bir Koca döner...', 'Toprak ile akt''olanda, Tohumlar ağaca döner. Hal ehline vakt''olanda, Hedefler kıskaca döner. Beklenirken kutlu doğum, Birliğe varmalı çoğum,...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kalkan']::text[], 8.5, '{"poet":"Mehmet Ali Kalkan","poet_slug":"mehmet-ali-kalkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anadolu-ya-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülün Derdi...', 'gulun-derdi-kasim-kaplan-tvb35', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül yaram bugün gene kanadı,

Acizim hiçbir şey gelmez elimden.

Gün be gün yerleşti o yarin adı,,

İz yaptı gönlümde, düşmez dilimden.

Bağban geldi ayrı kaldım gülümden,

Bir saat, bir hafta yıl gibi gelir.

Kaç fırtına delip geçti gönlümden.

Saymaya takat yok, bir Mevla bilir.

Gül mahzun her zaman, başı önünde,

Bülbül etrafında pervane onun.

Gülün beklediği, vuslat gününde,

Bayraktarı odur aşkın yolunun.

Bir mızrak kalınca sabah olmaya,

Şafak feyizlenir ondaki renkten.

Dirhem dirhem ondan ışık almaya,

Sıra sıra iner yıldızlar gökten.

Gecenin hüznünden eğilir başı,

Sis, duman, karanlık çöker hep birden.

Olur çiğ tanesi  gülün gözyaşı,

Konar yaprağına sabah erkenden.

Ağlar her seherde, çeker virdini,

Güneşe rengini veren ışıktır. 

Kim bilir ki onun asıl derdini,

Bülbül ona, gül Resule âşıktır.', 'Gönül yaram bugün gene kanadı, Acizim hiçbir şey gelmez elimden. Gün be gün yerleşti o yarin adı,, İz yaptı gönlümde, düşmez dilimden. Bağba...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kaplan']::text[], 8.5, '{"poet":"Kasım Kaplan","poet_slug":"kasim-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gulun-derdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakız Arıyorlar', 'sakiz-ariyorlar-ramazan-ates-dxt7n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adını soruyorlar sevdiğim,

Söylemem, sırdır bende.

Kimmiş gönül verdiğim? 

Söyleyemem, sırdır bende.

Niye sevdin güzel midir? 

Senin için özelmidir? 

Oda seni severmidir? 

Söyleyemem, sırdır bende.

Gözü kara mı? Ela mı? 

Saçı sarı mı? Kumral mı? 

Bize uzak mı? Yakın mı? 

Söyleyemem, sırdır bende.

Ne iş yapar? Yaşı kaçtır? 

Uzun, kısa, zayıf, tombul? 

Görüştün mü? Onla bol bol? 

Söyleyemem, sırdır bende.

Neyi sever?  Neden anlar? 

Şarkı, türkü neyi dinler? 

Nasıl giyer özel günler? 

Söyleyemem, sırdır bende.

Sorular, hep bu sorular,

Niye sorar? Kime yarar? 

Diline sakız ararlar,

Söyleyemem, sırdır bende.

Ramazan Ateş/Enschede-22.11.2005', 'Adını soruyorlar sevdiğim, Söylemem, sırdır bende. Kimmiş gönül verdiğim?  Söyleyemem, sırdır bende. Niye sevdin güzel midir?  Senin için öz...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sakiz-ariyorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babamın Ardından', 'babamin-ardindan-salim-erben-k014q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim babam öldü

Başın yayla, Çifte pınar

Kendi gelemedi

Ben geldim helallık almaya

Selam söyledi kurda kuşa

Karıncadan bal arısına

Keyiş beleni, Çamrak

Kıble pınar,Fırınlı Beşallı

Benim babam öldü anlıyormusun

Akpınar söğütçük

Bir daha gelemeyecek 

Bu topraklara

Ne suyundan içecek 

Nede fındıçak tan geçecek 

Benim babam öldü artık

Güneş toprağa düşerken

Helal edin hakkınızı

Kır çiçeği yaban gülü

Tutamayacak sevemeyecek sizleri

Batırıp tenine sayamadığı 

Dikenlerini ey ısırgan otu 

Ayakkabı içinde parmakları 

Kül kurusu dudaklarından 

Ateşten bir buse gibi

kor düşmeyecek bağrına 

Yanmayacak içi ırgatlık tarlasında

Benim babam öldü

Dağlar taşlar uçan kuşlar

Helal edin hakkınızı

Sevmezdi hiç ağlayanı

Ölümün yüzü soğuktur derdi yüreklim 

Nar çiçeği tadında yaşlanmak 

Ölüm karanfil ölüm gelincik

Bir o kadar da yalan dünya 

Çözül ey dilimin suskusu 

İçime sığmayan çığlığım 

Suyunu alan ham çelik gibi 

Bu yüzden dil suskun

Gözler kuru unutulur mu hiç

Akçakışlanın yolu', 'Benim babam öldü Başın yayla, Çifte pınar Kendi gelemedi Ben geldim helallık almaya Selam söyledi kurda kuşa Karıncadan bal arısına Keyiş be...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/babamin-ardindan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlediğim ölüme An Kala', 'ozledigim-olume-an-kala-belgin-erturk-t14hw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Alıp sırtıma sevdamı 

Bir uçurum kenarından 

Bırakıverdim kendimi 

Özlediğim ölüme an kala 

Bırakıpta bedenimin yarısını, 

Bıçak sırtı kayalarda 

Kan revan içinde buluştum tıoprakla 

Özlediğim ölüme an kala 

Artık ne acı vardı yüreğimde 

Nede yükünü çekemediğim sevdam yanımda 

Ne canım yandı, nede geriye bakacak halim vardı 

Özlediğim ölüme an kala 

Önce siyah saçları geldi aklıma 

Sonra vefasız bakan gözleri 

Sonrada..... 

Belkide sonsuza kadar seni sevemiyeceğim, 

sevemiyeceğim seni diye yazan o elleri 

Özlediğim ölüme an kala... 

06.11.2005', 'Alıp sırtıma sevdamı  Bir uçurum kenarından  Bırakıverdim kendimi  Özlediğim ölüme an kala  Bırakıpta bedenimin yarısını,  Bıçak sırtı kayal...', ARRAY['Türk Edebiyatı','Şiir','Belgin Erturk']::text[], 8.5, '{"poet":"Belgin Erturk","poet_slug":"belgin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ozledigim-olume-an-kala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Belledim', 'yaz-belledim-mehmet-ali-kalkan-hik5j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'At,yiğitin kanatıydı,

Mevsimleri yaz belledim.

Af,zaferin zekatıydı,

Affetmeyi haz belledim.

Bildim Hakk''ın güneşini,

Takip ettim hep peşini,

Ergenekon ateşini,

Gönlümdeki köz belledim.

Günü geldi düştüm dara,

Yakın baktım uzaklara,

Dünya iki hükümdara,

Çok gelirdi,az belledim.

Koparmadım gül domuru,

Aşkla yoğurdum hamuru,

Hira''lardan yağan nuru,

Dünya dünya öz belledim.

Devlet toprakla insandı,

Toprak benimle vatandı,

Güç aldığım Yaratan''dı,

Yokuşları düz belledim.

Rahmet idi bana yağan,

Adaletti zulmü boğan,

Niğbolu''da ''''Bre Doğan''''

Yıldırım''ca söz belledim.

Susayan arardı suyu,

Kevser buldum kuyu kuyu,

Uyumayan Devletluyu,

Gecelerde göz belledim.

Keşke dedim olmasaydı,

Beni vuran Han Giray''dı

Son durağım Viyana''ydı,

Oraları güz belledim.

Vurduğunu duya duya,

Ok elbet uyacak yaya,

Kızılelma muradım ya! 

Sevdaları hız belledim...', 'At,yiğitin kanatıydı, Mevsimleri yaz belledim. Af,zaferin zekatıydı, Affetmeyi haz belledim. Bildim Hakk''ın güneşini, Takip ettim hep peşini...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kalkan']::text[], 8.5, '{"poet":"Mehmet Ali Kalkan","poet_slug":"mehmet-ali-kalkan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yaz-belledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Zamanlar Ankara', 'bir-zamanlar-ankara-ruya-deniz-demir-b3ml5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar sevdiğim bu şehir artık bana dar geliyor

Bir zamanlar sevdiğim o kadar artık çekip gidiyor

Bir zamanlar uğruna kavga ettiklerim beni sevmiyor

Bir zamanlar beni sevenler ise artık selam vermiyor…

Bir zamanlar yarınlarını düşündüklerim

Bir zamanlar hikayelerini yazdıklarım

Bir zamanlar gecelerine ışık olduklarım

Bir zamanlar uğruna yandıklarım

Artık çok geç beni hiç tanımıyor…

Zaman kusurlu yarınlara dönüştüğünde

Elleri birbiri ardına ayrıldığında

Ve sevgiler artık bitmeye başladığında

Gözler tavana bakmaya başladığında

Bu şehir artık çöl oluyor

Ve kimse birbirini tanımıyor…

Ve korkarım gerçek oluyor

Bir zamanlar yazdıklarım

Düşlerimde yaşadıklarım

Uğruna ağladıklarım

Ve asla gelmesin diye andıklarım

Bir bir bu şehre geliyor…

Bir zamanlar atandığım

Bir zamanlar yalnızlığım

Bir zamanlar şarkılarım

Bir zamanlar aşklarım

Şimdi bir bir ölüyor…

Yalan makamına dönüyor her şey

Bütün trenler son kez kalkıyor

Biri acele edin diye bağırıyor

Sanırım bu istasyon da artık kapanıyor…

Gözlerimin ıslaklığına sebep çocuklar

Çocukluğumun emaneti aşklar

Okuduğum bütün romanlar

Hepsi şimdi hayal oluyor

Bu şehir de benim gibi son demini yaşıyor…', 'Bir zamanlar sevdiğim bu şehir artık bana dar geliyor Bir zamanlar sevdiğim o kadar artık çekip gidiyor Bir zamanlar uğruna kavga ettiklerim...', ARRAY['Türk Edebiyatı','Şiir','Rüya Deniz Demir']::text[], 8.5, '{"poet":"Rüya Deniz Demir","poet_slug":"ruya-deniz-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bir-zamanlar-ankara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Jandarma Marşı', 'jandarma-marsi-kasim-kaplan-nabri', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Jandarma erleriyiz, Türkiye mekânımız 

Gece gündüz demeden, hep tetikte dururuz

Gerekirse ölürüz, sağ olsun vatanımız 

Her karışı kutsaldır canla başla koruruz      

Mevsim bizden yanadır, dost olmuşuz soğukla 

Sıcak soğuk demeden hep eğitim yaparız. 

Daha güneş doğmadan biz doğarız şafakla, 

Adım adım, her yere, ismimizi yazarız. 

Yorulmak ne bilmeyiz, yollar kısalır bize. 

Bir kez yola çıkınca, dur denmeden durmayız. 

Herkes rahat uyusun, bir sözümüz var size, 

Nöbette bekliyoruz, ölsek de oturmayız. 

Yağmur gibi yağarız, akarız ırmaklarda.

Ay, yıldız yol gösterir, dağlar bize yol verir. 

Şehitlerin kanıyla sulanmış topraklarda.

Kar buz kar etmez bize, bastığımız yer erir 

Poyrazdan kanatlarla, rüzgâr ile eseriz. 

Bizimle huzurludur cennet gibi bu vatan

Karıncanın izinden tehlikeyi sezeriz., 

Ölüme de gideriz emrederse Komutan 

Yılmayız, yorulmayız eğitimdir gıdamız. 

Yüreklerde taht kurmuş, sevdası bu vatanın. 

Yeri göğü inletir, marş söylerken sedamız, 

Yolunda, izindeyiz Büyük Önder Ata''nın.', 'Jandarma erleriyiz, Türkiye mekânımız  Gece gündüz demeden, hep tetikte dururuz Gerekirse ölürüz, sağ olsun vatanımız  Her karışı kutsaldır ...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kaplan']::text[], 8.5, '{"poet":"Kasım Kaplan","poet_slug":"kasim-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/jandarma-marsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapı', 'kapi-erhan-demir-d05hn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne anılarımız oldu birlikte

Ne günler geçirdik biz

Çürüttük o genç yılları

Yaşatıldık ikimiz.

Kimi zama neşeli,

Kimizaman kederli,

Karşılıyordun beni.

Bazen açılıp, bazen kapanıyordun,

Yorgunluğumu alıyordun.

Evin boş köşelerinde,

Bazen gıcırtılarını duyuyordum. 

O da yeterdi yalnızlığımıza hani; 

Aşk adını duyurunca zorla alırdım içeri 

Hatırlıyor musu? 

Şimdi ise artık dışardayım,

Yalnız ve avareyim. 

Al beni içeri al ne olursun.

Titriyorum, üşüyorum,

Duyuyor musun? ..', 'Ne anılarımız oldu birlikte Ne günler geçirdik biz Çürüttük o genç yılları Yaşatıldık ikimiz. Kimi zama neşeli, Kimizaman kederli, Karşılıyo...', ARRAY['Türk Edebiyatı','Şiir','Erhan Demir']::text[], 8.5, '{"poet":"Erhan Demir","poet_slug":"erhan-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kapi-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hak terazi Doğru Tartar', 'hak-terazi-dogru-tartar-mehmet-ali-kalkan-elsoa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hak terazi doğru tartar,

Alabilsen mallar senin.

Sevgi paylaştıkça artar,

Sarılan ol,kollar senin.

Kimi yalan kimi gerçek,

Kimi kuru,kimi gökçek,

Gel dolanma çiçek çiçek,

Kovanı bul ballar senin.

Kimileri ham kalırlar,

Kimileri kam alırlar,

Kimiler makam alırlar,

Hedef bir''se yollar senin.

Hamur mayayla karılır,

Yara beraber sarılır,

Dal tutarsan dal kırılır,

Ağacı tut dallar senin.

Birleşende alay olur,

El tutanda halay olur,

Sabırla zor kolay olur,

Sözünü bil diller senin.

Varım deme yokuna bak,

Uzak dursun yakına bak,

Otu çek de köküne bak,

Hükmettiğin eller senin...', 'Hak terazi doğru tartar, Alabilsen mallar senin. Sevgi paylaştıkça artar, Sarılan ol,kollar senin. Kimi yalan kimi gerçek, Kimi kuru,kimi gö...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kalkan']::text[], 8.5, '{"poet":"Mehmet Ali Kalkan","poet_slug":"mehmet-ali-kalkan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hak-terazi-dogru-tartar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Dönüm Sarhoşluğu', 'gun-donum-sarhoslugu-kasim-kaplan-vaj4n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün dönüm sarhoşluğu 

Sarınca benliğimi

Bir kızıllık hırpalar

 Bu suskun yüreğimi

Emdiğim mavilikler 

Siyaha dönüşürken

Küf kokulu yosunlar 

Ancak anlar derdimi

Gelinlik giymiş martı

 Taşıyıp hayalini

Binler daha söyletir

 Seni çok sevdiğimi…

Nerden bileceksin ki, böyle sevildiğini

Bir nihan sevgiliye ölüp dirildiğimi', 'Gün dönüm sarhoşluğu  Sarınca benliğimi Bir kızıllık hırpalar  Bu suskun yüreğimi Emdiğim mavilikler  Siyaha dönüşürken Küf kokulu yosunlar ...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kaplan']::text[], 8.5, '{"poet":"Kasım Kaplan","poet_slug":"kasim-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gun-donum-sarhoslugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Gitmeyi Bildik Nede Kalmayı', 'ne-gitmeyi-bildik-nede-kalmayi-fatih-demir-rcp69', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gitmeni de istemedim kalmanı da. 

Gitmen de tüketti yüreğimi kalman da. 

Varlığında yokluğuna; yokluğunda varlığına ağlattın. 

Hiç ortası olmadı bu aşkın.

Sevdin mi? Sevmedin mi? 

Birleştik mi? Ayrıldık mı? 

Ben Hiç bilemedim...

Hep iki ayrı noktadaydık biz. 

Baharda varsan güzde yoktun. 

Dilde varsan sözde yoktun.

Hiç ortası olmadı bu aşkın.

Ne başı oldu bu aşkın ne sonu. 

Ne gitmeyi bildin nede kalmayı.

Ne gecesi oldu bu aşkın ne de sabahı. 

Ne güneşi bildik ne de ayı. 

Çok tökezledik biz bu aşkta. 

Ne düşmeyi bildik ne kalkmayı.

Hep eksikti bu aşkın bir yarısı

Ben geldikçe sen, sen geldikçe ben kaçtım. 

Oysa biz ne kalmayı bildik ne de kaçmayı..', 'Gitmeni de istemedim kalmanı da.  Gitmen de tüketti yüreğimi kalman da.  Varlığında yokluğuna; yokluğunda varlığına ağlattın.  Hiç ortası ol...', ARRAY['Türk Edebiyatı','Şiir','Fatih Demir']::text[], 8.5, '{"poet":"Fatih Demir","poet_slug":"fatih-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ne-gitmeyi-bildik-nede-kalmayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumhuriyet Kuruldu', 'cumhuriyet-kuruldu-kasim-kaplan-v3udn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıl, bin dokuz yüz yirmi üç, karanlığın zirvesi 

Ensemizde hainler ve düşmanın nefesi. 

Erzurum’un dadaşı, İzmir’imin efesi 

Toplandı bir bedende, kuruldu Cumhuriyet. 

Hani bulutlu gökte birden şimşek çakar ya! 

O zifiri karanlık birden aydınlanır ya! 

Hani kurak bir yazda, birden yağmur yağar ya! 

İşte öyle sevinçle kuruldu Cumhuriyet 

Bu öyle bir ışık ki bir daha sönmeyecek, 

Bu yola baş koyanlar, geriye dönmeyecek. 

İlelebet sürecek, bu sevda dinmeyecek 

Şehit ve gazilerle kuruldu cumhuriyet. 

Emanettir gençliğe Atam böyle söyledi 

Canınız pahasına onu koruyun dedi. 

Gençlik bir cevap verdi, yerler gökler inledi. 

Böylesi yiğitlerle kuruldu cumhuriyet. 

Atam sen müsterih ol, biz senin izindeyiz. 

Mukaddes emanete bir zarar verdirmeyiz. 

Canımızı verir de bundan geri dönmeyiz. 

Böyle büyük sevgiyle kuruldu cumhuriyet', 'Yıl, bin dokuz yüz yirmi üç, karanlığın zirvesi  Ensemizde hainler ve düşmanın nefesi.  Erzurum’un dadaşı, İzmir’imin efesi  Toplandı bir be...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kaplan']::text[], 8.5, '{"poet":"Kasım Kaplan","poet_slug":"kasim-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cumhuriyet-kuruldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğul', 'ogul-mehmet-ali-kalkan-2rtwx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gündüzler güneşin tapulu mülkü,

Geceler içinde belli ay oğuli

Töreyle yaşanır her kutlu ülkü,

Kensini bil,atanı bil,say oğul.

Bildin mi kısalır nice mesafe,

İncisi yok ise bakma sedefe,

Ok olanlar gönderilir hedefe,

Amma elde tutulanda yay oğul.

Bilmez misin yel kayadan ne alır? 

Gayesiz ne uzar,ne de kısalır,

Bin kamıştan belki biri ney olur,

Onu da ustası çalar hay oğul.

Elbette olmaya zamanlar vardır,

Kuyuda olana gökyüzü dardır,

Bilene alemler nokta kadardır,

Al kendine sen de ondan pay oğul.

Bırak örümcekler kursun ağını,

Bak ki dua dua yeşert bağını,

Ummanlar sessizce yaşar çağını,

Sesli sesli ona gelen çay oğul.

Sen ki gülsün,gönlün gülsün,yüz gülsün,

Yıllar sonra yaptıkların öğülsün,

Koy nefsini örs üstüne dövülsün,

Dövülmezse vay ki sana vay oğul...', 'Gündüzler güneşin tapulu mülkü, Geceler içinde belli ay oğuli Töreyle yaşanır her kutlu ülkü, Kensini bil,atanı bil,say oğul. Bildin mi kısa...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kalkan']::text[], 8.5, '{"poet":"Mehmet Ali Kalkan","poet_slug":"mehmet-ali-kalkan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ogul-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumhuriyet', 'cumhuriyet-kasim-kaplan-bcdnn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Fırtınalı o günler, bulutluydu gökyüzü,

Dünya umutlanmıştı, Osmanlı çok hastaydı.

Vatansever Türklerin, gülmez olmuştu yüzü,

Güneş çoktan tutulmuş ve yıldızlar yastaydı.

Türklerin karşısında iki kat eğilenler,

Yeniden baş kaldırdı, saldırdı pes edenler.

Karıştı Osmanlının gecesiyle gündüzü,

Utansın o günlerde oturup seyredenler.

İşgalci müstevliler, paylaştı yurdumuzu,

Topladı silahları, dağıttı ordumuzu.

Yurduma yönelmişti düşmanın dönmüş gözü,

Çakallar çevirmişti bu hasta kurdumuzu.

Bir aslan doğdu kurttan, mavi göz, sarı yele,

Daldı vahşi sürüye olanca heybetiyle.

Çeliktendi yüreği, cevherdi onun özü,

Zafer zafer dolaştı ardında milletiyle.

Kahretti düşmanları, canlandırdı milleti,

Başşehir Ankara''da yeniledi devleti.

Işıktı onun yolu, yere düşmedi sözü,

Ve Millet Meclisinde kurdu Cumhuriyeti.

Bayram edin çocuklar hakkınız bayram sizin,

Bu gün en kutlu günü, bayramı ülkemizin…

Ay yıldızlı bayraklar mavi semanın süsü,

Sonsuza dek başlarda tacıdır hepimizin.

Cumhuriyet  ulaştı bizlere bin çileyle,

O kahraman ordumuz birleşti milletiyle.

Artık mahzun değiller şehidi ve gazisi,

Yaşasın Türk Milleti bu yüce devletiyle.', 'Fırtınalı o günler, bulutluydu gökyüzü, Dünya umutlanmıştı, Osmanlı çok hastaydı. Vatansever Türklerin, gülmez olmuştu yüzü, Güneş çoktan tu...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kaplan']::text[], 8.5, '{"poet":"Kasım Kaplan","poet_slug":"kasim-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/cumhuriyet-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi mutlu yağmurlar', 'simdi-mutlu-yagmurlar-oguz-kagan-mirzabeyoglu-qrgqx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dayanamadın,çıktın artık

Seni sakladığım derinliklerden

Işık yağıyor,şimdi mutlu yağmurlar

Kan sızan tebessümüne...

Öyle yitiksin ki

Alıp götürebilirsen beni ve hayatımı

Ardımızda ne bu akşam

Ne de kan sızan tebessümün...', 'Dayanamadın,çıktın artık Seni sakladığım derinliklerden Işık yağıyor,şimdi mutlu yağmurlar Kan sızan tebessümüne... Öyle yitiksin ki Alıp gö...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Kağan Mirzabeyoğlu']::text[], 8.5, '{"poet":"Oğuz Kağan Mirzabeyoğlu","poet_slug":"oguz-kagan-mirzabeyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/simdi-mutlu-yagmurlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Taarruz, Zafer Muştusu', 'buyuk-taarruz-zafer-mustusu-kasim-kaplan-fa5co', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yirmi Altı Ağustos ordunun kader günü,

Gazilerin nişanı, şehitlerin düğünü…

Vuslatı isteyince, bahar kokulu zafer,

Şehadete Sevdalı ordum oldu muzaffer.

Otuz Ağustos bize, bir zafer muştusudur,

Gözlerden parıldayan bir yürek coşkusudur.

O gün hayat yeniden, gülümsedi bizlere,

Yeni bir kuvvet geldi, derman oldu dizlere.

Şafak daha bir parlak, ışıldadı yurduma,

Çiğnediği topraklar selam verdi orduma.

Dağlar alçaldı bize, dereler yol verdiler,

Ordular dört bir yandan düşmanı çevirdiler.

Atatürk ordulara gösterdi hedefleri,

‘Ordular, hedefiniz Akdeniz dir ileri’

Duyulunca bu gür ses Kocatepe inledi,

Dağlar, taşlar, ordular bu buyruğu dinledi.

Başladı bu emirle, büyük Taarruz artık,

Pis kanlı süngülerle, dikildi büyük yırtık.

Binler beden tek yürek, Yaradanın adına,

Aktı, coştu, ulaştı mukaddes muradına.

Başkomutan Atatürk, o gün Kocatepe’de,

Seyrederken onları, kor vardı yüreğinde.

Düşmanlar bir solukta, gemilere bindiler,

Geldikleri yollardan inlerine döndüler.', 'Yirmi Altı Ağustos ordunun kader günü, Gazilerin nişanı, şehitlerin düğünü… Vuslatı isteyince, bahar kokulu zafer, Şehadete Sevdalı ordum ol...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kaplan']::text[], 8.5, '{"poet":"Kasım Kaplan","poet_slug":"kasim-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/buyuk-taarruz-zafer-mustusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müsvedde Günler', 'musvedde-gunler-selda-ozturkmen-8biz7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasretine yanmak budur herhalde...

Hece hece ismin dökülür kızıl dudaklardan.

Ve ıstırabın tenha sokaklarında,

Müsvedde günler koparılır takvim yapraklarından.

Yıldızlar raks etmez oldu hasretinden.

Umut kırıntılarıyla avunur oldu zavallı yürekler,

Yüzyıla bedel birkaç saattir sevdamı neşterleyen,

Nerede, kapına karanfil ektiğim o sergüzeşt günler? 

Etrafıma örülür senin elinle surlar,

Yine o tenha sokaklarda kirlenir itiraflar.

Payımıza susmak düştü gülüm! 

Yok olduk gurbet ellerde.

Hasretine yanmak budur herhalde...

(21.11.2005)', 'Hasretine yanmak budur herhalde... Hece hece ismin dökülür kızıl dudaklardan. Ve ıstırabın tenha sokaklarında, Müsvedde günler koparılır tak...', ARRAY['Türk Edebiyatı','Şiir','Selda Öztürkmen']::text[], 8.5, '{"poet":"Selda Öztürkmen","poet_slug":"selda-ozturkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/musvedde-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Topu', 'kar-topu-ramazan-ates-shriw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kar yağarken gezinmeyi, 

Sever misin ela gözlüm? 

Karda izin seyretmeyi, 

Sever misin ela gözlüm? 

Lapa lapa yağarken kar, 

Ceketini giy, şalını sar, 

Ağzını aç, düşşün karlar, 

Severmisin ela gözlüm? 

Çiğnedikçe karın sesi, 

Ne hoş olur gezinmesi, 

Soğuk soğuk titremeyi, 

Sever misin ela gözlüm? 

Gel, kar topu oynayalım, 

Çocuk gibi biz coşalım, 

İz yapalım, biz koşalım, 

Sever misin ela gözlüm? 

Yıllar oldu hasret kaldım, 

Bir damla kar bulamadım. 

Gel, yatıp yuvarlanalım, 

Sever misin ela gözlüm? 

Kar ağartsın saçımızı, 

Üşütsün de içimizi, 

Bu aşk yaksın ikimizi, 

Sever misin ela gözlüm? 

He, der misin ela gözlüm? 

Ramazan Ateş/Enschede-22.11.2005', 'Kar yağarken gezinmeyi,  Sever misin ela gözlüm?  Karda izin seyretmeyi,  Sever misin ela gözlüm?  Lapa lapa yağarken kar,  Ceketini giy, şa...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kar-topu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı Tiyatronun Karakterleri...', 'ayni-tiyatronun-karakterleri-ruya-deniz-demir-v3rf0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep aynı oyunun karakteriydik

Aynı sahnede karşılaşırdık

Aynı heyecanla başlardık

Aynı öfkeyle ayrılırdık…

Geceleri başkaydık

Sabahları bambaşkaydık

Yüreklerimiz titrerdi

Kavuşma anlarının heyecanı

Ayrılma anının öfkesiyle kapatırdı perdesini

Hiç anlamayan gözlerimizde…

Sanırım aynı tiyatronun baş kişisi

Aynı oyunun prensesiydin

Ben ise hep kapıcının oğlunu oynuyordum

Yalancı bir sahnenin soğukluğunda

Hep gözlerine ağlıyordum…

Ben garip bir çoban oluyordum

Sen ise şehirli güzel bir kız

Suskunluğuma doyamıyordum

Hep aynı terane 

Koyunları kuzuları kaçırıyordum

Gözlerine hep gözlerine dalıyordum

Ufku bir türlü bulamıyordum

Yine başa dönüp ağlıyordum…

Bazen sahnenin ortasında repliklerimi

Bazen hareket etmeyi unutuyordum

Çünkü seni düşünürken konuşmamaya

Seni düşünürken hareket etmemeye 

İnan bana bir tanem çok alışıyordum…

Hep aynı sahnede çıkacaksın karşıma

Ama roller hep farklı olacak

Hep başka gönül derdinde olacaksın

Ben ise hep sana aşık kalacağım

Hiç tükenmeyen bir telaşla

Hep o rolü almaya çalışacağım…

Yine olmayacak biliyorum

Aynı heyecanla geleceğim tiyatro salonuna

Aynı terane dönecek yine salonda

Biri elini omzuna atacak

Bozulacağım

Sus bakma köylü çocuğu diyecek içimdeki

Gözlerimi kapayacağım

Gönlümü tutacağım

Göz yaşlarım akmayacak

Acıyla haykıramayacağım…', 'Hep aynı oyunun karakteriydik Aynı sahnede karşılaşırdık Aynı heyecanla başlardık Aynı öfkeyle ayrılırdık… Geceleri başkaydık Sabahları bamb...', ARRAY['Türk Edebiyatı','Şiir','Rüya Deniz Demir']::text[], 8.5, '{"poet":"Rüya Deniz Demir","poet_slug":"ruya-deniz-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/ayni-tiyatronun-karakterleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Yakın', 'uzak-yakin-mehmet-akif-gulhan-2nril', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hayatta iki gerçek var

biri aşk biri ölüm

aşk o kadar uzak ki

ölüm ise olabildiğince yakın

ben de yakındakine sarılmışım

Mehmet Akif Gülhan 22.11.2005 Saat 21.03', 'hayatta iki gerçek var biri aşk biri ölüm aşk o kadar uzak ki ölüm ise olabildiğince yakın ben de yakındakine sarılmışım Mehmet Akif Gülhan ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/uzak-yakin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehidi Bugüne Besler Milleti', 'sehidi-bugune-besler-milleti-kasim-kaplan-fgr55', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şehidi bugüne besler milleti,

Savaş için emir verir devleti,

Şüheda, alınca kutlu daveti,

Saf olur meydana savaş zamanı

Vatan sevdalısı, bayrak aşığı,

Cennet yollarının öncü ışığı,

Allah dostlarıdır, Resul maşuğu,

Vatana kurbandır, şehidin canı.

Şehit cephededir, hain korkarken,

Özgürlük ateşi yürek yakarken,

Her insanın kanı yere akarken,

Yukarıya akar şehidin kanı.

Ölüm bir nimettir vatan korurken,

Peygamber cephede yara sararken,

Yürek yangınıyla Hakkı ararken,

Şehadettir ancak hasret dermanı,

Ölü değil onlar, şehitler ölmez

İlahi haberdir, cahiller bilmez,

Cennete girenler geriye gelmez

Bir tek şehitlerdir, özler vatanı.', 'Şehidi bugüne besler milleti, Savaş için emir verir devleti, Şüheda, alınca kutlu daveti, Saf olur meydana savaş zamanı Vatan sevdalısı, bay...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kaplan']::text[], 8.5, '{"poet":"Kasım Kaplan","poet_slug":"kasim-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sehidi-bugune-besler-milleti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevlana', 'mevlana-kasim-kaplan-qk2k2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlmin ışığıyla Hakkı arayıp,

Mevla’mıza âşık olmuş Mevlana.

Asude yaşayıp, Hakkı tanıyıp,

Dünyaya bir ışık olmuş Mevlana.

Hakikat dünyada bir sırlı perde,

Anmış gece gündüz, Hakkı her yerde.

Ağlarken niyazla, her gün seherde,

Gerçeği ilimde bulmuş Mevlana.

Sıra sıra yollar çokmuş Mevla’ya,

O sevgi yolunda koşmuş Mevla’ya.

Dünya gurbetiymiş, dönüp sılaya,

İnsanlığa bir yol sunmuş Mevlana.

Tasavvuf mektebi ufkunu açmış,

Yıllarca ilimle, aşkla çalışmış.

Marifete erip, Hakka ulaşmış,

Allah’ın aşkıyla yanmış Mevlana.

Hak bildiği yoldan asla ayrılmaz,

Dilinden, ırkından insan kayırmaz.

Kim olursa olsun asla ayırmaz,

İnsan sevgisiyle dolmuş Mevlana.

Kimseler görmemiş üzüldüğünü,

Yeryüzünü sarmış onun bu ünü.

Düğün günü saymış, öldüğü günü,

Konya’da kabire konmuş Mevlana.', 'İlmin ışığıyla Hakkı arayıp, Mevla’mıza âşık olmuş Mevlana. Asude yaşayıp, Hakkı tanıyıp, Dünyaya bir ışık olmuş Mevlana. Hakikat dünyada bi...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kaplan']::text[], 8.5, '{"poet":"Kasım Kaplan","poet_slug":"kasim-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mevlana-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşıkların Efendisi,Mevlana', 'asiklarin-efendisi-mevlana-kasim-kaplan-jdma7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mevlana’nın felsefesi,

Tasavvufun en gür sesi,.

Onu böyle meşhur eden,

İnsanları çok sevmesi…

O dur Hakk’a âşık olan,

Aşkın deryasına dalan…

Sevgi ile Hakk’a giden,

O dur doğru yolu bulan.

Âşıkların efendisi, 

Bir hazine Mesnevisi…

Haktır onu Sultan eden,

Karada yürür gemisi.

Dışlamaz hiç günahkârı,

Davet eder insanları,

Hak yoluna can ve beden,

Koşar kurtarır canları.

Sultan Veled’in oğludur,

Mevla’nın bir has kuludur.

Bir anıt yaptı sevgiden,

Yolu hakikat yoludur', 'Mevlana’nın felsefesi, Tasavvufun en gür sesi,. Onu böyle meşhur eden, İnsanları çok sevmesi… O dur Hakk’a âşık olan, Aşkın deryasına dalan…...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kaplan']::text[], 8.5, '{"poet":"Kasım Kaplan","poet_slug":"kasim-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/asiklarin-efendisi-mevlana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Aşkım', 'gel-askim-mehmet-akif-gulhan-rw107', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bırak aşkım bırak

Baharları kışları

Bırak Eylülleri Ekimleri

Boş ver seneleri

Gel,zamanları düşünmeden

Ayları, yılları saymadan

Bunca zamanı harcadıkta 

Ne oldu

Saçlara ak düştü

Yıllar belimizi büktü

Daha ne bekliyorsun

Hesapsız gel

Zamansız gel

Gül kokun uçmadan gel

Gel gel gel aşkım

Ben göçmeden gel

Mehmet Akif Gülhan 22.11.2005 Saat 21.12', 'Bırak aşkım bırak Baharları kışları Bırak Eylülleri Ekimleri Boş ver seneleri Gel,zamanları düşünmeden Ayları, yılları saymadan Bunca zamanı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gel-askim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehmetçik...', 'mehmetcik-kasim-kaplan-6lovw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mehmetçik yurdumun yiğit bekçisi,

Bulunmaz dünyada bir ikincisi,

Hep böyle, savaşlar her olduğunda,

Korur vatanını ölse kendisi.

Rütbe yükseldikçe, büyür komutan,

Onların emriyle korunur vatan.

Düşmanı ezdiği gün otağında,

Bir kuzu postuna bürünür aslan.

Candan sevdalıdır O vatanına,

Yürekten bağlıdır komutanına,

Daha şafak atıp, gün doğduğunda,

Koşar kışlasına, evlatlarına.

Yürek taş sanılır, ipek gibidir,

İçinde Milletin aşkı gizlidir,

Vatan ve bayrağı koruduğunda,

Her Türk bu dünyaya bedel biridir.

Askeri liseden sonra harbiye,

Asker ocağından alır terbiye,

Başımı yastığa her koyduğumda,

Ben rahat uyurum onlar var diye.

Böyle bir ordu yok bütün cihanda,

Gülerek vatana olur can feda.

Cevabım işte bu, sorulduğunda,

Şerefli Mehmetçik tektir dünyada.

Her asker Atamın bir vekilidir,

Asker şehit olur, ölmez diridir.

Sadece bir değil, benim Ordumda,

Her Türk komutanı işte böyledir.	27.01.05', 'Mehmetçik yurdumun yiğit bekçisi, Bulunmaz dünyada bir ikincisi, Hep böyle, savaşlar her olduğunda, Korur vatanını ölse kendisi. Rütbe yükse...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kaplan']::text[], 8.5, '{"poet":"Kasım Kaplan","poet_slug":"kasim-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/mehmetcik-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günahımsın', 'gunahimsin-oguz-kagan-mirzabeyoglu-etzyg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yakınlaştıkça kaybolan

bir kente dönüştürdün

keşfedilmezim olurdun

içinde yolculuk etsemde...

Günahkar mevsimimdin.

Hiç umut yoktu sende,

o yüzden vazgeçilmezdin,

vazgeçilmezimdin...', 'Yakınlaştıkça kaybolan bir kente dönüştürdün keşfedilmezim olurdun içinde yolculuk etsemde... Günahkar mevsimimdin. Hiç umut yoktu sende, o ...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Kağan Mirzabeyoğlu']::text[], 8.5, '{"poet":"Oğuz Kağan Mirzabeyoğlu","poet_slug":"oguz-kagan-mirzabeyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gunahimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melankolik', 'melankolik-ramazan-ates-lyae5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Melankolik

Hava soğuk karı nerde? 

Şu gönlümün yari nerde? 

Soğuk hava geçer amma,

Gönlüm beni atar derde.

İçim üşür bazı bazı,

Niye böyle kara yazı? 

Hep ellerin yari varda,

Nerde şu gönlümün yari? 

Ramazan Ateş/Enschede-22.11.2005', 'Melankolik Hava soğuk karı nerde?  Şu gönlümün yari nerde?  Soğuk hava geçer amma, Gönlüm beni atar derde. İçim üşür bazı bazı, Niye böyle k...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/melankolik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güldüren Öğretmenim', 'gulduren-ogretmenim-i-lhan-kirbac-mkf4s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gelişini hatırlıyorum,sanki dün gibi,

Bizlere ilk bakışını,tanışmamızı.

Ben '' Muammer Güldüren,''

Ardından gülüşmelerimizi.

İlk günde sevdirmiştin bize kendini.

Nasıl da eğitmiştin hepimizi,

Hem de ne zorluklarla.

Azıcık sertleştiğini de bilirim,

Hani ders çalışmadığımızda.

Bakışın içimizi ısıtırdı,

Yufkaydı yüreğin.

Okuyun adam olun derdin.

Yolundan gittim okudum.

Sayende öğretmen oldum,

Senden aldım da ilham.

Çıkmazlarda yol gösterenimsin,

Bize hep sevin,sevilin derdin.

Sevdim hem de ölesiye sevdim,

Sendendir çocuklara olan sevgim.

Ne öğrenciler yetiştirdim,

Ne cevherler,elmaslar buldum da işledim.

Bu öğretmen sana minnettar öğretmenim,

Minnettarım,

Tüm öğretmenlerime.

Ama öncelik senin GÜLDÜREN öğretmenim.', 'Gelişini hatırlıyorum,sanki dün gibi, Bizlere ilk bakışını,tanışmamızı. Ben '' Muammer Güldüren,'' Ardından gülüşmelerimizi. İlk günde sevdirm...', ARRAY['Türk Edebiyatı','Şiir','İlhan Kırbaç']::text[], 8.5, '{"poet":"İlhan Kırbaç","poet_slug":"i-lhan-kirbac","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gulduren-ogretmenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakma Güzel', 'yakma-guzel-necati-keceli-tf8f3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerinde, aşk, sevgiyi buldumsa

    Kabahatlı benmiyim, yapma güzel

    Kalbine girip, ateşte yandımsa

    Dünya ahiret, beni yakma güzel

    Bir kanat açıp, dalına kondumsa

    Aşk sevda olup, kalbine doldumsa

    Bir dalga  gibi, kıyına vurdumsa

    Ceset gibi, kenara atma güzel

    Sevdana düşüp, gönlümü yaktımsa

    Damla damla, al kanında aktımsa

    Bir kere olsun, gözlere baktımsa

    Sen, yüzüme uzaktan bakma güzel

    Her çağırmana, koşarak geldimse

    Ellerine gül, çiçekler verdimse

    Ben sana aşkım, sevgilim dedimse

    Sen bu aşkımı, oyun sanma güzel

    Senin ugrunda, göz yaşı döktümse

    İki yanaktan, bir kere öptümse

    Gelip önünde, aşka diz çöktümse

    Bu aşkı, hiç ugruna, satma güzel

    Necati KEÇELİ

    ADANA', 'Gözlerinde, aşk, sevgiyi buldumsa     Kabahatlı benmiyim, yapma güzel     Kalbine girip, ateşte yandımsa     Dünya ahiret, beni yakma güzel ...', ARRAY['Türk Edebiyatı','Şiir','Necati Keçeli']::text[], 8.5, '{"poet":"Necati Keçeli","poet_slug":"necati-keceli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yakma-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asker Oğluma Nasihat', 'asker-ogluma-nasihat-kasim-kaplan-log3s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aslanım, can parçam, yiğit evladım,

Bil ki sensiz dünya boş benim yavrum.

Sen asker olunca, iyice anladım,

Asker babalığı hoş benim yavrum.

Bilirsin canımdan fazla severim,

Gerekirse canım bile veririm.

Helal lokma verdim bunu bilirim,

Eğitimde önde koş benim yavrum.

Seni biz büyüttük vatana kurban,

Sen koş ki yurduma girmesin yaban,

Koşmazsan o zaman yanar bu baban,

Vatan, millet için koş benim yavrum.

Sabır ve sebatı öğreneceksin,

Her zorluğa karşı direneceksin,

Senden öndekine imreneceksin,

Onu geçmek için koş benim yavrum.

Bu vatan dünyada her şeye değer,

Sevdaların başı bu imiş meğer

Sana bir vazife düşerse eğer,

Can ile baş ile koş benim yavrum.

Tutmasa ayağın, tutmasa kolun,

Ateşten çembere düşse de yolun,

Korkmayın, Mevla’ya emanet olun,

Allah diye diye koş benim yavrum.

İsterse yüreğin çatlasın  dursun,

Düşmanlar karşından atsa da kurşun,

Sırtından değil de, alnından vursun,

Silaha karşı da koş benim yavrum.

Yavrum vatan aşkı başka sevdadır,

Bu vatan uğrunda canlar fedadır,

Askeri koruyan Hafız Huda’dır,

Mevla’nın aşkına koş benim yavrum.

Bir Türk yaşayamaz eğer esirse,

Şehitlik şereftir, eğer gelirse,

Eğer komutanın emir verirse,

Ölüme de olsa koş benim yavrum.

Atalar bu yolda şehit oldular,

En büyük şerefi böyle buldular,

Bizi bu vatana bekçi koydular,

Onların yolundan koş benim yavrum.

Hakkım sana helal, sende helal et,

Yürü unutamaz seni bu millet,

Ardında koskoca, şanlı bir devlet,

Davran da geç kalma, koş benim yavrum.

Korunması lazım bu cumhuriyet,

Atatürk sizlere etti emanet,

Bu yüce millete layık hürriyet

Özgür kalmak için koş benim yavrum.', 'Aslanım, can parçam, yiğit evladım, Bil ki sensiz dünya boş benim yavrum. Sen asker olunca, iyice anladım, Asker babalığı hoş benim yavrum. ...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kaplan']::text[], 8.5, '{"poet":"Kasım Kaplan","poet_slug":"kasim-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/asker-ogluma-nasihat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzdüşüm', 'i-zdusum-ahmet-sureyya-durna-rkz2k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dün geceydi düşümde

Uçan tabuta bindim/

Taşlı tarlada indim! .

Ölümü düşündümde; 

     Ak düştü saçlarıma,ak düştü! .

Kim demiş ''yaş otuz beş'',

''Yolun yarısı'' diye? ! 

Ecele tahdit,niye? ! 

Tenim teneşire eş; 

     Ak düştü saçlarıma,ak düştü! .

Gerdeğime girmeden

İçime korku girdi/

Bende bir hal belirdi! .

Yaş kemale ermeden; 

     Ak düştü saçlarıma,ak düştü! .

Göçtüm gönül şehrinden

Uğramam gayrı daha/

Bel bağladım Allah''a! .

Şol güzelin kahrından; 

     Ak düştü saçlarıma,ak düştü! .

Değişik bir andayım

Kulağımda bir ses var/

Ensemde bir nefes var! .

Bir garip mekandayım; 

     Ak düştü saçlarıma,ak düştü! .

Öldüm,ölmeden önce

Beklemeden yarını/

Şu mezar taşlarını,

Yosun tutmuş görünce; 

     Ak düştü saçlarıma,ak düştü! .', 'Dün geceydi düşümde Uçan tabuta bindim/ Taşlı tarlada indim! . Ölümü düşündümde;       Ak düştü saçlarıma,ak düştü! . Kim demiş ''yaş otuz be...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Süreyya Durna']::text[], 8.5, '{"poet":"Ahmet Süreyya Durna","poet_slug":"ahmet-sureyya-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/izdusum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşündüm; Ama Seni Düşündüm...', 'dusundum-ama-seni-dusundum-cahid-kurt-y6hk6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'düşündüm, ama seni düşündüm

dün gece oturdum

sabaha kadar seni düşündüm

ve neden öksüz, yetim  konduğumu 

neden yalnızlığın mahkumu olduğumu

insanların, arabaların geçtiğini gördüm. 

sokak lambalarının söndüğünü,

ayla güneşin öpüştüğünü,

sarılıp vedalaştığını bizzat gördüm.

bir seni göremedim,

bir sen görünmedin.

ve soruyorum şimdi kendime; 

ben senin neden düşündüm? 

ben seni neden düşündüm?', 'düşündüm, ama seni düşündüm dün gece oturdum sabaha kadar seni düşündüm ve neden öksüz, yetim  konduğumu  neden yalnızlığın mahkumu olduğumu...', ARRAY['Türk Edebiyatı','Şiir','Cahid Kurt']::text[], 8.5, '{"poet":"Cahid Kurt","poet_slug":"cahid-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dusundum-ama-seni-dusundum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A-bu hayat çok kısadır', 'a-bu-hayat-cok-kisadir-mikdat-bal-lb3mf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu hayat çok kısadır

Hayatını ganimet bil çünkü ömür kısadır

Ah’la vahla o da biter çoğu gam ve tasadır

Her canlı ölümü tadar, bu değişmez yasadır

O can sana emanettir, biraz kalıp gidersin

Ölmeyecek gibi, nasıl zevke dalıp gidersin?

Şımarıp da azmayasın, gördüğünde bolluğu

Nankörler divanındasın terk edersen kulluğu

Aklın firkin dünya olur, unutursun yolluğu

Her amelin hesabı var, nasıl gülüp gidersin?

Son pişmanlık fayda etmez, bunu bilip gidersin

Kendine gel tövbe eyle, vaz geç eğri gitmeden

Derin gafletten aymalı fani ömür bitmeden

Nice günahlara dalıp hesabını etmeden

Bu gafletle yaşadıkça, günah dolup gidersin

Uyanırsan tövbe ile belki silip gidersin

Haramdır mal edindiysen dalavere, hileyle

El malına göz dikilmez kazandılar çileyle

Hak yemişsen iade et bu sorunu hal eyle

Aksine büyük bir vebal burdan alıp gidersin

Ölüm vardır bilmez misin, nasıl çalıp gidersin?

Gideceğin yer tehlike, günahların çok ise

Ne yüzle cennet istersin, sevapların yok ise

Hesapta iflas edersin, yükün agır yük ise

Hayat sana son fırsattır, sanma gelip gidersin

Bunları bir düşünürsen, pişman olup gidersin

Mikdadi der beklemeden, gelir çatar son anın

Azrailden kurtuluş yok, gelince çıkar canın

Kolay çıkar tatlı çıkar, eğer varsa imanın

İmanla son nefesini belki salıp gidersin

Dünya yalan, her şey yalan bir gun ölüp gidersin!

Şair Mikdat Bal', 'Bu hayat çok kısadır Hayatını ganimet bil çünkü ömür kısadır Ah’la vahla o da biter çoğu gam ve tasadır Her canlı ölümü tadar, bu değişmez y...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bu-hayat-cok-kisadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Yaşadığım Yıllara Vay Vay', 'sensiz-yasadigim-yillara-vay-vay-huseyin-ozan-ozturk-nb1yf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Göçtü bahar,geldi hazan mevsimi,

Dermeden sararan güllere vay! vay! 

Ha battı batacak,bu köhne gemi,

Murada ermeyen kollara vay! vay! 

Gönlüm kabar kabar,gözüm kan ağlar,

İçimde bir hasret ırmağı çağlar,

Gelmek istiyorum,yol vermez dağlar; 

Kar yağdı kapadı yollara vay! vay! 

Kararmış ufuklar,caddeler sensiz,

Şu gurbet ellerde kimsiz kimsesiz,

Sen orada bensiz,ben burda sensiz,

Öksüz yaşadığım yıllara vay! vay!', 'Göçtü bahar,geldi hazan mevsimi, Dermeden sararan güllere vay! vay!  Ha battı batacak,bu köhne gemi, Murada ermeyen kollara vay! vay!  Gönlü...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ozan Öztürk']::text[], 8.5, '{"poet":"Hüseyin Ozan Öztürk","poet_slug":"huseyin-ozan-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensiz-yasadigim-yillara-vay-vay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anama Mektup / 2', 'anama-mektup-2-ahmet-turan-altunsu-wmth8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ufuk mu kaldı annem, göz önümde engeller,

Her adım atışımda uğultular, “dön gel” ler...

Doğu yok, güney ateş, batmak üzere güneş:

Önümde, vicdanların asıldığı çengeller...

Yaşamak buysa eğer gururu ne etmeli? 

Hayatı zehir eden kararı ne etmeli? 

Dost diye ortalıkta dolaşan çakalların

Dergâhıma verdiği zararı ne etmeli? 

Annem! Ey güzel kadın! Ak sütünden emdiğim! ..

Sağanak koptu kopar: Boğazım düğüm düğüm...

Ne hazin! .. Ne hazindir: Bütün bir istikbalin

Kazarak mezarını, ellerimle gömdüğüm? ! .

Gözlerim, bir katarakt pusluluğunda şimdi…

Ruhum, “ölümlü yalan” mahpusluğunda şimdi…

Kulağım, aralanan kapısında uçmağın; 

Karındaşımın keskin, tiz ıslığında şimdi! ..

_________22.11.2005 / Güdül / Ankara

___________Ahmet Turan Altunsu

ahtual'' den......', 'Ufuk mu kaldı annem, göz önümde engeller, Her adım atışımda uğultular, “dön gel” ler... Doğu yok, güney ateş, batmak üzere güneş: Önümde, vi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/anama-mektup-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yayla Dumanı', 'yayla-dumani-huseyin-ozan-ozturk-bj420', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Denizlerden gelir bir nefes gibi.

Karışır yellere yayla dumanı.

Kulaklara fısıldanır  ses gibi,

Dolar  gönüllere yayla dumanı.

Birer birer çeşmeleri dolaşır,

Genç kızların saçlarında oynaşır,

Ahmet''ten Ayşe''ye öpücük taşır,

Düşürür dillere yayla dumanı

Öbek öbek çıkar al yıldızlara,

Taç olur yaylada güzel kızlara,

Nağme olur düşer dertli sazlara,

Sarılır tellere  yayla dumanı.

Gün olur karışır kaval sesine,

Eş olur kuzunun melemesine.

Yemyeşil çamların ak gölgesine

Serilir bellere yayla dumanı.

Gün batar sürüler ağıla döner

Gecede  yıldızlar bir renkli fener

Sabah çisil çisil çiğ olur iner

Tomurcuk güllere yayla dumanı', 'Denizlerden gelir bir nefes gibi. Karışır yellere yayla dumanı. Kulaklara fısıldanır  ses gibi, Dolar  gönüllere yayla dumanı. Birer birer ç...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ozan Öztürk']::text[], 8.5, '{"poet":"Hüseyin Ozan Öztürk","poet_slug":"huseyin-ozan-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yayla-dumani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan...', 'i-nsan-mutlu-gonen-qtf76', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İNSAN.....

İnsan o kadar küçük ki

Sonsuz evren içinde

Ve o kadar büyük ki; 

Sonsuz evren her insanın içinde

İnsan her şeyi yapabilir isterse,

Rengarenk bir kelebeğe 

Can verebilir fırçasıyla

Ve hayallerinin peşinden gidebilir özgürce.

İnsandır her şeyin özü,

Bazen gülümseyen bir çocuğun yüzü,

Bazen hiroşimada binlerce gözyaşı,

Doğruluk, güzellik

Kötülük ve çirkinlik

İnsan bazen bir dahi,

Bazen de acımasız bir cani.....

				Mutlu GÖNEN.', 'İNSAN..... İnsan o kadar küçük ki Sonsuz evren içinde Ve o kadar büyük ki;  Sonsuz evren her insanın içinde İnsan her şeyi yapabilir isterse...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Gönen']::text[], 8.5, '{"poet":"Mutlu Gönen","poet_slug":"mutlu-gonen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/insan-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Realite', 'realite-ahmet-sureyya-durna-su2vr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne kadar da uzun olsa geceler,

Çaresiz mutlaka,sökecek şafak! .

Ne kadar da dev geçinse,cüceler; 

İriliği sözde, ''öz'' de çok ufak! .', 'Ne kadar da uzun olsa geceler, Çaresiz mutlaka,sökecek şafak! . Ne kadar da dev geçinse,cüceler;  İriliği sözde, ''öz'' de çok ufak! ....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Süreyya Durna']::text[], 8.5, '{"poet":"Ahmet Süreyya Durna","poet_slug":"ahmet-sureyya-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/realite-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varlıktan yokluğa düşmek nekötü', 'varliktan-yokluga-dusmek-nekotu-munevver-senol-uuup9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Varlıktan yokluğa düşmek nekötü

Kardeşim münire benden daha şanslı,henüz 3 yaşında olduğu için varlığında yokluğunda farkında değil,ama ben ilk okul 3 e gidiyorum,varlığı yaşadığım için şimdiki sefalet ağırıma gidiyor,üsküdar sultantepe deki köşkün,tarasının camından denizi seyrederken,şimdi penikteki gecekondunun,bombelenmiş kotürapilak tavanından yıldızları seyrediyoruz,oda yetmezmiş gibi,mahallede nekadar kedi varsa bizim tavanda,galiba tekiri dövmeye gelmişler ama kolaymı öylebir bağırıyorki sormayın,annem hergün köyden gelen,tarhanayı pişiiyor,sabah arhana,öğlen tarhana,akşam tarhana,artık t harfini bile duymak istemiyorum,haftasonlarının gelmesinide,nedenmi? odunumuz yok ev soğuk,annem -Kardeşine masal anlat oyala yatağın için den çıkmayın kardeşin küçük üşür hastaolur diyor,iyide ayı masalı dinlemekten bıkıyor annemde -Uydur,uydur anlat diyor ama aklıma birşey gelmiyorki,kardeşimde -Öf be sıkıldım diye kalkıyor,tabi annem gene bana kızıyor,Evcilik falan oynayın diyor,hiç yatağın içinde evcilik oynanırmı? pazartesi olsada okula gitsem diyorum,ama o zamanda çantama koyduğu torbaya yolda bulduğun çalı çırpı yı topla sobamızı yakarız diyor bende arkadaşlarımdan önce çıkıyorum evden daha çok inşaatlerin etrafından tahta parçaları buluyorum,okulun bahçesinde kuytu bir yer var oraya saklıyorum çıkıştada alıyorum,eve dönerkende,öbür yoldan dönüyorum başka yakacak bulmak için,birde aksilik işte ayakkabımın altı delinmiş su alıyor,ayaklarım üşüdü buz gibi birde buruşmuş tıpı baba annemin ayakları gibi olmuş,ama annem gene bana kızıyor -Seksek,oynamışsın bak sağ ayakkabın delinmiş diyo,halbuki oynamadım vallahi,babam karton kutudan ayağımın kalıbını çizip ayakkabımın içine koydu giderken kuru yerlerden yürü diye tembihledi yağmur yağıyor kuru yer olurmu? akşam eve geldiğimde ayaklarım sırıl sıklam babamın koyduğu kartonda ıslanmış,annem battaniyelere  s ardı birde         sıcacık tarhana çorbası,ama bu sefer hoşum a gitti,bana yeni bir ayakkabı alınana dek okula gitmiyeceğimi söyledim,annemin aklına onun arkadan tokalı siyah ayakkabı  geldi aklına annemin ayağı küçükübana tenefüse çıkmassın öğretmenine hastayım üşüyorum dersin dedi bende öyle yaptım ama öğretmenim,-Bak arkadaşlarının birşeyi kaybolur senin üstüne kalır,sen eniyisi korüdorda bekle dedi çıktım okulun en yaramaz çocuğu asal -Aaa annesinin papuçlarını giymiş diye ayağıma bir çelme taktı kendimi yerde buldum ayakkabıda ayağımdan  fırladıtabi,oğlanlar topgibi bir birlerine atarken ben   hıçkırarak ağlıyorum biryandanda annemin ayakkabısını almaya çalışıyorum zil çalınca bıraktılar,ben sınıftan çantamı aldığım gibi eve geldim,annemle babam çok üzülmüştü,babam evdeki takım elbisesini götürüp eskiciye verip bana müstamel yani birazcık kullanılmış kolej tipi önden bağlı ayakkabı, birazda yakacak almış ertesi gün okula gittiğimde arkadaşlarım öğretmenimize anlatmışlar olanları oda beni aldı müdürün odasına gittik,dünki olanlara çok üzülmüştü,-Neden bana söylemedin bak ihtiyacı olmayan lar bile okul aile birliğinden yardım alıyorlarbak bir ayakkabı mağazası bağış yapmış hadi beğen birtane dedi -Teşekkürederim öğretmenim babam bana aldı diyince ayaklarıma bakarak -Bumu yeni diyerek sarıldı,benimle oda ağlıyordu,müdüre dönerek,görüyorsunuz değilmi hocam,tok gözlü insan evladı bu işte dedi,çok ısrar ettikleri için kırmızı rugan bir ayakkabbı beğendim kıyafette verdiler bayram yakındı erzak bile verdiler,arkadaşım asal  da yaptığına üzülmüş gelip özür diledi,kötü başlayan ayakkabı maceram      tatlı bitti     26.10.1970.Münevver Şenol                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          sıcacı tarhana çorbası', 'Varlıktan yokluğa düşmek nekötü Kardeşim münire benden daha şanslı,henüz 3 yaşında olduğu için varlığında yokluğunda farkında değil,ama ben ...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/varliktan-yokluga-dusmek-nekotu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tövbe', 'tovbe-kadir-albayrak-3h4gb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şükür ki dilimiz dönmez inkara

Gafletten muzdarip gönlüm dimağım

Düşecek nefsimiz o kızıl nar-a

Halimiz ne garip affet Allahım

Günahla harmanız halden bi-haber

Namazsız selamsız cümle beraber

Hayat ki anlamsız, meçhule gider

Mazimiz ne garip affet Allahım

Nefsimiz şeytana esir mi nedir

Küf vurmuş her yana demir mi nedir

Bilmeyiz hata mı ecir mi nedir

Kalbimiz ne garip affet Allahım

Unuttuk kabir de işi ne kul-un

Hakbu ki bir sonu olacak yolun

Sorulur hesabı kanatsız kuşun

Kavlimiz ne garip affet Allahım

Gelsek de bin kere tövbeyi bozup

Geri çevirmezsin huzurdan kovup

Varmadık secdeye emrine uyup

Halimiz ne garip affet Allahım

Kul bilir mizan-ı sırat-ı ancak

İlle de günahla halvet olacak

Her helal lokmaya haram koyacak

Midemiz ne garip affet Allahım

Musibet bekleriz kim bilir neden

Aklımız ermiyor ecel gelmeden

Şu kısa ömrümüz sona ermeden

Tövbemiz ne garip affet Allahım', 'Şükür ki dilimiz dönmez inkara Gafletten muzdarip gönlüm dimağım Düşecek nefsimiz o kızıl nar-a Halimiz ne garip affet Allahım Günahla harma...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/tovbe-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmaz efendim', 'kalmaz-efendim-salman-yildiz-vzdkf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sanma ki yaptığın kalır yanına

Zalimlere zulüm kalmaz efendim

Ölüm gelir çatar, tatlı canına

O zaman hesabın kalmaz efendim

Saç sakal ağarır,sallanır başın

Bel verir beline musalla taşın

Altmıştan yukarı varınca yaşın

Gün olur sevenin kalmaz efendim

İncitme kimseyi,bırakma darda

Düşmanın olsa da kalmasın zorda 

Son bulur senaryo, biter mezarda

Bu dünya kimseye kalmaz efendim

Sev her şeyi, sev insanı doğayı

Dost eyleme  malı,mülkü,parayı

Düşme sakın ak görsen de karayı

Tükenir, bir şeyin kalmaz efendim

Tamiri imkansız kırılan kalbin

Dağlar kadar olsun her zaman sevgin

Olunmaz parayla dünyada zengin

Ahirete bir şey kalmaz efendim', 'Sanma ki yaptığın kalır yanına Zalimlere zulüm kalmaz efendim Ölüm gelir çatar, tatlı canına O zaman hesabın kalmaz efendim Saç sakal ağarır...', ARRAY['Türk Edebiyatı','Şiir','Salman Yıldız']::text[], 8.5, '{"poet":"Salman Yıldız","poet_slug":"salman-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kalmaz-efendim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Sevgiye Aşığız', 'biz-sevgiye-asigiz-kadir-albayrak-v4637', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu gönlüm Mevlana dergahı benim

Sevene kapısı kapanır mı hiç

Dost diye göklere açılan elim

Allah vergisidir yorulur mu hiç

Meks-u aram eder rüzgar gönlümde

Çöl bile gülistan lalezar bende

Yunusun sevgisi dildar içimde

Yüreğim nefrete kul olur mu hiç

Tomurcuk gülümser dal da aşk ile

Sevgiyi yudumlar büyür şevk ile

Bu hazzı nefsetmek varken zevk ile

Dünyanın mürveti sorulur mu hiç

Nefs-i törpüledik aşka kul ettik

Mevlana''yı dergah okul belledik

Yabanla dost ile hep helalleştik

Çağlayan pınarım durulur mu hiç

Sevgiye aşığım sevgiye kurban

Herşeye zerafet vermiş yaradan

Bu duygu bu haslet bize Mevla''dan

Nakşetmiş kalbime yok olur mu hiç', 'Şu gönlüm Mevlana dergahı benim Sevene kapısı kapanır mı hiç Dost diye göklere açılan elim Allah vergisidir yorulur mu hiç Meks-u aram eder ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/biz-sevgiye-asigiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahraman', 'kahraman-kadir-soyturk-inip4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kim ne derse desin bacım, aldırma

Sen tarihi yazan bir kahramansın! 

Böyle benim gibi sessiz seyreden; 

Bir de seni hor görenler utansın!', 'Kim ne derse desin bacım, aldırma Sen tarihi yazan bir kahramansın!  Böyle benim gibi sessiz seyreden;  Bir de seni hor görenler utansın!...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kahraman-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçtim', 'vazgectim-rengin-alacaatli-f0trk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yeni bir gün, yeni bir başlangıç

Doğacak güneşi bedenimde topladım

Aynaya baktım aynı ben

Değişen ne diye sordum kendime

Gözyaşlarımla yıkandım arındım

Saçlarımı taradım yumuşak bir şarkıyla

Sarı elbisemi giydim ayrılığın rengi diye

Hüzünleri sarındım bedenime sımsıkı

Yalnızlığı doladım yüreğime çepeçevre

Kapıdan çıkarken bir kez daha baktım geriye

Ben senden vazgeçtim ıssız bir gecede.', 'Yeni bir gün, yeni bir başlangıç Doğacak güneşi bedenimde topladım Aynaya baktım aynı ben Değişen ne diye sordum kendime Gözyaşlarımla yıkan...', ARRAY['Türk Edebiyatı','Şiir','Rengin Alacaatlı']::text[], 8.5, '{"poet":"Rengin Alacaatlı","poet_slug":"rengin-alacaatli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/vazgectim-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Öğretmenim', 'ben-bir-ogretmenim-celal-unal-l8wks', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben bir öğretmenim,

Cehaletin karşısında,

Bükülmez kolum benim.

Vurulsam da  Erzurum’da , Batman ‘da,

Gene kalkarım dimdik ayağa,

Çünkü çocuklarım var benim

Nemrut’un eteklerinde, Ağrı’da

Işık gerek, bilgi gerek onlara,

Ben bir öğretmenim,

Bu yolda bakmayın,

Ağardığına saçlarımın,

Ağarsa da saçlarım benim,

Bükülmez benim belim.

Ben bir öğretmenim,

Ovalar kadar geniş yüreğim,

Denizler kadar derin sevgim,

Mutluluğum, sevincim,

Benim öğrencilerim.

Ben onlarla ağlar, onlarla gülerim.', 'Ben bir öğretmenim, Cehaletin karşısında, Bükülmez kolum benim. Vurulsam da  Erzurum’da , Batman ‘da, Gene kalkarım dimdik ayağa, Çünkü çocu...', ARRAY['Türk Edebiyatı','Şiir','Celal Ünal']::text[], 8.5, '{"poet":"Celal Ünal","poet_slug":"celal-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ben-bir-ogretmenim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuz Kadar Nefret', 'tuz-kadar-nefret-celalettin-ucar-ai1l5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilmeden içine darlık verdimse,

Vedamı özrüme sayıver gitsin.

Sevmek sevdiğini mutlu görmekse,

Ey gönlüm; bu aşktan cayıver gitsin! 

Aşkınla yüz yürek kavrula dursun,

Dilerim kahrınla can verip ölsün! 

Kalbinde tuz kadar bir yerim olsun,

Adıma ''nefretim'' deyiver gitsin!', 'Bilmeden içine darlık verdimse, Vedamı özrüme sayıver gitsin. Sevmek sevdiğini mutlu görmekse, Ey gönlüm; bu aşktan cayıver gitsin!  Aşkınla...', ARRAY['Türk Edebiyatı','Şiir','Celalettin Uçar']::text[], 8.5, '{"poet":"Celalettin Uçar","poet_slug":"celalettin-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tuz-kadar-nefret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben şiir yazmadım', 'ben-siir-yazmadim-kadir-albayrak-q49go', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Evet yazdım! ...

Eskiden de yazıyordum, hala yazıyorum

Kimse bilmiyordu, sen de bilmiyordun

Ben yazıyordum! 

Satır satır sayfa sayfa

Ne varsa gönlümde ne gelirse aklıma

Onu yazıyordum! 

Ben şiir yazmadım! .. Ben şiir yazmazdım

Ben seni yazdım! ...

Seni beni bizi anlattım! ...

.........................

Evet yazdım! ..

Defter defter kitap kitap

Yazdım çizdim karaladım

Seni yazdım.....seni yazıyordum

Seni beni bizi anlatıyordum! 

Sonra gördüler! .. Sonra sen gördün

Sen ağlıyordun! .....

Herkes şiir okuyordu ben seni yazıyordum

Sen vardın kalemim de yüreğim de

Ben şiir yazmadım! ..Ben şiir yazmazdım! .

Ben yalnız seni yazdım

Seni beni bizi anlattım! .....

......................

Çaresizliği mi anlattım yıldızlara

Ve kar tanesi göz yaşlarımı

Her solukladığım da nefesi geçmişi yaşadığımı

Çocuksu duygularımı anlattım 

Ve.... ve satıldığımı! ...

Ben şiir yazmadım! ..Ben şiir yazmazdım! 

Ben seni yazdım

Seni beni bizi anlattım! .....

......................

Evet yazdım! ....

Adını koydum satırlara

Bir değil, bin değil, belki milyonlarca kez

İsmin de olmayan harflere kızdım! ..Bağırdım

Hatta küfrettim..... 

Ve cümlesini ''Sana benzettim''

Ne güneşin doğuşundan zevk aldım, ne akşamlarından hüzün

Sen diye yaşarım her şeyi, sen diye ezeli, ebedi

Dalgalar seni anlatır yakamozlar seni

Seninle eser kavak yelleri

Yorgun yılların nefesleri

Sarp yamaçlar anlatır seni, kurumuş ağaçlar,dallar,yapraklar

Oturduğum ev yağan yağmur

Islak sokaklar çiğnenmiş kaldırımlar

Ben....Ben seni anlatırım! 

Seni yazar seni yaşarım! 

Ben şiir yazmadım! ..Ben şiir yazmazdım

Ben seni yazdım

Seni beni bizi anlattım! .....

........................

Evet yazdım! ....

Seni yazdım! ...

Ama bir gün; 

Şiir yazmak gelirse içimden

''Yine seni yazarım''

Bu yol ki hasret, bu yol ki kahır

Bu yol ki gönül, kalem ve satır! ..

Ben seni şiir diye değil, ''ŞİİRİ SEN DİYE YAZARIM! ...''

Ben şiir yazmadım! ..Ben şliir yazmazdım! 

Vallahi billahi yazmazdım

Ben seni yazdım

Seni yazıyorum

Ben ''Seni yaşıyorum''

Çünkü ben; 

Ben ''SENİ SEVİYORUM! ...''', 'Evet yazdım! ... Eskiden de yazıyordum, hala yazıyorum Kimse bilmiyordu, sen de bilmiyordun Ben yazıyordum!  Satır satır sayfa sayfa Ne vars...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/ben-siir-yazmadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölge', 'golge-kadir-albayrak-4vitx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir dost sual etti, dedi ki ''Nerde? ''

Gölgeyi gösterdim, sürünür yerde

Bedenim toprağa devrilmedi ki

Yerde ki gölgenin ''Sahibi nerde''', 'Bir dost sual etti, dedi ki ''Nerde? '' Gölgeyi gösterdim, sürünür yerde Bedenim toprağa devrilmedi ki Yerde ki gölgenin ''Sahibi nerde''...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/golge-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmen', 'ogretmen-ali-parlak-uuddb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Elinde tebeşir, kara tahtaya,

Durmadan birşryler yazar öğretmen.

Mevsim şeridine, güne, haftaya...

Sevginin resmini çizer öğretmen.

Çocuklar sınıfta bal arıları,

Onlar bu ülkenin hem yarınları,

Derdini unutup tüm sorunları, 

Gözleri kapalı çözer öğretmen.

Parola; Araştır, gerçeği söyle,

Bir arada olmaz kötü iyiyle,

Boş vakit bulursan gelde seyreyle,

Bilgi sergilenen pazar öğretmen.

Aşkı tembih eyler, sevgi öğütler,

Sınıfta kurulur en güzel düşler,

Aşk ne zaman biter... kin nerde başlar,

Bak işte o zaman kızar öğretmen! 

Memleket sevgisi, vatan aşkını,

Onun gibi yoktur bayrak düşkünü,

Aralık ayında soğuk kış günü! 

Eski bir ceketle gezer öğretmen...

Sınıf onun evi, köşkü, sarayı...

Borç hesap etmekle geçer her ayı,

Saymasını bilmez, sevmez parayı! 

Her dem yoksulluktan bîzar öğretmen.', 'Elinde tebeşir, kara tahtaya, Durmadan birşryler yazar öğretmen. Mevsim şeridine, güne, haftaya... Sevginin resmini çizer öğretmen. Çocuklar...', ARRAY['Türk Edebiyatı','Şiir','Ali Parlak']::text[], 8.5, '{"poet":"Ali Parlak","poet_slug":"ali-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ogretmen-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Kokuyorsun', 'deniz-kokuyorsun-orhan-eren-uncu-svt9d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Deniz Kokuyorsun

Çakıl taşlarını, çarpa çarpa

Yüreğime

Sıcak bir meltem

Seni bana taşıyor

Deniz kokuyorsun

Köpük, köpük

Yürüyorum yanında

Sen Hırçın

Dalga, dalga açılıyorsun

Geçmişim canlanıyor

Çekiyorsun özlemlerime

Kulaç, Kulaç

Ben kayboluyorum

Sen duruluyorsun..

Artık derinlerdeyim..

Mercanlar kesiyor

Islak, acımasız

Görünmeyen çizgilerle

Canım yanıyor..

Kaçıyorum, dalga dalga

Kıyıya...

Keder yaşıyorum

Özlüyorum

Anafor oluyorum

Küçük balık havuzlarında

Sen

Dalga dalga

Deniz kokuyorsun

Köpük, köpük

Sarıyorsun her tarafımı 

ve Ben

Deniz taşıyım, Yosun tutmuş

Batıyorum..', 'Deniz Kokuyorsun Çakıl taşlarını, çarpa çarpa Yüreğime Sıcak bir meltem Seni bana taşıyor Deniz kokuyorsun Köpük, köpük Yürüyorum yanında Se...', ARRAY['Türk Edebiyatı','Şiir','Orhan Eren Uncu']::text[], 8.5, '{"poet":"Orhan Eren Uncu","poet_slug":"orhan-eren-uncu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/deniz-kokuyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenler Günü', 'ogretmenler-gunu-mehmet-ali-yapici-851ds', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gökte nasıl parlıyorsa pırıl pırıl yıldızlar,

Yeryüzünde ışık kaynağımız öğretmenler var,

Korkutur insanları cehaletle karanlıklar,

Öğretmenler aleme bilgi ile ışık tutar.

Tertemiz taze beyinleri öğretmenler işler,

İçlerine doldururlar cesaret ve bilgiler,

Çocuklar cesaret ve bilgi ile yetişirler,

Aydın kişi hayata emin adımlarla gider.

Kabul edersek çocukları taze birer fidan,

Öğretmenleri de fidan yetiştiren bahçıvan,

Onlar bu fidanları büyütür ve yetiştirir,

Gün gelir yetişen fidanlar meyvesini verir.

Öğretmenlerdir bütün bu insanlara güç veren,

Onlardır bizi yetiştirip hayata gönderen,

Sanatkar, memur, general hatta cumhurbaşkanı,

Öğretmen sayesinde alırız en büyük sanı.

Nereden baksan öğretmen ulusun temel taşı,

Öğretmenlerdir her iyinin her güzelin başı,

Öğretmendir minik insanların ilk arkadaşı,

Unutulmaz anı olarak süslerler her yaşı.

Bu yıl da ilk kez öğretmenler günü bulduğunu,

Unutma hiç en yüce meslek dalı olduğunu,

Bin dokuz yüz seksen birin yirmi dört Kasım günü,

Hatırla ilk başöğretmen yüce Atatürk''ünü!', 'Gökte nasıl parlıyorsa pırıl pırıl yıldızlar, Yeryüzünde ışık kaynağımız öğretmenler var, Korkutur insanları cehaletle karanlıklar, Öğretmen...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Yapıcı']::text[], 8.5, '{"poet":"Mehmet Ali Yapıcı","poet_slug":"mehmet-ali-yapici","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ogretmenler-gunu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlık', 'i-nsanlik-ali-parlak-sz3mk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öz raflarda unutuldu.

Ön saflarda saf tutuldu.

Sözler dondu, laf tutuldu.

Sandığa girdi insanlık...

Vicdan oldu vicdansızlar! 

Dönek telden çaldı sazlar.

Cayır cayır yandı sözler,

Tandıra girdi insanlık...

Gevşedi esnek yuları,

Kirlendi duru pınarı,

Çukurluğun yok sınırı! 

Hendeğe girdi insanlık...

Yıkılmaz, yenilmez dendi,

Cümle mahlukları yendi,

Debelendi ve belendi,

Kundağa girdi insanlık...

Aldandı geldi oyuna,

İhanet etti soyuna,

Şeytanla koyun koyuna,

Gerdeğe girdi insanlık...', 'Öz raflarda unutuldu. Ön saflarda saf tutuldu. Sözler dondu, laf tutuldu. Sandığa girdi insanlık... Vicdan oldu vicdansızlar!  Dönek telden ...', ARRAY['Türk Edebiyatı','Şiir','Ali Parlak']::text[], 8.5, '{"poet":"Ali Parlak","poet_slug":"ali-parlak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/insanlik-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülmeyi Unutmuşsun Çocuk', 'gulmeyi-unutmussun-cocuk-ulas-guleviz-uz4s1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gülmeyi

unutmuşsun  çocuk

oysa

ne  yakışırdı

benli  yüzüne  gülücük

ve  yanağına  öpücük

ne  yakışırdı

giydiğin  bu  hüzün  mavisi

hayatın  dalgasına

ezik  düşmüş  hep

belli

yanağı  benli  çocuk

yüreğinin  seli  vurmuş

göz  uçlarına

hüzün

göz  uçlarından  dalgalara  kapılmış 

bir  kayık  gibi  sürüklenmekte

seni

kim  yaraladı

ve  kimdi

yaşama  sevincini  çalan

kimdir  o  ki

yapabileceklerini

hayal  gibi  uzaklaştırmış  senden

gülmeyi  unutmuşsun  mavi  çocuk

ve  gözlerinden  taşan  yari  içmeyi

öpmeyi

öpülmeyi  özlemişsin  belli

benli  yanaklarından

ve  bensi  dudaklarında  gizli  gülücüğüm – n

[email protected]', 'gülmeyi unutmuşsun  çocuk oysa ne  yakışırdı benli  yüzüne  gülücük ve  yanağına  öpücük ne  yakışırdı giydiğin  bu  hüzün  mavisi hayatın  ...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Güleviz']::text[], 8.5, '{"poet":"Ulaş Güleviz","poet_slug":"ulas-guleviz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gulmeyi-unutmussun-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahkeme', 'mahkeme-kadir-albayrak-u61xo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bunama başladı zamansız

''Gölgeler'' gerçeği sorguluyor du! 

Sanık sandalyesin de ben,

Ve! ........

''Bir Kahpe'' hakim olmuştu! ....

Kalemini kırdı ortasından

Halbu ki bir damla,

Mürekkep bile yoktu! ....', 'Bunama başladı zamansız ''Gölgeler'' gerçeği sorguluyor du!  Sanık sandalyesin de ben, Ve! ........ ''Bir Kahpe'' hakim olmuştu! .... Kalemini k...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mahkeme-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz Ucu', 'goz-ucu-ulas-guleviz-tpqa8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Göz  ucu  sinsidir  çocuk

Göz  ucu  hınzır

Belki  kavgacı

Belki  kalleş

Belirsizdir 

anlaşılmaz  ne  düşündüğü

Göz  ucu  katildir  belki

Belki  de  bubi  tuzağı 

Ucu  ucuna  değmesin  gözümün

Ve  ilişmesin  bedenim

hiç  bir  göz  ucuna

Hele  de  siyah  paltolu

köstebek   ruhlu  olanına 

Ve  bir  de  çocuk

Vatanına  boş  boş  bakan

Ve  değerlerini  vatanımın

Değersiz  başı  gibi  satan

Köstebek  ruhlu  insanların

Göz  ucundan  sakın  bu  vatanı

Ama çocuk

bu  vatan  mavi  bir  göz

O  mavi  gözlerin  nuru  bu  vatan 

Ki  o  gözlerdir  öncü

Onun  ateşiyle  söndü

söner  hainin  hıncı 

[email protected]', 'Göz  ucu  sinsidir  çocuk Göz  ucu  hınzır Belki  kavgacı Belki  kalleş Belirsizdir  anlaşılmaz  ne  düşündüğü Göz  ucu  katildir  belki Bel...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Güleviz']::text[], 8.5, '{"poet":"Ulaş Güleviz","poet_slug":"ulas-guleviz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/goz-ucu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıçak Sırtı Gözlerin', 'bicak-sirti-gozlerin-fethi-aslan-yoa3f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni bağışla bir veda etmeden gittim diye.

Hayırsızlığımdan değil

sadece

bakmaya cesaret edemedim o bıçak sırtı gözlerine.

Sen bilmesende, görmesende

ben her gece gelirim yanına.

Parmak uçlarımda,

usulca,

süzülürüm yatağının kenarına,

yıldızlardan bir taç yapıp takarım saçlarına

Gece karanlığında,

yüreğimin atışları çığlık olup yükselir göğe.

Bir öpücük kondururum gözlerine,

sonra bir nefes gibi dolarım ciğerlerine.

Sen nasıl olsa yeni sevdalara yelken açarsın,

bense yokluğunun mengenesinde,

törpülerim hayatımı.

Sorma ne olur bu ayrılığın nedeni ne

Bağışla beni bir veda etmeden gittim diye.

Hayırsızlığımdan değil, 

sadece

bakmaya cesaret edemedim o bıçak sırtı gözlerine.', 'Beni bağışla bir veda etmeden gittim diye. Hayırsızlığımdan değil sadece bakmaya cesaret edemedim o bıçak sırtı gözlerine. Sen bilmesende, g...', ARRAY['Türk Edebiyatı','Şiir','Fethi Aslan']::text[], 8.5, '{"poet":"Fethi Aslan","poet_slug":"fethi-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bicak-sirti-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyım Bu', 'kiyim-bu-ulas-guleviz-1tbn4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kıyım  bu

Şiir  yuttum

Ve  şiir  doldu  içim

Coştu  hüzün

Sonra

Dalgalandı  resimler

ve   kıyım

Yanık

Kuru 

Kıyım  bu 

ve  ölümdür  silahlı  savaşlar

silahsızlar  başka  bir  ölüm

Gel  gidelim 

Yaralı  kuşsun  yürek

Ya  da  bırak

Kafesimde  kalayım

[email protected]', 'Kıyım  bu Şiir  yuttum Ve  şiir  doldu  içim Coştu  hüzün Sonra Dalgalandı  resimler ve   kıyım Yanık Kuru  Kıyım  bu  ve  ölümdür  silahlı ...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Güleviz']::text[], 8.5, '{"poet":"Ulaş Güleviz","poet_slug":"ulas-guleviz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kiyim-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hata', 'bir-hata-kadir-albayrak-pv2ht', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben; Bir insanım! .. 

Duygulu

Biraz asi

Mağrur ve gururlu! ..

Dün-den şikayetim yoktu

Yarınımsa  umutlu! ..

Ve

''Seni tanıdım''

Hiç ama hiç ''Gereği yoktu! ..''', 'Ben; Bir insanım! ..  Duygulu Biraz asi Mağrur ve gururlu! .. Dün-den şikayetim yoktu Yarınımsa  umutlu! .. Ve ''Seni tanıdım'' Hiç ama hiç ''G...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-hata-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünlü Dağlar', 'huzunlu-daglar-ahmet-sureyya-durna-nh0k0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nerde o, koyağında karı üşüyen dağlar? 

Nerde o, kıvrım kıvrım dik yokuşlu yaylalar? 

Hoyratlar kamp kurarak kirletmiş oraları,

Değişmiş sert havalar,değişmiş soğuk sular! .

Binboğada,Bozokta,Obrukta,Çamlıbelde; 

Ne keklik öter şimdi,ne çoban kaval çalar! .

Toroslar,Amanoslar kurumuş belde belde; 

Çamlar katledilirken,mahzun çiçekler solar! .

Hipiler dans ediyor ardıç gölgelerinde,

Yamaçta yankılanır çılgınca vaveylalar! .

Hayret! Anadolu''mun en mutena yerinde; 

Yadeller mekan tutmuş,yerliler seyre dalar! .

Karadeniz dağları,Beydağları muzdarip,

Kekik ve yavşanları botanikçiler yolar! .

Yıldızlar,Uludağa bakıyor garip garip; 

Kenger sakızlarını kızıl akrepler yalar! .

Huzursuz Palandöken,Tecer ve Ağrı dağı; 

Ilgazı,Erciyesi habis ruhlular talar! .

Hepside bir ağızdan özlüyor, ''Altın çağı''; 

Yere eğilmiş başlar,Allah''a secde kılar! .', 'Nerde o, koyağında karı üşüyen dağlar?  Nerde o, kıvrım kıvrım dik yokuşlu yaylalar?  Hoyratlar kamp kurarak kirletmiş oraları, Değişmiş ser...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Süreyya Durna']::text[], 8.5, '{"poet":"Ahmet Süreyya Durna","poet_slug":"ahmet-sureyya-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/huzunlu-daglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunmayın Düşlerime', 'dokunmayin-duslerime-ufuk-coban-2efwc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çocuk kalmak isterdim hayatın acımasız yıllarında,

Büyümek üzülmekti elimden alınan oyuncaklarda.

Bir oyun gibiydi hayatı sevmek küçük ellerimde,

Bir uykuya dalmaktı anlatılan masalın satırlarında.

Uykularda gördüm korkmayı, korkup kaçmayı,

Bilemezdim sevdalarda rüyalara dalacağımı.

Yok olmak ister miydim çocuk olsam sabahlarda,

Saklanıp bir masanın altına çıkmadan sessizliğe.

Bir oyun arkadaşı aradım ömrümce oynamak için elele,

Tek kaldım oyunlarda, tek kişilik oynanmayan yalanlarda.

Bir top bir çember yettimi? yetmedi tabi yağmurlu akşamlarda,

Yine uyudum karanlıktan korkarak yastığın pamuk kokusunda.

Artık savunmasızlığım düşlerimde kaldı mutluyken,

Dokunmayın düşlerime tek cennetim o huzurlu bakışlarda.

Bırakın düşlerimi elimde kalan bir tek o,

Sen bile dokunma düşlerime, kendin zaten uzak kaldın gözlerimde.

22/11/2005 23:37', 'Çocuk kalmak isterdim hayatın acımasız yıllarında, Büyümek üzülmekti elimden alınan oyuncaklarda. Bir oyun gibiydi hayatı sevmek küçük eller...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dokunmayin-duslerime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaştımda Kaldım', 'sastimda-kaldim-munevver-senol-c5322', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana canımın canı demişim çokmu? 

EE bence az bile söylemişim

Kıymet bilensin bu canım feda sana.

Keşke herkes senin çeğreğin olsa.

O zaman dünyada fitne fesat olmazdı

Şimdi seni taşıdığım yıllara şaşıyorum.

İnsan oğlu şaşarda beşer.

Ama sonunda doğruyu bulduğuma inanıyorum.

Bak arkamdan dürtme beni,

Deh çüş,deh çüş,diyerek.

Herhalde insanım ben eşşek değilim.

Ne yaparsan yap zorla güzellik olmuyor.

Eşşeği sattık belaya çattık kurtuluş yok bundan

Fazla üstüme gelme benim bak çeker giderim.

Daha olmadı dünyayı yakar giderim.', 'Sana canımın canı demişim çokmu?  EE bence az bile söylemişim Kıymet bilensin bu canım feda sana. Keşke herkes senin çeğreğin olsa. O zaman ...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sastimda-kaldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Birde Sen Olsan Yanımda', 'ah-birde-sen-olsan-yanimda-okan-oztekin-k8sbn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karşımdaki haritaya her baktığımda seni çekiyorum sigara dumanı yerine içime,

Hasretin soğukluğu sarıyor içimi, iki kat hasır altında bile ısınamıyorum! 

Saat hep 22.22 olduğunda dilek tutuyorum ikimizin adına,hayaller kuruyorum; delice.amaçsızca! 

Ne zaman deniz dalgalansa seni sevdiğimi haykırmak istiyorum martılara; o ayazı kalbimde hissediyorum; boşluğunu gömmek istiyorum dalgalarla! 

Ne zaman resmine baksam gözlerin geliyor aklıma,tutarsız ama etkileyici; bakışlarını özlüyorum,çekiyorum esrarını içime; ama haykıramıyorum! 

Ne zaman şiir yazsam aklım gidiyor uzaklara,amaçsızca; ah birde sen olsan yanımda...', 'Karşımdaki haritaya her baktığımda seni çekiyorum sigara dumanı yerine içime, Hasretin soğukluğu sarıyor içimi, iki kat hasır altında bile ı...', ARRAY['Türk Edebiyatı','Şiir','Okan Öztekin']::text[], 8.5, '{"poet":"Okan Öztekin","poet_slug":"okan-oztekin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ah-birde-sen-olsan-yanimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtuldum Kabusumdan', 'kurtuldum-kabusumdan-nurten-tarim-17f0t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayalinin korkusuyla sarhoş oldum

Ay yüzlü güneş gözlüm

Çok geceler adını sayıkladım

Tutuştum yandım tükendim

Ruhumda sakladığım orkide

Artık anılarda kaldı göz yaşlarım

Gönlüm gördü artık ışıltısını

Tutuştu bir kere sevdalandı

Hayatımın engelli yollarında

Güneşim doğdu sım sıcak

Dans eder ateş böcekleri etrafımda

Kaktüs  çiçeği açtı gönlümde

Mazide kaldı yanlızlığım

Bütünleştim hayatla

Yüreğime aşk doldu 

Sevgi yerine geldi

Uçuyorum mutluluktan 

Kurtuldum kabusumdan', 'Hayalinin korkusuyla sarhoş oldum Ay yüzlü güneş gözlüm Çok geceler adını sayıkladım Tutuştum yandım tükendim Ruhumda sakladığım orkide Artı...', ARRAY['Türk Edebiyatı','Şiir','Nurten Tarım']::text[], 8.5, '{"poet":"Nurten Tarım","poet_slug":"nurten-tarim","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kurtuldum-kabusumdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
