INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ve Seninle', 'sen-ve-seninle-numan-i-stanbul-hdta1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdiysen eger 

bırak gözlerin bende kalsın 

Yarın 

bir başka mevsimi 

cizecek zaman 

ve sen 

yüregimde 

dev bir özlem olacaksın 

Sevdiysen eger 

bırak dudakların 

bende kalsın 

Bu son gecem biliyorsun 

