INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Akvaryum Balığı', 'sen-akvaryum-baligi-ercan-cengiz-ggrr2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen Akvaryum Balığı

sen akvaryum balığı 

akvaryumda doğdun akvaryumda büyürsün 

sen büyüdükçe duvar da büyür 

derin suları bilmezsin / ayak kesen karı 

ne doğayla savaşın ne de cinsinle 

kim bilir belki bundandır 

akarsulara gidemediğin 

tuzak kurmasını bilmezsin

sürüyle kurt mu, çakal mı 

karda izini bırakır 

sen akvaryum balığı 

dört duvar tutar seni / tanır dört duvar 

sen büyüdükçe büyüyen  / yıkılası dört duvar

Toprak Tutsun Külümü', 'Sen Akvaryum Balığı sen akvaryum balığı  akvaryumda doğdun akvaryumda büyürsün  sen büyüdükçe duvar da büyür  derin suları bilmezsin / ayak ...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-akvaryum-baligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitmeden Mavi Gel/Sen Ne Olur', 'yitmeden-mavi-gel-sen-ne-olur-nesrin-gocmen-790f6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne gece umrumda, ne de yergiler,

Hurda kalemimle, sorarım seni...

Ayıksız  yürekten, taşan sevgide,

Övünç, onur duyar, ararım seni...

.

Çiçekler imrenir, vardığım düşe,

Umarlıdır sevdam, kederde neşe...

Yazgının içine, düşen her kışta

Nefret dağlarından, korurum seni..

.

Bak, sonbahar yine, geldi, gidiyor,

Sarıyla karışan, mavi yitiyor...

Gerçek sevdaların soyu bitiyor, 

Hayalle örtünme, candan sar beni...

.

25 Kasım 2005', 'Ne gece umrumda, ne de yergiler, Hurda kalemimle, sorarım seni... Ayıksız  yürekten, taşan sevgide, Övünç, onur duyar, ararım seni... . Çiçe...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yitmeden-mavi-gel-sen-ne-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gün senin Mezarına (Şematik)', 'bir-gun-senin-mezarina-sematik-mikdat-bal-d9j28', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün senin......mezarına..........yazarlar..............öldü diye 

Mezarına.............rahmetlinin......vadesi.................doldu diye 

Yazarlar..............vadesi...............doldu gülbenzi....soldu diye 

Öldü diye............doldu diye........soldu diye...........yazarlar 

Farketmedi...........hiçbir şeyi........aniden................ömrü bitti 

hiç bir şeyi...........anlamadan........geldiği...............yere gitti 

aniden..................geldiği..............yere döndü bak...veda etti 

ömrü bitti.............yere gitti...........veda etti.............yazarlar 

Gömecekler.........dönecekler.........dostların..............herkes gider 

Dönecekler...........tek kalırsın........sadece..................kalır keder 

Dostların...............sadece...............gömer, mezarın....otu biter 

herkes gider..........kalır keder.........otu biter................mezarlar 

Mikdat der ki........öleceksin............mutlaka.................haktır ölüm 

Öleceksin..............dirilince..............hesap var...............etme zulüm 

Mutlaka.................hesap var............senin, suçların.......bölüm bölüm 

haktır ölüm...........etme zulüm.........bölüm bölüm.........yazarlar', 'Bir gün senin......mezarına..........yazarlar..............öldü diye  Mezarına.............rahmetlinin......vadesi.................doldu diy...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-gun-senin-mezarina-sematik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ask Masalı', 'bir-ask-masali-mehmet-erol-tm832', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir Aşk masalı benimki ağlarken dilimde

Morlu,kırmızılı çiçeklerin arasından

kıvrılıp elini tutuyorum sevdamın yolu..

Her gün? 

Sen yoksun! yanımda

İlerlemeyen saatlere,Geçmeyen günlere tanık! 

Yitik ve unutulmuş hissediyorum kendimi..

Gözlerini, karşımda görünce bir His

içimden bir ses  yalnız kaldığımı bildirir bana

yüreğim  taşıyamaz oluyor günden güne

Omuzlarımda ağırlaşan yükü

Denize attım kendimi,dert dökmeye

Ama unutmuşum

Yokluğunu, Sensizliği, acı veren saatleri...

Bakamazdı Gözlerime O uzaklardaydı...', 'Bir Aşk masalı benimki ağlarken dilimde Morlu,kırmızılı çiçeklerin arasından kıvrılıp elini tutuyorum sevdamın yolu.. Her gün?  Sen yoksun! ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Erol']::text[], 8.5, '{"poet":"Mehmet Erol","poet_slug":"mehmet-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-ask-masali-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yastayım', 'yastayim-asuman-zeynep-gunaydin-72e9e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aç yaslarım var 

başımı yasladığım...

Doyuramıyorum 

ezelden ebede 

yağdırdığım yaşlarla.

Yaşım geçiyor 

başım

her daim yasta…

2005/ist.', 'Aç yaslarım var  başımı yasladığım... Doyuramıyorum  ezelden ebede  yağdırdığım yaşlarla. Yaşım geçiyor  başım her daim yasta… 2005/ist....', ARRAY['Türk Edebiyatı','Şiir','Asuman Zeynep Günaydın']::text[], 8.5, '{"poet":"Asuman Zeynep Günaydın","poet_slug":"asuman-zeynep-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yastayim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece Seni Gördüm Düşümde', 'dun-gece-seni-gordum-dusumde-huseyin-erdogan-51z7c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dün gece seni gördüm düşümde

dolaşıyorduk seninle el ele sahilde

Suadiye''de Kadıköy''de Ataköy''de

ne de mutluyduk sevdiğim bir bilsen

vallahi çok güzel bir aşk şiirisin sen

o güzel ellerin hiç ayrılmasın ellerimden

bu dünyada sana bir kez bile dokunamasam da

sen benim tek şiirim olarak kalacaksın ebediyen

ah! keşke bu rüyadan hiç uyanmasaydım

ölünceye değin  hep seninle bu düşte kalsaydım

sen benim bin ömür bile bitmeyecek rüyamsın

yemyeşil rengarenk açan solmayacak baharımsın

hiç ayrılmayacağım kolumsun kanadımsın dalımsın

sen bana can veren damarlarımsın organlarımsın

ışıl ışıl sımsıcacık mutluluk neş''e sevinç kaynağımsın

sen benim dizemsin şiirimsin canımsın cananımsın 

ömrümce doruklarda yaşayacağım tek sevdamsın

                                                         25.11.2005

                                                       Hüseyin Erdoğan', 'dün gece seni gördüm düşümde dolaşıyorduk seninle el ele sahilde Suadiye''de Kadıköy''de Ataköy''de ne de mutluyduk sevdiğim bir bilsen vallahi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dun-gece-seni-gordum-dusumde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yunus', 'yunus-halil-i-brahim-kecebas-b5bui', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neden her gece hüzün sarar beni? 

Yalnızlıktan mıdır acaba? 

Gecenin karanlığında bin bir çaba...

Kimse bilmez ruhumun verdiğini.

Hüzne koşar gibi okurum Orhan Veli''yi

Ekseriya ayrılık ve yalnızlık...

Bazen sevinç bir tadımlık...

Sigaram bekler içilmeyi.

Neden her gece hüzün sarar beni? 

Yalnızlıktan mıdır acaba? 

Gecenin karanlığında bin bir çaba...

Kimse bilmez ruhumun verdiğini.

Uzaklarda bir sevgili aklıma gelir

Kavuşma hayalini kuramadığım

Ah! Nerde benim aydınlığım? 

Önüme yine ayrılık yolu serilir.

Neden her gece hüzün sarar beni? 

Yalnızlıktan mıdır acaba? 

Gecenin karanlığında bin bir çaba...

Kimse bilmez ruhumun verdiğini.

Ne zaman bitecek bu kâbus? 

Söyleyin bana, ne zaman

Kurtarmaz mı beni gecenin karnından? 

Çıkıp gelerek bir yunus.

22.11.05', 'Neden her gece hüzün sarar beni?  Yalnızlıktan mıdır acaba?  Gecenin karanlığında bin bir çaba... Kimse bilmez ruhumun verdiğini. Hüzne koşa...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Keçebaş']::text[], 8.5, '{"poet":"Halil İbrahim Keçebaş","poet_slug":"halil-i-brahim-kecebas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yunus-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zindan', 'zindan-i-rfan-kayagil-t7hfi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Damlıyor tavandan zalimin zulmü

Zindan delmiyor aklımın ilmi,

Dayanmaz bu acıya yufka yürekler

Yarim beni , ben özgürlüğü bekler

Taş duvarlar sanki feryat boğuyor

Yaktığım ağıtları kimse duymuyor

Damlıyor tavandan zalimin zulmü

Zindan delmiyor aklımın ilmi,

Üstüme çöreklendi bütün karanlık

Çektik bunca acıyı kime yarandık

Damlıyor tavandan zalimin zulmü,

Zindan delmiyor aklımın ilmi.

Aklım uçtu sanki, bedenim tutsak

Gerçek olmasa da düşte buluşsak

Damlıyor tavandan zalimin zulmü,

Zindan delmiyor aklımın ilmi.

Dayanamam artık ben bu acıya

Zindana değil yüreğimdeki sancıya

Damlıyor tavandan zalimin zulmü,

Zindan delmiyor aklımın ilmi.

 Ankara 2002 Kasım', 'Damlıyor tavandan zalimin zulmü Zindan delmiyor aklımın ilmi, Dayanmaz bu acıya yufka yürekler Yarim beni , ben özgürlüğü bekler Taş duvarla...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kayagil']::text[], 8.5, '{"poet":"İrfan Kayagil","poet_slug":"i-rfan-kayagil","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zindan-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahraman', 'kahraman-mehmet-ozcelebi-sc33y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben bir kahramanım

Kimse bilmez neden

Seninle iken

elimi tuttuğunda zaman donuyor 

 Gülümsediğinde ise çevrendeki her şey yok oluyor

 Renkli gözlerini bana diktiğinde

zaman - mekan - evren herşey 

hiçlige sürükleniyor. 

Yalnız sen kalıyorsun, 

sadece sen,

 bütün ruhumu kaplıyor bakışın....

Bir kahraman olarak vazifemi yapıp 

Evreni kurtarıyorum..

Gözlerimi kaçırıyorum senden....

Ben bir kahramanım

Kimse bilmez, bilmeyecek neden', 'Ben bir kahramanım Kimse bilmez neden Seninle iken elimi tuttuğunda zaman donuyor   Gülümsediğinde ise çevrendeki her şey yok oluyor  Renkli...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özçelebi']::text[], 8.5, '{"poet":"Mehmet Özçelebi","poet_slug":"mehmet-ozcelebi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kahraman-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Insanlar', 'su-insanlar-cemcemi-cem-vvm62', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Insanlar

Sevgililerine 

Gül toplamaya giderlerken

Cayir cimen üstünde güle güle giderler

Bilmezler ki sevgilerini ezerler

Görmezler ki papatyalar

Ayaklar altinda 

Kalmis kalmamis hic farketmezler', 'Insanlar Sevgililerine  Gül toplamaya giderlerken Cayir cimen üstünde güle güle giderler Bilmezler ki sevgilerini ezerler Görmezler ki papat...', ARRAY['Türk Edebiyatı','Şiir','Cemcemi Cem']::text[], 8.5, '{"poet":"Cemcemi Cem","poet_slug":"cemcemi-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/su-insanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çek Git Bensiz Gidebilirsen', 'cek-git-bensiz-gidebilirsen-i-rfan-kayagil-loqyz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüksek bir yerde oturmuşum

Sarhoş gibi, hafiften

Ömrümdeki belki son Çarşamba

Elimde kadeh 

Ve saat yirmi dördü vurmakta

Başım mı dönüyor bilmem

Gün batımını çoktan geçtik 

Güneşi mi kokluyorum son dem

Ben derim ki isabetli, nihayet

Yaşadığım ilk hasret

Güneş bana soğuk gelir

Elbet yanan yüreğimden

Hasret dedin de birden aklıma esti

Rüzgarla akrabalığın.

Kaçıp gidişin var ya

Yelesine tutunup aniden

Fırlayıp dört nala, rahvan gitmek varken

Bu acelen ne? Gecenin karanlığında

Kader denilen çizgiyi aşabilir misin? 

Buysa istediğin

Çek git bensiz gidebilirsen

Ankara 2005 Ağustos', 'Yüksek bir yerde oturmuşum Sarhoş gibi, hafiften Ömrümdeki belki son Çarşamba Elimde kadeh  Ve saat yirmi dördü vurmakta Başım mı dönüyor bi...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kayagil']::text[], 8.5, '{"poet":"İrfan Kayagil","poet_slug":"i-rfan-kayagil","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cek-git-bensiz-gidebilirsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiyle', 'sevgiyle-tunahan-ermihan-wnkph', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '“ Allah İnşallah ”

Yansın o bedenin hasretimden yıllarca

Sönmesin yüreğindeki ateş dilerim Allah’ tan

Karlar altında soğukta da kalsan sarılasın ona

İçten içe sevdam dediğimle tutuşasın inşallah

Yaban topraklarda hüküm süremesin hanedanlığın

Fermanında krallığında bedenimden öteye gitmesin dilerim Allah’tan

Emrinde hâzır bir teban ben olayım

Benden başka seveninde kalmasın inşallah

Ben bu satırları yazmaya devam etsem de ömrüm boyunca

Senin yine de umudun peşinde mutlu olmanı dilerim Allah’tan

Ben unutamayacak olsam da kadınım dediğim günleri

Sen artık başkalarına adamım de inşallah', '“ Allah İnşallah ” Yansın o bedenin hasretimden yıllarca Sönmesin yüreğindeki ateş dilerim Allah’ tan Karlar altında soğukta da kalsan sarıl...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgiyle-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmen', 'ogretmen-muharrem-cetinkaya-r14kl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ÖĞRETMEN (ORTAK ÇALIŞMA) 

Sesi ile canlandırır okulu 

Gülen gözle bize bakar ÖĞRETMEN 

Eli kitap ve tebeşir kokulu 

Okur yazar kalbe akar ÖĞRETMEN ________(ayak dörtlüğü) 

Verir bize çeşit çeşit bilgiyi 

Yanlışlarda kullanın der silgiyi 

Hiç eksiltmez hep gösterir ilgiyi 

Çağdaşlığa ışık yakar ÖĞRETMEN ________Rahim TAŞ 

Gözüm açtım sana geldim koşarak, 

Bilgi verdin sevgi verdin coşarak, 

Sorun etmez sorunları aşarak, 

Güler yüzle derse girer ÖĞRETMEN __________İshak Özlü 

Yüreğinde vatan millet sevgisi 

Kara tahta tebeşir ve silgisi 

Öğrenciler başarının simgesi 

Geleceğe ışık saçar ÖĞRETMEN _________Muharrem Çetinkaya 

Hem annedir hem babadır bizlere 

İlim irfan kaynağıdır cahile 

Ona saygı bir görevdir herkese 

Geleceğin kurucusu ÖĞRETMEN __________ömer yılmaz / sensinya 

Defter kalem tutmasını gösterdin 

İlk yazmayı okumayı öğrettin 

Anne baba gibi sevgi verirdin 

Kutsal ismin yürek yakar ÖĞRETMEN _____Berrin Civgin 

Milyonlara gerçekleri öğreten 

Gece gündüz ayırmadan didinen 

Gözyaşını akıtmayı bilmeden 

Canını dişine takar ÖĞRETMEN __________Burhanettin Akdağ 

Dereleri tepeleri aşarak 

Zorluklara direnerek koşarak 

İlim irfan öğrenelim yeter ki 

Yarınlara ışık tutar öğretmen __________Fatma Çağlayan 

Beyaz tebeşiri ışık yarına. 

Canın esirgemez vatan uğruna. 

Cehaletin kalem çalar bağrına. 

Gözetmez menfaat, çıkar Öğretmen _______Hüseyin Sığırtmaç 

Okul evi çocuklardır bahçesi 

Simittir azığı bilgi bohçası 

Öğretmendir hocaların hocası 

Cehaleti aşkla yıkar öğretmen __________Ömer Ekinci Micingirt 

Gözleri kitaptan kalkmazsa eğer 

Öğrencisiyle gülüp ağlarsa eğer 

Öğrettikçe çoğalıp artarsa eğer 

Elleri öpülesi olur öğretmen ___________Metin Yaltı 

Sen ufkuma güneş gibi doğansın 

Sen çalışkan öğrencide coşansın 

Karanlıktan aydınlığa koşansın 

İlim irfan kültür akar öğretmen ________Berrin Civgin 

Karanlık gecelerdeki ışığım 

Gelecek yolundaki ilk adımım 

Beyinlere akan bilgi ırmağım 

Daima gülerek bakar ÖĞRETMEN__________Burhanettin Akdağ 

Zor anlarımda yetişen hızırım 

Daraldığım anlarda tek koşanım 

Yüreğimdeki serin ferahlığım 

Derdime gönülden yanar ÖĞRETMEN________Burhanettin Akdağ 

Çok uzaklardaki bir dağ köyünde 

Gülümser her sabah kardelenlerine 

Sevgi dolu yüreği hep en önde 

Umutla sınıfa girer öğretmen ___________Umut Gül 

Yansa da içi vurmaz ki dışına 

Sevgiyi ortak eder hep aşına 

Rastlamadım asla onun kışına 

Her mevsimde olur bahar öğretmen _______Umut Gül 

Söyler doğruları bilmez yalanı 

Amacı “adam” etmektir insanı 

Sevgi olur bir çağlayan misali 

Yürekten yüreğe akar öğretmen __________Umut Gül 

Cehalete son verirsin evrende 

Sevilirsin sayılırsın çevrende 

İlim irfan meşalesi sayende 

Yükselerek arşa çıkar ÖĞRETMEN _________Feride Şentürk 

ŞİİR TARLASI GRUBU 

*Tüm öğretmenlerimizin Öğretmenler Gününü kutlar, eğitimli ve çağdaş bir toplum için göstermiş oldukları katkılarından dolayı teşekkür ederiz. 

Gösterdikleri duyarlılıktan dolayı ortak çalışmaya katılan tüm ŞİİR TARLASI grubu üyelerine ve ayak dörtlüğünü veren Sayın Rahim TAŞ’a teşekkürler', 'ÖĞRETMEN (ORTAK ÇALIŞMA)  Sesi ile canlandırır okulu  Gülen gözle bize bakar ÖĞRETMEN  Eli kitap ve tebeşir kokulu  Okur yazar kalbe akar ÖĞ...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/ogretmen-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Derinleşmekte Sızım', 'canim-derinlesmekte-sizim-fidan-bulut-gng9w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir damla göz yaşımdır şimdi,

Sakladığım sevdama dair.

Sindiğimde sinene akıtacağım yüreğine

Bir başka sevdim seni bu gün,

Toprağına düşen ilk yağmurla

Sevdama bereket diye.....

Düşünmek seni sevgilim

Senli sensiz,anlamlı anlamsız,

Canlı cansız tüm zamanlarda..

İş edindim,aş edindim,nefes edindim 

Nakış nakış işlemeyi, dokumayı ilmek ilmek

Gözlerim gözlerine yıldız yağdırıyor

kalbimde arı telaşı.

Kır çiçeklerin benim için açsın.

Gecene güneşi getireceğim söz sana sevdiğim

Ay darılmasın diye onu da; 

Yüreğimin bir köşesine saklayacağım

Senden yana umutlarıma eş olsun diye......', 'Bir damla göz yaşımdır şimdi, Sakladığım sevdama dair. Sindiğimde sinene akıtacağım yüreğine Bir başka sevdim seni bu gün, Toprağına düşen i...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/canim-derinlesmekte-sizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Çok Seviyorum', 'seni-cok-seviyorum-fatih-demir-lydzd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Önceleri söyleyemezdim,

Söyleyemezdim, aşkım diye.

Utanıp bakamazdım,

Bakamazdım,güzel yüzüne.

Şimdi ise dayanamıyorum,

Dayanamıyorum, sensizliğe.

Saatlerce bakmak,

Bakmak istiyorum, gözlerine.

Sevgin gittikçe büyüyor,

Büyüyor kalbimde.

Sana her seferinde demek istiyorum,

SENİ ÇOK SEVİYORUM, hemde ölürcesine...', 'Önceleri söyleyemezdim, Söyleyemezdim, aşkım diye. Utanıp bakamazdım, Bakamazdım,güzel yüzüne. Şimdi ise dayanamıyorum, Dayanamıyorum, sensi...', ARRAY['Türk Edebiyatı','Şiir','Fatih Demir']::text[], 8.5, '{"poet":"Fatih Demir","poet_slug":"fatih-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-cok-seviyorum-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '--Mavi sevdam', 'mavi-sevdam-ahmet-bektas-j01v5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mavi Sevdam

Nedensiz doluyor mutluluk içime,

Mavi bir sevdanın şokunu yaşıyorum.

Er geç bir gün sen de

Anlarsın beni demiştim...

Küllenen bir sevdayı

Körükleyen bir gölge...

Alev alev özlem ateşi,

Aydınlattı mavi geceyi...

Özlemek de güzel, özlenmek de...

Aradan uzun yıllar da geçse

Seviyorsan mutlaka söyle,

Kavuşsan da son nefeste.

Kaybetmedin ki üzülme,

İnsan ebedi elbette.

Yarım kalan nice sevdayı,

Yaşamak mümkün cennette.

Ahmet Bektaş

24.11.2005', 'Mavi Sevdam Nedensiz doluyor mutluluk içime, Mavi bir sevdanın şokunu yaşıyorum. Er geç bir gün sen de Anlarsın beni demiştim... Küllenen bi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bektaş']::text[], 8.5, '{"poet":"Ahmet Bektaş","poet_slug":"ahmet-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mavi-sevdam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Tuvalim Yeşil', 'umut-tuvalim-yesil-ertugrul-sakar-viek5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yayılan bir damlayı kuşattın mı

Halkaların kalkanlarında bir sevdayı

Düşlerinde

Düştün mü hayallerine gelişmelerin

Söz kürkünü sarılırsın, çıplaksan

Isıtır umulmadık üşümelerini

Kaşlarında

Koştun mu göz dünyanın derinliklerine

Niçin değişiyorum seni düşünürken niçin

Boşlukların ıssız döllerinde

Üşüyorum

Üşümelerimi hasret ateşine attığımda

Yakın yalın bir yalnızlığım var seninle

Yalansız bir yıldız görünmeyen

Görünmeyen bir öteki sensin

Sensin gönül köşkümün boyacısı

Yıldızlar yukarıda

Ben aşağıda bekliyorum

Gönül coğrafyam mavi

Umut tuvalim yeşil', 'Yayılan bir damlayı kuşattın mı Halkaların kalkanlarında bir sevdayı Düşlerinde Düştün mü hayallerine gelişmelerin Söz kürkünü sarılırsın, ç...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/umut-tuvalim-yesil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dermanına Dert Olmak', 'dermanina-dert-olmak-abdullah-acar-v0b7a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yatağın olamasam da akıp gideceğin

Selinin önünde bent de mi olamam

Dermanı olamıyor isem derdinin

Dermanına dert de mi olamam

(25/11/2005- Ankara)', 'Yatağın olamasam da akıp gideceğin Selinin önünde bent de mi olamam Dermanı olamıyor isem derdinin Dermanına dert de mi olamam (25/11/2005- ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Acar']::text[], 8.5, '{"poet":"Abdullah Acar","poet_slug":"abdullah-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dermanina-dert-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-nuri-ozoglu-h5220', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her can cananı özler,

Cananda canı gizler,

Olmaya canan bende,

Bende kıymet ne gezer.', 'Her can cananı özler, Cananda canı gizler, Olmaya canan bende, Bende kıymet ne gezer....', ARRAY['Türk Edebiyatı','Şiir','Nuri Özoğlu']::text[], 8.5, '{"poet":"Nuri Özoğlu","poet_slug":"nuri-ozoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-488-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Okurken', 'sen-okurken-askin-ay-7o6zu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen yazdıklarımı okurken 

Ben gitmiş olacağım yanından

Ayaklarım ne kadar dönmeye çalışsa da

kalbim acıdan paramparça olsa da

Sen bu yazdıklarımı okurken 

Ben gözlerimde yaşlar dolu

Elimdeki sıcaklığını kaybetmemek için

Avuçlarımı sıkı sıkıya kapatıp..

Sen yazdıklarımı okurken 

Çoktan ıslanmış olacak yanaklarım

Kalbim anılarla dolu uzaklaşırken ben,

Sen şaşkınlıktan ne yaptığını bilmeden..

Sen yazdıklarımı okurken 

Ne anlama geldiğini yeni anlamışken

Ne yapacağını daha kestiremezken sen

Ben gitmiş olacağım yanından

Yazdıklarımı okurken sen

Ben başbaşa kaldığım yalnızlığımla

Çoktan tüketmiş olduğum umutlarımla

Yokluğunla buz tutmuş tenimle beraber

Ağlamaktan kızarmış gözlerimle ben

Sıkı sıkıya sarıldığım anılarımla

kimseye söyleyemediğim sevgimle

Tüm yaşanmışları gömüp kalbime

Çıkmış olacağım hayatından

Elveda sevgilim

Unutma ben seni çok sevdim

Elveda sevgilim

Unutma biz çok şeydik

Hayatımızda açtığımız parantezdik! 

(16-11-2005,İst.)', 'Sen yazdıklarımı okurken  Ben gitmiş olacağım yanından Ayaklarım ne kadar dönmeye çalışsa da kalbim acıdan paramparça olsa da Sen bu yazdıkl...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Ay']::text[], 8.5, '{"poet":"Aşkın Ay","poet_slug":"askin-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sen-okurken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sana Ne Yaptımki', 'ben-sana-ne-yaptimki-mehmet-sait-akkus-nhhwo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni benden aldılar

Beni yaraladılar

Kanadımı yoldular

Ben Sana ne yaptımki

Seni sevmekten başka

Doyamadan o aşka

Senin tadın bambaşka

Ben sana ne yaptmki

Seni delicesine

Sevdim ölürcesine

Yeri öpercesine

Ben sana ne yaptımki

Pişman oldum sevmeye

Karar verdim dönmeye

Buealardan gitmeye

Ben sana ne yaptımki

Ben sana tapar idim

Seni taç yapar idim

Yürekten sever idim

Ben sana ne yaptımki

Ben dayanamıyorum

Üzülüp gidiyorum

Bi elveda diyorum

Ben sana ne yaptımki', 'Seni benden aldılar Beni yaraladılar Kanadımı yoldular Ben Sana ne yaptımki Seni sevmekten başka Doyamadan o aşka Senin tadın bambaşka Ben s...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-sana-ne-yaptimki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünmek', 'seni-dusunmek-askin-ay-8frdr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlığında en parlak yıldıza takılırya gözlerin,

Elini uzatıp dokunmaya çalışırsın

Avuçlarına alıp parlaklığını yaşamak

ve sonra tekrar bırakmak gökyüzüne

Dokunmak mümkünmüdür oysa? 

İmkansızlıklar içinde seni düşünmek

Seni yaşamak, seni hissetmek

Gökyüzündeki yıldız kadar uzaksındır sen

Benim tek lüksüm seni düşünmek

Parlaklığına bakıpta avutmak kendimi

Kalbimde saklı sevginle yetinmek

İşte benim tek isteğim seni düşünmek

Seni seninle yaşayabilmek..

(10-11-2005, ist.)', 'Gecenin karanlığında en parlak yıldıza takılırya gözlerin, Elini uzatıp dokunmaya çalışırsın Avuçlarına alıp parlaklığını yaşamak ve sonra t...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Ay']::text[], 8.5, '{"poet":"Aşkın Ay","poet_slug":"askin-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-dusunmek-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '\\..ERKEKÇE PİŞMaN OL...\\', 'erkekce-pi-sman-ol-dilek-egri-extx5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'geçici mutluluklar peşinde koşmak

kalıcı yorgunluklar bırakır erkek yüreğine

ne kaslı kolların

ne delikanlı naraların

geri getirmez giden gururlu bir kadını..

pişmanlıkların koluna dizilir

tespih diye çekersin yanlışlarını

''günahım neydi ve  nerde beni seven o kadın? ''

diye mırıldandıkların, 

geveze yalnızlığındır..

susturamazsın susturduğun yüreğini

ve durduramazsın sus olup gideni...

sahte ilişkiler ilişkisizlikler sahteleştirir seni

bozdurmaya kalksan yüreğini 

beş para etmez..

sen istediğin kadar harca eskileri

aşklarını./.seni./.beni

bitti...

24/11/05', 'geçici mutluluklar peşinde koşmak kalıcı yorgunluklar bırakır erkek yüreğine ne kaslı kolların ne delikanlı naraların geri getirmez giden gu...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/erkekce-pisman-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorgu', 'sorgu-salim-kabasakal-8h8y2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yankılarımla çırpındım; derin bir  sessizlik çökmüşken;  zaman sanki beni sorgulamadan akıp gidiyordu.

 Peki ne değişti ne kayboldu bunca zaman...

 30 yaş ağırmı geldi? 

 Bilmiyorum sadece dalgalı bir deniz misali ruhum

 öyle çalkantılıki helede hummalı beynim nerde durulur bilemiyorum,

 Kelimeler kalemimden uzakta duruyor ve ela gözlerimdeki güneşi kucaklayan 

 gizli ve yalnız mavi özgürlük ise parmaklarımın arasında; 

 sıcak çayımı yudumlarken kadıköy rıhtımında, yudum yudum kayboldum, 

 gözlerimin önünden çalkantılarla geçti bir on yıl oysa; 

 sallanan gemiler misali gerilerde bıraktığım köpüklerimi sarmaladım.. ve savurdum bir 

 geleceği bilinmez bir sonraya. sadece boş bir kadeh arkasında gülümsedim. 

 Boğazıma takılan üç beş kelime ise halen pişmanlığımla neden? 

 bu sorgularım...  Şimdi kaybolup gitme zamanı gölgem bile bugün sessiz, oysa ufukta

 boğulurken güneş, gecenin doğum sancısında ben sadece maviyi kucakladım. 

 şimdi mutluluğa doğrumu koşuyorum yoksa bir bataklıkta sivrisineklerlemi 

 boğuşuyorum? . 

 Kimliksiz düşüncelerim içinde yankılarımla boğuşup duruyorum. Oysa kaybettikleri mi kim     verecek ki', 'Yankılarımla çırpındım; derin bir  sessizlik çökmüşken;  zaman sanki beni sorgulamadan akıp gidiyordu.  Peki ne değişti ne kayboldu bunca za...', ARRAY['Türk Edebiyatı','Şiir','Salim Kabasakal']::text[], 8.5, '{"poet":"Salim Kabasakal","poet_slug":"salim-kabasakal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sorgu-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana bir şeyler anlatıyor gibisin.', 'bana-bir-seyler-anlatiyor-gibisin-ercan-akbay-qi07a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana bir şeyler anlatıyor gibisin

   Sevdadan söz etme sakın inanamam

   Ayrılık,dargınlık bitti der gibisin

   Bir daha boş yere yeniden yanamam.

   Dostça ayrılalım ikimiz ne dersin

   Senin uğruna bir gül gibi solamam

   Bu son akşam kalmasın bende gözlerin

   Bir suçlu gibi ömrümce taşıyamam.....

                                   10.8.1990  da İsmail Demirkıran

                                    Kürdili Hicazkar makamında bestelemiştir.

                                    TRT Repertuar no.1183', 'Bana bir şeyler anlatıyor gibisin    Sevdadan söz etme sakın inanamam    Ayrılık,dargınlık bitti der gibisin    Bir daha boş yere yeniden ya...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bana-bir-seyler-anlatiyor-gibisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sade hayal', 'sade-hayal-salim-kabasakal-v1v33', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geçmiş bahar mimozası; 

Ellerimin arasında sıkı sıkı tuttuğum; 

bir hayal tufanı öncesi 

gül dalından savrulalı al yaprak 

ellerimin arasında senin raks eden yüzün; 

Eski kerpiç evlerin ördüğü dar sokaklardan geçerken 

at arabaları ile

geçmişin sesiyle seni yaşadım 

içimde üşümekli bir yaz havasında.

Bugün gözlerimi açar açmaz 

sebebini hiç bilemediğim bir arzuydu bu.

Uzun çok uzun zaman önce bırakmıştım  ben onu? 

Kalbimde bir yerlerde derken beni geçmişten alıp mahkemeye çıkartan...

Duru duruydum birden dalgalandım,

Gözlerimin içindeki şu ışığı bir görebilsen 

bir anlayabilsen kelimelerin beni uzaklara nasıl taşıdığını...

Sana beni nasıl anlatsamki;', 'Geçmiş bahar mimozası;  Ellerimin arasında sıkı sıkı tuttuğum;  bir hayal tufanı öncesi  gül dalından savrulalı al yaprak  ellerimin arasınd...', ARRAY['Türk Edebiyatı','Şiir','Salim Kabasakal']::text[], 8.5, '{"poet":"Salim Kabasakal","poet_slug":"salim-kabasakal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sade-hayal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-gozem-basak-mbrih', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimleri unutmadı ki bu gönül, seni unutmasın? 

Hangi acıları taşımadı ki, sen hafif kalırsın.

Çektiğim son çile sen olasın,

Gönülde birazcık nefes alsın.

Gelse de üstüme bin bir dert,

Ben böyleyim edemem şikayet,

Yoktur içimde cahil cesaret,

Bu gönülde böyle yaşasın.

Bu yaşlara gelmedim ki kolayla,

Hayatım geçmedi hayla huyla,

Yanarım sadece tek bir acıya,

Ölümdür gerçek okan gerisi palavra.

Sevdaymış, aşkmış hepsi geçici,

Gönlümde kalmaz bile izleri.

Bu dünyanın değişmez gerçeği,

Sevdikçe artıyor yaşamın zevki.

Tek bir sevgiyle kalmaz bu gönül,

Atılan her sevgi tohumu çürümez, büyür.

Sevmeden yaşamak beni öldürür,

Aç gözlüdür bir türlü doymaz bu gönül.', 'Kimleri unutmadı ki bu gönül, seni unutmasın?  Hangi acıları taşımadı ki, sen hafif kalırsın. Çektiğim son çile sen olasın, Gönülde birazcık...', ARRAY['Türk Edebiyatı','Şiir','Gözem Başak']::text[], 8.5, '{"poet":"Gözem Başak","poet_slug":"gozem-basak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gonul-129-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-necmi-kuscan-exa2d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kar altında kalmış dağ çiçeği

Arılara isyan etmiş bal peteği

Soğukta geçirmiş kurt yavrusu geceyi

Sana noluyor gönlümün kelebeği

Sarmışken duygu battaniyemin ilmiği

Açılmışken sana kalbimin derinliği

Bak getirdim karanlıktan ay dedeyi', 'Kar altında kalmış dağ çiçeği Arılara isyan etmiş bal peteği Soğukta geçirmiş kurt yavrusu geceyi Sana noluyor gönlümün kelebeği Sarmışken d...', ARRAY['Türk Edebiyatı','Şiir','Necmi Kuşcan']::text[], 8.5, '{"poet":"Necmi Kuşcan","poet_slug":"necmi-kuscan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ben-215-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Limanda', 'bu-limanda-savas-dincbas-auou0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'içi boş bir zamanda yürüyorum

zaman içi boşken daha ağır

durağan bir yaşam

yüzeyi dümdüz, kıpırtısız bir göl gibi

fırtınalara gebe yüreğim

kasırgaların özleminde

öyle bir patlıyacağım ki

yanardağlar bile kıskanacak

lavlarım dolduracak zamanın içini

mevsimleri değişecek

fırtınalarım yok edecek sevisizliği

ve sonunda sükuna erdiğinde bu liman

ne yazık ki sen

demir atacak bir yer bulamıyacaksın...', 'içi boş bir zamanda yürüyorum zaman içi boşken daha ağır durağan bir yaşam yüzeyi dümdüz, kıpırtısız bir göl gibi fırtınalara gebe yüreğim k...', ARRAY['Türk Edebiyatı','Şiir','Savaş Dinçbaş']::text[], 8.5, '{"poet":"Savaş Dinçbaş","poet_slug":"savas-dincbas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bu-limanda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şifana hicrane sinem', 'sifana-hicrane-sinem-ali-riza-unal-6qxaw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni mecnun-u meftun eden, ey nazar-ı didem,

Aç hicabı zülfü nigâr-a  gayrı sensiz nidem,

Ne ar koydun ne haya,bi çare hilkâtin oldum,

Nikap eyleme didâra, şifana hicrane sinem.', 'Beni mecnun-u meftun eden, ey nazar-ı didem, Aç hicabı zülfü nigâr-a  gayrı sensiz nidem, Ne ar koydun ne haya,bi çare hilkâtin oldum, Nikap...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sifana-hicrane-sinem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül İlacın', 'gonul-i-lacin-huseyin-sigirtmac-8vxtc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nerede bulunur gönül ilacın? 

Akıl derde düştü elinden gönül.

Dayadın bağrıma sevda kılıcın.

Döndürmezsin aşkın çölünden gönül.

Enginlere konmaz uçarsın yüce.

Canlanır her hücren güzel görünce.

Düştüğün yol çetin, kıldan da ince.

Aşarsın sevdanın belinden gönül.

Yar hayali yangın, yürekte közü.

Düşüncemde kaldı sohbeti, sözü.

Göremeden ömür baharı, yazı.

Can perişan duygu selinden gönül.

Sığırtmaç’ı koyup yar dağlar aştı.

Yitirdim izini, pusulam şaştı.

Duygu nağme oldu ses verip coştu.

Medet bekler sazın telinden gönül.', 'Nerede bulunur gönül ilacın?  Akıl derde düştü elinden gönül. Dayadın bağrıma sevda kılıcın. Döndürmezsin aşkın çölünden gönül. Enginlere ko...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gonul-ilacin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeye Rağmen', 'herseye-ragmen-ufuk-coban-mmro3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaçış savunmadır yağmurların damlalarından,

Acı verir mi kimse bilmez durup yukarı bakmamıştır ki.

Belki bir mutluluk işler içine kalıp bakmalarda,

Belki bir anıdır yılların fırtınalarında.

Neden kolay yol kısadır ışık olmasa da ucunda? 

Adımlar kendinden gider kaçış bulduğunda.

Bırakmaz kendinde kendi de bilmez ne olsa

Uzaklar yakındır kendinden kaçış yolunda.

Sevgi ölesiye olması lazım ölüm olmasa da ucunda,

Kavuşmalar yıllanmış olmalı günler geçsede,

Gözler hasret dolmalı yaşlar silinmemiş gibi,

Kollar öyle sarmalı ki bırakırsa ölecekmiş gibi.

Herşeye rağmenleriniz oldu mu hayatınızda? 

Benim üç tane oldu,

Herşeye rağmen çok sevdim onu,

Herşeye rağmen uzak tuttum kendimi,

Herşeye rağmen kaçtım üzmemek için onu...

25/11/2005 13:05', 'Kaçış savunmadır yağmurların damlalarından, Acı verir mi kimse bilmez durup yukarı bakmamıştır ki. Belki bir mutluluk işler içine kalıp bakm...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/herseye-ragmen-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahşer', 'mahser-hikmet-uzun-dj0l3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkına düşmüştür yanar,sine-i üryanım benim.

Her yerde cemalin arar,dide-i giryanım benim.

Yokmudur insafta karar,ruz-i mahşere mi koydun? 

Zeval-i firkatim benim, müddet-i hiçranım benim.

Veçhine mail olayım,kapında sail olayım.

Lutfuna nail olayım,Zülfünde zail olayım.

Davet; Değerli gönül dostu şair kardeşlerim

ikinci dörtlük için katkılarınızı bekliyorum.', 'Aşkına düşmüştür yanar,sine-i üryanım benim. Her yerde cemalin arar,dide-i giryanım benim. Yokmudur insafta karar,ruz-i mahşere mi koydun?  ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Uzun']::text[], 8.5, '{"poet":"Hikmet Uzun","poet_slug":"hikmet-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mahser-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Seninle Dolu', 'yuregim-seninle-dolu-askin-ay-hd91w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğim seninle dolu sevgilim.

Bedenimde tarifi mümkün olmayan duygular.

Kimseye anlatamadığım, paylaşamadığım.

Korkuyorum yalnızlığınla başbaşa kalmaktan.

Damarlarımda kan yerine sen dolaşıyorsun.

Gözlerimi bile kapamıyorum seni düşünürken,

Buna gerekte yok zaten.

Çünkü sen hep yanımdasın.

Parmak uçlarımda bile hissediyorum seni.

Kalbime sığdıramıyorum sevgini.

Ya sen sevgili, sen nasılsın? 

Gün gelipte unutacak mısın beni? 

Yeni hülyalara dalıp bırakır mısın beni? 

Sende istiyor musun beni, benim seni istediğim kadar? 

Gözüm, kulağım hep telefonda.

Sen aradığında bir başka güzel telefonun sesi.

Keşke hep duysam sesini.

Korkmakta seni sevmek kadar güzel.

Evet korkuyorum aşkından.

İçim titriyor, gözlerim dalıyor seni düşünürken.

Bunca yıldan sonra, tam unutmuşken

Aşk acısı çekmeyi ya tekrar hatırlarsam.

Ne kadar karşı koydum bir bilsen,

İçimde senin için esen fırtınalara.

Ama olmadı işte, ne kadar çabalasamda,

Gelip yerleştin kalbimdeki baş köşeye.

Uyuması için masal anlatılan çocuk gibiyim.

Benim masalımda, ninnimde sensin.

Seni düşünürken dalıyorum tatlı uykulara.

Ah bide rüyamda görsem seni,

Doyasıya öpüp koklasam, hiç sabah olmasa.

Yada gözümü açıpta seni görsem yanımda.

Sımsıcak baksan bana.

Yatağım, bedenim kokunla dolsa.

Ben bile sen koksam.

Korkuyorum yalnızlığınla başbaşa kalmaktan.

Korkuyorum telefonun sesini hiç duymamaktan.

Sana doyamadan çıkıp gitmen hayatımdan..

Biraz olsun seni seninle yaşamak,

Benide sana yaşatmak...

Dudaklarımın tadını hiç unutmamanı isterim.

Bakışlarımla, dokunuşlarımla rahatlamanı,

Huzur bulmanı.

Gözlerine benden başkasının bakmamasını.

Benim elim kadar sıkı tutma kimsenin elini.

kalbine de söyle atmasın bir başkası için.

Sakın sevgili, sakın unutma beni! 

(12-11-2005, İst.)', 'Yüreğim seninle dolu sevgilim. Bedenimde tarifi mümkün olmayan duygular. Kimseye anlatamadığım, paylaşamadığım. Korkuyorum yalnızlığınla baş...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Ay']::text[], 8.5, '{"poet":"Aşkın Ay","poet_slug":"askin-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/yuregim-seninle-dolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar Diye Diye', 'yar-diye-diye-nuri-ozoglu-5spkx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağladı gözlerim yar diye diye,

Yoksa gözlerime perde mi çeksem? 

Belki de kavuşmak zor diye diye,

Kendimi onulmaz derde mi çeksem?', 'Ağladı gözlerim yar diye diye, Yoksa gözlerime perde mi çeksem?  Belki de kavuşmak zor diye diye, Kendimi onulmaz derde mi çeksem?...', ARRAY['Türk Edebiyatı','Şiir','Nuri Özoğlu']::text[], 8.5, '{"poet":"Nuri Özoğlu","poet_slug":"nuri-ozoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yar-diye-diye-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşersen Kaldırmam', 'dusersen-kaldirmam-mehmet-aslan-a50dk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sonu uçurum bir yolda gidiyorsun

Anlatıyorum onu sevdiğini söylüyorsun.

Şunu bil ki bu sevdada yanılıyorsun

Ne kadar anlatsam da anlamıyorsun.

Kulak ver konuşan yılların tecrübesi,

Kalmamış olsa da hayattan beklentisi,

Mutluluğun olmuştur yaşam gayesi,

Kalmamıştır senden başka tesellisi.

Bebeğim aldırmıyorsun artık sözlerime,

Yalanda söylüyorsun baka baka gözlerime,

Bir gün zarar gelirse sevdiklerime,

Acırım sizlere verdiğim öğütlerime.

Ben anlatırken tıkıyorsun kulaklarını,

Sıkıştırınca da salıyorsun gözyaşlarını,

Ardı ardına sıralıyorsun tekrar yalanlarını,

Utanacaksın ileride hatırladıkça anılarını.

Gelecekte utanmamak için,

Vazgeç bu boş hayallerinden,.

Hoşnut değilim senin bu gidişinden,

Düşersen kaldırmam tutup ta elinden.', 'Sonu uçurum bir yolda gidiyorsun Anlatıyorum onu sevdiğini söylüyorsun. Şunu bil ki bu sevdada yanılıyorsun Ne kadar anlatsam da anlamıyorsu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dusersen-kaldirmam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Bir Gün', 'sensiz-bir-gun-mehmet-aslan-tlf8h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir günlük yokluğun bile

Bir yıl gibi geldi bana.

Sensizliğe alışmaya çalıştığımda bile

Dünya’nın sonu gibi geldi bana.

Hasretinle yaşadım o bir günü

Zevksiz, neşesiz ve de sensiz.

Düşündüm sensiz geçecek her günü

Yaşadım o günü perişan ve çaresiz.

Yokluğun bana bir şey öğretti

Acı bir şeymiş sensiz kalmak.

Gerçekse yokluğun beni mahvetti

Teselli etmedi hayalinle avunmak.

Hani girme demiştim ya rüyalarıma

Dinlemedin dün gece rüyamdaydın.

Benzedin sende sahte aşklarıma

Keşke sende kalbimi çalmasaydın.

Soracaksın yine kime yazdığımı

Bende sana masal anlatacağım.

Söylesem bunu yazarken ağladığımı

Kızacaksın ama yinede yazacağım.', 'Bir günlük yokluğun bile Bir yıl gibi geldi bana. Sensizliğe alışmaya çalıştığımda bile Dünya’nın sonu gibi geldi bana. Hasretinle yaşadım o...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sensiz-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Direnme', 'direnme-mehmet-aslan-2m7c7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biliyorum çekiniyorsun

Birazda korkuyorsun

Sende sevmiyorsun

Sevgimi anlamıyorsun

Belki de anlıyorsun

Cevap vermiyorsun

Ya da nazlanıyorsun

Peşinden koşturuyorsun

Bıktırmaya çalışıyorsun

Boşuna uğraşıyorsun

Kendinle inatlaşıyorsun

Kalbine yeniliyorsun

Sevgimle savaşıyorsun

Kaybeden oluyorsun

Boşuna direniyorsun

İçimde yaşıyorsun

Yalan sanıyorsun

Gerçeği görüyorsun

Gözünü kapıyorsun

Gerçekten kurtulamıyorsun

Direnme yanıyorsun

Beni de yakıyorsun', 'Biliyorum çekiniyorsun Birazda korkuyorsun Sende sevmiyorsun Sevgimi anlamıyorsun Belki de anlıyorsun Cevap vermiyorsun Ya da nazlanıyorsun ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/direnme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor Düşün', 'mor-dusun-mehmet-aslan-64mvo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mavi düşün demiştim ya sana,

Sen yine mor düşünüyorsun.

Haklısın moru yazmamıştım sana,

Öğrendin artık anlamını biliyorsun.

Hakaretlerle dolu göndermiştim sana,

Anlamadan bilmeden güzeldi diyorsun.

Başkasına yazılmıştı o ait değildi sana,

Yinede kızmadın beni şaşırtıyorsun.

Artık kızmıyorsun aşkım deyince sana,

Bir ikilemdesin anlam veremiyorsun.

Sadece dokunduğum zaman sana,

Belli etmesen de anlıyorum kızıyorsun.

Bilemiyorum nasıl davranacağım sana,

Bir gün sevindirip öbür gün üzüyorsun.

Söyleyemiyorum açıkça sevdiğimi de sana,

Aslında gerekte yok çok iyi anlıyorsun.

Bazen sorular sorduğumda sana,

Yalan cevaplıyor beni kızdırıyorsun.', 'Mavi düşün demiştim ya sana, Sen yine mor düşünüyorsun. Haklısın moru yazmamıştım sana, Öğrendin artık anlamını biliyorsun. Hakaretlerle dol...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mor-dusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözler', 'gozler-zahide-handan-erengil-8g3q4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerin olduğu yerde,sözlere gerek yoktur.

Gözler,özlemi,sevdayı,şevkati anlatır.

Gözler vardır,hırsı,ümitsizliği,kederi anlatır.

Gözlerin olduğu yerde,sözlere gerek yoktur.

Gözler,aşkı,masumiyeti,vefayı anlatır,

Gözler vardır,kıskançlığı,öfkeyi anlatır.

Gözlerin olduğu yerde,susar diller,

Gönüllerin anlatamadığını,anlatır gözler.', 'Gözlerin olduğu yerde,sözlere gerek yoktur. Gözler,özlemi,sevdayı,şevkati anlatır. Gözler vardır,hırsı,ümitsizliği,kederi anlatır. Gözlerin ...', ARRAY['Türk Edebiyatı','Şiir','Zahide Handan Erengil']::text[], 8.5, '{"poet":"Zahide Handan Erengil","poet_slug":"zahide-handan-erengil","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gozler-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki memleket…', 'i-cimdeki-memleket-muammer-celik-vl9l6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '…darmadağın 

şiir şiir akan ırmakların 

önüne çekilen barajları var 

tirübünleri kör

duvarları yüksek

akmayan,

patlamaya hazır suları var! ... 

Gözlerimdeki gözlerin bulanık 

geçmeyen bir gecem yok uyanık 

dökmüyor artık, bozulmuş 

çeşmelerimin kurnası 

sen var ya sen… 

işte yoksun, 

ey gönlümün hilebaz kumarbazı! ... 

Bir sevda masalıydın 

bin yıllık yoldan gelen 

geçtiği yolların 

altını üstüne çeviren 

yüreğimin eşiğine 

tozlu ayaklarınla bastın 

anladım, 

benim canımaymış senin kastın! ... 

İçimdeki memleketler 

hala darmadağın 

yeraltı gölümsün artık 

sakladım, altına 

gönlümdeki karlı dağın 

sen bile 

abdest alamayacaksın o gölde! 

boğulursun, abdestsizce ölürsün, 

denemeye kalkma, sakın! ... 

BirDeli

25.11.2005', '…darmadağın  şiir şiir akan ırmakların  önüne çekilen barajları var  tirübünleri kör duvarları yüksek akmayan, patlamaya hazır suları var! ....', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/icimdeki-memleket-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşümdeki Rüya', 'dusumdeki-ruya-ali-baksi-qqyyh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Unuturum sözçüklerimi,

Seni görür gibi düşlerimi,

Aşkın adı hüzün olur,

Sever olur  gidişimde,

Yokluğuna dayanır bu acı,

Varamam sana bu durumda,

Binemem ben giden dolmuşa,

Benim sancılarımın depremidir bu,

Eksik olan düşlerimde,

Gülüşünde eski bir aşk,

Seni sevmek neyi değiştirirdiki? 

Giderim senle olan düşlerime,

Yollarım yorar beni,

Sever gibi düş kayıp? 

Kırılır aynalarım,

Seni görür gibi,

Yanar ateş ışıgında,

Bir ben yanarım,

Birde benle olan düşlerim,

Varamam sana bu durumda,

Kirlenir rüya,

Olmasa sensiz bir dünya,

Biner giderim uzağa,

Ucar giderim,

Mavi olan buluta,

Unuturum unutamadığım zamanlara! ! ! 

Zulüm gibi,

Giderim  yakın olduğun uzağına,

Senleymiş gibi,

Aşk hüzün olur,

Sever olup giderim,

Düş sokağına...', 'Unuturum sözçüklerimi, Seni görür gibi düşlerimi, Aşkın adı hüzün olur, Sever olur  gidişimde, Yokluğuna dayanır bu acı, Varamam sana bu dur...', ARRAY['Türk Edebiyatı','Şiir','Ali Baksı']::text[], 8.5, '{"poet":"Ali Baksı","poet_slug":"ali-baksi","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dusumdeki-ruya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özel Birgün', 'ozel-birgun-mehmet-aslan-c3beb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Oku hepsini, günün anlamını unutmadan,

Anlayarak oku, fakat hiç sıkılmadan,

Sabredin ne olur, bitene kadar ağlamadan,

Yorumlayın teker teker, ama darılmadan.

Bu günün anlamını biliyor musun,

Yoksa diğer günlerden farksız mı diyorsun,

Değilse, o zaman sende birini seviyorsun,

Fakat kimi, onu hiç söylemiyorsun.

Sana açıkça sevdiğimi söyleyebilsem,

Kırmızı bir gül ile ayağına gelsem,

Seni seviyorum deyip te sana versem,

Verirdim; alınıp ta darılmayacağını bilsem.

Kestiremiyorum senden ne karşılık göreceğim,

Nasıl cevap verirsin hiç onu bilemeyeceğim,

Onun için sana bir şey söyleyemeyeceğim,

Hediyem bu kitaptır, sana verebileceğim.', 'Oku hepsini, günün anlamını unutmadan, Anlayarak oku, fakat hiç sıkılmadan, Sabredin ne olur, bitene kadar ağlamadan, Yorumlayın teker teker...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozel-birgun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz üç kişiydik', 'biz-uc-kisiydik-enes-ates-9ewh4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '..destina''ya.. 

Biz üç kişiydik

   ''o'' vardı

  '' ben '' vardım

  bir de '' başkası''...

            Üç kişiydik biz,

           Yakınırken yalnızlığımıza çaresizce

          Buluverdik mucizevî ruhlarımızı...

  ''başkası''nı sevemedim

''o''nu sevdiğim kadar..

               ''ben'' kadar olamadım

        ''o'' istediğinde ''başkası''nı

       Diyeceklerim vardı ama,

            .................Konuşamadım...............

         Yıldırım gibi inerdi beynimize seslerimiz..

          Dağlarımızda şakayıklar açmadan önce

            Yüzlerimiz ağlamadan önceydi seviştiklerimiz.........

           ''o'',

          sessiz,

         mülayim,

    şehlâ idi masumiyetinde..

                    Derin helezonlar çiziyordu yüreğime

                   Öyle bîmecal, öyle çaresiz....

                     Ben vardım hudutlarında

               Sesim vardı gözyaşlarımdan önce.

                   İçimde ''o'' vardı,

               Biz vardık gerçek, ve yüce! ! ...

 Sade, mistik arayışlar içinde ''o'',

 ''başkası''na öykündü bensiz gecelerinde..

         Kifayetsiz kalan kelimelerin arasında

          Bir şarkı vardı mırıldandığı; ; ; ; ; ; ; ; ; ; ; 

        notaları ''ben''i çağıran..

              ................''başkası''nı isteyen hecelerinde..

  Dinmek bilmedi içimin fezasında ihaneti

 Sükûtu çağırarak mâbedime,

Yalnızca istememek kaldı ''başkası''nı

::::          ''başkası''nı istememek! ! 

 İnadına,,

     ....Ölümüne...

                  Biz üç kişiydik,

             ''o'', ''ben'', bir de ''başkası''..

  İkiye düşmeden önce nüfusumuz,

 ''ben'' afaroz edilmeden önce...

               Ve ''başkası'' paylaşmadan önce

        aynı kaderi benimle..

                 ..........Sevdâmız, tek kişi kalmadan önce....

02.07.2004 

          02:24', '..destina''ya..  Biz üç kişiydik    ''o'' vardı   '' ben '' vardım   bir de '' başkası''...             Üç kişiydik biz,            Yakınırken yaln...', ARRAY['Türk Edebiyatı','Şiir','Enes Ateş']::text[], 8.5, '{"poet":"Enes Ateş","poet_slug":"enes-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/biz-uc-kisiydik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyor', 'korkuyor-mustafa-yazka-7ji6h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsanın özelliği doğru dürüstlük,

Doğruyu destekten niçin korkuyor? 

Zararın bilsede oluyor küslük,

Barışmaktan niçin korkuyor? 

Yoldan çıkarır aşırı bolluk,

Bir dost bulmada çekiyor zorluk,

Yalakasından bulur muzurluk,

Dürüst yoksuldan niçin korkuyor? 

Mustafa kimine korkuyor dersin,

Varını yoğunu sanamı versin? 

İyiliğe kemlik bulur bilirsin,

Ağzı yanık onun için korkuyor.', 'İnsanın özelliği doğru dürüstlük, Doğruyu destekten niçin korkuyor?  Zararın bilsede oluyor küslük, Barışmaktan niçin korkuyor?  Yoldan çıka...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yazka']::text[], 8.5, '{"poet":"Mustafa Yazka","poet_slug":"mustafa-yazka","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/korkuyor-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Bana', 'yaz-bana-mehmet-aslan-3z5j4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çekiniyorsun bana, söylemeye sözlerini,

Kullan sende benim gibi, edebi maharetini,

Al kağıdı kalemi eline, döktür dizelerini,

Büyük bir zevkle okurum, yazdığın şiirlerini.

Bekliyorum cevabını, yaz ama okunaklı,

İyi yaz ki, olmasın kalbime dokunaklı,

Olmasın hiçbir satırında, gizli saklı,

Üzmesin beni, yazdıkların bal dudaklı.

Yaz sende bana, iyileşsin kırılan kalbim,

Daha çok alevlensin, sana olan sevgim,

Bitsin seninle, bütün sıkıntılarım derdim,

Son sevgim kalmıştı, onu da sana verdim.

Anlat bana, bütün zevklerini, renklerini,

Varsa anlat, dinlerim senin bütün dertlerini,

Bilmek isterim, hayattan beklentilerini,

Anlat hepsini, fakat aksatmadan işlerini.', 'Çekiniyorsun bana, söylemeye sözlerini, Kullan sende benim gibi, edebi maharetini, Al kağıdı kalemi eline, döktür dizelerini, Büyük bir zevk...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yaz-bana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldin', 'hosgeldin-abdulvahap-ates-8fgre', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'HOŞ  GELDİN

Şurda,şunun ardında biri var biliyorum,

Bağrıma basıp basıp öpmeyi diliyorum.

Seni bana verene candan eğiliyorum,

Hoş geldin ciğer parem,cancağızım hoş geldin,

Ürktüğüm yaşamıma kuvvet verdin,eş geldin.

Uğruna geceleri erken gündüzlediğim,

Her kıpırtınla coşup,imini izlediğim,

Hoş geldin aylar boyu yolunu gözlediğim,

Hoş geldin ciğer parem,cancağızım hoş geldin,

Ürktüğüm yaşamıma kuvvet verdin,eş geldin.

Sen karanlık odamın ışıldayan kandili,

Koynumda ıtır kokan sevgilinin mendili,

Bedbinlik boğazlayan umudun tatlı dili,

Hoş geldin ciğer parem,cancağızım hoş geldin,

Ürktüğüm yaşamıma kuvvet verdin,eş geldin.', 'HOŞ  GELDİN Şurda,şunun ardında biri var biliyorum, Bağrıma basıp basıp öpmeyi diliyorum. Seni bana verene candan eğiliyorum, Hoş geldin ciğ...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Ateş']::text[], 8.5, '{"poet":"Abdulvahap Ateş","poet_slug":"abdulvahap-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hosgeldin-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dertleştim 1', 'dertlestim-1-mustafa-yazka-odq2p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aniden bir deprem geldi,

Diğer meşakkatler takip etti,

Zaten bizimki bizden gitti,

Çelende ölmemi bekliyor kuzgun.

Depremzade aciz bekliyor yardım,

Milleti dururken dışarı yardım,

Bende zaten bunlara yandım,

Galiba bu iş başından bozgun.

Mustafa durmadan çile sarıyor,

Tuğlayı bulmadan çamur karıyor,

Durduğu yerde belamı arıyor? 

Doğruyu yazana çokları azgın.

 2002 Türkü (uzun hava)', 'Aniden bir deprem geldi, Diğer meşakkatler takip etti, Zaten bizimki bizden gitti, Çelende ölmemi bekliyor kuzgun. Depremzade aciz bekliyor ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yazka']::text[], 8.5, '{"poet":"Mustafa Yazka","poet_slug":"mustafa-yazka","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dertlestim-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzeldir Benim Köyüm Görseniz', 'ne-guzeldir-benim-koyum-gorseniz-yusuf-ter-3r9l8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaylalarda koyun kuzu buluştu

Ergen kızlar gençler bağa alıştı

Tarlalarda bu yıl herkes çalıştı

Ne güzeldir benim köyüm görseniz

Navruz açtı nergiz açtı gül açtı

Kısa ömre inat kelebek uçtu

Yüce dağdan koyaklara su geçti

Ne güzeldir benim köyüm bilseniz

Yusuf’um sarı başlı buğdayları

Topluyor analar babalar harmanı

Yazı yaban olmuş bıtırak dermanı 

Ne güzeldir benim köyüm gitseniz

Yusuf Ter 24.11.05

Saat 01:24 İsviçre', 'Yaylalarda koyun kuzu buluştu Ergen kızlar gençler bağa alıştı Tarlalarda bu yıl herkes çalıştı Ne güzeldir benim köyüm görseniz Navruz açtı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ne-guzeldir-benim-koyum-gorseniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir oğul doğdu', 'bir-ogul-dogdu-ali-kilic-6jqhi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir oğul doğdu o gün 

16/07/2003

kara gözlerle bakıp konuşmadan 

baba dediği ilk gün o gün

Açıldı parmaklar uzandı o minik eller

Bana ve herşeye sanki merhaba derler

Olmadı saramadı bu kollar oğulu

Ne olduğunu anlamadan

Tutular alıdılar benden küveze koydular

Beni  kör karanlığa

Tenim dışarda ruhum onunla 

Ben bilirim on gün on iki saat 

Nasıl bekledim görmeden oğulu 

Güneşe bakarken kaybolmanın 

Karanlıkta nasıl olduğunu', 'Bir oğul doğdu o gün  16/07/2003 kara gözlerle bakıp konuşmadan  baba dediği ilk gün o gün Açıldı parmaklar uzandı o minik eller Bana ve her...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç']::text[], 8.5, '{"poet":"Ali Kılıç","poet_slug":"ali-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-ogul-dogdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey İnsan Oğlu', 'ey-i-nsan-oglu-zahide-handan-erengil-ubfk5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kendine gel,gaflet uykusundan uyan,

Kulunu bağışlıyacak yüce rabbim.

Hak yolunu bulup,pişmanlık duyan.

Ahireti düşünmeden,dünyaya bağlanmışsın,

Zenginlikten başka bir şey düşünmez misin? 

Dünyanın tümü,fitne meşguliyet.

Bunların dışındadır,ahiret için iyi niyet.

Gönül diline uyulmuyor sa,

Fiilin sözlerini yansıtmıyor sa,

İstersen bin kere(Allahü ekber) de

Zira yalan söylüyorsun.

(La ilahe illellah) demeye utanmıyor musun? 

İki günün denk olursa aldanmışsın,

Dünün bu gününden iyi olursa ziyandasın.

Başındaki gözle dış dünyayı,

Kalbindeki gözle de iç dünyayı görmeyi öğren.

O yüceler yücesi rabbimdir seni bilen gören....', 'Kendine gel,gaflet uykusundan uyan, Kulunu bağışlıyacak yüce rabbim. Hak yolunu bulup,pişmanlık duyan. Ahireti düşünmeden,dünyaya bağlanmışs...', ARRAY['Türk Edebiyatı','Şiir','Zahide Handan Erengil']::text[], 8.5, '{"poet":"Zahide Handan Erengil","poet_slug":"zahide-handan-erengil","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ey-insan-oglu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskimiş Duygular', 'eskimis-duygular-necibe-sucuoglu-swtnf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bayatlamış yiyeceği,

çöpe atarlar...

Eskimiş eşyaları

bitpazarında satarlar...

Eskimiş düşünceleri,

toplumdan atarlar...

Eskimiş insanları bile

koyacak bir yer bulurlar da; 

Ya...,

Eskimiş duyguları ne yaparlar? ? ?', 'Bayatlamış yiyeceği, çöpe atarlar... Eskimiş eşyaları bitpazarında satarlar... Eskimiş düşünceleri, toplumdan atarlar... Eskimiş insanları b...', ARRAY['Türk Edebiyatı','Şiir','Necibe Sucuoğlu']::text[], 8.5, '{"poet":"Necibe Sucuoğlu","poet_slug":"necibe-sucuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/eskimis-duygular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimle Kal...', 'benimle-kal-haldun-uras-o2nu5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel sevgilim bu gece,

Söyleyecek çok şeyler var.

Gözümde hayal, dilimde hece,

İçimde kocaman bir aşk var.

Aylardan Temmuz, yer İstanbulsa,

Hele bir de Boğazda vakit akşamsa,

Bir başka türlü oluyor insan.

Tek dileğim var yanımda kalsan.

Deniz uysal, yıldızlar durgun.

Kalbimse yorgun mu yorgun.

İster yalan de ister duygusal,

Ne olur bu gecelik benimle kal.

Bilir misin ben hep böyleyim.

Her akşam sensiz de seninleyim.

Ben sevgi sarhoşu, aşkın tutsağı

Yaşadığım sanki sensizlik yasağı.

Gözlerim yıldızlarda hep seni arıyorum.

Çaresizim; bulmasam da biliyorum,

Bazen müzikte bazen kadehtesin.

Ama hep istemediğim yerdesin.', 'Gel sevgilim bu gece, Söyleyecek çok şeyler var. Gözümde hayal, dilimde hece, İçimde kocaman bir aşk var. Aylardan Temmuz, yer İstanbulsa, H...', ARRAY['Türk Edebiyatı','Şiir','Haldun Uras']::text[], 8.5, '{"poet":"Haldun Uras","poet_slug":"haldun-uras","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/benimle-kal-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anasını ağlattım hayatın.', 'anasini-aglattim-hayatin-necibe-sucuoglu-i5oko', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün,

Anasını ağlattım hayatın; 

Babası mı? 

Bana yetim dediler.

Gayrimeşruymuş; 

Sonradan öğrendim...

Oysa ona acımıştım! 

Seni gidi piç kurusu; 

Kolay lokma sanmıştın beni,

Boğazını aldım değil mi? ? ? ! !', 'Bugün, Anasını ağlattım hayatın;  Babası mı?  Bana yetim dediler. Gayrimeşruymuş;  Sonradan öğrendim... Oysa ona acımıştım!  Seni gidi piç k...', ARRAY['Türk Edebiyatı','Şiir','Necibe Sucuoğlu']::text[], 8.5, '{"poet":"Necibe Sucuoğlu","poet_slug":"necibe-sucuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/anasini-aglattim-hayatin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya dönerken kendi ekseninde', 'dunya-donerken-kendi-ekseninde-necibe-sucuoglu-6rtjm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünya dönerken kendi ekseninde

Yaşamsızlığın yaşanımını yaşamışım

Zamanı zamansızlıkta harcamışım.

Kabullenmeler yadsımalar

Bir aldatmaca mıydı yaşananlar? 

Çölde görünen bir serap mıydı umutlarım? 

Yağmurda ıslanmanın tadını yaşarken

Saçlarımde donan

Buz taneciklerinin acısı mı çektiğim? 

Gözlerimin önünü görmeye çalışırken

Habersiz yakalanmışım

Ufuktaki fırtınaya

Engin denizlere açılmaya korkarken,

Sahilde yanlız kalmışım.,

El sallamışım,türküler söylemişim

Giden geminin ardından.,

O gemide hayatım olduğunu 

Gemi kalktıktan sonra anlamışım.', 'Dünya dönerken kendi ekseninde Yaşamsızlığın yaşanımını yaşamışım Zamanı zamansızlıkta harcamışım. Kabullenmeler yadsımalar Bir aldatmaca mı...', ARRAY['Türk Edebiyatı','Şiir','Necibe Sucuoğlu']::text[], 8.5, '{"poet":"Necibe Sucuoğlu","poet_slug":"necibe-sucuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dunya-donerken-kendi-ekseninde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Battaniyeye sarmış sarmalamış', 'battaniyeye-sarmis-sarmalamis-ali-kilic-jlz6l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Battaniyeye sarmış sarmalamış

Küçük bebesini

Yağan yağmuru umursamıyor

Islansın ne olacak bebek kuru

Tek düşündüğüde bu

Yazlık terlikler ayağında

Akan sulara basarak geçer 

Islanmış hasta olacak dertmi sanki bu

Bebek kuru  ana yüreğidir bu

Ben dün gördüm bu anayı 

Anam geldi aklıma 

Görmüştür birileri battaniyde anamın kucağında

İşete o an yüreğimle sonsuzluğa 

Yüreğimle çığlık attım 

Beni ve kardeşlerimi

battaniyeye saran anama', 'Battaniyeye sarmış sarmalamış Küçük bebesini Yağan yağmuru umursamıyor Islansın ne olacak bebek kuru Tek düşündüğüde bu Yazlık terlikler aya...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç']::text[], 8.5, '{"poet":"Ali Kılıç","poet_slug":"ali-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/battaniyeye-sarmis-sarmalamis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gideceksin..', 'gideceksin-muharrem-kemal-gunduz-ahlcb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''''Akşamların koyu karanlığı çökerken

Hüznü düşer yüreğime sensizliğin,,

Sen giderken bir ben kalacağım

Birde yokluğun bu şehirde

Bitecek hayaller

Tükenecek umutlar; 

Bir başıma kalacağım sisli sokaklarında Ankara''nın 

Sensiz..

Buz kesecek zaman, donup kalacağım

Ayrılırken bıraktığın yarayla 

Sensiz hep ateşler içinde yanacağım..

Ayrılık vaktidir şimdi puşt akşamlarda

Cepden cebe sahte gülüşler

Öpücükler yalancıdır

Yalancıdır sevgi dolu sözcükler

Yitip gidersin sonsuzluğunda zamanın..

Sen yinede gözlerini düşür yüzüme

Yüreğime uzat ellerini anlayacaksın..

Gitme desemde..

Biliyorum gideceksin

Kan düşecek düşlerime

Gözlerim ararken buğulu bakışlarını

Ellerim uzanacak sensizliğe

Anlıyorum terk edeceksin

Bu şehri ve beni..

Şimdi yanma zamanıdır

Kayıp zamanlarda arta kalan an''larda

Şimdi seninle olmak zamanıdır

Geçmişi geçmişte bırakıp yarınlarda..

      

(27/02/2002 Ankara)', '''''Akşamların koyu karanlığı çökerken Hüznü düşer yüreğime sensizliğin,, Sen giderken bir ben kalacağım Birde yokluğun bu şehirde Bitecek hay...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Kemal Gündüz']::text[], 8.5, '{"poet":"Muharrem Kemal Gündüz","poet_slug":"muharrem-kemal-gunduz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gideceksin-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgim', 'sevgim-necibe-sucuoglu-7708l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Azgın bir sel olsa sevgim; 

Beton bir zemin değil,

Birikecek toprak ister.

Yağmur olsa sevgim; 

Bulutta saklı kalmak değil,

Gönlünce yağmak ister.

Işık olsa sevgim; 

Kapalı kalmak değil,

Aralayıp perdeleri,

Camlardan sızmak ister.

Rüzgar olsa sevgim; 

Dağıtıp bulutları,

Güneşi sermek ister.

Bir kalem olsa sevgim; 

Mutsuzluğu karalayıp,

Mutluluklar yazmak ister.

Harman olsa sevgim; 

Hasat için takat ister.

Orman olsa sevgim; 

Dalında ötecek kuş ister.

Sevgim, saklı kalmak değil kalbimde,

Çıkıp,dağılmak ister.

Her nereye gitse de

Değer verilmek ister.', 'Azgın bir sel olsa sevgim;  Beton bir zemin değil, Birikecek toprak ister. Yağmur olsa sevgim;  Bulutta saklı kalmak değil, Gönlünce yağmak ...', ARRAY['Türk Edebiyatı','Şiir','Necibe Sucuoğlu']::text[], 8.5, '{"poet":"Necibe Sucuoğlu","poet_slug":"necibe-sucuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevgim-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşuna', 'bosuna-ertugrul-gokceli-dffav', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkın adını çılgınlık koymuşlar

Çılgınlar günleri gecelere doldurmuşlar

Uykusuz kalmanın ne anlamı var

O seni sevmedikten sonra...

Bilmezler ki aşkın tarifi yok 

Dermansız derdinin dermanı çok

Onu hatırlamanın ne anlamı var

Oseni sevmedikten sonra...

O uzakta sen uzakta

Kadersiz kalbin hep tuzakta

Ayrılık acısı çekmenin ne anlamı var 

O seni sevmedikten sonra...

Unuttun artık unuttun

Ayrılık rüzgarıyla kalbini soğuttun

Kalbini yakmanın ne anlamı var

Sen onu sevmedikten sonra,boşuna...', 'Aşkın adını çılgınlık koymuşlar Çılgınlar günleri gecelere doldurmuşlar Uykusuz kalmanın ne anlamı var O seni sevmedikten sonra... Bilmezler...', ARRAY['Türk Edebiyatı','Şiir','Ertugrul Gokceli']::text[], 8.5, '{"poet":"Ertugrul Gokceli","poet_slug":"ertugrul-gokceli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bosuna-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygular,düşünceler ve eylem', 'duygular-dusunceler-ve-eylem-necibe-sucuoglu-pmsgu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Duygular,düşünceler ve eylem,

Kısaca yaşam.

Ve yaşam insanların sırtında

Hem de ağır mı ağır.

Oysa yaşam,

Bir kambur olmamalı

İnsanların sırtında.

Duydular sınırsız,

Düşünceler zincirsiz,

Ve yaşam dizginsiz olmalı.

İsyanın gözü kördür,

İnsafın kulağı sağır.

Oysa eylemler,

Tüm duygularla kavranmalı.', 'Duygular,düşünceler ve eylem, Kısaca yaşam. Ve yaşam insanların sırtında Hem de ağır mı ağır. Oysa yaşam, Bir kambur olmamalı İnsanların sır...', ARRAY['Türk Edebiyatı','Şiir','Necibe Sucuoğlu']::text[], 8.5, '{"poet":"Necibe Sucuoğlu","poet_slug":"necibe-sucuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/duygular-dusunceler-ve-eylem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Oluyor...', 'aksam-oluyor-haldun-uras-b1fpo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün de akşam oluyor.

Şeytan dürtmeye başladı.

Sohbet bahanesi ile,

Birkaç kadeh atmalı.

Açalım şişeleri artık.

İçkiler dolsun kadehe.

Mutluluk bizim olsun,

Kederler gitsin ellere.

Efkar dağıtalım diye diye,

Göründü şişenin dibi yine.

Gel geçmişi içine tıkalım,

Fırlatıp, ta uzaklara atalım.

Sızalım bir köşede yarına kadar,

Kim bilir daha kaç yarınımız var? 

Üstümüze inerse hayatın son perdesi

Yarın bu masada göremezsiniz beni.

Eğer kısmetse uyanmak yarına,

Açarız yeni bir şişeyi sevabına.

Biliriz ki, gecenin peşinden gitmedik.

Yapacaklarımız bitti ama biz bitmedik.', 'Bugün de akşam oluyor. Şeytan dürtmeye başladı. Sohbet bahanesi ile, Birkaç kadeh atmalı. Açalım şişeleri artık. İçkiler dolsun kadehe. Mutl...', ARRAY['Türk Edebiyatı','Şiir','Haldun Uras']::text[], 8.5, '{"poet":"Haldun Uras","poet_slug":"haldun-uras","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aksam-oluyor-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Beni Hiç Sevmedin ki', 'sen-beni-hic-sevmedin-ki-fatih-eser-senol-mvyno', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geri dön desem

Çok şey mi isterim? 

Bana gül desem

Güler mi gözlerin? 

Yeniden sev desem

Çok şey mi isterim? 

Çok mu zor gelir? 

Bu kadar mı zayıf hislerin? 

Oysa seni ne çok sevmiştim

Oysa ben neler ümit etmiştim

Her şeyi göze almıştım

Dünyayı gözlerine satmıştım

Sen beni hiç sevmedin ki

Acılardan geçerken

Elimden tutmadın ki

Sen beni hiç sevmedin ki

Sevsen geri dönerdin

Bir an bile düşünmezdin', 'Geri dön desem Çok şey mi isterim?  Bana gül desem Güler mi gözlerin?  Yeniden sev desem Çok şey mi isterim?  Çok mu zor gelir?  Bu kadar mı...', ARRAY['Türk Edebiyatı','Şiir','Fatih Eser Şenol']::text[], 8.5, '{"poet":"Fatih Eser Şenol","poet_slug":"fatih-eser-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-beni-hic-sevmedin-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleceksin', 'geleceksin-zahide-handan-erengil-9q4ap', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bekliyorum bu gün geleceksin,

Belkide af dileyeceksin.

Merdivende ayak seslerini dinliyorum,

Kapı çaldı,çalacak bekliyorum.

Biliyorsun ben oradayım,

Hemen kapının arkasında.

Yalnızlığıma sığınıp kalmışım.

Çalmıyorsun bak yine aldanmışım.

Ama alıştım bugün veya yarın,

Nasıl olsa bir gün döneceksin.

Geleceksin,başın önünde,

Kolların yana düşmüş,

Umutlar hep sönmüş,

Yaz sonbahara dönmüştür.

O gün çaldığın kapı açılmazsa eğer,

Bil ki bekleten,bekleyene vermemiştir değer.', 'Bekliyorum bu gün geleceksin, Belkide af dileyeceksin. Merdivende ayak seslerini dinliyorum, Kapı çaldı,çalacak bekliyorum. Biliyorsun ben o...', ARRAY['Türk Edebiyatı','Şiir','Zahide Handan Erengil']::text[], 8.5, '{"poet":"Zahide Handan Erengil","poet_slug":"zahide-handan-erengil","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/geleceksin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkak', 'korkak-ertugrul-gokceli-53nu0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dayanamıyorum o kömür gözlerine 

Uyumandan korkuyorum 

Gözlerini göremicem diye

Ağlamandan korkuyorum

O gül yüzünü saklarsın diye

Rüzgardan korkuyorum

Saçlarını alıp götürecek diye

Aslında ben bir korkağım

Bana bakmandan korkuyorum

Sensiz öleceğim diye....', 'Dayanamıyorum o kömür gözlerine  Uyumandan korkuyorum  Gözlerini göremicem diye Ağlamandan korkuyorum O gül yüzünü saklarsın diye Rüzgardan ...', ARRAY['Türk Edebiyatı','Şiir','Ertugrul Gokceli']::text[], 8.5, '{"poet":"Ertugrul Gokceli","poet_slug":"ertugrul-gokceli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/korkak-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ziyan Olurdun', 'ziyan-olurdun-firuze-keles-tu64o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ellerim uzanırdı sana, imkansız

Karanlık gecede yıldız olurdun.

Yazdığım bir şiirdin bazen, imzasız

Sonu gelmeyen bir mısra olurdun.

Tuttuğum bir dilektin sessiz sedasız

Vadesi dolmayan murat olurdun.

Sen yine bilme, kal bu aşktan habersiz

Benim kadar sevsen ziyan olurdun...', 'Ellerim uzanırdı sana, imkansız Karanlık gecede yıldız olurdun. Yazdığım bir şiirdin bazen, imzasız Sonu gelmeyen bir mısra olurdun. Tuttuğu...', ARRAY['Türk Edebiyatı','Şiir','Firuze Keleş']::text[], 8.5, '{"poet":"Firuze Keleş","poet_slug":"firuze-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ziyan-olurdun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolaydı Aslında Tekdüze Bir Sevda Yaşamak', 'kolaydi-aslinda-tekduze-bir-sevda-yasamak-ediz-karaoglu-thy8w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kolaydı aslında tekdüze bir sevda yaşamak,

Gözlerimin bir damla güldüğünde herkesi mutluluğuma inandırmak,

Kolaydı senin ilk tavrında senden uzaklaşmak…

Ama bil ki ben hayatımda hep zoru seçtim,

Ellerim değmedi mi,işte o zaman daha da fazla sevdim,

Kaçmak erkekliğin namertliği dediler,

Bunu duydum ve itaat ettim…

Sen şimdi bensiz gecelerde neler yapıyorsun bilinmez,

Kolay tabii ki “bana ne” diyip vazgeçmek senden,

Gözlerim gözlerine değmediğinde bu kalp iflah bilmez,

Ya seveceğim seni adam gibi,adama layık bir mertlikle,

Ya da bu gönülde bu devran asla bitmez…

Güçlüyüm naraları atmak çok basitti yere düştüğümde bile,

Ben ilişkilerimde satranç oynamam,

Güçsüzüm ve acizim bu naçiz bedende,

Ne ise o yaşanmalı,ne gerekliyse benim gerçeğimde,

Seni ilk anladığımda yüzümü çevirmek çok kolaydı…

Kaçmadım diye onur duyuyor değilim,

Ben sevdasının arkasından Kaf Dağı’na giden bir deliyim,

Ne namert korkuttu beni,ne de başka bir dert,

Kasım ayında herkes üşürken terleyen benim…

Tutsana ellerimi,artık bırakmamacasına,

Seni senden bile daha çok düşünüyorum,

Artık anlasana,

Her telefon çalışlarında senden sanıyorum,

Buna bir nazar buyursana,

Hiç yakınmadım duygularımdan hayatımda ama,

Bu duyguları benden çekip alsana…', 'Kolaydı aslında tekdüze bir sevda yaşamak, Gözlerimin bir damla güldüğünde herkesi mutluluğuma inandırmak, Kolaydı senin ilk tavrında senden...', ARRAY['Türk Edebiyatı','Şiir','Ediz Karaoğlu']::text[], 8.5, '{"poet":"Ediz Karaoğlu","poet_slug":"ediz-karaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kolaydi-aslinda-tekduze-bir-sevda-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarden Kalan', 'yarden-kalan-i-brahim-balci-bzhcd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmalanmış bir obadan ardakalan

Son yurt,isten kararmış direkleri

Ve cesetleriyle salkımsaçak

Yitirilmiş açlıkların neşesiyle dopdolu

Kuzgun sesleri bedenimi paylaşan

Bastırılmış bir sevdanın,yuvalanan

Tutkusudur,boşalmış göz çukurlarımdan

Oluşmamış göz yaşıdır akamayan

Krizalit olmuş bir kurtçuk,gözümdeki

Parçalanmış un ufak olmuş

Kızgın güneşin gazabından sonra

Dondurucu soğuğuyla gecenin,yüzgöz olan

Bir kayanın gözyaşıdır,yarden kalan', 'Yağmalanmış bir obadan ardakalan Son yurt,isten kararmış direkleri Ve cesetleriyle salkımsaçak Yitirilmiş açlıkların neşesiyle dopdolu Kuzgu...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Balcı']::text[], 8.5, '{"poet":"İbrahim Balcı","poet_slug":"i-brahim-balci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yarden-kalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Girdabına Düştüm', 'girdabina-dustum-hikmet-elitas-78oml', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Girdabına düştüm, zalim dünyanın

Izdırap çarkına sıkışan benim

Çile aynasına otuzbeş yıldır

Doğrulup baktıkça, yakışan  benim.

Yedi gençliğimi, bitirdi felek

Sürdü bir çıkmaza götürdü felek

Üstüme çullandı, yatırdı felek

Hile meydanında, yıkışan benim.

Hikmeti ben beni, bende gördüm de

Garip kaldım vatanımda yurdumda

Sevdiklerim hangi dağın ardında

Uzaktan uzağa, bakışan benim.', 'Girdabına düştüm, zalim dünyanın Izdırap çarkına sıkışan benim Çile aynasına otuzbeş yıldır Doğrulup baktıkça, yakışan  benim. Yedi gençliği...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Elitaş']::text[], 8.5, '{"poet":"Hikmet Elitaş","poet_slug":"hikmet-elitas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/girdabina-dustum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sana Ağlıyorum', 'bir-sana-agliyorum-muhsin-altintas-o16ce', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ve akan su sesiyle birlekte 

Bir sana ağlıyorum

Ve gözümde bir kıvılcım vuslata dair

Yinede ben beni düşünmeyip

Bir sana yanıyorum.

Sanki ben değilim boşlukta

Evet ben değilim aldatılan unutulan

Yapayalnız bırakılan

Ben değilim söz verdiğin

Ben değilim 

Seni çok ama çok seviyorum dediğin,

Sevmeyi bilmediğin

Bütün bunlar bir yana 

Yinede ben bir sana çağlıyorum

Ta derinden yürekten

Bir sana ağlıyorum.

Yıllar sonra yüzünde gülücükler kalmamış

Halin hatrın nedir diye 

Bir soranın olmamış

Acı ama gerçek bu

Sana kimse yanmamış

Yanan bendim, kanan ben

Şimdi yüreğim dağlıyor

Evet yalnız ama yalnız

Bir sana, Bir sana, Bir sana AĞLIYORUM...', 'Ve akan su sesiyle birlekte  Bir sana ağlıyorum Ve gözümde bir kıvılcım vuslata dair Yinede ben beni düşünmeyip Bir sana yanıyorum. Sanki be...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Altıntaş']::text[], 8.5, '{"poet":"Muhsin Altıntaş","poet_slug":"muhsin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-sana-agliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim İçin Bir Dilek Tutar Mısınız?', 'benim-i-cin-bir-dilek-tutar-misiniz-ebru-delice-m7pjr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Suskunluk elbisemi giyindim,

kendi sözümün suskunluğunu

                  Düşlerimde Oborjin''lerin diyarındayım

                  Sonra Meksika da

                  İnka''ların ve Aztek''lerin diyarı

Bilinmezliğin elbisesi var üstümde,

Düşlerin, geçmişin ve geleceğin

                 İtalya da Roma''dayım

                 Aşk çeşmesinde br dilek tutuyorum

                 Başka düşlerim için

Soğuktanda, sıcaktanda hoşlanmam ben,

Rüzgarlar esiyor, meltem yumuşaklığında

Dünya coğrafyasında Ebru isimli

Sislerin şehrinden

               Konuşmadan, uyanmadan, düşlerimin sarhoşluğundan

              Benim için de bir dilek tutar mısınız?', 'Suskunluk elbisemi giyindim, kendi sözümün suskunluğunu                   Düşlerimde Oborjin''lerin diyarındayım                   Sonra Meks...', ARRAY['Türk Edebiyatı','Şiir','Ebru Delice']::text[], 8.5, '{"poet":"Ebru Delice","poet_slug":"ebru-delice","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benim-icin-bir-dilek-tutar-misiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Rızan İçin', 'senin-rizan-i-cin-mehmet-postalli-4598t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rabbim haccı nasip et, ihrama bürüneyim

Tek senin rızan için, yollarda sürüneyim.', 'Rabbim haccı nasip et, ihrama bürüneyim Tek senin rızan için, yollarda sürüneyim....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/senin-rizan-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
